window.GUWEN = [{"source": "条1｜《心悸·第七章 评述》导言", "原文": "几千年来，中医药防治疾病过程中，形成了系统且独特的预防理论和实践体系。心悸预防调护虽未有专书专节论述，但相关内容散在心悸记载的部分古籍中，且中医药“治未病”预防理念，对心悸预防调护同样适用。", "白话": "几千年来，中医药在防治疾病过程中形成了系统而独特的预防理论与实践体系。心悸的预防调护虽没有专书专节论述，但相关内容散见于部分记载心悸的古籍中；中医药「治未病」的预防理念，对心悸预防调护同样适用。"}, {"source": "条2｜《心悸·第七章 评述》一、心悸预防的早期认识", "原文": "殷商时期甲骨文中已有了“心”的象形文字，“病心”这一病名是祖国中医学对心脏疾病早期认识的集中概况，心悸一病极有可能包含其中。《周礼·天官》记载“以五味、五谷、五药养其病，以五气、五声、五色视其生死”，可知当时对疾病防治方法有“五味、五谷、五药”。", "白话": "殷商时期的甲骨文中已有「心」的象形文字，「病心」这一病名是中医学对心脏疾病早期认识的集中概括，心悸一病极有可能包含其中。《周礼·天官》记载「以五味、五谷、五药养其病，以五气、五声、五色视其生死」（用五味、五谷、五药调养其病，用五气、五声、五色判断生死），可见当时对疾病的防治方法已有「五味、五谷、五药」。"}, {"source": "条3｜《心悸·第七章 评述》一、心悸预防的早期认识", "原文": "《山海经》载有包含了植物、动物和矿物等一百余种药物，并记载了食、汤服、沐浴、佩戴、涂抹等多种预防及养生方法。虽未有特指心悸一病，但对内科疾病广泛适用。", "白话": "《山海经》记载了包含植物、动物、矿物等一百余种药物，并记载了食用、汤服、沐浴、佩戴、涂抹等多种预防与养生方法。虽未特指心悸一病，但对内科疾病广泛适用。"}, {"source": "条4｜《心悸·第七章 评述》一、心悸预防的早期认识", "原文": "《黄帝内经》对心悸一病已经有较清晰的认识，但是对于其预防调摄还是宏观概括在疾病或心病中，如《素问·刺法论》有“正气存内，邪不可干”，即指提高正气的抗邪能力和防止邪气的侵害是防止其发病的重要基础。", "白话": "《黄帝内经》对心悸已有较清晰的认识，但对其预防调摄仍宏观概括于疾病或心病之中。如《素问·刺法论》有「正气存内，邪不可干」（正气存于体内，邪气不能侵犯），即指提高正气的抗邪能力、防止邪气侵害，是防止发病的重要基础。"}, {"source": "条5｜《心悸·第七章 评述》一、心悸预防的早期认识", "原文": "《素问·藏气法时脏气法时论》“心主夏，手少阴太阳主治，其日丙丁，心苦缓”阐明心主夏火之气，因此夏季宜进食苦味来收敛心火。《灵枢·五味》指明“心病禁咸”，《素问·藏气法时脏气法时论》提出“心色赤，宜食酸，小豆、犬肉、李、韭皆酸”提出了心悸患者的饮食宜忌，要注意禁咸和适当食酸。", "白话": "《素问·藏（脏）气法时论》「心主夏，手少阴太阳主治，其日丙丁，心苦缓」阐明心主夏火之气，因此夏季宜进食苦味来收敛心火。《灵枢·五味》指出「心病禁咸」；《素问·藏（脏）气法时论》提出「心色赤，宜食酸，小豆、犬肉、李、韭皆酸」，提出心悸患者的饮食宜忌——要注意禁咸、适当食酸。"}, {"source": "条6｜《心悸·第七章 评述》一、心悸预防的早期认识", "原文": "此外，《黄帝内经》中指出惊恐、思虑、愤怒及忧愁等情志是心悸发病的重要因素，因而调畅情志对减少心悸发病尤为重要，", "白话": "此外，《黄帝内经》指出惊恐、思虑、愤怒、忧愁等情志是心悸发病的重要因素，因而调畅情志对减少心悸发病尤为重要。"}, {"source": "条7｜《心悸·第七章 评述》一、心悸预防的早期认识", "原文": "如《素问·举痛论》有“惊则心无所倚，神无所归，虑无所定，故气乱矣。”。", "白话": "如《素问·举痛论》有「惊则心无所倚，神无所归，虑无所定，故气乱矣」（大惊则心神失去依附、神无所归、思虑无所定，所以气乱）。"}, {"source": "条8｜《心悸·第七章 评述》一、心悸预防的早期认识", "原文": "《素问·五藏五脏生成论》有“赤，脉之至也，喘而坚，诊曰有积气在中，时害于食，名曰心痹，得之外疾，思虑而心虚，故邪从之”。", "白话": "《素问·五藏（脏）生成论》有「赤，脉之至也，喘而坚，诊曰有积气在中，时害于食，名曰心痹，得之外疾，思虑而心虚，故邪从之」（面色赤、脉来急疾而坚，诊为中有积气、时常妨碍饮食，病名心痹——得之于外邪，思虑而心虚，邪气乘之）。"}, {"source": "条9｜《心悸·第七章 评述》一、心悸预防的早期认识", "原文": "《灵枢·口问》指出“悲哀愁忧则心动，心动则五藏五脏六府六腑皆摇”。", "白话": "《灵枢·口问》指出「悲哀愁忧则心动，心动则五藏（脏）六府（腑）皆摇」（悲哀愁忧先动摇于心，心动则五脏六腑皆不安）。"}, {"source": "条10｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "自汉代张仲景对心悸病位、病机及治疗的进一步明晰，历代医家对心悸的预防调摄也有了更深入的认识，在《内经》调摄情志预防心悸的基础上，进一步提出了预防心悸的劳逸、饮食等相关内容。", "白话": "自汉代张仲景进一步明确心悸的病位、病机及治疗之后，历代医家对心悸的预防调摄也有了更深入的认识，在《内经》调摄情志预防心悸的基础上，进一步提出预防心悸的劳逸、饮食等相关内容。"}, {"source": "条11｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "湖南长沙马王堆西汉古墓出土的《养生方》指出房劳损伤肾精可致惊悸“精藏于玉房，交接太数，则失精。失精者，令人怅怅，心常惊悸”。", "白话": "湖南长沙马王堆西汉古墓出土的《养生方》指出房劳损伤肾精可致惊悸：「精藏于玉房，交接太数，则失精。失精者，令人怅怅，心常惊悸」（精藏于玉房，交接太频繁则失精；失精使人怅然若失，心常惊悸）。"}, {"source": "条12｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "明代徐春甫《古今医统大全·痨瘵门》有“劳于心者，则神耗而血衰，惊悸之疾亦因之而作矣”。", "白话": "明代徐春甫《古今医统大全·痨瘵门》有「劳于心者，则神耗而血衰，惊悸之疾亦因之而作矣」（劳心过度，则神气耗损、血液衰少，惊悸之病也因此而发）。"}, {"source": "条13｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "明李中梓《病机沙篆·虚劳》中“曲运神机则心劳，而为虚汗怔忡”。", "白话": "明代李中梓《病机沙篆·虚劳》中说「曲运神机则心劳，而为虚汗怔忡」（竭虑运神则心劳，而见虚汗、怔忡）。"}, {"source": "条14｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "可见，劳心、房劳都可损伤心神、心阴血，故明代张景岳《景岳全书·怔忡惊恐》中指出心悸患者应注意劳逸结合，要节制劳心、劳力、房劳“凡患此者，速宜节欲节劳，切戒酒色。”。", "白话": "可见劳心、房劳都可损伤心神与心阴血。所以明代张景岳《景岳全书·怔忡惊恐》指出，心悸患者应注意劳逸结合，节制劳心、劳力、房劳：「凡患此者，速宜节欲节劳，切戒酒色」（凡患此病者，从速节欲、节劳，切戒酒色）。"}, {"source": "条15｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "唐代王焘《外台秘要》云：“又若饮酒不解，食不得下，乍寒乍热，不洗便热，洗之复寒，甚者数十日，轻者数日，昼夜不得寝寐，愁悲恚怒，自惊跳悸。", "白话": "唐代王焘《外台秘要》说：「又若饮酒不解，食不得下，乍寒乍热，不洗便热，洗之复寒，甚者数十日，轻者数日，昼夜不得寝寐，愁悲恚怒，自惊跳悸」（又如饮酒不消、饮食不下、忽冷忽热，不洗身则觉热、洗之又觉寒，重者数十日、轻者数日，昼夜不得睡眠，愁悲恚怒，自惊而心悸跳动）。"}, {"source": "条16｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "明代万全《养生四要·寡欲第一》指出：“酒客病酒，酒停不散，清则成饮，浊则成痰。入于肺则为喘，为咳。入于心则为心痛，为怔忡，为噫。", "白话": "明代万全《养生四要·寡欲第一》指出：「酒客病酒，酒停不散，清则成饮，浊则成痰。入于肺则为喘，为咳。入于心则为心痛，为怔忡，为噫」（嗜酒者病于酒，酒停不散，清者成饮、浊者成痰；入肺则为喘为咳；入心则为心痛、怔忡、嗳气）。"}, {"source": "条17｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "如清代李用粹《证治汇补》载有“有膏粱厚味，积成痰饮，口不作干，肌肤润泽如故，忽然惊惕而作悸……", "白话": "如清代李用粹《证治汇补》载有「有膏粱厚味，积成痰饮，口不作干，肌肤润泽如故，忽然惊惕而作悸……」（嗜食肥甘厚味，积成痰饮，口不作干、肌肤照旧润泽，忽然惊惕而心悸……）。"}, {"source": "条18｜《心悸·第七章 评述》二、心悸预防理论的发展完善", "原文": "可知，肥甘厚味、醇酒炙煿皆可酿生痰湿，日久化火，痰火扰神而致心悸，合理有节制的饮食、饮酒，可以减少化火、化痰的来源，减少痰火扰心神而发心悸的发病途径。", "白话": "可知肥甘厚味、醇酒炙煿都可酿生痰湿，日久化火，痰火扰神而致心悸；合理而有节制的饮食与饮酒，可以减少化火、化痰的来源，减少痰火扰心神而发心悸的发病途径。"}, {"source": "条19｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "随着对心悸预防认识的不断加深，历代医家也在调护手段上总结出食疗、导引等相关手段和方法。", "白话": "随着对心悸预防认识的不断加深，历代医家也在调护手段上总结出食疗、导引等相关手段和方法。"}, {"source": "条20｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "在食疗药食方面，东晋葛洪《肘后备急方·治卒得惊邪恍惚方》首次提出了心悸的食疗方法，即“白雄鸡一头治如食，真珠四两切，薤白四两。以水三升，煮取二升。宿勿食，旦悉食鸡等及饮汁尽”。", "白话": "在食疗药食方面，东晋葛洪《肘后备急方·治卒得惊邪恍惚方》首次提出心悸的食疗方法：「白雄鸡一头治如食，真珠四两切，薤白四两。以水三升，煮取二升。宿勿食，旦悉食鸡等及饮汁尽」（白公鸡一只如食法处理，珍珠四两切碎，薤白四两，加水三升煮取二升；前夜禁食，清晨把鸡与药全部吃完并饮尽药汁）。"}, {"source": "条21｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "宋代陈直《养老奉亲书》记载老人久病喘息，心悸少寐宜服炖胎盘方。", "白话": "宋代陈直《养老奉亲书》记载：老人久病喘息、心悸、睡眠少者，宜服炖胎盘（紫河车）方。"}, {"source": "条22｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "宋代《太平圣惠方·卷第九十六》记载了一些心悸病证的食疗方。如“治风邪癫痫，心烦惊悸，宜吃苦竹叶粥方”“治心胸结气，烦闷恐悸，风热惊邪，口干，茯苓粥方”“治心胸结气，烦热，或渴，狂言惊悸，茯神粥方”等等。", "白话": "宋代《太平圣惠方·卷第九十六》记载了一些心悸病证的食疗方，如「治风邪癫痫、心烦惊悸，宜吃苦竹叶粥方」「治心胸结气、烦闷恐悸、风热惊邪、口干，茯苓粥方」「治心胸结气、烦热或渴、狂言惊悸，茯神粥方」等。"}, {"source": "条23｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "元代忽思慧《饮膳正要》记载心气郁结者宜服炙羊心。", "白话": "元代忽思慧《饮膳正要》记载：心气郁结者宜吃烤羊心。"}, {"source": "条24｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "清代章穆《调疾饮食辩》提出心悸宜多食山药，“凡虚劳羸瘦、盗汗、怔忡等症，宜多食”。清代徐文弼《寿世传真》提出心悸宜食猪心“猪心性平，治惊邪虚悸，补心血不足”。", "白话": "清代章穆《调疾饮食辩》提出心悸宜多食山药：「凡虚劳羸瘦、盗汗、怔忡等症，宜多食」。清代徐文弼《寿世传真》提出心悸宜食猪心：「猪心性平，治惊邪虚悸，补心血不足」（猪心性平，治惊邪虚悸，补心血不足）。"}, {"source": "条25｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "以上各食疗药物精简，且制作方法简单，服用方便，对心悸病的预防能起到很好的辅助作用。", "白话": "以上各食疗药物精简，制作方法简单，服用方便，对心悸病的预防能起到很好的辅助作用。"}, {"source": "条26｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "在心悸忌食方面，历代医家沿袭《内经》养心思想，提出了心悸病的忌食。如唐王焘《外台秘要·中风惊悸方》所载心悸病证治疗方剂后均注明饮食宜忌，镇心丸“忌海藻、落菜、醋、蒜、面、粘黏食、陈臭等物”，深师大定心丸“忌生葱、醉物、猪肉、桃、李、雀肉等”，荆沥汤“忌海藻、落菜、醉、生葱、桃、李、雀肉等物”等等等。", "白话": "在心悸忌食方面，历代医家沿袭《内经》养心思想，提出心悸病的忌食。如唐代王焘《外台秘要·中风惊悸方》所载心悸病证治疗方剂后均注明饮食宜忌：镇心丸「忌海藻、落菜、醋、蒜、面、粘黏食、陈臭等物」，深师大定心丸「忌生葱、醉物、猪肉、桃、李、雀肉等」，荆沥汤「忌海藻、落菜、醉、生葱、桃、李、雀肉等物」等。"}, {"source": "条27｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "九首方剂各方煎服法也很讲究，药物用量也根据病情轻重而灵活变通，比如同卷载有大竹沥汤一方，方后云“上十四味切，以竹沥一斗，水五升，煮取四升，分服一升，羸人服五合佳。风轻者用竹沥三升，水七升。小重者竹沥五升，水五升。风大剧停水，用竹沥一斗”。”此外还指出该方的副作用：“此汤令人痹，宁少服也。", "白话": "九首方剂的煎服法也很讲究，药物用量根据病情轻重灵活变通。比如同卷载有大竹沥汤，方后说：「上十四味切，以竹沥一斗，水五升，煮取四升，分服一升，羸人服五合佳。风轻者用竹沥三升，水七升。小重者竹沥五升，水五升。风大剧停水，用竹沥一斗」（十四味切碎，以竹沥一斗加水五升煮取四升，每服一升，体弱者服五合为佳；风轻者用竹沥三升、水七升，稍重者竹沥五升、水五升，风甚剧者不加水、单用竹沥一斗）。此外还指出该方的副作用：「此汤令人痹，宁少服也」（此汤可令人痹，宁可少服）。"}, {"source": "条28｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "元代贾铭《饮食须知》提出糯米不宜久食，易发心悸“糯米味甘性温……久食发心悸”。", "白话": "元代贾铭《饮食须知》提出糯米不宜久食、易发心悸：「糯米味甘性温……久食发心悸」（糯米味甘性温……久食引发心悸）。"}, {"source": "条29｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "在导引养生方面，隋巢元方《诸病源候论·第十五卷》第二候提出心脏的生理特点与季节的对应关系及常见证候。，提出了相关的导引字诀：“心脏病者，体有冷热，若冷，呼气出，若热，吹气出”，通过“呼、”“吹”两个字诀来调整心脏的功能，起到预防的作用。又提出了具体的养心导引方法“左胁侧卧，口纳气，申臂直脚，以鼻出之。周而复始，除心下不便也。", "白话": "在导引养生方面，隋代巢元方《诸病源候论·第十五卷》第二候提出心脏的生理特点与季节的对应关系及常见证候，并提出相关的导引字诀：「心脏病者，体有冷热，若冷，呼气出，若热，吹气出」（心脏病身体有冷有热，冷则用「呼」字吐气，热则用「吹」字吐气），通过「呼」「吹」两个字诀调整心脏功能，起到预防作用。又提出具体的养心导引方法：「左胁侧卧，口纳气，申臂直脚，以鼻出之。周而复始，除心下不便也」（左侧卧，口吸气，伸臂直腿，以鼻呼出，周而复始，除心下不适）。"}, {"source": "条30｜《心悸·第七章 评述》三、心悸调护方法与手段", "原文": "南朝陶弘景《养性延命录》载“吹以去热，呼以去风”，进一步明确了吹字诀和呼字诀对心脏功能的调护作用。", "白话": "南朝陶弘景《养性延命录》载「吹以去热，呼以去风」，进一步明确了吹字诀与呼字诀对心脏功能的调护作用。"}, {"source": "条1｜《素问·藏脏气法时论》", "原文": "心主夏，手少阴，太阳主治，其日丙丁，心苦缓，急食酸以收之。", "白话": "心气旺于夏，与手少阴心经、手太阳小肠经相应，旺日是丙丁日。心气苦于涣散不收，宜急食酸味药食以收敛之。"}, {"source": "条2｜《素问·藏气法时论》", "原文": "心色赤，宜食酸，小豆、犬肉、李、韭皆酸。", "白话": "心对应赤色，宜食酸味：小豆、狗肉、李子、韭菜都属酸味（注：古五味归属与今有异）。"}, {"source": "条3｜《素问·举痛论》", "原文": "惊则心无所倚，神无所归，虑无所定，故气乱矣。", "白话": "大惊则心神失去依附，神无所归宿，思虑无所定止，所以气机紊乱。"}, {"source": "条4｜《素问·五藏脏生成论》", "原文": "赤，脉之至也，喘而坚，诊曰有积气在中，时害于食，名曰心痹，得之外疾，思虑而心虚，故邪从之。", "白话": "面色赤、脉来急疾而坚，诊断为中有积气、时常妨碍饮食，病名心痹——因外邪侵袭，加上思虑过度心气虚，邪气乘虚而入。"}, {"source": "条5｜《灵枢·五味》", "原文": "五禁：肝病禁辛，心病禁咸，脾病禁酸，肾病禁甘，肺病禁苦。", "白话": "五脏病饮食禁忌：肝病忌辛味，心病忌咸味，脾病忌酸味，肾病忌甘味，肺病忌苦味。"}, {"source": "条6｜《灵枢·口问》", "原文": "悲哀愁忧则心动，心动则五藏五脏六府六腑皆摇。", "白话": "悲哀愁忧等情志先扰动于心，心一动则五脏六腑都随之动摇不安。"}, {"source": "条7｜《肘后备急方》卷三", "原文": "治惊忧怖迫逐，或惊恐失财，或激愤惆怅，致志气错越，心行违僻不得安定者……又方白雄鸡一头治如食，真珠四两切，薤白四两。以水三升，煮取二升。宿勿食，旦悉食鸡等及饮汁尽。", "白话": "治因惊吓忧惧、失财受惊或激愤惆怅，以致神志错乱、行为乖戾不得安定者。又方：白公鸡一只按食用法处理，珍珠四两切碎，薤白四两，加水三升煮取二升；前一夜禁食，清晨把鸡、药、汁全部吃完。"}, {"source": "条8｜《诸病源候论·第一卷》", "原文": "养生方云：精藏于玉房，交接太数，则失精。失精者，令人怅怅，心常惊悸。", "白话": "养生书说：精藏于肾（玉房），房事太频则失精；失精使人怅然若失、心常惊悸。"}, {"source": "条9｜《诸病源候论·第十五卷》", "原文": "养生方导引云：心脏病者，体有冷热，若冷，呼气出；若热，吹气出。又云：左胁侧卧，口内气，申臂直脚，以鼻出之，周而复始，除心下不便也。", "白话": "养生导引法：心脏病身体发冷发热，冷则用「呼」字吐气，热则用「吹」字吐气。又法：左侧卧，口吸气，伸臂直腿，用鼻呼出，周而复始，可除心下不适。"}, {"source": "条10｜《外台秘要》卷十五·镇心丸（《广济》）", "原文": "疗热风惊悸，安心，久服长年，镇心丸方。茯神 人参 龙齿研 升麻 石膏研 黄芩 茯苓 麦门冬八分，去心 银薄二百番研 虎睛一具，炙 枳实炙 白蔹 玄参 芍药 葳蕤 甘草炙，各六分 生姜二分。上十七味捣筛，蜜和丸……忌海藻、菘菜、醋、蒜、面、黏食、陈臭等物。", "白话": "治热风惊悸、安心神、久服延年之镇心丸：茯神、人参、龙齿（研）、升麻、石膏（研）、黄芩、茯苓、麦门冬（去心）各八分，银箔二百番（研），虎睛一具（炙），枳实（炙）、白蔹、玄参、芍药、葳蕤、炙甘草各六分，生姜二分。共十七味捣筛、蜜丸，食后少时服梧子大十五丸，日二，渐加至三十丸。忌海藻、白菜、醋、蒜、面、黏食、陈臭物。"}, {"source": "条11｜《外台秘要》卷十五·大定心丸（深师）", "原文": "疗恍惚惊悸，心神不安，或风邪因虚加藏，语言喜忘，胸胁满，不得饮食方。人参 桂心各三两 白术 防己 茯苓 干姜 防风 大黄 茯神 桔梗 白蔹各一两 牛膝十铢 远志二两去心 银屑六铢……忌生葱、酢物、猪肉、桃李、雀肉等。", "白话": "治恍惚惊悸、心神不安，或风邪乘虚入脏、健忘多语、胸胁满闷、饮食不下：人参、桂心各三两，白术、防己、茯苓、干姜、防风、大黄、茯神、桔梗、白蔹各一两，牛膝十铢，远志（去心）二两，银屑六铢。共十四味蜜丸梧子大，饭前服五丸日三，不效渐增。忌生葱、酸物、猪肉、桃李、雀肉。"}, {"source": "条12｜《外台秘要》卷十五·补心汤", "原文": "疗心气不足，其病苦满，汗出心风，烦闷善恐，独苦多梦，不自觉者，咽喉痛，时时吐血，舌本强，水浆不通，手掌热，心惊悸，吐下血方。麦门冬三两去心 紫石英五分 紫菀二两 桂心一尺 茯苓四两 小豆二十四枚 人参半两 大枣二十五枚 甘草五寸炙……忌海藻、菘菜、生葱、酢物。", "白话": "治心气不足：胸中满闷、汗出、烦闷善恐、多梦、咽喉痛、时时吐血、舌根强硬、饮食难下、手掌热、心惊悸、吐血便血。麦门冬（去心）三两、紫石英五分、紫菀二两、桂心一尺、茯苓四两、小豆二十四枚、人参半两、大枣二十五枚、炙甘草五寸。九味水八升煮取二升四合，体弱者分三服，强壮者二服；心旺之时、有血证者可服。忌海藻、白菜、生葱、酸物。"}, {"source": "条13｜《外台秘要》卷十五·荆沥汤（《千全》）", "原文": "疗心虚寒，阴阳寒损，心惊掣悸，语声宽急混濯，口㖞冒昧，好自笑，历风伤心，荆沥汤方。荆沥三升 麻黄去节 白术 芎䓖各四两 防风 桂心 升麻 茯苓 远志去心 人参 羌活 当归各三两 防己 甘草炙各二两 母姜切一升取汁……分为四服，日三夜一。", "白话": "治心虚寒、阴阳俱损：心惊掣悸、语声时缓时急混浊、口歪神昧、无故自笑、风邪历节伤心。荆沥三升，麻黄（去节）、白术、芎䓖各四两，防风、桂心、升麻、茯苓、远志（去心）、人参、羌活、当归各三两，防己、炙甘草各二两，生姜一升取汁。水一斗先煮麻黄去沫，下诸药煮取三升，去滓，入荆沥姜汁煎取四升，分四服，日三夜一。"}, {"source": "条14｜《外台秘要》卷十五·大镇心丸", "原文": "疗心虚惊悸，梦寤恐畏方。紫石英 茯苓 防风 人参 甘草炙 泽泻各八分 秦艽 黄芪 白术 薯蓣 白蔹各六分 麦门冬 当归各五分 桂心 远志去心 柏子仁 石膏 桔梗 大黄 大豆卷各四分 椒汗去目 芍药 干姜 细辛各三分。上二十四味，酒服如梧子大十五丸，日再。", "白话": "治心虚惊悸、睡醒惊恐：紫石英、茯苓、防风、人参、炙甘草、泽泻各八分，秦艽、黄芪、白术、薯蓣、白蔹各六分，麦门冬、当归各五分，桂心、远志（去心）、柏子仁、石膏、桔梗、大黄、大豆卷各四分，花椒、芍药、干姜、细辛各三分。共二十四味，酒服梧子大十五丸，日二。"}, {"source": "条15｜《外台秘要》卷十五·小镇心散", "原文": "疗心气不足，虚悸恐畏，悲思恍惚，心神不定，惕惕而惊方。人参 远志去心 赤小豆 附子炮 桂心 细辛 干姜 防风 龙齿炙 菖蒲 干地黄各二两 茯苓 白术 黄芪各四两。上十四味，捣筛为散，以酒服两方寸匕，日三。", "白话": "治心气不足：虚悸恐畏、悲思恍惚、心神不定、惕惕易惊。人参、远志（去心）、赤小豆、炮附子、桂心、细辛、干姜、防风、炙龙齿、菖蒲、干地黄各二两，茯苓、白术、黄芪各四两。共十四味捣筛为散，酒服两方寸匕，日三。"}, {"source": "条16｜《外台秘要》卷十五·崔氏热风惊掣汤", "原文": "崔氏疗热风惊掣，心忪恐悸，风邪狂叫妄走者，服此汤亦差，朱四频用之极效方。茯神三两 杏仁三两去皮尖切 升麻 白鲜皮 沙参各二两 龙齿六两炙 寒水石一斤碎绵裹 石膏二十两碎绵裹 生麦门冬去心四两……若甚者减水三升，内竹沥三升……忌酢物。", "白话": "崔氏治热风惊掣、心慌恐悸、风邪狂叫乱跑方（朱四多次使用极效）：茯神三两、杏仁（去皮尖切）三两，升麻、白鲜皮、沙参各二两，炙龙齿六两，寒水石一斤（碎绵裹），石膏二十两（碎绵裹），生麦门冬（去心）四两。九味水一斗二升煎取三升，分温三服；病重者减水三升加竹沥三升。忌酸物。"}, {"source": "条17｜《外台秘要》卷十五·茯神汤（《古今录验》）", "原文": "疗风经五藏五脏虚惊悸，安神定志方。龙骨一两 干姜一两半 细辛一两半 白术一两 茯神三两 人参 远志去心 甘草炙 桂心 独活各二两 酸枣仁一两 防风二两。上十二味切，以水九升煮取三升，分为三服。", "白话": "治风邪侵入五脏之虚惊悸、安神定志：龙骨一两，干姜、细辛各一两半，白术一两，茯神三两，人参、远志（去心）、炙甘草、桂心、独活各二两，酸枣仁一两，防风二两。十二味水九升煮取三升，分三服。"}, {"source": "条18｜《外台秘要》卷十五·大竹沥汤", "原文": "疗大虚风气，人腹拘急，心痛烦冤，恍惚迷惑不知人，或惊悸时怖，吸吸口干，涩涩恶寒，时失精明，历节疼痛，或缓或不摄，产妇体虚，受风恶寒，惨惨愦愦，闷心欲绝者。并疗风痉，口噤不开……茵芋有毒，令人闷乱目花，虚人可半两良……", "白话": "治大虚风邪入腹：腹中拘急、心痛烦冤、恍惚不识人、阵发惊悸恐怖、气短口干、恶寒、时神昏、关节疼痛、或弛缓不收；又治产妇体虚受风恶寒、昏闷欲绝，及风痉口噤不开。秦艽、防风、茯苓、人参各二两，茵芋、炮乌头、黄芩、干姜、当归、细辛、白术各一两，炮天雄一枚，炙甘草三两，防己二两。竹沥一斗水五升煮取四升，分服。茵芋有毒令人闷乱目花，虚人用半两为宜。"}, {"source": "条19｜《外台秘要》卷三十七", "原文": "又若饮酒不解，食不得下，乍寒乍热，不洗便热，洗之复寒，甚者数十日，轻者数日，昼夜不得寝寐，愁悲恚怒，自惊跳悸。", "白话": "饮酒不消、饮食不下、忽冷忽热（不洗澡觉热、洗澡又冷），重者数十日、轻者数日，昼夜不能入睡，忧愁悲怒，自感惊跳心悸。"}, {"source": "条20｜《太平圣惠方》卷九十六·苦竹叶粥", "原文": "治风邪癫痫，心烦惊悸，宜吃苦竹叶粥方。苦竹叶二握 粟米二合。右上，先以水二大盏半，煮苦竹叶，取汁一盏五分，去滓，用米煮作粥，空腹食之。", "白话": "治风邪癫痫、心烦惊悸的食疗方：苦竹叶两握、粟米二合。先以水两大盏半煮苦竹叶取汁一盏半，去渣，加米煮粥，空腹食用。"}, {"source": "条21｜《太平圣惠方》卷九十六·茯苓粥", "原文": "治心胸结气，烦闷恐悸，风热惊邪，口干，茯苓粥方。赤茯苓一两 麦门冬一两去心 粟米二合。右上件药，细锉，先以水二大盏，煮至一盏半，去滓，下米煮粥，温温食之。", "白话": "治心胸气结、烦闷恐悸、风热惊邪、口干：赤茯苓一两、麦门冬（去心）一两、粟米二合。药细锉，水两大盏煮至一盏半去渣，下米煮粥，温食。"}, {"source": "条22｜《太平圣惠方》卷九十六·茯神粥", "原文": "治心胸结气，烦热，或渴，狂言惊悸，茯神粥方。茯神一两 羚羊角半两 粳米三合。上二味，捣罗为末，与米同煮为粥，食之。", "白话": "治心胸结气、烦热或口渴、狂言惊悸：茯神一两、羚羊角半两、粳米三合。前二味捣罗为末，与米同煮粥食。"}, {"source": "条23｜《养老奉亲书》·炖胎盘方", "原文": "食治老人久病喘息，咳嗽，吐少量清稀痰，动则喘甚，张口抬肩，心悸少寐，虚羸消瘦，舌淡，两寸尺脉弱，炖胎盘方。胎盘一具取新鲜者清水漂净污血切块 杏仁五钱去皮尖 百合一两渍一宿当白沫出去其水 胡桃仁净者一两。上四味，加水四碗，熟炖至两碗，入盐酱等调味品，分两次食之，早晚各服一次。", "白话": "食治老人久病气喘、咳嗽、吐少量清稀痰、动则喘甚、张口抬肩、心悸少眠、消瘦、舌淡、寸尺脉弱：新鲜胎盘一具（漂净切块）、杏仁五钱（去皮尖）、百合一两（浸一夜出白沫后去水）、胡桃仁一两。四味加水四碗炖至两碗，调味分两次早晚服。"}, {"source": "条24｜《圣济总录》卷九十一·大琥珀散", "原文": "治虚劳脱营，真气不足，形体毁沮，四肢沉重，咽干口燥，饮食无味，气乏少力。远视䀮䀮，惊悸不安，五脏虚损，病从内生，大琥珀散方。琥珀研二两 干姜炮 石苇去毛 滑石研 牡丹皮 白茯苓 芎䓖 石斛 续断 当归 远志 人参 牛膝各三两 桂去粗皮二两半 肉苁蓉 松脂 牡蒙 陈橘皮各四两 荏子 松实 柏子仁各三升 车前子 菟丝子 菴䕡子 枸杞子 胡麻子 芜菁子 麦门冬各一升 木通十四两 蛇床子炒半升……每服三钱", "白话": "治虚劳脱营、真气不足：形体衰败、四肢沉重、咽干口燥、饮食无味、气短乏力、视物模糊、惊悸不安、五脏虚损（病从内生）。大琥珀散：琥珀（研）二两，炮干姜、石苇、滑石、牡丹皮、白茯苓、芎䓖、石斛、续断、当归、远志、人参、牛膝各三两，桂心二两半，肉苁蓉、松脂、牡蒙、陈橘皮各四两，荏子、松实、柏子仁各三升，车前子、菟丝子、菴䕡子、枸杞子、胡麻子、芜菁子、麦门冬各一升，木通十四两，炒蛇床子半升。共三十味为散，每服三钱匕，牛乳半盏水一盏同煎温服；久服强身益气。"}, {"source": "条25｜《太平惠民和剂局方》卷五·黄芪六一汤", "原文": "大治男子、妇人诸虚不足，肢体劳倦，胸中烦悸，时常焦渴，唇口干燥，面色痿黄，不能饮食。或先渴而欲发疮疖，或病痈疽而后渴者，尤宜服此。常服平补气血，安和脏腑。黄芪去芦蜜炙六两 甘草炙一两。右上㕮咀。每二钱，水一盏，枣一枚，煎至七分，去滓，温服，不拘时。", "白话": "治男女诸虚不足：肢体劳倦、胸中烦悸、常口渴、唇口干燥、面色萎黄、不能饮食；或先渴而发疮疖、或痈疽后口渴者尤宜。常服平补气血、安和脏腑。蜜炙黄芪六两、炙甘草一两，每服二钱加枣一枚煎。"}, {"source": "条26｜《太平惠民和剂局方》卷五·大山蓣圆", "原文": "治诸虚百损，五劳七伤，肢体沉重，骨节痠疼，心中烦悸，唇口干燥，面体少色，情思不乐，咳嗽喘乏，伤血动气，夜多异梦，盗汗失精，腰背强痛，脐腹弦急，嗜卧少起，喜惊多忘，饮食减少，肌肉瘦瘁……久服补诸不足，愈风气百疾。", "白话": "治诸虚百损、五劳七伤：肢体沉重、骨节酸痛、心中烦悸、口干、面色无华、情志不乐、咳嗽气乏、伤血动气、多噩梦、盗汗失精、腰背强痛、脐腹拘急、嗜卧、易惊健忘、纳少消瘦。久服补诸不足。白术、麦门冬、白芍药、杏仁、防风、芎䓖各一两半，大豆黄卷、熟地、肉桂、曲、当归各二两半，桔梗、茯苓、柴胡各一两二钱半，炮干姜七钱半，炙甘草七两，大枣一百个，阿胶、人参各一两七钱半，白蔹半两，山蓣七两半。蜜枣丸弹子大，每服一圆。"}, {"source": "条27｜《太平惠民和剂局方》卷五·定志圆", "原文": "治心气不定，五脏不足，恍惚振悸，忧愁悲伤，差错谬忘，梦寐惊魇，恐怖不宁，喜怒无时，朝差暮剧，暮差朝剧，或发狂眩，并宜服之。远志去苗及心 菖蒲各二两 人参 白茯苓去皮各三两。右上为细末，炼蜜圆，如梧桐子大，朱砂为衣。每服七圆，加至二十圆，温米饮下，食后，临卧，日三服。常服益心强志，令人不忘。", "白话": "治心气不定、五脏不足：恍惚心悸、忧愁悲伤、差错健忘、噩梦惊魇、恐怖不宁、喜怒无常、晨轻暮重或暮轻晨重，或发狂眩。远志、菖蒲各二两，人参、茯苓各三两。细末蜜丸梧子大、朱砂为衣，每服七丸渐加至二十丸，米饮下，食后临卧日三。常服益心强志。"}, {"source": "条28｜《杨氏家藏方》卷九·三仁五子圆", "原文": "治血气耗虚，五脏不足，睡中惊悸，盗汗怔忪，梦遗失精，四肢倦懈，肌肤瘦弱，或发寒热，饮食减少。常服养心益肝，生血补气……菟丝子 五味子 枸杞子 覆盆子 车前子 柏子仁 酸枣仁炒 薏苡仁微炒 沉香 鹿茸 肉苁蓉 巴戟 当归 白茯苓 乳香 熟干地黄各一两……每服五十圆，温酒或盐汤送下，空心。", "白话": "治血气耗虚、五脏不足：睡中惊悸、盗汗怔忡、梦遗失精、四肢倦怠、消瘦、或寒热、纳少。常服养心益肝、生血补气。三仁（柏子仁、酸枣仁、薏苡仁）五子（菟丝子、五味子、枸杞子、覆盆子、车前子）加沉香、鹿茸、肉苁蓉、巴戟、当归、茯苓、乳香、熟地各一两。蜜丸每服五十丸，温酒或盐汤空心下。"}, {"source": "条29｜《杨氏家藏方》卷十·四味补心圆", "原文": "益血补心，安神定志。治怔忪惊悸，恍惚健忘。当归酒洗焙干二两 朱砂一两别研 肉苁蓉酒浸一宿焙干二两 杏仁一百五十枚汤泡去皮尖研成膏。右上件为细末，以杏仁膏同和……圆如绿豆大。每服三十圆，用米饮或温酒下，不拘时候。", "白话": "益血补心、安神定志，治怔忡惊悸、恍惚健忘。当归（酒洗）二两、朱砂一两（另研）、肉苁蓉（酒浸）二两、杏仁一百五十枚（去皮尖研膏）。细末以杏仁膏和匀，丸绿豆大，每服三十丸米饮或温酒下。"}, {"source": "条30｜《传信适用方》卷上·愈山人镇心丹", "原文": "黄芪五两炙 熟干地黄二两半 五味子二两半 柏子仁二两半 远志二两半 白茯神五两 酸枣仁五两去皮炒 朱砂三两别研为衣……此药性平凉，无毒，善安镇神脏，补养心气。专治惊忧思虑过伤，心气不足，怔忡盗汗，乱梦失精，卒暴心痛，中风不语，风痫癫狂，客忤不省，悲哭无常，色脱神瘁，飞尸鬼疰，恍惚惊悸，吐血便血，虚劳羸瘦，病后虚烦，不得眠睡，产前安胎，产后补虚，极有大功，种种心疾悉皆主之。恍惚惊悸怔忡不止，煎人参茯", "白话": "镇心丹：炙黄芪五两，熟地、五味子、柏子仁、远志各二两半，茯神、炒枣仁各五两，朱砂三两（另研为衣）。性平凉，安镇神脏、补养心气。主治惊忧思虑过度、心气不足、怔忡盗汗、乱梦失精、猝发心痛、中风不语、风痫癫狂、神志恍惚、惊悸、吐血便血、虚劳消瘦、病后虚烦不眠、产前安胎、产后补虚等一切心疾。服法随证调引：恍惚惊悸怔忡不止用人参茯神汤下；盗汗用参麸汤下；乱梦失精用人参龙骨汤下；猝发心乱用乳香汤下……"}, {"source": "条31｜《妇人大全良方》卷九·紫石英圆", "原文": "紫石英圆又名紫石门冬圆。紫石英 天门冬各三两 紫葳 牡蒙各二两 粉草一两半 桂心 川芎 卷柏 乌头炮 熟地黄 辛夷仁 禹余粮煅醋淬 当归 石斛各三两 乌贼骨 川牛膝 薯蓣各六分 桑寄生 人参 牡丹皮 干姜 厚朴 续断 食茱萸 细辛各五分 柏子仁一两。右上为细末，炼蜜圆如梧桐子大。每服三十圆，温酒吞下。渐加至五十圆。", "白话": "紫石英丸（又名紫石门冬丸）：紫石英、天门冬各三两，紫葳、牡蒙各二两，甘草一两半，桂心、川芎、卷柏、炮乌头、熟地、辛夷仁、煅禹余粮（醋淬）、当归、石斛各三两，乌贼骨、川牛膝、薯蓣各六分，桑寄生、人参、牡丹皮、干姜、厚朴、续断、食茱萸、细辛各五分，柏子仁一两。蜜丸梧子大，温酒下三十丸渐加至五十丸。"}, {"source": "条32｜《饮膳正要》卷一·炙羊心", "原文": "治心气惊悸，郁结不乐。羊心一个，带系桶 咱夫兰三钱。右上件用玫瑰水一盏，浸取汁，入盐少许，签子签羊心，于火上炙，将咱夫兰汁徐徐涂之，汁尽为度，食之安宁心气，令人多喜。", "白话": "治心气惊悸、郁郁不乐：羊心一个，咱夫兰（藏红花）三钱。玫瑰水一盏浸咱夫兰取汁加盐少许；羊心串签火烤，边烤边涂花汁，汁尽为度。食之安和心气、令人愉悦。"}, {"source": "条33｜《世医得效方》卷十四·大圣茯苓散", "原文": "治妊娠气闷，或为喧呼，心忪悸乱，睡里多惊，两胁膨胀，腹满连脐急痛，坐卧不安，气急逼迫，胎惊者。屡效。白茯苓去皮 川芎各一两 麦门冬去心一两 黄芪去芦蜜炙一两 当归去芦酒浸一两 木香不见火 条参 甘草各半两。上锉散。每服四钱，水一盏半，生姜五片煎，温服，不拘时候。常服，至分娩亦无恙，安养胎气甚佳。", "白话": "治妊娠气闷（或受惊喧呼）后心慌悸乱、睡中易惊、两胁胀、腹满连脐急痛、坐卧不安、气急、胎动不安，屡用有效。茯苓、川芎、麦门冬、蜜炙黄芪、当归各一两，木香、条参、甘草各半两。锉散每服四钱姜五片煎温服。常服安胎至分娩。"}, {"source": "条34｜《饮食须知》卷二·糯米", "原文": "糯米味甘性温。多食发热，壅经络之气，令身软筋缓。久食发心悸，及痈、疽、疮疖中痛。", "白话": "糯米味甘性温，多食生热、壅滞经络之气，令人身软筋缓；久食诱发心悸及疮痈疼痛。"}, {"source": "条35｜《奇效良方》卷二十二·人参补虚汤", "原文": "治虚劳，少气不足，四肢困弱，嗜卧少力，心中悸动，夜多盗汗，常服补诸虚不足，建中进食。人参 黄芪 陈皮去白 白芍药 当归 官桂去皮 细辛去叶 麦门冬去心 前胡 半夏汤泡 甘草炙 白茯苓去皮 熟干地黄以上各二两。上为细末，每服三钱，水一大盏，生姜五片，枣二枚，煎至七分，食前稍热服。", "白话": "治虚劳：气短不足、四肢困弱、嗜卧乏力、心中悸动、夜间盗汗。常服补诸虚不足、建中进食。人参、黄芪、陈皮、白芍、当归、官桂、细辛、麦冬、前胡、半夏、炙甘草、茯苓、熟地各二两。细末每服三钱姜枣煎，食前温服。"}, {"source": "条36｜《养生四要·寡欲第一》", "原文": "酒客病酒，酒停不散。清则成饮，浊则成痰。入于肺则为喘，为咳。入于心则为心痛，为怔忡，为噫。", "白话": "嗜酒者病酒，酒湿停滞不散：清稀者成饮、稠浊者成痰。入肺则喘咳，入心则心痛、怔忡、嗳气。"}, {"source": "条37｜《景岳全书·怔忡惊恐》", "原文": "诸动气皆不可汗下也。凡此者，即皆怔忡之类。此证惟唯阴虚劳损之人乃有之，盖阴虚于下，则宗气无根，而气不归源，所以在上则浮撼于胸臆，在下则振动于脐旁。虚微者动亦微，虚甚者动亦甚。凡患此者，速宜节欲节劳，切戒酒色。凡治此者，速宜养气养精，滋培根本，若或误认为痰火而妄施清利，则速其危矣。", "白话": "凡脐腹动气之证都不可发汗攻下，都属怔忡之类。此证只见于阴虚劳损之人：阴虚于下则宗气无根、气不归源，在上则胸中浮撼，在下则脐旁振动。虚轻微则动轻微，虚重则动重。患者须节欲节劳、戒酒色；治疗须养气养精、滋培根本；若误认作痰火而妄用清利，则加速其危。"}, {"source": "条38｜《证治汇补》卷五", "原文": "有膏梁厚味，积成痰饮，口不作干，肌肤润泽如故，忽然惊惕而作悸，其脉弦滑有力者是也。", "白话": "有嗜食肥甘厚味、积成痰饮者，口不干、肌肤润泽如常，忽然惊惕心悸，脉弦滑有力。"}, {"source": "条39｜《灵验良方汇编》卷上·归脾汤", "原文": "归脾汤。治脾经郁火，或失血，盗汗，或惊悸怔忡，或肢体作痛等症。人参 白术 黄芪 茯苓 当归 远志 龙眼 枣仁 木香 甘草。加柴胡、山栀即加味归脾汤，治失血过多、发热有汗，或怔忡惊悸、妄言妄见、睡卧不安等症。", "白话": "归脾汤治脾经郁火、失血、盗汗、惊悸怔忡、肢体疼痛等：人参、白术、黄芪、茯苓、当归、远志、龙眼肉、枣仁、木香、甘草。加柴胡、山栀名加味归脾汤，治失血过多、发热有汗、怔忡惊悸、妄言妄见、睡卧不安。"}, {"source": "条40｜《寿世传真》·猪心", "原文": "猪心性平，治惊邪虚悸，补心血不足。", "白话": "猪心性平，治惊邪虚悸，补心血不足。"}, {"source": "条41｜《调疾饮食辩》卷三·薯蓣", "原文": "薯蓣，一名玉延……凡虚劳羸瘦、盗汗、怔忡等症，宜多食。味甘微涩，凡脾虚久泻、肾虚精滑、便数等症，尤宜多食。", "白话": "薯蓣（山药）又名玉延：凡虚劳消瘦、盗汗、怔忡等宜多食；味甘微涩，脾虚久泻、肾虚精滑、尿频者尤宜。"}, {"source": "条42｜《调疾饮食辩》卷五·猪肉", "原文": "《纲目》曰：牡曰豭，牝曰豝……其余，则心补心（主虚汗惊悸，多梦怔忡）。", "白话": "《本草纲目》说猪的公母各有古名；其心可补心，主治虚汗惊悸、多梦怔忡。"}, {"source": "条43｜《湿温时疫治疗法》第三章", "原文": "虚症属阴亏，张石顽所谓痢下五色，脓血稠黏，滑泄无度，多属阴虚是也。不拘次数多寡，便见腰膝酸软，耳鸣心悸，咽干目眩，不寐多烦，或次数虽多，而胸腹不甚痛，或每痢后而烦困更增，掣痛反甚，饮食不思，速用猪肤汤合黄连阿胶汤，加茄楠香汁，甘咸救阴，苦味坚肠。", "白话": "虚证属阴亏（如张石顽说痢下五色、脓血稠黏、滑泄无度多属阴虚）：不论次数多少，见腰膝酸软、耳鸣心悸、咽干目眩、不寐多烦，或虽泻次多而胸腹不甚痛，或每泻后烦困更甚、掣痛反剧、饮食不思，速用猪肤汤合黄连阿胶汤加茄楠香汁，甘咸救阴、苦味坚肠。"}, {"source": "条1｜《华佗神方》卷一", "原文": "心虚则恐惧多惊，忧思不乐，胸腹中苦痛，言语颤栗，恶寒恍惚，面赤目黄，喜衄，诊其寸口两虚而微者是也。", "白话": "心虚就会恐惧而容易惊骇，忧愁思虑、闷闷不乐，胸腹里疼痛难受，说话声音颤抖，怕冷而精神恍惚，面色发红、眼睛发黄，容易鼻出血；诊察寸口脉两部都见虚而微的，就是这种证候。"}, {"source": "条2｜《太平圣惠方》卷四", "原文": "夫心虚则多惊，胆虚则多恐。此皆气血不实，腑脏虚伤，风邪所干，入于经络，心既不足，胆气衰微，故令神思恐怯而多惊悸也。", "白话": "心虚就会多惊，胆虚就会多恐。这都是气血不充、脏腑虚损，风邪所侵犯，进入经络；心既不足，胆气衰微，所以使人神思恐惧怯弱而多惊悸。"}, {"source": "条3｜《圣济总录》卷四十二", "原文": "论曰：胆虚不得眠者，胆为中正之官，足少阳其经也，若其经不足，复受风邪则胆寒，故虚烦而寝卧不安也。治肝虚胆寒，夜间少睡，睡即惊觉，心悸，神思不安，目昏心躁，肢节痿弱，补肝去胆寒和气。", "白话": "论述说：胆虚不能睡眠的病——胆是主决断的中正之官，其经脉为足少阳；如果该经气血不足，又感受风邪，胆就会寒，所以虚烦而睡卧不安。治疗肝虚胆寒，夜间睡眠少，睡着就惊醒、心悸、神思不安、眼睛昏花、心中烦躁、肢节痿软无力，用补肝、去胆寒、和气的方法。"}, {"source": "条4｜《奇效良方》卷四十六", "原文": "且夫惊悸即动悸也。动之为病，惕然而惊，悸之为病，心下怯怯，如人所捕，皆心虚胆怯之所致也，且心者，君主之官，神明出焉；胆者，中正之官，决断出焉。心事安逸，胆气不怯，决断思虑得其所矣。或因事有所大惊，或闻虚响，或见异相，登高涉险，惊忤心神，气与涎郁，遂使惊悸。惊悸不已，变生诸证。或短气悸乏，或体倦自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安，皆心虚胆怯之候也。人之所主心，心之所养血，心血一虚，神气不守", "白话": "而且惊悸就是动悸。动作为病，是惕然而惊；悸作为病，是心下怯怯不安，好像有人要抓捕自己——这都是心虚胆怯所造成的。心是君主之官，神明由此而出；胆是中正之官，决断由此而出。心境安逸，胆气不虚怯，决断与思虑就各得其所。或因遇事受到大惊，或听到空虚怪异声响，或见到怪异形像，登高涉险，惊动触犯心神，气与涎郁结，于是发生惊悸。惊悸不止，变生各种证候：或气短心悸乏力，或肢体倦怠自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安——这都是心虚胆怯的证候。人的主宰是心，心所奉养的是血；心血一旦亏虚，"}, {"source": "条5｜《医方选要》卷七", "原文": "若夫动悸者，谓心中惕然动悸而惊也，心下怯怯，如人将捕，由心胆虚怯之所致也。盖心者，君主之官，神明出焉；胆者，中正之官，决断出焉。或因事有所大惊，或见异相，登高涉险，惊忤心神，气与涎郁，则必惊悸，惊悸不已，变生诸证。或短气悸乏，或体倦自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不宁，此皆心胆虚怯之候也。", "白话": "至于动悸，是说心中惕然动悸而发惊，心下怯怯不安，好像有人要抓捕自己，由心胆虚怯所造成。心是君主之官，神明由此而出；胆是中正之官，决断由此而出。或因遇事受到大惊，或见到怪异形像，登高涉险，惊动触犯心神，气与涎郁结，就必然惊悸；惊悸不止，变生各种证候。或气短心悸乏力，或肢体倦怠自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不宁——这都是心胆虚怯的证候。"}, {"source": "条6｜《严氏济生方·惊悸怔忡健忘门》", "原文": "夫惊悸者，心虚胆怯之所致也。且心者，君主之官，神明出焉，胆者，中正之官，决断出焉。心气安逸，胆气不怯，决断思虑得其所矣。或因事有所大惊，或闻虚响，或见异相，登高涉险，惊忤心神，气与涎郁，遂使惊悸，惊悸不已，变生诸证，或短气悸乏，体倦自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安，皆心虚胆怯之候也。治之之法，宁其心以壮胆气，无不瘥者矣。", "白话": "惊悸是心虚胆怯所造成的。心是君主之官，神明由此而出；胆是中正之官，决断由此而出。心气安逸，胆气不虚怯，决断与思虑就各得其所。或因遇事受到大惊，或听到空虚怪异声响，或见到怪异形像，登高涉险，惊动触犯心神，气与涎郁结，于是发生惊悸；惊悸不止，变生各种证候：或气短心悸乏力，肢体倦怠自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安——这都是心虚胆怯的证候。治疗的方法，是安宁心神以壮胆气，没有不痊愈的。"}, {"source": "条7｜《证治准绳·杂病》", "原文": "心胆虚怯，触事易惊，或梦寐不祥，遂致心惊胆慑，气郁生涎，涎与气搏，变生诸证，或短气悸乏，或复自汗者，并温胆汤主之。", "白话": "心胆虚怯，遇事容易受惊，或梦寐不祥，于是导致心惊胆怯，气郁而生涎，涎与气相搏结，变生各种证候；或气短心悸乏力，或又自汗的，一并用温胆汤主治。"}, {"source": "条8｜《济阳纲目》卷五十四", "原文": "又曰：惊悸或因事有所大惊，触忤心神，气与涎郁，遂成惊悸，此乃心虚胆怯所为，宜养心汤，或温胆汤。", "白话": "又说：惊悸或因遇事受到大惊，触犯心神，气与涎郁结，于是形成惊悸，这是心虚胆怯所造成的，宜用养心汤，或温胆汤。"}, {"source": "条9｜《证治汇补》卷五", "原文": "肝胆心虚。或因怒伤肝，或因惊入胆，母令子虚，而心血为之不足。或富贵汲汲，贫贱戚戚，忧思过度，或遇事烦冗，则心君亦为之不宁，皆致惊悸怔忡之症。其脉弦者是也。汇补", "白话": "肝胆心虚。或因发怒伤肝，或因受惊入胆，母虚令子虚，而心血因此不足。或急切追求富贵、忧愁贫贱，忧思过度，或遇事繁杂，那么心君也因此不宁，都能导致惊悸怔忡之症。其脉象弦的就是。“汇补”为原书引文标记。"}, {"source": "条10｜《身经通考·身经通考卷二图说》", "原文": "心虚，病苦悸恐不乐，心腹痛难以言，心如寒，状恍惚，手心热，肘臂挛急，腋肿，心中大动。", "白话": "心虚，病苦于心悸恐惧不乐，心腹疼痛难以言语，心中寒冷，精神恍惚，手心发热，肘臂拘挛紧急，腋下肿，心中剧烈跳动。"}, {"source": "条11｜《医学答问》卷一", "原文": "里有胆虚，舌边淡白，左关脉细软，其症为惊悸者，心血不足以壮之也，宜安神定志丸；太息者，气虚也，宜四君子汤。", "白话": "里有胆虚之证，舌边淡白，左关脉细软，其症见惊悸的，是心血不足以壮养它，宜用安神定志丸；善太息的，是气虚，宜用四君子汤。"}, {"source": "条12｜《诸病源候论》卷十五", "原文": "心气不足，则胸腹大，胁下与腰背相引痛，惊悸恍惚，少颜色，舌本强，善忧悲，是为心气之虚也，则宜补之。", "白话": "心气不足，就会胸腹胀大，胁下与腰背相互牵引疼痛，惊悸恍惚，面色少华，舌根强硬，容易忧伤悲哀；这就是心气虚，就应当用补法治疗。"}, {"source": "条13｜《史载之方》卷上", "原文": "产后心虚中风，心中战栗，惊动不安，如人将捕，大府伤冷，六脉微，而肝心脉偏细沉，又产后只缘肾气之虚寒，风邪所中，肾脉细而搏以沉，肾既受病，传其所胜，心感肾邪，非时惊悸，如人将捕，初以益心气、去风邪药治之，次当补其肾，又次当益其肝，足其血，缘心受肾邪，而又肝气微弱，不能生其心气，故以三方药治之。", "白话": "产后心虚又中风邪，心中战栗，惊动不安，好像有人要抓捕自己，大腑伤于寒冷，六部脉微，而肝脉、心脉偏于细沉。又产后只因肾气虚寒，被风邪所中，肾脉细而搏指、沉伏；肾既然受病，就传给它所克的心，心感受肾的邪气，不时惊悸，好像有人要抓捕自己。初起用益心气、去风邪的药治疗，其次当补肾，再其次当补益肝、充养其血——因为心受肾邪，而肝气又微弱，不能生养心气，所以分三步用药治疗。"}, {"source": "条14｜《圣济总录》卷一百六十三", "原文": "论曰：产后气血俱虚，心气不足，风邪乘虚入于手少阴之经，则神气浮越，举动多惊，心悸，目睛不转者，是其候也。", "白话": "论述说：产后气血都虚，心气不足，风邪乘虚进入手少阴心经，于是神气浮越于外，举动多惊，心悸，目睛不转动的，就是它的证候。"}, {"source": "条15｜《妇人大全良方》卷十八", "原文": "二则产后脏虚，心中惊悸，志意不定，言语错乱，不自觉知，神思不安者，当在卜九卷第二论求之。", "白话": "第二种是产后脏虚，心中惊悸，意志不安定，言语错乱而自己不察觉，神思不安的，当在“卜九卷第二论”中求取治法。"}, {"source": "条16｜《万病回春》卷四", "原文": "健忘惊悸、怔忡失志、不寐心风，皆从痰涎沃心，以致心气不足。", "白话": "健忘、惊悸、怔忡、失志、不寐、心风，都因痰涎浸渍于心，以致心气不足。"}, {"source": "条17｜《证治汇补》卷五", "原文": "气虚。有阳气内虚，心下空豁，状若惊悸，右脉大而无力者是也。汇补", "白话": "气虚。有阳气内虚的，心下空虚豁然，症状好像惊悸，右脉大而无力的就是。“汇补”为原书引文标记。"}, {"source": "条18｜《石室秘录》卷六", "原文": "怔忡之症，扰扰不宁，心神恍惚，惊悸不已，此肝肾之虚，而心气之弱也，若作痰治，往往杀人。", "白话": "怔忡之症，纷扰不宁，心神恍惚，惊悸不止，这是肝肾亏虚而心气虚弱；如果当作痰来治疗，往往误人性命。"}, {"source": "条19｜《寿世传真·修养宜堤防疾病第七》", "原文": "面色赤者，心热也。好食苦者，心不足也。怔忡善忘者，心虚也。", "白话": "面色发红的，是心有热；喜食苦味的，是心气不足；怔忡健忘的，是心虚。"}, {"source": "条20｜《医方选要》卷七", "原文": "夫怔忡者，心血不足，心中躁动不宁也。盖心主血，血旺则心主自安矣。一或为喜怒忧恐所动，则真血虚耗，心主失辅而成怔忡矣。", "白话": "怔忡是心血不足、心中躁动不宁。心主血，血旺则心主自然安宁。一旦被喜怒忧恐所触动，真血虚耗，心主失去辅养而成怔忡。"}, {"source": "条21｜《明医指掌》卷一", "原文": "益荣汤。治怔忡恍惚无眠。怔忡，心悸动也。恍惚，如人将捕之，惕惕然之状也。皆荣血不足，致心神不宁，故无眠，益荣汤主之。", "白话": "益荣汤，治疗怔忡恍惚、不得眠。怔忡就是心悸动；恍惚，是好像有人要抓捕自己、惕惕然惊恐的样子。都是荣血不足，导致心神不宁，所以不得眠，用益荣汤主治。"}, {"source": "条22｜《医学纲目》卷五", "原文": "心虚则动悸恍惚，忧烦少色，舌强，宜养荣汤、琥珀定神丸之类，以益其心血。", "白话": "心虚则动悸恍惚，忧愁烦躁、面色少华，舌强，宜用养荣汤、琥珀定神丸之类，以补益心血。"}, {"source": "条23｜《严氏济生方·惊悸怔忡健忘门》", "原文": "夫怔忡者，此心血不足也。盖心主于血，血乃心之主，心乃形之君，血富则心君自安矣。多因汲汲富贵，戚戚贫贱，又思所爱，触事不意，真血虚耗。心帝失辅。渐成怔忡不已。怔忡不已，变生诸证，舌强恍惚，善忧悲，少颜色，皆心病之候。", "白话": "怔忡是心血不足。心主于血，血乃心之主、心乃形之君，血充盛则心君自然安宁。多因急切追求富贵、忧愁贫贱，又思念所爱之人、遇事不遂，真血虚耗，心君失去辅养，渐渐形成怔忡不止。怔忡不止，变生各种证候：舌强、恍惚、容易忧伤悲哀、面色少华——都是心病的证候。"}, {"source": "条24｜《医便·医便提纲》", "原文": "人遇劳心思虑损伤精神，头眩目昏，心虚气短，惊悸烦热，补血为主。", "白话": "人因劳心思虑损伤精神，出现头眩目昏、心虚气短、惊悸烦热，治疗以补血为主。"}, {"source": "条25｜《医学入门·内集》", "原文": "虚则神昏，梦飞而健忘，惊悸不乐，其则胸腹腰胁痛牵。心实则梦可忧、可惊、可怪之事，虚则魂梦飞扬。气逆于心，则梦丘山烟火，健忘失记，惊悸不安，心内懊憹不乐，皆心血少也。", "白话": "心虚则神昏，梦中飞扬而健忘，惊悸不乐，“其则”胸腹腰胁牵引作痛。心实则梦见可忧、可惊、可怪之事，虚则魂梦飞扬。气逆于心，则梦见山丘烟火，健忘失记，惊悸不安，心内烦乱不舒而不乐——这都是心血少。"}, {"source": "条26｜《医学入门·外集》", "原文": "又有健忘非质钝，精神短少痰相攻。怔忡久则健忘，三症虽有浅深，然皆心脾血少神亏，清气不足，痰火浊气上攻，引神归舍丹主之。", "白话": "又有健忘并非天资愚钝，而是精神短少、痰气相攻。怔忡日久则健忘——三症虽有浅深之别，但都是心脾血少、神气亏虚，清气不足，痰火浊气上攻，用引神归舍丹主治。"}, {"source": "条27｜《古今医鉴》卷八", "原文": "夫惊悸者，蓦然而跳跃，惊动如有欲厥之状，有时而作者是也，属血虚。或时觉心跳，亦是血虚。", "白话": "惊悸是蓦然跳跃，惊动如有要昏倒的样子，有时发作的就是，属血虚。或时常感觉心跳，也是血虚。"}, {"source": "条28｜《考证病源·十、考证病源七十四种》", "原文": "怔忡者，心中惚惚不安，如畏人捕捉之状，乃心血少也，用八物汤加酸枣仁、辰砂服之。", "白话": "怔忡是心中惚惚不安，好像害怕被人捕捉的样子，是心血少，用八物汤加酸枣仁、辰砂服用。"}, {"source": "条29｜《绛雪丹书·产后下卷》", "原文": "产妇惊忧劳倦，去血过多，以致心中躁动不宁，谓之怔忡；若惕然而惊，如人将捕之状，谓之惊悸。", "白话": "产妇惊恐忧愁劳倦，出血过多，以致心中躁动不宁，叫做怔忡；如果惕然而惊、好像有人要抓捕自己的样子，叫做惊悸。"}, {"source": "条30｜《证治汇补》卷五", "原文": "血虚。有阴气内虚，虚火妄动，心悸体瘦，五心烦热，面赤唇燥，左脉微弱，或虚大无力者是也。汇补", "白话": "血虚。有阴气内虚、虚火妄动的，心悸体瘦，五心烦热，面赤唇燥，左脉微弱，或虚大无力的就是。“汇补”为原书引文标记。"}, {"source": "条31｜《傅青主女科歌括·产后编下卷》", "原文": "血不足，则怔忡惊悸不安耳。”“歌括：劳倦失血心跳动，如人将捕惕然惊。症分怔忡与惊悸，调和脾胃神志宁。", "白话": "血不足，就会怔忡惊悸不安而已。歌括说：劳倦失血而心跳动，好像有人要抓捕自己、惕然发惊；证候分怔忡与惊悸，调和脾胃则神志安宁。"}, {"source": "条32｜《辨证录》卷八", "原文": "人有终日劳心，经营思虑，以致心火沸腾，先则夜梦不安，久则惊悸健忘，行神憔悴，血不华色，人以为心气之弱也，谁知是心血之亏乎。", "白话": "有人整天劳心、经营思虑，以致心火沸腾，先是夜梦不安，日久则惊悸健忘，形神憔悴，血不能荣华面色；人们以为是心气虚弱，谁知是心血亏损呢。"}, {"source": "条33｜《灵验良方汇编》卷下", "原文": "心得血而养，故血气充足则心神安静。产后劳倦伤血，所以神气不守，心中躁动不宁而怔忡，惕然如人来捕而惊悸。", "白话": "心得到血的奉养，所以血气充足则心神安静。产后劳倦伤血，所以神气不能守藏，心中躁动不宁而成怔忡，惕然如有人来捕而成惊悸。"}, {"source": "条34｜《医学心悟》卷三", "原文": "虚痛者，心悸怔忡，以手按之则痛止，归脾汤主之。", "白话": "虚痛，见心悸怔忡，用手按压则疼痛停止，用归脾汤主治。"}, {"source": "条35｜《不居集·上集卷之二》", "原文": "心虚者，恍惚忧烦，少颜色，或惊悸多汗，宜人参养荣汤、归神丹、养心丸之类。", "白话": "心虚的，恍惚忧烦，面色少华，或惊悸多汗，宜用人参养荣汤、归神丹、养心丸之类。"}, {"source": "条36｜《医医偶录》卷一", "原文": "心神惊悸者，心血空虚也。", "白话": "心神惊悸的，是心血空虚。"}, {"source": "条37｜《医医偶录》卷二", "原文": "心之虚，血不足也。脉左寸必弱，其症为惊悸，为不得卧，为健忘，为虚痛，为怔忡，为遗精。", "白话": "心的虚，是血不足。脉象左寸必弱，其症状为惊悸、不得卧、健忘、虚痛、怔忡、遗精。"}, {"source": "条38｜《医医偶录》卷二", "原文": "惊悸者，惕惕然恐，神失守也，七福饮、秘旨安神丸主之。”“怔忡者，气自下逆，心悸不安，归脾汤主之。", "白话": "惊悸是惕惕然恐惧、神失守藏，用七福饮、秘旨安神丸主治。怔忡是气从下焦上逆、心悸不安，用归脾汤主治。"}, {"source": "条39｜《温热经纬》卷四", "原文": "瘥后惊悸，属血虚，宜养血镇惊。", "白话": "热病痊愈后的惊悸，属血虚，宜养血镇惊。"}, {"source": "条40｜《血证论》卷六", "原文": "血虚则神不安而怔忡。", "白话": "血虚则神不安而成怔忡。"}, {"source": "条41｜《医学刍言·第十四章心腹痛》", "原文": "虚痛，虚痛心下悸而痛，脉虚细涩，喜按，得食少安，二便清利，宜归脾汤加石菖蒲；或当归肉桂建中汤，或黄芪建中汤加吴萸、川椒。", "白话": "虚痛，虚痛是心下悸动而又疼痛，脉虚细涩，喜按，进食后稍安，大小便清利，宜用归脾汤加石菖蒲；或当归肉桂建中汤，或黄芪建中汤加吴茱萸、川椒。"}, {"source": "条42｜《济阳纲目》卷五十四", "原文": "叶氏曰：怔忡或有阴火上冲，怔忡不已，甚者火炎于上，或头晕眼花，或齿落发脱，或手指如杵长大，或见异物，或腹中作声，此阴火为患也，治宜滋阴抑火汤。", "白话": "叶氏说：怔忡或有阴火上冲，怔忡不止，严重的火炎于上，或头晕眼花，或齿落发脱，或手指像杵一样粗大变长，或看见异物，或腹中作声——这是阴火为患，治疗宜用滋阴抑火汤。"}, {"source": "条43｜《儒门事亲》卷十一", "原文": "凡男子妇人，所显证候，皮肤发热，肌肉消瘦，四肢倦怠，兼有头痛颊赤，心忪，唇干舌燥，日晡潮热，夜有盗汗，涕唾稠粘黏，胸膈不利，或时喘嗽，五心烦热，睡卧不安，饮食减少，多思水浆，经脉不通，病名曰何病？《奇病论》曰：女子不月，血滞之病也；男子肾虚，精不足也。凡治此证，降心火、益肾水，此之谓也。", "白话": "凡男子妇人所显现的证候：皮肤发热，肌肉消瘦，四肢倦怠，兼有头痛、面颊发赤，心悸，唇干舌燥，午后潮热，夜间盗汗，涕唾稠粘，胸膈不利，或时时喘咳，五心烦热，睡卧不安，饮食减少，多想饮水，经脉不通——病名叫做什么病？《奇病论》说：女子月经不来，是血滞之病；男子是肾虚、精不足。凡治疗此证，当降心火、益肾水，说的就是这个。"}, {"source": "条44｜《保婴撮要》卷五", "原文": "睡因惊悸，合面而卧者，心经虚热也。", "白话": "睡眠因惊悸而合面俯卧的，是心经虚热。"}, {"source": "条45｜《脉贯》卷四", "原文": "肾，足少阴也。是动则病饥不欲食，水中有火，为脾之母。真火不生土则脾虚，虽饥不能食矣。面如漆柴，咳唾则有血，喝喝而喘，肾之本色见者，精衰故也。吐血与喘，水虚而火刑金也。坐而欲起，目䀮䀮如无所见，坐而欲起，阴虚则不能静也；肾虚则瞳神昏眩，故无所见也。心如悬，若饥状，相火不宁，君主亦不自安也；如悬若饥，心肾不交也。气不足则善恐，心惕惕如人将捕之，是为骨厥。肾志恐，故如捕也，肾主骨，故为骨厥。", "白话": "肾是足少阴经。本经受邪所动则病：饥饿却不想进食——肾水中有火，是脾之母，真火不能生土则脾虚，所以虽饥饿也不能进食。面色黑瘦如漆柴，咳唾带血，喘息有声；肾的本色（黑）出现，是精气衰败的缘故。吐血与喘，是水虚而火刑肺金。坐下就想起、目䀮䀮视物不清——坐下就想起是阴虚不能安静，肾虚则瞳神昏眩，所以视物不清。心如悬空、好像饥饿的样子，是相火不宁，君主（心）也不能自安；如悬若饥，是心肾不交。气不足则容易恐惧，心惕惕如有人要抓捕自己，这叫骨厥——肾在志为恐，所以如被捕；肾主骨，所以叫骨厥"}, {"source": "条46｜《妇人规》卷下", "原文": "产后有阴虚发热者，必素禀脾肾不足，及产后气血俱虚，故多有之。其证则倏忽往来，时作时止，或昼或夜，进退不常，或精神困倦，怔忡恍惚。但察其外无表证而脉见弦数，或浮弦豁大，或细微无力，其来也渐，非若他证之暴至者，即是阴虚之候。", "白话": "产后有阴虚发热的，必定平素禀赋脾肾不足，加上产后气血俱虚，所以多见。其证忽来忽去，时作时止，或昼或夜、进退不定，或精神困倦、怔忡恍惚。只要诊察到外无表证而脉见弦数，或浮弦豁大，或细微无力，其来也渐缓，不像其他证候突然而至，就是阴虚的证候。"}, {"source": "条47｜《辨证录》卷八", "原文": "人有夜卧常惊，或多恐怖，心悬悬未安，气吸吸欲尽，淫梦时作，盗汗日多，饮食无味，口内生疮，胸中烦热，终朝无力，惟唯思睡眠，唇似朱涂，颧如脂抹，手足心热，液燥津干，人以为肾经之痨瘵，谁知肾传于心，而心初受病乎。", "白话": "有人夜里睡眠常常受惊，或多恐惧，心悬悬不安，气息吸吸好像要断尽，怪梦时时发作，盗汗日渐增多，饮食无味，口内生疮，胸中烦热，整天无力，只想睡眠，唇色像涂朱一样红，颧部像抹了胭脂，手足心热，津液干燥——人们以为是肾经的痨瘵，谁知是肾传于心，而心刚刚受病呢。"}, {"source": "条48｜《证治汇补》卷五", "原文": "阴火。有阴火上冲，头晕眼花，耳鸣齿落；或腹中作声，怔忡不已者，宜滋阴抑火，加养心之剂。汇补", "白话": "阴火。有阴火上冲的，头晕眼花，耳鸣齿落；或腹中作声、怔忡不止的，宜滋阴抑火，加养心之药。“汇补”为原书引文标记。"}, {"source": "条49｜《杂病源流犀烛·卷十八内伤外感门》", "原文": "其或阴精走泄，阳不内依，欲寐即醒，心动震悸，气因精夺欤。宜青花龙骨汤。", "白话": "或阴精走泄，阳气不能内守依附，刚要睡着就醒来，心动震悸，是气因精被夺的缘故吧。宜用青花龙骨汤。"}, {"source": "条50｜《温热经纬》卷四", "原文": "瘥后怔忡，乃水衰火旺，心肾不交。宜补水养心。", "白话": "病愈后的怔忡，是水衰火旺、心肾不交，宜补水养心。"}, {"source": "条51｜《目经大成》卷三", "原文": "两肾，皆水也。由左右言之，乃有阴阳之分焉。故左虚则火不安其位而妄动，燔灼真阴，发为咳喘衄咯，虚热往来，自汗盗汗，头眩眼花，喉燥舌干，腰肢酸软，心跳不宁。", "白话": "两肾都属水。从左右来说，就有阴阳之分。所以左肾虚则火不安其位而妄动，燔灼真阴，发为咳嗽气喘、鼻衄咳血，虚热往来，自汗盗汗，头眩眼花，喉燥舌干，腰肢酸软，心跳不宁。"}, {"source": "条52｜《奉时旨要》卷三", "原文": "怔忡之病，《经》曰：胃之大络，名曰虚里，贯膈络肺，出于左乳下，其动应衣，宗气泄也。其症心胸筑筑振动，惶惶惕惕，无时得宁是也。自仲景始，有动气在上下左右之辨，谓皆不可汗下。良由阴虚于下，宗气无根而气不归原。故在上则浮撼于胸臆，在下则振动于脐旁。患此者，速宜养气养精，滋培根本……。", "白话": "怔忡之病，《内经》说：胃的大络名叫虚里，贯穿横膈、联络肺，出于左乳下，其搏动应手及衣，是宗气外泄。其症心胸筑筑振动，惶惶惕惕、没有安宁之时，就是这个。从张仲景开始，有动气在上下左右的辨别，说都不可以汗下。实在是因为阴虚于下，宗气无根而气不归原。所以在上则浮撼于胸中，在下则振动于脐旁。患此证的，赶快宜养气养精、滋培根本……。"}, {"source": "条53｜《奉时旨要》卷三", "原文": "笔花氏曰：怔忡，虚症也。古无是名，自《内经》有其动应衣一语，而仲景始有不可汗下之论。总由阴虚劳损，气不归原所致。", "白话": "笔花氏说：怔忡是虚证。古代没有这个名称，自从《内经》有“其动应衣”一句话，而张仲景才开始有不可汗下的论述。总由阴虚劳损、气不归原所致。"}, {"source": "条54｜《重订广温热论》卷一", "原文": "瘥后怔忡。乃水衰火旺，心肾不交也。", "白话": "病愈后的怔忡，是水衰火旺、心肾不交。"}, {"source": "条55｜《太平圣惠方》卷四", "原文": "夫心虚则生寒，寒则阴气盛，阴盛则血脉虚少，而多恐畏，情绪不乐，心腹暴痛。时唾清涎，心膈胀满，好忘多惊，梦寐飞扬，精神离散，其脉浮而虚者，是其候也。", "白话": "心虚就会生寒，寒则阴气盛，阴盛则血脉虚少，而多恐惧畏惧、情绪不乐，心腹突然疼痛。时时吐清涎，心膈胀满，健忘多惊，梦寐飞扬，精神离散；脉浮而虚的，就是它的证候。"}, {"source": "条56｜《圣济总录》卷四十三", "原文": "论曰：心虚之状，气血衰少，面黄烦热，多恐悸不乐，心腹痛难以言，时出清涎，心膈胀满，善忘多惊，梦寝不宁，精神恍惚，皆手少阴经虚寒所致。", "白话": "论述说：心虚的形态，气血衰少，面色发黄、烦热，多恐惧心悸不乐，心腹疼痛难以言语，时时流出清涎，心膈胀满，健忘多惊，梦寐不宁，精神恍惚——都是手少阴经虚寒所致。"}, {"source": "条57｜《医门法律》卷二", "原文": "其一，因误汗致心悸、头眩、身瞤动，无可奈何者，用真武汤为救法。其证发汗不解，仍发热、心下悸、头眩、身瞤动振振欲擗地。汗虽出而热不退，则邪未尽，而正已大伤。况里虚为悸，上虚为眩，经虚为瞤，身振振摇，无往而非亡阳之象，所以行真武把关坐镇之法也。", "白话": "第一种，是因误用汗法导致心悸、头眩、身瞤动、病情无可奈何的，用真武汤作为救法。其证发汗后不愈，仍发热、心下悸、头眩、身瞤动、振振欲倒地。汗虽出而热不退，则邪未尽而正气已大伤。况且里虚则悸，上虚则眩，经虚则瞤动，身体振振摇动，无一处不是亡阳的征象，所以用真武汤把关坐镇的方法。"}, {"source": "条58｜《医门法律》卷二", "原文": "盖太阳膀胱为肾之府，肾中阳虚阴盛，势必传出于府，以故才见脉微恶寒，漏汗恶风，心悸头眩，肉瞤筋惕，躁扰等证。", "白话": "太阳膀胱是肾之腑，肾中阳虚阴盛，势必传出到腑，所以才见到脉微恶寒、漏汗恶风、心悸头眩、肉瞤筋惕、躁扰等证。"}, {"source": "条59｜《严氏济生方·五脏门》", "原文": "方其虚也，虚则生寒，寒则血脉虚少，时多恐畏，情绪不乐，心暴痛，时唾清涎，心膈胀闷，好忘多惊，梦寐飞扬，精神离散，其脉浮而虚者，是虚寒之候也。", "白话": "当其虚时，虚则生寒，寒则血脉虚少，时常多恐惧、情绪不乐，心突然疼痛，时时吐清涎，心膈胀闷，健忘多惊，梦寐飞扬，精神离散；脉浮而虚的，是虚寒的证候。"}, {"source": "条60｜《脉义简摩·卷六名论汇编》", "原文": "怔忡头晕，二便有热者。肺不生津，阴不足以养阳，膻中小肠脉皆上行，故不能眠也。若二便无热，乃元阳已亏，血不养心，故怔忡。", "白话": "怔忡头晕，见大小便有热的，是肺不生津、阴不足以养阳，膻中与小肠之脉都上行，所以不能眠。如果大小便无热，那是元阳已亏、血不养心，所以怔忡。"}, {"source": "条61｜《圣济总录》卷九十", "原文": "论曰：虚劳惊悸者，心气不足，心下有停水也。心藏神，其主脉，若劳伤血脉，致心气不足，因为邪气所乘，则令人精神惊惕，悸动不定。若水停心下，水气乘心，亦令悸也。", "白话": "论述说：虚劳惊悸，是心气不足、心下有停水。心藏神，主血脉；如果劳伤血脉，导致心气不足，因而被邪气所乘，就使人精神惊惕、悸动不定。如果水停心下、水气乘心，也使人发悸。"}, {"source": "条62｜《三因极一病证方论》卷十", "原文": "况五饮停蓄，闭于中脘，最使人忪悸，治属饮家。", "白话": "况且五饮停蓄、闭阻于中脘，最使人心悸，治疗当从饮家论治。"}, {"source": "条63｜《普济方》卷一百六十五", "原文": "其知道者，不为血气所使所反，所以运其血也。其或喜怒哀乐不中节，起居饮食失其常，皆令营卫否龃，气血败浊，为痰、为涎、为饮，诸证生焉。结状于胸膈，则眩晕忪忡悸●，癃闭否膈，喘嗽气急；停滞于关节，则筋脉挛急，肢节疼痛，手足亸曳，寒热往来。三者同源而异知。", "白话": "那懂得养生之道的人，不被血气所驱使、所反乱，所以能运行其血。如果喜怒哀乐不中节度，起居饮食失其常态，都使营卫痞塞不和，气血败浊，为痰、为涎、为饮，各种证候由此而生。结聚于胸膈，就出现眩晕、怔忡、心悸，癃闭痞膈、喘咳气急；停滞于关节，就筋脉挛急、肢节疼痛、手足亸曳、寒热往来。三者同源而表现不同。"}, {"source": "条64｜《医学入门·外集》", "原文": "惊悸惕惕不自定，如人将捕曰怔忡。思虚过度及因大惊、大恐，以致心虚停痰，或耳闻大声，目见异物，临危触事，便觉惊悸，甚则心跳欲厥，脉弦濡者，虚也。", "白话": "惊悸惕惕不能自定，好像有人要抓捕自己的叫怔忡。思虑过度以及因大惊大恐，以致心虚停痰；或耳闻大声、目见异物、临危触事，便觉惊悸，甚则心跳欲厥；脉弦濡的，属虚。"}, {"source": "条65｜《古今医统大全》卷五十", "原文": "郁痰留饮，积于心包胃口，而致惊悸怔忡者有之，此又不可概以虚而治也。", "白话": "郁痰留饮，积于心包胃口，而导致惊悸怔忡的是有的，这又不可一概按虚来治疗。"}, {"source": "条66｜《丹溪手镜·卷之上》", "原文": "悸，心忪也，惕然动而不安矣。有停饮者，饮水多必心下悸，心火恶水，心不安也。", "白话": "悸就是心忪，惕然跳动而不安。有停饮的，饮水多必心下悸——心属火而厌恶水，所以心不安。"}, {"source": "条67｜《证治汇补》卷五", "原文": "停饮。有停饮水气乘心者，则胸中漉漉有声。虚气流动，水既上乘，心火恶之，故筑筑跳动，使人有怏怏之状，其脉偏弦。汇补", "白话": "停饮。有停饮、水气乘心的，胸中漉漉有声。虚气流动，水既然上乘，心火厌恶它，所以筑筑跳动，使人有怏怏不舒之状，其脉偏弦。“汇补”为原书引文标记。"}, {"source": "条68｜《医碥》卷二", "原文": "又谓水停心下，甚者则悸，心气为水所逼，而跳动不宁也。”“又谓短气有微饮，水停心下，甚者为悸，微者短气。", "白话": "又说水停心下，重的就发悸，是心气被水所逼而跳动不宁。又说短气是有微饮，水停心下，重的发悸，轻的短气。"}, {"source": "条69｜《文十六卷》卷八", "原文": "水在心，筑筑然悸动，火与水为仇，故不欲饮。", "白话": "水饮在心，筑筑然悸动，火与水相仇，所以不欲饮水。"}, {"source": "条70｜《医学摘粹·伤寒证方歌括》", "原文": "茯苓甘草证里有积水，方见太阳本病，厥逆旋惊在四肢，悸生心下病难支，胸停积水宜先治，入胃须防作利时。", "白话": "茯苓甘草汤证是内有积水，方证见太阳本病，厥逆旋即见于四肢而发惊，悸生于心下、病难以支持；胸中停有积水宜先治水，水入于胃须防下利之时。"}, {"source": "条71｜《类证治裁》卷四", "原文": "水停心下，水气乘心为悸，茯苓甘草汤、半夏茯苓汤。心为火而畏水，水气乘之，故跳动不安为悸。", "白话": "水停心下，水气乘心而为悸，用茯苓甘草汤、半夏茯苓汤。心属火而畏惧水，水气乘凌它，所以跳动不安而为悸。"}, {"source": "条72｜《医方选要》卷七", "原文": "又或外感风寒暑湿之气闭塞诸经，及协饮停留中脘，皆能令人怔忡。", "白话": "又或者外感风寒暑湿之气闭塞各经，以及水饮停留中脘，都能使人怔忡。"}, {"source": "条73｜《万病回春》卷二", "原文": "痰燥者，痰火作热烦躁也。痰话者，痰火作热惊惕不安、错语失神也。痰迷心窍，神不守舍，因思忧郁结，惊恐伤心，心不自安，神出舍空，使人烦乱，悲歌叫骂，奔走不识人也。", "白话": "痰燥，是痰火化热而烦躁；痰话，是痰火化热、惊惕不安、言语错乱、神志失常。痰迷心窍，神不守藏，因忧思郁结、惊恐伤心，心不能自安，神出而舍空，使人烦乱、悲歌叫骂、奔走而不识人。"}, {"source": "条74｜《济阳纲目》卷五十四", "原文": "丹溪云：怔忡属血虚有痰，有虑便动属虚。时作时止者，痰因火动。瘦人多是血少，肥人多是痰。", "白话": "朱丹溪说：怔忡属血虚有痰，有思虑就发作的属虚；时作时止的，是痰因火而动。瘦人多是血少，肥人多是痰。"}, {"source": "条75｜《济阳纲目》卷五十五", "原文": "悸为心动，谓之怔忡，心筑筑而跳，摇摇而动也，皆由心虚挟夹痰所致，定志丸加半夏、橘红主之。", "白话": "悸就是心动，叫做怔忡，心筑筑而跳、摇摇而动，都由心虚夹痰所致，用定志丸加半夏、橘红主治。"}, {"source": "条76｜《病机沙篆》卷下", "原文": "大凡怔忡、失志，惊悸、健忘、心风、不寐，皆系痰涎沃心，或因心气不足，反以凉心大过，心火益微，痰涎愈盛，惟唯以理痰顺气为第一义，导痰、二陈加枳壳、南星、菖蒲。", "白话": "大凡怔忡、失志，惊悸、健忘、心风、不寐，都关系到痰涎浸渍于心；或因心气不足，反而用凉心药太过，心火更加微弱，痰涎愈加旺盛，只有以理痰顺气为第一要义，用导痰汤、二陈汤加枳壳、南星、菖蒲。"}, {"source": "条77｜《证治汇补》卷五", "原文": "郁痰。或耳闻大声，目见异物，遇险临危，触事丧志，大惊大恐，心为之忤，以致心虚停痰，使人有惕惕之状，甚则心跳欲厥，其脉滑者是也。汇补", "白话": "郁痰。或耳闻大声、目见异物，遇险临危、触事失志，大惊大恐，心为之触忤，以致心虚停痰，使人有惕惕之状，甚则心跳欲厥，脉滑的就是。“汇补”为原书引文标记。"}, {"source": "条78｜《证治汇补》卷五", "原文": "痰结。有膏粱厚味，积成痰饮，口不作干，肌肤润泽如故。忽然惊惕而作悸，其脉弦滑有力者是也。汇补", "白话": "痰结。有嗜食膏粱厚味、积成痰饮的，口不作干、肌肤润泽如常，忽然惊惕而发悸，脉弦滑有力的就是。“汇补”为原书引文标记。"}, {"source": "条79｜《医碥》卷二", "原文": "痰在心胸，噫气吞酸嘈杂，或痛或秽干呕也。或心下如停冰铁，或惊悸怔忡如畏人捕，或胸膈迷闷如癫呆状，或痞满、健忘、恶心。", "白话": "痰在心胸，噫气、吞酸、嘈杂，或疼痛或泛恶干呕。或心下如停冰铁般冷重，或惊悸怔忡、好像害怕被人捕捉，或胸膈迷闷如痴呆之状，或痞满、健忘、恶心。"}, {"source": "条80｜《医学刍言·第十一章痰饮》", "原文": "痰饮为病，心悸头眩，短气而咳，舌苔白者多。", "白话": "痰饮为病，心悸头眩，短气而咳，舌苔白的居多。"}, {"source": "条81｜《儒医心镜·痰饮》", "原文": "痰者，人身之痰贵乎顺行，随气升降，无处不到。设若气逆，阻其道路，为喘，为咳，为呕哕，为眩晕，为惊悸，为健忘，为不语，为狂言，为癫呆，为厥逆，为怔忡，为嘈杂，为串痛，为糜，为流注，为肿块，为痰核，为痰气，为痰结，为痰燥，为痰话，为痰闷，为痰火，为寒，为热，皆是痰之为患。", "白话": "痰——人身之痰贵在顺行，随气升降，无处不到。如果气逆，阻其道路，或为喘、为咳、为呕哕、为眩晕、为惊悸、为健忘、为不语、为狂言、为癫呆、为厥逆、为怔忡、为嘈杂、为串痛、为糜、为流注、为肿块、为痰核、为痰气、为痰结、为痰燥、为痰话、为痰闷、为痰火、为寒、为热——都是痰之为患。"}, {"source": "条82｜《重订广温热论》卷一", "原文": "瘥后惊悸。凡温热新瘥，触事易惊，梦寐不安者，余热挟夹痰也。痰与气搏，震荡心宫，故惊悸。", "白话": "病愈后的惊悸。凡温热病初愈，触事易惊、梦寐不安的，是余热夹痰。痰与气相搏，震荡心宫，所以惊悸。"}, {"source": "条83｜《太平圣惠方》卷四", "原文": "夫心实则生热，热则阳气盛，阳盛则卫气不行，荣气不通，遂令热毒稽留，心神烦乱，面赤身热，口舌生疮，咽燥头疼，喜笑，恐悸，手心热，满汗出，衄血，其脉洪实相搏者，是其候也。”。", "白话": "心实就会生热，热则阳气盛，阳盛则卫气不行、荣气不通，于是热毒稽留，心神烦乱，面赤身热，口舌生疮，咽燥头疼，喜笑，恐惧心悸，手心热，满身汗出，鼻出血；脉洪实相搏的，就是它的证候。"}, {"source": "条84｜《圣济总录》卷五十六", "原文": "论曰：《内经》谓一阳发病，少气，善咳善泄，其传为心掣。夫心，君火也；三焦，相火也。盖人气血和平，三焦升降，则神明泰定。三焦既病，故上咳下泄，少气，致心火胥应而不宁。其动若掣者，乃其证也。", "白话": "论述说：《内经》说一阳发病，少气、易咳易泄，其传变为心掣。心是君火，三焦是相火。人气血和平、三焦升降，则神明安泰。三焦既然有病，所以上咳下泄、少气，致使心火相应而不宁；其搏动如牵掣的，就是它的证候。"}, {"source": "条85｜《严氏济生方·五脏门》", "原文": "及其实也，实则生热，热则心神烦乱，面赤身热，口舌生疮，咽燥头痛，喜笑恐悸，手心烦热，汗出衄血，其脉洪实者，是实热之候也。", "白话": "等到其实，实则生热，热则心神烦乱，面赤身热，口舌生疮，咽燥头痛，喜笑恐惧心悸，手心烦热，汗出鼻出血；脉洪实的，是实热的证候。"}, {"source": "条86｜《普济方》卷一百八十六", "原文": "脉痹不已，复感于邪，内舍于心，是为心痹。其状脉不通，烦则心下鼓，曝上气而喘，嗌干善噫，厥气上则恐。盖淫气忧思痹聚在心，经所谓诸痹不已，亦益内者如此。治心痹神思昏塞，四肢不利，胸中烦闷，时复恐悸。茯神汤方。", "白话": "脉痹不愈，又感受邪气，内舍于心，就是心痹。其状脉不通，烦则心下鼓动，暴气上逆而喘，咽干善嗳气，厥气上逆则恐。淫气与忧思痹聚于心，《经》所谓各种痹证不愈就向内发展的就是如此。治疗心痹、神思昏塞、四肢不利、胸中烦闷、时复恐惧心悸，用茯神汤方。"}, {"source": "条87｜《医林改错》卷上", "原文": "血府逐瘀汤。……心跳心忙，用归脾安神等方不效，用此方百发百中。", "白话": "血府逐瘀汤。……心跳心慌，用归脾汤、安神等方无效的，用此方百发百中。"}, {"source": "条88｜《血证论》卷六", "原文": "有瘀血亦怔仲怔忡。", "白话": "有瘀血也会导致怔忡。"}, {"source": "条1｜《灵枢·经脉》", "原文": "心主手厥阴心包络之脉，……是动则病手心热，臂肘挛急，腋肿，甚则胸胁支满，心中憺憺大动，面赤目黄，喜笑不休。", "白话": "心主手厥阴心包络的经脉……本经经气变动（是动）就出现手心发热、臂肘拘急、腋下肿，甚至胸胁支撑胀满、心中剧烈跳动、面红目黄、喜笑不止。"}, {"source": "条2｜《素问·至真要大论》", "原文": "太阳司天，寒淫所胜，则寒气反至，水且冰，血变于中，发为痈疡。民病厥心痛，呕血、血泄、鼽衄，善悲，时眩仆。运火炎烈，雨暴乃雹。胸腹满、手热、肘挛、掖肿，心澹澹大动，胸胁胃脘不安，面赤目黄，善噫嗌干，甚则色炲，渴而欲饮，病本于心。神门绝，死不治。所谓动气，知其脏也。", "白话": "太阳司天、寒气过胜为病，寒气反而到来，水将结冰，血在体内发生变化，发为痈疡。人们患厥心痛、呕血、便血、鼽衄，容易悲伤，时时眩晕仆倒。（若）运气之火炎烈，暴雨夹雹。胸腹胀满、手热、肘挛、腋肿，心中澹澹大动，胸胁胃脘不安，面红目黄，多嗳气、咽干，甚至面色黑如烟灰，口渴想喝水，病本在心。神门脉绝，是死证不可治。所谓诊察动气，就可以知道病在哪一脏。"}, {"source": "条3｜《素问·阴阳别论》", "原文": "曰：一阳发病，少气，善咳，善泄；其传为心掣，其传为膈。", "白话": "说：少阳一经发病，气少，容易咳嗽，容易泄泻；其病传变可成为心掣，再传可成为膈证。"}, {"source": "条4｜《素问·痹论》", "原文": "心痹者，脉不通，烦则心下鼓，暴上气而喘，嗌干善噫，厥气上则恐。", "白话": "心痹，血脉不通；烦躁则心下鼓动，突然气上逆而喘，咽干、多嗳气，厥气上逆则发恐。"}, {"source": "条5｜《素问·诊要经终论》", "原文": "夏刺秋分，病不愈，令人心中欲无言，惕惕如人将捕之。", "白话": "夏天误刺秋分（时令不合）而病不愈，使人心中不想说话，心中惕惕恐惧，好像有人要捕捉自己。"}, {"source": "条6｜《素问·平人气象论》", "原文": "人一呼脉一动，一吸脉一动，日少气。人一呼脉三动，一吸脉三动而躁，尺热曰病温，尺不热脉滑曰病风，脉涩曰痹。人一呼脉四动以上曰死，脉绝不至曰死，乍疏乍数曰死。", "白话": "人一呼脉跳一次、一吸脉跳一次，叫做少气。一呼脉跳三动、一吸脉跳三动而躁，尺肤发热的叫病温；尺肤不热而脉滑的叫病风；脉涩的叫痹。一呼脉跳四动以上的叫死；脉绝不来的叫死；忽慢忽快的叫死。"}, {"source": "条7｜《素问·平人气象论》（病心脉来）", "原文": "病心脉来，喘喘连属，其中微曲曰心病。死心脉来，前曲后居，如操带钩曰心死。", "白话": "有病的心脉来时，急促连续、其中微见弯曲，叫心病；将死的心脉来时，前曲后居（后直），像执持带钩一样，叫心死。"}, {"source": "条8｜《素问·平人气象论》（虚里）", "原文": "胃之大络。名曰虚里，贯膈络肺，出于左乳下，其动应衣，脉宗气也。盛喘数绝者，则在病中；结而横，有积矣；绝不至曰死，乳之下其动应衣，宗气泄也。", "白话": "胃的大络，名叫虚里，穿过横膈、联络肺，出于左乳之下，它的搏动应手（可见衣动），是脉中宗气的所在。搏动盛喘而时有歇止的，是病中；结滞而横着搏动的，是有积；脉绝不来的叫死；左乳之下搏动应衣，是宗气外泄。"}, {"source": "条9｜《素问·玉机真脏论》", "原文": "真脾脉至，弱而乍数乍疏，色黄青不泽，毛折乃死。", "白话": "真脾脉出现，脉弱而忽快忽慢，面色黄中带青、没有光泽，毫毛焦折，就要死亡。"}, {"source": "条10｜《素问·脉要精微论》", "原文": "夫脉者血之府也，长则气治，短则气病，数则烦心，大则病进。上盛则气急，下盛则气胀，代则气衰，细则气少，涩则心痛。", "白话": "脉是血的府库；脉长说明气治，脉短说明气病，脉数则心烦，脉大则病进。上部盛则气急，下部盛则气胀，代脉则气衰，细脉则气少，涩脉则心痛。"}, {"source": "条11｜《灵枢·禁服》", "原文": "人迎大一倍于寸口，……盛则为热，虚则为寒，紧则为痛痹，代则乍甚乍间。盛则泻之，虚则补之，紧痛则取之分肉，代则取血络，且饮药，……寸口大于人迎一倍，……代则乍痛乍止。……代则取血络，而后调之。", "白话": "人迎脉比寸口大一倍……（人迎）盛就是热，虚就是寒，紧就是痛痹，代就是时轻时重。盛就用泻法，虚就用补法，紧痛就取分肉之间针刺，代就刺血络，并且服药……寸口比人迎大一倍……代则时痛时止……代就刺血络，然后调治。"}, {"source": "条12｜《难经·十四难》", "原文": "何谓损？一呼一至曰离经，再呼一至曰夺精，三呼一至曰死，四呼一至曰命绝。此损之脉也。”“一呼三至，一吸三至，为适得病。前大后小，即头痛目眩，前小后大，即胸满短气。一呼四至，一吸四至，病欲甚，脉洪大者，苦烦满；沉细者，腹中痛，滑者伤热；涩者中雾露。一呼五至，一吸五至，其人当困，沉细夜加，浮大昼加，不大不小，虽困可治，其有大小者，为难治。一呼六至，一吸六至，为死脉也，沉细夜死，浮大昼死。一呼一至，一吸一", "白话": "什么叫做损？一呼脉一至叫离经，两呼一至叫夺精，三呼一至叫死，四呼一至叫命绝——这就是损脉。一呼三至、一吸三至，是刚得病；前（寸）大后（尺）小，就头痛目眩；前小后大，就胸满短气。一呼四至、一吸四至，病将加重：脉洪大的，苦于烦满；沉细的，腹中痛；滑的，伤于热；涩的，中雾露之邪。一呼五至、一吸五至，病人当困重：沉细的夜里加重，浮大的白天加重；不大不小的，虽困还可治；有大小不一的，难治。一呼六至、一吸六至，是死脉：沉细的夜死，浮大的昼死。一呼一至、一吸一至，名叫损；人虽能行走，仍当卧"}, {"source": "条13｜《中藏经·论心脏虚实寒热生死逆顺脉证之法第二十四》", "原文": "又，心病则胸中痛，四一作胁肢满胀，肩背臂膊皆痛；虚则多惊悸，惕惕然无眠，胸腹及腰背引痛，喜一作善悲时眩，仆心积气，久不去则苦忧烦，心中痛。实则喜笑不息，梦火发。心气盛则梦喜笑，及恐畏。……心病则曰中慧，夜半甚，平旦静。\n又，左手寸口脉大甚，则手内热，赤一作服肿太甚，则胸中满而烦，澹澹，面赤目黄也。", "白话": "又，心病则胸中痛、四肢（一说“胁”）满胀，肩背臂膊都痛；虚则多惊悸，恐惧不安而失眠，胸腹和腰背牵引作痛，容易（一说“善”）悲伤、时时眩晕仆倒；心积气久不消散，则苦于忧烦、心中痛。实则喜笑不止，梦见火发。心气盛则梦见喜笑和恐惧。……心病的表现是：中午清爽，夜半加重，天亮安静。\n又，左手寸口脉过于大，就手内发热；红（一说“服”）肿太甚，就胸中胀满而烦，心中澹澹跳动，面红目黄。"}, {"source": "条14｜《备急千金要方》卷十三", "原文": "诊得心积沉而芤时，上下无常处，病胸满悸，腹中热，面赤咽干，心烦，掌中热，甚则唾血。身瘛疭主血厥，夏瘥冬剧，色赤也。徵音人者，主心声也，心声笑其音竽，其志喜，其经手少阴，厥逆太阳则营卫不通，阴阳反错。阳气外击，阴气内伤，伤则寒，寒则虚，虚则惊掣心悸，定心汤主之。赤为心，心合脉赤如鸡冠者吉。心主舌，舌是心之余，其人火形相比于上徵赤色，广䏖，兑面小头，好肩背髀腹小手足行安地，疾行摇肩背，肉满有气轻财，少", "白话": "诊得心积之脉沉而芤、时有时无，上下没有定处；病见胸满、心悸，腹中热，面红咽干，心烦，掌中热，甚至唾血。身体瘛疭主血厥；夏天轻、冬天加重，色应赤。五音中的徵音属心，主心声：心之声为笑，其音为竽，其志为喜，其经为手少阴；厥逆于太阳，则营卫不通、阴阳错乱。阳气外击，阴气内伤；伤则寒，寒则虚，虚则惊掣心悸，用定心汤主治。赤色配心，心合于脉，色赤如鸡冠的为吉。心主舌，舌是心的余苗；火形人比类于上徵、色赤，体肤宽阔（“䏖”字义未详，照录），面锐头小，肩背髀腹长得好、手足小，走路平稳，快走"}, {"source": "条15｜《小儿药证直诀》卷上", "原文": "心主惊。实则叫哭发热，饮水而摇聚珍本作搐；虚则卧而悸动不安。", "白话": "心主惊。心实就叫哭、发热、饮水而摇动（聚珍本作“搐”）；心虚就躺卧而悸动不安。"}, {"source": "条16｜《三因极一病证方论》卷十", "原文": "夫惊悸与忪悸，二证不同。惊悸，则因事有所大惊，或闻虚响，或见异相，登高涉险，梦寐不祥，惊忤心神，气与涎郁，遂使惊悸，名曰心惊胆寒，在心胆经，属不内外因，其脉必动；忪悸，则因汲汲富贵，戚戚贫贱，久思所爱，遽失所重，触事不意，气郁涎聚，遂致忪悸，在心脾经，意思所主，属内所因。或冒寒暑湿，塞闭诸经，令人忽忽若有所失，恐恐如人将捕，中脘忪悸，此乃外邪，非因心病。", "白话": "惊悸与忪悸，两种证不同。惊悸，是因遇事受到大惊，或听到虚响，或见到怪异形状，登高涉险，梦寐不祥，惊忤心神，气与涎郁结，于是使人惊悸，名叫心惊胆寒，病在心胆经，属不内外因，其脉必动。忪悸，是因急切追求富贵、忧愁贫贱，长久思念所爱之人，骤然失去所重之人，遇事不遂，气郁涎聚，于是造成忪悸，病在心脾经，为思虑情志所主，属内因。或者冒犯寒暑湿邪，闭塞诸经，使人恍惚若有所失、恐惧好像有人要捕捉、中脘处忪悸，这是外邪所致，不是心本身的病。"}, {"source": "条17｜《仁斋直指方论》卷十一", "原文": "人之所主者心，心之所养者血，心血一虚，神气不守，此惊悸之所肇端也。曰惊、曰悸，其可无辨乎？惊者，恐怖之谓；悸者，怔忪之谓。心虚而郁痰，则耳闻大声、目击异物、遇险临危、触事丧志，心为之忤，使人有惕惕之状，是则为惊；心虚而停水，则胸中渗漉，虚气流动，水既上乘，心火恶之，心不自安，使人有怏怏之状，是则为悸。", "白话": "人的主宰是心，心所奉养的是血；心血一虚，神气不能守藏，这就是惊悸的开端。说惊、说悸，怎能不加辨别呢？惊，是恐怖的意思；悸，是怔忪的意思。心虚而痰郁的，就会耳闻大声、眼见异物、遇险临危、触事丧志，心被触动，使人有恐惧警惕的样子，这就是惊；心虚而水停的，就胸中渗漉作声，虚气流动，水既然上乘，心火厌恶它，心不能自安，使人有怏怏不乐的样子，这就是悸。"}, {"source": "条18｜《妇人大全良方》卷三", "原文": "夫妇人血风惊悸者，是风乘于心故也。心藏神，为诸脏之主。若血气调和，则心神安定；若虚损，则心神虚弱，致风邪乘虚干之，故惊而悸动不定也。其惊悸不止，则变恍惚而忧惧也。", "白话": "妇人血风惊悸，是风邪乘虚犯心。心藏神，是诸脏之主。如果血气调和，心神就安定；如果虚损，心神就虚弱，致使风邪乘虚侵犯，所以惊而悸动不定。如果惊悸不止，就变为恍惚而忧惧。"}, {"source": "条19｜《妇人大全良方》卷十九", "原文": "夫产后脏虚，心神惊悸者，由体虚心气不足，心之经为风邪所乘也。或恐惧忧迫，令心气受于风邪，风邪搏于心则惊不自安。若惊不已则悸动不安，其状目睛不转而不能呼，诊其脉动而弱者，惊悸也。动则为惊，弱则为悸矣。", "白话": "产后脏虚、心神惊悸，是由于体虚心气不足，心经被风邪所乘。或者恐惧忧迫，使心气受风邪，风邪与心相搏则惊而不自安。如果惊不止，就悸动不安；其状是目睛不转而不能呼气。诊其脉动而弱的，就是惊悸：脉动的是惊，脉弱的是悸。"}, {"source": "条20｜《普济方》卷十八", "原文": "附论夫怔忡者，此心血不足也。盖心主于血，血乃心之主，心乃形之君，血富则心君自安矣。多因汲汲富贵，戚戚贫贱，又思所爱，触事不意，真血虚耗，心帝失辅，渐成怔忡不已，变生诸证，舌强，恍惚，善忧悲，少颜色，皆心病之候。", "白话": "附论：怔忡，是心血不足。心主于血，血乃心之主，心乃形体之君；血充盛则心君自然安宁。多因急切追求富贵、忧愁贫贱，又思念所爱之人、遇事不遂，真血虚耗，心帝失去辅养，渐渐成为怔忡不止，变生诸证：舌强、恍惚、容易忧悲、面色少华，都是心病的征候。"}, {"source": "条21｜《普济方》卷一百三十七", "原文": "夫伤寒心悸者，谓心下悸动也。此由伤寒病，发汗以后，因又下之，内有虚热发渴，渴则饮，水气乘心，必振寒而心下悸也。太阳病，小便不利者，为多饮水，心下必悸。小便少者，必苦里急。夫脉浮数，法当汗出而愈，下之则身体重，心必悸也，不可发其汗，当自汗出而解，所以然者，尺中微，里虚表实，津液自和，当自汗出愈也。伤寒心下悸者。谓悸动不定也。伤寒饮水过多，水停心下，肾气乘心，则心气虚弱，故为之悸动也。此皆由发汗以后又", "白话": "伤寒心悸，是说心下悸动。这是由于伤寒病发汗以后，又用下法，内有虚热而发渴，渴就饮水，水气乘心，必然寒战而心下悸。太阳病小便不利的，是因多饮水，心下必悸；小便少的，必苦于里急。脉浮数，依法当汗出而愈；误下就身体沉重、心必悸；不可再发其汗，当自汗出而解。所以然者，尺中脉微，里虚表实，津液自和，当自汗出而愈。伤寒心下悸，是说悸动不定；伤寒饮水过多，水停心下，肾气乘心，则心气虚弱，所以悸动。这都是发汗以后又攻下，津液燥少；若内生虚热，热就饮水，水气停积，所以必然寒战而心下悸。伤寒心悸"}, {"source": "条22｜《普济方》卷一百三十七（续引）", "原文": "饮水多，必心下悸，是停饮而悸者也。其气虚者，由阳气内弱，心下空虚，正气内动而为悸也。其停饮者，由水停心下，心为火而恶水，水既内停，心不自安，则为悸也。又有汗下之后，正气内虚，邪气交击，而令悸者， 与气虚而悸者，则又甚焉。太阳病，发汗过多，其人叉手自冒，必心下悸。太阳病，若下之，身重，心下悸者，不可发汗。少阳病，不可吐下，吐下则悸而惊。少阳病，不可发汗，发汗则谵语，此属胃，胃和则愈，胃不和则烦而悸。", "白话": "饮水多，必心下悸，这是停饮而悸。气虚而悸的，是由于阳气内弱、心下空虚，正气内动而成为悸；停饮而悸的，是由于水停心下，心属火而厌恶水，水既然内停，心不能自安，就成为悸。又有汗下之后，正气内虚、邪气交击而致悸的，比起气虚而悸的就更重了。太阳病发汗过多，病人两手交叉护于心下（叉手自冒），必心下悸。太阳病若误下，身重、心下悸的，不可发汗。少阳病不可吐下，吐下就会悸而惊。少阳病不可发汗，发汗就会谵语，这属于胃；胃和则愈，胃不和则烦而悸。这几种都是汗后挟邪的，与气虚而悸的有所差异。或镇固"}, {"source": "条23｜《普济方》卷一百三十七（续引）", "原文": "厥而心下悸。悸者，怔忪也。", "白话": "手足厥冷而心下悸。悸，就是怔忪。"}, {"source": "条24｜《赤水玄珠》卷十七", "原文": "又云：发汗多叉手心悸欲得按者，用桂枝甘草汤，是亦闭汗孔也。", "白话": "又说：发汗过多、两手交叉护心、心悸而想按压的，用桂枝甘草汤；这也是固闭汗孔（敛汗）的意思。"}, {"source": "条25｜《诊家正眼》卷一", "原文": "诊时病人叉手摸心，闭目不言，必心虚怔忡。", "白话": "诊察时病人两手交叉摸着心口、闭着眼睛不说话的，必是心虚怔忡。"}, {"source": "条26｜《奇效良方》卷四十六", "原文": "原病式曰：夫怔忡为病，躁扰动烦热，扰乱而不宁，火之体也。甚于外则肢体躁扰，甚于内则神志躁动，返覆颠倒。惟唯憹烦心不得眠，或以烦心呕哕，而为胃冷心痰者，非也。故烦心心痛，腹空热旺，而发得食，热退而减也。或逆气动躁者，由水衰火旺，而犹火之动也，故心胸躁动，谓之怔忪，此心血不足也。盖心主血，血乃心之主，心乃形之主，血富则心主自安矣。多因汲汲富贵，戚戚贫贱，又思所爱触事，不意真血虚耗，心主失辅，渐成怔忡。", "白话": "《原病式》说：怔忡这个病，躁扰烦热、扰乱而不安宁，是火的本性。火甚于外则肢体躁扰，甚于内则神志躁动、反复颠倒。只是心中憹烦不得眠；有人把烦心呕哕当作胃冷心痰，是不对的。所以烦心心痛，腹中空时热旺而发作，得食则热退而减轻。又或逆气躁动，是由于水衰火旺，犹如火之躁动，所以心胸躁动，叫做怔忪，这是心血不足。心主血，血乃心之主，心乃形之主，血充盛则心主自然安宁。多因急切追求富贵、忧愁贫贱，又思念所爱之人、遇事不遂，不料真血虚耗，心主失去辅养，渐渐成为怔忡。怔忡不止，变生诸证：舌强、恍"}, {"source": "条27｜《苍生司命》卷七", "原文": "惊悸者，善恐怖，蓦然跳跃惊动，有时而作者是也。尤当分虚实治之。健忘、怔忡者，纯主不足，惊悸则不足中之有余也。", "白话": "惊悸，是容易恐怖、突然跳跃惊动、时有发作的病。尤其应当分辨虚实来治疗。健忘、怔忡，纯属不足；惊悸则是不足之中夹有余。"}, {"source": "条28｜《苍生司命》卷五", "原文": "心劳者，心神惊惕，怔忡，盗汗自汗，心烦热闷，口舌生疮，咯血面赤，脉洪而数。", "白话": "心劳，是心神惊惕、怔忡、盗汗自汗、心烦热闷、口舌生疮、咯血面红、脉洪而数。"}, {"source": "条29｜《医学正传》卷三", "原文": "其或心神惊惕，怔忡无时，盗汗自汗，心烦热闷，口舌生疮，咯血面赤，脉洪而数，知其邪在心也。", "白话": "如果心神惊惕、怔忡发作不定时、盗汗自汗、心烦热闷、口舌生疮、咯血面红、脉洪而数，就可知邪在心。"}, {"source": "条30｜《保婴撮要》卷十", "原文": "惊者，心卒动而恐怖也；悸者，心跳动而怔忡也。", "白话": "惊，是心突然跳动而恐怖；悸，是心跳动而怔忡。"}, {"source": "条31｜《明医指掌》卷七", "原文": "惊悸心中常惕惕，如人将捕时惊惑。心血一虚，神气失守，神去则舍空，舍空则郁而停痰，痰居心位，此惊悸之所以肇端也。或耳闻大声，目击异物，遇险临危，触事丧志，则心为之忤，使人有惕惕之状，始则为惊悸。", "白话": "惊悸，心中常常恐惧警惕，好像有人要捕捉时那样惊慌疑惑。心血一虚，神气失守；神离去则心舍空虚，舍空则气郁而痰停，痰占据心的位置，这就是惊悸的开端。或者耳闻大声、眼见异物、遇险临危、触事丧志，心被触动，使人有恐惧警惕的样子，开始就是惊悸。"}, {"source": "条32｜《古今医统大全》卷十三", "原文": "伤寒悸者，心中筑筑然动，怔仲怔忡不能自安者也。", "白话": "伤寒悸，是心中筑筑跳动、怔怔忡忡而不能自安。"}, {"source": "条33｜《古今医统大全》卷五十", "原文": "怔忡证，心中惕惕，摇动而不得安静，无时而作者是也。惊悸者，蓦然而跳跃，忽闻声而即惊，或触事而即悸，有时而仆者是也。", "白话": "怔忡证，是心中恐惧警惕、摇动而不得安静、发作没有定时。惊悸，是突然跳跃、忽闻声响就惊，或遇事就悸，有时甚至仆倒。"}, {"source": "条34｜《医学入门·外集》", "原文": "悸，动也。心膈间客邪乘之，筑筑然触动。如人将捕，即怔忡意也。有水停心下，头眩身摇，厥而悸者，渗其水而悸厥自定。有神气素虚，心中空耗不能自持者。有汗下后内虚而悸者，比之素虚者尤甚，须先定其气，而后治其悸。", "白话": "悸，就是动。心膈之间的客邪乘虚侵犯，筑筑地触动，好像有人要捕捉，就是怔忡的意思。有水停心下、头眩身摇、手足厥冷而悸的，渗利其水则悸厥自定。有神气平素虚弱、心中空耗不能自持的。有汗下之后内虚而悸的，比平素虚的更重，必须先安定其气，然后治其悸。"}, {"source": "条35｜《医学入门·内集》", "原文": "心烦否？或只烦躁不宁，或欲吐不吐，谓之嘈杂。或多惊恐，谓之怔忡。", "白话": "问：心烦不烦？或者只是烦躁不宁，或者想吐又吐不出，叫做嘈杂；或者多惊恐，叫做怔忡。"}, {"source": "条36｜《古今医鉴》卷八", "原文": "又曰：惊者，恐怖之谓。", "白话": "又说：惊，就是恐怖的意思。"}, {"source": "条37｜《云林神彀》卷一", "原文": "心下怔忡，如畏人捕，怵惕不安，阴阳隔阻。", "白话": "心下怔忡，好像害怕被人捕捉，恐惧警惕不安，是阴阳隔阻不通。"}, {"source": "条38｜《考证病源·十、考证病源七十四种》", "原文": "惊悸者，心中忽然跳动也。其因惊恐所致，痰迷心窍，神不安耳。", "白话": "惊悸，是心中忽然跳动。它由惊恐引起，痰迷心窍，神不安宁而已。"}, {"source": "条39｜《济阳纲目》卷五十四（引叶氏）", "原文": "叶氏曰：怔忡或有阴火上冲，怔忡不已，甚者火炎于上，或头晕眼花，或齿落发脱，或手指如杵长大，或见异物，或腹中作声，此阴火为患也，治宜滋阴抑火汤。", "白话": "叶氏说：怔忡或有阴火上冲，怔忡不止；重的火炎于上，或头晕眼花，或齿落发脱，或手指像杵一样粗大，或看见异物，或腹中作响，这是阴火为患，治疗宜用滋阴抑火汤。"}, {"source": "条40｜《育婴家秘》卷一", "原文": "钱氏云：心主惊，实则叫哭，发热，饮水而搐；虚则困卧，悸动不安，此心病之证也。心主血脉。", "白话": "钱氏说：心主惊。心实就叫哭、发热、饮水而抽搐；心虚就困倦多卧、悸动不安——这就是心病的证候。心主血脉。"}, {"source": "条41｜《医学纲目·惊悸怔忡》", "原文": "惊者，心卒动而不宁也。悸者，心跳动而怕惊也。怔忡，亦心动而不宁也。", "白话": "惊，是心突然跳动而不安宁；悸，是心跳动而怕惊；怔忡，也是心动而不安宁。"}, {"source": "条42｜《济阳纲目》卷五十四（怔忡惊悸之辨）", "原文": "又曰：或问怔忡惊悸之辨。曰：怔忡者，本无所惊，心常自怯；惊悸者，因事有所惊，或心有所思而卒动，二者若相类而实不同也治之实无大异。", "白话": "又说：有人问怔忡与惊悸的辨别。答：怔忡，本来没有什么惊，心常自怯；惊悸，是因事受惊，或心有所思而突然跳动。二者看似相类而其实不同，但治疗上没有太大差异。"}, {"source": "条43｜《简明医彀》卷四", "原文": "惊者，谓实有见闻；悸者，恍如见闻，虚之甚也。血不足则神不守，神不守则惊恐、悸怖、恍惚，众证作焉。肝脉急数，主惊；心脉涩数，虚热。", "白话": "惊，是确有见闻而受惊；悸，是恍惚间好像有所见闻，是虚得厉害。血不足则神不守藏，神不守则惊恐、悸怖、恍惚等证一齐发作。肝脉急数，主惊；心脉涩数，主虚热。"}, {"source": "条44｜《医灯续焰》卷十八", "原文": "《准绳》云：悸即怔忡。今历观病状，则二证少有分别。悸则心中微动，如恐如惊。怔忡则心胸振筑，莫知其来；忽尔宁寂，莫知其去。甚则头目眩晕，神气若浮，盖悸之重者也。", "白话": "《证治准绳》说：悸就是怔忡。如今历观病状，则二证稍有分别：悸是心中微动，又像恐又像惊；怔忡是心胸振跳撞击，不知从何而来；忽然安静，也不知何时而去。重的则头目眩晕、神气浮越，就是悸中之重者。"}, {"source": "条45｜《证治百问·惊悸、怔忡、健忘》", "原文": "盖惊悸者，出于仓卒，眼见异类，耳闻异声，顷刻惊惕而神惑。如此之后，心中常怀，念念不忘，恍惚而动，谓之惊悸。悸者，恐怯之谓。惟唯恐复惊，惊则神气散乱，恐则心气自怯，此惊悸之义也。其左寸关乍大乍小，或浮或沉，心不定而脉变乱也，以壮胆壮神、和血安神之药，常服自愈。\n盖怔忡者，心中有如物撞，谓之忡。忡者，忡逆之谓，忽然跳跃谓之怔；怔者，振动之谓，本心气虚而三焦之火冲于胞络，胞络不和而心忡，若心神自虚，胞络", "白话": "惊悸，出于仓猝之间：眼见异类、耳闻异声，顷刻惊惕而神志迷惑。如此之后，心中常怀、念念不忘、恍惚而动，就叫惊悸。悸，是恐惧胆怯的意思；只怕再次受惊——惊则神气散乱，恐则心气自怯，这就是惊悸的含义。其左寸关脉忽大忽小、或浮或沉，是心不定而脉变乱；用壮胆壮神、和血安神之药，常服自愈。\n怔忡，是心中好像有物撞击，叫做忡；忡是冲逆的意思。忽然跳跃叫做怔；怔是振动的意思。根本在于心气虚而三焦之火冲于心包络，胞络不和而心忡；或者心神自虚、胞络无血奉养，以致心体躁扰而忽然跳跃为心怔。必须以调"}, {"source": "条46｜《脉诀汇辨》卷七", "原文": "诊时病人，叉手扪心，闭目不言，心虚怔忡。", "白话": "诊察时病人两手交叉扪着心口、闭目不言的，是心虚怔忡。"}, {"source": "条47｜《医宗说约》卷二", "原文": "惊悸忽然心惕惕，如人将捕时惊惑，跳动不已名怔忡，寤寐神魂多恍惚。", "白话": "惊悸是忽然心中恐惧警惕，好像有人要捕捉时那样惊慌疑惑；跳动不停的名叫怔忡；无论醒着睡着，神魂多恍惚。"}, {"source": "条48｜《病机沙篆》卷下", "原文": "心中惕惕然跳，筑筑然动，怔怔忡忡，不能自安，即所谓悸也，一属虚，一属饮。", "白话": "心中恐惧地跳、筑筑地动，怔怔忡忡不能自安，就是所谓的悸；其病机一则属虚，一则属水饮。"}, {"source": "条49｜《古今名医汇粹》卷六", "原文": "夫所谓怔忡者，心神惕惕然，动摇而不得安静，无时而作者是也。", "白话": "所谓怔忡，是心神恐惧警惕、动摇而不得安静、发作没有定时。"}, {"source": "条50｜《辨证奇闻》卷四（闻声惊）", "原文": "闻声惊，心怦怦，半日后止。人谓心有痰，痰药不效。久不必闻声，亦惊且悸，常若有人来捕者，是惊悸相连而至。虽是心虚，惊悸实不同。盖惊轻悸重，惊从外来动心，悸从内生动心也。若怔忡，正悸之渐也；若悸，非惊之渐也。故惊悸宜知轻重。一遇怔忡，宜防惊，惊宜防悸。", "白话": "听到声响就惊，心怦怦跳，半天才止。人们说是心有痰，用痰药却无效。久了不必闻声也惊而且悸，常常好像有人来捕捉——这是惊悸相连而至。虽都是心虚，惊与悸其实不同：惊轻悸重；惊从外来动心，悸从内生动心。至于怔忡，正是悸的渐重；而悸，并非惊的渐重。所以惊悸应当知道轻重：一遇怔忡，应当防其成惊；惊，应当防其成悸。"}, {"source": "条51｜《辨证奇闻》卷四（先惊后悸）", "原文": "先惊后悸，亦有先悸后惊，似不同，不知实无异，不过轻重之殊。前已备言，此又重申者，盖辨惊悸，分中有合，合中有分耳。惊有出于暂不出于常，悸有成于暗不成于明者，又不可不别。暂惊轻于常惊，明悸重于暗悸而惊悸仍伺，则将分治乎？抑合治乎？知其合中之分，则分治效；知其分中之合，则合治亦效。", "白话": "先惊后悸，也有先悸后惊，看似不同，不知其实无异，不过是轻重的差别。前面已经详细说了，这里又重申，是因为辨别惊悸要分中有合、合中有分。惊有出于一时而不出于经常的，悸有成于暗处而不成于明处的，又不能不区别。一时之惊轻于经常之惊，明处之悸重于暗处之悸，而惊与悸仍然相随，那么是分别治疗呢，还是合并治疗？知道合中的分，分别治疗就有效；知道分中的合，合并治疗也有效。"}, {"source": "条52｜《济世全书·宋许学士伤寒脉法》", "原文": "心脉微小主心虚，心中惊悸流汗随，头脑昏沉多困倦，梦魂常在水边归。", "白话": "心脉微小主心虚，心中惊悸而汗出相随，头脑昏沉、多困倦，梦魂常在水边归来（多梦水）。"}, {"source": "条53｜《济世全书》卷六", "原文": "夫怔忡者，心胸躁动谓之怔忡，此心血不足也。又曰：惊者，恐怖之谓；悸者，怔忡之谓。怔忡、健忘、惊悸，三症名异而病同。", "白话": "怔忡，心胸躁动叫做怔忡，这是心血不足。又说：惊是恐怖的意思，悸是怔忡的意思。怔忡、健忘、惊悸三种证，名称不同而病本相同。"}, {"source": "条54｜《顾松园医镜》卷十二", "原文": "怔忡者，心中惕惕。动而不宁，无时而作；惊悸者、外有所触，心中跳动，因惊而作。", "白话": "怔忡，是心中恐惧警惕、跳动而不安宁、发作没有定时；惊悸，是外有所触动、心中跳动、因惊而发作。"}, {"source": "条55｜《灵验良方汇编》卷上", "原文": "一妇人气盛血少、火旺痰多，因事不遂意，得怔忡之患，心惕然而惊，时发时止。", "白话": "一个妇人气盛血少、火旺痰多，因事情不遂意，患上怔忡，心中恐惧而惊，时发时止。"}, {"source": "条56｜《不居集》卷二十二", "原文": "怔忡之病，心胸筑筑振动，惶惶惕惕，无时得宁者是也。", "白话": "怔忡这个病，是心胸筑筑振动、惶恐警惕、没有一刻安宁。"}, {"source": "条57｜《不居集》卷二十二（续引）", "原文": "或耳闻大声，目见异物，遇险临危，触事丧心，大惊大恐，以致心为之忤，停积痰涎，使人有惕惕不宁之状，甚则心跳欲厥，其脉滑大者是也。", "白话": "或者耳闻大声、眼见异物、遇险临危、触事丧心、大惊大恐，以致心被触动，痰涎停积，使人有恐惧不宁的样子；重的则心跳欲厥，其脉滑大的就是这种。"}, {"source": "条58｜《伤寒心法要诀》卷二", "原文": "心下筑筑惕惕、怔怔忡忡，谓悸病之状也。", "白话": "心下筑筑跳动、恐惧警惕、怔怔忡忡，说的就是悸病的样子。"}, {"source": "条59｜《疡医大全》卷二", "原文": "肾属水，其脉大紧，身无痛，形不瘦，不能食，善惊悸，以心萎者死。", "白话": "肾属水，其脉大而紧，身体不痛，形体不瘦，不能进食，容易惊悸，出现心萎征象的主死。"}, {"source": "条60｜《疡医大全》卷三", "原文": "又曰：悸者，心跳动也。", "白话": "又说：悸，就是心跳动。"}, {"source": "条61｜《疡医大全》卷三（引《纲目》）", "原文": "《纲目》曰：惊者，心卒动而不宁也。悸者，心跳动而怕惊也。", "白话": "《医学纲目》说：惊，是心突然跳动而不安宁；悸，是心跳动而怕惊。"}, {"source": "条62｜《疡医大全》卷三（引《三因》）", "原文": "《三因》曰：惊悸，因事有所大惊而成者，名曰心惊胆慑，病在心胆经，其脉大动。又曰：五饮停蓄，闭于中脘，最使人惊悸，属饮家。", "白话": "《三因极一病证方论》说：惊悸因遇事大惊而成的，名叫心惊胆慑，病在心胆经，其脉大动。又说：五饮停蓄、闭阻于中脘，最使人惊悸，属于饮家。"}, {"source": "条63｜《疡医大全》卷三（引丹溪）", "原文": "丹溪曰：惊悸者，有时而作，大概属血虚与痰；瘦人多是血虚，肥人多是痰饮，时觉心跳者，亦是血虚。", "白话": "朱丹溪说：惊悸时有发作，大概属血虚与痰；瘦人多是血虚，肥胖人多是痰饮；时时感觉心跳的，也是血虚。"}, {"source": "条64｜《疡医大全》卷三（引《入门》）", "原文": "《入门》曰：惊悸，因思虑过度及大惊恐而作，甚则心跳欲厥，时作时止者，乃痰因火动。又曰：心胆虚怯，触事易惊，涎与气搏，变生诸证。", "白话": "《医学入门》说：惊悸因思虑过度以及大惊大恐而发作，重的则心跳欲厥；时作时止的，是痰因火而动。又说：心胆虚怯，遇事容易受惊，涎与气相搏结，变生诸证。"}, {"source": "条65｜《疡医大全》卷三（引《直指》）", "原文": "《直指》曰：血虚心虚多惊。", "白话": "《仁斋直指方》说：血虚、心虚的人多惊。"}, {"source": "条66｜《疡医大全》卷三（引《正传》）", "原文": "《正传》曰：忧、愁、思、虑伤心，令人惕然心跳动，惊悸不安。", "白话": "《医学正传》说：忧、愁、思、虑损伤心，使人恐惧地心跳动、惊悸不安。"}, {"source": "条67｜《疡医大全》卷三（引《纲目》）", "原文": "《纲目》曰：怔忡，心动而不宁也。", "白话": "《医学纲目》说：怔忡，是心动而不安宁。"}, {"source": "条68｜《疡医大全》卷三（引戴氏）", "原文": "戴氏曰：怔忡者，心中躁动不安，惕惕然如人将捕者是也。", "白话": "戴氏说：怔忡，是心中躁动不安、恐惧警惕好像有人要捕捉的样子。"}, {"source": "条69｜《疡医大全》卷三（引《直指》）", "原文": "《直指》曰：心虚而痰郁，则耳闻大声，目击异物，遇险临危，触事丧志，使人有惕惕之状，是为惊悸。心虚而停水，则胸中渗漉怏怏之状，是为怔忡。", "白话": "《仁斋直指方》说：心虚而痰郁，就会耳闻大声、眼见异物、遇险临危、触事丧志，使人有恐惧警惕的样子，这叫惊悸；心虚而水停，则胸中渗漉作声、怏怏不乐的样子，这叫怔忡。"}, {"source": "条70｜《疡医大全》卷三（引《正传》）", "原文": "《正传》曰：怔忡者，心中惕惕然，动摇而不得安静，无时而作者是也。", "白话": "《医学正传》说：怔忡，是心中恐惧警惕、动摇而不得安静、发作没有定时。"}, {"source": "条71｜《疡医大全》卷三（引《纲目》）", "原文": "《纲目》曰：心澹澹动也，因痰动也，谓不怕惊而心自动也，惊恐亦曰心中澹澹，谓怕惊而亦动也。舌血谓之舌衄，汗孔出血谓之肌衄，属心与肝也。凡惊而动血者属心。又曰：诸病跗肿，疼酸惊骇，皆属于火。", "白话": "《医学纲目》说：心澹澹动，是因痰而动，说的是不怕惊而心自己跳动；惊恐也叫心中澹澹，说的是怕惊而心也跳动。舌出血叫做舌衄，汗孔出血叫做肌衄，属心与肝。凡因惊而动血的属心。又说：各种足背肿、疼痛酸楚、惊骇，都属于火。"}, {"source": "条72｜《疡医大全》卷三（引《医鉴》）", "原文": "《医鉴》曰：惊者，恐怖之谓；悸者，怔忡之谓。", "白话": "《古今医鉴》说：惊是恐怖的意思；悸是怔忡的意思。"}, {"source": "条73｜《疡医大全》卷十七", "原文": "又云：心中怔忡，胸前红甚，舌卷面赤，目上视者不治。", "白话": "又说：心中怔忡、胸前红得厉害、舌卷、面红、目睛上视的，不治。"}, {"source": "条74｜《盘珠集胎产症治》卷中", "原文": "血虚心气不足也。心虚而受风邪，遂成惊悸，名曰心风。其状目睛不转，其脉动而弱，宜大补气血。若作风治，速之危矣。", "白话": "血虚就是心气不足。心虚而感受风邪，就成惊悸，名叫心风。其状是目睛不转，其脉动而弱，宜大补气血；如果按风邪治疗，会很快趋于危殆。"}, {"source": "条75｜《杂病源流犀烛》卷六", "原文": "脉法。灵枢曰：手厥阴之脉甚动，则心中澹澹大动。\n怔忡形症。&lt;内经&gt;曰：胆病者，亦心中澹澹，如人将捕。又曰：太阳司天，寒淫所胜，则病心澹澹大动，寒伤心主也。注曰：澹澹，水摇貌，此属水病。直指曰：心虚而停水，则胸中渗漉，虚气流动，水既上升，心火恶之，心不自安，使人有怏怏之状，是为怔忡。又曰：怔忡，因惊悸久而成也。纲目曰：怔忡，惕惕然心动而不宁，无时而作者是也。", "白话": "脉法。《灵枢》说：手厥阴之脉搏动过甚，就心中澹澹大动。\n怔忡的形证。《内经》说：胆病的人，也心中澹澹，好像有人要捕捉。又说：太阳司天、寒气过胜为病，则病心澹澹大动，是寒伤心主。注解说：澹澹是水摇的样子，这属于水病。《直指》说：心虚而水停，则胸中渗漉、虚气流动，水既然上升，心火厌恶它，心不能自安，使人有怏怏不乐的样子，这就是怔忡。又说：怔忡是由惊悸日久而成。《纲目》说：怔忡，是恐惧警惕、心动而不安宁、发作没有定时。"}, {"source": "条76｜《医学实在易》卷四", "原文": "怔忡者，心下跳动不安，即惊有触而动曰惊悸不触而动曰悸之类也。", "白话": "怔忡，是心下跳动不安；也就是“有所触动而动的叫惊悸、无所触动而动的叫悸”之类。"}, {"source": "条77｜《医会元要·十二经穴脉筋主病图注各经药性并列》", "原文": "舌色红，心开窍于舌也。口干，心烦，心之热也。惊悸怔忡，心神不安也。", "白话": "舌色红，是心开窍于舌；口干、心烦，是心有热；惊悸怔忡，是心神不安。"}, {"source": "条78｜《医学从众录》卷二", "原文": "有所触而动曰惊，无所触而动曰悸。凡怔忡瞤惕，皆其类也。", "白话": "有所触动而跳动的叫惊，无所触动而跳动的叫悸；凡怔忡、瞤惕，都属于这一类。"}, {"source": "条79｜《医学从众录》卷三", "原文": "虚痛即悸痛，脉浮而小细，或沉而短涩，其痛重轻相间，多日不愈。心悸，最喜摩按，得食小愈，饥则更痛。", "白话": "虚痛就是悸痛：脉浮而小细，或者沉而短涩；其痛时轻时重，多日不愈。心悸（之痛）最喜按摩，进食后稍愈，饥饿时更痛。"}, {"source": "条80｜《证治针经》卷三", "原文": "惊悸悉心胸跳跃，悸来非自下上冲。", "白话": "惊悸都是心胸跳跃；悸的来势不是从下向上冲。"}, {"source": "条81｜《证治发微》（引于《证治针经》卷三）", "原文": "《证治发微》云：悸即怔忡，如有物撞谓之忡，忽然跳跃谓之怔，此血虚也。健忘心中了了，口欲言而忽然中止，此平素失意，抑郁而涎饮渗于心窍也。", "白话": "《证治发微》说：悸就是怔忡；好像有物撞击叫做忡，忽然跳跃叫做怔，这是血虚。健忘是心中明明白白、口想说话却忽然中止，这是平素失意、抑郁而涎饮渗入心窍。"}, {"source": "条82｜《杂证汇参·惊恐怔忡》", "原文": "怔忡者，心中惕惕然动摇不静，其作也，无时。《医学正传》有触而心动曰惊。无惊而自动曰悸，即怔忡也。", "白话": "怔忡，是心中恐惧警惕、动摇不静，其发作没有定时。《医学正传》说：有所触动而心动叫惊；无惊而自己跳动叫悸，也就是怔忡。"}, {"source": "条83｜《三指禅》卷二", "原文": "四曰悸，有触而惊曰惊，无触而惊曰悸，悸而至于痛，则悸之甚者也。", "白话": "第四叫悸：有所触动而受惊的叫惊，无所触动而受惊的叫悸；悸发展到疼痛，就是悸中之重者。"}, {"source": "条84｜《类证治裁》卷四", "原文": "惊悸脉必结代，寸口脉动而弱。动为惊，弱为悸。病在心胆，其脉必大动，惊者其脉止而复来，其人目睛不转，不能呼气。以上惊脉。\n恐则脉沉，恐伤肾，脉必沉。其人恐怖，其脉形如循丝，累累然，其面白，色脱也。以上恐脉。", "白话": "惊悸之脉必见结代，寸口脉动而弱：动脉主惊，弱脉主悸。病在心胆，其脉必大动；惊的脉止而复来，病人目睛不转、不能呼气——以上是惊的脉。\n恐惧则脉沉，恐伤肾，脉必沉；病人恐怖，其脉形像摸着细丝、累累不绝，面色白，是色脱——以上是恐的脉。"}, {"source": "条85｜《杂病广要·脏腑类》", "原文": "《伤寒明理论》释悸字云：悸，心忪也，筑筑惕惕然动，证怔忪忪不能自安也。则悸即怔忡，而今人分为两条，谬矣。《济生》心胸躁动，谓之怔忡，俗云心忪，皆为热也。《原病式》怔忡者血虚，怔忡无时，血少者多。有思虑便动，属虚。时作时止者，痰因火动。瘦人多是因血少，肥人属痰。寻常者多是痰。真觉心跳者是血少，四物、朱砂安神之类。", "白话": "《伤寒明理论》解释“悸”字说：悸就是心忪，筑筑惕惕地跳动，怔怔忪忪不能自安。那么悸就是怔忡，而现今的人分为两条，是错的。《济生方》说心胸躁动叫做怔忡，俗称心忪，都是热。《原病式》说：怔忡属血虚，怔忡发作无定时，属血少的居多；有所思虑就跳动的属虚；时作时止的，是痰因火而动；瘦人多因血少，肥胖人属痰；寻常的多是痰；真正感觉心跳的是血少，用四物汤、朱砂安神丸之类。"}, {"source": "条86｜《杂病源流犀烛》卷六（曰悸，劳役）", "原文": "曰悸，劳役则头面赤而下重，自烦发热，脉弦，脐上跳，心中痛，由心伤也。", "白话": "说到悸：劳役过度就头面红赤而下体沉重，自觉心烦发热，脉弦，脐上跳动，心中痛——这是心受伤所致。"}, {"source": "条87｜《王乐亭指要》卷二", "原文": "怔忡之症，心跳振动，惊恐怵惕者是也。缘乎营阴不足，心阳不藏，神不守舍，以致心神不宁而怔忡不安，渐至心悸不寐之所由来也。然怔忡心悸，其病虽异，而其源实由乎一也。", "白话": "怔忡之症，是心跳振动、惊恐警惕。由于营阴不足、心阳不藏、神不守舍，以致心神不宁而怔忡不安，这就是渐渐发展为心悸不寐的由来。然而怔忡与心悸，病名虽异，其根源其实是同一个。"}, {"source": "条88｜《灸法秘传·应灸七十症》", "原文": "《正传》曰：惊悸者，忽然若有惊，惕惕然心中不宁，其动也有时；怔忡者，心中惕惕然，动摇不静，其作也无时。", "白话": "《医学正传》说：惊悸，是忽然好像受惊、心中恐惧不宁，其跳动有定时；怔忡，是心中恐惧警惕、动摇不静，其发作没有定时。"}, {"source": "条89｜《景岳全书发挥》卷二", "原文": "盖惊出于暂，而暂者即可复；恐积于渐，而渐者不可解，甚至心怯而神伤，精却则阴痿，日消月缩，不亡不已。丹溪治周本心大恐，心不自安，如人将捕之状，夜卧不发，两耳后如见火光炎上，饮食虽进而无味，以参术当归为君，陈皮为佐，加盐炒黄柏、炙元参少许，服之月余而愈。", "白话": "惊出于一时，一时的还可以恢复；恐惧积于渐进，渐进的就不可解，甚至心怯而神伤，精气退却则阴痿，一天天一月月消缩，不死亡不止。丹溪治疗周本心大恐一案：心不自安，好像有人要捕捉的样子，夜里躺下不发作，两耳后好像看见火光上炎，饮食虽进却无味；用参、术、当归为君药，陈皮为佐，加盐炒黄柏、炙元参少许，服了一个多月而痊愈。"}, {"source": "条90｜《医学摘粹·伤寒证辨》", "原文": "心下筑筑惕惕，怔怔忡忡，悸病之状也。", "白话": "心下筑筑跳动、恐惧警惕、怔怔忡忡，就是悸病的样子。"}, {"source": "条91｜《四诊心法要诀·上》", "原文": "心赤善喜，舌红口干，脐上动气，心胸痛烦。健忘惊悸，怔忡不安，实狂昏冒，虚悲凄然。", "白话": "心色赤、多喜，舌红口干，脐上动气，心胸痛烦；健忘惊悸、怔忡不安；实证则发狂、昏冒，虚证则悲伤凄然。"}, {"source": "条92｜《医学衷中参西录·三、医论》", "原文": "有非心机亢进而有若心机亢进者，怔忡之证是也。心之本体，原长发动以运行血脉，然无病之人初不觉其动也，惟唯患怔忡者则时觉心中跳动不安。其脉微弱无力者，当系心气虚而莫支，宜用参、术、芪诸药以补其气，兼用生地黄、玄参诸滋阴药以防其因补生热，更用酸枣仁、山萸肉以凝固其神明，收敛其气化，其治法与前条脉弱怔忡者大略相同。特脉弱怔忡者，心机之发动尤能照常，而此则发动力微，而心之本体又不时颤动，犹人之力小任重而身颤", "白话": "有并非心机亢进却像心机亢进的病，怔忡就是。心的本体，原本不停地发动以运行血脉；但无病的人并不觉得它在动，只有患怔忡的人时时觉得心中跳动不安。其脉微弱无力的，当是心气虚而不能支撑，宜用人参、白术、黄芪等药补气，兼用生地黄、玄参等滋阴药以防因补而生热，再用酸枣仁、山萸肉来凝固神明、收敛气化；其治法与前面脉弱怔忡一条大略相同。只是脉弱怔忡者，心机发动尚能照常；而这里发动力微弱，心的本体又不时颤动，好比人力气小而负荷重、身体发颤，其心脏之弱似乎比怔忡更重。"}, {"source": "条93｜《医学衷中参西录·一、医方》", "原文": "然平人跳不自觉，若觉心跳即是心经改易常度。……太大、太阔，则血逼发不尽，或已出复返，运行不如常度矣。再者心跳：凡无病之人心跳每不自觉。若因病而跳时时自觉，抚之或觉动。然此证有真有假：真者心自病而跳也，或心未必有病，但因身虚而致心跳，亦以真论；若偶然心跳，其人惊惧，防有心病，其实心本无病，即心跳亦暂时之事，是为假心跳证，医者均须细辨。凡心匀跳无止息，侧身而卧，可左可右，呼吸如常，大概心自不病。所虑跳", "白话": "然而平人心跳自己不觉得，若觉得心跳，就是心经改易常度。……太大、太阔，就血逼发不尽，或者已经出去又返回，运行不合常规。再说心跳：凡无病之人，心跳常常不自觉；若因病而跳、时时自觉，抚按或能觉其搏动。然而这种证有真有假：真的，是心自己有病而跳；或者心未必有病，只因身体虚而致心跳的，也按真论。若偶然心跳，病人惊惧，疑心有心脏病，其实心本无病，心跳也只是暂时的事，这叫假心跳证，医生都必须仔细辨别。凡心跳均匀、没有止息，侧身而卧、左右皆可、呼吸如常的，大概心自己没有病。所担心的是跳跃不"}, {"source": "条94｜《华佗神方》卷四", "原文": "怔忡之症，扰扰不宁，心神恍惚，惊悸不已。此肝肾之虚，心气之弱也。", "白话": "怔忡之症，纷扰不得安宁，心神恍惚，惊悸不止；这是肝肾亏虚、心气虚弱所致。"}, {"source": "条95｜《杂病广要·脏腑类》（心虚八证）", "原文": "心虚八证：惊邪，属心气虚；癫痫，属心气虚，有热；不得眠，属心血虚，有热；心烦，属心家有热；怔忡，属心血不足；心淡淡动；盗汗，属心血虚，汗者，心之液也；伏梁，属心经气血虚，以致邪留不去。", "白话": "心虚有八证：惊邪，属心气虚；癫痫，属心气虚兼有热；不得眠，属心血虚兼有热；心烦，属心家有热；怔忡，属心血不足；心澹澹而动；盗汗，属心血虚——汗是心的液体；伏梁，属心经气血虚，以致邪气留滞不去。"}, {"source": "条1｜《心悸》三审稿·第三章评述（开篇）", "原文": "临床证治要求审明病机、辨清证候，以为确立相应的治疗法则提供依据，它既是基于辨证而形成的结果，又是施治的开端，为临床遣方用药的指南，在辨证施治中具有重要作用。本部分以历代心悸病证治相关文献为基础，分别从心悸病的心悸诊法、中医证候特点、论治分型、鉴别诊断四个方面进行论述并对相关古代文献进行文献辑录。", "白话": "临床证治要求审明病机、辨清证候，为确立相应的治疗法则提供依据；它既是辨证所得的结果，又是施治的开端，是临床遣方用药的指南，在辨证施治中具有重要作用。本部分以历代心悸病证治相关文献为基础，分别从心悸病的诊法、中医证候特点、论治分型、鉴别诊断四个方面进行论述，并对相关古代文献加以辑录。"}, {"source": "条2｜《心悸》三审稿·第三章评述（诊法引言）", "原文": "中医诊察分为望闻问切，然心悸自觉心中悸动，惊惕不安，乃患者的自我感受，乃由问诊所得，上一部分证候特点已对其做出详细论述，此处不再赘述。同时，由于心悸闻诊内容相对匮乏，故在此，仅从医者所诊察的角度出发，对心悸之望诊与切诊进行阐述和文献辑录。", "白话": "中医诊察分为望、闻、问、切。然而心悸是患者自觉心中悸动、惊惕不安，属于患者的自我感受，由问诊所得；上一部分（证候特点）已对此详论，此处不再赘述。同时，由于心悸的闻诊内容相对缺乏，所以这里仅从医者所诊察的角度出发，对心悸的望诊与切诊进行阐述和文献辑录。"}, {"source": "条3｜《心悸》三审稿·第三章评述（望诊定义）", "原文": "望诊，是指医生通过视觉对人体的全身、局部及排出物等方面进行有目的的观察，以了解健康状况，测知病情的方法。", "白话": "望诊，是指医生通过视觉对人体的全身、局部以及排出物等方面进行有目的的观察，以了解健康状况、测知病情的方法。"}, {"source": "条4｜《心悸》三审稿·第三章评述（望面色·五色配五脏）", "原文": "《灵枢·邪气脏腑病形》指出：“十二经脉，三百六十五络，其血气皆上于面而走空窍。”说明面部色泽是由气血上荣于面而成，面部的色泽改变与五脏六腑有着紧密的联系，《灵枢·五色》云：“青为肝，赤为心，白为肺，黄为脾，黑为肾。”心对应为赤色，故心病之惊悸亦见赤色。", "白话": "《灵枢·邪气脏腑病形》指出：“十二经脉，三百六十五络，其血气都上行于面而走行孔窍。”说明面部色泽由气血上荣于面而成，面部色泽的改变与五脏六腑有密切联系。《灵枢·五色》说：“青色属肝，赤色属心，白色属肺，黄色属脾，黑色属肾。”心对应赤色，所以心病的惊悸也可见赤色。"}, {"source": "条5｜《心悸》三审稿·第三章评述（望面色·额上属心）", "原文": "明·王肯堂《幼科证治准绳·初生门·证治通论》详细记载：“额上属心，南方之位，火性炎上故居上，夏见微赤者平，深赤者病，黑色者绝，赤色主心经有风热，心躁惊悸，睡卧不安。”", "白话": "明·王肯堂《幼科证治准绳·初生门·证治通论》详细记载：“额上属于心，对应南方之位，火性炎上所以居于上部；夏天见到微赤的是正常，深赤的是病，黑色的是危绝之色；赤色主心经有风热，心躁惊悸、睡卧不安。”"}, {"source": "条6｜《心悸》三审稿·第三章评述（望面色·青色）", "原文": "此外，惊悸亦可见色青，如明·万全《片玉心书·活幼指南赋》载：“青色露而惊悸。”清·陈复正《幼幼集成·面部形色赋》继而对“青色露而肝风怔悸”做出了阐释：“此概言通面之色，通面为足阳明胃经所主………风邪冲并，面必见青，心神不安，则为怔忡惊悸。”", "白话": "此外，惊悸也可见面色发青。如明·万全《片玉心书·活幼指南赋》载：“青色显露而发惊悸。”清·陈复正《幼幼集成·面部形色赋》接着对“青色露而肝风怔悸”作出阐释：“这是概说整个面部的颜色，通面为足阳明胃经所主………风邪冲并，面必见青色，心神不安，则为怔忡惊悸。”"}, {"source": "条7｜《心悸》三审稿·第三章评述（望面·明堂）", "原文": "五脏各有所司，五脏之疾会反映应在身体的不同部位，心悸常可以通过望面来诊察。早在《灵枢·五色第四十九》就记载望面的重要性：，“五色独决于明堂乎……”，“明堂骨高以起平以直，五脏藏次于中央，六腑府挟夹其两侧，首面上于阙庭，王宫在于下极。”", "白话": "五脏各有所主，五脏的疾病会反映在身体的不同部位，心悸常可以通过望面来诊察。早在《灵枢·五色第四十九》就记载了望面的重要性：“五色独取决于明堂吗……”“明堂骨高起、平直，五脏依次藏于中央，六腑附于其两侧，头面之部在阙庭之上，王宫（心）在于下极。”"}, {"source": "条8｜《心悸》三审稿·第三章评述（望面·颧左主心）", "原文": "南宋·刘昉指出颧左主心，惊悸多表现在左颧部，在《幼幼新书·察形色治病第九》中记载：“心多惊悸言颧左，右肺青风喘嗽声。”", "白话": "南宋·刘昉指出左颧主心，惊悸多表现在左颧部，在《幼幼新书·察形色治病第九》中记载：“心病多惊悸看左颧，右颧属肺、色青主风而见喘嗽之声。”"}, {"source": "条9｜《心悸》三审稿·第三章评述（望面·印堂山根）", "原文": "清·喻昌倡导心与小肠相表里，心火下移小肠见小便赤色，上炎头部则可出现惊悸，在面部表现在印堂至山根，在《（痘疹）生民切要·头面形色主病》中载：“印堂红脉至山根，是心与小肠俱热，主小便赤色，惊悸咬牙。”", "白话": "清·喻昌倡导心与小肠相表里：心火下移小肠则见小便赤色，上炎头部则可出现惊悸；在面部的反映是从印堂到山根。《（痘疹）生民切要·头面形色主病》中载：“印堂红脉延伸到山根，是心与小肠俱热，主小便赤色、惊悸、咬牙。”"}, {"source": "条10｜《心悸》三审稿·第三章评述（切诊总说）", "原文": "切即为接触、靠近、按压之意。切诊是医生用手指或手掌对患者的某些部位进行触、摸、按、压，从而了解病情，诊察疾病的方法。《难经·六十一难》谓：“切脉而知之谓之巧。”切诊作为中医四诊之一，在获取疾病关键信息方面，具有重要作用。后世的发展中，心悸的切诊主要包括脉诊和按诊两个部分。", "白话": "切就是接触、靠近、按压的意思。切诊是医生用手指或手掌对患者的某些部位进行触、摸、按、压，从而了解病情、诊察疾病的方法。《难经·六十一难》说：“切脉而知病情叫做巧。”切诊作为中医四诊之一，在获取疾病关键信息方面具有重要作用。后世发展中，心悸的切诊主要包括脉诊和按诊两部分。"}, {"source": "条11｜《心悸》三审稿·第三章评述（损脉）", "原文": "《难经》最早描述了心悸的脉象，并病指出不同的脉象会伴随出现不同证候特征。《难经·十四难》曰：“何谓损？一呼一至曰离经，再呼一至曰夺精，三呼一至曰死，四呼一至曰命绝。此损之脉也。”", "白话": "《难经》最早描述了心悸的脉象，并指出不同的脉象伴随出现不同的证候特征。《难经·十四难》说：“什么叫做损脉？一呼脉跳一至叫离经，两呼一至叫夺精，三呼一至叫死，四呼一至叫命绝——这就是损脉。”"}, {"source": "条12｜《心悸》三审稿·第三章评述（平脉至数与预后）", "原文": "同篇下文接着指出：“一呼三至，一吸三至，为适得其病。前大后小，即头痛、目眩，前小后大，即胸满、短气。一呼四至，一吸四至，病欲甚，脉洪大者，苦烦满，沉细者，腹中痛，滑者，伤热，涩者，中雾露。一呼五至，一吸五至，其人当困，沉细夜加，浮大昼加，不大不小，虽困可治，其有大小者，为难治。一呼六至，一吸六至，为死脉也，沉细夜死，浮大昼死。一呼一至，一吸一至，名曰损，人虽能行，犹当着床，所以然者，血气皆不足故也", "白话": "同篇下文接着指出：“一呼三至、一吸三至，是刚刚得病。脉前大后小，就头痛目眩；前小后大，就胸满短气。一呼四至、一吸四至，病将加重：脉洪大的，苦于烦满；沉细的，腹中痛；滑的，伤于热；涩的，中了雾露之邪。一呼五至、一吸五至，病人应当困顿：沉细的夜里加重，浮大的白天加重；不大不小的，虽困还可治，有大小不一的，属难治。一呼六至、一吸六至，是死脉：沉细的夜死，浮大的昼死。一呼一至、一吸一至，叫做损，人虽还能行走，还是应当卧床——之所以这样，是血气都不足的缘故。两呼一至、两吸一至，叫做无魂"}, {"source": "条13｜《心悸》三审稿·第三章评述（结脉）", "原文": "《难经·十八难》描述了结脉的形状及主病：“结者，脉来去时一止，无常数，名曰结也……假令脉结伏者，内无积聚，脉浮结者，外无痼疾；有积聚脉不结伏，有痼疾脉不浮结。”", "白话": "《难经·十八难》描述了结脉的形状及其主病：“结脉，是脉来时一止，止无定数，叫做结……假如脉结而伏的，内无积聚；脉浮而结的，外无痼疾；反之有积聚而脉不结伏、有痼疾而脉不浮结（则脉症不相应）。”"}, {"source": "条14｜《心悸》三审稿·第三章评述（结代脉·《伤寒论》）", "原文": "《伤寒论》指出了心悸病的脉象提示疾病的预后：“脉按之来缓，时一止复来者，名曰结。又脉来动而中止，更来小数，中有还者反动，名曰结，阴也；脉来动而中止，不能自还，因而复动者，名曰代，阴也，得此脉者必难治。”", "白话": "《伤寒论》指出心悸病的脉象提示疾病的预后：“脉按之来缓，时有一止而复来的，名叫结。又脉来动而中止，再见时稍快，中有回还之意而复动的，名叫结，属阴；脉来动而中止，不能自行恢复，因而复动的，名叫代，属阴——见到这种脉的必然难治。”"}, {"source": "条15｜《心悸》三审稿·第三章评述（动弱脉与惊悸）", "原文": "《金匮要略·惊悸吐衄下血胸满瘀血病脉证治》指出：“寸口脉动而弱，动则为惊，弱则为悸。”晋·王叔和则对惊悸的脉象进行了的记载，《脉经·平杂病脉第二》：“沉为水、为实，（又为鬼疰。）弱为虚、为悸。”清·刘默述《证治百问》则对惊悸和怔忡的脉象进行了对比区分，指出惊悸为“左寸关乍大乍小，或浮或沉，怔忡为左寸、右尺数而不敛”。", "白话": "《金匮要略·惊悸吐衄下血胸满瘀血病脉证治》指出：“寸口脉动而弱，动的为惊，弱的为悸。”晋·王叔和也对惊悸的脉象作了记载，《脉经·平杂病脉第二》说：“沉主水、主实（又主鬼疰），弱主虚、主悸。”清·刘默述《证治百问》则对惊悸和怔忡的脉象作了对比区分，指出惊悸是“左寸关忽大忽小，或浮或沉”，怔忡是“左寸、右尺数而无力不敛”。"}, {"source": "条16｜《心悸》三审稿·第三章评述（虚里按诊）", "原文": "虚里位于左乳下第四、五肋间，乳头下稍内侧，为心尖搏动处，系诸脉之所宗，又为宗气之外候，故虚里按诊亦是心悸切诊的重要内容。", "白话": "虚里位于左乳下第四、五肋间、乳头稍内侧，是心尖搏动处，为诸脉所宗，又是宗气的外在征候，所以虚里按诊也是心悸切诊的重要内容。"}, {"source": "条17｜《心悸》三审稿·第三章评述（张介宾论虚里）", "原文": "明·沈子禄《经络全书·分野·虚里》引张介宾之言对虚里按诊做出了详细的论述：“张介宾曰：虚里跳动，最为虚损病本，故凡患阴虚劳怯，则心下多有跳动，及为惊悸者，人但知其心跳，而不知为虚里之动也。其动微者病尚浅，动甚者病则甚。凡患此者，常以纯甘壮水之剂，填补真阴，活者多矣。”", "白话": "明·沈子禄《经络全书·分野·虚里》引张介宾的话对虚里按诊作了详细论述：“张介宾说：虚里跳动最是虚损病的根本，所以凡患阴虚劳怯的，心下多有跳动，甚至成为惊悸；人们只知道心跳，而不知道这是虚里在动。其动微的病还浅，动甚的病就重。凡患此证的，常用纯甘壮水之剂填补真阴，救活的很多。”"}, {"source": "条18｜《心悸》三审稿·第三章评述（诊法小结）", "原文": "总而言之，心悸之望诊注重望头面，见色赤或色青；从脉诊而言，心悸可出现结脉、代脉、促脉、疾脉、数脉、涩脉、沉脉、缓脉、迟脉等诸多不同的脉象；按诊则以虚里按诊为重，病因病机不同，临床表现亦不相同，故而在疾病诊疗中上需仔细甄别。", "白话": "总而言之，心悸的望诊注重望头面，可见色赤或色青；从脉诊而言，心悸可出现结脉、代脉、促脉、疾脉、数脉、涩脉、沉脉、缓脉、迟脉等多种不同脉象；按诊则以虚里按诊为重。病因病机不同，临床表现也不同，所以在疾病诊疗中需要仔细甄别。"}, {"source": "条19｜《心悸》三审稿·第三章评述（临床表现总说）", "原文": "心悸症状表现为病人患者自觉心中悸动，惊惕不安，甚则不能自主，临床一般多呈发作性，每因情志波动或劳累过度而发作，且常伴胸闷、气短、失眠、健忘、眩晕、耳鸣等症。", "白话": "心悸的症状表现为病人自觉心中悸动、惊惕不安，甚至不能自主；临床一般多呈发作性，常因情志波动或劳累过度而发作，且常伴胸闷、气短、失眠、健忘、眩晕、耳鸣等症。"}, {"source": "条20｜《心悸》三审稿·第三章评述（先秦文学中的心悸）", "原文": "早在《诗经》《楚辞》等先秦文学著作中就有关于心悸的症状描述，《诗经·召南·草虫》：“喓喓草虫，䢰䢰阜螽。未见君子，忧心忡忡。”《楚辞·九辩》：“私自怜兮何极，心怦怦兮谅直。”", "白话": "早在《诗经》《楚辞》等先秦文学著作中就有关于心悸的症状描述。《诗经·召南·草虫》：“喓喓叫的草虫，趯趯跳的阜螽；未见到君子，忧心忡忡。”《楚辞·九辩》：“暗自哀怜哪里有尽头，心怦怦跳动啊自守忠直。”"}, {"source": "条21｜《心悸》三审稿·第三章评述（马王堆帛书·足臂十一脉灸经）", "原文": "马王堆汉墓出土的帛书《足臂十一脉灸经》和《阴阳十一脉灸经》作为现存最早记载经脉及其病变的文献，《足臂十一脉灸经》在论述足太阴脉病时便载有“心烦，善疛”的描述，据马继兴氏考证“疛”即心动过速、心悸类的病，", "白话": "马王堆汉墓出土的帛书《足臂十一脉灸经》和《阴阳十一脉灸经》是现存最早记载经脉及其病变的文献。《足臂十一脉灸经》论述足太阴脉病时载有“心烦，善疛”的描述，据马继兴氏考证，“疛”就是心动过速、心悸一类的病。"}, {"source": "条22｜《心悸》三审稿·第三章评述（帛书诸脉心悸描述小结）", "原文": "《阴阳十一脉灸经》在论述足阳明脉病时亦载录“闻木音则惕然惊，心惕然”，论足少阳脉病时有“心如悬”、“”“心惕惕恐人将捕之”之记载，论臂巨阴脉病时有“心彭彭如痛”之描述，这些生动形象的描述与心悸病证的症状表现颇为吻合。", "白话": "《阴阳十一脉灸经》论述足阳明脉病时载录“闻木音则惕然惊，心惕然”；论足少阳脉病时有“心如悬”“心惕惕恐人将捕之”的记载；论臂巨阴脉病时有“心彭彭如痛”的描述——这些生动形象的描述与心悸病证的症状表现颇为吻合。"}, {"source": "条23｜《心悸》三审稿·第三章评述（《内经》心悸病名）", "原文": "《黄帝内经》虽无“惊悸”、“”“怔忡”之名，但是对心悸症状表现做出了明确的记载，即“心掣”“心下鼓”“心动”“心中澹澹大动”“心自中檐檐”等，如《素问·痹论》：“脉痹不已己，复感于邪，内舍于心……心痹者，脉不通，烦则心下鼓，暴上气而喘，嗌干善嗌，厥气上则恐。”", "白话": "《黄帝内经》虽没有“惊悸”“怔忡”之名，但对心悸的症状表现作了明确记载，即“心掣”“心下鼓”“心动”“心中澹澹大动”“心中檐檐”等。如《素问·痹论》：“脉痹不愈，又感受邪气，内舍于心……心痹，脉不通，烦则心下鼓动，暴气上逆而喘，咽干善嗳，厥气上逆则恐。”"}, {"source": "条24｜《心悸》三审稿·第三章评述（仲景定名）", "原文": "汉·张仲景的《金匮要略》和《伤寒论》开始将心悸称之为“心动悸”“心下悸”“心中悸”“惊悸”等，并指出其主要病因为惊扰、水饮，虚劳及汗后受邪等，《金匮要略·惊悸吐衄下血胸满瘀血病脉证治》还明确提出了心悸者“寸口脉动而弱，动则为惊，弱则为悸”之症状，对心悸脉象之结、代、促脉进行了区分。", "白话": "汉·张仲景的《金匮要略》和《伤寒论》开始把心悸称为“心动悸”“心下悸”“心中悸”“惊悸”等，并指出其主要病因为惊扰、水饮、虚劳以及汗后受邪等。《金匮要略·惊悸吐衄下血胸满瘀血病脉证治》还明确提出心悸者“寸口脉动而弱，动则为惊，弱则为悸”的脉症，对心悸脉象中的结、代、促脉作了区分。"}, {"source": "条25｜《心悸》三审稿·第三章评述（巢元方分类）", "原文": "隋·巢元方在《诸病源候论》中将心悸作为一个证候论述，据证候特点分为风惊悸、虚劳惊悸、脚气风经五脏惊悸、金疮惊悸等，明确以“惊悸”命名心悸之病证，且“目精不转，而不能呼”“悸者，动也，谓心下悸动也”“其将起脐下，上以腹至心，气筑筑然而悸动不定”“心下澹澹，如人将捕之”等描述准确而生动地体现了心悸病的临床表现。", "白话": "隋·巢元方在《诸病源候论》中把心悸作为一个证候来论述，据证候特点分为风惊悸、虚劳惊悸、脚气风经五脏惊悸、金疮惊悸等，明确以“惊悸”命名心悸病证；且“目睛不转，而不能呼”“悸就是动，是说心下悸动”“它将从脐下起，向上从腹部到心，气筑筑然悸动不定”“心下澹澹，好像有人要抓捕自己”等描述，准确而生动地体现了心悸病的临床表现。"}, {"source": "条26｜《心悸》三审稿·第三章评述（巢元方描述语）", "原文": "且“目精不转，而不能呼”“悸者，动也，谓心下悸动也”“其将起脐下，上以腹至心，气筑筑然而悸动不定”“心下澹澹，如人将捕之”等描述准确而生动地体现了心悸病的临床表现。", "白话": "而且“目睛不转，而不能呼”“悸就是动，是说心下悸动”“它将从脐下起，向上从腹部到心，气筑筑然悸动不定”“心下澹澹，好像有人要抓捕自己”等描述，准确而生动地体现了心悸病的临床表现。"}, {"source": "条27｜《心悸》三审稿·第三章评述（现代指南·主症）", "原文": "现代临床病证指南则将心悸的临床表现做出如下定义：（1）①心悸为主要症状，自觉心搏异常，或快速，或缓慢，或跳动过重，或忽跳忽止，呈阵发性或持续不解，神情紧张，心慌不安，不能自主。", "白话": "现代临床病证指南把心悸的临床表现定义如下：（1）①心悸为主要症状，自觉心搏异常——或快速，或缓慢，或跳动过重，或忽跳忽止，呈阵发性或持续不解，神情紧张、心慌不安、不能自主。"}, {"source": "条28｜《心悸》三审稿·第三章评述（现代指南·兼症）", "原文": "（2）②伴有胸闷不舒，易激动，心烦，寐差，颤动、乏力，头晕等症。中老年患者发作可伴有心胸疼痛，甚则喘促，汗出肢冷，或见晕厥。", "白话": "（2）②伴有胸闷不舒、易激动、心烦、睡眠差、颤动、乏力、头晕等症。中老年患者发作可伴心胸疼痛，甚至喘促、汗出肢冷，或见晕厥。"}, {"source": "条29｜《心悸》三审稿·第三章评述（现代指南·脉象）", "原文": "（3）③脉象可见结脉、代脉、促脉、疾脉、数脉、涩脉、沉脉、缓脉、迟脉等。", "白话": "（3）③脉象可见结脉、代脉、促脉、疾脉、数脉、涩脉、沉脉、缓脉、迟脉等。"}, {"source": "条30｜《心悸》三审稿·第三章评述（现代指南·诱因）", "原文": "（4）④常由情志刺激如惊恐、紧张，及劳倦、饮酒、饱食等因素而诱发。", "白话": "（4）④常由情志刺激（如惊恐、紧张）以及劳倦、饮酒、饱食等因素诱发。"}, {"source": "条31｜《心悸》三审稿·第三章评述（惊与悸之辨·楼英）", "原文": "惊与悸二字常同时出现，难以截然分开，但部分医家仍对其进行了仔细区分，如明·楼英《医学纲目》指出：“惊者，心卒动而不宁也。悸者，心跳动而怕惊也。”", "白话": "惊与悸二字常同时出现，难以截然分开，但部分医家仍作了仔细区分。如明·楼英《医学纲目》指出：“惊，是心突然跳动而不安宁；悸，是心跳动而容易受惊。”"}, {"source": "条32｜《心悸》三审稿·第三章评述（惊与悸之辨·宝辉）", "原文": "清·宝辉《资生篇》明确指出惊与悸的区别：“有所触而动曰惊，无所触而动曰悸。”。", "白话": "清·宝辉《资生篇》明确指出惊与悸的区别：“有触发而动的叫惊，无触发而动的叫悸。”"}, {"source": "条33｜《心悸》三审稿·第三章评述（怔忡惊悸之辨·《济阳纲目》）", "原文": "随着对心悸病证认识的不断深入，惊、悸与怔忡因症状表现的不同而常被分而论之。先一般将心悸分为惊悸与怔忡。明·武之望《济阳纲目》卷五十四言：“又曰：或问怔忡惊悸之辨。曰：怔忡者，本无所惊，心常自怯；惊悸者，因事有所惊，或心有所思而卒动，二者若相类而实不同也（治之实无大异）。”", "白话": "随着对心悸病证认识的不断深入，惊、悸与怔忡因症状表现不同而常被分开论述。一般将心悸分为惊悸与怔忡。明·武之望《济阳纲目》卷五十四说：“又说：有人问怔忡与惊悸的辨别。答：怔忡是本来没有什么惊，心常自己怯弱；惊悸是因事受惊，或心中有所思而突然跳动——二者看似相似而其实不同（治疗上实在没有大的差异）。”"}, {"source": "条34｜《心悸》三审稿·第三章评述（惊悸怔忡分论诸家）", "原文": "明代龚居中和虞抟亦分别在《红炉点雪》《医学正传》书中对惊、悸、怔忡从临床表现的角度做对作了区分。忡清·周学霆在《三指禅》卷二亦有论述：“四曰悸，有触而惊曰惊，无触而惊曰悸，悸而至于痛，则悸之甚者也。”", "白话": "明代龚居中和虞抟也分别在《红炉点雪》《医学正传》书中，从临床表现的角度对惊、悸、怔忡作了区分。清·周学霆在《三指禅》卷二也有论述：“第四是悸：有触发而惊的叫惊，无触发而惊的叫悸；悸而至于疼痛的，就是悸中之重证。”"}, {"source": "条35｜《心悸》三审稿·第三章评述（惊悸与怔忡鉴别）", "原文": "惊悸发病多与情绪因素有关，可由骤遇惊恐、忧思恼怒、悲哀过极或过度紧张而诱发，多为阵发性，病来虽速，病情较轻，实证居多，可自行缓解，不发时如常人。怔忡则多由久病体虚、心脏受损所致，无精神刺激等因素也可发生，常表现为持续的心悸、心中惕惕、不能自控、活动后加重，多属虚证，或虚中夹实，病来虽渐，病情较重，不发时亦可兼见脏腑虚损症状。此外，惊悸日久不愈亦可形成怔忡。", "白话": "惊悸发病多与情绪因素有关，可由骤遇惊恐、忧思恼怒、悲哀过极或过度紧张诱发，多为阵发性，病来虽快、病情较轻，实证居多，可自行缓解，不发作时如常人。怔忡则多由久病体虚、心脏受损所致，没有精神刺激等因素也可发生，常表现为持续心悸、心中惕惕、不能自控、活动后加重，多属虚证或虚中夹实，病来虽缓、病情较重，不发作时也可见脏腑虚损症状。此外，惊悸日久不愈也可形成怔忡。"}, {"source": "条36｜《心悸》三审稿·第三章评述（惊与恐·何梦瑶）", "原文": "惊常伴随着恐，清·何梦瑶《医碥确·杂症》从惊与恐的关系论之：“恐亦心之动也。故孟子言不动心，以无惧为训。惊恐常相因，恐则惊矣，惊则恐矣。”。", "白话": "惊常伴随着恐。清·何梦瑶《医碥确·杂症》从惊与恐的关系论述：“恐也是心的扰动。所以孟子说不动心，以无所畏惧为训诫。惊恐常常相互为因：恐则成惊，惊则成恐。”"}, {"source": "条37｜《心悸》三审稿·第三章评述（惊恐与心悸·张必禄、程国彭）", "原文": "清·张必禄《医方辩难大成》则对惊、恐与心悸的关系做作了中肯的描述：“人之为惊为恐，虽所出之经不侔，即所扰之端亦别，然当其有恐有惊之候，则证之著见，固无不有当心震动之可验，或虚里扇摇之足徵征也。”清·程国彭《医学心悟·惊悸恐》设立惊悸恐专篇详论之：“惊者，惊骇也。悸者，心动也。恐者，畏惧也。此三者皆发于心，而肝肾因之。方书分为三门，似可不必。经云：东方青色，入通乎肝，其病发惊骇。惊虽属肝，然心有主持", "白话": "清·张必禄《医方辩难大成》对惊、恐与心悸的关系作了中肯描述：“人发惊发恐，虽然所出的经脉不同，所扰的起因也别，但当有恐有惊的时候，其证候的显著表现，确实无不可以见到心胸震动之可验证，或虚里扇摇之足征象。”清·程国彭《医学心悟·惊悸恐》设立惊悸恐专篇详论：“惊就是惊骇，悸就是心动，恐就是畏惧。这三者都发于心，而肝肾随之受累。方书分为三门，似乎不必。《经》说：东方青色，入通于肝，其病发惊骇。惊虽属肝，然而心有主持就不惊；心惊而后胆怯，这是一定的道理。”"}, {"source": "条38｜《心悸》三审稿·第三章评述（刘默论惊悸怔忡）", "原文": "清·刘默亦指出心悸发作时常会伴随恐惧感，在《证治百问》中载：“悸者，惧怯之谓”，分析“盖惊悸者，出于仓卒，眼见异类，耳闻异声，顷刻惊惕而神惑。如此之后，心中常怀，念念不忘，恍惚而动，谓之惊悸。惟唯恐复惊，惊则神气散乱，恐则心气自怯，此惊悸之义也。”。并对心悸的症状表现做出了形象的描述：“盖怔忡者，心中如有物撞，谓之忡，忡者，忡逆之谓。忽然跳跃，谓之怔，怔者，振动之谓。”", "白话": "清·刘默也指出心悸发作时常伴随恐惧感，在《证治百问》中载：“悸就是惧怯的意思”，并分析：“惊悸出于仓促之间，眼见异类，耳闻异声，顷刻惊惕而神志迷惑。如此之后，心中常怀、念念不忘、恍惚而动，就叫惊悸。只恐再次受惊——惊则神气散乱，恐则心气自怯，这就是惊悸的含义。”又对心悸症状作了形象描述：“怔忡，是心中如有物撞击，叫做忡——忡就是忡逆的意思；忽然跳跃，叫做怔——怔就是振动的意思。”"}, {"source": "条39｜《心悸》三审稿·第三章评述（论治分型总纲·辨虚实）", "原文": "心悸辨证首辨虚实两端，如果病程日久，尤其要判断心悸虚实挟夹杂的程度。心悸之虚乃心之气血阴阳的亏虚，而实证则多指水饮、痰浊、火郁。然而水饮、痰浊虽属病理产物，但往往又是致病因素，临证应分清虚实程度，虚实兼顾。", "白话": "心悸辨证首先分辨虚实两端；如果病程日久，尤其要判断心悸虚实夹杂的程度。心悸之虚是心的气血阴阳亏虚，实证则多指水饮、痰浊、火郁。然而水饮、痰浊虽属病理产物，但往往又是致病因素，临证应分清虚实程度，虚实兼顾。"}, {"source": "条40｜《心悸》三审稿·第三章评述（论治分型总纲·八证型）", "原文": "本部分以古籍文献为基准，将心悸之证型分为心虚胆怯证、心气虚证、心血不足证、阴虚火旺证、心阳不振证、水饮凌心证、痰浊阻滞证、火热致惊证八个证型进行探讨。", "白话": "本部分以古籍文献为基准，把心悸的证型分为心虚胆怯证、心气虚证、心血不足证、阴虚火旺证、心阳不振证、水饮凌心证、痰浊阻滞证、火热致惊证八个证型进行探讨。"}, {"source": "条41｜《心悸》三审稿·第三章评述（心虚胆怯证）", "原文": "心悸之心虚胆怯证常表现为为心悸不宁，善惊易恐，坐卧不安，少寐多梦而易惊醒，食少纳呆，恶闻声响，苔薄白，脉细数或虚数。明·周文采《医方选要·怔忡健忘动悸门》指出动悸乃由心胆虚怯所致：“若夫动悸者，谓心中惕然动悸而惊也，心下怯怯，如人将捕，由心胆虚怯之所致也。”", "白话": "心悸的心虚胆怯证常表现为：心悸不宁，善惊易恐，坐卧不安，睡眠少、多梦而易惊醒，食少纳呆，恶闻声响，苔薄白，脉细数或虚数。明·周文采《医方选要·怔忡健忘动悸门》指出动悸由心胆虚怯所致：“至于动悸，是说心中惕然动悸而发惊，心下怯怯不安，好像有人要抓捕自己，由心胆虚怯所造成。”"}, {"source": "条42｜《心悸》三审稿·第三章评述（心虚胆怯证·《严氏济生方》）", "原文": "宋·严用和则对心胆气虚之惊悸的临床症状进行了详细的记载，《严氏济生方·惊悸怔忡健忘门》：“夫惊悸者，心虚胆怯之所致也……遂使惊悸，惊悸不已，变生诸证，或短气悸乏，体倦自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安，皆心虚胆怯之候也。”", "白话": "宋·严用和则对心胆气虚之惊悸的临床症状作了详细记载，《严氏济生方·惊悸怔忡健忘门》：“惊悸是心虚胆怯所造成的……于是发生惊悸；惊悸不止，变生各种证候：或气短心悸乏力，体倦自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安——这都是心虚胆怯的证候。”"}, {"source": "条43｜《心悸》三审稿·第三章评述（心气虚证）", "原文": "心悸之心气虚证常表现心悸怔忡，胸闷气短，或心胸疼痛，畏寒肢冷，自汗，神疲乏力，面色白，或面唇青紫，舌质淡胖或紫暗，苔白滑，脉弱或结、代。隋·巢元方的《诸病源候论·五脏六腑病诸候》即指出：“心气不足，则胸腹大，胁下与腰背相引痛，惊悸，恍惚，少颜色，舌本强，善忧悲，是为心气之虚也，则宜补之。”。", "白话": "心悸的心气虚证常表现为：心悸怔忡，胸闷气短，或心胸疼痛，畏寒肢冷，自汗，神疲乏力，面色㿠白，或面唇青紫，舌质淡胖或紫暗，苔白滑，脉弱或结、代。隋·巢元方《诸病源候论·五脏六腑病诸候》即指出：“心气不足，就会胸腹胀大，胁下与腰背相互牵引疼痛，惊悸恍惚，面色少华，舌根强硬，容易忧伤悲哀——这就是心气虚，就应当用补法治疗。”"}, {"source": "条44｜《心悸》三审稿·第三章评述（心气虚证·《太平圣惠方》）", "原文": "《太平圣惠方·治心气不足诸方》亦指出心气虚之症状表现：“若血脉虚损，神性劳伤，则多恐畏，喜怒，心烦，咽痛口干，精神恍惚。此皆心气不足之所致也。”", "白话": "《太平圣惠方·治心气不足诸方》也指出心气虚的症状表现：“如果血脉虚损、神气劳伤，就多恐惧畏惧、易怒，心烦，咽痛口干，精神恍惚——这都是心气不足所造成的。”"}, {"source": "条45｜《心悸》三审稿·第三章评述（心血不足证）", "原文": "心悸之心血不足证多表现为心悸不宁，动则尤甚，神疲倦怠，面色不华，头晕，舌质淡，苔薄白，脉细弱或结代。明·周文采《医方选要·怔忡健忘动悸门》：记载“夫怔忡者，心血不足，心中躁动不宁也。盖心主血，血旺则心主自安矣。”，指出怔忡可由心血不足所致。", "白话": "心悸的心血不足证多表现为：心悸不宁，活动后尤其加重，神疲倦怠，面色不华，头晕，舌质淡，苔薄白，脉细弱或结代。明·周文采《医方选要·怔忡健忘动悸门》记载：“怔忡是心血不足、心中躁动不宁。心主血，血旺则心主自然安宁。”指出怔忡可由心血不足所致。"}, {"source": "条46｜《心悸》三审稿·第三章评述（心血不足证·三症递进）", "原文": "明·武之望《济阳纲目·健忘》则记载了惊悸、怔忡、健忘具有病程递进关系，且均是由于心血不足所致：“李氏曰：惊悸久则怔忡，怔忡久则健忘，三证虽有浅深，然皆心脾血少神亏，清气不足，痰火浊气上攻，引神归舍丹主之。”", "白话": "明·武之望《济阳纲目·健忘》记载了惊悸、怔忡、健忘具有病程递进关系，且都是由于心血不足所致：“李氏说：惊悸日久则成怔忡，怔忡日久则成健忘；三证虽有浅深之别，但都是心脾血少、神气亏虚，清气不足，痰火浊气上攻，用引神归舍丹主治。”"}, {"source": "条47｜《心悸》三审稿·第三章评述（心血不足证·傅青主、蔡贻绩）", "原文": "清·傅山《傅青主女科歌括·产后编下卷》亦提出：“血不足，则怔忡惊悸不安耳。”清·蔡贻绩在《内伤集要·内伤虚损证治》中指出劳心太过而致心血亏虚，“人有劳心经营太过，心火沸腾，先则夜梦不安，久则惊悸健忘，心神憔悴，血不华色，此乃心血太亏也。”。", "白话": "清·傅山《傅青主女科歌括·产后编下卷》也提出：“血不足，就会怔忡惊悸不安。”清·蔡贻绩在《内伤集要·内伤虚损证治》中指出劳心太过可致心血亏虚：“有人劳心经营太过，心火沸腾，先是夜梦不安，日久则惊悸健忘，心神憔悴，血不能荣华面色——这是心血大亏。”"}, {"source": "条48｜《心悸》三审稿·第三章评述（阴虚火旺证·张从正）", "原文": "心悸之阴虚火旺证常表现为心悸易惊，心烦失眠，五心烦热，口干，盗汗；思虑劳心则症状加重，伴有耳鸣，腰酸，头晕目眩，舌红少津，苔少或无，脉细数。金·张从正对肾精不足，心火亢盛，心肾不交之证做出了详细的阐述，在《儒门事亲·论火热二门》中指出：“凡男子妇人，所显证候，皮肤发热，肌肉消瘦，四肢倦怠，兼有头痛颊赤，心忪，唇干舌燥，日晡潮热，夜有盗汗，涕唾稠粘黏，胸膈不利，或时喘嗽，五心烦热，睡卧不安，饮食减少", "白话": "心悸的阴虚火旺证常表现为：心悸易惊，心烦失眠，五心烦热，口干，盗汗；思虑劳心则症状加重，伴耳鸣、腰酸、头晕目眩，舌红少津，苔少或无，脉细数。金·张从正对肾精不足、心火亢盛、心肾不交之证作了详细阐述，在《儒门事亲·论火热二门》中指出：“凡男子妇人所显现的证候：皮肤发热，肌肉消瘦，四肢倦怠，兼有头痛面颊发赤、心悸、唇干舌燥、午后潮热、夜间盗汗、涕唾稠粘、胸膈不利，或时时喘咳，五心烦热，睡卧不安，饮食减少，多想饮水，经脉不通——病名叫做什么病？《奇病论》说：女子月经不来，是血滞之病"}, {"source": "条49｜《心悸》三审稿·第三章评述（阴虚火旺证·叶氏）", "原文": "明·武之望提到阴火上冲可致使怔忡，并可见诸多阴火之症状，《济阳纲目》卷五十四载：“叶氏曰：怔忡或有阴火上冲，怔忡不已，甚者火炎于上，或头晕眼花，或齿落发脱，或手指如杵长大，或见异物，或腹中作声，此阴火为患也，治宜滋阴抑火汤。”", "白话": "明·武之望提到阴火上冲可致怔忡，并可见诸多阴火症状，《济阳纲目》卷五十四载：“叶氏说：怔忡或有阴火上冲，怔忡不止，严重的火炎于上，或头晕眼花，或齿落发脱，或手指像杵一样长大，或看见异物，或腹中作声——这是阴火为患，治疗宜用滋阴抑火汤。”"}, {"source": "条50｜《心悸》三审稿·第三章评述（阴虚火旺证·王士雄）", "原文": "清·王士雄则认为其他疾病病愈后出现的怔忡乃为阴虚火旺，《温热经纬·余师愚疫病篇》记载：“瘥后怔忡，乃水衰火旺，心肾不交。宜补水养心。”", "白话": "清·王士雄认为其他疾病痊愈后出现的怔忡属于阴虚火旺，《温热经纬·余师愚疫病篇》记载：“病愈后的怔忡，是水衰火旺、心肾不交，宜补水养心。”"}, {"source": "条51｜《心悸》三审稿·第三章评述（心阳不振证）", "原文": "心悸之心阳不振证常表现为怔忡胸闷，面色㿠胱白，体倦懒言，形寒肢冷，舌淡苔白，脉虚无力。在《伤寒论》中即有上焦心阳受损而致心悸之桂枝甘草汤证，及肾阳受损蒸化无权而致水饮凌心的真武汤证。", "白话": "心悸的心阳不振证常表现为：怔忡胸闷，面色㿠白，体倦懒言，形寒肢冷，舌淡苔白，脉虚无力。《伤寒论》中既有上焦心阳受损而致心悸的桂枝甘草汤证，也有肾阳受损、蒸化无权而致水饮凌心的真武汤证。"}, {"source": "条52｜《心悸》三审稿·第三章评述（心阳不振证·喻昌）", "原文": "清·喻昌《医门法律·中寒门》中对心阳虚之心悸做出解释：“其一因误汗，致心悸头眩身瞤动，无可奈何者，用真武汤为救法。其证发汗不解，仍发热心下悸，头眩身瞤动，振振欲擗地。汗虽出而热不退，则邪未尽，而正已大伤。况里虚为悸，上虚为眩，经虚为瞤，身振振摇，无往而非亡阳之象，所以行真武把关坐镇之法也。盖太阳膀胱为肾之府，肾中阳虚阴盛，势必传出于府，以故才见脉微恶寒，漏汗恶风，心悸头眩，肉瞤筋惕，躁扰等证。”", "白话": "清·喻昌《医门法律·中寒门》对心阳虚之心悸作了解释：“其一是因误汗，导致心悸、头眩、身瞤动，无可奈何的，用真武汤作救法。其证发汗不愈，仍发热、心下悸、头眩、身瞤动、振振欲倒地。汗虽出而热不退，则邪未尽而正已大伤。况且里虚则悸，上虚则眩，经虚则瞤动，身体振振摇动，无一处不是亡阳之象，所以行真武汤把关坐镇之法。太阳膀胱是肾之腑，肾中阳虚阴盛，势必传出到腑，所以才见到脉微恶寒、漏汗恶风、心悸头眩、肉瞤筋惕、躁扰等证。”"}, {"source": "条53｜《心悸》三审稿·第三章评述（心阳不振证·周学海）", "原文": "清·周学海指出怔忡头晕并见二便无热，乃是元阳亏损，心阳不振，于《脉义简摩·王汉皋论老人脉病证治》记载：“怔忡头晕，二便有热者。肺不生津，阴不足以养阳，膻中小肠脉皆上行，故不能眠也。若二便无热，乃元阳已亏，血不养心，故怔忡。髓不实脑，故头晕。目昏者，脾湿乘肝热而上蒸。目陨花者，真阳虚而光不聚也，并无外感。”", "白话": "清·周学海指出怔忡头晕并见二便无热，是元阳亏损、心阳不振，在《脉义简摩·王汉皋论老人脉病证治》记载：“怔忡头晕，二便有热的，是肺不生津、阴不足以养阳，膻中与小肠之脉都上行，所以不能眠。如果二便无热，那是元阳已亏、血不养心，所以怔忡；髓不充养于脑，所以头晕；目昏的，是脾湿趁肝热而上蒸；目花的，是真阳虚而光不聚——都没有外感。”"}, {"source": "条54｜《心悸》三审稿·第三章评述（水饮凌心证）", "原文": "心悸之水饮凌心证常表现为心悸，胸闷痞满，渴不欲饮，小便短少，下肢浮肿，形寒肢冷；伴有头晕，恶心呕吐，流涎；舌淡胖，苔滑，脉弦滑或沉细，或结、代。心气不足，脾肾阳虚，水液不化停聚为痰饮可而导致心悸。", "白话": "心悸的水饮凌心证常表现为：心悸，胸闷痞满，渴不欲饮，小便短少，下肢浮肿，形寒肢冷；伴头晕、恶心呕吐、流涎；舌淡胖，苔滑，脉弦滑或沉细，或结、代。心气不足、脾肾阳虚，水液不化、停聚为痰饮，可以导致心悸。"}, {"source": "条55｜《心悸》三审稿·第三章评述（水饮凌心证·成无己）", "原文": "张仲景在《伤寒论》即认识到水饮与心悸的发生有关，成无己对其解释为：“其停饮者，由水停心下，心主火而恶水，水即内停，心自不安，则为悸也。”", "白话": "张仲景在《伤寒论》中就已认识到水饮与心悸的发生有关，成无己解释说：“那停饮的，是由于水停在心下，心属火而厌恶水；水既然内停，心自然不安，就成为悸。”"}, {"source": "条56｜《心悸》三审稿·第三章评述（水饮凌心证·《圣济总录》）", "原文": "《圣济总录·虚劳惊悸》则指出心气不足、水停心下乘心会致惊悸：“论曰虚劳惊悸者，心气不足，心下有停水也，心藏神，其主脉，若劳伤血脉，致心气不足，因为邪气所乘，则令人精神惊惕悸动不定，若水停心下，水气乘心，亦令悸也。”", "白话": "《圣济总录·虚劳惊悸》指出心气不足、水停心下乘心会引起惊悸：“论述说：虚劳惊悸，是心气不足、心下有停水。心藏神，主血脉；如果劳伤血脉，导致心气不足，因而被邪气所乘，就使人精神惊惕、悸动不定；如果水停心下、水气乘心，也使人发悸。”"}, {"source": "条57｜《心悸》三审稿·第三章评述（痰浊阻滞证·徐春甫）", "原文": "痰浊产生后可随一身之气流窜全身，外而肌肤、筋骨、经络，内而脏腑，无处不到，故亦积于心中而产生各种纷繁复杂的病变。明·徐春甫指出应辨别惊悸之证型，痰饮积于心包胃口导致的惊悸不可作做虚治，《古今医统大全·惊悸门》曰：“郁痰留饮，积于心包胃口而致惊悸怔忡者有之，此又不可概以虚而治也。”", "白话": "痰浊产生后可随一身之气流窜全身，外而肌肤、筋骨、经络，内而脏腑，无处不到，所以也积于心中而产生各种纷繁复杂的病变。明·徐春甫指出应辨别惊悸的证型：痰饮积于心包胃口导致的惊悸不可当作虚证治疗，《古今医统大全·惊悸门》说：“郁痰留饮，积于心包胃口而致惊悸怔忡的是有的，这又不可一概按虚来治疗。”"}, {"source": "条58｜《心悸》三审稿·第三章评述（痰浊阻滞证·何梦瑶）", "原文": "清·何梦瑶指出了痰在心胸之诸多临床表现，《医碥·杂症·痰》曰：“痰在心胸，噫气吞酸嘈杂，或痛或秽，（干呕也。）。或心下如停冰铁，或惊悸怔忡如畏人捕，或胸膈迷闷如癫呆状，或痞满、健忘、恶心。”", "白话": "清·何梦瑶指出了痰在心胸的诸多临床表现，《医碥·杂症·痰》说：“痰在心胸，噫气、吞酸、嘈杂，或疼痛或泛恶（就是干呕）。或心下如停冰铁般冷重，或惊悸怔忡、好像害怕被人捕捉，或胸膈迷闷如痴呆之状，或痞满、健忘、恶心。”"}, {"source": "条59｜《心悸》三审稿·第三章评述（痰浊阻滞证·王旭高）", "原文": "清·王旭高亦指出了痰饮致悸的病症特点，《医学刍言·第十一章痰饮》：“痰饮为病，心悸头眩，短气而咳，舌苔白者多。”", "白话": "清·王旭高也指出了痰饮致悸的病症特点，《医学刍言·第十一章痰饮》：“痰饮为病，心悸头眩，短气而咳，舌苔白的居多。”"}, {"source": "条60｜《心悸》三审稿·第三章评述（火热致惊证·王肯堂）", "原文": "各种原因导致的火热之邪扰及心神，皆可出现心悸。王肯堂指出“悸之为病，是心脏之气不得正动，而为火邪者也”，并提出包络之火能行于五脏，五脏妄动化火，“包络之火，非惟唯辅心，而且游行于五脏，故五脏之气妄动者，皆火也。是以各脏有疾，皆能与包络之火合动而作悸。”。", "白话": "各种原因导致的火热之邪扰及心神，都可出现心悸。王肯堂指出“悸的病，是心脏之气不得正动，而成为火邪”，并提出包络之火能行于五脏、五脏妄动化火：“包络之火不只辅助心，而且游行于五脏，所以五脏之气妄动的都是火。因此各脏有病，都能与包络之火相合发动而作悸。”"}, {"source": "条61｜《心悸》三审稿·第三章评述（火热致惊证·《太平圣惠方》）", "原文": "《太平圣惠方·治心实泻心诸方》则描述了火热致惊的临床表现：“夫心实则生热，热则阳气盛，阳盛则卫气不行，荣气不通，遂令热毒稽留，心神烦乱，面赤身热，口舌生疮，咽燥头疼，喜笑，恐悸，手心热，满汗出，衄血，其脉洪实相搏者，是其候也。”", "白话": "《太平圣惠方·治心实泻心诸方》则描述了火热致惊的临床表现：“心实就会生热，热则阳气盛，阳盛则卫气不行、营气不通，于是热毒稽留，心神烦乱，面赤身热，口舌生疮，咽燥头疼，喜笑，恐惧心悸，手心热，满身汗出，鼻出血；脉洪实相搏的，就是它的证候。”"}, {"source": "条62｜《心悸》三审稿·第三章评述（瘀阻心脉证）", "原文": "心悸之瘀阻心脉证常表现为心悸不安，胸闷不舒，心痛时作，痛如针剌刺，唇甲青紫，舌质紫暗或有瘀斑，脉涩或结或代。瘀阻血脉而致使心脉运行不畅，心失所养而发生心悸怔仲怔忡。唐容川在《血证论》写道：“有瘀血亦怔仲怔忡。”认为瘀血阻滞会导致怔仲怔忡心悸，", "白话": "心悸的瘀阻心脉证常表现为：心悸不安，胸闷不舒，心痛时作，痛如针刺，唇甲青紫，舌质紫暗或有瘀斑，脉涩或结或代。瘀阻血脉致使心脉运行不畅，心失所养而发生心悸怔忡。唐容川在《血证论》写道：“有瘀血也会导致怔忡。”认为瘀血阻滞会导致怔忡心悸。"}, {"source": "条63｜《心悸》三审稿·第三章评述（瘀阻心脉证·王清任）", "原文": "王清任亦指出，瘀血所致的心悸怔忡用归脾安神等方不效，需用血府逐瘀汤等活血祛瘀的方药方能取良效。", "白话": "王清任也指出，瘀血所致的心悸怔忡，用归脾汤、安神等方无效的，需用血府逐瘀汤等活血祛瘀的方药才能取得良效。"}, {"source": "条64｜《心悸》三审稿·第三章评述（与奔豚鉴别·文献）", "原文": "奔豚发作时，自觉心胸躁动不安，《难经·五十六难》云：“发于小腹，上至心下，若豚状，或上或下无时。”。清·黄元御在《金匮悬解·内伤杂病》中对奔豚与心悸进行了区分：“大凡虚劳内伤之家，必有惊悸、奔豚之病。奔豚或有时作止，而惊悸则无刻不然，其时常惊悸而奔豚不作者，己土未败，而风木不能遽发也。然悸动未息，则奔豚虽不发作，而发作之根，未尝不在。”", "白话": "奔豚发作时，自觉心胸躁动不安。《难经·五十六难》说：“（奔豚）发于小腹，上至心下，像小猪（奔突）之状，或上或下、发作无时。”清·黄元御在《金匮悬解·内伤杂病》中对奔豚与心悸作了区分：“大凡虚劳内伤之家，必有惊悸、奔豚之病。奔豚或时作时止，而惊悸则无时不然；其时常惊悸而奔豚不发作的，是己土（脾）未败、风木不能骤发。然而悸动不息，那么奔豚虽不发作，其发作之根未尝不存在。”"}, {"source": "条65｜《心悸》三审稿·第三章评述（与奔豚鉴别·要点）", "原文": "奔豚与心悸的鉴别要点在于，心悸为心中剧烈跳动，发自于心，发无定时；奔豚乃上下冲逆，发自少腹，有时作止。", "白话": "奔豚与心悸的鉴别要点在于：心悸是心中剧烈跳动，发自于心，发作无定时；奔豚是气上下冲逆，发自少腹，时作时止。"}, {"source": "条66｜《心悸》三审稿·第三章评述（与卑惵鉴别）", "原文": "卑惵之胸中不适乃是由于痞塞，明·戴思恭的《证治要诀·怔忡》卑惵症状描述为：“痞塞不欲食，心中常有所歉，爱处暗室，或倚门后，见人则惊避，似失志状。”。其病因在于“心血不足”，卑惵之胸中不适乃为痞塞感，并伴随神志异常的病证表现，且一般没有促、结、代、疾、迟等脉象；而心悸之胸中不适则是缘于心跳异常，虽有时坐卧不安，但不避人，无情志的改变。", "白话": "卑惵的胸中不适是由于痞塞。明·戴思恭《证治要诀·怔忡》对卑惵症状的描述是：“胸中痞塞不欲饮食，心中常有歉然不足之感，喜欢待在暗室，或倚在门后，见人就惊惶躲避，好像失志的样子。”其病因在于“心血不足”。卑惵的胸中不适是痞塞感，并伴随神志异常的病证表现，且一般没有促、结、代、疾、迟等脉象；而心悸的胸中不适是源于心跳异常，虽有时坐卧不安，但不回避他人，没有情志的改变。"}, {"source": "条67｜《心悸》三审稿·第三章评述（与胃脘痛鉴别）", "原文": "胃脘又称心下，胃脘痛亦可见惕惕然跳动，二者的鉴别要点为在于病位，其胃脘痛病位在胃，而心悸病位在心。明·赵贞观《绛雪丹书·产后下卷》对胃脘痛进行了详细的记载：“心痛，即胃脘痛，以胃脘在心之下，因伤寒气及冷物而作痛，因痛起于心，俗呼为心痛。夫心为君主之官，主气行血，统驭脏腑血气，血盛则泰然安宁，血不足则惕然惊悸，岂可痛乎。”清·梁玉瑜《医学答问·十二经各种证候的表现和治法如何》亦有言：“胃脘痛者，心悸", "白话": "胃脘又称心下，胃脘痛也可见惕惕然跳动。二者的鉴别要点在于病位：胃脘痛病位在胃，心悸病位在心。明·赵贞观《绛雪丹书·产后下卷》对胃脘痛作了详细记载：“心痛就是胃脘痛，因为胃脘在心之下，因伤寒之气及冷物而作痛；因疼痛发生在心的部位，俗称为心痛。心是君主之官，主气行血，统摄脏腑血气；血盛则泰然安宁，血不足则惕然惊悸——心岂可痛呢。”清·梁玉瑜《医学答问·十二经各种证候的表现和治法如何》也说：“胃脘痛的，见心悸怔忡而喜按。”"}, {"source": "条68｜《心悸》三审稿·第三章评述（结语）", "原文": "《灵枢·本脏》言：“视其外应，以知其内脏，则知所病矣。”在心悸病的诊治中证治条辨内容起到了关键性的衔接作用，为心悸病的诊断与治疗处方提供了参考与依据。本部分证候特点首论心悸的诊法，从医者角度出发探讨望、切二诊，以从中获取的具有诊断意义的客观征象。再则指出“心悸”的临床特点，并对心悸病中“惊”“悸”“怔忡”“恐”的概念进行了区分。鉴于上述内容，结合临床其他兼症表现对心悸病做出辩证辨证分型，分而论治。", "白话": "《灵枢·本脏》说：“观察外在的表现，以了解内脏的情况，就知道所病了。”在心悸病的诊治中，证治条辨内容起到了关键性的衔接作用，为心悸病的诊断与治疗处方提供了参考与依据。本部分（证候特点）先论心悸的诊法，从医者角度探讨望、切二诊，以获取具有诊断意义的客观征象；再指出“心悸”的临床特点，并对心悸病中“惊”“悸”“怔忡”“恐”的概念加以区分。鉴于上述内容，结合临床其他兼症表现，对心悸病作出辨证分型、分而论治。最后就临床上易混淆的心悸与奔豚、心悸与卑惵、心悸与胃脘痛进行鉴别诊断。"}, {"source": "条1｜《针灸甲乙经》六经受病发伤寒热病第一（中）", "原文": "热病先手臂痛，身热，瘛疭，唇口聚，鼻张目下，汗出如转珠，两乳下三寸坚，胁下满悸，列缺主之。", "白话": "患热病先见手臂疼痛，身体发热，手足抽搐，唇口紧撮，鼻翼张动、目下（异常），汗出如滚动的珠子，两乳下三寸处坚硬，胁下胀满悸动——取列缺穴主治。"}, {"source": "条2｜《幼幼新书》察形色治病第九", "原文": "心多惊悸言颧左，右肺青风喘嗽声。", "白话": "心（病）多见惊悸，说的是颧左（的色象）；右颊属肺，色青主风，（伴）喘咳有声。"}, {"source": "条3｜《万氏秘传片玉心书》水镜诀", "原文": "盖脉纹见有色者……又当辨：……水字形，主惊，积热烦躁，心神迷闷，夜啼痰盛，口噤搐搦。针形，主心肝受热，热极生风，惊悸烦闷，神困不食，痰盛搐搦。", "白话": "小儿指纹显出颜色的……又应当辨别：……指纹呈水字形的，主惊，积热烦躁，心神迷闷，夜间啼哭、痰涎壅盛，牙关紧闭、抽搐；指纹呈针形的，主心肝受热，热极生风，惊悸烦闷，精神困倦、不思饮食，痰盛抽搐。"}, {"source": "条4｜《古今医统大全》幼幼汇集", "原文": "《全婴方》云：额上属心，南方之位，火性炎上故居上，夏见微赤者平，深赤者病，黑色者绝，赤色主心经有风热，心躁惊悸，睡卧不安，青黑色主心中有邪，惊风腹疼，手足瘛疭而啼叫，青黑甚主心腹疼，黄色主惊疳骨热渴，皮毛干燥，夜多盗汗，头发焦黄。", "白话": "《全婴方》说：额上属于心，居南方之位，火性炎上所以故居于上位；夏季微微见赤色的为正常，深赤的是病色，黑色的是死绝之色。赤色主心经有风热，心烦躁、惊悸、睡卧不安；青黑色主心有邪，惊风腹痛，手足抽搐而啼叫；青黑严重的，主心腹疼痛；黄色主惊疳、骨蒸发热口渴，皮毛干燥，夜间多盗汗，头发焦黄。"}, {"source": "条5｜《全婴方》（据《古今医统大全·幼幼汇集》转引）", "原文": "《全婴方》云：额上属心，南方之位，火性炎上故居上，夏见微赤者平，深赤者病，黑色者绝，赤色主心经有风热，心躁惊悸，睡卧不安，青黑色主心中有邪，惊风腹疼，手足瘛疭而啼叫，青黑甚主心腹疼，黄色主惊疳骨热渴，皮毛干燥，夜多盗汗，头发焦黄。", "白话": "说额上属于心，应南方之位，火性炎上故居于上位；夏天微赤为平，深赤为病，黑色为绝。赤色主心经有风热，心躁惊悸、睡卧不安；青黑色主心有邪，惊风腹痛、手足抽搐啼叫；青黑甚者主心腹痛；黄色主惊疳、骨热口渴、皮毛干燥、夜间盗汗、头发焦黄。"}, {"source": "条6｜《幼科证治准绳》察色", "原文": "红赤色者为热，为痰积壅盛，惊悸烦躁增进。", "白话": "红赤色主热，主痰积壅盛，（并见）惊悸烦躁加重。"}, {"source": "条7｜《永类钤方》（见引于《幼科证治准绳·察色》）", "原文": "《永类钤方》……心部所主，颧面脸颊，皆属心位，黑即沉困，青即惊悸，赤心发风，白即疳气，虚黄卫积，浮肿气逆，心绝何因，大叫数声，过关不叫，必作鸦声，加热惊谵，散热清心。", "白话": "《永类钤方》……心部所主的部位，颧面脸颊都属于心位：黑色则病势沉困，青色则惊悸，赤色为心发风，白色是疳气，虚黄为（卫）积，浮肿为气逆。心绝的证候如何？大叫数声，过关（之后）不再叫，必发鸦声；加热则惊谵，散热则清心。"}, {"source": "条8｜《医宗必读》色诊", "原文": "红色见于口唇，及三阴、三阳，上下如马肝之色，死血之状者，心气绝，主死。若如橘红马尾色者，只是心病，有怔仲怔忡惊悸、夜卧不宁。", "白话": "红色出现在口唇，以及三阴三阳（部位），上下如同马肝的颜色、死血样子的，是心气绝，主死亡。如果像橘红、马尾色的，只是心病，可见怔忡、惊悸、夜卧不宁。"}, {"source": "条9｜《（痘疹）生民切要》头面形色主病", "原文": "印堂红脉至山根，是心与小肠俱热，主小便赤色，惊悸咬牙。” “风池红，主夜啼，惊悸，不得安卧。", "白话": "印堂的红脉延伸到山根，是心与小肠俱热，主小便色赤、惊悸、咬牙。（又）风池色红，主夜间啼哭、惊悸、不得安卧。"}, {"source": "条10｜《（痘疹）生民切要》辨五脏形色", "原文": "心属火，时发惊悸，其色赤，发而为血泡，其色赤。", "白话": "心属火，时时发作惊悸，其色赤；（痘疹）发出成为血泡，颜色也赤。"}, {"source": "条11｜《医宗说约》面部验色主病", "原文": "两颊赤时伤寒寻。额间赤色心经热；烦躁惊悸不必说；青黑腹痛又惊风，瘈瘛疭叫啼何时歇？微黄惊疳自古传；纯黑之时命已绝。", "白话": "两颊发赤时当从伤寒寻（证）；额间赤色是心经有热，烦躁惊悸自不必说；青黑主腹痛又主惊风，抽搐啼叫何时止歇？微黄主惊疳，自古相传；纯黑的时候，生命已绝。"}, {"source": "条12｜《小儿推拿广意》入门察色", "原文": "面部气色，为十二经总现之处。而五位色青者，惊积不散，欲发风候；五位色红者，伤寒痰积壅盛，惊悸不宁。", "白话": "面部的气色是十二经脉总汇显现之处。五位色青的，是惊积不散，将要发风的征兆；五位色红的，是伤寒痰积壅盛，惊悸不宁。"}, {"source": "条13｜《动功按摩秘诀》辨小儿诸症", "原文": "有如‘川、水’字形者，主惊悸，食积烦躁，痞闷少食，夜啼痰盛，口噤搐搦，此脾虚积滞，木克土也。", "白话": "（指纹）有像川字、水字形状的，主惊悸、食积烦躁、痞闷纳少、夜间啼哭、痰涎壅盛、牙关紧闭、抽搐；这是脾虚积滞，木克土所致。"}, {"source": "条14｜《四诊抉微》辨虎口纹十三形全幼心鉴", "原文": "第六，弓反里形。主感冒寒邪，哽气出气，惊悸倦怠，四肢冷，小便赤，咳嗽呕涎，先用惺惺散，助胃气，祛外邪；后以五味异功散，加茯苓、当归，养心血，助胃气。若外邪既解，而惊悸指冷，脾气受伤也，宜七味白术散补之。若闷乱气粗，喘促者难治，脾虚甚故也。” “第十一，长针形，过命关一二米许。主心肝热极生风，惊悸困倦，痰盛搐搦。", "白话": "第六种是弓反里形（指纹）。主感冒寒邪，哽气、出气，惊悸倦怠，四肢冷，小便色赤，咳嗽呕涎。先用惺惺散，助胃气、祛外邪；然后用五味异功散加茯苓、当归，养心血、助胃气。如果外邪已解而仍惊悸、指尖冷，是脾气受伤，宜用七味白术散补之。如果闷乱气粗、喘促的，难治，因为脾虚太甚。第十一种是长针形，指纹过命关一二米许。主心肝热极生风，惊悸困倦，痰盛抽搐。"}, {"source": "条15｜《幼幼集成》面部形色赋", "原文": "红色见而热痰壅盛，青色露而肝风怔悸。此概言通面之色，通面为足阳明胃经所主。胃经郁热，面必淡红，热搏津液，定化为痰而壅滞；风邪冲并，面必见青，心神不安，则为怔忡惊悸。", "白话": "红色出现而热痰壅盛，青色显露而肝风内动、怔悸。这是概说整个面部的颜色，整个面部为足阳明胃经所主。胃经郁热，面部必淡红，热邪搏结津液，必化为痰而壅滞；风邪冲逆合并，面部必现青色，心神不安，则成怔忡惊悸。"}, {"source": "条16｜《幼幼集成》万氏痘麻", "原文": "面目赤而惊悸兮，心火炎于膈上。” “耳后微赤属少阳，本经风热宜知悉；睡中惊悸若咬牙，微黄之色法无失。", "白话": "面目色赤而惊悸啊，是心火上炎于膈上。耳后微赤属于少阳，本经风热应当知晓；睡中惊悸、如咬牙，（色）微黄，（治）法无误。"}, {"source": "条17｜《金匮翼》心劳", "原文": "心劳者，恍惚惊悸，少颜色。", "白话": "心劳的病人，精神恍惚、惊悸，面色少华。"}, {"source": "条18｜《厘正按摩要术》诊指纹", "原文": "赤主心病，痰涎壅盛，惊悸不宁。", "白话": "（指纹）赤色主心病，痰涎壅盛，惊悸不宁。"}, {"source": "条19｜《医学摘粹》五色合五脏之病", "原文": "心化赤色，其病善喜，脐上动气，心胸烦痛，舌红口干，健忘惊悸，怔忡不安。如热乘心实，则发狂昏冒。如神怯心虚，则凄然好悲也。", "白话": "心应赤色，其病多喜笑，脐上动气，心胸烦痛，舌红口干，健忘惊悸、怔忡不安。如果热邪乘心之实，则发狂、昏冒；如果神气怯而心虚，则凄然好悲伤。"}, {"source": "条20｜《难经》十八难", "原文": "其外痼疾同法耶，将异也？然：结者，脉来去时一止无常数，名曰结也。伏者，脉行筋下也。浮者，脉在肉上行也。左右表里，法皆如此。假令脉结伏者，内无积聚，脉浮结者，外无痼疾，有积聚脉不结伏，有痼疾脉不浮结，为脉不应病，病不应脉，是为死病也。", "白话": "那外在的痼疾也是同一法则，还是有差异？答：结脉，是脉来去时有一止而没有常数，名叫结；伏脉，是脉行于筋下；浮脉，是脉在肉上行走。左右手、表里的诊法都是这样。假如脉结而伏的，内无积聚；脉浮而结的，外无痼疾；有积聚而脉不结伏，有痼疾而脉不浮结，这叫脉不应病、病不应脉，是死病。"}, {"source": "条21｜《伤寒论》辨太阳病脉证并治下第七", "原文": "伤寒脉结代，心动悸，炙甘草汤主之。……一名复脉汤。 脉按之来缓，时一止复来者，名曰结。又脉来动而中止，更来小数，中有还者反动，名曰结，阴也。脉来动而中止，不能自还，因而复动者，名曰代，阴也。得此脉者，必难治。", "白话": "患伤寒，脉结代、心动悸的，用炙甘草汤主治。……（炙甘草汤）又叫复脉汤。脉按之来势迟缓，时有一止而复来的，名叫结脉。又有脉来跳动而中止，再见稍数，其中有回还而又动的，也叫结脉，属阴。脉来跳动而中止，不能自行回还，因而复动的，名叫代脉，属阴。见到这种脉的，必难治。"}, {"source": "条22｜《金匮要略》惊悸吐衄下血胸满瘀血病脉证治", "原文": "寸口脉动而弱，动则为惊，弱则为悸。", "白话": "寸口脉动而弱，动的主惊，弱的主悸。"}, {"source": "条23｜《脉经》平杂病脉第二", "原文": "动为痛，为惊。沉为水为实，又为鬼疰。弱为虚为悸。", "白话": "动脉主痛、主惊；沉脉主水、主实，又主鬼疰；弱脉主虚、主悸。"}, {"source": "条24｜《脉经》平惊悸吐衄下血胸满瘀血脉证第十三", "原文": "寸口脉动而弱，动则为惊，弱则为悸。趺阳脉微而浮，浮则胃气虚，微则不能食，此恐惧之脉，忧迫所作也。惊生病者，其脉止而复来，其人目睛不转，不能呼气。” “胃气虚者，趺阳脉浮，少阳脉紧，心下必悸。何以言之？寒水相抟，二气相争，是以悸。脉得诸涩濡弱，为亡血。” “病人身热，脉小绝者，吐血，若下血，妇人亡经，此为寒，脉迟者，胸上有寒，噫气喜唾。", "白话": "寸口脉动而弱，动主惊，弱主悸。趺阳脉微而浮，浮是胃气虚，微是不能食，这是恐惧之脉，由忧迫所致。因惊而生病的，其脉止而复来，病人目睛不转动，不能呼气。胃气虚的，趺阳脉浮、少阳脉紧，心下必悸。为什么呢？寒水相结搏，二气相争，所以悸。脉见各种涩、濡、弱之象的，是亡血。病人身热而脉小绝的，主吐血或下血，妇人经血亡失；这是寒。脉迟的，胸上有寒，嗳气、多唾。"}, {"source": "条25｜《脉经》平人迎神门气口前后脉第二", "原文": "心虚。左手寸口、人迎以前，脉阴虚者，手厥阴经也。病苦悸恐不乐，心腹痛，难以言，心如寒状，恍惚。", "白话": "心虚。左手寸口、人迎以前，脉见阴虚的，属手厥阴经。病人苦于悸恐不乐、心腹痛难以名状、心中如寒、精神恍惚。"}, {"source": "条26｜《备急千金要方》心脏", "原文": "心虚寒。左手寸口人迎以前脉阴虚者，手少阴经也。病苦悸恐不乐，心腹痛难以言，心如寒，恍惚，名曰心虚寒也。", "白话": "心虚寒。左手寸口人迎以前脉见阴虚的，属手少阴经。病人苦于悸恐不乐、心腹痛难以名状、心中觉寒、精神恍惚，名叫心虚寒。"}, {"source": "条27｜《诸病源候论》阴挺出下脱候", "原文": "诊其少阴脉浮动，浮则为虚，动则为悸，故令下脱也。", "白话": "诊察少阴脉浮动，浮主虚，动主悸，所以使（阴挺）下脱。"}, {"source": "条28｜《备急千金要方》心脏脉论", "原文": "诊得心积，沉而芤，时上下无常处，病胸满悸。腹中热，面赤咽干，心烦，掌中热，甚则唾血。", "白话": "诊得心积之脉，沉而芤，（积气）时上时下无常处，病见胸满心悸；腹中热、面赤咽干、心烦、掌中热，重则唾血。"}, {"source": "条29｜《诸脉主病诗》浮", "原文": "怔忡惊悸寸常虚，血不荣心奈若何，腹胀诊关食不化尺痹痿，损伤精血骨蒸俱。此首统言左右两手虚脉病。” “左寸心虚故惊悸盗汗还短气，精神离散左关濡，又兼荣卫不和，体虚少力。尺男精败女脱血，自汗淋漓溲数俱。此首单言左手濡脉病。” “左寸怔忡右寸汗。", "白话": "怔忡惊悸而寸部常虚，是血不荣心，奈之何；腹胀诊关部（候中焦），食不化；尺部主痹痿，损伤精血、骨蒸并见。这一首统论左右两手虚脉的病。（又一首）左寸心虚所以惊悸、盗汗、短气，精神离散；左关脉濡，又兼荣卫不和，体虚少力；尺部男子精败、女子脱血，自汗淋漓、小便频数并见。这一首单论左手濡脉的病。（又）左寸主怔忡，右寸主汗。"}, {"source": "条30｜《诸脉主病诗》迟", "原文": "寸汗心虚左寸弱，阳虚心悸自汗，右身冷右寸弱病，又兼短气。” “寸缓心虚左寸缓，心气不足，怔忡多忘，又兼项背拘急痛，肺则浮右寸缓，肺气浮，言语短气。", "白话": "寸部主汗、心虚；左寸脉弱，主阳虚心悸、自汗；右身冷，右寸弱为病，又兼短气。（又一首）寸缓主心虚；左寸缓，心气不足，怔忡多忘，又兼项背拘急疼痛；（右寸）肺脉浮，右寸缓，肺气浮，言语短气。"}, {"source": "条31｜《金镜内台方议》炙甘草汤", "原文": "心中悸动，因脉结代，故知为真阴气虚少，阳气虚败。", "白话": "心中悸动，因为脉见结代，所以知道是真阴之气虚少、阳气虚败。"}, {"source": "条32｜《诊家枢要》脉阴阳类成", "原文": "代，更代也，动而中止，不能自还，因而复动，由是复止，寻之良久，乃复强起为代。主形容羸瘦，口不能言。若不因病，而人羸瘦，其脉代止，是一藏脏无气，他脏藏代之，真危亡之兆也。若因病而气血骤损，以致元气不续，或风家痛家，脉见止代，只为病脉。故伤寒家亦有心悸而脉代者，腹心痛亦有结涩止代不匀者，盖凡痛之脉，不可准也，又妊娠亦有脉代者，此必二月余之胎也。” “缓，不紧也。往来纡缓，呼吸徐徐，以气血向衰，故脉体为", "白话": "代，是更代的意思：脉跳动而中止，不能自行回还，因而又动，动而又止，切按良久才又勉强起动的，是代脉。主形体羸瘦、口不能言。如果不是因病而人羸瘦，其脉代止的，是一脏无气、他脏代之，真是危亡的征兆。如果因病而气血骤损，以致元气不续，或者风家、痛家脉见止代，只是病脉。所以伤寒家也有心悸而脉代的，腹心痛也有脉结涩、止代不匀的——大凡痛证之脉不可为准；又妊娠也有脉代的，这必是两个多月的胎。（又）缓，就是不紧：往来纡缓、呼吸徐徐，因为气血趋向衰少，所以脉体徐缓。主风、主虚、主痹、主弱、主疼"}, {"source": "条33｜《原幼心法》原治", "原文": "数则为热，迟则为寒，浮则为虚为风，沉则为实为积为痛，浮而数者为乳癎惊悸，虚而软者为慢惊瘛疭。", "白话": "数脉主热，迟脉主寒，浮脉主虚、主风，沉脉主实、主积、主痛；浮而数的是乳痫惊悸，虚而软的是慢惊、抽搐。"}, {"source": "条34｜《濒湖脉学》附四言举要", "原文": "代则气衰，或泄脓血；伤寒心悸，女胎三月。", "白话": "代脉主气衰，或泄下脓血；伤寒见之则心悸，女子见之主怀胎三月。"}, {"source": "条35｜《医学正传》癫狂痫证", "原文": "脉大坚疾者，癫狂。脉虚弦为惊，为风痫。", "白话": "脉大而坚疾的，是癫狂；脉虚弦的，是惊，是风痫。"}, {"source": "条36｜《医源经旨》经脉总论", "原文": "沉涩主惊，膻中宗气之脏也，膻中之气不足则火耗心血，神不内守，故惊悸而不宁耳。", "白话": "沉涩脉主惊；（心）是膻中宗气所居之脏，膻中之气不足，则火耗心血，神不能内守，所以惊悸不宁。"}, {"source": "条37｜《医源经旨》二十六脉主病", "原文": "动脉，为神气不安，主惊恐悸怖，为脱血虚劳。” “寸濡惊悸。关濡少食，尺濡为泄下，元气虚惫。", "白话": "动脉，主神气不安，主惊恐悸怖，又主脱血虚劳。寸部濡主惊悸，关部濡主少食，尺部濡主泄下、元气虚惫。"}, {"source": "条38｜《医学指南捷径六书》卷一", "原文": "统候：……虚。为虚候，气血耗散，惊悸恍惚。倦痿汗出。” “结为阴盛，阳无所附。……伤寒结代，心悸虚故。” “左寸逢弱，盗汗心悸。", "白话": "统论脉候：……虚脉，为虚候，气血耗散，惊悸恍惚，倦怠痿弱、汗出。结脉是阴盛、阳无所附。……伤寒见结代脉，心悸是虚的缘故。左寸逢弱脉，主盗汗、心悸。"}, {"source": "条39｜《医学指南捷径六书》《内经》正脉", "原文": "属候：……左寸后候膻中宗气。……沉逢心惕，沉涩或并其弦。或芤、或短，惊悸。", "白话": "分属脉候：……左寸之后候膻中宗气。……沉而逢之主心惕，沉涩或兼弦，或芤、或短，都主惊悸。"}, {"source": "条40｜《内经》（据《医学指南捷径六书·〈内经〉正脉》转引）", "原文": "属候：……左寸后候膻中宗气。……沉逢心惕，沉涩或并其弦。或芤、或短，惊悸。", "白话": "分属脉候：……左寸之后候膻中宗气。……沉而逢之主心惕；沉涩或兼弦，或芤、或短，都主惊悸。"}, {"source": "条41｜《古今医统大全》脉法部位表里虚实主病提纲", "原文": "左寸脉候：……里虚主病：沉而无力主里虚。悸怖惊恐，恶人声，精神恍惚，健忘，夜不寐。", "白话": "左寸脉所候：……里虚主病：沉而无力主里虚。可见悸怖惊恐、厌恶人声、精神恍惚、健忘、夜间不寐。"}, {"source": "条42｜《古今医统大全》痨瘵门", "原文": "卒喘心悸，其脉浮者，里虚也。", "白话": "突然气喘心悸，其脉浮的，是里虚。"}, {"source": "条43｜《脉理集要》统属诊法", "原文": "左寸后候，膻中宗气，凡诊浮分，弦大而涩，亏经伤卫，臂痛痰郁，弦涩脊软，弦大心跳，细涩芤短，皆为惊悸，浮大而滑，手心极热，沉分细涩，惊悸之类。", "白话": "左寸之后候膻中宗气。凡诊浮分（脉）弦大而涩的，是亏经伤卫，主臂痛、痰郁；弦涩的主脊软；弦大的主心跳；细、涩、芤、短的，都是惊悸之类；浮大而滑的，手心极热；沉分细涩的，也是惊悸之类。"}, {"source": "条44｜《赤水玄珠》结脉", "原文": "结者，间至而动缓，而一止复来者曰结。此阴盛之脉，凡伤寒脉结代心动悸者，炙甘草汤。", "白话": "结脉，是脉来动缓而时有一止、止后复来的，叫做结。这是阴盛之脉。凡伤寒脉结代、心动悸的，用炙甘草汤。"}, {"source": "条45｜《医学入门》脏腑六脉诊法", "原文": "沉弱阳虚多惊悸，《权舆》云：左寸弱兮阳气虚，心惊悸兮汗难除。” “沉弱惊汗濡寒热，沉弱阳虚，主惊悸多汗；沉濡虚损，主憎寒发热。” “沉滑痰热时相攻；滑与痰合本位，洪则为痰热，或呕逆，或怔忡，时作时止。", "白话": "沉弱脉主阳虚，多惊悸；《权舆》说：左寸弱啊阳气虚，心惊悸啊汗难除。沉弱主惊、汗，沉濡主寒热：沉弱属阳虚，主惊悸多汗；沉濡主虚损，主憎寒发热。沉滑主痰热时时相攻：滑与痰相合于本位，洪则为痰热，或呕逆，或怔忡，时作时止。"}, {"source": "条46｜《权舆》（据《医学入门·脏腑六脉诊法》转引）", "原文": "《权舆》云：左寸弱兮阳气虚，心惊悸兮汗难除。", "白话": "左寸脉弱啊，是阳气虚；心惊悸啊，汗难以除去。"}, {"source": "条47｜《医学入门》杂病脉法", "原文": "惊悸怔忡，寸动而弱，寸紧胃浮，悸病仍作。饮食痰火，伏动滑搏，浮微弦濡，忧惊过却，健忘神亏，心虚浮薄。寸口动而弱，动为惊，弱为悸。寸口脉紧，趺阳脉浮，胃气虚，是以惊悸，趺阳脉微而浮，浮为胃气虚，微则不能食，此恐惧之脉，忧迫所致也。", "白话": "惊悸怔忡，寸部动而弱；寸紧、（趺阳）胃浮，悸病仍然发作。饮食痰火，见伏、动、滑、搏；浮微弦濡，主忧惊已过；健忘神亏，心虚而脉浮薄。寸口动而弱，动主惊，弱主悸。寸口脉紧、趺阳脉浮，是胃气虚，所以惊悸；趺阳脉微而浮，浮是胃气虚，微则不能食，这是恐惧之脉，由忧迫所致。"}, {"source": "条48｜《医学入门》成童脉法", "原文": "浮数乳痫惊悸，虚濡慢惊瘛疭。", "白话": "浮数脉主乳痫惊悸；虚濡脉主慢惊、抽搐。"}, {"source": "条49｜《古今医鉴》幼科", "原文": "脉芤大小便中血，虚濡有气兼惊悸。", "白话": "脉芤主大小便出血；脉虚濡主有气（病）兼惊悸。"}, {"source": "条50｜《脉语》诸脉状主病", "原文": "虚。脉来有表无里，曰虚。为暑，为肠癖，为阴虚，精气不足。左寸虚，曰惊悸。右寸虚，曰喘息。", "白话": "虚脉。脉来有表无里的，叫做虚。主暑、主肠澼、主阴虚、精气不足。左寸虚叫惊悸，右寸虚叫喘息。"}, {"source": "条51｜《云林神彀》惊悸", "原文": "心中惊悸，脉必代结，饮食之悸，沉伏动滑。", "白话": "心中惊悸的，脉必见代、结；因饮食而悸的，脉见沉、伏、动、滑。"}, {"source": "条52｜《寿世保元》七表八里总归四脉", "原文": "关部主中焦胸腹之疾。……数而有力主热，无力主疮，主口热作渴，呕吐霍乱，怔忡烦躁，寒热交争。” “五脏见迟脉，主冷痛之病。……心脉迟，主小便频数，心疼呕水，怔忡多悸，伏梁脐痛。", "白话": "关部主中焦胸腹的疾病。……数而有力主热，无力主疮，主口热作渴、呕吐霍乱、怔忡烦躁、寒热交争。五脏见迟脉，主冷痛之病。……心脉迟，主小便频数、心痛呕水、怔忡多悸、伏梁脐痛。"}, {"source": "条53｜《景岳全书》正脉十六部（三）", "原文": "芤为阳脉，凡浮豁弦洪之属，皆相类也，为孤阳脱阴之候。为失血脱血，为气无所归，为阳无所附，为阴虚发热，为头晕目眩，为惊悸怔忡，为喘急盗汗。芤虽阳脉，而阳实无根，总属大虚之候。", "白话": "芤是阳脉，凡浮、豁、弦、洪之类都与它相似，是孤阳脱阴的征候。主失血脱血、气无所归、阳无所附、阴虚发热、头晕目眩、惊悸怔忡、喘急盗汗。芤虽然是阳脉，但阳实无根，总属大虚之候。"}, {"source": "条54｜《医学研悦》附诸证脉卷三", "原文": "怔忡惊悸健忘。心中动悸，脉必代结，饮食之悸，沉伏滑决。", "白话": "怔忡惊悸健忘。心中动悸的，脉必见代结；饮食所致之悸，脉见沉、伏、滑决。"}, {"source": "条55｜《古今医鉴》怔忡 惊悸", "原文": "脉：心中惊悸，脉必大结，饮食之悸，沉伏动滑。", "白话": "脉象：心中惊悸的，脉必大而结；饮食所致之悸，脉见沉伏动滑。"}, {"source": "条56｜《濒湖脉学》动脉（阳）", "原文": "动脉专司痛与惊，汗因阳动热因阴，或为泄痢拘挛病，男子亡精女子崩。", "白话": "动脉专主痛与惊；汗出因于阳动，发热因于阴（动）；或为泄痢、拘挛之病，男子亡精，女子血崩。"}, {"source": "条57｜《诊家正眼》虚脉（阴）", "原文": "体象：虚合四形，浮大迟软；及乎寻按，几不可见。主病：虚主血虚，又主伤暑。左寸心亏，惊悸怔忡。", "白话": "体象：虚脉合并四种脉形——浮、大、迟、软；等到寻按，几乎不可见。主病：虚主血虚，又主伤暑。左寸见虚，是心亏，主惊悸怔忡。"}, {"source": "条58｜《诊家正眼》动脉（阳）", "原文": "体象：动无头尾，其动如豆；厥厥动摇，必兼滑数。主病：动脉主痛，亦主于惊。左寸得动，惊悸可断；右寸得动，自汗无疑。左关若动，惊悸拘挛。", "白话": "体象：动脉无头无尾，其跳动如豆；厥厥动摇，必兼滑数。主病：动脉主痛，也主惊。左寸见动，可断为惊悸；右寸见动，自汗无疑；左关若见动，主惊悸拘挛。"}, {"source": "条59｜《诊家正眼》濡脉（阴中之阳）", "原文": "体象：濡脉细软，见于浮分；举之乃见，按之即空。主病:：濡主阴虚，髓绝精伤。左寸见濡，健忘惊悸。", "白话": "体象：濡脉细软，见于浮分；轻取才见，重按即空。主病：濡主阴虚、髓绝精伤。左寸见濡，主健忘惊悸。"}, {"source": "条60｜《诊家正眼》涩脉（阴）", "原文": "体象：涩脉蹇滞，如刀刮竹；迟细而短，三象俱足。主病：涩为血少，亦主精伤。寸涩心痛，或为怔忡。", "白话": "体象：涩脉蹇滞，如刀刮竹；迟、细、短三象俱全。主病：涩主血少，也主精伤。寸部脉涩，主心痛，或为怔忡。"}, {"source": "条61｜《诊家正眼》细脉（阴）", "原文": "体象:：细直而软，累累萦萦；状如丝线，较显于微。主病:：细主气衰，诸虚劳损。左寸细者，怔忡不寐。", "白话": "体象：细脉端直而软，累累萦萦，形状如丝线，比微脉更明显。主病：细主气衰、诸虚劳损。左寸细的，主怔忡不寐。"}, {"source": "条62｜《诊家正眼》散脉", "原文": "体象:：散脉浮乱，有表无里；中候渐空，按则绝矣。主病:：散为本伤，见则危殆。左寸见散，怔忡不寐。", "白话": "体象：散脉浮散紊乱，有表无里；中候渐空，重按则绝。主病：散主根本损伤，出现则危殆。左寸见散，主怔忡不寐。"}, {"source": "条63｜《类经》脉分四时无胃曰死", "原文": "乳之下，其动应衣，宗气泄也。前言应衣者，言其微动，似乎应衣，可验虚里之胃气。此言应衣者，言其大动，真有若与衣俱振者，是宗气不固而大泄于外，中虚之候也。愚按：虚里跳动，最为虚损病本，故凡患阴虚劳怯，则心下多有跳动，及为惊悸慌张者，是即此证，人止知其心跳而不知为虚里之动也。但动之微者病尚微，动之甚者病则甚，亦可因此以察病之轻重。", "白话": "乳之下（虚里）跳动应衣，是宗气外泄。前面说“应衣”，是说微微跳动、似乎应衣，可以查验虚里的胃气；这里说“应衣”，是说大为跳动，真像与衣服一起振动，这是宗气不固而大泄于外、中虚的征候。我按：虚里跳动最是虚损病的根本，所以凡患阴虚劳怯的，心下多有跳动，以至惊悸慌张的，就是此证；人们只知道心跳，而不知道是虚里在动。跳动轻微的病还轻，跳动厉害的病就重，也可以据此来察病的轻重。"}, {"source": "条64｜《脉诀汇辨》虚脉（阴）", "原文": "体象：虚合四形，浮大迟软；及乎寻按，几不可见。虚之为义，中空不足之象，专以软而无力得名者也。主病：虚主血虚，又主伤暑。左寸虚者，心亏惊悸。", "白话": "体象：虚脉合并浮、大、迟、软四种脉形；等到寻按，几乎不可见。虚的意义是中空不足之象，专以软而无力得名。主病：虚主血虚，又主伤暑。左寸虚的，主心亏惊悸。"}, {"source": "条65｜《脉诀汇辨》弱脉（阴）", "原文": "体象：弱脉细小，见于沉分；举之则无，按之乃得。沉而且细且小，体不充，势不鼓也。主病：弱为阳陷，真气衰弱。左寸弱者，惊悸健忘。", "白话": "体象：弱脉细小，见于沉分；轻取不见，重按才得。沉而兼细兼小，脉体不充，脉势不鼓。主病：弱主阳陷、真气衰弱。左寸弱的，主惊悸健忘。"}, {"source": "条66｜《脉诀汇辨》代脉（阴）", "原文": "若久病而得代脉，冀其回春，万不得一矣。 伤寒心悸，有中气虚者，停饮者，汗下后者。中气虚则阳陷，阳受气于胸中，阳气陷则不能上充于胸中，故悸。停饮者，饮水多而停于心下也。水停心下，水气上凌，心不自安，故悸。汗后则里虚矣。况汗乃心液，心液耗则心虚，心虚故悸。诸悸者，未必皆脉代。若脉代者，正指汗后之悸，以汗为心液，脉为心之合耳。", "白话": "如果久病而见代脉，希望它回春，一万个里也得不到一个。伤寒心悸，有因中气虚的，有停饮的，有汗下之后的。中气虚则阳陷，阳受气于胸中，阳气下陷就不能上充胸中，所以悸。停饮的，是饮水多而停于心下；水停心下，水气上凌，心不能自安，所以悸。汗后则里虚了，况且汗是心液，心液耗则心虚，心虚所以悸。各种悸未必都见代脉；若见代脉，正指汗后之悸——因为汗为心液、脉为心之合。"}, {"source": "条67｜《脉诀汇辨》濡脉（阴中之阴）", "原文": "体象：濡脉细软，见于浮分；举之乃见，按之即空。濡者，即软之象也。必在浮候见其细软，若中候、沉候，不可得而见也。叔和比之‘帛浮水面’，时珍比之‘水上浮沤’，皆状其随手而没之象也。主病：濡主阴虚，髓竭精伤。左寸濡者，健忘惊悸。濡在左关，血不荣筋。左尺得濡，精血枯损。右寸濡者，腠虚自汗。濡在右关，脾虚湿侵。右尺得濡，火败命倾。", "白话": "体象：濡脉细软，见于浮分；轻取才见，重按即空。濡就是软之象，必在浮候见其细软，中候、沉候都见不到。王叔和比作“帛浮水面”，李时珍比作“水上浮沤”，都是形容它随手而没的样子。主病：濡主阴虚、髓竭精伤。左寸濡的，主健忘惊悸；濡在左关，主血不荣筋；左尺得濡，主精血枯损；右寸濡的，腠理虚、自汗；濡在右关，主脾虚湿侵；右尺得濡，主火败命倾。"}, {"source": "条68｜《脉诀汇辨》散脉（阴）", "原文": "主病：散为本伤，见则危殆。左寸散者，怔忡不卧。散在左关，当有溢饮。左尺得散，北方水竭。右寸散者，自汗淋漓。散在右关，胀满蛊坏。右尺得散，阳消命绝。", "白话": "主病：散主根本损伤，出现则危殆。左寸散的，主怔忡不卧；散在左关，当有溢饮；左尺得散，主北方（肾）水竭；右寸散的，主自汗淋漓；散在右关，主胀满蛊坏；右尺得散，主阳消命绝。"}, {"source": "条69｜《脉诀汇辨》细脉（阴）", "原文": "体象：细直而软，累累萦萦；状如丝线，较显于微。小也，细也，状如丝也。比之于微，指下犹尚易见，未至于举按模糊也。主病：细主气衰，诸虚劳损。左寸细者，怔忡不寐。", "白话": "体象：细脉端直而软，累累萦萦，形状如丝线，比微脉更明显。就是小、细、如丝的意思；比起微脉，指下还容易见到，不至于举按模糊。主病：细主气衰、诸虚劳损。左寸细的，主怔忡不寐。"}, {"source": "条70｜《医宗说约》脉象主病二十九法", "原文": "小脉……寸小左神昏、善忘、惊悸，右懒言、气怯。” “滑脉。人身涩而脉往来滑者死；滑而盛病日进滑脉，行动不涩也，往来流利，如珠之盘，辗转替替然，与数相似一曰浮中如有力，一曰辘辘如欲脱曰滑，为阴气有余之候。《经》云：滑者，阴气有余也，阴气有余为多汗身寒。伯仁曰：滑为血实气壅之候，血不胜于气也。二论虽异，实可互为阐明。……寸滑左心悸，痰滞心包；右咳嗽、痰喘。” “涩脉。申酉月脉浮短而涩，病在外脉涩坚难治", "白话": "小脉：……寸小，左（寸）主神昏、善忘、惊悸，右（寸）主懒言、气怯。滑脉：人病体涩而脉往来滑的，主死；滑而盛的，病势日进。滑脉，行动不涩，往来流利，如珠在盘中辗转替替，与数脉相似：一说浮取中取有力，一说辘辘如欲脱，叫做滑，是阴气有余的征候。《经》说：滑者阴气有余也，阴气有余为多汗身寒。伯仁说：滑为血实气壅之候，是血不胜于气。两说虽异，实可互相阐明。……寸滑，左（寸）主心悸、痰滞心包，右（寸）主咳嗽、痰喘。涩脉：申酉月（秋）脉浮短而涩；病在外；脉涩坚的难治。涩脉之行，动而不滑：虚"}, {"source": "条71｜《经》（据《医宗说约·脉象主病二十九法》转引）", "原文": "《经》云：滑者，阴气有余也，阴气有余为多汗身寒。", "白话": "《经》说：滑是阴气有余；阴气有余，为多汗、身寒。"}, {"source": "条72｜《经》（据《医宗说约·脉象主病二十九法》转引·涩脉条）", "原文": "《经》曰：涩则心痛，涩则少血，脉涩曰痹，主亡汗、主伤精。", "白话": "《经》说：涩则心痛，涩则少血，脉涩叫做痹；又主亡汗、主伤精。"}, {"source": "条73｜《内经》（据《医宗说约·脉象主病二十九法》转引·弱脉条）", "原文": "寸口脉沉而弱曰寒热，脉弱以滑是有胃气，命曰易治《内经》。", "白话": "寸口脉沉而弱，叫做寒热；脉弱而兼滑，是有胃气，命名为易治。"}, {"source": "条74｜《医宗说约》嘈杂", "原文": "心嘈总是属虚火，火动痰生因作楚，……惊悸怔忡左寸涩，血少将来合四物，麦冬远志酸枣仁，竹茹乌梅炒米入。", "白话": "心嘈总属于虚火，火动生痰因而作楚。……惊悸怔忡而左寸脉涩，是血少，将来合四物汤，加入麦冬、远志、酸枣仁、竹茹、乌梅、炒米。"}, {"source": "条75｜《伤寒来苏集》厥阴病解第六", "原文": "脉结代心动悸者，似乎阳虚，实为阴弱，只可大剂滋阴，不可温补。", "白话": "脉结代而心动悸的，看似阳虚，其实是阴弱；只可用大剂滋阴，不可温补。"}, {"source": "条76｜《脉决阐微》第三篇", "原文": "左寸见小，惊悸时生；右寸见小，怯弱日甚。左寸见虚，心中恍惚；右寸见虚，胃内衰微。", "白话": "左寸见小脉，惊悸时时发生；右寸见小脉，怯弱一天天加重。左寸见虚脉，心中恍惚；右寸见虚脉，胃气衰微。"}, {"source": "条77｜《冯氏锦囊秘录》杂症大小合参卷十五", "原文": "下手脉沉，气痛。便知是气。沉极则伏，涩弱难治。其或沉滑，气兼痰饮。沉弦细动，心腹痛脉。皆是痛症。心痛在寸，腹痛在关，下部在尺，脉象显然。心中惊悸，脉必代结。饮食之悸，沉浮动滑。", "白话": "下手切脉见沉，（主）气痛，便知是气（为病）；沉极则伏，兼涩弱的难治。或者沉滑，是气兼痰饮；沉弦细动，是心腹痛的脉，都属于痛证。心痛候在寸，腹痛候在关，下部之病候在尺，脉象显然。心中惊悸，脉必见代结；饮食所致之悸，脉见沉浮动滑。"}, {"source": "条78｜《脉贯》弱脉（阴）", "原文": "贯释：弱由精气不足，故脉来萎弱而不振也，故主元气虚耗，萎弱不前，痼冷、虚热、泄精、虚汗等症也。左寸弱，阳虚、心悸、自汗。", "白话": "贯释：弱脉由精气不足，所以脉来萎弱不振，主元气虚耗、萎弱不前，以及痼冷、虚热、泄精、虚汗等症。左寸弱，主阳虚、心悸、自汗。"}, {"source": "条79｜《脉贯》滑脉（阳中阴）", "原文": "贯释：滑为血实气壅之候，是气不胜于血也，故主呕吐、痰逆、宿食、经闭之症也。左寸滑心经热痰，滑而实大，心惊舌强。", "白话": "贯释：滑是血实气壅的征候，是气不胜于血，所以主呕吐、痰逆、宿食、经闭等症。左寸滑，主心经热痰；滑而实大的，主心惊、舌强。"}, {"source": "条80｜《脉贯》微脉（阴）", "原文": "肺右微气促左心惊惕，肝为肢拘胃胀形，尺部带崩女精血弱男，恶寒消瘅痛呻吟。” “贯释：微为气血俱虚之候……左寸微，心虚怵惕，营血不足，头痛胸痞，虚劳盗汗。", "白话": "（歌曰）右寸微主气促，左寸微主心惊惕；左关（肝）微主肢拘，右关（胃）微主胀满之形；尺部微，女子主崩带，男子精血弱，恶寒、消瘅、疼痛呻吟。贯释：微是气血俱虚的征候。……左寸微，主心虚怵惕、营血不足、头痛胸痞、虚劳盗汗。"}, {"source": "条81｜《脉贯》虚脉（阴）", "原文": "虚脉浮大而迟，按之无力；芤脉浮大，按之中空。芤为脱血，虚为血虚。芤散二脉见浮脉。主病：脉虚身热为伤暑，自汗怔忡惊悸多；发热阴虚须早治，养营益气莫蹉跎。", "白话": "虚脉浮大而迟，重按无力；芤脉浮大，重按中空。芤主脱血，虚主血虚。芤、散二脉都见于浮部。主病：脉虚而身热是伤暑，自汗、怔忡、惊悸多见；发热属阴虚须早治，养营益气莫要蹉跎。"}, {"source": "条82｜《脉贯》微脉（阴）（原文释缓脉）", "原文": "贯释：缓为气血向衰之候，故主风湿痹痛等症，在上为项强，在下为脚弱。心不足则左寸缓，怔忡多忘，亦主项背急痛。", "白话": "贯释：缓是气血趋向衰少的征候，所以主风湿痹痛等症；在上主项强，在下主脚弱。心不足则左寸缓，主怔忡多忘，也主项背急痛。"}, {"source": "条83｜《脉贯》散脉（阴）", "原文": "主病分部：左寸怔忡右寸汗，溢饮左关应软散，右关软散胻肿胕，散居两尺魂应断。贯释：散为气血耗散，脏腑气绝之候，在病脉主虚阳不敛，又主心气不足，大抵非佳脉也。若两尺得散脉，乃精神衰惫，魂魄将离而不救也。左寸散，心脉衰而血少，神不安而怔忡作。", "白话": "主病分部：左寸主怔忡，右寸主自汗；左关软散，当有溢饮；右关软散，主胻肿、胕肿；散脉见于两尺，魂当断。贯释：散是气血耗散、脏腑气绝的征候；在病脉主虚阳不敛，又主心气不足，大抵不是好脉。如果两尺得散脉，是精神衰惫、魂魄将离，不可救了。左寸散，是心脉衰而血少，神不安而怔忡发作。"}, {"source": "条84｜《四诊抉微》弱（阴）", "原文": "左寸弱者，惊悸健忘；弱在左关，木枯挛急；左尺得弱，涸流可征。右寸弱者，自汗短气；弱在右关，水谷之疴；右尺得弱，阳陷可验。", "白话": "左寸弱的，主惊悸健忘；弱在左关，主肝木枯、筋挛急；左尺得弱，肾水涸流可征。右寸弱的，主自汗短气；弱在右关，主水谷之病；右尺得弱，阳陷可验。"}, {"source": "条85｜《四诊抉微》动（阳）", "原文": "左寸动者，惊悸可断；右寸动者，自汗无疑。左尺得动，亡精失血；右尺得动，龙火奋迅。动在左关，惊及拘挛；动在右关，心脾疼痛。", "白话": "左寸见动脉，可断为惊悸；右寸见动，自汗无疑。左尺得动，主亡精失血；右尺得动，主龙火奋迅。动在左关，主惊及拘挛；动在右关，主心脾疼痛。"}, {"source": "条86｜《四诊抉微》微（阴）", "原文": "分部诗：寸微气促或心惊，关脉微时胀满形，尺部见之精血弱，恶寒消瘅痛呻吟。” “滑伯仁曰：左寸微，心虚惊怯忧惕，营血不足。", "白话": "分部诗：寸部脉微主气促或心惊；关脉微时主胀满之形；尺部见微，精血弱，恶寒、消瘅、疼痛呻吟。滑伯仁说：左寸微，主心虚惊怯忧惕、营血不足。"}, {"source": "条87｜《四诊抉微》缓（阴）", "原文": "分部主病：汪、滑合曰，：两寸浮缓，伤风项背急痛；左寸沉缓，心气虚，怔忡健忘；右寸沉缓，肺气虚短。", "白话": "分部主病：汪、滑两家共同说：两寸浮缓，主伤风、项背拘急疼痛；左寸沉缓，主心气虚、怔忡健忘；右寸沉缓，主肺气虚、气短。"}, {"source": "条88｜《身经通考》何谓王叔和二十六脉", "原文": "濡脉，极软而浮细。为血气不足之候，为虚、为痹。为自汗。为下冷。寸濡惊悸，关濡少食，尺濡泄下。", "白话": "濡脉，极软而浮细。是血气不足的征候，主虚、主痹、主自汗、主下冷。寸部濡主惊悸，关部濡主少食，尺部濡主泄泻。"}, {"source": "条89｜《轩岐救正论》芤虚散不同", "原文": "虚脉迟大而软，按之无有，隐指豁豁然空。崔紫虚云，形大力薄，其虚可知，主伤暑，怔忡、自汗，惊悸、发热、阴虚、腹胀，痿瘅、遗精、，便泄诸症。” “所谓散脉者，其形如杨花散漫，去来无定，息数难齐，无统纪，无约束，涣散不收，稍按便四散不聚。主病为溢饮，为血耗，为怔忡，为脱汗，为胻肿胕。产妇得之生，妊妇得之坠，平人见之死。《难经》曰，散脉独见者危。柳氏曰，散为血气俱虚根本脱离之脉，若两尺见之魂断归冥。心脉洪", "白话": "虚脉迟大而软，重按如无，指下豁然空。崔紫虚说：形大而力薄，其虚可知，主伤暑、怔忡、自汗、惊悸、发热、阴虚、腹胀、痿瘅、遗精、便泄诸症。所谓散脉，其形状如杨花散漫，去来无定，呼吸之数难齐，无统纪、无约束，涣散不收，稍按便四散不聚。主病为溢饮、为血耗、为怔忡、为脱汗、为胻肿胕肿。产妇得之可生，妊妇得之（胎）坠，平人见之主死。《难经》说：散脉独见的危险。柳氏说：散是血气俱虚、根本脱离之脉，如果两尺见之，魂断归冥。心脉洪大而微散、肺脉浮涩而微散的，独这两种不妨。这就是散与虚不同，而虚"}, {"source": "条90｜《难经》（据《轩岐救正论·芤虚散不同》转引）", "原文": "《难经》曰，散脉独见者危。", "白话": "《难经》说：散脉单独出现的，危险。"}, {"source": "条91｜《医碥》附：伏动脉", "原文": "伏。沉极为伏，按至骨乃见，或竟有不见者。动，跳动之意，大惊多见此脉。盖惊则心胸跳突，故脉亦应之而跳突也，必带数，故上文系之数脉条下。", "白话": "伏脉：沉到极点就是伏，重按到骨才见，或者竟有不见的。动脉，是跳动的意思，大惊之后多见此脉。因为惊则心胸跳突，所以脉也相应而跳突，必兼数象，所以上文把它系在数脉条下。"}, {"source": "条92｜《医碥》各脉主病", "原文": "动。阴阳相搏，虚者则动，阳动见于寸，阴动见于尺，阴动为发热，血崩，阳动为汗出，惊，痛。阴阳相搏，气不顺，故痛。", "白话": "动脉：阴阳相搏，虚的就出现动脉；阳动见于寸，阴动见于尺。阴动主发热、血崩；阳动主汗出、惊、痛。阴阳相搏，气不顺，所以痛。"}, {"source": "条93｜《金匮翼》头痛统论", "原文": "气虚而痛者，遇劳则痛甚，其脉大。血虚而痛者，善惊惕，其脉芤。", "白话": "气虚头痛的，遇劳累则痛加重，其脉大；血虚头痛的，容易惊惕，其脉芤。"}, {"source": "条94｜《脉理求真》新增《四言脉要》", "原文": "心中惊悸，脉必代结。饮食之悸，沉伏动滑，癫乃重阴，狂乃重阳。浮洪吉象，沉急凶殃。痫宜虚缓，沉小急实。若但弦急，必死不失。惊悸非属心气亏损，即属有物阻滞，故脉必见代结。若因饮食致悸，则有沉伏动滑之象，所当审也。", "白话": "心中惊悸，脉必见代结；饮食所致之悸，脉见沉伏动滑。癫是重阴，狂是重阳。浮洪是吉象，沉急是凶殃。痫证宜见虚缓，忌沉小急实；如果只是弦急，必死无疑。惊悸不是心气亏损，就是有物阻滞，所以脉必见代结；如果因饮食致悸，则有沉伏动滑之象，这是应当审察的。"}, {"source": "条95｜《脉理求真》新著脉法心要", "原文": "芤为血虚不能濡气，其症必见发热、头昏、目眩、惊悸、怔忡、喘急、盗汗、失血、脱血。", "白话": "芤是血虚不能濡养气，其症必见发热、头昏、目眩、惊悸、怔忡、喘急、盗汗、失血、脱血。"}, {"source": "条96｜《脉象统类》浮而迟大为虚", "原文": "寸：血不荣心、怔忡、恍惚、惊悸。", "白话": "寸部（见浮迟大之虚脉）：主血不荣心、怔忡、恍惚、惊悸。"}, {"source": "条97｜《医学指要》二十八脉指要", "原文": "濡脉。体象：濡脉极软，按之不得，如水上沤，如水中帛。主病：濡主阳微，亦主卫气。寸部见濡，汗出惊悸，左关见濡，木气不升，右关见濡，土气不行，尺部见濡，温补可征。集要：濡主阴虚，为髓竭阴伤，为健忘惊悸，为腠虚自汗，为血不荣，为脾虚湿侵，为精血枯损，为真火衰残。” “芤脉。体象：芤是草名，形如青葱，浮沉俱有，中按则空中空非全无也。主病：芤主血病，营不宜实，固卫调营，血则归经。集要：芤为孤阳脱阴之候，为失", "白话": "濡脉。体象：濡脉极软，重按不得，如水上浮沤，如水中浮帛。主病：濡主阳微，也主卫气（虚）。寸部见濡，主汗出惊悸；左关见濡，主木气不升；右关见濡，主土气不行；尺部见濡，可征用温补。集要：濡主阴虚，为髓竭阴伤，为健忘惊悸，为腠理虚、自汗，为血不荣养，为脾虚湿侵，为精血枯损，为真火衰残。芤脉。体象：芤是草名，形状如青葱，浮沉俱有，中按则空——中空并非全无。主病：芤主血病，营不宜实，固卫调营，血就归经。集要：芤是孤阳脱阴的征候，为失血脱血、为气无所归、为阳无所附、为阴虚发热、为头晕目眩"}, {"source": "条98｜《医学指要》诊治六部虚实", "原文": "如左寸心脉，三按无力为虚，其外症多怔忡健忘，宜养心汤、归脾汤、茯苓补心汤。", "白话": "如左寸心脉，三次按取都无力的为虚，其外症多怔忡健忘，宜用养心汤、归脾汤、茯苓补心汤。"}, {"source": "条99｜《类证治裁》怔忡惊恐脉候卷四", "原文": "手厥阴脉甚动，则心澹澹大动。胃络名虚里，贯膈络肺，出左乳下，其动应衣，虚而有痰则动，更须臾发一阵热者是也。以上怔忡脉。", "白话": "手厥阴脉跳动剧烈，则心澹澹大动。胃之大络名叫虚里，穿过膈、络于肺，出于左乳下，其跳动应衣；虚而有痰则跳动，更有须臾间发一阵发热的，就是这种。以上是怔忡的脉候。"}, {"source": "条100｜《温热经纬》仲景外感热病篇", "原文": "方中行曰：脉结代而心动悸者，虚多实少，譬如寇欲退散，主弱不能遣发，而反自彷徨也。", "白话": "方中行说：脉结代而心动悸的，虚多实少；好比贼寇将要退散，主帅虚弱不能遣发，反而自己彷徨不安。"}, {"source": "条101｜《医门补要》脉象主病", "原文": "虚：寸虚血亏。关中腹胀。尺伤精血，骨蒸痿痹。脉虚血虚，气虚病弱，自汗怔忡，阴虚发热，惊悸伤暑，久病脉虚者死。” “弱：寸弱气虚。关中胃弱。尺主阴虚。弱主气虚，恶寒发热，筋骨萎弱，惊悸自汗，弱主筋。” “动：便泻拘挛，腹痛惊悸，女人带漏，男子遗精。 浮动盗汗，沉动发热。", "白话": "虚脉：寸虚主血亏，关中主腹胀，尺主伤精血、骨蒸痿痹。脉虚主血虚，气虚则病弱，自汗怔忡、阴虚发热、惊悸伤暑；久病脉虚的主死。弱脉：寸弱主气虚，关中主胃弱，尺主阴虚。弱主气虚、恶寒发热、筋骨萎弱、惊悸自汗；弱主筋（病）。动脉：主便泻拘挛、腹痛惊悸、女人带漏、男子遗精。浮取见动主盗汗，沉取见动主发热。"}, {"source": "条102｜《脉义简摩》郭元峰二十八脉集说", "原文": "缓而迟细者多虚寒，即诸家所言是也。为阳虚，为胃寒，为气怯，为疼痛，为晕眩，为脾弱，为痿厥，为怔忡健忘，为饮食不化，为鹜溏飧泄，为精寒肾冷，为小便频数，女子为经迟血少，为失血下血。", "白话": "脉缓而迟细的多属虚寒，即各家所说：主阳虚、主胃寒、主气怯、主疼痛、主晕眩、主脾弱、主痿厥、主怔忡健忘、主饮食不化、主鹜溏飧泄、主精寒肾冷、主小便频数；女子主经迟血少、主失血下血。"}, {"source": "条103｜《脉简补义》动脉有强弱附释惊悸", "原文": "悸者，邪气盛则形坚而力稍弱，正气衰则力弱而形亦不甚坚也。至于命火衰熄，寒水盛结之败候，其脉必形甚坚而力又甚弱，起不能高，去不能深，起伏之间有摇摆之状，如人之力弱举重者然，是元根已拔，其病必不止惊悸矣。” “心火自衰，寒水侵凌，阳气不伸，其脉累累如珠，应指无力，其病为怔忡、嘈杂之证，故曰悸也，是痰饮淫泆膻中之所致也。” “窃尝综纪临诊以来所见动脉主证：在左寸，为惊悸，为梦魇；在右寸，为咳嗽，为喘促。", "白话": "悸，邪气盛的则脉形坚而力稍弱，正气衰的则力弱而脉形也不甚坚。至于命门火衰熄、寒水盛结的败候，其脉必是形甚坚而力又甚弱，起不能高、去不能深，起伏之间有摇摆的样子，如同人力弱而举重物，这是元根已拔，其病必不止于惊悸了。心火自衰、寒水侵凌，阳气不得伸展，其脉累累如珠、应指无力，其病是怔忡、嘈杂之证，所以叫做悸；这是痰饮流溢于膻中所致。我曾综记临诊以来所见动脉主证：在左寸，主惊悸、主梦魇；在右寸，主咳嗽、主喘促。"}, {"source": "条104｜《脉简补义》诸脉补真", "原文": "何梦瑶曰：数而跳突，名曰动。大惊多见此脉。此误会动为惊之说也。须知动为惊、为痛，均要从阴阳相搏上理会。夫大惊卒恐，脉多骛暴，此喘而上争，来盛去衰，大类促脉，非动脉也，气虚神弱而常病恐惧者。", "白话": "何梦瑶说：数而跳突的，名叫动脉，大惊之后多见此脉。这是误解了“动为惊”的说法。须知动脉主惊、主痛，都要从阴阳相搏上来理会。大惊卒恐的，脉多骛暴——急迫上争，来盛去衰，很像促脉，不是动脉；（动脉见于）气虚神弱而时常病恐惧的人。"}, {"source": "条105｜《医学答问》怎样分别二十七种脉象？", "原文": "虚脉属阴，为里，为气血虚。……伤暑虚脉亦常有，怔忡虚脉不为奇，阴虚脉虚多发热，治虚以补最相宜，新病脉虚从症治，久病脉虚不用医。", "白话": "虚脉属阴，主里、主气血虚。……伤暑也常见虚脉，怔忡见虚脉不足为奇；阴虚脉虚多发热，治虚以补最为相宜；新病脉虚的随证施治，久病脉虚的就不必医治了。"}, {"source": "条106｜《医学衷中参西录》论火不归原治法", "原文": "有气海元气虚损，不能固摄下焦气化，致元阳因之浮越者。其脉尺弱寸强，浮大无根。其为病，或头目眩晕，或面红耳热，或心热怔忡，或气粗息贲。", "白话": "有因气海元气虚损，不能固摄下焦气化，致使元阳因而浮越的。其脉尺弱寸强、浮大无根。其发病，或头目眩晕，或面红耳热，或心热怔忡，或气粗息奔。"}, {"source": "条107｜《增订通俗伤寒论》滋补剂", "原文": "然必右脉浮大，左脉细数，舌绛心悸，自汗虚烦，手足躁扰，时时欲厥者，始为恰合。” “秀按：脉之动虽属心，而迫之使动者则在肺。肺主气，气主呼吸，一呼一吸，谓之一息，以促心血之跃动而发脉。病而至于心动悸，心主脉而本能动，动而至于悸，乃心筑筑然跳，按其心部动跃震手也，是为血虚。脉结代者，缓时一止为结，止有定数为代，脉行十余至一止，或七八至及五六至一止，皆有定数，是为血中之气虚。", "白话": "然而必须右脉浮大、左脉细数、舌绛、心悸、自汗、虚烦、手足躁扰、时时欲厥的，才恰好相合。秀按：脉的搏动虽然属于心，而迫使它搏动的则在肺。肺主气，气主呼吸，一呼一吸叫做一息，以推动心血的跃动而发出脉搏。病到了心动悸，心主脉而本自能动，动到了悸，就是心筑筑地跳，按其心部动跃震手，这是血虚。脉结代的：脉缓时有一止是结，止有定数是代——脉行十余至一止，或七八至、五六至一止，都有定数，这是血中之气虚。"}, {"source": "条1｜《华佗神方》卷一", "原文": "心病则胸中痛，四肢满胀，肩背臂膊皆痛，虚则多悸，惕然无眠，胸腹及腰背引痛，喜悲时常眩仆。”“又心积沉，空空然上下往来无常处，病胸满悸，腰腹中热颊赤，咽喉干燥，掌热甚则呕，春瘥冬甚，宜急疗之。", "白话": "心病就胸中痛、四肢满胀，肩背臂膊都痛；虚则多悸、恐惧不眠，胸腹和腰背牵引作痛，容易悲伤、时时眩晕仆倒。又心积沉伏，空空然上下往来没有定处；病见胸满、心悸，腰腹中热、两颊发红，咽喉干燥，掌心热，重则呕吐；春天轻、冬天重，应急治。"}, {"source": "条2｜《圣济总录》卷六十一", "原文": "论曰：胸痹之病，其脉阳微而阴弦，阳虚则知在上焦，阴弦故令胸痹心痛。古方用理中汤，取缓其中气则可也。然背者胸之府，或筑、或悸、或渴、或腹痛、或寒、或腹满，其候不一，治当随宜加损也。", "白话": "论曰：胸痹这个病，其脉阳微而阴弦；阳虚就知道病在上焦，阴弦所以使人胸痹心痛。古方用理中汤，取其缓补中气是可以的。然而背是胸的府，或筑动、或悸、或渴、或腹痛、或寒、或腹满，其证候不一，治疗当随证加减。"}, {"source": "条3｜《注解伤寒论》卷三", "原文": "发汗后，其人脐下悸者，欲作奔豚，茯苓桂枝甘草大枣汤主之。汗者，心之液。发汗后，脐下悸者，心气虚而肾气发动也。肾之积，名曰奔豚，发则从少腹上至心下，为肾气逆欲上凌心。今脐下悸为肾气发动，故云欲作奔豚。", "白话": "发汗以后，病人脐下悸的，是将要发作奔豚，用茯苓桂枝甘草大枣汤主治。汗是心的液体。发汗后脐下悸，是心气虚而肾气发动。肾的积名叫奔豚；发作时从少腹上冲到心下，是肾气逆而想上凌心。现在脐下悸是肾气发动，所以说将要发作奔豚。"}, {"source": "条4｜《济阳纲目》卷五十四", "原文": "又有每卧觉神离体，惊悸多魇，通夕无寐，此是肝经受邪，非心病也。", "白话": "又有每到躺下就觉得神魂离体、惊悸多梦魇、整夜不睡的，这是肝经受邪，不是心病。"}, {"source": "条5｜《绛雪丹书·产后下卷》", "原文": "心痛，即胃脘痛，以胃脘在心之下，因伤寒气及冷物而作痛，因痛起于心，俗呼为心痛。夫心为君主之官，主气行血，统驭脏腑血气，血盛则泰然安宁，血不足则惕然惊悸，岂可痛乎？。", "白话": "心痛，就是胃脘痛；因为胃脘在心的下面，因伤寒之气以及冷物而作痛，因痛起于心的部位，俗称为心痛。心是君主之官，主气行血，统摄脏腑血气；血盛就泰然安宁，血不足就恐惧惊悸——心哪里会痛呢？"}, {"source": "条6｜《症因脉治》卷二", "原文": "心虚劳伤。心虚劳伤之症，惊悸恍惚，神志不定，心痛咽肿，喉中介介如梗，实则毛焦发落，唇裂舌赤，烦热咳逆，此心劳之症也。", "白话": "心虚劳伤。心虚劳伤的症候是：惊悸恍惚、神志不定、心痛咽肿、喉中介介好像有东西梗塞；实则毛发焦枯脱落、嘴唇干裂舌红、烦热咳逆——这就是心劳的病。"}, {"source": "条7｜《医碥》卷二", "原文": "脐下悸，水停心下，则心下悸而痞塞。若停脐下，则脐下悸也。", "白话": "脐下悸（与心下悸相辨）：水停心下，就心下悸而痞塞；如果水停脐下，就脐下悸。"}, {"source": "条8｜《金匮悬解》卷九", "原文": "大凡虚劳内伤之家，必有惊悸、奔豚之病。奔豚或有时作止，而惊悸则无刻不然，其时常惊悸而奔豚不作者，己土未败，而风木不能遽发也。然悸动未息，则奔豚虽不发作，而发作之根，未尝不在。当其小腹硬块，岁月增长，即不必发作，而祸根已伏，不可不察也。", "白话": "大凡虚劳内伤的病人，必有惊悸、奔豚之病。奔豚或有发作和停止的时候，而惊悸则无时不然；那时时惊悸而奔豚不发作的，是己土未败，风木不能骤然发作。然而悸动不息，则奔豚虽不发作，而发作的根未尝不在。当其小腹硬块一年年增大，即使不发作，祸根已经潜伏，不可不细察。"}, {"source": "条9｜《一见能医》卷六", "原文": "心痛，即胃脘痛也。古云：心痛有九种。……悸痛者，其痛不甚，但觉胸中隐隐作痛，此因惊气乘心也，治用二陈汤加茯神、远志、黄连、枳实、当归。", "白话": "心痛，就是胃脘痛。古话说心痛有九种……悸痛，痛得不厉害，只是觉得胸中隐隐作痛，这是惊气乘心所致；治疗用二陈汤加茯神、远志、黄连、枳实、当归。"}, {"source": "条10｜《类证治裁》卷四", "原文": "卑惵症，与怔忡类，其症胸中痞塞，不能饮食，心常有歉，爱居暗室，见人则惊避无地，病至数年，不得以癫症治之。", "白话": "卑惵之症与怔忡相类似，其症是胸中痞塞、不能饮食、心中常有缺然不足之感、喜欢住在暗室、见人就惊慌躲避无地可藏；病延数年，不可按癫证来治疗。"}, {"source": "条11｜《先哲医话》卷下", "原文": "若嗳气吞酸，心下痛者，宜四味枳壳散。盖此证郁热支冲脉，水饮不能为之流通，因心下悸。若认为留饮治之，治之反生害，但解其热则饮自去也。", "白话": "如果嗳气吞酸、心下痛的，宜用四味枳壳散。此证是郁热支撑冲脉，水饮不能流通，因而心下悸。如果当作留饮来治疗，反而产生危害；只需解其热，水饮自然就去了。"}, {"source": "条12｜《医学答问》卷一", "原文": "胃脘痛者，心悸怔忡喜按，宜归脾汤或四君子，加柴胡、木香。", "白话": "胃脘痛而见心悸怔忡、喜按的，宜用归脾汤或四君子汤，加柴胡、木香。"}, {"source": "条1｜《黄帝内经素问》阳明脉解篇", "原文": "黄帝问曰：足阳明之脉病，恶人与火，闻木音则惕然而惊，钟鼓不为动，闻木音而惊何也？愿闻其故。岐伯对曰：阳明者胃脉也，胃者土也，故闻木音而惊者，土恶木也。帝曰：善。", "白话": "黄帝问：足阳明脉发病，厌恶人与火，听到木音就惕然而惊，听到钟鼓之声却不为所动，听到木音就惊是为什么？希望听听其中缘故。岐伯回答：阳明是胃脉，胃属土，所以听到木音而惊，是土恶木的缘故。黄帝说：好。"}, {"source": "条2｜《黄帝内经素问》阴阳别论篇", "原文": "一阳发病，少气善咳善泄；其传为心掣，其传为隔。", "白话": "一阳（少阳）发病，出现少气、易咳、易泄泻；其传变则为心掣，或传变为隔塞不通。"}, {"source": "条3｜《普济方》心脏门", "原文": "心虚之状，气血衰少，面黄烦热，多恐悸不乐，心腹痛难以言，时出清涎，心膈胀满，善忘多惊，梦寝不宁，精神恍惚，皆手少阴经虚寒所致。", "白话": "心虚的样子，是气血衰少，面黄烦热，多恐惧惊悸不乐，心腹痛难以名状，时时流出清涎，心膈胀满，健忘多惊，睡眠不宁，精神恍惚；都是手少阴经虚寒所致。"}, {"source": "条4｜《医镜》卷二", "原文": "脾胃一伤，则五脏皆无生气，由是为腰痛，为烦恼，为膀胱胀满，而肾始病矣；为恍惚，为怔忡，为烦躁，而心始病矣。", "白话": "脾胃一伤，五脏都失去生化之气，于是出现腰痛、烦恼、膀胱胀满，肾就开始生病；出现恍惚、怔忡、烦躁，心就开始生病。"}, {"source": "条5｜《古今名医汇粹》卷一", "原文": "心藏神而主血于脾，实为母子。脾乏膏腴，因夺母气以为食，虚处遂并移于母。健忘惊悸等证，实由脾虚乏津乏液之故。", "白话": "心藏神而主血，与脾实为母子（火生土）。脾缺乏膏腴之养，就夺取母气以为食，虚处于是并移到母（心）上。健忘惊悸等证，实在是脾虚乏津液的缘故。"}, {"source": "条6｜《金匮要略广注》惊悸吐衄下血胸满瘀血病脉证治第十六", "原文": "悸者，动也，有阳气内衰，心下空虚，火气内动，而为悸者；有水停心下，心属火恶水，神不自安，而为悸者；有汗吐下后，正气内虚而悸者；有荣卫涸流，脉结代而悸者，此俱属伤寒而论也。今总以意断之，肝病发惊骇，是惊属乎肝也，心动则为悸，是悸属乎心也。心主血，属君火，肝藏血，属相火，凡诸见血，皆火迫妄行，故吐衄、下血、瘀血与惊悸，统汇为一论乎。", "白话": "悸就是动。有因阳气内衰、心下空虚、火气内动而为悸的；有因水停心下、心属火而恶水、神不自安而为悸的；有因汗吐下之后正气内虚而悸的；有因营卫枯涸、脉结代而悸的；这些都是就伤寒立论。现在总合起来判断：肝病发惊骇，是惊属肝；心动则为悸，是悸属心。心主血属君火，肝藏血属相火，凡各种见血之证，都是火迫血妄行，所以吐血鼻衄、下血、瘀血与惊悸，汇合为一篇来讨论。"}, {"source": "条7｜《傅青主男科》虚劳门", "原文": "肾，水脏也。心，火脏也。是心、肾二经为仇敌矣。似不可牵连而合治之也，不知心、肾相克而实相须。肾无心之火则水寒，心无肾之水则火炽，心必得肾水以滋润，肾必得心火以温暖。如人惊惕不安，梦遗精泄，皆心肾不交之故。人以惊惕为心之病，我以为肾之病。", "白话": "肾是水脏，心是火脏，这样心肾二经就像仇敌了。似乎不可牵连合治；却不知心肾虽相克而实相互资生。肾没有心火则水寒，心没有肾水则火炽；心必得肾水来滋润，肾必得心火来温暖。如果有人惊惕不安、梦遗精泄，都是心肾不交的缘故。人们以为惊惕是心的病，我认为是肾的病。"}, {"source": "条8｜《石室秘录》内伤门", "原文": "怔忡之症，扰扰不宁，心神恍惚，惊悸不已，此肝肾之虚，而心气之弱也，若作痰治，往往杀人。盖肾虚以致心气不交，心虚以致肝气益耗，不治虚而反攻痰，安得不速死乎。", "白话": "怔忡之症，扰扰不宁，心神恍惚，惊悸不止；这是肝肾亏虚而心气虚弱，如果当作痰来治疗，往往杀人。因为肾虚以致心气不交，心虚以致肝气更耗；不治虚反而攻痰，怎能不速死呢。"}, {"source": "条9｜《辨证奇闻》怔忡", "原文": "怔忡，日轻夜重，欲思熟睡不可得，人谓心虚极，谁知肾气乏乎。人夜卧，心气下降肾宫，肾不虚则开门延入，彼此欢然。惟唯肾太耗，家贫客至，束手无策，客见如此，自不久留，徘徊岐路，托足无门，傍彷徨四顾，又将何如。法大补肾精，肾精充足，自然客至相投，开宴畅饮。", "白话": "怔忡，白天轻夜里重，想熟睡却不可得；人们说是心虚到了极点，谁知是肾气匮乏。人夜卧时心气下降到肾宫，肾不虚就开门迎入，彼此欢洽。只是肾精太耗，好比家贫客至，束手无策；客见如此，自然不久留，徘徊在岔路上，无处托足，彷徨四顾，又能怎样呢。治法当大补肾精，肾精充足，自然客至相投，开宴畅饮。"}, {"source": "条10｜《不居集》怔忡惊悸健忘善怒善恐不眠", "原文": "心者，身之主，神之舍也。心血不足，多为痰火扰动，心神不宁，多有惊悸怔忡诸症。惟唯虚损之人，阴亏于下，元海无根，气浮于上，撼振胸臆，是心不能下交于肾，肾不能上交于心，则筑筑心动，惕惕恐畏，为怔忡惊悸者有之。", "白话": "心是身体的主宰，神的居舍。心血不足，多被痰火扰动，心神不宁，多有惊悸怔忡诸症。只是虚损的人，阴亏于下，元海无根，气浮于上，撼振胸臆；这是心不能下交于肾，肾不能上交于心，于是筑筑心动、惕惕恐畏，成为怔忡惊悸的，是有的。"}, {"source": "条11｜《不居集》怔忡惊悸健忘善怒善恐不眠", "原文": "故虚烦惊悸者，中正之官以熇蒸而不宁也。", "白话": "所以虚烦惊悸的，是中正之官（胆）因火热熇蒸而不安宁。"}, {"source": "条12｜《医碥》卷一", "原文": "肾阴太盛，寒气上冲，心为之悸；或肾寒甚，而逼其龙火上乘，心为之烦，皆肾水克心火也。若饮水过多，停蓄不行，心火被逼不安而悸者，与肾无涉。", "白话": "肾阴太盛，寒气上冲，心因此而悸；或肾寒太甚，逼迫龙火上乘，心因此而烦；这都是肾水克心火。如果饮水过多、停蓄不行，心火被逼不安而悸的，与肾无关。"}, {"source": "条13｜《罗氏会约医镜》卷十", "原文": "惊悸者，肝胆怯也。", "白话": "惊悸，是肝胆怯弱。"}, {"source": "条14｜《金匮启钥》卷五", "原文": "至于惊悸恍惚虚烦等证，浅见者以为上焦病证，不知病实发根于下原。何也，人生真水一竭，则火失所附，无不随之上炎，即心脾二经之火，亦无不相引而动。是以惊烦等证，纷纷而作，究之水竭，则火浮泛，有不归位而亏者矣。火亏则不能摄水，兼失生土之权，土败水泛，而心脾心烦等病起矣。", "白话": "至于惊悸、恍惚、虚烦等证，见识浅的以为是上焦病证，不知病根实在下焦。为什么？人身真水一竭，火就失去依附，无不随之上炎，即使心脾二经之火，也无不相引而动。所以惊烦等证纷纷发作。推究起来，水竭则火浮泛，火浮泛不归本位就会亏；火亏则不能摄水，同时失去生土的职权，土败水泛，心脾心烦等病就起来了。"}, {"source": "条15｜《素灵微蕴》卷二", "原文": "至于内伤虚劳，惊悸不寐，俱缘水寒土湿，神魂不藏，无相火上旺，而宜清润者。即其千百之中偶而有之，而究其脾肾，终是湿寒。", "白话": "至于内伤虚劳、惊悸不寐，都因水寒土湿，神魂不能藏守；其中并没有相火上旺而适宜清润的，即使千百个里偶然有一个，推究其脾肾，终究是湿寒。"}, {"source": "条16｜《四圣悬枢》痘病解第三", "原文": "营血遏郁，木气不畅，肝木不升，则振撼而为悸，胆木勿降，则悬虚而为惊也。", "白话": "营血遏郁，木气不畅；肝木不升，就振撼而为悸；胆木不降，就悬虚而为惊。"}, {"source": "条17｜《医家心法》怔忡", "原文": "怔忡证，虽缘心血不足，然亦有胃络不能上通者，有脾脉不能入心者，有宗气虚而虚里穴动者，有水气凌心者，有奔豚上乘者。治法略同，惟唯水气与奔豚有别耳！", "白话": "怔忡证虽然由于心血不足，然而也有胃络不能上通的，有脾脉不能入心的，有宗气虚而虚里穴动的，有水气凌心的，有奔豚上乘的。治法大略相同，只有水气与奔豚有区别罢了。"}, {"source": "条18｜《知医必辨》论肝气", "原文": "肝之大脉，布于两胁，而胃之大络，亦在两胁也。又成上而冲心，致心跳不安。", "白话": "肝的大脉布于两胁，而胃的大络也在两胁。（肝气）又向上冲心，致使心跳不安。"}, {"source": "条19｜《医学摘粹》虚证类", "原文": "神藏于心，而交于肾，则神清而不摇。若神不交精，乃生惊悸。", "白话": "神藏于心而下交于肾，则神清而不摇动；如果神不交于精（肾精），就生惊悸。"}, {"source": "条20｜《黄帝内经》（评述总说）", "原文": "心悸的病因病机在《黄帝内经》中已有所阐发，经后世不断演变、丰富，发展至今，已然十分翔实。心悸的好发生多因素体虚弱、饮食劳倦、情志内伤、感受外邪、失治误治等引起，以致气血阴阳亏损，心神失养，或痰、饮、火、瘀等阻滞心脉，扰乱心神，发为心悸。心悸的病因主要有外邪侵袭、情志内伤、饮食失节、劳欲过度、久病失养、失治误治六个方面。", "白话": "心悸的病因病机在《黄帝内经》中已有阐发，经后世不断演变、丰富，发展到现在已经十分翔实。心悸的发生多由素体虚弱、饮食劳倦、情志内伤、感受外邪、失治误治等引起，以致气血阴阳亏损、心神失养，或痰、饮、火、瘀等阻滞心脉、扰乱心神，发为心悸。心悸的病因主要有外邪侵袭、情志内伤、饮食失节、劳欲过度、久病失养、失治误治六个方面。"}, {"source": "条21｜《黄帝内经》（外邪致悸）", "原文": "早在《黄帝内经》中已有关于感受外邪而致心悸的表述。", "白话": "早在《黄帝内经》中已有感受外邪而导致心悸的表述。"}, {"source": "条22｜《黄帝内经·素问》痹论篇", "原文": "《黄帝内经·素问·痹论篇》》曰：“风寒湿三气杂至，合而为痹也……心痹者，脉不通，烦则心下鼓。”该篇即认为因感受风、寒、湿邪，内克于心，痹阻心脉，日久则出现“心下鼓”的症状，“心下鼓”即为对心悸症状的一种描述。", "白话": "《黄帝内经·素问·痹论篇》说：“风寒湿三气交错而至，合起来成为痹……心痹，是血脉不通，烦躁则心下鼓动。”该篇认为：因感受风、寒、湿邪，向内克制于心，痹阻心脉，日久则出现“心下鼓”的症状；“心下鼓”就是对心悸症状的一种描述。"}, {"source": "条23｜《诸病源候论》风病诸候", "原文": "《诸病源候论·风病诸候》曰：“风惊悸者，由体虚，心气不足，心之腑为风邪所乘；或恐惧忧迫，令心气虚，亦受于风邪。风邪搏于心，则惊不自安。惊不已，则悸动不定。其状，目精不转，而不能呼。”则是由心气不足，风邪乘之，气血失和，心神受扰，发为惊悸。", "白话": "《诸病源候论·风病诸候》说：“风惊悸，是由于体虚、心气不足，心之腑为风邪所乘；或恐惧忧迫使心气虚，也易受风邪。风邪搏结于心，则惊而不自安；惊不止，则悸动不定。其症状是目睛不转，而不能呼。”这是由心气不足、风邪乘袭，气血失和，心神受扰，发为惊悸。"}, {"source": "条24｜《济生方》惊悸怔忡健忘门", "原文": "又如《济生方·惊悸怔忡健忘门》曰：“又有冒风寒暑湿，闭塞诸经，令人怔忡。”指出外感邪气，猝然所犯，易引起人体经脉气血壅塞不畅，闭塞脉络，从而使心脉受其影响，痹阻不畅，而出现心悸的情况。可见，外感邪气是致心悸的病因之一。", "白话": "又如《济生方·惊悸怔忡健忘门》说：“又有触冒风寒暑湿，闭塞各经，使人怔忡。”指出外感邪气猝然侵犯，容易引起人体经脉气血壅塞不畅、闭塞脉络，从而使心脉受影响、痹阻不畅而出现心悸。可见外感邪气是心悸的病因之一。"}, {"source": "条25｜《黄帝内经素问》举痛论篇", "原文": "《黄帝内经素问·举痛论篇》》曰：“惊则心无所倚，神无所归，虑无所定，故气乱矣。”即指出因受惊而心神受扰，使得气乱，而致惊悸。此外，也有因忧思过度，心气郁结，暗耗心血，失养致悸；或因五志过极化火，上扰心神致悸；或因情志不遂，气机郁闭，不复升降致悸。", "白话": "《黄帝内经素问·举痛论篇》说：“惊则心无所倚靠，神无所归宿，虑无所定处，所以气乱了。”指出因受惊而心神受扰、气乱而致惊悸。此外，也有因忧思过度、心气郁结、暗耗心血、心失所养而致悸的；或因五志过极化火、上扰心神而致悸的；或因情志不遂、气机郁闭、不能升降而致悸的。"}, {"source": "条26｜《严氏济生方》惊悸怔忡健忘门", "原文": "如《严氏济生方·惊悸怔忡健忘门》曰：“夫怔忡者，此心血不足也。盖心主于血，血乃心之主，心乃形之君，血富则心君自安矣。多因汲汲富贵，戚戚贫贱，又思所爱，触事不意，真血虚耗，心帝失辅，渐成怔忡。怔忡不已，变生诸证，舌强恍惚，善忧悲，少颜色，皆心病之候。", "白话": "如《严氏济生方·惊悸怔忡健忘门》说：“怔忡是心血不足。心主血，血乃心之主，心乃形之君，血充盛则心君自然安宁。多因急切追求富贵、忧愁贫贱，又思念所爱之人、遇事不遂，真血虚耗，心帝失去辅养，渐渐变成怔忡。怔忡不止，变生诸证：舌强恍惚、易忧悲、面色少华，都是心病的证候。"}, {"source": "条27｜《难经》（《严氏济生方》引）", "原文": "《难经》云：损其心者，益其荣，法当5专补真血，真血若富，心帝有辅，无不愈者矣。”此即指出情志不遂，过度思虑、忧悲，使得心血虚耗，从而出现心悸等系列病症表现。", "白话": "《难经》说：心受损伤的，要补益其营血，治法当专补真血；真血充盛，心帝有辅，没有不痊愈的。”这即指出情志不遂、过度思虑忧悲，使心血虚耗，从而出现心悸等一系列病症表现。"}, {"source": "条28｜《养生四要》寡欲第一", "原文": "如《养生四要·寡欲第一》指出：“酒客病酒，酒停不散，清则成饮，浊则成痰。入于肺则为喘，为咳。入于心则为心痛，为怔忡，为噫。”亦有因恣食生冷、寒湿之品，酿生寒湿，损伤胃气，导致心失所养而致悸；或因心为阳脏，寒湿为阴邪，重浊粘黏滞、阻塞气机，若寒湿之邪蒙蔽心神，则君火失其明，而致心悸难安。", "白话": "如《养生四要·寡欲第一》指出：“酒客被酒所伤，酒停不散，清的成为饮，浊的成为痰。入于肺则为喘、为咳；入于心则为心痛、为怔忡、为噫。”也有因恣食生冷寒湿之品，酿生寒湿，损伤胃气，导致心失所养而致悸；或因心为阳脏，寒湿为阴邪，重浊黏滞、阻塞气机，若寒湿之邪蒙蔽心神，则君火失去光明，而致心悸难安。"}, {"source": "条29｜《肘后备急方》治虚损羸瘦不堪劳动方第三十三", "原文": "如《肘后备急方·治虚损羸瘦不堪劳动方第三十三》曰：“凡男女因积劳虚损，或大病后不复，若四体沉滞，骨肉疼酸。吸吸少气，行动喘惙，或小腹拘急，腰背强痛，心中虚悸，咽干唇燥，面体少色，或饮食无味，阴阳废弱，悲忧惨戚，多卧少起。", "白话": "如《肘后备急方·治虚损羸瘦不堪劳动方第三十三》说：“凡男女因积劳虚损，或大病之后不得恢复，出现四肢沉重滞着、骨肉疼酸，呼吸短气，行动就喘促，或小腹拘急、腰背强痛，心中虚悸，咽干唇燥，面体少色，或饮食无味，阴阳衰弱，悲忧惨戚，多卧少起。”"}, {"source": "条30｜《古今医统大全》痨瘵门", "原文": "《古今医统大全·痨瘵门》曰：“劳于心者，则神耗而血衰，惊悸之疾亦因之而作矣。", "白话": "《古今医统大全·痨瘵门》说：“劳心的人，神气耗伤而血衰，惊悸之疾也因此而发作。”"}, {"source": "条31｜《内科通论》虚劳统论", "原文": "《内科通论· 虚劳统论》曰：“心劳者；恍惚惊悸，少颜色。热则烦心、口干、溺涩；寒则内栗、梦多恐怖。”若房劳过度，伤精而致下元亏虚，精血亏虚而致心失所养，也会导致心悸发生。", "白话": "《内科通论·虚劳统论》说：“心劳的人，恍惚惊悸，面色少华；热则烦心、口干、小便涩；寒则体内寒栗、梦多恐怖。”如果房劳过度，伤精而致下元亏虚，精血亏虚而致心失所养，也会导致心悸发生。"}, {"source": "条32｜《巢氏病源补养宣导法》（引《养生方》）", "原文": "如《巢氏病源补养宣导法》言：“《养生方》云：精藏于玉房，交接太数，则失精。失精者，令人怅怅，心常惊悸。", "白话": "如《巢氏病源补养宣导法》说：“《养生方》说：精藏在玉房，房事太频繁就会失精；失精使人怅怅不乐，心中常常惊悸。”"}, {"source": "条33｜《养生方》（据《巢氏病源补养宣导法》转引）", "原文": "《养生方》云：精藏于玉房，交接太数，则失精。失精者，令人怅怅，心常惊悸。”肾藏精，精作为人体生命活动中重要的物质，房劳过度，频繁失精，造成精气流失，使得肾精亏虚，因而易出现心肾不交的情况，使得心失所养，心火上炎，而见惊悸。", "白话": "《养生方》说：精藏在玉房，房事太频繁就会失精；失精使人怅怅不乐，心中常常惊悸。”肾藏精，精是人体生命活动中的重要物质；房劳过度、频繁失精，造成精气流失，使肾精亏虚，因而容易出现心肾不交的情况，心失所养，心火上炎，而见惊悸。"}, {"source": "条34｜《黄帝内经素问》五过论篇", "原文": "《黄帝内经素问·素问·五过论篇》》指出：“身体日减，气虚无精，病深无气，洒洒然时惊，病深者，以其外耗于卫，内夺于荣。”此则说明久病之人，身体亏虚，营卫亏损，心失所养，而见惊悸等表现。", "白话": "《黄帝内经素问·五过论篇》指出：“身体一天天消瘦，气虚而无精，病深则无气，洒洒然时时发惊；病之所以深重，是因为在外耗伤了卫气，在内夺劫了营血。”这说明久病之人身体亏虚、营卫亏损，心失所养，而见惊悸等表现。"}, {"source": "条35｜《医门棒喝》虚损论", "原文": "后世《医门棒喝·虚损论》亦指出：“夫虚损而至怔忡者，先因肾亏，劳心耗血。水不济火，虚火上冲心神动惕；血不养肝，肝风上冒而头眩。其心肾之脉，必动数、虚大，肝脉急强，乃为木火偏胜，阴血虚损之象。”故虚损日久，失于调护，则致气血虚衰，脏腑失养，见于心则可因血不养心，或水不济火、虚火上炎，从而出现惊悸等症状。", "白话": "后世《医门棒喝·虚损论》也指出：“虚损发展到怔忡的，先因肾亏、劳心耗血。水不济火，虚火上冲而心神动惕；血不养肝，肝风上冒而头眩。其心肾之脉必动数、虚大，肝脉急强，这是木火偏胜、阴血虚损之象。”所以虚损日久、失于调护，就致气血虚衰、脏腑失养；见于心的，可因血不养心，或水不济火、虚火上炎，从而出现惊悸等症状。"}, {"source": "条36｜《伤寒论》（汗吐下误治致悸）", "原文": "多因医者治法不当，或病延日久，使得病邪有所传变，而致心悸。《伤寒论》中则指出了因汗法、吐法、下法使用不当而使正气受扰，产生心悸。", "白话": "多因医者治法不当，或病延日久，使病邪发生传变，而致心悸。《伤寒论》指出了因汗法、吐法、下法使用不当，使正气受扰而产生心悸。"}, {"source": "条37｜《伤寒论》辨太阳病脉证并治中（桂枝甘草汤）", "原文": "如《伤寒论·辨太阳病脉证并治中》提到：“发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之。", "白话": "如《伤寒论·辨太阳病脉证并治中》提到：“发汗过多，病人两手交叉按护于心胸，心下悸动、想要按压的，用桂枝甘草汤主治。”"}, {"source": "条38｜《伤寒论》辨太阳病脉证并治中（真武汤）", "原文": "另外，《伤寒论·辨太阳病脉证并治中》尚还提到：“太阳病发汗，汗出不解，其人仍发热，心下悸，头眩，身瞤动，振振欲擗地者，真武汤主之。”由此可见，疾病诊治过程中出现失治误治，则易损伤正气，使邪气羁留、深入，侵扰脏腑经络，若邪气犯客于心，侵扰心神，则可见心悸。", "白话": "另外，《伤寒论·辨太阳病脉证并治中》还提到：“太阳病发汗，汗出而病不解，病人仍然发热，心下悸，头眩，身体瞤动，颤颤巍巍想要倒地的，用真武汤主治。”由此可见，诊治过程中出现失治误治，就容易损伤正气，使邪气羁留深入，侵扰脏腑经络；若邪气侵犯于心、侵扰心神，则可见心悸。"}, {"source": "条39｜《医学衷中参西录》论心病治法", "原文": "心悸病机总的来说，不外乎气、血、阴、阳的偏盛偏衰，以及水饮、痰湿、火热等邪气扰乱心神，使得心失所养、心神不宁。其病位在心，与肺、脾、肝、肾等脏腑有着密切关系。如《医学衷中参西录·论心病治法》指出：“心之本体，原长发动以运行血脉，然无病之人初不觉其动也，惟唯患怔忡者则时觉心中跳动不安。其脉微弱无力者，当系心气虚而莫支。", "白话": "心悸病机总的来说，不外乎气血阴阳的偏盛偏衰，以及水饮、痰湿、火热等邪气扰乱心神，使心失所养、心神不宁。病位在心，与肺、脾、肝、肾等脏腑关系密切。如《医学衷中参西录·论心病治法》指出：“心的本体，本来就时常发动以运行血脉，但无病的人起初不觉得它动；只有患怔忡的人时时觉心中跳动不安。其脉微弱无力的，当是心气虚而不能支撑。”"}, {"source": "条40｜《仁斋直指方》惊悸", "原文": "如《仁斋直指方·惊悸》指出：“人之所主者心，心之所养者血，心血一虚，神气不守，此惊悸之所肇端也。", "白话": "如《仁斋直指方·惊悸》指出：“人的主宰是心，心所奉养的是血；心血一虚，神气不守，这就是惊悸的开端。”"}, {"source": "条41｜《奇效良方》卷四十六", "原文": "《奇效良方》卷四十六指出：“或逆气动躁者，由水衰火旺，而犹火之动也，故心胸躁动，谓之怔忪，此心血不足也。盖心主血，血乃心之主，心乃形之主，血富则心主自安矣。多因汲汲富贵，戚戚贫贱，又思所爱触事，不意真血虚耗，心主失辅，渐成怔忡。”认为心主血，心血亏虚，或由情志偏胜引起，或由生化不足引起，导致心失所养，而见心悸怔忡。", "白话": "《奇效良方》卷四十六指出：“有的逆气躁动，是由于水衰火旺，犹如火之躁动，所以心胸躁动，叫做怔忪，这是心血不足。心主血，血乃心之主，心乃形之主，血充盛则心主自然安宁。多因急切追求富贵、忧愁贫贱，又思念所爱之人、遇事不遂，不料真血虚耗，心主失去辅养，渐渐变成怔忡。”认为心主血，心血亏虚，或由情志偏胜引起，或由生化不足引起，导致心失所养，而见心悸怔忡。"}, {"source": "条42｜《类经》脉分四时无胃曰死", "原文": "《类经·脉分四时无胃曰死》曰：“虚里跳动，最为虚损病本，故凡患阴虚劳怯，则心下多有跳动，及为惊悸慌张者，是即此证，人止知其心跳而不知为虚里之动也。”此则指明因为阴虚劳损，心脏失其涵养，而使心跳加速，以致惊悸。", "白话": "《类经·脉分四时无胃曰死》说：“虚里跳动最是虚损病的根本，所以凡患阴虚劳怯的，心下多有跳动，以至惊悸慌张的，就是此证；人们只知道心跳，而不知道是虚里在动。”这指明因为阴虚劳损，心脏失其涵养，而使心跳加速，以致惊悸。"}, {"source": "条43｜《医原》内伤大要论", "原文": "《医原·内伤大要论》则进一步阐明了阴虚致悸的病机及症状。“若劳心者伤神，又重于劳力伤气者也。或卷牍烦剧，或百计图谋，心神无片刻之静，心体无安养之时，由是君火内沸，销烁真阴，不但伤神，并能伤精，阳不依阴，自阴不潜阳，阴虚必生内热，内热必化内燥，脉多细涩，甚而数涩，或浮弦搏指，皆阴虚化刚之象。见证多惊悸、怔忡、心热、盗汗、虚烦不寐，甚则君火引动相火，伤及真阴，干咳、吐血、遗滑、淋浊、骨蒸潮热，诸证丛生", "白话": "《医原·内伤大要论》进一步阐明阴虚致悸的病机及症状。“劳心的人伤神，又比劳力伤气为重。或文卷繁剧，或千方百计谋虑，心神没有片刻安静，心体没有安养的时候，于是君火在内沸腾，销烁真阴；不但伤神，并且伤精。阳不依阴，阴不潜阳，阴虚必生内热，内热必化内燥，脉多细涩，甚至数涩，或浮弦搏指，都是阴虚化刚之象。见证多惊悸、怔忡、心热、盗汗、虚烦不寐；严重则君火引动相火，伤及真阴，出现干咳、吐血、遗精滑泄、淋浊、骨蒸潮热，诸证丛生。”该段说明：劳心劳力过多、思虑过度，则心神难安，君火偏亢，耗"}, {"source": "条44｜《备急千金要方》卷十三", "原文": "阳虚多由素体禀赋不足、久病失养等因素造成。如《备急千金要方》卷十三指出：“病苦悸恐不乐，心腹痛难以言，心如寒，恍惚，名曰心虚寒也。”此则因心主君火，为阳中之阳，心阳虚，则君火失于温煦，心神失养，而心悸不安；同时，阳虚易致阴寒凝滞于心脉，虚寒内阻心脉而产生心悸。", "白话": "阳虚多由素体禀赋不足、久病失养等因素造成。如《备急千金要方》卷十三指出：“病人苦于悸恐不乐，心腹痛难以名状，心中觉寒，恍惚，名叫心虚寒。”这是因为心主君火，为阳中之阳；心阳虚，则君火失于温煦，心神失养而心悸不安；同时阳虚易致阴寒凝滞于心脉，虚寒内阻心脉而产生心悸。"}, {"source": "条45｜《类经》五过四德", "原文": "《类经·五过四德》则进行了细致描述：“及其病深，则真气消索，故曰无气。无气则阳虚，故洒然畏寒也。阳虚则神不足，故心怯而惊也。”从上可见，阳气亏虚，则心阳不足，心神失于温煦，而易致惊悸恍惚。", "白话": "《类经·五过四德》作了细致描述：“等到病深，真气消散，所以说无气；无气则阳虚，所以洒然畏寒；阳虚则神不足，所以心怯而惊。”从上可见，阳气亏虚则心阳不足，心神失于温煦，容易导致惊悸恍惚。"}, {"source": "条46｜《黄帝内经》（十一脏皆取于胆）", "原文": "心为君主之官，为君火，胆属少阳、，主司枢机，内寄相火。《黄帝内经》认为“十一脏皆取于胆”，因此当心胆气虚时，心失其养而致心悸，且心胆气虚易致痰涎阻滞扰心，心受其扰亦会悸动不安。", "白话": "心是君主之官，属君火；胆属少阳，主司枢机，内寄相火。《黄帝内经》认为“十一脏皆取于胆”，所以当心胆气虚时，心失所养而致心悸；且心胆气虚容易导致痰涎阻滞扰心，心受其扰也会悸动不安。"}, {"source": "条47｜《济生方》惊悸", "原文": "如《济生方·惊悸》指出：“若惊悸者，心胆虚怯所致也。且心者君主之官，神明出焉；胆者中正之官，决断出焉。心气安逸，胆气不怯，决断思虑得其所矣。或因事有所大惊，或闻虚响，或见异相，登高涉险，惊忤心神，气与涎郁，遂使惊悸。惊悸不已，变生诸证，或短气悸乏，体倦自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安，皆心胆虚怯之候也。”由此可见，心胆气虚，则君火不明、心神失养，而易致心悸。", "白话": "如《济生方·惊悸》指出：“惊悸是心胆虚怯所致。心是君主之官，神明由此而出；胆是中正之官，决断由此而出。心气安逸，胆气不怯，决断思虑就各得其所。或因事受到大惊，或听到虚响，或见到怪异之相，登高涉险，惊扰触犯心神，气与痰涎郁滞，于是发生惊悸。惊悸不止，变生诸证：或短气悸乏、体倦自汗、四肢浮肿、饮食无味、心虚烦闷、坐卧不安，都是心胆虚怯的证候。”由此可见，心胆气虚则君火不明、心神失养，容易导致心悸。"}, {"source": "条48｜《金匮要略》痰饮咳嗽病脉证并治", "原文": "水饮为阴邪，心为阳脏，若水饮上犯，乘于心阳，则可致心阳不足，心失温煦，心悸不安。此外，心神亦因阴邪来犯而受扰，从而出现心悸。如《金匮要略·痰饮咳嗽病脉证并治》曰：“夫病人饮水多，必暴喘满。凡食少饮多，水停心下。甚者则悸，微者短气。”该段论述则表明若饮水过多，难以运化，积蓄心下，可致水饮上犯心阳，而出现心悸、短气的表现。", "白话": "水饮为阴邪，心为阳脏；若水饮上犯、乘袭心阳，就可致心阳不足、心失温煦而心悸不安。此外，心神也因阴邪来犯而受扰，从而出现心悸。如《金匮要略·痰饮咳嗽病脉证并治》说：“病人饮水多，必突然喘满。凡食少而饮水多，水停心下；重的则悸，轻的则短气。”该段表明饮水过多、难以运化、积蓄心下，可致水饮上犯心阳，而出现心悸、短气的表现。"}, {"source": "条49｜《备急千金要方》痰饮", "原文": "后世《备急千金要方·痰饮》指出：“凡心下有水者，筑筑而悸，短气而恐，其人眩而癫。先寒即为虚，先热即为实。故水在于心，其人心下坚，筑筑短气，恶水而不欲饮。”由此可见，心下停水可见心下坚满、短气，上犯凌心，则致心悸。", "白话": "后世《备急千金要方·痰饮》指出：“凡心下有水的，筑筑而悸，短气而恐惧，其人眩晕甚至发癫。先见寒象的属虚，先见热象的属实。所以水在心下，其人心下坚满，筑筑短气，厌恶水而不欲饮。”由此可见，心下停水可见心下坚满、短气；上犯凌心，则致心悸。"}, {"source": "条50｜《医灯续焰》悸、怔忡", "原文": "痰湿为阴邪，较水饮更为黏滞，易阻塞气机、蒙困心神，且因其重浊黏滞之性，易阻滞气血运行，同时影响中焦水谷精微的生成与转输，使心失所养，且为邪所伤，而使心中悸动。《医灯续焰·悸、怔忡》曰：“悸则心中微动，如恐如惊。怔忡则心胸振筑，莫知其来；忽尔宁寂，莫知其去。甚则头目眩晕，神气若浮，盖悸之重者也。大抵因痰积饮停，气冲火击所致。”该段即指出痰饮停蓄，阻碍气机，化火上逆，而致心悸。", "白话": "痰湿为阴邪，比水饮更为黏滞，容易阻塞气机、蒙困心神；且因其重浊黏滞之性，容易阻滞气血运行，同时影响中焦水谷精微的生成与转输，使心失所养又被邪所伤，而心中悸动。《医灯续焰·悸、怔忡》说：“悸是心中微动，如恐如惊；怔忡则心胸振筑，不知从何而来；忽然宁静，又不知从何而去。重的头目眩晕，神气浮越，这是悸中较重的。大抵因痰积饮停、气冲火击所致。”该段指出痰饮停蓄、阻碍气机、化火上逆而致心悸。"}, {"source": "条51｜《古今医统大全》惊悸门", "原文": "此外，痰湿黏滞，阻遏气机，为阴邪，犯及心阳，则心阳受遏，心神受扰，导致心悸。如《古今医统大全·惊悸门》曰：“郁痰留饮，积于心包胃口而致惊悸怔忡者有之，此又不可概以虚而治也。", "白话": "此外，痰湿黏滞，阻遏气机，属阴邪；犯及心阳，则心阳受遏、心神受扰，导致心悸。如《古今医统大全·惊悸门》说：“郁痰留饮积于心包胃口而致惊悸怔忡的，确有其事；这又不可一概按虚来治疗。”"}, {"source": "条52｜《太平圣惠方》治心实泻心诸方", "原文": "心为阳脏，若火热邪气侵袭，则使阳气偏胜，耗伤阴血，心神失养。火性炎上，易致心气耗散、心神不敛，从而出现心悸。《太平圣惠方·治心实泻心诸方》曰：“夫心实则生热，热则阳气盛，阳盛则卫气不行，荣气不通，遂令热毒稽留，心神烦乱，面赤身热，口舌生疮，咽燥头疼，喜笑，恐悸，手心热，满汗出，衄血，其脉洪实相搏者，是其候也。", "白话": "心为阳脏，若火热邪气侵袭，则阳气偏胜，耗伤阴血，心神失养；火性炎上，容易导致心气耗散、心神不敛，从而出现心悸。《太平圣惠方·治心实泻心诸方》说：“心实就生热，热则阳气盛，阳盛则卫气不行、营气不通，于是热毒稽留，心神烦乱，面赤身热，口舌生疮，咽燥头疼，喜笑，恐悸，手心热，大汗出，衄血；脉洪实相搏的，就是这种证候。”"}, {"source": "条53｜《素问玄机原病式》六气为病", "原文": "《素问玄机原病式·六气为病》明确指出：“故心胸躁动，谓之怔忡，俗云心忪，皆为热也。”其将怔忡归因于热邪，虽有所偏颇，但是足以见得火热对于心悸的影响。", "白话": "《素问玄机原病式·六气为病》明确指出：“所以心胸躁动，叫做怔忡，俗称心忪，都是热所致。”它把怔忡归因于热邪，虽有偏颇，但足以看出火热对于心悸的影响。"}, {"source": "条1｜《诸病源候论》心病候", "原文": "心气不足，则胸腹大，胁下与腰背相引痛，惊悸，恍惚，少颜色，舌本强，善忧悲，是为心气之虚也，则宜补之。", "白话": "心气不足，就会胸腹胀大，胁下与腰背相互牵引疼痛，出现惊悸、精神恍惚、面色少华、舌根强硬、容易忧伤悲哀；这就是心气虚，就应当用补法治疗。"}, {"source": "条2｜《证治准绳》惊悸恐", "原文": "心悸之由，不越二种，一者虚也，二者饮也。气虚者由阳气内虚，心下空虚，火气内动而为悸也。血虚者亦然。其停饮者，由水停心下，心为火而恶水，水既内停，心不白自安，故为悸也。", "白话": "心悸的原由，不超出两种：一是虚，二是水饮。气虚的，是由于阳气内虚、心下空虚，火气在内扰动而成为悸；血虚的也是这样。那停饮的，是由于水停在心下，心属火而厌恶水，水既然内停，心自然不能自安，所以成为悸。"}, {"source": "条3｜《华佗神方》卷四", "原文": "怔忡之症，扰扰不宁，心神恍惚，惊悸不已。此肝肾之虚，心气之弱也。", "白话": "怔忡这个病，纷扰不得安宁，心神恍惚，惊悸不止；这是肝肾亏虚、心气虚弱所致。"}, {"source": "条4｜《仁斋直指方》惊悸", "原文": "人之所主者心，心之所养者血，心血一虚，神气不守，此惊悸之所肇端也。", "白话": "人身的主宰是心，心所奉养的是血；心血一旦亏虚，神气就不能守藏，这就是惊悸的起始。"}, {"source": "条5｜《医学纲目》卷十三", "原文": "惊者，心卒动而不宁也。悸者，心跳动而怕惊也。瘦人多是血虚，肥人多是痰饮，真觉心跳者是血少，宜四物、安神之类。", "白话": "惊，是心突然跳动而不安宁；悸，是心跳动而容易受惊。形体瘦的人多属血虚，肥胖的人多属痰饮；真正感觉心跳的是血少，宜用四物汤、安神之类方剂。"}, {"source": "条6｜《奇效良方》卷四十六", "原文": "或逆气动躁者，由水衰火旺，而犹火之动也，故心胸躁动，谓之怔忪，此心血不足也。盖心主血，血乃心之主，心乃形之主，血富则心主自安矣。多因汲汲富贵，戚戚贫贱，又思所爱触事，不意真血虚耗，心主失辅，渐成怔忡。", "白话": "有的逆气躁动，是由于水衰而火旺，犹如火之躁动，所以心胸躁动，叫做怔忪，这是心血不足。心主血，血乃心之主，心乃形之主，血充盛则心主自然安宁。多因急切追求富贵、忧愁贫贱，又思念所爱之人、遇事不遂，不料真血渐渐虚耗，心主失去辅养，慢慢变成怔忡。"}, {"source": "条7｜《丹溪心法》惊悸怔忡", "原文": "怔忡者血虚，怔忡无时，血少者多。", "白话": "怔忡属于血虚；怔忡发作没有定时，属血少的居多。"}, {"source": "条8｜《医方选要》怔忡健忘动悸门", "原文": "夫怔忡者，心血不足，心中躁动不宁也。盖心主血，血旺则心主自安矣。一或为喜怒忧恐所动，则真血虚耗，心主失辅而成怔忡矣。又或外感风寒暑湿之气闭塞诸经，及协饮停留中脘，皆能令人怔忡。", "白话": "怔忡，是心血不足、心中躁动不宁。心主血，血旺则心主自然安宁。一旦被喜怒忧恐所触动，真血就虚耗，心主失去辅养而形成怔忡。又或者外感风寒暑湿之气闭塞各经，以及水饮停留中脘，都能使人怔忡。"}, {"source": "条9｜《保婴撮要》卷十", "原文": "惊者，心卒动而恐怖也；悸者，心跳动而怔忡也。二者因心虚血少，故健忘之症随之。", "白话": "惊，是心突然跳动而恐怖；悸，是心跳动而怔忡。二者都因心虚血少，所以健忘之症随之而来。"}, {"source": "条10｜《古今医统大全》惊悸门", "原文": "心血一亏，神气不守，此惊悸之所肇端也。惊者恐也，悸者怖也，血不足则神不守，神不守则惊恐悸怖之证作矣。", "白话": "心血一旦亏虚，神气不能守藏，这就是惊悸的开端。惊就是恐，悸就是怖；血不足则神不守，神不守则惊恐悸怖的证候就发作了。"}, {"source": "条11｜《古今医鉴》怔忡、惊悸", "原文": "夫惊悸者，蓦然而跳跃，惊动如有欲厥之状，有时而作者是也，属血虚。或时觉心跳，亦是血虚。", "白话": "惊悸，是突然跳跃、惊扰震动，如同将要昏厥的样子，时有发作；这属血虚。或者时时感觉心跳，也是血虚。"}, {"source": "条12｜《万病回春》怔忡", "原文": "怔忡者，心无血养，如鱼无水，心中惕惕然而跳动也，如人将捕捉之貌。若思虑即心跳者，是血虚也。", "白话": "怔忡，是心没有血来奉养，就像鱼没有水，心中惕惕地跳动，好像将被人捕捉的样子。如果一思虑就心跳的，是血虚。"}, {"source": "条13｜《考证病源》惊", "原文": "怔忡者，心中惚惚不安，如畏人捕捉之状，乃心血少也。", "白话": "怔忡，是心中恍惚不安，好像害怕被人捕捉的样子，这是心血少。"}, {"source": "条14｜《医学原理》怔忡惊悸门", "原文": "怔忡者，心中怵惕而不宁静之谓也，且有惊恐之状，皆心血有亏所致。原其所由，有因思想过度，心君不宁，神灵不安而致者；有因稠痰积饮，留结于心胸之间而致者。各有不同，治法亦难执一。是以心血不足者，在乎养血安神为主。", "白话": "怔忡，是指心中怵惕而不宁静，并有惊恐的样子，都是心血有亏所致。推原它的来由：有因思虑过度、心君不宁、神灵不安而导致的；有因稠痰积饮留结在心胸之间而导致的。各不相同，治法也难以固执一种。所以心血不足的，以养血安神为主。"}, {"source": "条15｜《证治准绳》惊悸恐（痰入舍空）", "原文": "人之所主者心，心之所养者血，心血一虚，神气失守，失守则舍空，舍空而痰入客之，此惊悸之所由发也。", "白话": "人的主宰是心，心所奉养的是血；心血一虚，神气失守，失守则心舍空虚，舍空则痰邪乘虚客居，这就是惊悸发生的原因。"}, {"source": "条16｜《简明医彀》惊悸", "原文": "血不足则神不守，神不守则惊恐、悸怖、恍惚，众证作焉。", "白话": "血不足则神不守藏，神不守则惊恐、悸怖、恍惚等证一齐发作。"}, {"source": "条17｜《傅青主女科》心痛", "原文": "血不足则怔忡、惊悸不安耳。", "白话": "血不足，就会怔忡、惊悸不安罢了。"}, {"source": "条18｜《辨证奇闻》卷八", "原文": "劳心经营太过，心火沸腾，先夜梦不安，久惊悸健忘，心神憔悴，血不华色，人谓心气弱，谁知心血亏乎。", "白话": "劳心经营太过，心火沸腾，先是夜梦不安，日久则惊悸健忘，心神憔悴，血不能荣华面色；人们说是心气弱，谁想到是心血亏呢。"}, {"source": "条19｜《顾松园医镜》卷十一", "原文": "健忘怔忡，心跳善惊，皆心血虚少之故，血虚则生火，火郁则生痰，痰动心胞，故为惊跳，及梦魇不宁。", "白话": "健忘怔忡、心跳易惊，都是心血虚少的缘故；血虚就生火，火郁就生痰，痰扰动心包，所以出现惊跳以及梦魇不宁。"}, {"source": "条20｜《医碥》卷四", "原文": "悸者，心筑筑惕惕然，动而不安也。（俗名心跳）。一由血虚，血虚则不能养心，心气常动，幸无火热相乘，故不至于惊而但悸也。若血不虚而动者，则为心火盛，，，，，（，，亦有肾火上冲者）。有失志之人，由所求不遂，或过误自咎，恨叹不已，独语书空，则心不息不安，时常劳动而怔忡作矣。", "白话": "悸，是心筑筑惕惕地跳动不安（俗名心跳）。一是由于血虚，血虚则不能养心，心气常常扰动，幸而没有火热相并，所以不至于惊而只是悸。如果血不虚而跳动的，就是心火盛（……也有肾火上冲的）。又有失志之人，由于所求不遂，或因过失错误自责，悔恨叹息不止，独语书空，则心不息不安，时常扰动而怔忡发作。"}, {"source": "条21｜《杂病源流犀烛》怔忡源流（卑惵）", "原文": "怔忡，心血不足病也。人所主者心，心所主者血，心血消亡，神气失守，则心中空虚，怏怏动摇，不得安宁。无时不作，名曰怔忡。", "白话": "怔忡是心血不足的病。人身的主宰是心，心所主的是血；心血消亡，神气失守，则心中空虚、怏怏动摇，不得安宁，无时不发作，名叫怔忡。"}, {"source": "条22｜《罗氏会约医镜》卷一", "原文": "荣行脉中，脉以血为形，今中空无血，则气无所归，阳无所附，而一切阴虚、发热、惊悸、怔忡、喘急、盗汗等症形焉。。", "白话": "营血运行在脉中，脉以血为形质；如今脉中空而无血，则气没有归宿、阳没有依附，于是阴虚、发热、惊悸、怔忡、喘急、盗汗等症都出现了。"}, {"source": "条23｜《杂病广要》虚劳", "原文": "怔忡惊悸，心血虚也。", "白话": "怔忡惊悸，属于心血虚。"}, {"source": "条24｜《王乐亭指要》怔忡", "原文": "怔忡之症，心跳振动，惊恐怵惕者是也。缘乎营阴不足，心阳不藏，神不守舍，以致心神不宁而怔忡不安，渐至心悸不寐之所由来也。然怔忡心悸，其病虽异，而其源实由乎一也。", "白话": "怔忡之症，是心跳振动、惊恐怵惕。由于营阴不足，心阳不藏，神不守舍，以致心神不宁而怔忡不安，这就是渐渐发展为心悸不寐的由来。然而怔忡与心悸，病名虽异，病源其实是一致的。"}, {"source": "条25｜《类经》卷五", "原文": "虚里跳动，最为虚损病本，故凡患阴虚劳怯，则心下多有跳动，及为惊悸慌张者，是即此证，人止知其心跳而不知为虚里之动也。但动之微者病尚微，动之甚者病则甚，亦可因此以察病之轻重。", "白话": "虚里跳动，最是虚损病的根本，所以凡患阴虚劳怯的，心下多有跳动，以至惊悸慌张的，就是此证；人们只知道心跳，而不知道是虚里在动。跳动轻微的病还轻，跳动厉害的病就重，也可以据此来察病的轻重。"}, {"source": "条26｜《不居集》卷二十二", "原文": "阴气内虚，虚火妄动，体瘦心悸，五心烦热，面赤唇燥，左脉微弱，或大而无力者是也。", "白话": "阴气内虚，虚火妄动，形体消瘦而心悸，五心烦热，面赤唇燥，左脉微弱或者大而无力，就是这种证。"}, {"source": "条27｜《景岳全书发挥》论怔忡", "原文": "怔忡乃心胸之间，上冲而筑筑惕惕然动，怔怔忡忡不能自安也。将动气为怔忡，大非也。此证惟唯阴虚劳损之人乃有之，盖阴虚于下，则宗气无根，而气不归源，所以在上则浮撼于胸臆，在下则振动于脐旁，怔忡之病不一，非但阴虚于下。", "白话": "怔忡是心胸之间有气上冲，筑筑惕惕地跳动，怔怔忡忡不能自安。把动气当作怔忡，是大错的。此证只有阴虚劳损的人才有；因为阴虚于下，则宗气无根，气不归源，所以在上就浮撼于胸臆，在下就振动于脐旁。怔忡的病不只一种，不只是阴虚于下。"}, {"source": "条28｜《杂病源流犀烛》怔忡源流", "原文": "悸者，心痹病也。非缘外有所触，自然跳动不宁，其原由水衰火旺，故心胸躁动，宜天王补心丹。", "白话": "悸是心痹一类的病。并非由于外有所触动，而是自然跳动不宁；其根源是水衰火旺，所以心胸躁动，宜用天王补心丹。"}, {"source": "条29｜《医原》内伤大要论", "原文": "若劳心者伤神，又重于劳力伤气者也。或卷牍烦剧，或百计图谋，心神无片刻之静，心体无安养之时，由是君火内沸，销烁真阴，不但伤神，并能伤精，阳不依阴，自阴不潜阳，阴虚必生内热，内热必化内燥，脉多细涩，甚而数涩，或浮弦搏指，皆阴虚化刚之象。见证多惊悸、怔忡、心热、盗汗、虚烦不寐，甚则君火引动相火，伤及真阴，干咳、吐血、遗滑、淋浊、骨蒸潮热，诸证丛生。", "白话": "劳心的人伤神，又比劳力伤气为重。或者文卷繁剧，或者千方百计谋虑，心神没有片刻安静，心体没有安养的时候，于是君火在内沸腾，销烁真阴；不但伤神，并且伤精。阳不依阴，阴不潜阳，阴虚必生内热，内热必化内燥，脉多细涩，甚至数涩，或浮弦搏指，都是阴虚化刚之象。见证多惊悸、怔忡、心热、盗汗、虚烦不寐；严重则君火引动相火，伤及真阴，出现干咳、吐血、遗精滑泄、淋浊、骨蒸潮热，诸证丛生。"}, {"source": "条30｜《备急千金要方》卷十三", "原文": "病苦悸恐不乐，心腹痛难以言，心如寒，恍惚，名曰心虚寒也。", "白话": "病人苦于悸恐不乐，心腹疼痛难以名状，心中觉寒，精神恍惚，名叫心虚寒。"}, {"source": "条31｜《本草汇言》草部", "原文": "真阳之气，得补而上升于胃，则能腐熟水谷，下应于脾，则能蒸糟粕而运化精微，以荣养五脏之阳。如脾之阴湿而不食，肾之寒冷而精流，心之怯悸而默默，大肠虚陷而溏泄，妇人血冷水带而腹疼，皆无阳也。", "白话": "真阳之气得到补养而上升于胃，就能腐熟水谷；下应于脾，就能蒸化糟粕而运化精微，以荣养五脏之阳。如脾阴湿而不思饮食，肾寒冷而精液滑流，心怯悸而沉默寡言，大肠虚陷而溏泄，妇人血冷水带而腹痛，都是无阳（阳气衰）的表现。"}, {"source": "条32｜《类经》五过四德", "原文": "及其病深，则真气消索，故曰无气。无气则阳虚，故洒然畏寒也。阳虚则神不足，故心怯而惊也。", "白话": "等到病深，真气消散，所以说无气。无气则阳虚，所以洒然畏寒。阳虚则神不足，所以心怯而惊。"}, {"source": "条33｜《景岳全书》黄疸", "原文": "凡神思困倦，言语轻微，或怔忡眩晕，畏寒少食，四肢无力，或大便不实，小水如膏，及脉息无力等证，悉皆阳虚之候。", "白话": "凡神思困倦、言语轻微，或怔忡眩晕、畏寒少食、四肢无力，或大便不实、小便如膏，以及脉息无力等证，都是阳虚之候。"}, {"source": "条34｜《景岳全书》妇人规", "原文": "总之，真阳不足者，必神疲气怯，或心跳不宁，或四体不收，或眼见邪祟，或阳衰无子等证，俱速宜益火之源，以培右肾之元阳，而神气自强矣。", "白话": "总之，真阳不足的，必然神疲气怯，或心跳不宁，或四肢不能收持，或眼见邪祟，或阳衰无子等证，都应赶快温益火之源，以培补右肾的元阳，神气自然强健。"}, {"source": "条35｜《太平圣惠方》治心脏风虚惊悸诸方", "原文": "夫心虚则多惊，胆虚则多恐。此皆气血不实，腑脏虚伤，风邪所干，入于经络，心既不足，胆气衰微，故令神思恐怯而多惊悸也。", "白话": "心虚就多惊，胆虚就多恐。这都是气血不充、脏腑虚伤，为风邪所侵犯，风邪进入经络；心既不足，胆气衰微，所以使人神思恐怯而多惊悸。"}, {"source": "条36｜《济生方》惊悸", "原文": "若惊悸者，心胆虚怯所致也。且心者君主之官，神明出焉；胆者中正之官，决断出焉。心气安逸，胆气不怯，决断思虑得其所矣。或因事有所大惊，或闻虚响，或见异相，登高涉险，惊忤心神，气与涎郁，遂使惊悸。惊悸不已，变生诸证，或短气悸乏，体倦自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安，皆心胆虚怯之候也。", "白话": "惊悸，是心胆虚怯所致。心是君主之官，神明由此而出；胆是中正之官，决断由此而出。心气安逸，胆气不怯，决断思虑就各得其所。或者因事受到大惊，或听到虚响，或见到怪异之相，登高涉险，惊扰触犯心神，气与痰涎郁滞，于是发生惊悸。惊悸不止，变生诸证：或短气悸乏、体倦自汗、四肢浮肿、饮食无味、心虚烦闷、坐卧不安，都是心胆虚怯的证候。"}, {"source": "条37｜《古今医鉴》不寐", "原文": "惊悸、健忘、怔忡、失志不寐、心风，皆是胆涎沃心，以致心气不足。", "白话": "惊悸、健忘、怔忡、失志不寐、心风，都是胆涎浸渍于心，以致心气不足。"}, {"source": "条38｜《辨证录》不寐", "原文": "胆气既虚，至不敢相延心肾二气而为之介绍，心肾乃怒其闭门不纳，两相攻击，故胆气愈虚，惊悸易起，益不能寐耳。", "白话": "胆气既然虚了，以至于不敢延引心肾二气为之介绍；心肾就恼怒它闭门不纳，两相攻击，所以胆气愈虚，惊悸容易发作，更加不能入睡。"}, {"source": "条39｜《叶选医衡》寝食说", "原文": "若神气衰微，疑神疑鬼，怔忡悸怯，独处无睡，病在肝胆也。", "白话": "如果神气衰微，疑神疑鬼，怔忡悸怯，独处时不能入睡，病在肝胆。"}, {"source": "条40｜《竹林女科证治》卷三", "原文": "胆无汁不能润心，心无血不能为养。是以心中恍惚而谵语、烦躁、惊悸相因而生也。", "白话": "胆没有精汁就不能濡润心，心没有血就不能受养。所以心中恍惚，而谵语、烦躁、惊悸相继而生。"}, {"source": "条41｜《伤寒杂病心法集解》神病门", "原文": "六症者，惊悸、怔忡、恍惚、健忘、失志、伤神六名也。此皆因心虚胆弱，诸邪得以乘之，但当审其所兼之症，分别虚实施治，又当按后癫痫、九气、痰饮等门合症拣方，自有效法之处。", "白话": "六症，是惊悸、怔忡、恍惚、健忘、失志、伤神六个病名。这都是因为心虚胆弱，各种邪气得以乘虚而入；只须审察所兼的症候，分别虚实施治，又当参照后面癫痫、九气、痰饮等门合症选方，自然有可以效法之处。"}, {"source": "条42｜《伤寒论》辨太阳病脉证并治上", "原文": "太阳病，小便利者，以饮水多，必心下悸；小便少者，必苦里急也。", "白话": "太阳病，小便通利的，因为饮水多，必心下悸；小便少的，必苦于里急。"}, {"source": "条43｜《金匮要略》痰饮咳嗽病脉证并治", "原文": "夫病人饮水多，必暴喘满。凡食少饮多，水停心下。甚者则悸，微者短气。", "白话": "病人饮水多，必突然喘满。凡食少而饮水多，水停在心下；重的则心悸，轻的则短气。"}, {"source": "条44｜《备急千金要方》卷十八", "原文": "凡心下有水者，筑筑而悸，短气而恐，其人眩而癫。先寒即为虚，先热即为实。故水在于心，其人心下坚，筑筑短气，恶水而不欲饮。", "白话": "凡心下有水的，筑筑而悸，短气而恐惧，其人眩晕甚至发癫。先见寒象的属虚，先见热象的属实。所以水在心下，其人心下坚满，筑筑短气，厌恶水而不欲饮。"}, {"source": "条45｜《济生方》怔忡论治", "原文": "五饮停蓄，湮塞中脘，亦令人怔忡。", "白话": "五饮停蓄，淤塞中脘，也能使人怔忡。"}, {"source": "条46｜《明医指掌》惊悸怔忡健忘证", "原文": "惊悸心中常惕惕，如人将捕时惊惑。延缠不已渐怔忡，寤寐神魂多恍惚。久而心虚停饮，水气乘心，胸中渗漉，虚气流动，水既上乘，心火畏之，心不自安，故怏怏然而怔忡也。", "白话": "惊悸则心中常常惕惕不安，好像将被人捕捉时的惊惑。迁延缠绵不止，渐渐成为怔忡，无论醒着睡着神魂多恍惚。日久心虚而停饮，水气乘袭于心，胸中渗漉，虚气流动；水既然上乘，心火畏惧它，心不能自安，所以怏怏然而成为怔忡。"}, {"source": "条47｜《医门法律》痰饮门", "原文": "水在肾，心下悸，缘肾水凌心，逼处不安，又非支饮邻国为壑之比矣。", "白话": "水在肾而见心下悸，是由于肾水上凌于心，逼迫于心而不得安宁；这又不是支饮“以邻国为壑”之类可比。"}, {"source": "条48｜《感症宝筏》伤寒变证", "原文": "然水亦不可恣饮，少少与之，胃和则愈。如多饮必致水气为患，而有悸喘等病矣。", "白话": "然而水也不可恣意多饮，稍稍给一点，胃气和调就会痊愈。如果多饮，必致水气为患，而发生悸、喘等病。"}, {"source": "条49｜《齐氏医案》卷五", "原文": "盖心下悸者，心下有水气；胁下悸者，胁下有水气；脐下悸者，脐下有水气，皆阴气挟夹水而动。法主扶阳以御阴，补土以逐水。", "白话": "心下悸的，是心下有水气；胁下悸的，是胁下有水气；脐下悸的，是脐下有水气；都是阴气挟水而动。治法主扶阳以御阴，补土以逐水。"}, {"source": "条50｜《伤寒直指》卷十二", "原文": "心主神，神依血，心血一虚，神失所守而舍空，痰水客之，此惊悸之所作也。惊者，惕然不宁，触事易惊，气郁生痰也。悸者，筑然跳动。盖以心虚则停水，水居火位，心实畏之，故怔忡也。", "白话": "心主神，神依附于血；心血一虚，神失所守而心舍空虚，痰水客居其中，这就是惊悸的发作。惊，是惕然不宁，遇事容易受惊，由气郁生痰所致；悸，是筑然跳动。因为心虚则停水，水居于火位，心实在畏惧它，所以成为怔忡。"}, {"source": "条51｜《保命歌括》痰病", "原文": "心有痰，为善惊，为癫痫，为怔忡，为嗌干渴而欲饮，为心痛，为舌肿痛，为笑，为不语，为痰迷如祟。", "白话": "心有痰，表现为易惊、癫痫、怔忡、咽喉干燥口渴想喝水、心痛、舌肿痛、多笑、不语、痰迷如同鬼祟。"}, {"source": "条52｜《古今医统大全》惊悸门", "原文": "郁痰留饮，积于心包胃口而致惊悸怔忡者有之，此又不可概以虚而治也。", "白话": "郁痰留饮积聚在心包、胃口而导致惊悸怔忡的，确有其事；这又不可一概按虚来治疗。"}, {"source": "条53｜《医学原理》怔忡惊悸门", "原文": "怔忡惊悸之症，肥人多是痰火冲心，瘦人多是心血不足。", "白话": "怔忡惊悸之症，胖人多是痰火冲心，瘦人多是心血不足。"}, {"source": "条54｜《客尘医话》卷一", "原文": "心主之阳为浊阴所乘，则为心悸怔忡。", "白话": "心主的阳气被浊阴所乘袭，就发为心悸怔忡。"}, {"source": "条55｜《医灯续焰》卷十八", "原文": "悸则心中微动，如恐如惊。怔忡则心胸振筑，莫知其来；忽尔宁寂，莫知其去。甚则头目眩晕，神气若浮，盖悸之重者也。大抵因痰积饮停，气冲火击所致。", "白话": "悸是心中微动，如恐如惊；怔忡则心胸振筑，不知从何而来；忽然宁静，又不知从何而去。重的头目眩晕，神气浮越，这是悸中较重的。大抵因痰积饮停、气冲火击所致。"}, {"source": "条56｜《医学心悟》惊悸恐", "原文": "悸为心动，谓之怔忡，心筑筑而跳，摇摇而动也。皆由心虚挟夹痰所致，定志丸加半夏、橘红主之。", "白话": "悸是心动，叫做怔忡，心筑筑地跳、摇摇地动。都由心虚夹痰所致，用定志丸加半夏、橘红主治。"}, {"source": "条57｜《不居集》怔忡惊悸健忘善怒善恐不眠", "原文": "惊悸健忘，怔忡失志，心风不寐，皆是痰涎沃心，以致心气不足。", "白话": "惊悸健忘、怔忡失志、心风不寐，都是痰涎浸渍于心，以致心气不足。"}, {"source": "条58｜《脉简补义》动脉有强弱", "原文": "心火自衰，寒水侵凌，阳气不伸，其脉累累如珠，应指无力，其病为怔忡、嘈杂之证，故曰悸也，是痰饮淫泆膻中之所致也。", "白话": "心火自衰，寒水侵凌，阳气不得伸展，其脉累累如串珠，应指无力，其病为怔忡、嘈杂之证，所以叫做悸；这是痰饮流溢于膻中所致。"}, {"source": "条59｜《太平圣惠方》卷四", "原文": "夫心实则生热，热则阳气盛，阳盛则卫气不行，荣气不通，遂令热毒稽留，心神烦乱，面赤身热，口舌生疮，咽燥头疼，喜笑，恐悸，手心热，满汗出，衄血，其脉洪实相搏者，是其候也。", "白话": "心实就生热，热则阳气盛，阳盛则卫气不行、营气不通，于是热毒稽留，心神烦乱，面赤身热，口舌生疮，咽喉干燥头痛，喜笑，恐悸，手心热，大汗出，衄血；脉洪实相搏的，就是这种证候。"}, {"source": "条60｜《黄帝素问宣明论方》卷四", "原文": "夫肾水真阴本虚，心火狂阳积热以甚，以致风热壅滞，头面昏眩，肢体麻痹，皮肤瘙痒，筋脉拘卷，胸膈痞满，时或痛闷，或鼻窒鼽衄，口舌生疮，咽喉不利，牙齿疳蚀，或遍身生疮癣疥，或睡语咬牙，惊惕虚汗，或健妄心松，烦躁多睡，或大小便涩滞，或烦热腹满，或酒过积毒。", "白话": "肾水真阴本来就虚，心火狂阳积热更甚，以致风热壅滞：头面昏眩，肢体麻痹，皮肤瘙痒，筋脉拘挛，胸膈痞满，时或痛闷；或鼻塞、流涕鼻衄，口舌生疮，咽喉不利，牙齿疳蚀；或遍身生疮癣疥；或睡中谵语咬牙、惊惕虚汗；或健忘心悸、烦躁多睡；或大小便涩滞；或烦热腹满；或饮酒过度积毒。"}, {"source": "条61｜《素问玄机原病式》六气为病", "原文": "故心胸躁动，谓之怔忡，俗云心忪，皆为热也。", "白话": "所以心胸躁动，叫做怔忡，俗称心忪，都是热所致。"}, {"source": "条62｜《医学启源》卷中", "原文": "躁动烦热，扰乱而不宁，火之体也。热甚于外，则肢体躁扰；热甚于内，则神志躁动，反覆颠倒，懊憹烦心，不得眠也。由水衰而火之动也。故心胸躁动，谓之怔忪，俗云心忪，皆为热也。", "白话": "躁动烦热、扰乱不宁，是火的本性。热甚于外，则肢体躁扰；热甚于内，则神志躁动，反复颠倒，懊憹烦心，不能入睡。这是由于水衰而火动。所以心胸躁动，叫做怔忪，俗称心忪，都是热所致。"}, {"source": "条63｜《严氏济生方》五脏门", "原文": "夫心者，手少阴之经，位居南方，属乎丙丁火，为形之君。外应于舌，主宰一身，统摄诸脏血脉，灌溉溪谷，内润五脏，外卫腠理，与手阳明小肠之经相为表里……及其实也，实则生热，热则心神烦乱，面赤身热，口舌生疮，咽燥头痛，喜笑恐悸，手心烦热，汗出衄血，其脉洪实者，是实热之候也。", "白话": "心是手少阴经，位居南方，属丙丁火，是形体的君主。外应于舌，主宰一身，统摄诸脏血脉，灌溉溪谷，内润五脏，外卫腠理，与手阳明小肠经相为表里……及其成实，实则生热，热则心神烦乱，面赤身热，口舌生疮，咽燥头痛，喜笑恐悸，手心烦热，汗出衄血；脉洪实的，是实热之候。"}, {"source": "条64｜《推求师意》杂病门", "原文": "若夫在身之阴阳盛衰而致其惊恐者，则惊是火热躁动其心，心动则神乱，神用无方故惊之。变状亦不一，为惊骇，为惊妄，为惊狂，为惊悸等。", "白话": "至于因身中阴阳盛衰而导致惊恐的，惊是火热躁动其心，心动则神乱，神的运用失其方寸，所以惊。变化的形态也不一：有惊骇、惊妄、惊狂、惊悸等。"}, {"source": "条65｜《奇效良方》卷八", "原文": "诸禁鼓栗，如丧神守，皆属于火。禁栗惊惑，如丧神守，悸动怔忡，皆热之内作，故治当以制火之剂，其神守血，荣自愈也。", "白话": "各种口噤鼓颔战栗、如同丧失神守的，都属于火。口噤战栗、惊惑如同丧失神守、悸动怔忡，都是热从内而作，所以治疗当用制火之剂，使神守血安，营血自愈。"}, {"source": "条66｜《素问吴注》卷二", "原文": "心为天君，不易受邪，在五行为火，胆与三焦之火既炽，则同气相求，必归于心，心引而动，名曰心掣。", "白话": "心是天君，不容易受邪，在五行为火；胆与三焦之火既然炽盛，同气相求，必归于心，心被引动，名叫心掣。"}, {"source": "条67｜《证治准绳》神志门", "原文": "又包络之火，非惟唯辅心，而且游行于五脏，故五脏之气妄动者，皆火也。是以各脏有疾，皆能与包络之火合动而作悸。", "白话": "又，包络之火不但辅助心，而且游行于五脏，所以五脏之气妄动的，都是火。因此各脏有病，都能与包络之火相合而动，发生心悸。"}, {"source": "条68｜《内经知要》卷下", "原文": "少阳为一阳，胆与三焦也。胆属木，三焦属火，壮火食气，相火刑金，故少气善咳。木旺则侮土，故善泄。三焦火动，则心掣而不宁。", "白话": "少阳是一阳，指胆与三焦。胆属木，三焦属火；壮火食气，相火刑金，所以少气而易咳。木旺则欺侮脾土，所以易泄泻。三焦火动，则心掣而不宁。"}, {"source": "条69｜《疡医大全》卷三（引《入门》）", "原文": "《入门》曰：惊悸，因思虑过度及大惊恐而作，甚则心跳欲厥，时作时止者，乃痰因火动。", "白话": "《入门》说：惊悸因思虑过度以及大惊大恐而发作，重的则心跳欲厥，时作时止的，是痰因火而动。"}, {"source": "条70｜《医学入门》（据《疡医大全》卷三转引）", "原文": "《入门》曰：惊悸，因思虑过度及大惊恐而作，甚则心跳欲厥，时作时止者，乃痰因火动。", "白话": "惊悸，因思虑过度以及大惊大恐而发作；重的则心跳欲厥，时作时止的，是痰因火动。"}, {"source": "条71｜《蠢子集》卷一", "原文": "一切心颤与心悸，尽是风火往上传。", "白话": "一切心颤与心悸，都是风火向上攻传所致。"}, {"source": "条1｜《卫生易简方》卷一·甘草", "原文": "《卫生易简方》卷一：“治伤寒二三日咽痛，用甘草二两,炙。  \n水三升，煮取一升半，服五合，日三服。又治伤寒脉结心悸。", "白话": "〔主治〕治伤寒得病二三日咽喉疼痛；又治伤寒脉结、心悸。〔组成·照录〕甘草二两（炙）。〔方义〕炙甘草补中缓急、清热利咽，单味即效。〔服法〕以水三升，煮取一升半，每次服五合，一日三次。"}, {"source": "条2｜《卫生易简方》卷六·覆盆子", "原文": "《卫生易简方》卷六：“治阴痿，用覆盆子复盆子取汁作煎点汤服。并益颜色，安五脏，养精气，强阴，女子食之有子；及疗中风身热，肺脏虚寒，惊悸、益力、长发明目，缩小便。", "白话": "〔主治〕治阴痿（阳痿）；又使颜色润泽，安和五脏，滋养精气，强健阴器，女子食之能受孕；并治中风身热、肺脏虚寒、惊悸，能增益气力、使头发生长、眼睛明亮、缩小便。〔组成·照录〕覆盆子（原稿作“覆盆子复盆子”）。〔方义〕覆盆子益肾固精缩尿，肾精得固则心神得养、惊悸可止。〔服法〕取汁作煎，点汤服。"}, {"source": "条3｜《赤水玄珠》卷十·紫石英散", "原文": "《赤水玄珠》卷十：“紫石英散。抱朴子云：紫石英久服成仙。《本草》云：壮神气。此方治虚怯惊悸，饮食不进，成痨者，服之有奇功。  \n紫石英五两  \n打成粗米粒。以水一斗，煎取三升，澄清，去滓，将汁作羹粥食之，服尽再煎，五料见功。久服能驻颜住世。", "白话": "〔方名〕紫石英散。抱朴子说：紫石英久服成仙。《本草》说：壮益神气。此方治虚怯惊悸、饮食不进、渐成痨者，服之有奇功。〔组成·照录〕紫石英五两。〔方义〕紫石英甘温，镇心安神、温养心气，心气得养则惊悸自止。〔制法·服法〕打成粗米粒大小，以水一斗煎取三升，澄清去渣，将药汁做成羹粥食之；服尽再煎，五料见效。久服能驻颜住世。"}, {"source": "条4｜《经验良方全集》卷一·荆沥", "原文": "《经验良方全集》卷一：治心虚惊悸羸瘦者。  \n荆沥二升，水煎至一升六合，分作四服，日三次，夜一次。", "白话": "〔主治〕治心虚惊悸、身体消瘦者。〔组成·照录〕荆沥二升。〔方义〕荆沥甘寒，清热化痰、宁心定惊。〔制法·服法〕水煎至一升六合，分作四次服，白天三次、夜间一次。"}, {"source": "条5｜《伤寒论·辨少阴病脉证并治》·四逆散", "原文": "《伤寒论·辨少阴病脉证并治》：少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，四逆散主之。  \n甘草炙  枳实破，水渍，炙干  柴胡  芍药  \n上四味，各十分，捣筛，白饮和服方寸匕，日三服。咳者，加五味子、干姜各五分，并主下利；悸者，加桂枝五分；小便不利者，加茯苓五分；腹中痛者，加附子一枚，炮令坼；泄利下重者，先以水五升，煮薤白三升，煮取三升，去滓，以散三方寸匕，内汤中，煮取一", "白话": "〔主治〕少阴病，四肢逆冷，病人或咳嗽，或心悸，或小便不利，或腹中疼痛，或泄泻而肛门重坠的，用四逆散主治。〔组成·照录〕甘草（炙）、枳实（破开，水浸，炙干）、柴胡、芍药。〔方义〕柴胡疏肝解郁、枳实行气散结、芍药和血、甘草调中，合用透解郁热、疏理肝脾，气机畅则悸自平。〔服法〕上四味各十分，捣筛为散，以米汤调服方寸匕，一日三次。〔加减〕咳嗽加五味子、干姜各五分，并主下利；心悸加桂枝五分；小便不利加茯苓五分；腹中痛加附子一枚（炮令坼）；泄利下重者，先以水五升煮薤白三升取三升去渣，用散"}, {"source": "条6｜《幼幼新书》卷十五·仲景四逆散", "原文": "《幼幼新书》卷十五：《活人书》仲景四逆散  \n甘草炙、枳实去白瓤，炒黄、柴胡、芍药以上各一两  \n咳者加五味子、干姜各半两。下利悸者，加桂半两。小便不利者，加茯苓半两。腹中痛者，加附子半枚，炮裂。泄利下重，先浓煎薤白汤，内药末三钱匕，再煮一二沸，温服。上捣筛为细散。米饮下二钱，日三服。", "白话": "〔出处〕《幼幼新书》引《活人书》所载仲景四逆散。〔组成·照录〕甘草（炙）、枳实（去白瓤，炒黄）、柴胡、芍药以上各一两。〔方义〕与《伤寒论》四逆散同功，疏肝理脾、透解郁热，改汤为散。〔服法〕上药捣筛为细散，米饮送下二钱，一日三次。〔加减〕咳嗽加五味子、干姜各半两；下利而心悸加桂半两；小便不利加茯苓半两；腹中痛加附子半枚（炮裂）；泄利下重者，先浓煎薤白汤，加入药末三钱匕，再煮一二沸，温服。"}, {"source": "条7｜《增订通俗伤寒论·第一编》·四逆散", "原文": "《增订通俗伤寒论·第一编》：太阴兼证：兼心经证，神烦而悸，汗出津津，似寐非寐，或不得卧；兼肝经证，心中痛热，饥不欲食，食即呕酸吐苦，胸胁满疼，甚则霍乱吐泻。故唯厥冷而或咳或悸，腹痛下重，是阳为阴遏之利，用四逆散。", "白话": "〔主治〕太阴兼证：兼心经证的，神烦而心悸，汗出津津，似睡非睡，或不得安卧；兼肝经证的，心中痛而热，饥而不欲食，食入即呕酸吐苦，胸胁满痛，甚则上吐下泻。所以只见四肢厥冷而或咳或悸、腹痛下重的，是阳气被阴邪郁遏之证，用四逆散。〔方义〕四逆散疏肝理脾、透解郁遏之阳，阳气得伸则厥回悸止。〔组成·服法〕原稿未载，参见《伤寒论》四逆散。"}, {"source": "条8｜《金匮玉函经》卷二·小柴胡汤", "原文": "《金匮玉函经》卷二：中风，五六日，伤寒，往来寒热，胸胁苦满，嘿嘿不欲饮食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞坚，或心中悸，小便不利，或不渴，外有微热，或咳，小柴胡汤主之。  \n柴胡半斤 黄芩三两 人参三两 半夏洗，半升 甘草炙、生姜切，各三两 大枣擘，十二枚  \n上七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。若胸中烦而不呕者，去半夏人参，加栝蒌实一枚……若心下", "白话": "〔主治〕中风（伤寒）五六日，往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕；或胸中烦而不呕，或口渴，或腹中痛，或胁下痞硬，或心中悸、小便不利，或口不渴而外有微热，或咳嗽——用小柴胡汤主治。〔组成·照录〕柴胡半斤、黄芩三两、人参三两、半夏（洗）半升、甘草（炙）、生姜（切）各三两、大枣（擘）十二枚。〔方义〕柴胡、黄芩和解少阳，半夏、生姜和胃止呕，参、草、枣扶正达邪，为和解少阳主方。〔服法〕上七味以水一斗二升煮取六升，去渣再煎取三升，温服一升，一日三次。〔加减〕胸中烦而不呕者，去半夏、"}, {"source": "条9｜《圣济总录》卷三十二·柴胡汤", "原文": "《圣济总录》卷三十二：治伤寒后虚劳，烦热惊悸，不得眠睡。柴胡汤方。  \n柴胡去苗，半两  酸枣仁微炒，二两  远志去心，一分  当归切，焙、防风去叉、甘草炙，锉、茯神去木、猪苓去黑皮、桂去粗皮、黄芪锉、人参、生干地黄、芎、麦门冬去心，焙，各半两  \n上一十四味，粗捣筛，每服三钱匕，水一大盏，生姜三片，煎至七分去滓，空心温服日再。", "白话": "〔主治〕治伤寒之后虚劳，烦热惊悸，不得睡眠。〔组成·照录〕柴胡（去苗）半两、酸枣仁（微炒）二两、远志（去心）一分、当归（切，焙）、防风（去叉）、甘草（炙，锉）、茯神（去木）、猪苓（去黑皮）、桂（去粗皮）、黄芪（锉）、人参、生干地黄、芎（原稿此字后一字残损）、麦门冬（去心，焙）各半两。〔方义〕柴胡清解余热，枣仁、远志、茯神养心安神，参、芪、归、地益气养血，标本兼顾。〔服法〕上十四味粗捣筛，每服三钱匕，水一大盏加生姜三片，煎至七分去渣，空腹温服，日两次。"}, {"source": "条10｜《伤寒直指》卷十四·柴胡双解饮", "原文": "《伤寒直指》卷十四：柴胡双解饮节庵。  \n柴胡、黄芩、半夏、人参、甘草、白芍、茯苓、姜三片  枣二枚  \n渴去半夏加花粉、知母；呕加姜汁、竹茹；胁痛加青皮；寒热似疟加桂枝；热多倍柴胡；寒多倍桂枝；小便不利加茯苓；嗽加金沸草一云去人参；痰盛加瓜蒌仁、杏仁、枳壳；胸中满闷，加枳壳、桔梗、陈皮，未效，去茯苓、甘草，再加黄连，豁然有效；虚烦，加竹叶、炒粳米一云加竹茹；腹痛，倍加芍药；心中悸，加猪苓。", "白话": "〔出处〕柴胡双解饮（节庵方）。〔组成·照录〕柴胡、黄芩、半夏、人参、甘草、白芍、茯苓，生姜三片、大枣二枚。〔方义〕以小柴胡汤为底，和解少阳、健脾化痰，表里双解。〔加减〕口渴去半夏加天花粉、知母；呕吐加姜汁、竹茹；胁痛加青皮；寒热如疟加桂枝；热多倍柴胡；寒多倍桂枝；小便不利加茯苓；咳嗽加金沸草（一说去人参）；痰盛加瓜蒌仁、杏仁、枳壳；胸中满闷加枳壳、桔梗、陈皮，若不效，去茯苓、甘草再加黄连，豁然有效；虚烦加竹叶、炒粳米（一说加竹茹）；腹痛倍加芍药；心中悸加猪苓。"}, {"source": "条11｜《医学指要》卷五·柴胡百合汤", "原文": "《医学指要》卷五：柴胡百合汤。治瘥后昏沉发热，口渴，错语失神，及食复、劳复、百合等症悉宜用。  \n柴胡、生地、黄芩各一钱 知母、百合、陈皮、人参各八分 甘草三分 姜 枣引  \n若头微痛，加羌活、川芎……心惊悸，为血虚，加当归、茯苓、远志。", "白话": "〔主治〕治病愈后昏沉发热、口渴、言语错乱、神志失常，以及食复、劳复、百合病等证都宜用。〔组成·照录〕柴胡、生地、黄芩各一钱，知母、百合、陈皮、人参各八分，甘草三分，生姜、大枣为引。〔方义〕柴胡、黄芩清解余热，百合、生地、知母滋阴清热，参、草益气，为瘥后调养之方。〔加减〕头微痛加羌活、川芎……（原稿节略）；心惊悸属血虚者，加当归、茯苓、远志。"}, {"source": "条12｜《太医院秘藏膏丹丸散方剂》卷二·防风通圣丸", "原文": "《太医院秘藏膏丹丸散方剂》卷二：防风通圣丸。  \n防风、大黄、白术、川芎、白芍、石膏、当归、荆芥、黄芩、栀子、桔梗、滑石、连翘各一两 麻黄五钱 薄荷七钱 朴硝七钱 甘草五钱  \n共为细末，水叠为丸，如梧桐子大。  \n治风热郁结，寒火相激，头目不清，咽喉不利，或疼或肿，发热发赤，咳嗽痰，溲便淋闭，舌强口噤，语言谵妄，瘫痪麻木，癫狂惊悸，伤风伤寒，感冒瘟疫时毒，肿毒初起，痈疽风刺瘾疹。此药发表通里，并", "白话": "〔主治〕治风热郁结、寒火相激，头目不清，咽喉不利，或痛或肿，发热发红，咳嗽有痰，小便淋涩、大便闭结，舌强口噤，语言谵妄，瘫痪麻木，癫狂惊悸，以及伤风伤寒、感冒瘟疫时毒、肿毒初起、痈疽粉刺瘾疹。此药发表通里，都能治疗。〔组成·照录〕防风、大黄、白术、川芎、白芍、石膏、当归、荆芥、黄芩、栀子、桔梗、滑石、连翘各一两，麻黄五钱，薄荷七钱，朴硝七钱，甘草五钱。〔方义〕防风、麻黄、荆芥、薄荷解表，大黄、朴硝通里，芩、栀、石膏、滑石清热，归、芎、芍养血，为表里双解之剂。〔制法·服法〕共为"}, {"source": "条13｜《伤寒论·辨太阳病脉证并治下》·炙甘草汤", "原文": "《伤寒论·辨太阳病脉证并治下》：伤寒脉结代，心动悸，炙甘草汤主之。  \n甘草炙，四两 生姜切，三两 人参二两 生地黄一斤 桂枝去皮，三两 阿胶二两 麦门冬去心，半升 麻仁半升 大枣擘，三十枚  \n上九味，以清酒七升，水八升，先煮八味，取三升，去滓，内胶烊消尽，温服一升，日三服。一名复脉汤。", "白话": "〔主治〕伤寒病脉象结代、心中动悸的，用炙甘草汤主治。〔组成·照录〕甘草（炙）四两、生姜（切）三两、人参二两、生地黄一斤、桂枝（去皮）三两、阿胶二两、麦门冬（去心）半升、麻仁半升、大枣（擘）三十枚。〔方义〕炙甘草配参、枣益气复脉为君，地、麦、麻、胶滋阴养血，桂枝、生姜通阳利脉，为益气滋阴、通阳复脉之祖方。〔服法〕上九味用清酒七升、水八升，先煮八味取三升，去渣，加入阿胶烊化消尽，温服一升，一日三次。一名复脉汤。"}, {"source": "条14｜《备急千金要方》卷三·人参丸", "原文": "《备急千金要方》卷三：人参丸。治产后大虚，心悸，志意不安，不自觉恍惚恐畏，夜不得眠，虚烦少气方。  \n人参、甘草、茯苓各三两  麦门冬、菖蒲、泽泻、薯蓣、干姜各二两  桂心一两  大枣五十枚  \n上十味为末，以蜜枣膏和丸如梧子，未食酒服二十丸，日三夜一，不知稍增。若有远志，纳二两佳。若风气加当归、独活各三两。亦治男子虚损心悸。", "白话": "〔主治〕治产后大虚，心悸，意志不安，不自觉地恍惚恐惧，夜不成眠，虚烦少气。〔组成·照录〕人参、甘草、茯苓各三两，麦门冬、菖蒲、泽泻、薯蓣、干姜各二两，桂心一两，大枣五十枚。〔方义〕参、草、薯蓣、干姜益气温中，茯苓、菖蒲安神定志，麦冬养阴，桂心通阳，枣膏和丸养心脾。〔服法〕上十味为末，以蜜、枣膏和丸如梧桐子大，饭前酒服二十丸，日三次夜一次，不效稍增。〔加减〕若有远志加入二两更佳；若兼风气加当归、独活各三两。亦治男子虚损心悸。"}, {"source": "条15｜《备急千金要方》卷三·大远志丸", "原文": "《备急千金要方》卷三：大远志丸。治产后心虚不足，心下虚悸志意不安，恍恍惚惚，腹中拘急痛，夜卧不安，胸中吸吸少气，内补伤损，益气，安定心神，亦治虚损方。  \n远志、甘草、桂心、茯苓、麦门冬、人参、当归、白术、泽泻、独活、菖蒲各三两  薯蓣、阿胶各二两  干姜四两  干地黄五两  \n上十五味为末，蜜和丸如大豆，未食温酒服二十丸，日三，不知稍增，至五十丸。若大虚，身体冷，少津液，加钟乳三两为善。", "白话": "〔主治〕治产后心虚不足，心下虚悸，意志不安，恍恍惚惚，腹中拘急疼痛，夜卧不安，胸中气短吸吸；功能内补伤损、益气、安定心神，亦治诸虚损。〔组成·照录〕远志、甘草、桂心、茯苓、麦门冬、人参、当归、白术、泽泻、独活、菖蒲各三两，薯蓣、阿胶各二两，干姜四两，干地黄五两。〔方义〕参、术、草、姜益气健脾，归、地、阿胶养血，远志、菖蒲、茯苓安神，桂心通阳，为气血双补、安神定悸之方。〔服法〕上十五味为末，蜜和丸如大豆大，饭前温酒服二十丸，一日三次，不效稍增至五十丸。〔加减〕若大虚、身体冷、津"}, {"source": "条16｜《备急千金要方》·内补黄芪汤", "原文": "《备急千金要方》：内补黄芪汤。治妇人七伤，身体疼痛，小腹急满，面目黄黑，不能饮食并诸虚乏不足，少气，心悸不安方。  \n黄芪、当归、芍药、干地黄、半夏各三两  茯苓、人参、桂心、远志、麦门冬、甘草、五味子、白术、泽泻各二两  干姜四两  大枣三十枚  \n上十六味，㕮咀，以水一斗半，煮取三升，去滓，一服五合，日三夜一服。", "白话": "〔主治〕治妇人七伤，身体疼痛，小腹急满，面色黄黑，不能饮食及一切虚乏不足、少气、心悸不安。〔组成·照录〕黄芪、当归、芍药、干地黄、半夏各三两，茯苓、人参、桂心、远志、麦门冬、甘草、五味子、白术、泽泻各二两，干姜四两，大枣三十枚。〔方义〕黄芪合四君益气健脾，归、地、芍养血，桂、姜温中，远志、麦冬、五味养心安神，为气血双补之剂。〔服法〕上十六味切碎，以水一斗半煮取三升，去渣，每服五合，日三次夜一次。"}, {"source": "条17｜《备急千金要方》卷三·甘草丸", "原文": "《备急千金要方》卷三：甘草丸。治产后心虚不足，虚悸，心神不安，吸吸乏气，或若恍恍惚惚，不自知觉者方。  \n甘草、远志、菖蒲各三两  人参、麦门冬、干姜、茯苓各二两  泽泻、桂心各一两  大枣五十枚  \n上十味为末，蜜和丸如大豆，酒服二十丸，日四五服，夜再服，不知稍加。若无泽泻，以白术代之。若胸中冷，增干姜。", "白话": "〔主治〕治产后心虚不足，虚悸，心神不安，气短吸吸，或恍恍惚惚、不自知觉。〔组成·照录〕甘草、远志、菖蒲各三两，人参、麦门冬、干姜、茯苓各二两，泽泻、桂心各一两，大枣五十枚。〔方义〕甘草、参、枣益气补中，远志、菖蒲、茯苓安神定志，桂心、干姜温阳，麦冬养阴，标本兼顾。〔服法〕上十味为末，蜜和丸如大豆大，酒服二十丸，日四五次，夜间再服，不效稍加。〔加减〕若无泽泻以白术代之；若胸中冷增加干姜。"}, {"source": "条18｜《备急千金要方》卷三·安心汤", "原文": "《备急千金要方》卷三：安心汤。治产后心忡悸不定，恍恍惚惚，不自知觉，言语错误，虚烦短气，志意不定，此是心虚所致方。  \n远志、甘草各二两  人参、茯神、当归、芍药各三两  麦门冬一升  大枣三十枚  \n上八味，㕮咀，以水一斗，煮取三升，去滓，分三服，日三。若苦虚烦短气者，加淡竹叶二升，水一斗二升，煮竹叶取一斗，纳药。若胸中少气者，加甘草为三两善。", "白话": "〔主治〕治产后心中忡悸不定，恍恍惚惚，不自知觉，言语错乱，虚烦短气，意志不定——此为心虚所致。〔组成·照录〕远志、甘草各二两，人参、茯神、当归、芍药各三两，麦门冬一升，大枣三十枚。〔方义〕远志、茯神安神定志为君，参、草、枣益气，归、芍养血，麦冬滋阴，共成养心安神之功。〔服法〕上八味切碎，以水一斗煮取三升，去渣，分三次服，一日三次。〔加减〕若苦于虚烦短气，加淡竹叶二升（先以水一斗二升煮竹叶取一斗再下药）；若胸中气少，甘草加至三两为好。"}, {"source": "条19｜《备急千金要方》卷三·远志汤", "原文": "《备急千金要方》卷三：远志汤。治产后忽苦心中忡悸不定，志意不安，言语错误，惚惚愦愦，情不自觉方。  \n远志、麦门冬、人参、甘草、当归、桂心各二两  芍药一两  茯苓五两  生姜六两  大枣二十枚  \n上十味，㕮咀，以水一斗煮取三升，去滓，分三服，日三。羸者分四服。产后得此，正是心虚所致。无当归用芎，若其人心胸逆气，加半夏三两。", "白话": "〔主治〕治产后突然心中忡悸不定，意志不安，言语错乱，神识昏乱、不能自主。〔组成·照录〕远志、麦门冬、人参、甘草、当归、桂心各二两，芍药一两，茯苓五两，生姜六两，大枣二十枚。〔方义〕远志、茯苓重用安神定志，参、草、姜、枣益气温中，归、芍养血，桂心通阳，麦冬养阴。〔服法〕上十味切碎，以水一斗煮取三升，去渣，分三次服，一日三次；体弱者分四服。产后得此证正是心虚所致。〔加减〕无当归用川芎；若病人心胸有逆气，加半夏三两。"}, {"source": "条20｜《备急千金要方》卷三·茯苓汤", "原文": "《备急千金要方》卷三：茯苓汤。治产后暴苦心悸不安，言语错谬，恍恍惚惚，心中愦愦，此皆心虚所致方。  \n茯苓五两  甘草、芍药、桂心、当归各二两  生姜六两  麦门冬一升  大枣三十枚  \n上八味，㕮咀，以水一斗，煮取三升，去滓，分三服，日三。", "白话": "〔主治〕治产后突然心悸不安、言语错乱、恍恍惚惚、心中昏乱——这都是心虚所致。〔组成·照录〕茯苓五两，甘草、芍药、桂心、当归各二两，生姜六两，麦门冬一升，大枣三十枚。〔方义〕茯苓重用宁心安神为君，合桂心通阳、归芍养血、麦冬滋阴、姜草枣和中。〔服法〕上八味切碎，以水一斗煮取三升，去渣，分三次服，一日三次。"}, {"source": "条21｜《备急千金要方》卷三·茯神汤", "原文": "《备急千金要方》卷三：茯神汤。治产后忽苦，心中忡悸，或志意不定，恍恍惚惚，言语错谬，心虚所致方。  \n茯神四两  人参、茯苓各三两  芍药、甘草、当归、桂心各一两  生姜八两  大枣三十枚  \n上九味，㕮咀，以水一斗，煮取三升，去滓，分三服，日三良。", "白话": "〔主治〕治产后突然心中忡悸，或意志不定、恍恍惚惚、言语错乱，属心虚所致者。〔组成·照录〕茯神四两，人参、茯苓各三两，芍药、甘草、当归、桂心各一两，生姜八两，大枣三十枚。〔方义〕茯神重用安神为君，参、苓益气，归、芍养血，桂心通阳，姜、草、枣和中。〔服法〕上九味切碎，以水一斗煮取三升，去渣，分三次服，一日三次，效果良。"}, {"source": "条22｜《备急千金要方》卷十三·大补心汤", "原文": "《备急千金要方》卷十三：大补心汤。治虚损不足，心气弱悸或时妄语，四肢损变气力，颜色不荣方。  \n黄芩、附子各一两  甘草、茯苓、麦门冬、干地黄、桂心、阿胶各三两  半夏、 远志、石膏各四两  生姜六两  饴糖一斤  大枣二十枚  \n上十四味，取十三味㕮咀，以水一斗五升煮取五升，汤成下糖，分四服。", "白话": "〔主治〕治虚损不足，心气虚弱而悸，或时有妄语，四肢受损、气力减退、面色不荣。〔组成·照录〕黄芩、附子各一两，甘草、茯苓、麦门冬、干地黄、桂心、阿胶各三两，半夏、远志、石膏各四两，生姜六两，饴糖一斤，大枣二十枚。〔方义〕附子、桂心温心阳，地、麦、阿胶滋心阴，远志、茯苓安神，石膏、黄芩清热，饴糖建中，为阴阳并调、寒热兼施之大方。〔服法〕上十四味取十三味切碎（饴糖不入煎），以水一斗五升煮取五升，汤成下饴糖，分四次服。"}, {"source": "条23｜《备急千金要方》卷十四·远志汤", "原文": "《备急千金要方》卷十四：远志汤。治心气虚惊悸善忘不进食补心方。  \n远志、干姜、白术、桂心、黄芪、紫石英各三两  人参、茯苓、甘草、芎、茯神、当归、羌活、防风各二两  麦门冬、半夏各四两  五味子二合  大枣十二枚  \n上十八味，㕮咀，以水一斗三升煮取三升半，分五服，日三夜二。", "白话": "〔主治〕治心气虚惊悸、善忘、不能进食的补心方。〔组成·照录〕远志、干姜、白术、桂心、黄芪、紫石英各三两，人参、茯苓、甘草、芎（川芎）、茯神、当归、羌活、防风各二两，麦门冬、半夏各四两，五味子二合，大枣十二枚。〔方义〕远志、茯神、紫石英镇心安神，参、芪、术、姜益气健脾，归、芎养血，桂心通阳，佐羌活、防风祛风，共成补心定悸之剂。〔服法〕上十八味切碎，以水一斗三升煮取三升半，分五次服，日三次夜两次。"}, {"source": "条24｜《备急千金要方》卷十九·乐令建中汤（附：肾沥汤）", "原文": "《备急千金要方》卷十九：乐令建中汤。治虚劳少气，心胸淡冷，时惊惕，心中悸动，手足逆冷，体常自汗，五脏六腑虚损，肠鸣风湿，营卫不调百病，补诸不足，又治风里急方。  \n黄芪、人参、橘皮、当归、桂心、细辛、前胡、芍药、甘草、茯苓、麦冬各一两  半夏二两半  生姜五两  大枣二十枚  \n上十四味，㕮咀，以水二斗，煮取四升，每服五合，日三夜一。  \n肾沥汤  \n 《备急千金要方》卷十九：肾沥汤。治虚劳损羸乏", "白话": "〔主治〕治虚劳少气，心胸寒冷，时时惊惕，心中悸动，手足逆冷，体常自汗，五脏六腑虚损，肠鸣，风湿，营卫不调百病，补诸不足，又治风里急。〔组成·照录〕黄芪、人参、橘皮、当归、桂心、细辛、前胡、芍药、甘草、茯苓、麦冬各一两，半夏二两半，生姜五两，大枣二十枚。〔方义〕黄芪建中合四君之意，益气建中、调和营卫、兼安心神。〔服法〕上十四味切碎，以水二斗煮取四升，每服五合，日三次夜一次。〔附·肾沥汤〕原稿同条附载：治虚劳瘦弱乏力，咳逆短气，四肢烦痛，腰背相引而痛，耳鸣面色黧黑，骨间发热，小便"}, {"source": "条25｜《千金翼方》卷五·大补内黄芪汤", "原文": "《千金翼方》卷五：大补内黄芪汤。主妇人七伤，骨髓疼，小腹急满，面目黄黑，不能食饮，并诸虚不足，少气心悸不安方。  \n黄芪、半夏各三两，洗  大枣三十枚  干地黄、桂心、人参、茯苓、远志去心、芍药、泽泻、五味子、麦门冬去心、白术、甘草炙，各二两  干姜四两  \n上一十六味，㕮咀，以水一斗半，煮取二升，一服五合，日三夜一。", "白话": "〔主治〕主治妇人七伤，骨髓疼痛，小腹急满，面色黄黑，不能食饮，及诸虚不足、少气、心悸不安。〔组成·照录〕黄芪、半夏（洗）各三两，大枣三十枚，干地黄、桂心、人参、茯苓、远志（去心）、芍药、泽泻、五味子、麦门冬（去心）、白术、甘草（炙）各二两，干姜四两。〔方义〕即《千金要方》内补黄芪汤方意，益气养血、温中安神。〔服法〕上十六味切碎，以水一斗半煮取二升，每服五合，日三次夜一次。"}, {"source": "条26｜《千金翼方》卷七·人参丸", "原文": "《千金翼方》卷七：人参丸。主产后大虚，心悸，志意不安，恍惚不自觉，心中畏恐，夜不得眠，虚烦少气方。  \n人参、茯苓、麦门冬去心、甘草炙，各三两  桂心一两  大枣五十枚，作膏  菖蒲、泽泻、薯蓣、干姜各二两  \n上一十味，捣筛为末，炼蜜枣膏和丸如梧子大。空腹酒下二十丸，日三夜一服，不知稍增至三十丸。若有远志得二两纳之为善。气绝纳当归、独活各三两更善。此方亦治男子虚心悸不定，至良。", "白话": "〔主治〕主治产后大虚，心悸，意志不安，恍惚不自觉，心中畏恐，夜不成眠，虚烦少气。〔组成·照录〕人参、茯苓、麦门冬（去心）、甘草（炙）各三两，桂心一两，大枣五十枚（作膏），菖蒲、泽泻、薯蓣、干姜各二两。〔方义〕益气养心、安神定志，兼温中健脾。〔服法〕上十味捣筛为末，炼蜜枣膏和丸如梧桐子大，空腹酒下二十丸，日三次夜一次，不效稍增至三十丸。〔加减〕若有远志二两加入为善；“气绝”者加当归、独活各三两更佳。此方亦治男子虚心悸不定，至良。"}, {"source": "条27｜《千金翼方》卷七·大远志丸", "原文": "《千金翼方》卷七：大远志丸。主妇人产后心虚不足，心下虚悸，志意不安，时复愦愦，腹中拘急痛，夜卧不安，胸中吸吸少气。药内补伤损，益气，安志定心，主诸虚损方。  \n远志去心、茯苓、桂心、麦门冬去心、泽泻、干姜、人参、当归、独活、阿胶炙、菖蒲、甘草炙、白术各三两  干地黄五两  薯蓣二两  \n上一十五味，捣筛为末，炼蜜和丸如梧子。空腹温酒服二十丸，日三服，不知稍加至三十丸。大虚身体冷少津液，加钟乳三两为", "白话": "〔主治〕主治妇人产后心虚不足，心下虚悸，意志不安，时时昏乱，腹中拘急疼痛，夜卧不安，胸中气短吸吸；功能内补伤损、益气、安志定心，主治诸虚损。〔组成·照录〕远志（去心）、茯苓、桂心、麦门冬（去心）、泽泻、干姜、人参、当归、独活、阿胶（炙）、菖蒲、甘草（炙）、白术各三两，干地黄五两，薯蓣二两。〔方义〕气血双补、安神定志，兼温中健脾。〔服法〕上十五味捣筛为末，炼蜜和丸如梧桐子大，空腹温酒服二十丸，日三次，不效稍加至三十丸。〔加减〕大虚、身体冷、津液少者，加钟乳石三两为好——钟乳益精"}, {"source": "条28｜《千金翼方》卷七·甘草丸", "原文": "《千金翼方》卷七：甘草丸。主妇人产后心虚不足，虚悸少气，心神不安，或若恍恍惚惚不自觉方。  \n甘草三两，炙  人参、泽泻、桂心各一两  大枣五枚、远志去心、茯苓、麦门冬去心、菖蒲、干姜各二两  \n上一十味，捣筛为末，炼蜜和丸如大豆许，酒服二十丸，日四五服，夜二服，不知稍增，若无泽泻，用术代之，若胸中冷增干姜。", "白话": "〔主治〕主治妇人产后心虚不足，虚悸少气，心神不安，或恍恍惚惚不自知觉。〔组成·照录〕甘草（炙）三两，人参、泽泻、桂心各一两，大枣五枚，远志（去心）、茯苓、麦门冬（去心）、菖蒲、干姜各二两。〔方义〕益气养心、安神定志，兼温中化饮。〔服法〕上十味捣筛为末，炼蜜和丸如大豆大，酒服二十丸，日四五次，夜两次，不效稍增。〔加减〕若无泽泻用白术代之；若胸中冷增加干姜。"}, {"source": "条29｜《千金翼方》卷十六·补心汤", "原文": "《千金翼方》卷十六：补心汤。主奄奄忽忽，朝瘥暮剧，惊悸，心中憧憧，胸满不下食饮，阴阳气衰，脾胃不磨，不欲闻人声，定志下气方。  \n人参、茯苓、龙齿炙、当归、远志去心、甘草炙，各三两  桂心、半夏洗，各五两  生姜六两，切  大枣二十枚，擘  黄芪四两  枳实炙、枳梗、茯神各二两半  \n上一十四味，㕮咀，以水一斗二升，先煮粳米五合。令熟，去滓纳药，煮取四升，每服八合，日三，夜二服。", "白话": "〔主治〕主治精神萎靡恍惚、早晨轻晚剧，惊悸，心中悸动不宁，胸满不能进食，阴阳之气衰减，脾胃不能运化，不欲闻人声——功能定志下气。〔组成·照录〕人参、茯苓、龙齿（炙）、当归、远志（去心）、甘草（炙）各三两，桂心、半夏（洗）各五两，生姜六两（切），大枣二十枚（擘），黄芪四两，枳实（炙）、枳梗、茯神各二两半。〔方义〕龙齿、茯神、远志镇心安神，参、芪、苓、草益气，当归养血，桂心、半夏、枳实下气宽胸，先煮粳米护胃。〔服法〕上十四味切碎，以水一斗二升先煮粳米五合令熟，去渣纳药，煮取四升，"}, {"source": "条30｜《外台秘要》卷三十七·麻黄汤", "原文": "《外台秘要》卷三十七：人参动紫石英，令人心急而痛，或惊悸不得卧，或恍惚忘误，失性发狂，或昏昏欲眠，或愦愦喜嗔，或瘥或剧，乍寒乍热，或耳聋目暗，又防风虽不动紫石，而紫石犹动防风，为药中亦有人参，缘防风动人参，转相发动，令人心痛烦热，头项强，才觉发，宜服麻黄汤方。（千金服后人参汤）  \n麻黄二两，去节  人参一两  甘草二两，炙  葱白切，一升  豉一升  大麦奴一把  \n上六味切，以酒五升汤三升，煮", "白话": "〔主治〕人参能引动紫石英，使人心胸急痛，或惊悸不得卧，或恍惚健忘错乱、失性发狂，或昏昏欲睡，或心中昏乱而易怒，或轻或重，忽冷忽热，或耳聋目暗；又防风虽不引动紫石英，而紫石英犹能引动防风，药中又有人参，因防风引动人参，辗转相发动，使人心痛烦热、头项强急——才觉发作，即宜服麻黄汤。（原稿注：《千金》作“服后人参汤”）〔组成·照录〕麻黄（去节）二两、人参一两、甘草（炙）二两、葱白（切）一升、豉一升、大麦奴一把。〔方义〕麻黄、葱白、豆豉发越郁热，人参、甘草扶正，大麦奴解毒除烦，为药对"}, {"source": "条31｜《太平圣惠方》卷四·远志丸", "原文": "《太平圣惠方》卷四：治心气不足，惊悸多忘，宜服远志丸方。  \n远志一两，去心  麦门冬一两，去心，焙  赤石脂一两  熟干地黄一两  人参一两，去芦头  茯神一两  甘草半两，炙微赤，锉  白术一（三）分 薯蓣一两  \n上件药，捣罗为末，炼蜜和捣一、二百杵，丸如梧桐子大。每于食后，以清粥饮下三十丸。", "白话": "〔主治〕治心气不足，惊悸多忘，宜服远志丸。〔组成·照录〕远志（去心）一两、麦门冬（去心，焙）一两、赤石脂一两、熟干地黄一两、人参（去芦头）一两、茯神一两、甘草（炙微赤，锉）半两、白术一（三）分、薯蓣一两。〔方义〕远志、茯神安神益智，参、术、薯蓣、甘草益气，地、麦滋阴，赤石脂收涩，为补心安神之丸。〔服法〕上药捣罗为末，炼蜜和捣一二百杵，丸如梧桐子大，每于食后以清粥饮下三十丸。"}, {"source": "条32｜《太平圣惠方》卷四·熟干地黄散", "原文": "《太平圣惠方》卷四：治心气不足，恍恍惚惚，朝差暮甚，惊悸，心中憧憧，胸满，不下食饮，阴阳气虚，脾胃不磨，不欲闻人声，宜服熟干地黄散方。  \n熟干地黄一两  当归一两，锉，微炒  龙骨一两  人参一两，去芦头  甘草一两，炙微赤，锉  桔梗一两，去芦头  黄芪二两，锉  桂心一两  半夏三分，汤洗七遍，去滑  茯神一两  远志半两，去心  枳壳一两，麸炒微黄，去瓤  白术半两  \n上件药，捣粗罗为散", "白话": "〔主治〕治心气不足，恍恍惚惚，早晨轻晚甚，惊悸，心中悸动不宁，胸满不能进食，阴阳气虚，脾胃不能运化，不欲闻人声。〔组成·照录〕熟干地黄一两、当归（锉，微炒）一两、龙骨一两、人参（去芦头）一两、甘草（炙微赤，锉）一两、桔梗（去芦头）一两、黄芪（锉）二两、桂心一两、半夏（汤洗七遍，去滑）三分、茯神一两、远志（去心）半两、枳壳（麸炒微黄，去瓤）一两、白术半两。〔方义〕熟地、当归养血，参、芪、术、草益气，龙骨、茯神、远志镇心安神，桂心通阳，半夏、枳壳、桔梗宽胸下气。〔服法〕上药捣粗罗"}, {"source": "条33｜《圣济总录》卷三十一·人参茯神汤", "原文": "《圣济总录》卷三十一：治伤寒后心虚惊悸，恍惚不宁，人参茯神汤方。  \n人参、茯神去木，各一两  陈橘皮汤浸，去白，焙，三分  杏仁汤浸，去皮尖，双仁，炒，一分  \n上四味，粗捣筛，每服三钱匕，水一盏，入生姜半分拍碎，同煎至半盏，去滓温服。", "白话": "〔主治〕治伤寒后心虚惊悸、恍惚不宁。〔组成·照录〕人参、茯神（去木）各一两，陈橘皮（汤浸，去白，焙）三分，杏仁（汤浸，去皮尖、双仁，炒）一分。〔方义〕人参益心气，茯神安神定志，陈皮理气和中，杏仁降气润肺，药少力专。〔服法〕上四味粗捣筛，每服三钱匕，水一盏加生姜半分拍碎，同煎至半盏，去渣温服。"}, {"source": "条34｜《圣济总录》卷三十一·麦门冬汤", "原文": "《圣济总录》卷三十一：治伤寒后心虚忪悸，麦门冬汤方。  \n麦门冬去心，焙、茯神去木、菊花、人参各一两  甘草炙，半两  \n上五味，粗捣筛，每服三钱匕，水一盏，煎至半盏，去滓温服。", "白话": "〔主治〕治伤寒后心虚忪悸。〔组成·照录〕麦门冬（去心，焙）、茯神（去木）、菊花、人参各一两，甘草（炙）半两。〔方义〕麦冬滋心阴，茯神安神，人参、甘草益气，菊花清利头目，为养心清润之剂。〔服法〕上五味粗捣筛，每服三钱匕，水一盏煎至半盏，去渣温服。"}, {"source": "条35｜《圣济总录》卷三十一·茯神丸", "原文": "《圣济总录》卷三十一：伤后治寒，或用心力劳倦，四肢羸弱，心忪惊悸，吸吸短气，补虚。茯神丸方。  \n茯神去木、麦门冬去心，焙  熟干地黄焙，各一两  牡丹皮、人参、黄芪锉，各三分  桂去粗皮、甘草炙、牛膝去苗、泽泻各半两  \n上一十味，捣罗为末，炼蜜和捣三五百杵，丸如梧桐子大，食前温酒下二十丸。", "白话": "〔主治〕伤寒之后（原稿作“伤后治寒”），或用心力劳倦，四肢瘦弱，心忪惊悸，气短吸吸，功能补虚。〔组成·照录〕茯神（去木）、麦门冬（去心，焙）、熟干地黄（焙）各一两，牡丹皮、人参、黄芪（锉）各三分，桂（去粗皮）、甘草（炙）、牛膝（去苗）、泽泻各半两。〔方义〕茯神、麦冬、熟地养心滋阴，参、芪、草益气，丹皮清虚热，桂通阳，牛膝、泽泻引浊下行。〔服法〕上十味捣罗为末，炼蜜和捣三五百杵，丸如梧桐子大，食前温酒下二十丸。"}, {"source": "条36｜《圣济总录》卷八十六·补心麦门冬丸", "原文": "《圣济总录》卷八十六：治心劳多惊悸，心气不足，补心麦门冬丸方。  \n麦门冬去心，焙，一两半  石菖蒲一两  远志去心，一两半  人参一两  白茯苓去黑皮，一两  熟干地黄一两半  桂去粗皮，半两  天门冬心去，焙，一两半  黄连去须，一两半  升麻一两半  \n上一十味，捣罗为末，炼蜜为丸，如梧桐子大，每日食后夜卧时，用熟水下二十丸，兼开心气，使人多记不忘。", "白话": "〔主治〕治心劳（心脏劳损）而多惊悸、心气不足。〔组成·照录〕麦门冬（去心，焙）一两半、石菖蒲一两、远志（去心）一两半、人参一两、白茯苓（去黑皮）一两、熟干地黄一两半、桂（去粗皮）半两、天门冬（去心，焙）一两半、黄连（去须）一两半、升麻一两半。〔方义〕二冬、地黄滋阴，参、苓益气，菖蒲、远志开心气安心神，黄连清心，桂通阳，升麻升举清阳。〔服法〕上十味捣罗为末，炼蜜为丸如梧桐子大，每日食后及夜卧时用熟水下二十丸；兼能开宣心气，使人多记不忘。"}, {"source": "条37｜《圣济总录》卷八十六·肉苁蓉丸", "原文": "《圣济总录》卷八十六：治肾劳心忪乏力，夜多梦泄，肌瘦发热，口内生疮，脐腹冷痛，肉苁蓉丸方。  \n肉苁蓉酒浸，切，焙，一两、巴戟天去心、石槲去根，各半两  牛膝酒浸、切焙、附子炮裂，去皮脐、羌活去芦头，各一两  桔梗炒、远志去心、萆薢、独活去芦头、枳壳去瓤麸炒、黄芪锉，各半两  熟干地黄焙、当归切，焙，各一两 海桐皮锉，一分  \n上一十五味，捣罗为末，炼蜜和丸，如梧桐子大，每服二十丸，米饮或温酒下，", "白话": "〔主治〕治肾劳而心忪乏力，夜间多梦遗精，肌肉消瘦发热，口内生疮，脐腹冷痛。〔组成·照录〕肉苁蓉（酒浸，切，焙）一两、巴戟天（去心）、石槲（去根）各半两、牛膝（酒浸，切，焙）、附子（炮裂，去皮脐）、羌活（去芦头）各一两、桔梗（炒）、远志（去心）、萆薢、独活（去芦头）、枳壳（去瓤，麸炒）、黄芪（锉）各半两、熟干地黄（焙）、当归（切，焙）各一两、海桐皮（锉）一分。〔方义〕苁蓉、巴戟、附子温肾益精，地、归养血，远志安神，芪益气，牛膝、萆薢强腰膝，为温肾固精、养心定悸之方。〔服法〕上十"}, {"source": "条38｜《圣济总录》卷八十七·黄芪汤", "原文": "《圣济总录》卷八十七：治热劳、肢节酸疼，吸吸少气，腰背强痛，心中虚悸，咽干唇赤，面色枯燥，饮食无味，悲忧惨戚，多睡少起，黄芪汤方。  \n黄芪锉，焙 地骨皮各一两  鳖甲一枚，去裙襴涂醋炙黄  甘草半两，炙，锉  麦门冬去心，焙，一两半  桂去粗皮，半两  \n上六味，粗捣筛，每服五钱匕，水一盏半，生姜半分拍破，粳米五十粒，煎至八分，去滓食前温服。", "白话": "〔主治〕治热劳，肢节酸疼，气短吸吸，腰背强痛，心中虚悸，咽干唇红，面色枯燥，饮食无味，悲忧凄惨，多睡少起。〔组成·照录〕黄芪（锉，焙）、地骨皮各一两，鳖甲一枚（去裙襴，涂醋炙黄），甘草（炙，锉）半两，麦门冬（去心，焙）一两半，桂（去粗皮）半两。〔方义〕黄芪、甘草益气，鳖甲、地骨皮清虚热，麦冬滋阴，桂通阳，为清补虚劳之剂。〔服法〕上六味粗捣筛，每服五钱匕，水一盏半加生姜半分拍破、粳米五十粒，煎至八分去渣，食前温服。"}, {"source": "条39｜《圣济总录》卷九十·补心麦门冬丸", "原文": "《圣济总录》卷九十：治虚劳惊悸，心气不足，补心麦门冬丸方。  \n麦门冬去心，焙，一两半  菖蒲石上者、远志去心、人参、白茯苓去黑皮，各一两  熟干地黄焙，一两半  桂去粗皮，半两  天门冬去心，焙、黄连去须、升麻各一两  \n上一十味，捣罗为末，炼蜜为丸，如梧桐子大。每服早食后及夜卧时，用熟水下二十丸。", "白话": "〔主治〕治虚劳惊悸、心气不足。〔组成·照录〕麦门冬（去心，焙）一两半、石上菖蒲、远志（去心）、人参、白茯苓（去黑皮）各一两、熟干地黄（焙）一两半、桂（去粗皮）半两、天门冬（去心，焙）、黄连（去须）、升麻各一两。〔方义〕与卷八十六补心麦门冬丸同方，滋阴益气、开心安神。〔服法〕上十味捣罗为末，炼蜜为丸如梧桐子大，每于早食后及夜卧时用熟水下二十丸。"}, {"source": "条40｜《圣济总录》卷九十·柴胡汤", "原文": "《圣济总录》卷九十：治虚劳羸瘦，心虚惊悸，气乏力劣等，柴胡汤方。  \n柴胡去苗，三分  黄芪锉，一两  厚朴去粗皮，涂生姜汁，炙  半夏汤洗去滑焙干，各三分  人参 白茯苓去黑皮 防风去叉 细辛去苗叶，各半两  当归切，焙 麦门冬去心，焙，各二两  陈橘皮汤浸，去白，焙、甘草炙，焙、杏仁汤浸去皮尖，双仁，别研、槟榔各半两  \n上一十四味，粗捣筛。每服五钱匕，水一盏半，入生姜一分切碎，煎至一盏，去滓", "白话": "〔主治〕治虚劳瘦弱，心虚惊悸，气短乏力等。〔组成·照录〕柴胡（去苗）三分、黄芪（锉）一两、厚朴（去粗皮，涂生姜汁炙）、半夏（汤洗去滑，焙干）各三分、人参、白茯苓（去黑皮）、防风（去叉）、细辛（去苗叶）各半两、当归（切，焙）、麦门冬（去心，焙）各二两、陈橘皮（汤浸，去白，焙）、甘草（炙，焙）、杏仁（汤浸，去皮尖、双仁，别研）、槟榔各半两。〔方义〕柴胡、防风疏达，参、芪、苓、草益气，归、麦养血滋阴，陈皮、厚朴、槟榔理气，为虚劳调补兼疏之方。〔服法〕上十四味粗捣筛，每服五钱匕，水一"}, {"source": "条41｜《圣济总录》卷九十一·枸杞汤", "原文": "《圣济总录》卷九十一：治虚劳骨肉酸疼，吸吸少气，少腹拘急，腰背强痛，心中虚悸，咽干唇燥，面无颜色，饮食无味，阴阳废弱，悲忧惨戚，多卧少起，枸杞汤方。  \n枸杞根锉、黄芪锉，各三分  甘草炙，锉、麦门冬去心，焙、桂去粗皮，各半两  \n上五味，粗捣筛，每服五钱匕，水一盏半，生姜一枣大切，粳米一匙，煎至一盏，去滓温服，空心夜卧各一。", "白话": "〔主治〕治虚劳骨肉酸疼，气短吸吸，少腹拘急，腰背强痛，心中虚悸，咽干唇燥，面无颜色，饮食无味，阴阳虚弱，悲忧凄惨，多卧少起。〔组成·照录〕枸杞根（锉）、黄芪（锉）各三分，甘草（炙，锉）、麦门冬（去心，焙）、桂（去粗皮）各半两。〔方义〕枸杞根（地骨皮）清虚热，黄芪、甘草益气，麦冬滋阴，桂通阳，为清补虚劳之剂。〔服法〕上五味粗捣筛，每服五钱匕，水一盏半加生姜一枣大切、粳米一匙，煎至一盏去渣温服，空腹、夜卧各一次。"}, {"source": "条42｜《圣济总录》卷九十一·黄芪汤", "原文": "《圣济总录》卷九十一：治大虚不足，小腹里急，气上冲胸，口舌干燥，短气烦悸，言语谬误，不能饮食，吸吸少气，黄芪汤方。  \n黄芪锉，三两  半夏汤洗去滑，姜汁制，五两  甘草炙，锉、人参、芍药各二两  桂去粗皮，一两  \n上六味，粗捣筛，每服三钱匕，水一盏，生姜半分切，枣二枚劈破，煎至七分，去滓温服，空心日午夜卧各一，手足寒加附子，炮去皮脐一两。", "白话": "〔主治〕治大虚不足，小腹里急，气上冲胸，口舌干燥，短气烦悸，言语错乱，不能饮食，气短吸吸。〔组成·照录〕黄芪（锉）三两、半夏（汤洗去滑，姜汁制）五两、甘草（炙，锉）、人参、芍药各二两、桂（去粗皮）一两。〔方义〕黄芪、人参、甘草益气，芍药缓急，桂通阳降冲，半夏化痰降逆。〔服法〕上六味粗捣筛，每服三钱匕，水一盏加生姜半分切、大枣二枚劈破，煎至七分去渣温服，空腹、日午、夜卧各一次。〔加减〕手足寒冷加附子（炮去皮脐）一两。"}, {"source": "条43｜《圣济总录》卷一百六十三·麦门冬汤", "原文": "《圣济总录》卷一百六十三：治产后心虚惊悸，恍惚不安。麦门冬汤方。  \n麦门冬去心，焙，半两  熟干地黄焙，一两  白茯苓去黑皮、甘草炙，锉，各一两  芍药锉，一两  \n上五味，粗捣筛，每服三钱匕，水一盏，入生姜五片，枣一枚擘破，煎至七分，去滓温服，不拘时候。", "白话": "〔主治〕治产后心虚惊悸、恍惚不安。〔组成·照录〕麦门冬（去心，焙）半两、熟干地黄（焙）一两、白茯苓（去黑皮）、甘草（炙，锉）各一两、芍药（锉）一两。〔方义〕麦冬、熟地滋阴养血，茯苓安神，芍药和血缓急，甘草和中，为产后养心之剂。〔服法〕上五味粗捣筛，每服三钱匕，水一盏加生姜五片、大枣一枚擘破，煎至七分去渣温服，不拘时候。"}, {"source": "条44｜《圣济总录》卷一百六十四·茯苓汤", "原文": "《圣济总录》卷一百六十四：治产后虚汗不止，心悸恍惚，怵惕多惊，茯苓汤方。  \n白茯苓去黑皮，一两半  甘草炙黄，一两  芍药锉，炒，一两  桂去粗皮，一两  当归切，炒，一两  麦门冬去心，焙，一两  黄芪一两半，锉  \n上七味，粗捣筛，每服五钱匕，水一盏半，入生姜半分切，枣二枚擘，煎至八分。去滓温服，不拘时。", "白话": "〔主治〕治产后虚汗不止，心悸恍惚，时时惊恐。〔组成·照录〕白茯苓（去黑皮）一两半、甘草（炙黄）一两、芍药（锉，炒）一两、桂（去粗皮）一两、当归（切，炒）一两、麦门冬（去心，焙）一两、黄芪（锉）一两半。〔方义〕黄芪、甘草益气固表止汗，归、芍养血，麦冬滋阴，茯苓安神，桂通阳。〔服法〕上七味粗捣筛，每服五钱匕，水一盏半加生姜半分切、大枣二枚擘，煎至八分去渣温服，不拘时。"}, {"source": "条45｜《圣济总录》卷一百七十二·退疳丸", "原文": "《圣济总录》卷一百七十二：治小儿惊疳，心忪惊悸。面黄肌瘦，口舌生疮，多困目涩，退疳丸方。  \n胡黄连、黄连去须、大黄各半钱、陈橘皮汤浸，去白焙、苦楝根各一分，五味同为末，用猪胆汁和药却入胆内线缝定，水二碗煮水尽取药出  青黛研、使君子去壳、丹砂研、芦荟研，各一分  麝香研，半钱  \n上一十味，将后五味别研为末，用前猪胆内药和匀为丸，如绿豆大，每服十丸，米饮下。不拘时候，量儿大小加减。", "白话": "〔主治〕治小儿惊疳，心忪惊悸，面黄肌瘦，口舌生疮，多困倦、眼睛干涩。〔组成·照录〕胡黄连、黄连（去须）、大黄各半钱，陈橘皮（汤浸，去白，焙）、苦楝根各一分——五味同为末，用猪胆汁和药，再纳入猪胆内以线缝定，水二碗煮至水尽取出药；青黛（研）、使君子（去壳）、丹砂（研）、芦荟（研）各一分，麝香（研）半钱。〔方义〕二连、青黛清心肝疳热，大黄、芦荟泻下消积，使君子、苦楝根杀虫，猪胆汁为引，为小儿疳积惊悸之方。〔服法〕上十味，后五味别研为末，与猪胆内药和匀为丸如绿豆大，每服十丸，米饮下"}, {"source": "条46｜《圣济总录》卷一百九十·脯鸡糁", "原文": "《圣济总录》卷一百九十：治产后心虚忪悸，遍身疼痛，脯鸡糁方。  \n黄雌鸡一只，去毛头足肠胃净洗，以小麦两合、以水五升煮鸡半熟即取出鸡去骨  蜀椒去目并闭口炒汗出取末，一钱  柴胡去苗，二钱  干姜末半钱  粳米三合  \n上五味，先取水再煮鸡及米令烂，入葱薤椒姜柴胡末等，次又入五味盐酱，煮取熟，任意食之。", "白话": "〔主治〕治产后心虚忪悸、遍身疼痛。〔组成·照录〕黄雌鸡一只（去毛、头、足、肠胃，洗净，加小麦两合，以水五升煮至半熟即取出鸡去骨），蜀椒（去目及闭口者，炒至汗出取末）一钱，柴胡（去苗）二钱，干姜末半钱，粳米三合。〔方义〕黄雌鸡、粳米、小麦补虚养血，干姜、蜀椒温中，柴胡疏达，为食疗补虚之方。〔服法〕上五味，先取水再煮鸡及米令烂，加入葱、薤、椒、姜、柴胡末等，再加入五味、盐、酱，煮熟任意食之。"}, {"source": "条47｜《太平惠民和剂局方》卷九·人参鳖甲丸", "原文": "《太平惠民和剂局方》卷九：人参鳖甲丸。治妇人一切虚损，肌肉瘦瘁，盗汗心忪，咳嗽上气，经脉不调，或作寒热，不思饮食。  \n杏仁汤浸，去皮、尖，炒、人参、当归洗，焙、赤芍药、甘草炙、柴胡去苗、桔梗去芦，各一两  地骨皮、宣黄连去须、胡黄连各一分  肉桂去粗皮、木香各半两  麝香别研，半分  鳖甲一枚，可重二两者，醋炙黄色为度  \n上为细末，用青蒿一斤，研烂，绞取汁，童子小便五升，酒五升，同熬至二升以来", "白话": "〔主治〕治妇人一切虚损，肌肉消瘦，盗汗心忪，咳嗽气上逆，月经不调，或发寒热，不思饮食。〔组成·照录〕杏仁（汤浸，去皮、尖，炒）、人参、当归（洗，焙）、赤芍药、甘草（炙）、柴胡（去苗）、桔梗（去芦）各一两，地骨皮、宣黄连（去须）、胡黄连各一分，肉桂（去粗皮）、木香各半两，麝香（别研）半分，鳖甲一枚（约重二两，醋炙黄色为度）。〔方义〕参、归、芍、草益气养血，鳖甲、地骨皮、青蒿清虚热，柴胡、桔梗、杏仁宣肺止咳，为虚劳咳嗽、盗汗心忪之方。〔制法·服法〕上为细末；用青蒿一斤研烂绞汁，加"}, {"source": "条48｜《太平惠民和剂局方（附：指南总论）》卷下·黄芪建中汤", "原文": "《太平惠民和剂局方（附：指南总论）》卷下虚汗、盗汗，心忪气短者，可与牡蛎散、止汗散、黄芪建中汤、大山药丸、人参当归散加小麦煎服。自汗不止者，术附汤、正元散。心热盗汗，可与辰砂妙香散。", "白话": "〔主治〕《局方·指南总论》卷下论虚汗、盗汗、心忪气短者，可给与牡蛎散、止汗散、黄芪建中汤、大山药丸、人参当归散加小麦煎服；自汗不止者，用术附汤、正元散；心热盗汗者，可给与辰砂妙香散。〔方义〕黄芪建中汤温中补虚、和里缓急，为虚劳里急、自汗心悸之要方。〔组成·服法〕原稿此处仅存方名与选方叙录，未载组成服法，参见《金匮要略》黄芪建中汤（黄芪、桂枝、芍药、甘草、生姜、大枣、饴糖）。"}, {"source": "条49｜《杨氏家藏方》卷九·还少丸", "原文": "《杨氏家藏方》卷九：还少丸。大补本气虚损，及脾胃怯弱，心忪恍惚，精神昏愦，气血凝滞，饮食无味，肌瘦体倦，目暗耳聋。  \n干山药一两半  牛膝酒浸一宿，焙干，一两半  白茯苓去皮、山茱萸、楮实、杜仲去粗皮，生姜汁和酒炙令香熟、五味子、巴戟去心、肉苁蓉酒浸一宿，切、焙干、远志去心、茴香九味各一两  石菖蒲、熟干地黄洗焙、枸杞子三味各半两  \n上件为细末，炼蜜入蒸熟、去皮核枣肉和匀，丸如梧桐子大。每服五", "白话": "〔主治〕大补元气虚损及脾胃怯弱，治心忪恍惚、精神昏乱、气血凝滞、饮食无味、肌肉消瘦、肢体倦怠、目暗耳聋。〔组成·照录〕干山药一两半、牛膝（酒浸一宿，焙干）一两半、白茯苓（去皮）、山茱萸、楮实、杜仲（去粗皮，生姜汁和酒炙令香熟）、五味子、巴戟（去心）、肉苁蓉（酒浸一宿，切，焙干）、远志（去心）、茴香九味各一两，石菖蒲、熟干地黄（洗，焙）、枸杞子三味各半两。〔方义〕山药、茯苓、地黄、山萸、枸杞平补脾肾，苁蓉、巴戟、茴香温肾，远志、菖蒲开心益智，为平补阴阳之剂。〔服法〕上件为细末，"}, {"source": "条50｜《杨氏家藏方》卷十·四味补心丸", "原文": "《杨氏家藏方》卷十：四味补心丸。益血补心，安神定志。治怔忪惊悸，恍惚健忘。  \n当归酒洗焙干，二两  朱砂一两，别研  肉苁蓉酒浸一宿，焙干，二两  杏仁一百五十枚，汤泡去皮尖，研成膏  \n上件为细末，以杏仁膏同和，如干，以浸药酒煮薄糊添和，杵千余下，丸如绿豆大。每服三十丸，用米饮或温酒下，不拘时候。", "白话": "〔功能·主治〕益血补心、安神定志，治怔忪惊悸、恍惚健忘。〔组成·照录〕当归（酒洗，焙干）二两、朱砂一两（别研）、肉苁蓉（酒浸一宿，焙干）二两、杏仁一百五十枚（汤泡去皮尖，研成膏）。〔方义〕当归、苁蓉益血补心，朱砂镇心安神，杏仁膏润养，四味成方。〔制法·服法〕上件为细末，以杏仁膏同和；若干，以浸药酒煮薄糊添和，杵千余下，丸如绿豆大，每服三十丸，米饮或温酒下，不拘时候。"}, {"source": "条51｜《杨氏家藏方》卷十·养心丸", "原文": "《杨氏家藏方》卷十：养心丸。治忧思太过，健忘怔忪，睡多恐惕，梦涉峻危，自汗不止，五心烦热，目涩昏倦，梦寐失精，口苦舌干，日渐羸瘦，全不思食。  \n茯神去木、人参去芦头、绵黄芪蜜炙、酸枣仁去皮称，别研成膏，以上四味各一两熟干地黄洗焙、远志去心、五味子、柏子仁别研成膏，以上四味各半两  朱砂三分，研细水飞  \n上件为细末，入二膏和匀研细，炼蜜为丸如梧桐子大。每服五十丸，食后、临卧，浓煎人参汤送下。", "白话": "〔主治〕治忧思太过，健忘怔忪，睡眠中多恐惧惊惕，梦涉险境，自汗不止，五心烦热，目涩昏倦，梦中失精，口苦舌干，日渐消瘦，全不思饮食。〔组成·照录〕茯神（去木）、人参（去芦头）、绵黄芪（蜜炙）、酸枣仁（去皮，称，别研成膏）以上四味各一两；熟干地黄（洗，焙）、远志（去心）、五味子、柏子仁（别研成膏）以上四味各半两；朱砂三分（研细水飞）。〔方义〕茯神、枣仁、柏子仁养心安神，参、芪益气，地、味滋阴敛阴，朱砂镇心，为养心安神之丸。〔制法·服法〕上件为细末，加入二膏和匀研细，炼蜜为丸如梧桐"}, {"source": "条52｜《杨氏家藏方》卷十五·养荣汤", "原文": "《杨氏家藏方》卷十五：养荣汤。治妇人血海虚弱，气不升降，心忪恍惚，时多惊悸，或发虚热，经候不调，可进饮食。  \n白芍药、川芎、熟干地黄洗焙、当归酒浸一宿，焙干、青橘皮去白、姜黄、牡丹皮、海桐皮、五加皮、香白芷以上十味各半两  牛膝酒浸一宿，焙干、延胡索、没药别研、五灵脂去砂石、肉桂去粗皮，以上五味各一分  \n上件㕮咀。每服五钱，水一盏半，生姜五片，乌梅一枚，煎至一盏，去滓温服，不拘时候。", "白话": "〔主治〕治妇人血海虚弱，气机升降失常，心忪恍惚，时时惊悸，或发虚热，月经不调，饮食尚可。〔组成·照录〕白芍药、川芎、熟干地黄（洗，焙）、当归（酒浸一宿，焙干）、青橘皮（去白）、姜黄、牡丹皮、海桐皮、五加皮、香白芷以上十味各半两；牛膝（酒浸一宿，焙干）、延胡索、没药（别研）、五灵脂（去砂石）、肉桂（去粗皮）以上五味各一分。〔方义〕四物养血调经，青皮、姜黄、延胡、没药、五灵脂行气活血，肉桂温通，为养血行血、宁心定悸之方。〔服法〕上件切碎，每服五钱，水一盏半加生姜五片、乌梅一枚，煎"}, {"source": "条53｜《叶氏录验方》中卷·养心丹", "原文": "《叶氏录验方》中卷：养心丹。益心强志，安心肾，使水火通交，阴阳既济，除恍惚惊悸。  \n通明辰砂成块者二两，用生绢袋子盛定，用无灰酒两碗半悬台浸七日。然后用银石器内慢火煮，令九分干，用井水浸一宿，研成膏子、通明乳香酒人参汤研如粉，入在朱砂膏同研，各半两  茯神一两半  人参拣末一两半，都入朱砂乳香膏内研  \n上和令匀，入猪羊心血合成丸，如小鸡头大。每服三两粒至十粒，煎人参炒酸枣仁汤化服。食后，临卧服", "白话": "〔功能·主治〕益心强志，安定心肾，使水火相交、阴阳既济，除恍惚惊悸。〔组成·照录〕通明辰砂成块者二两（用生绢袋盛定，以无灰酒两碗半悬浸七日，然后用银石器慢火煮至九分干，再用井水浸一宿，研成膏子）；通明乳香（用酒、人参汤研如粉）各半两；茯神一两半；人参拣末一两半（都入朱砂、乳香膏内同研）。〔方义〕辰砂重镇安神，乳香行气活血，茯神、人参养心益气，为镇心养心之丹。〔制法·服法〕上药和匀，加入猪、羊心血合成丸如小鸡头大，每服三至十粒，用煎人参炒酸枣仁汤化服，食后、临卧服。"}, {"source": "条54｜《是斋百一选方》卷一·无名方", "原文": "《是斋百一选方》卷一：昆山神济大师方，献张魏公丞相，韩子常知府阁中服之有效。  \n猪腰子一只，用水两碗煮至一盏半，将腰子细切，入人参半两，当归上去芦，下去细者，取中段半两，并切，同煎至八分，吃腰子，以汁送下。有吃不尽腰子，同上二味药滓焙干，为细末，山药糊丸如梧桐子大。每服三、五十丸。此药多服为佳。平江医者丁御干为葛枢密云：此药本治心气怔忡而自汗者，不过一二服即愈，盖奇药也！", "白话": "〔出处〕昆山神济大师方，献于张魏公丞相，韩子常知府服用有效。〔组成·照录〕猪腰子一只（用水两碗煮至一盏半，将腰子细切），人参半两，当归取中段半两（上段去芦头，下段细小者不用，切）。〔方义〕猪腰补肾，参、归益气养血，为食药并用之补虚方。〔服法〕同煎至八分，吃腰子、以药汁送下；若腰子吃不完，与上二味药渣一同焙干研为细末，山药糊丸如梧桐子大，每服三十至五十丸。此药多服为佳。平江医者丁御干对葛枢密说：此药本治心气怔忡而自汗者，不过一二服即愈，真是奇药！"}, {"source": "条55｜《活人事证方后集》卷二·震灵丹", "原文": "《活人事证方后集》卷二：震灵丹。治气虚心疾。盖心药多性寒，服之令人腹痛，饮食减少。此药治怔忡，恍惚健忘，睡卧不安。益心进食，补虚去冷。  张承节传授此方，用之无不效验。  \n以局方震灵丹，不拘多少，重研细，用灯芯、麝香少许煮北枣，去核、皮。  \n研细搜圆，如桐子大，每服三十圆。食空，枣汤或人参汤下。此丹不犯金石、飞走有性之药，不僭不燥，夺造化冲和之功。大治男子真元衰惫，五劳七伤等疾。", "白话": "〔方名〕震灵丹。〔主治〕治气虚心疾——盖治心之药多性寒，服之令人腹痛、饮食减少；此药治怔忡、恍惚健忘、睡卧不安，能益心进食、补虚去冷。张承节传授此方，用之无不效验。〔组成·制法·照录〕以《局方》震灵丹不拘多少，重新研细；用灯芯、麝香少许煮北枣，去核、皮。〔方义〕取《局方》震灵丹温补固涩，佐以枣肉和丸，避金石燥烈之性，得冲和补虚之用。〔服法〕研细和丸如梧桐子大，每服三十丸，空腹（食空）以枣汤或人参汤下。〔宜忌〕此丹不用金石、飞走有性之药，不燥不烈，得造化冲和之功；大治男子真元衰"}, {"source": "条56｜《妇人大全良方》卷十九·茯苓散", "原文": "《妇人大全良方》卷十九：茯苓散。疗产后心虚，忪悸不定，乱语错误，精神恍惚不主，当由心虚所致。  \n人参、甘草、芍药、当归、生姜各八分  远志、茯苓各十分  桂心六分  麦门冬、大枣各十二分  \n上为散，以水八升，煮取三升，去滓，温分三服。", "白话": "〔主治〕治产后心虚，忪悸不定，言语错乱，精神恍惚不能自主——当由心虚所致。〔组成·照录〕人参、甘草、芍药、当归、生姜各八分，远志、茯苓各十分，桂心六分，麦门冬、大枣各十二分。〔方义〕茯苓、远志安神定志，参、草益气，归、芍养血，麦冬滋阴，桂心通阳，姜枣和中。〔服法〕上为散，以水八升煮取三升，去渣，温分三服。"}, {"source": "条57｜《校注妇人良方》卷三·茯神散", "原文": "《校注妇人良方》卷三：茯神散。治五脏气血虚弱，惊悸怔忡，宜用此安神定志。  \n茯神去木、人参、龙齿另研、独活、酸枣仁炒，各三钱  防风、远志去心、桂心、细辛、白薇炒，各三钱  甘草、干姜炮，各三两  \n上为末，每服四五钱，水煎服。或蜜为丸服。", "白话": "〔主治〕治五脏气血虚弱，惊悸怔忡，宜用此安神定志。〔组成·照录〕茯神（去木）、人参、龙齿（另研）、独活、酸枣仁（炒）各三钱，防风、远志（去心）、桂心、细辛、白薇（炒）各三钱，甘草、干姜（炮）各三两。〔方义〕茯神、龙齿、枣仁、远志镇心安神，参、草益气，桂心、干姜温阳，防风、独活、细辛、白薇疏散风邪。〔服法〕上为末，每服四五钱，水煎服；或炼蜜为丸服。"}, {"source": "条58｜《校注妇人良方》卷三·养心汤", "原文": "《校注妇人良方》卷三：养心汤。治心血虚，惊悸怔忡不宁，或盗汗无寐，发热烦躁。  \n黄芪炒、白茯苓、茯神去木、半夏曲、当归酒拌、川芎各半两  辣桂去皮、柏子仁、酸枣仁炒、五味子杵炒、人参各三钱  甘草炙，四钱  \n上每服三五钱，姜枣水煎。", "白话": "〔主治〕治心血虚，惊悸怔忡不宁，或盗汗、失眠、发热烦躁。〔组成·照录〕黄芪（炒）、白茯苓、茯神（去木）、半夏曲、当归（酒拌）、川芎各半两，辣桂（去皮）、柏子仁、酸枣仁（炒）、五味子（杵炒）、人参各三钱，甘草（炙）四钱。〔方义〕参、芪、苓、草益气，归、芎养血，茯神、柏子仁、枣仁养心安神，五味敛阴，肉桂温阳，半夏曲和胃，为通行之养心汤。〔服法〕上药每服三五钱，姜枣水煎。"}, {"source": "条59｜《校注妇人良方》卷二十四·归脾汤", "原文": "《校注妇人良方》卷二十四：归脾汤。治脾经失血少寐，发热盗汗；或思虑伤脾，不能摄血，以致妄行；或健忘怔忡，惊悸不寐；或心脾伤痛，嗜卧少食；或忧思伤脾，血虚发热；或肢体作痛，大便不调；或经候不准，晡热内热；或瘰疬流注，不能消散溃敛。  \n人参、白术炒、黄芪炒、白茯苓、龙眼肉、当归、远志、酸枣仁炒，各一钱  木香、甘草炙，各五分  \n上姜枣水煎服。。", "白话": "〔主治〕治脾经失血、失眠、发热盗汗；或思虑伤脾，不能摄血而妄行；或健忘怔忡、惊悸不寐；或心脾伤痛、嗜卧少食；或忧思伤脾、血虚发热；或肢体疼痛、大便不调；或月经不准、午后潮热内热；或瘰疬流注，不能消散收敛。〔组成·照录〕人参、白术（炒）、黄芪（炒）、白茯苓、龙眼肉、当归、远志、酸枣仁（炒）各一钱，木香、甘草（炙）各五分。〔方义〕参、术、芪、苓、草健脾益气，龙眼、当归养血，远志、枣仁安神，木香理气醒脾，为益气补血、健脾养心之名方。〔服法〕上药加生姜、大枣水煎服。"}, {"source": "条60｜《婴童类萃》下卷·益荣汤", "原文": "《婴童类萃》下卷：益荣汤。惊恐后，心君失辅，脾胃衰弱，怔忡恍惚，悲喜不常，小便浑浊，夜睡不宁。此方补脾胃，养心血。经云：损其心，益其荣。男妇心血不足者并效。  \n当归、黄芪、远志、小草、茯神、人参、酸枣、柏子仁、白芍各八分  木香三分  紫石英二钱  甘草五分  \n生姜三片，枣一枚，水煎。", "白话": "〔主治〕受惊恐之后，心君失去辅佐，脾胃衰弱，怔忡恍惚，悲喜无常，小便浑浊，夜睡不宁。此方补脾胃、养心血。经云：“损其心，益其荣。”男子妇人心血不足者都有效。〔组成·照录〕当归、黄芪、远志、小草、茯神、人参、酸枣、柏子仁、白芍各八分，木香三分，紫石英二钱，甘草五分。〔方义〕归、芍、枣仁养心血，参、芪、草益气，远志、茯神、紫石英安神定志，木香醒脾，为养心益荣之剂。〔服法〕加生姜三片、大枣一枚，水煎。"}, {"source": "条61｜《严氏济生方·诸虚门》·心肾丸", "原文": "《严氏济生方·诸虚门》：心肾丸。治心肾不足，精少血燥，心下烦热，怔忡不安，或口干生疮，目赤头晕，小便赤浊，五心烦热，多渴引饮，但是精虚血少，不受峻补者，悉宜服之。  \n菟丝子淘，酒蒸，擂，二两  麦门冬去心，二两  \n上为细末，炼蜜为丸，如梧桐子大，每服七十丸，空心食前，用盐汤送下，热水亦得。", "白话": "〔主治〕治心肾不足，精少血燥，心下烦热，怔忡不安，或口干生疮，目赤头晕，小便赤浊，五心烦热，口渴多饮；凡精虚血少而不受峻补者，都宜服。〔组成·照录〕菟丝子（淘，酒蒸，擂）二两、麦门冬（去心）二两。〔方义〕菟丝子补肾益精，麦门冬养心阴，二味平补心肾，不燥不腻。〔服法〕上为细末，炼蜜为丸如梧桐子大，每服七十丸，空腹食前盐汤送下，热水亦可。"}, {"source": "条62｜《严氏济生方·诸虚门》·大建中汤", "原文": "《严氏济生方·诸虚门》：大建中汤。治诸虚不足，小腹急痛，胁肋䐜胀，骨肉酸痛，短气喘促，痰多咳嗽，潮热多汗，心下惊悸，腰背强痛，多卧少气。  \n黄芪去芦、附子炮，去皮脐、鹿茸酒蒸、地骨皮去木、续断、石斛去根、人参、川芎、当归去芦，酒浸、白芍药、小草各一两  甘草炙，半两  \n上㕮咀，每服四钱，水一盏半，生姜五片，煎至七分，去滓，温服，不拘时候。咳嗽者加款冬花；咳血者加阿胶；便精遗泄者加龙骨；怔忡者加", "白话": "〔主治〕治诸虚不足，小腹急痛，胁肋胀满，骨肉酸痛，短气喘促，痰多咳嗽，潮热多汗，心下惊悸，腰背强痛，多卧少气。〔组成·照录〕黄芪（去芦）、附子（炮，去皮脐）、鹿茸（酒蒸）、地骨皮（去木）、续断、石斛（去根）、人参、川芎、当归（去芦，酒浸）、白芍药、小草各一两，甘草（炙）半两。〔方义〕黄芪、人参益气，鹿茸、附子温肾壮阳，归、芎、芍养血，续断、石斛强腰膝，地骨皮清虚热，为温补气血、建中缓急之剂。〔服法〕上药切碎，每服四钱，水一盏半加生姜五片，煎至七分去渣温服，不拘时候。〔加减〕咳"}, {"source": "条63｜《严氏济生方·五脏门》·心丹", "原文": "《严氏济生方·五脏门》：心丹又名法丹。此丹颗粒辰砂加心药煮炼。主男子、妇人心气不足，神志不宁，忧愁思虑，谋用过度，或因惊恐伤神失志，耗伤心气，恍惚振悸，差错健忘，梦寐惊魇，喜怒无时，或发狂，眩晕，不省人事，及治元气虚弱，唇燥咽干，潮热盗汗，或肺热上壅，痰唾稠黏，咳嗽烦渴，或大病后心虚烦躁，小儿心气虚弱，欲发惊痫，或直视发搐，应是一切心疾并宜服之。常服养心益血，安魂定魄，宁心志，止惊悸，顺三焦，和五", "白话": "〔别名〕心丹又名法丹，以颗粒辰砂加养心药煮炼而成。〔主治〕主男子妇人心气不足、神志不宁：或忧愁思虑、谋虑过度，或因惊恐伤神失志、耗伤心气，致恍惚心悸、差错健忘、梦中惊魇、喜怒无时，或发狂、眩晕、不省人事；又治元气虚弱、唇燥咽干、潮热盗汗；或肺热上壅、痰唾稠黏、咳嗽烦渴；或大病后心虚烦躁；小儿心气虚弱、欲发惊痫，或两目直视、四肢抽搐——一切心疾都宜服。常服能养心益血、安魂定魄、宁心定志、止惊悸，顺三焦、和五脏、助脾胃、进饮食，聪明耳目、悦泽颜色、轻身耐老，不峻不燥，神效不能尽述"}, {"source": "条64｜《严氏济生方·诸虚门》·天地煎", "原文": "《严氏济生方·诸虚门》：天地煎。治心血燥少，口干咽燥，心烦喜冷，怔忡恍惚，小便黄赤，或生疮疡。  \n天门冬去心，二两  熟地黄九蒸曝，一两  \n上为细末，炼蜜为丸，如梧桐子大，每服百丸，用熟水人参汤任下，不拘时候。", "白话": "〔主治〕治心血燥少，口干咽燥，心烦喜冷饮，怔忡恍惚，小便黄赤，或生疮疡。〔组成·照录〕天门冬（去心）二两、熟地黄（九蒸曝）一两。〔方义〕天冬滋肺肾之阴，熟地补血填精，二药成方，滋阴补血以润心燥。〔服法〕上为细末，炼蜜为丸如梧桐子大，每服百丸，白开水或人参汤任下，不拘时候。"}, {"source": "条65｜《严氏济生方·诸虚门》·茸附汤", "原文": "《严氏济生方·诸虚门》：茸附汤。治精血俱虚，荣卫耗损，潮热自汗，怔忡惊悸，肢体倦乏，但是一切虚弱之证，皆宜服之。  \n鹿茸去毛，酒蒸，一两  附子炮，去皮脐，一两  \n上㕮咀，分作四服，水二盏，生姜十片，煎至八分，去滓，食前，温服。", "白话": "〔主治〕治精血俱虚、荣卫耗损，潮热自汗，怔忡惊悸，肢体倦乏；一切虚弱之证都宜服。〔组成·照录〕鹿茸（去毛，酒蒸）一两、附子（炮，去皮脐）一两。〔方义〕鹿茸补精血、壮元阳，附子温经回阳，二药大温大补。〔服法〕上药切碎，分作四服，每服水二盏加生姜十片，煎至八分去渣，食前温服。"}, {"source": "条66｜《严氏济生方·惊悸怔忡健忘门》·益荣汤", "原文": "《严氏济生方·惊悸怔忡健忘门》：益荣汤。治思虑过制，耗伤心血，心帝无辅，怔忡恍惚，善悲忧，少颜色，夜多不寐，小便或浊。  \n当归去芦，酒浸、黄芪去芦、小草、酸枣仁炒，去壳、柏子仁炒、麦门冬去心、茯神去木、白芍药、紫石英细研，各一两  木香不见火、人参、甘草炙，各半两  \n上㕮咀，每服四钱，水一盏半，生姜五片，枣一枚，煎至七分，去滓，温服，不拘时候。", "白话": "〔主治〕治思虑过度，耗伤心血，心君无辅，怔忡恍惚，易于悲忧，面色少华，夜多不寐，小便或浑浊。〔组成·照录〕当归（去芦，酒浸）、黄芪（去芦）、小草、酸枣仁（炒，去壳）、柏子仁（炒）、麦门冬（去心）、茯神（去木）、白芍药、紫石英（细研）各一两，木香（不见火）、人参、甘草（炙）各半两。〔方义〕归、芍养血，参、芪、草益气，枣仁、柏子仁、茯神、紫石英养心安神，麦冬滋阴，木香理气，为益荣养心之剂。〔服法〕上药切碎，每服四钱，水一盏半加生姜五片、大枣一枚，煎至七分去渣温服，不拘时候。"}, {"source": "条67｜《严氏济生方·诸虚门》·黄芪饮子", "原文": "《严氏济生方·诸虚门》：黄芪饮子。治诸虚劳损，四肢倦怠，骨节酸疼，潮热乏力，自汗怔忡，日渐黄瘦，胸膈痞塞，不思饮食，咳嗽痰多，甚则唾血。  \n黄芪蜜炙，一两半  当归去芦，酒浸、紫菀洗，去须、石斛去根、地骨皮去木、人参、桑白皮、附子炮，去皮脐、鹿茸酒蒸、款冬花各一两  半夏汤泡七次  甘草炙，各半两  \n上㕮咀，每服四钱，水一盏半，生姜七片，枣一枚，煎至七分，去滓，温服，不拘时。此药温补荣卫，枯燥", "白话": "〔主治〕治诸虚劳损，四肢倦怠，骨节酸疼，潮热乏力，自汗怔忡，日渐面黄消瘦，胸膈痞塞，不思饮食，咳嗽痰多，甚则唾血。〔组成·照录〕黄芪（蜜炙）一两半，当归（去芦，酒浸）、紫菀（洗，去须）、石斛（去根）、地骨皮（去木）、人参、桑白皮、附子（炮，去皮脐）、鹿茸（酒蒸）、款冬花各一两，半夏（汤泡七次）、甘草（炙）各半两。〔方义〕黄芪、参、归益气养血，鹿茸、附子温阳，紫菀、冬花、桑皮、半夏化痰止咳，地骨皮、石斛清热养阴。〔服法〕上药切碎，每服四钱，水一盏半加生姜七片、大枣一枚，煎至七分"}, {"source": "条68｜《仁斋直指方论（附补遗）》卷十一·十四友丸", "原文": "《仁斋直指方论（附补遗）》卷十一：十四友丸。治心血俱虚，怔忡惊惕。  \n柏子仁研、远志肉姜汁腌，焙、酸枣仁汤浸，去皮，隔纸炒香、紫石英煅、熟干地黄、川当归、白茯苓、白茯神、人参、黄芪炙、阿胶炒、辣桂、龙齿研，各一两  朱砂半两，研  \n上细末，炼蜜丸桐子大。每三四十丸，食后枣汤下。", "白话": "〔主治〕治心血俱虚，怔忡惊惕。〔组成·照录〕柏子仁（研）、远志肉（姜汁腌，焙）、酸枣仁（汤浸，去皮，隔纸炒香）、紫石英（煅）、熟干地黄、川当归、白茯苓、白茯神、人参、黄芪（炙）、阿胶（炒）、辣桂、龙齿（研）各一两，朱砂半两（研）。〔方义〕参、芪、归、地、阿胶益气养血，柏子仁、枣仁、远志、茯神、紫石英、龙齿、朱砂镇心安神，肉桂温阳，为养血镇心之丸。〔服法〕上为细末，炼蜜为丸如梧桐子大，每服三四十丸，食后枣汤下。"}, {"source": "条69｜《太平惠民和剂局方》卷五·十四友丸", "原文": "《太平惠民和剂局方》卷五：十四友丸。补心肾虚，怔忪昏愦，神志不宁，睡卧不安。故《经》曰：脏有所伤，情有所倚，人不能知其病，则卧不安。  \n熟地黄、白茯苓、白茯神去木、人参、酸枣仁炒、柏子仁别研、紫石英别研、肉桂、阿胶蛤粉炒、当归、黄芪、远志汤浸，去心，酒洒、蒸，各一两  辰砂别研，一分  龙齿别研，二两  \n上为末，同别研四味，炼蜜为丸，如梧桐子大。每服三十丸，食后枣汤下。", "白话": "〔功能·主治〕补心肾之虚，治怔忪昏愦、神志不宁、睡卧不安。所以《经》说：脏有所伤，情有所偏倚，人不能自知其病，则睡眠不安。〔组成·照录〕熟地黄、白茯苓、白茯神（去木）、人参、酸枣仁（炒）、柏子仁（别研）、紫石英（别研）、肉桂、阿胶（蛤粉炒）、当归、黄芪、远志（汤浸，去心，酒洒，蒸）各一两，辰砂（别研）一分，龙齿（别研）二两。〔方义〕与《仁斋直指方》十四友丸大同，益气养血、补心肾、镇心安神。〔服法〕上为末，与别研四味合匀，炼蜜为丸如梧桐子大，每服三十丸，食后枣汤下。"}, {"source": "条70｜《仁斋直指方论（附补遗）》卷十一·人参远志丸", "原文": "《仁斋直指方论（附补遗）》卷十一：人参远志丸圣惠方。治气不足，惊悸健忘，神思不宁。  \n天门冬去心、白茯苓、菖蒲各七钱半  人参去芦、远志去心、酸枣仁、黄芪蜜炙，各半两  桔梗、丹砂、官桂去皮，各二钱半  \n上为末，蜜丸如豆大。每服二十丸至三十丸，米汤下。", "白话": "〔主治〕治气不足，惊悸健忘，神思不宁。〔组成·照录〕天门冬（去心）、白茯苓、菖蒲各七钱半，人参（去芦）、远志（去心）、酸枣仁、黄芪（蜜炙）各半两，桔梗、丹砂、官桂（去皮）各二钱半。〔方义〕参、芪益气，天冬滋阴，菖蒲、远志、枣仁安神益智，丹砂镇心，官桂温阳，桔梗载药上行。〔服法〕上为末，炼蜜为丸如豆大，每服二十至三十丸，米汤下。"}, {"source": "条71｜《仁斋直指方论（附补遗）》卷十一·养心汤", "原文": "《仁斋直指方论（附补遗）》卷十一：养心汤。治心虚血少，惊惕不宁。  \n黄芪炙、白茯苓、茯神、半夏曲、当归、川芎各半两  远志取肉，姜汁腌，焙、辣桂柏子仁、酸枣仁浸，去皮，隔纸炒香、北五味子、人参各一分  甘草炙，四钱  \n上粗末。每服三钱，姜五片，枣二枚煎，食前服。加槟榔、赤茯苓，治停水怔悸。", "白话": "〔主治〕治心虚血少，惊惕不宁。〔组成·照录〕黄芪（炙）、白茯苓、茯神、半夏曲、当归、川芎各半两，远志（取肉，姜汁腌，焙）、辣桂、柏子仁、酸枣仁（浸，去皮，隔纸炒香）、北五味子、人参各一分，甘草（炙）四钱。〔方义〕参、芪、苓、草益气，归、芎养血，茯神、远志、柏子仁、枣仁养心安神，肉桂温阳，五味敛阴。〔服法〕上为粗末，每服三钱，加生姜五片、大枣二枚煎，食前服。〔加减〕加槟榔、赤茯苓，治停水怔悸。"}, {"source": "条72｜《郑氏家传女科万金方·胎前门》上卷·大圣散", "原文": "《郑氏家传女科万金方·胎前门》上卷：第六问：妊娠心惊神悸，两胁膨胀，腹满连脐急痛，坐卧不安，气急逼迫胎惊者何？  \n答曰：胎气既成，五脏安养，皆因气闷，或为喧呼，心怯悸乱，致令胎惊，筋骨伤痛，四大不安，急服大圣散安胎保孕。大圣散。  \n白茯苓、川芎、麦冬、当归、黄芪各一两，蜜水炙 木香不见火 人参、甘草炙，各五分  \n上者㕮咀。每服四钱，水盏半，加生姜五片，煎七分，去渣，不拘时温服。", "白话": "〔问答·主治〕第六问：妊娠心惊神悸，两胁膨胀，腹满连脐急痛，坐卧不安，气急逼迫、胎动受惊者，是何缘故？答：胎气已成，全赖五脏安养；皆因气闷，或受喧呼，心虚悸乱，致使胎惊，筋骨伤痛，四大不安——急服大圣散安胎保孕。〔组成·照录〕白茯苓、川芎、麦冬、当归、黄芪各一两（蜜水炙），木香（不见火），人参、甘草（炙）各五分。〔方义〕参、芪、苓、草益气，归、芎养血安胎，麦冬滋阴，木香理气止痛，为安胎定悸之方。〔服法〕上药切碎，每服四钱，水一盏半加生姜五片，煎至七分去渣，不拘时温服。"}, {"source": "条73｜《御药院方》卷六·人参补虚汤", "原文": "《御药院方》卷六：人参补虚汤。治虚劳，少气不足，四肢困弱，嗜卧少力，心中悸动，夜多盗汗。常服补诸虚不足，健中进食。  \n黄芪、人参、陈皮去白、当归炙、桂去皮、细辛去叶土、前胡、白芍药去皮、甘草炙、白茯苓去皮、麦门冬去心、半夏炮、熟干地黄以上各二两  \n上一十二味为细末。每服三钱，水一大盏，入生姜五片，枣两个，煎至七分，稍热服，食前。", "白话": "〔主治〕治虚劳少气不足，四肢困软，嗜卧乏力，心中悸动，夜间多盗汗；常服补诸虚不足、健中进食。〔组成·照录〕黄芪、人参、陈皮（去白）、当归（炙）、桂（去皮）、细辛（去叶土）、前胡、白芍药（去皮）、甘草（炙）、白茯苓（去皮）、麦门冬（去心）、半夏（炮）、熟干地黄以上各二两。〔方义〕参、芪、苓、草益气，归、地、芍养血，桂、夏、陈皮温中化痰，前胡、细辛宣肺，麦冬养阴。〔服法〕上十二味为细末，每服三钱，水一大盏加生姜五片、大枣两个，煎至七分，稍热服，食前。"}, {"source": "条74｜《御药院方》卷六·乐令黄芪汤", "原文": "《御药院方》卷六：乐令黄芪汤。治虚劳少气，胸心痰冷，时时惊惕，心中悸动，手脚逆冷，体常自汗，补诸不足，五脏六腑虚损，肠鸣，风湿，营卫不调，百病。又治风里急。  \n黄芪、人参去芦、陈皮去白、当归、桂心、细辛去叶、前胡、芍药、甘草炙、茯苓去皮、麦门冬去心，各一钱 生姜二钱半 半夏汤浸七次，一钱一字 大枣一个  \n上㕮咀，都用水四盏煎至二盏半，去滓，分二服。", "白话": "〔主治〕治虚劳少气，胸心痰冷，时时惊惕，心中悸动，手脚逆冷，体常自汗；补诸不足，治五脏六腑虚损、肠鸣、风湿、营卫不调百病；又治风里急。〔组成·照录〕黄芪、人参（去芦）、陈皮（去白）、当归、桂心、细辛（去叶）、前胡、芍药、甘草（炙）、茯苓（去皮）、麦门冬（去心）各一钱，生姜二钱半，半夏（汤浸七次）一钱一字，大枣一个。〔方义〕即乐令建中汤方意，益气建中、调和营卫、温中化痰。〔服法〕上药切碎，用水四盏煎至二盏半，去渣分两次服。"}, {"source": "条75｜《御药院方》卷十一·禹余粮散", "原文": "《御药院方》卷十一：禹余粮散。治气血伤冲任，虚损崩伤带漏，久而不断，或下如豆汁，或成片如肝，或五色相杂，或赤白相兼，脐腹冷痛，面体萎黄，心忪悸动，发热多汗，四肢困倦，饮食减少。  \n禹余粮醋淬、伏龙肝、赤石脂、白龙骨、牡蛎、乌鱼骨、桂去皮、浮石各等分  \n上件同为细末。每服三钱，煎乌梅汤调下，食前服。白多，加牡蛎、龙骨、乌鱼骨。赤多，加赤石脂、禹余粮。黄多，加伏龙肝、桂心，随病加治。", "白话": "〔主治〕治气血损伤冲任，虚损崩漏带下久而不止，或下如豆汁，或成片如肝，或五色相杂，或赤白相兼，脐腹冷痛，面体萎黄，心忪悸动，发热多汗，四肢困倦，饮食减少。〔组成·照录〕禹余粮（醋淬）、伏龙肝、赤石脂、白龙骨、牡蛎、乌鱼骨、桂（去皮）、浮石各等分。〔方义〕禹余粮、赤石脂、龙骨、牡蛎、乌鱼骨收涩止血止带，伏龙肝温中，桂通阳，浮石软坚，为固涩止崩之散。〔服法〕上件同为细末，每服三钱，煎乌梅汤调下，食前服。〔加减〕白多加牡蛎、龙骨、乌鱼骨；赤多加赤石脂、禹余粮；黄多加伏龙肝、桂心，随"}, {"source": "条76｜《活幼心书》卷下·黄芪六一汤", "原文": "《活幼心书》卷下：黄芪六一汤。治诸虚不足，烦躁惊悸目扬，身体软弱，不思饮食。  \n黄芪六两，蜜水涂炙 甘草一两，炙  \n上件㕮咀，每服二钱，水一盏，刺二枚，煎七分，无时温服。", "白话": "〔主治〕治诸虚不足，烦躁惊悸、两目上视，身体软弱，不思饮食。〔组成·照录〕黄芪六两（蜜水涂炙）、甘草一两（炙）。〔方义〕黄芪六、甘草一，取“六一”之比，益气补中以定悸。〔服法〕上药切碎，每服二钱，水一盏加“刺二枚”，煎至七分，不拘时温服。"}, {"source": "条77｜《活幼心书》卷下·茯神汤", "原文": "《活幼心书》卷下：茯神汤。治心气不足，虚而惊悸，日常烦哭，及婴孩生下，羸瘦多惊，宜子母同服，自然有效。  \n茯神去皮木根，一两 人参去芦，半两 甘草炙，二钱 当归去芦尾，酒洗，半两  \n上件㕮咀，每服二钱，水一盏，煎七分，无时温服。有微热烦躁，入麦门冬去心同煎。", "白话": "〔主治〕治心气不足、虚而惊悸，整日烦哭；及婴孩生下羸瘦多惊，宜母子同服，自然有效。〔组成·照录〕茯神（去皮木根）一两、人参（去芦）半两、甘草（炙）二钱、当归（去芦尾，酒洗）半两。〔方义〕茯神安神，参、草益气，当归养血，为小儿心虚惊悸之平剂。〔服法〕上药切碎，每服二钱，水一盏煎至七分，不拘时温服。〔加减〕有微热烦躁，加麦门冬（去心）同煎。"}, {"source": "条78｜《瑞竹堂经验方·羡补门》·益卫丹", "原文": "《瑞竹堂经验方·羡补门》：益卫丹。治心脉结而散，肺脉浮而软，余脉如经，原其所自，思虑伤心，忧虑伤肺，盖心乃诸血之源，肺为诸气之候，心虚则血少，脉弱则气虚，遂致目涩、口苦，唇燥舌咸，甚则齿为之痛，鼻为之不利，怔忡白浊，腠理不密，易为感风寒，今以补气汤补气以养肺，益荣丹滋血以助心，荣卫日充，心肺戢治，诸疾自愈。  \n当归二两，去芦，酒浸焙 紫石英火煅，醋淬七次，研细，一两 柏子仁炒，另研、酸枣仁去壳、", "白话": "〔主治〕治心脉结而散、肺脉浮而软，余脉如常。推究原由：思虑伤心，忧虑伤肺——心为诸血之源，肺为诸气之候；心虚则血少，脉弱则气虚，于是目涩、口苦、唇燥舌咸，甚则齿痛、鼻不利、怔忡白浊，腠理不密，易感风寒。今以补气汤补气养肺，益荣丹滋血助心，荣卫日益充实，心肺安和，诸疾自愈。〔组成·照录〕当归（去芦，酒浸，焙）二两，紫石英（火煅，醋淬七次，研细）一两，柏子仁（炒，另研）、酸枣仁（去壳）、小草、木香（不见火）、茯神（去木）、桑寄生、卷柏叶（酒炙）、熟地黄（洗净，酒蒸，焙干）、龙齿各"}, {"source": "条79｜《世医得效方》卷七·子午丸", "原文": "《世医得效方》卷七：子午丸。治心肾俱虚，梦寐惊悸，体常自汗，烦闷短气，悲忧不乐，消渴引饮，漩下赤白，停凝浊甚，四体无力，眼昏，形容瘦悴，耳鸣，头晕，恶风怯冷。  \n榧子去壳，二两、莲肉去心、枸杞子、白龙骨、川巴戟去心、破故纸炒、真琥珀另研、芡实、苦楮实去壳、白矾枯、赤茯苓去皮、白茯苓去皮、文蛤、莲花须盐蒸、白牡蛎煅，各一两  \n上为末，酒蒸肉苁蓉一斤二两，烂研为丸，梧桐子大，朱砂一两半重，细研为衣", "白话": "〔主治〕治心肾俱虚，梦寐惊悸，体常自汗，烦闷短气，悲忧不乐，消渴多饮，小便赤白浑浊、凝滞甚，四肢无力，眼昏，形体消瘦憔悴，耳鸣，头晕，恶风怕冷。〔组成·照录〕榧子（去壳）二两，莲肉（去心）、枸杞子、白龙骨、川巴戟（去心）、破故纸（炒）、真琥珀（另研）、芡实、苦楮实（去壳）、白矾（枯）、赤茯苓（去皮）、白茯苓（去皮）、文蛤、莲花须（盐蒸）、白牡蛎（煅）各一两。〔方义〕龙骨、牡蛎、琥珀、芡实、莲须固涩安神，巴戟、故纸、苁蓉温肾，二苓、文蛤分利，为心肾双补、固精安神之丸。〔制法·服"}, {"source": "条80｜《世医得效方》卷八·枣肉灵砂", "原文": "《世医得效方》卷八：枣肉灵砂。专治虚人夜不得睡，梦中惊魇，自汗忪悸。  \n灵砂二分，研 人参半分 酸枣仁肉一分  \n上为末，枣肉丸，临卧时，枣汤吞下五七粒。", "白话": "〔主治〕专治体虚之人夜间不得睡、梦中惊魇、自汗心悸。〔组成·照录〕灵砂二分（研）、人参半分、酸枣仁肉一分。〔方义〕灵砂镇心安神，人参益气，枣仁养心，佐枣肉和丸。〔制法·服法〕上为末，以枣肉为丸，临卧时枣汤吞下五至七粒。"}, {"source": "条81｜《世医得效方》卷八·增损乐令汤", "原文": "《世医得效方》卷八：增损乐令汤。治诸虚不足，小腹急痛，胁肋䐜胀，脐下虚满，胸中烦悸，面色痿黄，唇干口燥，手足逆冷，体常自汗，腰背强急，骨肉酸疼，咳嗽喘乏，不饮食。或因劳伤过度，或病后不复。  \n黄芪去芦、人参去芦、橘皮去白、当归去尾、桂心、细辛、前胡去芦、甘草、茯苓、麦门冬去心、芍药各二两 附子炮，去皮脐、熟地黄酒炒，各一两 半夏汤洗，二两半 远志三分，去心，炒  \n上锉散。每服三钱，水一盏半，生", "白话": "〔主治〕治诸虚不足，小腹急痛，胁肋胀满，脐下虚满，胸中烦悸，面色萎黄，唇干口燥，手足逆冷，体常自汗，腰背强急，骨肉酸疼，咳嗽喘乏，不欲饮食；或因劳伤过度，或病后不复。〔组成·照录〕黄芪（去芦）、人参（去芦）、橘皮（去白）、当归（去尾）、桂心、细辛、前胡（去芦）、甘草、茯苓、麦门冬（去心）、芍药各二两，附子（炮，去皮脐）、熟地黄（酒炒）各一两，半夏（汤洗）二两半，远志（去心，炒）三分。〔方义〕即乐令建中汤加附子、熟地、远志，益气温阳、养血安神。〔服法〕上药锉散，每服三钱，水一盏"}, {"source": "条82｜《脉因证治》卷一·炙甘草汤", "原文": "《脉因证治》卷一：炙甘草汤。治虚劳不足，汗出而闷，心悸，脉结代。心劳实热，口舌生疮，大便闭塞，心满痛，小腹热。心劳虚寒，惊悸恍惚多忘，梦寐惊魇，神志不定。精实，目视不明，齿焦发落，形衰，通身虚热。甚则胸中痹痛，烦闷泄精。精虚，尪羸，惊悸，梦泄遗沥，小便白浊。甚则茎弱核彻，小腹里急。", "白话": "〔主治〕治虚劳不足，汗出而胸闷，心悸，脉结代。又心劳实热者：口舌生疮，大便闭塞，心胸满痛，小腹热；心劳虚寒者：惊悸恍惚多忘，梦中惊魇，神志不定；精实者：视物不明，齿焦发落，形体衰惫，通身虚热，甚则胸中痹痛、烦闷泄精；精虚者：瘦弱，惊悸，梦泄遗沥，小便白浊，甚则阴茎软弱、睾丸冷彻、小腹里急。〔组成·照录〕原稿未载。〔方义〕炙甘草汤益气滋阴、通阳复脉（组成详见《伤寒论》条13）；本条以一方统治心劳虚实、精实精虚诸变证，属异病同治之例。"}, {"source": "条83｜《医学纲目》卷十一·薯蓣丸", "原文": "《医学纲目》卷十一：《千》薯蓣丸。治虚劳不足，风气百疾，头目眩冒，惊悸狂癫。  \n薯蓣二十八分 当归十分 桂心七分 神曲炒、熟地各十分 甘草二十分 人参十分 芎五分 芍药、白术、麦门冬、杏仁各六分 柴胡、桔梗、茯苓各五分 鹿角胶七分 干姜三分 白蔹三分 防风六分 大枣一百枚，为膏 黄芩六分 大豆黄卷七分  \n上二十二味，末之，和枣膏炼蜜丸，如弹子大，空腹酒服一丸，日三服。《甲》卒心中痛，瘛疭，互", "白话": "〔出处〕《医学纲目》引《千金》薯蓣丸。〔主治〕治虚劳不足，风气百疾，头目眩晕，惊悸狂癫。〔组成·照录〕薯蓣二十八分、当归十分、桂心七分、神曲（炒）、熟地各十分、甘草二十分、人参十分、芎（川芎）五分、芍药、白术、麦门冬、杏仁各六分、柴胡、桔梗、茯苓各五分、鹿角胶七分、干姜三分、白蔹三分、防风六分、大枣一百枚（为膏）、黄芩六分、大豆黄卷七分。〔方义〕薯蓣重用合甘草、大枣健脾益气，四物养血，柴胡、桔梗、防风、杏仁宣散风气，为虚劳诸不足、风气百疾之总治方。〔服法〕上二十二味为末，和枣"}, {"source": "条84｜《医学纲目》卷二十一·养荣汤", "原文": "《医学纲目》卷二十一：养荣汤。治五疸。脚弱心忪，口淡耳响，微寒发热，气急，小便白浊，当作虚劳治之。  \n黄芪、当归、桂心、甘草炙、陈皮、白术、人参各一两 白芍药三两 熟地、五味子、茯苓各三钱 远志去心，半两  \n上每服四钱，姜枣煎，空心服。上法治虚寒黄疸。", "白话": "〔主治〕治五疸（黄疸），脚软心悸，口中味淡，耳鸣，微恶寒发热，气急，小便白浊——当作虚劳治疗。〔组成·照录〕黄芪、当归、桂心、甘草（炙）、陈皮、白术、人参各一两，白芍药三两，熟地、五味子、茯苓各三钱，远志（去心）半两。〔方义〕参、芪、术、草益气健脾，归、芍、地养血，桂心温阳，茯苓、远志、五味安神，陈皮理气，为虚寒黄疸之补益方。〔服法〕上药每服四钱，姜枣煎，空腹服；此法主治虚寒黄疸。"}, {"source": "条85｜《普济方》卷十八·朱附丹余居士选奇方", "原文": "《普济方》卷十八：朱附丹余居士选奇方。治心肾不足，气不升降，惊悸，用心过度。  \n附子一两，炮去皮脐 朱砂半两，研 茯神一两  \n上为末，白面糊为丸，如梧桐子大。每服二十丸，空心盐汤下，主火惊失心出本草。", "白话": "〔出处〕余居士《选奇方》朱附丹。〔主治〕治心肾不足、气机升降失常、惊悸、用心过度。〔组成·照录〕附子一两（炮去皮脐）、朱砂半两（研）、茯神一两。〔方义〕附子温心肾之阳，朱砂镇心安神，茯神养心，三味成丹。〔制法·服法〕上为末，白面糊为丸如梧桐子大，每服二十丸，空腹盐汤下。原稿末注“主火惊失心出本草”。"}, {"source": "条86｜《普济方·卷二百二十七》·双补丸", "原文": "《普济方·卷二百二十七》：双补丸出医药方。治一切虚损，五劳七伤，面色黧黑。唇口干燥，发渴目暗，耳鸣心忪，气短食少，神倦夜梦惊恐，四肢酸疼，寒热盗汗，小肠拘急，小便滑数，妇人诸疾，并宜服之。常服既济水火，益气安神。  \n鹿角霜三两 熟地黄洗再蒸、沉香、菟丝子酒浸蒸研焙、覆盆子去枝蒂、白茯苓去皮、人参去芦头、宣木瓜、薏苡仁炒、黄芪炙、苁蓉洗酒浸、五味子去枝炒、石斛去根炒、当归去芦酒炒、泽泻切块再蒸，各", "白话": "〔出处〕《普济方》引医药方双补丸。〔主治〕治一切虚损、五劳七伤，面色黧黑，唇口干燥，口渴目暗，耳鸣心悸，气短食少，神倦夜梦惊恐，四肢酸疼，寒热盗汗，小腹拘急，小便滑数，及妇人诸疾，都宜服；常服能既济水火、益气安神。〔组成·照录〕鹿角霜三两；熟地黄（洗，再蒸）、沉香、菟丝子（酒浸，蒸，研，焙）、覆盆子（去枝蒂）、白茯苓（去皮）、人参（去芦头）、宣木瓜、薏苡仁（炒）、黄芪（炙）、苁蓉（洗，酒浸）、五味子（去枝，炒）、石斛（去根，炒）、当归（去芦，酒炒）、泽泻（切块，再蒸）各一两；"}, {"source": "条87｜《普济方》卷二百二十八·枸杞汤", "原文": "《普济方》卷二百二十八：枸杞汤。治虚劳骨肉酸疼，吸吸少气，少腹拘急，腰背强痛，心中惊悸，咽干唇燥，面无颜色，饮食减少，忧愁嗜卧。  \n大麻仁五两 枸杞叶五两 干姜炮，一两 桂去粗皮，五钱 甘草炙锉，三两  \n上粗捣筛，每服三钱。以水一盏，煎取半盏，去滓空腹温服。", "白话": "〔主治〕治虚劳骨肉酸疼，气短吸吸，少腹拘急，腰背强痛，心中惊悸，咽干唇燥，面无颜色，饮食减少，忧愁嗜卧。〔组成·照录〕大麻仁五两、枸杞叶五两、干姜（炮）一两、桂（去粗皮）五钱、甘草（炙，锉）三两。〔方义〕麻仁、枸杞叶润养，干姜、桂温中通阳，甘草和中，为虚劳润养之剂。〔服法〕上粗捣筛，每服三钱，以水一盏煎取半盏，去渣空腹温服。"}, {"source": "条88｜《普济方》卷二百二十八·鹿茸丸", "原文": "《普济方》卷二百二十八：鹿茸丸出《杨氏家藏方》。治真元虚惫，五劳七伤，面色黧黯，唇口干舌燥，目暗耳鸣，心忪气短，精神昏倦，喜怒无常，饮食无味，四肢酸疼，举动乏力，小腹拘急，小便滑数，或时出血。  \n熟地黄洗焙，五两 山药三两 杜仲炒断丝，一两半 鹿茸烧去毛，酒浸炙 五味子 附子炮焙，五两 肉苁蓉酒浸一宿、牛膝酒浸一宿，各一两  \n上为末，面糊丸，如梧桐子大，每服三十丸，温酒盐汤下，和剂方用药同，但", "白话": "〔出处〕《普济方》引《杨氏家藏方》鹿茸丸。〔主治〕治真元虚惫，五劳七伤，面色黧黑，唇口干燥，目暗耳鸣，心悸气短，精神昏倦，喜怒无常，饮食无味，四肢酸疼，举动乏力，小腹拘急，小便滑数，或时出血。〔组成·照录〕熟地黄（洗，焙）五两、山药三两、杜仲（炒断丝）一两半、鹿茸（烧去毛，酒浸炙）、五味子、附子（炮，焙）五两、肉苁蓉（酒浸一宿）、牛膝（酒浸一宿）各一两。〔方义〕鹿茸、附子、苁蓉温肾壮阳，熟地、山药、杜仲、牛膝补精血强腰膝，五味子敛精，为温补真元之丸。〔服法〕上为末，面糊为丸如"}, {"source": "条89｜《普济方》卷二百二十九·黄芪汤", "原文": "《普济方》卷二百二十九：黄芪汤一名地骨皮散。治热劳，肢节酸疼，吸吸少气，腰背强痛，心中虚悸，咽干唇赤，面色枯燥，饮食无味，悲忧惨戚，多睡少起。  \n黄芪锉焙、地骨皮各一两 鳖甲一枚，去裙涂醋炙黄 甘草炙，锉半两 麦门冬去心，焙，一两半 桂去粗皮，半两  \n上粗捣筛，每服五钱，水一盏半，生姜半分拍破，粳米五十粒，煎至八分，去滓，食前温服。", "白话": "〔主治〕治热劳，肢节酸疼，气短吸吸，腰背强痛，心中虚悸，咽干唇红，面色枯燥，饮食无味，悲忧凄惨，多睡少起。〔组成·照录〕黄芪（锉，焙）、地骨皮各一两，鳖甲一枚（去裙，涂醋炙黄），甘草（炙，锉）半两，麦门冬（去心，焙）一两半，桂（去粗皮）半两。〔方义〕与《圣济总录》黄芪汤同方，益气养阴、清退虚热。〔服法〕上粗捣筛，每服五钱，水一盏半加生姜半分拍破、粳米五十粒，煎至八分去渣，食前温服。"}, {"source": "条90｜《普济方》卷三百三十一·禹余粮丸", "原文": "《普济方》卷三百三十一：禹余粮丸一名吴茱萸丸。治妇人久赤白带下，胞络伤败，月水不调，渐成崩漏，气血虚竭，面黄体瘦，脐腹里急，腰膝疼痛，肢体烦痛，心忪头眩，手足发热。  \n禹余粮二两，烧醋淬七次 白石脂二两 当归一两，锉微炒 鳖甲一两，涂醋炙微黄去裙襕 狗脊二分，去毛 白芍药三分 白术一两 附子一两，涂醋微炙 桑寄生一两 柏叶一两，微炒 厚朴一两，去粗皮涂生姜汁炙令香熟 干姜一两，炮裂锉 吴茱萸半两", "白话": "〔主治〕治妇人久患赤白带下，胞络伤败，月经不调，渐成崩漏，气血虚竭，面黄体瘦，脐腹里急，腰膝疼痛，肢体烦痛，心悸头晕，手足发热。〔组成·照录〕禹余粮二两（烧醋淬七次）、白石脂二两、当归一两（锉，微炒）、鳖甲一两（涂醋炙微黄，去裙襕）、狗脊二分（去毛）、白芍药三分、白术一两、附子一两（涂醋微炙）、桑寄生一两、柏叶一两（微炒）、厚朴一两（去粗皮，涂生姜汁炙令香熟）、干姜一两（炮裂，锉）、吴茱萸半两（汤浸七次，焙干，微炒）。〔方义〕禹余粮、白石脂、柏叶收涩止血，归、芍养血，鳖甲滋阴"}, {"source": "条91｜《奇效良方》卷十·茯神散", "原文": "《奇效良方》卷十：茯神散。治伤寒后虚羸，心气乏力弱，惊悸多忘。  \n茯神、黄芪、菖蒲各一两 白芍药、人参各半两 远志去心，三分  \n上㕮咀，每服五钱，水一中盏，入枣三枚，煎至六分，去滓，不拘时温服。", "白话": "〔主治〕治伤寒后虚弱，心气不足乏力，惊悸多忘。〔组成·照录〕茯神、黄芪、菖蒲各一两，白芍药、人参各半两，远志（去心）三分。〔方义〕茯神、菖蒲、远志安神益智，参、芪益气，芍药养血。〔服法〕上药切碎，每服五钱，水一中盏加大枣三枚，煎至六分去渣，不拘时温服。"}, {"source": "条92｜《奇效良方》卷十·牡蛎散", "原文": "《奇效良方》卷十：牡蛎散。治伤寒后虚损，心多怔悸，夜梦泄精。  \n牡蛎烧为粉、桂心、白芍药、鹿茸酥炙、龙骨各一两 甘草炙，半两  \n上㕮咀，每服五钱，水一大盏，生姜半分，枣三枚，煎至五分，去渣，食前温服。", "白话": "〔主治〕治伤寒后虚损，心多怔悸，夜间梦中遗精。〔组成·照录〕牡蛎（烧为粉）、桂心、白芍药、鹿茸（酥炙）、龙骨各一两，甘草（炙）半两。〔方义〕牡蛎、龙骨镇心固精，鹿茸补虚，芍药、甘草和血缓急，桂心通阳。〔服法〕上药切碎，每服五钱，水一大盏加生姜半分、大枣三枚，煎至五分去渣，食前温服。"}, {"source": "条93｜《奇效良方》卷二十二·远志丸", "原文": "《奇效良方》卷二十二：远志丸。治虚劳惊悸，神气不足，多忘不安。  \n远志去心、石菖蒲、熟地黄、人参去芦、黄芪锉、薯蓣、茯神、紫石英研细，水飞各一两 麦门冬去心，焙 龙齿细研，二两  \n上为细末，研匀，炼蜜和捣三五百杵，丸如梧桐子大，每服十五丸，不拘时人参汤送下。", "白话": "〔主治〕治虚劳惊悸，神气不足，多忘不安。〔组成·照录〕远志（去心）、石菖蒲、熟地黄、人参（去芦）、黄芪（锉）、薯蓣、茯神、紫石英（研细，水飞）各一两，麦门冬（去心，焙）、龙齿（细研）二两。〔方义〕远志、菖蒲、茯神、紫石英、龙齿安神定志，参、芪、薯蓣益气，地、麦滋阴，为虚劳惊悸之丸。〔服法〕上为细末研匀，炼蜜和捣三五百杵，丸如梧桐子大，每服十五丸，不拘时人参汤送下。"}, {"source": "条94｜《奇效良方》卷二十二·白羊肉汤", "原文": "《奇效良方》卷二十二：白羊肉汤。治虚劳羸瘦，脚膝无力，耳聋盗汗，心多忪悸。  \n白羊肉二斤，去脂膜，汲水四升煮取二升 桂心三分 杜仲去粗皮，炙黄，锉、白茯苓熟地黄、牛膝去苗、人参去芦、白术、远志去心、黄芪锉、龙骨以上各一两 磁石三两，捣碎，水淘去赤汁  \n上㕮咀，每服四钱，用羊肉汁一中盏，煎至六分，去滓，每于食前温服之。", "白话": "〔主治〕治虚劳消瘦，脚膝无力，耳聋盗汗，心多忪悸。〔组成·照录〕白羊肉二斤（去脂膜，汲水四升煮取二升），桂心三分，杜仲（去粗皮，炙黄，锉）、白茯苓、熟地黄、牛膝（去苗）、人参（去芦）、白术、远志（去心）、黄芪（锉）、龙骨以上各一两，磁石三两（捣碎，水淘去赤汁）。〔方义〕羊肉血肉有情补虚，参、芪、术、苓益气，地、杜仲、牛膝补肾强腰，远志、龙骨、磁石安神潜阳。〔服法〕上药切碎，每服四钱，用羊肉汁一中盏煎至六分去渣，每于食前温服。"}, {"source": "条95｜《奇效良方》卷四十六·秘传酸枣仁汤", "原文": "《奇效良方》卷四十六：秘传酸枣仁汤。治心肾水火不交，精血虚耗，痰饮内蓄，怔忡恍惚，夜卧不安。  \n酸枣仁去皮，炒 远志去心，制 黄芪 白茯苓 莲肉去心 当归酒浸 人参 茯神以上各一两 陈皮 粉草炙，各半两  \n上㕮咀，每服四钱，水一盏半，生姜三片，枣一枚，以瓦器煎七分，日二服，临卧一服。", "白话": "〔主治〕治心肾水火不交，精血虚耗，痰饮内蓄，怔忡恍惚，夜卧不安。〔组成·照录〕酸枣仁（去皮，炒）、远志（去心，制）、黄芪、白茯苓、莲肉（去心）、当归（酒浸）、人参、茯神以上各一两，陈皮、粉草（炙）各半两。〔方义〕枣仁、远志、茯神、莲肉养心安神，参、芪、苓、草益气，当归养血，陈皮化痰，为交通心肾、养心安神之方。〔服法〕上药切碎，每服四钱，水一盏半加生姜三片、大枣一枚，以瓦器煎取七分，日服两次，临卧再服一次。"}, {"source": "条96｜《奇效良方》卷四十六·益荣汤", "原文": "《奇效良方》卷四十六：益荣汤。治思虑过多，耗伤心血，心血既伤，神无所守。是以怔忡恍惚，善悲忧，少颜色，夜不多寐，小便或浊。  \n当归去芦，酒浸  黄芪去芦  小草  酸枣仁炒，去壳  柏子仁炒  茯神去木  木香不见火  麦门冬去心  白芍药  人参去芦  紫石英煅研  甘草炙，各一钱  \n上作一服，水二盅，生姜三片，红枣一枚，煎一盅，不拘时服。", "白话": "〔主治〕治思虑过多，耗伤心血；心血既伤，神无所守，故怔忡恍惚，易于悲忧，面色少华，睡眠不多，小便或浑浊。〔组成·照录〕当归（去芦，酒浸）、黄芪（去芦）、小草、酸枣仁（炒，去壳）、柏子仁（炒）、茯神（去木）、木香（不见火）、麦门冬（去心）、白芍药、人参（去芦）、紫石英（煅，研）、甘草（炙）各一钱。〔方义〕与《严氏济生方》益荣汤同方，益气养血、养心安神。〔服法〕上药作一服，水二盅加生姜三片、红枣一枚，煎取一盅，不拘时服。"}, {"source": "条97｜《奇效良方》卷六十三·滋阴万病丸", "原文": "《奇效良方》卷六十三：滋阴万病丸。治虚劳血弱，肌肉枯燥，手足多烦，肢节酸痛，须发脱落，面少颜色，腹中拘急，痛引腰背，去血过多。崩伤内竭，胸中气短，昼夜不得眠，情思不乐，怔忡多汗。  \n熟地黄、当归各一两  \n上为末，炼蜜和丸，如梧桐子大，每服二十丸，不拘时米饮送下。", "白话": "〔主治〕治虚劳血弱，肌肉枯燥，手足烦热，肢节酸痛，须发脱落，面色少华，腹中拘急、痛引腰背，失血过多；崩漏内竭，胸中气短，昼夜不得眠，情志不乐，怔忡多汗。〔组成·照录〕熟地黄、当归各一两。〔方义〕熟地滋阴补血，当归养血和血，二味成丸，补血以润燥定悸。〔服法〕上为末，炼蜜和丸如梧桐子大，每服二十丸，不拘时米饮送下。"}, {"source": "条98｜《丹溪心法》卷四·养心汤", "原文": "《丹溪心法》卷四：养心汤。治心虚血少，惊悸不宁。治停水怔忡，加槟榔、赤茯苓。", "白话": "〔主治〕治心虚血少，惊悸不宁。〔加减〕治水停怔忡，加槟榔、赤茯苓。〔组成·照录〕原稿未载。〔方义〕养心汤类方以益气养血、安神定悸为法，组成参见《校注妇人良方》养心汤（条58）。"}, {"source": "条99｜《本草单方》卷一·无名方", "原文": "《本草单方》卷一：虚损积劳。凡男女因积虚，或大病后虚损，沉困酸疼，盗汗，少气，喘惙，或小腹拘急，心悸胃弱，多卧少起，渐至瘦削。若年深，五脏气竭，则难治也。  \n用乌雌鸡一头，治如食法。以生地黄一升切、饴糖一升，纳腹内，缚定，铜锡器贮于锅内，隔汤蒸五升米熟，取出，食肉饮汁。勿用盐。一月一作，神效。 《姚僧垣方》", "白话": "〔主治〕虚损积劳：凡男女因积虚，或大病之后虚损，身体困重酸疼，盗汗，少气，喘促，或小腹拘急，心悸胃弱，多卧少起，日渐消瘦；若病程年深，五脏气竭，则难治。〔组成·照录〕乌雌鸡一只（按食用法处理），生地黄一升（切）、饴糖一升。〔方义〕乌雌鸡补虚养血，生地滋阴，饴糖建中，为食疗补虚之方。〔制法·服法〕将生地、饴糖纳入鸡腹内缚定，用铜锡器盛之置于锅内隔水蒸，蒸至五升米熟为度，取出食肉饮汁。〔禁忌〕勿用盐。一月制作一次，效果神验。原稿末注方源《姚僧垣方》。"}, {"source": "条100｜《苍生司命》卷七·养心汤", "原文": "《苍生司命》卷七：养心汤。治心虚血少，神气不宁，令人惊悸怔忡。  \n黄芪、茯苓、茯神、半夏曲、川归、川芎各五钱 柏子仁、枣仁炒、人参、远志姜汁炒、五味、辣桂各二钱五分 甘草炙，四钱  \n共为末，每服五钱。", "白话": "〔主治〕治心虚血少，神气不宁，使人惊悸怔忡。〔组成·照录〕黄芪、茯苓、茯神、半夏曲、川归、川芎各五钱，柏子仁、枣仁（炒）、人参、远志（姜汁炒）、五味、辣桂各二钱五分，甘草（炙）四钱。〔方义〕即通行养心汤，益气养血、养心安神。〔服法〕共为末，每服五钱（煎服）。"}, {"source": "条101｜《外科经验方·溃疡》·黄芪人参汤", "原文": "《外科经验方·溃疡》：黄芪人参汤。治诸疮溃后，食少倦怠，口舌干燥，或寒热往来，惊悸少睡，并治之。  \n黄芪盐水拌，炒，三钱 人参 白术炒 苍术米泔水浸，炒，一钱 陈皮一钱 当归酒拌 炙甘草一钱 麦门冬五分，去心，胃寒不用 神曲五分，炒 升麻一分 黄柏三分，酒炒，腹不实者去之 五味子捣碎，炒，五分  \n作一剂，用水二钟，姜三片，煎至一钟，食远服。如少睡，加酸枣仁炒一钱。肌肉迟生，加白敛去皮，一钱。", "白话": "〔主治〕治诸疮溃后，食少倦怠，口舌干燥，或寒热往来，惊悸少睡，都可治。〔组成·照录〕黄芪（盐水拌，炒）三钱，人参、白术（炒）、苍术（米泔水浸，炒）一钱，陈皮一钱，当归（酒拌）、炙甘草一钱，麦门冬（去心）五分（胃寒不用），神曲（炒）五分，升麻一分，黄柏（酒炒）三分（腹不实者去之），五味子（捣碎，炒）五分。〔方义〕黄芪、参、术、草益气健脾，苍术、陈皮、神曲运脾，当归养血，麦冬、五味滋阴敛阴，升麻升提，黄柏清热，为疮疡溃后补虚之剂。〔服法〕作一剂，用水二钟加生姜三片，煎至一钟，食远"}, {"source": "条102｜《立斋外科发挥》卷七·归脾汤", "原文": "《立斋外科发挥》卷七：归脾汤。治思虑伤脾，不能统摄，心血以此妄行，或吐血下血，或健忘怔忡，惊悸少寐，或心脾作痛。  \n白术炒、茯神、黄芪蜜炙、龙眼肉、酸枣仁蒸，各一钱 人参、木香各五分 甘草炙，二分半  \n作一剂，水一钟，姜一片，枣一枚，煎六分，食远并临卧服。", "白话": "〔主治〕治思虑伤脾，不能统摄，心血因此妄行，或吐血下血，或健忘怔忡、惊悸少寐，或心脾疼痛。〔组成·照录〕白术（炒）、茯神、黄芪（蜜炙）、龙眼肉、酸枣仁（蒸）各一钱，人参、木香各五分，甘草（炙）二分半。〔方义〕即归脾汤，益气健脾、养血安神。〔服法〕作一剂，水一钟加生姜一片、大枣一枚，煎取六分，食远及临卧服。"}, {"source": "条103｜《女科撮要》卷下·归脾汤", "原文": "《女科撮要》卷下：归脾汤。治脾经失血，少寐发热，盗汗，或思虑伤脾，不能摄血妄行；或健忘怔忡，惊悸不寐；或心脾伤痛，怠惰嗜卧，饮食不思。  \n人参、白术、白茯苓、黄芪炒、当归、龙眼肉、远志、酸枣仁炒，各一钱 木香五分 甘草炙，五分  \n上姜枣水煎服。", "白话": "〔主治〕治脾经失血、少寐发热、盗汗；或思虑伤脾、不能摄血而妄行；或健忘怔忡、惊悸不寐；或心脾伤痛、怠惰嗜卧、不思饮食。〔组成·照录〕人参、白术、白茯苓、黄芪（炒）、当归、龙眼肉、远志、酸枣仁（炒）各一钱，木香五分，甘草（炙）五分。〔方义〕即归脾汤正方，益气补血、健脾养心。〔服法〕上药加生姜、大枣水煎服。"}, {"source": "条104｜《保婴撮要》·四君子汤", "原文": "《保婴撮要》：耳后微黄主睡中惊悸咬牙，用四君子加芎、归、升麻以调理脾气。", "白话": "〔主治〕小儿耳后微黄，主睡中惊悸、咬牙，用四君子汤加川芎、当归、升麻以调理脾气。〔组成·照录〕原稿未载（四君子汤：人参、白术、茯苓、甘草）。〔方义〕四君子益气健脾，加芎、归养血，升麻升举清阳，脾气和则惊悸自止。〔服法〕原稿未载，参见四君子汤煎法。"}, {"source": "条105｜《保婴撮要》卷六·四君子汤", "原文": "《保婴撮要》卷六：若惊悸困倦，痰盛不乳者，心脾血虚也，用四君子加芎、归、酸枣仁。", "白话": "〔主治〕若小儿惊悸困倦、痰盛而不吃奶者，属心脾血虚，用四君子汤加川芎、当归、酸枣仁。〔组成·照录〕原稿未载（四君子汤：人参、白术、茯苓、甘草）。〔方义〕四君子益气健脾，芎、归养血，枣仁安神。〔服法〕原稿未载。"}, {"source": "条106｜《保婴撮要》卷十·人参养荣汤", "原文": "《保婴撮要》卷十：人参养荣汤。治病后时自汗，或发潮热，口干食少，心虚惊悸，咳而下痢。前方去川芎，加陈皮、五味子、远志。", "白话": "〔主治〕治病后时时自汗，或发潮热，口干食少，心虚惊悸，咳嗽而下痢。〔组成·加减〕前方（人参养荣汤）去川芎，加陈皮、五味子、远志。〔方义〕益气养血、敛汗安神。〔服法〕原稿未载。"}, {"source": "条107｜《保婴撮要》卷十三·加味归脾汤", "原文": "《保婴撮要》卷十三：加味归脾汤。治小儿因乳母忧思郁怒，胸胁作痛；或肝脾经分患疮疡之症；或寒热惊悸无寐；或便血盗汗，疮口不敛等症。  \n人参、黄芪炒、茯神去木，各二两 甘草炒 白术炒，一两 木香五分 远志去心、酸枣仁、龙眼肉、当归、牡丹皮、山栀炒，各一钱、  \n上水煎，乳母服，儿亦服之。", "白话": "〔主治〕治小儿因乳母忧思郁怒，胸胁作痛；或肝脾经部位患疮疡；或寒热惊悸、失眠；或便血盗汗、疮口不敛等症。〔组成·照录〕人参、黄芪（炒）、茯神（去木）各二两，甘草（炒）、白术（炒）一两，木香五分，远志（去心）、酸枣仁、龙眼肉、当归、牡丹皮、山栀（炒）各一钱。〔方义〕归脾汤加丹皮、山栀清肝凉血，为肝脾同治之方。〔服法〕上药水煎，乳母服，患儿亦服。"}, {"source": "条108｜《保婴撮要》卷十四·秘旨安神丸", "原文": "《保婴撮要》卷十四：秘旨安神丸。治禀心脾气血虚弱，发热不安，疮不生肌，睡中则惊悸。  \n人参、半夏汤泡、酸枣仁、茯神各一钱 当归酒洗 橘红 赤芍药 五味子五粒，杵 甘草炙，三分  \n上为末，姜汁糊丸芡实大。每服一丸，姜汤下。", "白话": "〔主治〕治禀赋心脾气血虚弱，发热不安，疮口不生肌，睡中惊悸。〔组成·照录〕人参、半夏（汤泡）、酸枣仁、茯神各一钱，当归（酒洗）、橘红、赤芍药、五味子（五粒，杵）、甘草（炙）三分。〔方义〕参、草益气，归、芍养血，枣仁、茯神安神，半夏、橘红化痰，五味敛阴。〔制法·服法〕上为末，姜汁糊为丸如芡实大，每服一丸，姜汤下。"}, {"source": "条109｜《保婴撮要》卷十八·济生归脾汤", "原文": "《保婴撮要》卷十八：济生归脾汤。治脾血虚损，健忘惊悸，或心气虚不能摄血归源，以致妄行，或吐血下血，或因乳母心脾二经有热，疮不结痂，或疮痕赤色。加柴胡、山栀即加味归脾汤。  \n人参、白茯苓、黄芪、白术、龙眼肉、当归、远志、酸枣仁炒，各二钱 木香一钱 甘草五分 当归身一钱  \n上姜枣水煎，母子同服。", "白话": "〔主治〕治脾血虚损，健忘惊悸；或心气虚不能摄血归源而妄行，或吐血下血；或因乳母心脾二经有热，疮不结痂、疮痕赤色。〔组成·照录〕人参、白茯苓、黄芪、白术、龙眼肉、当归、远志、酸枣仁（炒）各二钱，木香一钱，甘草五分，当归身一钱。〔方义〕济生归脾汤益气养血、健脾养心；加柴胡、山栀即加味归脾汤。〔服法〕上药加生姜、大枣水煎，母子同服。"}, {"source": "条110｜《外科枢要》卷四·归脾汤", "原文": "《外科枢要》卷四：归脾汤。治忧思伤脾，血虚发热，食少体倦；或脾不能摄血，以致妄行吐下；或健忘怔忡，惊悸少寐；或心脾作痛，自汗盗汗；或肢体肿痛，大便不调；或妇人经候不准，晡热内热；或唇疮流注等症，不能消散溃敛。  \n白术、白茯苓、黄芪炒、当归、龙眼肉、远志、酸枣仁炒，各一钱 木香五分 甘草炙，三分 人参一钱  \n上姜、枣水煎服。", "白话": "〔主治〕治忧思伤脾，血虚发热，食少体倦；或脾不能摄血而妄行吐下；或健忘怔忡、惊悸少寐；或心脾作痛、自汗盗汗；或肢体肿痛、大便不调；或妇人月经不准、午后潮热内热；或唇疮流注等症不能消散收敛。〔组成·照录〕白术、白茯苓、黄芪（炒）、当归、龙眼肉、远志、酸枣仁（炒）各一钱，木香五分，甘草（炙）三分，人参一钱。〔方义〕归脾汤益气补血、健脾养心。〔服法〕上药加生姜、大枣水煎服。"}, {"source": "条111｜《疠疡机要》上卷·四君子汤", "原文": "《疠疡机要》上卷：一怔忡无寐，或兼衄血便血，若内热晡热，作渴饮汤，肢体倦怠，此脾血虚而火动也，用四君子加芎归；若思虑伤脾动火而致，用归脾汤加山栀；若发热晡热，用八珍汤加酸枣仁、茯神、远志；若因心血虚损，用柏子仁散。大抵此症皆心脾血少所致，但调补胃气，则痰清而神自安，不必专于清热治痰。", "白话": "〔主治·论〕凡怔忡失眠，或兼鼻衄便血，若内热、午后潮热，口渴喜饮热水，肢体倦怠——此脾血虚而火动，用四君子汤加川芎、当归；若思虑伤脾动火所致，用归脾汤加山栀；若发热、午后潮热，用八珍汤加酸枣仁、茯神、远志；若因心血虚损，用柏子仁散。大抵此证皆心脾血少所致，只要调补胃气，则痰清而神自安，不必专于清热治痰。〔组成·照录〕原稿未载。〔方义〕四君子益气健脾以养心，属治病求本之论。"}, {"source": "条112｜《古今医统大全》卷十八·养劳汤", "原文": "《古今医统大全》卷十八：养劳汤。治五疸虚弱，脚软心悸，口淡耳鸣，微发寒热，气急，小便白浊，当作虚劳治之。", "白话": "〔主治〕治五疸虚弱，脚软心悸，口淡耳鸣，微发寒热，气急，小便白浊——当作虚劳治疗。〔组成·照录〕原稿未载。〔方义〕养劳汤补虚劳、退黄疸，与《医学纲目》养荣汤（条84）主治相同。〔服法〕原稿未载。"}, {"source": "条113｜《古今医统大全》卷四十八·补气汤", "原文": "《古今医统大全》卷四十八：《瑞竹》补气汤。治气虚脉浮而弱，怔忡，无力，自汗。  \n黄芪三两，蜜水炒 人参、甘草炙，各半两 麦门冬、桔梗各一两  \n上咀，每服四钱，姜三片煎服。", "白话": "〔出处〕《古今医统大全》引《瑞竹》补气汤。〔主治〕治气虚，脉浮而弱，怔忡，乏力，自汗。〔组成·照录〕黄芪三两（蜜水炒），人参、甘草（炙）各半两，麦门冬、桔梗各一两。〔方义〕黄芪、参、草益气固表，麦冬养阴，桔梗载药上行、宣肺益气。〔服法〕上药切碎，每服四钱，加生姜三片煎服。"}, {"source": "条114｜《古今医统大全》卷四十九·养心汤", "原文": "《古今医统大全》卷四十九：养心汤。治心血虚少，七情郁逆，怔忡、健忘，惊悸，不识人事。", "白话": "〔主治〕治心血虚少，七情郁结上逆，怔忡、健忘、惊悸，甚至不识人事。〔组成·照录〕原稿未载。〔方义〕养心汤益气养血、安神定志（组成参见条58）。〔服法〕原稿未载。"}, {"source": "条115｜《古今医统大全》卷八十九·龙胆丸", "原文": "《古今医统大全》卷八十九：龙胆丸。治小儿心疳，颊赤面黄，鼻干心燥，口内生疮，惊悸。  \n龙胆草 赤茯苓 川黄连 胡黄连 朱砂二钱 麝香一字  \n上为极细末，蒸饼泡为丸，黍米大。每服二十丸，食远白汤下。", "白话": "〔主治〕治小儿心疳，两颊红赤、面色黄，鼻干心燥，口内生疮，惊悸。〔组成·照录〕龙胆草、赤茯苓、川黄连、胡黄连、朱砂二钱、麝香一字。〔方义〕龙胆、二连清心肝疳热，赤苓利湿，朱砂镇心，麝香开窍，为小儿心疳惊悸之方。〔制法·服法〕上为极细末，蒸饼泡为丸如黍米大，每服二十丸，食远白开水下。"}, {"source": "条116｜《明医指掌》卷三·四物汤", "原文": "《明医指掌》卷三：四物汤。补血之要药。  \n当归二钱，分三，治血中主药也，通肝经，全能活血，各归其经也  熟地黄一钱，血中血药也，通肾经，能生真阴之虚也  川芎一钱半，血中气药也，通肝经，能行血滞于气也  白芍药一钱半，阴分药也，通脾经，能治血虚腹痛也  \n上锉，一剂，水煎服。怔忡恍惚，加远志、枣仁。", "白话": "〔方名〕四物汤，补血之要药。〔组成·照录〕当归二钱（原稿注：治血中主药，通肝经，全能活血，各归其经），熟地黄一钱（血中血药，通肾经，能生真阴之虚），川芎一钱半（血中气药，通肝经，能行血滞于气），白芍药一钱半（阴分药，通脾经，能治血虚腹痛）。〔方义〕归、芎、地、芍四物配伍，补血调血，为补血之祖方。〔服法〕上药切碎，一剂水煎服。〔加减〕怔忡恍惚加远志、枣仁。"}, {"source": "条117｜《明医指掌》卷四·四君子汤", "原文": "《明医指掌》卷四：虚黄者，口淡怔忡，耳鸣脚软，怠惰无力，寒热溲白是也。虚黄  虚黄耳鸣口淡，怔忡微热，四肢无力，怠惰嗜卧，脚软脉沉细，四君子汤。若兼食积发黄者，小温中丸、大温中丸、或用六君子汤加茵陈、苍术、山药。", "白话": "〔主治〕虚黄：口淡、怔忡、耳鸣、脚软、怠惰无力、恶寒发热、小便色白。虚黄——耳鸣口淡、怔忡微热、四肢无力、怠惰嗜卧、脚软、脉沉细者，用四君子汤。〔组成·照录〕原稿未载（四君子汤：人参、白术、茯苓、甘草）。〔方义〕四君子益气健脾，气旺则黄退悸止。〔加减〕若兼食积发黄，用小温中丸、大温中丸，或六君子汤加茵陈、苍术、山药。"}, {"source": "条118｜《明医指掌》卷四·补中益气汤", "原文": "《明医指掌》卷四：补中益气汤。治形神劳役并饮食失节，劳倦虚损，身热而烦，脉洪大而虚，头痛，或恶寒而渴，自汗无力，气高而喘。  \n黄芪蜜炙，一钱五分 人参一钱 甘草炙，五分 归身酒洗，一钱 陈皮不去白，五分 白术五分 柴胡三分 升麻三分  \n上锉，一剂，生姜三片，大枣二枚，水煎温服。按：经曰：五味入口，甘先入脾。是方参、芪、归、术、甘草皆甘物也，故可以入脾而补中气……如用心太过，神思不宁，或怔忡惊悸", "白话": "〔主治〕治形体精神劳役及饮食失节，劳倦虚损，身热而烦，脉洪大而虚，头痛，或恶寒而口渴，自汗无力，气粗而喘。〔组成·照录〕黄芪（蜜炙）一钱五分、人参一钱、甘草（炙）五分、归身（酒洗）一钱、陈皮（不去白）五分、白术五分、柴胡三分、升麻三分。〔方义〕黄芪、参、术、草益气补中，当归养血，陈皮理气，柴胡、升麻升举清阳，为补中益气之名方。〔服法〕上药切碎，一剂加生姜三片、大枣二枚，水煎温服。按语：经曰“五味入口，甘先入脾”，此方参、芪、归、术、甘草都是甘味之品，故能入脾而补中气……（原稿"}, {"source": "条119｜《明医指掌》卷七·戊字号保真汤", "原文": "《明医指掌》卷七：戊字号保真汤。治劳证骨蒸体热而虚。  \n当归三分，酒洗 人参三分，去芦 生地黄三分 熟地黄三分 白术三分，炒 黄芪三分，蜜炙 赤茯苓三分 白茯苓三分 天冬二分，去心 麦冬二分，去心 赤芍药分半 白芍药分半 知母二分，盐炒 黄柏二分，盐炒 五味子二分 甘草一分半 陈皮一分半 柴胡二分 地骨皮二分  \n上，用水二盏，姜三片，枣五枚，莲心五个，每日三食前各进一服。惊悸加茯苓、茯神、远志", "白话": "〔主治〕治劳证骨蒸、体热而虚。〔组成·照录〕当归三分（酒洗）、人参三分（去芦）、生地黄三分、熟地黄三分、白术三分（炒）、黄芪三分（蜜炙）、赤茯苓三分、白茯苓三分、天冬二分（去心）、麦冬二分（去心）、赤芍药分半、白芍药分半、知母二分（盐炒）、黄柏二分（盐炒）、五味子二分、甘草一分半、陈皮一分半、柴胡二分、地骨皮二分。〔方义〕十全大补合二冬、知柏、地骨皮，气血双补兼清虚热，为保真之剂。〔服法〕上药用水二盏加生姜三片、大枣五枚、莲心五个，每日三餐前各进一服。〔加减〕惊悸加茯苓、茯神"}, {"source": "条120｜《医便》卷三·归脾汤", "原文": "《医便》卷三：归脾汤。治思虑过度，损伤心血，健忘怔忡，不寐。此药解郁结，养心健脾生血。  \n白术、白茯苓、黄芪 、归各一钱 木香三分 圆眼肉三枚 人参八分 甘草炙，三分 酸枣仁炒研，一钱二分  \n上用姜一片，枣一枚，水煎，食远服。", "白话": "〔主治〕治思虑过度，损伤心血，健忘怔忡，不寐；此药能解郁结、养心健脾生血。〔组成·照录〕白术、白茯苓、黄芪、当归各一钱，木香三分，圆眼肉三枚，人参八分，甘草（炙）三分，酸枣仁（炒，研）一钱二分。〔方义〕归脾汤益气养血、健脾养心、解郁安神。〔服法〕上药加生姜一片、大枣一枚，水煎，食远服。"}, {"source": "条121｜《古今医鉴》卷七·清离滋坎汤", "原文": "《古今医鉴》卷七：清离滋坎汤云林制。治阴血虚相火旺，盗汗潮热，咳嗽吐痰，一切虚劳等症，并加治之。  \n生地黄二钱 熟地黄二钱 天门冬一钱 麦门冬一钱 当归酒洗，一钱 白芍酒炒，一钱 山茱萸酒蒸，去核，一钱五分 干山药一钱 白茯苓八分 白术土炒，一钱 牡丹皮一钱二分 泽泻八分 黄柏蜜炒，八分 知母蜜炒，八分 甘草炙，七分  \n上锉一剂，水煎服。嗽盛，加紫菀、款冬花。痰盛，加贝母、栝蒌仁。热盛，加地骨", "白话": "〔出处〕清离滋坎汤，云林（龚廷贤）制。〔主治〕治阴血虚、相火旺，盗汗潮热，咳嗽吐痰，一切虚劳等证，都可加减治之。〔组成·照录〕生地黄二钱、熟地黄二钱、天门冬一钱、麦门冬一钱、当归（酒洗）一钱、白芍（酒炒）一钱、山茱萸（酒蒸，去核）一钱五分、干山药一钱、白茯苓八分、白术（土炒）一钱、牡丹皮一钱二分、泽泻八分、黄柏（蜜炒）八分、知母（蜜炒）八分、甘草（炙）七分。〔方义〕六味地黄合二冬、归芍滋阴补血，知柏清相火，白术、甘草健脾，为滋阴降火之剂。〔服法〕上药切碎一剂，水煎服。〔加减〕"}, {"source": "条122｜《古今医鉴》卷八·养心汤", "原文": "《古今医鉴》卷八：养心汤。治用心过度，心热遗精，恍惚多梦，或惊而不寐者。  \n人参 山药 茯神 麦门冬 当归身 白芍 石莲肉 远志 酸枣仁 鸡头实 莲花须 子芩酒洗  \n上锉一剂，加生姜三片，枣一枚，水煎服。气虚，加黄芪、白术；血虚，加熟地黄；遗久气陷，加川芎、升麻，去子芩。", "白话": "〔主治〕治用心过度，心热遗精，恍惚多梦，或受惊而不寐者。〔组成·照录〕人参、山药、茯神、麦门冬、当归身、白芍、石莲肉、远志、酸枣仁、鸡头实、莲花须、子芩（酒洗）。〔方义〕参、药益气，归、芍养血，茯神、远志、枣仁、莲须、芡实养心固精，麦冬、黄芩清心，为养心安神固精之剂。〔服法〕上药切碎一剂，加生姜三片、大枣一枚，水煎服。〔加减〕气虚加黄芪、白术；血虚加熟地黄；遗精日久气陷加川芎、升麻，去子芩。"}, {"source": "条123｜《医方考》卷五·养心汤", "原文": "《医方考》卷五：养心汤。  \n黄芪、白茯苓、茯神、半夏曲、当归、川芎各半两 柏子仁、酸枣仁炒、人参、远志去心，姜汁炒、五味子、辣桂各二钱半 甘草炙，四钱  \n每服五钱。心血虚少，神气不宁，令人惊悸怔忡者，此方主之。", "白话": "〔组成·照录〕黄芪、白茯苓、茯神、半夏曲、当归、川芎各半两，柏子仁、酸枣仁（炒）、人参、远志（去心，姜汁炒）、五味子、辣桂各二钱半，甘草（炙）四钱。〔主治〕心血虚少，神气不宁，使人惊悸怔忡者，此方主治。〔方义〕《医方考》方：益气养血、养心安神。〔服法〕每服五钱（水煎）。"}, {"source": "条124｜《仁术便览》卷三·养心汤", "原文": "《仁术便览》卷三：养心汤。治忧愁思虑，伤心，惊悸不宁。治停水，怔忡，加槟榔、赤茯苓。  \n黄芪、白茯、茯神、半夏曲、当归、川芎各五钱 甘草四钱、辣桂、远志去心，姜汁炒、柏子仁、五味子、酸枣仁、人参各二钱半  \n上每服三钱，姜三片，枣一枚煎。", "白话": "〔主治〕治忧愁思虑伤心，惊悸不宁；治水停怔忡，加槟榔、赤茯苓。〔组成·照录〕黄芪、白茯、茯神、半夏曲、当归、川芎各五钱，甘草四钱，辣桂、远志（去心，姜汁炒）、柏子仁、五味子、酸枣仁、人参各二钱半。〔方义〕即通行养心汤，益气养血、安神定悸。〔服法〕上药每服三钱，加生姜三片、大枣一枚煎。"}, {"source": "条125｜《万病回春》卷四·加味八珍丸", "原文": "《万病回春》卷四：加味八珍丸。大补血气、壮脾胃、益虚损。  \n当归酒洗，二两 南芎一两二钱 白芍酒炒，一两半 熟地黄酒蒸晒干，二两 人参去芦，二两 白术去芦，炒，二两 白茯苓去皮，二两 粉草蜜炙，七钱 陈皮二两  \n惊悸怔忡，加远志甘草水泡，去骨，二两，酸枣仁炒，一两。", "白话": "〔功能·主治〕大补气血、强壮脾胃、补益虚损。〔组成·照录〕当归（酒洗）二两、南芎一两二钱、白芍（酒炒）一两半、熟地黄（酒蒸晒干）二两、人参（去芦）二两、白术（去芦，炒）二两、白茯苓（去皮）二两、粉草（蜜炙）七钱、陈皮二两。〔方义〕八珍汤（四君子汤合四物汤）加陈皮，气血双补、健脾理气，为丸剂。〔加减〕惊悸怔忡加远志（甘草水泡，去骨）二两、酸枣仁（炒）一两。〔服法〕原稿未载，据方名当为丸剂。"}, {"source": "条126｜《万病回春》卷四·四物安神汤", "原文": "《万病回春》卷四：怔忡者，心无血养，如鱼无水，心中惕惕然而跳动也，如人将捕捉之貌。若思虑即心跳者，是血虚也。四物安神汤治心中无血养，故作怔忡。兼服辰砂安神丸。  \n当归酒洗 白芍酒炒 生地黄酒洗 熟地黄 人参去芦 白术去芦 茯神去皮木 酸枣仁炒 黄连姜炒 栀子炒 麦门冬去心 竹茹 辰砂研末，临服调入 乌梅一个  \n上锉一剂。枣二枚，炒米一撮，水煎，食远服。心若时跳时止者，是痰因火动也。二陈汤治痰因", "白话": "〔医论〕怔忡，是心无血养，如鱼无水，心中惕惕跳动，如被人追捕之状；若一思虑即心跳者，是血虚。四物安神汤治心中无血养而作怔忡，兼服辰砂安神丸。〔组成·照录〕当归（酒洗）、白芍（酒炒）、生地黄（酒洗）、熟地黄、人参（去芦）、白术（去芦）、茯神（去皮木）、酸枣仁（炒）、黄连（姜炒）、栀子（炒）、麦门冬（去心）、竹茹、辰砂（研末，临服调入）、乌梅一个。〔方义〕四物养血，参、术益气，茯神、枣仁安神，连、栀、竹茹清热化痰，为养血清热安神之剂。〔服法〕上药切碎一剂，加大枣二枚、炒米一撮，水"}, {"source": "条127｜《云林神彀》卷二·六味地黄丸", "原文": "《云林神彀》卷二：六味地黄丸治健忘怔忡，惊悸不寐，加远志肉、石菖蒲、人参、白茯神、当归、酸枣仁炒，各二钱。宁心保神，益血固精，壮力强志，定魄镇惊，怔忡健忘，痰火能清。", "白话": "〔主治〕六味地黄丸治健忘怔忡、惊悸不寐，加远志肉、石菖蒲、人参、白茯神、当归、酸枣仁（炒）各二钱。功能宁心保神、益血固精、壮力强志、定魄镇惊，治怔忡健忘，兼清痰火。〔组成·照录〕原稿未载六味本方（熟地、山药、山萸、丹皮、泽泻、茯苓），仅载加味药。〔方义〕六味地黄滋补肾阴，加味养心安神、益气养血。〔服法〕原稿未载，参见六味地黄丸服法。"}, {"source": "条128｜《医学原理》卷五·滋阴大补丸", "原文": "《医学原理》卷五：滋阴大补丸。  \n枸杞子甘温，补劳伤、益精强阴、济虚弱，三两  苁蓉甘酸温，益精补肾，酒浸洗，瓦焙干，二两  熟地黄甘寒，滋肾水、益真阴、补血，四两  巴戟辛甘温，益精气，去心，七分  茴香辛甘温，通肾气，七钱  远志苦温，安心神，定恍惚，补虚劳，去心，甘草水煮，七钱  山药甘温，补中、益精气，二两  牛膝苦酸平，行血、益精、壮筋，二两  杜仲辛甘温，益肾填精，炒，去丝，二两  ", "白话": "〔方名〕滋阴大补丸。〔组成·照录（原稿逐药附注性味功效）〕枸杞子（甘温，补劳伤、益精强阴、济虚弱）三两；苁蓉（甘酸温，益精补肾，酒浸洗，瓦焙干）二两；熟地黄（甘寒，滋肾水、益真阴、补血）四两；巴戟（辛甘温，益精气，去心）七分；茴香（辛甘温，通肾气）七钱；远志（苦温，安心神、定恍惚、补虚劳，去心，甘草水煮）七钱；山药（甘温，补中、益精气）二两；牛膝（苦酸平，行血、益精、壮筋）二两；杜仲（辛甘温，益肾填精，炒，去丝）二两；白茯苓（甘淡平，止惊悸，去皮）二两；五味子（甘酸平）五钱；"}, {"source": "条129｜《医学原理》卷五·八味定志丸", "原文": "《医学原理》卷五：八味定志丸。治中气虚败，以致心气不足，邪热上攻，恍惚惊悸，喘嗽不宁。治宜补中益心气，清热安心为主。故用参、苓、白术等补中气为本，麦冬清肺止嗽，牛黄、朱砂退热镇心，佐菖蒲、远志、茯神等安神定魄，以止惊悸恍惚。", "白话": "〔主治·方义〕八味定志丸治中气虚败，以致心气不足，邪热上攻，恍惚惊悸，喘嗽不宁。治宜补中益心气、清热安心为主：故用人参、茯苓、白术等补中气为本，麦冬清肺止咳，牛黄、朱砂退热镇心，佐菖蒲、远志、茯神等安神定魄，以止惊悸恍惚。〔组成·照录〕原稿仅于方义中述及诸药，未列剂量。〔服法〕原稿未载。"}, {"source": "条130｜《医学原理》卷五·四物汤", "原文": "《医学原理》卷五：痨瘵之症五，脏必归于一经，治宜分经而疗。如足酸，腰疼，背拘急，遗白浊，面带黧色，耳轮焦枯，脉沉细数，此乃肾经受伤。宜四物加黄柏、知母、五味、麦冬、泽泻、杜仲、肉桂之类，煎熟入童便、韭汁、竹沥。如心神惊悸怔忡，无时盗汗，心烦热闷，口舌生疮，咯血面赤，脉洪而数，乃心经受伤，以前方去杜仲、泽泻、肉桂，加茯神、莲心、黄连、远志、菖蒲、朱砂之类。", "白话": "〔医论〕痨瘵之证有五，病必归于一经，治疗宜分经而治。如足酸、腰痛、背拘急、遗精白浊、面色黧黑、耳轮焦枯、脉沉细数——此为肾经受伤，宜四物汤加黄柏、知母、五味、麦冬、泽泻、杜仲、肉桂之类，煎好后兑入童便、韭汁、竹沥。如心神惊悸怔忡、不定时盗汗、心烦热闷、口舌生疮、咯血面赤、脉洪而数——乃心经受伤，用前方去杜仲、泽泻、肉桂，加茯神、莲心、黄连、远志、菖蒲、朱砂之类。〔方义〕四物养血为底，随证分经加减，属异病同治。〔服法〕见上文。"}, {"source": "条131｜《医学原理》卷九·四物汤", "原文": "《医学原理》卷九：凡心跳，亦属血少，宜四物汤送朱砂安神丸及养心汤之类。或问：人当惊恐后，何故作此症？盖惊则神出其舍，神舍空虚，痰气上乘所致，亦宜用养心汤为主加减。", "白话": "〔医论〕凡心跳，也属血少，宜用四物汤送服朱砂安神丸及养心汤之类。或问：人在惊恐之后，为何发此证？盖因惊则神出于心舍，神舍空虚，痰气乘虚上扰所致——也宜以养心汤为主加减治疗。〔方义〕四物补血、养心安神，痰气上乘者佐以化痰。〔组成·服法〕原稿未载。"}, {"source": "条132｜《万氏家抄济世良方》卷二·加减四物汤", "原文": "《万氏家抄济世良方》卷二：加减四物汤。治瘦人血少，怔忡无时但觉心跳者。  \n当归 芍药 生地黄 茯神 酸枣仁 远志  \n钟半，煎七分，通口服。", "白话": "〔主治〕治瘦人血少，怔忡不定时、但觉心跳者。〔组成·照录〕当归、芍药、生地黄、茯神、酸枣仁、远志。〔方义〕四物减川芎，加茯神、枣仁、远志，养血安神。〔服法〕原稿作“钟半，煎七分，通口服”（水盅半煎取七分，一次服尽）。"}, {"source": "条133｜《证治准绳·类方》·滋阴抑火汤", "原文": "《证治准绳·类方》：滋阴抑火汤。  \n当归、芍药煨、生地黄、川芎、黄连、知母、熟地黄各一钱 肉桂、甘草各五分  \n若身如飞扬，心跳不定，加紫石英、人参各一钱。上水二盅，煎七分，入童便半盏，食前服。", "白话": "〔组成·照录〕当归、芍药（煨）、生地黄、川芎、黄连、知母、熟地黄各一钱，肉桂、甘草各五分。〔主治·加减〕若身如飞扬、心跳不定，加紫石英、人参各一钱。〔方义〕四物合知母、黄连滋阴抑火，肉桂引火归元，为滋阴降火之剂。〔服法〕上药水二盅煎至七分，兑入童便半盏，食前服。"}, {"source": "条134｜《幼科证治准绳》集二·羌活膏", "原文": "《幼科证治准绳》集二：治慢惊者谓土虚泄泻，火木乘之，谓手掌与腹俱热之证，若火木土俱虚而摇动恐悸、注泻、手腹冷者，非羌活膏不能治之。", "白话": "〔主治·论〕治慢惊风：所谓土虚泄泻、火木乘之，即手掌与腹部俱热之证；若火、木、土俱虚而肢体摇动、恐惧惊悸、洞泻、手腹冷者，非羌活膏不能治。〔组成·照录〕原稿未载。〔方义〕羌活膏疏风定搐，为慢惊风而设（组成详见原书）。"}, {"source": "条135｜《幼科证治准绳》集四·木香散", "原文": "《幼科证治准绳》集四：今也不然，但见出迟者、身热者、泄泻者、惊悸者、气急者、渴思饮者，不问寒热虚实，率投木香散、异功散，间有偶中，随手获效，设或误投，祸不旋踵。", "白话": "〔医论〕如今却不然，只要见出疹迟、身热、泄泻、惊悸、气急、口渴思饮者，不问寒热虚实，一律投木香散、异功散；间或偶然命中，随手取效，但若误投，祸患立至。〔方义〕本条为批评滥用木香散之医论。〔组成·服法〕原稿未载。"}, {"source": "条136｜《幼科证治准绳》集五·木香散", "原文": "《幼科证治准绳》集五：文中云：腹胀渴者，泻渴者，足指冷渴者，惊悸渴者，身温渴者，身热面㿠白色渴者，寒战渴不止者，气急咬牙渴者，饮水转水泻不已者，以上九证，即非热也，乃津液少，脾胃肌肉虚故也，宜木香散治之。如不愈，更加丁香、官桂此说，必加审用之，胀渴、泻渴、惊悸渴、寒战渴、咬牙渴、亦多属热者，不可不察。", "白话": "〔医论〕文中说：腹胀而渴、泻下而渴、足趾冷而渴、惊悸而渴、身温而渴、身热而面色㿠白而渴、寒战而渴不止、气急咬牙而渴、饮水即水泻不已——以上九证，并非热证，而是津液少、脾胃肌肉虚的缘故，宜用木香散治疗；如不愈，更加丁香、官桂。此说须审慎运用：胀渴、泻渴、惊悸渴、寒战渴、咬牙渴也有属热者，不可不辨。〔方义〕木香散温中健脾、生津止渴，为渴证之属虚寒者设。〔组成·服法〕原稿未载。"}, {"source": "条137｜《女科证治准绳》卷五·白茯苓散", "原文": "《女科证治准绳》卷五：白茯苓散。治产后心神惊悸，言语失常，心神昏愦。  \n白茯苓去皮、熟地黄、人参去芦，各一两半 远志去心、白芍药、黄芪去芦、桂心、当归炒，去芦、甘草炙、麦门冬各一两，去心  石菖蒲、桑寄生各七钱半  \n上为㕮咀，每服八钱，水一大盏半，生姜五片，枣三枚，竹叶三七片，煎至一大盏，去渣温服，无时。", "白话": "〔主治〕治产后心神惊悸，言语失常，心神昏乱。〔组成·照录〕白茯苓（去皮）、熟地黄、人参（去芦）各一两半，远志（去心）、白芍药、黄芪（去芦）、桂心、当归（炒，去芦）、甘草（炙）、麦门冬（去心）各一两，石菖蒲、桑寄生各七钱半。〔方义〕茯苓、远志、菖蒲安神，参、芪、草益气，归、芍、地养血，麦冬滋阴，桂心通阳，桑寄生养血安胎。〔服法〕上药切碎，每服八钱，水一大盏半加生姜五片、大枣三枚、竹叶三至七片，煎至一大盏去渣温服，不拘时。"}, {"source": "条138｜《女科证治准绳》卷五·黑神散", "原文": "《女科证治准绳》卷五：产后血气不通，咳嗽者何？答曰：产后咳嗽，多因食热面壅滞，或热病，或有气块，发时冲心痛，气急咳嗽，四肢寒热，心闷口干，或时烦躁，睡梦惊悸，气虚肢体无力，宜服《局方》黑神散、五积散加枣煎服。", "白话": "〔问答〕产后血气不通而咳嗽者为何？答：产后咳嗽，多因食热面壅滞，或热病，或有气块，发作时冲心而痛、气急咳嗽、四肢寒热、心闷口干，或时时烦躁、睡梦惊悸、气虚肢体无力——宜服《局方》黑神散、五积散加枣煎服。〔组成·照录〕原稿未载（黑神散、五积散均为《局方》成方）。〔方义〕黑神散温经活血，五积散解表温里，加枣和中。"}, {"source": "条139｜《先醒斋医学广笔记》卷二·产后调理方", "原文": "《先醒斋医学广笔记》卷二：产后调理方仲淳立，如产时恶露过多，无儿枕痛者，不可用此方。  \n当归身三钱 川芎一钱五分 生地二钱 赤芍药一钱五分 延胡索醋煮，二钱 牛膝五钱 蒲黄一钱五分 干姜炒黑，七分 肉桂七分，火盛者并夏月勿用 山楂肉三钱 五灵脂醋煮去沙，一钱 桃仁去皮尖、红花各八分 黑豆炒，一合 杜仲炒去丝，二钱 续断二钱 益母草五钱，瘀血行腹痛去之 泽兰叶一钱 荆芥穗一钱，炒  \n水煎，入童便", "白话": "〔出处·禁忌〕产后调理方，缪仲淳立。如产时恶露过多、无儿枕痛者，不可用此方。〔组成·照录〕当归身三钱、川芎一钱五分、生地二钱、赤芍药一钱五分、延胡索（醋煮）二钱、牛膝五钱、蒲黄一钱五分、干姜（炒黑）七分、肉桂七分（火盛者及夏月勿用）、山楂肉三钱、五灵脂（醋煮去沙）一钱、桃仁（去皮尖）、红花各八分、黑豆（炒）一合、杜仲（炒去丝）二钱、续断二钱、益母草五钱（瘀血已行、腹痛者去之）、泽兰叶一钱、荆芥穗（炒）一钱。〔方义〕生化汤加减：归、芎、地、芍养血，桃仁、红花、蒲黄、灵脂、延胡、"}, {"source": "条140｜《疹科类编·方》·加味四物汤", "原文": "《疹科类编·方》：加味四物汤。治疹后时发壮热，烦躁不宁，搐掣惊悸，神昏志乱者。此阴血衰耗，致余毒入肝而传于心也，宜用此养血安神。  \n当归 川芎 芍药 生地黄 麦门冬去心 茯神去木 石菖蒲 酸枣仁炒 龙胆草 黄连 甘草 辰砂 淡竹叶 灯心草  \n上锉，水煎服。或为末，用蒸饼猪心血丸亦可。", "白话": "〔主治〕治疹后时时壮热，烦躁不宁，抽掣惊悸，神昏志乱者。此因阴血衰耗，致余毒入肝而传于心，宜用此方养血安神。〔组成·照录〕当归、川芎、芍药、生地黄、麦门冬（去心）、茯神（去木）、石菖蒲、酸枣仁（炒）、龙胆草、黄连、甘草、辰砂、淡竹叶、灯心草。〔方义〕四物养血，麦冬滋阴，茯神、菖蒲、枣仁安神，龙胆、黄连清肝心余毒，辰砂镇心。〔服法〕上药切碎，水煎服；或为末，用蒸饼、猪心血为丸亦可。"}, {"source": "条141｜《外科正宗》卷二·滋荣散坚汤", "原文": "《外科正宗》卷二：滋荣散坚汤。滋阴散坚四物汤，甘桔参苓海粉当，陈术升麻香附贝，红花昆布共煎尝。治一切瘰疬，忧抑所伤，气血不足，形体瘦弱，潮热咳嗽，坚硬肿痛。毋分新久，但未穿溃者并效。  \n川芎、当归、白芍、熟地、陈皮、茯苓、桔梗、白术、香附各一钱 甘草、海粉、贝母、人参、昆布各五分 升麻、红花各三分  \n水二钟，姜三片，枣二枚，煎八分，食远服。身热加柴胡、黄芩，自汗盗汗去升麻倍人参、黄芪，饭食无味", "白话": "〔方歌〕滋阴散坚四物汤，甘桔参苓海粉当，陈术升麻香附贝，红花昆布共煎尝。〔主治〕治一切瘰疬，因忧郁所伤，气血不足，形体瘦弱，潮热咳嗽，坚硬肿痛；不论新久，凡未穿溃者都有效。〔组成·照录〕川芎、当归、白芍、熟地、陈皮、茯苓、桔梗、白术、香附各一钱，甘草、海粉、贝母、人参、昆布各五分，升麻、红花各三分。〔方义〕四物养血，参、术、苓、草益气，海粉、昆布、贝母软坚化痰，香附、陈皮理气，升麻、桔梗升散，红花活血。〔服法〕水二钟加生姜三片、大枣二枚，煎取八分，食远服。〔加减〕身热加柴胡、"}, {"source": "条142｜《济阴纲目》卷十二·琥珀散", "原文": "《济阴纲目》卷十二：琥珀散。治血虚，惊悸少寐，及产后败血停留，少腹作痛。  \n辰砂另研、没药、琥珀并研细、当归等分  \n上为细末，每服二钱，空心日午临卧白汤调下。", "白话": "〔主治〕治血虚惊悸、睡眠少，及产后败血停留、小腹作痛。〔组成·照录〕辰砂（另研）、没药、琥珀（同研细）、当归各等分。〔方义〕琥珀、辰砂镇心安神，当归养血，没药活血止痛。〔服法〕上为细末，每服二钱，空腹、日午、临卧白开水调下。"}, {"source": "条143｜《婴童类萃》下卷·大建中汤", "原文": "《婴童类萃》下卷：大建中汤。治虚热盗汗，怔忡惊悸，四肢倦怠，气促。  \n黄芪一钱，蜜炒 远志肉、当归各八分 泽泻、白芍、人参、甘草炙、酸枣仁炒、龙骨煨研，各五分", "白话": "〔主治〕治虚热盗汗，怔忡惊悸，四肢倦怠，气促。〔组成·照录〕黄芪（蜜炒）一钱，远志肉、当归各八分，泽泻、白芍、人参、甘草（炙）、酸枣仁（炒）、龙骨（煨，研）各五分。〔方义〕参、芪、草益气，归、芍养血，远志、枣仁、龙骨安神敛汗，泽泻利湿，为益气养血、安神止汗之剂。〔服法〕原稿未载（据方义当水煎服）。"}, {"source": "条144｜《景岳全书》卷五十一·小营煎", "原文": "《景岳全书》卷五十一：小营煎。治血少阴虚，此性味平和之方也。  \n当归二钱 熟地二、三钱 芍药酒炒，二钱 山药炒，二钱 枸杞二钱 炙甘草一钱  \n水二钟，煎七分，食远温服。如营虚于上，而为惊恐怔忡，不眠多汗者，加枣仁、茯神各二钱；如营虚兼寒者，去芍药，加生姜；如气滞有痛者，加香附一二钱，引而行之。", "白话": "〔主治〕治血少阴虚，此为性味平和之方。〔组成·照录〕当归二钱、熟地二至三钱、芍药（酒炒）二钱、山药（炒）二钱、枸杞二钱、炙甘草一钱。〔方义〕归、地、芍、杞养血滋阴，山药、甘草健脾和中，为平补营血之剂。〔服法〕水二钟煎取七分，食远温服。〔加减〕如营虚在上而见惊恐怔忡、不眠多汗，加枣仁、茯神各二钱；营虚兼寒去芍药加生姜；气滞有痛加香附一二钱以行之。"}, {"source": "条145｜《景岳全书》卷五十一·右归丸", "原文": "《景岳全书》卷五十一：右归丸。治元阳不足，或先天禀衰，或劳伤过度，以致命门火衰，不能生土，而为脾胃虚寒，饮食少进，或呕恶膨胀，或番胃噎膈，或怯寒畏冷，或脐腹多痛，或大便不实，泻痢频作，或小水自遗，虚淋寒疝，或寒侵溪谷而肢节痹痛，或寒在下焦而水邪浮肿。总之，真阳不足者，必神疲气怯，或心跳不宁，或四体不收，或眼见邪崇，或阳衰无子等证，俱速宜益火之原，以培右肾之元阳，而神气自强矣，此方主之。  \n大怀熟", "白话": "〔主治〕治元阳不足：或先天禀赋不足，或劳伤过度，以致命门火衰、不能生土，而为脾胃虚寒、饮食少进，或呕恶腹胀，或反胃噎膈，或怯寒怕冷，或脐腹多痛，或大便不实、泻痢频作，或小便自遗、虚淋寒疝，或寒侵溪谷而肢节痹痛，或寒在下焦而水邪浮肿。总之真阳不足者，必神疲气怯，或心跳不宁，或四肢不收，或眼见邪祟，或阳衰无子等证——都宜急益火之原，以培右肾元阳，则神气自强，此方主治。〔组成·照录〕大怀熟（地）八两、山药（炒）四两、山茱萸（微炒）三两、枸杞（微炒）四两、鹿角胶（炒珠）四两、菟丝子（"}, {"source": "条146｜《景岳全书》卷五十三·加味四君汤", "原文": "《景岳全书》卷五十三：加味四君汤。治痔漏下血，面色痿黄，怔忡耳鸣，脚软气弱，及一切脾胃气虚，口淡，食不知味，又治气虚不能摄血，以致下血不禁。  \n人参 白术炒 茯苓 炙甘草 黄芪炙 白扁豆炒  \n上水煎服。或为末，每服三钱，滚汤调服。", "白话": "〔主治〕治痔漏下血，面色萎黄，怔忡耳鸣，脚软气弱，及一切脾胃气虚、口淡、食不知味；又治气虚不能摄血而下血不止。〔组成·照录〕人参、白术（炒）、茯苓、炙甘草、黄芪（炙）、白扁豆（炒）。〔方义〕四君子汤加黄芪、扁豆，益气健脾、摄血止血。〔服法〕上药水煎服；或为末，每服三钱，滚开水调服。"}, {"source": "条147｜《济阳纲目》卷十六·当归补血汤", "原文": "《济阳纲目》卷十六：当归补血汤。治心中血少而嘈，兼治惊悸怔忡。  \n当归、芍药、生地黄、熟地黄各三钱 人参五分 白术、白茯苓、麦门冬去心、山栀仁炒、陈皮各八分 甘草、辰砂研末，临服入，各三分 乌梅一个，去核 炒米百粒  \n上锉一剂，加枣二枚，水煎，温服。", "白话": "〔主治〕治心中血少而嘈杂，兼治惊悸怔忡。〔组成·照录〕当归、芍药、生地黄、熟地黄各三钱，人参五分，白术、白茯苓、麦门冬（去心）、山栀仁（炒）、陈皮各八分，甘草、辰砂（研末，临服调入）各三分，乌梅一个（去核），炒米百粒。〔方义〕四物补血，参、术、苓、草益气，麦冬滋阴，栀子清热，辰砂镇心，为补血清热安神之剂。〔服法〕上药切碎一剂，加大枣二枚，水煎温服。"}, {"source": "条148｜《济阳纲目》卷五十四·养心安神汤", "原文": "《济阳纲目》卷五十四：养心安神汤。治血虚火动，惊悸怔忡。  \n当归身酒洗、川芎、白芍药炒、陈皮、黄连、柏子仁炒，各五分 生地黄酒炒、茯神各一钱 白术、酸枣仁炒，各七分 甘草炙，三分  \n上锉一服，水煎服。", "白话": "〔主治〕治血虚火动，惊悸怔忡。〔组成·照录〕当归身（酒洗）、川芎、白芍药（炒）、陈皮、黄连、柏子仁（炒）各五分，生地黄（酒炒）、茯神各一钱，白术、酸枣仁（炒）各七分，甘草（炙）三分。〔方义〕四物养血，连、地清热，茯神、柏子仁、枣仁安神，术、草健脾，为养血清火安神之剂。〔服法〕上药切碎一服，水煎服。"}, {"source": "条149｜《济阳纲目》卷五十五·人参远志丸", "原文": "《济阳纲目》卷五十五：人参远志丸。治心气不足，惊悸健忘，神思不安。  \n天门冬去心、白茯苓、菖蒲各七钱半 人参、远志去心、酸枣仁、黄芪各半两  桔梗、丹砂、官桂去皮，各二钱半  \n上为末，炼蜜丸如绿豆大，每服二十丸至三十丸，米汤下。", "白话": "〔主治〕治心气不足，惊悸健忘，神思不安。〔组成·照录〕天门冬（去心）、白茯苓、菖蒲各七钱半，人参、远志（去心）、酸枣仁、黄芪各半两，桔梗、丹砂、官桂（去皮）各二钱半。〔方义〕参、芪益气，天冬滋阴，菖蒲、远志、枣仁安神益智，丹砂镇心，官桂温阳。〔服法〕上为末，炼蜜为丸如绿豆大，每服二十至三十丸，米汤下。"}, {"source": "条150｜《济阳纲目》卷六十四·安神补心定志益元固真丸", "原文": "《济阳纲目》卷六十四：安神补心定志益元固真丸。安心安神，固精益血，壮力强志，令人善记不忘；除怔忡，定惊悸，清三焦，大化痰，祛烦热，疗咽干，滋肾水，健脾胃，悦颜色，生肌肤，不寒不热。  \n当归一两二钱，酒洗 天冬八钱，去心 麦冬一两，去心 柏子仁一两，炒 远志一两二钱，去皮，甘草浸 知母七钱，盐水炒 黄连一两，姜汁炒 百部五钱 酸枣仁一两，炒去油 白茯苓一两二钱 玄参七钱 生地黄二两，酒洗 石菖蒲一", "白话": "〔功能·主治〕安心安神，固精益血，壮力强志，使人善记不忘；除怔忡，定惊悸，清三焦，大化痰，祛烦热，疗咽干，滋肾水，健脾胃，悦颜色，生肌肤，不寒不热。〔组成·照录〕当归一两二钱（酒洗）、天冬八钱（去心）、麦冬一两（去心）、柏子仁一两（炒）、远志一两二钱（去皮，甘草浸）、知母七钱（盐水炒）、黄连一两（姜汁炒）、百部五钱、酸枣仁一两（炒去油）、白茯苓一两二钱、玄参七钱、生地黄二两（酒洗）、石菖蒲一两（炒）、熟地黄二两（酒洗）、杜仲一两（去丝，姜汁炒）、黄芪七钱（蜜炙）、枸杞子一两（"}, {"source": "条151｜《痰火点雪》卷一·芡实丸", "原文": "《痰火点雪》卷一：芡实丸。治思虑伤心，疲劳伤肾，心肾不交，精元不固，面无颜色，惊悸健忘，夜梦不宁，小便赤涩，遗精白浊，足胫酸痛，耳聋目昏，口干脚弱。  \n芡实取生肉，二两，益肾，固精，补脾 莲须一两，清心，通肾固精 茯神去木，一两，止惊悸，又开心益志，安魂魄，宁乱神，秘精髓，虚而小便不利者，加而用之 山茱萸取肉，二两，补肾气，添精髓，止小便不禁，养精气，取其味酸涩以收秘滑也 龙骨煅，研，五钱，治心", "白话": "〔主治〕治思虑伤心，疲劳伤肾，心肾不交，精元不固，面无颜色，惊悸健忘，夜梦不宁，小便赤涩，遗精白浊，足胫酸痛，耳聋目昏，口干脚弱。〔组成·照录（原稿逐药附注功效）〕芡实取生肉二两（益肾、固精、补脾）；莲须一两（清心、通肾固精）；茯神（去木）一两（止惊悸，又开心益志、安魂魄、宁乱神、秘精髓，虚而小便不利者加而用之）；山茱萸取肉二两（补肾气、添精髓、止小便不禁，取其味酸涩以收秘滑）；龙骨（煅，研）五钱（养精神、逐邪气、安心神、止夜梦，虚而多梦者益肾镇惊）；五味子（黑者）一两（治肾"}, {"source": "条152｜《医宗必读》卷十·镇心丸", "原文": "《医宗必读》卷十：镇心丸。治心血不足，怔忡多梦，如堕崖谷。  \n酸枣仁炒，二钱半 车前子去土、白茯苓去皮、麦门冬去心、五味子、茯神去木、 肉桂各一两二钱半 熟地黄酒浸，蒸、龙齿、天门冬去心、远志甘草水煮，去心、山药姜制，各一两半 人参、朱砂水飞为衣，各半两  \n上为末，蜜丸，梧子大，每服三钱，空心米汤下。", "白话": "〔主治〕治心血不足，怔忡多梦，梦中如堕崖谷。〔组成·照录〕酸枣仁（炒）二钱半，车前子（去土）、白茯苓（去皮）、麦门冬（去心）、五味子、茯神（去木）、肉桂各一两二钱半，熟地黄（酒浸，蒸）、龙齿、天门冬（去心）、远志（甘草水煮，去心）、山药（姜制）各一两半，人参、朱砂（水飞为衣）各半两。〔方义〕枣仁、茯神、远志、龙齿、朱砂镇心安神，二冬、熟地滋阴，参、药益气，肉桂温阳，车前子利湿，为镇心安神之丸。〔服法〕上为末，炼蜜为丸如梧桐子大，每服三钱，空腹米汤下。"}, {"source": "条153｜《绛雪丹书·产后》·加减养荣汤（附：养心汤、安神丸）", "原文": "《绛雪丹书·产后》：产妇惊忧劳倦，去血过多，以致心中躁动不宁，谓之怔忡；若惕然而惊，如人将捕之状，谓之惊悸。治此二症，唯调和脾胃，补养心血，使之志定神宁、气舒心安而病自愈矣。如分娩后血块未消而患此者，宜服生化汤以补血行血，血旺则惊悸自除，不必加定志安神剂；如块消痛止之后患此症，宜服后药。加减养荣汤内去川芎、麦冬，加木香，即归脾汤。  \n川芎一钱 当归二钱 茯苓、枣仁炒黑、人参、麦冬、远志、黄芪、白", "白话": "〔医论〕产妇惊忧劳倦、失血过多，以致心中躁动不宁，叫做怔忡；若突然受惊、如被人追捕之状，叫做惊悸。治此二证，只需调和脾胃、补养心血，使志定神宁、气舒心安，则病自愈。如分娩后血块未消而患此者，宜服生化汤补血行血，血旺则惊悸自除，不必加定志安神之药；如血块消、痛止之后患此证，宜服后方。〔方一·加减养荣汤〕组成照录：川芎一钱、当归二钱、茯苓、枣仁（炒黑）、人参、麦冬、远志、黄芪、白术各一钱，陈皮、炙草各四分，龙眼肉八分；方义：益气养血安神（加减养荣汤内去川芎、麦冬加木香即归脾汤）；"}, {"source": "条154｜《绛雪丹书·胎症》·补母寿子方", "原文": "《绛雪丹书·胎症》：补母寿子方。  \n人参二钱，弱甚加倍 白术、当归、熟地各二钱 川芎八分 炙草四分 条芩钱半 苏叶三分 陈皮三分 大枣三枚  \n煎服，内热加黄连五分；如肥人，陈皮去白加黄连五分；脾胃弱常泄泻加莲子十粒，带壳砂仁三分，减地黄；多怒而泻加木香三分；口燥加麦冬一钱；怔忡、惊悸加枣仁、益智仁各一钱，龙眼肉十枚。", "白话": "〔方名〕补母寿子方（补母体以保胎儿）。〔组成·照录〕人参二钱（虚弱甚者加倍）、白术、当归、熟地各二钱、川芎八分、炙草四分、条芩钱半、苏叶三分、陈皮三分、大枣三枚。〔方义〕八珍汤去芍药加条芩、苏叶、陈皮，益气养血、安胎理气。〔服法〕煎服。〔加减〕内热加黄连五分；肥人去陈皮白加黄连五分；脾胃弱常泄泻加莲子十粒、带壳砂仁三分，减地黄；多怒而泻加木香三分；口燥加麦冬一钱；怔忡、惊悸加枣仁、益智仁各一钱、龙眼肉十枚。"}, {"source": "条155｜《绛雪丹书·产后》·滋荣益气止崩汤", "原文": "《绛雪丹书·产后》：滋荣益气止崩汤。  \n川芎一钱 当归四钱 人参二钱 白术二钱 黄芪一钱 熟地二钱 陈皮四分 升麻四分 白芷四分 荆芥穗四分 炙草四分 黄连三分或四分  \n枣水煎，童便服。汗多加麻黄根一钱，浮小麦一撮；大便不通加肉苁蓉一钱，断不可用大黄；有气不舒加木香末二分；有痰加竹沥、姜汁、贝母；寒嗽加杏仁、桔梗各八分，知母一钱；惊悸加柏子仁一钱，枣仁一钱炒黑；伤食加山楂八分，砂仁五分，断不可", "白话": "〔方名〕滋荣益气止崩汤。〔组成·照录〕川芎一钱、当归四钱、人参二钱、白术二钱、黄芪一钱、熟地二钱、陈皮四分、升麻四分、白芷四分、荆芥穗四分、炙草四分、黄连三分或四分。〔方义〕参、芪、术、草益气，归、芎、地滋荣养血，升麻、荆芥、白芷升举止崩，为益气摄血止崩之剂。〔服法〕大枣煎汤，兑童便服。〔加减·禁忌〕汗多加麻黄根一钱、浮小麦一撮；大便不通加肉苁蓉一钱，断不可用大黄；气不舒加木香末二分；有痰加竹沥、姜汁、贝母；寒嗽加杏仁、桔梗各八分、知母一钱；惊悸加柏子仁一钱、枣仁一钱（炒黑）"}, {"source": "条156｜《青囊秘诀》下卷·转败汤", "原文": "《青囊秘诀》下卷：人有久生瘰疬，两项之间，尽已溃烂，串至胸膈之上，无非痰块，亦已头破而腐者，遂至身体发热发寒，肌肉消瘦，饮食少思，自汗盗汗，惊悸恍惚。此等之症，原系难治，然治得法，尚可救也。大约瘰疬初起，以解郁消痰为主，而佐之补虚以消其毒。病久宜以补虚为君，而佐之以解郁消痰。若徒以祛痰败毒为事，而不补气血之虚，鲜有不死矣！方用转败汤。  \n人参一两 当归一两 土炒白术一两 金银花三两 白芍三两 柴", "白话": "〔医论·主治〕有人久患瘰疬，颈项两侧都已溃烂，延串至胸膈之上，无非痰块，也有的头部破溃腐烂，于是全身发热发冷，肌肉消瘦，饮食少思，自汗盗汗，惊悸恍惚。此等证原本难治，但治法得当尚可救。大约瘰疬初起，以解郁消痰为主，佐以补虚以消其毒；病久则宜以补虚为君，佐以解郁消痰。若只管祛痰败毒而不补气血之虚，少有不死的！方用转败汤。〔组成·照录〕人参一两、当归一两、土炒白术一两、金银花三两、白芍三两、柴胡二钱、制半夏五钱、甘草三钱。〔方义〕参、归、术、芍补益气血，银花解毒，柴胡解郁，半夏化"}, {"source": "条157｜《医宗说约》卷五·滋阴溃坚汤", "原文": "《医宗说约》卷五：滋阴溃坚汤。治忧抑所伤，遂生瘰疬，气血不足，形体瘦弱，潮热咳嗽，坚硬肿痛，不分新久，未溃者并效。  \n川芎、当归、白芍、熟地、陈皮、白苓、桔梗、白术、香附各一钱 甘草、海粉、贝母、人参、昆布各五分 升麻、红花各三分  \n姜三片，枣二枚，水煎，食远服。身热加柴胡、黄芩；自汗盗汗去升麻，倍参芪；饮食无味，加藿香、砂仁；食而不化，加山楂、麦芽；胸膈痞闷，加泽泻、木香；咳嗽痰气不清，加杏", "白话": "〔主治〕治忧郁所伤，遂生瘰疬，气血不足，形体瘦弱，潮热咳嗽，坚硬肿痛；不论新久，凡未溃者都有效。〔组成·照录〕川芎、当归、白芍、熟地、陈皮、白苓、桔梗、白术、香附各一钱，甘草、海粉、贝母、人参、昆布各五分，升麻、红花各三分。〔方义〕与《外科正宗》滋荣散坚汤同方，益气养血、软坚化痰。〔服法〕加生姜三片、大枣二枚，水煎，食远服。〔加减〕身热加柴胡、黄芩；自汗盗汗去升麻、倍人参加黄芪；饮食无味加藿香、砂仁；食而不化加山楂、麦芽；胸膈痞闷加泽泻、木香；咳嗽痰气不清加杏仁、麦冬；口干作"}, {"source": "条158｜《伤寒绪论》卷下·归脾汤", "原文": "《伤寒绪论》卷下：表邪失汗伤阴，身大热，善忘时惊悸，干呕，错语呻吟，不得眠，犀角地黄汤。伤寒坏病久不愈，常不得眠，或心脾气血素亏，而惊悸不宁，不得眠，诸药不效者，大剂独参汤或归脾汤，用送下养正丹。", "白话": "〔医论〕表邪当汗未汗而伤阴，身大热、善忘、时惊悸、干呕、言语错乱呻吟、不得眠者，用犀角地黄汤；伤寒坏病久不愈、经常不得眠，或心脾气血素亏而惊悸不宁、不得眠，诸药无效者，用大剂独参汤或归脾汤，送服养正丹。〔方义〕归脾汤益气补血、健脾养心，独参汤大补元气，养正丹温阳镇摄。〔组成·服法〕原稿未载（归脾汤组成见条103）。"}, {"source": "条159｜《女科经纶》卷七·伏龙肝散", "原文": "《女科经纶》卷七：武叔卿曰：伏龙肝散，治劳伤冲任脉虚，非时崩下，或如豆汁，或成血片，或五色相杂，或赤白相兼，脐腹冷痛，经久未止，令人黄瘦，口干，饮食减少，四肢无力，虚烦惊悸。", "白话": "〔医论〕武叔卿说：伏龙肝散治劳伤冲任、脉虚，非时崩下，或下如豆汁，或成血片，或五色相杂，或赤白相兼，脐腹冷痛，经久不止，使人面黄消瘦、口干、饮食减少、四肢无力、虚烦惊悸。〔组成·照录〕原稿未载（伏龙肝散组成详见原书）。〔方义〕伏龙肝散温中固涩、止血止带。"}, {"source": "条160｜《履霜集》卷二·十全大补汤", "原文": "《履霜集》卷二：夫产后气血内虚，外为风寒湿乘虚而入皮肤经络，则毛孔闭塞，阳气郁结，九窍不利，以致头疼身疼，发热恶寒。若伤于风，重感于寒，则四肢筋脉拘挛，无汗而恶寒。若伤于风，重感于湿则四肢筋脉软弱，有汗而发热。若风入于脏，则心神不宁，恍惚惊悸，随所伤而为病。开目为阳风，闭目为阴风。产后得此，乃气血极虚之危症也，急以十全大补汤，大补气血，稍佐以祛风之剂。无汗恶寒，加荆芥穗、防风各一钱。有汗发热，加荆", "白话": "〔医论〕产后气血内虚，外为风寒湿邪乘虚而入皮肤经络，则毛孔闭塞、阳气郁结、九窍不利，以致头痛身痛、发热恶寒。若伤于风又重感于寒，则四肢筋脉拘挛、无汗而恶寒；若伤于风又重感于湿，则四肢筋脉软弱、有汗而发热；若风入于脏，则心神不宁、恍惚惊悸，随所伤而为病。睁眼为阳风，闭目为阴风。产后得此，是气血极虚之危证，急用十全大补汤大补气血，稍佐祛风之剂。〔组成·照录〕原稿未载（十全大补汤：四君子汤合四物汤加黄芪、肉桂）。〔方义〕十全大补气血双补，佐祛风药以治产后中风。〔加减·禁忌〕无汗恶寒"}, {"source": "条161｜《辨证奇闻》卷四·制忡汤", "原文": "《辨证奇闻》卷四：怔忡，遇拂情，听逆言，便觉心气怦怦，不能自主，似烦非烦，似晕非晕，人谓心虚。然心虚由肝虚，肝虚肺必旺，以心弱不能制肺也。肺无火炼，必制木太过，肝更不能生心，心气益困。故补心必补肝，补肝尤宜制肺。然肺娇脏，寒凉制肺，必伤脾胃，脾胃受寒，不能运化水谷，肝何所资？肾又何益？所以肺不宜制而宜养，况肺愈养愈安，愈制愈动，用制忡汤。  \n人参、白术、麦冬五钱 白芍、当归、枣仁一两 北味一钱 ", "白话": "〔医论〕怔忡之证，遇不顺心之事、听逆耳之言，便觉心气怦怦跳动，不能自主，似烦非烦，似晕非晕，人说是心虚。然而心虚由肝虚而来，肝虚则肺气必旺（金克木），因为心弱不能制约肺。肺无火来炼制，必过度制约肝木，肝更不能生心，心气越发困顿。所以补心必补肝，补肝尤宜制肺。但肺为娇脏，用寒凉制肺必伤脾胃；脾胃受寒不能运化水谷，肝靠什么资生？肾又何益？所以肺不宜制而宜养，况且肺愈养愈安、愈制愈动——用制忡汤。〔组成·照录〕人参、白术、麦冬五钱，白芍、当归、枣仁一两，北味一钱，贝母五分，竹沥十匙"}, {"source": "条162｜《辨证奇闻》卷八·滋肝饮", "原文": "《辨证奇闻》卷八：血虚，面无色泽，肌肉焦枯，大肠干燥，怔忡健忘，饮食少思，羸弱不堪，夜热无汗，人谓血痨，谁知肝燥生火乎。肝属木，木中火盛每自焚。然肝生火，由于肾水不足，木无水润，则木亦为火。非失血吐于外，即耗血燥于内，肝燥肝火生。夫木中有水，则肝生心，木中有火，肝焚心。故火在心中，可取给于肝，火在肝中，不可取给于心者，以肝自顾不暇耳。宜先补肾水。用滋肝饮：  \n玄参、白芍一两 丹皮、沙参、当归、麦", "白话": "〔医论〕血虚之人，面无色泽，肌肉焦枯，大肠干燥，怔忡健忘，饮食少思，瘦弱不堪，夜间发热而无汗——人说是血痨，谁知是肝燥生火？肝属木，木中火盛每每自焚。然而肝生火是由于肾水不足，木无水润，木也就成了火；不是失血吐于外，就是耗血燥于内，肝燥而肝火生。木中有水，则肝生心；木中有火，则肝焚心。所以火在心中，可以取给于肝；火在肝中，不能取给于心——因为肝已自顾不暇。宜先补肾水，用滋肝饮。〔组成·照录〕玄参、白芍一两，丹皮、沙参、当归、麦冬五钱，甘菊、茯苓三钱。〔方义〕玄参、麦冬、沙参滋"}, {"source": "条163｜《辨证奇闻》卷九·坎离两补汤", "原文": "《辨证奇闻》卷九：怔忡善忘，口淡舌燥，多汗，四肢疲软，发热，小便白浊，脉虚大而数，人谓内伤，谁知思虑过度乎。君火，心火也；相火，膻中火也。膻中，手厥阴经，性属阴，主热，古以厥阳名，以其火不可遏也。越人云忧愁思虑则伤心。心气伤，心血自耗，每欲寄权于心包，心包欺心弱，即夺权自恣。法宜以水济火。然火势炽，用寒凉心气益虚，激动焦焚之害。不如补心气，大滋肾水，则心火宁，心包火自安。用坎离两补汤：  \n人参、", "白话": "〔医论〕怔忡善忘，口淡舌燥，多汗，四肢疲软，发热，小便白浊，脉虚大而数——人说是内伤，谁知是思虑过度？君火即心火，相火即膻中（心包）之火；膻中属手厥阴经，性属阴而主热，古称“厥阳”，因其火不可遏。越人（扁鹊）说：忧愁思虑则伤心。心气伤则心血自耗，每每想把权寄于心包；心包欺心弱，便夺权放纵。治法宜以水济火；但火势炽盛时用寒凉，心气更虚，反有焦焚之害。不如补心气、大滋肾水，则心火自宁、心包之火自安——用坎离两补汤。〔组成·照录〕人参、生地、麦冬、山药五钱，熟地一两，菟丝子、炒枣仁"}, {"source": "条164｜《冯氏锦囊秘录·杂症大小合参》·益营汤", "原文": "《冯氏锦囊秘录·杂症大小合参》：益营汤。治思虑耗伤，心血怔忡恍惚。  \n当归酒浸、黄芪、小草、酸枣仁去壳炒、柏子仁炒、麦冬去心、茯神、白芍、紫石英各一两，炒 木香不见火，五钱 人参五钱 甘草炙，五钱  \n每服四钱，姜枣水煎服。", "白话": "〔主治〕治思虑耗伤、心血不足之怔忡恍惚。〔组成·照录〕当归（酒浸）、黄芪、小草、酸枣仁（去壳，炒）、柏子仁（炒）、麦冬（去心）、茯神、白芍、紫石英（炒）各一两，木香（不见火）五钱，人参五钱，甘草（炙）五钱。〔方义〕即《严氏济生方》益荣汤，益气养血、养心安神（此作“益营”，营血同义）。〔服法〕每服四钱，姜枣水煎服。"}, {"source": "条165｜《济世全书·震集》·补中益气汤", "原文": "《济世全书·震集》：补中益气汤。治中气不足，肢体倦怠，口干发热，或饮食无味，劳倦身热，脉洪大而虚；或头痛，恶寒，自汗，或气高而喘，身热而烦；或脉微细软弱，自汗，体倦少食，或中气虚弱而不能摄血，或饮食劳倦而患疟痢，或疟痢因脾胃虚而不能愈；或元气虚弱，感冒风寒不胜发表，宜用此代之；或入房而后感冒，或感冒而后入房，亦用此汤急加附子；或泻痢腹痛，急用附子理中汤。  \n嫩黄芪蜜水炒，一钱半 楝参一钱 甘草炙", "白话": "〔主治〕治中气不足：肢体倦怠，口干发热，或饮食无味，劳倦身热，脉洪大而虚；或头痛、恶寒、自汗，或气粗而喘、身热而烦；或脉微细软弱、自汗、体倦少食；或中气虚弱而不能摄血；或饮食劳倦而患疟痢，或疟痢因脾胃虚而不能愈；或元气虚弱、感冒风寒不胜发表，宜用此方代之；或入房后感冒，或感冒后入房，也用此汤急加附子；或泻痢腹痛，急用附子理中汤。〔组成·照录〕嫩黄芪（蜜水炒）一钱半、楝参一钱、甘草（炙）一钱、陈皮二钱、白术（去芦，微炒）一钱、当归身（酒洗）二钱、柴胡五分、升麻五分（原稿注：此二"}, {"source": "条166｜《广瘟疫论》卷三·六味地黄汤", "原文": "《广瘟疫论》卷三：屡经汗、下，渴而舌上无苔，胸腹无满痛，心悸而烦，脉虚细，或浮散、或涩，亡阴也，六味合生脉为主。", "白话": "〔主治·论〕温疫屡经汗法、下法之后，口渴而舌上无苔，胸腹无满痛，心悸而烦，脉虚细，或浮散、或涩——此为亡阴，以六味地黄汤合生脉散为主。〔组成·照录〕原稿未载。〔方义〕六味地黄滋肾阴，生脉散益气养阴，为亡阴救逆之法。〔服法〕原稿未载。"}, {"source": "条167｜《广瘟疫论》卷三·生脉散", "原文": "《广瘟疫论》卷三：至若屡经汗、下、清理，二便已清利，胸腹无阻滞，六脉虚散、结、代、微弱而谵语者，阴阳两虚，神无所倚也。虚在上焦，必心悸、神倦，生脉散加枣仁、天王补心丹。", "白话": "〔主治·论〕至于屡经汗、下、清利之后，二便已通利，胸腹无阻滞，而六脉虚散、结、代、微弱并见谵语者——此阴阳两虚、神无所依。虚在上焦的，必心悸、神倦，用生脉散加酸枣仁、天王补心丹。〔组成·照录〕原稿未载（生脉散：人参、麦冬、五味子）。〔方义〕生脉散益气养阴生脉，加枣仁养心，天王补心丹滋阴养血安神。〔服法〕原稿未载。"}, {"source": "条168｜《医家心法·怔忡》·归脾汤", "原文": "《医家心法·怔忡》：怔忡，心血少也。其源起于肾水不足，不能上升，以致心火不能下降。大剂归脾汤，去木香，加麦冬、五味、枸杞、白芍，吞都气丸。如怔忡而实，夹包络一种有余之火，兼痰者，则加生地、黄连、川贝之类清之。", "白话": "〔医论〕怔忡，是心血少。其根源起于肾水不足，不能上升，以致心火不能下降。用大剂归脾汤，去木香，加麦冬、五味、枸杞、白芍，送服都气丸。如怔忡而属实、夹心包络一种有余之火而兼痰者，则加生地、黄连、川贝之类清之。〔方义〕归脾汤养心脾，加味滋肾水、济心火，都气丸滋肾纳气。〔服法〕原稿未载（归脾汤组成见条103）。"}, {"source": "条169｜《灵验良方汇编》卷上·安胎饮", "原文": "《灵验良方汇编》卷上：安胎饮。治孕妇胎气不安，或腹痛、腰痛，或饮食不羡等症。又治孕妇屡产，生子无气，或生而不寿，或妊而数堕者，俱照前症，按月服之。  \n人参二钱 当归、白术、熟地同 川芎八分 甘草四分 紫苏、陈皮同 条芩一钱  \n加枣煎。如泄泻，减熟地加莲肉十粒、壳砂数分。如渴，加麦冬一钱。如惊悸，加枣仁、益智仁各一钱。如怒气，磨木香三分。", "白话": "〔主治〕治孕妇胎气不安，或腹痛、腰痛，或饮食不香等症；又治孕妇屡次生产、生子无气，或生而不寿，或屡孕屡堕者，都照前证按月服之。〔组成·照录〕人参二钱，当归、白术、熟地（同量），川芎八分，甘草四分，紫苏、陈皮（同量），条芩一钱。〔方义〕八珍汤去芍药加条芩、紫苏、陈皮，益气养血、安胎理气。〔服法〕加大枣煎。〔加减〕泄泻减熟地加莲肉十粒、带壳砂仁数分；口渴加麦冬一钱；惊悸加枣仁、益智仁各一钱；怒气磨木香三分。"}, {"source": "条170｜《灵验良方汇编》卷上·济坤大造丸", "原文": "《灵验良方汇编》卷上：济坤大造丸。益气血，温子宫，种子神方也男亦可服  \n紫河车儿胞也，取诸壮妇无病者，水洗血尽，用砂罐盛酒一碗，先格篾数片，置胞不着酒，蒸熟 当归二两 人参、山药、杜仲、天冬、麦冬各一两 熟地二两 黄柏八钱，酒炒  \n或加五味子五钱。行经腹痛，加牛膝一两酒浸，炒、玄明五钱。脾弱，加白术一两，或再加莲肉二两二味兼治泻。潮热或汗，加黄芪、知母各一两、地骨皮八钱。血少惊悸，加枣仁一两炒", "白话": "〔功能·主治〕益气血、温子宫，是种子神方（男子也可服）。〔组成·照录〕紫河车（即儿胞、胎盘：取健壮无病产妇者，水洗去净血，用砂罐盛酒一碗，先放竹篾数片，置胎盘不着酒，蒸熟）；当归二两，人参、山药、杜仲、天冬、麦冬各一两，熟地二两，黄柏八钱（酒炒）。〔方义〕紫河车血肉有情、大补气血，归、地养血，参、药益气，二冬、黄柏滋阴清热，杜仲补肾，为益气血、温子宫之剂。〔加减〕或加五味子五钱；行经腹痛加牛膝一两（酒浸，炒）、玄明五钱；脾弱加白术一两，或再加莲肉二两（二味兼治泄泻）；潮热或汗"}, {"source": "条171｜《胎产心法》卷下·人参丸", "原文": "《胎产心法》卷下：人参丸。治产后大虚心悸，志意不安，恍惚恐畏，虚烦不眠少气。  \n人参、茯苓、麦冬去心、薯蓣各二两 泽泻、菖蒲、干姜、桂心、甘草各一两  \n共为末，白蜜和枣膏丸如梧子大。空心酒服二三十丸，早晚服。", "白话": "〔主治〕治产后大虚心悸，意志不安，恍惚恐惧，虚烦不眠少气。〔组成·照录〕人参、茯苓、麦冬（去心）、薯蓣各二两，泽泻、菖蒲、干姜、桂心、甘草各一两。〔方义〕即《千金要方》人参丸加减，益气养心、安神定志、温中健脾。〔制法·服法〕共为末，白蜜和枣膏为丸如梧桐子大，空腹酒服二三十丸，早晚服。"}, {"source": "条172｜《不居集·上集》·资成汤", "原文": "《不居集·上集》：资成汤。治虚劳遗精盗汗，食少泄泻，血不归经，女子崩漏不止，虚劳不任芪、木、归、地者，此方主之。  \n人参、白芍、扁豆、山药、茯神各一钱 丹参八分 橘红六分 甘草五分 莲肉一钱五分 檀香三分  \n用雄健无病猪肚一具，酒洗磨净，取清汤煎药，或为丸亦可。虚热者，加丹皮、地骨皮。惊恐怔忡，不眠多汗者，加枣仁。火铄肺金，干枯多嗽者，加百合。便血失血者，加地榆、续断。小水不利者，加车前子。痰", "白话": "〔主治〕治虚劳遗精盗汗，食少泄泻，血不归经，女子崩漏不止；凡虚劳而不任黄芪、白术、当归、熟地之补者，此方主治。〔组成·照录〕人参、白芍、扁豆、山药、茯神各一钱，丹参八分，橘红六分，甘草五分，莲肉一钱五分，檀香三分。〔方义〕参、药、扁豆、莲肉健脾益气，芍、丹参养血和血，茯神安神，橘红、檀香理气，为清补平和之剂。〔制法·服法〕用健壮无病猪肚一具，酒洗磨净，取清汤煎药；或为丸亦可。〔加减〕虚热加丹皮、地骨皮；惊恐怔忡、不眠多汗加枣仁；火烁肺金、干咳多嗽加百合；便血失血加地榆、续断；"}, {"source": "条173｜《不居集·上集》·寿脾煎", "原文": "《不居集·上集》：若儒生蹇厄，思结枯肠，及任劳任怨，心脾受伤，以致怔忡健忘，倦怠少食，渐至消瘦，或为膈噎呕吐者，宜寿脾煎，七福饮。", "白话": "〔医论〕若读书人遭遇困厄、思虑结于枯肠，以及任劳任怨，心脾受伤，以致怔忡健忘、倦怠少食、渐渐消瘦，或成膈噎呕吐者，宜用寿脾煎、七福饮。〔组成·照录〕原稿未载。〔方义〕寿脾煎温补心脾，七福饮气血双补，均为景岳新方。〔服法〕原稿未载。"}, {"source": "条174｜《不居集·上集》·温脾汤（附：大菟丝子丸，原稿仅存方名）", "原文": "《不居集·上集》：若忧郁伤脾，而吞酸呕恶者，宜温胃饮、神香散。若忧郁伤脾肺，而困倦怔忡，倦怠食少者，宜温脾汤、寿脾煎。  \n大菟丝子丸。", "白话": "〔医论〕若忧郁伤脾而吞酸呕恶者，宜用温胃饮、神香散；若忧郁伤脾肺而困倦怔忡、倦怠少食者，宜用温脾汤、寿脾煎。〔组成·照录〕原稿未载（温脾汤、寿脾煎组成详见原书）。〔方义〕温脾汤温补脾阳、开郁进食，为忧郁伤脾肺者设。〔附〕原稿此条末另起“大菟丝子丸。”仅存方名，其组成主治当在下文（见方剂第二块），照录不改。"}, {"source": "条175｜《不居集·上集》·大菟丝子丸", "原文": "《不居集·上集》：肾气虚损，真阴中阳气不足，不能固摄，小便频多，水不济火，心忡气短，故多盗汗。大菟丝子丸。  \n《不居集·上集》：大菟丝子丸。治肾气虚损，五劳七伤，脚膝酸疼，面色痿黄黧黑，目眩耳鸣，心忡气短，时有盗汗，小便滑数等症。  \n菟丝子酒制、鹿茸酥炙、肉桂、石龙肉去土、附子炮、泽泻各一两 熟地、牛膝酒浸一宿，焙干、山萸肉、杜仲、茯苓、肉苁蓉酒浸，切焙、续断、石斛、防风、补骨脂酒炒、川芎、五", "白话": "前段：肾气虚损，真阴之中阳气不足，不能固摄，小便频多，水不济火，心忡气短，所以多盗汗——用大菟丝子丸。后段：大菟丝子丸。治肾气虚损、五劳七伤，脚膝酸疼，面色萎黄或黧黑，目眩耳鸣，心忡气短，时有盗汗，小便滑数等症。组成（照录）：菟丝子酒制、鹿茸酥炙、肉桂、石龙肉去土、附子炮、泽泻各一两；熟地、牛膝酒浸一宿焙干、山萸肉、杜仲、茯苓、肉苁蓉酒浸切焙、续断、石斛、防风、补骨脂酒炒、川芎、五味子、桑螵蛸、覆盆子各五钱。制法服法（照录）：上为末，酒煮面糊丸，如桐子大。每服三五十丸，空心，"}, {"source": "条176｜《不居集·上集》·十四友丸", "原文": "《不居集·上集》：十四友丸。治惊悸怔忡。  \n人参、黄芪、当归、生地、远志、茯神、枣仁炒、茯苓、阿胶、龙脑、紫石英、薄荷、朱砂各一两  \n上为末，炼蜜丸桐子大，每服五七十丸。", "白话": "十四友丸。治惊悸怔忡。组成（照录）：人参、黄芪、当归、生地、远志、茯神、枣仁炒、茯苓、阿胶、龙脑、紫石英、薄荷、朱砂各一两。制法服法（照录）：上为末，炼蜜丸桐子大，每服五七十丸。方义：益气养血、养心安神，佐金石重镇与龙脑开窍，治心虚之惊悸怔忡。"}, {"source": "条177｜《不居集·上集》·资成汤", "原文": "《不居集·上集》：劳伤心脾，思虑太过，则惊悸怔忡，气虚精陷，而不成寐者，宜资成汤。", "白话": "劳伤心脾，思虑太过，则见惊悸怔忡，气虚精气下陷，而不能成寐的，宜用资成汤。方义：益气健脾、养心安神，为劳伤心脾、心神失养而设。"}, {"source": "条178｜《不居集·上集》·养心汤", "原文": "《不居集·上集》：澄按：虚损多由失血太多，或自汗、盗汗、遗精之后，多有怔忡惊悸，健忘恍惚不寐之症，皆因心气不足，心神不安，殊非气郁痰涎为患。速宜养其气血，救其根本，此脱运之机也，宜养心汤、酸枣仁汤、加减茯苓补心汤。", "白话": "吴澄按语：虚损多由失血太多，或在自汗、盗汗、遗精之后，多有怔忡惊悸、健忘恍惚、不寐之症，皆因心气不足、心神不安，绝非气郁痰涎为患。速宜调养其气血、救护其根本，这是病势转脱的关键时刻，宜用养心汤、酸枣仁汤、加减茯苓补心汤。"}, {"source": "条179｜《不居集·下集》·河车如圣丹", "原文": "《不居集·下集》：河车如圣丹。  \n紫河车一具，酒洗净 青蒿一斗五升，入童便熬  \n熬童便减至二斗，去青蒿，再熬至一斗，再入紫河车煮烂，莲粉收为丸，如梧桐子大，每服五十丸。  \n按：杏仁翁云：凡虚损中诸症，务要得紫河车，取效甚速。入血药中则补血，入气药中则补气，入去热药中则退药。又治癫痫健忘，怔忡失志之症，及恍惚惊怖，神不守舍，多言不定，此药大能安心养血定神。又治骨蒸传尸，数种虚劳邪热，滋阴补阳，", "白话": "河车如圣丹。组成（照录）：紫河车一具，酒洗净；青蒿一斗五升，入童便熬。制法服法（照录）：熬童便减至二斗，去青蒿，再熬至一斗，再入紫河车煮烂，莲粉收为丸，如梧桐子大，每服五十丸。按语：杏仁翁说：凡虚损中诸症，务必得紫河车，取效甚速。入血药中则补血，入气药中则补气，入去热药中则退药。又治癫痫健忘、怔忡失志之症，以及恍惚惊怖、神不守舍、多言不定，此药大能安心养血定神。又治骨蒸传尸、数种虚劳邪热，滋阴补阳，是养寿的圣药。我用此屡验。方义：血肉有情之品合青蒿童便退蒸，攻补兼施。"}, {"source": "条180｜《目经大成》·人参养荣汤", "原文": "《目经大成》卷三：人参养荣汤。  \n人参 白术 茯苓 甘草 黄芪剂片蜜拌炒 橘皮 肉桂 当归 芍药 地黄 远志缓火炆去梗 五味子  \n脉极肉瞤，惊悸健忘，寝汗发热，食少气短，肌瘦目枯，毛发堕落，此方主之。经曰：脾气散精，上输于肺。此地气上升也。肺主治节，通调水道，下输膀胱，此天气下降也。肺脾虚，则上下不交，荣血无所藉以生。是故肺虚则气短，毛发堕落。脾虚则食少，肌瘦目枯。脾肺两虚，自无血以养心，则百", "白话": "人参养荣汤。组成（照录）：人参、白术、茯苓、甘草、黄芪（剂片蜜拌炒）、橘皮、肉桂、当归、芍药、地黄、远志（缓火炆去梗）、五味子。主治：脉极而肌肉瞤动，惊悸健忘，寝汗发热，食少气短，肌瘦目枯，毛发脱落，此方主之。经曰：脾气散精，上输于肺——这是地气上升；肺主治节，通调水道，下输膀胱——这是天气下降。肺脾虚，则上下不相交泰，营血无所赖以化生。所以肺虚则气短、毛发脱落，脾虚则食少、肌瘦目枯；脾肺两虚，则自然无血以养心，于是百脉疲惫之极，寝汗发热，惊悸健忘，筋肉不时振惕。上方黄芪、白"}, {"source": "条181｜《临症验舌法》·归脾汤", "原文": "《临症验舌法》下卷：归脾汤去木香加丹皮山栀方。  \n枣仁一钱，炒研 茯神一钱，去木 远志一钱，去心 归身一钱 人参一钱半 炙芪三钱，无参倍之 白术二钱半，米泔净蒸 尤圆七枚，去壳 甘草一钱，炙 白芍二钱 丹皮钱半 山栀钱半，炒黑 煨姜一钱 大枣三枚  \n按：上方主治思虑伤心脾，郁怒伤肝，以致三经血少而燥。渐至心口有块如拳，或左肋下有块如手掌，或右肋下有块如镰刀，且时作痛，及健忘怔忡、惊悸不寐等症。", "白话": "归脾汤去木香加丹皮山栀方。组成（照录）：枣仁一钱，炒研；茯神一钱，去木；远志一钱，去心；归身一钱；人参一钱半；炙芪三钱，无参倍之；白术二钱半，米泔净蒸；尤圆七枚，去壳；甘草一钱，炙；白芍二钱；丹皮钱半；山栀钱半，炒黑；煨姜一钱；大枣三枚。按语：上方主治思虑伤心脾、郁怒伤肝，以致三经血少而燥。渐至心口有块如拳，或左肋下有块如手掌，或右肋下有块如镰刀，且时作痛，以及健忘怔忡、惊悸不寐等症。即《内经》所谓“二阳之病发心脾”：在男子则隐曲不利，在女子则月事不来，其传为风消、其传为息贲"}, {"source": "条182｜《临症验舌法》·附子养荣汤", "原文": "《临症验舌法》下卷：附子养荣汤方。  \n附子钱半 远志一钱 白芍三钱，酒炒 归身二钱 五味钱半 熟地六钱 肉桂五分 茯苓钱半 人参钱半或二三钱 炙芪五钱，无参倍用 白术三钱 陈皮钱半 炙草钱半 煨姜二钱 大枣五枚  \n上将熟地枣肉捣烂，其余炒磨为末，加蜜为丸，即予家所制万应一粒丹者是也。凡中风伤寒，痘疹胎产，及血症喉痹等症，势在危急，刻不可缓者，每用一粒，滚汤研化，不时灌服，其势自定。继予两粒三粒", "白话": "附子养荣汤方。组成（照录）：附子钱半，远志一钱，白芍三钱酒炒，归身二钱，五味钱半，熟地六钱，肉桂五分，茯苓钱半，人参钱半或二三钱，炙芪五钱无参倍用，白术三钱，陈皮钱半，炙草钱半，煨姜二钱，大枣五枚。制法服法（照录）：上将熟地、枣肉捣烂，其余炒磨为末，加蜜为丸，即我家所制万应一粒丹。凡中风伤寒、痘疹胎产，及血证喉痹等症，势在危急、刻不可缓的，每次用一粒，滚汤研化，不时灌服，其势自定；继予两粒三粒，其病自退。如调治久病，则作细丸，每服五钱，早晚两时，空心米饮送下。按语：上方主治劳"}, {"source": "条183｜《景岳全书发挥》·寿脾煎", "原文": "《景岳全书发挥》卷二：若思虑劳倦伤心脾，以致气虚精陷，为怔忡、惊悸、不寐者，宜寿脾煎。治法未合病情。", "白话": "若思虑劳倦伤心脾，以致气虚精陷，成为怔忡、惊悸、不寐的，宜用寿脾煎。——（原书评曰）治法未合病情。"}, {"source": "条184｜《疡医大全》·转败丹", "原文": "《疡医大全》卷十八：又曰：有久生瘰疬，颈间尽烂，且及于胸膈，无非痰块，以至身体发热发寒，肌肉消瘦，不思饮食，自汗盗汗，惊悸恍惚。此证原难医治，然治得法，亦在可救也。夫此证初起，宜解郁为先，佐之补虚，以消其毒；倘执寻常治法，以祛痰败毒为事，鲜不速之亡矣。用转败丹：  \n人参二两 柴胡二钱 白芍三钱 金银花三两 当归二两 半夏五钱 白术一两 生甘草三钱  \n水煎服，四剂，痰块在胸者尽消，又四剂，颈上溃", "白话": "又说：有久生瘰疬的，颈间尽烂，且及于胸膈，无非痰块，以致身体发热发寒，肌肉消瘦，不思饮食，自汗盗汗，惊悸恍惚。此证原本难医，然治得法，也还可救。此证初起，宜以解郁为先，佐以补虚，以消其毒；倘若执寻常治法，专以祛痰败毒为事，很少有不加速死亡的。用转败丹：（组成照录）人参二两、柴胡二钱、白芍三钱、金银花三两、当归二两、半夏五钱、白术一两、生甘草三钱。水煎服：四剂，胸中痰块尽消；又四剂，颈上溃烂亦愈；将方减半，再服十剂，疮口渐平，不再发。此方补多于消，而开郁寓于其中、化痰存于内；从"}, {"source": "条185｜《疡医大全》·加味养荣丸", "原文": "《疡医大全》卷二十六：加味养荣丸。治妇女脚气，心虚血少，怔忡心悸，肝脾不足，调经养血，非此不效。  \n当归身酒洗焙，三两 白茯神人乳蒸，二两 肥玉竹焙，二两 杭白芍酒炒，二两 酸枣仁炒熟，二两 丹参酒炒，二两 远志肉甘草汤焙，二两 柏子仁二两 川续断酒炒，二两 橘红饭上蒸，一两 杜仲盐水炒，二两 秦艽酒炒，一两五钱 女贞实蜜拌蒸，二两 钩藤钩四两，同石斛熬 郁金二两  \n上制毕，磨细末。用金钗石斛", "白话": "加味养荣丸。治妇女脚气、心虚血少、怔忡心悸、肝脾不足，调经养血，非此不效。组成（照录）：当归身酒洗焙三两，白茯神人乳蒸二两，肥玉竹焙二两，杭白芍酒炒二两，酸枣仁炒熟二两，丹参酒炒二两，远志肉甘草汤焙二两，柏子仁二两，川续断酒炒二两，橘红饭上蒸一两，杜仲盐水炒二两，秦艽酒炒一两五钱，女贞实蜜拌蒸二两，钩藤钩四两（同石斛熬），郁金二两。制法服法（照录）：上制毕，磨细末。用金钗石斛一斤，同钩藤钩四两熬膏，和丸如豌豆大。每早白汤送下三钱。方义：养血安神、调补肝脾，兼以调经。"}, {"source": "条186｜《成方切用》·小营煎", "原文": "《成方切用》卷二：小营煎景岳。治血少阴虚，此性味和平之方也。  \n当归二钱 熟地三四钱 芍药酒炒 山药 枸杞二钱 炙草一钱  \n如营虚于上，而为惊恐怔忡不眠多汗者，加枣仁茯神各二钱。如营虚兼寒者，去芍药，加煨姜。如气滞有痛者，加香附一二钱，引而行之。", "白话": "小营煎，景岳方。治血少阴虚，这是性味平和的方子。组成（照录）：当归二钱、熟地三四钱、芍药（酒炒）、山药、枸杞二钱、炙草一钱。加减：如营虚于上，而见惊恐怔忡、不眠多汗的，加枣仁、茯神各二钱；如营虚兼寒的，去芍药，加煨姜；如气滞有痛的，加香附一二钱，引而行之。"}, {"source": "条187｜《金匮翼》·远志引子", "原文": "《金匮翼》卷三：远志引子。治心劳虚寒，梦寐惊悸。  \n远志去心、茯神去木、肉桂、人参、枣仁炒、黄芪、当归各一两 甘草炙，半两  \n上㕮咀，每服四钱，水一盏，姜五片，煎服无时。", "白话": "远志引子。治心劳虚寒，梦寐惊悸。组成（照录）：远志去心、茯神去木、肉桂、人参、枣仁炒、黄芪、当归各一两；甘草炙，半两。制法服法（照录）：上㕮咀，每服四钱，水一盏，姜五片，煎服无时。方义：温养心气、益气养血、安神定志。"}, {"source": "条188｜《杂病源流犀烛》·人参养荣汤", "原文": "《杂病源流犀烛》卷十六：又有虚黄，口淡，怔忡，寒热，溲白，耳鸣，脚软，怠惰无力，凡郁不得志人，多生此症宜人参养荣汤，又有风黄，身不黄，独目黄，其人肥，风不外泄故也宜青龙散。", "白话": "又有虚黄：口淡，怔忡，寒热，小便色白，耳鸣，脚软，怠惰无力——凡郁郁不得志之人，多生此症——宜用人参养荣汤；又有风黄：身不发黄，独见目黄，其人肥胖，是风邪不得外泄的缘故——宜用青龙散。"}, {"source": "条189｜《妇科玉尺》·通用古芩术汤", "原文": "《妇科玉尺》卷二：胎动，通用古芩术汤加阿胶，风邪加姜豉，寒加葱白，热加花粉，寒热加柴胡，项强加葱白，温热腹痛加白芍，腹胀加厚朴，下血加艾、地榆，腰痛加杜仲，惊悸加黄连，烦渴加麦冬、乌梅，思虑太过加茯神，痰呕加旋覆花、贝母，或酌用半夏曲，劳役加黄芪，气喘去术加香附，便燥加麻仁，素惯难产加枳壳、苏叶，素惯堕胎加杜仲，素血虚加芎、归，此安胎之圣药也。", "白话": "胎动，通用古芩术汤加阿胶；兼风邪加生姜、豆豉，兼寒加葱白，兼热加花粉，寒热往来加柴胡，项强加葱白，温热腹痛加白芍，腹胀加厚朴，下血加艾叶、地榆，腰痛加杜仲，惊悸加黄连，烦渴加麦冬、乌梅，思虑太过加茯神，痰呕加旋覆花、贝母，或酌用半夏曲，劳役加黄芪，气喘去白术加香附，大便燥结加麻仁，素惯难产加枳壳、苏叶，素惯堕胎加杜仲，素体血虚加川芎、当归——这是安胎的圣药。"}, {"source": "条190｜《慈幼新书》·木香散", "原文": "《慈幼新书》卷六：木香散。治纯阴无阳，泄泻而渴。  \n木香 人参 肉桂 半夏 青皮 前胡 丁香 大腹皮 赤茯苓 炙甘草 诃子煨去枝 生姜 糯米  \n虚甚，加黄芪。陈氏云：腹胀渴者，泻渴者，足指冷渴者，惊悸渴者，身温渴者，身热面㿠白渴者，寒颤渴不止者，气急咬牙渴者，饮水转水泻不已渴者，九症皆非热也，乃津液少，致脾胃肌肉虚故耳。此方治之。然必痘色白，手足凉，小便清利方效。若痘色红，大便秘，小便赤，即非", "白话": "木香散。治纯阴无阳，泄泻而渴。组成（照录）：木香、人参、肉桂、半夏、青皮、前胡、丁香、大腹皮、赤茯苓、炙甘草、诃子（煨去枝）、生姜、糯米。加减：虚甚，加黄芪。陈氏说：腹胀而渴者、泄泻而渴者、足趾冷而渴者、惊悸而渴者、身温而渴者、身热面白而渴者、寒战渴不止者、气急咬牙而渴者、饮水反而水泻不已而渴者——这九症都不是热证，而是津液少，以致脾胃肌肉虚的缘故。此方治之。但必须痘色白、手足凉、小便清利才有效；若痘色红、大便秘、小便赤，就不适宜了。"}, {"source": "条191｜《婴儿论·辨寒热脉证并治第二》·枸杞凉肝汤", "原文": "《婴儿论·辨寒热脉证并治第二》：气血两衰，郁火起伏，胸硬腹弱，少气悸动，兼主眼目不了了者，宜枸杞凉肝汤。  \n枸杞、厚朴、香附子各一钱 茯苓二钱 黄柏、甘草各五分  \n上九味，以水二升，煮取一升，去滓分温服。", "白话": "气血两衰，郁火起伏，胸硬腹弱，少气而悸动，兼见视物不清的，宜用枸杞凉肝汤。组成（照录）：枸杞、厚朴、香附子各一钱，茯苓二钱，黄柏、甘草各五分。煎服法（照录）：上九味，以水二升，煮取一升，去滓分温服。"}, {"source": "条192｜《婴儿论·辨疳病脉证并治第五》·八珍汤", "原文": "《婴儿论·辨疳病脉证并治第五》：病人，气血虚竭，郁热起伏，二脉细数，大便若燥，若溏，胸痞悸动，呴其气，而热愈动，滋其血，而胸益痞，宜八珍汤主之。八珍汤方：  \n人参三分 茯苓二钱 枸杞三钱 缩砂五分 鹿角霜七分 莲蕊三分 生姜一片 甘草三分  \n上八味，以水二升，煮取一升，去滓，分温服。", "白话": "病人，气血虚竭，郁热起伏，两手脉细数，大便或燥或溏，胸痞悸动；疏其气则热更动，滋其血则胸更痞——宜用八珍汤主治。八珍汤方：（组成照录）人参三分、茯苓二钱、枸杞三钱、缩砂五分、鹿角霜七分、莲蕊三分、生姜一片、甘草三分。煎服法（照录）：上八味，以水二升，煮取一升，去滓，分温服。方义：气血双补兼益肾安神，治疳病气血虚竭之悸。"}, {"source": "条193｜《伤寒瘟疫条辨》·人参固本汤", "原文": "《伤寒瘟疫条辨》卷五：人参固本汤。治温病虚极热极，循衣作空，不下必死者。下后神思稍苏，续得肢体振寒，怔忡惊悸，如人将捕之状，四肢厥逆，眩运郁冒，项背强直，此大虚之兆，将危之候也，此方救之。  \n大营煎。治男子真阴精血亏损，及妇人经迟血少，或腰膝筋骨疼痛，或虚寒心腹疼痛者。  \n大营煎。治男子真阴精血亏损，及妇人经迟血少，或腰膝筋骨疼痛，或虚寒心腹疼痛者。  \n熟地三、五、七钱 当归二、三、五钱 枸", "白话": "人参固本汤。治温病虚极热极，循衣作空，不攻下必死的；攻下之后神思稍苏，续得肢体振寒、怔忡惊悸如人将捕之状，四肢厥逆，眩运郁冒，项背强直——这是大虚的征兆、将危之候，用此方救之。其后又录大营煎：治男子真阴精血亏损，及妇人经迟血少，或腰膝筋骨疼痛，或虚寒心腹疼痛者（原稿此句重出一过，照录）。组成（照录）：熟地三、五、七钱，当归二、三、五钱，枸杞二钱，杜仲（盐炒）二钱，牛膝钱半，肉桂一钱，甘草（炙）二钱。服法加减（照录）：水煎温服。如寒滞在经、气血不能流通、筋骨疼痛甚的，必加制附子"}, {"source": "条194｜《竹林女科证治》·石斛散", "原文": "《竹林女科证治》卷三：产后惊悸，闻声欲死，非他人用力抱持，则虚烦欲死，由心肝脾三经虚也。宜石斛散。  \n人参、酸枣仁、茯神、远志肉、白芍、石斛、麦冬去心、炙甘草、五味子各等分  \n为末，每服二三钱，桂圆汤下。", "白话": "产后惊悸，闻声欲死，若非他人用力抱持，则虚烦欲死——这是心肝脾三经虚。宜用石斛散。组成（照录）：人参、酸枣仁、茯神、远志肉、白芍、石斛、麦冬去心、炙甘草、五味子各等分。制法服法（照录）：为末，每服二三钱，桂圆汤下。方义：心肝脾三经并补，养血安神定悸。"}, {"source": "条195｜《罗氏会约医镜》·养血安神汤", "原文": "《罗氏会约医镜》卷十五：养血安神汤。治产后心血不足，以致神魂不安而惊悸也。  \n当归身二钱 熟地三五钱 白芍酒炒，钱半 茯神、枣仁炒、生地、炙草各一钱 远志六分 五味三分 干姜炒黑，三四分 柏子仁微炒去油，七分 白莲五粒，去心，微炒，捶碎  \n水煎，温服。或用天王补心丹亦妙。", "白话": "养血安神汤。治产后心血不足，以致神魂不安而惊悸。组成（照录）：当归身二钱、熟地三五钱、白芍酒炒钱半、茯神、枣仁炒、生地、炙草各一钱、远志六分、五味三分、干姜炒黑三四分、柏子仁微炒去油七分、白莲五粒（去心，微炒，捶碎）。服法（照录）：水煎，温服。或用天王补心丹亦妙。方义：养血安神为主，佐以温中，治产后心血不足之惊悸。"}, {"source": "条196｜《金匮启钥（妇科）》·四物补心汤", "原文": "《金匮启钥（妇科）》卷五：神气不守惊悸作，可投四物补心汤。", "白话": "神气失守而惊悸发作的，可投四物补心汤。方义：养血补心、安神定悸。"}, {"source": "条197｜《金匮启钥（妇科）》·琥珀散", "原文": "《金匮启钥（妇科）》卷五：琥珀散。治血虚多惊悸，产后诸疾。  \n辰砂、琥珀、没药各研细、当归各等分  \n上为细末，每服二钱，空心白汤调下，日三服。", "白话": "琥珀散。治血虚多惊悸，及产后诸疾。组成（照录）：辰砂、琥珀、没药各研细、当归各等分。制法服法（照录）：上为细末，每服二钱，空心白汤调下，日三服。方义：养血活血、镇心安神。"}, {"source": "条198｜《医述》·归脾汤", "原文": "《医述》卷十：朱丹溪怔忡，心血少也。其原起于肾水不足，不能上升，以致心火不能下降。治宜归脾汤，去木香加麦、味、枸杞，吞都气丸。  \n《产孕集》下篇：产后虚劳，名曰蓐劳。其候乍起乍卧，饮食不化，时作嗽咳，目昏头痛，口渴盗汗，寒热往来，喘乏自汗，少气惊悸，此由摄养不善，内伤七情，阳陷阴逆，升降倒置，脏腑交病，表里均亏，误用寒凉，即死不治，宜羊肉汤。  \n羊肉汤 羊肉一斤，去脂 当归、桂心、甘草各六钱 ", "白话": "朱丹溪论怔忡：怔忡是心血少。其原起于肾水不足、不能上升，以致心火不能下降。治宜归脾汤，去木香，加麦冬、五味子、枸杞，吞服都气丸。其后又录《产孕集》：产后虚劳，名叫蓐劳。其候忽起忽卧，饮食不化，时时咳嗽，目昏头痛，口渴盗汗，寒热往来，喘乏自汗，少气惊悸——这是由于摄养不善、内伤七情，阳陷阴逆，升降倒置，脏腑交病，表里均亏；误用寒凉，即死不治——宜用羊肉汤。羊肉汤（组成照录）：羊肉一斤去脂，当归、桂心、甘草各六钱，芎一两，芍药、生姜各一两三钱，干地黄一两六钱。煎服法（照录）：以水"}, {"source": "条199｜《验方新编》·滋味活络汤", "原文": "《验方新编》卷二十：滋味活络汤。  \n当归、人参各三钱 川芎、熟地各二钱 黄芪、茯神、天麻、麦冬各一钱 陈皮、炙甘草各五分 荆芥、防风、羌活各四分  \n火盛产久，加炒连三分。有痰，加夏曲七分。痰多，加竹沥、姜汁。大便闭秘加苁蓉二钱。渴，加葛根八分。汗多，加麻黄根一钱。惊悸，加枣仁二钱。气息如结、手足渐冷，加桂子一钱，附子五分。", "白话": "滋味活络汤。组成（照录）：当归、人参各三钱，川芎、熟地各二钱，黄芪、茯神、天麻、麦冬各一钱，陈皮、炙甘草各五分，荆芥、防风、羌活各四分。加减（照录）：火盛产久，加炒连三分；有痰，加夏曲七分；痰多，加竹沥、姜汁；大便闭秘加苁蓉二钱；渴，加葛根八分；汗多，加麻黄根一钱；惊悸，加枣仁二钱；气息如结、手足渐冷，加桂子一钱，附子五分。方义：益气养血、祛风通络，产后气血两虚兼风邪者宜之。"}, {"source": "条200｜《杂病广要·内因类》·虚乏方", "原文": "《杂病广要·内因类》：虚乏方。（节录）  \n饴糖半斤 黄芪、远志、当归千金翼无、泽泻各三两 芍药、人参、龙骨、甘草各二两 生姜八两 大枣二十枚  \n上十一味，㕮咀，以水一斗，煮取二升半，汤成内糖令烊，一服八合。消息，又一服。（《千金》）《简易》引《究原方》，去饴糖、大枣，治小腹急痛，便溺失精，虚热盗汗，四体倦怠，支节烦疼，口苦舌涩，心怔气短，日渐羸弱。", "白话": "虚乏方（节录）。组成（照录）：饴糖半斤；黄芪、远志、当归（《千金翼》无）、泽泻各三两；芍药、人参、龙骨、甘草各二两；生姜八两；大枣二十枚。制法服法（照录）：上十一味，㕮咀，以水一斗，煮取二升半，汤成内糖令烊，一服八合。消息，又一服。（出自《千金》）《简易》引《究原方》，去饴糖、大枣，治小腹急痛、便溺失精、虚热盗汗、四体倦怠、支节烦疼、口苦舌涩、心怔气短、日渐羸弱。"}, {"source": "条201｜《百代医宗》·怔忡汤", "原文": "《百代医宗》怔忡汤  \n于本方去人参、远志、石菖蒲，加川芎、白芍、熟地黄、生地黄煎服。", "白话": "《百代医宗》怔忡汤：于本方去人参、远志、石菖蒲，加川芎、白芍、熟地黄、生地黄，煎服。方义：去温补开窍之品，转为养血凉血以安神定忡。"}, {"source": "条202｜《麻疹备要方论·收没论治》·枣麦四物汤", "原文": "《麻疹备要方论·收没论治》：如疹没后身虽不见瘦削，但时发壮热，烦躁不安，搐掣惊悸，神昏志乱者，此阴血虚耗，余毒入肝而传于心，宜枣麦四物汤主之。", "白话": "如疹子收没之后身体虽不见瘦削，但时时突发壮热，烦躁不安，搐掣惊悸，神昏志乱的——这是阴血虚耗，余毒入肝而传于心——宜用枣麦四物汤主治。方义：四物养血，枣仁、麦冬养心安神，治阴血虚耗、余热扰心之悸。"}, {"source": "条203｜《经验良方全集》·无名方", "原文": "《经验良方全集》卷一：治心虚惊悸羸瘦者。  \n荆沥二升，水煎至一升六合，分作四服，日三次，夜一次。", "白话": "治心虚惊悸羸瘦的方。组成服法（照录）：荆沥二升，水煎至一升六合，分作四服，日三次，夜一次。方义：荆沥甘寒，清热化痰、止惊定悸，治心虚兼痰热者。"}, {"source": "条204｜《医学答问》·七福饮", "原文": "《医学答问》卷四：七福饮。治心血虚而惊悸者。  \n人参、熟地各三钱 当归、枣仁各二钱 白术炒一钱半 炙甘草五分 远志五分", "白话": "七福饮。治心血虚而惊悸的。组成（照录）：人参、熟地各三钱，当归、枣仁各二钱，白术炒一钱半，炙甘草五分，远志五分。方义：益气养血、健脾安神。"}, {"source": "条205｜《医学衷中参西录·医方》·升陷汤", "原文": "《医学衷中参西录·医方》：升陷汤。治胸中大气下陷，气短不足以息。或努力呼吸，有似乎喘。或气息将停，危在顷刻。其兼证，或寒热往来，或咽干作渴，或满闷怔忡，或神昏健忘，种种病状，诚难悉数。其脉象沉迟微弱，关前尤甚。其剧者，或六脉不全，或参伍不调。  \n生箭芪六钱 知母三钱 柴胡一钱五分 桔梗一钱五分 升麻一钱  \n气分虚极下陷者，酌加人参数钱，或再加山萸肉去净核数钱，以收敛气分之耗散，使升者不至复陷更", "白话": "升陷汤。治胸中大气下陷，气短不足以息；或努力呼吸，有似乎喘；或气息将停，危在顷刻。其兼证：或寒热往来，或咽干作渴，或满闷怔忡，或神昏健忘——种种病状，实在难以尽述。其脉象沉迟微弱，关前尤其明显；病剧的，或六脉不全，或参伍不调。组成（照录）：生箭芪六钱、知母三钱、柴胡一钱五分、桔梗一钱五分、升麻一钱。加减（照录）：气分虚极下陷者，酌加人参数钱，或再加山萸肉去净核数钱，以收敛气分之耗散，使升者不至复陷更佳。若大气下陷过甚，至少腹下坠，或更作疼者，宜将升麻改用钱半，或倍作二钱。其怔"}, {"source": "条206｜《医学衷中参西录·医方》·安魂汤", "原文": "《医学衷中参西录·医方》：安魂汤。治心中气血虚损，兼心下停有痰饮，致惊悸不眠。  \n龙眼肉六钱 酸枣仁四钱，炒捣 生龙骨五钱，捣末 生牡蛎五钱，捣末 清半夏三钱 茯苓片三钱 生赭石四钱，轧细  \n若服一两剂后无效者，可于服汤药之外，临睡时用开水送服西药臭剥一瓦，借其麻痹神经之力，以收一时之效，俾汤剂易于为力也。方书谓：痰饮停于心下，其人多惊悸不寐。盖心，火也，痰饮，水也，火畏水刑，故惊悸至于不寐也", "白话": "安魂汤。治心中气血虚损，兼心下停有痰饮，以致惊悸不眠。组成（照录）：龙眼肉六钱、酸枣仁四钱炒捣、生龙骨五钱捣末、生牡蛎五钱捣末、清半夏三钱、茯苓片三钱、生赭石四钱轧细。服法（照录）：若服一两剂后无效者，可于服汤药之外，临睡时用开水送服西药臭剥一瓦，借其麻痹神经之力，以收一时之效，俾汤剂易于为力也。方书谓：痰饮停于心下，其人多惊悸不寐。盖心，火也，痰饮，水也，火畏水刑，故惊悸至于不寐也。方义：养心安神、化饮降逆、重镇定悸。"}, {"source": "条207｜《医学衷中参西录·医方》·定心汤", "原文": "《医学衷中参西录·医方》：定心汤。治心虚怔忡。  \n龙眼肉一两 酸枣仁五钱，炒捣 萸肉五钱，去净核 柏子仁四钱，炒捣 生龙骨四钱，捣细 生牡蛎四钱，捣细 生明乳香一钱 生明没药一钱  \n心因热怔忡者，酌加生地数钱，若脉沉迟无力者，其怔忡多因胸中大气下陷，详观拙拟升陷汤后跋语及诸案自明治法。", "白话": "定心汤。治心虚怔忡。组成（照录）：龙眼肉一两、酸枣仁五钱炒捣、萸肉五钱去净核、柏子仁四钱炒捣、生龙骨四钱捣细、生牡蛎四钱捣细、生明乳香一钱、生明没药一钱。加减（照录）：心因热怔忡者，酌加生地数钱；若脉沉迟无力者，其怔忡多因胸中大气下陷，详观拙拟升陷汤后跋语及诸案自明治法。方义：养心敛肝、重镇安神，兼活血定痛。"}, {"source": "条208｜《太医院秘藏膏丹丸散方剂》·滋血养心丸", "原文": "《太医院秘藏膏丹丸散方剂》卷四：滋血养心丸。  \n当归五钱，酒洗 白茯神四钱 白芍四钱，酒洗 远志四钱 天冬四钱，去心 麦门冬四钱，去心 酸枣仁三钱，炒 苦芩三钱，酒炒 柴胡三钱，酒炒 红花一钱，酒洗 沙参二钱 黑参二钱 黄连三钱，姜汁炒 柏子仁三钱 甘草二钱，生  \n上为细末，蜜水为丸，如梧桐子大。每服一钱五分或二钱，食远用灯心汤送下。此药用治心气不足，精神恍惚，夜卧不安，怔忡健忘，异梦多惊，心", "白话": "滋血养心丸。组成（照录）：当归五钱酒洗、白茯神四钱、白芍四钱酒洗、远志四钱、天冬四钱去心、麦门冬四钱去心、酸枣仁三钱炒、苦芩三钱酒炒、柴胡三钱酒炒、红花一钱酒洗、沙参二钱、黑参二钱、黄连三钱姜汁炒、柏子仁三钱、甘草二钱生。制法服法（照录）：上为细末，蜜水为丸，如梧桐子大。每服一钱五分或二钱，食远用灯心汤送下。此药用治心气不足、精神恍惚、夜卧不安、怔忡健忘、异梦多惊、心跳心烦等症。方义：养血滋阴、清心安神。"}, {"source": "条209｜《家传女科经验摘奇·补母益子论》·补母益子方", "原文": "《家传女科经验摘奇·补母益子论》：补母益子方。治屡产生子无气，或育而不寿。又补气血虚弱人，孕成不安，或得孕数堕。用此方每服十五帖，弱甚者日服一帖，大益胎而分娩易，又生子精神而有寿也。  \n人参一钱，弱者二三钱 川归二钱 白术二钱，生用 川芎八分 淮熟地二钱 陈皮、紫苏、炙甘草各四分 条芩一钱  \n虚肥人：陈皮去白，加黄连五分、枣三枚、姜一片煎服……怔忡惊悸，加枣仁、益智各一钱，圆眼十个。", "白话": "补母益子方。治屡次生产而子无生气，或育而不寿。又补气血虚弱之人：孕成不安，或得孕数堕。用此方每服十五帖，虚弱甚的每天服一帖，大能益胎而分娩容易，生子精神而有寿。组成（照录）：人参一钱（弱者二三钱）、川归二钱、白术二钱生用、川芎八分、淮熟地二钱、陈皮、紫苏、炙甘草各四分、条芩一钱。加减（照录）：虚肥人：陈皮去白，加黄连五分、枣三枚、姜一片煎服……怔忡惊悸，加枣仁、益智各一钱，圆眼十个。方义：益气养血、健脾安胎，母旺则子安。"}, {"source": "条210｜《家传女科经验摘奇·产后血崩》·滋荣益气汤", "原文": "《家传女科经验摘奇·产后血崩》：滋荣益气汤。治崩止血。  \n川芎、麦冬、黄芪各一钱 人参、川归、淮生地、白术各二钱 陈皮、甘草炙，各四分 白芷、荆芥、升麻各四分 黄连三分，退心火 枣三枚  \n水煎。汗多加麻黄根一钱，浮小麦一撮……惊悸，加酸枣仁、柏子仁各一钱。", "白话": "滋荣益气汤。治崩漏，止血。组成（照录）：川芎、麦冬、黄芪各一钱；人参、川归、淮生地、白术各二钱；陈皮、甘草炙各四分；白芷、荆芥、升麻各四分；黄连三分（退心火）；枣三枚。服法加减（照录）：水煎。汗多加麻黄根一钱，浮小麦一撮……惊悸，加酸枣仁、柏子仁各一钱。方义：益气养荣、升举清阳，佐黄连清心，治崩后气虚之悸。"}, {"source": "条211｜《伤寒论·辨厥阴病脉证并治》·茯苓甘草汤", "原文": "《伤寒论·辨厥阴病脉证并治》：伤寒厥而心下悸，宜先治水，当服茯苓甘草汤，却治其厥，不尔，水渍入胃，必作利也。  \n茯苓二两 甘草炙，一两 生姜切，三两 桂枝去皮，二两  \n上四味，以水四升，煮取二升，去滓，分温三服。", "白话": "伤寒，四肢厥冷而心下悸，宜先治水，当服茯苓甘草汤，然后再治其厥；不如此，水渍入胃，必作下利。（组成照录）：茯苓二两、甘草炙一两、生姜切三两、桂枝去皮二两。煎服（照录）：上四味，以水四升，煮取二升，去滓，分温三服。方义：温阳化饮、通阳利水，先治水饮之悸，厥自回。"}, {"source": "条212｜《金匮要略方论》·半夏麻黄丸", "原文": "《金匮要略方论》卷中：寸口脉动而弱，动即为惊，弱则为悸。心下悸者，半夏麻黄丸主之。  \n半夏、麻黄等分  \n上二味，末之，炼蜜和丸小豆大，饮服三丸，日三服。", "白话": "寸口脉动而弱：动即为惊，弱则为悸。心下悸的，用半夏麻黄丸主治。（组成照录）：半夏、麻黄等分。制法服法（照录）：上二味，末之，炼蜜和丸小豆大，饮服三丸，日三服。方义：水饮内停，以半夏蠲饮、麻黄宣通阳气，治水饮心下悸。"}, {"source": "条213｜《金匮玉函经》·茯苓桂枝甘草大枣汤", "原文": "《金匮玉函经》：发汗后，其人脐下悸者，欲作奔豚，茯苓桂枝甘草大枣汤主之。  \n茯苓半斤  桂枝四两，去皮  甘草二两，炙  大枣十五枚，擘  \n上四味，以甘澜水一斗，先煮茯苓，减二升，内诸药，煮取三升，去滓，温服一升，日三服。作甘澜水法：取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相逐，取用之。", "白话": "发汗以后，其人脐下悸动的，是要发作奔豚，用茯苓桂枝甘草大枣汤主治。（组成照录）：茯苓半斤、桂枝四两去皮、甘草二两炙、大枣十五枚擘。煎服（照录）：上四味，以甘澜水一斗，先煮茯苓，减二升，内诸药，煮取三升，去滓，温服一升，日三服。作甘澜水法：取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相逐，取用之。方义：温通心阳、化气行水，防水气上冲为奔豚。"}, {"source": "条214｜《金匮玉函经》·真武汤", "原文": "《金匮玉函经》卷二：太阳病，发其汗而不解，其人仍发热，心下悸，头眩身瞤而动，振振欲擗地者，真武汤主之。  \n茯苓三两  芍药三两  白术二两  生姜切，三两  附子炮，去皮，破八片，一枚  \n上五味，以水八升，煮取三升，去滓。温服七合，日三服。若咳者，加五味子半升，细辛一两，干姜一两；若小便利者，去茯苓；若下利者，去芍药，加干姜二两；若呕者，去附子，加生姜，足前为半斤。", "白话": "太阳病，发其汗而不解，其人仍发热，心下悸，头眩身瞤动，振振欲倒地的，用真武汤主治。（组成照录）：茯苓三两、芍药三两、白术二两、生姜切三两、附子一枚（炮，去皮，破八片）。煎服加减（照录）：上五味，以水八升，煮取三升，去滓。温服七合，日三服。若咳者，加五味子半升、细辛一两、干姜一两；若小便利者，去茯苓；若下利者，去芍药，加干姜二两；若呕者，去附子，加生姜，足前为半斤。方义：温阳利水，治阳虚水泛、水气凌心之悸眩身动。"}, {"source": "条215｜《肘后备急方》·无名方", "原文": "《肘后备急方》卷三：治人心下虚悸方。  \n麻黄、半夏等分。  \n捣蜜丸。服如大豆三丸，日三，稍增之。半夏汤洗去滑，干。  \n附方：张仲景主心下悸，半夏麻黄丸。二物等分，末，蜜丸如小豆。每服三丸，日三。", "白话": "治人心下虚悸的方。（组成照录）：麻黄、半夏等分。制法服法（照录）：捣蜜丸。服如大豆三丸，日三，稍增之。半夏汤洗去滑，干。附方（照录）：张仲景主心下悸，半夏麻黄丸。二物等分，末，蜜丸如小豆。每服三丸，日三。方义：即半夏麻黄丸之组方，蠲饮宣阳定悸。"}, {"source": "条216｜《小品方》·游气汤", "原文": "《小品方》卷一：游气汤。治五脏有余寒虚气、劳气、惊忧气，其人喜悸，胸中热，上下无常，多悲伤，气流四肢常肿，齐四边核赤肿，小便不利方。  \n厚朴四两  桂肉五两  人参二两  茯苓四两  半夏二两，洗  黄芩二两  生姜八两  陈枳实五枚  甘草二两  \n凡九物，以水一斗，煮取四升，分三服。", "白话": "游气汤。治五脏有余之寒虚气、劳气、惊忧气：其人善悸，胸中热，气上下游走无常，多悲伤，气流于四肢常肿，脐四边核起赤肿，小便不利的方。（组成照录）：厚朴四两、桂肉五两、人参二两、茯苓四两、半夏二两洗、黄芩二两、生姜八两、陈枳实五枚、甘草二两。煎服（照录）：凡九物，以水一斗，煮取四升，分三服。方义：行气散满、化饮利水，气顺饮消则悸平。"}, {"source": "条217｜《外台秘要》·茵陈汤", "原文": "《外台秘要》卷四：疗与黑疸同，谷疸食则眩，心忪怫郁不安，久久发黄为谷疸，并以前茵陈汤主之。方在遍身黄部中。", "白话": "治疗与黑疸相同的证：谷疸进食则眩，心中忪悸怫郁不安，久久发黄成为谷疸，一并用前面的茵陈汤主治。方在“遍身黄”部中。方义：清利湿热退黄，湿热既去，悸眩自安。"}, {"source": "条218｜《伤寒总病论》·甘草附子汤", "原文": "《伤寒总病论》卷三：风湿相搏，骨节疼烦，掣痛不得屈伸，近之则极，汗出短气，小便不利，恶风不欲去被，或有微肿者，甘草附子汤主之。  \n附子二枚  白术二两  桂枝三两  甘草二两  \n㕮咀，水三升，煮取一升，去滓，分温三服。身肿者加防己二两；悸气、小便不利加茯苓一两半，溢水成四升，煎一升三合。", "白话": "风湿相搏，骨节疼烦，掣痛不得屈伸，近之则痛剧，汗出短气，小便不利，恶风不欲去被，或有微肿的，用甘草附子汤主治。（组成照录）：附子二枚、白术二两、桂枝三两、甘草二两。煎服加减（照录）：㕮咀，水三升，煮取一升，去滓，分温三服。身肿者加防己二两；悸气、小便不利加茯苓一两半，益水成四升，煎一升三合。方义：温经祛风、化湿止痛，阳通湿去则悸气自平。"}, {"source": "条219｜《黄帝素问宣明论方》·人参白术散", "原文": "《黄帝素问宣明论方》卷十一：人参白术散。治遍身燥湿相抟，玄府致密，遂令忪悸发渴，饮食减少，不为肌肤。  \n人参三钱  白术七钱  薄荷半两  缩砂仁三钱  生地黄、茯苓去皮、甘草各半两 黄芩一钱  滑石三两  藿香三钱半  石膏一两  \n上为末，每服三钱，水一盏，煎至六分，去滓，温服，食前，日进二三服。", "白话": "人参白术散。治遍身燥湿相搏，玄府致密，于是使人忪悸、发渴，饮食减少，不长肌肉。（组成照录）：人参三钱、白术七钱、薄荷半两、缩砂仁三钱、生地黄、茯苓去皮、甘草各半两、黄芩一钱、滑石三两、藿香三钱半、石膏一两。制法服法（照录）：上为末，每服三钱，水一盏，煎至六分，去滓，温服，食前，日进二三服。方义：健脾益气、清热化湿，燥湿分消则悸渴自除。"}, {"source": "条220｜《仁斋直指方论（附补遗）》·桂枝附子汤", "原文": "《仁斋直指方论（附补遗）》卷三：桂枝附子汤。治风湿相搏，汗出气短，身体烦疼，微肿，恶风不欲去衣。  \n辣桂二两  白术、附子熟，各一两半  甘草炙，一两  \n上锉散。每服二钱半，水盏半，姜七片，枣二枚，煎一盏，食前，微温服。小便不利、悸气加茯苓；痹加防己，腹痛加芍药。", "白话": "桂枝附子汤。治风湿相搏，汗出气短，身体烦疼，微肿，恶风不欲去衣。（组成照录）：辣桂二两、白术、附子熟各一两半、甘草炙一两。制法服法与加减（照录）：上锉散。每服二钱半，水盏半，姜七片，枣二枚，煎一盏，食前，微温服。小便不利、悸气加茯苓；痹加防己，腹痛加芍药。方义：温经散寒、祛风胜湿。"}, {"source": "条221｜《仁斋直指方论（附补遗）》·芎夏汤", "原文": "《仁斋直指方论（附补遗）》卷七：芎夏汤。逐水利饮通用。  \n川芎、半夏制、茯苓各一两  青皮、陈皮、枳壳制，各半两  白术、甘草炒，各一分  \n上锉散。每服三钱，姜五厚片，煎服。川芎、半夏能逐水也。喘加去节麻黄，嗽加炒桑白皮，呕加生姜、半夏，泄加苍术，白术，痞隔加枳壳、桔梗，胀满加缩砂，白豆蔻，眩晕加半夏、南星，怔忪加白茯苓。寒热疼痛下其癖，浮肿体重渗其湿，余以类推。", "白话": "芎夏汤。逐水利饮的通用方。（组成照录）：川芎、半夏制、茯苓各一两；青皮、陈皮、枳壳制各半两；白术、甘草炒各一分。制法服法与加减（照录）：上锉散。每服三钱，姜五厚片，煎服。川芎、半夏能逐水也。喘加去节麻黄，嗽加炒桑白皮，呕加生姜、半夏，泄加苍术、白术，痞隔加枳壳、桔梗，胀满加缩砂、白豆蔻，眩晕加半夏、南星，怔忪加白茯苓。寒热疼痛下其癖，浮肿体重渗其湿，余以类推。方义：行气逐水、化饮定悸。"}, {"source": "条222｜《仁斋直指方论（附补遗）》·大半夏汤", "原文": "《仁斋直指方论（附补遗）》卷七：寻常水气，心下怔忪，大半夏汤、小半夏茯苓汤、五苓散辈通用可也。", "白话": "寻常水气、心下怔忪的，用大半夏汤、小半夏茯苓汤、五苓散之类通用即可。方义：皆属温化痰饮、和胃降逆之剂，饮去则怔忪止。"}, {"source": "条223｜《仁斋直指方论（附补遗）》·姜术汤", "原文": "《仁斋直指方论（附补遗）》卷十一：姜术汤。治虚证停饮怔忪。  \n白姜生、白术、茯苓、半夏曲各半两  辣桂、甘草炙，各一分  \n上锉，每服三钱，姜、枣煎服。", "白话": "姜术汤。治虚证停饮怔忪。（组成照录）：白姜生、白术、茯苓、半夏曲各半两；辣桂、甘草炙各一分。制法服法（照录）：上锉，每服三钱，姜、枣煎服。方义：温中健脾、化饮定悸。"}, {"source": "条224｜《仁斋直指方论（附补遗）》·茯苓甘草汤", "原文": "《仁斋直指方论（附补遗）》卷十一：茯苓甘草汤。治心下停水忪悸。  \n茯苓、桂枝各二两 甘草炙，一两 生姜三两  \n上锉。每服四钱，水煎服。", "白话": "茯苓甘草汤。治心下停水忪悸。（组成照录）：茯苓、桂枝各二两，甘草炙一两，生姜三两。制法服法（照录）：上锉。每服四钱，水煎服。方义：通阳化气、利水定悸。"}, {"source": "条225｜《世医得效方》·茯神汤", "原文": "《世医得效方》卷三：茯神汤。治喜怒忧思悲恐惊所感，脏气不行，郁而生涎，结为饮，随气上厥，伏留阳经。心中忪悸，四肢缓弱，翕然面热，头目眩冒，如欲摇动。  \n人参、麦门冬去心、山药各二两 前胡、熟地黄洗，酒拌炒，各一两 枳壳去瓤，麸炒，三分 远志甘草水煮去心，姜汁拌炒，三分 白茯苓、茯神各一两半 半夏汤洗七次、黄芪炙，各一两 甘草半两  \n上锉散。每服四钱，流水盏半，姜五片，秫米一撮煎，食前服。", "白话": "茯神汤。治被喜怒忧思悲恐惊七情所感，脏气不行，郁而生涎，结为饮，随气上厥，伏留阳经。心中忪悸，四肢缓弱，翕然面热，头目眩冒，如欲摇动。（组成照录）：人参、麦门冬去心、山药各二两；前胡、熟地黄洗酒拌炒各一两；枳壳去瓤麸炒三分；远志甘草水煮去心姜汁拌炒三分；白茯苓、茯神各一两半；半夏汤洗七次、黄芪炙各一两；甘草半两。制法服法（照录）：上锉散。每服四钱，流水盏半，姜五片，秫米一撮煎，食前服。方义：化饮降逆、益气养心，治七情动饮之忪悸眩冒。"}, {"source": "条226｜《世医得效方》·姜术汤", "原文": "《世医得效方》卷八：姜术汤。治虚证停饮，怔忡。  \n白姜生、白术、茯苓、半夏曲各半两 辣桂、甘草炙，各一分  \n上锉散。每服三钱，水一盏，生姜三片，红枣一枚煎，温服，不拘时候。", "白话": "姜术汤。治虚证停饮，怔忡。（组成照录）：白姜生、白术、茯苓、半夏曲各半两；辣桂、甘草炙各一分。制法服法（照录）：上锉散。每服三钱，水一盏，生姜三片，红枣一枚煎，温服，不拘时候。方义：温中化饮、健脾定忡。"}, {"source": "条227｜《脉因证治》·五苓散", "原文": "《脉因证治》卷三：五苓散。治瘦人，脐下有悸者，吐涎沫而颠眩，水也。痰饮证状 或咳或喘，或呕或泄，眩晕嘈烦，忪悸愪，寒热疼痛，肿满挛癖，癃闭痞膈，如风如癫。", "白话": "五苓散。治瘦人脐下有悸、吐涎沫而颠眩的，属水。痰饮证状：或咳或喘，或呕或泄，眩晕嘈烦，忪悸，寒热疼痛，肿满挛癖，癃闭痞膈，如风如癫。方义：利水渗湿、通阳化气，水饮去则悸眩自止。"}, {"source": "条228｜《奇效良方》·姜术汤", "原文": "《奇效良方》卷四十六：姜术汤。治虚证，停饮怔忡。  \n白姜生、白术、茯苓去皮 、夏曲各二钱 辣桂去皮、甘草炙，各半钱  \n上作一服，水二盅，生姜三片，红枣一枚，煎一盅，不拘时服。", "白话": "姜术汤。治虚证，停饮怔忡。（组成照录）：白姜生、白术、茯苓去皮、夏曲各二钱；辣桂去皮、甘草炙各半钱。制法服法（照录）：上作一服，水二盅，生姜三片，红枣一枚，煎一盅，不拘时服。方义：温中健脾、化饮定忡。"}, {"source": "条229｜《证治准绳·杂病》·五饮汤丸", "原文": "《证治准绳·杂病》：《三因》云：五饮停蓄，闭于中脘，最使人惊骇，属饮家。（五饮汤丸）心胆虚怯，触事易惊，或梦寐不祥，遂致心惊胆慑，气郁生涎，涎与气搏，变生诸证，或短气悸乏，或复自汗者，并温胆汤主之。呕则以人参代竹茹。若惊悸眠多异梦随即惊觉者，宜温胆汤加酸枣仁、莲肉各一钱，以金银煎下十四友丸，或镇心丹、远志丸、酒调妙香散、琥珀养心丹、定志丸、宁志丸。卧而多惊魇，真珠母丸、独活汤。", "白话": "《三因》说：五饮停蓄，闭于中脘，最使人惊骇，属饮家。（五饮汤丸）心胆虚怯，触事易惊，或梦寐不祥，遂致心惊胆慑，气郁生涎，涎与气搏，变生诸证：或短气悸乏，或又自汗的，都用温胆汤主治。呕则以人参代竹茹。若惊悸、眠多异梦随即惊觉的，宜温胆汤加酸枣仁、莲肉各一钱，用金银煎汤送下十四友丸；或用镇心丹、远志丸、酒调妙香散、琥珀养心丹、定志丸、宁志丸。卧而多惊魇的，用真珠母丸、独活汤。方义：温胆化饮、镇心安神，随证选用诸方。"}, {"source": "条230｜《济阳纲目》·羌活导滞汤", "原文": "《济阳纲目》卷七十七：三阴里证，胸满怔忡，遍体转筋，二便闭涩或自利者，羌活导滞汤、除湿丹、导水丸、搜风顺气丸。", "白话": "三阴里证，胸满怔忡，遍体转筋，二便闭涩或自利的，用羌活导滞汤、除湿丹、导水丸、搜风顺气丸。方义：攻下导滞、祛湿通腑，里湿滞去则怔忡平。"}, {"source": "条231｜《幼科折衷秘传真本·杂方》·六合定中丸", "原文": "《幼科折衷秘传真本·杂方》：六合定中丸。治暑月感凉，疟疾霍乱，胸闷恶心，头疼腹痛，或吐泻寒热如虐，以及小儿发热发搐，吐乳惊悸，一切中土不和等症。  \n老苏梗、陈香薷、广藿香以上，各四两 炒枳壳三两 羌活二两 赤苓四两  \n加老姜为丸，如龙眼肉大，每服一丸。", "白话": "六合定中丸。治暑月感凉，疟疾霍乱，胸闷恶心，头疼腹痛，或吐泻寒热如疟，以及小儿发热发搐、吐乳惊悸，一切中土不和等症。（组成照录）：老苏梗、陈香薷、广藿香以上各四两，炒枳壳三两，羌活二两，赤苓四两。制法服法（照录）：加老姜为丸，如龙眼肉大，每服一丸。方义：解表祛暑、理气和中，中土和则惊悸自止。"}, {"source": "条232｜《医通祖方·益元散》·辰砂六一散", "原文": "《医通祖方·益元散》：辰砂六一散。治暑月惊悸，多汗，小便涩痛。益元散一料，加辰砂一钱飞。", "白话": "辰砂六一散。治暑月惊悸、多汗、小便涩痛。用益元散一料，加水飞辰砂一钱。方义：清暑利湿、镇心安神。"}, {"source": "条233｜《伤寒论·辨霍乱病脉证并治》·理中丸", "原文": "《伤寒论·辨霍乱病脉证并治》：霍乱，头痛、发热、身疼痛、热多欲饮水者，五苓散主之；寒多不用水者，理中丸主之。  \n人参 干姜 甘草炙 白术各三两  \n上四味，捣筛，蜜和为丸，如鸡子黄许大。以沸汤数合，和一丸，研碎，温服之，日三四、夜二服；腹中未热，益至三四丸，然不及汤。汤法：以四物依两数切，用水八升，煮取三升，去滓，温服一升，日三服。若脐上筑者，肾气动也，去术加桂四两；吐多者，去术加生姜三两；下多", "白话": "霍乱，头痛、发热、身疼痛、热多欲饮水的，用五苓散主之；寒多不用水的，用理中丸主之。（组成照录）：人参、干姜、甘草炙、白术各三两。制法服法与加减（照录）：上四味，捣筛，蜜和为丸，如鸡子黄许大。以沸汤数合，和一丸，研碎，温服之，日三四、夜二服；腹中未热，益至三四丸，然不及汤。汤法：以四物依两数切，用水八升，煮取三升，去滓，温服一升，日三服。若脐上筑者，肾气动也，去术加桂四两；吐多者，去术加生姜三两；下多者还用术；悸者，加茯苓二两。方义：温中健脾；悸者加茯苓以宁心利水。"}, {"source": "条234｜《金匮玉函经》·小建中汤", "原文": "《金匮玉函经》：伤寒，二三日，心中悸而烦，小建中汤主之。  \n桂枝去皮，三两 甘草炙，二两 大枣擘，十二枚 芍药六两 生姜切，三两 胶饴一升  \n上六味，以水七升，煮取三升，去滓，内饴，更上微火消解。温服一升，日三服。呕家不可用建中汤，以甜故也。", "白话": "伤寒二三日，心中悸而烦的，用小建中汤主之。（组成照录）：桂枝去皮三两、甘草炙二两、大枣擘十二枚、芍药六两、生姜切三两、胶饴一升。煎服法（照录）：上六味，以水七升，煮取三升，去滓，内饴，更上微火消解。温服一升，日三服。呕家不可用建中汤，以甜故也。方义：温中补虚、和里缓急，中气建则悸烦自止。"}, {"source": "条235｜《金匮玉函经》·桂枝甘草汤", "原文": "《金匮玉函经》卷二：发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之。  \n桂枝四两，去皮 甘草二两，炙  \n上二味，以水三升，煮取一升，去滓，顿服。", "白话": "发汗过多，其人两手交叉按于心下，心下悸、欲得按的，用桂枝甘草汤主之。（组成照录）：桂枝四两去皮、甘草二两炙。煎服（照录）：上二味，以水三升，煮取一升，去滓，顿服。方义：辛甘化阳、温通心阳，心阳复则悸止。"}, {"source": "条236｜《小品方》·龙骨汤", "原文": "《小品方》卷三：龙骨汤。治梦失精，诸脉浮动，心悸少急，隐处寒，目眶疼，头发脱者，常七日许一剂，至良方。  \n龙骨、甘草炙，各二分  牡蛎三分，熬 桂心、芍药各四分  大枣四枚，擘  生姜五分  \n上七味，切，以水四升，煮取一升半，分再服。", "白话": "龙骨汤。治梦中失精，诸脉浮动，心悸而稍急，外阴部寒冷，目眶疼，头发脱落；常七日左右服一剂，是极好的方。（组成照录）：龙骨、甘草炙各二分，牡蛎三分熬，桂心、芍药各四分，大枣四枚擘，生姜五分。煎服（照录）：上七味，切，以水四升，煮取一升半，分再服。方义：潜镇固涩、调和阴阳，治虚阳浮动之悸。"}, {"source": "条237｜《小品方》·九痛丸", "原文": "《小品方》卷五：九痛丸。主九种心痛。一虫心痛，二注心痛，三风心痛，四悸心痛，五食心痛，六饮心痛，七冷心痛，八热心痛，九生来心痛，方悉主之。并治冷肿上气，落马堕车方。  \n附子二两  巴豆仁一两  生狼毒一两，炙令极香》  人参一两  干姜一两  吴茱萸一两  \n六味，蜜和，空腹服如梧子三丸。卒中恶腹痛，口不言，二日一服。连年积冷，流注心胸者，亦服之，好好将息，神验。", "白话": "九痛丸。主治九种心痛：一虫心痛，二注心痛，三风心痛，四悸心痛，五食心痛，六饮心痛，七冷心痛，八热心痛，九生来心痛——此方全都主治。并治冷肿上气、落马堕车之伤。（组成照录）：附子二两、巴豆仁一两、生狼毒一两（炙令极香》）、人参一两、干姜一两、吴茱萸一两。制法服法（照录）：六味，蜜和，空腹服如梧子三丸。卒中恶腹痛、口不言，二日一服。连年积冷、流注心胸者，亦服之，好好将息，神验。方义：温通攻积、逐冷止痛。"}, {"source": "条238｜《小品方》·理中汤", "原文": "《小品方》卷四：霍乱脐上筑者，肾气动也，先治气，理中汤去术加桂。凡方加术者，以内虚也；加桂者，恐作奔豚也，理中汤方。  \n人参三两  甘草三两，炙  白术三两  干姜三两，炮  \n上四味，切，以水八升，煮取三升，去滓，温服一升，日三夜一。  \n若脐上筑者，肾气动也，去术加桂心四两；吐多者，去术加生姜三两；若下多者，复用术，悸者加茯苓二两；若病先时渴喜得水者，加术合前成四两半；若腹中痛者，加人参合前", "白话": "霍乱脐上悸动的，是肾气动，先治气，用理中汤去术加桂。凡方中加白术的，是因为内虚；加桂的，是恐怕发作奔豚。理中汤方：（组成照录）：人参三两、甘草三两炙、白术三两、干姜三两炮。煎服与加减（照录）：上四味，切，以水八升，煮取三升，去滓，温服一升，日三夜一。若脐上筑者，肾气动也，去术加桂心四两；吐多者，去术加生姜三两；若下多者，复用术，悸者加茯苓二两；若病先时渴喜得水者，加术合前成四两半；若腹中痛者，加人参合前成四两半；若恶寒者，加干姜合前成四两半；若腹满者，去术加附子一枚（炮去皮、"}, {"source": "条239｜《外台秘要》·范汪大茱萸丸", "原文": "《外台秘要》卷七：范汪大茱萸丸。疗心腹寒疝，胸中有逆气，时上抢心痛，烦满不得卧，面目恶风，悸掉，惕惕时惊，不欲饮食而呕，变发寒热方。  \n吴茱萸半升  细辛、芍药、柴胡一方用前胡、旋覆花、黄芩、紫菀、人参、白术、茯苓、干姜、桂心、附子炮、甘草炙、半夏洗、当归各半两  \n上十六味，捣筛，以蜜和为丸，如梧子。先食服三丸，日三，不知稍加。忌生葱、羊肉、饧、酢物、桃、李、雀肉、猪肉、生菜、海藻、菘菜，除此", "白话": "范汪大茱萸丸。疗心腹寒疝，胸中有逆气，时时上抢心痛，烦满不得卧，面目恶风，悸动振掉，惕惕时惊，不欲饮食而呕，并发寒热的方。（组成照录）：吴茱萸半升；细辛、芍药、柴胡（一方用前胡）、旋覆花、黄芩、紫菀、人参、白术、茯苓、干姜、桂心、附子炮、甘草炙、半夏洗、当归各半两。制法服法与忌口（照录）：上十六味，捣筛，以蜜和为丸，如梧子。先食服三丸，日三，不知稍加。忌生葱、羊肉、饧、酢物、桃、李、雀肉、猪肉、生菜、海藻、菘菜，除此更无所忌。（一方有蜀椒、无桂心，又一方有干地黄、无黄芩，《深"}, {"source": "条240｜《严氏济生方·惊悸怔忡健忘门》·龙齿丹", "原文": "《严氏济生方·惊悸怔忡健忘门》：龙齿丹。治心血虚寒，怔忡不已，痰多恍惚。  \n龙齿、附子炮，去皮脐，切片，姜汁浸一宿、远志去心，甘草煮、酸枣仁炒，去壳，别研、当归去芦，酒浸、官桂去皮，不见火、琥珀别研、南星锉，姜汁浸一宿，各一两、木香不见火、紫石英煅，醋淬七遍、沉香别研、熟地黄酒蒸，焙，各半两  \n上为细末，炼蜜为丸，如梧桐子大，朱砂为衣，每服五十丸，用枣汤送下，不拘时候。", "白话": "龙齿丹。治心血虚寒，怔忡不已，痰多恍惚。（组成照录）：龙齿、附子（炮，去皮脐，切片，姜汁浸一宿）、远志（去心，甘草煮）、酸枣仁（炒，去壳，别研）、当归（去芦，酒浸）、官桂（去皮，不见火）、琥珀（别研）、南星（锉，姜汁浸一宿）各一两；木香（不见火）、紫石英（煅，醋淬七遍）、沉香（别研）、熟地黄（酒蒸，焙）各半两。制法服法（照录）：上为细末，炼蜜为丸，如梧桐子大，朱砂为衣，每服五十丸，用枣汤送下，不拘时候。方义：温养心血、镇心化痰，治虚寒怔忡。"}, {"source": "条241｜《严氏济生方·霍乱门》·理中汤", "原文": "《严氏济生方·霍乱门》：理中汤。治过食生冷，或饮寒浆，遂成吐下，胀满，食不消，心腹痛。  \n人参、甘草炙、干姜炮、白术各等分  \n上为锉散，每服四钱，水一大盏，煎至七分，去滓，温服，不拘时候。若脐上筑者，肾气动也，去术加桂一两；吐多者，去术加生姜、半夏各半两；利多者，复用术；心悸者，加茯苓一两。", "白话": "理中汤。治过食生冷，或饮寒浆，遂成上吐下泻，胀满，食不消化，心腹痛。（组成照录）：人参、甘草炙、干姜炮、白术各等分。制法服法与加减（照录）：上为锉散，每服四钱，水一大盏，煎至七分，去滓，温服，不拘时候。若脐上筑者，肾气动也，去术加桂一两；吐多者，去术加生姜、半夏各半两；利多者，复用术；心悸者，加茯苓一两。方义：温中散寒、健脾止泻；心悸者加茯苓宁心。"}, {"source": "条242｜《仁斋直指方论（附补遗）》·加减理中汤", "原文": "《仁斋直指方论（附补遗）》卷十三：加减理中汤。人参 白术 干姜 甘草（炙,各等分）……若悸多，加茯苓一两。", "白话": "加减理中汤。（组成照录）：人参、白术、干姜、甘草（炙，各等分）……若悸多，加茯苓一两。方义：理中温阳，悸甚加茯苓宁心定悸。"}, {"source": "条243｜《普济方》·吴茱萸汤", "原文": "《普济方》卷二百四十八：吴茱萸汤出《圣惠方》。治寒疝、腰腹痛，胸中冷气上抢，心胁支满，不得卧，面目痛，风寒悸栗多惊，不能饮食，食已即呕，寒热往来。  \n吴茱萸汤浸七次焙干微炒、半夏浸七次去滑、姜炮制锉、人参去芦头、当归锉碎微炒、赤芍药各三分 细辛、紫菀去苗土、附子炮裂去皮、熟干地黄、前胡去芦头、赤茯苓、白术、桂心、木香各一两 甘草炙微锉、旋覆花各半两 诃黎勒一两半，用皮  \n上为末，炼蜜和捣三二百", "白话": "吴茱萸汤，出自《圣惠方》。治寒疝、腰腹痛，胸中冷气上抢，心胁支满，不得卧，面目痛，风寒悸栗多惊，不能饮食，食已即呕，寒热往来。（组成照录）：吴茱萸（汤浸七次焙干微炒）、半夏（浸七次去滑）、姜（炮制锉）、人参（去芦头）、当归（锉碎微炒）、赤芍药各三分；细辛、紫菀（去苗土）、附子（炮裂去皮）、熟干地黄、前胡（去芦头）、赤茯苓、白术、桂心、木香各一两；甘草（炙微锉）、旋覆花各半两；诃黎勒一两半（用皮）。制法服法（照录）：上为末，炼蜜和捣三二百杵，丸如梧桐子大，不拘时，生姜汤下二十丸"}, {"source": "条244｜《奇效良方》·麻黄散", "原文": "《奇效良方》卷一：麻黄散。治心脏中风，虚寒颤，心惊掣悸，语声混浊，口歪冒昧，好笑，并宜服之。  \n麻黄去节，一钱 白术一钱 防风去芦，一钱 川芎一钱 甘草炙，一钱 汉防己一钱 当归一钱，去芦 人参一钱，去芦 羌活一钱半，去芦 远志一钱半，去心 川升麻八分 桂心半钱 茯神一钱半，去木  \n上作一服，水二盅，生姜五片，煎至一盅，入竹沥半盏，再煎一二沸，不拘时服。", "白话": "麻黄散。治心脏中风，虚寒颤栗，心惊掣悸，语声混浊，口眼歪斜、神识冒昧，好笑，都宜服之。（组成照录）：麻黄去节一钱、白术一钱、防风去芦一钱、川芎一钱、甘草炙一钱、汉防己一钱、当归去芦一钱、人参去芦一钱、羌活去芦一钱半、远志去心一钱半、川升麻八分、桂心半钱、茯神去木一钱半。煎服（照录）：上作一服，水二盅，生姜五片，煎至一盅，入竹沥半盏，再煎一二沸，不拘时服。方义：祛风散寒、通阳定悸。"}, {"source": "条245｜《女科证治准绳》·白芷暖宫丸", "原文": "《女科证治准绳》卷一：白芷暖宫丸。暖血海，实冲任。治子宫虚弱，风寒客滞，断绪不成孕育，及数坠胎；或带下赤白，漏下五色，虚眩少气，胸腹满痛，心下烦悸，自汗，下血过多。  \n禹余粮制，一两  干姜炮、芍药、白芷、川椒制、阿胶粉炒、艾叶制、川芎各七钱半  \n上为细末，蜜丸梧子大。每服四十丸，米饮、温酒、醋汤任下。", "白话": "白芷暖宫丸。暖血海，充实冲任。治子宫虚弱，风寒客滞，久不受孕，以及屡次堕胎；或带下赤白、漏下五色，虚眩少气，胸腹满痛，心下烦悸，自汗，下血过多。（组成照录）：禹余粮制一两；干姜炮、芍药、白芷、川椒制、阿胶粉炒、艾叶制、川芎各七钱半。制法服法（照录）：上为细末，蜜丸梧子大。每服四十丸，米饮、温酒、醋汤任下。方义：温暖子宫、养血固冲。"}, {"source": "条246｜《经验丹方汇编》·理中汤", "原文": "《经验丹方汇编》：阴疟二疸肢冷自汗、泄利便清、脉沉迟者是阴黄；耳鸣口淡、怔忡微热、四肢无力、嗜卧、脉沉细、寒热泄白者是虚黄。皆以理中汤治之。  \n人参、白术各三钱半 甘草炙、干姜炮，各一两  空心煎服。", "白话": "阴疟、二疸见肢冷自汗、泄利便清、脉沉迟的，是阴黄；耳鸣口淡、怔忡微热、四肢无力、嗜卧、脉沉细、寒热泄白的，是虚黄。都用理中汤治之。（组成照录）：人参、白术各三钱半，甘草炙、干姜炮各一两，空心煎服。方义：温中健脾，中阳得复则黄退悸安。"}, {"source": "条247｜《刘涓子鬼遗方》·㹠心汤", "原文": "《刘涓子鬼遗方》卷二：治金疮惊悸，心中满满如车所惊怛，㹠心汤方。  \n㹠心一具  人参  桂心  甘草炙  干地黄  桔梗  石膏末  芎  当归二两  \n上九味，细切锉，诸药㕮咀，先以水二斗煮心，取汁八升，纳诸药，煮取一升，一服八合，一日令尽。", "白话": "治金疮惊悸，心中胀满如受车马惊吓的，用㹠心汤方。（组成照录）：㹠心一具、人参、桂心、甘草炙、干地黄、桔梗、石膏末、芎、当归二两。煎服（照录）：上九味，细切锉，诸药㕮咀，先以水二斗煮心，取汁八升，纳诸药，煮取一升，一服八合，一日令尽。方义：以脏补脏、益气养心定悸。"}, {"source": "条248｜《备急千金要方》·大定心汤", "原文": "《备急千金要方》卷十四：大定心汤。治心气虚悸，恍惚多忘，或梦惊魇志少不足方。  \n人参、茯苓、茯神、远志、赤石脂、龙骨、干姜、当归、甘草、白术、芍药、 桂心、紫菀、防风各二两  大枣二十枚  \n上十五味，㕮咀，以水一斗二升煮取三升半，分五服，日三夜二。", "白话": "大定心汤。治心气虚悸，恍惚多忘，或梦惊魇、志意不足的方。（组成照录）：人参、茯苓、茯神、远志、赤石脂、龙骨、干姜、当归、甘草、白术、芍药、桂心、紫菀、防风各二两，大枣二十枚。煎服（照录）：上十五味，㕮咀，以水一斗二升煮取三升半，分五服，日三夜二。方义：补心气、镇心神、定惊悸。"}, {"source": "条249｜《备急千金要方》·大镇心散", "原文": "《备急千金要方》卷十四：大镇心散。治心虚惊悸，梦寐恐畏方。  \n紫石英、茯苓、防风、人参、甘草、泽泻各八分  黄芪、白术、薯蓣、秦艽、白蔹各六分  麦门冬、当归各五分  桔梗、大豆黄卷、柏子仁、桂心、远志、大黄、石膏各四分  干姜、蜀椒、芍药、细辛各三分  \n上二十四味治，下筛，酒服三方寸匕，日三。（一方无紫石英、茯苓、泽泻、干姜，有大枣四分，蜜丸如梧子大，酒下十五丸。", "白话": "大镇心散。治心虚惊悸、梦寐恐畏的方。（组成照录）：紫石英、茯苓、防风、人参、甘草、泽泻各八分；黄芪、白术、薯蓣、秦艽、白蔹各六分；麦门冬、当归各五分；桔梗、大豆黄卷、柏子仁、桂心、远志、大黄、石膏各四分；干姜、蜀椒、芍药、细辛各三分。服法（照录）：上二十四味治，下筛，酒服三方寸匕，日三。（一方无紫石英、茯苓、泽泻、干姜，有大枣四分，蜜丸如梧子大，酒下十五丸。方义：益气养心、重镇安神，兼以散风。"}, {"source": "条250｜《备急千金要方》·小镇心散", "原文": "《备急千金要方》卷十四：小镇心散。治心气不足，虚悸恐畏，悲思恍惚，心神不定惕惕然惊者方。  \n人参、白术、远志、附子、桂心、黄芪、细辛、干姜、干地黄、赤小豆、龙齿、防风、菖蒲各二两  茯苓四两  \n上十四味治，下筛，酒服二方寸匕，日三。", "白话": "小镇心散。治心气不足，虚悸恐畏，悲思恍惚，心神不定、惕惕然惊的方。（组成照录）：人参、白术、远志、附子、桂心、黄芪、细辛、干姜、干地黄、赤小豆、龙齿、防风、菖蒲各二两，茯苓四两。服法（照录）：上十四味治，下筛，酒服二方寸匕，日三。方义：补心气、温心阳、镇心神。"}, {"source": "条251｜《备急千金要方》·小镇心丸", "原文": "《备急千金要方》卷十四：小镇心丸。治心气少弱，惊虚振悸，胸中逆气，魇梦参错谬忘恍惚方。  \n紫石英、朱砂、茯神、银屑、雄黄、菖蒲、人参、桔梗、干姜、远志、甘草、 当归、桂心各二两  防风、防己、细辛、铁精各一两  \n上十七味为末，蜜丸，如大豆，饮服十丸，日三，加至二十丸。（一方有茯苓二分，为十八味）", "白话": "小镇心丸。治心气少弱，惊虚振悸，胸中逆气，魇梦错杂、健忘恍惚的方。（组成照录）：紫石英、朱砂、茯神、银屑、雄黄、菖蒲、人参、桔梗、干姜、远志、甘草、当归、桂心各二两；防风、防己、细辛、铁精各一两。制法服法（照录）：上十七味为末，蜜丸，如大豆，饮服十丸，日三，加至二十丸。（一方有茯苓二分，为十八味）方义：重镇安神、益气温阳。"}, {"source": "条252｜《备急千金要方》·镇心丸", "原文": "《备急千金要方》卷十四：镇心丸。治男子妇人虚损，梦寤惊悸或失精神，妇人赤白注漏或月水不利，风邪鬼疰，寒热往来，腹中积聚，忧恚结气诸病方。  \n紫石英、茯苓、菖蒲、肉苁蓉、麦门冬、远志、大黄、当归、细辛、大豆黄卷、卷柏、干姜各五分  人参、丹参、防风、秦艽、泽泻各六分  柏子仁、芍药、石膏各三分  乌头、桂心、桔梗、甘草、薯蓣、前胡、白蔹、铁精、银屑、牛黄各二分  白术、半夏各三分  䗪虫十二枚  ", "白话": "镇心丸。治男子妇人虚损，梦寤惊悸或失精神，妇人赤白注漏或月水不利，风邪鬼疰，寒热往来，腹中积聚，忧恚结气诸病的方。（组成照录）：紫石英、茯苓、菖蒲、肉苁蓉、麦门冬、远志、大黄、当归、细辛、大豆黄卷、卷柏、干姜各五分；人参、丹参、防风、秦艽、泽泻各六分；柏子仁、芍药、石膏各三分；乌头、桂心、桔梗、甘草、薯蓣、前胡、白蔹、铁精、银屑、牛黄各二分；白术、半夏各三分；䗪虫十二枚；干地黄十二分；大枣五十枚。制法服法（照录）：上三十五味为末，蜜枣和捣五千杵，丸如梧子，酒服五丸，日三，加至"}, {"source": "条253｜《千金翼方》·紫石英汤", "原文": "《千金翼方》卷十二：紫石英汤。主心虚惊悸、寒热、百病，令人肥健方。  \n紫石英十两  白石英十两  白石脂三十两  赤石脂三十两  干姜三十两  \n上五味，㕮咀皆完，用二石英各取一两，石脂等三味各取三两，以水三升合以微火煎，宿勿食，分为四服，日三夜一服。后午时乃食。日日依前秤取昨日药，乃置新药中共煮，乃至药尽常然，水数一准十，新药尽讫常添水，去滓，服之满四十日止，忌酒肉。药水皆用大升秤，取汁亦用大", "白话": "紫石英汤。主治心虚惊悸、寒热、百病，使人肥健的方。（组成照录）：紫石英十两、白石英十两、白石脂三十两、赤石脂三十两、干姜三十两。煎服法（照录）：上五味，㕮咀皆完，用二石英各取一两，石脂等三味各取三两，以水三升合以微火煎，宿勿食，分为四服，日三夜一服。后午时乃食。日日依前秤取昨日药，乃置新药中共煮，乃至药尽常然，水数一准十，新药尽讫常添水，去滓，服之满四十日止，忌酒肉。药水皆用大升秤，取汁亦用大升。服汤讫即行，勿住坐卧。须令药力遍身，百脉中行。若大冷者，春秋各四十九日。服令疾退"}, {"source": "条254｜《千金翼方》·大酸枣汤", "原文": "《千金翼方》卷十八：大酸枣汤。主虚劳烦悸，奔气在胸中，不得眠方。  \n酸枣仁五升、人参、茯苓、生姜切、芎、桂心各二两  甘草炙，一两半  \n上七味，㕮咀。以水一斗二升，煮枣仁取七升，去滓，纳诸药，煮取三升，分三服。", "白话": "大酸枣汤。主治虚劳烦悸，奔气在胸中，不得眠的方。（组成照录）：酸枣仁五升、人参、茯苓、生姜切、芎、桂心各二两，甘草炙一两半。煎服（照录）：上七味，㕮咀。以水一斗二升，煮枣仁取七升，去滓，纳诸药，煮取三升，分三服。方义：养心安神、温阳降冲，治虚劳烦悸不寐。"}, {"source": "条255｜《太平圣惠方》·龙齿散", "原文": "《太平圣惠方》卷四：治心脏风虚，惊悸失常，或喜或怒，神思不安，宜服龙齿散方。  \n龙齿一两  远志半两，去心  茯神一两  防风半两，去芦头  甘草半两，炙微赤，锉  人参三分，去芦头  麦门冬三分，去心  羚羊角屑三分  \n上件药，捣粗罗为散。每服三钱，以水一中盏，入生姜半分，枣三枚，煎至六分。去滓，不计时候温服。", "白话": "治心脏风虚，惊悸失常，或喜或怒，神思不安，宜服龙齿散方。（组成照录）：龙齿一两、远志半两去心、茯神一两、防风半两去芦头、甘草半两炙微赤锉、人参三分去芦头、麦门冬三分去心、羚羊角屑三分。制法服法（照录）：上件药，捣粗罗为散。每服三钱，以水一中盏，入生姜半分，枣三枚，煎至六分。去滓，不计时候温服。方义：镇心安神、祛风定悸。"}, {"source": "条256｜《太平圣惠方》·紫石英散", "原文": "《太平圣惠方》卷四：治心脏风虚，惊悸失志，或瞋恚悲愁，志意不乐，惕惕若惊怖，宜服紫石英散方。  \n紫石英〔一（半）两细研，水飞过〕 防风（三分去芦头） 朱砂（一两细研如粉） 龙骨（一两） 人参〔二（三）分去芦头〕 细辛（三分） 甘草（半两炙微赤，锉） 羚羊角屑（三分） 远志（三分去心） 白鲜皮（一两） 白茯苓（二两半） 熟干地黄（一两） 铁精（二两细研如粉） 牛黄（一分细研）  \n上件药，捣筛为散", "白话": "治心脏风虚，惊悸失志，或嗔恚悲愁、志意不乐，惕惕然如惊怖的，宜服紫石英散方。（组成照录）：紫石英〔一（半）两细研，水飞过〕、防风（三分去芦头）、朱砂（一两细研如粉）、龙骨（一两）、人参〔二（三）分去芦头〕、细辛（三分）、甘草（半两炙微赤锉）、羚羊角屑（三分）、远志（三分去心）、白鲜皮（一两）、白茯苓（二两半）、熟干地黄（一两）、铁精（二两细研如粉）、牛黄（一分细研）。制法服法（照录）：上件药，捣筛为散，入研了药令匀。每服不计时候，煎枣汤调下一钱。方义：重镇安神、养心祛风。"}, {"source": "条257｜《太平圣惠方》·茯神散", "原文": "《太平圣惠方》卷四：治心风恍惚妄语，有所见闻，心悸，志意不定，宜服茯神散方。  \n茯神一两  人参一两，去芦头  赤小豆半两  菖蒲三分  龙骨角，一两  犀角屑一两  铁粉半两，研  金箔三十片，研  \n上件药，捣细罗为散，入研了药，令匀。每服不计时候，以金银汤放温，调下一钱。", "白话": "治心风恍惚妄语，有所见闻，心悸，志意不定，宜服茯神散方。（组成照录）：茯神一两、人参一两去芦头、赤小豆半两、菖蒲三分、龙骨角一两、犀角屑一两、铁粉半两研、金箔三十片研。制法服法（照录）：上件药，捣细罗为散，入研了药，令匀。每服不计时候，以金银汤放温，调下一钱。方义：清心镇惊、安神定志。"}, {"source": "条258｜《圣济总录》·茯神汤", "原文": "《圣济总录》卷一十九：治心痹神思昏塞，四肢不利，胸中烦闷，时复恐悸，茯神汤方。  \n茯神去木、羌活去芦头、龙齿、麦门冬去心，焙、麻黄去根节，各一两  蔓荆实、人参、薏苡仁、防风去叉、远志去心、犀角屑各三分  赤芍药、甘草微炙，各半两  \n上一十三味，粗捣筛。每服三钱匕，水一盏，生姜五片，同煎至七分，去滓温服，不计时候。", "白话": "治心痹神思昏塞，四肢不利，胸中烦闷，时时又觉恐悸，用茯神汤方。（组成照录）：茯神去木、羌活去芦头、龙齿、麦门冬去心焙、麻黄去根节各一两；蔓荆实、人参、薏苡仁、防风去叉、远志去心、犀角屑各三分；赤芍药、甘草微炙各半两。煎服（照录）：上一十三味，粗捣筛。每服三钱匕，水一盏，生姜五片，同煎至七分，去滓温服，不计时候。方义：祛风通痹、养心安神。"}, {"source": "条259｜《圣济总录》·茯神丸", "原文": "《圣济总录》卷四十三：治心脏虚热，惊悸心忪，虚乏气短，睡卧不安。茯神丸方。  \n茯神去木，二两  人参、麦门冬去心，焙、龙齿、防风去叉、云母粉各一两半  犀角镑、黄芩去黑心、薏苡仁各二两  \n上九味，捣罗为末，炼蜜丸如绿豆大。每服食后，米饮下十五丸，至二十丸。", "白话": "治心脏虚热，惊悸心忪，虚乏气短，睡卧不安，用茯神丸方。（组成照录）：茯神去木二两；人参、麦门冬去心焙、龙齿、防风去叉、云母粉各一两半；犀角镑、黄芩去黑心、薏苡仁各二两。制法服法（照录）：上九味，捣罗为末，炼蜜丸如绿豆大。每服食后，米饮下十五丸，至二十丸。方义：清心除虚热、镇心安神。"}, {"source": "条260｜《圣济总录》·镇心丸", "原文": "《圣济总录》卷四十三：治心虚惊悸，或因忧虑，神气不安，镇心丸方。  \n茯神去木、人参、甘草炙，锉、龙齿各一两半  升麻、枳壳去瓤，麸炒，各一两  \n银箔二百片  麦门冬去心，焙，二两  \n上八味，捣罗为末，炼蜜和丸，如梧桐子大。每服十五丸至二十丸，米饮下，早晚食后服。", "白话": "治心虚惊悸，或因忧虑，神气不安，用镇心丸方。（组成照录）：茯神去木、人参、甘草炙锉、龙齿各一两半；升麻、枳壳去瓤麸炒各一两；银箔二百片；麦门冬去心焙二两。制法服法（照录）：上八味，捣罗为末，炼蜜和丸，如梧桐子大。每服十五丸至二十丸，米饮下，早晚食后服。方义：益气养心、镇心安神。"}, {"source": "条261｜《圣济总录》·檀香丸", "原文": "《圣济总录》卷四十三：治心常忪悸，恐惧多忘，檀香丸方。  \n檀香三两  菖蒲、犀角镑、天竺黄研、生干地黄焙、苏合香油各一两  桂去粗皮、 甘草炙、白茯苓去黑皮，各三两半  人参、远志去心、麦门冬去心，各一两半  \n上一十二味，除苏合香油外，为末，以苏合香油同少酒，化入炼蜜，丸如樱桃大。食后含化一丸。", "白话": "治心常忪悸、恐惧多忘，用檀香丸方。（组成照录）：檀香三两；菖蒲、犀角镑、天竺黄研、生干地黄焙、苏合香油各一两；桂去粗皮、甘草炙、白茯苓去黑皮各三两半；人参、远志去心、麦门冬去心各一两半。制法服法（照录）：上一十二味，除苏合香油外，为末，以苏合香油同少酒，化入炼蜜，丸如樱桃大。食后含化一丸。方义：芳香开窍、养心安神定悸。"}, {"source": "条262｜《太平惠民和剂局方》·平补镇心丹", "原文": "《太平惠民和剂局方》卷五：平补镇心丹。治丈夫、妇人心气不足，志意不定，神情恍惚，夜多异梦，忪悸烦郁，及肾气伤败，血少气多，四肢倦怠，足胫酸疼，睡卧不隐，梦寐遗精，时有白浊，渐至羸瘦。  \n酸枣仁去皮、隔纸炒，二钱半  车前子去土，碾破、白茯苓去皮、五味子去枝、梗、肉桂去粗皮，不见火、麦门冬去心、茯神去皮，各一两二钱半  天门冬去心、龙齿、熟地黄洗，酒蒸、山药姜汁制，各一两半  人参去芦，半两  朱", "白话": "平补镇心丹。治丈夫、妇人心气不足，志意不定，神情恍惚，夜多异梦，忪悸烦郁，以及肾气伤败、血少气多，四肢倦怠，足胫酸疼，睡卧不实，梦寐遗精，时有白浊，渐至羸瘦。（组成照录）：酸枣仁去皮隔纸炒二钱半；车前子去土碾破、白茯苓去皮、五味子去枝梗、肉桂去粗皮不见火、麦门冬去心、茯神去皮各一两二钱半；天门冬去心、龙齿、熟地黄洗酒蒸、山药姜汁制各一两半；人参去芦半两；朱砂细研为衣半两；远志去心、甘草炙一两半。制法服法（照录）：上为末，炼蜜丸，如梧桐子大。每服三十丸，空心，饭饮下，温酒亦得，"}, {"source": "条263｜《太平惠民和剂局方》·宁志膏", "原文": "《太平惠民和剂局方》卷五：宁志膏。治心脏亏虚，神志不守，恐怖惊惕，常多恍惚，易于健忘，睡卧不宁，梦涉危险，一切心疾，并皆治之。  \n酸枣仁微炒，去皮、人参各一两  辰砂研细，水飞，半两  乳香以乳钵坐水盆中研，一分  \n上四味研和停，炼蜜丸，如弹子大。每服一粒，温酒化下，枣汤亦得，空心 临卧服。", "白话": "宁志膏。治心脏亏虚，神志不守，恐怖惊惕，常多恍惚，容易健忘，睡卧不宁，梦涉危险——一切心疾，并皆治之。（组成照录）：酸枣仁微炒去皮、人参各一两；辰砂研细水飞半两；乳香（以乳钵坐水盆中研）一分。制法服法（照录）：上四味研和停，炼蜜丸，如弹子大。每服一粒，温酒化下，枣汤亦得，空心临卧服。方义：养心安神、活血定志。"}, {"source": "条264｜《太平惠民和剂局方》·定志丸", "原文": "《太平惠民和剂局方》卷五：定志丸。治心气不定，五脏不足，恍惚振悸，忧愁悲伤，差错谬忘，梦寐惊魇，恐怖不宁，喜怒无时，朝瘥暮剧，暮瘥朝剧，或发狂眩，并宜服之。  \n远志去苗及心、菖蒲各二两  人参、白茯苓去皮，各三两  \n上为细末，炼蜜丸，如梧桐子大，朱砂为衣。每服七丸，加至二十丸，温米饮下，食后，临卧，日三服。常服益心强志，令人不忘。", "白话": "定志丸。治心气不定，五脏不足，恍惚振悸，忧愁悲伤，差错健忘，梦寐惊魇，恐怖不宁，喜怒无时，朝瘥暮剧、暮瘥朝剧，或发狂眩，都宜服之。（组成照录）：远志去苗及心、菖蒲各二两；人参、白茯苓去皮各三两。制法服法（照录）：上为细末，炼蜜丸，如梧桐子大，朱砂为衣。每服七丸，加至二十丸，温米饮下，食后、临卧，日三服。常服益心强志，令人不忘。方义：补心气、开心窍、强志安神。"}, {"source": "条265｜《太平惠民和剂局方》·十四友丸", "原文": "《太平惠民和剂局方》卷五：十四友丸。补心肾虚，怔忪昏愦，神志不宁，睡卧不安。故《经》曰：脏有所伤，情有所倚，人不能知其病，则卧不安。  \n熟地黄、白茯苓、白茯神去木、人参、酸枣仁炒、柏子仁别研、紫石英别研、肉桂、阿胶蛤粉炒、当归、黄芪、远志汤浸，去心，酒洒、蒸，各一两  辰砂别研，一分  龙齿别研，二两  \n上为末，同别研四味，炼蜜为丸，如梧桐子大。每服三十丸，食后枣汤下。", "白话": "十四友丸。补心肾之虚，治怔忪昏愦，神志不宁，睡卧不安。所以《经》说：脏有所伤，情有所倚，人不能知其病，则卧不安。（组成照录）：熟地黄、白茯苓、白茯神去木、人参、酸枣仁炒、柏子仁别研、紫石英别研、肉桂、阿胶蛤粉炒、当归、黄芪、远志（汤浸去心，酒洒蒸）各一两；辰砂别研一分；龙齿别研二两。制法服法（照录）：上为末，同别研四味，炼蜜为丸，如梧桐子大。每服三十丸，食后枣汤下。方义：补心肾、养气血、镇心安神。"}, {"source": "条266｜《杨氏家藏方》·定志丸", "原文": "《杨氏家藏方》卷第十：定志丸。治怔忪健忘，精神恍惚，睡卧不宁，一切心疾。  \n人参去芦头、白茯苓去皮、石菖蒲、远志去心、龙齿、酸枣仁微炒、铁粉别研麦门冬去心，焙干、朱砂飞过、乳香别研、麝香别研、琥珀别研  \n上件各等分为细末，次入朱砂、铁粉同研匀，绞生地黄汁，浸蒸饼为丸如梧桐子大，别用朱砂为衣。每服二十丸，温熟水送下，食后、临卧。", "白话": "定志丸。治怔忪健忘，精神恍惚，睡卧不宁，一切心疾。（组成照录）：人参去芦头、白茯苓去皮、石菖蒲、远志去心、龙齿、酸枣仁微炒、铁粉别研、麦门冬去心焙干、朱砂飞过、乳香别研、麝香别研、琥珀别研（以上各等分）。制法服法（照录）：上件各等分为细末，次入朱砂、铁粉同研匀，绞生地黄汁，浸蒸饼为丸如梧桐子大，别用朱砂为衣。每服二十丸，温熟水送下，食后、临卧。方义：益气安神、镇心开窍。"}, {"source": "条267｜《杨氏家藏方》·百枝膏", "原文": "《杨氏家藏方》卷十七：百枝膏。治小儿禀赋怯弱，易感惊邪，心神恍惚，眠睡不安。常服安心神，压惊悸。  \n人参去芦头、防风去芦头、天麻三味各一两  麦门冬汤浸去心，焙干称、白附子炮、 白僵蚕炒去丝嘴、羌活去芦头、石菖蒲、五味各半两  朱砂二钱，别研  麝香一钱，别研", "白话": "百枝膏。治小儿禀赋怯弱，易感惊邪，心神恍惚，眠睡不安。常服安心神，压惊悸。（组成照录）：人参去芦头、防风去芦头、天麻三味各一两；麦门冬汤浸去心焙干称、白附子炮、白僵蚕炒去丝嘴、羌活去芦头、石菖蒲、五味各半两；朱砂二钱别研；麝香一钱别研。（原稿未出制法服法，照录待核）方义：扶正祛风、镇惊安神，小儿常服之方。"}, {"source": "条268｜《叶氏录验方》·辰砂茯神散", "原文": "《叶氏录验方》中卷：辰砂茯神散。治心间有气，邪热在内，精神恍惚，忘误怔忪，眠睡不稳，五心烦热，饮食不美，肢体昏倦。  \n辰砂半两，细研如粉  人参半两  茯神半两，去黑皮秤  白僵蚕一两，洗炒  远志一分，去心秤  犀角屑一分  牙硝一分，别研细  甘草一分，炙微赤  \n上件为细末，每服二钱，用薄荷煎汤调下，食后，临卧，日三服。  \n上件为细末，次入朱砂、麝香研匀，炼蜜为丸，每一两作四十丸。每服一", "白话": "辰砂茯神散。治心间有气，邪热在内，精神恍惚，忘误怔忪，眠睡不稳，五心烦热，饮食不美，肢体昏倦。（组成照录）：辰砂半两细研如粉、人参半两、茯神半两去黑皮秤、白僵蚕一两洗炒、远志一分去心秤、犀角屑一分、牙硝一分别研细、甘草一分炙微赤。制法服法（照录）：上件为细末，每服二钱，用薄荷煎汤调下，食后、临卧，日三服。上件为细末，次入朱砂、麝香研匀，炼蜜为丸，每一两作四十丸。每服一丸，温荆芥汤化下，食后，临卧。（后段疑为他方制法误入，原稿照录，待核）方义：清心化痰、镇惊安神。"}, {"source": "条269｜《叶氏录验方》·七宝丹", "原文": "《叶氏录验方》中卷：七宝丹。大镇心，养真血，安神魄。治血虚气结，惊悸不宁。  \n当归一两，洗焙  芎半两，洗  桂心半两，去皮  石菖蒲半两，去毛  茯神一两  远志肉半两，汤泡姜汁浸炒  人参一两，去须  柏子仁半两，研  酸枣仁半两，去皮净，微炒，以上修事为末  琥珀半两  真血竭半两  没药半两  朱砂一两  麝香肉一钱，以上细研  \n上为末，炼蜜和熟枣肉熬成膏，和药为丸，如梧桐子大。每服", "白话": "七宝丹。大镇心，养真血，安神魄。治血虚气结，惊悸不宁。（组成照录）：当归一两洗焙、芎半两洗、桂心半两去皮、石菖蒲半两去毛、茯神一两、远志肉半两汤泡姜汁浸炒、人参一两去须、柏子仁半两研、酸枣仁半两去皮净微炒（以上修事为末）；琥珀半两、真血竭半两、没药半两、朱砂一两、麝香肉一钱（以上细研）。制法服法（照录）：上为末，炼蜜和熟枣肉熬成膏，和药为丸，如梧桐子大。每服五六十丸。枣汤下，不拘时候。方义：养血行气、镇心安神。"}, {"source": "条270｜《叶氏录验方》·龙齿汤", "原文": "《叶氏录验方》中卷：龙齿汤。治心怔惊悸，常怀忧虑，神思昏昧，如人将捕状，小便赤少，或多，或浊，宜服李尧卿传。  \n人参去芦头、甘草炙、枳壳去瓤，麸炒、龙齿研、北桔梗以上各一两半  半夏二两，汤泡七次  黄芪炙  茯神一两  白茯苓一两半  远志去心，一两半  当归一两半  官桂二两半  \n上为末，每服三钱。水一盏半，生姜三片，枣子一个，粳米百粒，同煎七分，食前服。", "白话": "龙齿汤。治心怔惊悸，常怀忧虑，神思昏昧，如人将捕之状，小便赤少、或多、或浊，宜服（李尧卿传）。（组成照录）：人参去芦头、甘草炙、枳壳去瓤麸炒、龙齿研、北桔梗以上各一两半；半夏二两汤泡七次；黄芪炙、茯神一两、白茯苓一两半、远志去心一两半、当归一两半、官桂二两半。制法服法（照录）：上为末，每服三钱。水一盏半，生姜三片，枣子一个，粳米百粒，同煎七分，食前服。方义：益气养心、镇惊定悸。"}, {"source": "条271｜《叶氏录验方》·育神散", "原文": "《叶氏录验方》中卷：育神散。治心气不宁，二三十年不可者皆治，或虚弱多惊，神色昏愦，怔忪健忘，或言语无节，有类颠邪，或心志不定，小便白浊，饮食无味。  \n白茯苓、茯神白者、人参去须、远志去心，焙干秤、龙骨令研如粉，临时和入、赤石脂令研如粉，临时和入、干姜炮、当归净洗、白术切、红芍药、桂心去粗皮，不见火，临时入、紫菀茸净洗、防风、甘草炙，各等分  川乌炮，去皮脐，各半  没药一分  乳香一分 安息香一", "白话": "育神散。治心气不宁，二三十年不愈的都治；或虚弱多惊，神色昏愦，怔忪健忘；或言语无节，有类癫邪；或心志不定，小便白浊，饮食无味。（组成照录）：白茯苓、茯神白者、人参去须、远志去心焙干秤、龙骨（令研如粉，临时和入）、赤石脂（令研如粉，临时和入）、干姜炮、当归净洗、白术切、红芍药、桂心去粗皮不见火临时入、紫菀茸净洗、防风、甘草炙各等分；川乌炮去皮脐各半；没药一分、乳香一分、安息香一分、麝香一钱研。制法服法（照录）：上为细末，相和令匀，将安息香用无灰酒熬成膏，搜为丸，如龙眼大，用辰砂"}, {"source": "条272｜《叶氏录验方》·琥珀安神丸", "原文": "《叶氏录验方》中卷：琥珀安神丸。治心气不和，肢体麻痹，心忪惊愦，饮食无味，或耳内虚鸣，常服镇心安神。  \n木香 琥珀不见火，别研  人参  五灵脂拣净  沉香二钱半  \n上为细末，肉枣灯心煮去皮，取肉为丸，如梧桐子大。每服四十粒至五十粒，枣汤吞下，空心，日午服。", "白话": "琥珀安神丸。治心气不和，肢体麻痹，心忪惊愦，饮食无味，或耳内虚鸣；常服镇心安神。（组成照录）：木香、琥珀（不见火，别研）、人参、五灵脂拣净、沉香二钱半。制法服法（照录）：上为细末，肉枣灯心煮去皮，取肉为丸，如梧桐子大。每服四十粒至五十粒，枣汤吞下，空心，日午服。方义：行气活血、镇心安神。"}, {"source": "条273｜《活人事证方后集》·枣仁圆", "原文": "《活人事证方后集》卷二：枣仁圆。治心气不足，恍惚健忘，睡卧不宁，梦寐危奁，心忪如人捕。张承节累用有效。  \n酸枣仁炒，去皮  黑豆炒，去皮  \n上等分为细末，炼蜜为丸，如梧桐子大，朱砂少许为衣，每服三十圆。日午、临卧，熟水或人参汤送下。", "白话": "枣仁圆。治心气不足，恍惚健忘，睡卧不宁，梦寐危殆，心忪如有人捕捉。张承节屡用有效。（组成照录）：酸枣仁炒去皮、黑豆炒去皮。制法服法（照录）：上等分为细末，炼蜜为丸，如梧桐子大，朱砂少许为衣，每服三十圆。日午、临卧，熟水或人参汤送下。方义：养心安神，药简力专。"}, {"source": "条274｜《妇人大全良方》·无名方", "原文": "《妇人大全良方》卷十九：《经效》疗产后心虚忪悸，志意不定，烦躁恍惚。  \n茯神、当归、黄芩、麦门冬去心、甘草、人参、芍药、酸枣仁、白鲜皮各三两  大枣七个  \n上为粗末，水二升，煮取七合，去滓温服。", "白话": "《经效》疗产后心虚忪悸，志意不定，烦躁恍惚。（组成照录）：茯神、当归、黄芩、麦门冬去心、甘草、人参、芍药、酸枣仁、白鲜皮各三两，大枣七个。煎服（照录）：上为粗末，水二升，煮取七合，去滓温服。方义：养心安神、清热除烦，产后心虚兼热者宜之。"}, {"source": "条275｜《校注妇人良方》·酸枣仁丸", "原文": "《校注妇人良方》卷三：酸枣仁丸。治胆气实热，不得睡卧，神思不安，惊悸怔忡。  \n茯神去木、酸枣仁炒、远志去心、柏子仁炒、防风各一两  枳壳麸炒，半两  生地黄杵膏，半两  青竹茹二钱五分  \n上为末，炼蜜丸桐子大。每服七八十丸，滚汤下。", "白话": "酸枣仁丸。治胆气实热，不得睡卧，神思不安，惊悸怔忡。（组成照录）：茯神去木、酸枣仁炒、远志去心、柏子仁炒、防风各一两；枳壳麸炒半两；生地黄杵膏半两；青竹茹二钱五分。制法服法（照录）：上为末，炼蜜丸桐子大。每服七八十丸，滚汤下。方义：清胆热、养心安神。"}, {"source": "条276｜《校注妇人良方》·平补镇心丹", "原文": "《校注妇人良方》卷二十四：平补镇心丹。治心血不足，时或心忡惊悸，梦如高坠，常服安心肾，益荣卫。  \n朱砂细研，半两，为衣  人参五钱  龙齿一两五钱  白茯苓、五味子炒、车前子炒、茯神、麦门冬去心，杵膏、肉桂各一两二钱半  远志去心，甘草制、天门冬去心，杵膏、山药制，各一两五钱  酸枣仁去皮尖，二钱半  熟地黄酒蒸，五钱，杵膏  \n上为末，蜜丸桐子大。每服三十丸，空心温酒下。", "白话": "平补镇心丹。治心血不足，时或心忡惊悸，梦如从高坠下；常服安心肾、益营卫。（组成照录）：朱砂细研半两为衣；人参五钱；龙齿一两五钱；白茯苓、五味子炒、车前子炒、茯神、麦门冬去心杵膏、肉桂各一两二钱半；远志去心甘草制、天门冬去心杵膏、山药制各一两五钱；酸枣仁去皮尖二钱半；熟地黄酒蒸五钱杵膏。制法服法（照录）：上为末，蜜丸桐子大。每服三十丸，空心温酒下。方义：平补心肾、养血安神。"}, {"source": "条277｜《严氏济生方·惊悸怔忡健忘门》·排风汤", "原文": "《严氏济生方·惊悸怔忡健忘门》：排风汤。治风虚冷湿闭塞诸经，令人怔忡，宜加炒酸枣仁煎。", "白话": "排风汤。治风虚冷湿闭塞诸经，令人怔忡，宜加炒酸枣仁煎服。方义：祛风散寒胜湿，经络通畅则怔忡止。"}, {"source": "条278｜《仁斋直指方论（附补遗）》·加味定志丸", "原文": "《仁斋直指方论（附补遗）》卷十一：加味定志丸。治痰迷心膈，惊悸怔忡。  \n远志去心，二两  人参一两  菖蒲二两  白茯苓三两  琥珀、郁金各五钱  \n上为细末，炼蜜丸如梧子大，朱砂为衣，每服二十丸，米汤下。", "白话": "加味定志丸。治痰迷心膈，惊悸怔忡。（组成照录）：远志去心二两、人参一两、菖蒲二两、白茯苓三两、琥珀、郁金各五钱。制法服法（照录）：上为细末，炼蜜丸如梧子大，朱砂为衣，每服二十丸，米汤下。方义：化痰开窍、安神定志。"}, {"source": "条279｜《仁斋直指方论（附补遗）》·朱雀丸", "原文": "《仁斋直指方论（附补遗）》卷十一：朱雀丸。治心病怔忪不止。  \n白茯神二两，净  沉香半两  \n上细末，炼蜜丸小豆大。每三十丸，人参煎汤下。", "白话": "朱雀丸。治心病怔忪不止。（组成照录）：白茯神二两净、沉香半两。制法服法（照录）：上细末，炼蜜丸小豆大。每三十丸，人参煎汤下。方义：宁心安神、下气定怔。"}, {"source": "条280｜《郑氏家传女科万金方·产后门》·平补镇心丸", "原文": "《郑氏家传女科万金方·产后门》：产后惊悸，精神恍惚，夜卧不宁，此症心血少故也，宜服平补镇心丸主之，或加味温胆汤。平补镇心丸：  \n茯神 五味 车前子 远志 麦冬 姜制 山药 官桂 天冬 熟地 人参 龙齿 枣仁  \n朱砂为衣，蜜丸。空心服。  \n加味温胆汤：枣仁 远志 茯神 人参 熟地 五味 煎服。", "白话": "产后惊悸，精神恍惚，夜卧不宁——此症是心血少的缘故——宜服平补镇心丸主治，或用加味温胆汤。平补镇心丸（组成照录）：茯神、五味、车前子、远志、麦冬、姜制山药、官桂、天冬、熟地、人参、龙齿、枣仁；朱砂为衣，蜜丸。空心服。加味温胆汤（组成照录）：枣仁、远志、茯神、人参、熟地、五味，煎服。方义：补养心血、镇心安神。"}, {"source": "条281｜《御药院方》·镇心丸", "原文": "《御药院方》卷六：镇心丸。治心气不足，志意不定，精神恍惚，语言错妄，忪悸烦乱，愁忧惨戚，喜惊多恐，健忘少睡，夜多异梦，寤即惊魇，或发狂眩暴不知人，并宜服之。  \n预知子去皮、人参去芦头、白茯苓去皮、远志去心、石菖蒲、山药、枸杞子拣净、黄精蒸熟、柏子仁、地骨皮去土、茯神去木、朱砂飞研，各等分  \n上件为细末。炼蜜为丸，每两作二十丸，更以朱砂为衣。每服丸，细嚼，人参汤下，不计时候。", "白话": "镇心丸。治心气不足，志意不定，精神恍惚，语言错妄，忪悸烦乱，愁忧惨戚，喜惊多恐，健忘少睡，夜多异梦，醒即惊魇，或发狂眩暴不知人，都宜服之。（组成照录）：预知子去皮、人参去芦头、白茯苓去皮、远志去心、石菖蒲、山药、枸杞子拣净、黄精蒸熟、柏子仁、地骨皮去土、茯神去木、朱砂飞研各等分。制法服法（照录）：上件为细末。炼蜜为丸，每两作二十丸，更以朱砂为衣。每服一丸，细嚼，人参汤下，不计时候。（原稿“每服丸”脱“一”字，照录待核）方义：补心气、镇心神、定惊悸。"}, {"source": "条282｜《御药院方》·人参远志丸", "原文": "《御药院方》卷六：人参远志丸。治心气不安，惊悸恍惚，神思不宁。  \n人参去芦 远志去心，半钱 黄芪半两 酸枣仁半两 桂二钱半 桔梗炒黄，二钱半 丹砂二钱半 天门冬七钱半 菖蒲七钱 白茯苓去皮，七钱半  \n上为细末，蜜为丸，如豆大。每服二十丸，米饮下，加至三十丸，下不拘时候。", "白话": "人参远志丸。治心气不安，惊悸恍惚，神思不宁。（组成照录）：人参去芦、远志去心半钱、黄芪半两、酸枣仁半两、桂二钱半、桔梗炒黄二钱半、丹砂二钱半、天门冬七钱半、菖蒲七钱、白茯苓去皮七钱半。制法服法（照录）：上为细末，蜜为丸，如豆大。每服二十丸，米饮下，加至三十丸，不拘时候。方义：益气养心、安神定志。"}, {"source": "条283｜《御药院方·卷六》·牛黄铁粉丸", "原文": "《御药院方·卷六》：牛黄铁粉丸。镇定心气，止惊悸不宁。  \n牛黄研，二钱半、铁粉研、紫石英研、白石英研、酸枣仁炒、茯神去木、陈皮去白、人参去芦头，各一两  \n上为细末。入研者匀，白面糊和丸，如梧桐子大。每服五十丸，煎人参汤下，食前服。", "白话": "牛黄铁粉丸。镇定心气，止惊悸不宁。（组成照录）：牛黄研二钱半；铁粉研、紫石英研、白石英研、酸枣仁炒、茯神去木、陈皮去白、人参去芦头各一两。制法服法（照录）：上为细末。入研者匀，白面糊和丸，如梧桐子大。每服五十丸，煎人参汤下，食前服。方义：重镇安神、益气养心。"}, {"source": "条284｜《御药院方》·大镇心丸", "原文": "《御药院方》卷十一：大镇心丸。治小儿精神不爽，寝寐多惊，心忪恐悸，四肢战掉，举动欲倒，状类暗风，或烦躁而多啼。退惊风，化痰涎，壮心气，益精神。  \n生犀角镑，末、铁粉研，各一两 羚羊角镑，末、龟甲镑，末、赤箭各半两 牛黄研、茯神去木、远志去心、真珠末研、人参、桂去粗皮、蛇蜕皮炙，令焦黄、天竺黄研、龙脑各一分，研 麝香研、菖蒲各半两 丹砂研，半分 金箔研、银铂研，各五十片  \n上一十九味捣研为末，炼", "白话": "大镇心丸。治小儿精神不爽，睡中多惊，心忪恐悸，四肢战掉，举动欲倒，状类暗风；或烦躁而多啼。能退惊风、化痰涎、壮心气、益精神。（组成照录）：生犀角镑末、铁粉研各一两；羚羊角镑末、龟甲镑末、赤箭各半两；牛黄研、茯神去木、远志去心、真珠末研、人参、桂去粗皮、蛇蜕皮炙令焦黄、天竺黄研、龙脑各一分研、麝香研、菖蒲各半两；丹砂研半分；金箔研、银铂研各五十片。制法服法（照录）：上一十九味捣研为末，炼蜜和丸，如梧桐子大。每服一丸至二丸，食后临卧，薄荷汤化下，更量大小加减。方义：镇惊化痰、开窍"}, {"source": "条285｜《御药院方》·丹砂镇心丸", "原文": "《御药院方》卷十一：丹砂镇心丸。治小儿心神不宁，有时惊悸、目睛偏视、痰涎不利，甚则瘛疭。服之安镇心神，罢惊止搐。  \n朱砂一两，飞研 牛黄一钱 生龙脑、麝香各一钱 铅白霜二钱 天竺黄二钱，以上各细研 天麻明大者，二两 人参半两 茯苓半两，白者，去黑皮 甘草炙，半两  \n上一十味为细末，与研药同研匀细，炼蜜和丸，如鸡头实大。每服一丸，煎金银薄荷汤化下。", "白话": "丹砂镇心丸。治小儿心神不宁，有时惊悸、目睛偏视、痰涎不利，甚则瘛疭。服之安镇心神，罢惊止搐。（组成照录）：朱砂一两飞研、牛黄一钱、生龙脑、麝香各一钱、铅白霜二钱、天竺黄二钱（以上各细研）；天麻明大者二两、人参半两、茯苓半两白者去黑皮、甘草炙半两。制法服法（照录）：上一十味为细末，与研药同研匀细，炼蜜和丸，如鸡头实大。每服一丸，煎金银薄荷汤化下。方义：镇惊息风、化痰止搐。"}, {"source": "条286｜《世医得效方》·小定志丸", "原文": "《世医得效方》卷九：小定志丸。治心气不定，五脏不足，甚者忧忧愁愁不乐，忽忽喜忘，朝瘥暮剧，暮瘥朝发。及因事有所大惊，梦寐不祥，登高履险，致神魂不安，惊悸恐怯。  \n菖蒲炒、远志去心，姜汁淹，各二两 茯苓、茯神 、参各三两 辰砂一两，为衣  \n上为末，炼蜜丸如梧桐子大。每服五十丸，米汤下。一方，去茯神，名开心散。每服二钱匕，不以时服。", "白话": "小定志丸。治心气不定，五脏不足，甚者忧忧愁愁不乐、忽忽善忘，朝瘥暮剧、暮瘥朝发；以及因事有所大惊，梦寐不祥，登高履险，致神魂不安，惊悸恐怯。（组成照录）：菖蒲炒、远志去心姜汁淹各二两；茯苓、茯神、参各三两；辰砂一两为衣。制法服法（照录）：上为末，炼蜜丸如梧桐子大。每服五十丸，米汤下。一方，去茯神，名开心散。每服二钱匕，不以时服。方义：补心定志、镇心安神。"}, {"source": "条287｜《脉因证治》·朱砂安神丸", "原文": "《脉因证治》卷二：朱砂安神丸。治心神烦乱怔忡，兀兀欲吐，胸中气乱而热，似懊憹状，皆是膈上血中伏火。  \n朱砂一钱，研 黄连一钱半，酒制 炙甘草五分 生地五钱 当归半钱  \n饼丸，津下。如心痞，食入反出，加煨大黄，除地黄。", "白话": "朱砂安神丸。治心神烦乱怔忡，兀兀欲吐，胸中气乱而热，像懊憹的样子——都是膈上血中伏火。（组成照录）：朱砂一钱研、黄连一钱半酒制、炙甘草五分、生地五钱、当归半钱。制法服法（照录）：饼丸，津下。如心痞，食入反出，加煨大黄，除地黄。方义：清心降火、养血安神，治血中伏火之怔忡。"}, {"source": "条288｜《医学纲目》·辰砂安神丸", "原文": "《医学纲目》卷四：治心烦欲吐，怔忪不安卧，以辰砂安神丸，如米大，津液下十余丸，此近而奇偶，制小其服也（心肺在上为近。剂小者，不令下行故也）。", "白话": "治心烦欲吐、怔忪不安卧的，用辰砂安神丸，如米大，以津液送下十余丸——这是“近而奇偶，制小其服”（心肺在上为近，剂小者，不令下行的缘故）。（原稿未出组成，照录待核）方义：清心安神，小剂缓图。"}, {"source": "条289｜《医学纲目》·镇心丹", "原文": "《医学纲目》卷二十五：镇心丹。治惊悸自汗，心烦短气，喜怒悲恶，悉不自知，忘魂失魄，状若神灵所凭，及男子遗泄，女子带下。  \n辰砂研、白矾煅汁尽，各等分  \n上为末，水丸如鸡头大。每服一丸，煎人参汤下，食后服。", "白话": "镇心丹。治惊悸自汗，心烦短气，喜怒悲忧自己不能控制，忘魂失魄，状若神灵所凭；以及男子遗泄、女子带下。（组成照录）：辰砂研、白矾煅汁尽各等分。制法服法（照录）：上为末，水丸如鸡头大。每服一丸，煎人参汤下，食后服。方义：重镇安神、化痰定志。"}, {"source": "条290｜《普济方》·惊气丸", "原文": "《普济方》卷十六：惊气丸出《卫生家宝方》。治忧愁思虑，喜怒不常，或因惊怕而伤心，或因思虑而神损，或心忪恍惚，或手足不仁，身热自汗，腰背引痛，嗜卧少力，举动多惊，饮食无味，及治产后中风、一切惊病。", "白话": "惊气丸，出自《卫生家宝方》。治忧愁思虑、喜怒不常，或因惊怕而伤心，或因思虑而神损，或心忪恍惚，或手足不仁，身热自汗，腰背引痛，嗜卧少力，举动多惊，饮食无味；并治产后中风、一切惊病。（原稿未出组成，照录待核）方义：养心安神、调畅情志。"}, {"source": "条291｜《普济方》·救命丹", "原文": "《普济方》卷十六：救命丹出《卫生家宝方》。治心虚气短，神志不宁，或多惊悸，语言颠错。  \n辰砂一两，有墙壁者细研 獖猪血四两  \n上用水一斗，同置于银石器中，用炭火煮至一升，放冷，别用清水荡去猪血令净，渗朱砂干，以桃胶丸如麻子大，每服十丸，用去心麦门冬煎汤，下四五丸，服立效。", "白话": "救命丹，出自《卫生家宝方》。治心虚气短，神志不宁，或多惊悸，语言颠错。（组成照录）：辰砂一两（有墙壁者细研）、獖猪血四两。制法服法（照录）：上用水一斗，同置于银石器中，用炭火煮至一升，放冷，别用清水荡去猪血令净，渗朱砂干，以桃胶丸如麻子大，每服十丸，用去心麦门冬煎汤下四五丸，服立效。（“每服十丸”与“下四五丸”原稿并存，照录待核）方义：以血肉有情之品佐朱砂镇心安神。"}, {"source": "条292｜《普济方》·宁心丹", "原文": "《普济方》卷十八：宁心丹出《卫生家宝方《》。治思虑悲忧伤心，惊悸怔忪，睡卧不宁。  \n人参一两 茯神一两 朱砂细研、乳香细研、白附子微炮，各半两 雄黄一分 紫石英一分 真朱末一分，细研 桃奴一分 脑子半钱，细研 麝香一钱，细研 金箔五十片，研入药  \n上为末，酒煮半夏糊为丸，如鸡头大。别以金箔为衣，每服一丸，先用灯心汤浸，至睡时，磨化，暖水温服。小儿半丸。", "白话": "宁心丹，出自《卫生家宝方》。治思虑悲忧伤心，惊悸怔忪，睡卧不宁。（组成照录）：人参一两、茯神一两；朱砂细研、乳香细研、白附子微炮各半两；雄黄一分、紫石英一分、真朱末一分细研、桃奴一分、脑子半钱细研、麝香一钱细研、金箔五十片研入药。制法服法（照录）：上为末，酒煮半夏糊为丸，如鸡头大。别以金箔为衣，每服一丸，先用灯心汤浸，至睡时，磨化，暖水温服。小儿半丸。方义：益气养心、镇惊安神、开窍定悸。"}, {"source": "条293｜《普济方》·定心丸", "原文": "《普济方》卷一百二：方定心丸。治心虚忧悲不乐，惊悸心忪，恍惚忘误，神情不宁。  \n茯苓去黑皮、茯神去木，各一两 琥珀另研、龙齿、阿胶炙令燥、牛黄锉研、珍珠别研、犀角镑、龙脑别研、麝香别研，各半两 天南星牛胆内匮者、甘草炙锉，各一两半 远志去心，一分 金箔三十片，为衣 银箔三十片，研入药 菖蒲、酸枣仁炒、天竺黄别研、人参各三分 丹砂别研，四两 龙胆半分 雄黄别研，二两 苏合香二两 安息香二两，同苏合", "白话": "定心丸。治心虚忧悲不乐，惊悸心忪，恍惚忘误，神情不宁。（组成照录）：茯苓去黑皮、茯神去木各一两；琥珀另研、龙齿、阿胶炙令燥、牛黄锉研、珍珠别研、犀角镑、龙脑别研、麝香别研各半两；天南星牛胆内匮者、甘草炙锉各一两半；远志去心一分；金箔三十片为衣、银箔三十片研入药；菖蒲、酸枣仁炒、天竺黄别研、人参各三分；丹砂别研四两；龙胆半分；雄黄别研二两；苏合香二两、安息香二两（同苏合香以酒一大盏研化澄去砂脚，熬成膏）。制法服法（照录）：上除别研外，捣罗为末，和匀，以安息香膏同炼蜜为丸，如鸡头"}, {"source": "条294｜《奇效良方》·茯神散", "原文": "《奇效良方》卷三：茯神散。治诸风恍惚，心神烦乱，志意不安，或卧惊恐。  \n茯神一两 石膏研、龙齿各二两 麦门冬去心，一两半 黄芪一两 甘草半两，炙 石菖蒲、人参去芦，各一两 防风三分 远志半两，去心 熟干地黄、羚羊角屑各一两  \n上㕮咀，每服四钱，以水一中盏，入生姜半分，枣三枚，煎至六分，去滓，不拘时候温服。", "白话": "茯神散。治诸风恍惚，心神烦乱，志意不安，或卧而惊恐。（组成照录）：茯神一两、石膏研、龙齿各二两、麦门冬去心一两半、黄芪一两、甘草半两炙、石菖蒲、人参去芦各一两、防风三分、远志半两去心、熟干地黄、羚羊角屑各一两。煎服（照录）：上㕮咀，每服四钱，以水一中盏，入生姜半分，枣三枚，煎至六分，去滓，不拘时候温服。方义：祛风清热、镇心安神。"}, {"source": "条295｜《奇效良方》·人参远志丸", "原文": "《奇效良方》卷四十六：人参远志丸。治心气不安，惊悸恍惚，神思不宁。  \n人参去芦、远志去心、酸枣仁、黄芪以上各半两 桔梗去芦、官桂去皮、丹砂以上各二钱半 天门冬去心、白茯苓去皮、菖蒲各七钱半  \n上为细末，炼蜜为丸，如梧桐子大，每服三十丸，食远用米汤送下。", "白话": "人参远志丸。治心气不安，惊悸恍惚，神思不宁。（组成照录）：人参去芦、远志去心、酸枣仁、黄芪以上各半两；桔梗去芦、官桂去皮、丹砂以上各二钱半；天门冬去心、白茯苓去皮、菖蒲各七钱半。制法服法（照录）：上为细末，炼蜜为丸，如梧桐子大，每服三十丸，食远用米汤送下。方义：益气养心、安神定志。"}, {"source": "条296｜《奇效良方》·远志丸", "原文": "《奇效良方》卷四十六：远志丸。治因事有所大惊，梦寐不祥，登高涉险，神魂不安，惊悸恐怯。  \n远志去心，姜汁制、石菖蒲各二两 茯神去皮木、白茯苓去皮、参去芦、龙齿各一两  \n上为细末，炼蜜和丸，如梧桐子大，朱砂为衣，每服七十丸，用白汤送下，食后临卧服。", "白话": "远志丸。治因事有所大惊，梦寐不祥，登高涉险，神魂不安，惊悸恐怯。（组成照录）：远志去心姜汁制、石菖蒲各二两；茯神去皮木、白茯苓去皮、参去芦、龙齿各一两。制法服法（照录）：上为细末，炼蜜和丸，如梧桐子大，朱砂为衣，每服七十丸，用白汤送下，食后临卧服。方义：安神定志、镇惊止怯。"}, {"source": "条297｜《奇效良方》·大圣散", "原文": "《奇效良方》卷六十三：大圣散。治妊娠怔悸，睡里多惊，腹胁膨胀，坐卧不宁。  \n白茯苓去皮、麦门冬去心、黄芪去芦，蜜炙、当归去芦，酒浸、川芎各一钱半 木香不见火、人参、甘草炙，各一钱  \n上作一服，水二盅，生姜五片，煎至一盅，不拘时服。", "白话": "大圣散。治妊娠怔悸，睡里多惊，腹胁膨胀，坐卧不宁。（组成照录）：白茯苓去皮、麦门冬去心、黄芪去芦蜜炙、当归去芦酒浸、川芎各一钱半；木香不见火、人参、甘草炙各一钱。煎服（照录）：上作一服，水二盅，生姜五片，煎至一盅，不拘时服。方义：益气养血、安神定悸，为妊娠而设。"}, {"source": "条298｜《奇效良方》·宁心膏", "原文": "《奇效良方》卷六十四：宁心膏。治小儿惊悸不宁，心经有热，多啼，安神定志。  \n人参、白术、茯神、茯苓、山药、羌活、甘草各一两 朱砂二两 片脑一钱 麝香少许 金箔二十片，为衣  \n上为细末，炼蜜为丸，如芡实大，每服半丸，用薄荷汤无时化下。", "白话": "宁心膏。治小儿惊悸不宁，心经有热，多啼；安神定志。（组成照录）：人参、白术、茯神、茯苓、山药、羌活、甘草各一两；朱砂二两；片脑一钱；麝香少许；金箔二十片为衣。制法服法（照录）：上为细末，炼蜜为丸，如芡实大，每服半丸，用薄荷汤无时化下。方义：健脾清心、镇惊安神。"}, {"source": "条299｜《丹溪心法》·朱砂安神丸", "原文": "《丹溪心法》卷四：真觉心跳者是血少，四物、朱砂安神之类。入方。治劳役心跳大虚证。  \n朱砂 归身 白芍 侧柏叶炒，五钱 川芎、陈皮、甘草各二钱 黄连炒,一钱半  \n上为末，猪心血丸服。", "白话": "真正觉得心跳的，是血少，用四物、朱砂安神之类。入方，治劳役心跳的大虚证。（组成照录）：朱砂、归身、白芍、侧柏叶炒五钱，川芎、陈皮、甘草各二钱，黄连炒一钱半。制法服法（照录）：上为末，猪心血丸服。方义：养血清心、安神定悸。"}, {"source": "条300｜《医学正传》·定志丸", "原文": "《医学正传》卷五：定志丸。治心气不足，恍惚多忘，及怔忡惊悸等证。  \n人参、白茯苓各三钱 远志去心、石菖蒲各二两  \n上为细末，炼蜜为丸，如梧桐子大，朱砂为衣，每服五十丸，食后白汤下。", "白话": "定志丸。治心气不足，恍惚多忘，以及怔忡惊悸等证。（组成照录）：人参、白茯苓各三钱；远志去心、石菖蒲各二两。制法服法（照录）：上为细末，炼蜜为丸，如梧桐子大，朱砂为衣，每服五十丸，食后白汤下。方义：补心气、开心窍、定志安神。"}, {"source": "条301｜《医学正传》·无名方", "原文": "《医学正传》卷五：祖传方治忧愁思虑伤心，令人惕然心跳动，惊悸不安之证。  \n川归酒洗用身、生地黄酒洗、远志去心、茯神各五钱 石菖蒲九节、黄连各二钱五分 牛黄一钱，另研 辰砂二钱，另研 金箔十五片  \n上以前六味研细，入牛黄、辰砂二味末子，猪心血丸如黍米大，金箔为衣，每服五十丸，煎灯心汤送下。", "白话": "祖传方，治忧愁思虑伤心，使人惕然心跳动、惊悸不安之证。（组成照录）：川归酒洗用身、生地黄酒洗、远志去心、茯神各五钱；石菖蒲九节、黄连各二钱五分；牛黄一钱另研、辰砂二钱另研、金箔十五片。制法服法（照录）：上以前六味研细，入牛黄、辰砂二味末子，猪心血丸如黍米大，金箔为衣，每服五十丸，煎灯心汤送下。方义：养血清心、镇惊安神。"}, {"source": "条302｜《医学正传》·茯苓散", "原文": "《医学正传》卷七：茯苓散。治产后心虚，怔忡不定，言语错乱。  \n人参、甘草、山药、当归各一钱 远志、茯苓、桂心、麦门冬各半钱  \n上细切，作一服，加生姜三片，大枣一枚，水一盏半，煎至一盏，去渣温服。", "白话": "茯苓散。治产后心虚，怔忡不定，言语错乱。（组成照录）：人参、甘草、山药、当归各一钱；远志、茯苓、桂心、麦门冬各半钱。煎服（照录）：上细切，作一服，加生姜三片，大枣一枚，水一盏半，煎至一盏，去渣温服。方义：益气养血、宁心安神，产后心虚宜之。"}, {"source": "条303｜《苍生司命》·安神丸", "原文": "《苍生司命》卷五：安神丸。治忧愁思虑伤心，惊悸善忘，夜不安卧。  \n黄连、朱砂各一两 当归、生地、炙甘草各五钱  \n上末，米糊丸。", "白话": "安神丸。治忧愁思虑伤心，惊悸善忘，夜不安卧。（组成照录）：黄连、朱砂各一两；当归、生地、炙甘草各五钱。制法服法（照录）：上末，米糊丸。方义：清心降火、养血安神。"}, {"source": "条304｜《苍生司命》·安神丸", "原文": "《苍生司命》卷七：怔忡者，心中惕惕不安，如人将捕之状，无时而作者是也。惊悸者，善恐怖，蓦然跳跃惊动，有时而作者是也。尤当分虚实治之。健忘、怔忡者，纯主不足，惊悸则不足中之有余也。  \n治健忘、怔忡者多主心血不足，精神亏欠，皆用四物汤、安神丸、八味定志丸、归脾汤、天王补心丹，随证加减。", "白话": "怔忡者，是心中惕惕不安，如人将捕之状，无定时而发作的；惊悸者，是善恐怖，蓦然跳跃惊动，有定时而发作的。尤其应当分虚实来治。健忘、怔忡，纯属不足；惊悸则是不足之中夹有余。治健忘、怔忡多主心血不足、精神亏欠，都用四物汤、安神丸、八味定志丸、归脾汤、天王补心丹，随证加减。方义：本条为怔忡惊悸辨证与选方之总论。"}, {"source": "条305｜《韩氏医通》·驻阳小丹", "原文": "《韩氏医通》卷下：驻阳小丹炼法此本古方，主乌须不验。方外一衲，因予小惠，报以炼法。  \n茯神四两，去心 赤石脂火煅存性，四两 辰砂水飞，二两 乳香二两，灯芯研 川椒二两，净，以炭烧黄土地至通红，扫净，置椒于上，以瓦缶掩之，令为出汗  \n上五味，为细末，以人乳和稀剂，入鹅、鸭蛋壳内，糊封完固，加以绛袋，令体洁妇人带于胸乳之间，四十九日，日夕不离，取出干透则成，否则坏。再研，用枣肉和为丸绿豆大。每日空", "白话": "驻阳小丹炼法：这本是古方，主治乌须无效。方外一僧，因我有小惠，报以此炼法。（组成照录）：茯神四两去心；赤石脂火煅存性四两；辰砂水飞二两；乳香二两，灯芯研；川椒二两净（以炭烧黄土地至通红，扫净，置椒于上，以瓦缶掩之，令出汗）。制法服法（照录）：上五味，为细末，以人乳和稀剂，入鹅、鸭蛋壳内，糊封完固，加以绛袋，令体洁妇人带于胸乳之间，四十九日，日夕不离，取出干透则成，否则坏。再研，用枣肉和为丸绿豆大。每日空心人乳送下，或人参、麦门冬汤代之，卧时酒下亦可。凡心血不足、怔忡、健忘等疾"}, {"source": "条306｜《女科撮要》·朱砂安神丸", "原文": "《女科撮要》卷下：朱砂安神丸。治产后血晕、心神惊悸等症。  \n朱砂飞过，五钱 生地黄一钱半 黄连酒洗，六钱 甘草炙，五分 当归一钱五分  \n上为末，饭糊为丸，每服十五丸。", "白话": "朱砂安神丸。治产后血晕、心神惊悸等症。（组成照录）：朱砂飞过五钱、生地黄一钱半、黄连酒洗六钱、甘草炙五分、当归一钱五分。制法服法（照录）：上为末，饭糊为丸，每服十五丸。方义：清心养血、安神定悸，产后血虚有热者宜之。"}, {"source": "条307｜《保婴撮要》·养心汤", "原文": "《保婴撮要》卷三：养心汤。治心血虚怯惊痫，或惊悸怔忡，盗汗无寐，发热烦躁。  \n黄芪、白茯苓、茯神、半夏曲、当归、川芎、辣桂、柏子仁、酸枣仁、五味子、人参各三钱 甘草炒，四钱  \n上每服一、二钱，姜枣水煎。", "白话": "养心汤。治心血虚怯之惊痫，或惊悸怔忡，盗汗不寐，发热烦躁。（组成照录）：黄芪、白茯苓、茯神、半夏曲、当归、川芎、辣桂、柏子仁、酸枣仁、五味子、人参各三钱，甘草炒四钱。制法服法（照录）：上每服一、二钱，姜枣水煎。方义：养心益气、化痰安神。"}, {"source": "条308｜《保婴撮要》·朱砂安神丸", "原文": "《保婴撮要》卷八：朱砂安神丸。治心疳怔忡，心中痞闷。  \n朱砂四钱 黄连、生地黄各半两 生甘草二钱半 兰香叶二钱，烧灰 铜青、轻粉各五分  \n上为末，干敷上。", "白话": "朱砂安神丸。治心疳怔忡，心中痞闷。（组成照录）：朱砂四钱、黄连、生地黄各半两、生甘草二钱半、兰香叶二钱烧灰、铜青、轻粉各五分。制法服法（照录）：上为末，干敷上。方义：清热解毒、敛疮安神（本方为外治敷方）。"}, {"source": "条309｜《保婴撮要》·活人酸枣仁汤", "原文": "《保婴撮要》卷二十：活人酸枣仁汤。治痘疹虚烦，惊悸不得眠。  \n酸枣仁炒、甘草炙、知母炒、白茯苓、麦门冬去心、川芎、干姜炒，各三分  \n上水煎温服，儿大倍之。", "白话": "活人酸枣仁汤。治痘疹虚烦，惊悸不得眠。（组成照录）：酸枣仁炒、甘草炙、知母炒、白茯苓、麦门冬去心、川芎、干姜炒各三分。煎服（照录）：上水煎温服，儿大倍之。方义：养心清热除烦，治痘疹后虚烦惊悸。"}, {"source": "条310｜《保婴金镜录·面部见色主症》·六味地黄丸", "原文": "《保婴金镜录·面部见色主症》：若惊悸倦怠，属肝经血虚，用六味地黄丸。", "白话": "若惊悸倦怠，属于肝经血虚的，用六味地黄丸。方义：滋补肝肾之阴，阴血足则惊悸自止。"}, {"source": "条311｜《扶寿精方·诸虚门》·柏子养心丸", "原文": "《扶寿精方·诸虚门》：柏子养心丸。  \n柏子仁水洗净，略蒸晒干，去壳，四两，北京有净仁卖 生地黄水洗，次入酒浸蒸一时，晒一日，又酒拌如前蒸晒共五次，二两 枸杞水洗净，三两，晒干 玄参坚黑者，水洗，二两 麦门冬水润，去心、白茯神去皮木、当归酒洗，各一两 石菖蒲去尾洗净、甘草各五钱，如心神不宁，多惧少睡加酸枣仁，水润去红皮  \n健忘加远志，水润去木，甘草煎汤浸一宿，如志一两则草用五钱。  \n上为细末，", "白话": "柏子养心丸。（组成照录）：柏子仁（水洗净，略蒸晒干，去壳）四两（北京有净仁卖）；生地黄（水洗，次入酒浸蒸一时，晒一日，又酒拌如前蒸晒共五次）二两；枸杞（水洗净）三两，晒干；玄参（坚黑者，水洗）二两；麦门冬（水润，去心）、白茯神去皮木、当归酒洗各一两；石菖蒲去尾洗净、甘草各五钱。加减（照录）：如心神不宁、多惧少睡加酸枣仁（水润去红皮）；健忘加远志（水润去木），甘草煎汤浸一宿，如志一两则草用五钱。制法服法与功效（照录）：上为细末，除柏子、地黄石臼捣如泥，余末加炼蜜丸梧桐子大，每服"}, {"source": "条312｜《扶寿精方·小儿门》·抱龙丸", "原文": "《扶寿精方·小儿门》：抱龙丸。  \n南星汤泡，去皮脐，锉片，微炒为末，入黑黄牛胆中，悬风处阴干，春夏五钱，秋冬六钱 白茯苓去皮、山药各三钱 天竺黄、雄黄水飞，另研、琥珀猪胆浸一宿，火焙研，各一钱五分 麝一分 朱砂水飞，另研为衣  \n上为细末，腊月取雪，新坛盛埋土中，合药取一碗，甘草三钱，煎汁为丸。如无雪水，新汲水亦可。和匀如芡实大，阴干，葱头、薄荷汤任下。痰嗽，姜汤下。痘疹见形，白汤下。悸不安，灯", "白话": "抱龙丸。（组成照录）：南星（汤泡，去皮脐，锉片，微炒为末，入黑黄牛胆中，悬风处阴干）春夏五钱、秋冬六钱；白茯苓去皮、山药各三钱；天竺黄、雄黄（水飞，另研）、琥珀（猪胆浸一宿，火焙研）各一钱五分；麝一分；朱砂（水飞，另研为衣）。制法服法（照录）：上为细末，腊月取雪，新坛盛埋土中，合药取一碗，甘草三钱，煎汁为丸。如无雪水，新汲水亦可。和匀如芡实大，阴干，葱头、薄荷汤任下。痰嗽，姜汤下。痘疹见形，白汤下。悸不安，灯心汤下。方义：清热化痰、镇惊安神，小儿痰热惊悸之方。"}, {"source": "条313｜《扶寿精方·诸虚门》·加味宁志丸", "原文": "《扶寿精方·诸虚门》：加味宁志丸。治虚惫精神恍惚，心思昏愦，气不足，健忘怔忡。  \n白茯苓去皮 人参 远志甘草煎汤浸软，去木 菖蒲十九节者，米泔浸 黄连去毛 酸枣仁水浸，去仁皮 柏子仁如法去壳，一两 当归酒洗、生地黄酒洗，各八钱 木香四钱，不用火 朱砂研，水飞，一两二钱，半入药半为衣  \n上为末，炼蜜丸，绿豆大，半饥时，用麦门冬去心，煎汤下五六十丸。", "白话": "加味宁志丸。治虚惫精神恍惚，心思昏愦，气不足，健忘怔忡。（组成照录）：白茯苓去皮、人参、远志（甘草煎汤浸软，去木）、菖蒲（十九节者，米泔浸）、黄连去毛、酸枣仁（水浸，去仁皮）、柏子仁（如法去壳）一两；当归酒洗、生地黄酒洗各八钱；木香四钱（不用火）；朱砂研水飞一两二钱（半入药半为衣）。制法服法（照录）：上为末，炼蜜丸，绿豆大，半饥时，用麦门冬去心煎汤下五六十丸。方义：益气养心、安神定志。"}, {"source": "条314｜《广嗣纪要》·大圣散", "原文": "《广嗣纪要》卷十三：妊娠胎惊者，七八月以后，胎形既成，或因气闷，或因喧呼，心神脉乱，致令子惊，使母心神忪悸，睡里多惊，坐卧不宁，气急逼迫，宜服大圣散，保安胎孕，子母无虞。  \n白茯苓、川芎、麦冬、炙草、当归、木香、人参、炙芪等分  \n上㕮咀，每服七钱，水钟半，姜三片，煎服。", "白话": "妊娠胎惊：七八月以后胎形已成，或因气闷，或因喧呼，心神脉乱，致使子惊，令母心神忪悸，睡里多惊，坐卧不宁，气急逼迫——宜服大圣散，保安胎孕，子母无虞。（组成照录）：白茯苓、川芎、麦冬、炙草、当归、木香、人参、炙芪等分。煎服（照录）：上㕮咀，每服七钱，水钟半，姜三片，煎服。方义：益气养血、安神定悸以安胎。"}, {"source": "条315｜《养生四要》·天王补心丹", "原文": "《养生四要》卷四：天王补心丹。  \n熟地黄、白茯苓、人参、远志去心，甘草水煎、石菖蒲、玄参、柏子仁去壳、天冬去心、麦冬去心、丹参、酸枣仁去壳，炒、炙甘草、归身酒洗、杜仲去皮，姜汁炒，断丝取末、五味各一两  \n上十五味，共为末，炼蜜杵为丸，如弹子大，每丸重一钱，金箔为衣，每服一丸，枣汤化下，临卧食远服。此方熟地黄、白茯苓、天冬、玄参、杜仲、五味，皆补肾之药也。其制方之法，以熟地黄、当归、五味、杜仲益", "白话": "天王补心丹。（组成照录）：熟地黄、白茯苓、人参、远志（去心，甘草水煎）、石菖蒲、玄参、柏子仁去壳、天冬去心、麦冬去心、丹参、酸枣仁去壳炒、炙甘草、归身酒洗、杜仲（去皮，姜汁炒，断丝取末）、五味各一两。制法服法与方义（照录）：上十五味，共为末，炼蜜杵为丸，如弹子大，每丸重一钱，金箔为衣，每服一丸，枣汤化下，临卧食远服。此方熟地黄、白茯苓、天冬、玄参、杜仲、五味，皆补肾之药也。其制方之法，以熟地黄、当归、五味、杜仲益血固精；以人参、白茯苓、柏子仁、远志、菖蒲、酸枣仁宁心保神，除惊"}, {"source": "条316｜《保命歌括》·平补镇心丹", "原文": "《保命歌括》卷十二：平补镇心丹。治心血不足，时或怔忡，夜多异梦，如坠层崖。常服安心肾，益荣卫。  \n白茯苓、五味子、车前子、茯神、桂心、麦冬各一两二钱半 远志甘草水煮，一两半，去心 天冬、山药姜汁蒸、地黄酒蒸，各一两半 酸枣仁去壳、炒，二钱半 人参半两 龙齿二两半 朱砂水飞，半两，为衣  \n上为末，炼蜜丸，如梧桐子大，每二十，空心米饮温酒下。", "白话": "平补镇心丹。治心血不足，时或怔忡，夜多异梦，如坠层崖。常服安心肾，益营卫。（组成照录）：白茯苓、五味子、车前子、茯神、桂心、麦冬各一两二钱半；远志（甘草水煮）一两半去心；天冬、山药姜汁蒸、地黄酒蒸各一两半；酸枣仁去壳炒二钱半；人参半两；龙齿二两半；朱砂水飞半两为衣。制法服法（照录）：上为末，炼蜜丸，如梧桐子大，每二十丸，空心米饮温酒下。方义：平补心肾、镇心安神。"}, {"source": "条317｜《古今医统大全》·平胃镇心丹", "原文": "《古今医统大全》卷六十二：平胃镇心丹。治男妇心气不足，志意不定，精神恍惚，夜多异梦，惊悸烦郁，及肾气伤败，血少气多，四肢倦怠，足膝酸疼，睡卧不安，梦寐遗精，时有白浊，渐至羸，以致耳聋。  \n熟地黄、生地黄、干山药、天门冬去心、麦门冬去心、柏子仁、茯神各四两 辰砂另研为末、苦梗炒，各一两 石菖蒲一斤 远志甘草水煮去心，七两 当归六两 龙骨一两  \n上为细末，炼蜜丸，如梧桐子大。每服三十丸，空心饮汤下", "白话": "平胃镇心丹。治男子妇人心气不足，志意不定，精神恍惚，夜多异梦，惊悸烦郁，以及肾气伤败、血少气多，四肢倦怠，足膝酸疼，睡卧不安，梦寐遗精，时有白浊，渐至羸瘦，以致耳聋。（组成照录）：熟地黄、生地黄、干山药、天门冬去心、麦门冬去心、柏子仁、茯神各四两；辰砂另研为末、苦梗炒各一两；石菖蒲一斤；远志（甘草水煮去心）七两；当归六两；龙骨一两。制法服法（照录）：上为细末，炼蜜丸，如梧桐子大。每服三十丸，空心饮汤下，温酒亦可，渐加至五十丸。方义：补心肾、益气血、镇心安神。"}, {"source": "条318｜《古今医统大全》·抱龙丸", "原文": "《古今医统大全》卷八十八：抱龙丸。抱者，保也。龙者，肝也。肝应东方青龙木，木生火，谓生我者，父母也。肝为母，心为子，母安则子安，况心藏神，肝藏魂，神魂既定，惊从何生？故曰抱龙丸。理小儿诸惊，四时感冒，瘟疫邪热，烦躁不宁，痰嗽气急，疮疹欲出，发搐并宜用此。常服驱风化痰，解镇心热，和脾胃，益精神，镇虚惊恐怖谵语。  \n人参、天竺黄、琥珀、檀香、茯苓各一两五钱 甘草炙，三两 枳壳炒 枳实炒 辰砂飞，五两", "白话": "抱龙丸。抱者，保也；龙者，肝也。肝应东方青龙木，木生火，所谓生我者，是父母也。肝为母，心为子，母安则子安；何况心藏神，肝藏魂，神魂既定，惊从何生？所以叫抱龙丸。调理小儿诸惊、四时感冒、瘟疫邪热、烦躁不宁、痰嗽气急、疮疹欲出、发搐，都宜用此。常服驱风化痰、解镇心热、和脾胃、益精神、镇虚惊恐怖谵语。（组成照录）：人参、天竺黄、琥珀、檀香、茯苓各一两五钱；甘草炙三两；枳壳炒、枳实炒、辰砂飞五两；山药炒一斤；牛胆南星炒一两；金箔一百片。制法服法（照录）：上为极细末，随手新汲水和匀，如"}, {"source": "条319｜《古今医统大全》·安神丸", "原文": "《古今医统大全》卷八十八：安神丸。治小儿惊悸渴闷，脉实面红，颊赤口燥。  \n麦门冬、马牙硝、白茯苓、山药、寒水石各半两 朱砂一两 甘草半两 龙胆一字  \n上为末，炼蜜为丸，如鸡头子大，每服半丸，砂糖水下。", "白话": "安神丸。治小儿惊悸渴闷，脉实面红，颊赤口燥。（组成照录）：麦门冬、马牙硝、白茯苓、山药、寒水石各半两；朱砂一两；甘草半两；龙胆一字。制法服法（照录）：上为末，炼蜜为丸，如鸡头子大，每服半丸，砂糖水下。方义：清热镇惊、生津除烦。"}, {"source": "条320｜《医学入门·外集》·朱砂安神丸", "原文": "《医学入门·外集》：胎惊心中怔忡，睡卧不宁，热者朱砂安神丸；虚者定志丸。余可类推。", "白话": "胎惊见心中怔忡、睡卧不宁：属热的用朱砂安神丸，属虚的用定志丸。其余可以类推。方义：分虚实论治，热者清镇，虚者补定。"}, {"source": "条321｜《古今医鉴》·定心汤", "原文": "《古今医鉴》卷三：定心汤秘方。治伤寒瘥后心下怔忡。生地汁、童便各半盏，二味和合，重汤煮数沸服。", "白话": "定心汤秘方。治伤寒瘥后心下怔忡。（组成服法照录）：生地汁、童便各半盏，二味和合，重汤煮数沸服。方义：滋阴凉血、引火下行，治瘥后余热扰心之怔忡。"}, {"source": "条322｜《古今医鉴》·天王补心丹", "原文": "《古今医鉴》卷七：天王补心丹。宁心益志，壮力强精，安神魂，定惊悸怔忡，祛烦热，化痰涎稠浊。  \n熟地二两，酒洗 白茯苓二两 丹参二两 柏子仁去壳，二两 百部二两 石菖蒲二两 牛膝酒洗，二两 杜仲酥炙，去丝，二两 当归酒洗，二两 枣仁炒，二两 玄参二两 天门冬去心，二两 五味子二两 人参二两 白茯神二两 远志甘草水泡，二两 桔梗一两 甘草一两 麦门冬一两  \n上为细末，炼蜜为丸如弹子大，金箔为衣。每", "白话": "天王补心丹。宁心益志，壮力强精，安神魂，定惊悸怔忡，祛烦热，化痰涎稠浊。（组成照录）：熟地二两酒洗、白茯苓二两、丹参二两、柏子仁去壳二两、百部二两、石菖蒲二两、牛膝酒洗二两、杜仲酥炙去丝二两、当归酒洗二两、枣仁炒二两、玄参二两、天门冬去心二两、五味子二两、人参二两、白茯神二两、远志甘草水泡二两、桔梗一两、甘草一两、麦门冬一两。制法服法（照录）：上为细末，炼蜜为丸如弹子大，金箔为衣。每服一丸，临卧灯心、红枣煎汤，细嚼送下。方义：滋阴养血、宁心安神、化痰定悸。"}, {"source": "条323｜《医方考》·朱雀丸", "原文": "《医方考》卷五：朱雀丸。  \n白茯神二两 沉香五钱  \n惊气怔忡者，此方主之。因惊而得者，名曰惊气怔忡。《内经》曰：惊则气乱。宜其怔怔忡忡，如物之扑也。是方也，茯神之甘平，可以宁心；沉香之坚实，可使下气，气下则怔忡瘥矣。", "白话": "朱雀丸。（组成照录）：白茯神二两、沉香五钱。主治：惊气怔忡者，此方主之。因惊而得的，名叫惊气怔忡。《内经》说：惊则气乱。所以怔怔忡忡，如物之扑。此方中，茯神甘平，可以宁心；沉香坚实，可以下气，气下则怔忡愈。方义：宁心下气，治惊气怔忡。"}, {"source": "条324｜《仁术便览》·朱砂安神丸", "原文": "《仁术便览》卷三：朱砂安神丸。治心烦懊憹，心乱怔忡，胸中气乱，心中痞闷，食入反吐出。  \n朱砂四钱，研 黄连末五钱 生甘草二钱半  \n上为末，蒸饼丸如黄米大。每十丸，唾津咽下。", "白话": "朱砂安神丸。治心烦懊憹，心乱怔忡，胸中气乱，心中痞闷，食入反吐出。（组成照录）：朱砂四钱研、黄连末五钱、生甘草二钱半。制法服法（照录）：上为末，蒸饼丸如黄米大。每十丸，唾津咽下。方义：清心降火、镇心安神。"}, {"source": "条325｜《怪证奇方》·茯神汤", "原文": "《怪证奇方》卷下：怔忡多忘，魇梦不已，茯神汤下。", "白话": "怔忡多忘、魇梦不已的，用茯神汤送下。（原稿未出组成与汤方内容，照录待核）方义：养心安神定悸。"}, {"source": "条326｜《幼幼集成》·安神丸", "原文": "《幼幼集成》卷四：神不安而啼者，睡中惊悸，抱母大哭，面色紫黑，盖神虚惊悸。宜安神丸定其心志。", "白话": "神不安而啼哭的：睡中惊悸，抱母大哭，面色紫黑——这是神虚惊悸。宜用安神丸定其心志。（原稿未出组成，照录待核）方义：镇惊安神。"}, {"source": "条327｜《医学原理》·妙香散", "原文": "《医学原理》卷八：妙香散。治遗精恍惚惊悸，乃心气亏败所致。法当补益心气为主。故用茯苓、茯神、远志、辰砂补心安神定惚，人参、黄芪、山药益正气，木香行郁，麝香通窍，甘草泄火，桔梗载诸药不令下沉。", "白话": "妙香散。治遗精恍惚惊悸，是心气亏败所致。法当以补益心气为主。所以用茯苓、茯神、远志、辰砂补心安神定惚，人参、黄芪、山药益正气，木香行郁，麝香通窍，甘草泄火，桔梗载诸药不令下沉。（原稿未出分量，照录待核）方义：补心气、行郁滞、通窍安神。"}, {"source": "条328｜《医学原理》·朱砂安神丸", "原文": "《医学原理》卷九：如因惊悸而致者，当安神为主，宜朱砂安神丸为主加减。", "白话": "如因惊悸而致者，当以安神为主，宜用朱砂安神丸为主加减。（原稿未出组成，照录待核）方义：安神为治惊悸之主法。"}, {"source": "条329｜《幼科证治准绳》·安神丸", "原文": "《幼科证治准绳》集二：安神丸。治小儿惊悸，热渴心闷，脉实面红，颊赤口燥。  \n麦门冬、马牙硝、白茯苓、山药、寒水石各半两 朱砂一两 甘草半两 龙脑一字  \n上为末，炼蜜丸，如鸡头大。每服半丸，沙糖水下。", "白话": "安神丸。治小儿惊悸，热渴心闷，脉实面红，颊赤口燥。（组成照录）：麦门冬、马牙硝、白茯苓、山药、寒水石各半两；朱砂一两；甘草半两；龙脑一字。制法服法（照录）：上为末，炼蜜丸，如鸡头大。每服半丸，沙糖水下。方义：清热镇惊、生津除烦。"}, {"source": "条330｜《幼科证治准绳》·酸枣仁汤", "原文": "《幼科证治准绳》集五：活人酸枣仁汤。治痘疹，虚烦惊悸不得眠。  \n酸枣仁炒、甘草炙、知母炒、白茯苓、麦门冬去心、川芎、干姜炒，各三分  \n上，水煎，温服。儿大倍之。", "白话": "活人酸枣仁汤。治痘疹虚烦、惊悸不得眠。（组成照录）：酸枣仁炒、甘草炙、知母炒、白茯苓、麦门冬去心、川芎、干姜炒各三分。煎服（照录）：上，水煎，温服。儿大倍之。方义：养心清热除烦。"}, {"source": "条331｜《女科证治准绳》·白茯苓丸", "原文": "《女科证治准绳》卷五：白茯苓丸。治产后心虚惊悸，神志不安。  \n白茯苓去皮、熟干地黄各一两 人参去芦、桂心、远志去心、石菖蒲、柏子仁、琥珀各半两，另研细  \n上为细末，炼蜜和捣三二百下，丸如梧子大。每服三十丸，不拘时，粥饮送下。", "白话": "白茯苓丸。治产后心虚惊悸，神志不安。（组成照录）：白茯苓去皮、熟干地黄各一两；人参去芦、桂心、远志去心、石菖蒲、柏子仁、琥珀各半两（另研细）。制法服法（照录）：上为细末，炼蜜和捣三二百下，丸如梧子大。每服三十丸，不拘时，粥饮送下。方义：养心安神、益气定悸。"}, {"source": "条332｜《女科证治准绳》·远志丸", "原文": "《女科证治准绳》卷五：远志丸。治产后脏虚不足，心神惊悸，志意不安，腹中急痛，或时怕怖，夜卧不安。  \n远志、麦门冬各去心、黄芪、当归炒、人参、白术、独活各去芦、白茯苓去皮、桂心、柏子仁、石菖蒲、熟干地黄、山茱萸、钟乳粉、阿胶碎、炒，各一两  \n上为细末，炼蜜和捣五七百下，丸如梧桐子大。每服三十丸，温酒送下，不拘时候，日进二服。", "白话": "远志丸。治产后脏虚不足，心神惊悸，志意不安，腹中急痛，或时怕怖，夜卧不安。（组成照录）：远志、麦门冬各去心、黄芪、当归炒、人参、白术、独活各去芦、白茯苓去皮、桂心、柏子仁、石菖蒲、熟干地黄、山茱萸、钟乳粉、阿胶（碎，炒）各一两。制法服法（照录）：上为细末，炼蜜和捣五七百下，丸如梧桐子大。每服三十丸，温酒送下，不拘时候，日进二服。方义：补虚养心、安神定悸。"}, {"source": "条333｜《济阳纲目》·归神丹", "原文": "《济阳纲目》卷四十五：归神丹。治癫痫诸疾，惊悸，神不守舍。  \n朱砂颗块二两，猪心内酒蒸 罗参、当归、白茯苓、酸枣仁各二两 远志姜制、琥珀、龙齿各一两 金箔、银箔各二十片  \n上为细末，酒糊丸，如桐子大，每服二三十丸，麦门冬汤下，炒酸枣仁亦可。", "白话": "归神丹。治癫痫诸疾，惊悸，神不守舍。（组成照录）：朱砂颗块二两（猪心内酒蒸）；罗参、当归、白茯苓、酸枣仁各二两；远志姜制、琥珀、龙齿各一两；金箔、银箔各二十片。制法服法（照录）：上为细末，酒糊丸，如桐子大，每服二三十丸，麦门冬汤下，炒酸枣仁亦可。方义：养心安神、镇惊定志。"}, {"source": "条334｜《济阳纲目》·寒水石散", "原文": "《济阳纲目》卷五十四：寒水石散。治因惊心气不行，郁而生涎，结为饮，遂为大疾，怔悸陨获，不自胜持，少遇惊则发，尤宜服之。  \n寒水石煅、滑石水飞，各二钱 生甘草一钱  \n上为末，每服二钱，热则用新汲水下，怯寒则用姜枣汤下。加龙胆草少许尤佳。", "白话": "寒水石散。治因惊而心气不行，郁而生涎，结为饮，遂成大病：怔悸陨获，不能自持，稍遇惊即发作——尤其宜服此方。（组成照录）：寒水石煅、滑石水飞各二钱，生甘草一钱。制法服法（照录）：上为末，每服二钱，热则用新汲水下，怯寒则用姜枣汤下。加龙胆草少许尤佳。方义：清热利湿、镇心定悸。"}, {"source": "条335｜《医学研悦》·远志甘草汤", "原文": "《医学研悦》卷四：达生散。胎至八九月多服易产。  \n陈皮八分 甘草炒，三分 白芍酒炒，一钱 当归用身，钱半 川芎六分 香附醋炒，二钱 苏梗七分 白术土炒，八分 续断酒洗，一钱 杜仲盐水炒去丝，一钱 山楂一钱二分  \n生姜水煎。咳嗽去香附，加麦冬、五味子九粒；脾胃不实加山药饭上蒸一钱，砂仁五分；心跳恍惚，加酸枣仁炒香一钱二分、远志甘草汤，煺去骨七分；发热加黄芩炒六分。", "白话": "达生散。胎至八九月多服容易生产。（组成照录）：陈皮八分、甘草炒三分、白芍酒炒一钱、当归用身钱半、川芎六分、香附醋炒二钱、苏梗七分、白术土炒八分、续断酒洗一钱、杜仲盐水炒去丝一钱、山楂一钱二分。煎服与加减（照录）：生姜水煎。咳嗽去香附，加麦冬、五味子九粒；脾胃不实加山药饭上蒸一钱、砂仁五分；心跳恍惚，加酸枣仁炒香一钱二分、远志甘草汤，煺去骨七分；发热加黄芩炒六分。方义：养血理气、安胎达生。"}, {"source": "条336｜《医学研悦》·天王补心丹", "原文": "《医学研悦》卷七：古人制心肾丸、补心丹、养心丸，盖兼心肾而补之也。丹溪云：心为手少阴君火，肾为足少阴子水。少阴者，体也。水火者，用也。同体异用，不必虚至健忘、怔忡、惊悸、神志昏乱者，在所当用。天王补心丹，主方  \n熟地黄一两 白茯苓一两 人参一两 远志去心，甘草煮，一两 石菖蒲一两 玄参一两 柏子仁去壳，一两 天冬去心，一两 麦冬去心，一两 丹参一两 酸枣仁去壳炒，一两 甘草炙，一两 归身酒洗，一", "白话": "古人制心肾丸、补心丹、养心丸，是兼顾心肾而补之。丹溪说：心为手少阴君火，肾为足少阴子水。少阴是体，水火是用，同体而异用。不必等到虚至健忘、怔忡、惊悸、神志昏乱，才在所当用。天王补心丹主方（组成照录）：熟地黄一两、白茯苓一两、人参一两、远志（去心，甘草煮）一两、石菖蒲一两、玄参一两、柏子仁去壳一两、天冬去心一两、麦冬去心一两、丹参一两、酸枣仁去壳炒一两、甘草炙一两、归身酒洗一两、杜仲（盐水入姜汁炒，去丝）一两、五味子一两。方义（照录）：此方熟地、茯苓、天冬、玄参、杜仲、五味皆用"}, {"source": "条337｜《删补颐生微论》·天王补心丹", "原文": "《删补颐生微论》卷四：天王补心丹。主心血不足，神志不宁，津液枯竭，健忘怔忡，大便不利，口舌生疮等症。  \n人参去芦、白茯苓去皮、玄参炒、丹参炒、远志去木炒、桔梗各五钱 五味子烘、当归身酒洗、麦门冬去心、天门冬去心、柏子仁炒、酸枣仁炒，各二两 生地黄四两，酒洗  \n上为末，炼蜜丸如椒目大。白滚汤下。  \n心者，神明之官也。忧愁思虑则伤心，神明受伤则主不明而十二官危，故健忘怔忡。", "白话": "天王补心丹。主治心血不足，神志不宁，津液枯竭，健忘怔忡，大便不利，口舌生疮等症。（组成照录）：人参去芦、白茯苓去皮、玄参炒、丹参炒、远志去木炒、桔梗各五钱；五味子烘、当归身酒洗、麦门冬去心、天门冬去心、柏子仁炒、酸枣仁炒各二两；生地黄四两酒洗。制法服法（照录）：上为末，炼蜜丸如椒目大。白滚汤下。医论（照录）：心者，神明之官也。忧愁思虑则伤心，神明受伤则主不明而十二官危，故健忘怔忡。方义：滋阴养血、宁心安神。"}, {"source": "条338｜《奇方类编》·无名方", "原文": "《奇方类编》卷下：治神短烦躁不安，夜卧不宁，惊悸怔忡，恍惚健忘。  \n川连八两，姜炒 归身三两 生地三两 生草一两 玄参四两，酒洗 枣仁二两，炒黑 白茯神四两 远志肉二两，甘草水泡 琥珀一两 犀角一两 辰砂一两，为衣  \n莲子、灯心煎汤为丸，梧子大。每服一钱，空心白滚水送下。", "白话": "治神短烦躁不安，夜卧不宁，惊悸怔忡，恍惚健忘。（组成照录）：川连八两姜炒、归身三两、生地三两、生草一两、玄参四两酒洗、枣仁二两炒黑、白茯神四两、远志肉二两甘草水泡、琥珀一两、犀角一两、辰砂一两为衣。制法服法（照录）：莲子、灯心煎汤为丸，梧子大。每服一钱，空心白滚水送下。方义：养血清心、安神定悸。"}, {"source": "条339｜《顾松园医镜》·天王补心丹", "原文": "《顾松园医镜》卷十一：心跳善惊，虚烦无寐，则用天王补心。", "白话": "心跳善惊，虚烦不寐的，就用天王补心（丹）。（原稿未出组成，照录）方义：滋阴养血、宁心安神。"}, {"source": "条340｜《不居集·上集》·宁志丸", "原文": "《不居集·上集》：宁志丸。治怔忡惊悸，癫痫。  \n人参、枣仁酒浸、茯苓、柏子仁、当归、远志酒浸、茯神、石菖蒲、琥珀各五钱 乳香、朱砂各三钱  \n上为末，炼蜜丸桐子大，每服三五十丸，食后，枣汤下。", "白话": "宁志丸。治怔忡惊悸、癫痫。（组成照录）：人参、枣仁酒浸、茯苓、柏子仁、当归、远志酒浸、茯神、石菖蒲、琥珀各五钱；乳香、朱砂各三钱。制法服法（照录）：上为末，炼蜜丸桐子大，每服三五十丸，食后，枣汤下。方义：养心安神、化痰定志。"}, {"source": "条341｜《外科心法要诀》·白芍药汤", "原文": "《外科心法要诀》卷十六：如旬日外，儿脐忽肿，如吹不赤，捻动微响，或惊悸作啼者，宜用白芍药汤加薏苡仁，令儿服之，外以外消散敷之即愈。  \n白芍药汤  白芍酒炒，一两 泽泻五钱 甘草生，一钱二分 肉桂拣薄者刮去粗皮，一钱  \n共研粗末，每用二钱，水一盅，煎四分，空心频服。脐下痛加钩藤一钱，生姜一片，食盐五厘。", "白话": "如果十日以后，小儿脐部忽然肿起，如吹气样而不红，捻动微有响声，或惊悸作啼的，宜用白芍药汤加薏苡仁，令儿内服，外用以外消散敷之即愈。白芍药汤（组成照录）：白芍酒炒一两、泽泻五钱、甘草生一钱二分、肉桂（拣薄者刮去粗皮）一钱。制法服法与加减（照录）：共研粗末，每用二钱，水一盅，煎四分，空心频服。脐下痛加钩藤一钱，生姜一片，食盐五厘。方义：缓急和血、温中止痛。"}, {"source": "条342｜《妇科玉尺》·大圣汤", "原文": "《妇科玉尺》卷二：妊娠有怔忡脉乱，惊悸不安，夜卧不宁，恍惚气触者，宜大圣汤。", "白话": "妊娠见怔忡脉乱、惊悸不安、夜卧不宁、恍惚气触的，宜用大圣汤。（原稿未出组成，照录待核）方义：益气养血、安神定悸以安胎。"}, {"source": "条343｜《幼科释谜》·谭氏金珠丸", "原文": "《幼科释谜》卷六：谭氏金珠丸。  \n南星、白矾、半夏各七钱 人参、山药各五钱 朱砂、腻粉各二钱 金箔十片  \n即为衣，薄荷汁同水打糊丸，绿豆大，每一丸，姜汤下，量加减。", "白话": "谭氏金珠丸。（组成照录）：南星、白矾、半夏各七钱；人参、山药各五钱；朱砂、腻粉各二钱；金箔十片。制法服法（照录）：即为衣，薄荷汁同水打糊丸，绿豆大，每一丸，姜汤下，量加减。（“即为衣”句原稿不顺，照录待核）方义：化痰镇惊、健脾安神。"}, {"source": "条344｜《疫疹一得》·惊悸茯神镇惊汤", "原文": "《疫疹一得》卷下：惊悸茯神镇惊汤。  \n人参一钱 黄芪钱半，炙 当归二钱 茯神三钱 远志钱半 龙齿二钱，煅 白芍一钱 麦冬二钱 琥珀一钱，研冲服 炙甘草八分 龙眼三枚 灯芯三十寸", "白话": "惊悸茯神镇惊汤。（组成照录）：人参一钱、黄芪钱半炙、当归二钱、茯神三钱、远志钱半、龙齿二钱煅、白芍一钱、麦冬二钱、琥珀一钱（研冲服）、炙甘草八分、龙眼三枚、灯芯三十寸。（原稿未出煎服法，照录待核）方义：益气养血、镇惊安神。"}, {"source": "条345｜《大方脉·伤寒杂病医方》·安神丸", "原文": "《大方脉·伤寒杂病医方》：安神丸。治心热胆弱，怔忡惊悸。  \n黄连一两 当归、生地各五钱 甘草三钱  \n研末，面糊为小丸，朱砂滚衣。临卧，盐汤，每下二钱。", "白话": "安神丸。治心热胆弱，怔忡惊悸。（组成照录）：黄连一两、当归、生地各五钱、甘草三钱。制法服法（照录）：研末，面糊为小丸，朱砂滚衣。临卧，盐汤，每下二钱。方义：清心养血、安神定悸。"}, {"source": "条346｜《彤园医书（外科）》·安神散", "原文": "《彤园医书（外科）》卷四：凡针后出脓之时，气虚惊悸者，宜服安神散。", "白话": "凡针刺之后出脓之时，气虚惊悸的，宜服安神散。（原稿未出组成，照录待核）方义：益气安神定悸。"}, {"source": "条347｜《痘科辑要·杂症》·定心散", "原文": "《痘科辑要·杂症》：初热时，小便不长，梦中或发惊悸，急与定心散。灯心汤为引，否则惊搐之症至矣。", "白话": "痘疹初热时，小便不长，梦中或发惊悸的，急与定心散，用灯心汤为引；否则惊搐之症就要到来了。（原稿未出组成，照录待核）方义：清心定惊，防患未然。"}, {"source": "条348｜《医学妙谛》·酸枣仁汤", "原文": "《医学妙谛》卷下：怔忡健忘都可医，加减天王补心治。怔忡人呆将捕如，惕惕不宁神明殊。不寐怔忡，胆液亏，阳升虚烦，《金匮》酸枣仁汤。  \n枣仁 甘草 知母 茯苓 川芎  \n不寐健忘，肝肾阴亏，阳浮咸苦酸收甘缓法。", "白话": "怔忡健忘都可医，加减天王补心丹治。怔忡之人呆滞如人将捕，惕惕不宁，神明殊乱。不寐怔忡，属胆液亏、阳升虚烦的，用《金匮》酸枣仁汤。（组成照录）：枣仁、甘草、知母、茯苓、川芎。方义（照录）：不寐健忘，肝肾阴亏，阳浮，用咸苦酸收甘缓法。方义补述：即酸枣仁汤养肝血、清虚热、安心神。"}, {"source": "条349｜《验方新编》卷二十四·安神散", "原文": "《验方新编》卷二十四：安神散。治疔毒针后，气虚惊悸。  \n人参、麦冬、茯神、生芪、焦术、元参、陈皮、石菖蒲、炒枣仁、远志肉、五味子、炙草等分  \n服时，加朱砂末五分调服，凡恶毒攻心，心神不定者，用地骨皮研末，滚蜜水调服即安，亦名安神散。", "白话": "《验方新编》卷二十四载：安神散。主治疔毒针刺之后，气虚而生惊悸。（组成照录见原文。方义：人参、黄芪、白术补气，麦冬、五味子、元参滋阴，茯神、菖蒲、枣仁、远志安神定志，陈皮理气，炙草和中，共成益气养阴、安神定悸之方。）服药时，加朱砂末五分调服。凡恶毒攻心、心神不定的，用地骨皮研末，滚开的蜜水调服即安，也叫安神散。"}, {"source": "条350｜《杂病广要·脏腑类》·朱砂散", "原文": "朱砂散  \n《杂病广要·脏腑类》：治心脏不安，惊悸善忘，上膈风热，化痰安神，朱砂散方。  \n朱砂一两，研 白石英一两，研  \n上件药二味同细研为散，每服半钱，食后临卧煎金银汤调下。", "白话": "《杂病广要·脏腑类》载：主治心脏不安、惊悸善忘，上焦有风热，能化痰安神，用朱砂散方。（组成照录见原文。方义：朱砂镇心安神，白石英重镇安神，二药合研为散，以金银汤送服，取金石重镇、清心定悸之义。）上二味药同细研为散，每次服半钱，食后临卧前煎金银汤调下。"}, {"source": "条351｜《杂病广要·脏腑类》·朱砂安神丸", "原文": "朱砂安神丸  \n《杂病广要·脏腑类》：真觉心跳者是血少，四物、朱砂安神之类。丹溪曰：心气虚怯之人，怔忡或烦乱，或健忘，或失心后神痴不清，辰砂安神丸。又朱砂丸，治劳役心跳，于本方去地黄，加芍药、侧柏叶、川芎、陈皮。", "白话": "《杂病广要·脏腑类》载：真正觉得心跳的，是血少所致，宜四物汤、朱砂安神丸之类。朱丹溪说：心气虚怯之人，或怔忡烦乱，或健忘，或失心之后神志痴呆不清，用辰砂安神丸。又有朱砂丸，治劳役所致心跳，于本方去地黄，加芍药、侧柏叶、川芎、陈皮。"}, {"source": "条352｜《尊生书》·静神丹", "原文": "静神丹  \n《尊生书》静神丹  \n酒当归、酒生地、姜远志、茯神各五钱  菖蒲、黄连各二钱半  朱砂二钱  牛黄一钱  \n治忧思过度，惕然心跳。  \n猪心血，丸黍米大，金箔十五片为衣，灯心汤下五十丸。", "白话": "《尊生书》静神丹：酒当归、酒生地、姜远志、茯神各五钱，菖蒲、黄连各二钱半，朱砂二钱，牛黄一钱。主治忧思过度，惕然心跳。用猪心血为丸，如黍米大，金箔十五片为衣，灯心汤送下五十丸。"}, {"source": "条353｜《校注医醇賸义》卷二·大安汤", "原文": "大安汤  \n《校注医醇賸义》卷二：惊则气浮，真阳外越，真阴不守，心悸筋惕，大安汤主之大安汤自制。  \n白芍一钱五分，酒炒 五味子五分 牡蛎四钱，煅研 龙齿二钱 木瓜一钱，酒炒 枣仁二钱，炒研 熟地黄五钱 人参二钱 茯苓二钱 柏仁二钱 金器一具同煎  \n此方治惊，以龙、牡、金器镇其浮，以枣仁、白芍、五味、木瓜敛其越，人参、茯苓以益气，当归、柏仁以养血，乃心肝兼顾，神气同固之法也。祖怡注。", "白话": "《校注医醇賸义》卷二载：受惊则气浮越，真阳外越，真阴不能内守，以致心悸筋惕，用大安汤主治——大安汤为自制方。（组成照录见原文。方义：以龙齿、牡蛎、金器重镇浮阳，以枣仁、白芍、五味子、木瓜收敛耗散之气，人参、茯苓益气，当归、柏仁养血，是心肝兼顾、神气同固的方法。祖怡注。）"}, {"source": "条354｜《经验良方全集》卷一·补心酒方", "原文": "补心酒方  \n《经验良方全集》卷一：补心酒方。治怔忡，心神不宁。  \n麦冬去心，二两 柏子仁去油，一两 白茯神一两 归身一两 龙眼肉二两 生地黄一两五钱  \n盛绢袋中，入无灰酒十斤，坛内浸七日用，连坛煮亦可。", "白话": "《经验良方全集》卷一载：补心酒方。主治怔忡、心神不宁。（组成照录见原文。方义：麦冬、生地滋阴，柏子仁、茯神、归身、龙眼肉养血安神，浸酒借酒力上行心经，共成养血宁心之剂。）装入绢袋中，放入无灰酒十斤，坛内浸泡七天即可用，连坛同煮也可以。"}, {"source": "条355｜《医学衷中参西录·医方》·安魂汤", "原文": "安魂汤  \n《医学衷中参西录·医方》：安魂汤。治心中气血虚损，兼心下停有痰饮，致惊悸不眠。  \n龙眼肉六钱 酸枣仁四钱，炒捣 生龙骨五钱，捣末 生牡蛎五钱，捣末 清半夏三钱 茯苓片三钱 生赭石四钱，轧细  \n若服一两剂后无效者，可于服汤药之外，临睡时用开水送服西药臭剥一瓦，借其麻痹神经之力，以收一时之效，俾汤剂易于为力也。方书谓：痰饮停于心下，其人多惊悸不寐。盖心，火也，痰饮，水也，火畏水刑，故惊", "白话": "《医学衷中参西录·医方》载：安魂汤。主治心中气血虚损，兼心下停有痰饮，以致惊悸不眠。（组成照录见原文。方义：龙眼肉、枣仁养血安神，龙骨、牡蛎、赭石重镇潜阳，半夏、茯苓化痰饮，共成养血镇心、化痰安神之方。）若服一两剂后无效，可在汤药之外，临睡时用开水送服西药臭剥一片，借其麻痹神经之力收一时之效，使汤剂易于发挥作用。方书说：痰饮停于心下，其人多惊悸不寐。因为心属火，痰饮属水，火畏水刑，所以惊悸以至于不寐。"}, {"source": "条356｜《备急千金要方》卷三·竹叶汤", "原文": "竹叶汤  \n《备急千金要方》卷三：竹叶汤。治产后心中烦闷不解方。  \n生淡竹叶、麦门冬各一升  甘草二两  生姜、茯苓各三两  大枣十四枚  小麦五合  \n上七味，㕮咀，以水一斗，先煮竹叶、小麦，取八升，纳诸药，煮取三升，去滓，分三服。若心中虚悸者，加人参二两。", "白话": "《备急千金要方》卷三载：竹叶汤。主治产后心中烦闷不解之方。（组成照录见原文。方义：竹叶、小麦清心除烦，麦冬养阴，茯苓、甘草、大枣、生姜健脾和中，共成清心除烦、和中安神之剂。）上七味药切碎，用水一斗，先煮竹叶、小麦，取八升，放入诸药，煮取三升，去药滓，分三次服。若心中虚悸的，加人参二两。"}, {"source": "条357｜《备急千金要方》卷三·淡竹茹汤", "原文": "淡竹茹汤  \n《备急千金要方》卷三：淡竹茹汤。治产后虚烦，头痛、短气欲绝，心中闷乱不解方。  \n生淡竹茹一升  麦门冬、小麦各五合  甘草一两  生姜三两，《产宝》用干葛  大枣十四枚，《产宝》用石膏三两  \n上六味，㕮咀，以水一斗煮竹茹、小麦，取八升，去滓，纳诸药，煮取一升，去滓，分二服，羸人分作三服，若有人参，入一两，若无人参，纳茯苓一两半亦佳。人参、茯苓皆治心烦闷及心虚惊悸，安定精神，有则为", "白话": "《备急千金要方》卷三载：淡竹茹汤。主治产后虚烦、头痛、短气欲绝、心中闷乱不解之方。（组成照录见原文。方义：竹茹清热除烦止呕，麦冬、小麦养心阴，甘草、生姜、大枣和中，共成清热养阴、和中除烦之剂。）上六味药切碎，用水一斗煮竹茹、小麦，取八升，去滓，放入诸药，煮取一升，去滓，分二服，瘦弱人分三服。若有人参加一两；若无人参，纳入茯苓一两半也好。人参、茯苓都治心烦闷及心虚惊悸、安定精神，有则为良，无则照方服一剂，不愈再作。"}, {"source": "条358｜《备急千金要方》卷十三·竹沥汤", "原文": "竹沥汤  \n《备急千金要方》卷十三：竹沥汤。治心实热，惊梦喜笑恐畏悸惧不安方。  \n淡竹沥一升  生地黄汁一升  石膏八两  芍药、白术、栀子仁、人参各三两  赤石脂、紫菀、知母、茯神各二两  \n上十一味，㕮咀，以水九升煮十味至二升七合，去滓，下竹沥更煎，取三升。  \n若须利入芒硝二两，去芍药，分三服。", "白话": "《备急千金要方》卷十三载：竹沥汤。主治心经实热、惊梦喜笑、恐畏悸惧不安之方。（组成照录见原文。方义：竹沥、生地汁清热化痰养阴，石膏、知母清实热，栀子清心，人参、白术、茯神益气安神，赤石脂、紫菀收敛下气，共成清心泻火、化痰安神之剂。）上十一味药切碎，用水九升煮十味至二升七合，去滓，下竹沥再煎，取三升。若需泻下则加芒硝二两，去芍药，分三服。"}, {"source": "条359｜《千金翼方》卷六·竹叶汤", "原文": "竹叶汤  \n《千金翼方》卷六：竹叶汤。主产后心烦闷不解方。  \n生淡竹叶切、麦门冬去心、小麦各一升  大枣十四枚，擘 茯苓、生姜切，各三两  甘草炙，二两  \n上七味，㕮咀，以水一斗，先煮竹叶小麦取八升，纳诸药，煮取三升，分为三服。若心中虚悸者，加人参二两；若其人食少无气力者，可更加白粳米五合；气逆者加半夏二两。", "白话": "《千金翼方》卷六载：竹叶汤。主治产后心烦闷不解之方。（组成照录见原文。方义：与《千金要方》竹叶汤同法，竹叶、小麦清心，麦冬养阴，姜枣苓草和中。）上七味药切碎，用水一斗，先煮竹叶、小麦取八升，放入诸药，煮取三升，分三服。若心中虚悸的，加人参二两；若其人食少无气力的，可再加白粳米五合；气逆的加半夏二两。"}, {"source": "条360｜《千金翼方》卷六·淡竹茹汤", "原文": "淡竹茹汤  \n《千金翼方》卷六：淡竹茹汤。主产后虚烦，头痛短气欲死，心中闷乱不起方。  \n生淡竹茹一升  麦门冬五合，去心  小麦五合  大枣十四枚，一方用石膏  生姜三两，切，一方用干姜  甘草炙，一两  \n上六味，㕮咀，以水八升煮竹茹、小麦，减一升，仍纳诸药，更煮二升，分为二服，羸人分为三服，若有人参，纳一两，若无人参，纳茯苓一两半亦佳。人参、茯苓皆治心烦闷及心惊悸，安定精神，有即为良，无自依", "白话": "《千金翼方》卷六载：淡竹茹汤。主治产后虚烦、头痛短气欲死、心中闷乱不起之方。（组成照录见原文。方义：竹茹清热除烦，麦冬、小麦养心，姜枣草和中，与《千金要方》淡竹茹汤同法。）上六味药切碎，用水八升煮竹茹、小麦，减少一升，再放诸药，更煮取二升，分二服，瘦弱人分三服。若有人参，纳入一两；若无人参，纳入茯苓一两半也好。人参、茯苓都治心烦闷及心惊悸、安定精神，有则为良，无则照本方服一剂，不愈再服。若气逆的加半夏二两，洗去滑。"}, {"source": "条361｜《外台秘要》卷十九·竹叶汤", "原文": "竹叶汤  \n《外台秘要》卷十九：又凡人入八月，气自渐定，非意气大发者，作半夏独活汤，多唾或睡觉心忪心闷，风热故也。竹叶汤食后服之为佳，如不已，作后汤服。  \n麦门冬三两，去心  茯苓二两  石膏四两，碎  小麦五合  竹叶切，一升  生姜二两  \n上六味切，以水五升，煮取一升二合，食后分再服，相去七八里久。忌酢物。", "白话": "《外台秘要》卷十九载：凡人进入八月，气自然渐定，若非意气大发的，作半夏独活汤；多唾或睡觉时心忪心闷，是风热之故。竹叶汤食后服为佳，如不愈，作后面汤药服。（组成照录见原文。方义：竹叶、小麦清心除烦，麦冬养阴，茯苓、生姜、石膏清热和中，为风热扰心之轻剂。）上六味切，用水五升，煮取一升二合，食后分两次服，相隔七八里路的工夫。忌酸酢之物。"}, {"source": "条362｜《外台秘要》卷三十四·无名方", "原文": "无名方  \n《外台秘要》卷三十四：千金疗妇人产后气欲绝，心中烦闷不解，必效方。  \n竹叶切、麦门冬去心、小麦各一升  甘草一两，炙  生姜二两  大枣十四枚  \n上六味切，以水一斗煮竹叶小麦，取八升去滓，纳余药煮，取三升去滓，分服，心虚悸，加人参二两，少气力，加粳米五合，一方用竹皮，若胸中气逆，加半夏二两，忌如常法。", "白话": "《外台秘要》卷三十四载：千金治疗妇人产后气欲绝、心中烦闷不解，必效方。（组成照录见原文。方义：竹叶、麦冬、小麦清心养阴除烦，甘草、生姜、大枣和中，为产后虚烦之基本方。）上六味切，用水一斗煮竹叶、小麦，取八升去滓，放余药煮，取三升去滓，分服。心虚悸加人参二两，少气力加粳米五合；一方用竹皮；若胸中气逆，加半夏二两。忌如常法。"}, {"source": "条363｜《太平圣惠方》卷四·小草散", "原文": "小草散  \n《太平圣惠方》卷四：治心风烦热，恍惚，狂言妄语，时复惊恐，不自觉知，发作有时，宜服小草散方。  \n小草一两  柏子仁一两  犀角屑半两  赤茯苓一两  铁精一两，细研  龙齿三分，细研  天竺黄一两，细研  生干地黄一两  琥珀末一两，细研  \n上件药，捣细罗为散，入研了药，令匀。每服不计时候，以竺黄（竹叶）汤调下一钱。", "白话": "《太平圣惠方》卷四载：治心风烦热、恍惚、狂言妄语、时复惊恐、不自觉知、发作有时，宜服小草散方。（组成照录见原文。方义：小草（远志苗）配柏子仁、琥珀、龙齿安神定志，犀角、生地、天竺黄清心凉血，赤茯苓、铁精镇心化痰，共成清心镇惊之剂。）上药捣细罗为散，加入研好的药，拌匀。每服不论时候，用竺黄（竹叶）汤调下一钱。"}, {"source": "条364｜《太平圣惠方》卷四·沙参散", "原文": "沙参散  \n《太平圣惠方》卷四：治心风虚悸，恍惚多忘，惊恐，宜服沙参散方。  \n沙参三分，去芦头  白茯苓三分  远志半两，去心 犀角屑半两 甘草半两，炙微赤，锉  防风半两，去芦头  龙齿一两  天门冬一两，去心  生干地黄一两  \n上件药，捣粗罗为散。每服三钱，以水一中盏，入生姜半分，枣二枚，煎至六分。去滓，不计时候温服。", "白话": "《太平圣惠方》卷四载：治心风虚悸、恍惚多忘、惊恐，宜服沙参散方。（组成照录见原文。方义：沙参、天冬、生地滋阴，茯苓、甘草健脾，远志、龙齿安神定志，犀角清心，防风散风，共成养阴祛风、安神定悸之剂。）上药捣粗罗为散。每服三钱，用水一中盏，入生姜半分、枣二枚，煎至六分。去滓，不论时候温服。"}, {"source": "条365｜《圣济总录》卷四十三·乌犀汤", "原文": "乌犀汤  \n《圣济总录》卷四十三：治心脏烦热，睡即多惊，心忪不欲见人，乌犀汤方。  \n犀角镑，八钱  龙齿、升麻各一两  茯神去木，一两半  麦门冬去心，焙，二两玄参一两  栝蒌根锉，焙，三两  赤芍药一两半  \n上八味，粗捣筛，每服三钱匕。水一盏，入马牙硝半钱匕，生地黄五七寸拍碎，同煎至七分，去滓温服。", "白话": "《圣济总录》卷四十三载：治心脏烦热、睡即多惊、心忪不欲见人，用乌犀汤方。（组成照录见原文。方义：犀角、赤芍、玄参清心凉血，龙齿、茯神镇心安神，麦冬、栝蒌根养阴生津，升麻散火，共成清心凉血、安神定志之剂。）上八味药粗捣筛，每服三钱匕。用水一盏，入马牙硝半钱匕、生地黄五七寸拍碎，同煎至七分，去滓温服。"}, {"source": "条366｜《圣济总录》卷五十八·麦门冬丸", "原文": "麦门冬丸  \n《圣济总录》卷五十八：治消渴，口干喜饮水，小便数。心烦闷、健忘怔忪，麦门冬丸方。  \n麦门冬去心，焙、土瓜根锉、山茱萸、鹿茸酒浸，炙，去毛、牛膝去苗，锉、狗脊碎，锉，去毛、茯神去木、人参各一两  黄连去须、菟丝子酒浸一宿，曝干，别捣为末，各一两半  龙骨烧、牡蛎煅，各三分  \n上一十二味，捣罗为末，炼蜜丸。  \n如梧桐子大，每服二十丸，不拘时、煮小麦饮下。加至三十丸。", "白话": "《圣济总录》卷五十八载：治消渴、口干喜饮水、小便数，兼心烦闷、健忘怔忪，用麦门冬丸方。（组成照录见原文。方义：麦冬、土瓜根滋阴生津，山茱萸、鹿茸、菟丝子、狗脊、牛膝补肾固精，黄连清热，人参、茯神益气安神，龙骨、牡蛎潜镇，共成滋阴清热、补肾安神之剂。）上十二味药捣罗为末，炼蜜为丸。如梧桐子大，每服二十丸，不拘时候，煮小麦饮送下。加至三十丸。"}, {"source": "条367｜《圣济总录》卷八十七·鳖甲饮", "原文": "鳖甲饮  \n《圣济总录》卷八十七：治急劳肌瘦壮热，心忪战掉，鳖甲饮方。  \n鳖甲去裙襕醋炙，半分  豉去皮，一分  甘草量病人中指长用  青蒿干者一握  桃仁七粒，汤浸去皮尖双仁生研  葱并须三茎，切  \n上六味细锉，每服五钱匕，以童子小便二盏，煎至一盏，去滓空心温服，避风取汗。", "白话": "《圣济总录》卷八十七载：治急劳肌肉消瘦、壮热、心忪战掉，用鳖甲饮方。（组成照录见原文。方义：鳖甲滋阴清热，青蒿、豆豉透热，桃仁活血，葱须通阳，甘草和中，童便为引取降火凉血之义。）上六味细锉，每服五钱匕，用童子小便二盏，煎至一盏，去滓空心温服，避风取汗。"}, {"source": "条368｜《圣济总录》卷八十八·胡黄连汤", "原文": "胡黄连汤  \n《圣济总录》卷八十八：治虚劳寒热心忪，骨节酸疼，胡黄连汤方。  \n胡黄连、柴胡去苗、鳖甲去裙襕醋炙、甘草炙锉、白蒺藜炒、黄芪、附子炮裂去皮脐，各半两  威灵仙去土，一两  \n上八味，锉如麻豆，每服三钱匕，水一盏，童子小便酒共半盏，乌梅一枚拍碎，同煎至一盏，去滓不拘时候温服。", "白话": "《圣济总录》卷八十八载：治虚劳寒热心忪、骨节酸疼，用胡黄连汤方。（组成照录见原文。方义：胡黄连、柴胡、鳖甲清虚热，黄芪益气，白蒺藜、威灵仙祛风通络，附子温经，甘草和中，共成清虚热、益气血、通经络之剂。）上八味药锉如麻豆，每服三钱匕，用水一盏，童子小便与酒共半盏，乌梅一枚拍碎，同煎至一盏，去滓不拘时候温服。"}, {"source": "条369｜《圣济总录》卷九十三·麦门冬汤", "原文": "麦门冬汤  \n《圣济总录》卷九十三：治心中烦热，唯欲露体，复之即闷烦，惊悸心忪，面无颜色，忘前失后，妇人患血风气者，多成此疾，乃心蒸之状，麦门冬汤方。  \n麦门冬去心，焙、茯神去木、防风去叉、地骨皮去土，各三两  人参、龙齿、远志去心、甘草炙黄、羚羊角屑、石膏各二两  紫石英一两  \n上一十一味，各锉如麻豆大，每服三钱匕，以水一盏半，入枣两枚，煎取半盏，去滓温服，服一剂，未全安再作之，以瘥为度，甚", "白话": "《圣济总录》卷九十三载：治心中烦热、只想裸露身体、覆盖即闷烦、惊悸心忪、面无颜色、忘前失后；妇人患血风气的多成此病，这是心蒸之状，用麦门冬汤方。（组成照录见原文。方义：麦冬、地骨皮、石膏养阴清热，人参、茯神、远志、龙齿益气安神，羚羊角清心，防风散风，紫石英镇心，共成养阴清心、安神定志之剂。）上十一味各锉如麻豆大，每服三钱匕，用水一盏半，入枣两枚，煎取半盏，去滓温服。服一剂未全安再作，以愈为度，甚益心力；曾经吐血的服之尤佳。若畏石药，不用紫石英也好。"}, {"source": "条370｜《圣济总录》卷一百六十八·天南星丸", "原文": "天南星丸  \n《圣济总录》卷一百六十八：治小儿夹热，痰盛温壮，夜卧不稳，天南星丸方。  \n天南星炮为末、半夏汤洗七遍，焙为末、腻粉研、滑石研，各一钱、巴豆二十四枚，去心膜，以水浸一宿，研细不出油  \n上五味，先研巴豆令熟，次下众药末，以糯米粥和丸，如绿豆大，每服三丸，更量儿大小加减，泻痢米饮下，取食葱汤下，惊悸薄荷荆芥汤下。", "白话": "《圣济总录》卷一百六十八载：治小儿夹热、痰盛温壮、夜卧不稳，用天南星丸方。（组成照录见原文。方义：天南星、半夏化痰，腻粉、滑石、巴豆攻痰逐水，为小儿痰热惊悸之峻剂。）上五味，先研巴豆令熟，次下众药末，以糯米粥和丸，如绿豆大。每服三丸，按儿大小加减：泻痢用米饮下，取食用葱汤下，惊悸用薄荷荆芥汤下。"}, {"source": "条371｜《圣济总录》卷一百八十五·清心丸", "原文": "清心丸  \n《圣济总录》卷一百八十五：治热盛梦泄，怔忪恍惚，膈壅舌干，清心丸方。  \n黄柏去粗皮，锉，一两  \n上一味，捣罗为末，入龙脑一钱匕同研匀。炼蜜和丸如梧桐子大，每服十丸至十五丸，浓煎麦门冬汤下。", "白话": "《圣济总录》卷一百八十五载：治热盛梦泄、怔忪恍惚、膈壅舌干，用清心丸方。（组成照录见原文。方义：黄柏一味清下焦湿热、坚阴，佐龙脑芳香开窍，麦冬汤送下养阴清心，为清心止遗之小方。）上一味药捣罗为末，加入龙脑一钱匕同研匀。炼蜜和丸如梧桐子大，每服十丸至十五丸，浓煎麦门冬汤送下。"}, {"source": "条372｜《古今医统大全》卷八十九·龙胆丸", "原文": "龙胆丸  \n《古今医统大全》卷八十九：龙胆丸。治小儿心疳，颊赤面黄，鼻干心燥，口内生疮，惊悸。  \n龙胆草 赤茯苓 川黄连 胡黄连 朱砂二钱 麝香一字  \n上为极细末，蒸饼泡为丸，黍米大。每服二十丸，食远白汤下。", "白话": "《古今医统大全》卷八十九载：龙胆丸。主治小儿心疳，颊赤面黄，鼻干心燥，口内生疮，惊悸。（组成照录见原文。方义：龙胆草、黄连、胡黄连清心肝疳热，赤茯苓利湿，朱砂、麝香镇心开窍，为清疳热、定惊悸之剂。）上药研为极细末，蒸饼泡为丸，黍米大。每服二十丸，食远白汤送下。"}, {"source": "条373｜《幼幼新书》卷八·茯神散", "原文": "茯神散  \n《幼幼新书》卷八：《圣惠》治小儿心惊悸、烦乱，茯神散方。  \n茯神、川升麻各三分  龙齿、甘草炙微赤，锉，各半两  寒水石、石膏、麦门冬去心焙，各一两  \n上件药捣，粗罗为散。每服一钱，以水一小盏，煎至五分，去滓，入竹沥半合，更煎二沸。量儿大小，以意加减。", "白话": "《幼幼新书》卷八引《圣惠》：治小儿心惊悸、烦乱，用茯神散方。（组成照录见原文。方义：茯神、麦冬宁心养阴，龙齿镇惊，石膏、寒水石清热，升麻散火，甘草和中，竹沥化痰，共成清心镇惊之剂。）上药捣，粗罗为散。每服一钱，用水一小盏，煎至五分，去滓，加入竹沥半合，再煎两沸。按儿大小随意加减。"}, {"source": "条374｜《明医指掌》卷七·戊字号保真汤", "原文": "戊字号保真汤  \n《明医指掌》卷七：戊字号保真汤。治劳证骨蒸体热而虚。  \n当归三分，酒洗 人参三分，去芦 生地黄三分 熟地黄三分 白术三分，炒 黄芪三分，蜜炙 赤茯苓三分 白茯苓三分 天冬二分，去心 麦冬二分，去心 赤芍药分半 白芍药分半 知母二分，盐炒 黄柏二分，盐炒 五味子二分 甘草一分半 陈皮一分半 柴胡二分 地骨皮二分  \n上，用水二盏，姜三片，枣五枚，莲心五个，每日三食前各进一服。惊悸", "白话": "《明医指掌》卷七载：戊字号保真汤。主治劳证骨蒸、体热而虚。（组成照录见原文。方义：四君四物合黄芪益气补血，二冬、二地、知母、黄柏滋阴降火，柴胡、地骨皮退蒸热，五味子敛阴，为气血双补、滋阴退蒸之剂。）上药用水二盏，姜三片，枣五枚，莲心五个，每日三餐前各进一服。惊悸加茯苓、茯神、远志、枣仁。"}, {"source": "条375｜《幼幼新书》卷三十九·仙人炼绛雪", "原文": "仙人炼绛雪  \n《幼幼新书》卷三十九：《外台》仙人炼绛雪。疗一切病。肺气积聚，咳逆呕吐脓血；丹石毒发；天行时气，一切热病诸黄疸等；心风昏乱、心忪健忘：四肢烦热、头痛眼赤，大小便不通，烦闷不安，骨节疼痛，赤白痢、血痢、热毒痢，宿食不消化，心腹胀满，出气不得；下一切诸毒药，脚气等；饮酒多醉困，久痢不瘥：孩子惊痫等。以上和水服之。产后一切诸病堕胎和酒服之方。  \n朴硝十斤  升麻三两  大青、桑白皮、槐", "白话": "《幼幼新书》卷三十九引《外台》仙人炼绛雪。治疗一切病：肺气积聚、咳逆呕吐脓血；丹石毒发；天行时气、一切热病诸黄疸等；心风昏乱、心忪健忘；四肢烦热、头痛眼赤，大小便不通，烦闷不安，骨节疼痛，赤白痢、血痢、热毒痢，宿食不消化，心腹胀满，出气不得；下一切诸毒药，脚气等；饮酒多醉困，久痢不愈；孩子惊痫等。以上都和水服。产后一切诸病、堕胎和酒服之方。（组成照录见原文。方义：朴硝、硝石咸寒泻下，升麻、大青、槐花、栀子清热凉血，犀角、羚羊角清心，槟榔、诃黎勒下气，朱砂、麝香镇心开窍，为清热"}, {"source": "条376｜《妇人大全良方》卷二十·无名方", "原文": "无名方  \n《妇人大全良方》卷二十：疗妇人产后短气欲绝，心中烦闷不解。必效方。  \n竹叶切、麦门冬、小麦各一升  甘草一两  生姜二两  大枣十四个  \n上六味细切，以水一斗，煮竹叶、小麦，取八升去滓；内余药，煮取三升，去滓温服。若虚悸，加人参二两；少气力，加粳米五合。一方用竹皮，若胸中气逆，加半夏二两。忌如常法与竹根汤、淡竹茹汤大同小异。", "白话": "《妇人大全良方》卷二十载：治疗妇人产后短气欲绝、心中烦闷不解。必效方。（组成照录见原文。方义：竹叶、麦冬、小麦清心养阴除烦，草姜枣和中，与《外台》所载同法。）上六味细切，用水一斗，煮竹叶、小麦，取八升去滓；放入余药，煮取三升，去滓温服。若虚悸加人参二两；少气力加粳米五合。一方用竹皮；若胸中气逆，加半夏二两。忌如常法。与竹根汤、淡竹茹汤大同小异。"}, {"source": "条377｜《世医得效方》卷七·清心丸", "原文": "清心丸  \n《世医得效方》卷七：清心丸。治经络热而梦泄，心怔怔恍惚。  \n大柏皮一两，去粗皮  \n上为末，入脑子一钱同研，炼蜜丸如梧子大。每服十五丸至十九丸，浓煎去心麦门冬汤下。", "白话": "《世医得效方》卷七载：清心丸。主治经络有热而梦泄、心怔怔恍惚。（组成照录见原文。方义：柏皮（黄柏）清热坚阴，佐脑子（冰片）开窍，麦冬汤下养阴，为清经络热、止梦泄之剂。）上药研为末，加入脑子一钱同研，炼蜜丸如梧子大。每服十五丸至十九丸，浓煎去心麦门冬汤送下。"}, {"source": "条378｜《世医得效方》卷九·淡竹茹汤", "原文": "淡竹茹汤  \n《世医得效方》卷九：淡竹茹汤。治心虚烦闷，头疼，气短，内热不解，心中闷乱。及妇人产后，心虚，惊悸，烦闷欲绝。  \n麦门冬去心、小麦各二两半 甘草炙，一两 人参、白茯苓各一两半 半夏汤洗七次，二两  \n上锉散。每服四钱，水二盏，生姜七片，枣子三枚，淡竹茹一块如指大同煎，食煎服。虚劳烦闷，尤宜服之。", "白话": "《世医得效方》卷九载：淡竹茹汤。主治心虚烦闷、头疼、气短、内热不解、心中闷乱；及妇人产后心虚、惊悸、烦闷欲绝。（组成照录见原文。方义：竹茹清热除烦，麦冬、小麦养心，参苓夏草益气化痰和中，为清补兼施之剂。）上药锉散。每服四钱，用水二盏，生姜七片、枣子三枚、淡竹茹一块如指大同煎，食前服。虚劳烦闷尤其适宜。"}, {"source": "条379｜《医学纲目》卷二十九·清心丸", "原文": "清心丸  \n《医学纲目》卷二十九：《本》治经络热梦遗，心忪恍惚膈热，清心丸。  \n用好黄柏皮一两，研为细末，生脑子一钱，同研匀，炼蜜为丸，如桐子大，每服十丸至十五丸，浓煎麦门冬汤吞下。", "白话": "《医学纲目》卷二十九引《本事》：治经络有热、梦遗、心忪恍惚、膈热，用清心丸。（组成照录见原文。方义：黄柏清热坚阴，龙脑开窍，麦冬汤送下养阴清心。）用好黄柏皮一两研为细末，生脑子一钱同研匀，炼蜜为丸如桐子大，每服十丸至十五丸，浓煎麦门冬汤吞下。"}, {"source": "条380｜《普济方》卷十六·沙参散", "原文": "沙参散  \n《普济方》卷十六：沙参散永类钤方。 治心实热。惊悸喜笑。心神不安。泄热安心。  \n沙参去芦头、白薇、川芒硝、茯神、栀子仁、羚羊角屑、子芩各一两 石膏二两半 人参三分，去芦头 甘草半两，炙微赤锉  \n上为粗散。每服三钱。水一中盏。煎五分。去滓。入生地黄汁一合。竹沥半合。更煎一两沸。每于食后温服。忌炙爆热面。", "白话": "《普济方》卷十六载：沙参散（出《永类钤方》）。治心经实热，惊悸喜笑，心神不安，能泄热安心。（组成照录见原文。方义：沙参、白薇养阴清热，芒硝、栀子、子芩、石膏、羚羊角清心泻火，茯神、人参、甘草安神和中，为泄热安心之剂。）上药为粗散。每服三钱。用水一中盏，煎五分，去滓。加入生地黄汁一合、竹沥半合，再煎一两沸。每于食后温服。忌炙爆热面。"}, {"source": "条381｜《普济方》卷十六·定心丸", "原文": "定心丸  \n《普济方》卷十六：定心丸。治实热在内，狂妄不常。  \n硝石半两 丹砂一分钱  \n上细研，糯米粥和丸，如樱桃大，每服一丸，生糯米汁入油一两，点青柳枝，打匀服。", "白话": "《普济方》卷十六载：定心丸。主治实热在内，狂妄不常。（组成照录见原文。方义：硝石咸寒攻下，丹砂（朱砂）镇心安神，二药相配泻实热、镇心神。）上药细研，糯米粥和丸如樱桃大，每服一丸，用生糯米汁加入油一两，点青柳枝，打匀服。"}, {"source": "条382｜《普济方》卷二百八十六·解毒丸", "原文": "解毒丸  \n《普济方》卷二百八十六：解毒丸。治中外诸邪毒痈肿疮，筋脉拘挛，寝汗咬牙，一切惊悸热毒。  \n大黄、黄连、栀子、黄芩各五钱 牵牛、滑石各一两  \n上为细末，滴水为丸，如梧桐子大，每服三四十丸，温水送下，加减用服之。", "白话": "《普济方》卷二百八十六载：解毒丸。主治内外诸邪毒痈肿疮疡，筋脉拘挛，寝汗咬牙，一切惊悸热毒。（组成照录见原文。方义：大黄、黄连、黄芩、栀子清热泻火解毒，牵牛、滑石攻下利水，使热毒从二便而解。）上药为细末，滴水为丸如梧桐子大，每服三四十丸，温水送下，随证加减。"}, {"source": "条383｜《奇效良方》卷三十一·金珠化痰丸", "原文": "金珠化痰丸  \n《奇效良方》卷三十一：金珠化痰丸。治痰热，安神志，除头痛眩晕，心忪恍惚，胁膈烦闷，涕唾稠黏，咳嗽咽嗌不利。  \n皂角子仁炒、天竺黄另研、半夏汤浸洗七次，生姜二两，去皮，同捣作饼，炙微黄、白矾明者枯过，另研，以上各四两 龙脑另研，半两 辰砂水飞，研，二两  \n上将皂角仁半夏为末，与诸药研匀，生姜汁煮面糊和丸，如梧桐子大，金箔二十片为衣，每服十五丸，加至二十五丸，食后用生姜汤送下。", "白话": "《奇效良方》卷三十一载：金珠化痰丸。主治痰热，安神志，除头痛眩晕、心忪恍惚、胁膈烦闷、涕唾稠黏、咳嗽咽喉不利。（组成照录见原文。方义：半夏、皂角子仁、白矾化痰，天竺黄、龙脑清热豁痰开窍，辰砂、金箔镇心安神，生姜汁和丸，共成清热化痰、镇心安神之剂。）上将皂角仁、半夏为末，与诸药研匀，生姜汁煮面糊和丸如梧桐子大，金箔二十片为衣，每服十五丸，加至二十五丸，食后用生姜汤送下。"}, {"source": "条384｜《奇效良方》卷六十四·辰砂胆星膏", "原文": "辰砂胆星膏  \n《奇效良方》卷六十四：辰砂胆星膏。治小儿痰热惊热，气急喘嗽，惊悸不安。  \n辰砂一钱 牛胆南星一两 琥珀、青礞石末各一钱 天竺黄一钱 甘草五分 麝香少许  \n上为细末，炼蜜为丸，如芡实大，每服半丸，用生姜汤不拘时化服。", "白话": "《奇效良方》卷六十四载：辰砂胆星膏。主治小儿痰热惊热、气急喘嗽、惊悸不安。（组成照录见原文。方义：牛胆南星、天竺黄、青礞石清热化痰，辰砂、琥珀镇心安神，甘草调和，炼蜜为膏，为小儿痰热惊悸之剂。）上药为细末，炼蜜为丸如芡实大，每服半丸，用生姜汤不拘时候化服。"}, {"source": "条385｜《原幼心法》中卷·安神丸", "原文": "安神丸  \n《原幼心法》中卷：惊热者，遍身发热，面青白，自汗，心悸不宁，脉数，烦躁，颠叫恍惚，以钱氏凉惊丸、安神丸主之。", "白话": "《原幼心法》中卷载：惊热之证，遍身发热，面色青白，自汗，心悸不宁，脉数，烦躁，颠叫恍惚，用钱乙凉惊丸、安神丸主治。"}, {"source": "条386｜《医学正传》卷五·惊悸养血汤", "原文": "惊悸养血汤  \n《医学正传》卷五：惊悸养血汤局方。治肥人因痰火而心惕然跳动惊起。  \n黄芪、茯神、半夏曲、川芎各五分 远志去心，甘草水浸、桂心、柏子仁、酸枣仁炒、五味子、人参各二分半 甘草四分  \n上细切，作一服，生姜三片，大枣一枚，水一盏，煎至七分服。如停水，加茯神、槟榔各三分同煎。", "白话": "《医学正传》卷五载：惊悸养血汤（局方）。主治肥人因痰火而心惕然跳动惊起。（组成照录见原文。方义：黄芪、人参补气，当归、柏子仁、枣仁、川芎养血，半夏曲、茯神、远志化痰安神，肉桂、五味子、甘草温敛和中，共成益气养血、化痰定悸之剂。）上药细切，作一服，生姜三片、大枣一枚，水一盏，煎至七分服。如有停水，加茯苓、槟榔各三分同煎。"}, {"source": "条387｜《保婴撮要》卷二·泻心散", "原文": "泻心散  \n《保婴撮要》卷二：额间：赤色主心经有热，烦躁惊悸，若饮水或叫哭，属本经实热，用泻心散以清心火；微赤困卧惊悸，热渴饮汤，属虚热，用秘旨安神丸以生心血；青黑主惊风，腹痛或瘛疭啼叫，用五味异功散加木香、柴胡、钩藤钩补脾肝；青黑主心腹作痛，此寒水乘心，用益黄散；微黄主惊疳，用安神丸。", "白话": "《保婴撮要》卷二载：额间：赤色主心经有热，烦躁惊悸；若饮水或叫哭，属本经实热，用泻心散清心火；微赤而困卧惊悸、热渴饮汤，属虚热，用秘旨安神丸以生心血；青黑主惊风，腹痛或瘛疭啼叫，用五味异功散加木香、柴胡、钩藤钩补脾肝；青黑主心腹作痛，这是寒水乘心，用益黄散；微黄主惊疳，用安神丸。"}, {"source": "条388｜《保婴撮要》卷十三·黄连安神丸", "原文": "黄连安神丸  \n《保婴撮要》卷十三：黄连安神丸。治心经血热发热，惊悸不安。  \n黄连五分 生甘草二钱五分 生地黄五钱 当归 朱砂三钱  \n上为末，饭糊丸，小豆大。每服十五丸，滚汤下。如二三服不应，当服归脾汤，婴儿乳母并服。", "白话": "《保婴撮要》卷十三载：黄连安神丸。主治心经血热发热、惊悸不安。（组成照录见原文。方义：黄连清心火，生地、当归凉血养血，生甘草泻火和中，朱砂镇心安神，为清心凉血、安神定悸之剂。）上药为末，饭糊为丸，小豆大。每服十五丸，滚汤送下。如服二三剂不应，当服归脾汤，婴儿与乳母并服。"}, {"source": "条389｜《扶寿精方·痰门》·清热化痰丸", "原文": "清热化痰丸  \n《扶寿精方·痰门》：清热化痰丸。治痰饮为患，恶心头眩，心悸，中脘不快，或因食生冷饮酒过多，脾胃不和。  \n半夏汤泡七次，五钱 陈皮去白，四钱 白茯苓、当归酒洗、川芎各三钱 黄芩酒炒、生甘草、栀子各一钱半，去杇 黄连去毛炒，一钱  \n上为细末，面糊丸，梧桐子大，食远白汤下，五十丸。", "白话": "《扶寿精方·痰门》载：清热化痰丸。主治痰饮为患，恶心头眩，心悸，中脘不快；或因食生冷、饮酒过多，脾胃不和。（组成照录见原文。方义：二陈汤（半夏、陈皮、茯苓、甘草）化痰和中，黄芩、黄连、栀子清热，当归、川芎养血和血，为清热化痰、和胃止悸之剂。）上药为细末，面糊为丸，梧桐子大，食远白汤送下五十丸。"}, {"source": "条390｜《赤水玄珠》卷九·龙脑鸡苏丸", "原文": "龙脑鸡苏丸  \n《赤水玄珠》卷九：海藏龙脑鸡苏丸。治上焦热，除烦解劳，去肺热咳衄，血热惊悸，脾胃口疳，吐血，肝胆热，泣出口苦，肾热神志不定。上而酒毒，膈热，消渴。下而血滞，五淋，血崩等疾。  \n薄荷一斤 麦门冬去心、阿胶炒、黄芪、薄黄炒、人参已上俱净药、木通、银柴胡各二两，锉，同木通浸一宿，绞出汁 生地黄六两 甘草一两五钱 黄连一两  \n上为细末，好蜜二升，先煎一二沸，然后下生地黄末，不住手搅匀，", "白话": "《赤水玄珠》卷九载：海藏龙脑鸡苏丸。主治上焦热，除烦解劳，去肺热咳衄，血热惊悸，脾胃口疳，吐血，肝胆热，流泪口苦，肾热神志不定。上而酒毒、膈热、消渴，下而血滞、五淋、血崩等疾。（组成照录见原文。方义：薄荷、鸡苏清上焦热，麦冬、生地、阿胶滋阴凉血，黄芪、人参益气，黄连清心，银柴胡、木通疏利，为清上焦、凉血热、益气阴之剂。）上药为细末，用好蜜二升先煎一二沸，然后下生地黄末，不住手搅匀，加木通、柴胡汁浸熬成膏，勿火力过猛煎焦，然后加入前药末和丸如豌豆大。每服二十丸，白汤送下。虚劳虚"}, {"source": "条391｜《医学入门·外集》·小调中汤", "原文": "小调中汤  \n《医学入门·外集》：凡咽痛喉闭，膈噎胸痞，癫狂惊悸，怔忡健忘之类，皆痰火滞中之所为也，小调中汤，大调中汤。", "白话": "《医学入门·外集》载：凡咽痛喉闭、膈噎胸痞、癫狂惊悸、怔忡健忘之类，都是痰火滞于中焦所致，用小调中汤、大调中汤。"}, {"source": "条392｜《医学入门·外集》·妙香散", "原文": "妙香散  \n《医学入门·外集》：七情怔悸虫不定，九种：悸痛、虫痛、来去痛、疰痛、饮痛、食痛、风痛、冷痛、热痛。悸痛，内因七情，轻则怔忡惊悸，似痛非痛，妙香散、四七汤、小草丸，热者连附六一汤；重则两目赤黄，手足青至食，即真痛，不治。虫痛，湿热生虫攻心，痛发难当，痛定能食，饥则临沐，灵槟散、乌梅丸、化虫丸选用。", "白话": "《医学入门·外集》载：七情所致怔悸与虫痛等九种心痛：悸痛、虫痛、来去痛、疰痛、饮痛、食痛、风痛、冷痛、热痛。悸痛，内因七情，轻则怔忡惊悸，似痛非痛，用妙香散、四七汤、小草丸，热者用连附六一汤；重则两目赤黄，手足青冷至肘膝，即是真心痛，不治。虫痛，是湿热生虫攻心，疼痛难当，痛止能食，饥则发作，用灵槟散、乌梅丸、化虫丸选用。"}, {"source": "条393｜《仁术便览》卷一·竹叶石膏汤", "原文": "竹叶石膏汤  \n《仁术便览》卷一：竹叶石膏汤。治伤寒汗下后，表里俱虚，津液枯竭，余热不解，心烦不眠，或气逆欲吐，及诸虚烦热并宜服之。  \n石膏 淡竹叶 麦门冬 粳米百余粒 半夏 人参 甘草  \n阴虚甚者加知母、黄柏、川芎、地黄。惊悸不宁、盗汗，加酸枣仁、茯神。小便不利，加栀子。气短无力，加人参、黄芪。上水一钟半煎。", "白话": "《仁术便览》卷一载：竹叶石膏汤。主治伤寒汗下之后，表里俱虚，津液枯竭，余热不解，心烦不眠，或气逆欲吐，以及诸虚烦热都宜服。（组成照录见原文。方义：竹叶、石膏清余热，麦冬、粳米养阴和胃，半夏降逆，人参、甘草益气，为清热生津、益气和胃之剂。）阴虚甚者加知母、黄柏、川芎、地黄；惊悸不宁、盗汗，加酸枣仁、茯神；小便不利加栀子；气短无力加人参、黄芪。上药用水一钟半煎。"}, {"source": "条394｜《万病回春》卷四·滋阴降火汤", "原文": "滋阴降火汤  \n《万病回春》卷四：滋阴降火汤。治阴虚火动，发热咳嗽，吐痰喘急，盗汗口干。此方与六味地黄丸相兼服之，大补虚劳，神效。  \n当归酒洗，一钱二分 白芍酒洗，二钱三分 生地黄八分 熟地黄姜汁炒、天门冬去心、麦门冬去心、白术去芦，各一钱 陈皮七分 黄柏去皮，蜜水炒、知母各五分 甘草炙，五分  \n上锉一剂。生姜三片，大枣一枚，水煎。临服入竹沥、童便、姜汁少许，同服。同治；痰火作热，烦躁不安，气", "白话": "《万病回春》卷四载：滋阴降火汤。主治阴虚火动，发热咳嗽，吐痰喘急，盗汗口干。此方与六味地黄丸相兼服，大补虚劳，神效。（组成照录见原文。方义：二地、二冬、白芍、当归滋阴养血，知母、黄柏降火，白术、陈皮、甘草健脾和中，共成滋阴降火之剂。）上药锉一剂。生姜三片、大枣一枚，水煎。临服时加入竹沥、童便、姜汁少许同服。同治：痰火作热，烦躁不安，气随火升，以及痰火怔忡嘈杂，加酸枣仁、黄芩、炒黄连、竹茹、辰砂、竹沥。"}, {"source": "条395｜《医学原理》卷五·保真汤", "原文": "保真汤  \n《医学原理》卷五：保真汤。治气血虚败已极，以致相火炽盛，煎熬真阴而成痨瘵、骨蒸发热、盗汗、遗精、咳嗽等症。治宜补益气血，滋阴制火为本，清热止嗽，固精为标。故用人参、白术、茯苓、甘草、黄芪、大枣等以补气，归、芍、赤茯以益血，黄柏、知母、熟地补益真阴，柴胡、地骨皮以解蒸热，天麦冬、北五味清肺金以止嗽，莲蕊固精，陈皮、生姜散逆气，以导地黄之滞。  \n人参甘温，四钱 白术苦甘温，二钱 白茯甘淡", "白话": "《医学原理》卷五载：保真汤。主治气血虚败已极，以致相火炽盛，煎熬真阴而成痨瘵、骨蒸发热、盗汗、遗精、咳嗽等症。治宜补益气血、滋阴制火为本，清热止嗽、固精为标。故用人参、白术、茯苓、甘草、黄芪、大枣等补气，当归、芍药、赤茯益血，黄柏、知母、熟地补益真阴，柴胡、地骨皮解蒸热，天冬、麦冬、北五味清肺金以止嗽，莲蕊固精，陈皮、生姜散逆气，以导地黄之滞。（组成照录见原文。方义：本方以十全大补合滋阴降火，标本兼顾，为虚劳气血两亏、阴虚火旺之调补剂。）用水五盅，煎二盅半，温服。如惊悸，加茯"}, {"source": "条396｜《医学原理》卷十三·猪心龙脑丸", "原文": "猪心龙脑丸  \n《医学原理》卷十三：猪心龙脑丸。治痘疹躁乱，谵语惊悸。此乃心经蕴热所致。法当疏散心经郁热。是以用猪心血为心经引使，梅花脑子以散心经郁热。  \n猪心血酸咸平 脑子辛凉，一钱  \n为末，用猪心血为丸绿豆大，每以井花水，或薄荷汤化下一丸。", "白话": "《医学原理》卷十三载：猪心龙脑丸。主治痘疹躁乱、谵语惊悸。这是心经蕴热所致，治法当疏散心经郁热。所以用猪心血为心经引使，梅花脑子以散心经郁热。（组成照录见原文。方义：猪心血引药入心，龙脑（冰片）辛凉散郁热，为引经清心之小方。）研为末，用猪心血为丸绿豆大，每次用井花水或薄荷汤化服一丸。"}, {"source": "条397｜《医学原理》卷十三·泻心汤", "原文": "泻心汤  \n《医学原理》卷十三：心主热，目病或大热，泻心汤主之。实则烦热，黄连泻心汤主之，虚则热惊悸，生犀散主之。", "白话": "《医学原理》卷十三载：心主热，目病或大热，用泻心汤主治。实证则烦热，用黄连泻心汤主治；虚证则热而惊悸，用生犀散主治。"}, {"source": "条398｜《万氏家抄济世良方》卷五·辰砂抱龙丸", "原文": "辰砂抱龙丸  \n《万氏家抄济世良方》卷五：辰砂抱龙丸。治小儿伤风咳嗽、痰喘烦渴、鼻流清涕、惊悸风热等症。  \n天竺黄、天花粉、茯神去皮木、明天麻各一两 胆星二两 雄黄、防风各五钱 麝香一钱半 辰砂五钱，水飞  \n为细末，甘草浓煎汁，丸芡实大，辰砂为衣。灯心薄荷汤下。伤风痰盛，紫苏姜汤下。", "白话": "《万氏家抄济世良方》卷五载：辰砂抱龙丸。主治小儿伤风咳嗽、痰喘烦渴、鼻流清涕、惊悸风热等症。（组成照录见原文。方义：天竺黄、胆星清热化痰，天麻、防风熄风，茯神、辰砂安神镇惊，雄黄、麝香辟秽开窍，天花粉生津，为小儿风热痰惊之剂。）研为细末，用甘草浓煎汁为丸，芡实大，辰砂为衣。灯心薄荷汤送下。伤风痰盛，用紫苏姜汤送下。"}, {"source": "条399｜《证治准绳·类方》·柏皮汤", "原文": "柏皮汤  \n《证治准绳·类方》：柏皮汤元戎。治衄血、吐血、呕血，皆失血虚损，形气不理，羸瘦不能食，心忪少气，燥渴发热。  \n生地黄、甘草、黄柏、白芍药各一两  \n上㕮咀，用醇酒三升，渍之一宿，以铜器盛，米饮下蒸一炊时久，渍汁半升服，食后。时对病增损。《肘后》用熟地黄，水、酒煎饮清。", "白话": "《证治准绳·类方》载：柏皮汤（元戎方）。主治衄血、吐血、呕血，凡失血虚损、形气不理、羸瘦不能食、心忪少气、燥渴发热。（组成照录见原文。方义：生地、白芍滋阴凉血，黄柏坚阴清热，甘草和中，酒渍蒸制以养血和血。）上药切碎，用醇酒三升浸一夜，以铜器盛，米饮中蒸一炊时久，取渍汁半升服，食后服。随时按病增减。《肘后方》用熟地黄，水、酒煎饮清汁。"}, {"source": "条400｜《幼科证治准绳》集二·防风丸", "原文": "防风丸  \n《幼科证治准绳》集二：防风丸。治惊风痰热，神昏惊悸。  \n天麻、防风、人参、川芎各一两 全蝎、甘草、僵蚕、朱砂、雄黄、牛胆南星各二钱五分  \n上为末，蜜丸鸡头大。每一丸，薄荷汤下。", "白话": "《幼科证治准绳》集二载：防风丸。主治惊风痰热、神昏惊悸。（组成照录见原文。方义：天麻、全蝎、僵蚕熄风止痉，防风、川芎散风，胆星、牛胆南星化痰，朱砂、雄黄镇惊辟秽，人参、甘草扶正，为熄风化痰、镇惊安神之剂。）上药为末，蜜丸鸡头大。每次一丸，薄荷汤送下。"}, {"source": "条401｜《幼科证治准绳》集三·导赤散", "原文": "导赤散  \n《幼科证治准绳》集三：钱心，主惊。实则叫哭发热，饮水而搐，虚则困卧，悸动不安。心病，多叫哭惊悸，手足动摇，发热饮水。视其睡，口中气温，或合面睡，及上窜咬牙，皆心热也，导赤散主之。", "白话": "《幼科证治准绳》集三载：钱乙谓心主惊。实证则叫哭发热，饮水而抽搐；虚证则困卧、悸动不安。心病多叫哭惊悸、手足动摇、发热饮水。看其睡时口中气温，或合面睡，以及上窜咬牙，都是心热，用导赤散主治。"}, {"source": "条402｜《幼科证治准绳》集四·无名方", "原文": "无名方  \n《幼科证治准绳》集四：癍疹者，因内伤必出，癍乃荣气逆故也，大禁牵牛、巴豆、峻药，宜半夏、枳实、大黄、益智仁、之类去泻止吐，若耳尖冷、呵欠、睡惊、嚏喷、眼涩，知必出癍也，宜：  \n升麻、葛根、白芍药、甘草、归身、连翘各等分  \n上㕮咀，水煎服。此定法也，后、随证加减：如肺出脓癍，先显喘嗽，或气高而喘促，少加人参黄芩以泻伏火，而补元气。如心出小红癍，必先见嗌干惊悸，身热肌肉肿，脉弦洪，少加", "白话": "《幼科证治准绳》集四载：癍疹因内伤必发，癍是营气逆乱之故。大禁牵牛、巴豆及峻药，宜半夏、枳实、大黄、益智仁之类去泻止吐。若耳尖冷、呵欠、睡惊、喷嚏、眼涩，知必发癍，宜服：（组成照录见原文。方义：升麻、葛根、连翘、甘草升散透疹，白芍、当归和血，为透癍初起之平剂。）上药切碎，水煎服。此为定法，其后随证加减：如肺出脓癍，先见喘嗽，或气高而喘促，少加人参、黄芩以泻伏火而补元气；如心出小红癍，必先见咽喉干、惊悸、身热肌肉肿、脉弦洪，少加黄连；如命门出瘾疹，必先骨痛身热、疼痛不敢动摇，少"}, {"source": "条403｜《幼科证治准绳》集四·升麻汤", "原文": "《幼科证治准绳》集四：小儿耳冷尻冷，手足乍暖乍凉，面赤，时嗽时嚏，惊悸，此疮疹欲发候也，未能辨认间，服升麻汤、消毒散，已发未发皆宜服，仍用胡荽酒、黄柏膏。", "白话": "《幼科证治准绳》集四载：小儿耳冷尻冷，手足乍暖乍凉，面赤，时咳时嚏，惊悸，这是疮疹将发之候。未能辨认之间，服升麻汤、消毒散；已发未发都宜服，仍用胡荽酒、黄柏膏。"}, {"source": "条404｜《女科证治准绳》卷二·茯神散", "原文": "茯神散  \n《女科证治准绳》卷二：茯神散。圣惠治妇人血风劳气，头疼目赤，胸背气壅，四肢疼痛，心烦惊悸，少欲饮食。  \n柴胡去苗、石膏各二两 茯神、羚羊角、防风去芦、赤芍药、人参去芦、天门冬去心、独活、郁李仁去皮，微炒、生干地黄、枳壳麸炒，去瓤，各一两 甘草炙，半两  桃仁汤浸，去皮、尖、双仁，麸炒黄，研如泥，一两半  \n上为散，每服四钱，以水一中盏，入生姜半分，煎至六分，去滓温服，无时。", "白话": "《女科证治准绳》卷二载：茯神散（《圣惠》方）。治妇人血风劳气，头疼目赤，胸背气壅，四肢疼痛，心烦惊悸，不思饮食。（组成照录见原文。方义：柴胡、石膏、羚羊角、防风、独活疏风清热，茯神、人参、天冬、生地益气养阴安神，赤芍、桃仁、郁李仁、枳壳活血行气，为疏风清热、安神定悸之剂。）上药为散，每服四钱，用水一中盏，入生姜半分，煎至六分，去滓温服，不拘时候。"}, {"source": "条405｜《女科证治准绳》卷二·清气汤", "原文": "清气汤  \n《女科证治准绳》卷二：清气汤普济。治肌热骨瘦者，阴衰阳盛也。是气弱而血热，则外蒸肌肉，内蒸骨髓，烦渴口干，颊赤头疼，饮食无味，心神惊悸，肢体酸疼，或时盗汗，或时咳嗽，或月家断绝，或经极少，俗谓血劳，产后曰蓐劳，及羸瘦之人，与清气汤、羊乳丸治之。  \n紫苏子、五味子、大腹子、枳壳、桑白皮微炒、菖蒲、地骨皮、白术、柴胡、秦艽、独活、干葛、甘草炙，各等分  \n上㕮咀，每服五钱，水一盏，入紫苏", "白话": "《女科证治准绳》卷二载：清气汤（《普济》方）。治肌热骨瘦者，是阴衰阳盛。气弱而血热，则外蒸肌肉、内蒸骨髓，烦渴口干，颊赤头疼，饮食无味，心神惊悸，肢体酸疼；或时盗汗，或时咳嗽；或月经断绝，或经量极少，俗称血劳，产后称蓐劳；以及羸瘦之人，与清气汤、羊乳丸治之。（组成照录见原文。方义：紫苏子、桑白皮、大腹子、枳壳降气，菖蒲、柴胡、秦艽、独活、干葛疏风，地骨皮、白术、五味子、甘草清热健脾敛阴，为清气疏风、退蒸定悸之剂。）上药切碎，每服五钱，用水一盏，入紫苏七片、乌梅一个，煎至七分，"}, {"source": "条406｜《邯郸遗稿》卷四·龙齿清魂散", "原文": "龙齿清魂散  \n《邯郸遗稿》卷四：有因心虚惊悸，言语错乱，不知人事，目瞪不能叫呼，宜用龙齿清魂散。", "白话": "《邯郸遗稿》卷四载：有因心虚而惊悸、言语错乱、不知人事、目瞪不能叫呼的，宜用龙齿清魂散。"}, {"source": "条407｜《外科正宗》卷二·金液戊土丹", "原文": "金液戊土丹  \n《外科正宗》卷二：金液戊土丹。金液戊土丹五味，牛黄神志石菖蒲，砂雄硝石乌梅等，片射人中黄不殊。治脱疽及疔疮、发背，纵食膏粱厚味法酒，又或丹石补药，勉力房劳，多致积毒脏腑，久则胃汁中干，肾水枯竭，不能上制心火，以致消渴、消中、消肾，饶饮多干，能食多瘦，九窍不通，惊悸健忘，此症若出后必发疽，多难治疗。宜预服此，亦可转重就轻，移深就浅，又解五金八石之毒药也。  \n乌梅肉、茯神、胡黄连、五", "白话": "《外科正宗》卷二载：金液戊土丹。歌曰：金液戊土丹五味，牛黄神志石菖蒲，砂雄硝石乌梅等，片射人中黄不殊。主治脱疽及疔疮、发背：因纵食膏粱厚味、法酒，又或服丹石补药、勉力房劳，多致积毒于脏腑，久则胃汁中干、肾水枯竭，不能上制心火，以致消渴、消中、消肾，多饮多尿，能食而瘦，九窍不通，惊悸健忘。此症既出必发疽，多难治疗。宜预先服此，可转重就轻、移深就浅，又解五金八石之毒药。（组成照录见原文。方义：乌梅、五味子酸收敛阴，茯神、远志、菖蒲安神开窍，牛黄、冰片、辰砂、雄黄清心解毒镇惊，胡黄"}, {"source": "条408｜《婴童类萃》下卷·犀角汤", "原文": "犀角汤  \n《婴童类萃》下卷：犀角汤。治身热发黄，口干烦躁，心神惊悸。  \n茵陈一钱 干葛 龙胆草 升麻 滑石一钱五分 寒水石一钱五分 犀角、生地各七分  \n灯心二十寸，竹叶十片，水煎。", "白话": "《婴童类萃》下卷载：犀角汤。主治身热发黄，口干烦躁，心神惊悸。（组成照录见原文。方义：犀角、生地清心凉血，茵陈、龙胆草、升麻、葛根清热利湿退黄，滑石、寒水石清热利水，为清心凉血、退黄除烦之剂。）用灯心二十寸、竹叶十片，水煎。"}, {"source": "条409｜《妇人规》下卷·东垣朱砂安神丸", "原文": "东垣朱砂安神丸  \n《妇人规》下卷：东垣朱砂安神丸，一名黄连安神丸。治心神烦乱，发热怔忡，不寐或寐中惊悸、头运同晕等证。  \n生地、朱砂另飞为衣、当归各一钱 甘草五分 黄连一钱半  \n汤浸蒸饼为丸，黍米大，每服十五丸或二十丸，津液咽之，或食后用温水、凉水送下亦可。", "白话": "《妇人规》下卷载：东垣朱砂安神丸，又名黄连安神丸。主治心神烦乱，发热怔忡，不寐或睡中惊悸、头目眩晕等证。（组成照录见原文。方义：黄连清心火，生地、当归滋阴养血，朱砂镇心安神，甘草调和，即李东垣安神丸法，泻心火、养阴血以安心神。）用汤浸蒸饼为丸，黍米大，每服十五丸或二十丸，以津液咽下，或食后用温水、凉水送下也可以。"}, {"source": "条410｜《（痘疹）生民切要》·连翘防风汤", "原文": "连翘防风汤  \n《（痘疹）生民切要》：少阳三焦、胆经，主寒热往来，时或惊悸而发搐，宜连翘防风汤。", "白话": "《（痘疹）生民切要》载：少阳三焦、胆经主寒热往来，时或惊悸而发抽搐，宜用连翘防风汤。"}, {"source": "条411｜《济世神验良方·女科门》·神应丹", "原文": "神应丹  \n《济世神验良方·女科门》：神应丹。治经不行有实热，五心烦热，口燥咽干，心忪额赤，胸膈不利，咳唾稠痰。  \n大黄八两，醋二碗，煮干晒 血竭、桃仁、红花各五钱  \n酒糊丸如桐子大，朱砂为衣，每服七十丸。", "白话": "《济世神验良方·女科门》载：神应丹。主治经闭不行有实热，五心烦热，口燥咽干，心忪额赤，胸膈不利，咳唾稠痰。（组成照录见原文。方义：大黄醋煮泻热通经，血竭、桃仁、红花活血通经，朱砂为衣镇心，酒糊为丸，为泻热通经、活血定悸之剂。）酒糊丸如桐子大，朱砂为衣，每服七十丸。"}, {"source": "条412｜《辨证录》卷六·清胃生髓丹", "原文": "清胃生髓丹  \n《辨证录》卷六：胃火上冲于心，心中烦闷，怔忡惊悸，久则成痿，两足无力，不能动履，此总属胃火之盛，非心火之旺也。方用清胃生髓丹：  \n玄参一两 麦冬五钱 甘菊花五钱 熟地二两 北五味二钱 沙参五钱  \n水煎服。十剂即可行步，二十剂怔忡惊悸之病除，又十剂烦闷痿弱之症去，再服十剂全愈。", "白话": "《辨证录》卷六载：胃火上冲于心，心中烦闷，怔忡惊悸，日久则成痿，两足无力，不能行动，这总属胃火之盛，不是心火之旺。方用清胃生髓丹：（组成照录见原文。方义：玄参、麦冬、沙参、熟地、五味子滋阴生髓，甘菊花清上，共奏清胃滋阴、生髓起痿之效。）水煎服。十剂即可行步，二十剂怔忡惊悸之病除，再十剂烦闷痿弱之症去，再服十剂全愈。"}, {"source": "条413｜《身经通考·身经答问十》·黄连泻心汤", "原文": "黄连泻心汤  \n《身经通考·身经答问十》：心实则烦热，黄连泻心汤；虚则惊悸，生犀散。", "白话": "《身经通考·身经答问十》载：心实证则烦热，用黄连泻心汤；虚证则惊悸，用生犀散。"}, {"source": "条414｜《不居集·上集》·二阴煎", "原文": "二阴煎  \n《不居集·上集》：若火在心肾而惊悸失志者，宜二阴煎。", "白话": "《不居集·上集》载：若火在心肾而惊悸失志的，宜用二阴煎。"}, {"source": "条415｜《不居集·上集》·理脾益营汤", "原文": "理脾益营汤  \n《不居集·上集》：心虚火盛，烦热内热，怔忡不寐者，宜理脾益营汤，或古方安神丸。", "白话": "《不居集·上集》载：心虚火盛，烦热内热，怔忡不寐的，宜用理脾益营汤，或古方安神丸。"}, {"source": "条416｜《不居集·上集》·小营煎", "原文": "小营煎  \n《不居集·上集》：产后有阴虚发热者，必素禀脾肾不足，及产后气血俱虚，故多有之。其症则倏忽往来，时作时止，或昼或夜，进退不常，或精神困倦，怔忡恍惚。但察其外无表症，而脉见弦数，或浮弦豁大，或细微无力，其来也渐，非若他症之暴至者，即是阴虚之候。治当专补真阴，大、小营煎，三阴煎，五阴煎，理阴煎，理脾益荣汤，培土养阴汤。", "白话": "《不居集·上集》载：产后有阴虚发热的，必是平素禀赋脾肾不足，加上产后气血俱虚，所以多有此证。其症寒热倏忽往来，时作时止，或昼或夜，进退不常；或精神困倦，怔忡恍惚。只要察其外无表证，而脉见弦数，或浮弦豁大，或细微无力，其来也渐，不像他症之暴然而至，即是阴虚之候。治当专补真阴，用大营煎、小营煎、三阴煎、五阴煎、理阴煎、理脾益荣汤、培土养阴汤。"}, {"source": "条417｜《杂病源流犀烛》卷六·十味导赤散", "原文": "十味导赤散  \n《杂病源流犀烛》卷六：十味导赤散。实热。  \n黄连、黄芩、麦冬、半夏、茯苓、赤芍、木通、生地、甘草、地骨皮各用五分 姜五片  \n此治心脏实热，一切口舌生疮、惊悸、烦渴诸症。", "白话": "《杂病源流犀烛》卷六载：十味导赤散。治实热。（组成照录见原文。方义：黄连、黄芩、地骨皮清心泻火，生地、麦冬、赤芍滋阴凉血，木通、茯苓、半夏、甘草利湿和中，姜为引，为清心导赤之剂。）此治心脏实热，一切口舌生疮、惊悸、烦渴诸症。"}, {"source": "条418｜《彤园医书（外科）》卷四·白芍汤", "原文": "白芍汤  \n《彤园医书（外科）》卷四：若十日半月儿脐忽然突肿如吹，色不红赤，捻动微响，或惊悸而多啼，宜服白芍汤。", "白话": "《彤园医书（外科）》卷四载：若十日半月大的小儿脐部忽然突肿如吹气状，颜色不红赤，捻动微有响声，或惊悸而多啼哭，宜服白芍汤。"}, {"source": "条419｜《鸡鸣录·虚劳第四》·无名方（通神补血丸）", "原文": "无名方  \n《鸡鸣录·虚劳第四》：治虚火上炎，气升咳逆，时吐涎沫，为保肺清金，而不碍脾胃之要药。  \n生地三两 茯神三两五钱 紫石英煅飞、远志、枣仁炒，各二两 当归一两五钱 人参、麦冬、丹参、制半夏各一两 石菖蒲八钱 胆星四钱 琥珀三钱 川连二钱  \n十四味研细，用连血猪心一个，入辰砂三钱 煮烂打丸，如干加炼蜜，或独用炼蜜亦可。每丸重一钱五分，辰砂为衣，空心枣汤，或盐汤化服，每服一丸，名通神补血丸", "白话": "《鸡鸣录·虚劳第四》载：治虚火上炎，气升咳逆，时吐涎沫，是保肺清金而不碍脾胃的要药。（组成照录见原文。方义：生地、麦冬、当归、丹参滋阴养血，人参、茯神、枣仁、远志、菖蒲、琥珀、辰砂安神定志，紫石英、半夏、胆星、川连镇心化痰清热，猪心血为丸引药入心，共成补血安神之剂。）十四味研细，用带血猪心一个，加入辰砂三钱煮烂打丸，如干加炼蜜，或单用炼蜜也可以。每丸重一钱五分，辰砂为衣，空心枣汤或盐汤化服，每服一丸。名通神补血丸，专治神虚血少、惊悸健忘、不寐怔忡、易恐易汗等证。"}, {"source": "条420｜《经验良方全集》卷四·升麻葛根汤", "原文": "《经验良方全集》卷四：出痘形证。痘发时身热呕吐，体痛腹痛，烦躁喷嚏，惊悸昏倦……惊悸谵语妄视，小便通忌睡发汗，以后忌痰。已发热时，寒战、咬牙、惊悸者，勿虑，此毒欲出，与皮肉相撞也。如太甚，以升麻葛根汤一剂而愈。", "白话": "《经验良方全集》卷四载：出痘形证。痘发时身热呕吐，体痛腹痛，烦躁喷嚏，惊悸昏倦……惊悸谵语妄视，小便通利者忌睡中发汗，以后忌痰。已发热时寒战、咬牙、惊悸的，不必忧虑，这是毒气将出、与皮肉相撞所致。如太甚，以升麻葛根汤一剂而愈。"}, {"source": "条421｜《诊验医方歌括·中》·驯龙驭虎汤", "原文": "驯龙驭虎汤  \n《诊验医方歌括·中》：驯龙驭虎汤。喉舌作痛。驯龙驭虎真珠母，地黄斛玉沉香乳，蒌荷莲芍柏子霜，喉舌作痛惊悸愈。惊悸气促，喉舌作痛。  \n龙齿二钱 琥珀一钱 真珠母八钱 生地六钱 玉竹四钱 蒌皮三钱 石斛三钱 柏子霜二钱 白芍一钱五分 薄荷一钱 莲子二十粒，打碎，勿去心 沉香四分，人乳磨冲", "白话": "《诊验医方歌括·中》载：驯龙驭虎汤。治喉舌作痛。歌曰：驯龙驭虎真珠母，地黄斛玉沉香乳，蒌荷莲芍柏子霜，喉舌作痛惊悸愈。主治惊悸气促，喉舌作痛。（组成照录见原文。方义：龙齿、琥珀、真珠母重镇安神，生地、玉竹、石斛、白芍滋阴，柏子霜、莲子养心，蒌皮、薄荷、沉香利咽下气，为镇心养阴、利咽定悸之剂。）"}, {"source": "条422｜《医学衷中参西录·医方》·清降汤", "原文": "清降汤  \n《医学衷中参西录·医方》：清降汤。治因吐衄不止，致阴分亏损，不能潜阳而作热，不能纳气而作喘。甚或冲气因虚上干，为呃逆、为眩晕。心血因虚甚不能内荣，为怔忡、为惊悸不寐。或咳逆、或自汗诸虚证蜂起之候。  \n生山药一两 清半夏三钱 净萸肉五钱 生赭石六钱，轧细 牛蒡子二钱，炒捣 生杭芍四钱 甘草钱半", "白话": "《医学衷中参西录·医方》载：清降汤。主治因吐血衄血不止，致阴分亏损，不能潜阳而作热，不能纳气而作喘；甚至冲气因虚上干，为呃逆、为眩晕；心血因虚甚不能内荣，为怔忡、为惊悸不寐；或咳逆、或自汗，诸虚证蜂起之候。（组成照录见原文。方义：山药、萸肉补阴固摄，赭石镇冲降逆，半夏、牛蒡子降气化痰，芍药、甘草敛阴和中，共成滋阴潜阳、降冲定悸之剂。）"}, {"source": "条423｜《医学衷中参西录·医方》·清降汤", "原文": "清降汤  \n《医学衷中参西录·医方》：清降汤。心血因虚甚不能内荣，为怔忡、为惊悸不寐。或咳逆、或自汗诸虚证蜂起之候。  \n生山药一两 清半夏三钱 净萸肉五钱 生赭石六钱，轧细 牛蒡子二钱，炒捣 生杭芍四钱 甘草钱半", "白话": "《医学衷中参西录·医方》载：清降汤。心血因虚甚不能内荣，为怔忡、为惊悸不寐；或咳逆、或自汗，诸虚证蜂起之候。（组成照录见原文。方义：同条422清降汤，滋阴潜阳、降冲定悸。）"}, {"source": "条424｜《医学衷中参西录·医论》·滋阴清降汤", "原文": "滋阴清降汤  \n《医学衷中参西录·医论》：滋阴清降汤。治吐衄证失血过多，阴分亏损，不能潜阳而作热，不能纳气而作喘，甚或冲气因虚上干，为呃逆、眩晕、咳嗽，心血因不能内荣，为怔忡、惊悸、不寐，脉象浮数重按无力者。  \n生赭石八钱，轧细 生怀山药一两 生地黄八钱 生龙骨六钱，捣细 生牡蛎六钱，捣细 生杭芍四钱 甘草二钱 广三七细末，二钱，分两次，用头煎二煎之汤送服", "白话": "《医学衷中参西录·医论》载：滋阴清降汤。主治吐血衄血证失血过多，阴分亏损，不能潜阳而作热，不能纳气而作喘；甚至冲气因虚上干，为呃逆、眩晕、咳嗽；心血因虚不能内荣，为怔忡、惊悸、不寐；脉象浮数而重按无力。（组成照录见原文。方义：较清降汤增生地、龙骨、牡蛎、三七，滋阴潜阳、止血化瘀之力更著。）"}, {"source": "条425｜《增订通俗伤寒论·第三编》·正诚露珠丹", "原文": "正诚露珠丹  \n《增订通俗伤寒论·第三编》：又次用正诚露珠丹透明辰砂一两，以瓷器盛，露四十九夜，猪心中血，丝绵绞去滓，用净血三两，每次一个，拌砂晒干，再拌再晒，三个用讫，再研极细，加西牛黄一钱，共研匀细，用糯米糊和捣万杵为丸，每重七分，阴干得五分，瓷瓶密收。夜卧时噙化一丸，治殚虑劳神，火升痰壅，心悸不寐，遇事善忘等证，最效，善其后以防复发。", "白话": "《增订通俗伤寒论·第三编》载：其次用正诚露珠丹：透明辰砂一两，以瓷器盛，露四十九夜；猪心中血，以丝绵绞去滓，用净血三两，每次取一个猪心血拌辰砂晒干，再拌再晒，三个用完，再研极细，加西牛黄一钱，共研匀细，用糯米糊和捣万杵为丸，每丸重七分，阴干得五分，瓷瓶密收。夜卧时噙化一丸。主治殚虑劳神、火升痰壅、心悸不寐、遇事善忘等证，最效，善其后以防复发。"}, {"source": "条426｜《陈氏幼科秘诀·痫》·小红丸", "原文": "小红丸  \n《陈氏幼科秘诀·痫》：儿有热痰，一不饮乳，眠睡不稳，常时惊悸，即用小红丸，减其盛气为妙。", "白话": "《陈氏幼科秘诀·痫》载：小儿有热痰，不吃乳，睡眠不稳，时常惊悸，即用小红丸，减其盛气为妙。"}, {"source": "条427｜《备急千金要方》卷八·大续命汤", "原文": "大续命汤  \n《备急千金要方》卷八：大续命汤。治大风经脏，奄忽不能言，四肢垂曳，皮肉痛痒不自知方。  \n独活、麻黄各三两  川芎、防风、当归、葛根、生姜、桂心、茯苓、附子、细辛、甘草各一两  \n上十二味，㕮咀，以水一斗二升，煮取四升，分五服，老小半之。若初得病便自大汗者减麻黄，不汗者依方。上气者，加吴茱萸二两、厚朴一两。干呕者，倍加附子一两。哕者，加橘皮二两。若胸中吸吸少气者，加大枣十二枚。心下惊", "白话": "《备急千金要方》卷八载：大续命汤。主治大风入于经脏，突然不能言语，四肢垂曳，皮肉痛痒不自知之方。（组成照录见原文。方义：麻黄、葛根、生姜解表，独活、防风、细辛、川芎祛风，当归养血，桂心、附子温经，茯苓、甘草健脾和中，为祛风通络、温经养血之剂。）上十二味切碎，用水一斗二升，煮取四升，分五服，老小减半。若初得病即大汗的减麻黄，不出汗的依方。上气的加吴茱萸二两、厚朴一两；干呕的倍加附子一两；呃逆的加橘皮二两；若胸中吸吸少气的加大枣十二枚；心下惊悸的加茯苓一两；若热的可去生姜加葛根。"}, {"source": "条428｜《备急千金要方》卷八·仲景三黄汤", "原文": "仲景三黄汤  \n《备急千金要方》卷八：仲景三黄汤。治中风手足拘挛，百节疼痛，烦热心乱，恶寒，经日不欲饮食方。  \n麻黄三十铢  黄芩十八铢  黄芪、细辛各十二铢  独活一两  \n上五味，㕮咀，以水五斗，煮取二升，分二服，一服小汗，两服大汗。心中热加大黄半两，胀满加枳实六铢，气逆加人参，心悸加牡蛎，渴加栝蒌各十八铢，先有寒加附子一枚。", "白话": "《备急千金要方》卷八载：仲景三黄汤。主治中风手足拘挛，百节疼痛，烦热心乱，恶寒，整日不欲饮食之方。（组成照录见原文。方义：麻黄、独活、细辛祛风散寒，黄芪益气固表，黄芩清热，为祛风通痹、益气清热之剂。）上五味切碎，用水五斗，煮取二升，分二服，一服小汗，两服大汗。心中热加大黄半两，胀满加枳实六铢，气逆加人参，心悸加牡蛎，渴加栝蒌各十八铢，先有寒加附子一枚。"}, {"source": "条429｜《备急千金要方》卷十四·茯神汤", "原文": "茯神汤  \n《备急千金要方》卷十四：茯神汤。治风经五脏大虚，惊悸，安神定志方。  \n茯神、防风各三两  人参、远志、甘草、龙骨、桂心、独活各二两  白术一两酸枣一升  细辛、干姜各六两  \n上十二味，㕮咀，以水九升煮取三升，分三服。", "白话": "《备急千金要方》卷十四载：茯神汤。主治风邪经过五脏、大虚，惊悸，能安神定志之方。（组成照录见原文。方义：茯神、远志、龙骨安神定志，人参、白术、甘草益气，防风、独活、细辛祛风，桂心、干姜温阳，酸枣养心，为益气祛风、安神定志之剂。）上十二味切碎，用水九升煮取三升，分三服。"}, {"source": "条430｜《千金翼方》卷十七·三黄汤", "原文": "三黄汤  \n《千金翼方》卷十七：三黄汤。主中风，手足拘挛，百节疼痛，烦热心乱，恶寒，经日不欲饮食方。  \n麻黄五分，去节  独活一两  黄芩三分  黄芪半两  细辛半两  \n上五味，㕮咀，以水五升，煮取二升，去滓，分二服，一服小汗，两服大汗。心中热，加大黄半两；腹满加枳实一枚；气逆加人参三分；心悸加牡蛎三分；渴加栝蒌三分；先有寒加八角附子一枚。此仲景方，神秘，不传。", "白话": "《千金翼方》卷十七载：三黄汤。主治中风，手足拘挛，百节疼痛，烦热心乱，恶寒，整日不欲饮食之方。（组成照录见原文。方义：麻黄、独活、细辛祛风散寒，黄芪益气，黄芩清热，即仲景三黄汤。）上五味切碎，用水五升，煮取二升，去滓，分二服，一服小汗，两服大汗。心中热加大黄半两；腹满加枳实一枚；气逆加人参三分；心悸加牡蛎三分；渴加栝蒌三分；先有寒加八角附子一枚。这是仲景方，神秘不传。"}, {"source": "条431｜《养生通论·养老奉亲书》·旋覆花散", "原文": "旋覆花散  \n《养生通论·养老奉亲书》：治老人风热上攻，头旋运闷，喜卧，怔悸，起即欲倒，背急身强。旋覆花散（女人通用）。", "白话": "《养生通论·养老奉亲书》载：治老人风热上攻，头旋晕闷，喜躺卧，怔悸，起身即欲倒，背急身体强直。用旋覆花散（女人通用）。"}, {"source": "条432｜《圣济总录》卷五·独活汤", "原文": "独活汤  \n《圣济总录》卷五：治风中五脏，奄忽不能言，四肢垂曳，皮肉癇痹，痛痒不知，独活汤方。  \n独活去芦头，三两  防风去叉、芎、白茯苓去黑皮、当归切焙、葛根、桂去粗皮，各二两  麻黄去根节，先洗、煎，掠去沫，焙，三两  附子炮裂，去皮脐、细辛去苗叶、甘草炙，各一两  \n上一十一，锉如麻豆，每服五钱匕，水一盏半，生姜五片。煎至八分，去滓空心，日午夜卧温服……心下惊悸，加茯苓去黑皮一两。若热，", "白话": "《圣济总录》卷五载：治风邪中于五脏，突然不能言语，四肢垂曳，皮肉顽痹，痛痒不知，用独活汤方。（组成照录见原文。方义：独活、防风、芎䓖、麻黄、葛根祛风通络，当归、茯苓养血健脾，桂心、附子、细辛温经，甘草和中，与《千金》大续命汤同法。）上十一味，锉如麻豆，每服五钱匕，用水一盏半、生姜五片，煎至八分，去滓空心、日午、夜卧温服。心下惊悸，加茯苓去黑皮一两；若热，去生姜加葛根。初得风不必加减，即依本方服；四五日以后，再看病之虚实，或加针灸。"}, {"source": "条433｜《圣济总录》卷一百五十·三黄汤", "原文": "三黄汤  \n《圣济总录》卷一百五十：治妇人中风，手足拘挛，百节疼痛，烦热闷乱，不欲饮食，三黄汤方。  \n麻黄去节煎，掠去沫，焙，一两一分  独活去芦头，一两  细辛去苗叶，一分  黄芪锉，半两  黄芩去黑心，三分  \n上五味，粗捣筛，每服五钱匕，水一盏半，煎取一盏，去滓温服，心躁加大黄半两锉炒，腹满加枳实一枚去瓤麸炒，气虚加人参三分，惊悸加牡蛎粉三分熬，渴加栝蒌根三分锉，先有寒加附子一枚，炮裂去皮", "白话": "《圣济总录》卷一百五十载：治妇人中风，手足拘挛，百节疼痛，烦热闷乱，不欲饮食，用三黄汤方。（组成照录见原文。方义：麻黄、独活、细辛祛风，黄芪益气固表，黄芩清热，与仲景三黄汤同法而用量略异。）上五味，粗捣筛，每服五钱匕，用水一盏半，煎取一盏，去滓温服。心躁加大黄半两锉炒；腹满加枳实一枚去瓤麸炒；气虚加人参三分；惊悸加牡蛎粉三分熬；渴加栝蒌根三分锉；先有寒加附子一枚炮裂去皮脐。"}, {"source": "条434｜《圣济总录》卷一百五十·蓬香散", "原文": "蓬香散  \n《圣济总录》卷一百五十：治妇人血风，每至天阴，即先头旋眼睛痛，头目昏，躁闷怔忪，手足热疼，吃食减少，经候不匀，有时腹痛，或多便利，蓬香散方。  \n蓬莪术煨锉、京三棱煨锉、荆芥穗、沉香锉、厚朴去粗皮，生姜汁炙、桂去粗皮、 乌药、当归切，焙、延胡索、天麻、附子炮裂，去皮脐，各一两  \n上一十一味，捣罗为末，每服二钱匕，生姜自然汁少许，和温酒调下，日三。", "白话": "《圣济总录》卷一百五十载：治妇人血风，每到天阴即先头旋眼痛、头目昏、躁闷怔忪、手足热疼、饮食减少、经候不匀，有时腹痛，或多便利，用蓬香散方。（组成照录见原文。方义：蓬莪术、京三棱、延胡索、当归活血行气，乌药、沉香、厚朴温中下气，荆芥穗、天麻、桂心、附子祛风散寒，为活血行气、祛风温中之剂。）上十一味，捣罗为末，每服二钱匕，用生姜自然汁少许和温酒调下，日三服。"}, {"source": "条435｜《圣济总录》卷一百七十·茯神汤", "原文": "茯神汤  \n《圣济总录》卷一百七十：治小儿风热惊掣，心忪恐悸，茯神汤方。  \n茯神去木，一分  龙齿半两  寒水石研，一分  升麻三分  石膏研，一两  麦门冬去心，焙，三分  \n上六味，粗捣筛，一二岁儿，每服一钱匕，水七分，入竹沥少许，煎至四分，去滓温服，日三夜一，量儿大小，以意加减。", "白话": "《圣济总录》卷一百七十载：治小儿风热惊掣、心忪恐悸，用茯神汤方。（组成照录见原文。方义：茯神、龙齿、麦冬安神定志，石膏、寒水石、升麻清热散火，加竹沥化痰，为小儿清热镇惊之剂。）上六味，粗捣筛。一二岁小儿每服一钱匕，用水七分，加入竹沥少许，煎至四分，去滓温服，日三夜一，按儿大小随意加减。"}, {"source": "条436｜《圣济总录》卷一百八十八·大枣粥", "原文": "大枣粥  \n《圣济总录》卷一百八十八：治中风，惊恐虚悸，如人将捕之，四肢沉重，补益，大枣粥方。  \n大枣七枚，去核  青粱粟米二合  \n上二味，以水三升半，先煮枣取一升半，去滓投米，煮粥食之。", "白话": "《圣济总录》卷一百八十八载：治中风、惊恐虚悸、如人将捕之、四肢沉重，能补益，用大枣粥方。（组成照录见原文。方义：大枣补脾养心，青粱粟米益胃，煮粥食之，为食疗补虚定悸之方。）上二味，用水三升半，先煮枣取一升半，去滓放入米，煮粥食用。"}, {"source": "条437｜《仁斋直指方论（附补遗）》卷三·保命丹", "原文": "保命丹  \n《仁斋直指方论（附补遗）》卷三：保命丹（《千金方》）。治诸风痪疭，不能语言，心忪健忘，恍惚去来，头目晕眩，胸中烦郁，痰涎壅塞，抑气攻心，精神昏愦。治心气不足，神志不定，惊恐怕怖，悲忧惨蹙，虚烦少睡，喜怒不时，或发狂癫，神情昏乱，及小儿惊痫，惊风抽搐不定，及大人暗风，并羊癫、猪癫发叫。  \n朱砂一两  珍珠二钱  南星一两  麻黄去根、节、白附子炮、雄黄、龙脑各半两琥珀三钱  僵蚕炒、犀", "白话": "《仁斋直指方论（附补遗）》卷三载：保命丹（《千金方》）。主治诸风瘛疭、不能言语、心忪健忘、恍惚去来、头目晕眩、胸中烦郁、痰涎壅塞、气逆攻心、精神昏愦；又治心气不足、神志不定、惊恐怕怖、悲忧惨蹙、虚烦少睡、喜怒不时，或发狂癫、神情昏乱；及小儿惊痫、惊风抽搐不定，大人暗风，以及羊癫、猪癫发叫。（组成照录见原文。方义：朱砂、珍珠、琥珀、金箔、龙齿重镇安神，牛黄、龙脑、麝香、天竺黄、犀角清心开窍，天麻、僵蚕、蝉蜕、防风熄风，南星、白附子、胆矾化痰，麻黄、荆芥、升麻、桔梗宣散，参苓术草"}, {"source": "条438｜《御药院方》卷一·生犀丸", "原文": "生犀丸  \n《御药院方》卷一：生犀丸。主心虚喜忘，烦悸，风涎不利，聪明耳目。治诸风颤掉及治三十六种风。益精神，壮心气，或多健忘，寝寐之惊心，常似忧，或忪，或动，往往欲倒状，类暗风，四肢颤掉，多生怯怕，每起烦躁，悲涕愁煎，并皆属心脏气亏，宜服此以镇心神。  \n生犀镑，一两 天麻炙黄，半两 败龟酥炙，半两 牛黄研一分 茯神去皮，一分 远志去心，一分 人参去芦头，一分 肉桂去粗皮，一分 龙齿酥炙黄，一分", "白话": "《御药院方》卷一载：生犀丸。主治心虚喜忘、烦悸、风涎不利、聪明耳目；治诸风颤掉及三十六种风。益精神、壮心气。或多健忘，睡眠中惊心，常似忧虑，或忪或动，往往欲倒，类似暗风；四肢颤掉，多生怯怕，每起身烦躁、悲涕愁煎——都属心脏气亏，宜服此以镇心神。（组成照录见原文。方义：生犀角、羚羊角、牛黄清心凉肝，龙齿、朱砂、金箔、银箔、琥珀重镇安神，天麻熄风，菖蒲、远志、茯神开窍益智，人参、肉桂益心气，龟板滋阴，麝香、龙脑开窍，为镇心安神、益气熄风之剂。）上药捣研极细，炼蜜为丸如梧桐子大。食"}, {"source": "条439｜《御药院方》卷一·石膏丸", "原文": "石膏丸  \n《御药院方》卷一：石膏丸。治诸风痰涎，头痛目眩，旋欲晕倒，心忪悸动，恍惚不宁，神思昏愦，肢体倦疼，颈项强硬，手足麻痹。常服除偏正头疼。  \n石膏另研、白附子炮、半夏汤洗七次、川芎、天南星炮、白僵蚕炒去丝、菊花拣净、陈皮去白、旋覆花、天麻以上各一两 全蝎炒，半两  \n上件一十一味为细末，生姜汁浸，浸饼为丸，如梧桐子大。每服五十丸，渐加一百丸，食后生姜汤下。忌黏滑生硬等物。", "白话": "《御药院方》卷一载：石膏丸。主治诸风痰涎、头痛目眩、旋转欲倒、心忪悸动、恍惚不宁、神思昏愦、肢体倦疼、颈项强硬、手足麻痹。常服除偏正头痛。（组成照录见原文。方义：石膏、菊花清热，白附子、半夏、南星、僵蚕、全蝎、天麻化痰熄风，川芎、旋覆花、陈皮理气和中，为清热化痰、熄风定悸之剂。）上十一味为细末，生姜汁浸，浸饼为丸如梧桐子大。每服五十丸，渐加一百丸，食后生姜汤送下。忌黏滑生硬等物。"}, {"source": "条440｜《御药院方》卷一·辟风丹", "原文": "辟风丹  \n《御药院方》卷一：辟风丹。治诸风疾无问新久者。半身不遂，口眼斜，语言謇涩，精神昏愦，痰涎并多，咽嗌不利，及风虚头痛目眩，旋晕欲倒，或心忪健忘，恍惚不宁，手足麻痹，颤掉无力，筋脉拘急，骨节烦疼，行步艰难，并宜服之。  \n独活洗去土，焙干、防风去芦头、吴白芷、桂、藁本去土、麻黄去节，微炒、白芍药去皮、天麻以上各一两 川乌头炮制，去皮捶碎，炒黄，半两 藿香叶去土，半两川芎七钱 羌活去苗，三", "白话": "《御药院方》卷一载：辟风丹。主治诸风疾不论新久：半身不遂，口眼歪斜，语言謇涩，精神昏愦，痰涎多，咽喉不利；以及风虚头痛目眩、旋转欲倒，或心忪健忘、恍惚不宁、手足麻痹、颤掉无力、筋脉拘急、骨节烦疼、行步艰难，都宜服。（组成照录见原文。方义：麻黄、防风、白芷、藁本、羌活、藿香、白花蛇祛风通络，川乌、白附子、天南星、僵蚕、全蝎化痰熄风，天麻、川芎、白芍养血熄风，朱砂镇心，远志安神，为祛风化痰、通络定悸之重剂。）上药捣罗为细末，炼蜜和丸，每两作十丸，朱砂为衣。每服一丸，细嚼或化服，用"}, {"source": "条441｜《御药院方》卷一·芎䓖天麻丸", "原文": "芎天麻丸  \n《御药院方》卷一：芎天麻丸。清利头目，消风化痰，宽胃利膈。心忪烦闷，旋晕欲倒，颈项紧急，肩背拘倦，神昏多睡，肢体烦痛，皮肤瘙痒，偏正头痛，鼻塞声重，面目浮肿，并宜服之。  \n芎二两 天麻半两  \n上二味为细末，炼蜜为丸。每一两半作二十丸。每服一丸，食后细嚼，茶酒任下。", "白话": "《御药院方》卷一载：芎䓖天麻丸。能清利头目，消风化痰，宽胃利膈。主治心忪烦闷、旋转欲倒、颈项紧急、肩背拘倦、神昏多睡、肢体烦痛、皮肤瘙痒、偏正头痛、鼻塞声重、面目浮肿，都宜服。（组成照录见原文。方义：川芎上行头目、活血祛风，天麻熄风定眩，二味相须，为风痰眩晕心忪之小方。）上二味为细末，炼蜜为丸。每一两半作二十丸。每服一丸，食后细嚼，茶酒任下。"}, {"source": "条442｜《御药院方》卷十一·人参荆芥煮散", "原文": "人参荆芥煮散  \n《御药院方》卷十一：人参荆芥煮散。治妇人血风劳气攻刺疼痛，四肢无力，不思饮食，多困黄瘦，胸膈痞满，经水不利，心多怔忪，并治之。  \n荆芥穗四两 柴胡、秦艽去芦头，洗去泥、肉豆蔻、白芷、黄芪、鳖甲醋炙黄，洗净、桔梗、官桂去皮，各二两 当归、川芎、蓬莪术、麦门冬去心、芍药、人参、茯苓、海桐皮、甘草炙、枳壳麸炒，去瓤、熟干地黄、酸枣仁、木香各一两 沉香、槟榔各半两  \n上件罗为末，每服", "白话": "《御药院方》卷十一载：人参荆芥煮散。主治妇人血风劳气攻冲疼痛，四肢无力，不思饮食，多困倦黄瘦，胸膈痞满，月经不利，心中多怔忪，并治。（组成照录见原文。方义：荆芥穗、柴胡、秦艽、白芷疏风，四物（归芎芍地）合人参、黄芪补气血，鳖甲、麦冬、酸枣仁滋阴安神，肉豆蔻、木香、沉香、槟榔、枳壳、莪术行气活血，官桂温经，为益气养血、疏风行气之剂。）上药罗为末，每服三钱，用水一盏、生姜三片、乌梅二个，煎至七分，温服，一日四五服。如觉脏腑热即空心食前服；小便多即食后卧时服。如患气血块，立刻消化。"}, {"source": "条443｜《世医得效方》卷十三·通气驱风汤", "原文": "通气驱风汤  \n《世医得效方》卷十三：通气驱风汤。治男子妇人血气虚弱，虚风攻注，肌体颤掉，肩背刺痛，手足拳挛，口眼斜，半身不遂，头目旋晕，痰涎壅盛，语言謇涩，行步艰难，心忪气短。客风所凑，四肢拘急，鼻塞声重，头疼。脾胃不和，心腹刺痛，胸膈不快，少力多困，精神不爽，不思饮食，呕吐恶心，霍乱吐泻。胎前产后，但是气虚百病，皆可服之。  \n天台乌药五两 桔梗去芦、川白芷、川芎、甘草炙、陈皮去白、白术各三", "白话": "《世医得效方》卷十三载：通气驱风汤。主治男子妇人血气虚弱、虚风攻注，肌体颤掉，肩背刺痛，手足拳挛，口眼歪斜，半身不遂，头目旋晕，痰涎壅盛，语言謇涩，行步艰难，心忪气短；客风所凑，四肢拘急，鼻塞声重，头疼；脾胃不和，心腹刺痛，胸膈不快，少力多困，精神不爽，不思饮食，呕吐恶心，霍乱吐泻。胎前产后，凡气虚百病都可服。（组成照录见原文。方义：乌药、桔梗、白芷、川芎、枳壳、陈皮理气通滞，麻黄解表，白术、甘草、人参健脾益气，即乌药顺气散加减。）上药为末，每服三钱，用紫苏、木瓜煎汤调下。去"}, {"source": "条444｜《医学纲目》卷十·三黄汤", "原文": "三黄汤  \n《医学纲目》卷十：三黄汤。治中风手足拘急，百节疼痛，烦热，心乱，恶寒，终日不欲饮食陈无择兼半身不遂，失音不言。  \n黄芪二钱 独活四钱 细辛二钱 麻黄五钱 黄芩三钱  \n上五味，以水六升，煮取二升。分温作三服。一服小汗，二服大汗。心热加大黄二钱；腹满加枳实一枚；气逆加人参三钱；悸加牡蛎三钱；渴加栝蒌根三钱；先有寒加附子一枚。", "白话": "《医学纲目》卷十载：三黄汤。治中风手足拘急，百节疼痛，烦热、心乱、恶寒，终日不欲饮食。陈无择兼治半身不遂、失音不言。（组成照录见原文。方义：麻黄、独活、细辛祛风散寒，黄芪益气固表，黄芩清热，为仲景三黄汤之变方。）上五味，用水六升，煮取二升，分温作三服。一服小汗，二服大汗。心热加大黄二钱；腹满加枳实一枚；气逆加人参三钱；悸加牡蛎三钱；渴加栝蒌根三钱；先有寒加附子一枚。"}, {"source": "条445｜《普济方》卷四十七·麝香天麻丸", "原文": "麝香天麻丸  \n《普济方》卷四十七：麝香天麻丸圣济总录。治风头旋目黑，肩背拘急，恍惚忪悸，肢节疼痛，宜服。  \n麝香研一钱半 天麻、天南星炮、白附子炮、羌活去芦头、赤茯苓去黑皮、干蝎去土炒、丹砂研、防风去叉、桂去粗皮、蝉蜕洗炒各一两半 乌蛇酒浸，去皮骨炙，二两 铅霜研一分  \n上除研者外，捣罗为末，再同研匀，炼蜜和丸，如梧桐子大，每服二十丸，温酒下，荆芥汤亦得，不拘时候。", "白话": "《普济方》卷四十七载：麝香天麻丸（《圣济总录》方）。治风头旋目黑，肩背拘急，恍惚忪悸，肢节疼痛，宜服。（组成照录见原文。方义：天麻、干蝎、乌蛇、防风、蝉蜕祛风通络，天南星、白附子化痰，麝香、铅霜、丹砂开窍镇心，赤茯苓、桂心利湿温经，为祛风化痰、镇心定悸之剂。）上药除研者外，捣罗为末，再同研匀，炼蜜和丸如梧桐子大。每服二十丸，温酒送下，荆芥汤也可以，不拘时候。"}, {"source": "条446｜《普济方》卷一百一·麻黄丸", "原文": "麻黄丸  \n《普济方》卷一百一：麻黄丸出圣济总录。治中风邪狂走，或自高自贤，或悲泣呻吟。及猝得惊悸邪魅，恍惚，心下虚悸。  \n麻黄去根节煎掠去沫焙、甘草炙锉、半夏汤浸生布揉洗七次焙，各一两 生姜去皮，一两半，先与半夏同捣炒干  \n上为末，炼蜜和丸如大豆大。生姜汤下三丸，加至五丸。空心午时各一服，渐加至十丸。", "白话": "《普济方》卷一百一载：麻黄丸（出《圣济总录》）。治中风邪狂走，或自高自贤，或悲泣呻吟；以及猝得惊悸邪魅、恍惚、心下虚悸。（组成照录见原文。方义：麻黄开郁散邪，半夏化痰降逆，甘草、生姜和中，为豁痰开郁、定悸之小方。）上药为末，炼蜜和丸如大豆大。生姜汤送下三丸，加至五丸。空心、午时各一服，渐加至十丸。"}, {"source": "条447｜《普济方》卷一百二·丹砂镇心丸", "原文": "丹砂镇心丸  \n《普济方》卷一百二：丹砂镇心丸。治风惊悸，或忧愁思虑，心神恍惚，狂言烦闷，口眼斜，化痰利咽膈。  \n丹砂别研，一两 牛黄别研、龙脑别研、麝香别研，各一钱 铅白霜别研、天竺黄各二钱 天麻酒炙二两 人参、茯苓去黑皮、甘草炙锉，各半两  \n上为末，和匀，炼蜜为丸，如鸡头大。每服三丸，煎金银薄荷汤化下，食后临卧服。", "白话": "《普济方》卷一百二载：丹砂镇心丸。治风惊悸，或忧愁思虑，心神恍惚，狂言烦闷，口眼歪斜，能化痰利咽喉胸膈。（组成照录见原文。方义：丹砂、铅白霜、天竺黄、牛黄、龙脑、麝香镇心开窍化痰，天麻熄风，人参、茯苓、甘草益气和中，为镇心安神、化痰开窍之剂。）上药为末，和匀，炼蜜为丸如鸡头大。每服三丸，煎金银薄荷汤化服，食后临卧服。"}, {"source": "条448｜《普济方》卷一百八十六·排风汤", "原文": "排风汤  \n《普济方》卷一百八十六：排风汤出《治风经验方》。治风疾，身体拘挛、麻痹，精神错乱，心多怔忡。  \n独活、白茯苓、麻黄去节，各一两半 白鲜皮、川芎、当归切焙、桂去皮不见火、甘草炙、杏仁去皮炒，各一两、  \n上捣筛为粗末，每服五钱，水一盏半，生姜四片，煎至一盏，滤去滓，通口服，空心食前，日进三服。", "白话": "《普济方》卷一百八十六载：排风汤（出《治风经验方》）。治风疾，身体拘挛、麻痹，精神错乱，心多怔忡。（组成照录见原文。方义：麻黄、独活、白鲜皮、川芎、当归祛风养血，桂心、杏仁、茯苓、甘草温中化饮，为祛风养血、化痰定忡之剂。）上药捣筛为粗末，每服五钱，用水一盏半、生姜四片，煎至一盏，滤去滓，通口服，空心食前，日进三服。"}, {"source": "条449｜《本草单方》卷七·天麻丸", "原文": "天麻丸  \n《本草单方》卷七：天麻丸。消风化痰，清利头目，宽胸利膈；治心忪烦闷，头运欲倒，项急，肩背拘倦，神昏多睡，肢节烦痛，皮肤搔痒，偏正头痛，鼻齆，面目虚浮，并宜服之。  \n天麻半两 芎二两  \n为末，炼蜜丸，如芡子大。每食后嚼一丸，茶酒任下。", "白话": "《本草单方》卷七载：天麻丸。能消风化痰，清利头目，宽胸利膈；治心忪烦闷、头旋欲倒、项急、肩背拘倦、神昏多睡、肢节烦痛、皮肤瘙痒、偏正头痛、鼻塞、面目虚浮，都宜服。（组成照录见原文。方义：川芎活血祛风上行头目，天麻熄风定眩，炼蜜为丸，风痰眩晕心忪之小方。）研为末，炼蜜丸如芡子大。每食后嚼一丸，茶酒任下。"}, {"source": "条450｜《古今医统大全》卷八十八·醒风汤", "原文": "醒风汤  \n《古今医统大全》卷八十八：醒风汤。治小儿吐泻后胃虚生风，手足搐搦惊悸。  \n天麻炮 防风 人参 白附子炮 全蝎毒炒 僵蚕去嘴炒 天南星 甘草炙  \n上咀，用姜三片、冬瓜仁三十粒同煎，不拘时服。", "白话": "《古今医统大全》卷八十八载：醒风汤。治小儿吐泻后胃虚生风，手足抽搦惊悸。（组成照录见原文。方义：天麻、全蝎、僵蚕熄风止痉，防风、白附子、天南星祛风化痰，人参、甘草益气和中，为熄风定惊、益气健胃之剂。）上药切碎，用姜三片、冬瓜仁三十粒同煎，不拘时候服。"}, {"source": "条451｜《万氏家抄济世良方》卷五·人参羌活散", "原文": "人参羌活散  \n《万氏家抄济世良方》卷五：人参羌活散。截风定搐、豁痰安神。  \n柴胡 天麻 前胡 人参 枳壳 茯神 羌活 桔梗 陈皮 防风 僵蚕 甘草  \n水煎，入姜汁、竹沥服。痰盛加南星；泻加泽泻、诃子；大便结加皂角；昏迷加黄连；壮热加黄芩；嗽加杏仁；天瘹加钩藤；心跳加当归；胸闷加枳壳；目连眶动及肝风加青皮、黄连。", "白话": "《万氏家抄济世良方》卷五载：人参羌活散。功能截风定搐、豁痰安神。（组成照录见原文。方义：羌活、柴胡、前胡、防风、僵蚕、天麻疏风定搐，人参、茯神、陈皮、枳壳、桔梗、甘草益气化痰安神，为扶正祛风、豁痰定惊之剂。）水煎，加入姜汁、竹沥服。痰盛加南星；泻加泽泻、诃子；大便结加皂角；昏迷加黄连；壮热加黄芩；咳嗽加杏仁；天瘹加钩藤；心跳加当归；胸闷加枳壳；目连眶动及肝风加青皮、黄连。"}, {"source": "条452｜《证治准绳·类方》·三黄汤", "原文": "三黄汤  \n《证治准绳·类方》：附：风拘挛方三黄汤集验。  \n治中风手足拘挛，百节疼痛，烦热心乱恶寒，不进饮食。兼治贼风，腲腿风，半身不随，失音不语。  \n麻黄一两，去节 黄芪去芦，半两 黄芩七钱半 独活一两，去芦  \n上为㕮咀，每服四钱，水一盏半，煎至七分，去渣温服，不拘时候。取汗为效。心热加大黄半两，胀满加枳实二钱半，气逆加人参七钱半，心悸加牡蛎七钱半，渴加栝蒌根七钱半，寒加附子一枚，炮熟入药", "白话": "《证治准绳·类方》附载：治风拘挛方三黄汤（《集验》方）。治中风手足拘挛，百节疼痛，烦热心乱恶寒，不进饮食；兼治贼风、腲腿风、半身不遂、失音不语。（组成照录见原文。方义：麻黄、独活祛风，黄芪益气固表，黄芩清热，即三黄汤法。）上药切碎，每服四钱，用水一盏半，煎至七分，去渣温服，不拘时候，以取汗为效。心热加大黄半两，胀满加枳实二钱半，气逆加人参七钱半，心悸加牡蛎七钱半，渴加栝蒌根七钱半，寒加附子一枚炮熟入药。"}, {"source": "条453｜《婴童类萃》上卷·天麻定惊丸", "原文": "天麻定惊丸  \n《婴童类萃》上卷：天麻定惊丸。治小儿急慢惊风，身体壮热，精神恍惚，痰涎多睡，惊悸不安，手足搐搦，并宜服之。  \n天麻明、僵蚕炒、防风、人参各五钱 甘草、朱砂、全蝎各三钱 雄黄一钱五分 牛黄一钱 麝香三分  \n为末，蜜丸，芡实大，每服一丸，薄荷汤下。", "白话": "《婴童类萃》上卷载：天麻定惊丸。治小儿急慢惊风，身体壮热，精神恍惚，痰涎多、多睡，惊悸不安，手足抽搦，都宜服。（组成照录见原文。方义：天麻、僵蚕、全蝎熄风止痉，防风祛风，朱砂、牛黄、麝香、雄黄镇惊开窍，人参、甘草益气和中，为熄风定惊、开窍化痰之剂。）研为末，蜜丸芡实大，每服一丸，薄荷汤送下。"}, {"source": "条454｜《杂病源流犀烛》卷二十五·天麻丸", "原文": "天麻丸  \n《杂病源流犀烛》卷二十五：风痰闭壅眩晕，必胸膈痞塞，项急，肩背拘倦，神昏多睡，或心忪烦闷而发宜天麻五钱，川芎二两，蜜丸芡子大，食后清茶嚼下一丸，名天麻丸。", "白话": "《杂病源流犀烛》卷二十五载：风痰闭阻而眩晕，必见胸膈痞塞、颈项紧急、肩背拘倦、神昏多睡，或心忪烦闷而发。宜用天麻五钱、川芎二两，蜜丸芡子大，食后清茶嚼服一丸，名叫天麻丸。"}, {"source": "条455｜《竹林女科证治》卷三·佛手散", "原文": "佛手散  \n《竹林女科证治》卷三：产后少阳感风。谵语、烦躁，更加惊悸者死，盖少阳胆也。胆无汁不能润心，心无血不能为养。是以心中恍惚而谵语、烦躁、惊悸相因而生也。夫胆受邪不发表则血无以生，然徒发表则血更耗散。宜佛手散，加人参、枣仁、麦冬、竹茹、朱砂、熟地黄治之。", "白话": "《竹林女科证治》卷三载：产后少阳经受风，出现谵语、烦躁，再加惊悸者死。因为少阳属胆，胆无汁液不能润心，心无血不能受养，所以心中恍惚而谵语、烦躁、惊悸相继而生。胆受邪不发表则血无以生，然单发表则血更耗散。宜用佛手散，加人参、枣仁、麦冬、竹茹、朱砂、熟地黄治之。"}, {"source": "条456｜《金匮要略浅注》卷二·千金三黄汤", "原文": "千金三黄汤  \n《金匮要略浅注》卷二：千金三黄汤。治中风，手足拘急，百节疼痛，烦热心乱，恶寒，经曰不欲饮食。  \n麻黄五分 独活四分 细辛、黄芪各二分 黄芩三分  \n上五味。以水六升。煮取二升。分温三服。一服小汗出。二服大汗出。心热加大黄二分。腹满加枳实一枚。气逆加人参三分。悸加牡蛎三分。渴加栝蒌根三分。先有寒，加附子一枚。", "白话": "《金匮要略浅注》卷二载：千金三黄汤。治中风，手足拘急，百节疼痛，烦热心乱，恶寒，整日不欲饮食。（组成照录见原文。方义：麻黄、独活、细辛祛风散寒，黄芪益气，黄芩清热，即《千金》三黄汤。）上五味，用水六升，煮取二升，分温三服。一服小汗出，二服大汗出。心热加大黄二分；腹满加枳实一枚；气逆加人参三分；悸加牡蛎三分；渴加栝蒌根三分；先有寒加附子一枚。"}, {"source": "条457｜《医略十三篇》卷一·真黄风汤", "原文": "真黄风汤  \n《医略十三篇》卷一：或证言微蹇，或面戴阳色，或消谷善饥，或饮食少进，或浊痰未清，或肢体无力，或无故多思，或怔忡惊悸不寐等证，接服第三方调理。第三真黄风汤，主治真中风，服前二方，表里俱和，诸证悉退，或二气未充，或余氛未尽，宜此方调理，真善后之良法也。  \n炙黄芪三钱 防风根三分 人参钱半 大熟地四钱 云茯苓三钱 炙甘草五分 制半夏钱半 福橘皮一钱 麸炒枳实五分 豨莶三钱  \n长流水煎服", "白话": "《医略十三篇》卷一载：或语言微有謇涩，或面带戴阳之色，或消谷善饥，或饮食少进，或浊痰未清，或肢体无力，或无故多思，或怔忡惊悸不寐等证，接着服第三方调理。第三是真黄风汤，主治真中风：服前二方后表里俱和、诸证悉退，或二气未充，或余邪未尽，宜此方调理，真是善后之良法。（组成照录见原文。方义：黄芪、人参、炙甘草益气，熟地养血，半夏、橘皮、枳实化痰理气，茯苓健脾，防风、豨莶祛风通络，为益气养血、化痰祛风之善后方。）用长流水煎服一二剂，或三五剂至十剂后；或再以十剂为末，水叠为丸，每早晚开"}, {"source": "条458｜《备急千金要方》卷九·阳旦汤", "原文": "阳旦汤  \n《备急千金要方》卷九：阳旦汤。治伤寒中风脉浮，发热往来，汗出恶风，头项强，鼻鸣干呕，桂枝汤主之。随病加减如下方。  \n以泉水一斗煮取四升分服一升，日三。自汗者，去桂枝加附子一枚。渴者去桂加栝蒌根三两。利者去芍药、桂，加干姜三累、附子一枚炮。心下悸者，去芍药加茯苓四两。虚劳里急正阳旦主之。煎得二升，纳胶饴半斤，为再服。若脉浮紧发热者，不可与之。", "白话": "《备急千金要方》卷九载：阳旦汤。治伤寒中风脉浮，发热往来，汗出恶风，头项强痛，鼻鸣干呕，用桂枝汤主治，随病加减如下方。（组成照录见原文。方义：阳旦汤即桂枝汤加黄芩，解肌和营、清热，加减法随证出入。）用泉水一斗煮取四升，分服一升，日三服。自汗的去桂枝加附子一枚；渴的去桂加栝蒌根三两；下利的去芍药、桂，加干姜三累、附子一枚炮；心下悸的去芍药加茯苓四两；虚劳里急用正阳旦主治。煎得二升，加入胶饴半斤，分再服。若脉浮紧发热的，不可给服。"}, {"source": "条459｜《幼幼新书》卷十三·生姜汤", "原文": "生姜汤  \n《幼幼新书》卷十三：《婴孺》治少小中风，脉浮发热，汗不出头，鼻鸣干呕，生姜汤方。  \n生姜、甘草炙、芍药各一两  桂心三两  枣十个，去核  \n上以水三升，煮取一升，为三服。自汗出者，加附子一个小者；如渴，去桂枝，加栝蒌半两；痢作去芍药、加干姜三分、附子小者一个炮；心下悸去芍药加茯苓三两；表虚里实，去桂加胶饴二两。", "白话": "《幼幼新书》卷十三引《婴孺》：治少小中风，脉浮发热，汗不出，头项强，鼻鸣干呕，用生姜汤方。（组成照录见原文。方义：生姜、桂心解表散寒，芍药和营，甘草、大枣和中，为小儿中风表实之桂枝汤变方。）上药用水三升，煮取一升，分三服。自汗出的加小个附子一个；如渴，去桂枝加栝蒌半两；下痢的去芍药，加干姜三分、小个附子一个炮；心下悸的去芍药加茯苓三两；表虚里实的，去桂加胶饴二两。"}, {"source": "条460｜《妇人大全良方》卷二十二·阳旦汤", "原文": "阳旦汤  \n《妇人大全良方》卷二十二：治妇人产后伤风十数日不解，头微痛，恶寒，时时有热，心下坚，干呕，汗出，宜阳旦汤。  \n桂枝、芍药各三两  甘草炙、黄芩各二两  \n上㕮咀，每服三钱。水一盏，姜三片，枣一枚，煎至七分，去滓温服，无时候。自汗者，去桂，加炮熟附子一枚；渴者，去桂，加栝蒌根三两；下痢者，去芍药，加干姜三两；心下悸者，去芍药，加茯苓四两；虚劳里急者，正阳旦汤主之，煎时入胶饴为佳。若脉浮", "白话": "《妇人大全良方》卷二十二载：治妇人产后伤风十几天不愈，头微痛，恶寒，时时发热，心下坚，干呕，汗出，宜用阳旦汤。（组成照录见原文。方义：桂枝汤加黄芩，解肌和营兼清里热，为产后中风之剂。）上药切碎，每服三钱。用水一盏，姜三片、枣一枚，煎至七分，去滓温服，不拘时候。自汗的去桂，加炮熟附子一枚；渴的去桂，加栝蒌根三两；下痢的去芍药，加干姜三两；心下悸的去芍药，加茯苓四两。"}, {"source": "条461｜《经验良方全集》卷四·升麻葛根汤", "原文": "《经验良方全集》卷四：出痘形证。痘发时身热呕吐，体痛腹痛，烦躁喷嚏，惊悸昏倦……惊悸谵语妄视，小便通忌睡发汗，以后忌痰。已发热时，寒战、咬牙、惊悸者，勿虑，此毒欲出，与皮肉相撞也。如太甚，以升麻葛根汤一剂而愈。", "白话": "《经验良方全集》卷四载：出痘形证。痘发时身热呕吐，体痛腹痛，烦躁喷嚏，惊悸昏倦……惊悸谵语妄视，小便通利者忌睡中发汗，以后忌痰。已发热时寒战、咬牙、惊悸的，不必忧虑，这是毒气将出、与皮肉相撞所致。"}, {"source": "条462｜《傅氏杂方·附录》·无名方", "原文": "无名方  \n《傅氏杂方·附录》：第二方治外感也，或伤风伤寒，或咳嗽，或发热，或不发热，或头痛，或鼻塞，或痰多，或惊悸，或角弓反张，皆以此方通治之，无不神效，方用：  \n柴胡七分 甘草三分 桔梗五分 半夏三分 黄芩三分 白芍二钱 当归五分 茯苓五分  \n水煎服。头痛者，加蔓荆子三分。心痛手不可按者，乃实火也，加栀子一钱；按之不痛者，乃虚火也，加甘草八分、管仲五分、广木香三分、乳香一分。胁痛者，加白芍", "白话": "《傅氏杂方·附录》载：第二方治外感：或伤风伤寒，或咳嗽，或发热或不发热，或头痛，或鼻塞，或痰多，或惊悸，或角弓反张，都以此方通治，无不神效。方用：（组成照录见原文。方义：柴胡、黄芩和解少阳，桔梗、半夏、茯苓、甘草化痰和中，白芍、当归养血，为和解化痰、通治外感之方。）水煎服。头痛加蔓荆子三分；心痛手不可按的是实火，加栀子一钱；按之不痛的是虚火，加甘草八分、管仲五分、广木香三分、乳香一分；胁痛加白芍三钱；腹痛以手按之而疼甚的（原稿下缺）。"}, {"source": "条463｜《伤寒论·辨少阴病脉证并治》·四逆散", "原文": "海藻汤  \n  \n《伤寒论·辨少阴病脉证并治》：“少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，四逆散主之。  \n甘草炙、  枳实破，水渍，炙干、  柴胡、  芍药  \n上四味，各十分，捣筛，白饮和服方寸匕，日三服。咳者，加五味子、干姜各五分，并主下利；悸者，加桂枝五分；小便不利者，加茯苓五分；腹中痛者，加附子一枚，炮令坼；泄利下重者，先以水五升，煮薤白三升，煮取三升，去滓，以", "白话": "《伤寒论·辨少阴病脉证并治》：「少阴病，四肢厥冷，其人或咳嗽，或心悸，或小便不利，或腹中痛，或泄泻下重的，用四逆散主治。（组成照录见原文。方义：柴胡疏肝透邪，枳实行气，芍药和血，甘草和中，为疏肝理气、调和肝脾之基础方；悸者加桂枝通阳。）上四味各十分，捣筛，白饮和服方寸匕，日三服。咳嗽加五味子、干姜各五分，并主下利；心悸加桂枝五分；小便不利加茯苓五分；腹中痛加附子一枚炮令坼；泄利下重的先用水五升……」"}, {"source": "条464｜《伤寒论·辨太阳病脉证并治下》·炙甘草汤", "原文": "《伤寒论·辨太阳病脉证并治下》：“伤寒脉结代，心动悸，炙甘草汤主之。  \n甘草炙，四两 生姜切，三两 人参二两 生地黄一斤 桂枝去皮，三两 阿胶二两 麦门冬去心，半升 麻仁半升 大枣擘，三十枚  \n上九味，以清酒七升，水八升，先煮八味，取三升，去滓，内胶烊消尽，温服一升，日三服。一名复脉汤。", "白话": "《伤寒论·辨太阳病脉证并治下》：「伤寒脉结代、心动悸，用炙甘草汤主治。（组成照录见原文。方义：炙甘草、人参、大枣益气，生地、麦冬、麻仁、阿胶滋阴养血，桂枝、生姜、清酒通阳复脉，为益气滋阴、通阳复脉之名方，主治脉结代、心动悸。）上九味，用清酒七升、水八升，先煮八味取三升，去滓，加入阿胶烊化消尽，温服一升，日三服。又名复脉汤。」"}, {"source": "条465｜《伤寒论·辨厥阴病脉证并治》·茯苓甘草汤", "原文": "《伤寒论·辨厥阴病脉证并治》：“伤寒厥而心下悸，宜先治水，当服茯苓甘草汤，却治其厥，不尔，水渍入胃，必作利也。  \n茯苓二两 甘草炙，一两 生姜切，三两 桂枝去皮，二两  \n上四味，以水四升，煮取二升，去滓，分温三服。", "白话": "《伤寒论·辨厥阴病脉证并治》：「伤寒四肢厥冷而心下悸，应当先治水，当服茯苓甘草汤，然后再治其厥；否则水渍入胃，必致下利。（组成照录见原文。方义：茯苓、桂枝通阳化饮，甘草、生姜和中散水，即苓桂姜甘汤，为温阳化饮、治心下悸之方。）上四味，用水四升，煮取二升，去滓，分温三服。」"}, {"source": "条466｜《伤寒论·辨霍乱病脉证并治》·理中丸（并论五苓散）", "原文": "《伤寒论·辨霍乱病脉证并治》：“霍乱，头痛、发热、身疼痛、热多欲饮水者，五苓散主之；寒多不用水者，理中丸主之。  \n人参、 干姜、 甘草炙、 白术各三两  \n上四味，捣筛，蜜和为丸，如鸡子黄许大。以沸汤数合，和一丸，研碎，温服之，日三四、夜二服；腹中未热，益至三四丸，然不及汤。汤法：以四物依两数切，用水八升，煮取三升，去滓，温服一升，日三服。若脐上筑者，肾气动也，去术加桂四两；吐多者，去术加生姜三", "白话": "《伤寒论·辨霍乱病脉证并治》：「霍乱，头痛、发热、身疼痛、热多想饮水的，用五苓散主治；寒多不想喝水的，用理中丸主治。（组成照录见原文。方义：人参、白术、甘草、干姜温中健脾，为理中丸；五苓散化气利水，此条并论二方。）上四味，捣筛，蜜和为丸如鸡子黄许大。用沸汤数合，和一丸研碎温服，日三四次、夜二次服；腹中未热，加至三四丸，但不及汤剂。汤法：按四味药的两数切碎，用水八升煮取三升，去滓，温服一升，日……」"}, {"source": "条467｜《金匮玉函经》·小建中汤", "原文": "《金匮玉函经》：“伤寒，二三日，心中悸而烦，小建中汤主之。  \n桂枝去皮，三两 甘草炙，二两 大枣擘，十二枚 芍药六两 生姜切，三两 胶饴一升  \n上六味，以水七升，煮取三升，去滓，内饴，更上微火消解。温服一升，日三服。呕家不可用建中汤，以甜故也。", "白话": "《金匮玉函经》：「伤寒二三日，心中悸而烦，用小建中汤主治。（组成照录见原文。方义：桂枝汤倍芍药加胶饴，温中补虚、和里缓急，治中焦虚寒、心中悸烦。）上六味，用水七升，煮取三升，去滓，加入饴糖，再上微火消解。温服一升，日三服。呕家不可用建中汤，因为味甜之故。」"}, {"source": "条468｜《金匮玉函经》卷二·小柴胡汤", "原文": "《金匮玉函经》卷二：“中风，五六日，伤寒，往来寒热，胸胁苦满，嘿嘿不欲饮食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞坚，或心中悸，小便不利，或不渴，外有微热，或咳，小柴胡汤主之。  \n柴胡半斤 黄芩三两 人参三两 半夏洗，半升 甘草炙、生姜切，各三两 大枣擘，十二枚  \n上七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。若胸中烦而不呕者，去半夏人参，加栝蒌实一枚……若心", "白话": "《金匮玉函经》卷二：「中风五六日，伤寒，往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕；或胸中烦而不呕，或口渴，或腹中痛，或胁下痞坚，或心中悸、小便不利，或不渴、外有微热，或咳嗽，用小柴胡汤主治。（组成照录见原文。方义：柴胡、黄芩和解少阳，半夏、生姜和胃降逆，参枣草益气，为和解少阳之主方；心下悸、小便不利者去黄芩加茯苓。）上七味，用水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。若胸中烦而不呕，去半夏、人参加栝蒌实一枚……若心下悸、小便不利，去黄芩，加茯苓四两；若不渴、"}, {"source": "条469｜《金匮要略方论》卷中·半夏麻黄丸", "原文": "《金匮要略方论》卷中：“寸口脉动而弱，动即为惊，弱则为悸。心下悸者，半夏麻黄丸主之。  \n半夏、麻黄等分  \n上二味，末之，炼蜜和丸小豆大，饮服三丸，日三服。", "白话": "《金匮要略方论》卷中：「寸口脉动而弱，动即为惊，弱则为悸。心下悸的，用半夏麻黄丸主治。（组成照录见原文。方义：半夏蠲饮降逆，麻黄宣阳散水，蜜丸小量，治水饮内停、心下悸动。）上二味，研末，炼蜜和丸小豆大，饮服三丸，日三服。」"}, {"source": "条470｜《金匮玉函经》卷二·桂枝甘草汤", "原文": "《金匮玉函经》卷二：“发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之。  \n桂枝四两，去皮 甘草二两，炙  \n上二味，以水三升，煮取一升，去滓，顿服。", "白话": "《金匮玉函经》卷二：「发汗过多，其人两手交叉自按护心胸部，心下悸、想要按压的，用桂枝甘草汤主治。（组成照录见原文。方义：桂枝、甘草辛甘化阳，温补心阳，为治心阳虚悸之最小方。）上二味，用水三升，煮取一升，去滓，一次服尽。」"}, {"source": "条471｜《金匮玉函经》·茯苓桂枝甘草大枣汤", "原文": "《金匮玉函经》：“发汗后，其人脐下悸者，欲作奔豚，茯苓桂枝甘草大枣汤主之。  \n茯苓半斤  桂枝四两，去皮  甘草二两，炙  大枣十五枚，擘  \n上四味，以甘澜水一斗，先煮茯苓，减二升，内诸药，煮取三升，去滓，温服一升，日三服。作甘澜水法：取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相逐，取用之。", "白话": "《金匮玉函经》：「发汗后，其人脐下悸动，将要发作奔豚的，用茯苓桂枝甘草大枣汤主治。（组成照录见原文。方义：茯苓利水，桂枝通阳，甘草、大枣培土制水，防奔豚发作，为温阳化饮、平冲定悸之方。）上四味，用甘澜水一斗，先煮茯苓减二升，放入诸药煮取三升，去滓，温服一升，日三服。作甘澜水法：取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相追逐，取用。」"}, {"source": "条472｜《金匮玉函经》卷二·真武汤", "原文": "《金匮玉函经》卷二：“太阳病，发其汗而不解，其人仍发热，心下悸，头眩身瞤而动，振振欲擗地者，真武汤主之。  \n茯苓三两  芍药三两  白术二两  生姜切，三两  附子炮，去皮，破八片，一枚  \n上五味，以水八升，煮取三升，去滓。温服七合，日三服。若咳者，加五味子半升，细辛一两，干姜一两；若小便利者，去茯苓；若下利者，去芍药，加干姜二两；若呕者，去附子，加生姜，足前为半斤。", "白话": "《金匮玉函经》卷二：「太阳病，发汗而不解，其人仍发热，心下悸，头眩身瞤动，颤颤欲扑地的，用真武汤主治。（组成照录见原文。方义：附子温肾阳，茯苓、白术健脾利水，生姜散水，芍药和营敛阴，为温阳利水之主方，治阳虚水泛之心悸头眩。）上五味，用水八升，煮取三升，去滓。温服七合，日三服。若咳嗽，加五味子半升、细辛一两、干姜一两；若小便利，去茯苓；若下利，去芍药加干姜二两；若呕，去附子加生姜足前成半斤。」"}, {"source": "条473｜《肘后备急方》卷三·无名方（心下虚悸方）", "原文": "《肘后备急方》卷三：“治人心下虚悸方。  \n麻黄、半夏等分。  \n捣蜜丸。服如大豆三丸，日三，稍增之。半夏汤洗去滑，干。  \n附方：张仲景主心下悸，半夏麻黄丸。二物等分，末，蜜丸如小豆。每服三丸，日三。", "白话": "《肘后备急方》卷三：「治人心下虚悸方：（组成照录见原文。方义：麻黄、半夏等分蜜丸，宣阳蠲饮，治水饮心下悸，与《金匮》半夏麻黄丸同法。）捣碎蜜丸。服如大豆三丸，日三服，渐增。半夏用汤洗去滑，晒干。附方：张仲景主治心下悸，用半夏麻黄丸。二物等分，研末，蜜丸如小豆大。每服三丸，日三服。」"}, {"source": "条474｜《小品方》卷一·游气汤", "原文": "《小品方》卷一：“游气汤。治五脏有余寒虚气、劳气、惊忧气，其人喜悸，胸中热，上下无常，多悲伤，气流四肢常肿，齐四边核赤肿，小便不利方。  \n厚朴四两  桂肉五两  人参二两  茯苓四两  半夏二两，洗  黄芩二两  生姜八两  陈枳实五枚  甘草二两  \n凡九物，以水一斗，煮取四升，分三服。", "白话": "《小品方》卷一：「游气汤。治五脏有余寒虚气、劳气、惊忧气：其人容易心悸，胸中热，气上下无常，多悲伤，气流于四肢常肿，脐四边核赤肿，小便不利之方。（组成照录见原文。方义：厚朴、枳实、桂心、生姜温中下气，人参、茯苓、甘草益气健脾，半夏、黄芩化痰清热，为行气散结、温中定悸之方。）共九味药，用水一斗，煮取四升，分三服。」"}, {"source": "条475｜《小品方》卷三·龙骨汤", "原文": "《小品方》卷三：“龙骨汤。治梦失精，诸脉浮动，心悸少急，隐处寒，目眶疼，头发脱者，常七日许一剂，至良方。  \n龙骨、甘草炙，各二分  牡蛎三分，熬 、桂心、芍药各四分  大枣四枚，擘  生姜五分  \n上七味，切，以水四升，煮取一升半，分再服。", "白话": "《小品方》卷三：「龙骨汤。治梦遗失精，诸脉浮动，心悸而急，前阴寒冷，目眶疼，头发脱落。常七日左右服一剂，是极好的方。（组成照录见原文。方义：龙骨、牡蛎镇摄固涩，桂心、芍药调和阴阳，甘草、大枣、生姜和中，为潜镇固涩、调和阴阳之剂。）上七味，切碎，用水四升，煮取一升半，分两次服。」"}, {"source": "条476｜《小品方》卷五·九痛丸", "原文": "《小品方》卷五：“九痛丸。主九种心痛。一虫心痛，二注心痛，三风心痛，四悸心痛，五食心痛，六饮心痛，七冷心痛，八热心痛，九生来心痛，方悉主之。并治冷肿上气，落马堕车方。  \n附子二两  巴豆仁一两  生狼毒一两，炙令极香、抨》  人参一两  干姜一两  吴食茱萸一两  \n六味，蜜和，空腹服如梧子三丸。卒中恶腹痛，口不言，二日一服。连年积冷，流注心胸者，亦服之，好好将息，神验。", "白话": "《小品方》卷五：「九痛丸。主治九种心痛：一虫心痛，二注心痛，三风心痛，四悸心痛，五食心痛，六饮心痛，七冷心痛，八热心痛，九生来心痛，一方都主治。并治冷肿上气、落马堕车之方。（组成照录见原文。方义：附子、干姜、吴茱萸温中散寒，巴豆攻冷积，狼毒破积聚，人参扶正，为温通攻积、治九种心痛之峻剂。）六味，蜜和，空腹服如梧子大三丸。卒中恶腹痛、口不能言的，二日一服。连年积冷、流注心胸的，也服之，好好将息，神验。」"}, {"source": "条477｜《小品方》卷四·理中汤", "原文": "《小品方》卷四：“霍乱脐上筑者，肾气动也，先治气，理中汤去术加桂。凡方加术者，以内虚也；加桂者，恐作奔豚也，理中汤方。  \n人参三两  甘草三两，炙  白术三两  干姜三两，炮  \n上四味，切，以水八升，煮取三升，去滓，温服一升，日三夜一。  \n若脐上筑者，肾气动也，去术加桂心四两；吐多者，去术加生姜三两；若下多者，复用术，悸者加茯苓二两；若病先时渴喜得水者，加术合前成四两半；若腹中痛者，加人参合", "白话": "《小品方》卷四：「霍乱脐上筑动的，是肾气动，先治气，用理中汤去术加桂。凡方中加白术的，是因为内虚；加桂的，是恐发作奔豚。理中汤方：（组成照录见原文。方义：人参、白术、甘草、干姜温中健脾，即理中汤；脐上悸为肾气动，去术加桂温肾平冲。）上四味，切碎，用水八升，煮取三升，去滓，温服一升，日三夜一服。若脐上筑动（肾气动），去术加桂心四两；吐多的去术加生姜三两；下多的仍用白术；心悸的加茯苓二两；若病前口渴喜饮水的，加白术合成四两半；腹中痛的加人参合成四两半；恶寒的加干姜合成四两半；腹满"}, {"source": "条478｜《刘涓子鬼遗方》卷二·㹠心汤", "原文": "《刘涓子鬼遗方》卷二：“治金疮惊悸，心中满满如车所惊怛，㹠心汤方。  \n㹠心一具  人参  桂心  甘草炙  干地黄  桔梗  石膏末  芎  当归二两  \n上九味，细切锉，诸药㕮咀，先以水二斗煮心，取汁八升，纳诸药，煮取一升，一服八合，一日令尽。", "白话": "《刘涓子鬼遗方》卷二：「治金疮惊悸，心中满闷如受车马惊吓，用㹠心汤方。（组成照录见原文。方义：㹠（豚）心以心补心、引药入心，配人参、桂心、甘草益气通阳，干地黄、当归、芎䓖养血，桔梗、石膏宣肺清热，为治金疮惊悸之方。）上九味，细切锉，诸药切碎，先用水二斗煮猪心取汁八升，放入诸药，煮取一升，一次服八合，一日服尽。」"}, {"source": "条479｜《备急千金要方》卷三·人参丸", "原文": "《备急千金要方》卷三：“人参丸。治产后大虚，心悸，志意不安，不自觉恍惚恐畏，夜不得眠，虚烦少气方。  \n人参、甘草、茯苓各三两  麦门冬、菖蒲、泽泻、薯蓣、干姜各二两  桂心一两  大枣五十枚  \n上十味为末，以蜜枣膏和丸如梧子，未食酒服二十丸，日三夜一，不知稍增。若有远志，纳二两佳。若风气加当归、独活各三两。亦治男子虚损心悸。", "白话": "《备急千金要方》卷三：「人参丸。治产后大虚，心悸，志意不安，不自觉恍惚恐畏，夜不得眠，虚烦少气之方。（组成照录见原文。方义：人参、甘草、茯苓、薯蓣、大枣益气健脾，麦冬、菖蒲、泽泻养心开窍利湿，干姜、桂心温中，为产后心虚心悸之补益剂。）上十味为末，以蜜枣膏和丸如梧子大，饭前酒服二十丸，日三夜一服，不效渐增。若有远志，加入二两更好。若风气加当归、独活各三两。也治男子虚损心悸。」"}, {"source": "条480｜《备急千金要方》卷三·大远志丸", "原文": "《备急千金要方》卷三：“大远志丸。治产后心虚不足，心下虚悸志意不安，恍恍惚惚，腹中拘急痛，夜卧不安，胸中吸吸少气，内补伤损，益气，安定心神，亦治虚损方。  \n远志、甘草、桂心、茯苓、麦门冬、人参、当归、白术、泽泻、独活、菖蒲各三两  薯蓣、阿胶各二两  干姜四两  干地黄五两  \n上十五味为末，蜜和丸如大豆，未食温酒服二十丸，日三，不知稍增，至五十丸。若大虚，身体冷，少津液，加钟乳三两为善。", "白话": "《备急千金要方》卷三：「大远志丸。治产后心虚不足，心下虚悸，志意不安，恍恍惚惚，腹中拘急痛，夜卧不安，胸中吸吸少气；能内补伤损，益气，安定心神，也治虚损之方。（组成照录见原文。方义：远志、菖蒲、茯神安神定志，参苓术草薯蓣益气健脾，归地麦冬阿胶养血滋阴，桂心干姜温阳，独活泽泻祛风利湿，为气血阴阳兼补、安神定悸之剂。）上十五味为末，蜜和丸如大豆，饭前温酒服二十丸，日三服，不效渐加至五十丸。若大虚、身体冷、津液少，加钟乳石三两为好。」"}, {"source": "条481｜《备急千金要方》·内补黄芪汤", "原文": "《备急千金要方》：“内补黄芪汤。治妇人七伤，身体疼痛，小腹急满，面目黄黑，不能饮食并诸虚乏不足，少气，心悸不安方。  \n黄芪、当归、芍药、干地黄、半夏各三两  茯苓、人参、桂心、远志、麦门冬、甘草、五味子、白术、泽泻各二两  干姜四两  大枣三十枚  \n上十六味，㕮咀，以水一斗半，煮取三升，去滓，一服五合，日三夜一服。", "白话": "《备急千金要方》：「内补黄芪汤。治妇人七伤，身体疼痛，小腹急满，面目黄黑，不能饮食及诸虚乏不足，少气，心悸不安之方。（组成照录见原文。方义：黄芪、人参、白术、甘草、大枣益气，四物养血，半夏、茯苓、泽泻化痰利湿，麦冬、五味子滋阴敛气，桂心、干姜、远志温阳安神，为大补气血、安神定悸之剂。）上十六味切碎，用水一斗半，煮取三升，去滓，一次服五合，日三夜一服。」"}, {"source": "条482｜《备急千金要方》卷三·甘草丸", "原文": "《备急千金要方》卷三：“甘草丸。治产后心虚不足，虚悸，心神不安，吸吸乏气，或若恍恍惚惚，不自知觉者方。  \n甘草、远志、菖蒲各三两  人参、麦门冬、干姜、茯苓各二两  泽泻、桂心各一两  大枣五十枚  \n上十味为末，蜜和丸如大豆，酒服二十丸，日四五服，夜再服，不知稍加。若无泽泻，以白术代之。若胸中冷，增干姜。", "白话": "《备急千金要方》卷三：「甘草丸。治产后心虚不足，虚悸，心神不安，短气乏力，或恍恍惚惚不自知觉之方。（组成照录见原文。方义：甘草、人参、茯苓、大枣益气健脾，远志、菖蒲、麦冬安神养心，干姜、桂心、泽泻温阳利湿，为益气安神之小补剂。）上十味为末，蜜和丸如大豆，酒服二十丸，日四五服，夜再服，不效渐加。若无泽泻，以白术代之。若胸中冷，增加干姜。」"}, {"source": "条483｜《备急千金要方》卷三·安心汤", "原文": "《备急千金要方》卷三：“安心汤。治产后心忡悸不定，恍恍惚惚，不自知觉，言语错误，虚烦短气，志意不定，此是心虚所致方。  \n远志、甘草各二两  人参、茯神、当归、芍药各三两  麦门冬一升  大枣三十枚  \n上八味㕮咀味，㕮咀，以水一斗，煮取三升，去滓，分三服，日三。若苦虚烦短气者，加淡竹叶二升，水一斗二升，煮竹叶取一斗，纳药。若胸中少气者，加甘草为三两善。", "白话": "《备急千金要方》卷三：「安心汤。治产后心中怔忡悸动不定，恍恍惚惚不自知觉，言语错误，虚烦短气，志意不定，这是心虚所致之方。（组成照录见原文。方义：远志、茯神、麦冬、大枣养心安神，人参、甘草益气，当归、芍药养血，为益气养血、安心定志之剂。）上八味切碎，用水一斗，煮取三升，去滓，分三服，日三。若苦于虚烦短气，加淡竹叶二升，用水一斗二升先煮竹叶取一斗再放药。若胸中气少，加甘草至三两为好。」"}, {"source": "条484｜《备急千金要方》卷三·竹叶汤", "原文": "《备急千金要方》卷三：“竹叶汤。治产后心中烦闷不解方。  \n生淡竹叶、麦门冬各一升  甘草二两  生姜、茯苓各三两  大枣十四枚  小麦五合  \n上七味，㕮咀，以水一斗，先煮竹叶、小麦，取八升，纳诸药，煮取三升，去滓，分三服。若心中虚悸者，加人参二两。", "白话": "《备急千金要方》卷三：「竹叶汤。治产后心中烦闷不解之方。（组成照录见原文。方义：竹叶、小麦清心除烦，麦冬养阴，茯苓、甘草、大枣、生姜和中，为产后虚烦之清润剂。）上七味切碎，用水一斗，先煮竹叶、小麦取八升，放入诸药，煮取三升，去滓，分三服。若心中虚悸的，加人参二两。」"}, {"source": "条485｜《备急千金要方》卷三·远志汤", "原文": "《备急千金要方》卷三：“远志汤。治产后忽苦心中忡悸不定，志意不安，言语错误，惚惚愦愦，情不自觉方。  \n远志、麦门冬、人参、甘草、当归、桂心各二两  芍药一两  茯苓五两  生姜六两  大枣二十枚  \n上十味㕮咀味，㕮咀，以水一斗煮取三升，去滓，分三服，日三。羸者分四服。产后得此，正是心虚所致。无当归用芎，若其人心胸逆气，加半夏三两。", "白话": "《备急千金要方》卷三：「远志汤。治产后忽然苦于心中怔忡悸动不定，志意不安，言语错误，恍惚昏愦，情不自知之方。（组成照录见原文。方义：远志、茯苓、麦冬、大枣养心安神，参草益气，归芍养血，桂心、生姜温通，为益气养血、安神定志之剂。）上十味切碎，用水一斗煮取三升，去滓，分三服，日三。瘦弱人分四服。产后得此证正是心虚所致。无当归用芎䓖；若其人心胸有逆气，加半夏三两。」"}, {"source": "条486｜《备急千金要方》卷三·茯苓汤", "原文": "《备急千金要方》卷三：“茯苓汤。治产后暴苦心悸不安，言语错谬，恍恍惚惚，心中愦愦，此皆心虚所致方。  \n茯苓五两  甘草、芍药、桂心、当归各二两  生姜六两  麦门冬一升  大枣三十枚  \n上八味㕮咀味，㕮咀，以水一斗，煮取三升，去滓，分三服，日三。", "白话": "《备急千金要方》卷三：「茯苓汤。治产后突然心悸不安，言语错谬，恍恍惚惚，心中昏乱，这都是心虚所致之方。（组成照录见原文。方义：茯苓、甘草、桂心、生姜温阳化饮、和中，当归、芍药、麦冬、大枣养血安神，为养血温阳、定悸安神之剂。）上八味切碎，用水一斗，煮取三升，去滓，分三服，日三。」"}, {"source": "条487｜《备急千金要方》卷三·茯神汤", "原文": "《备急千金要方》卷三：“茯神汤。治产后忽苦，心中忡悸，或志意不定，恍恍惚惚，言语错谬，心虚所致方。  \n茯神四两  人参、茯苓各三两  芍药、甘草、当归、桂心各一两  生姜八两  大枣三十枚  \n上九味㕮咀味，㕮咀，以水一斗，煮取三升，去滓，分三服，日三良。", "白话": "《备急千金要方》卷三：「茯神汤。治产后忽然心中怔忡悸动，或志意不定，恍恍惚惚，言语错谬，是心虚所致之方。（组成照录见原文。方义：茯神、人参、茯苓益气安神为君，芍药、当归、甘草养血和中，桂心、生姜、大枣温中和营，为产后心虚怔忡之专方。）上九味切碎，用水一斗，煮取三升，去滓，分三服，日三，效果良好。」"}, {"source": "条488｜《备急千金要方》卷三·淡竹茹汤", "原文": "《备急千金要方》卷三：“淡竹茹汤。治产后虚烦，头痛、短气欲绝，心中闷乱不解方。  \n生淡竹茹一升  麦门冬、小麦各五合  甘草一两  生姜三两，《产宝》用干葛  大枣十四枚，《产宝》用石膏三两  \n上六味，6，㕮咀，以水一斗煮竹茹、小麦，取八升，去滓，纳诸药，煮取一升，去滓，分二服，羸人分作三服，若有人参，入一两，若无人参，纳茯苓一两半亦佳。人参、茯苓皆治心烦闷及心虚惊悸，安定精神，有则为良，无自", "白话": "《备急千金要方》卷三：「淡竹茹汤。治产后虚烦，头痛、短气欲绝，心中闷乱不解之方。（组成照录见原文。方义：竹茹清热除烦，麦冬、小麦养心，甘草、生姜、大枣和中，为产后虚烦之清润剂。）上六味切碎，用水一斗煮竹茹、小麦取八升，去滓，放入诸药，煮取一升，去滓，分二服，瘦弱人分三服。若有人参加一两；若无人参，纳入茯苓一两半也好。人参、茯苓都治心烦闷及心虚惊悸、安定精神，有则为良，无则照方服一剂，不愈再作。」"}, {"source": "条489｜《备急千金要方》卷八·大续命汤", "原文": "《备急千金要方》卷八：“大续命汤。治大风经脏，奄忽不能言，四肢垂曳，皮肉痛痒不自知方。  \n独活、麻黄各三两  川芎、防风、当归、葛根、生姜、桂心、茯苓、附子、细辛、甘草各一两  \n上十二味㕮咀味，㕮咀。，以水一斗二升，煮取四升，分五服，老小半之。若初得病便自大汗者减麻黄，不汗者依方。上气者，加吴茱萸二两、厚朴一两。干呕者，倍加附子一两。啘哕者，加橘皮二两。若胸中吸吸少气者，加大枣十二枚。心下惊悸", "白话": "《备急千金要方》卷八：「大续命汤。治大风经脏，忽然不能言语，四肢垂曳，皮肉痛痒不自知之方。（组成照录见原文。方义：麻黄、葛根、生姜解表，独活、防风、细辛、川芎祛风，当归养血，桂心、附子温经，苓草健脾，为祛风通络、温经养血之剂。）上十二味切碎，用水一斗二升，煮取四升，分五服，老小减半。若初得病便自大汗的减麻黄，不出汗的依方。上气的加吴茱萸二两、厚朴一两；干呕的倍加附子一两；呃逆的加橘皮二两；胸中吸吸少气的加大枣十二枚；心下惊悸的加茯苓一两；若热的可去生姜加葛根。初得风不必加减，"}, {"source": "条490｜《备急千金要方》卷八·仲景三黄汤", "原文": "《备急千金要方》卷八：“仲景三黄汤。治中风手足拘挛，百节疼痛，烦热心乱，恶寒，经日不欲饮食方。  \n麻黄三十铢  黄芩十八铢  黄芪、细辛各十二铢  独活一两  \n上五味㕮咀味，㕮咀，以水五斗，煮取二升，分二服，一服小汗，两服大汗。心中热加大黄半两，胀满加枳实六铢，气逆加人参，心悸加牡蛎，渴加栝蒌各十八铢，先有寒加附子一枚。", "白话": "《备急千金要方》卷八：「仲景三黄汤。治中风手足拘挛，百节疼痛，烦热心乱，恶寒，整日不欲饮食之方。（组成照录见原文。方义：麻黄、独活、细辛祛风散寒，黄芪益气固表，黄芩清热。）上五味切碎，用水五斗，煮取二升，分二服，一服小汗，两服大汗。心中热加大黄半两，胀满加枳实六铢，气逆加人参，心悸加牡蛎，渴加栝蒌各十八铢，先有寒加附子一枚。」"}, {"source": "条491｜《备急千金要方》卷九·阳旦汤", "原文": "《备急千金要方》卷九：“阳旦汤。治伤寒中风脉浮，发热往来，汗出恶风，头项强，鼻鸣干呕，桂枝汤主之。随病加减如下方。  \n以泉水一斗煮取四升分服一升，日三。自汗者，去桂枝加附子一枚。渴者去桂加栝蒌根三两。利者去芍药、桂，加干姜三累、附子一枚炮。心下悸者，去芍药加茯苓四两。虚劳里急正阳旦主之。煎得二升，纳胶饴半斤，为再服。若脉浮紧发热者，不可与之。", "白话": "《备急千金要方》卷九：「阳旦汤。治伤寒中风脉浮，发热往来，汗出恶风，头项强痛，鼻鸣干呕，用桂枝汤主治。随病加减如下方。（组成照录见原文。方义：即桂枝汤加黄芩之阳旦汤，解肌和营。）用泉水一斗煮取四升，分服一升，日三服。自汗的去桂枝加附子一枚；渴的去桂加栝蒌根三两；下利的去芍药、桂，加干姜三累、附子一枚炮；心下悸的去芍药加茯苓四两；虚劳里急用正阳旦主治。煎得二升，加入胶饴半斤，分再服。若脉浮紧发热的，不可给服。」"}, {"source": "条492｜《备急千金要方》卷十三·大补心汤", "原文": "《备急千金要方》卷十三：“大补心汤。治虚损不足，心气弱悸或时妄语，四肢损变气力，颜色不荣方。  \n黄芩、附子各一两  甘草、茯苓、麦门冬、干地黄、桂心、阿胶各三两  半夏、 远志、石膏各四两  生姜六两  饴糖一斤  大枣二十枚  \n上十四味，取十三味㕮咀，以水一斗五升煮取五升，汤成下糖，分四服。", "白话": "《备急千金要方》卷十三：「大补心汤。治虚损不足，心气虚弱心悸，或时发妄语，四肢失养、气力减退，面色不荣之方。（组成照录见原文。方义：人参、甘草、麦冬、干地黄、阿胶、大枣益气养阴补血，桂心、附子、干姜、半夏、远志温阳化痰安神，黄芩、石膏清余热，饴糖建中，为大补心气、调和阴阳之剂。）上十四味，取十三味切碎，用水一斗五升煮取五升，汤成下饴糖，分四服。」"}, {"source": "条493｜《备急千金要方》卷十三·竹沥汤", "原文": "《备急千金要方》卷十三：“竹沥汤。治心实热，惊梦喜笑恐畏悸惧不安方。  \n淡竹沥一升  生地黄汁一升  石膏八两  芍药、白术、栀子仁、人参各三两  赤石脂、紫菀、知母、茯神各二两  \n上十一味㕮咀味，㕮咀，以水九升煮十味至二升七合，去滓，下竹沥更煎，取三升。  \n若须利入芒硝二两，去芍药，分三服。", "白话": "《备急千金要方》卷十三：「竹沥汤。治心实热，惊梦喜笑恐畏悸惧不安之方。（组成照录见原文。方义：竹沥、生地汁清热化痰养阴，石膏、知母、栀子清心泻火，人参、白术、茯神益气安神，赤石脂、紫菀收敛下气，为清心泻火、化痰安神之剂。）上十一味切碎，用水九升煮十味至二升七合，去滓，下竹沥再煎取三升。若须泻下加芒硝二两，去芍药，分三服。」"}, {"source": "条494｜《备急千金要方》卷十四·大定心汤", "原文": "《备急千金要方》卷十四：“大定心汤。治心气虚悸，恍惚多忘，或梦惊魇志少不足方。  \n人参、茯苓、茯神、远志、赤石脂、龙骨、干姜、当归、甘草、白术、芍药、 桂心、紫菀、防风各二两  大枣二十枚  \n上十五味㕮咀味，㕮咀，以水一斗二升煮取三升半，分五服，日三夜二。", "白话": "《备急千金要方》卷十四：「大定心汤。治心气虚悸，恍惚多忘，或梦中惊魇、志气不足之方。（组成照录见原文。方义：人参、茯苓、茯神、远志、龙齿益气安神定志，当归、芍药、紫菀养血，白术、甘草、干姜、桂心健脾温阳，防风散风，赤石脂收涩，为益气养心、镇惊定志之剂。）上十五味切碎，用水一斗二升煮取三升半，分五服，日三夜二服。」"}, {"source": "条495｜《备急千金要方》卷十四·大镇心散", "原文": "《备急千金要方》卷十四：“大镇心散。治心虚惊悸，梦寐恐畏方。  \n紫石英、茯苓、防风、人参、甘草、泽泻各八分  黄芪、白术、薯蓣、秦艽、白蔹各六分  麦门冬、当归各五分  桔梗、大豆黄卷、柏子仁、桂心、远志、大黄、石膏各四分  干姜、蜀椒、芍药、细辛各三分  \n上二十四味治，下筛，酒服三方寸匕，日三。（一方无紫石英、茯苓、泽泻、干姜，有大枣四分，蜜丸如梧子大，酒下十五丸。", "白话": "《备急千金要方》卷十四：「大镇心散。治心虚惊悸，梦寐恐畏之方。（组成照录见原文。方义：紫石英、柏子仁、桂心、远志镇心安神温阳，参苓术芪薯蓣甘草益气健脾，麦冬、当归、芍药养血，秦艽、防风、白蔹散风，大黄、石膏、泽泻、大豆黄卷清热利湿，桔梗载药上行，为镇心益气、养血安神之大方。）上二十四味治净，过筛，酒服三方寸匕，日三服。（一方无紫石英、茯苓、泽泻、干姜，有大枣四分，蜜丸如梧子大，酒下十五丸。」"}, {"source": "条496｜《备急千金要方》卷十四·小镇心散", "原文": "《备急千金要方》卷十四：“小镇心散。治心气不足，虚悸恐畏，悲思恍惚，心神不定惕惕然惊者方。  \n人参、白术、远志、附子、桂心、黄芪、细辛、干姜、干地黄、赤小豆、龙齿、防风、菖蒲各二两  茯苓四两  \n上十四味治，下筛，酒服二方寸匕，日三。", "白话": "《备急千金要方》卷十四：「小镇心散。治心气不足，虚悸恐畏，悲思恍惚，心神不定、惕惕然惊之方。（组成照录见原文。方义：人参、黄芪、白术、茯苓、甘草益气，龙齿、紫石英镇心，远志、菖蒲安神开窍，归地养血，桂心、干姜、细辛、附子温阳，防风散风，赤小豆利水，为益气镇惊、温阳安神之剂。）上十四味治净，过筛，酒服二方寸匕，日三服。」"}, {"source": "条497｜《备急千金要方》卷十四·小镇心丸", "原文": "《备急千金要方》卷十四：“小镇心丸。治心气少弱，惊虚振悸，胸中逆气，魇梦参错谬忘恍惚方。  \n紫石英、朱砂、茯神、银屑、雄黄、菖蒲、人参、桔梗、干姜、远志、甘草、 当归、桂心各二两  防风、防己、细辛、铁精各一两  \n上十七味为末，蜜丸，如大豆，饮服十丸，日三，加至二十丸。（一方有茯苓二分，为十八味。）", "白话": "《备急千金要方》卷十四：「小镇心丸。治心气少弱，惊虚振悸，胸中逆气，噩梦错杂、谬忘恍惚之方。（组成照录见原文。方义：紫石英、铁精、银屑、朱砂、雄黄、龙齿重镇安神，参苓菖蒲远志甘草益气开窍，当归养血，桂心干姜桔梗细辛防己防风温通散邪，为镇心定悸、益气安神之剂。）上十七味为末，蜜丸如大豆，饮服十丸，日三服，加至二十丸。（一方有茯苓二分，为十八味。）」"}, {"source": "条498｜《备急千金要方》卷十四·远志汤", "原文": "《备急千金要方》卷十四：“远志汤。治心气虚惊悸善忘不进食补心方。  \n远志、干姜、白术、桂心、黄芪、紫石英各三两  人参、茯苓、甘草、芎、茯神、当归、羌活、防风各二两  麦门冬、半夏各四两  五味子二合  大枣十二枚  \n上十八味，㕮咀，以水一斗三升煮取三升半，分五服，日三夜二。", "白话": "《备急千金要方》卷十四：「远志汤。治心气虚、惊悸善忘、不能进食，补心之方。（组成照录见原文。方义：远志、茯神、菖蒲安神开窍，参苓术芪草益气健脾，归芎养血，麦冬半夏五味子滋阴化痰敛气，桂心干姜紫石英温阳镇心，羌活防风散风，为益气养血、镇心安神之补心方。）上十八味切碎，用水一斗三升煮取三升半，分五服，日三夜二服。」"}, {"source": "条499｜《备急千金要方》卷十四·茯神汤", "原文": "《备急千金要方》卷十四：“茯神汤。治风经五脏大虚，惊悸，安神定志方。  \n茯神、防风各三两  人参、远志、甘草、龙骨、桂心、独活各二两  白术一两酸枣一升  细辛、干姜各六两  \n上十二味㕮咀味，㕮咀，以水九升煮取三升，分三服。", "白话": "《备急千金要方》卷十四：「茯神汤。治风邪经过五脏、大虚，惊悸，安神定志之方。（组成照录见原文。方义：茯神、远志、龙骨、酸枣安神定志，参术草益气，防风、独活、细辛祛风，桂心、干姜温阳，为益气祛风、安神定志之剂。）上十二味切碎，用水九升煮取三升，分三服。」"}, {"source": "条500｜《备急千金要方》卷十四·镇心丸", "原文": "《备急千金要方》卷十四：“镇心丸。治男子妇人虚损，梦寤惊悸或失精神，妇人赤白注漏或月水不利，风邪鬼疰，寒热往来，腹中积聚，忧恚结气诸病方。  \n紫石英、茯苓、菖蒲、肉苁蓉、麦门冬、远志、大黄、当归、细辛、大豆黄卷、卷柏、干姜各五分  人参、丹参、防风、秦艽、泽泻各六分  柏子仁、芍药、石膏各三分  乌头、桂心、桔梗、甘草、薯蓣、前胡、白蔹、铁精、银屑、牛黄各二分  白术、半夏各三分  䗪虫十二枚 ", "白话": "《备急千金要方》卷十四：「镇心丸。治男子妇人虚损，梦中惊悸或失精神；妇人赤白注漏或月经不利；风邪鬼疰，寒热往来，腹中积聚，忧恚结气诸病之方。（组成照录见原文。方义：紫石英、铁精、银屑、牛黄、龙齿重镇安神，参苓术草薯蓣益气健脾，归地芍药麦冬远志菖蒲肉苁蓉养血滋阴开窍，桂心干姜细辛乌头温阳，大黄、石膏、前胡、白蔹、丹参、秦艽、泽泻、大豆黄卷、卷柏清热活血利湿，䗪虫破积，为虚损惊悸、积聚结气之大方。）上三十五味为末，蜜枣和捣五千杵，丸如梧子大，酒服五丸，日三服，加至二十丸。（一本无"}, {"source": "条501｜《备急千金要方》卷十八·海藻汤", "原文": "《备急千金要方》卷十八：“海藻汤。治咳而下利，胸中痞而短气，心中时悸，四肢不欲动，手足烦不欲食，肩背痛，时恶寒方。  \n海藻四两  半夏、五味子各半升  生姜一两  细辛二两  茯苓六两  杏仁五十枚  \n上七味㕮咀味，㕮咀，以水一斗，煮取三升，去滓，分三服，日三。（一方无五味子、生姜）", "白话": "《备急千金要方》卷十八：「海藻汤。治咳嗽而下利，胸中痞闷而短气，心中时时悸动，四肢不欲动，手足烦热不欲食，肩背疼痛，时时恶寒之方。（组成照录见原文。方义：海藻、茯苓、半夏化痰散结利水，细辛、生姜、杏仁温肺降气，五味子敛肺，为化痰散结、温肺定悸之剂。）上七味切碎，用水一斗，煮取三升，去滓，分三服，日三。（一方无五味子、生姜。）」"}, {"source": "条502｜《幼幼新书》卷十五·仲景四逆散", "原文": "仲景四逆散  \n《幼幼新书》卷十五：《活人书》仲景四逆散  \n甘草炙、枳实去白瓤，炒黄、柴胡、芍药以上各一两  \n咳者加五味子、干姜各半两。下利悸者，加桂半两。小便不利者，加茯苓半两。腹中痛者，加附子半枚，炮裂。泄利下重，先浓煎薤白汤，内药末三钱匕，再煮一二沸，温服。上捣筛为细散。米饮下二钱，日三服。", "白话": "《幼幼新书》卷十五引《活人书》仲景四逆散：（组成照录见原文。方义：柴胡疏肝，枳实行气，芍药和血，甘草和中，为疏肝理脾之基础方；下利悸者加桂枝温阳。）咳嗽加五味子、干姜各半两；下利而悸的加桂半两；小便不利的加茯苓半两；腹中痛的加附子半枚炮裂；泄利下重的，先浓煎薤白汤，放入药末三钱匕，再煮一二沸温服。上药捣筛为细散，米饮送下二钱，日三服。"}, {"source": "条503｜《太平惠民和剂局方》卷九·术香散", "原文": "术香散  \n《太平惠民和剂局方》卷九：术香散。治妇人血风脏气，头目昏晕，心烦怔忪，手足热疼，经候不调，脐腹时痛，或多便利，饮食减少，并宜服之。  \n天台乌药、三棱煨、蓬莪术煨、川当归去芦、荆芥穗、天麻、桂心不见火、延胡索、厚朴姜汁制，炒、附子炮，去皮、脐，各一两  \n上为细末。每服一钱，生姜汁少许，和温酒调下。", "白话": "《太平惠民和剂局方》卷九载：术香散。治妇人血风脏气，头目昏晕，心烦怔忪，手足热疼，月经不调，脐腹时时疼痛，或多泄利，饮食减少，都宜服。（组成照录见原文。方义：乌药、木香类行气（此用三棱、莪术、厚朴、延胡索行气活血），当归、荆芥、天麻、桂心养血祛风，附子温经，为行气活血、祛风温经之剂。）上药为细末。每服一钱，用生姜汁少许和温酒调下。"}, {"source": "条504｜《太平惠民和剂局方》卷十·檀香汤", "原文": "檀香汤  \n《太平惠民和剂局方》卷十：檀香汤。治精神不爽，头目昏眩，心忪烦躁，志意不定。  \n川芎不见火、白芷不见火，各二两  桔梗焙，三十两  檀香不见火，三两  甘草炒，六两  \n上为细末。每服一钱，入盐少许，沸汤点服。调中顺气，安神定志，清爽头目。", "白话": "《太平惠民和剂局方》卷十载：檀香汤。治精神不爽，头目昏眩，心忪烦躁，志意不定。（组成照录见原文。方义：檀香、川芎、白芷理气止痛、清利头目，桔梗载药上行，甘草和中，为理气安神、清爽头目之剂。）上药为细末。每服一钱，加入盐少许，沸汤点服。能调中顺气，安神定志，清爽头目。"}, {"source": "条505｜《校注妇人良方》卷十二·大圣散", "原文": "大圣散  \n《校注妇人良方》卷十二：大圣散。治妊娠忪悸梦惊，心腹胀满，连脐急痛。  \n白茯苓、川芎、麦门冬去心、黄芪炒、当归各一钱  人参、甘草炙、木香各五分  \n上姜水煎服。", "白话": "《校注妇人良方》卷十二载：大圣散。治妊娠心忪惊悸、梦中惊吓，心腹胀满，连脐部拘急疼痛。（组成照录见原文。方义：茯苓、川芎、麦冬、黄芪、当归、人参、甘草益气养血安神，木香理气止痛，为妊娠心悸之补益安神剂。）上药用姜水煎服。"}, {"source": "条506｜《奇效良方》卷二十六·调中汤", "原文": "调中汤  \n《奇效良方》卷二十六：调中汤。治心掣，胸中忿气，不欲饮食。  \n赤茯苓去黑皮、当归切碎、干姜炮、参、术以上各二两 官桂去粗皮，一两半 五味子、甘草炙，各一两  \n上锉如麻豆大，每服五钱，水一盏半，煎至八分，去滓稍热服，日二夜二。", "白话": "《奇效良方》卷二十六载：调中汤。主治心掣，胸中忿气，不欲饮食。（组成照录见原文。方义：赤茯苓、当归、干姜、人参、白术、官桂、五味子、甘草温中益气、养血敛心，为温中散寒、调中定掣之剂。）上药锉如麻豆大，每服五钱，用水一盏半，煎至八分，去滓稍热服，日二夜二服。"}, {"source": "条507｜《本草单方》卷十三·醋附丸", "原文": "醋附丸  \n《本草单方》卷十三：醋附丸。治妇人、室女一切经候不调，血气刺痛，腹胁膨胀，心怔乏力，面色萎黄，头晕恶心，崩漏带下，便血，癥瘕积聚，及妇人数堕胎，由气不升降，服此尤妙。  \n香附子米醋浸半日，沙锅煮干，捣，焙，石臼为末，醋糊为丸，醋汤下。", "白话": "《本草单方》卷十三载：醋附丸。治妇人、室女一切月经不调，血气刺痛，腹胁膨胀，心怔乏力，面色萎黄，头晕恶心，崩漏带下，便血，癥瘕积聚，以及妇人屡屡堕胎由气机升降失常者，服此尤妙。（组成照录见原文。方义：香附子疏肝理气调经，米醋制后入肝经，醋糊为丸、醋汤送下，为理气调经、和血定怔之单方。）香附子用米醋浸半日，沙锅煮干，捣碎焙干，石臼研为末，醋糊为丸，醋汤送下。"}, {"source": "条508｜《医学正传》卷四·玉液汤", "原文": "玉液汤  \n《医学正传》卷四：玉液汤严氏方。治七情感动，气郁生涎，随气上冲，头目眩运，心嘈忪悸，眉梭骨痛。  \n大半夏汤泡七次，去皮脐  \n 上以一味薄切成片，每服四钱，加生姜十片煎，入沉香磨水一呷服，大效。", "白话": "《医学正传》卷四载：玉液汤（严氏方）。治七情所感，气郁生涎，随气上冲，头目眩晕，心嘈忪悸，眉棱骨痛。（组成照录见原文。方义：半夏为主，化痰降逆，生姜和胃，沉香磨水降气，为理气化痰、降逆定悸之剂。）用一味半夏薄切成片，每服四钱，加生姜十片煎，加入沉香磨水一匙服，效果很大。"}, {"source": "条509｜《医方考》卷六·十一味木香散", "原文": "十一味木香散  \n《医方考》卷六：十一味木香散。  \n木香 丁香 肉桂 人参 青皮 大腹皮 半夏 甘草 前胡 诃子 赤茯苓  \n里虚泄泻而渴者，此方主之……陈文仲云：腹胀渴者，泻渴者，足指冷渴者，惊悸渴者，身温渴者，身热面㿠白色渴者，寒战渴不止者，气急咬牙渴者，饮水转水泻不已者，以上九证，即非热也，乃津液少，脾胃肌肉虚故耳。宜木香散治之。如不愈，更加丁香、肉桂。昆谓痘色㿠白，手足寒，小便利，如是渴", "白话": "《医方考》卷六载：十一味木香散。（组成照录见原文。方义：木香、丁香、肉桂、青皮、大腹皮、前胡理气温中，人参、甘草、赤茯苓益气健脾，半夏化痰，诃子涩肠，为温中理气、健脾止泻之剂。）里虚泄泻而口渴的，用此方主治。陈文仲说：腹胀而渴、泄泻而渴、足趾冷而渴、惊悸而渴、身温而渴、身热面白而渴、寒战渴不止、气急咬牙而渴、饮水反而水泻不止——以上九证都不是热证，而是津液少、脾胃肌肉虚的缘故，宜用木香散治之。如不愈，再加丁香、肉桂。吴昆谓：痘色㿠白、手足寒、小便利，这样的口渴是虚证，本方主治"}, {"source": "条510｜《幼科证治准绳》集二·前朴散", "原文": "前朴散  \n《幼科证治准绳》集二：前朴散。治心腹结气，或呕哕吐泻，腹胀痛，惊悸。  \n前胡、白术、人参、陈皮、良姜、藿香、甘草、厚朴各等分  \n上锉。每服三钱，水一盏，煎七分，稍热，空心服。", "白话": "《幼科证治准绳》集二载：前朴散。治心腹结气，或呕哕吐泻，腹胀痛，惊悸。（组成照录见原文。方义：前胡、厚朴、陈皮、藿香理气化湿，人参、白术、甘草、良姜温中健脾，为理气温中、化湿定悸之剂。）上药锉碎。每服三钱，用水一盏，煎七分，稍热空心服。"}, {"source": "条511｜《产鉴》下卷·无名方", "原文": "无名方  \n《产鉴》下卷：治产后恶露冲心，语言乱通，如见鬼神，惊悸不定，小便不利者。  \n琥珀、辰砂、没药各研细 当归各一两  \n上为细末，每服二钱，空心白汤调下，日三服，心腹痛者加延胡索，兼晕者加蒲黄。", "白话": "《产鉴》下卷载：治产后恶露上冲于心，言语错乱，如见鬼神，惊悸不定，小便不利者。（组成照录见原文。方义：琥珀、辰砂镇心安神，没药、当归活血化瘀，为产后瘀血冲心、惊悸不安之逐瘀镇心方。）上药为细末，每服二钱，空心白汤调下，日三服。心腹痛的加延胡索；兼眩晕的加蒲黄。"}, {"source": "条512｜《良朋汇集经验神方》卷六·紫苏饮", "原文": "紫苏饮  \n《良朋汇集经验神方》卷六：紫苏饮。治妊娠胎上逼、胀满疼痛，谓之子悬。兼治临产惊悸，气结连日不下。  \n紫苏一两 当归、甘草各二钱半 人参、川芎、大腹皮、陈皮、白芍药各半两  \n上㕮咀，每服半两，水一盏半、姜四片、葱白七寸，去渣空心温服。", "白话": "《良朋汇集经验神方》卷六载：紫苏饮。治妊娠胎气上逼、胀满疼痛，叫做子悬；兼治临产惊悸、气结连日不下。（组成照录见原文。方义：紫苏、大腹皮、陈皮理气宽中，当归、白芍、川芎养血和血，人参、甘草益气，为理气安胎、养血定悸之剂。）上药切碎，每服半两，用水一盏半、姜四片、葱白七寸，去渣空心温服。"}, {"source": "条513｜《增订通俗伤寒论·第一编》·四逆散", "原文": "四逆散  \n《增订通俗伤寒论·第一编》：太阴兼证：兼心经证，神烦而悸，汗出津津，似寐非寐，或不得卧；兼肝经证，心中痛热，饥不欲食，食即呕酸吐苦，胸胁满疼，甚则霍乱吐泻。故唯厥冷而或咳或悸，腹痛下重，是阳为阴遏之利，用四逆散。", "白话": "《增订通俗伤寒论·第一编》载：太阴兼证：兼心经证，神烦而心悸，汗出津津，似睡非睡，或不得卧；兼肝经证，心中痛热，饥不欲食，食即呕酸吐苦，胸胁满疼，甚至霍乱吐泻。所以四肢厥冷而或咳或悸、腹痛下重的，是阳气被阴邪郁遏之证，用四逆散。"}, {"source": "条514｜《备急千金要方》卷十九·乐令建中汤", "原文": "祛痰剂《备急千金要方》卷十九：“乐令建中汤。治虚劳少气，心胸淡冷，时惊惕，心中悸动，手足逆冷，体常自汗，五脏六腑虚损，肠鸣风湿，营卫不调百病，补诸不足，又治风里急方。  \n黄芪、人参、橘皮、当归、桂心、细辛、前胡、芍药、甘草、茯苓、麦冬各一两  半夏二两半  生姜五两  大枣二十枚  \n上十四味㕮咀味，㕮咀，以水二斗，煮取四升，每服五合，日三夜一。", "白话": "《备急千金要方》卷十九：「乐令建中汤。治虚劳少气，心胸淡冷，时时惊惕，心中悸动，手足逆冷，身体常自汗，五脏六腑虚损，肠鸣，风湿，营卫不调百病，补诸不足，又治风里急之方。（组成照录见原文。方义：黄芪、人参、茯苓、甘草益气，当归、芍药养血，桂心、细辛温阳，麦冬滋阴，橘皮、前胡、半夏理气化痰，生姜、大枣和中，即黄芪建中汤合养血化痰法。）上十四味切碎，用水二斗，煮取四升，每服五合，日三夜一服。」"}, {"source": "条515｜《备急千金要方》卷十九·肾沥汤", "原文": "《备急千金要方》卷十九：“肾沥汤。治虚劳损羸乏，咳逆短气，四肢烦疼，腰背相引痛，耳鸣面黧黯，骨间热，小便赤黄，心悸目眩，诸虚乏方。  \n羊肾一具  桂心一两  人参、泽泻、五味子、甘草、防风、川芎、地骨皮、黄芪、当归各二两  茯苓、元参、芍药、生姜各四两  磁石五两  \n上十六味㕮咀味，㕮咀，以水一斗五升，先煮肾，取一斗，去肾入药，煎取三升，分三服。可常服之。", "白话": "《备急千金要方》卷十九：「肾沥汤。治虚劳羸瘦乏力，咳逆短气，四肢烦疼，腰背相引而痛，耳鸣面色黧黑，骨间发热，小便赤黄，心悸目眩，诸虚不足之方。（组成照录见原文。方义：羊肾以脏补脏，配磁石补肾镇纳，参芪归芎地芍苓草泽泻五味子益气养血利湿，桂心、防风、地骨皮、生姜温通清热，为补肾益精、定悸明目之剂。）上十六味切碎，用水一斗五升，先煮羊肾取一斗，去肾放入药，煎取三升，分三服。可以常服。」"}, {"source": "条516｜《千金翼方》卷五·大补内黄芪汤", "原文": "《千金翼方》卷五：“大补内黄芪汤。主妇人七伤，骨髓疼，小腹急满，面目黄黑，不能食饮，并诸虚不足，少气心悸不安方。  \n黄芪、半夏各三两，洗  大枣三十枚  干地黄、桂心、人参、茯苓、远志去心、芍药、泽泻、五味子、麦门冬去心、白术、甘草炙，各二两  干姜四两  \n上一十六味，㕮咀，以水一斗半，煮取二升，一服五合，日三夜一。", "白话": "《千金翼方》卷五：「大补内黄芪汤。主治妇人七伤，骨髓疼痛，小腹急满，面目黄黑，不能饮食，以及诸虚不足，少气心悸不安之方。（组成照录见原文。方义：黄芪、人参、白术、甘草、大枣益气，归地芍药养血，半夏、茯苓、泽泻化痰利湿，麦冬、五味子滋阴敛气，桂心、干姜温阳，为大补气血、安神定悸之剂。）上十六味切碎，用水一斗半，煮取二升，一次服五合，日三夜一服。」"}, {"source": "条517｜《千金翼方》卷六·竹叶汤", "原文": "《千金翼方》卷六：“竹叶汤。主产后心烦闷不解方。  \n生淡竹叶切、麦门冬去心、小麦各一升  大枣十四枚，擘、 茯苓、生姜切，各三两  甘草炙，二两  \n上七味，㕮咀，以水一斗，先煮竹叶小麦取八升，纳诸药，煮取三升，分为三服。若心中虚悸者，加人参二两；若其人食少无气力者，可更加白粳米五合；气逆者加半夏二两。", "白话": "《千金翼方》卷六：「竹叶汤。主治产后心烦闷不解之方。（组成照录见原文。方义：竹叶、小麦清心除烦，麦冬养阴，茯苓、生姜、甘草、大枣和中。）上七味切碎，用水一斗，先煮竹叶、小麦取八升，放入诸药，煮取三升，分三服。若心中虚悸的加人参二两；若其人食少无气力的，可再加白粳米五合；气逆的加半夏二两。」"}, {"source": "条518｜《千金翼方》卷六·淡竹茹汤", "原文": "《千金翼方》卷六：“淡竹茹汤。主产后虚烦，头痛短气欲死，心中闷乱不起方。  \n生淡竹茹一升  麦门冬五合，去心  小麦五合  大枣十四枚，一方用石膏  生姜三两，切，一方用干姜  甘草炙，一两  \n上六味，㕮咀，以水八升煮竹茹、小麦，减一升，仍纳诸药，更煮二升，分为二服，羸人分为三服，若有人参，纳一两，若无人参，纳茯苓一两半亦佳。人参、茯苓皆治心烦闷及心惊悸，安定精神，有即为良，无自依本方服一剂，", "白话": "《千金翼方》卷六：「淡竹茹汤。主治产后虚烦，头痛短气欲死，心中闷乱不起之方。（组成照录见原文。方义：竹茹清热除烦，麦冬、小麦养心，姜枣草和中。）上六味切碎，用水八升煮竹茹、小麦减去一升，仍放诸药，再煮取二升，分二服，瘦弱人分三服。若有人参纳入一两；若无人参纳入茯苓一两半也好。人参、茯苓都治心烦闷及心惊悸、安定精神，有则为良，无则照本方服一剂，不愈再服。若气逆的加半夏二两，洗去滑。」"}, {"source": "条519｜《千金翼方》卷七·人参丸", "原文": "《千金翼方》卷七：“人参丸。主产后大虚，心悸，志意不安，恍惚不自觉，心中畏恐，夜不得眠，虚烦少气方。  \n人参、茯苓、麦门冬去心、甘草炙，各三两  桂心一两  大枣五十枚，作膏  菖蒲、泽泻、薯蓣、干姜各二两  \n上一十味，捣筛为末，炼蜜枣膏和丸如梧子大。空腹酒下二十丸，日三夜一服，不知稍增至三十丸。若有远志得二两纳之为善。气绝纳当归、独活各三两更善。此方亦治男子虚心悸不定，至良。", "白话": "《千金翼方》卷七：「人参丸。主治产后大虚，心悸，志意不安，恍惚不自觉，心中畏恐，夜不得眠，虚烦少气之方。（组成照录见原文。方义：人参、茯苓、甘草、薯蓣、大枣膏益气健脾，麦冬、菖蒲、泽泻养心开窍利湿，桂心、干姜温中，为产后心虚心悸之补益剂。）上十味，捣筛为末，炼蜜枣膏和丸如梧子大。空腹酒送下二十丸，日三夜一服，不效渐增至三十丸。若有远志二两加入为好。气绝的加入当归、独活各三两更好。此方也治男子虚心悸不定，效果极好。」"}, {"source": "条520｜《千金翼方》卷七·大远志丸", "原文": "《千金翼方》卷七：“大远志丸。主妇人产后心虚不足，心下虚悸，志意不安，时复愦愦，腹中拘急痛，夜卧不安，胸中吸吸少气。药内补伤损，益气，安志定心，主诸虚损方。  \n远志去心、茯苓、桂心、麦门冬去心、泽泻、干姜、人参、当归、独活、阿胶炙、菖蒲、甘草炙、白术各三两  干地黄五两  薯蓣二两  \n上一十五味，捣筛为末，炼蜜和丸如梧子。空腹温酒服二十丸，日三服，不知稍加至三十丸。大虚身体冷少津液，加钟乳三两", "白话": "《千金翼方》卷七：「大远志丸。主治妇人产后心虚不足，心下虚悸，志意不安，时时昏乱，腹中拘急疼痛，夜卧不安，胸中短气不续。能内补伤损，益气，安志定心，主治诸虚损之方。（组成照录见原文。方义：远志、菖蒲、茯苓安神定志，参苓术草益气，归地麦冬阿胶养血滋阴，桂心干姜温阳，独活泽泻祛风利湿，薯蓣补脾肾，为气血阴阳兼补之剂。）上十五味，捣筛为末，炼蜜和丸如梧子大。空腹温酒服二十丸，日三服，不效渐加至三十丸。大虚身体冷、津液少的加钟乳石三两为好。钟乳益精气，安心镇志，令人颜色美，效果极好。"}, {"source": "条521｜《千金翼方》卷七·甘草丸", "原文": "《千金翼方》卷七：“甘草丸。主妇人产后心虚不足，虚悸少气，心神不安，或若恍恍惚惚不自觉方。  \n甘草三两，炙  人参、泽泻、桂心各一两  大枣五枚、远志去心、茯苓、麦门冬去心、菖蒲、干姜各二两  \n上一十味，捣筛为末，炼蜜和丸如大豆许，酒服二十丸，日四五服，夜二服，不知稍增，若无泽泻，用术代之，若胸中冷增干姜。", "白话": "《千金翼方》卷七：「甘草丸。主治妇人产后心虚不足，虚悸少气，心神不安，或恍恍惚惚不自知之方。（组成照录见原文。方义：甘草、人参、茯苓、大枣益气健脾，远志、菖蒲、麦冬养心安神，干姜、桂心、泽泻温阳利湿，为益气安神之小补剂。）上十味，捣筛为末，炼蜜和丸如大豆许，酒服二十丸，日四五服，夜二服，不效渐增。若无泽泻，用白术代替；若胸中冷，增加干姜。」"}, {"source": "条522｜《千金翼方》卷十二·紫石英汤", "原文": "《千金翼方》卷十二：“紫石英汤。主心虚惊悸、寒热、百病，令人肥健方。  \n紫石英十两  白石英十两  白石脂三十两  赤石脂三十两  干姜三十两  \n上五味，㕮咀皆完，用二石英各取一两，石脂等三味各取三两，以水三升合以微火煎，宿勿食，分为四服，日三夜一服。后午时乃食。日日依前秤取昨日药，乃置新药中共煮，乃至药尽常然，水数一准十，新药尽讫常添水，去滓，服之满四十日止，忌酒肉。药水皆用大升秤，取汁亦用", "白话": "《千金翼方》卷十二：「紫石英汤。主治心虚惊悸、寒热、百病，令人肥健之方。（组成照录见原文。方义：紫石英、白石英、白石脂、赤石脂重镇安神、收涩固脱，干姜温中，为金石重镇之补虚剂。）上五味，都整个切碎，用二种石英各取一两，石脂等三味各取三两，用水三升以微火合煎。隔夜勿食，分四服，日三夜一服，到午时才进食。每天照前法秤取昨日之药，放入新药中共煮，直至药尽常如此，水数一律以十为准，新药尽时常添水，去滓服之，满四十日止。忌酒肉。药与水都用大升秤量，取汁也用大升。服汤后即行走，勿停坐卧，"}, {"source": "条523｜《千金翼方》卷十六·补心汤", "原文": "《千金翼方》卷十六：“补心汤。主奄奄忽忽，朝瘥暮剧，惊悸，心中憧憧，胸满不下食饮，阴阳气衰，脾胃不磨，不欲闻人声，定志下气方。  \n人参、茯苓、龙齿炙、当归、远志去心、甘草炙，各三两  桂心、半夏洗，各五两  生姜六两，切  大枣二十枚，擘  黄芪四两  枳实炙、枳梗、茯神各二两半  \n上一十四味，㕮咀，以水一斗二升，先煮粳米五合。令熟，去滓纳药，煮取四升，每服八合，日三，夜二服。", "白话": "《千金翼方》卷十六：「补心汤。主治精神萎靡、忽忽不乐，朝愈暮剧，惊悸，心中动摇不宁，胸满不能饮食，阴阳气衰，脾胃不能消化，不欲闻人声，能定志下气之方。（组成照录见原文。方义：人参、黄芪、茯苓、茯神、远志、龙齿益气镇心安神，归头养血，半夏、枳实、桔梗化痰下气，桂心、生姜、大枣、粳米温中和营，为益气定志、下气安神之剂。）上十四味切碎，用水一斗二升，先煮粳米五合令熟，去滓放入药，煮取四升，每服八合，日三夜二服。」"}, {"source": "条524｜《千金翼方》卷十七·三黄汤", "原文": "《千金翼方》卷十七：“三黄汤。主中风，手足拘挛，百节疼痛，烦热心乱，恶寒，经日不欲饮食方。  \n麻黄五分，去节  独活一两  黄芩三分  黄芪半两  细辛半两  \n上五味，㕮咀，以水五升，煮取二升，去滓，分二服，一服小汗，两服大汗。心中热，加大黄半两；腹满加枳实一枚；气逆加人参三分；心悸加牡蛎三分；渴加栝蒌三分；先有寒加八角附子一枚。此仲景方，神秘，不传。", "白话": "《千金翼方》卷十七：「三黄汤。主治中风，手足拘挛，百节疼痛，烦热心乱，恶寒，整日不欲饮食之方。（组成照录见原文。方义：麻黄、独活、细辛祛风散寒，黄芪益气固表，黄芩清热，即仲景三黄汤。）上五味切碎，用水五升，煮取二升，去滓，分二服，一服小汗，两服大汗。心中热加大黄半两；腹满加枳实一枚；气逆加人参三分；心悸加牡蛎三分；渴加栝蒌三分；先有寒加八角附子一枚。这是仲景方，神秘不传。」"}, {"source": "条525｜《千金翼方》卷十八·大酸枣汤", "原文": "《千金翼方》卷十八：“大酸枣汤。主虚劳烦悸，奔气在胸中，不得眠方。  \n酸枣仁五升、人参、茯苓、生姜切、芎、桂心各二两  甘草炙，一两半  \n上七味，㕮咀。以水一斗二升，煮枣仁取七升，去滓，纳诸药，煮取三升，分三服。", "白话": "《千金翼方》卷十八：「大酸枣汤。主治虚劳烦悸，奔豚之气在胸中，不得眠之方。（组成照录见原文。方义：酸枣仁重用为君，养心安神敛汗，配川芎、人参、茯苓、桂心、生姜、甘草益气通阳和中，为养心安神、平冲定悸之剂。）上七味切碎。用水一斗二升，先煮酸枣仁取七升，去滓，放入诸药，煮取三升，分三服。」"}, {"source": "条523｜《外台秘要》卷四·茵陈汤", "原文": "《外台秘要》卷四：“疗与黑疸同，谷疸食则眩，心忪怫郁不安，久久发黄为谷疸，并以前茵陈汤主之。方在遍身黄部中。", "白话": "〔主治〕所疗之证与黑疸相同：谷疸进食即眩晕，心忪（心悸）怫郁不安，日久身体发黄成为谷疸，一并用前述茵陈汤主治，方在原书「遍身黄」部中。〔组成·服法〕原稿未录，仅存主治。"}, {"source": "条524｜《外台秘要》卷七·范汪大茱萸丸", "原文": "《外台秘要》卷七：“范汪大茱萸丸。疗心腹寒疝，胸中有逆气，时上抢心痛，烦满不得卧，面目恶风，悸掉，惕惕时惊，不欲饮食而呕，变发寒热方。 　 \n吴茱萸半升  细辛、芍药、柴胡一方用前胡、旋复花旋覆花、黄芩、紫菀、人参、白术、茯苓、干姜、桂心、附子炮、甘草炙、半夏洗、当归各半两　 \n上十六味，捣筛，以蜜和为丸，如梧子。先食服三丸，日三，不知稍加。忌生葱、羊肉、饧、酢物、桃、李、雀肉、猪肉、生菜、海藻、", "白话": "〔方名〕范汪大茱萸丸。〔主治〕疗心腹寒疝，胸中有逆气时时上冲抢心而痛，烦满不得卧，面目恶风，心悸身掉（震颤），时时惊惕，不欲饮食而呕吐，或变生寒热。〔组成·照录〕吴茱萸半升；细辛、芍药、柴胡（一方用前胡）、旋复花（旋覆花）、黄芩、紫菀、人参、白术、茯苓、干姜、桂心、附子（炮）、甘草（炙）、半夏（洗）、当归各半两。〔方义〕吴茱萸、干姜、桂心、附子温里散寒，半夏、旋覆花降逆化痰，参、术、苓、草健脾益气，归、芍养血，细辛、柴胡、紫菀、黄芩寒热并投，为温中降逆、止悸定惊之丸。〔服法〕"}, {"source": "条525｜《外台秘要》卷十九·竹叶汤", "原文": "《外台秘要》卷十九：“又凡人入八月，气自渐定，非意气大发者，作半夏独活汤，多唾或睡觉心忪心闷，风热故也。竹叶汤食后服之为佳，如不已，作后汤服。 　 \n麦门冬三两，去心  茯苓二两  石膏四两，碎  小麦五合  竹叶切，一升  生姜二两　 \n上六味切，以水五升，煮取一升二合，食后分再服，相去七八里久。忌酢物。", "白话": "〔主治〕凡人入八月，其气自然渐定，若非意气大发者，见多唾，或睡醒后心忪心闷，是风热之故，作半夏独活汤；先以竹叶汤食后服之为佳，如不愈，再作后汤服。〔组成·照录〕麦门冬三两（去心）、茯苓二两、石膏四两（碎）、小麦五合、竹叶（切）一升、生姜二两。〔方义〕竹叶、石膏清热除烦，麦冬、小麦养心安神，茯苓宁心，生姜和胃，为清热养心、除烦定悸之方。〔服法〕上六味切碎，以水五升煮取一升二合，食后分两次服，两服相隔七八里（约行七八里路）时间。〔禁忌〕忌酢物。"}, {"source": "条526｜《外台秘要》卷三十四·必效方（产后气欲绝）", "原文": "《外台秘要》卷三十四：“千金疗妇人产后气欲绝，心中烦闷不解，必效方。 　 \n竹叶切、麦门冬去心、小麦各一升  甘草一两，炙  生姜二两  大枣十四枚　 \n上六味切，以水一斗煮竹叶小麦，取八升去滓，纳余药煮，取三升去滓，分服，心虚悸，加人参二两，少气力，加粳米五合，一方用竹皮，若胸中气逆，加半夏二两，忌如常法。", "白话": "〔主治〕《千金》疗妇人产后气欲绝，心中烦闷不解（必效方）。〔组成·照录〕竹叶（切）、麦门冬（去心）、小麦各一升，甘草一两（炙），生姜二两，大枣十四枚。〔方义〕竹叶、小麦清心除烦，麦冬养阴，甘草、生姜、大枣和中益气，治产后阴血耗伤、心烦心悸。〔服法〕上六味切，以水一斗先煮竹叶、小麦取八升去渣，再入余药煮取三升去渣，分次服。〔加减〕心虚悸加人参二两；少气无力加粳米五合；一方用竹皮；若胸中气逆加半夏二两。〔禁忌〕忌如常法。"}, {"source": "条527｜《外台秘要》卷三十七·麻黄汤（石药发动解）", "原文": "《外台秘要》卷三十七：“人参动紫石英，令人心急而痛，或惊悸不得卧，或恍惚忘误，失性发狂，或昏昏欲眠，或愦愦喜嗔，或瘥或剧，乍寒乍热，或耳聋目暗，又防风虽不动紫石，而紫石犹动防风，为药中亦有人参，缘防风动人参，转相发动，令人心痛烦热，头项强，才觉发，宜服麻黄汤方。（千金服后人参汤） 　 \n麻黄二两，去节  人参一两  甘草二两，炙  葱白切，一升  豉一升  大麦奴一把　 \n上六味切，以酒五升汤三升", "白话": "〔主治〕人参触动紫石英，令人心急而痛，或惊悸不得卧，或恍惚遗忘错乱、失性发狂，或昏昏欲眠，或昏乱易怒，或时轻时重，乍寒乍热，或耳聋目暗；又防风虽不动紫石英，而紫石英犹能动防风，药中又有人参，因防风动人参，转相发动，令人心痛烦热、头项强——才觉发作，宜服麻黄汤（《千金》服后人参汤）。〔组成·照录〕麻黄二两（去节）、人参一两、甘草二两（炙）、葱白（切）一升、豉一升、大麦奴一把。〔方义〕麻黄、葱白、豆豉发散透邪，人参、甘草扶正，大麦奴解毒除烦，为解救服石发动之方。〔服法〕上六味切，"}, {"source": "条528｜《太平圣惠方》卷四·小草散", "原文": "《太平圣惠方》卷四：“治心风烦热，恍惚，狂言妄语，时复惊恐，不自觉知，发作有时，宜服小草散方。 　 \n小草一两  柏子仁一两  犀角屑半两  赤茯苓一两  铁精一两，细研  龙齿三分，细研  天竺黄一两，细研  生干地黄一两  琥珀末一两，细研　 \n上件药，捣细罗为散，入研了药，令匀。每服不计时候，以竺黄（竹叶）汤调下一钱。", "白话": "〔主治〕治心风烦热、恍惚、狂言妄语，时复惊恐而不自知，发作有定时，宜服小草散。〔组成·照录〕小草一两、柏子仁一两、犀角屑半两、赤茯苓一两、铁精一两（细研）、龙齿三分（细研）、天竺黄一两（细研）、生干地黄一两、琥珀末一两（细研）。〔方义〕小草（远志苗）、柏子仁、赤茯苓养心安神，犀角、天竺黄清心化痰，龙齿、铁精、琥珀重镇定惊，生干地黄滋阴，为清心镇惊之散。〔服法〕上药捣细罗为散，入已研药末混匀，不拘时候，以竺黄（竹叶）汤调下一钱服。"}, {"source": "条529｜《太平圣惠方》卷四·龙齿散", "原文": "《太平圣惠方》卷四：“治心脏风虚，惊悸失常，或喜或怒，神思不安，宜服龙齿散方。 　 \n龙齿一两  远志半两，去心  茯神一两  防风半两，去芦头  甘草半两，炙微赤，锉  人参三分，去芦头  麦门冬三分，去心  羚羊角屑三分　 \n上件药，捣粗罗为散。每服三钱，以水一中盏，入生姜半分，枣三枚，煎至六分。去滓，不计时候温服。", "白话": "〔主治〕治心脏风虚，惊悸失常，或喜或怒，神思不安。〔组成·照录〕龙齿一两、远志半两（去心）、茯神一两、防风半两（去芦头）、甘草半两（炙微赤，锉）、人参三分（去芦头）、麦门冬三分（去心）、羚羊角屑三分。〔方义〕龙齿镇惊安神，茯神、远志、麦冬养心，人参、甘草补心气，防风、羚羊角祛风清热，为养心祛风、镇惊定悸之散。〔服法〕上药捣粗罗为散，每服三钱，以水一中盏加生姜半分、枣三枚，煎至六分，去渣，不拘时候温服。"}, {"source": "条530｜《太平圣惠方》卷四·远志丸", "原文": "《太平圣惠方》卷四：“治心气不足，惊悸多忘，宜服远志丸方。 　 \n远志一两，去心  麦门冬一两，去心，焙  赤石脂一两  熟干地黄一两  人参一两，去芦头  茯神一两  甘草半两，炙微赤，锉  白术一（三）分 薯蓣一两　 \n上件药，捣罗为末，炼蜜和捣一、二百杵，丸如梧桐子大。每于食后，以清粥饮下三十丸。", "白话": "〔主治〕治心气不足，惊悸多忘。〔组成·照录〕远志一两（去心）、麦门冬一两（去心，焙）、赤石脂一两、熟干地黄一两、人参一两（去芦头）、茯神一两、甘草半两（炙微赤，锉）、白术一（三）分、薯蓣一两。〔方义〕人参、白术、薯蓣、甘草健脾益气，熟地、麦冬滋阴养血，远志、茯神安神益智，赤石脂收涩安神，为补心气、安心神之丸。〔服法〕上药捣罗为末，炼蜜和捣一二百杵，丸如梧桐子大，每于食后以清粥饮下三十丸。"}, {"source": "条531｜《太平圣惠方》卷四·沙参散", "原文": "《太平圣惠方》卷四：“治心风虚悸，恍惚多忘，惊恐，宜服沙参散方。 　 \n沙参三分，去芦头  白茯苓三分  远志半两，去心 犀角屑半两 甘草半两，炙微赤，锉  防风半两，去芦头  龙齿一两  天门冬一两，去心  生干地黄一两　 \n上件药，捣粗罗为散。每服三钱，以水一中盏，入生姜半分，枣二枚，煎至六分。去滓，不计时候温服。", "白话": "〔主治〕治心风虚悸，恍惚多忘，惊恐。〔组成·照录〕沙参三分（去芦头）、白茯苓三分、远志半两（去心）、犀角屑半两、甘草半两（炙微赤，锉）、防风半两（去芦头）、龙齿一两、天门冬一两（去心）、生干地黄一两。〔方义〕沙参、二冬、生地滋阴清热，远志、茯苓、龙齿安神定惊，防风祛风，甘草和中，为滋阴祛风、安神定悸之散。〔服法〕上药捣粗罗为散，每服三钱，以水一中盏加生姜半分、枣二枚煎至六分，去渣，不拘时候温服。"}, {"source": "条532｜《太平圣惠方》卷四·紫石英散", "原文": "《太平圣惠方》卷四：“治心脏风虚，惊悸失志，或瞋恚悲愁，志意不乐，惕惕若惊怖，宜服紫石英散方。 　 \n紫石英〔一（半）两细研，水飞过〕 防风（三分去芦头） 朱砂（一两细研如粉） 龙骨（一两） 人参〔二（三）分去芦头〕 细辛（三分） 甘草（半两炙微赤，锉） 羚羊角屑（三分） 远志（三分去心） 白藓皮白鲜皮（一两） 白茯苓（二两半） 熟干地黄（一两） 铁精（二两细研如粉） 牛黄（一分细研）　 \n上件药", "白话": "〔主治〕治心脏风虚，惊悸失志，或发怒悲愁，志意不乐，心惕惕然如受惊怖。〔组成·照录〕紫石英〔一（半）两，细研，水飞过〕、防风（三分，去芦头）、朱砂（一两，细研如粉）、龙骨（一两）、人参〔二（三）分，去芦头〕、细辛（三分）、甘草（半两，炙微赤，锉）、羚羊角屑（三分）、远志（三分，去心）、白藓皮（白鲜皮，一两）、白茯苓（二两半）、熟干地黄（一两）、铁精（二两，细研如粉）、牛黄（一分，细研）。〔方义〕紫石英、龙骨、铁精、朱砂、牛黄重镇安神，参、苓、熟地、甘草益气养血，远志安神，防风"}, {"source": "条533｜《太平圣惠方》卷四·熟干地黄散", "原文": "《太平圣惠方》卷四：“治心气不足，恍恍惚惚，朝差暮甚，惊悸，心中憧憧，胸满，不下食饮，阴阳气虚，脾胃不磨，不欲闻人声，宜服熟干地黄散方。 　 \n熟干地黄一两  当归一两，锉，微炒  龙骨一两  人参一两，去芦头  甘草一两，炙微赤，锉  桔梗一两，去芦头  黄芪二两，锉  桂心一两  半夏三分，汤洗七遍，去滑  茯神一两  远志半两，去心  枳壳一两，麸炒微黄，去瓤  白术半两 　 \n上件药，捣粗", "白话": "〔主治〕治心气不足，恍恍惚惚，早晨轻而傍晚加重，惊悸，心中憧憧不宁，胸满，饮食不下，阴阳气虚，脾胃运化无力，不欲闻人声。〔组成·照录〕熟干地黄一两、当归一两（锉，微炒）、龙骨一两、人参一两（去芦头）、甘草一两（炙微赤，锉）、桔梗一两（去芦头）、黄芪二两（锉）、桂心一两、半夏三分（汤洗七遍，去滑）、茯神一两、远志半两（去心）、枳壳一两（麸炒微黄，去瓤）、白术半两。〔方义〕参、芪、术、草配桂心益气温阳，熟地、当归养血，龙骨、茯神、远志安神定悸，半夏、枳壳、桔梗理气化痰和胃，为气血"}, {"source": "条534｜《太平圣惠方》卷四·茯神散", "原文": "《太平圣惠方》卷四：“治心风恍惚妄语，有所见闻，心悸，志意不定，宜服茯神散方。 　 \n茯神一两  人参一两，去芦头  赤小豆半两  菖蒲三分  龙骨角，一两  犀角屑一两  铁粉半两，研  金箔三十片，研　 \n上件药，捣细罗为散，入研了药，令匀。每服不计时候，以金银汤放温，调下一钱。", "白话": "〔主治〕治心风恍惚妄语，似有所见闻，心悸，志意不定。〔组成·照录〕茯神一两、人参一两（去芦头）、赤小豆半两、菖蒲三分、龙骨角一两、犀角屑一两、铁粉半两（研）、金箔三十片（研）。〔方义〕茯神、菖蒲、人参安神定志，龙骨（角）、铁粉、金箔重镇定惊，犀角清心，赤小豆利湿，为镇心安神之散。〔服法〕上药捣细罗为散，入已研药末混匀，不拘时候，以金银汤放温调下一钱。"}, {"source": "条535｜《养生通论·养老奉亲书》·旋覆花散", "原文": "《养生通论·养老奉亲书》：“治老人风热上攻，头旋运闷，喜卧，怔悸，起即欲倒，背急身强。旋复花旋覆花散（女人通用）。", "白话": "〔主治〕治老人风热上攻，头旋晕闷，喜躺卧，怔悸，起身即欲跌倒，背急身体强直——用旋覆花散（女人通用）。〔组成·服法〕原稿未载。〔方义〕旋覆花降气化痰，配祛风清热之品则眩悸可止（组成原稿未录，方义姑以方名推之）。"}, {"source": "条536｜《单方验方·旅舍备要方》·半夏化痰丸", "原文": "《半夏化痰丸\n《单方验方·旅舍备要方》：“半夏化痰丸。治痰实恶心呕吐，头目昏晕，心悸，背寒，臂病，涎漱，膈不快。 　 \n半夏一两，汤洗去滑  赤茯苓半两，去皮  白矾一分，枯 铅白霜半两　 \n上为末。取生姜自然汁，煮面糊为丸，如梧桐子大。每服十五丸，生姜汤下。", "白话": "〔方名〕半夏化痰丸。〔主治〕治痰实恶心呕吐，头目昏晕，心悸，背寒，臂痛，涎沫频出，胸膈不快。〔组成·照录〕半夏一两（汤洗去滑）、赤茯苓半两（去皮）、白矾一分（枯）、铅白霜半两。〔方义〕半夏、赤茯苓化痰燥湿降逆，枯白矾、铅白霜劫痰定惊，为攻逐痰实之丸。〔制法·服法〕上为末，取生姜自然汁煮面糊为丸如梧桐子大，每服十五丸，生姜汤下。"}, {"source": "条537｜《圣济总录》卷三十一·前胡汤", "原文": "前胡汤\n《圣济总录》卷三十一：治伤寒后惊悸不定，前胡汤方。 　 \n前胡去芦头、茯神去木、人参各一两  远志去心，一两半  甘草炙，一分 \n上五味，粗捣筛每服二钱匕，水一盏，同煎至七分，去滓温服，不计时候。", "白话": "〔主治〕治伤寒后惊悸不定。〔组成·照录〕前胡（去芦头）、茯神（去木）、人参各一两，远志（去心）一两半，甘草（炙）一分。〔方义〕前胡清余热、降气，茯神、远志、人参安神定志，炙甘草和中，为伤寒后养心定悸之方。〔服法〕上五味粗捣筛，每服二钱匕，水一盏同煎至七分，去渣温服，不拘时候。"}, {"source": "条538｜《圣济总录》卷七十三·白术丸", "原文": "白术丸\n《圣济总录》卷七十三：治冷癖气因服热药发热。心惊虚悸，下冷上热，头风呕逆，白术丸方。 　 \n白术、陈橘皮去白，焙，各一两半  白芷三分   防风去叉、吴茱萸汤洗七遍，焙干、芎、山芋、厚朴去粗皮，涂生汁，炙熟、桂去粗皮、大麦锉，炒、干姜炮、防葵锉，各一两  甘草炙，锉、茯神去木、人参各一两一分　 \n上一十五味，捣罗为末，炼蜜和丸，如梧桐子大，每日空心温酒下二十丸。", "白话": "〔主治〕治冷癖气因服热药而发热，心惊虚悸，下冷上热，头风呕逆。〔组成·照录〕白术、陈橘皮（去白，焙）各一两半，白芷三分，防风（去叉）、吴茱萸（汤洗七遍，焙干）、芎、山芋、厚朴（去粗皮，涂生姜汁，炙熟）、桂（去粗皮）、大麦（锉，炒）、干姜（炮）、防葵（锉）各一两，甘草（炙，锉）、茯神（去木）、人参各一两一分。〔方义〕白术、干姜、吴茱萸、桂温中散寒，陈皮、厚朴理气，防风、白芷、防葵祛风，芎活血，参、苓、草益气，山芋（山药）补脾，大麦和中，为温中健脾、散寒定悸之丸。〔服法〕上十五味"}, {"source": "条539｜《太平惠民和剂局方》卷四·二陈汤", "原文": "二陈汤\n《太平惠民和剂局方》卷四：二陈汤。治痰饮为患，或呕吐恶心，或头眩心悸，或中脘不快，或发为寒热，或因食生冷，脾胃不和。 　 \n半夏汤洗七次、橘红各五两  白茯苓三两  甘草炙，一两半　 \n上为㕮咀，每服四钱，用水一钱，生姜七片，乌梅一个，同煎六分，去滓，\n热服，不拘时候。", "白话": "〔主治〕治痰饮为患：或呕吐恶心，或头眩心悸，或中脘不快，或发为寒热，或因食生冷而脾胃不和。〔组成·照录〕半夏（汤洗七次）、橘红各五两，白茯苓三两，甘草（炙）一两半。〔方义〕半夏、橘红燥湿化痰理气，茯苓健脾渗湿，炙甘草和中，为治痰湿总方，痰化则眩悸自止。〔服法〕上药㕮咀，每服四钱，用水一钱（疑当作一盏），生姜七片、乌梅一个同煎至六分，去渣热服，不拘时候。"}, {"source": "条540｜《校注妇人良方》卷三·温胆汤", "原文": "温胆汤\n《校注妇人良方》卷三：温胆汤。治胆虚痰热，惊悸不眠。 　 \n半夏、竹茹、枳实麸炒，各一两  陈皮  生姜四两  甘草炒，三两　 \n上每服一两，水煎。", "白话": "〔主治〕治胆虚痰热，惊悸不眠。〔组成·照录〕半夏、竹茹、枳实（麸炒）各一两，陈皮（原稿未著剂量），生姜四两，甘草（炒）三两。〔方义〕半夏、竹茹、枳实、陈皮理气化痰清热，生姜、甘草和胃，为清胆化痰、安神定悸之方。〔服法〕上药每服一两，水煎。"}, {"source": "条541｜《严氏济生方·惊悸怔忡健忘门》·茯苓饮子", "原文": "茯苓饮子\n《严氏济生方·惊悸怔忡健忘门》：茯苓饮子。治痰饮蓄于心胃，怔忡不已。 　 \n赤茯苓去皮、半夏汤泡七次、茯神去木、橘皮去白、麦门冬去心，各一两  沉香不见火、甘草炙、槟榔各半两　 \n上㕮咀，每服四钱，水一盏半，生姜五片，煎至七分，去滓，温服，不拘时候。", "白话": "〔主治〕治痰饮蓄积于心胃，怔忡不止。〔组成·照录〕赤茯苓（去皮）、半夏（汤泡七次）、茯神（去木）、橘皮（去白）、麦门冬（去心）各一两，沉香（不见火）、甘草（炙）、槟榔各半两。〔方义〕二茯、麦冬养心安神，半夏、橘皮化痰，沉香、槟榔降气行滞，炙草和中，为化痰饮、降逆气、定怔忡之方。〔服法〕上药㕮咀，每服四钱，水一盏半加生姜五片煎至七分，去渣温服，不拘时候。"}, {"source": "条542｜《严氏济生方·惊悸怔忡健忘门》·温胆汤", "原文": "温胆汤\n《严氏济生方·惊悸怔忡健忘门》：温胆汤。治心虚胆怯，触事易惊，梦寐不祥，异象感惑，遂致心惊胆怯，气郁生涎，涎与气搏，复生诸证，或短气悸乏，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。 　 \n半夏汤泡七次、竹茹、枳实去瓤，各二两  陈皮去白，三两  白茯苓去皮，一两半甘草一两，炙　 \n上㕮咀，每服四钱，水一盏半，生姜五片，枣子一枚，煎至七分，去滓，温服，不拘时候。", "白话": "〔主治〕治心虚胆怯，遇事易惊，梦寐不祥，为异象所惑，遂致心惊胆怯，气郁生涎，涎与气相搏结，变生诸证：或短气悸乏，或自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。〔组成·照录〕半夏（汤泡七次）、竹茹、枳实（去瓤）各二两，陈皮（去白）三两，白茯苓（去皮）一两半，甘草一两（炙）。〔方义〕半夏、竹茹、枳实、陈皮理气化痰，茯苓、甘草健脾和中，痰气得化则胆宁心安。〔服法〕上药㕮咀，每服四钱，水一盏半加生姜五片、枣子一枚煎至七分，去渣温服，不拘时候。"}, {"source": "条543｜《严氏济生方·惊悸怔忡健忘门》·寿星丸", "原文": "寿星丸\n《严氏济生方·惊悸怔忡健忘门》：寿星丸。治惊忧思虑，气结成痰，留蓄心包，怔忡惊惕，痰逆恶心，睡卧不安。", "白话": "〔主治〕治惊恐忧思，气结成痰，留蓄于心包，致怔忡惊惕、痰逆恶心、睡卧不安。〔组成·服法〕原稿未载。〔方义〕行气化痰、清心安神（组成原稿未录，方义以主治推之）。"}, {"source": "条544｜《仁斋直指方论（附补遗）》卷十一·温胆汤", "原文": "温胆汤\n《仁斋直指方论（附补遗）》卷十一：温胆汤。治心胆虚怯，触事多惊。亦治水气怔悸。 　 \n半夏制、枳壳制、白茯苓各一两 橘红一两半 甘草炙，半两　 \n上锉，每服三钱半，姜七片，枣二枚，刮青竹皮一块如钱大，煎服。或加制远志尤妙。", "白话": "〔主治〕治心胆虚怯，遇事多惊；也治水气上凌之怔悸。〔组成·照录〕半夏（制）、枳壳（制）、白茯苓各一两，橘红一两半，甘草（炙）半两。〔方义〕半夏、橘红、枳壳理气化痰，茯苓利水宁心，炙甘草和中，加青竹皮清热除烦，共成化痰定悸之方。〔服法〕上药锉碎，每服三钱半，生姜七片、枣二枚、刮青竹皮一块如钱大，煎服；或加制远志尤妙。"}, {"source": "条545｜《御药院方》卷五·小半夏汤", "原文": "小半夏汤\n《御药院方》卷五：小半夏汤。治诸呕哕，心下坚痞，膈间有痰水，眩悸。  \n半夏五两，汤洗七次 白茯苓去皮，用三两   \n上㕮咀，每服称半两，水三盏煎至一盏，称生姜四钱，取自然汁投药中，更煎一两沸，热吃，不拘时候。", "白话": "〔主治〕治各种呕吐呃逆，心下坚痞，膈间有痰水，眩晕心悸。〔组成·照录〕半夏五两（汤洗七次）、白茯苓（去皮）三两。〔方义〕半夏化痰降逆止呕，茯苓健脾利水，为治膈间痰水眩悸之小方。〔服法〕上药㕮咀，每服称取半两，水三盏煎至一盏；另称生姜四钱，取自然汁投入药中，再煎一两沸，热服，不拘时候。"}, {"source": "条546｜《御药院方》卷五·白术茯苓丸", "原文": "白术茯苓丸\n《御药院方》卷五：白术茯苓丸。治三焦气涩，停痰不消，胸膈痞闷，腹胁胀满，咳嗽涎甚，咽嗌干痛，心忪悸动，头目眩晕，寒热时作，肢节疼痛，呕吐清水，神昏多倦，不欲饮食。  \n白茯苓、白术各半两，白者 天南星、白附子各一两 白矾三分 半夏三两，并生用  \n上为细末，白面糊和丸，如梧桐子大。每服二三十丸，生姜汤下，不拘时候。", "白话": "〔主治〕治三焦气涩，停痰不消，胸膈痞闷，腹胁胀满，咳嗽涎多，咽嗌干痛，心忪悸动，头目眩晕，寒热时作，肢节疼痛，呕吐清水，神昏多倦，不欲饮食。〔组成·照录〕白茯苓、白术各半两（用白者），天南星、白附子各一两，白矾三分，半夏三两（并生用）。〔方义〕白术、茯苓健脾燥湿，南星、白附、半夏、白矾化痰逐饮，为攻化三焦停痰之丸。〔制法·服法〕上为细末，白面糊和丸如梧桐子大，每服二三十丸，生姜汤下，不拘时候。"}, {"source": "条547｜《御药院方》卷五·半夏利膈丸", "原文": "半夏利膈丸\n《御药院方》卷五：半夏利膈丸。治风痰郁甚，头疼目眩，咽膈不利，涕唾稠黏，胸中烦满，酒癖停饮，呕逆恶心，胁下急痛，腹中水声，神思昏愦，心忪面热，止嗽化痢。  \n白术、人参、白茯苓去皮、白矾生、滑石、贝母各一两 天南星生用，一两半 白附子生二两 半夏汤洗，三两   \n上为细末，水面糊为丸，如梧桐子大。每服三十丸，食后生姜汤送下。", "白话": "〔主治〕治风痰郁甚：头疼目眩，咽膈不利，涕唾稠黏，胸中烦满，酒癖停饮，呕逆恶心，胁下急痛，腹中水声，神思昏愦，心忪面热；并能止嗽化痢。〔组成·照录〕白术、人参、白茯苓（去皮）、白矾（生）、滑石、贝母各一两，天南星（生用）一两半，白附子（生）二两，半夏（汤洗）三两。〔方义〕参、术、苓健脾，南星、白附、半夏、白矾祛风痰，贝母化痰，滑石利湿，为祛风痰、利胸膈之丸。〔制法·服法〕上为细末，水面糊为丸如梧桐子大，每服三十丸，食后生姜汤送下。"}, {"source": "条548｜《御药院方》卷五·润肺丸", "原文": "润肺丸\n《御药院方》卷五：润肺丸。治肺气不调，咳嗽声重，日久不止，痰涕结搏，咽嗌不利，心神烦躁，头目昏重，精神不爽，心忪烦悸，喉中呀呷，逐气有声，一切痰实并皆治之。  \n朱砂水飞、五灵脂微炒，各二两 苦葶苈隔纸炒、杏仁去皮尖，麸炒、半夏曲各一两   \n上为细末。生姜汁面糊为丸，如梧桐子大。每服四十丸，食后生姜汤送下。", "白话": "〔主治〕治肺气不调，咳嗽声重，日久不止，痰涕结搏，咽嗌不利，心神烦躁，头目昏重，精神不爽，心忪烦悸，喉中呀呷有声，呼吸气出有声；一切痰实之证并皆治之。〔组成·照录〕朱砂（水飞）、五灵脂（微炒）各二两，苦葶苈（隔纸炒）、杏仁（去皮尖，麸炒）、半夏曲各一两。〔方义〕葶苈、杏仁、半夏曲降气化痰止咳，朱砂镇心安神，五灵脂活血，为润肺化痰、镇心定悸之丸。〔制法·服法〕上为细末，生姜汁面糊为丸如梧桐子大，每服四十丸，食后生姜汤送下。"}, {"source": "条549｜《御药院方》卷六·辰砂远志丸", "原文": "辰砂远志丸\n《御药院方》卷六：辰砂远志丸。安神镇心，补肾益志。治惊悸，消风痰，止头眩。  \n石菖蒲、远志去心、人参、茯神、川芎、山芋、铁粉、麦门冬、天麻、细夏曲、天南星锉，炒黄、白附子生用，以上各一两  细辛半两  辰砂一两四钱，入药六钱，为末  \n上为细末，生姜五两取汁，入水煮面糊为丸，如绿豆大，以朱砂为衣。每服三五十丸，临卧生姜汤下。", "白话": "〔功效·主治〕安神镇心，补肾益志；治惊悸，消风痰，止头眩。〔组成·照录〕石菖蒲、远志（去心）、人参、茯神、川芎、山芋、铁粉、麦门冬、天麻、细夏曲、天南星（锉，炒黄）、白附子（生用）以上各一两，细辛半两，辰砂一两四钱（其中六钱入药，为末）。〔方义〕菖蒲、远志、茯神、人参安神益智，天麻、南星、白附、夏曲祛风痰，川芎、细辛上行头目，麦冬、山芋、铁粉、辰砂镇心定惊，为安神镇心、消风痰之丸。〔制法·服法〕上为细末，生姜五两取汁入水煮面糊为丸如绿豆大，以朱砂为衣，每服三五十丸，临卧生姜汤"}, {"source": "条550｜《世医得效方》卷八·十味温胆汤", "原文": "十味温胆汤\n《世医得效方》卷八：十味温胆汤。治心胆虚怯，触事易惊，梦寐不祥，异象感惑，遂致心惊胆慑，气郁生涎，涎与气搏，变生诸证。或短气悸乏，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。 　 \n半夏汤洗七次、枳实去瓤，切，麸炒、陈皮去白，各三两 白茯苓去皮，两半 酸枣仁微炒 大远志去心，甘草水煮，姜汁炒，一两 北五味子、熟地黄切，酒炒、条参各一两 粉草五钱　 \n上锉散。每服四钱，水盏半，姜五", "白话": "〔主治〕治心胆虚怯，遇事易惊，梦寐不祥，为异象所惑，遂致心惊胆慑，气郁生涎，涎与气相搏，变生诸证：或短气悸乏，或自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。〔组成·照录〕半夏（汤洗七次）、枳实（去瓤，切，麸炒）、陈皮（去白）各三两，白茯苓（去皮）两半，酸枣仁（微炒）、大远志（去心，甘草水煮，姜汁炒）一两，北五味子、熟地黄（切，酒炒）、条参各一两，粉草五钱。〔方义〕温胆汤（半夏、枳实、陈皮、茯苓）理气化痰，加枣仁、远志、五味子、熟地、条参养心安神益阴，为化痰与养心并进之十味方"}, {"source": "条551｜《婴童百问》卷二·温胆汤", "原文": "温胆汤\n《婴童百问》卷二：温胆汤。治惊悸烦躁不得眠。  \n半夏、枳实各二钱半 茯苓半两 桔红、甘草各一钱半 酸枣仁去壳，二钱半 腹疼加芍药。\n上㕮咀，每服一钱，入竹茹少许，姜、枣煎服。", "白话": "〔主治〕治惊悸烦躁不得眠。〔组成·照录〕半夏、枳实各二钱半，茯苓半两，桔红、甘草各一钱半，酸枣仁（去壳）二钱半。〔方义〕半夏、枳实、桔红、竹茹化痰清热，茯苓、枣仁养心安神，姜、枣、草和中，为小儿化痰安神之温胆汤小剂。〔服法〕上药㕮咀，每服一钱，入竹茹少许，姜、枣煎服。〔加减〕腹痛加芍药。"}, {"source": "条552｜《婴童百问》卷六·生犀散", "原文": "生犀散\n《婴童百问》卷六：生犀散。治咳嗽，解时气痰逆喘满，心忪忡惊悸、风热。  \n杏仁二钱、炒 桔梗二钱 茯苓一钱 前胡一钱半 人参一钱 半夏一钱 五味子一钱 甘草一钱  \n上㕮咀，生姜薄荷煎服。有热加羌活，或加麻黄细辛。", "白话": "〔主治〕治咳嗽，解时行之气痰逆喘满，心忪忡惊悸、风热。〔组成·照录〕杏仁二钱（炒）、桔梗二钱、茯苓一钱、前胡一钱半、人参一钱、半夏一钱、五味子一钱、甘草一钱。〔方义〕杏仁、桔梗、前胡宣肺止咳，半夏化痰，参、苓、草、五味子益气敛肺，为解表化痰、兼安心神之散。〔服法〕上药㕮咀，生姜、薄荷煎服。〔加减〕有热加羌活，或加麻黄、细辛。"}, {"source": "条553｜《婴童百问》卷七·茯苓半夏汤", "原文": "茯苓半夏汤\n《婴童百问》卷七：茯苓半夏汤。治诸呕吐，心下坚痞，膈间有痰水眩悸。  \n茯苓二两 半夏五钱、汤泡七次  \n上㕮咀，每服三钱，水一盏，生姜三片，煎六分服。", "白话": "〔主治〕治各种呕吐，心下坚痞，膈间有痰水而眩悸。〔组成·照录〕茯苓二两、半夏五钱（汤泡七次）。〔方义〕茯苓健脾利水，半夏化痰降逆止呕，为治膈间痰水眩悸之小方（与条545 小半夏汤同法而分量异）。〔服法〕上药㕮咀，每服三钱，水一盏加生姜三片煎至六分服。"}, {"source": "条554｜《医学正传》卷一·二陈汤（中风加减）", "原文": "二陈汤\n《医学正传》卷一：凡中风证，悉以二陈汤加姜汁、竹沥为主。风痰盛、声如拽锯者，加南星、枳壳、皂角、防风、栝蒌仁。或心动摇惊悸者，更加酸枣仁、茯神、侧柏叶、竹茹，连前共作一剂，煎服。", "白话": "〔主治〕凡中风证，都以二陈汤加姜汁、竹沥为主治。风痰盛、喉中痰声如拉锯者，加南星、枳壳、皂角、防风、栝蒌仁；若心动摇惊悸者，再加酸枣仁、茯神、侧柏叶、竹茹，连同前方共作一剂，煎服。〔组成·服法〕二陈汤（半夏、橘红、茯苓、甘草）加姜汁、竹沥，随证加减，水煎服。〔方义〕二陈汤化痰，姜汁、竹沥豁痰开窍，加枣仁、茯神、侧柏叶、竹茹安神定悸。"}, {"source": "条555｜《扶寿精方·脾胃门》·黄连磨积丸", "原文": "黄连磨积丸\n《扶寿精方·脾胃门》：黄连磨积丸。治一切痰饮痰积，积聚怫郁，胁下闷倦，懒惰饮食不消，或吐逆，恶心，眩晕怔忡，时作时止，用之如神。  \n黄连一两，内五钱吴茱萸同炒，五钱益智仁同炒，去二味不用，止用黄连 栀子炒，去杇、白芥子醋浸炒，各五钱 川芎、苍术米泔浸七日、桃仁去皮存尖、青皮去瓤、香附子童便浸，炒、莪术酒浸，炒、山楂肉、莱菔子炒研、白术各一两 三棱用西安府者，一两五钱  \n上为细末，量", "白话": "〔主治〕治一切痰饮痰积，积聚怫郁，胁下闷倦，懒于饮食而食不消化，或吐逆、恶心、眩晕怔忡，时作时止，用之如神。〔组成·照录〕黄连一两（其中五钱与吴茱萸同炒、五钱与益智仁同炒，去二味不用，只用黄连），栀子（炒，去杇）、白芥子（醋浸炒）各五钱，川芎、苍术（米泔浸七日）、桃仁（去皮存尖）、青皮（去瓤）、香附子（童便浸，炒）、莪术（酒浸，炒）、山楂肉、莱菔子（炒研）、白术各一两，三棱（用西安府者）一两五钱。〔方义〕黄连、栀子清热，三棱、莪术、桃仁、山楂消积破血，青皮、香附、莱菔子理气，"}, {"source": "条556｜《古今医统大全》卷四十三·茯苓饮子", "原文": "茯苓饮子\n《古今医统大全》卷四十三：济生茯苓饮子。治痰饮蓄于心膈，怔忡不已。  \n赤茯苓、茯神、半夏、麦门冬、陈皮各一两 沉香、槟榔、甘草各三钱   \n上咀，每服八钱，生姜五片，煎八分，食后温服。", "白话": "〔主治〕治痰饮蓄于心膈，怔忡不止（《济生》茯苓饮子）。〔组成·照录〕赤茯苓、茯神、半夏、麦门冬、陈皮各一两，沉香、槟榔、甘草各三钱。〔方义〕二茯、麦冬养心，半夏、陈皮化痰，沉香、槟榔降气，甘草和中，为化痰定怔忡之方。〔服法〕上药咀碎，每服八钱，生姜五片煎取八分，食后温服。"}, {"source": "条557｜《脉症治方》卷四·二陈汤（加减）", "原文": "二陈汤\n《脉症治方》卷四：二陈汤。心下怔忡，属痰，加麦门冬、枳实、竹茹各等分。脾黄，加白术、厚朴、苍术各一钱、草果七分。", "白话": "〔主治·加减〕二陈汤：心下怔忡属痰者，加麦门冬、枳实、竹茹各等分；脾色黄（脾湿见证）者，加白术、厚朴、苍术各一钱、草果七分。〔组成·服法〕二陈汤（半夏、橘红、茯苓、甘草）加减水煎服。〔方义〕二陈汤化痰，加麦冬、竹茹、枳实清热化痰定悸，加术、朴、草果健脾燥湿。"}, {"source": "条558｜《医学入门·外集》·参胡温胆汤", "原文": "参胡温胆汤\n《医学入门·外集》：参胡温胆汤。\n陈皮、半夏、茯苓、枳实、人参各一钱，竹茹、香附、麦门冬、柴胡、桔梗各八分，甘草三分  姜三片  枣二枚\n水煎温服。\n治心胆虚怯，触事易惊，梦寝不安，气郁生痰，变生诸证，或短气悸乏，或复自汗，四肢浮肿，饮食无味，烦躁不安。", "白话": "〔方名〕参胡温胆汤。〔组成·照录〕陈皮、半夏、茯苓、枳实、人参各一钱，竹茹、香附、麦门冬、柴胡、桔梗各八分，甘草三分，生姜三片，大枣二枚。〔方义〕温胆汤（半夏、陈皮、茯苓、枳实、竹茹）化痰清胆，加人参益气、柴胡疏肝、香附理气、麦冬养阴、桔梗宣肺，为益气化痰、疏肝安神之方。〔服法〕水煎温服。〔主治〕治心胆虚怯，触事易惊，梦寝不安，气郁生痰，变生诸证：或短气悸乏，或自汗，四肢浮肿，饮食无味，烦躁不安。"}, {"source": "条559｜《古今医鉴》卷八·温胆汤", "原文": "温胆汤\n《古今医鉴》卷八：温胆汤。治病后虚烦不得卧，及心胆虚怯，触事易惊，短气悸乏，或复自汗，并治。  \n半夏七钱 竹茹、枳实各三钱 陈皮四钱半 白茯苓去皮 甘草炙，二钱二分半  \n上锉作一剂，姜、枣煎服。", "白话": "〔主治〕治病后虚烦不得卧，及心胆虚怯、触事易惊、短气悸乏，或自汗，均治。〔组成·照录〕半夏七钱，竹茹、枳实各三钱，陈皮四钱半，白茯苓（去皮，原稿未著剂量），甘草（炙）二钱二分半。〔方义〕半夏、竹茹、枳实、陈皮理气化痰，茯苓、甘草健脾和中，为化痰安神之温胆汤。〔服法〕上药锉作一剂，姜、枣煎服。"}, {"source": "条560｜《育婴家秘》卷一·温胆汤", "原文": "温胆汤\n《育婴家秘》卷一：温胆汤。治心胆虚怯，触事多惊，亦治水气怔悸。  \n半夏制、枳壳制、白茯苓各一两 橘红一两半 甘草炙，五钱  \n锉，和匀，每服三钱半，姜七片，枣三枚，刮竹青一块，如钱大，水煎服。或加制远志尤妙。不睡者，胆寒也，加酸枣仁炒。若喜睡者，胆热也，酸枣仁生用。", "白话": "〔主治〕治心胆虚怯，遇事多惊；也治水气怔悸。〔组成·照录〕半夏（制）、枳壳（制）、白茯苓各一两，橘红一两半，甘草（炙）五钱。〔方义〕半夏、橘红、枳壳理气化痰，茯苓利水宁心，炙甘草和中，为化痰定悸之方。〔服法〕锉碎和匀，每服三钱半，生姜七片、枣三枚、刮竹青一块如钱大，水煎服；或加制远志尤妙。〔加减〕不睡者属胆寒，加炒酸枣仁；喜睡者属胆热，酸枣仁生用。"}, {"source": "条561｜《仁术便览》卷一·加味温胆汤", "原文": "加味温胆汤\n《仁术便览》卷一：加味温胆汤。治心胆虚怯，触事易惊，梦昧不祥，气郁生涎。涎与气抟亦生诸症，或短气悸乏，或复自汗，四肢浮肿，饮食无味。  \n枳实、半夏、竹茹各八两 陈皮十二两 白茯苓六两 甘草炙，四两 加香附一斤半 人参、柴胡、麦冬、桔梗各六两  \n每服一两，生姜五片，枣二枚，水煎服。", "白话": "〔主治〕治心胆虚怯，触事易惊，梦寐不祥，气郁生涎，涎与气相抟亦生诸证：或短气悸乏，或自汗，四肢浮肿，饮食无味。〔组成·照录〕枳实、半夏、竹茹各八两，陈皮十二两，白茯苓六两，甘草（炙）四两，加香附一斤半，人参、柴胡、麦冬、桔梗各六两。〔方义〕温胆汤加香附、柴胡疏肝理气，人参益气，麦冬养阴，桔梗宣肺，为大剂加味温胆汤。〔服法〕每服一两，生姜五片、枣二枚，水煎服。"}, {"source": "条562｜《仁术便览》卷三·茯苓饮子", "原文": "茯苓饮子\n《仁术便览》卷三：茯苓饮子。治痰饮蓄于心经，怔忡不已。  \n赤茯苓、半夏、麦门冬、陈皮各一两 沉香不见火、甘草、槟榔各五钱\n上每服八钱，姜三片，水煎服。", "白话": "〔主治〕治痰饮蓄于心经，怔忡不止。〔组成·照录〕赤茯苓、半夏、麦门冬、陈皮各一两，沉香（不见火）、甘草、槟榔各五钱。〔方义〕赤茯苓、麦冬养心，半夏、陈皮化痰，沉香、槟榔降气，甘草和中，为化痰饮、定怔忡之方。〔服法〕上药每服八钱，生姜三片，水煎服。"}, {"source": "条563｜《医学原理》卷九·养心汤", "原文": "养心汤\n《医学原理》卷九：养心汤。治肥人气虚夹痰惊悸。治宜补气豁痰为主，安神定气为标。是以用人参、黄芪、甘草以补气，茯神、远志、柏子仁、酸枣仁等，安心神以定惊悸，佐桂心、川芎以导血脉，五味、半夏清金以豁痰。  \n人参甘温，二钱 黄芪甘温，钱半 甘草甘温，五分 茯神甘平，八分 远志苦温，七分 柏子仁辛平，八分 酸枣仁酸平，一钱 桂心辛温，五分 川芎辛温，八分 五味子甘酸平，七分 半夏苦辛温，七分  ", "白话": "〔主治〕治肥人气虚夹痰之惊悸。治宜补气豁痰为主，安神定气为标。故用人参、黄芪、甘草补气，茯神、远志、柏子仁、酸枣仁等安心神以定惊悸，佐桂心、川芎通导血脉，五味子、半夏清金（肺）以豁痰。〔组成·照录〕人参（甘温）二钱，黄芪（甘温）钱半，甘草（甘温）五分，茯神（甘平）八分，远志（苦温）七分，柏子仁（辛平）八分，酸枣仁（酸平）一钱，桂心（辛温）五分，川芎（辛温）八分，五味子（甘酸平）七分，半夏（苦辛温）七分。〔方义〕参、芪、草补气，茯神、远志、柏子仁、枣仁安神，桂心、川芎温通血脉，"}, {"source": "条564｜《证治准绳·杂病》·导痰汤加石菖蒲", "原文": "导痰汤\n《证治准绳·杂病》：大抵惊悸健忘，怔忡失志，心风不寐，皆是胆涎沃心，以致心气不足。若用凉心之剂太过，则心火愈微，痰涎愈盛，病愈不减，唯当以理痰气为第一义，导痰汤加石菖蒲半钱。", "白话": "〔主治·论治〕大抵惊悸健忘、怔忡失志、心风不寐，皆是胆中痰涎浸渍于心，以致心气不足。若用凉心之剂太过，则心火愈微、痰涎愈盛，病愈不减；唯当以理痰气为第一要义，用导痰汤加石菖蒲半钱。〔组成·服法〕导痰汤（半夏、南星、枳实、橘红、茯苓、甘草类）加石菖蒲半钱，水煎服（原稿未列组成，方名导痰汤）。"}, {"source": "条565｜《济阳纲目》卷五十四·加味定志丸", "原文": "加味定志丸\n《济阳纲目》卷五十四：加味定志丸。治肥人痰迷心膈，寻常怔忡惊悸。  \n远志、菖蒲各二两 人参一两 白茯苓三两 琥珀 郁金  \n上为末，炼蜜丸如桐子大，朱砂为衣，每服三十丸，米汤下。一方有天花粉、贝母、瓜蒌仁。", "白话": "〔主治〕治肥人痰迷心膈，寻常怔忡惊悸。〔组成·照录〕远志、菖蒲各二两，人参一两，白茯苓三两，琥珀、郁金（原稿未著剂量）。〔方义〕定志丸（远志、菖蒲、人参、茯苓）益心定志，加琥珀、郁金活血安神、解郁化痰，为化痰开窍、安神定志之丸。〔制法·服法〕上为末，炼蜜丸如梧桐子大，朱砂为衣，每服三十丸，米汤下。一方有天花粉、贝母、瓜蒌仁。"}, {"source": "条566｜《济阳纲目》卷五十四·辰砂远志丸", "原文": "辰砂远志丸\n《济阳纲目》卷五十四：辰砂远志丸。治惊悸，消风痰。  \n石菖蒲、远志、人参、茯神、川芎、山药、铁粉、麦冬、天麻、半夏、南星、茯苓各一两 北细辛、辰砂各半两  \n上为细末，生姜五两，取汁入水，煮糊为丸，如绿豆大，另以朱砂为衣，每服二十五丸，临卧生姜汤下，小儿减服。", "白话": "〔主治〕治惊悸，消风痰。〔组成·照录〕石菖蒲、远志、人参、茯神、川芎、山药、铁粉、麦冬、天麻、半夏、南星、茯苓各一两，北细辛、辰砂各半两。〔方义〕菖蒲、远志、茯神、人参安神益智，天麻、半夏、南星祛风痰，川芎、细辛上行头目，铁粉、辰砂镇心，山药、麦冬、茯苓养心健脾，为消风痰、定惊悸之丸。〔制法·服法〕上为细末，生姜五两取汁入水煮糊为丸如绿豆大，另以朱砂为衣，每服二十五丸，临卧生姜汤下，小儿减量。"}, {"source": "条567｜《济阳纲目》卷五十四·温胆汤加味", "原文": "温胆汤\n《济阳纲目》卷五十四：怔忡因惊悸久而成，痰在下火在上故也，温胆汤加黄连、山栀、当归、贝母。", "白话": "〔主治·论治〕怔忡由惊悸日久而成，是痰在下而火在上之故，用温胆汤加黄连、山栀、当归、贝母。〔组成·服法〕温胆汤（半夏、竹茹、枳实、陈皮、茯苓、甘草类）加黄连、山栀、当归、贝母，水煎服。〔方义〕温胆汤化痰，加黄连、山栀清上焦之火，当归养血，贝母化痰散结，为清火化痰、养血定悸之方。"}, {"source": "条568｜《菉竹堂集验方》卷六·无名方（治怔忡痰厥）", "原文": "无名方\n《菉竹堂集验方》卷六：治怔忡痰厥方。\n腊八日用大雄猪胆一个，将明矾碾细，入胆内，盛满为度，阴干去皮，仍碾细。每钱加飞过朱砂三分和匀，用无根水服三铜钱边即愈。所谓三铜钱边者，即一刀圭之意，而极言其少也。", "白话": "〔主治〕治怔忡痰厥方。〔制法〕腊八日取大雄猪胆一个，将明矾碾细，装入胆内，以盛满为度，阴干后去胆皮，仍将药碾细。〔服法〕每钱（药末一钱）加水飞过朱砂三分和匀，用无根水服“三铜钱边”即愈。所谓三铜钱边，即一刀圭之意，极言其量之少。"}, {"source": "条569｜《病机沙篆》卷下·导痰汤、二陈汤加减", "原文": "导痰汤\n《病机沙篆》卷下：大凡怔忡失志，惊悸健忘，心风不寐，皆系胆涎沃心，或因心气不足，反以凉心大过，心火益微，痰涎愈盛，唯以理痰顺气为第一义，导痰、二陈加枳壳、南星，菖蒲。", "白话": "〔主治·论治〕大凡怔忡失志、惊悸健忘、心风不寐，皆系胆中痰涎浸渍于心；或因心气不足，反用凉心之药太过，致心火愈微、痰涎愈盛——唯以理痰顺气为第一要义，用导痰汤、二陈汤加枳壳、南星、菖蒲。〔组成·服法〕导痰汤或二陈汤加枳壳、天南星、石菖蒲，水煎服。"}, {"source": "条570｜《不居集·上集》·朱砂消痰饮", "原文": "朱砂消痰饮\n《不居集·上集》：或迷心窍，心痛惊悸，怔忡恍惚，梦寐奇怪，妄言见鬼，颠狂痫喑。朱砂消痰饮。", "白话": "〔主治〕或痰迷心窍，心痛惊悸，怔忡恍惚，梦寐奇怪，妄言见鬼，癫狂、痫证、喑哑——用朱砂消痰饮。〔组成·服法〕原稿未载。〔方义〕朱砂镇心安神、化痰开窍（组成原稿未录，方义以方名推之）。"}, {"source": "条571｜《不居集·上集》·温胆汤", "原文": "温胆汤\n《不居集·上集》：温胆汤。治气郁生涎，梦寐不宁，怔忡惊悸，心虚胆怯，变生诸症。  \n半夏汤泡、枳实、竹茹各一两 陈皮一两五钱 茯苓七钱 炙甘草四钱  \n每服五钱，生姜七片，枣一枚，水一钟半，煎七分，食远温服。—方加人参、柏子仁为丸，朱砂为衣。", "白话": "〔主治〕治气郁生涎，梦寐不宁，怔忡惊悸，心虚胆怯，变生诸证。〔组成·照录〕半夏（汤泡）、枳实、竹茹各一两，陈皮一两五钱，茯苓七钱，炙甘草四钱。〔方义〕半夏、竹茹、枳实、陈皮理气化痰，茯苓、甘草健脾和中，为化痰安神之温胆汤。〔服法〕每服五钱，生姜七片、枣一枚，水一钟半煎至七分，食后稍远（食远）温服。一方加人参、柏子仁为丸，朱砂为衣。"}, {"source": "条572｜《慈幼新书》卷四·益元汤", "原文": "益元汤\n治小儿惊悸怔忡，化痰涎，利胸膈烦热，止嗽。\n《慈幼新书》卷四：益元汤。此为元气虚弱者立也，辨症果真，则前后皆不可易，中间杂症，虽或不同，要皆气虚致之，治者只于本方消息加减。  \n人参 黄芪 甘草 白术 陈皮 当归 川芎 升麻 桔梗 生姜  \n惊悸，加天麻、钩藤，磨安神丸。", "白话": "〔功效·主治〕治小儿惊悸怔忡，化痰涎，利胸膈烦热，止嗽。〔方论〕益元汤是为元气虚弱者立的方，辨证果真，则前后各步都不可更易；中间杂症虽或不同，要之皆由气虚所致，治者只于本方中斟酌加减。〔组成·照录〕人参、黄芪、甘草、白术、陈皮、当归、川芎、升麻、桔梗、生姜。〔方义〕参、芪、术、草补气，归、芎养血，陈皮、桔梗理气化痰，升麻升举清阳，为益气养血、化痰定悸之方。〔加减〕惊悸加天麻、钩藤，磨安神丸同服。"}, {"source": "条573｜《彤园医书（妇人科）》卷五·二陈汤", "原文": "二陈汤\n《彤园医书（妇人科）》卷五：二陈汤。主治产后呕吐痰饮，随症加减。\n去白陈皮 姜制半夏 白茯苓 甘草 生姜  \n风痰加胆星、白附、竹沥……惊悸怔忡，加石菖蒲、炒研益智。", "白话": "〔主治〕主治产后呕吐痰饮，随证加减。〔组成·照录〕去白陈皮、姜制半夏、白茯苓、甘草、生姜。〔方义〕二陈汤（陈皮、半夏、茯苓、甘草、生姜）化痰和胃止呕，为产后痰饮呕吐之基础方。〔加减〕风痰加胆南星、白附子、竹沥……（原稿节略）；惊悸怔忡加石菖蒲、益智仁（炒研）。"}, {"source": "条574｜《感症宝筏》卷二·温胆汤（加枣仁远志）", "原文": "温胆汤\n《感症宝筏》卷二：感证热退之后，夜不欲寐者，胃不和也，温胆汤和之。惊悸不宁者，心气虚也心气虚而神不敛，当安神以敛心阳，加枣仁、远志。", "白话": "〔主治·论治〕外感证热退之后，夜间不想睡的，是胃不和，用温胆汤调和之；惊悸不宁的，是心气虚——心气虚而神不内敛，当安神以敛心阳，加酸枣仁、远志。〔组成·服法〕温胆汤加酸枣仁、远志，水煎服。"}, {"source": "条575｜《类证治裁》卷四·导痰汤（加茯神人参菖蒲）", "原文": "导痰汤\n《类证治裁》卷四：凡怔忡惊恐健忘，癫狂失志不寐，皆由痰涎沃心，以致心气不足。若凉心之剂太过，则心火愈微，痰涎愈盛，唯以理痰顺气，养心安神，为第一义。导痰汤加茯神、人参、石菖蒲。", "白话": "〔主治·论治〕凡怔忡惊恐健忘、癫狂失志不寐，皆由痰涎浸渍于心，以致心气不足。若凉心之剂太过，则心火愈微、痰涎愈盛；唯以理痰顺气、养心安神为第一要义，用导痰汤加茯神、人参、石菖蒲。〔组成·服法〕导痰汤加茯神、人参、石菖蒲，水煎服。"}, {"source": "条576｜《医学衷中参西录·医方》·理痰汤", "原文": "理痰汤\n《医学衷中参西录·医方》：理痰汤。治痰涎郁塞胸膈，满闷短气。或渍于肺中为喘促咳逆。停于心下为惊悸不寐。", "白话": "〔主治〕治痰涎郁塞胸膈，满闷短气；或浸渍于肺中而成喘促咳逆；停于心下则为惊悸不寐。〔组成·服法〕原稿未载。〔方义〕理气化痰、降逆平喘，痰化则心下之惊悸自止（组成原稿未录，方义以主治推之）。"}, {"source": "条577｜《太医院秘藏膏丹丸散方剂》卷三·一捻金", "原文": "一捻金\n《太医院秘藏膏丹丸散方剂》卷三：一捻金。  \n黑丑一钱 白丑一钱 槟榔一钱 大黄一钱 朱砂五分 赤金一张  \n共为细末。专治小儿一切风痰壅塞，口吐涎沫，胸高肺胀，喘满气促，咳嗽面黄，两胁扇动，陷下作坑，癫痫发抽，急惊上视，鼻窍开张，精神烦乱，声哑不鸣，痰涎壅盛，夜卧惊悸，发渴潮热，肚腹膨胀，不思饮食等症。每服四五分，量大小用之，引蜂蜜少许，无根水调服。", "白话": "〔方名〕一捻金。〔组成·照录〕黑丑一钱、白丑一钱、槟榔一钱、大黄一钱、朱砂五分、赤金一张。〔方义〕黑白丑（牵牛子）、槟榔、大黄攻下逐痰消积，朱砂、赤金镇心安神，为小儿痰壅惊悸之峻药。〔主治〕专治小儿一切风痰壅塞：口吐涎沫，胸高肺胀，喘满气促，咳嗽面黄，两胁扇动、肋下陷下作坑，癫痫发搐，急惊上视，鼻窍开张，精神烦乱，声哑不鸣，痰涎壅盛，夜卧惊悸，发渴潮热，肚腹膨胀，不思饮食等症。〔服法〕共为细末，每服四五分，按小儿大小增减，以蜂蜜少许、无根水调服。"}, {"source": "条578｜《仁斋直指方论（附补遗）》卷九·牡蛎散", "原文": "牡蛎散\n《仁斋直指方论（附补遗）》卷九：牡蛎散。治诸虚体常自汗，惊惕不宁。　\n左顾牡蛎米泔浸洗，煅透、麻黄根、黄芪蜜炙，各一两  加白术半两  甘草炙，一分　 \n上锉，每服三五钱，小麦百余粒同煎服。", "白话": "〔主治〕治诸虚之体常自汗，惊惕不宁。〔组成·照录〕左顾牡蛎（米泔浸洗，煅透）、麻黄根、黄芪（蜜炙）各一两，加白术半两，甘草（炙）一分。〔方义〕牡蛎敛汗潜镇，麻黄根止汗，黄芪、白术、甘草益气固表，小麦养心，为益气固表、敛汗定惊之散。〔服法〕上药锉碎，每服三五钱，加小麦百余粒同煎服。"}, {"source": "条579｜《仁斋直指方论（附补遗）》卷十一·苏合香丸（调服法）", "原文": "《仁斋直指方论（附补遗）》卷十一：苏合香丸用枣汤调开，吞震灵丹，治心气不敛，怔忪头运。", "白话": "〔服法·主治〕苏合香丸用枣汤调开，送吞震灵丹，治心气不敛、怔忪头晕。〔组成·服法〕原稿未载组成，仅记调服法。〔方义〕苏合香丸芳香开窍、温通心气，配震灵丹镇摄，治心气不敛之怔忪。"}, {"source": "条580｜《御药院方》卷五·锦朱丸", "原文": "锦朱丸\n《御药院方》卷五：锦朱丸。治膈痰风厥，头目昏痛，眼黑旋晕，怔忪恶心，惊悸恍惚，梦寐不安，渐发冒昧，不知人事。 　 \n乳香研、朱砂研、白矾灰研、皂荚子炮裂，为末、铅白霜研、铁粉研，各一两 半夏曲二两 　 \n上为细末，生姜汁面糊和丸，如绿豆大。每服十五、二十丸，生姜汤下。惊悸语涩，金银汤下，或荆芥汤下。", "白话": "〔主治〕治膈痰风厥：头目昏痛，眼黑旋晕，怔忪恶心，惊悸恍惚，梦寐不安，渐渐昏冒，不知人事。〔组成·照录〕乳香（研）、朱砂（研）、白矾灰（研）、皂荚子（炮裂，为末）、铅白霜（研）、铁粉（研）各一两，半夏曲二两。〔方义〕乳香活血行气，朱砂、铁粉镇心安神，白矾灰、皂荚子、半夏曲化痰开闭，铅白霜劫痰，为镇心化痰、开闭醒神之丸。〔制法·服法〕上为细末，生姜汁面糊和丸如绿豆大，每服十五至二十丸，生姜汤下；惊悸语涩者用金银汤下，或荆芥汤下。"}, {"source": "条581｜《太医院秘藏膏丹丸散方剂》卷二·十香返魂丹", "原文": "十香返魂丹\n《太医院秘藏膏丹丸散方剂》卷二：十香返魂丹。\n伽南香、雄丁香、清木香、苏合油、檀香、降香、乳香、藿香、姜蚕炒，去丝嘴、天麻煨热、朱砂飞、郁金、建莲子心、栝蒌仁去净油、香附米童便、酒、醋、盐水，分为四次制、血珀以上各二两 安息香水，一两 麝香一两 礞石醋煅九次，二两 冰片五钱 诃子二两 牛黄一两 \n上各药俱研极细末，分量兑准，无有低昂。用甘草四两熬稠汁，对炼蜜为丸，每丸重一钱，金箔为衣…", "白话": "〔方名〕十香返魂丹。〔组成·照录〕伽南香、雄丁香、清木香、苏合油、檀香、降香、乳香、藿香、姜蚕（炒，去丝嘴）、天麻（煨热）、朱砂（飞）、郁金、建莲子心、栝蒌仁（去净油）、香附米（童便、酒、醋、盐水分为四次制）、血珀以上各二两，安息香水一两，麝香一两，礞石（醋煅九次）二两，冰片五钱，诃子二两，牛黄一两。〔方义〕诸香（伽南、丁香、木香、苏合、檀香、降香、乳香、藿香、安息香、麝香、冰片）芳香开窍醒神，朱砂、血珀、金箔重镇，天麻、姜蚕祛风，莲子心、郁金清心，牛黄豁痰，礞石坠痰，诃子敛"}, {"source": "条582｜《女科仙方》卷三·生化汤（加定志）", "原文": "生化汤\n《女科仙方》卷三：怔忡惊悸，生化汤加以定志。", "白话": "〔主治·加减〕产后怔忡惊悸，用生化汤加定志（安神定志之品）。〔组成·服法〕生化汤（当归、川芎、桃仁、炮姜、炙甘草类）加定志之药，水煎服（原稿未列组成）。〔方义〕生化汤化瘀生新，加定志之品安神，则瘀去神安而悸止。"}, {"source": "条583｜《胎产指南》卷七·生化汤", "原文": "生化汤\n《胎产指南》卷七：如分娩后，血块未消，宜服生化汤，补血行块，血旺则怔忡惊悸自平，不必加定安心神之剂。", "白话": "〔主治·论治〕如分娩之后血块未消，宜服生化汤，补血而行血块；血旺则怔忡惊悸自平，不必再加安定心神之剂。〔组成·服法〕生化汤，水煎服（原稿未列组成）。〔方义〕生化汤养血化瘀，瘀去血生，心血得养则悸自止，为“治病求本”之法。"}, {"source": "条584｜《济世全书·离集》·芎归调血饮", "原文": "芎归调血饮\n《济世全书·离集》：芎归调血饮主方。治产后诸病。\n当归身酒洗 川芎 白芍火煨，切片，酒炒熟用 怀生地黄酒蒸黑 白术去油芦，土炒 白茯苓去皮 陈皮 香附童便炒 甘草炒，初产临服，加童便一钟，好酒半钟同服，是能行瘀血，退热如神  \n上锉作剂，生姜一片，枣一枚，水煎温服。看病加减于后。一产后惊悸、怔忡，加远志、麦门冬、酸枣仁。", "白话": "〔主治〕芎归调血饮主方，治产后诸病。〔组成·照录〕当归身（酒洗）、川芎、白芍（火煨，切片，酒炒熟用）、怀生地黄（酒蒸黑）、白术（去油芦，土炒）、白茯苓（去皮）、陈皮、香附（童便炒）、甘草（炒）；初产临服时加童便一钟、好酒半钟同服，能行瘀血、退热如神。〔方义〕芎、归、芍、地养血和血，术、苓、草健脾，陈皮、香附理气，童便、好酒行瘀退热，为产后调血之主方。〔服法〕上药锉作剂，生姜一片、大枣一枚，水煎温服。〔加减〕看病加减于后：一、产后惊悸怔忡，加远志、麦门冬、酸枣仁。"}, {"source": "条585｜《胎产心法》卷下·加味生脉散", "原文": "加味生脉散\n《胎产心法》卷下：加味生脉散。治产后去血太多，心血虚弱不能上荣于舌，语言不清，含糊蹇涩。  \n人参、麦冬去心、归身、生地、炙草、石菖蒲各一钱 五味子十三粒，捶碎  \n獖猪心一个，劈开，水二盏，煎至一盏半，去心，入药煎七分，食后服。此方治怔忡甚效。", "白话": "〔主治〕治产后失血太多，心血虚弱不能上荣于舌，语言不清、含糊謇涩。〔组成·照录〕人参、麦冬（去心）、归身、生地、炙草、石菖蒲各一钱，五味子十三粒（捶碎）。〔方义〕生脉散（参、麦、味）益气养阴，加归身、生地养血，菖蒲开窍，猪心以心补心，为养心复脉、开窍利舌之方。〔服法〕獖猪（阉割公猪）心一个劈开，水二盏煎至一盏半，去猪心，入药再煎至七分，食后服。此方治怔忡甚效。"}, {"source": "条586｜《胎产心法》卷下·尊生升举大补汤", "原文": "尊生升举大补汤\n《胎产心法》卷下：尊生升举大补汤。治产后血块痛止崩证。  \n人参、当归、白术土炒，各二钱 川芎、麦冬去心、黄芪蜜炙，各一钱 熟地三钱、 陈皮、炙草、白芷、荆芥穗炒黑、升麻、血余灰各四分  \n枣二枚，水煎服。汗多，加麻黄根、浮麦。便难，加酒洗苁蓉一钱。痰，加去心贝母六分。咳嗽，加桔梗、去皮尖杏仁各一钱。不寐惊悸，加炒枣仁、柏子仁各一钱。本方少加黄连三分以坠火，亦妙。凡遇崩证，有如此等", "白话": "〔主治〕治产后血块痛止后之崩证。〔组成·照录〕人参、当归、白术（土炒）各二钱，川芎、麦冬（去心）、黄芪（蜜炙）各一钱，熟地三钱，陈皮、炙草、白芷、荆芥穗（炒黑）、升麻、血余灰各四分。〔方义〕参、芪、术、草补气，归、芎、熟地、麦冬养血，升麻、荆芥穗升举收摄，血余灰止血，陈皮、白芷理气和血，为升举气血、固摄止崩之大补方。〔服法〕大枣二枚，水煎服。〔加减〕汗多加麻黄根、浮小麦；大便难加酒洗肉苁蓉一钱；有痰加去心贝母六分；咳嗽加桔梗、去皮尖杏仁各一钱；不寐惊悸加炒酸枣仁、柏子仁各一钱"}, {"source": "条587｜《伤寒总病论》卷三·甘草附子汤", "原文": "《伤寒总病论》卷三：“风湿相搏，骨节疼烦，掣痛不得屈伸，近之则极，汗出短气，小便不利，恶风不欲去被，或有微肿者，甘草附子汤主之。 　 \n附子二枚  白术二两  桂枝三两  甘草二两 　 \n㕮咀，水三升，煮取一升，去滓，分温三服。身肿者加防己二两；悸气、小便不利加茯苓一两半，溢水成四升，煎一升三合。", "白话": "〔主治〕风湿相搏，骨节疼烦，掣痛不能屈伸，近之则痛甚，汗出短气，小便不利，恶风不欲去被，或有微肿的，用甘草附子汤主治。〔组成·照录〕附子二枚、白术二两、桂枝三两、甘草二两。〔方义〕附子温经助阳，桂枝祛风通阳，白术健脾祛湿，甘草调和，为温阳祛湿、通痹止痛之方；悸气加茯苓利水宁心。〔服法〕㕮咀，水三升煮取一升，去渣，分三次温服。〔加减〕身肿加防己二两；悸气、小便不利加茯苓一两半，加水成四升，煎取一升三合。"}, {"source": "条588｜《圣济总录》卷五·独活汤", "原文": "《圣济总录》卷五：“治风中五脏，奄忽不能言，四肢垂曳，皮肉癇痹，痛痒不知，独活汤方。  \n独活去芦头，三两  防风去叉、芎、白茯苓去黑皮、当归切焙、葛根、桂去粗皮，各二两  麻黄去根节，先洗、煎，掠去沫，焙，三两  附子炮裂，去皮脐、细辛去苗叶、甘草炙，各一两 \n上一十一，锉如麻豆，每服五钱匕，水一盏半，生姜五片。煎至八分，去滓空心，日午夜卧温服……心下惊悸，加茯苓去黑皮一两。若热，去生姜加葛根。", "白话": "〔主治〕治风中五脏，突然不能言语，四肢下垂拖曳，皮肉麻木痹痛，痛痒不知，用独活汤。〔组成·照录〕独活（去芦头）三两，防风（去叉）、芎、白茯苓（去黑皮）、当归（切，焙）、葛根、桂（去粗皮）各二两，麻黄（去根节，先洗、煎，掠去沫，焙）三两，附子（炮裂，去皮脐）、细辛（去苗叶）、甘草（炙）各一两。〔方义〕独活、防风、细辛、麻黄、葛根祛风通络，桂、附温经，芎、归活血，苓、草健脾，为祛风通络、温经活血之方。〔服法〕上十一味锉如麻豆，每服五钱匕，水一盏半加生姜五片煎至八分，去渣，空腹、日"}, {"source": "条589｜《圣济总录》卷一十九·茯神汤", "原文": "《圣济总录》卷一十九：“治心痹神思昏塞，四肢不利，胸中烦闷，时复恐悸，茯神汤方。 　 \n茯神去木、羌活去芦头、龙齿、麦门冬去心，焙、麻黄去根节，各一两  蔓荆实、人参、薏苡仁、防风去叉、远志去心、犀角屑各三分  赤芍药、甘草微炙，各半两　 \n上一十三味，粗捣筛。每服三钱匕，水一盏，生姜五片，同煎至七分，去滓温服，不计时候。", "白话": "〔主治〕治心痹神思昏塞，四肢不利，胸中烦闷，时复恐惧心悸。〔组成·照录〕茯神（去木）、羌活（去芦头）、龙齿、麦门冬（去心，焙）、麻黄（去根节）各一两，蔓荆实、人参、薏苡仁、防风（去叉）、远志（去心）、犀角屑各三分，赤芍药、甘草（微炙）各半两。〔方义〕茯神、远志、龙齿、麦冬、人参养心安神，羌活、防风、蔓荆、麻黄祛风通痹，犀角、赤芍清热凉血，薏苡仁、甘草健脾和中，为养心安神、祛风通痹之方。〔服法〕上十三味粗捣筛，每服三钱匕，水一盏加生姜五片同煎至七分，去渣温服，不拘时候。"}, {"source": "条590｜《圣济总录》卷三十一·人参茯神汤", "原文": "《圣济总录》卷三十一：“治伤寒后心虚惊悸，恍惚不宁，人参茯神汤方。 　 \n人参、茯神去木，各一两  陈橘皮汤浸，去白，焙，三分  杏仁汤浸，去皮尖，双仁，炒，一分 \n上四味，粗捣筛，每服三钱匕，水一盏，入生姜半分拍碎，同煎至半盏，去滓温服。", "白话": "〔主治〕治伤寒后心虚惊悸，恍惚不宁。〔组成·照录〕人参、茯神（去木）各一两，陈橘皮（汤浸，去白，焙）三分，杏仁（汤浸，去皮尖，双仁，炒）一分。〔方义〕人参补心气，茯神安神，陈皮理气，杏仁降气，为益气安神、理气和中之小方。〔服法〕上四味粗捣筛，每服三钱匕，水一盏加拍碎生姜半分同煎至半盏，去渣温服。"}, {"source": "条591｜《圣济总录》卷三十一·麦门冬汤", "原文": "《圣济总录》卷三十一：“治伤寒后心虚忪悸，麦门冬汤方。 　 \n麦门冬去心，焙、茯神去木、菊花、人参各一两  甘草炙，半两  \n上五味，粗捣筛，每服三钱匕，水一盏，煎至半盏，去滓温服。", "白话": "〔主治〕治伤寒后心虚忪悸。〔组成·照录〕麦门冬（去心，焙）、茯神（去木）、菊花、人参各一两，甘草（炙）半两。〔方义〕麦冬、人参益气养阴，茯神安神，菊花清余热，甘草和中，为养心定悸之方。〔服法〕上五味粗捣筛，每服三钱匕，水一盏煎至半盏，去渣温服。"}, {"source": "条592｜《圣济总录》卷三十一·前胡汤", "原文": "《圣济总录》卷三十一：“治伤寒后惊悸不定，前胡汤方。 　 \n前胡去芦头、茯神去木、人参各一两  远志去心，一两半  甘草炙，一分 \n上五味，粗捣筛每服二钱匕，水一盏，同煎至七分，去滓温服，不计时候。", "白话": "〔主治〕治伤寒后惊悸不定。〔组成·照录〕前胡（去芦头）、茯神（去木）、人参各一两，远志（去心）一两半，甘草（炙）一分。〔方义〕前胡清余热降气，茯神、远志、人参安神定志，炙甘草和中，为伤寒后养心定悸之方。〔服法〕上五味粗捣筛，每服二钱匕，水一盏同煎至七分，去渣温服，不拘时候。"}, {"source": "条593｜《圣济总录》卷三十一·茯神丸", "原文": "《圣济总录》卷三十一：“伤后治寒，或用心力劳倦，四肢羸弱，心忪惊悸，吸吸短气，补虚。茯神丸方。 　 \n茯神去木、麦门冬去心，焙  熟干地黄焙，各一两  牡丹皮、人参、黄芪锉，各三分  桂去粗皮、甘草炙、牛膝去苗、泽泻各半两\n上一十味，捣罗为末，炼蜜和捣三五百杵，丸如梧桐子大，食前温酒下二十丸。", "白话": "〔主治〕伤后治寒（伤寒之后），或用心力劳倦，四肢羸弱，心忪惊悸，吸吸短气，用以补虚。〔组成·照录〕茯神（去木）、麦门冬（去心，焙）、熟干地黄（焙）各一两，牡丹皮、人参、黄芪（锉）各三分，桂（去粗皮）、甘草（炙）、牛膝（去苗）、泽泻各半两。〔方义〕茯神、麦冬、熟地养心滋阴，参、芪、甘草补气，桂温阳，丹皮、牛膝活血，泽泻利湿，为益气养阴、补虚定悸之丸。〔服法〕上十味捣罗为末，炼蜜和捣三五百杵，丸如梧桐子大，食前温酒下二十丸。"}, {"source": "条594｜《圣济总录·卷第三十二》卷三十二·柴胡汤", "原文": "《圣济总录·卷第三十二》卷三十二：“治伤寒后虚劳，烦热惊悸，不得眠睡。柴胡汤方。 　 \n柴胡去苗，半两  酸枣仁微炒，二两  远志去心，一分  当归切，焙、防风去叉、甘草炙，锉、茯神去木、猪苓去黑皮、桂去粗皮、黄芪锉、人参、生干地黄、芎、麦门冬去心，焙，各半两　 \n上一十四味，粗捣筛，每服三钱匕，水一大盏，生姜三片，煎至七分去滓，空心温服日再。", "白话": "〔主治〕治伤寒后虚劳，烦热惊悸，不得睡眠。〔组成·照录〕柴胡（去苗）半两，酸枣仁（微炒）二两，远志（去心）一分，当归（切，焙）、防风（去叉）、甘草（炙，锉）、茯神（去木）、猪苓（去黑皮）、桂（去粗皮）、黄芪（锉）、人参、生干地黄、芎、麦门冬（去心，焙）各半两。〔方义〕柴胡清解余热，枣仁、远志、茯神养心安神，参、芪、归、地益气养血，桂、防风通阳，猪苓利湿，为清余热、养心神之方。〔服法〕上十四味粗捣筛，每服三钱匕，水一大盏加生姜三片煎至七分去渣，空腹温服，日两次。"}, {"source": "条595｜《圣济总录》卷四十三·茯神丸", "原文": "《圣济总录》卷四十三：“治心脏虚热，惊悸心忪，虚乏气短，睡卧不安。茯神丸方。  \n茯神去木，二两  人参、麦门冬去心，焙、龙齿、防风去叉、云母粉各一两半  犀角镑、黄芩去黑心、薏苡仁各二两 \n上九味，捣罗为末，炼蜜丸如绿豆大。每服食后，米饮下十五丸，至二十丸。", "白话": "〔主治〕治心脏虚热，惊悸心忪，虚乏气短，睡卧不安。〔组成·照录〕茯神（去木）二两，人参、麦门冬（去心，焙）、龙齿、防风（去叉）、云母粉各一两半，犀角（镑）、黄芩（去黑心）、薏苡仁各二两。〔方义〕茯神、麦冬、人参养心益气，龙齿、云母镇心，犀角、黄芩清心热，防风祛风，薏苡仁健脾，为清心镇惊、养心安神之丸。〔服法〕上九味捣罗为末，炼蜜丸如绿豆大，每于食后米饮下十五至二十丸。"}, {"source": "条596｜《圣济总录》卷四十三·镇心丸", "原文": "《圣济总录》卷四十三：“治心虚惊悸，或因忧虑，神气不安，镇心丸方。  \n茯神去木、人参、甘草炙，锉、龙齿各一两半  升麻、枳壳去瓤，麸炒，各一两\n银箔二百片  麦门冬去心，焙，二两  \n上八味，捣罗为末，炼蜜和丸，如梧桐子大。每服十五丸至二十丸，米饮下，早晚食后服。", "白话": "〔主治〕治心虚惊悸，或因忧虑而神气不安。〔组成·照录〕茯神（去木）、人参、甘草（炙，锉）、龙齿各一两半，升麻、枳壳（去瓤，麸炒）各一两，银箔二百片，麦门冬（去心，焙）二两。〔方义〕茯神、人参、麦冬养心安神，龙齿、银箔重镇，升麻升清，枳壳理气，甘草和中，为镇心安神之丸。〔服法〕上八味捣罗为末，炼蜜和丸如梧桐子大，每服十五至二十丸，米饮下，早晚食后服。"}, {"source": "条597｜《圣济总录》卷四十三·檀香丸", "原文": "《圣济总录》卷四十三：“治心常忪悸，恐惧多忘，檀香丸方。 　 \n檀香三两  菖蒲、犀角镑、天竺黄研、生干地黄焙、苏合香油各一两  桂去粗皮、 甘草炙、白茯苓去黑皮，各三两半  人参、远志去心、麦门冬去心，各一两半　 \n上一十二味。，除苏合香油外，为末，以苏合香油同少酒，化入炼蜜，丸如樱桃大。食后含化一丸。", "白话": "〔主治〕治心常忪悸，恐惧多忘。〔组成·照录〕檀香三两，菖蒲、犀角（镑）、天竺黄（研）、生干地黄（焙）、苏合香油各一两，桂（去粗皮）、甘草（炙）、白茯苓（去黑皮）各三两半，人参、远志（去心）、麦门冬（去心）各一两半。〔方义〕檀香、苏合香油芳香开窍，菖蒲、远志、茯神（苓）、人参安神益智，犀角、天竺黄清心化痰，地黄、麦冬滋阴，桂、甘草温中和药，为芳香开窍、养心定悸之丸。〔制法·服法〕上十二味（原稿作“上一十二味。”），除苏合香油外为末，以苏合香油同少量酒化入炼蜜，丸如樱桃大，食后含"}, {"source": "条598｜《圣济总录》卷四十三·乌犀汤", "原文": "《圣济总录》卷四十三：“治心脏烦热，睡即多惊，心忪不欲见人，乌犀汤方。 　 \n犀角镑，八钱  龙齿、升麻各一两  茯神去木，一两半  麦门冬去心，焙，二两玄参一两  栝蒌根锉，焙，三两  赤芍药一两半\n上八味，粗捣筛，每服三钱匕。水一盏，入马牙硝半钱匕，生地黄五七寸拍碎，同煎至七分，去滓温服。", "白话": "〔主治〕治心脏烦热，睡即多惊，心忪不欲见人。〔组成·照录〕犀角（镑）八钱，龙齿、升麻各一两，茯神（去木）一两半，麦门冬（去心，焙）二两，玄参一两，栝蒌根（锉，焙）三两，赤芍药一两半。〔方义〕犀角、玄参、赤芍、栝蒌根清心凉血滋阴，龙齿镇惊，茯神、麦冬养心，升麻升散郁火，为清心除烦、镇惊定悸之汤。〔服法〕上八味粗捣筛，每服三钱匕，水一盏加马牙硝半钱匕、拍碎生地黄五七寸同煎至七分，去渣温服。"}, {"source": "条599｜《圣济总录》卷五十八·麦门冬丸", "原文": "《圣济总录》卷五十八：“治消渴，口干喜饮水，小便数。心烦闷、健忘怔忪，麦门冬丸方。 　 \n麦门冬去心，焙、土瓜根锉、山茱萸、鹿茸酒浸，炙，去毛、牛膝去苗，锉、狗脊碎，锉，去毛、茯神去木、人参各一两  黄连去须、菟丝子酒浸一宿，曝干，别捣为末，各一两半  龙骨烧、牡蛎煅，各三分　 \n上一十二味，捣罗为末，炼蜜丸如梧桐子大，每服二十丸，不拘时、煮小麦饮下。加至三十丸。", "白话": "〔主治〕治消渴，口干喜饮水，小便数，心烦闷、健忘怔忪。〔组成·照录〕麦门冬（去心，焙）、土瓜根（锉）、山茱萸、鹿茸（酒浸，炙，去毛）、牛膝（去苗，锉）、狗脊（碎，锉，去毛）、茯神（去木）、人参各一两，黄连（去须）、菟丝子（酒浸一宿，曝干，别捣为末）各一两半，龙骨（烧）、牡蛎（煅）各三分。〔方义〕麦冬、土瓜根、黄连清热生津，参、苓、山茱萸、鹿茸、菟丝子、狗脊、牛膝补肾益精，龙骨、牡蛎固涩潜镇，为治消渴心烦、补肾定悸之丸。〔服法〕上十二味捣罗为末，炼蜜丸如梧桐子大，每服二十丸，不"}, {"source": "条600｜《圣济总录》卷七十三·白术丸", "原文": "《圣济总录》卷七十三：“治冷癖气因服热药发热。心惊虚悸，下冷上热，头风呕逆，白术丸方。 　 \n白术、陈橘皮去白，焙，各一两半  白芷三分   防风去叉、吴茱萸汤洗七遍，焙干、芎、山芋、厚朴去粗皮，涂生汁，炙熟、桂去粗皮、大麦锉，炒、干姜炮、防葵锉，各一两  甘草炙，锉、茯神去木、人参各一两一分　 \n上一十五味，捣罗为末，炼蜜和丸，如梧桐子大，每日空心温酒下二十丸。", "白话": "〔主治〕治冷癖气因服热药而发热，心惊虚悸，下冷上热，头风呕逆。〔组成·照录〕白术、陈橘皮（去白，焙）各一两半，白芷三分，防风（去叉）、吴茱萸（汤洗七遍，焙干）、芎、山芋、厚朴（去粗皮，涂生姜汁，炙熟）、桂（去粗皮）、大麦（锉，炒）、干姜（炮）、防葵（锉）各一两，甘草（炙，锉）、茯神（去木）、人参各一两一分。〔方义〕白术、干姜、吴茱萸、桂温中散寒，陈皮、厚朴理气，防风、白芷、防葵祛风，芎活血，参、苓、草益气，山芋补脾，大麦和中，为温中健脾、散寒定悸之丸。〔服法〕上十五味捣罗为末"}, {"source": "条601｜《圣济总录》卷八十六·补心麦门冬丸", "原文": "《圣济总录》卷八十六：“治心劳多惊悸，心气不足，补心麦门冬丸方。 　 \n麦门冬去心，焙，一两半  石菖蒲一两  远志去心，一两半  人参一两  白茯苓去黑皮，一两  熟干地黄一两半  桂去粗皮，半两  天门冬心去，焙，一两半  黄连去须，一两半  升麻一两半　 \n上一十味，捣罗为末，炼蜜为丸，如梧桐子大，每日食后夜卧时，用熟水下二十丸，兼开心气，使人多记不忘。", "白话": "〔主治〕治心劳多惊悸，心气不足。〔组成·照录〕麦门冬（去心，焙）一两半，石菖蒲一两，远志（去心）一两半，人参一两，白茯苓（去黑皮）一两，熟干地黄一两半，桂（去粗皮）半两，天门冬（心去，焙）一两半，黄连（去须）一两半，升麻一两半。〔方义〕二冬、地黄滋阴，参、苓、桂益气温阳，菖蒲、远志安神益智，黄连清心，升麻升清，为补心气、养心阴、益智不忘之丸。〔服法〕上十味捣罗为末，炼蜜为丸如梧桐子大，每日食后及夜卧时用熟水下二十丸；兼能开心气，使人多记不忘。"}, {"source": "条602｜《圣济总录》卷八十六·肉苁蓉丸", "原文": "《圣济总录》卷八十六：“治肾劳心忪乏力，夜多梦泄，肌瘦发热，口内生疮，脐腹冷痛，肉苁蓉丸方。 　 \n肉苁蓉酒浸，切，焙，一两、巴戟天去心、石槲去根，各半两  牛膝酒浸、切焙、附子炮裂，去皮脐、羌活去芦头，各一两  桔梗炒、远志去心、萆薢、独活去芦头、枳壳去瓤麸炒、黄芪锉，各半两  熟干地黄焙、当归切，焙，各一两 海桐皮锉，一分　 \n上一十五味，捣罗为末，炼蜜和丸，如梧桐子大，每服二十丸，米饮或温酒", "白话": "〔主治〕治肾劳心忪乏力，夜间多梦遗泄，肌肉消瘦发热，口内生疮，脐腹冷痛。〔组成·照录〕肉苁蓉（酒浸，切，焙）一两，巴戟天（去心）、石槲（去根）各半两，牛膝（酒浸，切，焙）、附子（炮裂，去皮脐）、羌活（去芦头）各一两，桔梗（炒）、远志（去心）、萆薢、独活（去芦头）、枳壳（去瓤，麸炒）、黄芪（锉）各半两，熟干地黄（焙）、当归（切，焙）各一两，海桐皮（锉）一分。〔方义〕苁蓉、巴戟、石斛、牛膝、地黄、当归补肾养血，附子温阳，黄芪益气，远志安神，羌活、独活、萆薢、海桐皮祛风湿，桔梗、枳"}, {"source": "条603｜《圣济总录》卷八十七·鳖甲饮", "原文": "《圣济总录》卷八十七：“治急劳肌瘦壮热，心忪战掉，鳖甲饮方。 　 \n鳖甲去裙襕襴醋炙，半分  豉去皮，一分  甘草量病人中指长用  青蒿干者一握  桃仁七粒，汤浸去皮尖双仁生研  葱并须三茎，切　 \n上六味细锉，每服五钱匕，以童子小便二盏，煎至一盏，去滓空心温服，避风取汗。", "白话": "〔主治〕治急劳肌肉消瘦、高热，心忪战抖。〔组成·照录〕鳖甲（去裙襕，醋炙）半分，豉（去皮）一分，甘草（用量以病人中指长度为准），青蒿（干者）一握，桃仁七粒（汤浸去皮尖双仁，生研），葱连须三茎（切）。〔方义〕鳖甲、青蒿、豆豉清虚热，桃仁活血，葱、甘草通阳和中，为清虚热、除骨蒸之饮。〔服法〕上六味细锉，每服五钱匕，以童子小便二盏煎至一盏，去渣空腹温服，避风取汗。"}, {"source": "条604｜《圣济总录》卷八十七·黄芪汤", "原文": "《圣济总录》卷八十七：“治热劳、肢节酸疼，吸吸少气，腰背强痛，心中虚悸，咽干唇赤，面色枯燥，饮食无味，悲忧惨戚，多睡少起，黄芪汤方。 　 \n黄芪锉，焙、 地骨皮各一两  鳖甲一枚，去裙襴涂醋炙黄  甘草半两，炙，锉  麦门冬去心，焙，一两半  桂去粗皮，半两　 \n上六味，粗捣筛，每服五钱匕，水一盏半，生姜半分拍破，粳米五十粒，煎至八分，去滓食前温服。", "白话": "〔主治〕治热劳：肢节酸疼，呼吸短气，腰背强痛，心中虚悸，咽干唇赤，面色枯燥，饮食无味，悲忧惨戚，多睡少起。〔组成·照录〕黄芪（锉，焙）、地骨皮各一两，鳖甲一枚（去裙襕，涂醋炙黄），甘草半两（炙，锉），麦门冬（去心，焙）一两半，桂（去粗皮）半两。〔方义〕黄芪、甘草益气，麦冬、地骨皮、鳖甲滋阴清虚热，桂通阳，为益气养阴、清热定悸之汤。〔服法〕上六味粗捣筛，每服五钱匕，水一盏半加拍破生姜半分、粳米五十粒煎至八分，去渣食前温服。"}, {"source": "条605｜《圣济总录》卷八十八·胡黄连汤", "原文": "《圣济总录》卷八十八：“治虚劳寒热心忪，骨节酸疼，胡黄连汤方。 　 \n胡黄连、柴胡去苗、鳖甲去裙襕襴醋炙、甘草炙锉、白蒺藜炒、黄芪、附子炮裂去皮脐，各半两  威灵仙去土，一两　\n上八味，锉如麻豆，每服三钱匕，水一盏，童子小便酒共半盏，乌梅一枚拍碎，同煎至一盏，去滓不拘时候温服。", "白话": "〔主治〕治虚劳寒热心忪，骨节酸疼。〔组成·照录〕胡黄连、柴胡（去苗）、鳖甲（去裙襕，醋炙）、甘草（炙，锉）、白蒺藜（炒）、黄芪、附子（炮裂，去皮脐）各半两，威灵仙（去土）一两。〔方义〕胡黄连、柴胡、鳖甲清虚热，黄芪、甘草益气，附子温阳，白蒺藜、威灵仙祛风通络，为清补兼施、除蒸定悸之汤。〔服法〕上八味锉如麻豆，每服三钱匕，水一盏加童便与酒共半盏、拍碎乌梅一枚同煎至一盏，去渣不拘时候温服。"}, {"source": "条606｜《圣济总录》卷九十·补心麦门冬丸", "原文": "《圣济总录》卷九十：“治虚劳惊悸，心气不足，补心麦门冬丸方。 　 \n麦门冬去心，焙，一两半  菖蒲石上者、远志去心、人参、白茯苓去黑皮，各一两  熟干地黄焙，一两半  桂去粗皮，半两  天门冬去心，焙、黄连去须、升麻各一两　 \n上一十味，捣罗为末，炼蜜为丸，如梧桐子大。每服早食后及夜卧时，用熟水下二十丸。", "白话": "〔主治〕治虚劳惊悸，心气不足。〔组成·照录〕麦门冬（去心，焙）一两半，菖蒲（石上者）、远志（去心）、人参、白茯苓（去黑皮）各一两，熟干地黄（焙）一两半，桂（去粗皮）半两，天门冬（去心，焙）、黄连（去须）、升麻各一两。〔方义〕二冬、地黄滋阴，参、苓、桂益气温阳，菖蒲、远志安神，黄连清心，升麻升清，为补心定悸之丸。〔服法〕上十味捣罗为末，炼蜜为丸如梧桐子大，每于早食后及夜卧时用熟水下二十丸。"}, {"source": "条607｜《圣济总录》卷九十·柴胡汤", "原文": "《圣济总录》卷九十：“治虚劳羸瘦，心虚惊悸，气乏力劣等，柴胡汤方。 　 \n柴胡去苗，三分  黄芪锉，一两  厚朴去粗皮，涂生姜汁，炙  半夏汤洗去滑焙干，各三分  人参、 白茯苓去黑皮、 防风去叉、 细辛去苗叶，各半两  当归切，焙、 麦门冬去心，焙，各二两  陈橘皮汤浸，去白，焙、甘草炙，焙、杏仁汤浸去皮尖，双仁，别研、槟榔各半两　 \n上一十四味，粗捣筛。每服五钱匕，水一盏半，入生姜一分切碎，煎", "白话": "〔主治〕治虚劳羸瘦，心虚惊悸，气乏力弱等。〔组成·照录〕柴胡（去苗）三分，黄芪（锉）一两，厚朴（去粗皮，涂生姜汁，炙）、半夏（汤洗去滑，焙干）各三分，人参、白茯苓（去黑皮）、防风（去叉）、细辛（去苗叶）各半两，当归（切，焙）、麦门冬（去心，焙）各二两，陈橘皮（汤浸，去白，焙）、甘草（炙，焙）、杏仁（汤浸，去皮尖，双仁，别研）、槟榔各半两。〔方义〕柴胡、防风、细辛疏散，参、芪、苓、草益气，归、麦养血滋阴，陈皮、厚朴、槟榔、半夏、杏仁理气化痰降逆，为益气养血、理气定悸之汤。〔服法"}, {"source": "条608｜《圣济总录》卷九十一·枸杞汤", "原文": "《圣济总录》卷九十一：“治虚劳骨肉酸疼，吸吸少气，少腹拘急，腰背强痛，心中虚悸，咽干唇燥，面无颜色，饮食无味，阴阳废弱，悲忧惨戚，多卧少起，枸杞汤方。 　 \n枸杞根锉、黄芪锉，各三分  甘草炙，锉、麦门冬去心，焙、桂去粗皮，各半两）　 \n上五味，粗捣筛，每服五钱匕，水一盏半，生姜一枣大切，粳米一匙，煎至一盏，去滓温服，空心夜卧各一。", "白话": "〔主治〕治虚劳骨肉酸疼，呼吸短气，少腹拘急，腰背强痛，心中虚悸，咽干唇燥，面无颜色，饮食无味，阴阳俱虚衰，悲忧惨戚，多卧少起。〔组成·照录〕枸杞根（锉）、黄芪（锉）各三分，甘草（炙，锉）、麦门冬（去心，焙）、桂（去粗皮）各半两。〔方义〕枸杞根（地骨皮）清虚热，麦冬滋阴，黄芪、甘草益气，桂通阳，为益气养阴、清热定悸之汤。〔服法〕上五味粗捣筛，每服五钱匕，水一盏半加枣大生姜一片、粳米一匙煎至一盏，去渣温服，空腹、夜卧各一次。"}, {"source": "条609｜《圣济总录》卷九十一·黄芪汤", "原文": "《圣济总录》卷九十一：“治大虚不足，小腹里急，气上冲胸，口舌干燥，短气烦悸，言语谬误，不能饮食，吸吸少气，黄芪汤方。 　 \n黄芪锉，三两  半夏汤洗去滑，姜汁制，五两  甘草炙，锉、人参、芍药各二两  桂去粗皮，一两　 \n上六味，粗捣筛，每服三钱匕，水一盏，生姜半分切，枣二枚劈破，煎至七分，去滓温服，空心日午夜卧各一，手足寒加附子，炮去皮脐一两。", "白话": "〔主治〕治大虚不足，小腹里急，气上冲胸，口舌干燥，短气烦悸，言语谬误，不能饮食，呼吸短气。〔组成·照录〕黄芪（锉）三两，半夏（汤洗去滑，姜汁制）五两，甘草（炙，锉）、人参、芍药各二两，桂（去粗皮）一两。〔方义〕黄芪、人参、甘草大补元气，桂、芍调和营卫，半夏降逆化痰，为补虚降逆、定悸除烦之汤。〔服法〕上六味粗捣筛，每服三钱匕，水一盏加切生姜半分、劈破枣二枚煎至七分，去渣温服，空腹、日午、夜卧各一次。〔加减〕手足寒冷加附子（炮，去皮脐）一两。"}, {"source": "条610｜《圣济总录》卷九十三·麦门冬汤", "原文": "《圣济总录》卷九十三：“治心中烦热，唯欲露体，复之即闷烦，惊悸心忪，面无颜色，忘前失后，妇人患血风气者，多成此疾，乃心蒸之状，麦门冬汤方。 　 \n麦门冬去心，焙、茯神去木、防风去叉、地骨皮去土，各三两  人参、龙齿、远志去心、甘草炙黄、羚羊角屑、石膏各二两  紫石英一两　\n上一十一味，各锉如麻豆大，每服三钱匕，以水一盏半，入枣两枚，煎取半盏，去滓温服，服一剂，未全安再作之，以瘥为度，甚益心力，曾经", "白话": "〔主治〕治心中烦热，只想袒露身体，覆盖即闷烦，惊悸心忪，面无颜色，忘前失后；妇人患血风之气者多成此疾，即“心蒸”之状。〔组成·照录〕麦门冬（去心，焙）、茯神（去木）、防风（去叉）、地骨皮（去土）各三两，人参、龙齿、远志（去心）、甘草（炙黄）、羚羊角屑、石膏各二两，紫石英一两。〔方义〕麦冬、地骨皮、石膏滋阴清热，茯神、远志、龙齿、紫石英安神定悸，人参、甘草益气，防风祛风，羚羊角清心镇惊，为清心除蒸、安神定悸之汤。〔服法〕上十一味各锉如麻豆大，每服三钱匕，水一盏半加枣两枚煎取半盏"}, {"source": "条611｜《圣济总录》卷一百五十·三黄汤", "原文": "《圣济总录》卷一百五十：“治妇人中风，手足拘挛，百节疼痛，烦热闷乱，不欲饮食，三黄汤方。\n麻黄去节煎，掠去沫，焙，一两一分  独活去芦头，一两  细辛去苗叶，一分  黄芪锉，半两  黄芩去黑心，三分　 \n上五味，粗捣筛，每服五钱匕，水一盏半，煎取一盏，去滓温服，心躁加大黄半两锉炒，腹满加枳实一枚去瓤麸炒，气虚加人参三分，惊悸加牡蛎粉三分熬，渴加栝蒌根三分锉，先有寒加附子一枚，炮裂去皮脐。", "白话": "〔主治〕治妇人中风，手足拘挛，百节疼痛，烦热闷乱，不欲饮食。〔组成·照录〕麻黄（去节，煎，掠去沫，焙）一两一分，独活（去芦头）一两，细辛（去苗叶）一分，黄芪（锉）半两，黄芩（去黑心）三分。〔方义〕麻黄、独活、细辛祛风散邪，黄芪益气固表，黄芩清热，为祛风通络、益气清热之汤。〔服法〕上五味粗捣筛，每服五钱匕，水一盏半煎取一盏，去渣温服。〔加减〕心躁加大黄半两（锉，炒）；腹满加枳实一枚（去瓤，麸炒）；气虚加人参三分；惊悸加牡蛎粉三分（熬）；口渴加栝蒌根三分（锉）；先有寒加附子一枚（"}, {"source": "条612｜《圣济总录》卷一百五十·蓬香散", "原文": "《圣济总录》卷一百五十：“治妇人血风，每至天阴，即先头旋眼睛痛，头目昏，躁闷怔忪，手足热疼，吃食减少，经候不匀，有时腹痛，或多便利，蓬香散方。 　 \n蓬莪术煨锉、京三棱煨锉、荆芥穗、沉香锉、厚朴去粗皮，生姜汁炙、桂去粗皮、 乌药、当归切，焙、延胡索、天麻、附子炮裂，去皮脐，各一两　 \n上一十一味，捣罗为末，每服二钱匕，生姜自然汁少许，和温酒调下，日三。", "白话": "〔主治〕治妇人血风：每当天阴即先头旋眼痛，头目昏，躁闷怔忪，手足热疼，饮食减少，经候不调，有时腹痛，或大便泄利。〔组成·照录〕蓬莪术（煨，锉）、京三棱（煨，锉）、荆芥穗、沉香（锉）、厚朴（去粗皮，生姜汁炙）、桂（去粗皮）、乌药、当归（切，焙）、延胡索、天麻、附子（炮裂，去皮脐）各一两。〔方义〕三棱、莪术、延胡索、当归活血行滞，沉香、乌药、厚朴理气，桂、附温经，荆芥、天麻祛风，为活血理气、祛风定悸之散。〔服法〕上十一味捣罗为末，每服二钱匕，用生姜自然汁少许和温酒调下，一日三次。"}, {"source": "条613｜《圣济总录》卷一百六十三·麦门冬汤", "原文": "《圣济总录》卷一百六十三：“治产后心虚惊悸，恍惚不安。麦门冬汤方。 　 \n麦门冬去心，焙，半两  熟干地黄焙，一两  白茯苓去黑皮、甘草炙，锉，各一两  芍药锉，一两　 \n上五味，粗捣筛，每服三钱匕，水一盏，入生姜五片，枣一枚擘破，煎至七分，去滓温服，不拘时候。", "白话": "〔主治〕治产后心虚惊悸，恍惚不安。〔组成·照录〕麦门冬（去心，焙）半两，熟干地黄（焙）一两，白茯苓（去黑皮）、甘草（炙，锉）各一两，芍药（锉）一两。〔方义〕麦冬、熟地滋阴养血，茯苓、甘草健脾安神，芍药和血敛阴，为养血安神、定悸之汤。〔服法〕上五味粗捣筛，每服三钱匕，水一盏加生姜五片、擘破枣一枚煎至七分，去渣温服，不拘时候。"}, {"source": "条614｜《圣济总录》卷一百六十四·茯苓汤", "原文": "《圣济总录》卷一百六十四：“治产后虚汗不止，心悸恍惚，怵惕多惊，茯苓汤方。 　 \n白茯苓去黑皮，一两半  甘草炙黄，一两  芍药锉，炒，一两  桂去粗皮，一两  当归切，炒，一两  麦门冬去心，焙，一两  黄芪一两半，锉　 \n上七味，粗捣筛，每服五钱匕，水一盏半，入生姜半分切，枣二枚擘，煎至八分。去滓温服，不拘时。", "白话": "〔主治〕治产后虚汗不止，心悸恍惚，怵惕多惊。〔组成·照录〕白茯苓（去黑皮）一两半，甘草（炙黄）一两，芍药（锉，炒）一两，桂（去粗皮）一两，当归（切，炒）一两，麦门冬（去心，焙）一两，黄芪一两半（锉）。〔方义〕黄芪、甘草益气固表止汗，归、芍、麦冬养血滋阴，茯苓安神，桂通阳和营，为益气固表、养血安神之汤。〔服法〕上七味粗捣筛，每服五钱匕，水一盏半加切生姜半分、擘枣二枚煎至八分，去渣温服，不拘时。"}, {"source": "条615｜《圣济总录》卷一百六十八·天南星丸", "原文": "《圣济总录》卷一百六十八：“治小儿挟夹热，痰盛温壮，夜卧不稳，天南星丸方。 　 \n天南星炮为末、半夏汤洗七遍，焙为末、腻粉研、滑石研，各一钱、巴豆二十四枚，去心膜，以水浸一宿，研细不出油　\n上五味，先研巴豆令熟，次下众药末，以糯米粥和丸，如绿豆大，每服三丸，更量儿大小加减，泻痢米饮下，取食葱汤下，惊悸薄荷荆芥汤下。", "白话": "〔主治〕治小儿夹热，痰盛温热高壮，夜卧不稳。〔组成·照录〕天南星（炮，为末）、半夏（汤洗七遍，焙，为末）、腻粉（研）、滑石（研）各一钱，巴豆二十四枚（去心膜，以水浸一宿，研细不出油）。〔方义〕南星、半夏化痰，腻粉（轻粉）劫痰，滑石清热利湿，巴豆攻下痰积，为小儿攻痰之峻丸。〔服法〕上五味先研巴豆令熟，次下众药末，以糯米粥和丸如绿豆大，每服三丸，按儿大小加减；泻痢以米饮下，取食（消食）以葱汤下，惊悸以薄荷荆芥汤下。"}, {"source": "条616｜《圣济总录》卷一百七十·茯神汤", "原文": "《圣济总录》卷一百七十：“治小儿风热惊掣，心忪恐悸，茯神汤方。 　 \n茯神去木，一分  龙齿半两  寒水石研，一分  升麻三分  石膏研，一两  麦门冬去心，焙，三分　 \n上六味，粗捣筛，一二岁儿，每服一钱匕，水七分，入竹沥少许，煎至四分，去滓温服，日三夜一，量儿大小，以意加减。", "白话": "〔主治〕治小儿风热惊掣，心忪恐惧心悸。〔组成·照录〕茯神（去木）一分，龙齿半两，寒水石（研）一分，升麻三分，石膏（研）一两，麦门冬（去心，焙）三分。〔方义〕茯神、龙齿安神镇惊，石膏、寒水石清热，升麻散风热，麦冬养阴，为小儿清热镇惊之汤。〔服法〕上六味粗捣筛，一二岁儿每服一钱匕，水七分加竹沥少许煎至四分，去渣温服，日三夜一，按儿大小加减。"}, {"source": "条617｜《圣济总录》卷一百七十二·退疳丸", "原文": "《圣济总录》卷一百七十二：“治小儿惊疳，心忪惊悸。面黄肌瘦，口舌生疮，多困目涩，退疳丸方。 　 \n胡黄连、黄连去须、大黄各半钱、陈橘皮汤浸，去白焙、苦楝根各一分，五味同为末，用猪胆汁和药却入胆内线缝定，水二碗煮水尽取药出  青黛研、使君子去壳、丹砂研、芦荟研，各一分  麝香研，半钱　 \n上一十味，将后五味别研为末，用前猪胆内药和匀为丸，如绿豆大，每服十丸，米饮下。不拘时候，量儿大小加减。", "白话": "〔主治〕治小儿惊疳：心忪惊悸，面黄肌瘦，口舌生疮，多困倦、目涩。〔组成·照录〕胡黄连、黄连（去须）、大黄各半钱，陈橘皮（汤浸，去白，焙）、苦楝根各一分——五味同为末，用猪胆汁和药，再装入猪胆内以线缝定，水二碗煮至水尽取出药；青黛（研）、使君子（去壳）、丹砂（研）、芦荟（研）各一分，麝香（研）半钱。〔方义〕胡黄连、黄连、大黄、青黛清热，使君子、苦楝根、芦荟杀虫消疳，陈皮理气，丹砂、麝香镇心开窍，为清热消疳、镇惊之丸。〔制法·服法〕上十味，将后五味别研为末，与前猪胆内药和匀为丸如"}, {"source": "条618｜《圣济总录》卷一百八十五·清心丸", "原文": "《圣济总录》卷一百八十五：“治热盛梦泄，怔忪恍惚，膈壅舌干，清心丸方。\n黄柏去粗皮，锉，一两　 \n上一味，捣罗为末，入龙脑一钱匕同研匀。炼蜜和丸如梧桐子大，每服十丸至十五丸，浓煎麦门冬汤下。", "白话": "〔主治〕治热盛梦泄，怔忪恍惚，胸膈壅滞、舌干。〔组成·照录〕黄柏（去粗皮，锉）一两。〔方义〕黄柏清下焦之热，龙脑（冰片）清心开窍，为清心止泄之丸。〔制法·服法〕上一味捣罗为末，入龙脑一钱匕同研匀，炼蜜和丸如梧桐子大，每服十丸至十五丸，浓煎麦门冬汤下。"}, {"source": "条619｜《圣济总录》卷一百八十八·大枣粥", "原文": "《圣济总录》卷一百八十八：“治中风，惊恐虚悸，如人将捕之，四肢沉重，补益，大枣粥方。 　 \n大枣七枚，去核  青粱粟米二合　 \n上二味，以水三升半，先煮枣取一升半，去滓投米，煮粥食之。", "白话": "〔主治〕治中风后惊恐虚悸，如人将捕之状，四肢沉重，用以补益。〔组成·照录〕大枣七枚（去核），青粱粟米二合。〔方义〕大枣补脾养心，粟米和中益虚，为食补养心之粥。〔制法·服法〕上二味以水三升半，先煮枣取一升半，去渣后下米，煮粥食之。"}, {"source": "条620｜《圣济总录》卷一百九十·脯鸡糁", "原文": "《圣济总录》卷一百九十：“治产后心虚忪悸，遍身疼痛，脯鸡糁方。\n黄雌鸡一只，去毛头足肠胃净洗，以小麦两合、以水五升煮鸡半熟即取出鸡去骨  蜀椒去目并闭口炒汗出取末，一钱  柴胡去苗，二钱  干姜末半钱  粳米三合　 \n上五味，先取水再煮鸡及米令烂，入葱薤椒姜柴胡末等，次又入五味盐酱，煮取熟，任意食之。", "白话": "〔主治〕治产后心虚忪悸，遍身疼痛。〔组成·照录〕黄雌鸡一只（去毛、头、足、肠胃，净洗，以小麦两合、水五升煮至半熟，取出鸡去骨）；蜀椒（去目及闭口者，炒至汗出取末）一钱，柴胡（去苗）二钱，干姜末半钱，粳米三合。〔方义〕黄雌鸡、粳米、小麦补虚养心，椒、姜温中，柴胡疏达，葱薤通阳，为食补温养之糁。〔制法·服法〕上五味，先取水再煮鸡及米令烂，入葱、薤、椒、姜、柴胡末等，再入五味、盐、酱，煮熟任意食之。"}, {"source": "条621｜《幼幼新书》卷八·茯神散", "原文": "《幼幼新书》卷八：“《圣惠》治小儿心惊悸、烦乱，茯神散方。 　 \n茯神、川升麻各三分  龙齿、甘草炙微赤，锉，各半两  寒水石、石膏、麦门冬去心焙，各一两　 \n上件药捣，粗罗为散。每服一钱，以水一小盏，煎至五分，去滓，入竹沥半合，更煎二沸。量儿大小，以意加减。", "白话": "〔出处·主治〕《幼幼新书》引《圣惠》（《太平圣惠方》）治小儿心惊悸、烦乱，茯神散方。〔组成·照录〕茯神、川升麻各三分，龙齿、甘草（炙微赤，锉）各半两，寒水石、石膏、麦门冬（去心，焙）各一两。〔方义〕茯神、龙齿安神镇惊，石膏、寒水石清热，升麻散火，麦冬养阴，甘草和中，为小儿清热镇惊之散。〔服法〕上药捣，粗罗为散，每服一钱，以水一小盏煎至五分，去渣，入竹沥半合再煎二沸，按儿大小加减。"}, {"source": "条622｜《幼幼新书》卷十三·生姜汤", "原文": "《幼幼新书》卷十三：“《婴孺》治少小中风，脉浮发热，汗不出头，鼻鸣干呕，生姜汤方。 　 \n生姜、甘草炙、芍药各一两  桂心三两  枣十个，去核　 \n上以水三升，煮取一升，为三服。自汗出者，加附子一个小者；如渴，去桂枝，加栝蒌半两；痢作去芍药、加干姜三分、附子小者一个炮；心下悸去芍药加茯苓三两；表虚里实，去桂加胶饴二两。", "白话": "〔出处·主治〕《幼幼新书》引《婴孺》治少小中风，脉浮发热，汗不出（头面无汗），鼻鸣干呕，生姜汤方。〔组成·照录〕生姜、甘草（炙）、芍药各一两，桂心三两，大枣十个（去核）。〔方义〕桂心、生姜解肌散寒，芍药和营，甘草、大枣和中，为小儿解表和营之汤。〔服法〕以水三升煮取一升，分三次服。〔加减〕自汗出者加小个附子一枚；口渴去桂枝加栝蒌半两；下痢发作去芍药，加干姜三分、小个附子一枚（炮）；心下悸去芍药加茯苓三两；表虚里实者去桂加胶饴（饴糖）二两。"}, {"source": "条623｜《幼幼新书》卷十五·仲景四逆散", "原文": "《幼幼新书》卷十五：“《活人书》仲景四逆散  \n甘草炙、枳实去白瓤，炒黄、柴胡、芍药以上各一两  \n咳者加五味子、干姜各半两。下利悸者，加桂半两。小便不利者，加茯苓半两。腹中痛者，加附子半枚，炮裂。泄利下重，先浓煎薤白汤，内药末三钱匕，再煮一二沸，温服。上捣筛为细散。米饮下二钱，日三服。", "白话": "〔出处·组成·照录〕《幼幼新书》引《活人书》仲景四逆散：甘草（炙）、枳实（去白瓤，炒黄）、柴胡、芍药以上各一两。〔方义〕四逆散疏肝理脾、透解郁热，改汤为散。〔服法〕上药捣筛为细散，米饮下二钱，一日三次。〔加减〕咳嗽加五味子、干姜各半两；下利而悸加桂半两；小便不利加茯苓半两；腹中痛加附子半枚（炮裂）；泄利下重者，先浓煎薤白汤，加入药末三钱匕，再煮一二沸，温服。"}, {"source": "条624｜《幼幼新书》卷三十九·仙人炼绛雪", "原文": "《幼幼新书》卷三十九：“《外台》仙人炼绛雪。疗一切病。肺气积聚，咳逆呕吐脓血；丹石毒发；天行时气，一切热病诸黄疸等；心风昏乱、心忪健忘：四肢烦热、头痛眼赤，大小便不通，烦闷不安，骨节疼痛，赤白痢、血痢、热毒痢，宿食不消化，心腹胀满，出气不得；下一切诸毒药，脚气等；饮酒多醉困，久痢不瘥：孩子惊痫等。以上和水服之。产后一切诸病堕胎和酒服之方。 　 \n朴硝十斤  升麻三两  大青、桑白皮、槐花各二两  ", "白话": "〔出处·方名〕《幼幼新书》引《外台》仙人炼绛雪，疗一切病。〔主治〕肺气积聚，咳逆呕吐脓血；丹石毒发；天行时气，一切热病、诸黄疸等；心风昏乱、心忪健忘；四肢烦热、头痛眼赤，大小便不通，烦闷不安，骨节疼痛，赤白痢、血痢、热毒痢，宿食不消化，心腹胀满，出气不得；下一切诸毒药、脚气等；饮酒多醉困，久痢不愈；小儿惊痫等——以上和水服之；产后一切诸病、堕胎，和酒服之。〔组成·照录〕朴硝十斤，升麻三两，大青、桑白皮、槐花各二两，犀角屑、羚羊角屑各一两，苏枋木六两，竹叶两握，诃黎勒皮、山栀子"}, {"source": "条625｜《太平惠民和剂局方》卷四·二陈汤", "原文": "《太平惠民和剂局方》卷四：“二陈汤。治痰饮为患，或呕吐恶心，或头眩心悸，或中脘不快，或发为寒热，或因食生冷，脾胃不和。 　 \n半夏汤洗七次、橘红各五两  白茯苓三两  甘草炙，一两半　 \n上为㕮咀，每服四钱，用水一钱，生姜七片，乌梅一个，同煎六分，去滓，\n热服，不拘时候。", "白话": "〔主治〕治痰饮为患：或呕吐恶心，或头眩心悸，或中脘不快，或发为寒热，或因食生冷而脾胃不和。〔组成·照录〕半夏（汤洗七次）、橘红各五两，白茯苓三两，甘草（炙）一两半。〔方义〕半夏、橘红燥湿化痰理气，茯苓健脾渗湿，炙甘草和中，为治痰湿总方。〔服法〕上为㕮咀，每服四钱，用水一钱（疑当作一盏），生姜七片、乌梅一个同煎至六分，去渣热服，不拘时候。"}, {"source": "条626｜《太平惠民和剂局方》卷五·平补镇心丹", "原文": "《太平惠民和剂局方》卷五：“平补镇心丹。治丈夫、妇人心气不足，志意不定，神情恍惚，夜多异梦，忪悸烦郁，及肾气伤败，血少气多，四肢倦怠，足胫酸疼，睡卧不隐，梦寐遗精，时有白浊，渐至羸瘦。 　\n酸枣仁去皮、隔纸炒，二钱半  车前子去土，碾破、白茯苓去皮、五味子去枝、梗、肉桂去粗皮，不见火、麦门冬去心、茯神去皮，各一两二钱半  天门冬去心、龙齿、熟地黄洗，酒蒸、山药姜汁制，各一两半  人参去芦，半两  ", "白话": "〔主治〕治男子、妇人心气不足，志意不定，神情恍惚，夜间多做怪梦，忪悸烦郁，及肾气伤败，血少气多，四肢倦怠，足胫酸疼，睡卧不稳，梦寐遗精，时有白浊，渐至羸瘦。〔组成·照录〕酸枣仁（去皮，隔纸炒）二钱半，车前子（去土，碾破）、白茯苓（去皮）、五味子（去枝、梗）、肉桂（去粗皮，不见火）、麦门冬（去心）、茯神（去皮）各一两二钱半，天门冬（去心）、龙齿、熟地黄（洗，酒蒸）、山药（姜汁制）各一两半，人参（去芦）半两，朱砂（细研为衣）半两，远志（去心）、甘草（炙）一两半。〔方义〕枣仁、茯神"}, {"source": "条627｜《太平惠民和剂局方》卷五·宁志膏", "原文": "《太平惠民和剂局方》卷五：“宁志膏。治心脏亏虚，神志不守，恐怖惊惕，常多恍惚，易于健忘，睡卧不宁，梦涉危险，一切心疾，并皆治之。 　\n酸枣仁微炒，去皮、人参各一两  辰砂研细，水飞，半两  乳香以乳钵坐水盆中研，一分　 \n上四味研和停，炼蜜丸，如弹子大。每服一粒，温酒化下，枣汤亦得，空心 临卧服。", "白话": "〔主治〕治心脏亏虚，神志不守，恐怖惊惕，常多恍惚，易于健忘，睡卧不宁，梦涉危险——一切心疾并皆治之。〔组成·照录〕酸枣仁（微炒，去皮）、人参各一两，辰砂（研细，水飞）半两，乳香（以乳钵坐水盆中研）一分。〔方义〕枣仁、人参养心安神，辰砂镇心，乳香活血行气，为养心安神、镇心定志之膏。〔制法·服法〕上四味研和匀，炼蜜丸如弹子大，每服一粒，温酒化下，枣汤亦可，空腹、临卧服。"}, {"source": "条628｜《太平惠民和剂局方》卷五·定志丸", "原文": "《太平惠民和剂局方》卷五：“定志丸。治心气不定，五脏不足，恍惚振悸，忧愁悲伤，差错谬忘，梦寐惊魇，恐怖不宁，喜怒无时，朝瘥暮剧，暮瘥朝剧，或发狂眩，并宜服之。 　\n远志去苗及心、菖蒲各二两  人参、白茯苓去皮，各三两　 \n上为细末，炼蜜丸，如梧桐子大，朱砂为衣。每服七丸，加至二十丸，温米饮下，食后，临卧，日三服。常服益心强志，令人不忘。", "白话": "〔主治〕治心气不定，五脏不足，恍惚振悸，忧愁悲伤，差错谬忘，梦寐惊魇，恐怖不宁，喜怒无时，朝轻暮重、暮轻朝重，或发狂眩，均宜服。〔组成·照录〕远志（去苗及心）、菖蒲各二两，人参、白茯苓（去皮）各三两。〔方义〕远志、菖蒲开窍益智，人参、茯苓补心气，为益心强志、安神定悸之祖方。〔制法·服法〕上为细末，炼蜜丸如梧桐子大，朱砂为衣，每服七丸渐加至二十丸，温米饮下，食后、临卧，日三次；常服益心强志，令人不忘。"}, {"source": "条629｜《太平惠民和剂局方》卷五·十四友丸", "原文": "《太平惠民和剂局方》卷五：“十四友丸。补心肾虚，怔忪昏愦，神志不宁，睡卧不安。故《经》曰：“脏有所伤，情有所倚，人不能知其病，则卧不安。” 　\n熟地黄、白茯苓、白茯神去木、人参、酸枣仁炒、柏子仁别研、紫石英别研、肉桂、阿胶蛤粉炒、当归、黄芪、远志汤浸，去心，酒洒、蒸，各一两  辰砂别研，一分  龙齿别研，二两　 \n上为末，同别研四味，炼蜜为丸，如梧桐子大。每服三十丸，食后枣汤下。", "白话": "〔主治〕补心肾之虚，治怔忪昏愦、神志不宁、睡卧不安。故《经》曰：“脏有所伤，情有所倚，人不能知其病，则卧不安。”〔组成·照录〕熟地黄、白茯苓、白茯神（去木）、人参、酸枣仁（炒）、柏子仁（别研）、紫石英（别研）、肉桂、阿胶（蛤粉炒）、当归、黄芪、远志（汤浸，去心，酒洒，蒸）各一两，辰砂（别研）一分，龙齿（别研）二两。〔方义〕参、芪、苓、地、归、胶气血双补，枣仁、柏子仁、茯神、远志安神，紫石英、龙齿、辰砂重镇，肉桂温阳，为补心肾、镇心神之丸。〔制法·服法〕上为末，同别研四味（柏子"}, {"source": "条630｜《太平惠民和剂局方》卷九·术香散", "原文": "《太平惠民和剂局方》卷九：“术香散。治妇人血风脏气，头目昏晕，心烦怔忪，手足热疼，经候不调，脐腹时痛，或多便利，饮食减少，并宜服之。 　\n天台乌药、三棱煨、蓬莪术煨、川当归去芦、荆芥穗、天麻、桂心不见火、延胡索、厚朴姜汁制，炒、附子炮，去皮、脐，各一两　 \n上为细末。每服一钱，生姜汁少许，和温酒调下。", "白话": "〔主治〕治妇人血风脏气：头目昏晕，心烦怔忪，手足热疼，经候不调，脐腹时痛，或大便泄利，饮食减少，均宜服。〔组成·照录〕天台乌药、三棱（煨）、蓬莪术（煨）、川当归（去芦）、荆芥穗、天麻、桂心（不见火）、延胡索、厚朴（姜汁制，炒）、附子（炮，去皮、脐）各一两。〔方义〕乌药、厚朴、延胡索理气止痛，三棱、莪术、当归活血调经，荆芥、天麻祛风，桂、附温经，为理气活血、温经定悸之散。〔服法〕上为细末，每服一钱，生姜汁少许和温酒调下。"}, {"source": "条631｜《太平惠民和剂局方》卷九·人参鳖甲丸", "原文": "《太平惠民和剂局方》卷九：“人参鳖甲丸。治妇人一切虚损，肌肉瘦瘁，盗汗心忪，咳嗽上气，经脉不调，或作寒热，不思饮食。 　\n杏仁汤浸，去皮、尖，炒、人参、当归洗，焙、赤芍药、甘草炙、柴胡去苗、桔梗去芦，各一两  地骨皮、宣黄连去须、胡黄连各一分  肉桂去粗皮、木香各半两  麝香别研，半分  鳖甲一枚，可重二两者，醋炙黄色为度　\n上为细末，用青蒿一斤，研烂，绞取汁，童子小便五升，酒五升，同熬至二升以来", "白话": "〔主治〕治妇人一切虚损，肌肉消瘦憔悴，盗汗心忪，咳嗽上气，经脉不调，或发寒热，不思饮食。〔组成·照录〕杏仁（汤浸，去皮、尖，炒）、人参、当归（洗，焙）、赤芍药、甘草（炙）、柴胡（去苗）、桔梗（去芦）各一两，地骨皮、宣黄连（去须）、胡黄连各一分，肉桂（去粗皮）、木香各半两，麝香（别研）半分，鳖甲一枚（约重二两，醋炙黄色为度）。〔方义〕参、归、芍、草益气养血，柴胡、地骨皮、二连、鳖甲、青蒿清虚热，杏仁、桔梗止咳，肉桂、木香、麝香温通行气，为补虚除蒸、养心定悸之丸。〔制法·服法〕上"}, {"source": "条632｜《太平惠民和剂局方（附：指南总论）》卷下·虚汗盗汗心忪选方", "原文": "《太平惠民和剂局方（附：指南总论）》卷下“虚汗、盗汗，心忪气短者，可与牡蛎散、止汗散、黄芪建中汤、大山药丸、人参当归散加小麦煎服。自汗不止者，术附汤、正元散。心热盗汗，可与辰砂妙香散。", "白话": "〔主治·选方〕虚汗、盗汗，心忪气短者，可给牡蛎散、止汗散、黄芪建中汤、大山药丸、人参当归散加小麦煎服；自汗不止者，用术附汤、正元散；心热盗汗者，可用辰砂妙香散。〔组成·服法〕原稿为成方选介，各方组成未录。〔方义〕以益气固表（牡蛎散、黄芪建中汤）、养血（人参当归散）、温阳（术附汤、正元散）、清心（辰砂妙香散）分治各类汗证兼心忪。"}, {"source": "条633｜《太平惠民和剂局方》卷十·檀香汤", "原文": "《太平惠民和剂局方》卷十：“檀香汤。治精神不爽，头目昏眩，心忪烦躁，志意不定。 　\n川芎不见火、白芷不见火，各二两  桔梗焙，三十两  檀香不见火，三两  甘草炒，六两　 \n上为细末。每服一钱，入盐少许，沸汤点服。调中顺气，安神定志，清爽头目。", "白话": "〔主治〕治精神不爽，头目昏眩，心忪烦躁，志意不定。〔组成·照录〕川芎（不见火）、白芷（不见火）各二两，桔梗（焙）三十两，檀香（不见火）三两，甘草（炒）六两。〔方义〕檀香、川芎、白芷芳香行气、清爽头目，桔梗宣肺，甘草和中，为调中顺气、安神定志之汤。〔制法·服法〕上为细末，每服一钱，加盐少许，沸汤点服（冲泡服）。"}, {"source": "条634｜《伤寒直指》卷十四·柴胡双解饮", "原文": "柴胡双解饮\n《伤寒直指》卷十四：柴胡双解饮节庵。 \n柴胡、黄芩、半夏、人参、甘草、白芍、茯苓、姜三片  枣二枚 \n渴去半夏加花粉、知母；呕加姜汁、竹茹；胁痛加青皮；寒热似疟加桂枝；热多倍柴胡；寒多倍桂枝；小便不利加茯苓；嗽加金沸草一云去人参；痰盛加瓜蒌仁、杏仁、枳壳；胸中满闷，加枳壳、桔梗、陈皮，未效，去茯苓、甘草，再加黄连，豁然有效；虚烦，加竹叶、炒粳米一云加竹茹；腹痛，倍加芍药；心中悸，加猪苓", "白话": "〔出处〕柴胡双解饮（节庵方）。〔组成·照录〕柴胡、黄芩、半夏、人参、甘草、白芍、茯苓，生姜三片、大枣二枚。〔方义〕以小柴胡汤为底，和解少阳、健脾化痰，表里双解。〔加减〕口渴去半夏加花粉（天花粉）、知母；呕加姜汁、竹茹；胁痛加青皮；寒热似疟加桂枝；热多倍柴胡；寒多倍桂枝；小便不利加茯苓；咳嗽加金沸草（一说去人参）；痰盛加瓜蒌仁、杏仁、枳壳；胸中满闷加枳壳、桔梗、陈皮，若不效，去茯苓、甘草再加黄连，豁然有效；虚烦加竹叶、炒粳米（一说加竹茹）；腹痛倍加芍药；心中悸加猪苓。"}, {"source": "条635｜《杨氏家藏方》卷九·还少丸", "原文": "《杨氏家藏方》卷九：“还少丸。大补本气虚损，及脾胃怯弱，心忪恍惚，精神昏愦，气血凝滞，饮食无味，肌瘦体倦，目暗耳聋。 　\n干山药一两半  牛膝酒浸一宿，焙干，一两半  白茯苓去皮、山茱萸、楮实、杜仲去粗皮，生姜汁和酒炙令香熟、五味子、巴戟去心、肉苁蓉酒浸一宿，切、焙干、远志去心、茴香九味各一两  石菖蒲、熟干地黄洗焙、枸杞子三味各半两　\n上件为细末，炼蜜入蒸熟、去皮核枣肉和匀，丸如梧桐子大。每服五", "白话": "〔主治〕大补本气虚损，及脾胃怯弱：心忪恍惚，精神昏愦，气血凝滞，饮食无味，肌瘦体倦，目暗耳聋。〔组成·照录〕干山药一两半，牛膝（酒浸一宿，焙干）一两半，白茯苓（去皮）、山茱萸、楮实、杜仲（去粗皮，生姜汁和酒炙令香熟）、五味子、巴戟（去心）、肉苁蓉（酒浸一宿，切，焙干）、远志（去心）、茴香九味各一两，石菖蒲、熟干地黄（洗，焙）、枸杞子三味各半两。〔方义〕山药、茯苓、山茱萸、熟地、枸杞、楮实、杜仲、巴戟、苁蓉、茴香补肾健脾，五味子、远志、菖蒲安神益智，牛膝强腰膝，为平补脾肾、安神"}, {"source": "条636｜《杨氏家藏方》卷十·四味补心丸", "原文": "《杨氏家藏方》卷十：“四味补心丸。益血补心，安神定志。治怔忪惊悸，恍惚健忘。 　\n当归酒洗焙干，二两  朱砂一两，别研  肉苁蓉酒浸一宿，焙干，二两  杏仁一百五十枚，汤泡去皮尖，研成膏　 \n上件为细末，以杏仁膏同和，如干，以浸药酒煮薄糊添和，杵千余下，丸如绿豆大。每服三十丸，用米饮或温酒下，不拘时候。", "白话": "〔功效·主治〕益血补心，安神定志；治怔忪惊悸，恍惚健忘。〔组成·照录〕当归（酒洗，焙干）二两，朱砂一两（别研），肉苁蓉（酒浸一宿，焙干）二两，杏仁一百五十枚（汤泡去皮尖，研成膏）。〔方义〕当归、苁蓉益血补心，朱砂镇心安神，杏仁膏润下和药，为益血补心、安神定志之丸。〔制法·服法〕上为细末，以杏仁膏同和，若干则以浸药酒煮薄糊添和，杵千余下，丸如绿豆大，每服三十丸，米饮或温酒下，不拘时候。"}, {"source": "条637｜《杨氏家藏方》卷第十·定志丸", "原文": "《杨氏家藏方》卷第十：“定志丸。治怔忪健忘，精神恍惚，睡卧不宁，一切心疾。 　\n人参去芦头、白茯苓去皮、石菖蒲、远志去心、龙齿、酸枣仁微炒、铁粉别研麦门冬去心，焙干、朱砂飞过、乳香别研、麝香别研、琥珀别研　 \n上件各等分为细末，次入朱砂、铁粉同研匀，绞生地黄汁，浸蒸饼为丸如梧桐子大，别用朱砂为衣。每服二十丸，温熟水送下，食后、临卧。", "白话": "〔主治〕治怔忪健忘，精神恍惚，睡卧不宁，一切心疾。〔组成·照录〕人参（去芦头）、白茯苓（去皮）、石菖蒲、远志（去心）、龙齿、酸枣仁（微炒）、铁粉（别研）、麦门冬（去心，焙干）、朱砂（飞过）、乳香（别研）、麝香（别研）、琥珀（别研）。〔方义〕定志丸（参、苓、菖、远）益心定志，加龙齿、铁粉、朱砂、琥珀重镇，枣仁、麦冬养心，乳香、麝香通窍，为重镇安神、益心定志之丸。〔制法·服法〕上药各等分为细末，次入朱砂、铁粉同研匀，绞生地黄汁浸蒸饼为丸如梧桐子大，另用朱砂为衣，每服二十丸，温开水"}, {"source": "条638｜《杨氏家藏方》卷十·养心丸", "原文": "《杨氏家藏方》卷十：“养心丸。治忧思太过，健忘怔忪，睡多恐惕，梦涉峻危，自汗不止，五心烦热，目涩昏倦，梦寐失精，口苦舌干，日渐羸瘦，全不思食。 　\n茯神去木、人参去芦头、绵黄芪蜜炙、酸枣仁去皮称，别研成膏，以上四味各一两熟干地黄洗焙、远志去心、五味子、柏子仁别研成膏，以上四味各半两  朱砂三分，研细水飞　\n上件为细末，入二膏和匀研细，炼蜜为丸如梧桐子大。每服五十丸，食后、临卧，浓煎人参汤送下。", "白话": "〔主治〕治忧思太过：健忘怔忪，睡中多恐惧，梦涉高险，自汗不止，五心烦热，目涩昏倦，梦寐失精，口苦舌干，日渐羸瘦，全不思食。〔组成·照录〕茯神（去木）、人参（去芦头）、绵黄芪（蜜炙）、酸枣仁（去皮，称，别研成膏）以上四味各一两，熟干地黄（洗，焙）、远志（去心）、五味子、柏子仁（别研成膏）以上四味各半两，朱砂三分（研细，水飞）。〔方义〕茯神、枣仁、柏子仁、远志、五味子养心安神，参、芪益气，熟地滋阴，朱砂镇心，为养心安神、益气滋阴之丸。〔制法·服法〕上为细末，入枣仁、柏子仁二膏和匀"}, {"source": "条639｜《杨氏家藏方》卷十五·养荣汤", "原文": "《杨氏家藏方》卷十五：“养荣汤。治妇人血海虚弱，气不升降，心忪恍惚，时多惊悸，或发虚热，经候不调，可进饮食。 　\n白芍药、川芎、熟干地黄洗焙、当归酒浸一宿，焙干、青橘皮去白、姜黄、牡丹皮、海桐皮、五加皮、香白芷以上十味各半两  牛膝酒浸一宿，焙干、延胡索、没药别研、五灵脂去砂石、肉桂去粗皮，以上五味各一分　 \n上件㕮咀。每服五钱，水一盏半，生姜五片，乌梅一枚，煎至一盏，去滓温服，不拘时候。", "白话": "〔主治〕治妇人血海虚弱，气机升降失常，心忪恍惚，时多惊悸，或发虚热，经候不调，饮食尚可。〔组成·照录〕白芍药、川芎、熟干地黄（洗，焙）、当归（酒浸一宿，焙干）、青橘皮（去白）、姜黄、牡丹皮、海桐皮、五加皮、香白芷以上十味各半两，牛膝（酒浸一宿，焙干）、延胡索、没药（别研）、五灵脂（去砂石）、肉桂（去粗皮）以上五味各一分。〔方义〕四物（芍、芎、地、归）养血，姜黄、丹皮、延胡、没药、五灵脂活血行滞，青皮理气，牛膝、五加皮、海桐皮强筋通络，白芷、肉桂温通，为养血活血、理气定悸之汤。"}, {"source": "条640｜《杨氏家藏方》卷十七·百枝膏", "原文": "《杨氏家藏方》卷十七：“百枝膏。治小儿禀赋怯弱，易感惊邪，心神恍惚，眠睡不安。常服安心神，压惊悸。 　\n人参去芦头、防风去芦头、天麻三味各一两  麦门冬汤浸去心，焙干称、白附子炮、 白僵蚕炒去丝嘴、羌活去芦头、石菖蒲、五味各半两  朱砂二钱，别研  麝香一钱，别研　 \n上件为细末，次入朱砂、麝香研匀，炼蜜为丸，每一两作四十丸。每服一丸，温荆芥汤化下，食后，临卧。", "白话": "〔主治〕治小儿先天禀赋怯弱，易感惊邪，心神恍惚，眠睡不安；常服安心神、压惊悸。〔组成·照录〕人参（去芦头）、防风（去芦头）、天麻三味各一两，麦门冬（汤浸去心，焙干，称）、白附子（炮）、白僵蚕（炒，去丝嘴）、羌活（去芦头）、石菖蒲五味各半两，朱砂二钱（别研），麝香一钱（别研）。〔方义〕参、麦冬益气养阴，防风、天麻、僵蚕、羌活祛风镇惊，菖蒲开窍，白附子祛风痰，朱砂、麝香镇心安神，为小儿祛风镇惊、安神定悸之膏。〔制法·服法〕上为细末，次入朱砂、麝香研匀，炼蜜为丸，每一两作四十丸，每"}, {"source": "条641｜《黄帝素问宣明论方》卷十一·人参白术散", "原文": "《黄帝素问宣明论方》卷十一：“人参白术散。治遍身燥湿相抟，玄府致密，遂令忪悸发渴，饮食减少，不为肌肤。 　\n人参三钱  白术七钱  薄荷半两  缩砂仁三钱  生地黄、茯苓去皮、甘草各半两 黄芩一钱  滑石三两  藿香三钱半  石膏一两 　 \n上为末，每服三钱，水一盏，煎至六分，去滓，温服，食前，日进二三服。", "白话": "〔主治〕治遍身燥湿相抟，腠理（玄府）致密，遂令忪悸、口渴，饮食减少，肌肉不长。〔组成·照录〕人参三钱，白术七钱，薄荷半两，缩砂仁三钱，生地黄、茯苓（去皮）、甘草各半两，黄芩一钱，滑石三两，藿香三钱半，石膏一两。〔方义〕参、术、苓、草健脾益气，石膏、黄芩、滑石清热利湿，生地滋阴，薄荷、藿香、砂仁芳香化湿醒脾，为清热化湿、益气生津之散。〔服法〕上为末，每服三钱，水一盏煎至六分，去渣温服，食前，日二三服。"}, {"source": "条642｜《叶氏录验方》中卷·辰砂茯神散", "原文": "《叶氏录验方》中卷：“辰砂茯神散。治心间有气，邪热在内，精神恍惚，忘误怔忪，眠睡不稳，五心烦热，饮食不美，肢体昏倦。 　\n辰砂半两，细研如粉  人参半两  茯神半两，去黑皮秤  白僵蚕一两，洗炒  远志一分，去心秤  犀角屑一分  牙硝一分，别研细  甘草一分，炙微赤　\n上件为细末，每服二钱，用薄荷煎汤调下，食后，临卧，日三服。", "白话": "〔主治〕治心间有气，邪热在内，精神恍惚，忘误怔忪，眠睡不稳，五心烦热，饮食不美，肢体昏倦。〔组成·照录〕辰砂半两（细研如粉），人参半两，茯神半两（去黑皮，秤），白僵蚕一两（洗，炒），远志一分（去心，秤），犀角屑一分，牙硝一分（别研细），甘草一分（炙微赤）。〔方义〕辰砂、犀角、牙硝镇心清热，茯神、远志、人参安神益气，僵蚕祛风，甘草和中，为清热镇心、安神定悸之散。〔服法〕上为细末，每服二钱，用薄荷煎汤调下，食后、临卧，日三次。"}, {"source": "条643｜《叶氏录验方》中卷·七宝丹", "原文": "《叶氏录验方》中卷：“七宝丹。大镇心，养真血，安神魄。治血虚气结，惊悸不宁。 　\n当归一两，洗焙  芎半两，洗  桂心半两，去皮  石菖蒲半两，去毛  茯神一两  远志肉半两，汤泡姜汁浸炒  人参一两，去须  柏子仁半两，研  酸枣仁半两，去皮净，微炒，以上修事为末  琥珀半两  真血竭半两  没药半两  朱砂一两  麝香肉一钱，以上细研 　 \n上为末，炼蜜和熟枣肉熬成膏，和药为丸，如梧桐子大。每", "白话": "〔功效·主治〕大镇心，养真血，安神魄；治血虚气结，惊悸不宁。〔组成·照录〕当归一两（洗，焙），芎半两（洗），桂心半两（去皮），石菖蒲半两（去毛），茯神一两，远志肉半两（汤泡，姜汁浸炒），人参一两（去须），柏子仁半两（研），酸枣仁半两（去皮净，微炒）——以上修治为末；琥珀半两，真血竭半两，没药半两，朱砂一两，麝香肉一钱——以上细研。〔方义〕当归、芎、枣仁、柏子仁、茯神、远志、人参养血安神，琥珀、血竭、没药活血镇心，朱砂、麝香镇心开窍，桂心温通，菖蒲开窍，为养血活血、镇心安神之丹"}, {"source": "条644｜《叶氏录验方》中卷·龙齿汤", "原文": "《叶氏录验方》中卷：“龙齿汤。治心怔惊悸，常怀忧虑，神思昏昧，如人将捕状，小便赤少，或多，或浊，宜服李尧卿传。 　\n人参去芦头、甘草炙、枳壳去瓤，麸炒、龙齿研、北桔梗以上各一两半  半夏二两，汤泡七次  黄芪炙  茯神一两  白茯苓一两半  远志去心，一两半  当归一两半  官桂二两半　 \n上为末，每服三钱。水一盏半，生姜三片，枣子一个，粳米百粒，同煎七分，食前服。", "白话": "〔主治〕治心怔惊悸，常怀忧虑，神思昏昧，如人将捕之状，小便赤少或量多或浑浊——宜服（李尧卿传方）。〔组成·照录〕人参（去芦头）、甘草（炙）、枳壳（去瓤，麸炒）、龙齿（研）、北桔梗以上各一两半，半夏二两（汤泡七次），黄芪（炙，原稿未著剂量），茯神一两，白茯苓一两半，远志（去心）一两半，当归一两半，官桂二两半。〔方义〕参、芪、苓、草益气，当归养血，茯神、远志、龙齿安神镇惊，枳壳、桔梗、半夏理气化痰，官桂温阳，为益气养血、化痰定悸之汤。〔服法〕上为末，每服三钱，水一盏半加生姜三片、"}, {"source": "条645｜《叶氏录验方》中卷·育神散", "原文": "《叶氏录验方》中卷：“育神散。治心气不宁，二三十年不可者皆治，或虚弱多惊，神色昏愦，怔忪健忘，或言语无节，有类颠邪，或心志不定，小便白浊，饮食无味。  \n白茯苓、茯神白者、人参去须、远志去心，焙干秤、龙骨令研如粉，临时和入、赤石脂令研如粉，临时和入、干姜炮、当归净洗、白术切、红芍药、桂心去粗皮，不见火，临时入、紫菀茸净洗、防风、甘草炙，各等分  川乌炮，去皮脐，各半  没药一分  乳香一分 安息香", "白话": "〔主治〕治心气不宁，二三十年不愈者皆治；或虚弱多惊，神色昏愦，怔忪健忘，或言语无节、有类癫邪，或心志不定，小便白浊，饮食无味。〔组成·照录〕白茯苓、茯神（白者）、人参（去须）、远志（去心，焙干，秤）、龙骨（令研如粉，临时和入）、赤石脂（令研如粉，临时和入）、干姜（炮）、当归（净洗）、白术（切）、红芍药、桂心（去粗皮，不见火，临时入）、紫菀茸（净洗）、防风、甘草（炙）各等分；川乌（炮，去皮脐）各半（分量疑残）；没药一分，乳香一分，安息香一分，麝香一钱（研）。〔方义〕茯苓、茯神、"}, {"source": "条646｜《叶氏录验方》中卷·养心丹", "原文": "《叶氏录验方》中卷：“养心丹。益心强志，安心肾，使水火通交，阴阳既济，除恍惚惊悸。 　\n通明辰砂成块者二两，用生绢袋子盛定，用无灰酒两碗半悬台浸七日。然后用银石器内慢火煮，令九分干，用井水浸一宿，研成膏子、通明乳香酒人参汤研如粉，入在朱砂膏同研，各半两  茯神一两半  人参拣末一两半，都入朱砂乳香膏内研　\n上和令匀，入猪羊心血合成丸，如小鸡头大。每服三两粒至十粒，煎人参炒酸枣仁汤化服。食后，临卧服", "白话": "〔功效·主治〕益心强志，安心肾，使水火交通，阴阳既济，除恍惚惊悸。〔组成·照录〕通明辰砂成块者二两（用生绢袋盛定，以无灰酒两碗半悬浸七日，然后用银石器内慢火煮至九分干，用井水浸一宿，研成膏）；通明乳香（用酒、人参汤研如粉，入朱砂膏同研）半两；茯神一两半；人参拣末一两半（都入朱砂乳香膏内研）。〔方义〕辰砂镇心，乳香活血，茯神、人参养心益气，以猪羊心血和丸取同气相求，为益心强志、交通心肾之丹。〔制法·服法〕上和令匀，入猪羊心血合成丸如小鸡头（芡实）大，每服两三粒至十粒，煎人参炒酸"}, {"source": "条647｜《叶氏录验方》中卷·琥珀安神丸", "原文": "《叶氏录验方》中卷：“琥珀安神丸。治心气不和，肢体麻痹，心忪惊愦，饮食无味，或耳内虚鸣，常服镇心安神。  \n木香 琥珀不见火，别研  人参  五灵脂拣净  沉香二钱半  \n上为细末，肉枣灯心煮去皮，取肉为丸，如梧桐子大。每服四十粒至五十粒，枣汤吞下，空心，日午服。", "白话": "〔主治〕治心气不和，肢体麻痹，心忪惊愦，饮食无味，或耳内虚鸣；常服镇心安神。〔组成·照录〕木香、琥珀（不见火，别研）、人参、五灵脂（拣净）、沉香二钱半（前四味原稿未著剂量）。〔方义〕琥珀镇心安神，木香、沉香行气，人参益气，五灵脂活血，为镇心安神、行气活血之丸。〔制法·服法〕上为细末，以肉枣加灯心同煮去皮，取枣肉为丸如梧桐子大，每服四十至五十粒，枣汤吞下，空腹、日午服。"}, {"source": "条648｜《医学启源》卷上·惊悸用药法", "原文": "《医学启源》卷上：“小便黄用黄柏，涩者加泽泻余沥者杜仲，惊悸恍惚，用茯神凡春加防风、升麻；夏加黄芩、知母、白芍药；秋加泽泻、茯苓；冬加桂、桂枝。", "白话": "〔论治〕小便黄用黄柏；小便涩加泽泻；小便余沥加杜仲；惊悸恍惚用茯神。凡春季加防风、升麻；夏季加黄芩、知母、白芍药；秋季加泽泻、茯苓；冬季加桂、桂枝。〔组成·服法〕此为随证、随时令加减用药法，非成方。〔方义〕惊悸恍惚以茯神为主，合时令升降浮沉而加味。"}, {"source": "条649｜《是斋百一选方》卷一·猪腰子方（人参当归方）", "原文": "《是斋百一选方》卷一：“昆山神济大师方，献张魏公丞相，韩子常知府阁中服之有效。 　\n猪腰子一只，用水两碗煮至一盏半，将腰子细切，入人参半两，当归上去芦，下去细者，取中段半两，并切，同煎至八分，吃腰子，以汁送下。有吃不尽腰子，同上二味药滓焙干，为细末，山药糊丸如梧桐子大。每服三、五十丸。此药多服为佳。平江医者丁御干为葛枢密云：此药本治心气怔忡而自汗者，不过一、二服即愈，盖奇药也！", "白话": "〔出处〕昆山神济大师方，献于张魏公丞相，韩子常知府阁中服之有效。〔组成·照录〕猪腰子一只（用水两碗煮至一盏半，将腰子细切），人参半两，当归（上去芦、下去细者，取中段）半两（并切）。〔方义〕猪腰子以脏补脏，人参益气，当归养血，为补心气、养心血之食疗方。〔服法〕同煎至八分，吃腰子、以汁送下药；吃不完的腰子同上二味药渣焙干为细末，以山药糊丸如梧桐子大，每服三五十丸；此药多服为佳。〔原稿载〕平江医者丁御干对葛枢密说：此药本治心气怔忡而自汗者，不过一二服即愈，盖奇药也。"}, {"source": "条650｜《活人事证方后集》卷二·枣仁圆", "原文": "《活人事证方后集》卷二：“枣仁圆。治心气不足，恍惚健忘，睡卧不宁，梦寐危奁，心忪如人捕。张承节累用有效。 　\n酸枣仁炒，去皮  黑豆炒，去皮　 \n上等分为细末，炼蜜为丸，如梧桐子大，朱砂少许为衣，每服三十圆。日午、临卧，熟水或人参汤送下。", "白话": "〔主治〕治心气不足，恍惚健忘，睡卧不宁，梦寐涉险，心忪如人将捕；张承节屡用有效。〔组成·照录〕酸枣仁（炒，去皮）、黑豆（炒，去皮）。〔方义〕枣仁养心安神，黑豆补肾益精，为养心安神之小丸。〔制法·服法〕上等分为细末，炼蜜为丸如梧桐子大，朱砂少许为衣，每服三十丸，日午、临卧用熟水或人参汤送下。"}, {"source": "条651｜《活人事证方后集》卷二·震灵丹", "原文": "《活人事证方后集》卷二：“震灵丹。治气虚心疾。盖心药多性寒，服之令人腹痛，饮食减少。此药治怔忡，恍惚健忘，睡卧不安。益心进食，补虚去冷。  张承节传授此方，用之无不效验。\n以局方震灵丹，不拘多少，重研细，用灯芯、麝香少许煮北枣，去核、皮。\n研细搜圆，如桐子大，每服三十圆。食空，枣汤或人参汤下。此丹不犯金石、飞走有性之药，不僭不燥，夺造化冲和之功。大治男子真元衰惫，五劳七伤等疾。", "白话": "〔主治〕治气虚心疾。盖心药多性寒，服之令人腹痛、饮食减少；此药治怔忡、恍惚健忘、睡卧不安，益心进食，补虚去冷。张承节传授此方，用之无不效验。〔组成·制法〕以《局方》震灵丹不拘多少，重研细；用灯心、麝香少许煮北枣，去核、皮。〔方义〕震灵丹（禹余粮、紫石英、赤石脂、代赭石等金石类原方，本法改用枣肉和丸）温摄固涩、补虚去冷；此法去金石之性，取冲和之功。〔服法〕研细，以枣肉搜和为丸如梧桐子大，每服三十丸，食空（空腹）时枣汤或人参汤下。〔原稿载〕此丹不犯金石、飞走有性之药，不僭不燥，夺"}, {"source": "条652｜《妇人大全良方》卷十九·经效方（产后心虚忪悸）", "原文": "《妇人大全良方》卷十九：“《经效》疗产后心虚忪悸，志意不定，烦躁恍惚。 　\n茯神、当归、黄芩、麦门冬去心、甘草、人参、芍药、酸枣仁、白藓皮白鲜皮各三两  大枣七个　 \n上为粗末，水二升，煮取七合，去滓温服。", "白话": "〔出处·主治〕《妇人大全良方》引《经效》疗产后心虚忪悸，志意不定，烦躁恍惚。〔组成·照录〕茯神、当归、黄芩、麦门冬（去心）、甘草、人参、芍药、酸枣仁、白藓皮（白鲜皮）各三两，大枣七个。〔方义〕茯神、枣仁、参、草安神益气，归、芍、麦冬养血滋阴，黄芩清热，白鲜皮祛风，为产后养心安神之方。〔服法〕上为粗末，水二升煮取七合，去渣温服。"}, {"source": "条653｜《妇人大全良方》卷十九·茯苓散", "原文": "《妇人大全良方》卷十九：“茯苓散。疗产后心虚，忪悸不定，乱语错误，精神恍惚不主，当由心虚所致。 　\n人参、甘草、芍药、当归、生姜各八分  远志、茯苓各十分  桂心六分  麦门冬、大枣各十二分　 \n上为散，以水八升，煮取三升，去滓，温分三服。", "白话": "〔主治〕疗产后心虚，忪悸不定，言语错乱，精神恍惚不能自主，当由心虚所致。〔组成·照录〕人参、甘草、芍药、当归、生姜各八分，远志、茯苓各十分，桂心六分，麦门冬、大枣各十二分。〔方义〕参、草、苓、远志益气安神，归、芍、麦冬养血滋阴，桂心温阳，姜、枣和中，为产后养心安神之散。〔服法〕上为散，以水八升煮取三升，去渣，温分三次服。"}, {"source": "条654｜《妇人大全良方》卷二十·必效方（产后短气欲绝）", "原文": "《妇人大全良方》卷二十：“疗妇人产后短气欲绝，心中烦闷不解。必效方。 　\n竹叶切、麦门冬、小麦各一升  甘草一两  生姜二两  大枣十四个　 \n上六味细切，以水一斗，煮竹叶、小麦，取八升去滓；内余药，煮取三升，去滓温服。若虚悸，加人参二两；少气力，加粳米五合。一方用竹皮，若胸中气逆，加半夏二两。忌如常法与竹根汤、淡竹茹汤大同小异。", "白话": "〔主治〕疗妇人产后短气欲绝，心中烦闷不解（必效方）。〔组成·照录〕竹叶（切）、麦门冬、小麦各一升，甘草一两，生姜二两，大枣十四个。〔方义〕竹叶、小麦清心除烦，麦冬养阴，甘草、生姜、大枣和中益气。〔服法〕上六味细切，以水一斗先煮竹叶、小麦取八升去渣，入余药煮取三升，去渣温服。〔加减〕虚悸加人参二两；少气力加粳米五合；一方用竹皮；胸中气逆加半夏二两。〔禁忌〕忌如常法。与竹根汤、淡竹茹汤大同小异。"}, {"source": "条655｜《妇人大全良方》卷二十二·阳旦汤", "原文": "《妇人大全良方》卷二十二：“治妇人产后伤风十数日不解，头微痛，恶寒，时时有热，心下坚，干呕，汗出，宜阳旦汤。 　\n桂枝、芍药各三两  甘草炙、黄芩各二两　 \n上㕮咀，每服三钱。水一盏，姜三片，枣一枚，煎至七分，去滓温服，无时候。自汗者，去桂，加炮熟附子一枚；渴者，去桂，加栝蒌根三两；下痢者，去芍药，加干姜三两；心下悸者，去芍药，加茯苓四两；虚劳里急者，正阳旦汤主之，煎时入胶饴为佳。若脉浮紧，无汗发", "白话": "〔主治〕治妇人产后伤风十数日不解，头微痛，恶寒，时时发热，心下坚，干呕，汗出，宜阳旦汤。〔组成·照录〕桂枝、芍药各三两，甘草（炙）、黄芩各二两。〔方义〕桂枝汤加黄芩，解肌和营、兼清里热，为产后中风之方。〔服法〕上药㕮咀，每服三钱，水一盏加姜三片、枣一枚煎至七分，去渣温服，不拘时候。〔加减〕自汗者去桂枝加炮熟附子一枚；口渴者去桂枝加栝蒌根三两；下痢者去芍药加干姜三两；心下悸者去芍药加茯苓四两；虚劳里急者用正阳旦汤，煎时加入胶饴（饴糖）为佳。〔禁忌〕若脉浮紧、无汗发热者，莫与之。"}, {"source": "条656｜《校注妇人良方》卷三·酸枣仁丸", "原文": "《校注妇人良方》卷三：“酸枣仁丸。治胆气实热，不得睡卧，神思不安，惊悸怔忡。 　\n茯神去木、酸枣仁炒、远志去心、柏子仁炒、防风各一两  枳壳麸炒，半两  生地黄杵膏，半两  青竹茹二钱五分　 \n上为末，炼蜜丸桐子大。每服七八十丸，滚汤下。", "白话": "〔主治〕治胆气实热，不得睡卧，神思不安，惊悸怔忡。〔组成·照录〕茯神（去木）、酸枣仁（炒）、远志（去心）、柏子仁（炒）、防风各一两，枳壳（麸炒）半两，生地黄（杵膏）半两，青竹茹二钱五分。〔方义〕枣仁、茯神、远志、柏子仁养心安神，生地滋阴清热，竹茹、枳壳清胆理气，防风祛风，为清胆养心、安神定悸之丸。〔制法·服法〕上为末，炼蜜丸如梧桐子大，每服七八十丸，滚开水下。"}, {"source": "条657｜《校注妇人良方》卷三·茯神散", "原文": "《校注妇人良方》卷三：“茯神散。治五脏气血虚弱，惊悸怔忡，宜用此安神定志。 　\n茯神去木、人参、龙齿另研、独活、酸枣仁炒，各三钱  防风、远志去心、桂心、细辛、白薇炒，各三钱  甘草、干姜炮，各三两　 \n上为末，每服四五钱，水煎服。或蜜为丸服。", "白话": "〔主治〕治五脏气血虚弱，惊悸怔忡，宜用此安神定志。〔组成·照录〕茯神（去木）、人参、龙齿（另研）、独活、酸枣仁（炒）各三钱，防风、远志（去心）、桂心、细辛、白薇（炒）各三钱，甘草、干姜（炮）各三两。〔方义〕茯神、龙齿、枣仁、远志安神定志，参、草、姜益气温中，桂心通阳，独活、防风、细辛祛风，白薇清虚热，为益气安神、祛风定悸之散。〔服法〕上为末，每服四五钱，水煎服；或炼蜜为丸服。"}, {"source": "条658｜《校注妇人良方》卷三·养心汤", "原文": "《校注妇人良方》卷三：“养心汤。治心血虚，惊悸怔忡不宁，或盗汗无寐，发热烦躁。\n黄芪炒、白茯苓、茯神去木、半夏曲、当归酒拌、川芎各半两  辣桂去皮、柏子仁、酸枣仁炒、五味子杵炒、人参各三钱  甘草炙，四钱　 \n上每服三五钱，姜枣水煎。", "白话": "〔主治〕治心血虚，惊悸怔忡不宁，或盗汗不寐，发热烦躁。〔组成·照录〕黄芪（炒）、白茯苓、茯神（去木）、半夏曲、当归（酒拌）、川芎各半两，辣桂（去皮）、柏子仁、酸枣仁（炒）、五味子（杵，炒）、人参各三钱，甘草（炙）四钱。〔方义〕参、芪、苓、草益气，归、芎养血，茯神、柏子仁、枣仁、五味子养心安神，辣桂温阳，半夏曲化痰和胃，为益气养血、安神定悸之汤。〔服法〕上药每服三五钱，姜、枣水煎。"}, {"source": "条659｜《校注妇人良方》卷三·温胆汤", "原文": "《校注妇人良方》卷三：“温胆汤。治胆虚痰热，惊悸不眠。 　\n半夏、竹茹、枳实麸炒，各一两  陈皮  生姜四两  甘草炒，三两　 \n上每服一两，水煎。", "白话": "〔主治〕治胆虚痰热，惊悸不眠。〔组成·照录〕半夏、竹茹、枳实（麸炒）各一两，陈皮（原稿未著剂量），生姜四两，甘草（炒）三两。〔方义〕半夏、竹茹、枳实、陈皮理气化痰清热，生姜、甘草和胃，为清胆化痰、安神定悸之方。〔服法〕上药每服一两，水煎。"}, {"source": "条660｜《校注妇人良方》卷十二·大圣散", "原文": "《校注妇人良方》卷十二：“大圣散。治妊娠忪悸梦惊，心腹胀满，连脐急痛。 　\n白茯苓、川芎、麦门冬去心、黄芪炒、当归各一钱  人参、甘草炙、木香各五分　 \n上姜水煎服。", "白话": "〔主治〕治妊娠忪悸梦惊，心腹胀满，连脐急痛。〔组成·照录〕白茯苓、川芎、麦门冬（去心）、黄芪（炒）、当归各一钱，人参、甘草（炙）、木香各五分。〔方义〕参、芪、苓、草益气，归、芎养血，麦冬滋阴，木香理气止痛，为妊娠益气养血、安神定悸之散。〔服法〕上药加生姜，水煎服。"}, {"source": "条661｜《校注妇人良方》卷二十四·平补镇心丹", "原文": "《校注妇人良方》卷二十四：“平补镇心丹。治心血不足，时或心忡惊悸，梦如高坠，常服安心肾，益荣卫。 　\n朱砂细研，半两，为衣  人参五钱  龙齿一两五钱  白茯苓、五味子炒、车前子炒、茯神、麦门冬去心，杵膏、肉桂各一两二钱半  远志去心，甘草制、天门冬去心，杵膏、山药制，各一两五钱  酸枣仁去皮尖，二钱半  熟地黄酒蒸，五钱，杵膏　 \n上为末，蜜丸桐子大。每服三十丸，空心温酒下。", "白话": "〔主治〕治心血不足，时或心忡惊悸，梦中如自高处坠下；常服安心肾、益营卫。〔组成·照录〕朱砂（细研）半两（为衣），人参五钱，龙齿一两五钱，白茯苓、五味子（炒）、车前子（炒）、茯神、麦门冬（去心，杵膏）、肉桂各一两二钱半，远志（去心，甘草制）、天门冬（去心，杵膏）、山药（制）各一两五钱，酸枣仁（去皮尖）二钱半，熟地黄（酒蒸）五钱（杵膏）。〔方义〕与条626《局方》平补镇心丹同法：参、苓、山药益气，二冬、熟地、五味滋阴，枣仁、茯神、远志、龙齿、朱砂安神镇心，肉桂温阳，车前子利湿。〔"}, {"source": "条662｜《校注妇人良方》卷二十四·归脾汤", "原文": "《校注妇人良方》卷二十四：“归脾汤。治脾经失血少寐，发热盗汗；或思虑伤脾，不能摄血，以致妄行；或健忘怔忡，惊悸不寐；或心脾伤痛，嗜卧少食；或忧思伤脾，血虚发热；或肢体作痛，大便不调；或经候不准，晡热内热；或瘰疬流注，不能消散溃敛。 　\n人参、白术炒、黄芪炒、白茯苓、龙眼肉、当归、远志、酸枣仁炒，各一钱  木香、甘草炙，各五分　 \n上姜枣水煎服。", "白话": "〔主治〕治脾经失血而少寐，发热盗汗；或思虑伤脾，不能摄血，以致血行妄溢；或健忘怔忡、惊悸不寐；或心脾伤痛，嗜卧少食；或忧思伤脾，血虚发热；或肢体作痛，大便不调；或经候不准，午后潮热、内热；或瘰疬流注，不能消散溃敛。〔组成·照录〕人参、白术（炒）、黄芪（炒）、白茯苓、龙眼肉、当归、远志、酸枣仁（炒）各一钱，木香、甘草（炙）各五分。〔方义〕参、术、芪、苓、草健脾益气，龙眼、当归养血，枣仁、远志安神，木香理气醒脾，为益气补血、健脾养心之名方。〔服法〕上药加姜、枣，水煎服。"}, {"source": "条663｜《婴童类萃》下卷·益荣汤", "原文": "《婴童类萃》下卷：“益荣汤。惊恐后，心君失辅，脾胃衰弱，怔忡恍惚，悲喜不常，小便浑浊，夜睡不宁。此方补脾胃，养心血。经云：损其心，益其荣。男妇心血不足者并效。 　\n当归、黄芪、远志、小草、茯神、人参、酸枣、柏子仁、白芍各八分  木香三分  紫石英二钱  甘草五分　 \n生姜三片，枣一枚，水煎。", "白话": "〔主治〕惊恐之后，心君失其辅佐，脾胃衰弱，怔忡恍惚，悲喜无常，小便浑浊，夜睡不宁。此方补脾胃、养心血。经云：“损其心，益其荣。”男子、妇人心血不足者均效。〔组成·照录〕当归、黄芪、远志、小草、茯神、人参、酸枣、柏子仁、白芍各八分，木香三分，紫石英二钱，甘草五分。〔方义〕参、芪、草补脾益气，归、芍养血，茯神、远志、小草、枣仁、柏子仁养心安神，紫石英镇心，木香理气，为补脾胃、养心血之汤。〔服法〕生姜三片、大枣一枚，水煎。"}, {"source": "条664｜《严氏济生方·诸虚门》·心肾丸", "原文": "《严氏济生方·诸虚门》：“心肾丸。治心肾不足，精少血燥，心下烦热，怔忡不安，或口干生疮，目赤头晕，小便赤浊，五心烦热，多渴引饮，但是精虚血少，不受峻补者，悉宜服之。 　\n菟丝子淘，酒蒸，擂，二两  麦门冬去心，二两　 \n上为细末，炼蜜为丸，如梧桐子大，每服七十丸，空心食前，用盐汤送下，热水亦得。", "白话": "〔主治〕治心肾不足，精少血燥，心下烦热，怔忡不安，或口干生疮，目赤头晕，小便赤浊，五心烦热，多渴引饮；凡精虚血少而不受峻补者，均宜服。〔组成·照录〕菟丝子（淘，酒蒸，擂）二两，麦门冬（去心）二两。〔方义〕菟丝子补肾益精，麦门冬养心阴，二味平补心肾，为精虚血少者设。〔制法·服法〕上为细末，炼蜜为丸如梧桐子大，每服七十丸，空腹食前盐汤送下，热水亦可。"}, {"source": "条665｜《严氏济生方·诸虚门》·大建中汤", "原文": "《严氏济生方·诸虚门》：“大建中汤。治诸虚不足，小腹急痛，胁肋䐜胀，骨肉酸痛，短气喘促，痰多咳嗽，潮热多汗，心下惊悸，腰背强痛，多卧少气。 　\n黄芪去芦、附子炮，去皮脐、鹿茸酒蒸、地骨皮去木、续断、石斛去根、人参、川芎、当归去芦，酒浸、白芍药、小草各一两  甘草炙，半两　 \n上㕮咀，每服四钱，水一盏半，生姜五片，煎至七分，去滓，温服，不拘时候。咳嗽者加款冬花；咳血者加阿胶；便精遗泄者加龙骨；怔忡者", "白话": "〔主治〕治诸虚不足：小腹急痛，胁肋胀满，骨肉酸痛，短气喘促，痰多咳嗽，潮热多汗，心下惊悸，腰背强痛，多卧少气。〔组成·照录〕黄芪（去芦）、附子（炮，去皮脐）、鹿茸（酒蒸）、地骨皮（去木）、续断、石斛（去根）、人参、川芎、当归（去芦，酒浸）、白芍药、小草各一两，甘草（炙）半两。〔方义〕参、芪、草益气，鹿茸、附子温阳，归、芎、芍养血，石斛、地骨皮养阴清热，续断强腰，小草（远志苗）安神，为大建中气、温补阴阳之汤。〔服法〕上药㕮咀，每服四钱，水一盏半加生姜五片煎至七分，去渣温服，不拘"}, {"source": "条666｜《严氏济生方·五脏门》·心丹（法丹）", "原文": "《严氏济生方·五脏门》：“心丹又名法丹。此丹颗粒辰砂加心药煮炼。主男子、妇人心气不足，神志不宁，忧愁思虑，谋用过度，或因惊恐伤神失志，耗伤心气，恍惚振悸，差错健忘，梦寐惊魇，喜怒无时，或发狂，眩晕，不省人事，及治元气虚弱，唇燥咽干，潮热盗汗，或肺热上壅，痰唾稠粘黏，咳嗽烦渴，或大病后心虚烦躁，小儿心气虚弱，欲发惊痫，或直视发搐，应是一切心疾并宜服之。常服养心益血，安魂定魄，宁心志，止惊悸，顺三焦，", "白话": "〔方名〕心丹，又名法丹。此丹以颗粒辰砂加养心药煮炼而成。〔主治〕主男子、妇人心气不足，神志不宁，忧愁思虑、谋虑过度，或因惊恐伤神失志、耗伤心气，恍惚振悸，差错健忘，梦寐惊魇，喜怒无时，或发狂、眩晕、不省人事；又治元气虚弱，唇燥咽干，潮热盗汗；或肺热上壅，痰唾稠黏，咳嗽烦渴；或大病后心虚烦躁；小儿心气虚弱欲发惊痫，或两眼直视、四肢发搐——一切心疾均宜服。常服养心益血，安魂定魄，宁心志，止惊悸，顺三焦，和五脏，助脾胃，进饮食，聪明耳目，悦泽颜色，轻身耐老，不偏不燥，神效不能尽述。"}, {"source": "条667｜《严氏济生方·诸虚门》·天地煎", "原文": "《严氏济生方·诸虚门》：“天地煎。治心血燥少，口干咽燥，心烦喜冷，怔忡恍惚，小便黄赤，或生疮疡。 　\n天门冬去心，二两  熟地黄九蒸曝，一两　 \n上为细末，炼蜜为丸，如梧桐子大，每服百丸，用熟水人参汤任下，不拘时候。", "白话": "〔主治〕治心血燥少：口干咽燥，心烦喜冷，怔忡恍惚，小便黄赤，或生疮疡。〔组成·照录〕天门冬（去心）二两，熟地黄（九蒸九晒）一两。〔方义〕天冬滋阴清热（天之精），熟地滋阴养血（地之精），二味合用为滋阴养血之小方，故名天地煎。〔制法·服法〕上为细末，炼蜜为丸如梧桐子大，每服百丸，熟水或人参汤任下，不拘时候。"}, {"source": "条668｜《严氏济生方·惊悸怔忡健忘门》·龙齿丹", "原文": "《严氏济生方·惊悸怔忡健忘门》：“龙齿丹。治心血虚寒，怔忡不已，痰多恍惚。 　\n龙齿、附子炮，去皮脐，切片，姜汁浸一宿、远志去心，甘草煮、酸枣仁炒，去壳，别研、当归去芦，酒浸、官桂去皮，不见火、琥珀别研、南星锉，姜汁浸一宿，各一两、木香不见火、紫石英煅，醋淬七遍、沉香别研、熟地黄酒蒸，焙，各半两　 \n上为细末，炼蜜为丸，如梧桐子大，朱砂为衣，每服五十丸，用枣汤送下，不拘时候。", "白话": "〔主治〕治心血虚寒，怔忡不已，痰多恍惚。〔组成·照录〕龙齿、附子（炮，去皮脐，切片，姜汁浸一宿）、远志（去心，甘草煮）、酸枣仁（炒，去壳，别研）、当归（去芦，酒浸）、官桂（去皮，不见火）、琥珀（别研）、南星（锉，姜汁浸一宿）各一两，木香（不见火）、紫石英（煅，醋淬七遍）、沉香（别研）、熟地黄（酒蒸，焙）各半两。〔方义〕龙齿、琥珀、紫石英镇心安神，枣仁、远志、当归、熟地养血安神，附子、官桂温心阳，南星化痰，木香、沉香理气，为温心阳、养心血、镇心化痰之丹。〔制法·服法〕上为细末，"}, {"source": "条669｜《严氏济生方·诸虚门》·茸附汤", "原文": "《严氏济生方·诸虚门》：“茸附汤。治精血俱虚，荣卫耗损，潮热自汗，怔忡惊悸，肢体倦乏，但是一切虚弱之证，皆宜服之。 　\n鹿茸去毛，酒蒸，一两  附子炮，去皮脐，一两　 \n上㕮咀，分作四服，水二盏，生姜十片，煎至八分，去滓，食前，温服。", "白话": "〔主治〕治精血俱虚，营卫耗损，潮热自汗，怔忡惊悸，肢体倦乏；一切虚弱之证均宜服。〔组成·照录〕鹿茸（去毛，酒蒸）一两，附子（炮，去皮脐）一两。〔方义〕鹿茸补精血、壮元阳，附子温经回阳，二味为温补精血之峻剂。〔服法〕上药㕮咀，分作四服，每服水二盏加生姜十片煎至八分，去渣食前温服。"}, {"source": "条670｜《严氏济生方·惊悸怔忡健忘门》·茯苓饮子", "原文": "《严氏济生方·惊悸怔忡健忘门》：“茯苓饮子。治痰饮蓄于心胃，怔忡不已。 　\n赤茯苓去皮、半夏汤泡七次、茯神去木、橘皮去白、麦门冬去心，各一两  沉香不见火、甘草炙、槟榔各半两　 \n上㕮咀，每服四钱，水一盏半，生姜五片，煎至七分，去滓，温服，不拘时候。", "白话": "〔主治〕治痰饮蓄于心胃，怔忡不止。〔组成·照录〕赤茯苓（去皮）、半夏（汤泡七次）、茯神（去木）、橘皮（去白）、麦门冬（去心）各一两，沉香（不见火）、甘草（炙）、槟榔各半两。〔方义〕二茯、麦冬养心，半夏、橘皮化痰，沉香、槟榔降气，炙甘草和中，为化痰定怔忡之方。〔服法〕上药㕮咀，每服四钱，水一盏半加生姜五片煎至七分，去渣温服，不拘时候。"}, {"source": "条671｜《严氏济生方·惊悸怔忡健忘门》·益荣汤", "原文": "《严氏济生方·惊悸怔忡健忘门》：“益荣汤。治思虑过制，耗伤心血，心帝无辅，怔忡恍惚，善悲忧，少颜色，夜多不寐，小便或浊。 　\n当归去芦，酒浸、黄芪去芦、小草、酸枣仁炒，去壳、柏子仁炒、麦门冬去心、茯神去木、白芍药、紫石英细研，各一两  木香不见火、人参、甘草炙，各半两　 \n上㕮咀，每服四钱，水一盏半，生姜五片，枣一枚，煎至七分，去滓，温服，不拘时候。", "白话": "〔主治〕治思虑过度，耗伤心血，心帝（心神）失去辅养，怔忡恍惚，善悲忧，面色少华，夜间多不寐，小便或浑浊。〔组成·照录〕当归（去芦，酒浸）、黄芪（去芦）、小草、酸枣仁（炒，去壳）、柏子仁（炒）、麦门冬（去心）、茯神（去木）、白芍药、紫石英（细研）各一两，木香（不见火）、人参、甘草（炙）各半两。〔方义〕参、芪、草补气，归、芍养血，枣仁、柏子仁、茯神、小草、麦冬养心安神，紫石英镇心，木香理气，为益气养血、安神定悸之汤。〔服法〕上药㕮咀，每服四钱，水一盏半加生姜五片、大枣一枚煎至七分"}, {"source": "条672｜《严氏济生方·诸虚门》·黄芪饮子", "原文": "《严氏济生方·诸虚门》：“黄芪饮子。治诸虚劳损，四肢倦怠，骨节酸疼，潮热乏力，自汗怔忡，日渐黄瘦，胸膈痞塞，不思饮食，咳嗽痰多，甚则唾血。 　\n黄芪蜜炙，一两半  当归去芦，酒浸、紫菀洗，去须、石斛去根、地骨皮去木、人参、桑白皮、附子炮，去皮脐、鹿茸酒蒸、款冬花各一两  半夏汤泡七次  甘草炙，各半两　 \n上㕮咀，每服四钱，水一盏半，生姜七片，枣一枚，煎至七分，去滓，温服，不拘时。此药温补荣卫，枯", "白话": "〔主治〕治诸虚劳损：四肢倦怠，骨节酸疼，潮热乏力，自汗怔忡，日渐黄瘦，胸膈痞塞，不思饮食，咳嗽痰多，甚则唾血。〔组成·照录〕黄芪（蜜炙）一两半，当归（去芦，酒浸）、紫菀（洗，去须）、石斛（去根）、地骨皮（去木）、人参、桑白皮、附子（炮，去皮脐）、鹿茸（酒蒸）、款冬花各一两，半夏（汤泡七次）、甘草（炙）各半两。〔方义〕参、芪、归、鹿茸益气养血温阳，附子助阳，石斛、地骨皮养阴清虚热，紫菀、款冬、桑皮、半夏化痰止咳，为温补营卫、化痰止咳之饮。〔服法〕上药㕮咀，每服四钱，水一盏半加生"}, {"source": "条673｜《严氏济生方·霍乱门》·理中汤", "原文": "《严氏济生方·霍乱门》：“理中汤。治过食生冷，或饮寒浆，遂成吐下，胀满，食不消，心腹痛。  \n人参、甘草炙、干姜炮、白术各等分  \n上为锉散，每服四钱，水一大盏，煎至七分，去滓，温服，不拘时候。若脐上筑者，肾气动也，去术加桂一两；吐多者，去术加生姜、半夏各半两；利多者，复用术；心悸者，加茯苓一两。", "白话": "〔主治〕治过食生冷，或饮寒凉之浆，遂成上吐下泻，胀满，食不消化，心腹痛。〔组成·照录〕人参、甘草（炙）、干姜（炮）、白术各等分。〔方义〕干姜温中，参、术、草健脾益气，为温中健脾之祖方。〔服法〕上为锉散，每服四钱，水一大盏煎至七分，去渣温服，不拘时候。〔加减〕脐上筑动者为肾气动，去白术加桂一两；吐多者去白术加生姜、半夏各半两；下利多者仍用白术；心悸者加茯苓一两。"}, {"source": "条674｜《严氏济生方·惊悸怔忡健忘门》·温胆汤", "原文": "《严氏济生方·惊悸怔忡健忘门》：“温胆汤。治心虚胆怯，触事易惊，梦寐不祥，异象感惑，遂致心惊胆怯，气郁生涎，涎与气搏，复生诸证，或短气悸乏，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。 　\n半夏汤泡七次、竹茹、枳实去瓤，各二两  陈皮去白，三两  白茯苓去皮，一两半甘草一两，炙　 \n上㕮咀，每服四钱，水一盏半，生姜五片，枣子一枚，煎至七分，去滓，温服，不拘时候。", "白话": "〔主治〕治心虚胆怯，触事易惊，梦寐不祥，为异象所惑，遂致心惊胆怯，气郁生涎，涎与气搏，复生诸证：或短气悸乏，或自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。〔组成·照录〕半夏（汤泡七次）、竹茹、枳实（去瓤）各二两，陈皮（去白）三两，白茯苓（去皮）一两半，甘草一两（炙）。〔方义〕半夏、竹茹、枳实、陈皮理气化痰，茯苓、甘草健脾和中，为化痰安神之温胆汤。〔服法〕上药㕮咀，每服四钱，水一盏半加生姜五片、枣子一枚煎至七分，去渣温服，不拘时候。"}, {"source": "条675｜《严氏济生方·惊悸怔忡健忘门》·排风汤", "原文": "《严氏济生方·惊悸怔忡健忘门》：“排风汤。治风虚冷湿闭塞诸经，令人怔忡，宜加炒酸枣仁煎。", "白话": "〔主治·加减〕排风汤治风虚冷湿闭塞诸经，令人怔忡，宜加炒酸枣仁煎服。〔组成·服法〕排风汤（《局方》方：白鲜皮、白术、芍药、桂心、川芎、当归、杏仁、防风、甘草、独活、麻黄、茯苓类）加炒酸枣仁，水煎（原稿未列组成）。"}, {"source": "条676｜《严氏济生方·惊悸怔忡健忘门》·寿星丸", "原文": "《严氏济生方·惊悸怔忡健忘门》：“寿星丸。治惊忧思虑，气结成痰，留蓄心包，怔忡惊惕，痰逆恶心，睡卧不安。", "白话": "〔主治〕治惊忧思虑，气结成痰，留蓄心包，怔忡惊惕，痰逆恶心，睡卧不安。〔组成·服法〕原稿未载。〔方义〕行气化痰、清心安神（组成原稿未录，方义以主治推之）。"}, {"source": "条677｜《仁斋直指方论（附补遗）》卷三·保命丹", "原文": "《仁斋直指方论（附补遗）》卷三：“保命丹（《千金方》）。治诸风痪疭，不能语言，心忪健忘，恍惚去来，头目晕眩，胸中烦郁，痰涎壅塞，抑气攻心，精神昏愦。治心气不足，神志不定，惊恐怕怖，悲忧惨蹙，虚烦少睡，喜怒不时，或发狂癫，神情昏乱，及小儿惊痫，惊风抽搐不定，及大人暗风，并羊癫、猪癫发叫。 　\n朱砂一两  珍珠二钱  南星一两  麻黄去根、节、白附子炮、雄黄、龙脑各半两琥珀三钱  僵蚕炒、犀角镑、麦门", "白话": "〔主治〕治诸风痪疭，不能语言，心忪健忘，恍惚往来，头目眩晕，胸中烦郁，痰涎壅塞，气逆攻心，精神昏愦；又治心气不足，神志不定，惊恐怕怖，悲忧惨蹙，虚烦少睡，喜怒无时，或发狂癫、神情昏乱，及小儿惊痫、惊风抽搐不定，及大人暗风，并羊癫、猪癫发叫。〔组成·照录〕朱砂一两，珍珠二钱，南星一两，麻黄（去根、节）、白附子（炮）、雄黄、龙脑各半两，琥珀三钱，僵蚕（炒）、犀角（镑）、麦门冬（去心）、枳壳、地骨皮、神曲、茯神、远志（去心）、人参、柴胡各一两，金箔一薄片，牛黄三钱，天麻半两，脑子少"}, {"source": "条678｜《仁斋直指方论（附补遗）》卷三·桂枝附子汤", "原文": "《仁斋直指方论（附补遗）》卷三：“桂枝附子汤。治风湿相搏，汗出气短，身体烦疼，微肿，恶风不欲去衣。 　\n辣桂二两  白术、附子熟，各一两半  甘草炙，一两　 \n上锉散。每服二钱半，水盏半，姜七片，枣二枚，煎一盏，食前，微温服。小便不利、悸气加茯苓；痹加防己，腹痛加芍药。", "白话": "〔主治〕治风湿相搏，汗出气短，身体烦疼，微肿，恶风不欲去衣。〔组成·照录〕辣桂二两，白术、附子（熟）各一两半，甘草（炙）一两。〔方义〕桂、附温经助阳，白术健脾祛湿，甘草和中，为温阳祛湿之方。〔服法〕上药锉散，每服二钱半，水一盏半加生姜七片、大枣二枚煎至一盏，食前微温服。〔加减〕小便不利、悸气加茯苓；痹证加防己；腹痛加芍药。"}, {"source": "条679｜《仁斋直指方论（附补遗）》卷七·芎夏汤", "原文": "《仁斋直指方论（附补遗）》卷七：“芎夏汤。逐水利饮通用。  \n川芎、半夏制、茯苓各一两  青皮、陈皮、枳壳制，各半两  白术、甘草炒，各一分 \n上锉散。每服三钱，姜五厚片，煎服。川芎、半夏能逐水也。喘加去节麻黄，嗽加炒桑白皮，呕加生姜、半夏，泄加苍术，白术，痞隔加枳壳、桔梗，胀满加缩砂，白豆蔻，眩晕加半夏、南星，怔忪加白茯苓。寒热疼痛下其癖，浮肿体重渗其湿，余以类推。", "白话": "〔功效〕芎夏汤，逐水利饮通用。〔组成·照录〕川芎、半夏（制）、茯苓各一两，青皮、陈皮、枳壳（制）各半两，白术、甘草（炒）各一分。〔方义〕川芎、半夏逐水，二陈（陈皮、半夏、茯苓、甘草）化痰，青皮、枳壳理气，白术健脾，为逐水利饮之通剂。〔服法〕上药锉散，每服三钱，生姜五厚片煎服。〔加减〕喘加去节麻黄；咳嗽加炒桑白皮；呕加生姜、半夏；泄泻加苍术、白术；痞隔加枳壳、桔梗；胀满加缩砂、白豆蔻；眩晕加半夏、南星；怔忪加白茯苓。寒热疼痛者下其癖积，浮肿体重者渗其湿，余以类推。"}, {"source": "条680｜《仁斋直指方论（附补遗）》卷七·水气怔忪用方", "原文": "《仁斋直指方论（附补遗）》卷七：“寻常水气，心下怔忪，大半夏汤、小半夏茯苓汤、五苓散辈通用可也。", "白话": "〔主治·选方〕寻常水气、心下怔忪者，用大半夏汤、小半夏茯苓汤、五苓散一类通用即可。〔组成·服法〕原稿为成方选介，各方组成未录。〔方义〕皆温中化饮、利水定悸之剂，随证选用。"}, {"source": "条681｜《仁斋直指方论（附补遗）》卷九·牡蛎散", "原文": "《仁斋直指方论（附补遗）》卷九：“牡蛎散。治诸虚体常自汗，惊惕不宁。　\n左顾牡蛎米泔浸洗，煅透、麻黄根、黄芪蜜炙，各一两  加白术半两  甘草炙，一分　 \n上锉，每服三五钱，小麦百余粒同煎服。", "白话": "〔主治〕治诸虚之体常自汗，惊惕不宁。〔组成·照录〕左顾牡蛎（米泔浸洗，煅透）、麻黄根、黄芪（蜜炙）各一两，加白术半两，甘草（炙）一分。〔方义〕牡蛎敛汗潜镇，麻黄根止汗，黄芪、白术、甘草益气固表，小麦养心，为益气固表、敛汗定惊之散。〔服法〕上药锉碎，每服三五钱，加小麦百余粒同煎服。"}, {"source": "条682｜《仁斋直指方论（附补遗）》卷十一·十四友丸", "原文": "《仁斋直指方论（附补遗）》卷十一：“十四友丸。治心血俱虚，怔忡惊惕。 　\n柏子仁研、远志肉姜汁腌，焙、酸枣仁汤浸，去皮，隔纸炒香、紫石英煅、熟干地黄、川当归、白茯苓、白茯神、人参、黄芪炙、阿胶炒、辣桂、龙齿研，各一两  朱砂半两，研　 \n上细末，炼蜜丸桐子大。每三四十丸，食后枣汤下。", "白话": "〔主治〕治心血俱虚，怔忡惊惕。〔组成·照录〕柏子仁（研）、远志肉（姜汁腌，焙）、酸枣仁（汤浸，去皮，隔纸炒香）、紫石英（煅）、熟干地黄、川当归、白茯苓、白茯神、人参、黄芪（炙）、阿胶（炒）、辣桂、龙齿（研）各一两，朱砂半两（研）。〔方义〕参、芪、苓、地、归、胶气血双补，枣仁、柏子仁、茯神、远志安神，紫石英、龙齿、朱砂重镇，辣桂温阳，为补心血、镇心神之丸。〔制法·服法〕上为细末，炼蜜丸如梧桐子大，每服三四十丸，食后枣汤下。"}, {"source": "条683｜《仁斋直指方论（附补遗）》卷十一·人参远志丸", "原文": "《仁斋直指方论（附补遗）》卷十一：“人参远志丸圣惠方。治气不足，惊悸健忘，神思不宁。 　\n天门冬去心、白茯苓、菖蒲各七钱半  人参去芦、远志去心、酸枣仁、黄芪蜜炙，各半两  桔梗、丹砂、官桂去皮，各二钱半　 \n上为末，蜜丸如豆大。每服二十丸至三十丸，米汤下。", "白话": "〔主治〕治气不足，惊悸健忘，神思不宁（圣惠方）。〔组成·照录〕天门冬（去心）、白茯苓、菖蒲各七钱半，人参（去芦）、远志（去心）、酸枣仁、黄芪（蜜炙）各半两，桔梗、丹砂、官桂（去皮）各二钱半。〔方义〕参、芪、苓、草（桔梗载药上行）益气，二冬、枣仁养心，菖蒲、远志安神益智，丹砂镇心，官桂温阳，为益气安神之丸。〔制法·服法〕上为末，蜜丸如绿豆大，每服二十至三十丸，米汤下。"}, {"source": "条684｜《仁斋直指方论（附补遗）》卷十一·加味定志丸", "原文": "《仁斋直指方论（附补遗）》卷十一：“加味定志丸。治痰迷心膈，惊悸怔忡。 　\n远志去心，二两  人参一两  菖蒲二两  白茯苓三两  琥珀、郁金各五钱　 \n上为细末，炼蜜丸如梧子大，朱砂为衣，每服二十丸，米汤下。", "白话": "〔主治〕治痰迷心膈，惊悸怔忡。〔组成·照录〕远志（去心）二两，人参一两，菖蒲二两，白茯苓三两，琥珀、郁金各五钱。〔方义〕定志丸（远志、菖蒲、人参、茯苓）益心定志，加琥珀镇心、郁金解郁化痰，为化痰开窍、安神定志之丸。〔制法·服法〕上为细末，炼蜜丸如梧桐子大，朱砂为衣，每服二十丸，米汤下。"}, {"source": "条685｜《仁斋直指方论（附补遗）》卷十一·朱雀丸", "原文": "《仁斋直指方论（附补遗）》卷十一：“朱雀丸。治心病怔忪不止。 　\n白茯神二两，净  沉香半两 　 \n上细末，炼蜜丸小豆大。每三十丸，人参煎汤下。", "白话": "〔主治〕治心病怔忪不止。〔组成·照录〕白茯神二两（净），沉香半两。〔方义〕茯神养心安神，沉香降气纳肾，二味交通心肾，为治怔忪之小丸。〔制法·服法〕上为细末，炼蜜丸如小豆大，每服三十丸，人参煎汤下。"}, {"source": "条686｜《仁斋直指方论（附补遗）》卷十一·养心汤", "原文": "《仁斋直指方论（附补遗）》卷十一：“养心汤。治心虚血少，惊惕不宁。 　\n黄芪炙、白茯苓、茯神、半夏曲、当归、川芎各半两  远志取肉，姜汁腌，焙、辣桂柏子仁、酸枣仁浸，去皮，隔纸炒香、北五味子、人参各一分  甘草炙，四钱　 \n上粗末。每服三钱，姜五片，枣二枚煎，食前服。加槟榔、赤茯苓，治停水怔悸。", "白话": "〔主治〕治心虚血少，惊惕不宁。〔组成·照录〕黄芪（炙）、白茯苓、茯神、半夏曲、当归、川芎各半两，远志（取肉，姜汁腌，焙）、辣桂、柏子仁、酸枣仁（浸，去皮，隔纸炒香）、北五味子、人参各一分，甘草（炙）四钱。〔方义〕参、芪、苓、草益气，归、芎养血，茯神、远志、柏子仁、枣仁、五味子养心安神，辣桂温阳，半夏曲化痰和胃，为益气养血、安神定悸之汤。〔服法〕上为粗末，每服三钱，生姜五片、大枣二枚煎，食前服。〔加减〕加槟榔、赤茯苓，治停水怔悸。"}, {"source": "条687｜《仁斋直指方论（附补遗）》卷十一·姜术汤", "原文": "《仁斋直指方论（附补遗）》卷十一：“姜术汤。治虚证停饮怔忪。 　\n白姜生、白术、茯苓、半夏曲各半两  辣桂、甘草炙，各一分　 \n上锉，每服三钱，姜、枣煎服。", "白话": "〔主治〕治虚证停饮之怔忪。〔组成·照录〕白姜（生）、白术、茯苓、半夏曲各半两，辣桂、甘草（炙）各一分。〔方义〕白姜、辣桂温中化饮，白术、茯苓健脾利水，半夏曲化痰，甘草和中，为温中化饮、定悸之汤。〔服法〕上药锉碎，每服三钱，生姜、大枣煎服。"}, {"source": "条688｜《仁斋直指方论（附补遗）》卷十一·温胆汤", "原文": "《仁斋直指方论（附补遗）》卷十一：“温胆汤。治心胆虚怯，触事多惊。亦治水气怔悸。 　\n半夏制、枳壳制、白茯苓各一两 橘红一两半 甘草炙，半两　 \n上锉，每服三钱半，姜七片，枣二枚，刮青竹皮一块如钱大，煎服。或加制远志尤妙。", "白话": "〔主治〕治心胆虚怯，触事多惊；也治水气怔悸。〔组成·照录〕半夏（制）、枳壳（制）、白茯苓各一两，橘红一两半，甘草（炙）半两。〔方义〕半夏、橘红、枳壳理气化痰，茯苓利水宁心，炙甘草和中，加青竹皮清热除烦。〔服法〕上药锉碎，每服三钱半，生姜七片、大枣二枚、刮青竹皮一块如钱大煎服；或加制远志尤妙。"}, {"source": "条689｜《仁斋直指方论（附补遗）》卷十一·茯苓甘草汤", "原文": "《仁斋直指方论（附补遗）》卷十一：“茯苓甘草汤。治心下停水忪悸。 　\n茯苓、桂枝各二两 甘草炙，一两 生姜三两　 \n上锉。每服四钱，水煎服。", "白话": "〔主治〕治心下停水之忪悸。〔组成·照录〕茯苓、桂枝各二两，甘草（炙）一两，生姜三两。〔方义〕茯苓利水，桂枝通阳，生姜散饮，甘草和中，为温阳化饮、定悸之经方（《伤寒论》茯苓甘草汤）。〔服法〕上药锉碎，每服四钱，水煎服。"}, {"source": "条690｜《仁斋直指方论（附补遗）》卷十一·苏合香丸（调服法）", "原文": "《仁斋直指方论（附补遗）》卷十一：“苏合香丸用枣汤调开，吞震灵丹，治心气不敛，怔忪头运。", "白话": "〔服法·主治〕苏合香丸用枣汤调开，送吞震灵丹，治心气不敛、怔忪头晕。〔组成·服法〕原稿未载组成，仅记调服法。〔方义〕苏合香丸芳香开窍、温通心气，配震灵丹镇摄，治心气不敛之怔忪。"}, {"source": "条691｜《仁斋直指方论（附补遗）》卷十三·加减理中汤", "原文": "《仁斋直指方论（附补遗）》卷十三：“加减理中汤。人参 白术 干姜 甘草（炙,各等分）……若悸多，加茯苓一两。", "白话": "〔方名·组成·照录〕加减理中汤：人参、白术、干姜、甘草（炙，各等分）……（原稿节略）若悸多，加茯苓一两。〔方义〕理中汤温中健脾，悸多者加茯苓利水宁心。〔服法〕水煎服（原稿未详载）。"}, {"source": "条692｜《郑氏家传女科万金方·胎前门》上卷·大圣散", "原文": "《郑氏家传女科万金方·胎前门》上卷：“第六问：妊娠心惊神悸，两胁膨胀，腹满连脐急痛，坐卧不安，气急逼迫胎惊者何？\n答曰：胎气既成，五脏安养，皆因气闷，或为喧呼，心怯悸乱，致令胎惊，筋骨伤痛，四大不安，急服大圣散安胎保孕。大圣散。 　\n白茯苓、川芎、麦冬、当归、黄芪各一两，蜜水炙 木香不见火 人参、甘草炙，各五分　 \n上者㕮咀。每服四钱，水盏半，加生姜五片，煎七分，去渣，不拘时温服。", "白话": "〔问答·主治〕第六问：妊娠心惊神悸，两胁膨胀，腹满连脐急痛，坐卧不安，气急逼迫而致胎惊者，是什么缘故？答曰：胎气已成，五脏安养，皆因气闷，或因喧呼惊扰，心怯悸乱，致令胎惊，筋骨伤痛，四大不安——急服大圣散安胎保孕。〔组成·照录〕白茯苓、川芎、麦冬、当归、黄芪各一两（蜜水炙），木香（不见火），人参、甘草（炙）各五分。〔方义〕参、芪、苓、草益气，归、芎、麦冬养血滋阴，木香理气安胎，为益气养血、安胎定悸之散。〔服法〕上药㕮咀，每服四钱，水一盏半加生姜五片煎至七分，去渣，不拘时温服。"}, {"source": "条693｜《郑氏家传女科万金方·产后门》·平补镇心丸、加味温胆汤", "原文": "《郑氏家传女科万金方·产后门》：“产后惊悸，精神恍惚，夜卧不宁，此症心血少故也，宜服平补镇心丸主之，或加味温胆汤。平补镇心丸： 　\n茯神 五味 车前子 远志 麦冬 姜制 山药 官桂 天冬 熟地 人参 龙齿 枣仁　 \n朱砂为衣，蜜丸。空心服。\n加味温胆汤：枣仁 远志 茯神 人参 熟地 五味 煎服。", "白话": "〔主治·论治〕产后惊悸，精神恍惚，夜卧不宁，此症由心血少所致，宜以平补镇心丸主治，或用加味温胆汤。〔组成·照录〕平补镇心丸：茯神、五味、车前子、远志、麦冬（姜制）、山药、官桂、天冬、熟地、人参、龙齿、枣仁；朱砂为衣，蜜丸，空腹服。加味温胆汤：枣仁、远志、茯神、人参、熟地、五味，煎服。〔方义〕平补镇心丸养心肾、镇心神（与条626、条661 同法）；加味温胆汤以温胆汤意加枣仁、远志、茯神、人参、熟地、五味养心安神。"}, {"source": "条694｜《御药院方》卷一·生犀丸", "原文": "《御药院方》卷一：“生犀丸。主心虚喜忘，烦悸，风涎不利，聪明耳目。治诸风颤掉及治三十六种风。益精神，壮心气，或多健忘，寝寐之惊心，常似忧，或忪，或动，往往欲倒状，类暗风，四肢颤掉，多生怯怕，每起烦躁，悲涕愁煎，并皆属心脏气亏，宜服此以镇心神。 　\n生犀镑，一两 天麻炙黄，半两 败龟酥炙，半两 牛黄研一分 茯神去皮，一分 远志去心，一分 人参去芦头，一分 肉桂去粗皮，一分 龙齿酥炙黄，一分 朱砂另研", "白话": "〔功效·主治〕主心虚喜忘，烦悸，风涎不利，聪明耳目；治诸风颤掉及三十六种风。益精神，壮心气；或多健忘，睡眠中惊心，常似忧，或忪悸，或心动，往往欲倒，类似暗风，四肢颤掉，多生怯怕，每起即烦躁，悲泣愁煎——皆属心脏气亏，宜服此以镇心神。〔组成·照录〕生犀（镑）一两，天麻（炙黄）半两，败龟（酥炙）半两，牛黄（研）一分，茯神（去皮）一分，远志（去心）一分，人参（去芦头）一分，肉桂（去粗皮）一分，龙齿（酥炙黄）一分，朱砂（另研）一分，麝香（另研）半两，龙脑（研）一分，石菖蒲（锉）半两，"}, {"source": "条695｜《御药院方》卷一·石膏丸", "原文": "《御药院方》卷一：“石膏丸。治诸风痰涎，头痛目眩，旋欲晕倒，心忪悸动，恍惚不宁，神思昏愦，肢体倦疼，颈项强硬，手足麻痹。常服除偏正头疼。  \n石膏另研、白附子炮、半夏汤洗七次、川芎、天南星炮、白僵蚕炒去丝、菊花拣净、陈皮去白、旋复花旋覆花、天麻以上各一两 全蝎炒，半两  \n上件一十一味为细末，生姜汁浸，浸饼为丸，如梧桐子大。每服五十丸，渐加一百丸，食后生姜汤下。忌粘黏滑生硬等物。", "白话": "〔主治〕治诸风痰涎：头痛目眩，旋转欲晕倒，心忪悸动，恍惚不宁，神思昏愦，肢体倦疼，颈项强硬，手足麻痹；常服能除偏正头痛。〔组成·照录〕石膏（另研）、白附子（炮）、半夏（汤洗七次）、川芎、天南星（炮）、白僵蚕（炒，去丝）、菊花（拣净）、陈皮（去白）、旋复花（旋覆花）、天麻以上各一两，全蝎（炒）半两。〔方义〕石膏、菊花清热，天麻、僵蚕、全蝎、白附、南星、半夏祛风化痰，川芎、旋覆花、陈皮理气降逆，为祛风化痰、清热定悸之丸。〔制法·服法〕上十一味为细末，生姜汁浸，浸饼为丸如梧桐子大，"}, {"source": "条696｜《御药院方》卷一·辟风丹", "原文": "《御药院方》卷一：“辟风丹。治诸风疾无问新久者。半身不遂，口眼斜，语言謇涩，精神昏愦，痰涎并多，咽嗌不利，及风虚头痛目眩，旋晕欲倒，或心忪健忘，恍惚不宁，手足麻痹，颤掉无力，筋脉拘急，骨节烦疼，行步艰难，并宜服之。  \n独活洗去土，焙干、防风去芦头、吴白芷、桂、藁本去土、麻黄去节，微炒、白芍药去皮、天麻以上各一两 川乌头炮制，去皮捶碎，炒黄，半两 藿香叶去土，半两川芎七钱 羌活去苗，三钱 甘草锉炒", "白话": "〔主治〕治诸风疾不分新久：半身不遂，口眼斜，语言謇涩，精神昏愦，痰涎多，咽嗌不利，及风虚头痛目眩、旋转欲倒，或心忪健忘、恍惚不宁，手足麻痹、颤掉无力、筋脉拘急、骨节烦疼、行步艰难，均宜服。〔组成·照录〕独活（洗去土，焙干）、防风（去芦头）、吴白芷、桂、藁本（去土）、麻黄（去节，微炒）、白芍药（去皮）、天麻以上各一两，川乌头（炮制，去皮捶碎，炒黄）半两，藿香叶（去土）半两，川芎七钱，羌活（去苗）三钱，甘草（锉，炒）半两，白花蛇（酒浸，去皮骨）半两，白僵蚕（炒黄）三钱，全蝎（去毒"}, {"source": "条697｜《御药院方》卷一·芎天麻丸", "原文": "《御药院方》卷一：“芎天麻丸。清利头目，消风化痰，宽胃利膈。心忪烦闷，旋晕欲倒，颈项紧急，肩背拘倦，神昏多睡，肢体烦痛，皮肤瘙痒，偏正头痛，鼻塞声重，面目浮肿，并宜服之。  \n芎二两 天麻半两   \n上二味为细末，炼蜜为丸。每一两半作二十丸。每服一丸，食后细嚼，茶酒任下。", "白话": "〔功效·主治〕清利头目，消风化痰，宽胃利膈。治心忪烦闷，旋晕欲倒，颈项紧急，肩背拘倦，神昏多睡，肢体烦痛，皮肤瘙痒，偏正头痛，鼻塞声重，面目浮肿，均宜服。〔组成·照录〕芎二两，天麻半两。〔方义〕川芎活血祛风、上行头目，天麻熄风定眩，二味为治风眩心忪之小丸。〔制法·服法〕上二味为细末，炼蜜为丸，每一两半作二十丸，每服一丸，食后细嚼，茶或酒任下。"}, {"source": "条697｜《御药院方》卷五·小半夏汤", "原文": "《御药院方》卷五：“小半夏汤。治诸呕哕，心下坚痞，膈间有痰水，眩悸。  \n半夏五两，汤洗七次 白茯苓去皮，用三两   \n上㕮咀，每服称半两，水三盏煎至一盏，称生姜四钱，取自然汁投药中，更煎一两沸，热吃，不拘时候。", "白话": "〔主治〕治各种呕吐呃逆，胃脘坚硬痞满，膈间有痰水，眩晕心悸。〔组成·照录〕半夏五两（汤洗七次）、白茯苓（去皮）三两。〔方义〕半夏化痰降逆止呕，茯苓健脾渗湿化饮，痰水一去则眩悸自止。〔制法·服法〕上药切碎，每次称取半两，用水三盏煎至一盏；另称生姜四钱，取自然汁投入药中，再煎一两沸，热服，不拘时候。"}, {"source": "条698｜《御药院方》卷五·白术茯苓丸", "原文": "《御药院方》卷五：“白术茯苓丸。治三焦气涩，停痰不消，胸膈痞闷，腹胁胀满，咳嗽涎甚，咽嗌干痛，心忪悸动，头目眩晕，寒热时作，肢节疼痛，呕吐清水，神昏多倦，不欲饮食。  \n白茯苓、白术各半两，白者 天南星、白附子各一两 白矾三分 半夏三两，并生用  \n上为细末，白面糊和丸，如梧桐子大。每服二三十丸，生姜汤下，不拘时候。", "白话": "〔主治〕治三焦气机涩滞、痰饮停积不化，胸膈痞闷，腹胁胀满，咳嗽痰涎甚多，咽喉干痛，心悸动，头目眩晕，寒热时作，肢节疼痛，呕吐清水，神昏多倦，不欲饮食。〔组成·照录〕白茯苓、白术各半两（取白者），天南星、白附子各一两，白矾三分，半夏三两（以上并生用）。〔方义〕苓、术健脾燥湿以绝生痰之源，南星、白附、半夏化痰散结，白矾祛痰，痰消则悸眩自平。〔制法·服法〕共为细末，白面糊和丸如梧桐子大，每服二三十丸，生姜汤送下，不拘时候。"}, {"source": "条699｜《御药院方》卷五·半夏利膈丸", "原文": "《御药院方》卷五：“半夏利膈丸。治风痰郁甚，头疼目眩，咽膈不利，涕唾稠粘黏，胸中烦满，酒癖停饮，呕逆恶心，胁下急痛，腹中水声，神思昏愦，心忪面热，止嗽化痢。  \n白术、人参、白茯苓去皮、白矾生、滑石、贝母各一两 天南星生用，一两半 白附子生二两 半夏汤洗，三两   \n上为细末，水面糊为丸，如梧桐子大。每服三十丸，食后生姜汤送下。", "白话": "〔主治〕治风痰郁结甚重，头痛目眩，咽喉胸膈不利，鼻涕唾液稠粘，胸中烦满，酒癖停饮，呕逆恶心，胁下急痛，腹中水声，神思昏乱，心悸面热；并能止嗽化痢。〔组成·照录〕白术、人参、白茯苓（去皮）、白矾（生）、滑石、贝母各一两，天南星（生用）一两半，白附子（生）二两，半夏（汤洗）三两。〔方义〕苓、术、参健脾化痰，白附、南星搜风痰，滑石、贝母清热化痰，风痰去则悸眩除。〔制法·服法〕共为细末，水面糊为丸如梧桐子大，每服三十丸，食后生姜汤送下。"}, {"source": "条700｜《御药院方》卷五·润肺丸", "原文": "《御药院方》卷五：“润肺丸。治肺气不调，咳嗽声重，日久不止，痰涕结搏，咽嗌不利，心神烦躁，头目昏重，精神不爽，心忪烦悸，喉中呀呷，逐气有声，一切痰实并皆治之。  \n朱砂水飞、五灵脂微炒，各二两 苦葶苈隔纸炒、杏仁去皮尖，麸炒、半夏曲各一两   \n上为细末。生姜汁面糊为丸，如梧桐子大。每服四十丸，食后生姜汤送下。", "白话": "〔主治〕治肺气不调，咳嗽声重，日久不止，痰涕结聚搏结，咽喉不利，心神烦躁，头目昏重，精神不爽，心悸烦乱，喉中呀呷作声，逐气有声；一切痰实之证并皆治之。〔组成·照录〕朱砂（水飞）、五灵脂（微炒）各二两，苦葶苈（隔纸炒）、杏仁（去皮尖，麸炒）、半夏曲各一两。〔方义〕杏仁、葶苈宣降肺气，半夏曲化痰，五灵脂行血，朱砂镇心，肺气降、痰浊化则悸烦自安。〔制法·服法〕共为细末，生姜汁面糊为丸如梧桐子大，每服四十丸，食后生姜汤送下。"}, {"source": "条701｜《御药院方》卷五·锦朱丸", "原文": "《御药院方》卷五：“锦朱丸。治膈痰风厥，头目昏痛，眼黑旋晕，怔忪恶心，惊悸恍惚，梦寐不安，渐发冒昧，不知人事。　　\n乳香研、朱砂研、白矾灰研、皂荚子炮裂，为末、铅白霜研、铁粉研，各一两 半夏曲二两 　　\n上为细末，生姜汁面糊和丸，如绿豆大。每服十五、二十丸，生姜汤下。惊悸语涩，金银汤下，或荆芥汤下。", "白话": "〔主治〕治膈痰风厥，头目昏痛，眼前发黑、旋转眩晕，怔忡恶心，惊悸恍惚，睡眠不安，渐渐神识昏蒙、不省人事。〔组成·照录〕乳香（研）、朱砂（研）、白矾灰（研）、皂荚子（炮裂，为末）、铅白霜（研）、铁粉（研）各一两，半夏曲二两。〔方义〕朱砂、铁粉、铅白霜重镇安神，皂荚、白矾、半夏曲化痰开闭，乳香行气活血，痰化神安则惊悸止。〔制法·服法〕共为细末，生姜汁面糊和丸如绿豆大，每服十五至二十丸，生姜汤送下；惊悸语涩者，用金银汤或荆芥汤送下。"}, {"source": "条702｜《御药院方》卷六·辰砂远志丸", "原文": "《御药院方》卷六：“辰砂远志丸。安神镇心，补肾益志。治惊悸，消风痰，止头眩。  \n石菖蒲、远志去心、人参、茯神、川芎、山芋、铁粉、麦门冬、天麻、细夏曲、天南星锉，炒黄、白附子生用，以上各一两  细辛半两  辰砂一两四钱，入药六钱，为末  \n上为细末，生姜五两取汁，入水煮面糊为丸，如绿豆大，以朱砂为衣。每服三五十丸，临卧生姜汤下。", "白话": "〔功用·主治〕安神镇心，补肾益志；治惊悸，消风痰，止头眩。〔组成·照录〕石菖蒲、远志（去心）、人参、茯神、川芎、山芋、铁粉、麦门冬、天麻、细夏曲、天南星（锉，炒黄）、白附子（生用）以上各一两，细辛半两，辰砂一两四钱（入药六钱，为末）。〔方义〕菖蒲、远志、茯神、辰砂安神定志，参、山芋益气，天麻、南星、白附息风化痰，铁粉镇心，为镇心化痰、补肾益志之剂。〔制法·服法〕共为细末，生姜五两取汁，入水煮面糊为丸如绿豆大，以朱砂为衣，每服三五十丸，临卧生姜汤送下。"}, {"source": "条703｜《御药院方》卷六·镇心丸", "原文": "《御药院方》卷六：“镇心丸。治心气不足，志意不定，精神恍惚，语言错妄，忪悸烦乱，愁忧惨戚，喜惊多恐，健忘少睡，夜多异梦，寤即惊魇，或发狂眩暴不知人，并宜服之。  \n预知子去皮、人参去芦头、白茯苓去皮、远志去心、石菖蒲、山药、枸杞子拣净、黄精蒸熟、柏子仁、地骨皮去土、茯神去木、朱砂飞研，各等分  \n上件为细末。炼蜜为丸，每两作二十丸，更以朱砂为衣。每服丸，细嚼，人参汤下，不计时候。", "白话": "〔主治〕治心气不足，意志不定，精神恍惚，语言错乱妄言，心悸烦乱，忧愁悲伤，善惊多恐，健忘少睡，夜多怪梦，醒来即惊魇，或发狂眩晕、暴然不省人事，均宜服之。〔组成·照录〕预知子（去皮）、人参（去芦头）、白茯苓（去皮）、远志（去心）、石菖蒲、山药、枸杞子（拣净）、黄精（蒸熟）、柏子仁、地骨皮（去土）、茯神（去木）、朱砂（飞研）各等分。〔方义〕参、苓、薯蓣、黄精、枸杞补心脾肾之虚，菖蒲、远志、柏仁、茯神、朱砂安神定志，地骨皮清虚热，为补虚镇心之丸。〔制法·服法〕共为细末，炼蜜为丸，每"}, {"source": "条704｜《御药院方》卷六·人参远志丸", "原文": "《御药院方》卷六：“人参远志丸。治心气不安，惊悸恍惚，神思不宁。 \n 人参去芦 远志去心，半钱 黄芪半两 酸枣仁半两 桂二钱半 桔梗炒黄，二钱半 丹砂二钱半 天门冬七钱半 菖蒲七钱 白茯苓去皮，七钱半  \n上为细末，蜜为丸，如豆大。每服二十丸，米饮下，加至三十丸，下不拘时候。", "白话": "〔主治〕治心气不安，惊悸恍惚，神思不宁。〔组成·照录〕人参（去芦）、远志（去心）半钱、黄芪半两、酸枣仁半两、桂二钱半、桔梗（炒黄）二钱半、丹砂二钱半、天门冬七钱半、菖蒲七钱、白茯苓（去皮）七钱半。〔方义〕人参、黄芪益心气，远志、菖蒲、茯苓、酸枣仁养心安神，丹砂镇心，天冬滋阴，桂温心阳，桔梗载药上行。〔制法·服法〕共为细末，蜜为丸如豆大，每服二十丸，米饮送下，渐加至三十丸，不拘时候。"}, {"source": "条705｜《御药院方》卷六·人参补虚汤", "原文": "《御药院方》卷六：“人参补虚汤。治虚劳，少气不足，四肢困弱，嗜卧少力，心中悸动，夜多盗汗。常服补诸虚不足，健中进食。  \n黄芪、人参、陈皮去白、当归炙、桂去皮、细辛去叶土、前胡、白芍药去皮、甘草炙、白茯苓去皮、麦门冬去心、半夏炮、熟干地黄以上各二两 \n上一十二味为细末。每服三钱，水一大盏，入生姜五片，枣两个，煎至七分，稍热服，食前。", "白话": "〔主治〕治虚劳，短气不足，四肢困弱，嗜卧乏力，心中悸动，夜间盗汗。常服补诸虚不足，健运中焦、增进饮食。〔组成·照录〕黄芪、人参、陈皮（去白）、当归（炙）、桂（去皮）、细辛（去叶土）、前胡、白芍药（去皮）、甘草（炙）、白茯苓（去皮）、麦门冬（去心）、半夏（炮）、熟干地黄以上各二两。〔方义〕参、芪、苓、草配归、地、芍气血双补，麦冬滋阴，桂、细辛温阳，陈皮、前胡、半夏理气化痰，为虚劳心悸平补之剂。〔制法·服法〕上十二味为细末，每服三钱，用水一大盏，加生姜五片、大枣二枚，煎至七分，稍"}, {"source": "条706｜《御药院方》卷六·乐令黄芪汤", "原文": "《御药院方》卷六：“乐令黄芪汤。治虚劳少气，胸心痰冷，时时惊惕，心中悸动，手脚逆冷，体常自汗，补诸不足，五脏六腑虚损，肠鸣，风湿，营卫不调，百病。又治风里急。  \n黄芪、人参去芦、陈皮去白、当归、桂心、细辛去叶、前胡、芍药、甘草炙、茯苓去皮、麦门冬去心，各一钱 生姜二钱半 半夏汤浸七次，一钱一字 大枣一个  \n上㕮咀，都用水四盏煎至二盏半，去滓，分二服。", "白话": "〔主治〕治虚劳短气，胸中心窝痰冷，时时惊惕，心中悸动，手足逆冷，身体常自汗；补诸不足，治五脏六腑虚损、肠鸣、风湿、营卫不调诸病。又治风里急。〔组成·照录〕黄芪、人参（去芦）、陈皮（去白）、当归、桂心、细辛（去叶）、前胡、芍药、甘草（炙）、茯苓（去皮）、麦门冬（去心）各一钱，生姜二钱半，半夏（汤浸七次）一钱一字，大枣一个。〔方义〕即十全大补、温经汤意合方，参、芪、归、芍补气血，桂、辛、姜温阳，夏、陈化痰，为虚劳心悸手足厥冷之方。〔制法·服法〕上药切碎，都用水四盏煎至二盏半，去渣"}, {"source": "条707｜《御药院方·卷六》·牛黄铁粉丸", "原文": "《御药院方·卷六》：“牛黄铁粉丸。镇定心气，止惊悸不宁。　　\n牛黄研，二钱半、铁粉研、紫石英研、白石英研、酸枣仁炒、茯神去木、陈皮去白、人参去芦头，各一两　　\n上为细末。入研者匀，白面糊和丸，如梧桐子大。每服五十丸，煎人参汤下，食前服。", "白话": "〔功用·主治〕镇定心气，止惊悸不宁。〔组成·照录〕牛黄（研）二钱半、铁粉（研）、紫石英（研）、白石英（研）、酸枣仁（炒）、茯神（去木）、陈皮（去白）、人参（去芦头）各一两。〔方义〕牛黄、铁粉、二石英重镇清心，枣仁、茯神养心安神，参、陈益气和中，共成镇心定悸之丸。〔制法·服法〕共为细末，与研药拌匀，白面糊和丸如梧桐子大，每服五十丸，煎人参汤送下，食前服。"}, {"source": "条708｜《御药院方》卷十一·人参荆芥煮散", "原文": "《御药院方》卷十一：“人参荆芥煮散。治妇人血风劳气攻刺疼痛，四肢无力，不思饮食，多困黄瘦，胸膈痞满，经水不利，心多怔忪，并治之。  \n荆芥穗四两 柴胡、秦艽去芦头，洗去泥、肉豆蔻、白芷、黄芪、鳖甲醋炙黄，洗净、桔梗、官桂去皮，各二两 当归、川芎、蓬莪术、麦门冬去心、芍药、人参、茯苓、海桐皮、甘草炙、枳壳麸炒，去穰瓤、熟干地黄、酸枣仁、木香各一两 沉香、槟榔各半两  \n上件罗为末，每服三钱，水一盏，", "白话": "〔主治〕治妇人血风劳气攻冲刺痛，四肢无力，不思饮食，多困倦而黄瘦，胸膈痞满，月经不利，心多怔忡，皆治之。〔组成·照录〕荆芥穗四两，柴胡、秦艽（去芦头，洗去泥）、肉豆蔻、白芷、黄芪、鳖甲（醋炙黄，洗净）、桔梗、官桂（去皮）各二两，当归、川芎、蓬莪术、麦门冬（去心）、芍药、人参、茯苓、海桐皮、甘草（炙）、枳壳（麸炒，去穰瓤）、熟干地黄、酸枣仁、木香各一两，沉香、槟榔各半两。〔方义〕荆芥、柴胡、秦艽、白芷疏风，参、芪、归、地、芍补气血，鳖甲、麦冬滋阴，莪术、枳壳、木香、沉香行气活血"}, {"source": "条709｜《御药院方》卷十一·大镇心丸", "原文": "《御药院方》卷十一：“大镇心丸。治小儿精神不爽，寝寐多惊，心忪恐悸，四肢战掉，举动欲倒，状类暗风，或烦躁而多啼。退惊风，化痰涎，壮心气，益精神。  \n生犀角镑，末、铁粉研，各一两 羚羊角镑，末、龟甲镑，末、赤箭各半两 牛黄研、茯神去木、远志去心、真珠末研、人参、桂去粗皮、蛇蜕皮炙，令焦黄、天竺黄研、龙脑各一分，研 麝香研、菖蒲各半两 丹砂研，半分 金箔研、银铂研，各五十片  \n上一十九味捣研为末，", "白话": "〔主治〕治小儿精神不爽，睡眠多惊，心悸恐惧，四肢颤抖，举动欲倒，状如暗风之证，或烦躁而多啼哭。能退惊风，化痰涎，壮心气，益精神。〔组成·照录〕生犀角（镑末）、铁粉（研）各一两，羚羊角（镑末）、龟甲（镑末）、赤箭各半两，牛黄（研）、茯神（去木）、远志（去心）、真珠末（研）、人参、桂（去粗皮）、蛇蜕皮（炙令焦黄）、天竺黄（研）、龙脑各一分（研），麝香（研）、菖蒲各半两，丹砂（研）半分，金箔（研）、银铂（研）各五十片。〔方义〕犀角、羚羊角、牛黄清心凉肝定惊，铁粉、真珠、金箔、银箔重"}, {"source": "条710｜《御药院方》卷十一·丹砂镇心丸", "原文": "《御药院方》卷十一：“丹砂镇心丸。治小儿心神不宁，有时惊悸、目睛偏视、痰涎不利，甚则瘛疭。服之安镇心神，罢惊止搐。  \n朱砂一两，飞研 牛黄一钱 生龙脑、麝香各一钱 铅白霜二钱 天竺黄二钱，以上各细研 天麻明大者，二两 人参半两 茯苓半两，白者，去黑皮 甘草炙，半两  \n上一十味为细末，与研药同研匀细，炼蜜和丸，如鸡头实大。每服一丸，煎金银薄荷汤化下。", "白话": "〔主治〕治小儿心神不宁，有时惊悸、眼睛偏视、痰涎不利，甚则抽搐。服之安镇心神，止惊止搐。〔组成·照录〕朱砂一两（飞研），牛黄一钱，生龙脑、麝香各一钱，铅白霜二钱，天竺黄二钱（以上各细研），天麻（明大者）二两，人参半两，茯苓半两（白者，去黑皮），甘草（炙）半两。〔方义〕朱砂、铅白霜、牛黄、龙脑、麝香镇惊开窍，天竺黄、天麻化痰息风，参、苓、草益气和中。〔制法·服法〕上十味为细末，与研药同研匀细，炼蜜和丸如鸡头实大，每服一丸，煎金银薄荷汤化下。"}, {"source": "条711｜《御药院方》卷十一·禹余粮散", "原文": "《御药院方》卷十一：“禹余粮散。治气血伤冲任，虚损崩伤带漏，久而不断，或下如豆汁，或成片如肝，或五色相杂，或赤白相兼，脐腹冷痛，面体萎黄，心忪悸动，发热多汗，四肢困倦，饮食减少。  \n禹余粮醋淬、伏龙肝、赤石脂、白龙骨、牡蛎、乌鱼骨、桂去皮、浮石各等分  \n上件同为细末。每服三钱，煎乌梅汤调下，食前服。白多，加牡蛎、龙骨、乌鱼骨。赤多，加赤石脂、禹余粮。黄多，加伏龙肝、桂心，随病加治。", "白话": "〔主治〕治气血损伤冲任，虚损崩漏带下，久而不止，或下如豆汁，或成片如肝，或五色相杂，或赤白相兼，脐腹冷痛，面黄体瘦，心悸动，发热多汗，四肢困倦，饮食减少。〔组成·照录〕禹余粮（醋淬）、伏龙肝、赤石脂、白龙骨、牡蛎、乌鱼骨、桂（去皮）、浮石各等分。〔方义〕禹余粮、赤石脂、龙骨、牡蛎、乌贼骨收涩止崩，伏龙肝温中，桂温经，浮石软坚，为崩带兼心悸之方。〔制法·服法〕上药同为细末，每服三钱，煎乌梅汤调下，食前服。白带多者，加牡蛎、龙骨、乌鱼骨；赤带多者，加赤石脂、禹余粮；黄带多者，加伏"}, {"source": "条712｜《活幼心书》卷下·黄芪六一汤", "原文": "《活幼心书》卷下：“黄芪六一汤。治诸虚不足，烦躁惊悸目扬，身体软弱，不思饮食。  \n黄芪六两，蜜水涂炙 甘草一两，炙  \n上件㕮咀，每服二钱，水一盏，刺二枚，煎七分，无时温服。", "白话": "〔主治〕治诸虚不足，烦躁惊悸、两目上视，身体软弱，不思饮食。〔组成·照录〕黄芪六两（蜜水涂炙）、甘草一两（炙）。〔方义〕黄芪六、甘草一，取“六一”之比，大补脾肺之气，气旺则神安、惊悸可止。〔制法·服法〕上药切碎，每服二钱，用水一盏，加“刺二枚”（原稿如此），煎取七分，不拘时候温服。"}, {"source": "条713｜《活幼心书》卷下·茯神汤", "原文": "《活幼心书》卷下：“茯神汤。治心气不足，虚而惊悸，日常烦哭，及婴孩生下，羸瘦多惊，宜子母同服，自然有效。  \n茯神去皮木根，一两 人参去芦，半两 甘草炙，二钱 当归去芦尾，酒洗，半两  \n上件㕮咀，每服二钱，水一盏，煎七分，无时温服。有微热烦躁，入麦门冬去心同煎。", "白话": "〔主治〕治心气不足，虚弱而惊悸，日常烦哭；以及婴孩生下后羸瘦多惊，宜母子同服，自然有效。〔组成·照录〕茯神（去皮木根）一两、人参（去芦）半两、甘草（炙）二钱、当归（去芦尾，酒洗）半两。〔方义〕茯神、参、草益心气安神，当归养心血，母子同服则乳汁药力相济。〔制法·服法〕上药切碎，每服二钱，用水一盏，煎取七分，不拘时候温服。有微热烦躁者，加麦门冬（去心）同煎。"}, {"source": "条714｜《瑞竹堂经验方·羡补门》·益卫丹", "原文": "《瑞竹堂经验方·羡补门》：“益卫丹。治心脉结而散，肺脉浮而软，余脉如经，原其所自，思虑伤心，忧虑伤肺，盖心乃诸血之源，肺为诸气之候，心虚则血少，脉弱则气虚，遂致目涩、口苦，唇燥舌咸，甚则齿为之痛，鼻为之不利，怔忡白浊，腠理不密，易为感风寒，今以补气汤补气以养肺，益荣丹滋血以助心，荣卫日充，心肺戢治，诸疾自愈。  \n当归二两，去芦，酒浸焙 紫石英火煅，醋淬七次，研细，一两 柏子仁炒，另研、酸枣仁去壳", "白话": "〔主治〕治心脉结而散、肺脉浮而软，其余脉如常。推原其由，是思虑伤心、忧虑伤肺：心为诸血之源，肺为诸气之候（外候），心虚则血少，脉弱则气虚，于是目涩、口苦，唇燥舌咸，甚则牙齿作痛，鼻窍不利，怔忡白浊，腠理不密，易感风寒。今以补气汤补气以养肺，益荣丹滋血以助心，营卫日渐充盛，心肺得治，诸疾自愈。〔组成·照录〕当归二两（去芦，酒浸焙）、紫石英（火煅，醋淬七次，研细）一两、柏子仁（炒，另研）、酸枣仁（去壳）、小草、木香（不见火）、茯神（去木）、桑寄生、卷柏叶（酒炙）、熟地黄（洗净，酒"}, {"source": "条715｜《世医得效方》卷三·茯神汤", "原文": "《世医得效方》卷三：“茯神汤。治喜怒忧思悲恐惊所感，脏气不行，郁而生涎，结为饮，随气上厥，伏留阳经。心中忪悸，四肢缓弱，翕然面热，头目眩冒，如欲摇动。  \n人参、麦门冬去心、山药各二两 前胡、熟地黄洗，酒拌炒，各一两 枳壳去穰瓤，麸炒，三分 远志甘草水煮去心，姜汁拌炒，三分 白茯苓、茯神各一两半 半夏汤洗七次、黄芪炙，各一两 甘草半两  \n上锉散。每服四钱，流水盏半，姜五片，秫米一撮煎，食前服。", "白话": "〔主治〕治被喜、怒、忧、思、悲、恐、惊七情所感，脏气不行，郁而生涎，结为痰饮，随气上逆，伏留于阳经。心中悸动，四肢缓弱，骤然面热，头目眩晕，如欲摇动。〔组成·照录〕人参、麦门冬（去心）、山药各二两，前胡、熟地黄（洗，酒拌炒）各一两，枳壳（去穰瓤，麸炒）三分，远志（甘草水煮去心，姜汁拌炒）三分，白茯苓、茯神各一两半，半夏（汤洗七次）、黄芪（炙）各一两，甘草半两。〔方义〕参、芪、薯蓣、苓、草益气，地、麦、远志、茯神养心安神，半夏、前胡、枳壳化痰降气，气顺痰消则悸眩止。〔制法·服法"}, {"source": "条716｜《世医得效方》卷七·子午丸", "原文": "《世医得效方》卷七：“子午丸。治心肾俱虚，梦寐惊悸，体常自汗，烦闷短气，悲忧不乐，消渴引饮，漩下赤白，停凝浊甚，四体无力，眼昏，形容瘦悴，耳鸣，头晕，恶风怯冷。  \n榧子去壳，二两、莲肉去心、枸杞子、白龙骨、川巴戟去心、破故纸炒、真琥珀另研、芡实、苦楮实去壳、白矾枯、赤茯苓去皮、白茯苓去皮、文蛤、莲花须盐蒸、白牡蛎煅，各一两\n上为末，酒蒸肉苁蓉一斤二两，烂研为丸，梧桐子大，朱砂一两半重，细研为衣。", "白话": "〔主治〕治心肾俱虚，睡眠多梦惊悸，身体常自汗，烦闷短气，悲忧不乐，消渴引饮，小便赤白混浊、凝浊甚重，四肢无力，眼目昏花，形体瘦悴，耳鸣，头晕，恶风怯冷。〔组成·照录〕榧子（去壳）二两，莲肉（去心）、枸杞子、白龙骨、川巴戟（去心）、破故纸（炒）、真琥珀（另研）、芡实、苦楮实（去壳）、白矾（枯）、赤茯苓（去皮）、白茯苓（去皮）、文蛤、莲花须（盐蒸）、白牡蛎（煅）各一两。〔方义〕巴戟、故纸、莲须、芡实、楮实温肾固精，龙骨、牡蛎、琥珀、文蛤、白矾收涩安神，杞子、二苓补心脾，为心肾双补"}, {"source": "条717｜《世医得效方》卷七·清心丸", "原文": "《世医得效方》卷七：“清心丸。治经络热而梦泄，心怔怔恍惚。  \n大柏皮一两，去粗皮  \n上为末，入脑子一钱同研，炼蜜丸如梧子大。每服十五丸至十九丸，浓煎去心麦门冬汤下。", "白话": "〔主治〕治经络有热而梦中遗泄，心中怔忡恍惚。〔组成·照录〕大柏皮一两（去粗皮）。〔方义〕黄柏苦寒，清下焦与经络之热，热清则梦遗、怔忡自止。〔制法·服法〕上为末，加入脑子一钱同研，炼蜜为丸如梧子大，每服十五丸至十九丸，浓煎去心麦门冬汤送下。"}, {"source": "条718｜《世医得效方》卷八·十味温胆汤", "原文": "《世医得效方》卷八：“十味温胆汤。治心胆虚怯，触事易惊，梦寐不祥，异象感惑，遂致心惊胆慑，气郁生涎，涎与气搏，变生诸证。或短气悸乏，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。　　\n半夏汤洗七次、枳实去穰瓤，切，麸炒、陈皮去白，各三两 白茯苓去皮，两半 酸枣仁微炒 大远志去心，甘草水煮，姜汁炒，一两 北五味子、熟地黄切，酒炒、条参各一两 粉草五钱　　\n上锉散。每服四钱，水盏半，姜五片，枣一枚", "白话": "〔主治〕治心胆虚怯，遇事易惊，梦寐不祥，为异象所感，以致心惊胆慑，气郁生涎，涎与气相搏，变生诸证：或短气心悸乏力，或又自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。〔组成·照录〕半夏（汤洗七次）、枳实（去穰瓤，切，麸炒）、陈皮（去白）各三两，白茯苓（去皮）两半，酸枣仁（微炒）、大远志（去心，甘草水煮，姜汁炒）一两，北五味子、熟地黄（切，酒炒）、条参各一两，粉草五钱。〔方义〕即温胆汤加枣仁、远志、五味、熟地、人参，化痰定惊兼养心气阴，为心胆虚怯、惊悸短气之名方。〔制法·服法〕上"}, {"source": "条719｜《世医得效方》卷八·姜术汤", "原文": "《世医得效方》卷八：“姜术汤。治虚证停饮，怔忡。  \n白姜生、白术、茯苓、半夏曲各半两 辣桂、甘草炙，各一分  \n上锉散。每服三钱，水一盏，生姜三片，红枣一枚煎，温服，不拘时候。", "白话": "〔主治〕治虚证停饮、怔忡。〔组成·照录〕白姜（生）、白术、茯苓、半夏曲各半两，辣桂、甘草（炙）各一分。〔方义〕干姜、白术、茯苓温中健脾化饮，半夏曲化痰，桂通阳，饮去阳通则怔忡止。〔制法·服法〕上药锉散，每服三钱，用水一盏，加生姜三片、红枣一枚同煎，温服，不拘时候。"}, {"source": "条720｜《世医得效方》卷八·枣肉灵砂", "原文": "《世医得效方》卷八：“枣肉灵砂。专治虚人夜不得睡，梦中惊魇，自汗忪悸。  \n灵砂二分，研 人参半分 酸枣仁肉一分  \n上为末，枣肉丸，临卧时，枣汤吞下五七粒。", "白话": "〔主治〕专治虚弱之人夜间不得睡，梦中惊魇，自汗心悸。〔组成·照录〕灵砂二分（研）、人参半分、酸枣仁肉一分。〔方义〕灵砂重镇安神，参益气，枣仁养心敛汗，以枣肉为丸兼顾中焦。〔制法·服法〕上为末，以枣肉为丸，临卧时用枣汤吞下五七粒。"}, {"source": "条721｜《世医得效方》卷八·增损乐令汤", "原文": "《世医得效方》卷八：“增损乐令汤。治诸虚不足，小腹急痛，胁肋䐜胀，脐下虚满，胸中烦悸，面色痿黄，唇干口燥，手足逆冷，体常自汗，腰背强急，骨肉酸疼，咳嗽喘乏，不饮食。或因劳伤过度，或病后不复。  \n黄芪去芦、人参去芦、橘皮去白、当归去尾、桂心、细辛、前胡去芦、甘草、茯苓、麦门冬去心、芍药各二两 附子炮，去皮脐、熟地黄酒炒，各一两 半夏汤洗，二两半 远志三分，去心，炒  \n上锉散。每服三钱，水一盏半，", "白话": "〔主治〕治诸虚不足，小腹急痛，胁肋胀，脐下虚满，胸中烦悸，面色萎黄，唇干口燥，手足逆冷，身体常自汗，腰背强急，骨肉酸疼，咳嗽喘乏，不欲饮食；或因劳伤过度，或病后不复。〔组成·照录〕黄芪（去芦）、人参（去芦）、橘皮（去白）、当归（去尾）、桂心、细辛、前胡（去芦）、甘草、茯苓、麦门冬（去心）、芍药各二两，附子（炮，去皮脐）、熟地黄（酒炒）各一两，半夏（汤洗）二两半，远志三分（去心，炒）。〔方义〕即乐令黄芪汤加附子温肾回阳，参、芪、归、地气血双补，为虚劳烦悸、手足逆冷之重剂。〔制法"}, {"source": "条722｜《世医得效方》卷九·淡竹茹汤", "原文": "《世医得效方》卷九：“淡竹茹汤。治心虚烦闷，头疼，气短，内热不解，心中闷乱。及妇人产后，心虚，惊悸，烦闷欲绝。  \n麦门冬去心、小麦各二两半 甘草炙，一两 人参、白茯苓各一两半 半夏汤洗七次，二两  \n上锉散。每服四钱，水二盏，生姜七片，枣子三枚，淡竹茹一块如指大同煎，食煎服。虚劳烦闷，尤宜服之。", "白话": "〔主治〕治心虚烦闷，头痛，气短，内热不解，心中闷乱；以及妇人产后心虚、惊悸、烦闷欲绝。〔组成·照录〕麦门冬（去心）、小麦各二两半，甘草（炙）一两，人参、白茯苓各一两半，半夏（汤洗七次）二两。〔方义〕麦冬、小麦、参、苓、草养心益气（甘麦大枣汤意），半夏、竹茹和胃化痰除烦，为产后心虚惊悸之方。〔制法·服法〕上药锉散，每服四钱，用水二盏，加生姜七片、大枣三枚、淡竹茹一块如指大同煎，食煎（食前）服。虚劳烦闷者尤宜服之。"}, {"source": "条723｜《世医得效方》卷九·小定志丸", "原文": "《世医得效方》卷九：“小定志丸。治心气不定，五脏不足，甚者忧忧愁愁不乐，忽忽喜忘，朝瘥暮剧，暮瘥朝发。及因事有所大惊，梦寐不祥，登高履险，致神魂不安，惊悸恐怯。  \n菖蒲炒、远志去心，姜汁淹，各二两 茯苓、茯神 、参各三两 辰砂一两，为衣  \n上为末，炼蜜丸如梧桐子大。每服五十丸，米汤下。一方，去茯神，名开心散。每服二钱匕，不以时服。", "白话": "〔主治〕治心气不定，五脏不足，甚者忧忧愁愁不乐，恍惚善忘，朝轻暮重、暮轻朝发；以及因事大惊，梦寐不祥，登高履险，以致神魂不安，惊悸恐怯。〔组成·照录〕菖蒲（炒）、远志（去心，姜汁淹）各二两，茯苓、茯神、参各三两，辰砂一两（为衣）。〔方义〕菖蒲、远志、二茯苓、人参益气定志安神，辰砂重镇，为治心气不足、惊悸善忘之小方。〔制法·服法〕上为末，炼蜜为丸如梧桐子大，每服五十丸，米汤送下。一方去茯神，名“开心散”，每服二钱匕，不拘时候服。"}, {"source": "条724｜《世医得效方》卷十三·通气驱风汤", "原文": "《世医得效方》卷十三：“通气驱风汤。治男子妇人血气虚弱，虚风攻注，肌体颤掉，肩背刺痛，手足拳挛，口眼斜，半身不遂，头目旋晕，痰涎壅盛，语言謇涩，行步艰难，心忪气短。客风所凑，四肢拘急，鼻塞声重，头疼。脾胃不和，心腹刺痛，胸膈不快，少力多困，精神不爽，不思饮食，呕吐恶心，霍乱吐泻。胎前产后，但是气虚百病，皆可服之。  \n天台乌药五两 桔梗去芦、川白芷、川芎、甘草炙、陈皮去白、白术各三两半 麻黄去根", "白话": "〔主治〕治男子妇人血气虚弱、虚风攻注，肌体颤抖，肩背刺痛，手足拳挛，口眼歪斜，半身不遂，头目眩晕，痰涎壅盛，语言謇涩，行步艰难，心悸气短；客风所凑，四肢拘急，鼻塞声重，头疼；脾胃不和，心腹刺痛，胸膈不快，乏力多困，精神不爽，不思饮食，呕吐恶心，霍乱吐泻；胎前产后，凡是气虚百病，皆可服之。〔组成·照录〕天台乌药五两，桔梗（去芦）、川白芷、川芎、甘草（炙）、陈皮（去白）、白术各三两半，麻黄（去根）、枳壳（麸炒去穰瓤）各两半，人参（去芦）半两。〔方义〕乌药、枳壳、陈皮理气，麻黄、白"}, {"source": "条725｜《脉因证治》卷一·炙甘草汤", "原文": "《脉因证治》卷一：“炙甘草汤。治虚劳不足，汗出而闷，心悸，脉结代。心劳实热，口舌生疮，大便闭塞，心满痛，小腹热。心劳虚寒，惊悸恍惚多忘，梦寐惊魇，神志不定。精实，目视不明，齿焦发落，形衰，通身虚热。甚则胸中痹痛，烦闷泄精。精虚，尪羸，惊悸，梦泄遗沥，小便白浊。甚则茎弱核彻，小腹里急。", "白话": "〔主治〕治虚劳不足，汗出而胸闷，心悸，脉结代。又心劳实热证：口舌生疮，大便闭塞，心胸满痛，小腹热。心劳虚寒证：惊悸恍惚多忘，睡中惊魇，神志不定。精实（有余）证：目视不明，齿焦发落，形体衰惫，通身虚热，甚则胸中痹痛，烦闷泄精。精虚证：瘦弱，惊悸，梦泄遗沥，小便白浊，甚则阴茎软弱、睾丸冷痛彻引，小腹里急。〔组成·照录〕原稿未载（参见《伤寒论》炙甘草汤：甘草、生姜、人参、生地黄、桂枝、阿胶、麦门冬、麻仁、大枣）。〔方义〕炙甘草汤益气滋阴、通阳复脉，为脉结代、心动悸之主方。〔服法〕原"}, {"source": "条726｜《脉因证治》卷二·朱砂安神丸", "原文": "《脉因证治》卷二：“朱砂安神丸。治心神烦乱怔忡，兀兀欲吐，胸中气乱而热，似懊憹状，皆是膈上血中伏火。  \n朱砂一钱，研 黄连一钱半，酒制 炙甘草五分 生地五钱 当归半钱  \n饼丸，津下。如心痞，食入反出，加煨大黄，除地黄。", "白话": "〔主治〕治心神烦乱怔忡，兀兀欲吐，胸中气乱而热，似懊憹之状——皆因膈上血中伏火所致。〔组成·照录〕朱砂一钱（研）、黄连一钱半（酒制）、炙甘草五分、生地五钱、当归半钱。〔方义〕朱砂镇心，黄连清伏火，归、地养阴血，甘草和中，为清心镇惊、养血安神之名方。〔制法·服法〕作饼为丸，津液（唾液）送下。如心下痞、食入反出者，加煨大黄，除去地黄。"}, {"source": "条727｜《脉因证治》卷三·五苓散", "原文": "《脉因证治》卷三：“五苓散。治瘦人，脐下有悸者，吐涎沫而颠眩，水也。痰饮证状 或咳或喘，或呕或泄，眩晕嘈烦，忪悸愪，寒热疼痛，肿满挛癖，癃闭痞膈，如风如癫。", "白话": "〔主治〕治瘦人脐下有悸动，吐涎沫而头目颠眩者，是水饮为患。痰饮证状：或咳或喘，或呕或泄，眩晕嘈杂烦乱，心悸（原稿作“忪悸愪”），寒热疼痛，肿满拘挛积癖，小便癃闭、痞塞膈闷，状如风证、如癫疾。〔组成·照录〕原稿未载（五苓散：猪苓、泽泻、白术、茯苓、桂枝）。〔方义〕五苓散化气利水、健脾渗湿，水饮一去则悸眩自止。〔服法〕原稿未载。"}, {"source": "条728｜《医学纲目》卷四·辰砂安神丸（小剂服法）", "原文": "《医学纲目》卷四：“治心烦欲吐，怔忪不安卧，以辰砂安神丸，如米大，津液下十余丸，此近而奇耦偶，制小其服也（心肺在上为近。剂小者，不令下行故也）。", "白话": "〔主治〕治心烦欲吐、怔忡不得安卧。〔组成·照录〕辰砂安神丸（即朱砂安神丸）。〔服法〕制成米粒大小，用津液（唾液）送下十余丸。此即“治近而用奇偶、制小其服”之法（心肺在上，故称“近”；剂量小者，是不使药力下行之故）。"}, {"source": "条729｜《医学纲目》卷十·三黄汤", "原文": "《医学纲目》卷十：“三黄汤。治中风手足拘急，百节疼痛，烦热，心乱，恶寒，终日不欲饮食陈无择兼半身不遂，失音不言。\n黄芪二钱 独活四钱 细辛二钱 麻黄五钱 黄芩三钱  \n上五味，以水六升，煮取二升。分温作三服。一服小汗，二服大汗。心热加大黄二钱；腹满加枳实一枚；气逆加人参三钱；悸加牡蛎三钱；渴加栝蒌根三钱；先有寒加附子一枚。", "白话": "〔主治〕治中风手足拘急，百节疼痛，烦热，心乱，恶寒，终日不欲饮食（原稿下接“陈无择兼半身不遂，失音不言”，为陈无择《三因方》兼治之文，混入正文）。〔组成·照录〕黄芪二钱、独活四钱、细辛二钱、麻黄五钱、黄芩三钱。〔方义〕麻黄、独活、细辛祛风散寒，黄芪益气固表，黄芩清热，即仲景三黄汤法。〔服法〕上五味，用水六升，煮取二升，分温作三服：一服小汗，二服大汗。〔加减〕心热加大黄二钱；腹满加枳实一枚；气逆加人参三钱；心悸加牡蛎三钱；口渴加栝蒌根三钱；先有寒加附子一枚。"}, {"source": "条730｜《医学纲目》卷十一·薯蓣丸（附《甲乙经》针灸条）", "原文": "《医学纲目》卷十一：“《千》薯蓣丸。治虚劳不足，风气百疾，头目眩冒，惊悸狂癫。  \n薯蓣二十八分 当归十分 桂心七分 神曲炒、熟地各十分 甘草二十分 人参十分 芎五分 芍药、白术、麦门冬、杏仁各六分 柴胡、桔梗、茯苓各五分 鹿角胶七分 干姜三分 白蔹三分 防风六分 大枣一百枚，为膏 黄芩六分 大豆黄卷七分  \n上二十二味，末之，和枣膏炼蜜丸，如弹子大，空腹酒服一丸，日三服。《甲》卒心中痛，瘛疭，", "白话": "〔出处〕《医学纲目》引《千金》薯蓣丸。〔主治〕治虚劳不足，风气百疾，头目眩晕昏冒，惊悸狂癫。〔组成·照录〕薯蓣二十八分，当归十分，桂心七分，神曲（炒）、熟地各十分，甘草二十分，人参十分，芎（原稿此字后一字残损）五分，芍药、白术、麦门冬、杏仁各六分，柴胡、桔梗、茯苓各五分，鹿角胶七分，干姜三分，白蔹三分，防风六分，大枣一百枚（为膏），黄芩六分，大豆黄卷七分。〔方义〕薯蓣（山药）为君，合四君、四物、麦冬、阿胶、大枣气血双补，柴胡、桔梗、防风、杏仁、白蔹、大豆黄卷疏风清热，为虚劳惊"}, {"source": "条731｜《医学纲目》卷二十一·养荣汤", "原文": "《医学纲目》卷二十一：“养荣汤。治五疸。脚弱心忪，口淡耳响，微寒发热，气急，小便白浊，当作虚劳治之。  \n黄芪、当归、桂心、甘草炙、陈皮、白术、人参各一两 白芍药三两 熟地、五味子、茯苓各三钱 远志去心，半两   \n上每服四钱，姜枣煎，空心服。上法治虚寒黄疸。", "白话": "〔主治〕治五疸。脚弱心悸，口淡耳鸣，微寒发热，气急，小便白浊，当作虚劳治之。〔组成·照录〕黄芪、当归、桂心、甘草（炙）、陈皮、白术、人参各一两，白芍药三两，熟地、五味子、茯苓各三钱，远志（去心）半两。〔方义〕参、芪、术、苓、草合归、芍、地、五味益气养血，桂心温阳，远志安神，为虚寒黄疸、心悸脚弱之剂。〔服法〕上每服四钱，姜、枣煎，空腹服。上法（本方）治虚寒黄疸。"}, {"source": "条732｜《医学纲目》卷二十五·镇心丹", "原文": "《医学纲目》卷二十五：“镇心丹。治惊悸自汗，心烦短气，喜怒悲恶，悉不自知，忘魂失魄，状若神灵所凭，及男子遗泄，女子带下。  \n辰砂研、白矾煅汁尽，各等分  \n上为末，水丸如鸡头大。每服一丸，煎人参汤下，食后服。", "白话": "〔主治〕治惊悸自汗，心烦短气，喜怒悲恶自己全然不知，忘魂失魄，状若神灵所凭（精神失常之状），以及男子遗精、女子带下。〔组成·照录〕辰砂（研）、白矾（煅汁尽）各等分。〔方义〕辰砂重镇安神，白矾祛痰敛摄，药仅二味，镇心定悸、敛汗止遗。〔制法·服法〕上为末，水为丸如鸡头大，每服一丸，煎人参汤送下，食后服。"}, {"source": "条733｜《医学纲目》卷二十九·清心丸（《本事方》）", "原文": "《医学纲目》卷二十九：“《本》治经络热梦遗，心忪恍惚膈热，清心丸。  \n用好黄柏皮一两，研为细末，生脑子一钱，同研匀，炼蜜为丸，如桐子大，每服十丸至十五丸，浓煎麦门冬汤吞下。", "白话": "〔出处〕《医学纲目》引《本》（《普济本事方》）治经络有热梦遗、心悸恍惚、膈热之清心丸。〔组成·照录〕好黄柏皮一两（研为细末），生脑子一钱。〔方义〕黄柏清下焦经络之热，龙脑（冰片）辛凉透散，热清则梦遗心悸止。〔制法·服法〕二药同研匀，炼蜜为丸如梧桐子大，每服十丸至十五丸，浓煎麦门冬汤吞下。"}, {"source": "条734｜《普济方》卷十六·沙参散（永类钤方）", "原文": "《普济方》卷十六：“沙参散永类钤方。 治心实热。惊悸喜笑。心神不安。泄热安心。　　\n沙参去芦头、白薇、川芒硝、茯神、栀子仁、羚羊角屑、子芩各一两 石膏二两半 人参三分，去芦头 甘草半两，炙微赤锉 \n上为粗散。每服三钱。水一中盏。煎五分。去滓。入生地黄汁一合。竹沥半合。更煎一两沸。每于食后温服。忌炙爆热面。", "白话": "〔出处〕沙参散（《永类钤方》）。〔主治〕治心实热，惊悸喜笑，心神不安。能泄热安心。〔组成·照录〕沙参（去芦头）、白薇、川芒硝、茯神、栀子仁、羚羊角屑、子芩各一两，石膏二两半，人参三分（去芦头），甘草半两（炙微赤，锉）。〔方义〕石膏、芒硝、栀子、子芩（黄芩）清心泄热，羚羊角凉肝定惊，沙参、白薇、茯神、参、草养心安神，为心实热惊悸之方。〔制法·服法〕上为粗散，每服三钱，用水一中盏，煎取五分，去渣，加入生地黄汁一合、竹沥半合，再煎一两沸，每于食后温服。忌炙爆热面。"}, {"source": "条735｜《普济方》卷十六·定心丸", "原文": "《普济方》卷十六：“定心丸。治实热在内，狂妄不常。  \n硝石半两 丹砂一分钱\n上细研，糯米粥和丸，如樱桃大，每服一丸，生糯米汁入油一两，点青柳枝，打匀服。", "白话": "〔主治〕治实热在内，狂妄失常。〔组成·照录〕硝石半两、丹砂一钱（原稿作“丹砂一分钱”）。〔方义〕硝石咸寒攻下泄热，丹砂重镇安神，治实热狂妄之证。〔制法·服法〕上药细研，糯米粥和丸如樱桃大，每服一丸；以生糯米汁入油一两，点青柳枝搅打均匀服下。"}, {"source": "条736｜《普济方》卷十六·惊气丸（出《卫生家宝方》）", "原文": "《普济方》卷十六：“惊气丸出《卫生家宝方》。治忧愁思虑，喜怒不常，或因惊怕而伤心，或因思虑而神损，或心忪恍惚，或手足不仁，身热自汗，腰背引痛，嗜卧少力，举动多惊，饮食无味，及治产后中风、一切惊病。", "白话": "〔主治〕治忧愁思虑、喜怒无常，或因惊怕而伤心，或因思虑而神损，或心悸恍惚，或手足麻木不仁，身热自汗，腰背牵引作痛，嗜卧乏力，举动多惊，饮食无味；并治产后中风、一切惊病。〔组成·照录〕原稿未载。〔方义〕从主治看，为养心安神、定惊止悸之剂。〔服法〕原稿未载。"}, {"source": "条737｜《普济方》卷十六·救命丹（出《卫生家宝方》）", "原文": "《普济方》卷十六：“救命丹出《卫生家宝方》。治心虚气短，神志不宁，或多惊悸，语言颠错。　　\n辰砂一两，有墙壁者细研 獖猪血四两\n上用水一斗，同置于银石器中，用炭火煮至一升，放冷，别用清水荡去猪血令净，渗朱砂干，以桃胶丸如麻子大，每服十丸，用去心麦门冬煎汤，下四五丸，服立效。", "白话": "〔主治〕治心虚气短，神志不宁，或多惊悸，语言错乱。〔组成·照录〕辰砂一两（成块坚实者，细研）、獖猪血四两。〔方义〕辰砂重镇安神，猪心血以心入心、引药入心经，治心虚惊悸。〔制法·服法〕用水一斗，与上药同置于银石器中，用炭火煮至一升，放冷；另用清水将猪血漂荡洗净，把辰砂渗干，以桃胶为丸如麻子大；每服十丸，用去心麦门冬煎汤送下四五丸（原稿“每服十丸……下四五丸”前后不一），服之立效。"}, {"source": "条738｜《普济方》卷十八·宁心丹（出《卫生家宝方》）", "原文": "《普济方》卷十八：“宁心丹出《卫生家宝方《》。治思虑悲忧伤心，惊悸怔忪，睡卧不宁。　　\n人参一两 茯神一两 朱砂细研、乳香细研、白附子微炮，各半两 雄黄一分 紫石英一分 真朱末一分，细研 桃奴一分 脑子半钱，细研 麝香一钱，细研 金箔五十片，研入药 \n上为末，酒煮半夏糊为丸，如鸡头大。别以金箔为衣，每服一丸，先用灯心汤浸，至睡时，磨化，暖水温服。小儿半丸。", "白话": "〔主治〕治思虑悲忧伤心，惊悸怔忡，睡卧不宁。〔组成·照录〕人参一两、茯神一两，朱砂（细研）、乳香（细研）、白附子（微炮）各半两，雄黄一分，紫石英一分，真朱末一分（细研），桃奴一分，脑子半钱（细研），麝香一钱（细研），金箔五十片（研入药）。〔方义〕参、茯神益心气，朱砂、真珠、金箔、紫石英重镇安神，乳香行气，白附子化痰，雄黄、麝香、龙脑开窍，桃奴（碧桃干）敛汗，为镇心安神之丹。〔制法·服法〕上为末，酒煮半夏糊为丸如鸡头大，另以金箔为衣；每服一丸，先用灯心汤浸，至睡时磨化，暖水温服"}, {"source": "条739｜《普济方》卷十八·朱附丹（余居士选奇方）", "原文": "《普济方》卷十八：“朱附丹余居士选奇方。治心肾不足，气不升降，惊悸，用心过度。　　\n附子一两，炮去皮脐 朱砂半两，研 茯神一两 \n上为末，白面糊为丸，如梧桐子大。每服二十丸，空心盐汤下，主火惊失心出本草。", "白话": "〔主治〕治心肾不足，气不升降，惊悸，用心过度。〔组成·照录〕附子一两（炮，去皮脐）、朱砂半两（研）、茯神一两。〔方义〕附子温心肾之阳，朱砂镇心安神，茯神养心，为心肾阳虚惊悸之小丹。〔制法·服法〕上为末，白面糊为丸如梧桐子大，每服二十丸，空腹盐汤送下。原稿末附“主火惊失心出本草”。"}, {"source": "条740｜《普济方》卷四十七·麝香天麻丸（圣济总录）", "原文": "《普济方》卷四十七：“麝香天麻丸圣济总录。治风头旋目黑，肩背拘急，恍惚忪悸，肢节疼痛，宜服。  \n麝香研一钱半 天麻、天南星炮、白附子炮、羌活去芦头、赤茯苓去黑皮、干蝎去土炒、丹砂研、防风去叉、桂去粗皮、蝉蜕洗炒各一两半 乌蛇酒浸，去皮骨炙，二两 铅霜研一分 \n上除研者外，捣罗为末，再同研匀，炼蜜和丸，如梧桐子大，每服二十丸，温酒下，荆芥汤亦得，不拘时候。", "白话": "〔主治〕治风头旋、目黑，肩背拘急，恍惚心悸，肢节疼痛，宜服。〔组成·照录〕麝香（研）一钱半，天麻、天南星（炮）、白附子（炮）、羌活（去芦头）、赤茯苓（去黑皮）、干蝎（去土炒）、丹砂（研）、防风（去叉）、桂（去粗皮）、蝉蜕（洗炒）各一两半，乌蛇（酒浸，去皮骨炙）二两，铅霜（研）一分。〔方义〕天麻、蝎、蛇、蝉蜕搜风通络，羌活、防风、桂散风寒，南星、白附化痰，麝香开窍，丹砂、铅霜镇心，为风眩心悸之丸。〔制法·服法〕除研细药外，捣罗为末，再同研匀，炼蜜和丸如梧桐子大，每服二十丸，温酒"}, {"source": "条741｜《普济方》卷一百一·麻黄丸（圣济总录）", "原文": "《普济方》卷一百一：“麻黄丸出圣济总录。治中风邪狂走，或自高自贤，或悲泣呻吟。及猝得惊悸邪魅，恍惚，心下虚悸。 \n麻黄去根节煎掠去沫焙、甘草炙锉、半夏汤浸生布揉洗七次焙，各一两 生姜去皮，一两半，先与半夏同捣炒干 \n上为末，炼蜜和丸如大豆大。生姜汤下三丸，加至五丸。空心午时各一服，渐加至十丸。", "白话": "〔主治〕治中风邪气狂走，或自高自大自以为贤，或悲泣呻吟；以及猝得惊悸邪魅、恍惚，心下虚悸。〔组成·照录〕麻黄（去根节，煎掠去沫，焙）、甘草（炙，锉）、半夏（汤浸，生布揉洗七次，焙）各一两，生姜（去皮）一两半（先与半夏同捣炒干）。〔方义〕麻黄宣散风邪，半夏、生姜化痰和胃，甘草和中，风痰去则狂定悸安。〔制法·服法〕上为末，炼蜜和丸如大豆大，生姜汤送下三丸，渐加至五丸；空腹、午时各一服，渐加至十丸。"}, {"source": "条742｜《普济方》卷一百二·丹砂镇心丸", "原文": "《普济方》卷一百二：“丹砂镇心丸。治风惊悸，或忧愁思虑，心神恍惚，狂言烦闷，口眼斜，化痰利咽膈。　　\n丹砂别研，一两 牛黄别研、龙脑别研、麝香别研，各一钱 铅白霜别研、天竺黄各二钱 天麻酒炙二两 人参、茯苓去黑皮、甘草炙锉，各半两 \n上为末，和匀，炼蜜为丸，如鸡头大。每服三丸，煎金银薄荷汤化下，食后临卧服。", "白话": "〔主治〕治风惊悸，或忧愁思虑、心神恍惚，狂言烦闷，口眼歪斜；能化痰利咽膈。〔组成·照录〕丹砂（别研）一两，牛黄（别研）、龙脑（别研）、麝香（别研）各一钱，铅白霜（别研）、天竺黄各二钱，天麻（酒炙）二两，人参、茯苓（去黑皮）、甘草（炙，锉）各半两。〔方义〕丹砂、铅白霜重镇定惊，牛黄、龙脑、麝香清心开窍，天麻息风，竺黄化痰，参、苓、草益气，为风痰惊悸之镇心剂。〔制法·服法〕上为末，和匀，炼蜜为丸如鸡头大，每服三丸，煎金银薄荷汤化下，食后临卧服。"}, {"source": "条743｜《普济方》卷一百二·定心丸", "原文": "《普济方》卷一百二：“方定心丸。治心虚忧悲不乐，惊悸心忪，恍惚忘误，神情不宁。  \n茯苓去黑皮、茯神去木，各一两 琥珀另研、龙齿、阿胶炙令燥、牛黄锉研、珍珠别研、犀角镑、龙脑别研、麝香别研，各半两 天南星牛胆内匮者、甘草炙锉，各一两半 远志去心，一分 金箔三十片，为衣 银箔三十片，研入药 菖蒲、酸枣仁炒、天竺黄别研、人参各三分 丹砂别研，四两 龙胆半分 雄黄别研，二两 苏合香二两 安息香二两，同苏", "白话": "〔主治〕治心虚忧悲不乐，惊悸心慌，恍惚善忘，神情不宁。〔组成·照录〕茯苓（去黑皮）、茯神（去木）各一两，琥珀（另研）、龙齿、阿胶（炙令燥）、牛黄（锉研）、珍珠（别研）、犀角（镑）、龙脑（别研）、麝香（别研）各半两，天南星（牛胆内匮者）、甘草（炙，锉）各一两半，远志（去心）一分，金箔三十片（为衣）、银箔三十片（研入药），菖蒲、酸枣仁（炒）、天竺黄（别研）、人参各三分，丹砂（别研）四两，龙胆半分，雄黄（别研）二两，苏合香二两，安息香二两（同苏合香以酒一大盏研化，澄去砂脚，熬成膏）"}, {"source": "条744｜《普济方·卷二百二十七》·双补丸（出医药方）", "原文": "《普济方·卷二百二十七》：“双补丸出医药方。治一切虚损，五劳七伤，面色黧黑。唇口干燥，发渴目暗，耳鸣心忪，气短食少，神倦夜梦惊恐，四肢酸疼，寒热盗汗，小肠拘急，小便滑数，妇人诸疾，并宜服之。常服既济水火，益气安神。 \n鹿角霜三两 熟地黄洗再蒸、沉香、菟丝子酒浸蒸研焙、复盆子覆盆子去枝蒂、白茯苓去皮、人参去芦头、宣木瓜、薏苡仁炒、黄芪炙、苁蓉洗酒浸、五味子去枝炒、石斛去根炒、当归去芦酒炒、泽泻切块再", "白话": "〔主治〕治一切虚损、五劳七伤，面色黧黑，唇口干燥，口渴目暗，耳鸣心悸，气短食少，神倦夜梦惊恐，四肢酸疼，寒热盗汗，小肠拘急，小便滑数，妇人诸疾，并宜服之。常服能既济水火、益气安神。〔组成·照录〕鹿角霜三两，熟地黄（洗再蒸）、沉香、菟丝子（酒浸蒸研焙）、复盆子覆盆子（去枝蒂）、白茯苓（去皮）、人参（去芦头）、宣木瓜、薏苡仁（炒）、黄芪（炙）、苁蓉（洗，酒浸）、五味子（去枝，炒）、石斛（去根，炒）、当归（去芦，酒炒）、泽泻（切块再蒸）各一两，麝香一钱（别研），朱砂半两（别研末）。"}, {"source": "条745｜《普济方》卷一百八十六·排风汤（出《治风经验方》）", "原文": "《普济方》卷一百八十六：“排风汤出《治风经验方》。治风疾，身体拘挛、麻痹，精神错乱，心多怔忡。  \n独活、白茯苓、麻黄去节，各一两半 白藓皮白鲜皮、川芎、当归切焙、桂去皮不见火、甘草炙、杏仁去皮炒，各一两、\n上捣筛为粗末，每服五钱，水一盏半，生姜四片，煎至一盏，滤去滓，通口服，空心食前，日进三服。", "白话": "〔主治〕治风疾，身体拘挛、麻痹，精神错乱，心多怔忡。〔组成·照录〕独活、白茯苓、麻黄（去节）各一两半，白藓皮白鲜皮、川芎、当归（切，焙）、桂（去皮，不见火）、甘草（炙）、杏仁（去皮，炒）各一两。〔方义〕独活、麻黄、白藓皮祛风，芎、归、桂养血通络，苓、杏、草化痰和中，为风疾怔忡之剂。〔制法·服法〕上捣筛为粗末，每服五钱，用水一盏半，加生姜四片，煎至一盏，滤去渣，一次口服，空腹食前，日进三服。"}, {"source": "条746｜《普济方》卷二百二十八·枸杞汤", "原文": "《普济方》卷二百二十八：“枸杞汤。治虚劳骨肉酸疼，吸吸少气，少腹拘急，腰背强痛，心中惊悸，咽干唇燥，面无颜色，饮食减少，忧愁嗜卧。　　\n大麻仁五两 枸杞叶五两 干姜炮，一两 桂去粗皮，五钱 甘草炙锉，三两 \n上粗捣筛，每服三钱。以水一盏，煎取半盏，去滓空腹温服。", "白话": "〔主治〕治虚劳骨肉酸疼，气短少气，少腹拘急，腰背强痛，心中惊悸，咽干唇燥，面无血色，饮食减少，忧愁嗜卧。〔组成·照录〕大麻仁五两、枸杞叶五两、干姜（炮）一两、桂（去粗皮）五钱、甘草（炙，锉）三两。〔方义〕枸杞叶、麻仁滋阴润燥，干姜、桂温中通阳，甘草和中，为虚劳惊悸、咽干唇燥之剂。〔制法·服法〕上粗捣筛，每服三钱，用水一盏，煎取半盏，去渣，空腹温服。"}, {"source": "条747｜《普济方》卷二百二十八·鹿茸丸（出《杨氏家藏方》）", "原文": "《普济方》卷二百二十八：“鹿茸丸出《杨氏家藏方》。治真元虚惫，五劳七伤，面色黧黯，唇口干舌燥，目暗耳鸣，心忪气短，精神昏倦，喜怒无常，饮食无味，四肢酸疼，举动乏力，小腹拘急，小便滑数，或时出血。  \n熟地黄洗焙，五两 山药三两 杜仲炒断丝，一两半 鹿茸烧去毛，酒浸炙 五味子 附子炮焙，五两 肉苁蓉酒浸一宿、牛膝酒浸一宿，各一两 \n上为末，面糊丸，如梧桐子大，每服三十丸，温酒盐汤下，和剂方用药同，但", "白话": "〔主治〕治真元虚惫，五劳七伤，面色黧黯，唇口干舌燥，目暗耳鸣，心悸气短，精神昏倦，喜怒无常，饮食无味，四肢酸疼，举动乏力，小腹拘急，小便滑数，或时出血。〔组成·照录〕熟地黄（洗焙）五两、山药三两、杜仲（炒断丝）一两半、鹿茸（烧去毛，酒浸炙）、五味子、附子（炮焙）五两、肉苁蓉（酒浸一宿）、牛膝（酒浸一宿）各一两。〔方义〕鹿茸、苁蓉、杜仲、牛膝温肾填精，熟地、薯蓣、五味补肾敛精，附子温阳，为真元虚惫心悸之丸。〔制法·服法〕上为末，面糊为丸如梧桐子大，每服三十丸，温酒或盐汤送下。和"}, {"source": "条748｜《普济方》卷二百二十九·黄芪汤（一名地骨皮散）", "原文": "《普济方》卷二百二十九：“黄芪汤一名地骨皮散。治热劳，肢节酸疼，吸吸少气，腰背强痛，心中虚悸，咽干唇赤，面色枯燥，饮食无味，悲忧惨戚，多睡少起。  \n黄芪锉焙、地骨皮各一两 鳖甲一枚，去裙涂醋炙黄 甘草炙，锉半两 麦门冬去心，焙，一两半 桂去粗皮，半两 \n上粗捣筛，每服五钱，水一盏半，生姜半分拍破，粳米五十粒，煎至八分，去滓，食前温服。", "白话": "〔主治〕治热劳，肢节酸疼，气短少气，腰背强痛，心中虚悸，咽干唇赤，面色枯燥，饮食无味，悲忧凄惨，多睡少起。〔组成·照录〕黄芪（锉，焙）、地骨皮各一两，鳖甲一枚（去裙，涂醋炙黄），甘草（炙，锉）半两，麦门冬（去心，焙）一两半，桂（去粗皮）半两。〔方义〕黄芪、甘草益气，地骨皮、鳖甲、麦冬滋阴清虚热，桂通阳，为热劳虚悸之剂。〔制法·服法〕上粗捣筛，每服五钱，用水一盏半，加生姜半分（拍破）、粳米五十粒，煎至八分，去渣，食前温服。"}, {"source": "条749｜《普济方》卷二百四十八·吴茱萸汤（出《圣惠方》）", "原文": "《普济方》卷二百四十八：“吴茱萸汤出《圣惠方》。治寒疝、腰腹痛，胸中冷气上抢，心胁支满，不得卧，面目痛，风寒悸栗多惊，不能饮食，食已即呕，寒热往来。  \n吴茱萸汤浸七次焙干微炒、半夏浸七次去滑、姜炮制锉、人参去芦头、当归锉碎微炒、赤芍药各三分 细辛、紫菀去苗土、附子炮裂去皮、熟干地黄、前胡去芦头、赤茯苓、白术、桂心、木香各一两 甘草炙微锉、旋复花旋覆花各半两 诃黎勒一两半，用皮 \n上为末，炼蜜和捣", "白话": "〔主治〕治寒疝、腰腹痛，胸中冷气上冲，心胁支撑胀满，不得卧，面目痛，风寒悸栗多惊，不能饮食，食已即呕，寒热往来。〔组成·照录〕吴茱萸（汤浸七次，焙干微炒）、半夏（浸七次去滑）、姜（炮制，锉）、人参（去芦头）、当归（锉碎，微炒）、赤芍药各三分，细辛、紫菀（去苗土）、附子（炮裂，去皮）、熟干地黄、前胡（去芦头）、赤茯苓、白术、桂心、木香各一两，甘草（炙微锉）、旋复花旋覆花各半两，诃黎勒一两半（用皮）。〔方义〕吴茱萸、附子、桂、姜温里散寒，参、归、地、芍益气养血，半夏、紫菀、前胡化"}, {"source": "条750｜《普济方》卷二百八十六·解毒丸", "原文": "《普济方》卷二百八十六：“解毒丸。治中外诸邪毒痈肿疮，筋脉拘挛，寝汗咬牙，一切惊悸热毒。  \n大黄、黄连、栀子、黄芩各五钱 牵牛、滑石各一两 \n上为细末，滴水为丸，如梧桐子大，每服三四十丸，温水送下，加减用服之。", "白话": "〔主治〕治中外诸邪毒痈肿疮疡，筋脉拘挛，寝汗咬牙，一切惊悸热毒。〔组成·照录〕大黄、黄连、栀子、黄芩各五钱，牵牛、滑石各一两。〔方义〕芩、连、栀、大黄泻火解毒，牵牛攻下，滑石清热利湿，热毒去则惊悸止。〔制法·服法〕上为细末，滴水为丸如梧桐子大，每服三四十丸，温水送下，随证加减服之。"}, {"source": "条751｜《普济方》卷三百三十一·禹余粮丸（一名吴茱萸丸）", "原文": "《普济方》卷三百三十一：“禹余粮丸一名吴茱萸丸。治妇人久赤白带下，胞络伤败，月水不调，渐成崩漏，气血虚竭，面黄体瘦，脐腹里急，腰膝疼痛，肢体烦痛，心忪头眩，手足发热。  \n禹余粮二两，烧醋淬七次 白石脂二两 当归一两，锉微炒 鳖甲一两，涂醋炙微黄去裙襕 狗脊二分，去毛 白芍药三分 白术一两 附子一两，涂醋微炙 桑寄生一两 柏叶一两，微炒 厚朴一两，去粗皮涂生姜汁炙令香熟 干姜一两，炮裂锉 吴茱萸半", "白话": "〔主治〕治妇人久患赤白带下，胞络伤败，月经不调，渐成崩漏，气血虚竭，面黄体瘦，脐腹里急，腰膝疼痛，肢体烦痛，心悸头眩，手足发热。〔组成·照录〕禹余粮二两（烧，醋淬七次）、白石脂二两、当归一两（锉，微炒）、鳖甲一两（涂醋炙微黄，去裙襕）、狗脊二分（去毛）、白芍药三分、白术一两、附子一两（涂醋微炙）、桑寄生一两、柏叶一两（微炒）、厚朴一两（去粗皮，涂生姜汁炙令香熟）、干姜一两（炮裂，锉）、吴茱萸半两（汤浸七次，焙干微炒）。〔方义〕禹余粮、白石脂、龙…收涩止崩，归、芍、寄生、柏叶养"}, {"source": "条752｜《婴童百问》卷二·温胆汤", "原文": "《婴童百问》卷二：“温胆汤。治惊悸烦躁不得眠。  \n半夏、枳实各二钱半 茯苓半两 桔红、甘草各一钱半 酸枣仁去壳，二钱半 腹疼加芍药。\n上㕮咀，每服一钱，入竹茹少许，姜、枣煎服。", "白话": "〔主治〕治惊悸烦躁不得眠。〔组成·照录〕半夏、枳实各二钱半，茯苓半两，桔红、甘草各一钱半，酸枣仁（去壳）二钱半；腹痛加芍药。〔方义〕半夏、枳实、橘红（桔红）理气化痰，茯苓、甘草健脾，枣仁养心安神，为小儿惊悸不寐之剂。〔制法·服法〕上药切碎，每服一钱，加入竹茹少许，姜、枣煎服。"}, {"source": "条753｜《婴童百问》卷六·生犀散", "原文": "《婴童百问》卷六：“生犀散。治咳嗽，解时气痰逆喘满，心忪忡惊悸、风热。  \n杏仁二钱、炒 桔梗二钱 茯苓一钱 前胡一钱半 人参一钱 半夏一钱 五味子一钱 甘草一钱  \n上㕮咀，生姜薄荷煎服。有热加羌活，或加麻黄细辛。", "白话": "〔主治〕治咳嗽，解时气痰逆喘满，心悸怔忡、惊悸、风热。〔组成·照录〕杏仁二钱（炒）、桔梗二钱，茯苓一钱，前胡一钱半，人参一钱，半夏一钱，五味子一钱，甘草一钱。〔方义〕杏仁、桔梗、前胡宣肺止咳，半夏化痰，参、苓、草益气，五味敛肺，为时气痰逆、心悸之小儿方。〔制法·服法〕上药切碎，生姜、薄荷煎服。有热加羌活，或加麻黄、细辛。"}, {"source": "条754｜《婴童百问》卷七·茯苓半夏汤", "原文": "《婴童百问》卷七：“茯苓半夏汤。治诸呕吐，心下坚痞，膈间有痰水眩悸。  \n茯苓二两 半夏五钱、汤泡七次  \n上㕮咀，每服三钱，水一盏，生姜三片，煎六分服。", "白话": "〔主治〕治各种呕吐，心下坚硬痞满，膈间有痰水、眩晕心悸。〔组成·照录〕茯苓二两、半夏五钱（汤泡七次）。〔方义〕茯苓健脾利水，半夏化痰降逆，即小半夏加茯苓汤意，痰水除则呕悸止。〔制法·服法〕上药切碎，每服三钱，用水一盏，加生姜三片，煎取六分服。"}, {"source": "条755｜《卫生易简方》卷二·糯米饮（霍乱心悸方）", "原文": "《卫生易简方》卷二：“治霍乱心悸热渴，用糯米水研。冷熟水混，取米泔汁，任意饮之。若悸多者，加茯苓。", "白话": "〔主治〕治霍乱心悸、发热口渴。〔组成·照录〕糯米。〔方义〕糯米水研取泔汁，甘凉和中、益气生津，止渴除烦定悸。〔制法·服法〕将糯米水研，冷热水调和，取米泔汁，任意饮之。若心悸多者，加茯苓。"}, {"source": "条756｜《奇效良方》卷一·麻黄散", "原文": "《奇效良方》卷一：“麻黄散。治心脏中风，虚寒颤，心惊掣悸，语声混浊，口歪冒昧，好笑，并宜服之。  \n麻黄去节，一钱 白术一钱 防风去芦，一钱 川芎一钱 甘草炙，一钱 汉防己一钱 当归一钱，去芦 人参一钱，去芦 羌活一钱半，去芦 远志一钱半，去心 川升麻八分 桂心半钱 茯神一钱半，去木  \n上作一服，水二盅，生姜五片，煎至一盅，入竹沥半盏，再煎一二沸，不拘时服。", "白话": "〔主治〕治心脏中风，虚寒颤栗，心惊掣悸，语声混浊，口歪神昧，好笑（喜笑失常），并宜服之。〔组成·照录〕麻黄（去节）一钱，白术一钱，防风（去芦）一钱，川芎一钱，甘草（炙）一钱，汉防己一钱，当归（去芦）一钱，人参（去芦）一钱，羌活（去芦）一钱半，远志（去心）一钱半，川升麻八分，桂心半钱，茯神（去木）一钱半。〔方义〕麻黄、防风、羌活、升麻疏散风邪，参、术、苓、草、归、芎益气养血，桂心温阳，远志安神，为心经中风、虚寒惊悸之剂。〔制法·服法〕上作一服，用水二盅，加生姜五片，煎至一盅，加"}, {"source": "条757｜《奇效良方》卷三·茯神散", "原文": "《奇效良方》卷三：“茯神散。治诸风恍惚，心神烦乱，志意不安，或卧惊恐。  \n茯神一两 石膏研、龙齿各二两 麦门冬去心，一两半 黄芪一两 甘草半两，炙 石菖蒲、人参去芦，各一两 防风三分 远志半两，去心 熟干地黄、羚羊角屑各一两  \n上㕮咀，每服四钱，以水一中盏，入生姜半分，枣三枚，煎至六分，去滓，不拘时候温服。", "白话": "〔主治〕治诸风恍惚，心神烦乱，意志不安，或卧中惊恐。〔组成·照录〕茯神一两，石膏（研）、龙齿各二两，麦门冬（去心）一两半，黄芪一两，甘草（炙）半两，石菖蒲、人参（去芦）各一两，防风三分，远志（去心）半两，熟干地黄、羚羊角屑各一两。〔方义〕茯神、菖蒲、远志、龙齿安神定志，参、芪、地、麦益气养阴，石膏清热，防风散风，为风邪恍惚惊悸之剂。〔制法·服法〕上药切碎，每服四钱，用水一中盏，加生姜半分、大枣三枚，煎至六分，去渣，不拘时候温服。"}, {"source": "条758｜《奇效良方》卷十·茯神散", "原文": "《奇效良方》卷十：“茯神散。治伤寒后虚羸，心气乏力弱，惊悸多忘。  \n茯神、黄芪、菖蒲各一两 白芍药、人参各半两 远志去心，三分  \n上㕮咀，每服五钱，水一中盏，入枣三枚，煎至六分，去滓，不拘时温服。", "白话": "〔主治〕治伤寒之后身体虚羸，心气不足乏力，惊悸多忘。〔组成·照录〕茯神、黄芪、菖蒲各一两，白芍药、人参各半两，远志（去心）三分。〔方义〕茯神、菖蒲、远志安神益智，参、芪、芍益气养血，为伤寒后心虚惊悸善忘之剂。〔制法·服法〕上药切碎，每服五钱，用水一中盏，加大枣三枚，煎至六分，去渣，不拘时候温服。"}, {"source": "条759｜《奇效良方》卷十·牡蛎散", "原文": "《奇效良方》卷十：“牡蛎散。治伤寒后虚损，心多怔悸，夜梦泄精。  \n牡蛎烧为粉、桂心、白芍药、鹿茸酥炙、龙骨各一两 甘草炙，半两  \n上㕮咀，每服五钱，水一大盏，生姜半分，枣三枚，煎至五分，去渣，食前温服。", "白话": "〔主治〕治伤寒后虚损，心中多怔悸，夜间梦中遗精。〔组成·照录〕牡蛎（烧为粉）、桂心、白芍药、鹿茸（酥炙）、龙骨各一两，甘草（炙）半两。〔方义〕牡蛎、龙骨镇心潜阳、固精止遗，鹿茸补肾，桂、芍和营，为伤寒后心悸梦泄之剂。〔制法·服法〕上药切碎，每服五钱，用水一大盏，加生姜半分、大枣三枚，煎至五分，去渣，食前温服。"}, {"source": "条760｜《奇效良方》卷二十二·远志丸", "原文": "《奇效良方》卷二十二：“远志丸。治虚劳惊悸，神气不足，多忘不安。  \n远志去心、石菖蒲、熟地黄、人参去芦、黄芪锉、薯蓣、茯神、紫石英研细，水飞各一两 麦门冬去心，焙 龙齿细研，二两  \n上为细末，研匀，炼蜜和捣三五百杵，丸如梧桐子大，每服十五丸，不拘时人参汤送下。", "白话": "〔主治〕治虚劳惊悸，神气不足，多忘不安。〔组成·照录〕远志（去心）、石菖蒲、熟地黄、人参（去芦）、黄芪（锉）、薯蓣、茯神、紫石英（研细，水飞）各一两，麦门冬（去心，焙）、龙齿（细研）二两。〔方义〕远志、菖蒲、茯神、龙齿、紫石英安神定悸，参、芪、薯蓣、熟地、麦冬益气养阴，为虚劳惊悸之丸。〔制法·服法〕上为细末，研匀，炼蜜和捣三五百杵，为丸如梧桐子大，每服十五丸，不拘时候人参汤送下。"}, {"source": "条761｜《奇效良方》卷二十二·白羊肉汤", "原文": "《奇效良方》卷二十二：“白羊肉汤。治虚劳羸瘦，脚膝无力，耳聋盗汗，心多忪悸。  \n白羊肉二斤，去脂膜，汲水四升煮取二升 桂心三分 杜仲去粗皮，炙黄，锉、白茯苓熟地黄、牛膝去苗、人参去芦、白术、远志去心、黄芪锉、龙骨以上各一两 磁石三两，捣碎，水淘去赤汁  \n上㕮咀，每服四钱，用羊肉汁一中盏，煎至六分，去滓，每于食前温服之。", "白话": "〔主治〕治虚劳羸瘦，脚膝无力，耳聋盗汗，心多悸动。〔组成·照录〕白羊肉二斤（去脂膜，汲水四升煮取二升），桂心三分，杜仲（去粗皮，炙黄，锉）、白茯苓、熟地黄、牛膝（去苗）、人参（去芦）、白术、远志（去心）、黄芪（锉）、龙骨以上各一两，磁石三两（捣碎，水淘去赤汁）。〔方义〕羊肉血肉有情之品补虚，参、芪、术、苓、地益气养血，杜仲、牛膝补肾强腰，磁石、龙骨镇心，为虚劳心悸之食药并用方。〔制法·服法〕上药切碎，每服四钱，用羊肉汁一中盏，煎至六分，去渣，每于食前温服。"}, {"source": "条762｜《奇效良方》卷二十六·调中汤", "原文": "《奇效良方》卷二十六：“调中汤。治心掣，胸中忿气，不欲饮食。  \n赤茯苓去黑皮、当归切碎、干姜炮、参、术以上各二两 官桂去粗皮，一两半 五味子、甘草炙，各一两  \n上锉如麻豆大，每服五钱，水一盏半，煎至八分，去滓稍热服，日二夜二。", "白话": "〔主治〕治心掣，胸中气郁不舒，不欲饮食。〔组成·照录〕赤茯苓（去黑皮）、当归（切碎）、干姜（炮）、参、术以上各二两，官桂（去皮）一两半，五味子、甘草（炙）各一两。〔方义〕参、术、苓、草健脾，归、桂、姜温中养血，五味子敛心气，为心掣、胸闷不食之剂。〔制法·服法〕上药锉如麻豆大，每服五钱，用水一盏半，煎至八分，去渣，稍热服，日二服、夜二服。"}, {"source": "条763｜《奇效良方》卷三十一·金珠化痰丸", "原文": "《奇效良方》卷三十一：“金珠化痰丸。治痰热，安神志，除头痛眩晕，心忪恍惚，胁膈烦闷，涕唾稠粘黏，咳嗽咽嗌不利。  \n皂角子仁炒、天竺黄另研、半夏汤浸洗七次，生姜二两，去皮，同捣作饼，炙微黄、白矾明者枯过，另研，以上各四两 龙脑另研，半两 辰砂水飞，研，二两  \n上将皂角仁半夏为末，与诸药研匀，生姜汁煮面糊和丸，如梧桐子大，金箔二十片为衣，每服十五丸，加至二十五丸，食后用生姜汤送下。", "白话": "〔主治〕治痰热，安神志，除头痛眩晕、心悸恍惚、胁膈烦闷、鼻涕唾液稠粘、咳嗽咽喉不利。〔组成·照录〕皂角子仁（炒）、天竺黄（另研）、半夏（汤浸洗七次；生姜二两去皮，同捣作饼，炙微黄）、白矾（明者，枯过，另研）以上各四两，龙脑（另研）半两，辰砂（水飞，研）二两。〔方义〕皂角仁、半夏、白矾、竺黄化痰，龙脑开窍，辰砂镇心安神，为痰热惊悸之丸。〔制法·服法〕先将皂角仁、半夏为末，与诸药研匀，生姜汁煮面糊和丸如梧桐子大，以金箔二十片为衣，每服十五丸，渐加至二十五丸，食后生姜汤送下。"}, {"source": "条764｜《奇效良方》卷四十六·秘传酸枣仁汤", "原文": "《奇效良方》卷四十六：“秘传酸枣仁汤。治心肾水火不交，精血虚耗，痰饮内蓄，怔忡恍惚，夜卧不安。 \n酸枣仁去皮，炒、 远志去心，制、 黄芪、 白茯苓、 莲肉去心、 当归酒浸、 人参、 茯神以上各一两 陈皮、 粉草炙，各半两  \n上㕮咀，每服四钱，水一盏半，生姜三片，枣一枚，以瓦器煎七分，日二服，临卧一服。", "白话": "〔主治〕治心肾水火不交，精血虚耗，痰饮内蓄，怔忡恍惚，夜卧不安。〔组成·照录〕酸枣仁（去皮，炒）、远志（去心，制）、黄芪、白茯苓、莲肉（去心）、当归（酒浸）、人参、茯神以上各一两，陈皮、粉草（炙）各半两。〔方义〕枣仁、远志、茯神、莲肉养心安神，参、芪、苓、草益气，当归养血，陈皮理气化痰，为心肾不交、怔忡不寐之名方。〔制法·服法〕上药切碎，每服四钱，用水一盏半，加生姜三片、大枣一枚，以瓦器煎取七分，日二服，临卧一服。"}, {"source": "条765｜《奇效良方》卷四十六·益荣汤", "原文": "《奇效良方》卷四十六：“益荣汤。治思虑过多，耗伤心血，心血既伤，神无所守。是以怔忡恍惚，善悲忧，少颜色，夜不多寐，小便或浊。  \n当归去芦，酒浸、  黄芪去芦、  小草、  酸枣仁炒，去壳、  柏子仁炒、  茯神去木、  木香不见火、  麦门冬去心、  白芍药、  人参去芦、  紫石英煅研、  甘草炙，各一钱  \n上作一服，水二盅，生姜三片，红枣一枚，煎一盅，不拘时服。", "白话": "〔主治〕治思虑过多，耗伤心血；心血既伤，神无所守，于是怔忡恍惚，善悲忧，面色少泽，夜寐不多，小便或浊。〔组成·照录〕当归（去芦，酒浸）、黄芪（去芦）、小草、酸枣仁（炒，去壳）、柏子仁（炒）、茯神（去木）、木香（不见火）、麦门冬（去心）、白芍药、人参（去芦）、紫石英（煅研）、甘草（炙）各一钱。〔方义〕归、芪、参、芍益气养血，枣仁、柏仁、茯神、远志苗（小草）、紫石英养心镇悸，麦冬滋阴，木香理气，为思虑伤心血之剂。〔制法·服法〕上作一服，用水二盅，加生姜三片、红枣一枚，煎取一盅，不"}, {"source": "条766｜《奇效良方》卷四十六·人参远志丸", "原文": "《奇效良方》卷四十六：“人参远志丸。治心气不安，惊悸恍惚，神思不宁。  \n人参去芦、远志去心、酸枣仁、黄芪以上各半两 桔梗去芦、官桂去皮、丹砂以上各二钱半 天门冬去心、白茯苓去皮、菖蒲各七钱半  \n上为细末，炼蜜为丸，如梧桐子大，每服三十丸，食远用米汤送下。", "白话": "〔主治〕治心气不安，惊悸恍惚，神思不宁。〔组成·照录〕人参（去芦）、远志（去心）、酸枣仁、黄芪以上各半两，桔梗（去芦）、官桂（去皮）、丹砂以上各二钱半，天门冬（去心）、白茯苓（去皮）、菖蒲各七钱半。〔方义〕参、芪益心气，远志、菖蒲、枣仁、茯苓安神，丹砂镇心，天冬滋阴，桂温心阳，桔梗载药上行。〔制法·服法〕共为细末，炼蜜为丸如梧桐子大，每服三十丸，食远（离进食稍远时）用米汤送下。"}, {"source": "条767｜《奇效良方》卷四十六·远志丸", "原文": "《奇效良方》卷四十六：“远志丸。治因事有所大惊，梦寐不祥，登高涉险，神魂不安，惊悸恐怯。  \n远志去心，姜汁制、石菖蒲各二两 茯神去皮木、白茯苓去皮、参去芦、龙齿各一两  \n上为细末，炼蜜和丸，如梧桐子大，朱砂为衣，每服七十丸，用白汤送下，食后临卧服。", "白话": "〔主治〕治因事大惊，梦寐不祥，登高涉险，神魂不安，惊悸恐怯。〔组成·照录〕远志（去心，姜汁制）、石菖蒲各二两，茯神（去皮木）、白茯苓（去皮）、参（去芦）、龙齿各一两。〔方义〕远志、菖蒲、茯神、茯苓、人参益气定志安神，龙齿重镇，为惊恐惊悸之剂。〔制法·服法〕共为细末，炼蜜和丸如梧桐子大，以朱砂为衣，每服七十丸，白汤送下，食后临卧服。"}, {"source": "条768｜《奇效良方》卷四十六·姜术汤", "原文": "《奇效良方》卷四十六：“姜术汤。治虚证，停饮怔忡。　　\n白姜生、白术、茯苓去皮 、夏曲各二钱 辣桂去皮、甘草炙，各半钱　　\n上作一服，水二盅，生姜三片，红枣一枚，煎一盅，不拘时服。", "白话": "〔主治〕治虚证，停饮怔忡。〔组成·照录〕白姜（生）、白术、茯苓（去皮）、夏曲各二钱，辣桂（去皮）、甘草（炙）各半钱。〔方义〕干姜、白术、茯苓温中化饮，半夏曲化痰，桂通阳，为虚证停饮怔忡之剂。〔制法·服法〕上作一服，用水二盅，加生姜三片、红枣一枚，煎取一盅，不拘时候服。"}, {"source": "条769｜《奇效良方》卷六十三·滋阴万病丸", "原文": "《奇效良方》卷六十三：“滋阴万病丸。治虚劳血弱，肌肉枯燥，手足多烦，肢节酸痛，须发脱落，面少颜色，腹中拘急，痛引腰背，去血过多。崩伤内竭，胸中气短，昼夜不得眠，情思不乐，怔忡多汗。  \n熟地黄、当归各一两  \n上为末，炼蜜和丸，如梧桐子大，每服二十丸，不拘时米饮送下。", "白话": "〔主治〕治虚劳血弱，肌肉枯燥，手足多烦，肢节酸痛，须发脱落，面色少泽，腹中拘急，痛引腰背，失血过多、崩漏伤内，胸中气短，昼夜不得眠，情思不乐，怔忡多汗。〔组成·照录〕熟地黄、当归各一两。〔方义〕熟地滋阴补血，当归养血和血，药仅二味而滋阴养血力专，血足则怔忡自止。〔制法·服法〕上为末，炼蜜和丸如梧桐子大，每服二十丸，不拘时候米饮送下。"}, {"source": "条770｜《奇效良方》卷六十三·大圣散", "原文": "《奇效良方》卷六十三：“大圣散。治妊娠怔悸，睡里多惊，腹胁膨胀，坐卧不宁。  \n白茯苓去皮、麦门冬去心、黄芪去芦，蜜炙、当归去芦，酒浸、川芎各一钱半 木香不见火、人参、甘草炙，各一钱  \n上作一服，水二盅，生姜五片，煎至一盅，不拘时服。", "白话": "〔主治〕治妊娠怔悸，睡中多惊，腹胁膨胀，坐卧不宁。〔组成·照录〕白茯苓（去皮）、麦门冬（去心）、黄芪（去芦，蜜炙）、当归（去芦，酒浸）、川芎各一钱半，木香（不见火）、人参、甘草（炙）各一钱。〔方义〕参、芪、苓、草益气，归、芎养血和血，麦冬滋阴，木香理气安胎，为妊娠心虚怔悸之剂。〔制法·服法〕上作一服，用水二盅，加生姜五片，煎至一盅，不拘时候服。"}, {"source": "条771｜《奇效良方》卷六十四·宁心膏", "原文": "《奇效良方》卷六十四：“宁心膏。治小儿惊悸不宁，心经有热，多啼，安神定志。  \n人参、白术、茯神、茯苓、山药、羌活、甘草各一两 朱砂二两 片脑一钱 麝香少许 金箔二十片，为衣  \n上为细末，炼蜜为丸，如芡实大，每服半丸，用薄荷汤无时化下。", "白话": "〔主治〕治小儿惊悸不宁，心经有热，多啼哭；能安神定志。〔组成·照录〕人参、白术、茯神、茯苓、山药、羌活、甘草各一两，朱砂二两，片脑一钱，麝香少许，金箔二十片（为衣）。〔方义〕参、术、苓、薯蓣、草健脾益气，茯神、朱砂、金箔镇心安神，片脑、麝香开窍，羌活散风，为小儿惊悸之膏丸。〔制法·服法〕上为细末，炼蜜为丸如芡实大，每服半丸，用薄荷汤不拘时候化下。"}, {"source": "条772｜《奇效良方》卷六十四·辰砂胆星膏", "原文": "《奇效良方》卷六十四：“辰砂胆星膏。治小儿痰热惊热，气急喘嗽，惊悸不安。  \n辰砂一钱 牛胆南星一两 琥珀、青礞石末各一钱 天竺黄一钱 甘草五分 麝香少许  \n上为细末，炼蜜为丸，如芡实大，每服半丸，用生姜汤不拘时化服。", "白话": "〔主治〕治小儿痰热、惊热，气急喘嗽，惊悸不安。〔组成·照录〕辰砂一钱，牛胆南星一两，琥珀、青礞石末各一钱，天竺黄一钱，甘草五分，麝香少许。〔方义〕胆星、竺黄、礞石清热化痰坠痰，琥珀、辰砂镇心安神，麝香开窍，为小儿痰热惊悸之剂。〔制法·服法〕上为细末，炼蜜为丸如芡实大，每服半丸，用生姜汤不拘时候化服。"}, {"source": "条773｜《丹溪心法》卷四·养心汤", "原文": "《丹溪心法》卷四：“养心汤。治心虚血少，惊悸不宁。治停水怔忡，加槟榔、赤茯苓。", "白话": "〔主治〕治心虚血少，惊悸不宁。〔加减〕治停水怔忡者，加槟榔、赤茯苓。〔组成·照录〕原稿未载。〔方义〕从主治看，为养心补血、安神定悸之剂（参后世养心汤方）。〔服法〕原稿未载。"}, {"source": "条774｜《丹溪心法》卷四·治劳役心跳方", "原文": "《丹溪心法》卷四：“真觉心跳者是血少，四物、朱砂安神之类。入方。治劳役心跳大虚证。　　\n朱砂 归身 白芍 侧柏叶炒，五钱 川芎、陈皮、甘草各二钱 黄连炒,一钱半　　\n上为末，猪心血丸服。", "白话": "〔论述〕真正觉心跳者，是血少所致，用四物汤、朱砂安神丸之类。入方：治劳役过度、心跳之大虚证。〔组成·照录〕朱砂、归身、白芍、侧柏叶（炒）各五钱，川芎、陈皮、甘草各二钱，黄连（炒）一钱半。〔方义〕四物（归、芍、芎）加侧柏养血凉血，黄连、朱砂清心镇心，陈皮、甘草和中，为劳役血虚心跳之方。〔制法·服法〕上为末，以猪心血为丸服。"}, {"source": "条775｜《本草单方》卷一·乌雌鸡方（《姚僧垣方》）", "原文": "《本草单方》卷一：“虚损积劳。凡男女因积虚，或大病后虚损，沉困酸疼，盗汗，少气，喘惙，或小腹拘急，心悸胃弱，多卧少起，渐至瘦削。若年深，五脏气竭，则难治也。  \n用乌雌鸡一头，治如食法。以生地黄一升切、饴糖一升，纳腹内，缚定，铜锡器贮于锅内，隔汤蒸五升米熟，取出，食肉饮汁。勿用盐。一月一作，神效。 《姚僧垣方》", "白话": "〔主治〕虚损积劳：凡男女因积虚，或大病之后虚损，身体沉重困倦酸疼，盗汗，少气，喘促，或小腹拘急，心悸胃弱，多卧少起，渐渐消瘦。若病程年深，五脏气竭，则难治。〔组成·照录〕乌雌鸡一头（按食用法处理），生地黄一升（切）、饴糖一升。〔方义〕乌雌鸡补虚劳，生地黄滋阴养血，饴糖建中缓急，为虚劳心悸之食疗方。〔制法·服法〕将生地黄、饴糖纳入鸡腹内缚定，用铜锡器盛贮于锅内，隔水蒸至五升米熟为度，取出，食肉饮汁。勿用盐。每月制作一次，神效。"}, {"source": "条776｜《本草单方》卷七·天麻丸", "原文": "《本草单方》卷七：“天麻丸。消风化痰，清利头目，宽胸利膈；治心忪烦闷，头运欲倒，项急，肩背拘倦，神昏多睡，肢节烦痛，皮肤搔痒，偏正头痛，鼻齆，面目虚浮，并宜服之。  \n天麻半两 芎二两  \n为末，炼蜜丸，如芡子大。每食后嚼一丸，茶酒任下。”", "白话": "〔功用·主治〕消风化痰，清利头目，宽胸利膈；治心悸烦闷，头晕欲倒，颈项拘急，肩背拘倦，神昏多睡，肢节烦痛，皮肤瘙痒，偏正头痛，鼻塞（齆），面目虚浮，并宜服之。〔组成·照录〕天麻半两、芎（原稿此字后一字残损）二两。〔方义〕天麻息风定眩，川芎行气活血、上行头目，风痰清则悸眩止。〔制法·服法〕上为末，炼蜜为丸如芡子大，每于食后嚼一丸，茶、酒任下。"}, {"source": "条777｜《本草单方》卷十三·醋附丸", "原文": "《本草单方》卷十三：“醋附丸。治妇人、室女一切经候不调，血气刺痛，腹胁膨胀，心怔乏力，面色萎黄，头晕恶心，崩漏带下，便血，癥瘕积聚，及妇人数堕胎，由气不升降，服此尤妙。  \n香附子米醋浸半日，沙锅煮干，捣，焙，石臼为末，醋糊为丸，醋汤下。", "白话": "〔主治〕治妇人、室女一切月经不调，血气刺痛，腹胁膨胀，心悸乏力，面色萎黄，头晕恶心，崩漏带下，便血，癥瘕积聚，以及妇人屡次堕胎（因气机升降失常者），服此尤妙。〔组成·照录〕香附子。〔方义〕香附疏肝理气、调经止痛，醋制入肝，气顺血和则怔悸自止。〔制法·服法〕香附子用米醋浸半日，沙锅煮干，捣碎，焙干，石臼研为末，醋糊为丸，醋汤送下。"}, {"source": "条778｜《原幼心法》中卷·惊热（凉惊丸、安神丸）", "原文": "《原幼心法》中卷：“惊热者，遍身发热，面青白，自汗，心悸不宁，脉数，烦躁，颠叫恍惚，以钱氏凉惊丸、安神丸主之。", "白话": "〔论述〕惊热之证：遍身发热，面色青白，自汗，心悸不宁，脉数，烦躁，惊叫恍惚——用钱氏（钱乙）凉惊丸、安神丸主治。〔组成·照录〕原稿未载（见钱乙《小儿药证直诀》凉惊丸、安神丸）。〔方义〕凉惊丸清热镇惊，安神丸养心安神，热清神安则惊悸止。〔服法〕原稿未载。"}, {"source": "条779｜《医学正传》卷一·二陈汤加减（中风）", "原文": "《医学正传》卷一：“凡中风证，悉以二陈汤加姜汁、竹沥为主。风痰盛、声如拽锯者，加南星、枳壳、皂角、防风、栝蒌仁。或心动摇惊悸者，更加酸枣仁、茯神、侧柏叶、竹茹，连前共作一剂，煎服。", "白话": "〔论述〕凡中风证，一概以二陈汤加姜汁、竹沥为主。风痰盛、喉中痰声如拉锯者，加南星、枳壳、皂角、防风、栝蒌仁；或心动摇惊悸者，再加酸枣仁、茯神、侧柏叶、竹茹，连同前药共作一剂，煎服。〔组成·照录〕二陈汤（半夏、陈皮、茯苓、甘草）加姜汁、竹沥。〔方义〕二陈汤燥湿化痰、理气和中，加姜汁、竹沥豁痰开窍；心悸加枣仁、茯神、侧柏、竹茹以安神清热。〔服法〕水煎服。"}, {"source": "条780｜《医学正传》卷三·心经受伤加减", "原文": "《医学正传》卷三：“其或心神惊惕，怔忡无时，盗汗自汗，心烦热闷，口舌生疮，咯血面赤，脉洪而数，知其邪在心也，宜以前方去杜仲、泽泻、肉桂，加茯神、胡黄连、莲心、远志、菖蒲、朱砂之类。", "白话": "〔论述〕若心神惊惕、怔忡无时，盗汗自汗，心烦热闷，口舌生疮，咯血面赤，脉洪而数，知其邪在心，宜用前方去杜仲、泽泻、肉桂，加茯神、胡黄连、莲心、远志、菖蒲、朱砂之类。〔组成·照录〕即前补肾方（原稿未具名）去杜仲、泽泻、肉桂，加茯神、胡黄连、莲心、远志、菖蒲、朱砂。〔方义〕去温补固涩之品，加清心安神之药，为痨瘵属心经受伤之加减法。〔服法〕煎熟入童便、韭汁、竹沥（承前文）。"}, {"source": "条781｜《医学正传》卷四·玉液汤（严氏方）", "原文": "《医学正传》卷四：“玉液汤严氏方。治七情感动，气郁生涎，随气上冲，头目眩运，心嘈忪悸，眉梭骨痛。  \n大半夏汤泡七次，去皮脐 \n 上以一味薄切成片，每服四钱，加生姜十片煎，入沉香磨水一呷服，大效。", "白话": "〔出处〕玉液汤（严氏《济生方》方）。〔主治〕治七情所动，气郁生涎，随气上冲，头目眩晕，心嘈心悸，眉棱骨痛。〔组成·照录〕大半夏（汤泡七次，去皮脐）。〔方义〕半夏一味化痰降逆，痰涎降则冲气平、悸眩止。〔制法·服法〕将半夏一味薄切成片，每服四钱，加生姜十片同煎，另以沉香磨水一小口兑入服下，大效。"}, {"source": "条782｜《医学正传》卷五·惊悸养血汤（局方）", "原文": "《医学正传》卷五：“惊悸养血汤局方。治肥人因痰火而心惕然跳动惊起。  \n黄芪、茯神、半夏曲、川芎各五分 远志去心，甘草水浸、桂心、柏子仁、酸枣仁炒、五味子、人参各二分半 甘草四分  \n上细切，作一服，生姜三片，大枣一枚，水一盏，煎至七分服。如停水，加茯神、槟榔各三分同煎。", "白话": "〔出处〕惊悸养血汤（局方）。〔主治〕治肥胖之人因痰火而心惕然跳动、惊起者。〔组成·照录〕黄芪、茯神、半夏曲、川芎各五分，远志（去心，甘草水浸）、桂心、柏子仁、酸枣仁（炒）、五味子、人参各二分半，甘草四分。〔方义〕参、芪、苓益气，枣仁、柏仁、远志、五味养心安神，半夏曲化痰，芎、桂通血脉，为肥人痰火惊悸之剂。〔制法·服法〕上药细切，作一服，加生姜三片、大枣一枚，用水一盏，煎至七分服。如停水，加茯神、槟榔各三分同煎。"}, {"source": "条783｜《医学正传》卷五·定志丸", "原文": "《医学正传》卷五：“定志丸。治心气不足，恍惚多忘，及怔忡惊悸等证。　\n人参、白茯苓各三钱 远志去心、石菖蒲各二两　　\n上为细末，炼蜜为丸，如梧桐子大，朱砂为衣，每服五十丸，食后白汤下。", "白话": "〔主治〕治心气不足，恍惚多忘，以及怔忡惊悸等证。〔组成·照录〕人参、白茯苓各三钱，远志（去心）、石菖蒲各二两。〔方义〕参、苓益心气，远志、菖蒲开窍益智安神，为心气不足、惊悸健忘之小丸。〔制法·服法〕共为细末，炼蜜为丸如梧桐子大，以朱砂为衣，每服五十丸，食后白汤送下。"}, {"source": "条784｜《医学正传》卷五·祖传方（惊悸方）", "原文": "《医学正传》卷五：“祖传方治忧愁思虑伤心，令人惕然心跳动，惊悸不安之证。  \n川归酒洗用身、生地黄酒洗、远志去心、茯神各五钱 石菖蒲九节、黄连各二钱五分 牛黄一钱，另研 辰砂二钱，另研 金箔十五片  \n上以前六味研细，入牛黄、辰砂二味末子，猪心血丸如黍米大，金箔为衣，每服五十丸，煎灯心汤送下。", "白话": "〔主治〕治忧愁思虑伤心，使人惕然心跳动、惊悸不安之证。〔组成·照录〕川归（酒洗用身）、生地黄（酒洗）、远志（去心）、茯神各五钱，石菖蒲（九节）、黄连各二钱五分，牛黄一钱（另研），辰砂二钱（另研），金箔十五片。〔方义〕归、地养血，远志、菖蒲、茯神安神，黄连清心，牛黄、辰砂、金箔镇惊，为家传惊悸验方。〔制法·服法〕将前六味研细，加入牛黄、辰砂二味末，以猪心血为丸如黍米大，金箔为衣，每服五十丸，煎灯心汤送下。"}, {"source": "条785｜《医学正传》卷七·茯苓散", "原文": "《医学正传》卷七：“茯苓散。治产后心虚，怔忡不定，言语错乱。  \n人参、甘草、山药、当归各一钱 远志、茯苓、桂心、麦门冬各半钱  \n上细切，作一服，加生姜三片，大枣一枚，水一盏半，煎至一盏，去渣温服。", "白话": "〔主治〕治产后心虚，怔忡不定，言语错乱。〔组成·照录〕人参、甘草、山药、当归各一钱，远志、茯苓、桂心、麦门冬各半钱。〔方义〕参、草、薯蓣益气，归、麦养血滋阴，茯苓、远志安神，桂心温心阳，为产后心虚怔忡之剂。〔制法·服法〕上药细切，作一服，加生姜三片、大枣一枚，用水一盏半，煎至一盏，去渣温服。"}, {"source": "条786｜《苍生司命》卷五·安神丸", "原文": "《苍生司命》卷五：“安神丸。治忧愁思虑伤心，惊悸善忘，夜不安卧。  \n黄连、朱砂各一两 当归、生地、炙甘草各五钱 \n上末，米糊丸。", "白话": "〔主治〕治忧愁思虑伤心，惊悸善忘，夜间不得安卧。〔组成·照录〕黄连、朱砂各一两，当归、生地、炙甘草各五钱。〔方义〕即朱砂安神丸方：朱砂镇心，黄连清热，归、地养血，甘草和中，为思虑伤心、惊悸不寐之剂。〔制法·服法〕上为末，米糊为丸。"}, {"source": "条787｜《苍生司命》卷七·养心汤", "原文": "《苍生司命》卷七：“养心汤。治心虚血少，神气不宁，令人惊悸怔忡。  \n黄芪、茯苓、茯神、半夏曲、川归、川芎各五钱 柏子仁、枣仁炒、人参、远志姜汁炒、五味、辣桂各二钱五分 甘草炙，四钱  \n共为末，每服五钱。", "白话": "〔主治〕治心虚血少，神气不宁，使人惊悸怔忡。〔组成·照录〕黄芪、茯苓、茯神、半夏曲、川归、川芎各五钱，柏子仁、枣仁（炒）、人参、远志（姜汁炒）、五味、辣桂各二钱五分，甘草（炙）四钱。〔方义〕参、芪、苓、草益气，归、芎、枣仁、柏仁、五味养血安神，半夏曲化痰，辣桂温心阳，为心虚血少惊悸怔忡之剂。〔制法·服法〕共为末，每服五钱。"}, {"source": "条788｜《苍生司命》卷七·怔忡惊悸辨", "原文": "《苍生司命》卷七：“怔忡者，心中惕惕不安，如人将捕之状，无时而作者是也。惊悸者，善恐怖，蓦然跳跃惊动，有时而作者是也。尤当分虚实治之。健忘、怔忡者，纯主不足，惊悸则不足中之有余也。\n治健忘、怔忡者多主心血不足，精神亏欠，皆用四物汤、安神丸、八味定志丸、归脾汤、天王补心丹，随证加减。", "白话": "〔论述〕怔忡者，心中惕惕不安，如有人将要捕捉自己之状，无定时而发作者是也；惊悸者，善恐怖，突然跳跃惊动，有定时而发作者是也。二者尤当分辨虚实而治之。健忘、怔忡者，纯属不足；惊悸则是不足之中兼有余。治健忘、怔忡者，多主心血不足、精神亏欠，皆用四物汤、安神丸、八味定志丸、归脾汤、天王补心丹，随证加减。〔组成·照录〕原稿未载（各方见各书）。〔方义〕怔忡主虚、惊悸兼实，故补心养血为主，佐以镇惊。〔服法〕随证加减煎服。"}, {"source": "条789｜《韩氏医通》卷下·驻阳小丹", "原文": "《韩氏医通》卷下：“驻阳小丹炼法此本古方，主乌须不验。方外一衲，因予小惠，报以炼法。  \n茯神四两，去心 赤石脂火煅存性，四两 辰砂水飞，二两 乳香二两，灯芯研 川椒二两，净，以炭烧黄土地至通红，扫净，置椒于上，以瓦缶掩之，令为出汗  \n上五味，为细末，以人乳和稀剂，入鹅、鸭蛋壳内，糊封完固，加以绛袋，令体洁妇人带于胸乳之间，四十九日，日夕不离，取出干透则成，否则坏。再研，用枣肉和为丸绿豆大。每日", "白话": "〔出处·来历〕驻阳小丹炼法：此本古方，主治乌须（黑发）无效。方外一僧人因受我小惠，报以此炼法。〔组成·照录〕茯神四两（去心），赤石脂（火煅存性）四两，辰砂（水飞）二两，乳香二两（灯芯研），川椒二两（拣净；以炭将黄土地烧至通红，扫净，置椒于其上，以瓦罐覆盖，令出汗）。〔方义〕茯神、辰砂养心镇心，赤石脂收涩，乳香行血，川椒温中，为心血不足、怔忡健忘之丹。〔制法·服法〕上五味为细末，用人乳调成稀剂，纳入鹅、鸭蛋壳内，糊封完固，外加红色布袋，令身体洁净的妇人佩带于胸乳之间，四十九日日"}, {"source": "条790｜《外科经验方·溃疡》·黄芪人参汤", "原文": "《外科经验方·溃疡》：“黄芪人参汤。治诸疮溃后，食少倦怠，口舌干燥，或寒热往来，惊悸少睡，并治之。  \n黄芪盐水拌，炒，三钱 人参 白术炒 苍术米泔水浸，炒，一钱 陈皮一钱 当归酒拌 炙甘草一钱 麦门冬五分，去心，胃寒不用 神曲五分，炒 升麻一分 黄柏三分，酒炒，腹不实者去之 五味子捣碎，炒，五分  \n作一剂，用水二钟，姜三片，煎至一钟，食远服。如少睡，加酸枣仁炒一钱。肌肉迟生，加白敛去皮，一钱。", "白话": "〔主治〕治各种疮疡溃破之后，食少倦怠，口舌干燥，或寒热往来，惊悸少睡，并治之。〔组成·照录〕黄芪（盐水拌炒）三钱，人参（原稿无量），白术（炒，原稿无量），苍术（米泔水浸，炒）一钱，陈皮一钱，当归（酒拌，原稿无量），炙甘草一钱，麦门冬五分（去心，胃寒不用），神曲五分（炒），升麻一分，黄柏三分（酒炒，腹部不实者去之），五味子五分（捣碎，炒）。〔方义〕参、芪、术、草补气，归、麦养阴，苍术、陈皮、神曲健脾，升麻举陷，黄柏清余热，为疮溃后气阴两虚、惊悸少睡之剂。〔制法·服法〕作一剂，用"}, {"source": "条791｜《立斋外科发挥》卷七·归脾汤", "原文": "《立斋外科发挥》卷七：“归脾汤。治思虑伤脾，不能统摄，心血以此妄行，或吐血下血，或健忘怔忡，惊悸少寐，或心脾作痛。  \n白术炒、茯神、黄芪蜜炙、龙眼肉、酸枣仁蒸，各一钱 人参、木香各五分 甘草炙，二分半 \n作一剂，水一钟，姜一片，枣一枚，煎六分，食远并临卧服。", "白话": "〔主治〕治思虑伤脾，不能统摄，心血因此妄行，或吐血下血，或健忘怔忡、惊悸少寐，或心脾作痛。〔组成·照录〕白术（炒）、茯神、黄芪（蜜炙）、龙眼肉、酸枣仁（蒸）各一钱，人参、木香各五分，甘草（炙）二分半。〔方义〕参、芪、术、草、龙眼补脾养心，枣仁、茯神安神，木香理气使补而不滞，为思虑伤脾、心悸怔忡之名方。〔制法·服法〕作一剂，用水一钟，加姜一片、大枣一枚，煎取六分，食远及临卧服。"}, {"source": "条792｜《女科撮要》卷下·归脾汤", "原文": "《女科撮要》卷下：“归脾汤。治脾经失血，少寐发热，盗汗，或思虑伤脾，不能摄血妄行；或健忘怔忡，惊悸不寐；或心脾伤痛，怠惰嗜卧，饮食不思。  \n人参、白术、白茯苓、黄芪炒、当归、龙眼肉、远志、酸枣仁炒，各一钱 木香五分 甘草炙，五分  \n上姜枣水煎服。", "白话": "〔主治〕治脾经失血，少寐发热，盗汗；或思虑伤脾，不能摄血妄行；或健忘怔忡、惊悸不寐；或心脾伤痛，怠惰嗜卧，饮食不思。〔组成·照录〕人参、白术、白茯苓、黄芪（炒）、当归、龙眼肉、远志、酸枣仁（炒）各一钱，木香五分，甘草（炙）五分。〔方义〕即归脾汤原方，益气补血、健脾养心，为妇科心脾两虚诸证之剂。〔制法·服法〕上药加姜、枣水煎服。"}, {"source": "条793｜《女科撮要》卷下·朱砂安神丸", "原文": "《女科撮要》卷下：“朱砂安神丸。治产后血晕、心神惊悸等症。  \n朱砂飞过，五钱 生地黄一钱半 黄连酒洗，六钱 甘草炙，五分 当归一钱五分  \n上为末，饭糊为丸，每服十五丸。", "白话": "〔主治〕治产后血晕、心神惊悸等症。〔组成·照录〕朱砂（飞过）五钱，生地黄一钱半，黄连（酒洗）六钱，甘草（炙）五分，当归一钱五分。〔方义〕朱砂镇心，黄连清心，归、地养血，甘草和中，为产后惊悸之剂。〔制法·服法〕上为末，饭糊为丸，每服十五丸。"}, {"source": "条794｜《保婴撮要》卷二·额间望色（惊悸辨治）", "原文": "《保婴撮要》卷二：“额间：赤色主心经有热，烦躁惊悸，若饮水或叫哭，属本经实热，用泻心散以清心火；微赤困卧惊悸，热渴饮汤，属虚热，用秘旨安神丸以生心血；青黑主惊风，腹痛或瘛疭啼叫，用五味异功散加木香、柴胡、钩藤钩补脾肝；青黑主心腹作痛，此寒水乘心，用益黄散；微黄主惊疳，用安神丸。", "白话": "〔论述〕额部：赤色主心经有热、烦躁惊悸，若饮水或叫哭，属本经实热，用泻心散以清心火；微赤、困卧惊悸、热而口渴喜饮汤者，属虚热，用秘旨安神丸以生心血；青黑主惊风，腹痛或抽搐啼叫，用五味异功散加木香、柴胡、钩藤钩以补脾肝；青黑又主心腹作痛，此为寒水乘心，用益黄散；微黄主惊疳，用安神丸。〔组成·照录〕原稿未载（泻心散、秘旨安神丸、五味异功散、益黄散、安神丸分见各书）。〔方义〕望额色辨心经寒热虚实，分别以清心、养血、补脾肝、温中、治疳为法。〔服法〕原稿未载。"}, {"source": "条795｜《保婴撮要》·耳后望色", "原文": "《保婴撮要》：“耳后微黄主睡中惊悸咬牙，用四君子加芎、归、升麻以调理脾气。", "白话": "〔论述〕耳后微黄，主睡中惊悸、咬牙，用四君子汤加川芎、当归、升麻以调理脾气。〔组成·照录〕四君子汤（人参、白术、茯苓、甘草）加川芎、当归、升麻。〔方义〕四君子健脾益气，芎、归养血，升麻升举清阳，脾健血足则睡安惊止。〔服法〕煎服。"}, {"source": "条796｜《保婴撮要》卷三·养心汤", "原文": "《保婴撮要》卷三：“养心汤。治心血虚怯惊痫，或惊悸怔忡，盗汗无寐，发热烦躁。  \n黄芪、白茯苓、茯神、半夏曲、当归、川芎、辣桂、柏子仁、酸枣仁、五味子、人参各三钱 甘草炒，四钱  \n上每服一、二钱，姜枣水煎。", "白话": "〔主治〕治心血虚怯之惊痫，或惊悸怔忡，盗汗不寐，发热烦躁。〔组成·照录〕黄芪、白茯苓、茯神、半夏曲、当归、川芎、辣桂、柏子仁、酸枣仁、五味子、人参各三钱，甘草（炒）四钱。〔方义〕参、芪、苓、草益气，归、芎、枣仁、柏仁、五味养血安神，半夏曲化痰，辣桂温心阳，为小儿心血虚惊悸之剂。〔制法·服法〕上每服一、二钱，加姜、枣水煎。"}, {"source": "条797｜《保婴撮要》卷六·惊悸困倦治法", "原文": "《保婴撮要》卷六：“若惊悸困倦，痰盛不乳者，心脾血虚也，用四君子加芎、归、酸枣仁。", "白话": "〔论述〕若惊悸困倦、痰盛而不吃乳者，属心脾血虚，用四君子汤加川芎、当归、酸枣仁。〔组成·照录〕四君子汤加川芎、当归、酸枣仁。〔方义〕四君子健脾益气，芎、归养血，枣仁安神，脾健血足则痰消悸安。〔服法〕煎服。"}, {"source": "条798｜《保婴撮要》卷八·朱砂安神丸（心疳）", "原文": "《保婴撮要》卷八：“朱砂安神丸。治心疳怔忡，心中痞闷。  \n朱砂四钱 黄连、生地黄各半两 生甘草二钱半 兰香叶二钱，烧灰 铜青、轻粉各五分  \n上为末，干敷上。", "白话": "〔主治〕治心疳怔忡，心中痞闷。〔组成·照录〕朱砂四钱，黄连、生地黄各半两，生甘草二钱半，兰香叶二钱（烧灰），铜青、轻粉各五分。〔方义〕黄连、生地清心热，朱砂镇心，兰香叶（罗勒）和中，铜青、轻粉杀虫消疳，为心疳惊悸之剂。〔制法·服法〕上为末，干敷上（原稿如此）。"}, {"source": "条799｜《保婴撮要》卷十·人参养荣汤", "原文": "《保婴撮要》卷十：“人参养荣汤。治病后时自汗，或发潮热，口干食少，心虚惊悸，咳而下痢。前方去川芎，加陈皮、五味子、远志。", "白话": "〔主治〕治病后时时自汗，或发潮热，口干食少，心虚惊悸，咳嗽而下痢。〔组成·照录〕即前方（人参养荣汤）去川芎，加陈皮、五味子、远志。〔方义〕人参养荣汤气血双补，去川芎之走窜，加陈皮理气、五味敛汗、远志安神，为病后心虚惊悸之加减法。〔服法〕煎服（原稿未具）。"}, {"source": "条800｜《保婴撮要》卷十三·黄连安神丸", "原文": "《保婴撮要》卷十三：“黄连安神丸。治心经血热发热，惊悸不安。  \n黄连五分 生甘草二钱五分 生地黄五钱 当归 朱砂三钱  \n上为末，饭糊丸，小豆大。每服十五丸，滚汤下。如二三服不应，当服归脾汤，婴儿乳母并服。", "白话": "〔主治〕治心经血热发热，惊悸不安。〔组成·照录〕黄连五分，生甘草二钱五分，生地黄五钱，当归（原稿无量），朱砂三钱。〔方义〕即朱砂安神丸加减：黄连、生地清心凉血，当归养血，朱砂镇心，甘草和中。〔制法·服法〕上为末，饭糊为丸如小豆大，每服十五丸，滚水送下。如服二三次不应，当服归脾汤，婴儿与乳母并服。"}, {"source": "条801｜《保婴撮要》卷十三·加味归脾汤", "原文": "《保婴撮要》卷十三：“加味归脾汤。治小儿因乳母忧思郁怒，胸胁作痛；或肝脾经分患疮疡之症；或寒热惊悸无寐；或便血盗汗，疮口不敛等症。  \n人参、黄芪炒、茯神去木，各二两 甘草炒 白术炒，一两 木香五分 远志去心、酸枣仁、龙眼肉、当归、牡丹皮、山栀炒，各一钱、 \n上水煎，乳母服，儿亦服之。", "白话": "〔主治〕治小儿因乳母忧思郁怒，胸胁作痛；或肝脾经分患疮疡；或寒热惊悸不寐；或便血盗汗、疮口不敛等症。〔组成·照录〕人参、黄芪（炒）、茯神（去木）各二两，甘草（炒）、白术（炒）一两，木香五分，远志（去心）、酸枣仁、龙眼肉、当归、牡丹皮、山栀（炒）各一钱。〔方义〕归脾汤加丹皮、山栀清肝凉血，母子同治，为乳母情志内伤、儿病惊悸之剂。〔制法·服法〕上药水煎，乳母服，患儿亦服之。"}, {"source": "条802｜《保婴撮要》卷十四·秘旨安神丸", "原文": "《保婴撮要》卷十四：“秘旨安神丸。治禀心脾气血虚弱，发热不安，疮不生肌，睡中则惊悸。  \n人参、半夏汤泡、酸枣仁、茯神各一钱 当归酒洗 橘红 赤芍药 五味子五粒，杵 甘草炙，三分  \n上为末，姜汁糊丸芡实大。每服一丸，姜汤下。", "白话": "〔主治〕治先天禀赋心脾气血虚弱，发热不安，疮疡不生肌肉，睡中惊悸。〔组成·照录〕人参、半夏（汤泡）、酸枣仁、茯神各一钱，当归（酒洗，原稿无量），橘红（原稿无量），赤芍药（原稿无量），五味子五粒（杵），甘草（炙）三分。〔方义〕参、苓、枣仁、五味益气养心，归、芍养血，半夏、橘红化痰，为小儿心脾虚、睡中惊悸之剂。〔制法·服法〕上为末，姜汁糊为丸如芡实大，每服一丸，姜汤送下。"}, {"source": "条803｜《保婴撮要》卷十八·济生归脾汤", "原文": "《保婴撮要》卷十八：“济生归脾汤。治脾血虚损，健忘惊悸，或心气虚不能摄血归源，以致妄行，或吐血下血，或因乳母心脾二经有热，疮不结痂，或疮痕赤色。加柴胡、山栀即加味归脾汤。  \n人参、白茯苓、黄芪、白术、龙眼肉、当归、远志、酸枣仁炒，各二钱 木香一钱 甘草五分 当归身一钱  \n上姜枣水煎，母子同服。", "白话": "〔主治〕治脾血虚损，健忘惊悸；或心气虚不能摄血归源，以致妄行，或吐血下血；或因乳母心脾二经有热，疮不结痂，或疮痕赤色。加柴胡、山栀即加味归脾汤。〔组成·照录〕人参、白茯苓、黄芪、白术、龙眼肉、当归、远志、酸枣仁（炒）各二钱，木香一钱，甘草五分，当归身一钱。〔方义〕即《济生》归脾汤原方，健脾养心、益气补血，母子同服。〔制法·服法〕上药加姜、枣水煎，母子同服。"}, {"source": "条804｜《保婴撮要》卷二十·活人酸枣仁汤", "原文": "《保婴撮要》卷二十：“活人酸枣仁汤。治痘疹虚烦，惊悸不得眠。 \n酸枣仁炒、甘草炙、知母炒、白茯苓、麦门冬去心、川芎、干姜炒，各三分  \n上水煎温服，儿大倍之。", "白话": "〔主治〕治痘疹虚烦，惊悸不得眠。〔组成·照录〕酸枣仁（炒）、甘草（炙）、知母（炒）、白茯苓、麦门冬（去心）、川芎、干姜（炒）各三分。〔方义〕枣仁养心安神，知母、麦冬滋阴清热，苓、草健脾，川芎调血，干姜温中，为痘疹虚烦惊悸不寐之剂。〔制法·服法〕上药水煎温服，儿大者加倍。"}, {"source": "条805｜《保婴金镜录·面部见色主症》·六味地黄丸", "原文": "《保婴金镜录·面部见色主症》：“若惊悸倦怠，属肝经血虚，用六味地黄丸。", "白话": "〔论述〕若惊悸倦怠，属肝经血虚，用六味地黄丸。〔组成·照录〕六味地黄丸（熟地黄、山茱萸、山药、泽泻、牡丹皮、茯苓）。〔方义〕六味地黄丸滋补肝肾之阴，阴血得充则惊悸自止。〔服法〕原稿未具（常法为炼蜜为丸，空腹淡盐汤下）。"}, {"source": "条806｜《外科枢要》卷四·归脾汤", "原文": "《外科枢要》卷四：“归脾汤。治忧思伤脾，血虚发热，食少体倦；或脾不能摄血，以致妄行吐下；或健忘怔忡，惊悸少寐；或心脾作痛，自汗盗汗；或肢体肿痛，大便不调；或妇人经候不准，晡热内热；或唇疮流注等症，不能消散溃敛。  \n白术、白茯苓、黄芪炒、当归、龙眼肉、远志、酸枣仁炒，各一钱 木香五分 甘草炙，三分 人参一钱  \n上姜、枣水煎服。", "白话": "〔主治〕治忧思伤脾，血虚发热，食少体倦；或脾不能统摄，以致妄行吐下；或健忘怔忡、惊悸少寐；或心脾作痛，自汗盗汗；或肢体肿痛，大便不调；或妇人经期不准，晡时发热、内热；或唇疮、流注等症不能消散、溃破、收敛者。〔组成·照录〕白术、白茯苓、黄芪（炒）、当归、龙眼肉、远志、酸枣仁（炒）各一钱，木香五分，甘草（炙）三分，人参一钱。〔方义〕归脾汤健脾养心、益气补血，脾能统血则诸症自愈。〔制法·服法〕上药加姜、枣水煎服。"}, {"source": "条807｜《疠疡机要》上卷·怔忡无寐辨治", "原文": "《疠疡机要》上卷：“一怔忡无寐，或兼衄血便血，若内热晡热，作渴饮汤，肢体倦怠，此脾血虚而火动也，用四君子加芎归；若思虑伤脾动火而致，用归脾汤加山栀；若发热晡热，用八珍汤加酸枣仁、茯神、远志；若因心血虚损，用柏子仁散。大抵此症皆心脾血少所致，但调补胃气，则痰清而神自安，不必专于清热治痰。", "白话": "〔论述〕其一，怔忡不寐，或兼衄血便血：若内热晡热、口渴喜饮汤、肢体倦怠，此脾血虚而火动，用四君子汤加川芎、当归；若因思虑伤脾动火而致，用归脾汤加山栀；若发热晡热，用八珍汤加酸枣仁、茯神、远志；若因心血虚损，用柏子仁散。大抵此症皆心脾血少所致，但调补胃气，则痰清而神自安，不必专于清热治痰。〔组成·照录〕四君子加芎归、归脾汤加山栀、八珍汤加枣仁茯神远志、柏子仁散（各方见各书）。〔方义〕总以补心脾之血为主，胃气得复则痰自清、神自安。〔服法〕煎服。"}, {"source": "条808｜《扶寿精方·痰门》·清热化痰丸", "原文": "《扶寿精方·痰门》：“清热化痰丸。治痰饮为患，恶心头眩，心悸，中脘不快，或因食生冷饮酒过多，脾胃不和。  \n半夏汤泡七次，五钱 陈皮去白，四钱 白茯苓、当归酒洗、川芎各三钱 黄芩酒炒、生甘草、栀子各一钱半，去杇 黄连去毛炒，一钱  \n上为细末，面糊丸，梧桐子大，食远白汤下，五十丸。", "白话": "〔主治〕治痰饮为患，恶心头眩，心悸，中脘不快；或因食生冷、饮酒过多，脾胃不和。〔组成·照录〕半夏（汤泡七次）五钱，陈皮（去白）四钱，白茯苓、当归（酒洗）、川芎各三钱，黄芩（酒炒）、生甘草、栀子各一钱半（去杇），黄连（去毛，炒）一钱。〔方义〕二陈汤（半夏、陈皮、茯苓、甘草）化痰，芩、连、栀清热，归、芎养血和血，为痰热兼血虚心悸之剂。〔制法·服法〕上为细末，面糊为丸如梧桐子大，食远白汤送下五十丸。"}, {"source": "条809｜《扶寿精方·诸虚门》·柏子养心丸", "原文": "《扶寿精方·诸虚门》：“柏子养心丸。\n柏子仁水洗净，略蒸晒干，去壳，四两，北京有净仁卖 生地黄水洗，次入酒浸蒸一时，晒一日，又酒拌如前蒸晒共五次，二两 枸杞水洗净，三两，晒干 玄参坚黑者，水洗，二两 麦门冬水润，去心、白茯神去皮木、当归酒洗，各一两 石菖蒲去尾洗净、甘草各五钱，如心神不宁，多惧少睡加酸枣仁，水润去红皮  \n健忘加远志，水润去木，甘草煎汤浸一宿，如志一两则草用五钱。  \n上为细末，除", "白话": "〔方名〕柏子养心丸。〔组成·照录〕柏子仁（水洗净，略蒸晒干，去壳）四两（北京有净仁卖），生地黄（水洗，次入酒浸蒸一时，晒一日，又酒拌如前蒸晒，共五次）二两，枸杞（水洗净）三两（晒干），玄参（坚黑者，水洗）二两，麦门冬（水润，去心）、白茯神（去皮木）、当归（酒洗）各一两，石菖蒲（去尾洗净）、甘草各五钱；如心神不宁、多惧少睡，加酸枣仁（水润，去红皮）；健忘加远志（水润，去木，用甘草煎汤浸一宿；如远志一两则甘草用五钱）。〔方义〕柏仁、茯神、菖蒲养心安神，地、杞、玄参、麦冬、当归滋阴"}, {"source": "条810｜《扶寿精方·小儿门》·抱龙丸", "原文": "《扶寿精方·小儿门》：“抱龙丸。\n南星汤泡，去皮脐，锉片，微炒为末，入黑黄牛胆中，悬风处阴干，春夏五钱，秋冬六钱 白茯苓去皮、山药各三钱 天竺黄、雄黄水飞，另研、琥珀猪胆浸一宿，火焙研，各一钱五分 麝一分 朱砂水飞，另研为衣  \n上为细末，腊月取雪，新坛盛埋土中，合药取一碗，甘草三钱，煎汁为丸。如无雪水，新汲水亦可。和匀如芡实大，阴干，葱头、薄荷汤任下。痰嗽，姜汤下。痘疹见形，白汤下。悸不安，灯心", "白话": "〔方名〕抱龙丸。〔组成·照录〕南星（汤泡，去皮脐，锉片，微炒为末，入黑黄牛胆中，悬风处阴干；春夏用五钱，秋冬用六钱），白茯苓（去皮）、山药各三钱，天竺黄、雄黄（水飞，另研）、琥珀（猪胆浸一宿，火焙研）各一钱五分，麝一分，朱砂（水飞，另研为衣）。〔方义〕胆南星、竺黄清热化痰，琥珀、朱砂镇心安神，雄黄解毒，茯苓、山药健脾，麝香开窍，为小儿痰热惊悸之丸。〔制法·服法〕上为细末；腊月取雪，用新坛盛埋土中，合药时取一碗；甘草三钱煎汁为丸（如无雪水，新汲水亦可），和匀如芡实大，阴干。葱头"}, {"source": "条811｜《扶寿精方·诸虚门》·加味宁志丸", "原文": "《扶寿精方·诸虚门》：“加味宁志丸。治虚惫精神恍惚，心思昏愦，气不足，健忘怔忡。  \n白茯苓去皮 人参 远志甘草煎汤浸软，去木 菖蒲十九节者，米泔浸 黄连去毛 酸枣仁水浸，去仁皮 柏子仁如法去壳，一两 当归酒洗、生地黄酒洗，各八钱 木香四钱，不用火 朱砂研，水飞，一两二钱，半入药半为衣  \n上为末，炼蜜丸，绿豆大，半饥时，用麦门冬去心，煎汤下五六十丸。", "白话": "〔主治〕治虚惫精神恍惚，心思昏愦，气不足，健忘怔忡。〔组成·照录〕白茯苓（去皮）、人参、远志（甘草煎汤浸软，去木）、菖蒲（十九节者，米泔浸）、黄连（去毛）、酸枣仁（水浸，去仁皮）、柏子仁（如法去壳）一两，当归（酒洗）、生地黄（酒洗）各八钱，木香四钱（不用火），朱砂（研，水飞）一两二钱（一半入药，一半为衣）。〔方义〕参、苓、归、地益气养血，远志、菖蒲、枣仁、柏仁、朱砂安神定志，黄连清心，木香理气，为虚惫怔忡健忘之剂。〔制法·服法〕上为末，炼蜜为丸如绿豆大；半饥时用麦门冬（去心）"}, {"source": "条812｜《扶寿精方·脾胃门》·黄连磨积丸", "原文": "《扶寿精方·脾胃门》：“黄连磨积丸。治一切痰饮痰积，积聚怫郁，胁下闷倦，懒惰饮食不消，或吐逆，恶心，眩晕怔忡，时作时止，用之如神。  \n黄连一两，内五钱吴茱萸同炒，五钱益智仁同炒，去二味不用，止用黄连 栀子炒，去杇、白芥子醋浸炒，各五钱 川芎、苍术米泔浸七日、桃仁去皮存尖、青皮去穰瓤、香附子童便浸，炒、莪术酒浸，炒、山楂肉、莱菔子炒研、白术各一两 三棱用西安府者，一两五钱  \n上为细末，量用汤浸蒸", "白话": "〔主治〕治一切痰饮痰积，积聚怫郁，胁下闷倦，懒惰、饮食不消，或吐逆、恶心、眩晕、怔忡，时作时止，用之如神。〔组成·照录〕黄连一两（内五钱与吴茱萸同炒、五钱与益智仁同炒，去二味不用，只用黄连），栀子（炒，去杇）、白芥子（醋浸炒）各五钱，川芎、苍术（米泔浸七日）、桃仁（去皮存尖）、青皮（去穰瓤）、香附子（童便浸，炒）、莪术（酒浸，炒）、山楂肉、莱菔子（炒研）、白术各一两，三棱（用西安府者）一两五钱。〔方义〕黄连、栀子清热，苍术、白术健脾，青皮、香附、三棱、莪术、桃仁行气破积，楂、"}, {"source": "条813｜《广嗣纪要》卷十三·大圣散（胎惊）", "原文": "《广嗣纪要》卷十三：“妊娠胎惊者，七八月以后，胎形既成，或因气闷，或因喧呼，心神脉乱，致令子惊，使母心神忪悸，睡里多惊，坐卧不宁，气急逼迫，宜服大圣散，保安胎孕，子母无虞。  \n白茯苓、川芎、麦冬、炙草、当归、木香、人参、炙芪等分  \n上㕮咀，每服七钱，水钟半，姜三片，煎服。", "白话": "〔主治〕妊娠胎惊：七八月以后，胎形已成，或因气闷，或因喧呼惊叫，心神脉乱，以致胎儿受惊，使母体心悸，睡中多惊，坐卧不宁，气急逼迫——宜服大圣散，保安胎孕，母子无虞。〔组成·照录〕白茯苓、川芎、麦冬、炙草、当归、木香、人参、炙芪各等分。〔方义〕参、芪、苓、草益气，归、芎养血和血，麦冬滋阴，木香理气安胎，为妊娠胎惊之剂。〔制法·服法〕上药切碎，每服七钱，用水一钟半，加姜三片，煎服。"}, {"source": "条814｜《养生四要》卷四·天王补心丹", "原文": "《养生四要》卷四：“天王补心丹。\n熟地黄、白茯苓、人参、远志去心，甘草水煎、石菖蒲、玄参、柏子仁去壳、天冬去心、麦冬去心、丹参、酸枣仁去壳，炒、炙甘草、归身酒洗、杜仲去皮，姜汁炒，断丝取末、五味各一两\n上十五味，共为末，炼蜜杵为丸，如弹子大，每丸重一钱，金箔为衣，每服一丸，枣汤化下，临卧食远服。此方熟地黄、白茯苓、天冬、玄参、杜仲、五味，皆补肾之药也。其制方之法，以熟地黄、当归、五味、杜仲益血固精", "白话": "〔方名〕天王补心丹。〔组成·照录〕熟地黄、白茯苓、人参、远志（去心，甘草水煎）、石菖蒲、玄参、柏子仁（去壳）、天冬（去心）、麦冬（去心）、丹参、酸枣仁（去壳，炒）、炙甘草、归身（酒洗）、杜仲（去皮，姜汁炒，断丝取末）、五味各一两。〔方义〕原书自释：此方熟地黄、白茯苓、天冬、玄参、杜仲、五味皆补肾之药；制方之法，以熟地黄、当归、五味、杜仲益血固精；以人参、白茯苓、柏子仁、远志、菖蒲、酸枣仁宁心保神，除惊悸、止怔忡，令人不忘；以天麦门冬、丹参、玄参、甘草清三焦、去烦热、疗咽干。此"}, {"source": "条815｜《保命歌括》卷十二·平补镇心丹", "原文": "《保命歌括》卷十二：“平补镇心丹。治心血不足，时或怔忡，夜多异梦，如坠层崖。常服安心肾，益荣卫。\n白茯苓、五味子、车前子、茯神、桂心、麦冬各一两二钱半 远志甘草水煮，一两半，去心 天冬、山药姜汁蒸、地黄酒蒸，各一两半 酸枣仁去壳、炒，二钱半 人参半两 龙齿二两半 朱砂水飞，半两，为衣  \n上为末，炼蜜丸，如梧桐子大，每二十，空心米饮温酒下。", "白话": "〔主治〕治心血不足，时时怔忡，夜多怪梦，如坠层崖。常服安心肾、益营卫。〔组成·照录〕白茯苓、五味子、车前子、茯神、桂心、麦冬各一两二钱半，远志（甘草水煮）一两半（去心），天冬、山药（姜汁蒸）、地黄（酒蒸）各一两半，酸枣仁（去壳，炒）二钱半，人参半两，龙齿二两半，朱砂（水飞）半两（为衣）。〔方义〕二茯、远志、枣仁、龙齿、朱砂安神镇心，二冬、地黄、山药、五味滋阴，参、桂益气温阳，车前子利湿，为心血不足怔忡之平补剂。〔制法·服法〕上为末，炼蜜为丸如梧桐子大，每服二十丸，空腹米饮或温"}, {"source": "条816｜《古今医统大全》卷十八·养劳汤", "原文": "《古今医统大全》卷十八：“养劳汤。治五疸虚弱，脚软心悸，口淡耳鸣，微发寒热，气急，小便白浊，当作虚劳治之。", "白话": "〔主治〕治五疸虚弱，脚软心悸，口淡耳鸣，微发寒热，气急，小便白浊，当作虚劳治之。〔组成·照录〕原稿未载（参条731《医学纲目》养荣汤）。〔方义〕以补虚养荣、健脾养血为法，虚黄（虚疸）脚弱心悸者宜。〔服法〕原稿未载。"}, {"source": "条817｜《古今医统大全》卷四十三·济生茯苓饮子", "原文": "《古今医统大全》卷四十三：“济生茯苓饮子。治痰饮蓄于心膈，怔忡不已。  \n赤茯苓、茯神、半夏、麦门冬、陈皮各一两 沉香、槟榔、甘草各三钱   \n上咀，每服八钱，生姜五片，煎八分，食后温服。", "白话": "〔出处〕济生（《济生方》）茯苓饮子。〔主治〕治痰饮蓄于心膈，怔忡不已。〔组成·照录〕赤茯苓、茯神、半夏、麦门冬、陈皮各一两，沉香、槟榔、甘草各三钱。〔方义〕二茯、半夏、陈皮化痰蠲饮，麦冬养阴，沉香、槟榔降气下气，气降饮消则怔忡止。〔制法·服法〕上药切碎，每服八钱，加生姜五片，煎取八分，食后温服。"}, {"source": "条818｜《古今医统大全》卷四十八·补气汤（《瑞竹》）", "原文": "《古今医统大全》卷四十八：“《瑞竹》补气汤。治气虚脉浮而弱，怔忡，无力，自汗。　　\n黄芪三两，蜜水炒 人参、甘草炙，各半两 麦门冬、桔梗各一两　　\n上咀，每服四钱，姜三片煎服。", "白话": "〔出处〕《瑞竹》（《瑞竹堂经验方》）补气汤。〔主治〕治气虚、脉浮而弱，怔忡，乏力，自汗。〔组成·照录〕黄芪三两（蜜水炒），人参、甘草（炙）各半两，麦门冬、桔梗各一两。〔方义〕黄芪、参、草大补肺脾之气，麦冬滋阴，桔梗载药上行，气足则怔忡自汗止。〔制法·服法〕上药切碎，每服四钱，加姜三片煎服。"}, {"source": "条819｜《古今医统大全》卷四十九·养心汤", "原文": "《古今医统大全》卷四十九：“养心汤。治心血虚少，七情郁逆，怔忡、健忘，惊悸，不识人事。", "白话": "〔主治〕治心血虚少，七情郁逆，怔忡、健忘、惊悸，不识人事（神识不清）。〔组成·照录〕原稿未载（参条787《苍生司命》养心汤）。〔方义〕养心补血、安神定志为法。〔服法〕原稿未载。"}, {"source": "条820｜《古今医统大全》卷六十二·平胃镇心丹", "原文": "《古今医统大全》卷六十二：“平胃镇心丹。治男妇心气不足，志意不定，精神恍惚，夜多异梦，惊悸烦郁，及肾气伤败，血少气多，四肢倦怠，足膝酸疼，睡卧不安，梦寐遗精，时有白浊，渐至羸，以致耳聋。  \n熟地黄、生地黄、干山药、天门冬去心、麦门冬去心、柏子仁、茯神各四两 辰砂另研为末、苦梗炒，各一两 石菖蒲一斤 远志甘草水煮去心，七两 当归六两 龙骨一两  \n上为细末，炼蜜丸，如梧桐子大。每服三十丸，空心饮汤", "白话": "〔主治〕治男女心气不足，意志不定，精神恍惚，夜多怪梦，惊悸烦郁，以及肾气伤败，血少气多，四肢倦怠，足膝酸疼，睡卧不安，梦中遗精，时有白浊，渐至羸瘦，以致耳聋。〔组成·照录〕熟地黄、生地黄、干山药、天门冬（去心）、麦门冬（去心）、柏子仁、茯神各四两，辰砂（另研为末）、苦梗（炒）各一两，石菖蒲一斤，远志（甘草水煮去心）七两，当归六两，龙骨一两。〔方义〕二地、二冬、薯蓣、柏仁、当归滋阴养血，菖蒲、远志、茯神、辰砂、龙骨安神镇心，桔梗载药上行，为心肾不足、惊悸遗精之丹。〔制法·服法〕"}, {"source": "条821｜《古今医统大全》卷八十八·抱龙丸", "原文": "《古今医统大全》卷八十八：“抱龙丸。抱者，保也。龙者，肝也。肝应东方青龙木，木生火，谓生我者，父母也。肝为母，心为子，母安则子安，况心藏神，肝藏魂，神魂既定，惊从何生？故曰抱龙丸。理小儿诸惊，四时感冒，瘟疫邪热，烦躁不宁，痰嗽气急，疮疹欲出，发搐并宜用此。常服驱风化痰，解镇心热，和脾胃，益精神，镇虚惊恐怖谵语。  \n人参、天竺黄、琥珀、檀香、茯苓各一两五钱 甘草炙，三两 枳壳炒 枳实炒 辰砂飞，五", "白话": "〔释名·主治〕抱者，保也；龙者，肝也。肝应东方青龙木，木生火——生我者为父母，肝为母，心为子，母安则子安；况且心藏神、肝藏魂，神魂既定，惊从何生？故名抱龙丸。治小儿诸惊、四时感冒、瘟疫邪热、烦躁不宁、痰嗽气急、疮疹欲出、发搐，均宜用此。常服能驱风化痰、解镇心热、和脾胃、益精神、镇虚惊恐怖谵语。〔组成·照录〕人参、天竺黄、琥珀、檀香、茯苓各一两五钱，甘草（炙）三两，枳壳（炒）、枳实（炒）、辰砂（飞）五两，山药（炒）一斤，牛胆南星（炒）一两，金箔一百片。〔方义〕胆星、竺黄化痰，琥"}, {"source": "条822｜《古今医统大全》卷八十八·安神丸", "原文": "《古今医统大全》卷八十八：“安神丸。治小儿惊悸渴闷，脉实面红，颊赤口燥。  \n麦门冬、马牙硝、白茯苓、山药、寒水石各半两 朱砂一两 甘草半两 龙胆一字  \n上为末，炼蜜为丸，如鸡头子大，每服半丸，砂糖水下。", "白话": "〔主治〕治小儿惊悸口渴烦闷，脉实面红，颊赤口燥。〔组成·照录〕麦门冬、马牙硝、白茯苓、山药、寒水石各半两，朱砂一两，甘草半两，龙胆一字。〔方义〕马牙硝、寒水石、龙胆清热泻火，麦冬滋阴，朱砂镇心，苓、薯蓣、草健脾和中，为小儿心经实热惊悸之剂。〔制法·服法〕上为末，炼蜜为丸如鸡头子大，每服半丸，砂糖水送下。"}, {"source": "条823｜《古今医统大全》卷八十八·醒风汤", "原文": "《古今医统大全》卷八十八：“醒风汤。治小儿吐泻后胃虚生风，手足搐搦惊悸。  \n天麻炮 防风 人参 白附子炮 全蝎毒炒 僵蚕去嘴炒 天南星 甘草炙  \n上咀，用姜三片、冬瓜仁三十粒同煎，不拘时服。", "白话": "〔主治〕治小儿吐泻之后胃虚生风，手足抽搐惊悸。〔组成·照录〕天麻（炮）、防风、人参、白附子（炮）、全蝎（毒炒）、僵蚕（去嘴，炒）、天南星、甘草（炙）（原稿各药均无剂量）。〔方义〕天麻、全蝎、僵蚕息风止痉，防风散风，南星、白附化痰，参、草益气和胃，为吐泻后虚风惊悸之剂。〔制法·服法〕上药切碎，用姜三片、冬瓜仁三十粒同煎，不拘时候服。"}, {"source": "条824｜《古今医统大全》卷八十九·龙胆丸", "原文": "《古今医统大全》卷八十九：“龙胆丸。治小儿心疳，颊赤面黄，鼻干心燥，口内生疮，惊悸。  \n龙胆草 赤茯苓 川黄连 胡黄连 朱砂二钱 麝香一字  \n上为极细末，蒸饼泡为丸，黍米大。每服二十丸，食远白汤下。", "白话": "〔主治〕治小儿心疳，颊赤面黄，鼻干心燥，口内生疮，惊悸。〔组成·照录〕龙胆草、赤茯苓、川黄连、胡黄连、朱砂二钱、麝香一字（原稿前四味无剂量）。〔方义〕龙胆、连、胡连清心泻疳热，朱砂镇心，麝香开窍，赤苓利湿，为小儿心疳惊悸之剂。〔制法·服法〕上为极细末，蒸饼泡为丸如黍米大，每服二十丸，食远白汤送下。"}, {"source": "条825｜《明医指掌》卷三·四物汤", "原文": "《明医指掌》卷三：“四物汤。补血之要药。  \n当归二钱，分三，治血中主药也，通肝经，全能活血，各归其经也  熟地黄一钱，血中血药也，通肾经，能生真阴之虚也  川芎一钱半，血中气药也，通肝经，能行血滞于气也  白芍药一钱半，阴分药也，通脾经，能治血虚腹痛也  \n上锉，一剂，水煎服。怔忡恍惚，加远志、枣仁。", "白话": "〔功用〕补血之要药。〔组成·照录〕当归二钱（原稿注“分三”），治血中主药也，通肝经，全能活血，各归其经也；熟地黄一钱，血中血药也，通肾经，能生真阴之虚也；川芎一钱半，血中气药也，通肝经，能行血滞于气也；白芍药一钱半，阴分药也，通脾经，能治血虚腹痛也。〔方义〕归、芎、芍、地四药配伍，补血活血、调养肝脾，为补血之祖方。〔制法·服法〕上药锉，一剂，水煎服。〔加减〕怔忡恍惚者，加远志、枣仁。"}, {"source": "条826｜《明医指掌》卷四·虚黄（四君子汤）", "原文": "《明医指掌》卷四：“虚黄者，口淡怔忡，耳鸣脚软，怠惰无力，寒热溲白是也。虚黄  虚黄耳鸣口淡，怔忡微热，四肢无力，怠惰嗜卧，脚软脉沉细，四君子汤。若兼食积发黄者，小温中丸、大温中丸、或用六君子汤加茵陈、苍术、山药。", "白话": "〔论述〕虚黄之证：口淡、怔忡，耳鸣脚软，怠惰无力，寒热、小便白，即是。虚黄：耳鸣口淡，怔忡微热，四肢无力，怠惰嗜卧，脚软，脉沉细——用四君子汤；若兼食积发黄者，用小温中丸、大温中丸，或用六君子汤加茵陈、苍术、山药。〔组成·照录〕四君子汤（人参、白术、茯苓、甘草）；六君子汤加茵陈、苍术、山药。〔方义〕虚黄属脾虚血少，四君子健脾益气，脾旺则气血生化有源，怔忡自愈。〔服法〕煎服。"}, {"source": "条827｜《明医指掌》卷四·补中益气汤", "原文": "《明医指掌》卷四：“补中益气汤。治形神劳役并饮食失节，劳倦虚损，身热而烦，脉洪大而虚，头痛，或恶寒而渴，自汗无力，气高而喘。  \n黄芪蜜炙，一钱五分 人参一钱 甘草炙，五分 归身酒洗，一钱 陈皮不去白，五分 白术五分 柴胡三分 升麻三分  \n上锉，一剂，生姜三片，大枣二枚，水煎温服。按：经曰：五味入口，甘先入脾。是方参、芪、归、术、甘草皆甘物也，故可以入脾而补中气……如用心太过，神思不宁，或怔忡惊", "白话": "〔主治〕治形体精神劳役并饮食失节，劳倦虚损，身热而烦，脉洪大而虚，头痛，或恶寒而渴，自汗无力，气高而喘。〔组成·照录〕黄芪（蜜炙）一钱五分，人参一钱，甘草（炙）五分，归身（酒洗）一钱，陈皮（不去白）五分，白术五分，柴胡三分，升麻三分。〔方义〕参、芪、术、草补中益气，归身养血，陈皮理气，柴胡、升麻升举清阳，为劳倦气虚发热之主方。〔制法·服法〕上药锉，一剂，加生姜三片、大枣二枚，水煎温服。〔按语〕经曰：“五味入口，甘先入脾。”此方参、芪、归、术、甘草皆甘味之品，故能入脾而补中气…"}, {"source": "条828｜《明医指掌》卷七·戊字号保真汤", "原文": "《明医指掌》卷七：“戊字号保真汤。治劳证骨蒸体热而虚。  \n当归三分，酒洗 人参三分，去芦 生地黄三分 熟地黄三分 白术三分，炒 黄芪三分，蜜炙 赤茯苓三分 白茯苓三分 天冬二分，去心 麦冬二分，去心 赤芍药分半 白芍药分半 知母二分，盐炒 黄柏二分，盐炒 五味子二分 甘草一分半 陈皮一分半 柴胡二分 地骨皮二分  \n上，用水二盏，姜三片，枣五枚，莲心五个，每日三食前各进一服。惊悸加茯苓、茯神、远", "白话": "〔主治〕治劳证骨蒸、体热而虚。〔组成·照录〕当归三分（酒洗），人参三分（去芦），生地黄三分，熟地黄三分，白术三分（炒），黄芪三分（蜜炙），赤茯苓三分，白茯苓三分，天冬二分（去心），麦冬二分（去心），赤芍药分半，白芍药分半，知母二分（盐炒），黄柏二分（盐炒），五味子二分，甘草一分半，陈皮一分半，柴胡二分，地骨皮二分。〔方义〕四君、四物合二冬、知柏、地骨皮，气血双补兼清虚热，为痨证骨蒸之剂。〔制法·服法〕上药，用水二盏，加姜三片、大枣五枚、莲心五个，每日三餐前各进一服。〔加减〕惊"}, {"source": "条829｜《医便》卷三·归脾汤", "原文": "《医便》卷三：“归脾汤。治思虑过度，损伤心血，健忘怔忡，不寐。此药解郁结，养心健脾生血。  \n白术、白茯苓、黄芪 、归各一钱 木香三分 圆眼肉三枚 人参八分 甘草炙，三分 酸枣仁炒研，一钱二分  \n上用姜一片，枣一枚，水煎，食远服。", "白话": "〔主治〕治思虑过度，损伤心血，健忘怔忡，不寐。此药能解郁结，养心健脾生血。〔组成·照录〕白术、白茯苓、黄芪、归各一钱，木香三分，圆眼肉三枚，人参八分，甘草（炙）三分，酸枣仁（炒研）一钱二分。〔方义〕即归脾汤，健脾养心、益气补血，心脾得养则怔忡健忘自愈。〔制法·服法〕上用姜一片、大枣一枚，水煎，食远服。"}, {"source": "条830｜《脉症治方》卷四·二陈汤加减", "原文": "《脉症治方》卷四：“二陈汤。心下怔忡，属痰，加麦门冬、枳实、竹茹各等分。脾黄，加白术、厚朴、苍术各一钱、草果七分。", "白话": "〔论述〕心下怔忡属痰者，二陈汤加麦门冬、枳实、竹茹各等分。脾黄（脾虚发黄）者，加白术、厚朴、苍术各一钱、草果七分。〔组成·照录〕二陈汤（半夏、陈皮、茯苓、甘草）加麦门冬、枳实、竹茹；或加白术、厚朴、苍术、草果。〔方义〕二陈化痰，麦冬、竹茹清热除烦，枳实下气；脾虚加术、朴、苍、果健脾燥湿。〔服法〕煎服。"}, {"source": "条831｜《赤水玄珠》卷九·海藏龙脑鸡苏丸", "原文": "《赤水玄珠》卷九：“海藏龙脑鸡苏丸。治上焦热，除烦解劳，去肺热咳衄，血热惊悸，脾胃口疳，吐血，肝胆热，泣出口苦，肾热神志不定。上而酒毒，膈热，消渴。下而血滞，五淋，血崩等疾。  \n薄荷一斤 麦门冬去心、阿胶炒、黄芪、薄黄炒、人参已上俱净药、木通、银柴胡各二两，锉，同木通浸一宿，绞出汁 生地黄六两 甘草一两五钱 黄连一两  \n上为细末，好蜜二升，先煎一二沸，然后下生地黄末，不住手搅匀，加木通、柴胡汁", "白话": "〔出处〕海藏（王好古）龙脑鸡苏丸。〔主治〕治上焦热，除烦解劳，去肺热咳衄、血热惊悸、脾胃口疳、吐血、肝胆热、流泪口苦、肾热神志不定；上而酒毒、膈热、消渴，下而血滞、五淋、血崩等疾。〔组成·照录〕薄荷一斤，麦门冬（去心）、阿胶（炒）、黄芪、薄黄（炒）、人参以上俱净药、木通、银柴胡各二两（锉，同木通浸一宿，绞出汁），生地黄六两，甘草一两五钱，黄连一两。〔方义〕薄荷、鸡苏（薄荷类）清凉宣散，生地、麦冬、阿胶滋阴凉血，芩（黄连）清热，参、芪益气，木通、柴胡引热下行，为血热惊悸、上焦烦"}, {"source": "条832｜《医学入门·外集》·参胡温胆汤", "原文": "《医学入门·外集》：“参胡温胆汤。\n陈皮、半夏、茯苓、枳实、人参各一钱，竹茹、香附、麦门冬、柴胡、桔梗各八分，甘草三分  姜三片  枣二枚\n水煎温服。\n治心胆虚怯，触事易惊，梦寝不安，气郁生痰，变生诸证，或短气悸乏，或复自汗，四肢浮肿，饮食无味，烦躁不安。", "白话": "〔方名〕参胡温胆汤。〔组成·照录〕陈皮、半夏、茯苓、枳实、人参各一钱，竹茹、香附、麦门冬、柴胡、桔梗各八分，甘草三分，姜三片，枣二枚。〔方义〕温胆汤加参、柴、麦冬、香附、桔梗，化痰和胃兼疏肝益气养阴，为心胆虚怯、气郁生痰之剂。〔制法·服法〕水煎温服。〔主治〕治心胆虚怯，触事易惊，睡眠不安，气郁生痰，变生诸证：或短气心悸乏力，或又自汗，四肢浮肿，饮食无味，烦躁不安。"}, {"source": "条833｜《医学入门·外集》·痰火滞中（调中汤）", "原文": "《医学入门·外集》：“凡咽痛喉闭，膈噎胸痞，癫狂惊悸，怔忡健忘之类，皆痰火滞中之所为也，小调中汤，大调中汤。", "白话": "〔论述〕凡咽痛喉闭、膈噎胸痞、癫狂惊悸、怔忡健忘之类，皆痰火滞于中焦所致，用小调中汤、大调中汤治之。〔组成·照录〕原稿未载（小调中汤、大调中汤见《医学入门》）。〔方义〕痰火滞中，当调中化痰清火。〔服法〕原稿未载。"}, {"source": "条834｜《医学入门·外集》·九种心痛（悸痛）", "原文": "《医学入门·外集》：“七情怔悸虫不定，九种：悸痛、虫痛、来去痛、疰痛、饮痛、食痛、风痛、冷痛、热痛。悸痛，内因七情，轻则怔忡惊悸，似痛非痛，妙香散、四七汤、小草丸，热者连附六一汤；重则两目赤黄，手足青至食，即真痛，不治。虫痛，湿热生虫攻心，痛发难当，痛定能食，饥则临沐，灵槟散、乌梅丸、化虫丸选用。", "白话": "〔论述〕七情怔悸（原稿作“七情怔悸虫不定”，文义未详），心痛有九种：悸痛、虫痛、来去痛、疰痛、饮痛、食痛、风痛、冷痛、热痛。悸痛：内因七情，轻则怔忡惊悸，似痛非痛，用妙香散、四七汤、小草丸；有热者用连附六一汤；重则两目赤黄，手足青至“食”（原稿如此），即是真心痛，不治。虫痛：湿热生虫攻心，痛发难忍，痛定能食，饥则“临沐”（原稿如此），用灵槟散、乌梅丸、化虫丸选用。〔组成·照录〕原稿未载（各分方见各书）。〔方义〕悸痛属七情伤心，轻者安神定悸，重者邪犯心主则危。〔服法〕原稿未载。"}, {"source": "条835｜《医学入门·外集》·胎惊", "原文": "《医学入门·外集》：“胎惊心中怔忡，睡卧不宁，热者朱砂安神丸；虚者定志丸。余可类推。", "白话": "〔论述〕胎惊：心中怔忡、睡卧不宁——属热者用朱砂安神丸；属虚者用定志丸。其余可类推。〔组成·照录〕朱砂安神丸、定志丸（见前条726、783）。〔方义〕热者清心镇惊，虚者益气定志。〔服法〕照各原方。"}, {"source": "条836｜《古今医鉴》卷三·定心汤（秘方）", "原文": "《古今医鉴》卷三：“定心汤秘方。治伤寒瘥后心下怔忡。生地汁、童便各半盏，二味和合，重汤煮数沸服。", "白话": "〔方名〕定心汤（秘方）。〔主治〕治伤寒病愈后心下怔忡。〔组成·照录〕生地汁、童便各半盏。〔方义〕生地黄汁滋阴凉血，童便（人中白液）降火滋阴，二味合用治瘥后阴虚余热之怔忡。〔制法·服法〕二味和合，隔水（重汤）煮数沸服。"}, {"source": "条837｜《古今医鉴》卷七·天王补心丹", "原文": "《古今医鉴》卷七：“天王补心丹。宁心益志，壮力强精，安神魂，定惊悸怔忡，祛烦热，化痰涎稠浊。  \n熟地二两，酒洗 白茯苓二两 丹参二两 柏子仁去壳，二两 百部二两 石菖蒲二两 牛膝酒洗，二两 杜仲酥炙，去丝，二两 当归酒洗，二两 枣仁炒，二两 玄参二两 天门冬去心，二两 五味子二两 人参二两 白茯神二两 远志甘草水泡，二两 桔梗一两 甘草一两 麦门冬一两  \n上为细末，炼蜜为丸如弹子大，金箔为衣。", "白话": "〔功用·主治〕宁心益志，壮力强精，安神魂，定惊悸怔忡，祛烦热，化痰涎稠浊。〔组成·照录〕熟地二两（酒洗），白茯苓二两，丹参二两，柏子仁（去壳）二两，百部二两，石菖蒲二两，牛膝（酒洗）二两，杜仲（酥炙，去丝）二两，当归（酒洗）二两，枣仁（炒）二两，玄参二两，天门冬（去心）二两，五味子二两，人参二两，白茯神二两，远志（甘草水泡）二两，桔梗一两，甘草一两，麦门冬一两。〔方义〕二冬、二地（熟地）、玄参、丹参、归、膝、杜仲滋阴养血补肾，参、苓、二仁、远志、菖蒲、茯神宁心安神，桔梗载药上"}, {"source": "条838｜《古今医鉴》卷七·清离滋坎汤（云林制）", "原文": "《古今医鉴》卷七：“清离滋坎汤云林制。治阴血虚相火旺，盗汗潮热，咳嗽吐痰，一切虚劳等症，并加治之。  \n生地黄二钱 熟地黄二钱 天门冬一钱 麦门冬一钱 当归酒洗，一钱 白芍酒炒，一钱 山茱萸酒蒸，去核，一钱五分 干山药一钱 白茯苓八分 白术土炒，一钱 牡丹皮一钱二分 泽泻八分 黄柏蜜炒，八分 知母蜜炒，八分 甘草炙，七分  \n上锉一剂，水煎服。嗽盛，加紫菀、款冬花。痰盛，加贝母、栝蒌仁。热盛，加地", "白话": "〔出处〕清离滋坎汤（云林〔龚廷贤〕制）。〔主治〕治阴血虚、相火旺，盗汗潮热，咳嗽吐痰，一切虚劳等症，并加治之。〔组成·照录〕生地黄二钱，熟地黄二钱，天门冬一钱，麦门冬一钱，当归（酒洗）一钱，白芍（酒炒）一钱，山茱萸（酒蒸，去核）一钱五分，干山药一钱，白茯苓八分，白术（土炒）一钱，牡丹皮一钱二分，泽泻八分，黄柏（蜜炒）八分，知母（蜜炒）八分，甘草（炙）七分。〔方义〕即六味地黄丸合二至、知柏之意，滋阴降火、清补肺肾（离为心火，坎为肾水，清离滋坎即清心滋肾）。〔制法·服法〕上药锉一"}, {"source": "条839｜《古今医鉴》卷八·温胆汤", "原文": "《古今医鉴》卷八：“温胆汤。治病后虚烦不得卧，及心胆虚怯，触事易惊，短气悸乏，或复自汗，并治。  \n半夏七钱 竹茹、枳实各三钱 陈皮四钱半 白茯苓去皮 甘草炙，二钱二分半  \n上锉作一剂，姜、枣煎服。", "白话": "〔主治〕治病后虚烦不得卧，以及心胆虚怯，触事易惊，短气心悸乏力，或又自汗，并治。〔组成·照录〕半夏七钱，竹茹、枳实各三钱，陈皮四钱半，白茯苓（去皮，原稿无量），甘草（炙）二钱二分半。〔方义〕半夏、竹茹、枳实、陈皮理气化痰清热，茯苓、甘草健脾和中，为心胆虚怯、虚烦不寐之主方。〔制法·服法〕上药锉作一剂，加姜、枣煎服。"}, {"source": "条840｜《古今医鉴》卷八·养心汤", "原文": "《古今医鉴》卷八：“养心汤。治用心过度，心热遗精，恍惚多梦，或惊而不寐者。  \n人参 山药 茯神 麦门冬 当归身 白芍 石莲肉 远志 酸枣仁 鸡头实 莲花须 子芩酒洗 \n上锉一剂，加生姜三片，枣一枚，水煎服。气虚，加黄芪、白术；血虚，加熟地黄；遗久气陷，加川芎、升麻，去子芩。", "白话": "〔主治〕治用心过度，心热遗精，恍惚多梦，或受惊而不寐者。〔组成·照录〕人参、山药、茯神、麦门冬、当归身、白芍、石莲肉、远志、酸枣仁、鸡头实、莲花须、子芩（酒洗）（原稿各药无剂量）。〔方义〕参、薯蓣益气，归、芍养血，二仁、茯神、远志、莲肉、莲须安神固精，麦冬、子芩清心除烦，为用心过度、惊悸遗精之剂。〔制法·服法〕上药锉一剂，加生姜三片、大枣一枚，水煎服。〔加减〕气虚加黄芪、白术；血虚加熟地黄；遗精日久气陷，加川芎、升麻，去子芩。"}, {"source": "条841｜《育婴家秘》卷一·温胆汤", "原文": "《育婴家秘》卷一：“温胆汤。治心胆虚怯，触事多惊，亦治水气怔悸。  \n半夏制、枳壳制、白茯苓各一两 橘红一两半 甘草炙，五钱  \n锉，和匀，每服三钱半，姜七片，枣三枚，刮竹青一块，如钱大，水煎服。或加制远志尤妙。不睡者，胆寒也，加酸枣仁炒。若喜睡者，胆热也，酸枣仁生用。", "白话": "〔主治〕治心胆虚怯，遇事多惊；亦治水气怔悸。〔组成·照录〕半夏（制）、枳壳（制）、白茯苓各一两，橘红一两半，甘草（炙）五钱。〔方义〕温胆汤去竹茹加橘红，理气化痰、温胆和胃，水气去则怔悸止。〔制法·服法〕上药锉，和匀，每服三钱半，加姜七片、大枣三枚、刮竹青一块如钱大，水煎服。或加制远志尤妙。不睡者属胆寒，加炒酸枣仁；若喜睡者属胆热，酸枣仁生用。"}, {"source": "条842｜《医方考》卷五·养心汤", "原文": "《医方考》卷五：“养心汤。\n黄芪、白茯苓、茯神、半夏曲、当归、川芎各半两 柏子仁、酸枣仁炒、人参、远志去心，姜汁炒、五味子、辣桂各二钱半 甘草炙，四钱  \n每服五钱。心血虚少，神气不宁，令人惊悸怔忡者，此方主之。", "白话": "〔方名〕养心汤。〔组成·照录〕黄芪、白茯苓、茯神、半夏曲、当归、川芎各半两，柏子仁、酸枣仁（炒）、人参、远志（去心，姜汁炒）、五味子、辣桂各二钱半，甘草（炙）四钱。〔主治·方义〕心血虚少、神气不宁，使人惊悸怔忡者，此方主之：参、芪、苓、草益气，归、芎、二仁、五味养血安神，半夏曲化痰，辣桂温心阳。〔制法·服法〕每服五钱（煎服）。"}, {"source": "条843｜《医方考》卷五·朱雀丸", "原文": "《医方考》卷五：“朱雀丸。\n白茯神二两 沉香五钱\n惊气怔忡者，此方主之。因惊而得者，名曰惊气怔忡。《内经》曰：惊则气乱。宜其怔怔忡忡，如物之扑也。是方也，茯神之甘平，可以宁心；沉香之坚实，可使下气，气下则怔忡瘥矣。", "白话": "〔方名〕朱雀丸。〔组成·照录〕白茯神二两，沉香五钱。〔主治·方义〕因惊而得之怔忡者，名曰惊气怔忡，此方主之。《内经》曰：“惊则气乱。”故其人怔怔忡忡，如物之扑（如被物扑击心胸）。此方茯神甘平，可以宁心；沉香坚实，可以下气，气下行则怔忡痊愈。〔制法·服法〕（炼蜜为丸，原稿未具）。"}, {"source": "条844｜《医方考》卷六·十一味木香散", "原文": "《医方考》卷六：“十一味木香散。\n木香 丁香 肉桂 人参 青皮 大腹皮 半夏 甘草 前胡 诃子 赤茯苓  \n里虚泄泻而渴者，此方主之……陈文仲云：腹胀渴者，泻渴者，足指冷渴者，惊悸渴者，身温渴者，身热面㿠白色渴者，寒战渴不止者，气急咬牙渴者，饮水转水泻不已者，以上九证，即非热也，乃津液少，脾胃肌肉虚故耳。宜木香散治之。如不愈，更加丁香、肉桂。昆谓痘色㿠白，手足寒，小便利，如是渴者虚也，本方主之；若", "白话": "〔方名〕十一味木香散。〔组成·照录〕木香、丁香、肉桂、人参、青皮、大腹皮、半夏、甘草、前胡、诃子、赤茯苓。〔主治·方义〕里虚泄泻而口渴者，此方主之……陈文仲说：腹胀而渴者、泄泻而渴者、足趾冷而渴者、惊悸而渴者、身温而渴者、身热面色㿠白而渴者、寒战而渴不止者、气急咬牙而渴者、饮水反而水泻不止者——以上九证，皆非热证，乃津液少、脾胃肌肉虚弱之故，宜用木香散治之；如不愈，更加丁香、肉桂。吴昆（按）谓：痘色㿠白、手足寒、小便利，见此等口渴者属虚，本方主之；若痘色红赤、大便秘、小便赤，"}, {"source": "条845｜《仁术便览》卷一·竹叶石膏汤", "原文": "《仁术便览》卷一：“竹叶石膏汤。治伤寒汗下后，表里俱虚，津液枯竭，余热不解，心烦不眠，或气逆欲吐，及诸虚烦热并宜服之。  \n石膏 淡竹叶 麦门冬 粳米百余粒 半夏 人参 甘草 \n阴虚甚者加知母、黄柏、川芎、地黄。惊悸不宁、盗汗，加酸枣仁、茯神。小便不利，加栀子。气短无力，加人参、黄芪。上水一钟半煎。", "白话": "〔主治〕治伤寒汗下之后，表里俱虚，津液枯竭，余热不解，心烦不眠，或气逆欲吐，以及诸虚烦热之证并宜服之。〔组成·照录〕石膏、淡竹叶、麦门冬、粳米百余粒、半夏、人参、甘草。〔方义〕竹叶、石膏清余热，麦冬、粳米、参、草益气生津，半夏和胃降逆，为伤寒后虚烦惊悸之剂。〔制法·服法〕上药用水一钟半煎。〔加减〕阴虚甚者加知母、黄柏、川芎、地黄；惊悸不宁、盗汗者加酸枣仁、茯神；小便不利者加栀子；气短无力者加人参、黄芪。"}, {"source": "条846｜《仁术便览》卷一·加味温胆汤", "原文": "《仁术便览》卷一：“加味温胆汤。治心胆虚怯，触事易惊，梦昧不祥，气郁生涎。涎与气抟亦生诸症，或短气悸乏，或复自汗，四肢浮肿，饮食无味。  \n枳实、半夏、竹茹各八两 陈皮十二两 白茯苓六两 甘草炙，四两 加香附一斤半 人参、柴胡、麦冬、桔梗各六两  \n每服一两，生姜五片，枣二枚，水煎服。", "白话": "〔主治〕治心胆虚怯，触事易惊，梦寐不祥，气郁生涎；涎与气相搏亦生诸证：或短气心悸乏力，或又自汗，四肢浮肿，饮食无味。〔组成·照录〕枳实、半夏、竹茹各八两，陈皮十二两，白茯苓六两，甘草（炙）四两，加香附一斤半，人参、柴胡、麦冬、桔梗各六两。〔方义〕温胆汤加香附、柴胡疏肝，参、麦益气养阴，桔梗宣肺，为心胆虚怯、气郁生痰之重剂。〔制法·服法〕每服一两，加生姜五片、大枣二枚，水煎服。"}, {"source": "条847｜《仁术便览》卷三·养心汤", "原文": "《仁术便览》卷三：“养心汤。治忧愁思虑，伤心，惊悸不宁。治停水，怔忡，加槟榔、赤茯苓。  \n黄芪、白茯、茯神、半夏曲、当归、川芎各五钱 甘草四钱、辣桂、远志去心，姜汁炒、柏子仁、五味子、酸枣仁、人参各二钱半\n上每服三钱，姜三片，枣一枚煎。", "白话": "〔主治〕治忧愁思虑伤心，惊悸不宁。〔加减〕治停水怔忡者，加槟榔、赤茯苓。〔组成·照录〕黄芪、白茯、茯神、半夏曲、当归、川芎各五钱，甘草四钱，辣桂、远志（去心，姜汁炒）、柏子仁、五味子、酸枣仁、人参各二钱半。〔方义〕参、芪、苓、草益气，归、芎、二仁、五味养血安神，半夏曲化痰，辣桂温心阳，为忧思伤心惊悸之剂。〔制法·服法〕上每服三钱，加姜三片、大枣一枚煎。"}, {"source": "条848｜《仁术便览》卷三·朱砂安神丸", "原文": "《仁术便览》卷三：“朱砂安神丸。治心烦懊憹，心乱怔忡，胸中气乱，心中痞闷，食入反吐出。  \n朱砂四钱，研 黄连末五钱 生甘草二钱半  \n上为末，蒸饼丸如黄米大。每十丸，唾津咽下。", "白话": "〔主治〕治心烦懊憹，心乱怔忡，胸中气乱，心中痞闷，食入反吐出。〔组成·照录〕朱砂四钱（研）、黄连末五钱、生甘草二钱半。〔方义〕朱砂镇心，黄连清热，甘草和中，为心烦怔忡之小丸（较朱砂安神丸少归、地）。〔制法·服法〕上为末，蒸饼为丸如黄米大，每服十丸，唾津（唾液）咽下。"}, {"source": "条849｜《仁术便览》卷三·茯苓饮子", "原文": "《仁术便览》卷三：“茯苓饮子。治痰饮蓄于心经，怔忡不已。  \n赤茯苓、半夏、麦门冬、陈皮各一两 沉香不见火、甘草、槟榔各五钱\n上每服八钱，姜三片，水煎服。", "白话": "〔主治〕治痰饮蓄于心经，怔忡不已。〔组成·照录〕赤茯苓、半夏、麦门冬、陈皮各一两，沉香（不见火）、甘草、槟榔各五钱。〔方义〕即条817济生茯苓饮子，二茯、半夏、陈皮化痰蠲饮，沉香、槟榔降气，麦冬养阴，饮去气降则怔忡止。〔制法·服法〕上每服八钱，加姜三片，水煎服。"}, {"source": "条850｜《万病回春》卷四·加味八珍丸", "原文": "《万病回春》卷四：“加味八珍丸。大补血气、壮脾胃、益虚损。  \n当归酒洗，二两 南芎一两二钱 白芍酒炒，一两半 熟地黄酒蒸晒干，二两 人参去芦，二两 白术去芦，炒，二两 白茯苓去皮，二两 粉草蜜炙，七钱 陈皮二两  \n惊悸怔忡，加远志甘草水泡，去骨，二两，酸枣仁炒，一两。", "白话": "〔功用〕大补血气、壮脾胃、益虚损。〔组成·照录〕当归（酒洗）二两，南芎一两二钱，白芍（酒炒）一两半，熟地黄（酒蒸晒干）二两，人参（去芦）二两，白术（去芦，炒）二两，白茯苓（去皮）二两，粉草（蜜炙）七钱，陈皮二两。〔方义〕即八珍汤加陈皮，气血双补、健脾和胃。〔加减〕惊悸怔忡者，加远志（甘草水泡，去骨）二两、酸枣仁（炒）一两。〔制法·服法〕（炼蜜为丸，原稿未具服法）。"}, {"source": "条851｜《万病回春》卷四·滋阴降火汤", "原文": "《万病回春》卷四：“滋阴降火汤。治阴虚火动，发热咳嗽，吐痰喘急，盗汗口干。此方与六味地黄丸相兼服之，大补虚劳，神效。  \n当归酒洗，一钱二分 白芍酒洗，二钱三分 生地黄八分 熟地黄姜汁炒、天门冬去心、麦门冬去心、白术去芦，各一钱 陈皮七分 黄柏去皮，蜜水炒、知母各五分 甘草炙，五分  \n上锉一剂。生姜三片，大枣一枚，水煎。临服入竹沥、童便、姜汁少许，同服。同治；痰火作热，烦躁不安，气随火升也，并痰", "白话": "〔主治〕治阴虚火动，发热咳嗽，吐痰喘急，盗汗口干。此方与六味地黄丸相兼服之，大补虚劳，神效。〔组成·照录〕当归（酒洗）一钱二分，白芍（酒洗）二钱三分，生地黄八分，熟地黄（姜汁炒）、天门冬（去心）、麦门冬（去心）、白术（去芦）各一钱，陈皮七分，黄柏（去皮，蜜水炒）、知母各五分，甘草（炙）五分。〔方义〕四物合二冬养血滋阴，知柏清降相火，白术、陈皮健脾理气，为阴虚火动之剂。〔制法·服法〕上药锉一剂，加生姜三片、大枣一枚，水煎；临服加入竹沥、童便、姜汁少许同服。〔加减〕同治：痰火作热"}, {"source": "条852｜《万病回春》卷四·四物安神汤", "原文": "《万病回春》卷四：“怔忡者，心无血养，如鱼无水，心中惕惕然而跳动也，如人将捕捉之貌。若思虑即心跳者，是血虚也。四物安神汤 治心中无血养，故作怔忡。兼服辰砂安神丸。  \n当归酒洗 白芍酒炒 生地黄酒洗 熟地黄 人参去芦 白术去芦 茯神去皮木 酸枣仁炒 黄连姜炒 栀子炒 麦门冬去心 竹茹 辰砂研末，临服调入 乌梅一个  \n上锉一剂。枣二枚，炒米一撮，水煎，食远服。心若时跳时止者，是痰因火动也。二陈汤治", "白话": "〔论述〕怔忡者，心无血养，如鱼无水，心中惕惕然而跳动，如有人将要捕捉自己之状。若一思虑即心跳者，是血虚也。四物安神汤治心中无血养、故作怔忡之证；兼服辰砂安神丸。〔组成·照录〕当归（酒洗）、白芍（酒炒）、生地黄（酒洗）、熟地黄、人参（去芦）、白术（去芦）、茯神（去皮木）、酸枣仁（炒）、黄连（姜炒）、栀子（炒）、麦门冬（去心）、竹茹、辰砂（研末，临服调入）、乌梅一个。〔方义〕四物养血，参、术益气，二仁、茯神安神，连、栀、竹茹清热，辰砂镇心，乌梅敛阴，为血虚怔忡之剂。〔制法·服法〕"}, {"source": "条853｜《云林神彀》卷二·六味地黄丸加味", "原文": "《云林神彀》卷二：“六味地黄丸治健忘怔忡，惊悸不寐，加远志肉、石菖蒲、人参、白茯神、当归、酸枣仁炒，各二钱。宁心保神，益血固精，壮力强志，定魄镇惊，怔忡健忘，痰火能清。", "白话": "〔主治〕六味地黄丸治健忘怔忡、惊悸不寐，加远志肉、石菖蒲、人参、白茯神、当归、酸枣仁（炒）各二钱。功能宁心保神、益血固精、壮力强志、定魄镇惊，怔忡健忘、痰火能清。〔组成·照录〕六味地黄丸（熟地黄、山茱萸、山药、泽泻、牡丹皮、茯苓）加远志肉、石菖蒲、人参、白茯神、当归、酸枣仁（炒）各二钱。〔方义〕六味滋补肝肾，加远志、菖蒲、茯神、枣仁、参、归养心安神，为心肾两虚、怔忡健忘之剂。〔服法〕（炼蜜为丸，原稿未具服法）。"}, {"source": "条854｜《怪证奇方》卷下·茯神汤（怔忡多忘）", "原文": "《怪证奇方》卷下：“怔忡多忘，魇梦不已，茯神汤下。", "白话": "〔主治〕怔忡多忘、噩梦不止者，用茯神汤送下（所服之丸药）。〔组成·照录〕茯神汤（见前条713、715等）。〔方义〕茯神汤养心安神，用作药引送下丸药。〔服法〕以茯神汤送下。"}, {"source": "条855｜《幼幼集成》卷四·神不安而啼", "原文": "《幼幼集成》卷四：“神不安而啼者，睡中惊悸，抱母大哭，面色紫黑，盖神虚惊悸。宜安神丸定其心志。", "白话": "〔论述〕神不安而啼哭者，睡中惊悸，抱住母亲大哭，面色紫黑——盖因神虚惊悸，宜用安神丸安定其心志。〔组成·照录〕安神丸（见前条786等）。〔方义〕小儿神虚惊悸夜啼，以安神丸镇心安神。〔服法〕照原方。"}, {"source": "条856｜《医学原理》卷五·滋阴大补丸", "原文": "《医学原理》卷五：“滋阴大补丸。\n枸杞子甘温，补劳伤、益精强阴、济虚弱，三两  苁蓉甘酸温，益精补肾，酒浸洗，瓦焙干，二两  熟地黄甘寒，滋肾水、益真阴、补血，四两  巴戟辛甘温，益精气，去心，七分  茴香辛甘温，通肾气，七钱  远志苦温，安心神，定恍惚，补虚劳，去心，甘草水煮，七钱  山药甘温，补中、益精气，二两  牛膝苦酸平，行血、益精、壮筋，二两  杜仲辛甘温，益肾填精，炒，去丝，二两  白", "白话": "〔方名〕滋阴大补丸。〔组成·照录〕枸杞子（甘温，补劳伤、益精强阴、济虚弱）三两；苁蓉（甘酸温，益精补肾，酒浸洗，瓦焙干）二两；熟地黄（甘寒，滋肾水、益真阴、补血）四两；巴戟（辛甘温，益精气，去心）七分；茴香（辛甘温，通肾气）七钱；远志（苦温，安心神、定恍惚、补虚劳，去心，甘草水煮）七钱；山药（甘温，补中、益精气）二两；牛膝（苦酸平，行血、益精、壮筋）二两；杜仲（辛甘温，益肾填精，炒，去丝）二两；白茯苓（甘淡平，止惊悸，去皮）二两；五味子（甘酸平）五钱；石菖蒲（苦辛平，开心气、"}, {"source": "条857｜《医学原理》卷五·八味定志丸", "原文": "《医学原理》卷五：“八味定志丸。治中气虚败，以致心气不足，邪热上攻，恍惚惊悸，喘嗽不宁。治宜补中益心气，清热安心为主。故用参、苓、白术等补中气为本，麦冬清肺止嗽，牛黄、朱砂退热镇心，佐菖蒲、远志、茯神等安神定魄，以止惊悸恍惚。", "白话": "〔主治·方义〕治中气虚败，以致心气不足，邪热上攻，恍惚惊悸，喘嗽不宁。治宜补中益心气、清热安心为主：故用人参、茯苓、白术等补中气为本，麦冬清肺止嗽，牛黄、朱砂退热镇心，佐以菖蒲、远志、茯神等安神定魄，以止惊悸恍惚。〔组成·照录〕参、苓、白术、麦冬、牛黄、朱砂、菖蒲、远志、茯神（原稿未标剂量，八味定志丸通行方为：人参、茯苓、茯神、远志、菖蒲、朱砂、麦冬、白术）。〔服法〕原稿未具。"}, {"source": "条858｜《医学原理》卷五·痨瘵分经论治（心经受伤）", "原文": "《医学原理》卷五：“痨瘵之症五，藏脏必归于一经，治宜分经而疗。如足酸，腰疼，背拘急，遗白浊，面带黧色，耳轮焦枯，脉沉细数，此乃肾经受伤。宜四物加黄柏、知母、五味、麦冬、泽泻、杜仲、肉桂之类，煎熟入童便、韭汁、竹沥。如心神惊悸怔忡，无时盗汗，心烦热闷，口舌生疮，咯血面赤，脉洪而数，乃心经受伤，以前方去杜仲、泽泻、肉桂，加茯神、莲心、黄连、远志、菖蒲、朱砂之类。", "白话": "〔论述〕痨瘵之证有五，脏腑必归于一经，治宜分经而疗。如足酸、腰疼、背拘急、遗精白浊、面色黧、耳轮焦枯、脉沉细数——此乃肾经受伤，宜用四物汤加黄柏、知母、五味、麦冬、泽泻、杜仲、肉桂之类，煎熟后加入童便、韭汁、竹沥。如心神惊悸怔忡、无时盗汗、心烦热闷、口舌生疮、咯血面赤、脉洪而数——乃心经受伤，用前方去杜仲、泽泻、肉桂，加茯神、莲心、黄连、远志、菖蒲、朱砂之类。〔组成·照录〕四物汤加减（见文内）。〔方义〕肾伤者滋阴降火，心伤者清心安神，为痨瘵分经论治之纲。〔服法〕煎服，入童便、"}, {"source": "条859｜《医学原理》卷五·保真汤", "原文": "《医学原理》卷五：“保真汤。治气血虚败已极，以致相火炽盛，煎熬真阴而成痨瘵、骨蒸发热、盗汗、遗精、咳嗽等症。治宜补益气血，滋阴制火为本，清热止嗽，固精为标。故用人参、白术、茯苓、甘草、黄芪、大枣等以补气，归、芍、赤茯以益血，黄柏、知母、熟地补益真阴，柴胡、地骨皮以解蒸热，天麦冬、北五味清肺金以止嗽，莲蕊固精，陈皮、生姜散逆气，以导地黄之滞。  \n人参甘温，四钱 白术苦甘温，二钱 白茯甘淡平，一钱 ", "白话": "〔主治·方义〕治气血虚败已极，以致相火炽盛，煎熬真阴而成痨瘵、骨蒸发热、盗汗、遗精、咳嗽等症。治宜补益气血、滋阴制火为本，清热止嗽、固精为标：故用人参、白术、茯苓、甘草、黄芪、大枣等补气，当归、芍药、赤茯苓益血，黄柏、知母、熟地补益真阴，柴胡、地骨皮解蒸热，天冬、麦冬、北五味清肺金以止咳，莲蕊固精，陈皮、生姜散逆气，以导地黄之滞。〔组成·照录〕人参（甘温）四钱，白术（苦甘温）二钱，白茯（甘淡平）一钱，炙草（甘温）五分，黄芪（甘温）五钱，大枣（甘温）三枚，当归（辛甘温）二钱，生"}, {"source": "条860｜《医学原理》卷八·妙香散", "原文": "《医学原理》卷八：“妙香散。治遗精恍惚惊悸，乃心气亏败所致。法当补益心气为主。故用茯苓、茯神、远志、辰砂补心安神定惚，人参、黄芪、山药益正气，木香行郁，麝香通窍，甘草泄火，桔梗载诸药不令下沉。", "白话": "〔主治·方义〕治遗精、恍惚、惊悸，乃心气亏败所致，法当以补益心气为主：故用茯苓、茯神、远志、辰砂补心安神定惚，人参、黄芪、山药益正气，木香行郁，麝香通窍，甘草泻火，桔梗载诸药不使下沉。〔组成·照录〕茯苓、茯神、远志、辰砂、人参、黄芪、山药、木香、麝香、甘草、桔梗（原稿未标剂量；《太平惠民和剂局方》妙香散为：麝香、木香、山药、茯神、茯苓、黄芪、远志、人参、桔梗、甘草、朱砂）。〔服法〕（原方为末，温酒调服，原稿未具）。"}, {"source": "条861｜《医学原理》卷九·养心汤", "原文": "《医学原理》卷九：“养心汤。治肥人气虚挟夹痰惊悸。治宜补气豁痰为主，安神定气为标。是以用人参、黄芪、甘草以补气，茯神、远志、柏子仁、酸枣仁等，安心神以定惊悸，佐桂心、川芎以导血脉，五味、半夏清金以豁痰。  \n人参甘温，二钱 黄芪甘温，钱半 甘草甘温，五分 茯神甘平，八分 远志苦温，七分 柏子仁辛平，八分 酸枣仁酸平，一钱 桂心辛温，五分 川芎辛温，八分 五味子甘酸平，七分 半夏苦辛温，七分 \n用水", "白话": "〔主治·方义〕治肥胖人气虚夹痰之惊悸。治宜补气豁痰为主、安神定气为标：故用人参、黄芪、甘草补气，茯神、远志、柏子仁、酸枣仁等安心神以定惊悸，佐桂心、川芎以导血脉，五味、半夏清金以豁痰。〔组成·照录〕人参（甘温）二钱，黄芪（甘温）钱半，甘草（甘温）五分，茯神（甘平）八分，远志（苦温）七分，柏子仁（辛平）八分，酸枣仁（酸平）一钱，桂心（辛温）五分，川芎（辛温）八分，五味子（甘酸平）七分，半夏（苦辛温）七分。〔方义〕见上（原稿逐药注性味）。〔制法·服法〕用水二大钟，煎一大钟，温服。"}, {"source": "条862｜《医学原理》卷九·惊悸致者治法", "原文": "《医学原理》卷九：“如因惊悸而致者，当安神为主，宜朱砂安神丸为主加减。", "白话": "〔论述〕如因惊悸而致（诸证）者，当以安神为主，宜以朱砂安神丸为主方加减。〔组成·照录〕朱砂安神丸（见条726）。〔方义〕镇心安神为主，随证加减。〔服法〕照原方。"}, {"source": "条863｜《医学原理》卷九·心跳（血少论）", "原文": "《医学原理》卷九：“凡心跳，亦属血少，宜四物汤送朱砂安神丸及养心汤之类。或问：人当惊恐后，何故作此症？盖惊则神出其舍，神舍空虚，痰气上乘所致，亦宜用养心汤为主加减。", "白话": "〔论述·问答〕凡心跳者，亦属血少，宜用四物汤送服朱砂安神丸及养心汤之类。或问：人当惊恐之后，何故发作此症？答：盖惊则神出于其舍（心神外越），神舍空虚，痰气上乘所致，亦宜用养心汤为主加减。〔组成·照录〕四物汤送朱砂安神丸、养心汤（各见前条）。〔方义〕血少者养血为主，惊后痰乘者兼化痰安神。〔服法〕四物汤送丸。"}, {"source": "条864｜《医学原理》卷十三·猪心龙脑丸", "原文": "《医学原理》卷十三：“猪心龙脑丸。治痘疹躁乱，谵语惊悸。此乃心经蕴热所致。法当疏散心经郁热。是以用猪心血为心经引使，梅花脑子以散心经郁热。  \n猪心血酸咸平 脑子辛凉，一钱\n为末，用猪心血为丸绿豆大，每以井花水，或薄荷汤化下一丸。", "白话": "〔主治·方义〕治痘疹躁乱、谵语惊悸——此乃心经蕴热所致，法当疏散心经郁热：故用猪心血为心经引使，梅花脑子以散心经郁热。〔组成·照录〕猪心血（酸咸平）、脑子（辛凉）一钱。〔方义〕猪心血引药入心，龙脑（梅花脑子）辛凉透散心经郁热。〔制法·服法〕为末，用猪心血为丸如绿豆大，每以井花水或薄荷汤化下一丸。"}, {"source": "条865｜《医学原理》卷十三·泻心汤（心主热）", "原文": "《医学原理》卷十三：“心主热，目病或大热，泻心汤主之。实则烦热，黄连泻心汤主之，虚则热惊悸，生犀散主之。", "白话": "〔论述〕心主热：目病或大热者，泻心汤主之。实证见烦热者，黄连泻心汤主之；虚证见热而惊悸者，生犀散主之。〔组成·照录〕泻心汤、黄连泻心汤、生犀散（各见前条753及各书）。〔方义〕心经实热者泻之，虚热惊悸者清补兼施。〔服法〕照各原方。"}, {"source": "条866｜《万氏家抄济世良方》卷二·加减四物汤", "原文": "《万氏家抄济世良方》卷二：“加减四物汤。治瘦人血少，怔忡无时但觉心跳者。  \n当归 芍药 生地黄 茯神 酸枣仁 远志  \n钟半，煎七分，通口服。", "白话": "〔主治〕治瘦人血少，怔忡无定时、但觉心跳者。〔组成·照录〕当归、芍药、生地黄、茯神、酸枣仁、远志。〔方义〕四物汤去川芎加茯神、枣仁、远志，养血安神，为瘦人血虚怔忡之剂。〔制法·服法〕用水一钟半，煎取七分，一次口服。"}, {"source": "条867｜《万氏家抄济世良方》卷五·人参羌活散", "原文": "《万氏家抄济世良方》卷五：“人参羌活散。截风定搐、豁痰安神。  \n柴胡 天麻 前胡 人参 枳壳 茯神 羌活 桔梗 陈皮 防风 僵蚕 甘草  \n水煎，入姜汁、竹沥服。痰盛加南星；泻加泽泻、诃子；大便结加皂角；昏迷加黄连；壮热加黄芩；嗽加杏仁；天瘹加钩藤；心跳加当归；胸闷加枳壳；目连眶动及肝风加青皮、黄连。", "白话": "〔功用〕截风定搐、豁痰安神。〔组成·照录〕柴胡、天麻、前胡、人参、枳壳、茯神、羌活、桔梗、陈皮、防风、僵蚕、甘草。〔方义〕羌活、防风、柴胡、前胡疏风，天麻、僵蚕息风定搐，二陈（陈皮、甘草）合枳壳、桔梗豁痰理气，参、茯神益气安神。〔制法·服法〕水煎，加入姜汁、竹沥服。〔加减〕痰盛加南星；泄泻加泽泻、诃子；大便结加皂角；昏迷加黄连；壮热加黄芩；咳嗽加杏仁；天瘹（抽搐）加钩藤；心跳加当归；胸闷加枳壳；目连眶跳动及肝风加青皮、黄连。"}, {"source": "条868｜《万氏家抄济世良方》卷五·辰砂抱龙丸", "原文": "《万氏家抄济世良方》卷五：“辰砂抱龙丸。治小儿伤风咳嗽、痰喘烦渴、鼻流清涕、惊悸风热等症。  \n天竺黄、天花粉、茯神去皮木、明天麻各一两 胆星二两 雄黄、防风各五钱 麝香一钱半 辰砂五钱，水飞 \n为细末，甘草浓煎汁，丸芡实大，辰砂为衣。灯心薄荷汤下。伤风痰盛，紫苏姜汤下。", "白话": "〔主治〕治小儿伤风咳嗽、痰喘烦渴、鼻流清涕、惊悸风热等症。〔组成·照录〕天竺黄、天花粉、茯神（去皮木）、明天麻各一两，胆星二两，雄黄、防风各五钱，麝香一钱半，辰砂五钱（水飞）。〔方义〕胆星、竺黄化痰，天麻息风，防风散风，花粉生津，辰砂、茯神镇心安神，雄黄、麝香解毒开窍，为小儿风热痰惊之丸。〔制法·服法〕上为细末，用甘草浓煎汁为丸如芡实大，辰砂为衣；灯心、薄荷汤送下；伤风痰盛者，紫苏、姜汤送下。"}, {"source": "条869｜《证治准绳·类方》·柏皮汤（元戎）", "原文": "《证治准绳·类方》：“柏皮汤元戎。治衄血、吐血、呕血，皆失血虚损，形气不理，羸瘦不能食，心忪少气，燥渴发热。  \n生地黄、甘草、黄柏、白芍药各一两  \n上㕮咀，用醇酒三升，渍之一宿，以铜器盛，米饮下蒸一炊时久，渍汁半升服，食后。时对病增损。《肘后》用熟地黄，水、酒煎饮清。", "白话": "〔出处〕柏皮汤（《医垒元戎》方）。〔主治〕治衄血、吐血、呕血——皆失血虚损，形气不理（形体气血不调），羸瘦不能食，心悸少气，燥渴发热。〔组成·照录〕生地黄、甘草、黄柏、白芍药各一两。〔方义〕生地、白芍滋阴养血止血，黄柏清热，甘草和中，为失血后虚热心悸之剂。〔制法·服法〕上药切碎，用醇酒三升浸一夜，以铜器盛，放米饮上蒸一顿饭之久，取浸汁半升服，食后服。随时随病增损。《肘后方》用熟地黄，水、酒煎饮其清汁。"}, {"source": "条870｜《证治准绳·类方》·三黄汤（集验，附风拘挛方）", "原文": "《证治准绳·类方》：“附：风拘挛方三黄汤集验。  \n治中风手足拘挛，百节疼痛，烦热心乱恶寒，不进饮食。兼治贼风，腲腿风，半身不随，失音不语。  \n麻黄一两，去节 黄芪去芦，半两 黄芩七钱半 独活一两，去芦  \n上为㕮咀，每服四钱，水一盏半，煎至七分，去渣温服，不拘时候。取汗为效。心热加大黄半两，胀满加枳实二钱半，气逆加人参七钱半，心悸加牡蛎七钱半，渴加栝蒌根七钱半，寒加附子一枚，炮熟入药。", "白话": "〔出处〕附：风拘挛方三黄汤（《集验》方）。〔主治〕治中风手足拘挛，百节疼痛，烦热心乱，恶寒，不进饮食；兼治贼风、腲腿风、半身不遂、失音不语。〔组成·照录〕麻黄一两（去节），黄芪（去芦）半两，黄芩七钱半，独活一两（去芦）。〔方义〕麻黄、独活祛风散寒，黄芪益气固表，黄芩清热，即仲景三黄汤法（与条729、条490相参）。〔制法·服法〕上药切碎，每服四钱，用水一盏半，煎至七分，去渣温服，不拘时候，以取汗为效。〔加减〕心热加大黄半两；胀满加枳实二钱半；气逆加人参七钱半；心悸加牡蛎七钱半"}, {"source": "条871｜《证治准绳·类方》·滋阴抑火汤", "原文": "《证治准绳·类方》：“滋阴抑火汤。\n当归、芍药煨、生地黄、川芎、黄连、知母、熟地黄各一钱 肉桂、甘草各五分  \n若身如飞扬，心跳不定，加紫石英、人参各一钱。上水二盅，煎七分，入童便半盏，食前服。", "白话": "〔方名〕滋阴抑火汤。〔主治〕原稿未另列主治，据方名及加减，治阴虚火旺、身如飞扬、心跳不定之证。〔组成·照录〕当归、芍药（煨）、生地黄、川芎、黄连、知母、熟地黄各一钱，肉桂、甘草各五分。〔方义〕四物配二地养血滋阴，知母、黄连抑火，少佐肉桂引火归原，为滋阴抑火之剂。〔服法〕水二盅煎取七分，加入童便半盏，食前服。〔加减〕若身如飞扬、心跳不定，加紫石英、人参各一钱。"}, {"source": "条872｜《证治准绳·杂病》·导痰汤加石菖蒲", "原文": "《证治准绳·杂病》：“大抵惊悸健忘，怔忡失志，心风不寐，皆是胆涎沃心，以致心气不足。若用凉心之剂太过，则心火愈微，痰涎愈盛，病愈不减，惟唯当以理痰气为第一义，导痰汤加石菖蒲半钱。", "白话": "〔主治〕大抵惊悸、健忘、怔忡、失志、心风、不寐诸证，都是胆中痰涎浸渍于心，以致心气不足。〔治法〕如果用寒凉清心之药太过，反使心火愈加微弱、痰涎愈加旺盛，病更加不减，只当以理气化痰为第一要义，用导痰汤加石菖蒲半钱。"}, {"source": "条873｜《证治准绳·杂病》·温胆汤（附五饮汤丸等）", "原文": "《证治准绳·杂病》：“《三因》云：五饮停蓄，闭于中脘，最使人惊骇，属饮家。（五饮汤丸）心胆虚怯，触事易惊，或梦寐不祥，遂致心惊胆慑，气郁生涎，涎与气搏，变生诸证，或短气悸乏，或复自汗者，并温胆汤主之。呕则以人参代竹茹。若惊悸眠多异梦随即惊觉者，宜温胆汤加酸枣仁、莲肉各一钱，以金银煎下十四友丸，或镇心丹、远志丸、酒调妙香散、琥珀养心丹、定志丸、宁志丸。卧而多惊魇，真珠母丸、独活汤。", "白话": "〔引文〕《三因方》说：五种痰饮停蓄，闭阻于中脘，最易使人惊骇，属于饮家之病（用五饮汤丸）。〔主治〕心胆虚怯，遇事易惊，或梦寐不祥，以致心惊胆怯，气郁生涎，涎与气相搏结，变生诸证：或短气心悸疲乏，或兼自汗——一律用温胆汤主治。〔加减〕呕者以人参代竹茹；若惊悸、睡眠中多怪梦随即惊醒者，宜温胆汤加酸枣仁、莲肉各一钱，用金银器煎汤送下十四友丸，或用镇心丹、远志丸、酒调妙香散、琥珀养心丹、定志丸、宁志丸；睡卧而多惊梦魇者，用真珠母丸、独活汤。"}, {"source": "条874｜《幼科证治准绳》集二·安神丸", "原文": "《幼科证治准绳》集二：“安神丸。治小儿惊悸，热渴心闷，脉实面红，颊赤口燥。  \n麦门冬、马牙硝、白茯苓、山药、寒水石各半两 朱砂一两 甘草半两 龙脑一字  \n上为末，炼蜜丸，如鸡头大。每服半丸，沙糖水下。", "白话": "〔方名〕安神丸。〔主治〕治小儿惊悸、发热口渴、心胸烦闷，脉实、面红、两颊发赤、口中干燥。〔组成·照录〕麦门冬、马牙硝、白茯苓、山药、寒水石各半两，朱砂一两，甘草半两，龙脑一字。〔方义〕麦冬、寒水石、马牙硝清热生津，茯苓、山药、甘草护中，朱砂镇心安神，合治心经实热之惊悸。〔制法·服法〕上药为末，炼蜜为丸，鸡头实大；每次服半丸，沙糖水送下。"}, {"source": "条875｜《幼科证治准绳》集二·羌活膏", "原文": "《幼科证治准绳》集二：“治慢惊者谓土虚泄泻，火木乘之，谓手掌与腹俱热之证，若火木土俱虚而摇动恐悸、注泻、手腹冷者，非羌活膏不能治之。", "白话": "〔主治〕治慢惊风：所谓土虚泄泻、火与木来乘克，即手掌与腹部俱热之证；若火、木、土俱虚，而见肢体摇动、恐惧心悸、洞泻不止、手腹俱冷者，非羌活膏不能治。"}, {"source": "条876｜《幼科证治准绳》集二·防风丸", "原文": "《幼科证治准绳》集二：“防风丸。治惊风痰热，神昏惊悸。  \n天麻、防风、人参、川芎各一两 全蝎、甘草、僵蚕、朱砂、雄黄、牛胆南星各二钱五分\n上为末，蜜丸鸡头大。每一丸，薄荷汤下。", "白话": "〔方名〕防风丸。〔主治〕治惊风痰热，神志昏迷、惊悸。〔组成·照录〕天麻、防风、人参、川芎各一两；全蝎、甘草、僵蚕、朱砂、雄黄、牛胆南星各二钱五分。〔方义〕天麻、防风、僵蚕、全蝎祛风定惊，胆星、雄黄化痰，参、芎扶正和血，朱砂镇心安神。〔制法·服法〕上为末，炼蜜为丸，鸡头实大；每次服一丸，薄荷汤送下。"}, {"source": "条877｜《幼科证治准绳》集二·前朴散", "原文": "《幼科证治准绳》集二：“前朴散。治心腹结气，或呕哕吐泻，腹胀痛，惊悸。  \n前胡、白术、人参、陈皮、良姜、藿香、甘草、厚朴各等分  \n上锉。每服三钱，水一盏，煎七分，稍热，空心服。", "白话": "〔方名〕前朴散。〔主治〕治心腹气结，或呕吐呃逆、上吐下泻，腹胀而痛，惊悸。〔组成·照录〕前胡、白术、人参、陈皮、良姜、藿香、甘草、厚朴各等分。〔方义〕前胡、厚朴、陈皮下气除胀，藿香、良姜温中止呕，参、术、草健脾益气，气顺脾健则惊悸自平。〔服法〕上药切碎，每次服三钱，水一盏煎取七分，稍热时空腹服。"}, {"source": "条878｜《幼科证治准绳》集三·导赤散", "原文": "《幼科证治准绳》集三：“钱心，主惊。实则叫哭发热，饮水而搐，虚则困卧，悸动不安。心病，多叫哭惊悸，手足动摇，发热饮水。视其睡，口中气温，或合面睡，及上窜咬牙，皆心热也，导赤散主之。", "白话": "〔引文〕钱乙论心：心主惊。心实则叫哭、发热、饮水而抽搐；心虚则困倦喜卧、悸动不安。心病多见叫哭惊悸、手足动摇、发热、渴欲饮水。〔诊法〕看其睡卧：口中呼气温热，或覆面而睡，以及目睛上窜、咬牙，都是心热之征。〔方名〕用导赤散主治。"}, {"source": "条879｜《幼科证治准绳》集四·升麻葛根", "原文": "《幼科证治准绳》集四：“升麻葛根二药，皆治伏热毒动，心恍惚，惊悸烦躁，大抵疮疹是蕴热毒，葛根解热，升麻去毒也。", "白话": "〔药对〕升麻、葛根两味药，都治伏热毒气发动，心神恍惚、惊悸烦躁。大抵疮疹是蕴蓄热毒所致：葛根解肌散热，升麻透发解毒。"}, {"source": "条880｜《幼科证治准绳》集四·升麻葛根白芍汤（癍疹方）", "原文": "《幼科证治准绳》集四：“癍疹者，因内伤必出，癍乃荣气逆故也，大禁牵牛、巴豆、峻药，宜半夏、枳实、大黄、益智仁、之类去泻止吐，若耳尖冷、呵欠、睡惊、嚏喷、眼涩，知必出癍也，宜：\n升麻、葛根、白芍药、甘草、归身、连翘各等分  \n上㕮咀，水煎服。此定法也，后、随证加减：如肺出脓癍，先显喘嗽，或气高而喘促，少加人参黄芩以泻伏火，而补元气。如心出小红癍，必先见嗌干惊悸，身热肌肉肿，脉弦洪，少加黄连。如命门出", "白话": "〔主治〕癍疹因内伤而必出，癍是营气逆乱之故；大禁牵牛、巴豆等峻烈药，宜用半夏、枳实、大黄、益智仁之类以去泻止吐。若见耳尖发冷、呵欠、睡中惊跳、喷嚏、眼涩，即知必出癍。〔组成·照录〕升麻、葛根、白芍药、甘草、当归身、连翘各等分。〔方义〕升麻、葛根透毒解肌，归、芍和血，连翘清热解毒，为出癍定法之方。〔服法〕上药切碎，水煎服，此为定法，其后随证加减。〔加减〕如肺出脓癍，先见喘咳或气高喘促，稍加人参、黄芩以泻伏火而补元气；如心出小红癍，必先见咽喉干、惊悸、身热肌肉肿、脉弦洪，稍加黄连"}, {"source": "条881｜《幼科证治准绳》集四·升麻汤、消毒散", "原文": "《幼科证治准绳》集四：“小儿耳冷尻冷，手足乍暖乍凉，面赤，时嗽时嚏，惊悸，此疮疹欲发候也，未能辨认间，服升麻汤、消毒散，已发未发皆宜服，仍用胡荽酒、黄柏膏。", "白话": "〔主治〕小儿耳廓发冷、尾骶部发冷，手足忽暖忽凉，面色发赤，时而咳嗽时而喷嚏，惊悸——这是疮疹将发的征候。在尚未辨认清楚之间，即服升麻汤、消毒散，已发未发都宜服用；外治仍用胡荽酒、黄柏膏。"}, {"source": "条882｜《幼科证治准绳》集四·木香散、异功散（误投之戒）", "原文": "《幼科证治准绳》集四：“今也不然，但见出迟者、身热者、泄泻者、惊悸者、气急者、渴思饮者，不问寒热虚实，率投木香散、异功散，间有偶中，随手获效，设或误投，祸不旋踵。", "白话": "〔评论〕现今医者不然：只要见痘出迟缓、身热、泄泻、惊悸、气急、口渴想饮水的，不问寒热虚实，一律投木香散、异功散；间或有偶然命中者，随手取效，但若误投，祸患接踵即至。"}, {"source": "条883｜《幼科证治准绳》集五·活人酸枣仁汤", "原文": "《幼科证治准绳》集五：“活人酸枣仁汤。治痘疹，虚烦惊悸不得眠。  \n酸枣仁炒、甘草炙、知母炒、白茯苓、麦门冬去心、川芎、干姜炒，各三分  \n上，水煎，温服。儿大倍之”。", "白话": "〔方名〕活人酸枣仁汤。〔主治〕治痘疹病中虚烦、惊悸、不得睡眠。〔组成·照录〕酸枣仁（炒）、甘草（炙）、知母（炒）、白茯苓、麦门冬（去心）、川芎、干姜（炒）各三分。〔方义〕枣仁养心安神，知母、麦冬清热除烦，苓、草健脾，川芎调血，干姜温中，合治痘疹余热扰心之虚烦惊悸。〔服法〕水煎温服，孩子年龄大者剂量加倍。"}, {"source": "条884｜《幼科证治准绳》集五·木香散（九证辨渴）", "原文": "《幼科证治准绳》集五：“文中云：腹胀渴者，泻渴者，足指冷渴者，惊悸渴者，身温渴者，身热面㿠白色渴者，寒战渴不止者，气急咬牙渴者，饮水转水泻不已者，以上九证，即非热也，乃津液少，脾胃肌肉虚故也，宜木香散治之。如不愈，更加丁香、官桂此说，必加审用之，胀渴、泻渴、惊悸渴、寒战渴、咬牙渴、亦多属热者，不可不察。", "白话": "〔引文〕文中说：腹胀而渴、泄泻而渴、足趾发冷而渴、惊悸而渴、身温而渴、身热而面色㿠白而渴、寒战而渴不止、气急咬牙而渴、饮水即水泻不止——以上九种见证，都不是热证，而是津液少、脾胃与肌肉虚弱之故，宜用木香散治疗。如不愈，再加丁香、官桂。此说必须审慎运用：胀渴、泻渴、惊悸渴、寒战渴、咬牙渴，也有不少属热者，不可不辨察。"}, {"source": "条885｜《女科证治准绳》卷一·白芷暖宫丸", "原文": "《女科证治准绳》卷一：“白芷暖宫丸。暖血海，实冲任。治子宫虚弱，风寒客滞，断绪不成孕育，及数坠胎；或带下赤白，漏下五色，虚眩少气，胸腹满痛，心下烦悸，自汗，下血过多。  \n禹余粮制，一两  干姜炮、芍药、白芷、川椒制、阿胶粉炒、艾叶制、川芎各七钱半   \n上为细末，蜜丸梧子大。每服四十丸，米饮、温酒、醋汤任下。", "白话": "〔方名〕白芷暖宫丸。〔功用〕温暖血海，充实冲任。〔主治〕治子宫虚弱、风寒客留停滞，断续久不孕育，及屡次堕胎；或带下赤白、漏下五色，虚眩短气，胸腹胀满疼痛，心下烦悸，自汗，下血过多。〔组成·照录〕禹余粮（制）一两；干姜（炮）、芍药、白芷、川椒（制）、阿胶（蛤粉炒）、艾叶（制）、川芎各七钱半。〔方义〕白芷、干姜、川椒、艾叶暖宫散寒，禹余粮、阿胶固涩止血，芎、芍和血，共成暖宫固冲之剂。〔制法·服法〕上为细末，炼蜜为丸，梧桐子大；每次服四十丸，米汤、温酒、醋汤任选一种送下。"}, {"source": "条886｜《女科证治准绳》卷二·茯神散", "原文": "《女科证治准绳》卷二：“茯神散。圣惠治妇人血风劳气，头疼目赤，胸背气壅，四肢疼痛，心烦惊悸，少欲饮食。  \n柴胡去苗、石膏各二两 茯神、羚羊角、防风去芦、赤芍药、人参去芦、天门冬去心、独活、郁李仁去皮，微炒、生干地黄、枳壳麸炒，去穰瓤，各一两 甘草炙，半两  桃仁汤浸，去皮、尖、双仁，麸炒黄，研如泥，一两半  \n上为散，每服四钱，以水一中盏，入生姜半分，煎至六分，去滓温服，无时。", "白话": "〔方名〕茯神散（《圣惠方》方）。〔主治〕治妇人血风劳气：头痛目赤，胸背气机壅滞，四肢疼痛，心烦惊悸，不欲饮食。〔组成·照录〕柴胡（去苗）、石膏各二两；茯神、羚羊角、防风（去芦）、赤芍药、人参（去芦）、天门冬（去心）、独活、郁李仁（去皮，微炒）、生干地黄、枳壳（麸炒，去瓤）各一两；甘草（炙）半两；桃仁（汤浸去皮尖双仁，麸炒黄，研如泥）一两半。〔方义〕柴胡、石膏、羚羊角清热熄风，茯神、二冬、地黄养心安神，参、草扶正，桃仁、郁李仁润通，治血风劳气兼惊悸者。〔制法·服法〕上为散，每服"}, {"source": "条887｜《女科证治准绳》卷二·清气汤", "原文": "《女科证治准绳》卷二：“清气汤普济。治肌热骨瘦者，阴衰阳盛也。是气弱而血热，则外蒸肌肉，内蒸骨髓，烦渴口干，颊赤头疼，饮食无味，心神惊悸，肢体酸疼，或时盗汗，或时咳嗽，或月家断绝，或经极少，俗谓血劳，产后曰白蓐劳，及羸瘦之人，与清气汤、羊乳丸治之。  \n紫苏子、五味子、大腹子、枳壳、桑白皮微炒、菖蒲、地骨皮、白术、柴胡、秦艽、独活、干葛、甘草炙，各等分  \n上㕮咀，每服五钱，水一盏，入紫苏七片，乌", "白话": "〔方名〕清气汤（《普济方》方）。〔主治〕治肌热骨瘦者，此阴衰阳盛之证：气弱而血热，外则蒸灼肌肉，内则熏蒸骨髓，见烦渴口干、颊赤头痛、饮食无味、心神惊悸、肢体酸疼，或时发盗汗，或时咳嗽，或月经断绝，或经量极少——俗称血劳，产后称白蓐劳；凡羸瘦之人，用清气汤、羊乳丸治疗。〔组成·照录〕紫苏子、五味子、大腹子、枳壳、桑白皮（微炒）、菖蒲、地骨皮、白术、柴胡、秦艽、独活、干葛、甘草（炙）各等分。〔方义〕地骨皮、桑白皮、葛根清虚热，苏子、枳壳、大腹子下气，参入白术健脾，菖蒲安神，合治气"}, {"source": "条888｜《女科证治准绳》卷五·白茯苓丸", "原文": "《女科证治准绳》卷五：“白茯苓丸。治产后心虚惊悸，神志不安。  \n白茯苓去皮、熟干地黄各一两 人参去芦、桂心、远志去心、石菖蒲、柏子仁、琥珀各半两，另研细  \n上为细末，炼蜜和捣三二百下，丸如梧子大。每服三十丸，不拘时，粥饮送下。", "白话": "〔方名〕白茯苓丸。〔主治〕治产后心虚惊悸、神志不安。〔组成·照录〕白茯苓（去皮）、熟干地黄各一两；人参（去芦）、桂心、远志（去心）、石菖蒲、柏子仁、琥珀各半两（琥珀另研细）。〔方义〕茯苓、人参益心气，地黄、柏子仁养心血，远志、菖蒲、琥珀开窍安神，桂心温阳，为产后养心安神之丸。〔制法·服法〕上为细末，炼蜜和药捣三二百下，丸如梧桐子大；每次服三十丸，不拘时，粥汤送下。"}, {"source": "条889｜《女科证治准绳》卷五·白茯苓散", "原文": "《女科证治准绳》卷五：“白茯苓散。治产后心神惊悸，言语失常，心神昏愦。  \n白茯苓去皮、熟地黄、人参去芦，各一两半 远志去心、白芍药、黄芪去芦、桂心、当归炒，去芦、甘草炙、麦门冬各一两，去心  石菖蒲、桑寄生各七钱半   \n上为㕮咀，每服八钱，水一大盏半，生姜五片，枣三枚，竹叶三七片，煎至一大盏，去渣温服，无时。", "白话": "〔方名〕白茯苓散。〔主治〕治产后心神惊悸、言语失常、心神昏乱。〔组成·照录〕白茯苓（去皮）、熟地黄、人参（去芦）各一两半；远志（去心）、白芍药、黄芪（去芦）、桂心、当归（炒，去芦）、甘草（炙）、麦门冬（去心）各一两；石菖蒲、桑寄生各七钱半。〔方义〕茯苓、人参、黄芪益气安神，四物养血，麦冬滋阴，远志、菖蒲开心气，桂心通阳，标本兼顾。〔服法〕上药切碎，每服八钱，水一大盏半加生姜五片、大枣三枚、竹叶二十一片，煎至一大盏，去渣温服，不拘时。"}, {"source": "条890｜《女科证治准绳》卷五·远志丸", "原文": "《女科证治准绳》卷五：“远志丸。治产后脏虚不足，心神惊悸，志意不安，腹中急痛，或时怕怖，夜卧不安。  \n远志、麦门冬各去心、黄芪、当归炒、人参、白术、独活各去芦、白茯苓去皮、桂心、柏子仁、石菖蒲、熟干地黄、山茱萸、钟乳粉、阿胶碎、炒，各一两  \n上为细末，炼蜜和捣五七百下，丸如梧桐子大。每服三十丸，温酒送下，不拘时候，日进二服。", "白话": "〔方名〕远志丸。〔主治〕治产后脏气虚损不足，心神惊悸，意志不安，腹中拘急疼痛，或时觉恐惧，夜卧不安。〔组成·照录〕远志、麦门冬（各去心）、黄芪、当归（炒）、人参、白术、独活（各去芦）、白茯苓（去皮）、桂心、柏子仁、石菖蒲、熟干地黄、山茱萸、钟乳粉、阿胶（碎，炒）各一两。〔方义〕远志、菖蒲、柏仁安神定志，参、芪、术、苓益气，归、地、阿胶养血，桂心、山茱萸、钟乳温固下元，为产后脏虚惊悸之剂。〔制法·服法〕上为细末，炼蜜和药捣五至七百下，丸如梧桐子大；每次服三十丸，温酒送下，不拘时"}, {"source": "条891｜《女科证治准绳》卷五·产后咳嗽（黑神散、五积散）", "原文": "《女科证治准绳》卷五：“产后血气不通，咳嗽者何？答曰：产后咳嗽，多因食热面壅滞，或热病，或有气块，发时冲心痛，气急咳嗽，四肢寒热，心闷口干，或时烦躁，睡梦惊悸，气虚肢体无力，宜服《局方》黑神散、五积散加枣煎服。", "白话": "〔问答〕问：产后血气不通而咳嗽者为何？答：产后咳嗽，多因食热面壅滞，或因热病，或因有气块，发作时气冲心胸而痛，气急咳嗽，四肢或寒或热，心闷口干，或时烦躁，睡梦中惊悸，气虚而肢体无力——宜服《局方》黑神散、五积散加姜枣煎服。"}, {"source": "条892｜《先醒斋医学广笔记》卷二·产后调理方", "原文": "《先醒斋医学广笔记》卷二：“产后调理方仲淳立，如产时恶露过多，无儿枕痛者，不可用此方。  \n当归身三钱 川芎一钱五分 生地二钱 赤芍药一钱五分 延胡索醋煮，二钱 牛膝五钱 蒲黄一钱五分 干姜炒黑，七分 肉桂七分，火盛者并夏月勿用 山楂肉三钱 五灵脂醋煮去沙，一钱 桃仁去皮尖、红花各八分 黑豆炒，一合 杜仲炒去丝，二钱 续断二钱 益母草五钱，瘀血行腹痛去之 泽兰叶一钱 荆芥穗一钱，炒  \n水煎，入童", "白话": "〔方名〕产后调理方（缪仲淳立）。〔禁忌〕如产时恶露过多而无儿枕痛者，不可用此方。〔组成·照录〕当归身三钱，川芎一钱五分，生地二钱，赤芍药一钱五分，延胡索（醋煮）二钱，牛膝五钱，蒲黄一钱五分，干姜（炒黑）七分，肉桂七分（火盛者及夏季勿用），山楂肉三钱，五灵脂（醋煮去沙）一钱，桃仁（去皮尖）、红花各八分，黑豆（炒）一合，杜仲（炒去丝）二钱，续断二钱，益母草五钱（瘀血已行、腹痛者去之），泽兰叶一钱，荆芥穗（炒）一钱。〔方义〕生化汤加减法，以芎、归、桃仁、红花、蒲黄、灵脂、延胡行瘀活"}, {"source": "条893｜《疹科类编·方》·加味四物汤", "原文": "《疹科类编·方》：“加味四物汤。治疹后时发壮热，烦躁不宁，搐掣惊悸，神昏志乱者。此阴血衰耗，致余毒入肝而传于心也，宜用此养血安神。  \n当归 川芎 芍药 生地黄 麦门冬去心 茯神去木 石菖蒲 酸枣仁炒 龙胆草 黄连 甘草 辰砂 淡竹叶 灯心草  \n上锉，水煎服。或为末，用蒸饼猪心血丸亦可。", "白话": "〔方名〕加味四物汤。〔主治〕治疹后时时发作壮热、烦躁不宁、抽掣惊悸、神昏志乱者。此因阴血衰耗，以致余毒入肝而传于心，宜用此方养血安神。〔组成·照录〕当归、川芎、芍药、生地黄、麦门冬（去心）、茯神（去木）、石菖蒲、酸枣仁（炒）、龙胆草、黄连、甘草、辰砂、淡竹叶、灯心草。〔方义〕四物加麦冬养血滋阴，茯神、菖蒲、枣仁安神，龙胆、黄连、竹叶、灯心清心肝余毒，为疹后养血安神之剂。〔服法〕上药切碎，水煎服；或研为末，用蒸饼加猪心血为丸亦可。"}, {"source": "条894｜《邯郸遗稿》卷四·龙齿清魂散", "原文": "《邯郸遗稿》卷四：“有因心虚惊悸，言语错乱，不知人事，目瞪不能叫呼，宜用龙齿清魂散。", "白话": "〔主治〕有因心虚而惊悸、言语错乱、不省人事、两目直瞪不能呼叫者，宜用龙齿清魂散。"}, {"source": "条895｜《外科正宗》卷二·金液戊土丹", "原文": "《外科正宗》卷二：“金液戊土丹。金液戊土丹五味，牛黄神志石菖蒲，砂雄硝石乌梅等，片射人中黄不殊。治脱疽及疔疮、发背，纵食膏粱厚味法酒，又或丹石补药，勉力房劳，多致积毒脏腑，久则胃汁中干，肾水枯竭，不能上制心火，以致消渴、消中、消肾，饶饮多干，能食多瘦，九窍不通，惊悸健忘，此症若出后必发疽，多难治疗。宜预服此，亦可转重就轻，移深就浅，又解五金八石之毒药也。  \n乌梅肉、茯神、胡黄连、五味子各一两 石", "白话": "〔方名〕金液戊土丹（附方歌：金液戊土丹五味，牛黄神志石菖蒲，砂雄硝石乌梅等，片射人中黄不殊）。〔主治〕治脱疽及疔疮、发背：因纵食膏粱厚味、饮酒无度，或服丹石补药，勉强行房劳伤，多致积毒于脏腑；久则胃中津液干涸、肾水枯竭，不能上制心火，以致消渴、消中、消肾，饮多而口干，能食而消瘦，九窍不通，惊悸健忘；此证既现，其后必发痈疽，多难治疗。宜预先服此药，可转重为轻、移深就浅，并解五金八石药石之毒。〔组成·照录〕乌梅肉、茯神、胡黄连、五味子各一两；石菖蒲、辰砂、雄黄、远志、硝石各三钱；"}, {"source": "条896｜《外科正宗》卷二·滋荣散坚汤", "原文": "《外科正宗》卷二：“滋荣散坚汤。滋阴散坚四物汤，甘桔参苓海粉当，陈术升麻香附贝，红花昆布共煎尝。治一切瘰疬，忧抑所伤，气血不足，形体瘦弱，潮热咳嗽，坚硬肿痛。毋分新久，但未穿溃者并效。  \n川芎、当归、白芍、熟地、陈皮、茯苓、桔梗、白术、香附各一钱 甘草、海粉、贝母、人参、昆布各五分 升麻、红花各三分  \n水二钟，姜三片，枣二枚，煎八分，食远服。身热加柴胡、黄芩，自汗盗汗去升麻倍人参、黄芪，饭食无", "白话": "〔方名〕滋荣散坚汤（方歌：滋阴散坚四物汤，甘桔参苓海粉当，陈术升麻香附贝，红花昆布共煎尝）。〔主治〕治一切瘰疬，因忧郁所伤，气血不足，形体瘦弱，潮热咳嗽，坚硬肿痛；不分新久，凡未穿破溃烂者都有效。〔组成·照录〕川芎、当归、白芍、熟地、陈皮、茯苓、桔梗、白术、香附各一钱；甘草、海粉、贝母、人参、昆布各五分；升麻、红花各三分。〔方义〕四物养血，参、术、苓、草益气，海粉、昆布、贝母化痰软坚，桔梗、升麻、香附理气散结，为滋荣散坚之剂。〔服法〕水二钟加姜三片、枣二枚，煎取八分，食远服。"}, {"source": "条897｜《济阴纲目》卷十二·琥珀散", "原文": "《济阴纲目》卷十二：“琥珀散。治血虚，惊悸少寐，及产后败血停留，少腹作痛。  \n辰砂另研、没药、琥珀并研细、当归等分  \n上为细末，每服二钱，空心日午临卧白汤调下。", "白话": "〔方名〕琥珀散。〔主治〕治血虚惊悸、睡眠少，及产后败血停留、小腹疼痛。〔组成·照录〕辰砂（另研）、没药、琥珀（并研细）、当归各等分。〔方义〕当归养血，琥珀、辰砂镇心安神，没药散瘀定痛，治血虚夹瘀之惊悸少寐。〔制法·服法〕上为细末，每服二钱，空腹、中午、临睡前白开水调下。"}, {"source": "条898｜《婴童类萃》上卷·天麻定惊丸", "原文": "《婴童类萃》上卷：“天麻定惊丸。治小儿急慢惊风，身体壮热，精神恍惚，痰涎多睡，惊悸不安，手足搐搦，并宜服之。  \n天麻明、僵蚕炒、防风、人参各五钱 甘草、朱砂、全蝎各三钱 雄黄一钱五分 牛黄一钱 麝香三分  \n为末，蜜丸，芡实大，每服一丸，薄荷汤下。", "白话": "〔方名〕天麻定惊丸。〔主治〕治小儿急、慢惊风：身体壮热，精神恍惚，痰涎壅盛多睡，惊悸不安，手足抽搐，都宜服用。〔组成·照录〕天麻（明）、僵蚕（炒）、防风、人参各五钱；甘草、朱砂、全蝎各三钱；雄黄一钱五分；牛黄一钱；麝香三分。〔方义〕天麻、僵蚕、全蝎、防风祛风定惊，牛黄、雄黄、朱砂清心镇惊，参、草扶正，为定惊化痰之丸。〔制法·服法〕为末，炼蜜为丸，芡实大；每次服一丸，薄荷汤送下。"}, {"source": "条899｜《婴童类萃》下卷·大建中汤", "原文": "《婴童类萃》下卷：“大建中汤。治虚热盗汗，怔忡惊悸，四肢倦怠，气促。  \n黄芪一钱，蜜炒 远志肉、当归各八分 泽泻、白芍、人参、甘草炙、酸枣仁炒、龙骨煨研，各五分", "白话": "〔方名〕大建中汤。〔主治〕治虚热盗汗、怔忡惊悸、四肢倦怠、气短。〔组成·照录〕黄芪（蜜炒）一钱；远志肉、当归各八分；泽泻、白芍、人参、甘草（炙）、酸枣仁（炒）、龙骨（煨，研）各五分。〔方义〕黄芪、人参、甘草益气，归、芍养血，枣仁、远志、龙骨安神敛汗，为建中补虚、安神定悸之剂。"}, {"source": "条900｜《婴童类萃》下卷·犀角汤", "原文": "《婴童类萃》下卷：“犀角汤。治身热发黄，口干烦躁，心神惊悸。\n茵陈一钱 干葛 龙胆草 升麻 滑石一钱五分 寒水石一钱五分 犀角、生地各七分  \n灯心二十寸，竹叶十片，水煎。", "白话": "〔方名〕犀角汤。〔主治〕治身热发黄、口干烦躁、心神惊悸。〔组成·照录〕茵陈一钱，干葛、龙胆草、升麻，滑石一钱五分，寒水石一钱五分，犀角、生地各七分。〔方义〕茵陈、滑石、寒水石清热利湿退黄，犀角、生地清心凉血，龙胆、升麻、葛根解毒透邪，治热黄兼惊悸者。〔服法〕灯心二十寸、竹叶十片为引，水煎。"}, {"source": "条901｜《景岳全书》卷五十一·小营煎", "原文": "《景岳全书》卷五十一：“小营煎。治血少阴虚，此性味平和之方也。  \n当归二钱 熟地二、三钱 芍药酒炒，二钱 山药炒，二钱 枸杞二钱 炙甘草一钱  \n水二钟，煎七分，食远温服。如营虚于上，而为惊恐怔忡，不眠多汗者，加枣仁、茯神各二钱；如营虚兼寒者，去芍药，加生姜；如气滞有痛者，加香附一、二钱，引而行之。", "白话": "〔方名〕小营煎。〔主治〕治血少阴虚，这是性味平和之方。〔组成·照录〕当归二钱，熟地二三钱，芍药（酒炒）二钱，山药（炒）二钱，枸杞二钱，炙甘草一钱。〔方义〕当归、熟地、芍药、枸杞养营血、滋肝肾，山药、甘草健脾和中，为平补营血之剂。〔服法〕水二钟煎取七分，食远温服。〔加减〕如营血虚于上，而见惊恐怔忡、不眠多汗者，加酸枣仁、茯神各二钱；如营虚兼寒者，去芍药加生姜；如气滞有痛者，加香附一二钱以行气。"}, {"source": "条902｜《景岳全书》卷五十一·右归丸", "原文": "《景岳全书》卷五十一：“右归丸。治元阳不足，或先天禀衰，或劳伤过度，以致命门火衰，不能生土，而为脾胃虚寒，饮食少进，或呕恶膨胀，或番胃噎膈，或怯寒畏冷，或脐腹多痛，或大便不实，泻痢频作，或小水自遗，虚淋寒疝，或寒侵溪谷而肢节痹痛，或寒在下焦而水邪浮肿。总之，真阳不足者，必神疲气怯，或心跳不宁，或四体不收，或眼见邪崇，或阳衰无子等证，俱速宜益火之原，以培右肾之元阳，而神气自强矣，此方主之。  \n大怀", "白话": "〔方名〕右归丸。〔主治〕治元阳不足：或先天禀赋不足，或劳伤过度，以致命门火衰，不能生土，而见脾胃虚寒、饮食减少，或呕吐恶心、腹胀，或反胃噎膈，或怯寒畏冷，或脐腹多痛，或大便不实、泻痢频作，或小便自遗、虚淋寒疝，或寒侵溪谷而肢节痹痛，或寒在下焦而水邪浮肿。总之真阳不足者，必见神疲气怯，或心跳不宁，或四肢不收，或眼见鬼祟，或阳衰无子等证——都应赶紧温益火之本源，以培补右肾元阳，则神气自然强健，此方主治。〔组成·照录〕大怀熟地八两，山药（炒）四两，山茱萸（微炒）三两，枸杞（微炒）四"}, {"source": "条903｜《景岳全书》卷五十三·加味四君汤", "原文": "《景岳全书》卷五十三：“加味四君汤。治痔漏下血，面色痿黄，怔忡耳鸣，脚软气弱，及一切脾胃气虚，口淡，食不知味，又治气虚不能摄血，以致下血不禁。　　\n人参 白术炒 茯苓 炙甘草 黄芪炙 白扁豆炒　　\n上水煎服。或为末，每服三钱，滚汤调服。", "白话": "〔方名〕加味四君汤。〔主治〕治痔漏下血，面色萎黄，怔忡耳鸣，脚软气弱，及一切脾胃气虚之口淡、食不知味；又治气虚不能摄血而下血不止。〔组成·照录〕人参、白术（炒）、茯苓、炙甘草、黄芪（炙）、白扁豆（炒）。〔方义〕四君子汤加黄芪、扁豆，益气健脾、气旺摄血，脾健则心有所养、怔忡可止。〔服法〕水煎服；或研为末，每服三钱，滚开水调服。"}, {"source": "条904｜《妇人规》下卷·东垣朱砂安神丸", "原文": "《妇人规》下卷：“东垣朱砂安神丸，一名黄连安神丸。治心神烦乱，发热怔忡，不寐或寐中惊悸、头运同晕等证。  \n生地、朱砂另飞为衣、当归各一钱 甘草五分 黄连一钱半  \n汤浸蒸饼为丸，黍米大，每服十五丸或二十丸，津液咽之，或食后用温水、凉水送下亦可。", "白话": "〔方名〕东垣朱砂安神丸，又名黄连安神丸。〔主治〕治心神烦乱、发热怔忡、不寐，或睡中惊悸、头眩晕等证。〔组成·照录〕生地、朱砂（另飞为衣）、当归各一钱，甘草五分，黄连一钱半。〔方义〕黄连清心火，生地、当归养阴血，朱砂镇心安神，为清心养血安神之名方。〔制法·服法〕以汤浸蒸饼为丸，黍米大；每服十五至二十丸，以津液（唾液）咽下，或食后用温水、凉水送下亦可。"}, {"source": "条905｜《济阳纲目》卷十六·当归补血汤", "原文": "《济阳纲目》卷十六：“当归补血汤。治心中血少而嘈，兼治惊悸怔忡。  \n当归、芍药、生地黄、熟地黄各三钱 人参五分 白术、白茯苓、麦门冬去心、山栀仁炒、陈皮各八分 甘草、辰砂研末，临服入，各三分 乌梅一个，去核 炒米百粒  \n上锉一剂，加枣二枚，水煎，温服。", "白话": "〔方名〕当归补血汤。〔主治〕治心中血少而嘈杂，兼治惊悸怔忡。〔组成·照录〕当归、芍药、生地黄、熟地黄各三钱；人参五分；白术、白茯苓、麦门冬（去心）、山栀仁（炒）、陈皮各八分；甘草、辰砂（研末，临服时加入）各三分；乌梅一个（去核）；炒米百粒。〔方义〕四物补血，参、术、苓、草益气，麦冬滋阴，栀子清热，佐辰砂镇心，为补血养心、兼清虚热之剂。〔服法〕上药切碎一剂，加大枣二枚，水煎温服。"}, {"source": "条906｜《济阳纲目》卷四十五·归神丹", "原文": "《济阳纲目》卷四十五：“归神丹。治癫痫诸疾，惊悸，神不守舍。  \n朱砂颗块二两，猪心内酒蒸 罗参、当归、白茯苓、酸枣仁各二两 远志姜制、琥珀、龙齿各一两 金箔、银箔各二十片  \n上为细末，酒糊丸，如桐子大，每服二三十丸，麦门冬汤下，炒酸枣仁亦可。", "白话": "〔方名〕归神丹。〔主治〕治癫痫诸疾、惊悸、神不守舍。〔组成·照录〕朱砂（颗块）二两，纳猪心内酒蒸；罗参、当归、白茯苓、酸枣仁各二两；远志（姜制）、琥珀、龙齿各一两；金箔、银箔各二十片。〔方义〕朱砂、琥珀、龙齿、金银箔重镇安神，参、归、苓、枣仁补养心脾，远志开心气，为镇心归神之丹。〔制法·服法〕上为细末，酒糊为丸，梧桐子大；每服二三十丸，麦门冬汤送下，用炒酸枣仁煎汤送下亦可。"}, {"source": "条907｜《济阳纲目》卷五十四·加味定志丸", "原文": "《济阳纲目》卷五十四：“加味定志丸。治肥人痰迷心膈，寻常怔忡惊悸。  \n远志、菖蒲各二两 人参一两 白茯苓三两 琥珀 郁金  \n上为末，炼蜜丸如桐子大，朱砂为衣，每服三十丸，米汤下。一方有天花粉、贝母、瓜蒌仁。", "白话": "〔方名〕加味定志丸。〔主治〕治肥人痰浊蒙蔽心膈，平时怔忡惊悸。〔组成·照录〕远志、菖蒲各二两，人参一两，白茯苓三两，琥珀、郁金（原稿未注剂量）。〔方义〕远志、菖蒲、郁金化痰开窍，茯苓、人参健脾益气以杜生痰之源，琥珀镇心安神。〔制法·服法〕上为末，炼蜜为丸，梧桐子大，朱砂为衣；每服三十丸，米汤送下。另一方有天花粉、贝母、瓜蒌仁。"}, {"source": "条908｜《济阳纲目》卷五十四·辰砂远志丸", "原文": "《济阳纲目》卷五十四：“辰砂远志丸。治惊悸，消风痰。  \n石菖蒲、远志、人参、茯神、川芎、山药、铁粉、麦冬、天麻、半夏、南星、茯苓各一两 北细辛、辰砂各半两  \n上为细末，生姜五两，取汁入水，煮糊为丸，如绿豆大，另以朱砂为衣，每服二十五丸，临卧生姜汤下，小儿减服。", "白话": "〔方名〕辰砂远志丸。〔主治〕治惊悸，消风痰。〔组成·照录〕石菖蒲、远志、人参、茯神、川芎、山药、铁粉、麦冬、天麻、半夏、南星、茯苓各一两；北细辛、辰砂各半两。〔方义〕菖蒲、远志、茯神、天麻安神定悸，半夏、南星、细辛祛风痰，铁粉重镇，参、药、苓健脾，为消风痰、镇惊悸之丸。〔制法·服法〕上为细末，取生姜五两汁加水煮糊为丸，绿豆大，另以朱砂为衣；每服二十五丸，临睡前生姜汤送下，小儿减量。"}, {"source": "条909｜《济阳纲目》卷五十四·养心安神汤", "原文": "《济阳纲目》卷五十四：“养心安神汤。治血虚火动，惊悸怔忡。  \n当归身酒洗、川芎、白芍药炒、陈皮、黄连、柏子仁炒，各五分 生地黄酒炒、茯神各一钱 白术、酸枣仁炒，各七分 甘草炙，三分  \n上锉一服，水煎服。", "白话": "〔方名〕养心安神汤。〔主治〕治血虚火动、惊悸怔忡。〔组成·照录〕当归身（酒洗）、川芎、白芍药（炒）、陈皮、黄连、柏子仁（炒）各五分；生地黄（酒炒）、茯神各一钱；白术、酸枣仁（炒）各七分；甘草（炙）三分。〔方义〕归、芎、芍、地养血，黄连清火，枣仁、柏仁、茯神养心安神，术、草健脾，为养血清火、安神定悸之剂。〔服法〕上药切碎一服，水煎服。"}, {"source": "条910｜《济阳纲目》卷五十四·寒水石散", "原文": "《济阳纲目》卷五十四：“寒水石散。治因惊心气不行，郁而生涎，结为饮，遂为大疾，怔悸陨获，不自胜持，少遇惊则发，尤宜服之。  \n寒水石煅、滑石水飞，各二钱 生甘草一钱  \n上为末，每服二钱，热则用新汲水下，怯寒则用姜枣汤下。加龙胆草少许尤佳。", "白话": "〔方名〕寒水石散。〔主治〕治因惊而心气不行，郁结生涎，凝结为饮，遂成大病：怔忡心悸、惊恐不安，不能自持，稍遇惊即发作——尤宜服此。〔组成·照录〕寒水石（煅）、滑石（水飞）各二钱，生甘草一钱。〔方义〕寒水石、滑石清热利湿、导饮下行，生甘草和中缓急，为清镇化饮之散。〔制法·服法〕上为末，每服二钱：发热者用新汲井水送下，怯寒者用姜枣汤送下，加龙胆草少许尤佳。"}, {"source": "条911｜《济阳纲目》卷五十四·温胆汤加味", "原文": "《济阳纲目》卷五十四：“怔忡因惊悸久而成，痰在下火在上故也，温胆汤加黄连、山栀、当归、贝母。", "白话": "〔病机〕怔忡是由惊悸日久发展而成，其原因是痰在下、火在上。〔方名·加减〕用温胆汤加黄连、山栀、当归、贝母。"}, {"source": "条912｜《济阳纲目》卷五十五·人参远志丸", "原文": "《济阳纲目》卷五十五：“人参远志丸。治心气不足，惊悸健忘，神思不安。  \n天门冬去心、白茯苓、菖蒲各七钱半 人参、远志去心、酸枣仁、黄芪各半两  桔梗、丹砂、官桂去皮，各二钱半\n上为末，炼蜜丸如绿豆大，每服二十丸至三十丸，米汤下。", "白话": "〔方名〕人参远志丸。〔主治〕治心气不足，惊悸健忘，神思不安。〔组成·照录〕天门冬（去心）、白茯苓、菖蒲各七钱半；人参、远志（去心）、酸枣仁、黄芪各半两；桔梗、丹砂、官桂（去皮）各二钱半。〔方义〕参、芪、苓益心气，二冬、枣仁养心阴，远志、菖蒲、桔梗开窍安神，丹砂镇心，官桂温阳，为益气养心安神之丸。〔制法·服法〕上为末，炼蜜为丸，绿豆大；每服二三十丸，米汤送下。"}, {"source": "条913｜《济阳纲目》卷六十四·安神补心定志益元固真丸", "原文": "《济阳纲目》卷六十四：“安神补心定志益元固真丸。安心安神，固精益血，壮力强志，令人善记不忘；除怔忡，定惊悸，清三焦，大化痰，祛烦热，疗咽干，滋肾水，健脾胃，悦颜色，生肌肤，不寒不热。  \n当归一两二钱，酒洗 天冬八钱，去心 麦冬一两，去心 柏子仁一两，炒 远志一两二钱，去皮，甘草浸 知母七钱，盐水炒 黄连一两，姜汁炒 百部五钱 酸枣仁一两，炒去油 白茯苓一两二钱 玄参七钱 生地黄二两，酒洗 石菖蒲", "白话": "〔方名〕安神补心定志益元固真丸。〔功用〕安心安神，固精益血，壮力强志，使人善记不忘；除怔忡，定惊悸，清三焦，大化痰浊，祛烦热，疗咽干，滋肾水，健脾胃，悦颜色，生肌肤，性不寒不热。〔组成·照录〕当归一两二钱（酒洗），天冬八钱（去心），麦冬一两（去心），柏子仁一两（炒），远志一两二钱（去皮，甘草浸），知母七钱（盐水炒），黄连一两（姜汁炒），百部五钱，酸枣仁一两（炒去油），白茯苓一两二钱，玄参七钱，生地黄二两（酒洗），石菖蒲一两（炒），熟地黄二两（酒洗），杜仲一两（去丝，姜汁炒），"}, {"source": "条914｜《济阳纲目》卷七十七·三阴里证诸方", "原文": "《济阳纲目》卷七十七：“三阴里证，胸满怔忡，遍体转筋，二便闭涩或自利者，羌活导滞汤、除湿丹、导水丸、搜风顺气丸。", "白话": "〔主治〕三阴里证，胸满怔忡，周身转筋，大小便闭结涩滞或自利者——用羌活导滞汤、除湿丹、导水丸、搜风顺气丸。"}, {"source": "条915｜《医学研悦》卷四·达生散", "原文": "《医学研悦》卷四：“达生散。胎至八九月多服易产。 \n陈皮八分 甘草炒，三分 白芍酒炒，一钱 当归用身，钱半 川芎六分 香附醋炒，二钱 苏梗七分 白术土炒，八分 续断酒洗，一钱 杜仲盐水炒去丝，一钱 山楂一钱二分  \n生姜水煎。咳嗽去香附，加麦冬、五味子九粒；脾胃不实加山药饭上蒸一钱，砂仁五分；心跳恍惚，加酸枣仁炒香一钱二分、远志甘草汤，煺去骨七分；发热加黄芩炒六分。", "白话": "〔方名〕达生散。〔功用〕妊娠至八九个月时多服，易于分娩。〔组成·照录〕陈皮八分，甘草（炒）三分，白芍（酒炒）一钱，当归（用身）一钱半，川芎六分，香附（醋炒）二钱，苏梗七分，白术（土炒）八分，续断（酒洗）一钱，杜仲（盐水炒去丝）一钱，山楂一钱二分。〔方义〕归、芍、芎养血，术、草健脾，杜仲、续断固肾安胎，香附、苏梗、陈皮理气，为安胎达生之方。〔服法〕生姜水煎服。〔加减〕咳嗽去香附，加麦冬、五味子九粒；脾胃不实加饭上蒸山药一钱、砂仁五分；心跳恍惚，加炒香酸枣仁一钱二分、远志（甘草汤"}, {"source": "条916｜《医学研悦》卷七·天王补心丹", "原文": "《医学研悦》卷七：“古人制心肾丸、补心丹、养心丸，盖兼心肾而补之也。丹溪云：心为手少阴君火，肾为足少阴子水。少阴者，体也。水火者，用也。同体异用，不必虚至健忘、怔忡、惊悸、神志昏乱者，在所当用。天王补心丹，主方  \n熟地黄一两 白茯苓一两 人参一两 远志去心，甘草煮，一两 石菖蒲一两 玄参一两 柏子仁去壳，一两 天冬去心，一两 麦冬去心，一两 丹参一两 酸枣仁去壳炒，一两 甘草炙，一两 归身酒洗，", "白话": "〔引论〕古人制心肾丸、补心丹、养心丸，都是兼顾心肾而补之。朱丹溪说：心为手少阴君火，肾为足少阴子水；少阴是其体，水火是其用，同体而异用。凡虚损未至健忘、怔忡、惊悸、神志昏乱者，也在所当用。〔方名〕天王补心丹，主方：〔组成·照录〕熟地黄一两，白茯苓一两，人参一两，远志（去心，甘草煮）一两，石菖蒲一两，玄参一两，柏子仁（去壳）一两，天冬（去心）一两，麦冬（去心）一两，丹参一两，酸枣仁（去壳炒）一两，甘草（炙）一两，当归身（酒洗）一两，杜仲（盐水入姜汁炒，去丝）一两，五味子一两。〔"}, {"source": "条917｜《产鉴》下卷·产后恶露冲心方", "原文": "《产鉴》下卷：“治产后恶露冲心，语言乱通，如见鬼神，惊悸不定，小便不利者。  \n琥珀、辰砂、没药各研细 当归各一两  \n上为细末，每服二钱，空心白汤调下，日三服，心腹痛者加延胡索，兼晕者加蒲黄。", "白话": "〔主治〕治产后恶露上冲于心，语言错乱，如见鬼神，惊悸不安，小便不利者。〔组成·照录〕琥珀、辰砂、没药（各研细）、当归各一两。〔方义〕琥珀、辰砂镇心安神，没药、当归行瘀止痛，治败血冲心之惊悸谵妄。〔制法·服法〕上为细末，每服二钱，空腹白开水调下，一日三次。〔加减〕心腹痛者加延胡索；兼头晕者加蒲黄。"}, {"source": "条918｜《痰火点雪》卷一·芡实丸", "原文": "《痰火点雪》卷一：“芡实丸。治思虑伤心，疲劳伤肾，心肾不交，精元不固，面无颜色，惊悸健忘，夜梦不宁，小便赤涩，遗精白浊，足胵胫酸痛，耳聋目昏，口干脚弱。  \n芡实取生肉，二两，益肾，固精，补脾 莲须一两，清心，通肾固精 茯神去木，一两，止惊悸，又开心益志，安魂魄，宁乱神，秘精髓，虚而小便不利者，加而用之 山茱萸取肉，二两，补肾气，添精髓，止小便不禁，养精气，取其味酸涩以收秘滑也 龙骨煅，研，五钱，", "白话": "〔方名〕芡实丸。〔主治〕治思虑伤心、疲劳伤肾，心肾不交，精元不固，面色无华，惊悸健忘，夜梦不宁，小便赤涩，遗精白浊，足小腿酸痛，耳聋目昏，口干脚软。〔组成·照录（含原稿药后注解）〕芡实取生肉二两（益肾、固精、补脾）；莲须一两（清心、通肾固精）；茯神去木一两（止惊悸，又开心益志、安魂魄、宁乱神、秘精髓，虚而小便不利者加而用之）；山茱萸取肉二两（补肾气、添精髓、止小便不禁、养精气，取其味酸涩以收秘滑）；龙骨煅研五钱（治心腹鬼忤鬼疰、养精神、逐邪气、安心神、止夜梦鬼交，虚而多梦者益"}, {"source": "条919｜《医宗必读》卷十·镇心丸", "原文": "《医宗必读》卷十：“镇心丸。治心血不足，怔忡多梦，如堕崖谷。　　\n酸枣仁炒，二钱半 车前子去土、白茯苓去皮、麦门冬去心、五味子、茯神去木、 肉桂各一两二钱半 熟地黄酒浸，蒸、龙齿、天门冬去心、远志甘草水煮，去心、山药姜制，各一两半 人参、朱砂水飞为衣，各半两　　\n上为末，蜜丸，梧子大，每服三钱，空心米汤下。", "白话": "〔方名〕镇心丸。〔主治〕治心血不足，怔忡多梦，梦中如坠崖谷。〔组成·照录〕酸枣仁（炒）二钱半；车前子（去土）、白茯苓（去皮）、麦门冬（去心）、五味子、茯神（去木）、肉桂各一两二钱半；熟地黄（酒浸，蒸）、龙齿、天门冬（去心）、远志（甘草水煮，去心）、山药（姜制）各一两半；人参、朱砂（水飞为衣）各半两。〔方义〕枣仁、二冬、五味、地黄、龙齿、朱砂养心镇心，参、苓、山药益气健脾，肉桂温阳，车前子利湿，为养血镇心之丸。〔制法·服法〕上为末，炼蜜为丸，梧桐子大；每服三钱，空腹米汤送下。"}, {"source": "条920｜《幼科折衷秘传真本·杂方》·六合定中丸", "原文": "《幼科折衷秘传真本·杂方》：“六合定中丸。治暑月感凉，疟疾霍乱，胸闷恶心，头疼腹痛，或吐泻寒热如虐，以及小儿发热发搐，吐乳惊悸，一切中土不和等症。  \n老苏梗、陈香薷、广藿香以上，各四两 炒枳壳三两 羌活二两 赤苓四两  \n加老姜为丸，如龙眼肉大，每服一丸。", "白话": "〔方名〕六合定中丸。〔主治〕治暑月感受凉邪，疟疾霍乱，胸闷恶心，头痛腹痛，或呕吐泄泻、寒热往来如疟，以及小儿发热抽搐、吐乳惊悸，一切中焦脾胃不和等证。〔组成·照录〕老苏梗、陈香薷、广藿香以上各四两；炒枳壳三两；羌活二两；赤茯苓四两。〔方义〕苏梗、香薷、藿香芳香化浊解暑，枳壳理气，羌活祛风，赤苓利湿，为解暑和中定中之丸。〔制法·服法〕加老姜为丸，龙眼肉大；每服一丸。"}, {"source": "条921｜《删补颐生微论》卷四·天王补心丹", "原文": "《删补颐生微论》卷四：“天王补心丹。主心血不足，神志不宁，津液枯竭，健忘怔忡，大便不利，口舌生疮等症。　　\n人参去芦、白茯苓去皮、玄参炒、丹参炒、远志去木炒、桔梗各五钱 五味子烘、当归身酒洗、麦门冬去心、天门冬去心、柏子仁炒、酸枣仁炒，各二两 生地黄四两，酒洗　　\n上为末，炼蜜丸如椒目大。白滚汤下。\n心者，神明之官也。忧愁思虑则伤心，神明受伤则主不明而十二官危，故健忘怔忡。", "白话": "〔方名〕天王补心丹。〔主治〕主心血不足、神志不宁、津液枯竭、健忘怔忡、大便不利、口舌生疮等证。〔组成·照录〕人参（去芦）、白茯苓（去皮）、玄参（炒）、丹参（炒）、远志（去木，炒）、桔梗各五钱；五味子（烘）、当归身（酒洗）、麦门冬（去心）、天门冬（去心）、柏子仁（炒）、酸枣仁（炒）各二两；生地黄四两（酒洗）。〔方义〕生地、二冬、玄参滋阴生津，归身、丹参养血，枣仁、柏仁、远志、茯苓、人参养心安神，五味子敛心气，桔梗载药上行，为补心安神之名方。〔制法·服法〕上为末，炼蜜为丸，椒目大"}, {"source": "条922｜《绛雪丹书·产后》·加减养荣汤（归脾汤）／养心汤／安神丸", "原文": "《绛雪丹书·产后》：“产妇惊忧劳倦，去血过多，以致心中躁动不宁，谓之怔忡；若惕然而惊，如人将捕之状，谓之惊悸。治此二症，惟唯调和脾胃，补养心血，使之志定神宁、气舒心安而病自愈矣。如分娩后血块未消而患此者，宜服生化汤以补血行血，血旺则惊悸自除，不必加定志安神剂；如块消痛止之后患此症，宜服后药。加减养荣汤内去川芎、麦冬，加木香，即归脾汤。\n川芎一钱 当归二钱 茯苓、枣仁炒黑、人参、麦冬、远志、黄芪、白", "白话": "〔辨证〕产妇受惊、忧愁、劳倦，失血过多，以致心中躁动不宁，叫做怔忡；若突然惊惕，如有人要捕捉他的样子，叫做惊悸。治疗这两证，只须调和脾胃、补养心血，使志定神宁、气舒心安，病自愈。如分娩后血块未消而患此者，宜服生化汤补血行血，血旺则惊悸自除，不必加定志安神之剂；如血块消、腹痛止之后患此证，宜服后列方药。〔方名〕加减养荣汤（内去川芎、麦冬，加木香，即归脾汤）：〔组成·照录〕川芎一钱，当归二钱，茯苓、枣仁（炒黑）、人参、麦冬、远志、黄芪、白术各一钱，陈皮、炙甘草各四分，龙眼肉八分。"}, {"source": "条923｜《绛雪丹书·胎症》·补母寿子方", "原文": "《绛雪丹书·胎症》：“补母寿子方。\n人参二钱，弱甚加倍 白术、当归、熟地各二钱 川芎八分 炙草四分 条芩钱半 苏叶三分 陈皮三分 大枣三枚  \n煎服，内热加黄连五分；如肥人，陈皮去白加黄连五分；脾胃弱常泄泻加莲子十粒，带壳砂仁三分，减地黄；多怒而泻加木香三分；口燥加麦冬一钱；怔忡、惊悸加枣仁、益智仁各一钱，龙眼肉十枚。", "白话": "〔方名〕补母寿子方。〔组成·照录〕人参二钱（弱甚者加倍），白术、当归、熟地各二钱，川芎八分，炙甘草四分，条芩一钱半，苏叶三分，陈皮三分，大枣三枚。〔方义〕八珍益气养血，条芩、苏叶清热安胎，为补母（母体）以寿子（胎儿）之安胎方。〔服法〕水煎服。〔加减〕内热加黄连五分；肥人去陈皮白加黄连五分；脾胃弱常泄泻加莲子十粒、带壳砂仁三分，减地黄；多怒而泻加木香三分；口燥加麦冬一钱；怔忡惊悸加酸枣仁、益智仁各一钱，龙眼肉十枚。"}, {"source": "条924｜《绛雪丹书·产后》·滋荣益气止崩汤", "原文": "《绛雪丹书·产后》：“滋荣益气止崩汤。\n川芎一钱 当归四钱 人参二钱 白术二钱 黄芪一钱 熟地二钱 陈皮四分 升麻四分 白芷四分 荆芥穗四分 炙草四分 黄连三分或四分  \n枣水煎，童便服。汗多加麻黄根一钱，浮小麦一撮；大便不通加肉苁蓉一钱，断不可用大黄；有气不舒加木香末二分；有痰加竹沥、姜汁、贝母；寒嗽加杏仁、桔梗各八分，知母一钱；惊悸加柏子仁一钱，枣仁一钱炒黑；伤食加山楂八分，砂仁五分，断不可用", "白话": "〔方名〕滋荣益气止崩汤。〔组成·照录〕川芎一钱，当归四钱，人参二钱，白术二钱，黄芪一钱，熟地二钱，陈皮四分，升麻四分，白芷四分，荆芥穗四分，炙甘草四分，黄连三分或四分。〔方义〕参、芪、术益气，归、芎、地滋荣养血，升麻、荆芥升举止崩，为产后益气摄血止崩之剂。〔服法〕大枣水煎，以童便送服。〔加减〕汗多加麻黄根一钱、浮小麦一撮；大便不通加肉苁蓉一钱，断不可用大黄；气不舒加木香末二分；有痰加竹沥、姜汁、贝母；寒咳加杏仁、桔梗各八分、知母一钱；惊悸加柏子仁一钱、炒黑枣仁一钱；伤食加山楂"}, {"source": "条925｜《菉竹堂集验方》卷六·治怔忡痰厥方", "原文": "《菉竹堂集验方》卷六：“治怔忡痰厥方。\n腊八日用大雄猪胆一个，将明矾碾细，入胆内，盛满为度，阴干去皮，仍碾细。每钱加飞过朱砂三分和匀，用无根水服三铜钱边即愈。所谓三铜钱边者，即一刀圭之意，而极言其少也。", "白话": "〔方名〕治怔忡痰厥方。〔制法〕腊八日取大雄猪胆一个，将明矾碾细装入胆内，以盛满为度，阴干后去外皮，仍碾成细末。每钱药末加水飞朱砂三分和匀。〔服法〕用无根水送服“三铜钱边”即愈——所谓三铜钱边，即一刀圭之意，极言其量之少。"}, {"source": "条926｜《（痘疹）生民切要》·连翘防风汤", "原文": "《（痘疹）生民切要》：“少阳三焦、胆经，主寒热往来，时或惊悸而发搐，宜连翘防风汤。", "白话": "〔主治〕邪在少阳三焦、胆经，见寒热往来，时或惊悸而发抽搐者，宜用连翘防风汤。"}, {"source": "条927｜《青囊秘诀》下卷·转败汤", "原文": "《青囊秘诀》下卷：“人有久生瘰疬，两项之间，尽已溃烂，串至胸膈之上，无非痰块，亦已头破而腐者，遂至身体发热发寒，肌肉消瘦，饮食少思，自汗盗汗，惊悸恍惚。此等之症，原系难治，然治得法，尚可救也。大约瘰疬初起，以解郁消痰为主，而佐之补虚以消其毒。病久宜以补虚为君，而佐之以解郁消痰。若徒以祛痰败毒为事，而不补气血之虚，鲜有不死矣！方用转败汤。  \n人参一两 当归一两 土炒白术一两 金银花三两 白芍三两 ", "白话": "〔主治〕有人久患瘰疬，颈项两侧尽已溃烂，延串至胸膈之上，无非痰块，有的已破头腐烂，于是身体发热恶寒，肌肉消瘦，饮食少思，自汗盗汗，惊悸恍惚。此等证本属难治，但治法得当尚可救治。大抵瘰疬初起，以解郁消痰为主，佐以补虚以消其毒；病久则宜以补虚为君，佐以解郁消痰。若只知祛痰败毒而不补气血之虚，少有不死者！〔方名〕方用转败汤：〔组成·照录〕人参一两，当归一两，土炒白术一两，金银花三两，白芍三两，柴胡二钱，制半夏五钱，甘草三钱。〔方义〕参、术、归、芍补气血，柴胡疏肝解郁，半夏化痰，金银"}, {"source": "条928｜《医宗说约》卷五·滋阴溃坚汤", "原文": "《医宗说约》卷五：“滋阴溃坚汤。治忧抑所伤，遂生瘰疬，气血不足，形体瘦弱，潮热咳嗽，坚硬肿痛，不分新久，未溃者并效。  \n川芎、当归、白芍、熟地、陈皮、白苓、桔梗、白术、香附各一钱 甘草、海粉、贝母、人参、昆布各五分 升麻、红花各三分  \n姜三片，枣二枚，水煎，食远服。身热加柴胡、黄芩；自汗盗汗去升麻，倍参芪；饮食无味，加藿香、砂仁；食而不化，加山楂、麦芽；胸膈痞闷，加泽泻、木香；咳嗽痰气不清，加", "白话": "〔方名〕滋阴溃坚汤。〔主治〕治忧郁所伤，遂生瘰疬，气血不足，形体瘦弱，潮热咳嗽，坚硬肿痛；不分新久，凡未溃破者都有效。〔组成·照录〕川芎、当归、白芍、熟地、陈皮、白苓、桔梗、白术、香附各一钱；甘草、海粉、贝母、人参、昆布各五分；升麻、红花各三分。〔方义〕四物滋阴养血，参、术、苓、草益气，海粉、昆布、贝母软坚化痰，桔梗、升麻、香附理气散结，与《外科正宗》滋荣散坚汤同法。〔服法〕姜三片、枣二枚，水煎，食远服。〔加减〕身热加柴胡、黄芩；自汗盗汗去升麻、倍人参加黄芪；饮食无味加藿香、"}, {"source": "条929｜《伤寒绪论》卷下·犀角地黄汤／独参汤／归脾汤", "原文": "《伤寒绪论》卷下：“表邪失汗伤阴，身大热，善忘时惊悸，干呕，错语呻吟，不得眠，犀角地黄汤。伤寒坏病久不愈，常不得眠，或心脾气血素亏，而惊悸不宁，不得眠，诸药不效者，大剂独参汤或归脾汤，用送下养正丹。", "白话": "〔主治一〕表邪因失于发汗而伤阴，身大热，善忘、时发惊悸，干呕，言语错乱呻吟，不得眠——用犀角地黄汤。〔主治二〕伤寒坏病久不愈，经常不得眠；或心脾气血素亏，而惊悸不宁、不得眠，诸药无效者——用大剂独参汤或归脾汤送下养正丹。"}, {"source": "条930｜《病机沙篆》卷下·导痰二陈加味", "原文": "《病机沙篆》卷下：“大凡怔忡失志，惊悸健忘，心风不寐，皆系胆涎沃心，或因心气不足，反以凉心大过，心火益微，痰涎愈盛，惟唯以理痰顺气为第一义，导痰、二陈加枳壳、南星，菖蒲。", "白话": "〔病机〕大凡怔忡失志、惊悸健忘、心风不寐，都是胆中痰涎浸渍于心所致；或因心气不足，反而用寒凉清心太过，心火愈加微弱，痰涎愈加旺盛。只以理痰顺气为第一要义——用导痰汤、二陈汤加枳壳、南星、菖蒲。"}, {"source": "条931｜《济世神验良方·女科门》·神应丹", "原文": "《济世神验良方·女科门》：“神应丹。治经不行有实热，五心烦热，口燥咽干，心忪额赤，胸膈不利，咳唾稠痰。  \n大黄八两，醋二碗，煮干晒 血竭、桃仁、红花各五钱\n酒糊丸如桐子大，朱砂为衣，每服七十丸。", "白话": "〔方名〕神应丹。〔主治〕治经闭不行而有实热：五心烦热，口燥咽干，心忪（心悸）额赤，胸膈不利，咳唾稠痰。〔组成·照录〕大黄八两（用醋二碗煮干晒干），血竭、桃仁、红花各五钱。〔方义〕大黄醋制攻下瘀热，桃仁、红花、血竭活血通经，为泻热逐瘀通经之丹。〔制法·服法〕酒糊为丸，梧桐子大，朱砂为衣；每服七十丸。"}, {"source": "条932｜《女科经纶》卷七·伏龙肝散", "原文": "《女科经纶》卷七：“武叔卿曰：伏龙肝散，治劳伤冲任脉虚，非时崩下，或如豆汁，或成血片，或五色相杂，或赤白相兼，脐腹冷痛，经久未止，令人黄瘦，口干，饮食减少，四肢无力，虚烦惊悸。", "白话": "〔引文〕武叔卿说：伏龙肝散治劳伤冲任、脉气虚衰，非时血崩而下：或下如豆汁，或成血片，或五色相杂，或赤白相兼，脐腹冷痛，经久不止，使人面色发黄消瘦、口干、饮食减少、四肢无力、虚烦惊悸。"}, {"source": "条933｜《履霜集》卷二·产后中风（十全大补汤加减）", "原文": "《履霜集》卷二：“夫产后气血内虚，外为风寒湿乘虚而入皮肤经络，则毛孔闭塞，阳气郁结，九窍不利，以致头疼身疼，发热恶寒。若伤于风，重感于寒，则四肢筋脉拘挛，无汗而恶寒。若伤于风，重感于湿则四肢筋脉软弱，有汗而发热。若风入于脏，则心神不宁，恍惚惊悸，随所伤而为病。开目为阳风，闭目为阴风。产后得此，乃气血极虚之危症也，急以十全大补汤，大补气血，稍佐以祛风之剂。无汗恶寒，加荆芥穗、防风各一钱。有汗发热，加", "白话": "〔病机〕产后气血内虚，外在风寒湿邪乘虚而入皮肤经络，则毛孔闭塞，阳气郁结，九窍不利，以致头痛身痛、发热恶寒。若伤于风又重感于寒，则四肢筋脉拘挛、无汗而恶寒；若伤于风又重感于湿，则四肢筋脉软弱、有汗而发热。若风邪入于内脏，则心神不宁、恍惚惊悸，随所伤之处而为病。目开者为阳风，目闭者为阴风。产后得此，是气血极虚之危重证。〔治法〕急用十全大补汤大补气血，稍佐祛风之剂。〔加减〕无汗恶寒，加荆芥穗、防风各一钱；有汗发热，加荆芥穗、软防风各五分；痰盛加半夏一钱；心悸加白茯苓、远志各一钱。"}, {"source": "条934｜《女科仙方》卷三·生化汤加定志", "原文": "《女科仙方》卷三：“怔忡惊悸，生化汤加以定志。", "白话": "〔主治〕产后怔忡惊悸，用生化汤加定志（安神定志之品）治疗。"}, {"source": "条935｜《傅氏杂方·附录》·第二方（治外感方）", "原文": "《傅氏杂方·附录》：“第二方治外感也，或伤风伤寒，或咳嗽，或发热，或不发热，或头痛，或鼻塞，或痰多，或惊悸，或角弓反张，皆以此方通治之，无不神效，方用：\n柴胡七分 甘草三分 桔梗五分 半夏三分 黄芩三分 白芍二钱 当归五分 茯苓五分  \n水煎服。头痛者，加蔓荆子三分。心痛手不可按者，乃实火也，加栀子一钱；按之不痛者，乃虚火也，加甘草八分、管仲五分、广木香三分、乳香一分。胁痛者，加白芍三钱。腹痛者，", "白话": "〔主治〕第二方治外感病：或伤风伤寒，或咳嗽，或发热，或不发热，或头痛，或鼻塞，或痰多，或惊悸，或角弓反张——都可用此方通治，无不神效。〔组成·照录〕柴胡七分，甘草三分，桔梗五分，半夏三分，黄芩三分，白芍二钱，当归五分，茯苓五分。〔方义〕柴胡、黄芩和解表里，桔梗、半夏化痰，归、芍养血，苓、草健脾，为通治外感兼惊悸之方。〔服法〕水煎服。〔加减〕头痛加蔓荆子三分；心痛手不可按者为实火，加栀子一钱；按之不痛者为虚火，加甘草八分、管仲五分、广木香三分、乳香一分；胁痛加白芍三钱；腹痛按之"}, {"source": "条936｜《胎产指南》卷七·生化汤", "原文": "《胎产指南》卷七：“如分娩后，血块未消，宜服生化汤，补血行块，血旺则怔忡惊悸自平，不必加定安心神之剂。", "白话": "〔治法〕如分娩后血块未消，宜服生化汤补血行块；血旺之后怔忡惊悸自然平复，不必另加安神定志之剂。"}, {"source": "条937｜《辨证奇闻》卷四·制忡汤", "原文": "《辨证奇闻》卷四：“怔忡，遇拂情，听逆言，便觉心气怦怦，不能自主，似烦非烦，似晕非晕，人谓心虚。然心虚由肝虚，肝虚肺必旺，以心弱不能制肺也。肺无火炼，必制木太过，肝更不能生心，心气益困。故补心必补肝，补肝尤宜制肺。然肺娇脏，寒凉制肺，必伤脾胃，脾胃受寒，不能运化水谷，肝何所资？肾又何益？所以肺不宜制而宜养，况肺愈养愈安，愈制愈动，用制忡汤。\n人参、白术、麦冬五钱 白芍、当归、枣仁一两 北味一钱 贝", "白话": "〔辨证〕怔忡之病：遇到不顺心之事、听到逆耳之言，便觉心气怦怦跳动，不能自主，似烦非烦，似晕非晕——人们说是心虚。然而心虚源于肝虚：肝虚则肺气必旺，因为心弱不能制约肺；肺无心火煎炼，必然制约肝木太过，肝更不能生心，心气愈加困惫。所以补心必须补肝，补肝更宜制约肺。但肺为娇脏，用寒凉制肺必伤脾胃；脾胃受寒不能运化水谷，肝靠什么滋养？肾又有什么益处？所以肺不宜克制而宜养护——况且肺愈养愈安，愈制愈动。〔方名〕用制忡汤：〔组成·照录〕人参、白术、麦冬五钱，白芍、当归、枣仁一两，北五味一"}, {"source": "条938｜《辨证录》卷六·清胃生髓丹", "原文": "《辨证录》卷六：“胃火上冲于心，心中烦闷，怔忡惊悸，久则成痿，两足无力，不能动履，此总属胃火之盛，非心火之旺也。方用清胃生髓丹：  \n玄参一两 麦冬五钱 甘菊花五钱 熟地二两 北五味二钱 沙参五钱  \n水煎服。十剂即可行步，二十剂怔忡惊悸之病除，又十剂烦闷痿弱之症去，再服十剂痊全愈。", "白话": "〔辨证〕胃火上冲于心，心中烦闷，怔忡惊悸，日久则成痿证，两足无力，不能行走——这总属胃火炽盛，而非心火之旺。〔方名〕方用清胃生髓丹：〔组成·照录〕玄参一两，麦冬五钱，甘菊花五钱，熟地二两，北五味二钱，沙参五钱。〔方义〕玄参、菊花清胃热，二冬、沙参、熟地滋阴生髓，五味子敛阴，为清胃滋阴之剂。〔服法〕水煎服：十剂即可行步，二十剂怔忡惊悸除，再十剂烦闷痿弱去，续服十剂痊愈。"}, {"source": "条939｜《辨证奇闻》卷八·滋肝饮", "原文": "《辨证奇闻》卷八：“血虚，面无色泽，肌肉焦枯，大肠干燥，怔忡健忘，饮食少思，羸弱不堪，夜热无汗，人谓血痨，谁知肝燥生火乎。肝属木，木中火盛每自焚。然肝生火，由于肾水不足，木无水润，则木亦为火。非失血吐于外，即耗血燥于内，肝燥肝火生。夫木中有水，则肝生心，木中有火，肝焚心。故火在心中，可取给于肝，火在肝中，不可取给于心者，以肝自顾不暇耳。宜先补肾水。用滋肝饮：\n玄参、白芍一两 丹皮、沙参、当归、麦冬", "白话": "〔辨证〕血虚之人，面色无光泽，肌肉焦枯，大肠干燥，怔忡健忘，饮食少思，羸弱不堪，夜间发热而无汗——人们说是血痨，谁知是肝燥生火呢？肝属木，木中火盛每致自焚；然而肝之所以生火，是因肾水不足，木无水润，木也就成了火。不是失血吐出于外，就是耗血燥于内，肝燥而肝火内生。木中有水，则肝能生心；木中有火，则肝反焚心。所以火在心中，可以向肝索取给养；火在肝中，却不能向心索取给养，因为肝已自顾不暇。宜先补肾水。〔方名〕用滋肝饮：〔组成·照录〕玄参、白芍一两，丹皮、沙参、当归、麦冬五钱，甘菊、"}, {"source": "条940｜《辨证奇闻》卷九·坎离两补汤", "原文": "《辨证奇闻》卷九：“怔忡善忘，口淡舌燥，多汗，四肢疲软，发热，小便白浊，脉虚大而数，人谓内伤，谁知思虑过度乎。君火，心火也；相火，膻中火也。膻中，手厥阴经，性属阴，主热，古以“厥阳”名，以其火不可遏也。越人云忧愁思虑则伤心。心气伤，心血自耗，每欲寄权于心包，心包欺心弱，即夺权自恣。法宜以水济火。然火势炽，用寒凉心气益虚，激动焦焚之害。不如补心气，大滋肾水，则心火宁，心包火自安。用坎离两补汤：\n人参", "白话": "〔辨证〕怔忡善忘，口淡舌燥，多汗，四肢疲软，发热，小便白浊，脉虚大而数——人们说是内伤，谁知是思虑过度呢？君火是心火，相火是膻中之火；膻中属手厥阴经，性属阴而主热，古称“厥阳”，因其火不可遏止。扁鹊（越人）说：忧愁思虑则伤心。心气受伤，心血自耗，每每想把权柄寄托于心包；心包欺心弱，便夺权放纵。治法宜以水济火；但火势炽盛时用寒凉，心气更虚，反有焦焚之害。不如补心气、大滋肾水，则心火自宁，心包之火自安。〔方名〕用坎离两补汤：〔组成·照录〕人参、生地、麦冬、山药五钱，熟地一两，菟丝"}, {"source": "条941｜《冯氏锦囊秘录·杂症大小合参》·益营汤", "原文": "《冯氏锦囊秘录·杂症大小合参》：“益营汤。治思虑耗伤，心血怔忡恍惚。  \n当归酒浸、黄芪、小草、酸枣仁去壳炒、柏子仁炒、麦冬去心、茯神、白芍、紫石英各一两，炒 木香不见火，五钱 人参五钱 甘草炙，五钱  \n每服四钱，姜枣水煎服。", "白话": "〔方名〕益营汤。〔主治〕治思虑耗伤心血，怔忡恍惚。〔组成·照录〕当归（酒浸）、黄芪、小草、酸枣仁（去壳炒）、柏子仁（炒）、麦冬（去心）、茯神、白芍、紫石英（炒）各一两；木香（不见火）五钱；人参五钱；甘草（炙）五钱。〔方义〕参、芪、归、芍益气养营，枣仁、柏仁、麦冬、茯神、紫石英养心镇心，佐木香醒脾，为益营安神之剂。〔服法〕每服四钱，姜枣水煎服。"}, {"source": "条942｜《医通祖方·益元散》·辰砂六一散", "原文": "《医通祖方·益元散》：“辰砂六一散。治暑月惊悸，多汗，小便涩痛。益元散一料，加辰砂一钱飞。", "白话": "〔方名〕辰砂六一散。〔主治〕治暑月惊悸、多汗、小便涩痛。〔组成·照录〕益元散一料，加水飞辰砂一钱。〔方义〕六一散（滑石、甘草）清暑利湿，加辰砂镇心安神，治暑热扰心之惊悸。"}, {"source": "条943｜《济世全书·震集》·补中益气汤", "原文": "《济世全书·震集》：“补中益气汤。治中气不足，肢体倦怠，口干发热，或饮食无味，劳倦身热，脉洪大而虚；或头痛，恶寒，自汗，或气高而喘，身热而烦；或脉微细软弱，自汗，体倦少食，或中气虚弱而不能摄血，或饮食劳倦而患疟痢，或疟痢因脾胃虚而不能愈；或元气虚弱，感冒风寒不胜发表，宜用此代之；或入房而后感冒，或感冒而后入房，亦用此汤急加附子；或泻痢腹痛，急用附子理中汤。\n嫩黄芪蜜水炒，一钱半 楝参一钱 甘草炙，", "白话": "〔方名〕补中益气汤。〔主治〕治中气不足、肢体倦怠、口干发热，或饮食无味、劳倦身热、脉洪大而虚；或头痛恶寒自汗；或气高而喘、身热而烦；或脉微细软弱、自汗、体倦少食；或中气虚弱不能摄血；或饮食劳倦而患疟痢；或疟痢因脾胃虚而不能愈；或元气虚弱、感冒风寒不胜发散，宜用此方代之；或房事后感冒，或感冒后房事，也用此汤急加附子；或泻痢腹痛，急用附子理中汤。〔组成·照录〕嫩黄芪（蜜水炒）一钱半，楝参一钱，甘草（炙）一钱，陈皮二钱，白术（去芦，微炒）一钱，当归身（酒洗）二钱，柴胡五分，升麻五分"}, {"source": "条944｜《济世全书·离集》·芎归调血饮", "原文": "《济世全书·离集》：“芎归调血饮主方。治产后诸病。\n当归身酒洗 川芎 白芍火煨，切片，酒炒熟用 怀生地黄酒蒸黑 白术去油芦，土炒 白茯苓去皮 陈皮 香附童便炒 甘草炒，初产临服，加童便一钟，好酒半钟同服，是能行瘀血，退热如神  \n上锉作剂，生姜一片，枣一枚，水煎温服。看病加减于后。一产后惊悸、怔忡，加远志、麦门冬、酸枣仁。", "白话": "〔方名〕芎归调血饮（主方）。〔主治〕治产后诸病。〔组成·照录〕当归身（酒洗），川芎，白芍（火煨，切片，酒炒熟用），怀生地黄（酒蒸黑），白术（去油芦，土炒），白茯苓（去皮），陈皮，香附（童便炒），甘草（炒）；初产临服时加童便一盅、好酒半盅同服，能行瘀血，退热如神。〔方义〕芎、归、芍、地调血养血，术、苓、陈、草健脾理气，香附调气和血，为产后调血之主方。〔服法〕上药切碎作剂，生姜一片、大枣一枚，水煎温服；随病加减如下。〔加减〕一、产后惊悸怔忡，加远志、麦门冬、酸枣仁。"}, {"source": "条945｜《经验丹方汇编》·理中汤（阴黄虚黄）", "原文": "《经验丹方汇编》：“阴疟二疸肢冷自汗、泄利便清、脉沉迟者是阴黄；耳鸣口淡、怔忡微热、四肢无力、嗜卧、脉沉细、寒热泄白者是虚黄。皆以理中汤治之。  \n人参、白术各三钱半 甘草炙、干姜炮，各一两  空心煎服。", "白话": "〔辨证〕阴疟与两种疸证中：肢冷自汗、泄利便清、脉沉迟者是阴黄；耳鸣口淡、怔忡微热、四肢无力、嗜卧、脉沉细、寒热交作而小便泄白者是虚黄。都用理中汤治疗。〔组成·照录〕人参、白术各三钱半，甘草（炙）、干姜（炮）各一两。〔方义〕理中汤温中健脾，脾阳得振则寒湿去、怔忡止。〔服法〕空腹煎服。"}, {"source": "条946｜《良朋汇集经验神方》卷六·紫苏饮", "原文": "《良朋汇集经验神方》卷六：“紫苏饮。治妊娠胎上逼、胀满疼痛，谓之子悬。兼治临产惊悸，气结连日不下。  \n紫苏一两 当归、甘草各二钱半 人参、川芎、大腹皮、陈皮、白芍药各半两  \n上㕮咀，每服半两，水一盏半、姜四片、葱白七寸，去渣空心温服。", "白话": "〔方名〕紫苏饮。〔主治〕治妊娠胎气上逼、胸腹胀满疼痛，叫做子悬；兼治临产惊悸、气机结滞而胎儿连日不下。〔组成·照录〕紫苏一两；当归、甘草各二钱半；人参、川芎、大腹皮、陈皮、白芍药各半两。〔方义〕紫苏、大腹皮、陈皮理气宽中，归、芎、芍养血安胎，参、草益气，为顺气安胎之剂。〔服法〕上药切碎，每服半两，水一盏半加姜四片、葱白七寸，去渣空腹温服。"}, {"source": "条947｜《奇方类编》卷下·安神定惊方（原稿未标方名）", "原文": "《奇方类编》卷下：“治神短烦躁不安，夜卧不宁，惊悸怔忡，恍惚健忘。  \n川连八两，姜炒 归身三两 生地三两 生草一两 玄参四两，酒洗 枣仁二两，炒黑 白茯神四两 远志肉二两，甘草水泡 琥珀一两 犀角一两 辰砂一两，为衣  \n莲子、灯心煎汤为丸，梧子大。每服一钱，空心白滚水送下。", "白话": "〔主治〕治神短、烦躁不安，夜卧不宁，惊悸怔忡，恍惚健忘（原稿未标方名）。〔组成·照录〕川连八两（姜炒），当归身三两，生地三两，生甘草一两，玄参四两（酒洗），酸枣仁二两（炒黑），白茯神四两，远志肉二两（甘草水泡），琥珀一两，犀角一两，辰砂一两（为衣）。〔方义〕川连、犀角清心凉血，生地、玄参、归身滋阴养血，枣仁、茯神、远志、琥珀、辰砂安神定惊，为清心养血、安神定志之丸。〔制法·服法〕以莲子、灯心煎汤为丸，梧桐子大；每服一钱，空腹白开水送下。"}, {"source": "条948｜《广瘟疫论》卷三·六味合生脉（亡阴）", "原文": "《广瘟疫论》卷三：“屡经汗、下，渴而舌上无苔，胸腹无满痛，心悸而烦，脉虚细，或浮散、或涩，亡阴也，六味合生脉为主。", "白话": "〔辨证〕屡经发汗、攻下之后，口渴而舌上无苔，胸腹无胀满疼痛，心悸而烦，脉虚细，或浮散，或涩——这是亡阴之证。〔治法〕以六味地黄丸合生脉散为主。"}, {"source": "条949｜《广瘟疫论》卷三·生脉散加枣仁、天王补心丹", "原文": "《广瘟疫论》卷三：“至若屡经汗、下、清理，二便已清利，胸腹无阻滞，六脉虚散、结、代、微弱而谵语者，阴阳两虚，神无所倚也。虚在上焦，必心悸、神倦，生脉散加枣仁、天王补心丹。", "白话": "〔辨证〕至于屡经汗、下、清里之后，二便已通利，胸腹无阻滞，而六脉虚散、结、代、微弱并见谵语者，是阴阳两虚、心神无所依附。虚在上焦者，必见心悸、神倦。〔治法〕用生脉散加酸枣仁、天王补心丹。"}, {"source": "条950｜《顾松园医镜》卷十一·天王补心", "原文": "《顾松园医镜》卷十一：“心跳善惊，虚烦无寐，则用天王补心。", "白话": "〔主治〕心跳易惊、虚烦不寐者，用天王补心丹。"}, {"source": "条951｜《身经通考·身经答问十》·黄连泻心汤／生犀散", "原文": "《身经通考·身经答问十》：“心实则烦热，黄连泻心汤；虚则惊悸，生犀散。", "白话": "〔辨证〕心实证见烦热，用黄连泻心汤；心虚证见惊悸，用生犀散。"}, {"source": "条952｜《医家心法·怔忡》·归脾汤加减", "原文": "《医家心法·怔忡》：“怔忡，心血少也。其源起于肾水不足，不能上升，以致心火不能下降。大剂归脾汤，去木香，加麦冬、五味、枸杞、白芍，吞都气丸。如怔忡而实，挟夹包络一种有余之火，兼痰者，则加生地、黄连、川贝之类清之。", "白话": "〔病机〕怔忡是心血少；其根源起于肾水不足、不能上升，以致心火不能下降。〔治法〕用大剂归脾汤，去木香，加麦冬、五味子、枸杞、白芍，送服都气丸。〔加减〕如怔忡而属实，兼夹心包络一种有余之火并有痰者，则加生地、黄连、川贝之类清之。"}, {"source": "条953｜《灵验良方汇编》卷上·安胎饮", "原文": "《灵验良方汇编》卷上：“安胎饮。治孕妇胎气不安，或腹痛、腰痛，或饮食不羡等症。又治孕妇屡产，生子无气，或生而不寿，或妊而数堕者，俱照前症，按月服之。  \n人参二钱 当归、白术、熟地同 川芎八分 甘草四分 紫苏、陈皮同 条芩一钱  \n加枣煎。如泄泻，减熟地加莲肉十粒、壳砂数分。如渴，加麦冬一钱。如惊悸，加枣仁、益智仁各一钱。如怒气，磨木香三分。", "白话": "〔方名〕安胎饮。〔主治〕治孕妇胎气不安，或腹痛、腰痛，或饮食无味等证；又治孕妇屡次生产、生子无气，或生而不寿，或怀孕屡次堕胎者，都照前证按月服之。〔组成·照录〕人参二钱；当归、白术、熟地（同量）；川芎八分；甘草四分；紫苏、陈皮（同量）；条芩一钱。〔方义〕四君合四物去芍药益气养血，条芩、紫苏清热安胎，为安胎常用之剂。〔服法〕加枣煎服。〔加减〕泄泻减熟地，加莲肉十粒、带壳砂仁数分；口渴加麦冬一钱；惊悸加酸枣仁、益智仁各一钱；怒气磨木香三分。"}, {"source": "条954｜《灵验良方汇编》卷上·济坤大造丸", "原文": "《灵验良方汇编》卷上：“济坤大造丸。益气血，温子宫，种子神方也男亦可服  \n紫河车儿胞也，取诸壮妇无病者，水洗血尽，用砂罐盛酒一碗，先格蔑数片，置胞不着酒，蒸熟 当归二两 人参、山药、杜仲、天冬、麦冬各一两 熟地二两 黄柏八钱，酒炒  \n或加五味子五钱。行经腹痛，加牛膝一两酒浸，炒、玄明五钱。脾弱，加白术一两，或再加莲肉二两二味兼治泻。潮热或汗，加黄芪、知母各一两、地骨皮八钱。血少惊悸，加枣仁一两", "白话": "〔方名〕济坤大造丸。〔功用〕益气血，温子宫，是种子（助孕）神方（男子也可服）。〔组成·照录〕紫河车（即儿胞，取壮健无病妇人者，水洗去尽血污，用砂罐盛酒一碗，先以格蔑数片垫置，使胞不着酒，蒸熟）；当归二两；人参、山药、杜仲、天冬、麦冬各一两；熟地二两；黄柏八钱（酒炒）。〔方义〕紫河车大补精血，参、药、二冬、归、地益气养血滋阴，杜仲补肾，黄柏坚阴，为温养子宫、益气血之种子方。〔制法·服法〕上各为末，同紫河车捣匀为丸。〔加减〕或加五味子五钱；行经腹痛加牛膝（酒浸炒）一两、玄明五钱；"}, {"source": "条955｜《胎产心法》卷下·人参丸", "原文": "《胎产心法》卷下：“人参丸。治产后大虚心悸，志意不安，恍惚恐畏，虚烦不眠少气。  \n人参、茯苓、麦冬去心、薯蓣各二两 泽泻、菖蒲、干姜、桂心、甘草各一两  \n共为末，白蜜和枣膏丸如梧子大。空心酒服二三十丸，早晚服。", "白话": "〔方名〕人参丸。〔主治〕治产后大虚心悸，意志不安，恍惚恐惧，虚烦不眠，短气。〔组成·照录〕人参、茯苓、麦冬（去心）、薯蓣各二两；泽泻、菖蒲、干姜、桂心、甘草各一两。〔方义〕参、苓、薯蓣、甘草益气健脾，麦冬养阴，菖蒲安神，干姜、桂心温阳，泽泻利浊，为产后补虚安神之丸。〔制法·服法〕共为末，白蜜与枣膏为丸，梧桐子大；空腹酒服二三十丸，早晚各服。"}, {"source": "条956｜《胎产心法》卷下·加味生脉散", "原文": "《胎产心法》卷下：“加味生脉散。治产后去血太多，心血虚弱不能上荣于舌，语言不清，含糊蹇涩。  \n人参、麦冬去心、归身、生地、炙草、石菖蒲各一钱 五味子十三粒，捶碎  \n獖猪心一个，劈开，水二盏，煎至一盏半，去心，入药煎七分，食后服。此方治怔忡甚效。", "白话": "〔方名〕加味生脉散。〔主治〕治产后失血过多，心血虚弱不能上荣于舌，语言不清、含糊蹇涩。〔组成·照录〕人参、麦冬（去心）、当归身、生地、炙甘草、石菖蒲各一钱；五味子十三粒（捶碎）。〔方义〕生脉散（参、麦、味）益气生津，加归、地养血，菖蒲开窍，为产后养心开窍之剂。〔服法〕用阉割公猪心一个劈开，水二盏煎至一盏半，去猪心，加入药再煎取七分，食后服。此方治怔忡甚效。"}, {"source": "条957｜《胎产心法》卷下·尊生升举大补汤", "原文": "《胎产心法》卷下：“尊生升举大补汤。治产后血块痛止崩证。  \n人参、当归、白术土炒，各二钱 川芎、麦冬去心、黄芪蜜炙，各一钱 熟地三钱、 陈皮、炙草、白芷、荆芥穗炒黑、升麻、血余灰各四分  \n枣二枚，水煎服。汗多，加麻黄根、浮麦。便难，加酒洗苁蓉一钱。痰，加去心贝母六分。咳嗽，加桔梗、去皮尖杏仁各一钱。不寐惊悸，加炒枣仁、柏子仁各一钱。本方少加黄连三分以坠火，亦妙。凡遇崩证，有如此等余病，大忌峻利", "白话": "〔方名〕尊生升举大补汤。〔主治〕治产后血块痛止后之崩证。〔组成·照录〕人参、当归、白术（土炒）各二钱；川芎、麦冬（去心）、黄芪（蜜炙）各一钱；熟地三钱；陈皮、炙甘草、白芷、荆芥穗（炒黑）、升麻、血余灰各四分。〔方义〕参、芪、术、归、地益气养血摄血，升麻、荆芥升举，血余灰止血，为产后升举固崩之剂。〔服法〕大枣二枚，水煎服。〔加减〕汗多加麻黄根、浮小麦；大便难加酒洗肉苁蓉一钱；有痰加去心贝母六分；咳嗽加桔梗、去皮尖杏仁各一钱；不寐惊悸加炒酸枣仁、柏子仁各一钱；本方稍加黄连三分以降"}, {"source": "条958｜《不居集·上集》·二阴煎", "原文": "《不居集·上集》：“若火在心肾而惊悸失志者，宜二阴煎。", "白话": "〔主治〕若火在心肾而见惊悸、失志者，宜用二阴煎。"}, {"source": "条959｜《不居集·上集》·资成汤", "原文": "《不居集·上集》：“资成汤。治虚劳遗精盗汗，食少泄泻，血不归经，女子崩漏不止，虚劳不任芪、木、归、地者，此方主之。  \n人参、白芍、扁豆、山药、茯神各一钱 丹参八分 橘红六分 甘草五分 莲肉一钱五分 檀香三分  \n用雄健无病猪肚一具，酒洗磨净，取清汤煎药，或为丸亦可。虚热者，加丹皮、地骨皮。惊恐怔忡，不眠多汗者，加枣仁。火铄肺金，干枯多嗽者，加百合。便血失血者，加地榆、续断。小水不利者，加车前子。", "白话": "〔方名〕资成汤。〔主治〕治虚劳遗精盗汗，食少泄泻，血不归经，女子崩漏不止；凡虚劳而不能承受黄芪、白术、当归、地黄等呆补者，此方主治。〔组成·照录〕人参、白芍、扁豆、山药、茯神各一钱；丹参八分；橘红六分；甘草五分；莲肉一钱五分；檀香三分。〔方义〕参、药、扁豆、莲肉、甘草健脾益气，芍、丹参和血，茯神安神，佐檀香、橘红理气醒脾，补而不滞。〔服法〕用雄健无病猪肚一具，酒洗磨净，取清汤煎药；或为丸亦可。〔加减〕虚热者加丹皮、地骨皮；惊恐怔忡、不眠多汗者加酸枣仁；火铄肺金、干咳多嗽者加百"}, {"source": "条960｜《不居集·上集》·朱砂消痰饮", "原文": "《不居集·上集》：“或迷心窍，心痛惊悸，怔忡恍惚，梦寐奇怪，妄言见鬼，巅颠狂痫喑。朱砂消痰饮。", "白话": "〔主治〕或痰迷心窍，见心痛、惊悸、怔忡恍惚，梦寐怪异，妄言见鬼，癫狂、痫证、失音诸证——用朱砂消痰饮。"}, {"source": "条961｜《不居集·上集》·寿脾煎、七福饮", "原文": "《不居集·上集》：“若儒生蹇厄，思结枯肠，及任劳任怨，心脾受伤，以致怔忡健忘，倦怠少食，渐至消瘦，或为膈噎呕吐者，宜寿脾煎，七福饮。", "白话": "〔主治〕若读书人遭遇困厄、思虑过度以致肠枯，以及任劳任怨、心脾受伤，以致怔忡健忘、倦怠少食、渐至消瘦，或成膈噎呕吐者——宜用寿脾煎、七福饮。"}, {"source": "条962｜《不居集·上集》·温胃饮、神香散／温脾汤、寿脾煎", "原文": "《不居集·上集》：“若忧郁伤脾，而吞酸呕恶者，宜温胃饮、神香散。若忧郁伤脾肺，而困倦怔忡，倦怠食少者，宜温脾汤、寿脾煎。", "白话": "〔主治〕若忧郁伤脾而吞酸呕恶者，宜用温胃饮、神香散；若忧郁伤脾肺而困倦怔忡、倦怠食少者，宜用温脾汤、寿脾煎。"}, {"source": "条963｜《不居集·上集》·大菟丝子丸（病机）", "原文": "《不居集·上集》：“肾气虚损，真阴中阳气不足，不能固摄，小便频多，水不济火，心忡气短，故多盗汗。大菟丝子丸。", "白话": "〔病机〕肾气虚损，真阴之中阳气不足，不能固摄，故小便频数；肾水不能上济心火，故心忡气短，因而多盗汗。〔方名〕用大菟丝子丸。"}, {"source": "条964｜《不居集·上集》·大菟丝子丸（方）", "原文": "《不居集·上集》：“大菟丝子丸。治肾气虚损，五劳七伤，脚膝酸疼，面色痿黄黧黑，目眩耳鸣，心忡气短，时有盗汗，小便滑数等症。  \n菟丝子酒制、鹿茸酥炙、肉桂、石龙肉去土、附子炮、泽泻各一两 熟地、牛膝酒浸一宿，焙干、山萸肉、杜仲、茯苓、肉苁蓉酒浸，切焙、续断、石斛、防风、补骨脂酒炒、川芎、五味子、桑螵蛸、覆盆子各五钱  \n上为末，酒煮面糊丸，如桐子大。每服三五十丸，空心，盐汤、温酒任下。", "白话": "〔方名〕大菟丝子丸。〔主治〕治肾气虚损、五劳七伤，脚膝酸疼，面色萎黄黧黑，目眩耳鸣，心忡气短，时有盗汗，小便滑数等证。〔组成·照录〕菟丝子（酒制）、鹿茸（酥炙）、肉桂、石龙肉（去土）、附子（炮）、泽泻各一两；熟地、牛膝（酒浸一宿，焙干）、山萸肉、杜仲、茯苓、肉苁蓉（酒浸，切焙）、续断、石斛、防风、补骨脂（酒炒）、川芎、五味子、桑螵蛸、覆盆子各五钱。〔方义〕菟丝子、鹿茸、苁蓉、补骨脂、杜仲、牛膝、山萸、覆盆子、桑螵蛸温肾固精，桂、附温阳，熟地、石斛滋阴，为温补肾气、固摄下元之丸"}, {"source": "条965｜《不居集·上集》·十四友丸", "原文": "《不居集·上集》：“十四友丸。治惊悸怔忡。  \n人参、黄芪、当归、生地、远志、茯神、枣仁炒、茯苓、阿胶、龙脑、紫石英、薄荷、朱砂各一两  \n上为末，炼蜜丸桐子大，每服五七十丸。", "白话": "〔方名〕十四友丸。〔主治〕治惊悸怔忡。〔组成·照录〕人参、黄芪、当归、生地、远志、茯神、酸枣仁（炒）、茯苓、阿胶、龙脑、紫石英、薄荷、朱砂各一两。〔方义〕参、芪、归、地、阿胶益气养血，远志、茯神、枣仁、朱砂、紫石英安神镇心，龙脑、薄荷芳香开窍，为养心安神之丸。〔制法·服法〕上为末，炼蜜为丸，梧桐子大；每服五七十丸。"}, {"source": "条966｜《不居集·上集》·资成汤（劳伤心脾）", "原文": "《不居集·上集》：“劳伤心脾，思虑太过，则惊悸怔忡，气虚精陷，而不成寐者，宜资成汤。", "白话": "〔主治〕劳伤心脾，思虑太过，以致惊悸怔忡、气虚精气下陷而不成寐者，宜用资成汤。"}, {"source": "条967｜《不居集·上集》·温胆汤", "原文": "《不居集·上集》：“温胆汤。治气郁生涎，梦寐不宁，怔忡惊悸，心虚胆怯，变生诸症。  \n半夏汤泡、枳实、竹茹各一两 陈皮一两五钱 茯苓七钱 炙甘草四钱  \n每服五钱，生姜七片，枣一枚，水一钟半，煎七分，食远温服。—方加人参、柏子仁为丸，朱砂为衣。", "白话": "〔方名〕温胆汤。〔主治〕治气郁生涎，梦寐不宁，怔忡惊悸，心虚胆怯，变生诸证。〔组成·照录〕半夏（汤泡）、枳实、竹茹各一两；陈皮一两五钱；茯苓七钱；炙甘草四钱。〔方义〕半夏、陈皮、茯苓、甘草（二陈）化痰，枳实、竹茹理气清热，为理气化痰、温胆和胃之名方。〔服法〕每服五钱，生姜七片、大枣一枚，水一钟半煎取七分，食远温服。另一方加人参、柏子仁为丸，朱砂为衣。"}, {"source": "条968｜《不居集·上集》·宁志丸", "原文": "《不居集·上集》：“宁志丸。治怔忡惊悸，癫痫。　　\n人参、枣仁酒浸、茯苓、柏子仁、当归、远志酒浸、茯神、石菖蒲、琥珀各五钱 乳香、朱砂各三钱　　\n上为末，炼蜜丸桐子大，每服三五十丸，食后，枣汤下。", "白话": "〔方名〕宁志丸。〔主治〕治怔忡惊悸、癫痫。〔组成·照录〕人参、酸枣仁（酒浸）、茯苓、柏子仁、当归、远志（酒浸）、茯神、石菖蒲、琥珀各五钱；乳香、朱砂各三钱。〔方义〕参、归、苓、枣仁、柏仁养心安神，远志、菖蒲、琥珀、朱砂开窍镇心，乳香行气活血，为宁心定志之丸。〔制法·服法〕上为末，炼蜜为丸，梧桐子大；每服三五十丸，食后枣汤送下。"}, {"source": "条969｜《不居集·上集》·理脾益营汤／古方安神丸", "原文": "《不居集·上集》：“心虚火盛，烦热内热，怔忡不寐者，宜理脾益营汤，或古方安神丸。", "白话": "〔主治〕心虚火盛，烦热内热，怔忡不寐者，宜用理脾益营汤，或古方安神丸。"}, {"source": "条970｜《不居集·上集》·澄按（虚损惊悸）", "原文": "《不居集·上集》：“澄按：虚损多由失血太多，或自汗、盗汗、遗精之后，多有怔忡惊悸，健忘恍惚不寐之症，皆因心气不足，心神不安，殊非气郁痰涎为患。速宜养其气血，救其根本，此脱运之机也，宜养心汤、酸枣仁汤、加减茯苓补心汤。", "白话": "〔按语〕吴澄按：虚损多由失血过多，或自汗、盗汗、遗精之后，多见怔忡惊悸、健忘恍惚不寐之证；都是因为心气不足、心神不安，绝不是气郁痰涎为患。应赶紧养其气血、救治根本，这是脱却厄运的关键时机——宜用养心汤、酸枣仁汤、加减茯苓补心汤。"}, {"source": "条971｜《不居集·上集》·产后阴虚发热", "原文": "《不居集·上集》：“产后有阴虚发热者，必素禀脾肾不足，及产后气血俱虚，故多有之。其症则倏忽往来，时作时止，或昼或夜，进退不常，或精神困倦，怔忡恍惚。但察其外无表症，而脉见弦数，或浮弦豁大，或细微无力，其来也渐，非若他症之暴至者，即是阴虚之候。治当专补真阴，大、小营煎，三阴煎，五阴煎，理阴煎，理脾益荣汤，培土养阴汤。", "白话": "〔辨证〕产后有阴虚发热者，必是素来禀赋脾肾不足，加上产后气血俱虚，所以多见此证。其症状发热倏忽往来，时作时止，或昼或夜，进退无常，或精神困倦、怔忡恍惚。只要察其外无表证，而脉见弦数，或浮弦豁大，或细微无力，其来也渐缓，不像他证那样暴然即至——这就是阴虚之候。〔治法〕当专补真阴：用大营煎、小营煎、三阴煎、五阴煎、理阴煎、理脾益荣汤、培土养阴汤。"}, {"source": "条972｜《不居集·下集》·河车如圣丹", "原文": "《不居集·下集》：“河车如圣丹。\n紫河车一具，酒洗净 青蒿一斗五升，入童便熬  \n熬童便减至二斗，去青蒿，再熬至一斗，再入紫河车煮烂，莲粉收为丸，如梧桐子大，每服五十丸。\n按：杏仁翁云：凡虚损中诸症，务要得紫河车，取效甚速。入血药中则补血，入气药中则补气，入去热药中则退药。又治癫痫健忘，怔忡失志之症，及恍惚惊怖，神不守舍，多言不定，此药大能安心养血定神。又治骨蒸传尸，数种虚劳邪热，滋阴补阳，乃养寿", "白话": "〔方名〕河车如圣丹。〔组成·照录〕紫河车一具（酒洗净），青蒿一斗五升（入童便熬）。〔制法〕熬童便减至二斗，去青蒿，再熬至一斗，加入紫河车煮烂，以莲粉收为丸，梧桐子大。〔服法〕每服五十丸。〔按语〕杏仁翁说：凡虚损诸证，务必要用紫河车，取效甚速；入血药中则补血，入气药中则补气，入退热药中则退热。又治癫痫健忘、怔忡失志之证，以及恍惚惊怖、神不守舍、多言不定——此药大能安心养血定神。又治骨蒸传尸、数种虚劳邪热，滋阴补阳，是养寿之圣药。我用此屡试屡验。"}, {"source": "条973｜《目经大成》卷三·人参养荣汤", "原文": "《目经大成》卷三：“人参养荣汤。  \n人参 白术 茯苓 甘草 黄芪剂片蜜拌炒 橘皮 肉桂 当归 芍药 地黄 远志缓火炆去梗 五味子  \n脉极肉瞤，惊悸健忘，寝汗发热，食少气短，肌瘦目枯，毛发堕落，此方主之。经曰：脾气散精，上输于肺。此地气上升也。肺主治节，通调水道，下输膀胱，此天气下降也。肺脾虚，则上下不交，荣血无所藉以生。是故肺虚则气短，毛发堕落。脾虚则食少，肌瘦目枯。脾肺两虚，自无血以养心，则", "白话": "〔方名〕人参养荣汤。〔组成·照录〕人参、白术、茯苓、甘草、黄芪（切片蜜拌炒）、橘皮、肉桂、当归、芍药、地黄、远志（缓火炆去梗）、五味子。〔主治〕脉极、肌肉瞤动，惊悸健忘，睡中盗汗发热，食少气短，肌肉消瘦、目睛枯涩，毛发脱落——此方主治。〔方论〕《内经》说：脾气散精，上输于肺，这是地气上升；肺主治节，通调水道，下输膀胱，这是天气下降。肺脾虚则上下不交，营血无所凭借而生。所以肺虚则气短、毛发脱落；脾虚则食少、肌瘦目枯；脾肺两虚则自然无血养心，于是百脉疲惫极甚，睡中盗汗发热、惊悸健"}, {"source": "条974｜《外科心法要诀》卷十六·白芍药汤", "原文": "《外科心法要诀》卷十六：“如旬日外，儿脐忽肿，如吹不赤，捻动微响，或惊悸作啼者，宜用白芍药汤加薏苡仁，令儿服之，外以外消散敷之即愈。\n白芍药汤  白芍酒炒，一两 泽泻五钱 甘草生，一钱二分 肉桂拣薄者刮去粗皮，一钱  \n共研粗末，每用二钱，水一盅，煎四分，空心频服。脐下痛加钩藤一钱，生姜一片，食盐五厘。", "白话": "〔主治〕小儿出生十天半月后，脐部忽然肿起，如吹气状而不红，捻动时微有响声，或惊悸啼哭者——宜用白芍药汤加薏苡仁令儿内服，外用外消散敷之即愈。〔方名〕白芍药汤：〔组成·照录〕白芍（酒炒）一两，泽泻五钱，生甘草一钱二分，肉桂（拣薄者刮去粗皮）一钱。〔方义〕白芍、甘草缓急和中，泽泻利湿，肉桂温阳散结，为小儿脐肿内服之方。〔制法·服法〕共研粗末，每用二钱，水一盅煎取四分，空腹频服。〔加减〕脐下痛加钩藤一钱、生姜一片、食盐五厘。"}, {"source": "条975｜《临症验舌法》下卷·归脾汤去木香加丹皮山栀方", "原文": "《临症验舌法》下卷：“归脾汤去木香加丹皮山栀方。  \n枣仁一钱，炒研 茯神一钱，去木 远志一钱，去心 归身一钱 人参一钱半 炙芪三钱，无参倍之 白术二钱半，米泔净蒸 尤圆七枚，去壳 甘草一钱，炙 白芍二钱 丹皮钱半 山栀钱半，炒黑 煨姜一钱 大枣三枚\n按：上方主治思虑伤心脾，郁怒伤肝，以致三经血少而燥。渐至心口有块如拳，或左肋下有块如手掌，或右肋下有块如镰刀，且时作痛，及健忘怔忡、惊悸不寐等症。《", "白话": "〔方名〕归脾汤去木香加丹皮山栀方。〔组成·照录〕酸枣仁（炒研）一钱，茯神（去木）一钱，远志（去心）一钱，当归身一钱，人参一钱半，炙黄芪三钱（无参则倍用），白术（米泔净蒸）二钱半，龙眼（原稿作“尤圆”）七枚（去壳），甘草（炙）一钱，白芍二钱，丹皮一钱半，山栀（炒黑）一钱半，煨姜一钱，大枣三枚。〔方义〕归脾汤补心脾、去木香之燥，加丹皮、山栀清血分郁热，治心脾两虚兼郁热之怔忡惊悸。〔原稿按语〕上方主治思虑伤心脾、郁怒伤肝，以致三经血少而燥，渐至心口有块如拳，或左肋下有块如手掌，或右"}, {"source": "条976｜《临症验舌法》下卷·附子养荣汤方", "原文": "《临症验舌法》下卷：“附子养荣汤方。  \n附子钱半 远志一钱 白芍三钱，酒炒 归身二钱 五味钱半 熟地六钱 肉桂五分 茯苓钱半 人参钱半或二三钱 炙芪五钱，无参倍用 白术三钱 陈皮钱半 炙草钱半 煨姜二钱 大枣五枚\n上将熟地枣肉捣烂，其余炒磨为末，加蜜为丸，即予家所制万应一粒丹者是也。凡中风伤寒，痘疹胎产，及血症喉痹等症，势在危急，刻不可缓者，每用一粒，滚汤研化，不时灌服，其势自定。继予两粒三粒，", "白话": "〔方名〕附子养荣汤方。〔组成·照录〕附子一钱半，远志一钱，白芍（酒炒）三钱，当归身二钱，五味子一钱半，熟地六钱，肉桂五分，茯苓一钱半，人参一钱半或二三钱，炙黄芪五钱（无参则倍用），白术三钱，陈皮一钱半，炙甘草一钱半，煨姜二钱，大枣五枚。〔方义〕附子、肉桂温阳，参、芪、术、苓、草益气，归、芍、地养血，远志、五味养心安神，为温阳益气养荣之剂。〔制法·服法〕上将熟地、枣肉捣烂，其余炒后磨为末，加蜜为丸，即我家所制“万应一粒丹”。凡中风、伤寒、痘疹、胎产及血证、喉痹等证，病势危急、刻"}, {"source": "条977｜《景岳全书发挥》卷二·寿脾煎", "原文": "《景岳全书发挥》卷二：“若思虑劳倦伤心脾，以致气虚精陷，为怔忡、惊悸、不寐者，宜寿脾煎。治法未合病情。", "白话": "〔主治〕若思虑劳倦伤心脾，以致气虚精气下陷，而成怔忡、惊悸、不寐者，宜用寿脾煎。〔评〕（原稿末句）治法未合病情。"}, {"source": "条978｜《疡医大全》卷十八·转败丹", "原文": "《疡医大全》卷十八：“又曰：有久生瘰疬，颈间尽烂，且及于胸膈，无非痰块，以至身体发热发寒，肌肉消瘦，不思饮食，自汗盗汗，惊悸恍惚。此证原难医治，然治得法，亦在可救也。夫此证初起，宜解郁为先，佐之补虚，以消其毒；倘执寻常治法，以祛痰败毒为事，鲜不速之亡矣。用转败丹：\n人参二两 柴胡二钱 白芍三钱 金银花三两 当归二两 半夏五钱 白术一两 生甘草三钱\n水煎服，四剂，痰块在胸者尽消，又四剂，颈上溃烂亦愈", "白话": "〔引文〕又说：有人久患瘰疬，颈间尽已溃烂，且延及胸膈，无非痰块，以致身体发热恶寒，肌肉消瘦，不思饮食，自汗盗汗，惊悸恍惚。此证本难医治，但治法得当，也在可救之列。此证初起，宜以解郁为先，佐以补虚以消其毒；倘若固执寻常治法，一味祛痰败毒，少有不加速死亡者。〔方名〕用转败丹：〔组成·照录〕人参二两，柴胡二钱，白芍三钱，金银花三两，当归二两，半夏五钱，白术一两，生甘草三钱。〔方义〕参、术、归、芍大补气血，柴胡开郁，半夏化痰，金银花解毒，补多于消而开郁化痰寓于其中。〔服法〕水煎服：四"}, {"source": "条979｜《疡医大全》卷二十六·加味养荣丸", "原文": "《疡医大全》卷二十六：“加味养荣丸。治妇女脚气，心虚血少，怔忡心悸，肝脾不足，调经养血，非此不效。  \n当归身酒洗焙，三两 白茯神人乳蒸，二两 肥玉竹焙，二两 杭白芍酒炒，二两 酸枣仁炒熟，二两 丹参酒炒，二两 远志肉甘草汤焙，二两 柏子仁二两 川续断酒炒，二两 橘红饭上蒸，一两 杜仲盐水炒，二两 秦艽酒炒，一两五钱 女贞实蜜拌蒸，二两 钩藤钩四两，同石斛熬 郁金二两  \n上制毕，磨细末。用金钗石", "白话": "〔方名〕加味养荣丸。〔主治〕治妇女脚气、心虚血少、怔忡心悸、肝脾不足，用以调经养血，非此不效。〔组成·照录〕当归身（酒洗焙）三两，白茯神（人乳蒸）二两，肥玉竹（焙）二两，杭白芍（酒炒）二两，酸枣仁（炒熟）二两，丹参（酒炒）二两，远志肉（甘草汤焙）二两，柏子仁二两，川续断（酒炒）二两，橘红（饭上蒸）一两，杜仲（盐水炒）二两，秦艽（酒炒）一两五钱，女贞实（蜜拌蒸）二两，钩藤钩四两（同石斛熬），郁金二两。〔方义〕归、芍、丹参、玉竹、女贞养血滋阴，茯神、枣仁、柏仁、远志安神定悸，杜仲"}, {"source": "条980｜《成方切用》卷二·小营煎", "原文": "《成方切用》卷二：“小营煎景岳。治血少阴虚，此性味和平之方也。  \n当归二钱 熟地三四钱 芍药酒炒 山药 枸杞二钱 炙草一钱  \n如营虚于上，而为惊恐怔忡不眠多汗者，加枣仁茯神各二钱。如营虚兼寒者，去芍药，加煨姜。如气滞有痛者，加香附一二钱，引而行之。", "白话": "〔方名〕小营煎（景岳方）。〔主治〕治血少阴虚，此性味平和之方。〔组成·照录〕当归二钱，熟地三四钱，芍药（酒炒）、山药、枸杞二钱，炙甘草一钱。〔方义〕与《景岳全书》小营煎同（见本块 条901），平补营血。〔加减〕营虚于上而见惊恐怔忡、不眠多汗者，加酸枣仁、茯神各二钱；营虚兼寒者，去芍药加煨姜；气滞有痛者，加香附一二钱以行之。"}, {"source": "条981｜《金匮翼》卷三·远志引子", "原文": "《金匮翼》卷三：“远志引子。治心劳虚寒，梦寐惊悸。  \n远志去心、茯神去木、肉桂、人参、枣仁炒、黄芪、当归各一两 甘草炙，半两  \n上㕮咀，每服四钱，水一盏，姜五片，煎服无时。", "白话": "〔方名〕远志引子。〔主治〕治心劳虚寒，梦寐惊悸。〔组成·照录〕远志（去心）、茯神（去木）、肉桂、人参、酸枣仁（炒）、黄芪、当归各一两；甘草（炙）半两。〔方义〕参、芪、归、草益气养血，枣仁、茯神、远志养心安神，肉桂温心阳，为温养心气、安神定悸之剂。〔服法〕上药切碎，每服四钱，水一盏加姜五片煎服，不拘时。"}, {"source": "条982｜《杂病源流犀烛》卷六·十味导赤散", "原文": "《杂病源流犀烛》卷六：“十味导赤散。实热。\n黄连、黄芩、麦冬、半夏、茯苓、赤芍、木通、生地、甘草、地骨皮各用五分 姜五片  \n此治心脏实热，一切口舌生疮、惊悸、烦渴诸症。", "白话": "〔方名〕十味导赤散（实热）。〔组成·照录〕黄连、黄芩、麦冬、半夏、茯苓、赤芍、木通、生地、甘草、地骨皮各用五分，生姜五片。〔方义〕黄连、黄芩、生地、木通、赤芍、地骨皮清心导赤，麦冬滋阴，半夏、茯苓化痰和中，为清心泻火之剂。〔主治〕治心脏实热，一切口舌生疮、惊悸、烦渴诸证。"}, {"source": "条983｜《杂病源流犀烛》卷十六·虚黄／风黄", "原文": "《杂病源流犀烛》卷十六：“又有虚黄，口淡，怔忡，寒热，溲白，耳鸣，脚软，怠惰无力，凡郁不得志人，多生此症宜人参养荣汤，又有风黄，身不黄，独目黄，其人肥，风不外泄故也宜青龙散。", "白话": "〔辨证〕又有虚黄：口淡、怔忡、寒热、小便色白、耳鸣、脚软、怠惰无力——凡郁郁不得志之人多生此证，宜用人参养荣汤。又有风黄：身不发黄，唯独两目发黄，其人肥胖，是风邪不得外泄之故——宜用青龙散。"}, {"source": "条984｜《杂病源流犀烛》卷二十五·天麻丸", "原文": "《杂病源流犀烛》卷二十五：“风痰闭壅眩晕，必胸膈痞塞，项急，肩背拘倦，神昏多睡，或心忪烦闷而发宜天麻五钱，川芎二两，蜜丸芡子大，食后清茶嚼下一丸，名天麻丸。", "白话": "〔主治〕风痰闭阻之眩晕：必见胸膈痞塞、颈项拘急、肩背拘挛疲倦、神昏多睡，或心忪（心悸）烦闷而发作——宜用天麻五钱、川芎二两，炼蜜为丸，芡实子大，食后清茶嚼下一丸，名天麻丸。"}, {"source": "条985｜《妇科玉尺》卷二·大圣汤", "原文": "《妇科玉尺》卷二：“妊娠有怔忡脉乱，惊悸不安，夜卧不宁，恍惚气触者，宜大圣汤。", "白话": "〔主治〕妊娠见怔忡、脉象紊乱、惊悸不安、夜卧不宁、恍惚如气所触者，宜用大圣汤。"}, {"source": "条986｜《妇科玉尺》卷二·古芩术汤加减（安胎）", "原文": "《妇科玉尺》卷二：“胎动，通用古芩术汤加阿胶，风邪加姜豉，寒加葱白，热加花粉，寒热加柴胡，项强加葱白，温热腹痛加白芍，腹胀加厚朴，下血加艾、地榆，腰痛加杜仲，惊悸加黄连，烦渴加麦冬、乌梅，思虑太过加茯神，痰呕加旋复花旋覆花、贝母，或酌用半夏曲，劳役加黄芪，气喘去术加香附，便燥加麻仁，素惯难产加枳壳、苏叶，素惯堕胎加杜仲，素血虚加芎、归，此安胎之圣药也。", "白话": "〔主治〕胎动不安，通用古芩术汤加阿胶为基本方。〔加减〕受风邪加姜、豆豉；有寒加葱白；有热加天花粉；寒热往来加柴胡；项强加葱白；温热腹痛加白芍；腹胀加厚朴；下血加艾叶、地榆；腰痛加杜仲；惊悸加黄连；烦渴加麦冬、乌梅；思虑太过加茯神；痰呕加旋覆花、贝母（或酌用半夏曲）；劳役伤加黄芪；气喘去白术加香附；大便干燥加火麻仁；素惯难产加枳壳、紫苏叶；素惯堕胎加杜仲；素来血虚加川芎、当归——这是安胎之圣药。"}, {"source": "条987｜《幼科释谜》卷六·谭氏金珠丸", "原文": "《幼科释谜》卷六：“谭氏金珠丸。\n南星、白矾、半夏各七钱 人参、山药各五钱 朱砂、腻粉各二钱 金箔十片\n即为衣，薄荷汁同水打糊丸，绿豆大，每一丸，姜汤下，量加减。\n治小儿惊悸怔忡，化痰涎，利胸膈烦热，止嗽。", "白话": "〔方名〕谭氏金珠丸。〔组成·照录〕南星、白矾、半夏各七钱；人参、山药各五钱；朱砂、腻粉各二钱；金箔十片（即用作衣）。〔方义〕南星、半夏、白矾化痰，参、山药健脾，朱砂、金箔镇心，腻粉坠痰，为化痰镇惊之丸。〔制法·服法〕以薄荷汁同水打糊为丸，绿豆大；每次服一丸，姜汤送下，随年龄大小加减。〔主治〕治小儿惊悸怔忡，化痰涎，利胸膈烦热，止嗽。"}, {"source": "条988｜《慈幼新书》卷四·益元汤", "原文": "《慈幼新书》卷四：“益元汤。此为元气虚弱者立也，辨症果真，则前后皆不可易，中间杂症，虽或不同，要皆气虚致之，治者只于本方消息加减。  \n人参 黄芪 甘草 白术 陈皮 当归 川芎 升麻 桔梗 生姜  \n惊悸，加天麻、钩藤，磨安神丸。", "白话": "〔方名〕益元汤。〔立意〕此方为元气虚弱者设立：辨证如果真切，则前后主方都不可更换；中间兼夹杂症虽或不同，总由气虚所致，治疗者只在本方基础上斟酌加减。〔组成·照录〕人参、黄芪、甘草、白术、陈皮、当归、川芎、升麻、桔梗、生姜。〔方义〕参、芪、术、草益气，归、芎养血，升麻、桔梗升提，陈皮、生姜和中，为益元气之基础方。〔加减〕惊悸者加天麻、钩藤，送服安神丸（“磨安神丸”即研化安神丸同服）。"}, {"source": "条989｜《慈幼新书》卷六·木香散", "原文": "《慈幼新书》卷六：“木香散。治纯阴无阳，泄泻而渴。  \n木香 人参 肉桂 半夏 青皮 前胡 丁香 大腹皮 赤茯苓 炙甘草 诃子煨去枝 生姜 糯米  \n虚甚，加黄芪。陈氏云：腹胀渴者，泻渴者，足指冷渴者，惊悸渴者，身温渴者，身热面㿠白渴者，寒颤渴不止者，气急咬牙渴者，饮水转水泻不已渴者，九症皆非热也，乃津液少，致脾胃肌肉虚故耳。此方治之。然必痘色白，手足凉，小便清利方效。若痘色红，大便秘，小便赤，即", "白话": "〔方名〕木香散。〔主治〕治纯阴无阳、泄泻而渴。〔组成·照录〕木香、人参、肉桂、半夏、青皮、前胡、丁香、大腹皮、赤茯苓、炙甘草、诃子（煨，去核）、生姜、糯米。〔方义〕木香、青皮、大腹皮理气，参、桂、丁香温中益气，半夏、前胡化痰，诃子涩肠，治阴盛阳衰之泄泻而渴。〔加减〕虚甚加黄芪。〔引文〕陈氏说：腹胀而渴、泄泻而渴、足趾冷而渴、惊悸而渴、身温而渴、身热面㿠白而渴、寒颤而渴不止、气急咬牙而渴、饮水即水泻不止而渴——九证都不是热证，而是津液少、脾胃肌肉虚之故，此方治之。但必须痘色白、"}, {"source": "条990｜《婴儿论·辨寒热脉证并治第二》·枸杞凉肝汤", "原文": "《婴儿论·辨寒热脉证并治第二》：“气血两衰，郁火起伏，胸硬腹弱，少气悸动，兼主眼目不了了者，宜枸杞凉肝汤。  \n枸杞、厚朴、香附子各一钱 茯苓二钱 黄柏、甘草各五分  \n上九味，以水二升，煮取一升，去滓分温服。", "白话": "〔主治〕气血两衰，郁火起伏，胸硬腹软，短气悸动，兼治视物不清者，宜用枸杞凉肝汤。〔组成·照录〕枸杞、厚朴、香附子各一钱，茯苓二钱，黄柏、甘草各五分。〔方义〕枸杞滋阴养肝，黄柏清郁火，厚朴、香附理气，茯苓、甘草健脾和中，为凉肝清郁之剂。〔服法〕上九味，以水二升煮取一升，去渣分次温服。"}, {"source": "条991｜《婴儿论·辨疳病脉证并治第五》·八珍汤", "原文": "《婴儿论·辨疳病脉证并治第五》：“病人，气血虚竭，郁热起伏，二脉细数，大便若燥，若溏，胸痞悸动，呴其气，而热愈动，滋其血，而胸益痞，宜八珍汤主之。八珍汤方：  \n人参三分 茯苓二钱 枸杞三钱 缩砂五分 鹿角霜七分 莲蕊三分 生姜一片 甘草三分  \n上八味，以水二升，煮取一升，去滓，分温服。", "白话": "〔辨证〕病人气血虚竭，郁热起伏，两手脉细数，大便或干或溏，胸痞悸动；疏泄其气则热更动，滋补其血则胸更痞——宜用八珍汤主治。〔方名〕八珍汤方：〔组成·照录〕人参三分，茯苓二钱，枸杞三钱，缩砂五分，鹿角霜七分，莲蕊三分，生姜一片，甘草三分。〔方义〕参、苓、姜、草益气健脾，枸杞、鹿角霜、莲蕊补肾固精，缩砂理气和中，补而不滞。〔服法〕上八味，以水二升煮取一升，去渣分次温服。"}, {"source": "条992｜《伤寒瘟疫条辨》卷五·人参固本汤（附大营煎）", "原文": "《伤寒瘟疫条辨》卷五：“人参固本汤。治温病虚极热极，循衣作空，不下必死者。下后神思稍苏，续得肢体振寒，怔忡惊悸，如人将捕之状，四肢厥逆，眩运郁冒，项背强直，此大虚之兆，将危之候也，此方救之。\n大营煎。治男子真阴精血亏损，及妇人经迟血少，或腰膝筋骨疼痛，或虚寒心腹疼痛者。  \n熟地三、五、七钱 当归二、三、五钱 枸杞二钱 杜仲盐炒，二钱 牛膝钱半 肉桂一钱 甘草炙，二钱  \n水煎温服。如寒滞在经，气", "白话": "〔方名一〕人参固本汤。〔主治〕治温病虚极热极，循衣摸床、撮空理线，不攻下必死者；攻下后神思稍苏，接着出现肢体振颤发冷、怔忡惊悸如人将捕之状、四肢厥冷、眩晕昏冒、项背强直——这是大虚之兆、将危之候，用此方救治（组成原稿未载）。〔方名二〕大营煎。〔主治〕治男子真阴精血亏损，及妇人月经后期、血少，或腰膝筋骨疼痛，或虚寒心腹疼痛者。〔组成·照录〕熟地三、五、七钱，当归二、三、五钱，枸杞二钱，杜仲（盐炒）二钱，牛膝一钱半，肉桂一钱，甘草（炙）二钱。〔方义〕熟地、当归、枸杞、杜仲、牛膝补"}, {"source": "条993｜《疫疹一得》卷下·惊悸茯神镇惊汤", "原文": "《疫疹一得》卷下：“惊悸茯神镇惊汤。\n人参一钱 黄芪钱半，炙 当归二钱 茯神三钱 远志钱半 龙齿二钱，煅 白芍一钱 麦冬二钱 琥珀一钱，研冲服 炙甘草八分 龙眼三枚 灯芯三十寸", "白话": "〔方名〕惊悸茯神镇惊汤。〔组成·照录〕人参一钱，黄芪（炙）一钱半，当归二钱，茯神三钱，远志一钱半，龙齿（煅）二钱，白芍一钱，麦冬二钱，琥珀一钱（研末冲服），炙甘草八分，龙眼三枚，灯心三十寸。〔方义〕参、芪、归、芍益气养血，茯神、远志、龙眼养心安神，龙齿、琥珀镇惊，麦冬、灯心清心除烦，为益气养血、镇惊安神之剂。〔服法〕原稿未载煎服法，据组成为水煎，琥珀研末冲服。"}, {"source": "条994｜《竹林女科证治》卷三·石斛散", "原文": "《竹林女科证治》卷三：“产后惊悸，闻声欲死，非他人用力抱持，则虚烦欲死，由心肝脾三经虚也。宜石斛散。  \n人参、酸枣仁、茯神、远志肉、白芍、石斛、麦冬去心、炙甘草、五味子各等分\n为末，每服二三钱，桂圆汤下。", "白话": "〔辨证〕产后惊悸：闻声响即欲死，非得他人用力抱持不可，否则虚烦欲死——这是心、肝、脾三经俱虚之故。〔方名〕宜用石斛散。〔组成·照录〕人参、酸枣仁、茯神、远志肉、白芍、石斛、麦冬（去心）、炙甘草、五味子各等分。〔方义〕参、草益气，芍、斛、麦冬、五味养阴柔肝，枣仁、茯神、远志养心安神，为三经并补、安神定惊之散。〔制法·服法〕为末，每服二三钱，桂圆（龙眼）汤送下。"}, {"source": "条995｜《竹林女科证治》卷三·佛手散加味（产后少阳感风）", "原文": "《竹林女科证治》卷三：“产后少阳感风。谵语、烦躁，更加惊悸者死，盖少阳胆也。胆无汁不能润心，心无血不能为养。是以心中恍惚而谵语、烦躁、惊悸相因而生也。夫胆受邪不发表则血无以生，然徒发表则血更耗散。宜佛手散，加人参、枣仁、麦冬、竹茹、朱砂、熟地黄治之。", "白话": "〔辨证〕产后感受少阳风邪，见谵语、烦躁，再加惊悸者预后不良（死）——因为少阳属胆：胆无汁液不能润养心，心无血液不能受养，所以心中恍惚而谵语、烦躁、惊悸相继而生。〔治法〕胆受邪，不发表则血无以生；但徒用发表则血更耗散。宜用佛手散加人参、酸枣仁、麦冬、竹茹、朱砂、熟地黄治疗。"}, {"source": "条996｜《罗氏会约医镜》卷十五·养血安神汤", "原文": "《罗氏会约医镜》卷十五：“养血安神汤。治产后心血不足，以致神魂不安而惊悸也。  \n当归身二钱 熟地三五钱 白芍酒炒，钱半 茯神、枣仁炒、生地、炙草各一钱 远志六分 五味三分 干姜炒黑，三四分 柏子仁微炒去油，七分 白莲五粒，去心，微炒，捶碎  \n水煎，温服。或用天王补心丹亦妙。", "白话": "〔方名〕养血安神汤。〔主治〕治产后心血不足，以致神魂不安而惊悸。〔组成·照录〕当归身二钱，熟地三五钱，白芍（酒炒）一钱半，茯神、酸枣仁（炒）、生地、炙甘草各一钱，远志六分，五味子三分，干姜（炒黑）三四分，柏子仁（微炒去油）七分，白莲子五粒（去心，微炒，捶碎）。〔方义〕四物养血，枣仁、柏仁、茯神、远志、莲子养心安神，五味子敛心气，少佐干姜温中，为养血安神之剂。〔服法〕水煎温服；或用天王补心丹亦妙。"}, {"source": "条997｜《彤园医书（妇人科）》卷五·二陈汤", "原文": "《彤园医书（妇人科）》卷五：“二陈汤。主治产后呕吐痰饮，随症加减。\n去白陈皮 姜制半夏 白茯苓 甘草 生姜  \n风痰加胆星、白附、竹沥……惊悸怔忡，加石菖蒲、炒研益智。", "白话": "〔方名〕二陈汤。〔主治〕主治产后呕吐痰饮，随证加减。〔组成·照录〕去白陈皮、姜制半夏、白茯苓、甘草、生姜。〔方义〕二陈汤燥湿化痰、理气和中，为治痰饮之基础方。〔加减〕风痰加胆南星、白附子、竹沥……（原稿节略）；惊悸怔忡加石菖蒲、炒研益智仁。"}, {"source": "条998｜《彤园医书（外科）》卷四·白芍汤", "原文": "《彤园医书（外科）》卷四：“若十日半月儿脐忽然突肿如吹，色不红赤，捻动微响，或惊悸而多啼，宜服白芍汤。", "白话": "〔主治〕若小儿出生十天至半月后脐部忽然突肿如吹气状，颜色不红，捻动时微有响声，或惊悸而多啼哭者，宜服白芍汤。"}, {"source": "条999｜《大方脉·伤寒杂病医方》·安神丸", "原文": "《大方脉·伤寒杂病医方》：“安神丸。治心热胆弱，怔忡惊悸。  \n黄连一两 当归、生地各五钱 甘草三钱  \n研末，面糊为小丸，朱砂滚衣。临卧，盐汤，每下二钱。", "白话": "〔方名〕安神丸。〔主治〕治心热胆弱、怔忡惊悸。〔组成·照录〕黄连一两，当归、生地各五钱，甘草三钱。〔方义〕黄连清心热，当归、生地养阴血，甘草和中，即东垣朱砂安神丸之法。〔制法·服法〕研末，面糊为小丸，朱砂滚为衣；临睡前盐汤送下，每服二钱。"}, {"source": "条1000｜《彤园医书（外科）》卷四·安神散", "原文": "《彤园医书（外科）》卷四：“凡针后出脓之时，气虚惊悸者，宜服安神散。", "白话": "〔主治〕凡针刺排脓之后，见气虚惊悸者，宜服安神散。"}, {"source": "条1001｜《感症宝筏》卷二·温胆汤加枣仁远志", "原文": "《感症宝筏》卷二：“感证热退之后，夜不欲寐者，胃不和也，温胆汤和之。惊悸不宁者，心气虚也心气虚而神不敛，当安神以敛心阳，加枣仁、远志。", "白话": "〔主治〕外感证热退之后，夜间不想入睡者，是胃不和，用温胆汤调和之；惊悸不宁者，是心气虚——心气虚则神不能内敛，当安神以敛心阳，在温胆汤中加酸枣仁、远志。"}, {"source": "条1002｜《痘科辑要·杂症》·定心散", "原文": "《痘科辑要·杂症》：“初热时，小便不长，梦中或发惊悸，急与定心散。灯心汤为引，否则惊搐之症至矣。", "白话": "〔主治〕痘疹初热之时，小便短少，梦中或发惊悸——急用定心散，以灯心汤为药引；否则惊搐之证就要到来。"}, {"source": "条1003｜《金匮要略浅注》卷二·千金三黄汤", "原文": "《金匮要略浅注》卷二：“千金三黄汤。治中风，手足拘急，百节疼痛，烦热心乱，恶寒，经日曰不欲饮食。  \n麻黄五分 独活四分 细辛、黄芪各二分 黄芩三分  \n上五味。以水六升。煮取二升。分温三服。一服小汗出。二服大汗出。心热加大黄二分。腹满加枳实一枚。气逆加人参三分。悸加牡蛎三分。渴加栝蒌根三分。先有寒、，加附子一枚。", "白话": "〔方名〕千金三黄汤。〔主治〕治中风，手足拘急，周身百节疼痛，烦热心乱，恶寒，整日不欲饮食。〔组成·照录〕麻黄五分，独活四分，细辛、黄芪各二分，黄芩三分。〔方义〕麻黄、独活、细辛祛风散寒，黄芪固表，黄芩清热，为祛风清热、扶正达邪之剂。〔服法〕上五味，以水六升煮取二升，分三次温服：一服小汗出，二服大汗出。〔加减〕心热加大黄二分；腹满加枳实一枚；气逆加人参三分；心悸加牡蛎三分；口渴加栝蒌根三分；素有寒者加附子一枚。"}, {"source": "条1004｜《金匮启钥（妇科）》卷五·四物补心汤", "原文": "《金匮启钥（妇科）》卷五：“神气不守惊悸作，可投四物补心汤。", "白话": "〔主治〕神气不能内守而惊悸发作者，可用四物补心汤。"}, {"source": "条1005｜《金匮启钥（妇科）》卷五·琥珀散", "原文": "《金匮启钥（妇科）》卷五：“琥珀散。治血虚多惊悸，产后诸疾。  \n辰砂、琥珀、没药各研细、当归各等分  \n上为细末，每服二钱，空心白汤调下，日三服。", "白话": "〔方名〕琥珀散。〔主治〕治血虚多惊悸，及产后诸疾。〔组成·照录〕辰砂、琥珀、没药（各研细）、当归各等分。〔方义〕当归养血，琥珀、辰砂镇心安神，没药散瘀，为养血镇心之散。〔制法·服法〕上为细末，每服二钱，空腹白开水调下，一日三次。"}, {"source": "条1006｜《医学指要》卷五·柴胡百合汤", "原文": "《医学指要》卷五：“柴胡百合汤。治瘥后昏沉发热，口渴，错语失神，及食复、劳复、百合等症悉宜用。\n柴胡、生地、黄芩各一钱 知母、百合、陈皮、人参各八分 甘草三分 姜 枣引 \n若头微痛，加羌活、川芎……心惊悸，为血虚，加当归、茯苓、远志。", "白话": "〔方名〕柴胡百合汤。〔主治〕治病愈后昏沉发热、口渴、言语错乱、神志失常，以及食复、劳复、百合病等证都宜用。〔组成·照录〕柴胡、生地、黄芩各一钱，知母、百合、陈皮、人参各八分，甘草三分，生姜、大枣为引。〔方义〕柴胡、黄芩清解余热，百合、生地、知母滋阴清热，参、草益气，为瘥后调养之方。〔加减〕头微痛加羌活、川芎……（原稿节略）；心惊悸属血虚者，加当归、茯苓、远志。"}, {"source": "条1007｜《医述》卷十·朱丹溪怔忡论（归脾汤加减）", "原文": "《医述》卷十：“朱丹溪怔忡，心血少也。其原起于肾水不足，不能上升，以致心火不能下降。治宜归脾汤，去木香加麦、味、枸杞，吞都气丸。", "白话": "〔引文〕朱丹溪论怔忡：怔忡是心血少，其根源起于肾水不足、不能上升，以致心火不能下降。〔治法〕治疗宜用归脾汤，去木香，加麦冬、五味子、枸杞，送服都气丸。"}, {"source": "条1008｜《产孕集》下篇·羊肉汤（蓐劳）", "原文": "《产孕集》下篇：“产后虚劳，名曰蓐劳。其候乍起乍卧，饮食不化，时作嗽咳，目昏头痛，口渴盗汗，寒热往来，喘乏自汗，少气惊悸，此由摄养不善，内伤七情，阳陷阴逆，升降倒置，藏府脏腑交病，表里均亏，误用寒凉，即死不治，宜羊肉汤。\n羊肉汤 羊肉一斤，去脂 当归、桂心、甘草各六钱 芎一两 芍药、生姜各一两三钱 干地黄一两六钱  \n以水五升，先煮羊肉，取二升三合，内药，煮取一升，分三服。", "白话": "〔病机〕产后虚劳，名叫蓐劳。其症状忽起忽卧，饮食不化，时时咳嗽，目昏头痛，口渴盗汗，寒热往来，喘而乏力、自汗，少气惊悸——这是由于摄养不当、内伤七情，阳气下陷、阴气上逆，升降倒置，脏腑交病，表里俱虚；误用寒凉之药，即成不治之死证。〔方名〕宜用羊肉汤。〔组成·照录〕羊肉汤：羊肉一斤（去脂），当归、桂心、甘草各六钱，芎（原稿“芎”下一字为缺字符）一两，芍药、生姜各一两三钱，干地黄一两六钱。〔方义〕羊肉血肉有情之品温补气血，合当归、地黄、芍药养血，桂心、生姜温阳，为产后蓐劳温补之剂"}, {"source": "条1009｜《医学妙谛》卷下·酸枣仁汤（歌括）", "原文": "《医学妙谛》卷下：“怔忡健忘都可医，加减天王补心治。怔忡人呆将捕如，惕惕不宁神明殊。不寐怔忡，胆液亏，阳升虚烦，《金匮》酸枣仁汤。  \n枣仁 甘草 知母 茯苓 川芎\n不寐健忘，肝肾阴亏，阳浮咸苦酸收甘缓法。", "白话": "〔歌括〕怔忡健忘都可医治，用加减天王补心丹治疗；怔忡之人神情呆滞、如有人将捕，惊惕不宁、神明异常。〔主治〕不寐怔忡属胆液亏、阳气升浮而虚烦者，用《金匮要略》酸枣仁汤。〔组成·照录〕酸枣仁、甘草、知母、茯苓、川芎。〔治法〕不寐健忘属肝肾阴亏、阳气浮越者，用咸苦酸收、甘缓之法。"}, {"source": "条1010｜《类证治裁》卷四·导痰汤加茯神人参石菖蒲", "原文": "《类证治裁》卷四：“凡怔忡惊恐健忘，癫狂失志不寐，皆由痰涎沃心，以致心气不足。若凉心之剂太过，则心火愈微，痰涎愈盛，惟唯以理痰顺气，养心安神，为第一义。导痰汤加茯神、人参、石菖蒲。", "白话": "〔病机〕凡怔忡、惊恐、健忘、癫狂、失志、不寐，都是痰涎浸渍于心，以致心气不足。如果寒凉清心之药用得太过，则心火愈加微弱，痰涎愈加旺盛；只以理痰顺气、养心安神为第一要义。〔方名·加减〕用导痰汤加茯神、人参、石菖蒲。"}, {"source": "条1011｜《医略十三篇》卷一·第三真黄风汤", "原文": "《医略十三篇》卷一：“或证言微蹇，或面戴阳色，或消谷善饥，或饮食少进，或浊痰未清，或肢体无力，或无故多思，或怔忡惊悸不寐等证，接服第三方调理。第三真黄风汤，主治真中风，服前二方，表里俱和，诸证悉退，或二气未充，或余氛未尽，宜此方调理，真善后之良法也。  \n炙黄芪三钱 防风根三分 人参钱半 大熟地四钱 云茯苓三钱 炙甘草五分 制半夏钱半 福橘皮一钱 麸炒枳实五分 豨莶三钱  \n长流水煎服一二剂，或三", "白话": "〔主治〕或言语微涩，或面戴阳色，或消谷善饥，或饮食少进，或浊痰未清，或肢体无力，或无故多思，或怔忡惊悸不寐等证——接着服第三方调理。〔方名〕第三真黄风汤，主治真中风：服前二方后表里俱和、诸证悉退，但或阴阳二气未充，或余邪未尽者，宜用此方调理，真是善后之良法。〔组成·照录〕炙黄芪三钱，防风根三分，人参一钱半，大熟地四钱，云茯苓三钱，炙甘草五分，制半夏一钱半，福橘皮一钱，麸炒枳实五分，豨莶三钱。〔方义〕黄芪、防风益气固表（玉屏风法），参、苓、草健脾，熟地养血，半夏、橘皮、枳实化痰"}, {"source": "条1012｜《验方新编》卷二十·滋味活络汤", "原文": "《验方新编》卷二十：“滋味活络汤。\n当归、人参各三钱 川芎、熟地各二钱 黄芪、茯神、天麻、麦冬各一钱 陈皮、炙甘草各五分 荆芥、防风、羌活各四分\n火盛产久，加炒连三分。有痰，加夏曲七分。痰多，加竹沥、姜汁。大便闭秘加苁蓉二钱。渴，加葛根八分。汗多，加麻黄根一钱。惊悸，加枣仁二钱。气息如结、手足渐冷，加桂子一钱，附子五分。", "白话": "〔方名〕滋味活络汤。〔组成·照录〕当归、人参各三钱，川芎、熟地各二钱，黄芪、茯神、天麻、麦冬各一钱，陈皮、炙甘草各五分，荆芥、防风、羌活各四分。〔方义〕参、芪、归、芎、地益气养血，荆芥、防风、羌活、天麻祛风通络，茯神、麦冬安神，为产后养血祛风活络之剂。〔加减〕火盛产久加炒黄连三分；有痰加半夏曲七分；痰多加竹沥、姜汁；大便秘结加肉苁蓉二钱；口渴加葛根八分；汗多加麻黄根一钱；惊悸加酸枣仁二钱；气息如结、手足渐冷加桂子（肉桂）一钱、附子五分。"}, {"source": "条1013｜《验方新编》卷二十四·安神散", "原文": "《验方新编》卷二十四：“安神散。治疔毒针后，气虚惊悸。\n人参、麦冬、茯神、生芪、焦术、元参、陈皮、石菖蒲、炒枣仁、远志肉、五味子、炙草等分\n服时，加朱砂末五分调服，凡恶毒攻心，心神不定者，用地骨皮研末，滚蜜水调服即安，亦名安神散。", "白话": "〔方名〕安神散。〔主治〕治疗毒针刺之后，气虚惊悸。〔组成·照录〕人参、麦冬、茯神、生黄芪、焦白术、元参、陈皮、石菖蒲、炒酸枣仁、远志肉、五味子、炙甘草各等分。〔方义〕参、芪、术、草益气，麦冬、元参滋阴，枣仁、茯神、远志、菖蒲、五味安神定悸。〔服法〕服时加朱砂末五分调服。〔又方〕凡恶毒攻心、心神不定者，用地骨皮研末，滚蜜水调服即安，也叫安神散。"}, {"source": "条1014｜《鸡鸣录·虚劳第四》·通神补血丸", "原文": "《鸡鸣录·虚劳第四》：“治虚火上炎，气升咳逆，时吐涎沫，为保肺清金，而不碍脾胃之要药。  \n生地三两 茯神三两五钱 紫石英煅飞、远志、枣仁炒，各二两 当归一两五钱 人参、麦冬、丹参、制半夏各一两 石菖蒲八钱 胆星四钱 琥珀三钱 川连二钱  \n十四味研细，用连血猪心一个，入辰砂三钱 煮烂打丸，如干加炼蜜，或独用炼蜜亦可。每丸重一钱五分，辰砂为衣，空心枣汤，或盐汤化服，每服一丸，名通神补血丸，专治神虚", "白话": "〔主治〕治虚火上炎，气逆上冲、咳逆，时时吐涎沫——是保肺清金而不碍脾胃的要药。〔组成·照录〕生地三两，茯神三两五钱，紫石英（煅，水飞）、远志、酸枣仁（炒）各二两，当归一两五钱，人参、麦冬、丹参、制半夏各一两，石菖蒲八钱，胆南星四钱，琥珀三钱，黄连二钱。〔方义〕生地、麦冬、当归、丹参养血滋阴，参、苓益气，枣仁、远志、菖蒲、茯神安神，紫石英、琥珀、辰砂镇心，黄连清火，为养血安神之丸。〔制法·服法〕十四味研细，用带血猪心一个，加入辰砂三钱煮烂打丸；若干加炼蜜，或单用炼蜜亦可。每丸重"}, {"source": "条1015｜《杂病广要·脏腑类》·朱砂散", "原文": "《杂病广要·脏腑类》：“治心脏不安，惊悸善忘，上膈风热，化痰安神，朱砂散方。  \n朱砂一两，研 白石英一两，研  \n上件药二味同细研为散，每服半钱，食后临卧煎金银汤调下。", "白话": "〔方名〕朱砂散。〔主治〕治心脏不安、惊悸善忘，上膈风热，功能化痰安神。〔组成·照录〕朱砂一两（研），白石英一两（研）。〔方义〕朱砂镇心安神，白石英重镇化痰，为镇心安神之散。〔制法·服法〕二味同细研为散，每服半钱，食后临睡前以金银器煎汤调下。"}, {"source": "条1016｜《杂病广要·内因类》·虚乏方", "原文": "《杂病广要·内因类》：“虚乏方。（节录）  \n饴糖半斤 黄芪、远志、当归千金翼无、泽泻各三两 芍药、人参、龙骨、甘草各二两 生姜八两 大枣二十枚  \n上十一味㕮咀味，㕮咀，以水一斗，煮取二升半，汤成内糖令烊，一服八合。消息，又一服。（《千金》）《简易》引《究原方》，去饴糖、大枣，治小腹急痛，便溺失精，虚热盗汗，四体倦怠，支节烦疼，口苦舌涩，心怔气短，日渐羸弱。", "白话": "〔方名〕虚乏方（节录）。〔组成·照录〕饴糖半斤；黄芪、远志、当归（《千金翼方》无）、泽泻各三两；芍药、人参、龙骨、甘草各二两；生姜八两；大枣二十枚。〔方义〕黄芪、人参、甘草、饴糖、大枣建中益气，归、芍养血，远志、龙骨安神，泽泻利浊，为补虚建中之剂。〔服法〕上十一味切碎，以水一斗煮取二升半，汤成加入饴糖烊化；一次服八合，斟酌再服（出《千金方》）。〔异本〕《简易方》引《究原方》，去饴糖、大枣，治小腹急痛、大小便失精、虚热盗汗、四肢倦怠、肢节烦疼、口苦舌涩、心怔气短、日渐羸弱。"}, {"source": "条1017｜《杂病广要·脏腑类》·辰砂安神丸、朱砂丸", "原文": "《杂病广要·脏腑类》：“真觉心跳者是血少，四物、朱砂安神之类。丹溪曰：心气虚怯之人，怔忡或烦乱，或健忘，或失心后神痴不清，辰砂安神丸。又朱砂丸，治劳役心跳，于本方去地黄，加芍药、侧柏叶、川芎、陈皮。", "白话": "〔辨证〕真觉心跳者是血少，用四物汤、朱砂安神丸之类。〔引文〕丹溪说：心气虚怯之人，或怔忡烦乱，或健忘，或失心之后神痴不清——用辰砂安神丸。又朱砂丸治劳役过度之心跳：于本方去地黄，加芍药、侧柏叶、川芎、陈皮。"}, {"source": "条1018｜《百代医宗》·怔忡汤", "原文": "《百代医宗》怔忡汤。\n于本方去人参、远志、石菖蒲，加川芎、白芍、熟地黄、生地黄煎服。", "白话": "〔方名〕《百代医宗》怔忡汤。〔组成·加减〕于本方（承上文辰砂安神丸）去人参、远志、石菖蒲，加川芎、白芍、熟地黄、生地黄，煎服。〔方义〕去益气开窍之品，加四物养血滋阴，为血虚怔忡而设。"}, {"source": "条1019｜《尊生书》·静神丹", "原文": "《尊生书》静神丹。\n酒当归、酒生地、姜远志、茯神各五钱  菖蒲、黄连各二钱半  朱砂二钱  牛黄一钱\n治忧思过度，惕然心跳。\n猪心血，丸黍米大，金箔十五片为衣，灯心汤下五十丸。", "白话": "〔方名〕《尊生书》静神丹。〔组成·照录〕酒当归、酒生地、姜远志、茯神各五钱；菖蒲、黄连各二钱半；朱砂二钱；牛黄一钱。〔主治〕治忧思过度、突然心惊跳动。〔方义〕归、地养血，黄连清心，菖蒲、远志、茯神安神，朱砂、牛黄镇心清心，为静神定惊之丹。〔制法·服法〕以猪心血为丸，黍米大，金箔十五片为衣，灯心汤送下五十丸。〔引文终〕（本条末引号与 条1017 起首引号相配，为《杂病广要》同段所引，照录。）"}, {"source": "条1020｜《麻疹备要方论·收没论治》·枣麦四物汤", "原文": "《麻疹备要方论·收没论治》：“如疹没后身虽不见瘦削，但时发壮热，烦躁不安，搐掣惊悸，神昏志乱者，此阴血虚耗，余毒入肝而传于心，宜枣麦四物汤主之。", "白话": "〔主治〕如麻疹收没之后，身体虽不见瘦削，但时时发作壮热、烦躁不安、抽掣惊悸、神昏志乱——这是阴血虚耗、余毒入肝而传于心，宜用枣麦四物汤主治。"}, {"source": "条1021｜《校注医醇賸义》卷二·大安汤", "原文": "《校注医醇賸义》卷二：“惊则气浮，真阳外越，真阴不守，心悸筋惕，大安汤主之大安汤自制。  \n白芍一钱五分，酒炒 五味子五分 牡蛎四钱，煅研 龙齿二钱 木瓜一钱，酒炒 枣仁二钱，炒研 熟地黄五钱 人参二钱 茯苓二钱 柏仁二钱 金器一具同煎  \n此方治惊，以龙、牡、金器镇其浮，以枣仁、白芍、五味、木瓜敛其越，人参、茯苓以益气，当归、柏仁以养血，乃心肝兼顾，神气同固之法也。祖怡注。", "白话": "〔病机〕惊则气浮，真阳外越，真阴不守，故见心悸、筋肉瞤惕。〔方名〕大安汤主治（大安汤为自制方）：〔组成·照录〕白芍一钱五分（酒炒），五味子五分，牡蛎四钱（煅研），龙齿二钱，木瓜一钱（酒炒），酸枣仁二钱（炒研），熟地黄五钱，人参二钱，茯苓二钱，柏仁二钱，金器一具同煎。〔方义〕此方治惊：以龙齿、牡蛎、金器镇其浮越，以酸枣仁、白芍、五味子、木瓜敛其外越，人参、茯苓益气，当归、柏仁养血，是心肝兼顾、神气同固之法。〔注〕祖怡注。"}, {"source": "条1022｜《经验良方全集》卷四·出痘形证（升麻葛根汤）", "原文": "《经验良方全集》卷四：“出痘形证。痘发时身热呕吐，体痛腹痛，烦躁喷嚏，惊悸昏倦……惊悸谵语妄视，小便通忌睡发汗，以后忌痰。已发热时，寒战、咬牙、惊悸者，勿虑，此毒欲出，与皮肉相撞也。如太甚，以升麻葛根汤一剂而愈。", "白话": "〔出痘形证〕痘疹发出时身热呕吐、体痛腹痛、烦躁喷嚏、惊悸昏倦……惊悸、谵语、妄见；小便已通者忌睡卧发汗，其后忌生痰之物。〔判断〕已发热之时，见寒战、咬牙、惊悸者不必忧虑——这是痘毒将出、与皮肉相撞击之故；如果太甚，用升麻葛根汤一剂即愈。"}, {"source": "条1023｜《经验良方全集》卷一·补心酒方", "原文": "《经验良方全集》卷一：“补心酒方。治怔忡，心神不宁。  \n麦冬去心，二两 柏子仁去油，一两 白茯神一两 归身一两 龙眼肉二两 生地黄一两五钱  \n盛绢袋中，入无灰酒十斤，坛内浸七日用，连坛煮亦可。", "白话": "〔方名〕补心酒方。〔主治〕治怔忡、心神不宁。〔组成·照录〕麦冬（去心）二两，柏子仁（去油）一两，白茯神一两，当归身一两，龙眼肉二两，生地黄一两五钱。〔方义〕麦冬、生地滋阴，归身、龙眼养血，茯神、柏仁安神，为补心养血之药酒。〔制法·服法〕盛入绢袋，放入无灰酒十斤，坛内浸七日可用；连坛隔水煮亦可。"}, {"source": "条1024｜《经验良方全集》卷一·荆沥", "原文": "《经验良方全集》卷一：“治心虚惊悸羸瘦者。  \n荆沥二升，水煎至一升六合，分作四服，日三次，夜一次。", "白话": "〔主治〕治心虚惊悸、身体消瘦者。〔组成·照录〕荆沥二升。〔方义〕荆沥甘寒，清热化痰、宁心定惊。〔制法·服法〕水煎至一升六合，分作四次服，白天三次、夜间一次。"}, {"source": "条1025｜《诊验医方歌括·中》·驯龙驭虎汤", "原文": "《诊验医方歌括·中》：“驯龙驭虎汤。喉舌作痛。驯龙驭虎真珠母，地黄斛玉沉香乳，蒌荷莲芍柏子霜，喉舌作痛惊悸愈。惊悸气促，喉舌作痛。  \n龙齿二钱 琥珀一钱 真珠母八钱 生地六钱 玉竹四钱 蒌皮三钱 石斛三钱 柏子霜二钱 白芍一钱五分 薄荷一钱 莲子二十粒，打碎，勿去心 沉香四分，人乳磨冲", "白话": "〔方名〕驯龙驭虎汤（方歌：驯龙驭虎真珠母，地黄斛玉沉香乳，蒌荷莲芍柏子霜，喉舌作痛惊悸愈）。〔主治〕喉舌作痛、惊悸气促。〔组成·照录〕龙齿二钱，琥珀一钱，真珠母八钱，生地六钱，玉竹四钱，蒌皮三钱，石斛三钱，柏子霜二钱，白芍一钱五分，薄荷一钱，莲子二十粒（打碎，勿去心），沉香四分（人乳磨冲）。〔方义〕龙齿、琥珀、真珠母镇心安神，生地、玉竹、石斛、白芍滋阴，蒌皮、薄荷、莲子、柏子霜清润利咽，沉香降气，为镇心滋阴、利咽定悸之剂。"}, {"source": "条1026｜《医学答问》卷四·七福饮", "原文": "《医学答问》卷四：“七福饮。治心血虚而惊悸者。  \n人参、熟地各三钱 当归、枣仁各二钱 白术炒一钱半 炙甘草五分 远志五分", "白话": "〔方名〕七福饮。〔主治〕治心血虚而惊悸者。〔组成·照录〕人参、熟地各三钱，当归、酸枣仁各二钱，白术（炒）一钱半，炙甘草五分，远志五分。〔方义〕参、术、草益气，熟地、当归、枣仁养血安神，远志开心气，为景岳七福饮（补气养血安神）之方。〔服法〕原稿未载煎服法，据组成为水煎服。"}, {"source": "条1027｜《医学衷中参西录·医方》·升陷汤", "原文": "《医学衷中参西录·医方》：“升陷汤。治胸中大气下陷，气短不足以息。或努力呼吸，有似乎喘。或气息将停，危在顷刻。其兼证，或寒热往来，或咽干作渴，或满闷怔忡，或神昏健忘，种种病状，诚难悉数。其脉象沉迟微弱，关前尤甚。其剧者，或六脉不全，或参伍不调。  \n生箭芪六钱 知母三钱 柴胡一钱五分 桔梗一钱五分 升麻一钱  \n气分虚极下陷者，酌加人参数钱，或再加山萸肉去净核数钱，以收敛气分之耗散，使升者不至复陷", "白话": "〔方名〕升陷汤。〔主治〕治胸中大气下陷：气短不足以息，或努力呼吸有似喘证，或气息将停、危在顷刻。其兼证或寒热往来，或咽干作渴，或胸满闷、怔忡，或神昏健忘——种种病状难以尽述。其脉象沉迟微弱，关前尤甚；病重者或六脉不全，或参伍不调。〔组成·照录〕生箭芪六钱，知母三钱，柴胡一钱五分，桔梗一钱五分，升麻一钱。〔方义〕黄芪为主升举胸中大气，知母凉润制芪之热，柴胡、升麻、桔梗载药上行，为升补大气之名方。〔加减〕气分虚极下陷者，酌加人参数钱，或再加去核山萸肉数钱，以收敛气分耗散，使升者不"}, {"source": "条1028｜《医学衷中参西录·医方》·安魂汤", "原文": "《医学衷中参西录·医方》：“安魂汤。治心中气血虚损，兼心下停有痰饮，致惊悸不眠。  \n龙眼肉六钱 酸枣仁四钱，炒捣 生龙骨五钱，捣末 生牡蛎五钱，捣末 清半夏三钱 茯苓片三钱 生赭石四钱，轧细  \n若服一两剂后无效者，可于服汤药之外，临睡时用开水送服西药臭剥一瓦，借其麻痹神经之力，以收一时之效，俾汤剂易于为力也。方书谓：痰饮停于心下，其人多惊悸不寐。盖心，火也，痰饮，水也，火畏水刑，故惊悸至于不寐", "白话": "〔方名〕安魂汤。〔主治〕治心中气血虚损，兼心下停有痰饮，以致惊悸不眠。〔组成·照录〕龙眼肉六钱，酸枣仁（炒，捣）四钱，生龙骨（捣末）五钱，生牡蛎（捣末）五钱，清半夏三钱，茯苓片三钱，生赭石（轧细）四钱。〔方义〕龙眼、枣仁养心血，龙骨、牡蛎、赭石重镇安神，半夏、茯苓化痰饮，为养血镇心、化痰安魂之剂。〔西说〕若服一两剂无效者，可在汤药之外，临睡时用开水送服西药“臭剥”一瓦（grain，格令），借其麻痹神经之力收一时之效，使汤剂易于为力。〔方论〕方书说：痰饮停于心下，其人多惊悸不寐"}, {"source": "条1029｜《医学衷中参西录·医方》·定心汤", "原文": "《医学衷中参西录·医方》：“定心汤。治心虚怔忡。  \n龙眼肉一两 酸枣仁五钱，炒捣 萸肉五钱，去净核 柏子仁四钱，炒捣 生龙骨四钱，捣细 生牡蛎四钱，捣细 生明乳香一钱 生明没药一钱  \n心因热怔忡者，酌加生地数钱，若脉沉迟无力者，其怔忡多因胸中大气下陷，详观拙拟升陷汤后跋语及诸案自明治法。", "白话": "〔方名〕定心汤。〔主治〕治心虚怔忡。〔组成·照录〕龙眼肉一两，酸枣仁（炒，捣）五钱，山萸肉（去净核）五钱，柏子仁（炒，捣）四钱，生龙骨（捣细）四钱，生牡蛎（捣细）四钱，生明乳香一钱，生明没药一钱。〔方义〕龙眼、枣仁、柏仁养心血，萸肉、龙骨、牡蛎收敛固摄，乳香、没药活血通络，为养心定怔之剂。〔加减〕因热而怔忡者，酌加生地数钱；若脉沉迟无力者，其怔忡多因胸中大气下陷——详看拙著升陷汤后跋语及诸医案自明治法。"}, {"source": "条1030｜《医学衷中参西录·医方》·清降汤", "原文": "《医学衷中参西录·医方》：“清降汤。治因吐衄不止，致阴分亏损，不能潜阳而作热，不能纳气而作喘。甚或冲气因虚上干，为呃逆、为眩晕。心血因虚甚不能内荣，为怔忡、为惊悸不寐。或咳逆、或自汗诸虚证蜂起之候。  \n生山药一两 清半夏三钱 净萸肉五钱 生赭石六钱，轧细 牛蒡子二钱，炒捣 生杭芍四钱 甘草钱半", "白话": "〔方名〕清降汤。〔主治〕治因吐血、鼻衄不止，以致阴分亏损：不能潜阳而发热，不能纳气而作喘；甚至冲气因虚上逆，为呃逆、为眩晕；心血因虚甚不能内养，为怔忡、为惊悸不寐；或咳逆、或自汗——诸虚证蜂起之候。〔组成·照录〕生山药一两，清半夏三钱，净萸肉五钱，生赭石（轧细）六钱，牛蒡子（炒，捣）二钱，生杭芍四钱，甘草一钱半。〔方义〕山药、萸肉、白芍滋阴敛阴，赭石降逆潜阳，半夏、牛蒡降气，甘草和中，为清热降逆、滋阴敛阳之剂。"}, {"source": "条1031｜《医学衷中参西录·医方》·清降汤（重出节录）", "原文": "《医学衷中参西录·医方》：“清降汤。心血因虚甚不能内荣，为怔忡、为惊悸不寐。或咳逆、或自汗诸虚证蜂起之候。  \n生山药一两 清半夏三钱 净萸肉五钱 生赭石六钱，轧细 牛蒡子二钱，炒捣 生杭芍四钱 甘草钱半", "白话": "〔方名〕清降汤（原稿节录重出）。〔主治〕心血因虚甚不能内养，为怔忡、为惊悸不寐；或咳逆、或自汗——诸虚证蜂起之候。〔组成·照录〕生山药一两，清半夏三钱，净萸肉五钱，生赭石（轧细）六钱，牛蒡子（炒，捣）二钱，生杭芍四钱，甘草一钱半。〔方义〕同 条1030 清降汤，滋阴降逆、敛阳安神。"}, {"source": "条1032｜《医学衷中参西录·医方》·理痰汤", "原文": "《医学衷中参西录·医方》：“理痰汤。治痰涎郁塞胸膈，满闷短气。或渍于肺中为喘促咳逆。停于心下为惊悸不寐。", "白话": "〔方名〕理痰汤。〔主治〕治痰涎郁塞胸膈，满闷短气；或浸渍于肺中而为喘促咳逆；停于心下而为惊悸不寐（组成原稿未载）。"}, {"source": "条1033｜《医学衷中参西录·医论》·滋阴清降汤", "原文": "《医学衷中参西录·医论》：“滋阴清降汤。治吐衄证失血过多，阴分亏损，不能潜阳而作热，不能纳气而作喘，甚或冲气因虚上干，为呃逆、眩晕、咳嗽，心血因不能内荣，为怔忡、惊悸、不寐，脉象浮数重按无力者。  \n生赭石八钱，轧细 生怀山药一两 生地黄八钱 生龙骨六钱，捣细 生牡蛎六钱，捣细 生杭芍四钱 甘草二钱 广三七细末，二钱，分两次，用头煎二煎之汤送服", "白话": "〔方名〕滋阴清降汤。〔主治〕治吐血、鼻衄失血过多，阴分亏损：不能潜阳而发热，不能纳气而作喘，甚至冲气因虚上逆，为呃逆、眩晕、咳嗽；心血因不能内养，为怔忡、惊悸、不寐，脉象浮数而重按无力者。〔组成·照录〕生赭石（轧细）八钱，生怀山药一两，生地黄八钱，生龙骨（捣细）六钱，生牡蛎（捣细）六钱，生杭芍四钱，甘草二钱，广三七细末二钱（分两次，用头煎二煎之汤送服）。〔方义〕山药、生地、白芍滋阴，赭石、龙骨、牡蛎清降潜镇，三七止血化瘀，为滋阴清降之剂。"}, {"source": "条1034｜《太医院秘藏膏丹丸散方剂》卷二·十香返魂丹", "原文": "《太医院秘藏膏丹丸散方剂》卷二：“十香返魂丹。\n伽南香、雄丁香、清木香、苏合油、檀香、降香、乳香、藿香、姜蚕炒，去丝嘴、天麻煨热、朱砂飞、郁金、建莲子心、栝蒌仁去净油、香附米童便、酒、醋、盐水，分为四次制、血珀以上各二两 安息香水，一两 麝香一两 礞石醋煅九次，二两 冰片五钱 诃子二两 牛黄一两  \n上各药俱研极细末，分量兑准，无有低昂。用甘草四两熬稠汁，对炼蜜为丸，每丸重一钱，金箔为衣……治夜梦", "白话": "〔方名〕十香返魂丹。〔组成·照录〕伽南香、雄丁香、清木香、苏合油、檀香、降香、乳香、藿香、姜蚕（炒，去丝嘴）、天麻（煨热）、朱砂（水飞）、郁金、建莲子心、栝蒌仁（去净油）、香附米（分四次以童便、酒、醋、盐水制）、血珀以上各二两；安息香水一两；麝香一两；礞石（醋煅九次）二两；冰片五钱；诃子二两；牛黄一两。〔方义〕十香诸药芳香开窍、理气化痰，天麻、姜蚕熄风，朱砂、血珀、金箔镇心，牛黄、冰片清心，为开窍醒神、镇心安神之丹。〔制法·服法〕上各药俱研极细末，分量配准；用甘草四两熬稠汁，"}, {"source": "条1035｜《太医院秘藏膏丹丸散方剂》卷二·防风通圣丸", "原文": "《太医院秘藏膏丹丸散方剂》卷二：“防风通圣丸。\n防风、大黄、白术、川芎、白芍、石膏、当归、荆芥、黄芩、栀子、桔梗、滑石、连翘各一两 麻黄五钱 薄荷七钱 朴硝七钱 甘草五钱  \n共为细末，水叠为丸，如梧桐子大。  \n治风热郁结，寒火相激，头目不清，咽喉不利，或疼或肿，发热发赤，咳嗽痰，溲便淋闭，舌强口噤，语言谵妄，瘫痪麻木，癫狂惊悸，伤风伤寒，感冒瘟疫时毒，肿毒初起，痈疽风刺瘾疹。此药发表通里，并皆", "白话": "〔方名〕防风通圣丸。〔组成·照录〕防风、大黄、白术、川芎、白芍、石膏、当归、荆芥、黄芩、栀子、桔梗、滑石、连翘各一两；麻黄五钱；薄荷七钱；朴硝七钱；甘草五钱。〔方义〕防风、麻黄、荆芥、薄荷解表，大黄、朴硝、滑石通里，石膏、黄芩、栀子、连翘清热，归、芎、芍和血，术、草健脾，为表里双解之剂。〔制法·服法〕共为细末，水泛为丸，梧桐子大。〔主治〕治风热郁结、寒火相激：头目不清，咽喉不利或疼或肿，发热发赤，咳嗽有痰，小便淋闭，舌强口噤，语言谵妄，瘫痪麻木，癫狂惊悸，伤风伤寒，感冒瘟疫时"}, {"source": "条1036｜《太医院秘藏膏丹丸散方剂》卷三·一捻金", "原文": "《太医院秘藏膏丹丸散方剂》卷三：“一捻金。  \n黑丑一钱 白丑一钱 槟榔一钱 大黄一钱 朱砂五分 赤金一张  \n共为细末。专治小儿一切风痰壅塞，口吐涎沫，胸高肺胀，喘满气促，咳嗽面黄，两胁扇动，陷下作坑，癫痫发抽，急惊上视，鼻窍开张，精神烦乱，声哑不鸣，痰涎壅盛，夜卧惊悸，发渴潮热，肚腹膨胀，不思饮食等症。每服四五分，量大小用之，引蜂蜜少许，无根水调服。", "白话": "〔方名〕一捻金。〔组成·照录〕黑丑一钱，白丑一钱，槟榔一钱，大黄一钱，朱砂五分，赤金一张。〔方义〕黑丑、白丑（牵牛子）泻下逐痰，槟榔、大黄导滞通便，朱砂、赤金镇惊，为攻逐痰滞之小儿散剂。〔制法·服法〕共为细末。〔主治〕专治小儿一切风痰壅塞：口吐涎沫，胸高肺胀，喘满气促，咳嗽面黄，两胁扇动，胸骨下陷作坑，癫痫抽搐，急惊上视，鼻孔张开，精神烦乱，声哑不出，痰涎壅盛，夜卧惊悸，口渴潮热，肚腹膨胀，不思饮食等证。每服四五分，按年龄大小增减，以蜂蜜少许、无根水调服。"}, {"source": "条1037｜《太医院秘藏膏丹丸散方剂》卷四·滋血养心丸", "原文": "《太医院秘藏膏丹丸散方剂》卷四：“滋血养心丸。\n当归五钱，酒洗 白茯神四钱 白芍四钱，酒洗 远志四钱 天冬四钱，去心 麦门冬四钱，去心 酸枣仁三钱，炒 苦芩三钱，酒炒 柴胡三钱，酒炒 红花一钱，酒洗 沙参二钱 黑参二钱 黄连三钱，姜汁炒 柏子仁三钱 甘草二钱，生  \n上为细末，蜜水为丸，如梧桐子大。每服一钱五分或二钱，食远用灯心汤送下。此药用治心气不足，精神恍惚，夜卧不安，怔忡健忘，异梦多惊，心跳", "白话": "〔方名〕滋血养心丸。〔组成·照录〕当归（酒洗）五钱，白茯神四钱，白芍（酒洗）四钱，远志四钱，天冬（去心）四钱，麦门冬（去心）四钱，酸枣仁（炒）三钱，苦芩（酒炒）三钱，柴胡（酒炒）三钱，红花（酒洗）一钱，沙参二钱，黑参二钱，黄连（姜汁炒）三钱，柏子仁三钱，生甘草二钱。〔方义〕归、芍、二冬、二参滋血养阴，枣仁、柏仁、茯神、远志养心安神，芩、连清火，柴胡疏达，红花和血，为滋血养心之丸。〔制法·服法〕上为细末，蜜水为丸，梧桐子大；每服一钱五分或二钱，食远以灯心汤送下。〔主治〕治心气不"}, {"source": "条1038｜《增订通俗伤寒论·第一编》·四逆散", "原文": "《增订通俗伤寒论·第一编》：“太阴兼证：兼心经证，神烦而悸，汗出津津，似寐非寐，或不得卧；兼肝经证，心中痛热，饥不欲食，食即呕酸吐苦，胸胁满疼，甚则霍乱吐泻。故惟唯厥冷而或咳或悸，腹痛下重，是阳为阴遏之利，用四逆散。", "白话": "〔主治〕太阴兼证：兼心经证者，神烦而心悸，汗出津津，似睡非睡，或不得安卧；兼肝经证者，心中痛而热，饥而不欲食，食入即呕酸吐苦，胸胁满痛，甚则上吐下泻。所以只见四肢厥冷而或咳或悸、腹痛下重的，是阳气被阴邪郁遏之证，用四逆散。"}, {"source": "条1039｜《增订通俗伤寒论·第三编》·正诚露珠丹", "原文": "《增订通俗伤寒论·第三编》：“又次用正诚露珠丹透明辰砂一两，以瓷器盛，露四十九夜，猪心中血，丝绵绞去滓，用净血三两，每次一个，拌砂晒干，再拌再晒，三个用讫，再研极细，加西牛黄一钱，共研匀细，用糯米糊和捣万杵为丸，每重七分，阴干得五分，瓷瓶密收。夜卧时噙化一丸，治殚虑劳神，火升痰壅，心悸不寐，遇事善忘等证，最效，善其后以防复发。", "白话": "〔方名〕正诚露珠丹。〔制法〕取透明辰砂一两，用瓷器盛，露天晾四十九夜；取猪心内血，以丝绵绞去渣滓，用净血三两，每次取一个猪心之血拌辰砂晒干，再拌再晒，三个猪心用完后，再研极细；加西牛黄一钱，共研匀细，用糯米糊和捣万杵为丸，每丸重七分，阴干后得五分，瓷瓶密收。〔服法〕夜卧时噙化一丸。〔主治〕治殚虑劳神、火升痰壅、心悸不寐、遇事善忘等证，最效，并善其后以防复发。"}, {"source": "条1040｜《陈氏幼科秘诀·痫》·小红丸", "原文": "《陈氏幼科秘诀·痫》：“儿有热痰，一不饮乳，眠睡不稳，常时惊悸，即用小红丸，减其盛气为妙。", "白话": "〔主治〕小儿有热痰，完全不吃奶，睡眠不安，时常惊悸——即用小红丸，减其壅盛之气为妙。"}, {"source": "条1041｜《家传女科经验摘奇·补母益子论》·补母益子方", "原文": "《家传女科经验摘奇·补母益子论》：“补母益子方。治屡产生子无气，或育而不寿。又补气血虚弱人，孕成不安，或得孕数堕。用此方每服十五帖，弱甚者日服一帖，大益胎而分娩易，又生子精神而有寿也。  \n人参一钱，弱者二、三钱 川归二钱 白术二钱，生用 川芎八分 淮熟地二钱 陈皮、紫苏、炙甘草各四分 条芩一钱  \n虚肥人：陈皮去白，加黄连五分、枣三枚、姜一片煎服……怔忡惊悸，加枣仁、益智各一钱，圆眼十个。", "白话": "〔方名〕补母益子方。〔主治〕治屡次生产而生子无气，或养育而不长寿；又补气血虚弱之人，怀孕后胎元不安，或孕而屡堕。用此方每服十五帖，虚弱甚者日服一帖，大能有益于胎儿而分娩容易，所生孩子精神充沛而长寿。〔组成·照录〕人参一钱（弱者二三钱），川当归二钱，白术（生用）二钱，川芎八分，淮熟地二钱，陈皮、紫苏、炙甘草各四分，条芩一钱。〔方义〕参、术、归、芎、地益气养血，条芩、紫苏安胎，陈皮理气，为补母益子之安胎方。〔加减〕虚胖之人：陈皮去白，加黄连五分、大枣三枚、姜一片煎服……（原稿节略"}, {"source": "条1042｜《家传女科经验摘奇·产后血崩》·滋荣益气汤", "原文": "《家传女科经验摘奇·产后血崩》：“滋荣益气汤。治崩止血。\n川芎、麦冬、黄芪各一钱 人参、川归、淮生地、白术各二钱 陈皮、甘草炙，各四分 白芷、荆芥、升麻各四分 黄连三分，退心火 枣三枚  \n水煎。汗多加麻黄根一钱，浮小麦一撮……惊悸，加酸枣仁、柏子仁各一钱。", "白话": "〔方名〕滋荣益气汤。〔主治〕治血崩，止血。〔组成·照录〕川芎、麦冬、黄芪各一钱；人参、川当归、淮生地、白术各二钱；陈皮、甘草（炙）各四分；白芷、荆芥、升麻各四分；黄连三分（退心火）；大枣三枚。〔方义〕参、芪、术益气摄血，归、芎、地、麦冬滋营养血，升麻、荆芥、白芷升举，黄连清心，为止崩养荣之剂。〔服法〕水煎服。〔加减〕汗多加麻黄根一钱、浮小麦一撮……（原稿节略）；惊悸加酸枣仁、柏子仁各一钱。"}, {"source": "条1043｜《太医院秘藏膏丹丸散方剂》卷二·防风通圣丸（表里双解剂节重出）", "原文": "（原稿本条前有节题两行：“表里双解剂”“防风通圣丸”）《太医院秘藏膏丹丸散方剂》卷二：防风通圣丸。\n防风、大黄、白术、川芎、白芍、石膏、当归、荆芥、黄芩、栀子、桔梗、滑石、连翘各一两 麻黄五钱 薄荷七钱 朴硝七钱 甘草五钱  \n共为细末，水叠为丸，如梧桐子大。  \n治风热郁结，寒火相激，头目不清，咽喉不利，或疼或肿，发热发赤，咳嗽痰，溲便淋闭，舌强口噤，语言谵妄，瘫痪麻木，癫狂惊悸，伤风伤寒，感冒", "白话": "〔出处〕原稿此条前有节题「表里双解剂」「防风通圣丸」，标示转入新类目。〔方名〕防风通圣丸（与 条1035 同方重出，本条无引号、为节题下重录）。〔组成·照录〕防风、大黄、白术、川芎、白芍、石膏、当归、荆芥、黄芩、栀子、桔梗、滑石、连翘各一两；麻黄五钱；薄荷七钱；朴硝七钱；甘草五钱。〔方义〕表里双解：解表通里、清热和血。〔制法·服法〕共为细末，水泛为丸，梧桐子大。〔主治〕治风热郁结、寒火相激：头目不清，咽喉不利或疼或肿，发热发赤，咳嗽有痰，小便淋闭，舌强口噤，语言谵妄，瘫痪麻木"}, {"source": "条1｜《神农本草经·上品》·人参", "原文": "《神农本草经·上品》：“味甘，微寒。主补五脏，安精神，定魂魄，止惊悸，除邪气，明目、开心、益智。久服，轻身、延年。一名人衔，一名鬼盖。生山谷。", "白话": "味甘，性微寒。主治补益五脏，安定精神，安定魂魄，止惊悸，祛除邪气，明目、开窍益智。久服，身体轻健、延年益寿。又名人衔，又名鬼盖。产于山谷。"}, {"source": "条2｜《本草经集注·草木上品》·人参", "原文": "《本草经集注·草木上品》：“味甘，微寒、微温，无毒。主补五藏五脏，安精神，定魂魄，止惊悸，除邪气，明目，开心益智，治肠胃中冷，心腹鼓痛，胸胁逆满，霍乱吐逆，调中，止消渴，通血脉，破坚积，令人不忘。久服轻身延年。一名人衔，一名鬼盖，一名神草，一名人微，一名土精，一名血参。如人形者有神。", "白话": "味甘，微寒、微温，无毒。主治补益五脏，安定精神，安定魂魄，止惊悸，祛除邪气，明目，开窍益智，治肠胃中冷，心腹胀痛，胸胁逆满，霍乱呕吐，调和中焦，止消渴，通血脉，破除坚积，使人不忘事。久服身体轻健、延年益寿。又名人衔、鬼盖、神草、人微、土精、血参。根形如人的有神效。"}, {"source": "条3｜《本草发挥·草部》·人参", "原文": "《本草发挥·草部》：“味甘，微温，无毒。主补五脏，安精神，定魂魄，止惊悸，除邪气、霍乱、吐逆，调中，止消渴，通血脉。", "白话": "味甘，微温，无毒。主治补益五脏，安定精神，安定魂魄，止惊悸，祛除邪气、霍乱、呕吐，调和中焦，止消渴，通血脉。"}, {"source": "条4｜《本草集要·草部上》·人参", "原文": "《本草集要·草部上》：“味甘、气温、微寒，气味俱轻，阳也。阳中微阴，无毒。……主补五脏，安精神，定魂魄，止惊悸，除邪气，明目开心益志，调中生津，通血脉。", "白话": "味甘、气温、微寒，气味俱轻，属阳。阳中微阴，无毒。……主治补益五脏，安定精神，安定魂魄，止惊悸，祛除邪气，明目开心益智，调和中焦、生津液，通血脉。"}, {"source": "条5｜《本草蒙筌·草部上》·人参", "原文": "《本草蒙筌·草部上》：“健脉理中，生津止渴。开心益志，明目轻身。却惊悸，除梦邪，消胸胁逆满；养精神，安魂魄，苏心腹鼓疼。肠胃积冷温平，霍乱吐泻止息。定喘嗽，通畅血脉，泻阴火。", "白话": "使脉道健旺、调理中焦，生津止渴。开窍益智，明目轻身。祛惊悸，除梦邪，消除胸胁逆满；养精神，安魂魄，缓解心腹胀疼。肠胃积冷者温而平之，霍乱吐泻得以止息。定喘止嗽，通畅血脉，泻阴火。"}, {"source": "条6｜《本草汇言·草部山草部》·人参", "原文": "《本草汇言·草部山草部》：“味甘、微苦，气温，无毒。入肺脾二经。补气生血，助津养神之药也。故真气衰弱，短促虚喘，以此补之。如荣卫空虚，用之可治也。精神散乱，魂魄飞扬，以此敛之。如阳亡阴脱，用之可回也。惊悸怔忡，健忘恍惚，以此宁之……", "白话": "味甘、微苦，气温，无毒。入肺脾二经。是补气生血、助津养神的药。所以真气衰弱、气短虚喘，用它来补；如营卫空虚，用它可以治。精神散乱、魂魄浮越，用它来收敛；如阳亡阴脱，用它可以挽回。惊悸怔忡、健忘恍惚，用它来安宁……"}, {"source": "条7｜《本草详节·草部》·人参", "原文": "《本草详节·草部》：“味甘、苦，气微温，一云微寒。气味俱薄，浮而升，阳也；一云阳中微阴。……主补五脏，安精神，健脉理中，生津止渴，除梦邪惊悸，补肺胃中阳气不足，泻心、肺、脾、胃中伏火，治肺痿、胸痰、呕哕、反胃、痎疟、痫疾，冷气逆上、心腹鼓痛、胸胁逆满、霍乱、泻痢、小便频数、淋沥、劳倦内伤、中风中暑，又及一切血证、胎前产后、一切虚证、发热自汗。", "白话": "味甘、苦，气微温，一说微寒。气味俱薄，浮而升，属阳；一说阳中微阴。……主治补益五脏，安定精神，健脉理中，生津止渴，除梦邪惊悸，补肺胃中阳气不足，泻心、肺、脾、胃中伏火，治肺痿、胸中痰、呕哕、反胃、痎疟、痫疾，冷气上逆、心腹胀痛、胸胁逆满、霍乱、泄泻痢疾、小便频数、淋沥、劳倦内伤、中风中暑，又及一切血证、胎前产后、一切虚证、发热自汗。"}, {"source": "条8｜《本草备要·草部》·人参", "原文": "《本草备要·草部》：“益土、健脾。生金，补肺。明目，开心益智，添精神，定惊悸，邪火退，正气旺，则心肝宁而惊悸定。除烦渴，泻火故除烦、生津故止渴。通血脉，气行则血行，贺汝瞻曰：生脉散用之者，以其通经活血，则脉自生也，古方解散药、行表药多用之，皆取其通经而走表也。破坚积，气运则积化。消痰水，气旺则痰行水消。", "白话": "益土健脾（脾属土），生金补肺（肺属金）。明目，开心益智，添精神，定惊悸；邪火退、正气旺，心肝得宁而惊悸自定。除烦渴——泻火所以除烦，生津所以止渴。通血脉——气行则血行；贺汝瞻说：生脉散用人参，是取其通经活血，血脉就自能生；古方解散药、行表药多用它，都取其通经而走表。破坚积——气运则积聚化。消痰水——气旺则痰行水消。"}, {"source": "条9｜《滇南本草·土千年健》·土千年健", "原文": "《滇南本草·土千年健》：“味酸，性温。治寒湿伤筋。此药能舒经活络，筋挛骨痛，痰火痿软，半身不遂，手足顽麻，脚痛。酒为使，神效……怔忡睡卧不宁者，采子煎服立瘥。", "白话": "味酸，性温。治寒湿伤筋。此药能舒经活络，治筋挛骨痛、痰火所致痿软、半身不遂、手足顽麻、脚痛。以酒为使药，效如神……患怔忡、睡卧不宁的，采其子煎服，立即痊愈。"}, {"source": "条10｜《神农本草经·上品》·大枣", "原文": "《神农本草经·上品》：“味甘，平。主心腹邪气，安中养脾，肋十二经，平胃气，通九窍，补少气、少津液、身中不足，大惊，四肢重，和百药。久服，轻身、长年。叶覆麻黄，能令出汗。生平泽。", "白话": "味甘，性平。主治心腹邪气，安和中焦、滋养脾胃，助益十二经，平和胃气，通利九窍，补气少、津液少及身体不足，治大惊、四肢沉重，调和诸药。久服，身体轻健、延年。用叶覆盖麻黄，能使人出汗。产于平原水泽。"}, {"source": "条11｜《千金食治·果实第二》·大枣", "原文": "《千金食治·果实第二》：“枣：味甘、辛、热、滑、无毒。主心腹邪气，安中养脾气，助十二经，平胃气；通九窍；补少气，少津液，身中不足；大惊；四肢重；可和百药，补中益气，强志，除烦闷，心下悬，治肠澼。久服轻身，长年不饥，神仙。", "白话": "枣：味甘、辛、热、滑，无毒。主治心腹邪气，安中养脾气，助十二经，平胃气；通九窍；补气少、津液少、身体不足；治大惊；四肢沉重；可调和诸药，补中益气，强志，除烦闷、心下悬空感，治肠澼。久服身体轻健，长年不饥，可至神仙。"}, {"source": "条12｜《修真秘录·食宜篇》·大枣", "原文": "《修真秘录·食宜篇》：“味甘辛温。主心服邪气，安中，养脾气，助十二经脉，通九窍，补少津液、大惊、强志，久服轻身延年，不饥成仙。", "白话": "味甘辛温。主治心腹邪气（“心服”为“心腹”之讹），安中，养脾气，助十二经脉，通九窍，补津液不足、治大惊、强志，久服轻身延年，不饥而成仙。"}, {"source": "条13｜《医学入门·果部》·大枣", "原文": "《医学入门·果部》：“甘温和胃脾，肠澼癖气故能医，润心肺令神液足，助十二经百药宜，生枣甘辛动湿热，令人胀泄瘦人肌。无毒。降也，阳也。养脾平胃，安中，补中益气。治四肢重及肠澼下痢，肠胃间癖气，一切心腹邪气，更疗心悬大惊烦闷。壮神润肺，止嗽，补津液，补气。", "白话": "甘温而和胃脾，肠澼癖气所以能治，润心肺使神液充足，助十二经、宜和百药；生枣甘辛能动湿热，使人腹胀泄泻、消瘦。无毒。性降，属阳。养脾平胃，安中，补中益气。治四肢沉重及肠澼下痢、肠胃间癖气、一切心腹邪气，更疗心下悬、大惊烦闷。壮神润肺，止嗽，补津液，补气。"}, {"source": "条14｜《本草汇言·果部果类》·大枣", "原文": "《本草汇言·果部果类》：“味甘，气温，无毒。气味俱厚，可升可降，阳也。入手少阴、太阴经……如龙潭方：治惊悸怔忡，健忘恍惚，志意昏迷，精神不守，或中气不和，饮食无味，四体懒重，肌肉羸瘦，此属心脾二脏元神亏损之证，必用大枣治之。", "白话": "味甘，气温，无毒。气味俱厚，可升可降，属阳。入手少阴（心）、太阴（肺脾）经……如龙潭方所治：惊悸怔忡，健忘恍惚，意志昏迷，精神不能守藏，或中气不和、饮食无味、四肢懒重、肌肉消瘦——这属于心脾二脏元神亏损之证，必用大枣治疗。"}, {"source": "条15｜《本草集要·草部下》·大黄", "原文": "《本草集要·草部下》：“大黄……号称将军。取其荡涤峻快也。又敷贴一切疮疖痈肿。酒浸引之，上至巅颠，入太阳经。以舟楫载之可浮胸中。若用于下，不用酒浸洗。得芍药、黄芩、牡蛎、细辛、茯苓，疗惊恙怒，心下悸气。得硝石、紫石英、桃仁，疗女子血闭。", "白话": "大黄……号称将军，取其荡涤峻猛快捷之意。又可外敷一切疮疖痈肿。酒浸可引药上至巅顶，入太阳经；用舟楫（载药上行之品）载之可浮于胸中。若用于攻下，不必酒浸洗。配芍药、黄芩、牡蛎、细辛、茯苓，疗惊恙易怒、心下悸气；配硝石、紫石英、桃仁，疗女子血闭。"}, {"source": "条16｜《药性赋·草部上》·山药", "原文": "《药性赋·草部上》：“薯蓣，俗名山药。味甘、温、平。无毒。补心气不足，镇心神。", "白话": "薯蓣，俗名山药。味甘，性温、平。无毒。补心气不足，镇心安神。"}, {"source": "条17｜《本草汇言·菜部柔滑类》·山药", "原文": "《本草汇言·菜部柔滑类》：“养脾胃，益心肺，滋肾阴之药也。按（邵起寰抄）方龙潭言甘能和脾，甘能补肝，甘能除大热，甘能益阴气。如六味丸，所以用此以滋阴也。如脾弱泄泻，久痢肠滑养脾胃，如惊悸怔忡，健忘恍惚益心气，如皮肤惟唯悴，干咳无痰益肺气，如梦泄遗精，腰膝痿弱滋肾阴，必须此药治之。", "白话": "是养脾胃、益心肺、滋肾阴的药。按语（邵起寰抄本）：方龙潭说甘能和脾，甘能补肝，甘能除大热，甘能益阴气。如六味丸就用它来滋阴。如脾弱泄泻、久痢肠滑，用之养脾胃；如惊悸怔忡、健忘恍惚，用之益心气；如皮肤憔悴、干咳无痰，用之益肺气；如梦泄遗精、腰膝痿弱，用之滋肾阴——都必须用此药治疗。"}, {"source": "条18｜《雷公炮制药性解·草部上》·山药", "原文": "《雷公炮制药性解·草部上》：“山药，味甘，性温，无毒，入脾、肺、肾三经。补阴虚，消肿硬，健脾气，长肌肉，强筋骨，疗干咳，止遗泄，定惊悸，除泻痢。乳制用。紫芝为使，喜门冬，恶甘遂。", "白话": "山药，味甘，性温，无毒，入脾、肺、肾三经。补阴虚，消肿硬，健脾气，长肌肉，强筋骨，疗干咳，止遗精滑泄，定惊悸，除泄泻痢疾。用乳制法炮制。紫芝为使药，喜与麦门冬同用，恶甘遂。"}, {"source": "条19｜《得配本草·菜部柔滑类》·山药", "原文": "《得配本草·菜部柔滑类》：“甘，平，入手足太阴经血分，兼入足少阴经气分。补脾阴，调肺气，治虚热干咳，遗精泄泻，游风眼眩，惊悸健忘。生者捣敷疮毒，能消肿硬。", "白话": "味甘，性平，入手足太阴经血分，兼入足少阴经气分。补脾阴，调肺气，治虚热干咳、遗精泄泻、游风眼眩、惊悸健忘。生品捣敷疮毒，能消肿硬。"}, {"source": "条20｜《神农本草经·上品》·川芎", "原文": "《神农本草经·上品》：“蘼芜，味辛，温。主咳逆，定惊气，辟邪恶，除蛊毒鬼注，去三虫，久服通神。一名薇芜。生川泽。", "白话": "蘼芜（川芎苗），味辛，性温。主治咳逆，定惊气，辟除邪恶，除蛊毒鬼注，去三虫，久服通神。又名薇芜。产于川泽。"}, {"source": "条21｜《本草正·竹木部》·天竺黄", "原文": "《本草正·竹木部》：“味甘辛，性凉，降也。阴中有阳。善开风痰，降热痰，治中风失音，痰滞胸膈，烦闷癫痫。清心火，镇心气，醒脾疏肝。明眼目，安惊悸。疗小儿风痰急惊客忤，其性和缓，最所宜用。亦治金疮并内热药毒。", "白话": "味甘辛，性凉，主降。阴中有阳。善于开泄风痰、降泄热痰，治中风失音、痰滞胸膈、烦闷癫痫。清心火，镇心气，醒脾疏肝。明目，安惊悸。疗小儿风痰急惊、客忤，其性和缓，最宜用。又治金疮及内热药毒。"}, {"source": "条22｜《杂症痘疹药性主治合参·木部 》·天竺黄", "原文": "《杂症痘疹药性主治合参·木部 》：“天竺黄，一名竹膏。产于天竺国，乃竹之精气结成。其气味功用与竹沥相仿，但竺黄气微寒，性亦稍缓，故为小儿要药，入手少阴经，专为清热养心化痰，安惊之需，久用亦能寒中。天竺黄，治小儿天吊惊痫。大人中风不语，镇心明目，解热驱邪，豁痰利窍，除热养心，滋养五脏，金疮风热。主治痘疹合参主痰壅失音明目，去风湿惊悸镇心，滋养五脏，小儿最宜，和缓故也。", "白话": "天竺黄，又名竹膏。产于天竺国，是竹的精气结成。其气味功用与竹沥相仿，但竺黄气微寒，性也稍缓，所以是小儿要药，入手少阴经，专供清热养心化痰、安惊之用；久用也能寒伤中焦。天竺黄治小儿天吊惊痫；大人中风不语，能镇心明目、解热驱邪、豁痰利窍、除热养心、滋养五脏，治金疮风热。痘疹合参项下主治：痰壅失音，明目，去风湿惊悸、镇心，滋养五脏——小儿最宜，因其性和缓。"}, {"source": "条23｜《珍珠囊补遗药性赋·草部下》·天南星", "原文": "《珍珠囊补遗药性赋·草部下》：“专能下气，风痰脑痛止怔忡。", "白话": "专能下气，治风痰脑痛，止怔忡。"}, {"source": "条24｜《药论·降痰》·天南星", "原文": "《药论·降痰》：“南星入肝，治口眼喎斜与肢体麻痹不遂，疗牙关紧急与心神昏迷难清。小儿惊搐如神，女子妊娠须忌。固宜于目晕头眩，尤妙于耳鸣心悸。燥湿消痰，功逾半夏。半夏味辛而守，南星性烈而走。故须牛胆一制，庶几燥烈全收。", "白话": "南星入肝，治口眼歪斜与肢体麻痹不遂，疗牙关紧急与心神昏迷难以清醒。治小儿惊搐如神，女子妊娠须忌用。本宜于目眩头晕，尤妙在治耳鸣心悸。燥湿消痰，功效超过半夏。半夏味辛而守而不走，南星性烈而走窜。故须用牛胆制过，方使其燥烈之性尽收。"}, {"source": "条25｜《药性本草约言卷之一·天麻》·天麻", "原文": "《药性本草约言卷之一·天麻》：“味辛、甘，气平，无毒，阳也，升也。疗大人风热头眩，治小儿风痫惊悸，祛风麻痹不仁，主瘫痪语言不遂。", "白话": "味辛、甘，气平，无毒，属阳，主升。疗大人风热头眩，治小儿风痫惊悸，祛风治麻痹不仁，主瘫痪、语言不遂。"}, {"source": "条26｜《本草蒙筌·草部上》·天麻", "原文": "《本草蒙筌·草部上》：“味辛、苦，气平。无毒。春初始生苗叶，仿佛芍药成丛。中起梗二三尺高，因名赤箭；下发根王瓜般大，此谓天麻。郓利二州并属山东，山谷俱有。秋月采取，乘润刮皮。略煮沸汤，曝干入药。治小儿风痫惊悸，疗大人风热头眩。驱湿痹拘挛，主瘫痪蹇滞。通血脉开窍，利腰膝强筋。诸毒痈疽，并堪调愈。", "白话": "味辛、苦，气平。无毒。春初生苗叶，仿佛芍药成丛。中间起梗二三尺高，故名赤箭；下生根如王瓜大，这叫天麻。郓、利二州同属山东，山谷俱有。秋天采挖，趁润刮皮。稍煮于沸汤，晒干入药。治小儿风痫惊悸，疗大人风热头眩。驱湿痹拘挛，主瘫痪、行步蹇滞。通血脉开窍，利腰膝强筋。各种毒肿痈疽，也都能调理治愈。"}, {"source": "条27｜《杂症痘疹药性主治合参·草部上》·天麻", "原文": "《杂症痘疹药性主治合参·草部上》：“天麻，治小儿风痫惊悸，大人风热头眩，驱湿痹拘挛，主瘫痪语塞，疏痰气通血脉，开窍除风湿，利腰膝强筋，搜风润燥，益气强阴，为肝经治风之神剂，有自内达外之功。", "白话": "天麻治小儿风痫惊悸，大人风热头眩，驱湿痹拘挛，主瘫痪语塞，疏痰气、通血脉，开窍除风湿，利腰膝、强筋骨，搜风润燥，益气强阴，是肝经治风的神效之药，有自内达外的功效。"}, {"source": "条28｜《本草备要·草部》·木香", "原文": "《本草备要·草部》：“宣，行气。辛苦而温。三焦气分之药，能升降诸气，泄肺气，疏肝气，和脾气（怒则肝气上，肺气调，则金能制木而肝平，木不克土而脾和）。治一切气痛，九种心痛（皆属胃脘，曰寒痛、热痛、气痛、血痛、湿痛、痰痛、食痛、蛔痛、悸痛。盖君心不易受邪，真心痛者手足冷过腕节，朝发夕死）……", "白话": "宣散，行气。辛苦而温。是三焦气分之药，能升降诸气，泄肺气，疏肝气，和脾气（发怒则肝气上逆，肺气调畅，则金能制木而肝气平，木不克土而脾气和）。治一切气痛、九种心痛（都属胃脘部位，即寒痛、热痛、气痛、血痛、湿痛、痰痛、食痛、蛔痛、悸痛。心为君主不易受邪，真心痛者手足冷过腕关节，朝发夕死）……"}, {"source": "条29｜《雷公炮制药性解·草部中》·木通", "原文": "《雷公炮制药性解·草部中》：“木通，味辛、甘，性平，无毒，入小肠经。主五淋，小便闭，经凝，乳闭，难产，积聚，惊悸，心烦，健忘，耳聋，声哑，鼻塞，痈疮，脾疸喜睡，天行瘟疫。按：木通利便，专泻小肠，宜疗五淋等证。其惊悸等证，虽属心经，而心与小肠相为表里，故并治之。脾疸喜睡，此脾之病，皆湿所酿也，利小肠而湿不去乎？瘟疫之来，感天地不正之气，今受盛之官行，而邪不能容，亦宜疗矣。", "白话": "木通，味辛、甘，性平，无毒，入小肠经。主治五淋、小便闭、经血凝滞、乳汁不通、难产、积聚、惊悸、心烦、健忘、耳聋、声哑、鼻塞、痈疮、脾疸善睡、天行瘟疫。按语：木通利小便，专泻小肠，宜治五淋等证。惊悸等证虽属心经，而心与小肠相为表里，故一并可治。脾疸善睡是脾的病，皆湿所酿成——利小肠而湿岂有不去之理？瘟疫之来是感受天地不正之气，今使受盛之官（小肠）通行，邪不能容留，也宜治疗。"}, {"source": "条30｜《杂症痘疹药性主治合参·草部上》·木通", "原文": "《杂症痘疹药性主治合参·草部上》：“木通，甘淡轻虚，上通心包，降心火，清肺热，泻小便火郁不散，利膀胱水闭不行，消痈疽作痛，疗脾疽嗜眠，解烦哕，开耳聋，出声音，通鼻塞，行经下乳，催产堕胎，开关导格湿热，利关节血脉，通九窍五淋，乃心胞、小肠、膀胱三经之药。凡肺受热邪，则气化之源绝而寒水断流，宜此甘淡以助秋气下降。若君火为邪，宜用木通，相火为邪，宜用泽泻。但性寒通利，凡精滑气虚，内无湿热，并虚症孕妇，并", "白话": "木通，甘淡轻虚，上通心包，降心火，清肺热，泻小便火郁不散，利膀胱水闭不行，消痈疽作痛，疗脾疽嗜眠，解烦除哕，开耳聋，出声音，通鼻塞，行经下乳，催产堕胎，开通关格湿热，利关节血脉，通九窍、治五淋，是心包、小肠、膀胱三经之药。凡肺受热邪，则气化之源断绝而寒水断流，宜用此甘淡以助秋气下降。若君火为邪，宜用木通；相火为邪，宜用泽泻。但性寒通利，凡精滑气虚、内无湿热，以及虚证孕妇，都宜忌用。主治利水泻火，宣通气血。凡热闭不通、心经蕴热惊悸的，用它泻心经邪热，从膀胱而出，与灯心草同功。"}, {"source": "条31｜《本草征要·（三）补阴》·太子参", "原文": "《本草征要·（三）补阴》：“太子参，又名孩儿参。味甘、微苦，性平，无毒。入脾、肺二经。益气健脾，生津养肺。气血不足，病后虚羸。倦怠乏力，自汗萎靡。食少心悸，口干液亏，用以调补，能使春回。", "白话": "太子参，又名孩儿参。味甘、微苦，性平，无毒。入脾、肺二经。益气健脾，生津养肺。治气血不足、病后虚弱消瘦、倦怠乏力、自汗萎靡、食少心悸、口干津亏——用以调补，能使生机回春。"}, {"source": "条32｜《本草汇言·草部山草类》·升麻", "原文": "《本草汇言·草部山草类》：“……但属阳性升，凡吐血、衄血、咳嗽、气急，阴虚火动，及气逆呕吐，怔忡癫狂等证，一切禁用。", "白话": "……但本品属阳、性主升，凡吐血、衄血、咳嗽、气急、阴虚火动，以及气逆呕吐、怔忡癫狂等证，一概禁用。"}, {"source": "条33｜《滇南本草·丹参》·丹参", "原文": "《滇南本草·丹参》：“丹参，味微苦，性微寒。色赤象火。入心经。补心，生血，养心，定志，安神宁心，健忘怔忡，惊悸不寐，生新血，去瘀血，安生胎，落死胎。一味可抵四物汤补血之功。", "白话": "丹参，味微苦，性微寒。色赤象征火。入心经。补心、生血、养心、定志、安神宁心，治健忘怔忡、惊悸不寐，生新血、去瘀血，安生胎、下死胎。单味一味可抵四物汤补血之功。"}, {"source": "条34｜《滇南本草·双尾参》·双尾参", "原文": "《滇南本草·双尾参》：“气味甘、甜，性微寒。无毒。专治男妇老幼一切风痰昏迷，五癫或怔忡，如有人捕捉之状。久服，消痰镇惊，安神定魄，用之效。即气癫、色癫可解。一治妇人生一胎后，久不生产。服之暖宫，调血，顺经，亦可妊也。一治 HYPERLINK &quot;http://mip.wiki8.com/taiqian_7866/&quot; \\o &quot;医学百科：胎前&quot; 胎前产后， HYP", "白话": "气味甘甜，性微寒。无毒。专治男女老幼一切风痰昏迷、五癫或怔忡（心慌如有人捕捉之状）。久服消痰镇惊、安神定魄，用之有效，即气癫、色癫也可解。其一，治妇人生一胎后久不再孕：服之暖宫、调血、顺经，也可以受孕。其一，治胎前产后血积冲心，神效。采叶治小儿惊风（即七日内外之证），皆愈。"}, {"source": "条35｜《药论·香散》·石菖蒲", "原文": "《药论·香散》：“石菖蒲入心、脾、肺，辛香邪可辟，燥烈郁堪行。鼻塞耳鸣，夹黄连以开心窍；健忘惊悸，偕远志以肃心神。入平胃散而云单鼓胀消，惟唯宜暴病；入参苓散而云噤口痢夺，独利脾亏。既害津枯，又妨赤目。", "白话": "石菖蒲入心、脾、肺，辛香之气可辟邪，燥烈之性可行郁。治鼻塞耳鸣，配黄连以开心窍；治健忘惊悸，配远志以清肃心神。入平胃散而说单用可消鼓胀，只宜暴病；入参苓散而说噤口痢可愈，独有利于脾亏。本品既伤津枯者，又碍赤目者。"}, {"source": "条36｜《苍生司命·药性》·石斛", "原文": "《苍生司命·药性》：“味甘，却惊定志，壮骨补虚，筋力衰替。", "白话": "味甘，祛惊定志，壮骨补虚，治筋力衰退。"}, {"source": "条37｜《本草正·水石草部》·石斛", "原文": "《本草正·水石草部》：“此药有二种，力皆微薄，圆细而肉实者，味微甘而淡，其力尤薄。", "白话": "此药有两种，药力都微薄；圆细而肉实的一种，味微甘而淡，药力尤其薄弱。"}, {"source": "条38｜《本草》·石斛（《本草正》石斛条内引书）", "原文": "《本草》云：圆细者为上。且谓其：益精强阴，壮筋补虚，健脚膝，驱冷痹，却惊悸，定心志。但此物性味最薄，焉能滋补如此？惟唯是扁大而松，形如钗股者，颇有苦味，用除脾胃之火，去嘈杂善饥，及营中蕴热。其性轻清和缓，有从容分解之炒，故能退火养阴除烦，清肺下气，亦止消渴热汗。而诸家谓其厚肠胃，健阳道，暖水脏，岂苦凉之性味所能也？不可不辨。", "白话": "《本草》说：圆细者为上。并且说它能益精强阴、壮筋补虚、健脚膝、驱冷痹、祛惊悸、定心志。但此物性味最薄，岂能如此滋补？只有扁大而松、形如钗股的一种，颇有苦味，用以除脾胃之火，去嘈杂易饥，及营中蕴热。其性轻清和缓，有从容分解之妙，所以能退火养阴除烦、清肺下气，也止消渴热汗。而诸家说它厚肠胃、健阳道、暖水脏，岂是苦凉之性味所能做到的？不可不辨。"}, {"source": "条39｜《杂症痘疹药性主治合参·草部中》·石斛", "原文": "《杂症痘疹药性主治合参·草部中》：“石斛，却惊定志，益精强阴，壮筋骨补虚羸，健脚膝，驱冷痹，皮外邪热，胃中虚火，厚肠胃轻身，长肌肉下气，但气力浅薄，得参芪便能凑功，专倚之无捷效也。主治痘疹合参入胃，清湿热，故理痹证泄泻。入肾强阴，故理精衰骨痛。其安神定惊者，亦清热强阴之力，兼入心也。痘后调理，药中多用，总平胃气之至药。", "白话": "石斛祛惊定志，益精强阴，壮筋骨、补虚羸，健脚膝，驱冷痹，去皮外邪热、胃中虚火，厚肠胃、轻身，长肌肉、下气；但气力浅薄，得人参、黄芪便能建功，单靠它不会有快捷之效。痘疹合参项下：入胃清湿热，所以治痹证泄泻；入肾强阴，所以治精衰骨痛。其安神定惊，也是清热强阴之力，兼入心。痘后调理方中多用，是平和胃气的良药。"}, {"source": "条40｜《神农本草经·上品》·龙胆", "原文": "《神农本草经·上品》：“味苦涩。主骨间寒热，惊痫邪气，续绝伤，定五脏，杀蛊毒。久服，益智、不忘，轻身、耐老。一名陵游，生山谷。", "白话": "味苦涩。主治骨间寒热、惊痫邪气，续接绝伤，安定五脏，杀蛊毒。久服，益智不忘，轻身耐老。又名陵游，产于山谷。"}, {"source": "条41｜《名医别录》卷第一·龙胆", "原文": "《名医别录》卷第一：“大寒，无毒。主除胃中伏热，时气温热，热泄下痢，去肠中小蛊，益肝胆气，止惊惕。", "白话": "性大寒，无毒。主治除胃中伏热、时气温热、热泻下痢，去肠中小虫，益肝胆之气，止惊惕。"}, {"source": "条42｜《本草蒙筌·果部》·龙眼", "原文": "《本草蒙筌·果部》：“味甘，气平。无毒。树颇大，叶微小凌冬常青；实极圆，壳淡黄纹作鳞甲。肉甘甚薄，名亚荔枝。亦产蜀闽岭南，荔枝过后才熟。士人鄙之，又呼荔枝奴也。取肉入药，因甘归脾。古方归脾汤中，功与人参并奏。", "白话": "味甘，气平。无毒。树颇大，叶微小凌冬常青；果实极圆，壳淡黄、纹如鳞甲。肉味甘而薄，名声仅次于荔枝。也产于蜀、闽、岭南，荔枝过后才成熟。士人轻视它，又称荔枝奴。取肉入药，因味甘而归脾。古方归脾汤中，功效与人参并驾齐驱。"}, {"source": "条43｜《本经》·龙眼（《本草蒙筌》龙眼条内引书）", "原文": "《本经》一名益智，禅益脾之所藏。脾藏智故云。解毒去虫，安志厌食。养肌肉，美颜色，除健志，却怔忡。多服强魂聪明，久服轻身不老。", "白话": "《本经》说（龙眼）又名益智，裨益脾所藏之意——因脾藏智，所以这样说。能解毒去虫，安志、除不思饮食，养肌肉，美颜色，除健忘，祛怔忡。多服使人魂强聪明，久服轻身不老。"}, {"source": "条44｜《本草纲目·健忘》·龙眼", "原文": "《本草纲目·健忘》：“龙眼安志强魂，主思虑伤脾，健忘怔忡，自汗惊悸，归脾汤用之。", "白话": "龙眼安志强魂，主治思虑伤脾所致健忘怔忡、自汗惊悸，归脾汤用它。"}, {"source": "条45｜《医宗说约·果部共十八种》·龙眼", "原文": "《医宗说约·果部共十八种》：“龙眼甘温，补虚益智，健忘怔忡，明目同治（中满气膈者勿用，去壳取肉）。", "白话": "龙眼甘温，补虚益智，健忘怔忡与目疾一并可治（中满气膈者勿用，去壳取肉入药）。"}, {"source": "条46｜《药性赋·草部上》·生地黄", "原文": "《药性赋·草部上》：“生地黄，能行血兼止吐衄折伤；熟地黄，能补血重治虚劳焦躁。生地黄大寒，亦治产后血攻心及女人经水闭绝。熟地黄，净洗酒浸，蒸三两次，焙干。味甘、温。无毒。熟干则温补，生干则平宣。熟者止崩漏，安魂魄，治惊悸，补内伤。", "白话": "生地黄能行血，兼止吐血衄血及跌打损伤；熟地黄能补血，重治虚劳焦躁。生地黄大寒，也治产后血攻心及女子经闭。熟地黄制法：洗净酒浸，蒸两三次，焙干。味甘，性温，无毒。熟用则温补，生用则平宣。熟地止崩漏，安魂魄，治惊悸，补内伤。"}, {"source": "条47｜《本草纲目·草之五》·生地黄", "原文": "《本草纲目·草之五》：“地黄，助心胆气，强筋骨长志，安魂定魄，治惊悸劳劣，心肺损，吐血鼻衄，妇人崩中血晕大明。", "白话": "地黄，助心胆之气，强筋骨、长志，安魂定魄，治惊悸、劳劣、心肺损伤、吐血鼻衄、妇人崩中血晕。（以上为“大明”即《日华子本草》所载。）"}, {"source": "条48｜《本草汇言·草部隰草类》·生地黄", "原文": "《本草汇言·草部隰草类》：“凉血补血张元素之药也。生则入手少阴陈赤葵集，凉血而生血，熟则入足少阴，补血而滋阴，所以呕、吐、咯、衄、唾血之证，非此不除，惊悸怔忡，烦热之证，非此不效，盖心肾之要药也。", "白话": "这是张元素凉血补血之药。生用则入手少阴，凉血而生血；熟用则入足少阴，补血而滋阴。所以呕、吐、咯、衄、唾血诸证，非此不能除；惊悸怔忡、烦热之证，非此不能效——实为心肾的要药。"}, {"source": "条49｜《本草易读》卷四·生地黄", "原文": "《本草易读》卷四：“甘，寒，微苦，无毒。入太阴脾、厥阴肝、手足少阴、厥阴。凉血滋肝，清风润木，消瘀通经，润燥开结。解温病之阳旺，退痘疮之热盛。除咳嗽火动，调崩中之血热。溺唾吐衄之血，惊悸痿痹之疴。填骨髓而长肌肉，平折跌而续绝筋。最损脾胃，尤泻大肠。", "白话": "味甘，性寒，微苦，无毒。入太阴脾、厥阴肝、手足少阴、厥阴。凉血滋肝，清风润木，消瘀通经，润燥开结。解温病阳旺，退痘疮热盛。除咳嗽火动，调崩中血热。治溺血、唾血、吐血、衄血，及惊悸痿痹之病。填骨髓而长肌肉，平折伤而续绝筋。最能损伤脾胃，尤其泻大肠。"}, {"source": "条50｜《得配本草·草部隰草类》·生地黄", "原文": "《得配本草·草部隰草类》：“甘凉，微苦，入手足少阴、厥阴，及手太阳经血分。其生血以清阴火，举世皆知。能生气以行阳分，人多不晓。血足气得所归，所谓藉精生气。一切惊悸经枯，掌中热，劳劣痿厥，吐衄崩漏，便秘等症，均此治之。消谷食，大便下，则中气动而食自化。实脾胃，湿热去,脾胃自实。亦奏奇功。", "白话": "味甘凉，微苦，入手足少阴、厥阴及手太阳经血分。它生血以清阴火，举世皆知；能生气以行阳分，人多不晓。血足则气得所归，这就是藉精生气。一切惊悸、经枯、掌中热、劳劣痿厥、吐衄崩漏、便秘等症，都用它治疗。消谷食：大便通下，则中气转动而食自化。实脾胃：湿热去，则脾胃自实。也奏奇功。"}, {"source": "条51｜《本草纲目·草之一》·玄参", "原文": "《本草纲目·草之一》：“腹中寒热积聚，女子产乳余疾，补肾气，令人目明", "白话": "主治腹中寒热积聚，女子产后乳余之疾，补肾气，使人目明。"}, {"source": "条52｜《本经》·玄参（《本草纲目》玄参条内引书）", "原文": "《本经》。主暴中风伤寒，身热支满，狂邪忽忽不知人，温疟洒洒，血瘕，下寒血，除胸中气，下水止烦渴，散颈下核，痈肿，心腹痛，坚症，定五脏。久服补虚明目，强阴益精", "白话": "（承上，标示《本经》文）主治暴中风伤寒，身热肢节胀满，狂邪恍惚不识人，温疟洒淅恶寒，血瘕，下寒血，除胸中气，利水止烦渴，散颈下结核、痈肿、心腹痛、坚积，安定五脏。久服补虚明目，强阴益精。"}, {"source": "条53｜《别录》·玄参（《本草纲目》玄参条内引书）", "原文": "《别录》。热风头痛，伤寒劳复，治暴结热，散瘤瘘瘰疬甄权。治游风，补劳损，心惊烦躁，骨蒸传尸邪气，止健忘，消肿毒大明。滋阴降火，解斑毒，利咽喉，通小便血滞。", "白话": "（承上，标示《别录》文及后世诸家）治热风头痛、伤寒劳复，治暴结热，散瘤瘘瘰疬（甄权说）；治游风，补劳损，除心惊烦躁、骨蒸传尸邪气，止健忘，消肿毒（大明说）；滋阴降火，解斑毒，利咽喉，通小便血滞。"}, {"source": "条54｜《证类本草》卷第十·半夏", "原文": "《证类本草》卷第十：“味辛，平，生微寒、熟温，有毒。主伤寒寒热，心下坚，下气，喉咽肿痛，头眩，胸胀咳逆，腹鸣，止汗，消心腹胸膈痰热满结，咳嗽上气，心下急有痛坚痞，时气呕逆，消痈肿，堕胎，疗痿黄，悦泽面目。生令人吐，熟令人下。", "白话": "味辛，性平，生用微寒、制熟性温，有毒。主治伤寒寒热、心下坚满，下气，咽喉肿痛，头眩，胸胀咳逆，腹鸣，止汗，消心腹胸膈痰热满结、咳嗽上气、心下急痛坚痞、时气呕逆，消痈肿，堕胎，疗痿黄，悦泽面目。生用使人吐，制熟使人泻下。"}, {"source": "条55｜《长沙药解》卷一·半夏", "原文": "《长沙药解》卷一：“半夏味辛，气平，入手太阴肺、足阳明胃经。下冲逆而除咳嗽，降浊阴而止呕吐，排决水饮，清涤涎沫，开胸膈胀塞，消咽喉肿痛，平头上之眩晕，泻心下之痞满，善调反胃，妙安惊悸。", "白话": "半夏味辛，气平，入手太阴肺、足阳明胃经。下冲逆而除咳嗽，降浊阴而止呕吐，排决水饮，清涤涎沫，开胸膈胀塞，消咽喉肿痛，平头上眩晕，泻心下痞满，善于调理反胃，妙于安定惊悸。"}, {"source": "条56｜《得配本草·草部》·半夏", "原文": "《得配本草·草部》：“辛，温，有毒。入足太阴、阳明、少阳经气分。利窍和胃，而通阴阳，为除湿化痰，开郁止呕之圣药。发声音，救暴卒，治不眠，疗带浊，除瘿瘤，消痞结，治惊悸，止疟疾。", "白话": "味辛，性温，有毒。入足太阴、阳明、少阳经气分。利窍和胃而通阴阳，是除湿化痰、开郁止呕的圣药。发声音，救暴卒，治不眠，疗带浊，除瘿瘤，消痞结，治惊悸，止疟疾。"}, {"source": "条57｜《药征》中卷·半夏", "原文": "《药征》中卷：“主治痰饮呕吐也。旁治心痛，逆满，咽中痛，咳悸，腹中雷鸣。", "白话": "主治痰饮呕吐。兼治心痛、气逆胀满、咽中疼痛、咳嗽心悸、腹中雷鸣。"}, {"source": "条58｜《医学摘粹·滋阴类》·芍药", "原文": "《医学摘粹·滋阴类》：“味酸微苦，微寒，入足厥阴肝、足少阳胆经。入肝家而清风，走胆腑而泄热。善调心中烦悸，最消腹里痛满，散胸胁之痞热，伸腿足之挛急。吐衄悉瘳，崩漏胥断。泄痢与淋带皆灵，痔漏共瘰疬并效。", "白话": "味酸微苦，微寒，入足厥阴肝、足少阳胆经。入肝而清风，走胆而泄热。善于调理心中烦悸，最能消腹里痛满，散胸胁痞热，舒展腿足挛急。吐血衄血都能痊愈，崩漏尽止。泄痢与淋带都灵验，痔漏与瘰疬一并见效。"}, {"source": "条59｜《本草纲目·草之四》·西红花", "原文": "《本草纲目·草之四》：“番红花纲目【释名】洎夫蓝纲目、撒法郎……【气味】甘，平，无毒。【主治】心忧郁积，气闷不散，活血。久服令人心喜。又治惊悸时珍。", "白话": "番红花（《本草纲目》载）【释名】洎夫蓝、撒法郎……【气味】甘，平，无毒。【主治】心有忧郁积结，气闷不散，能活血。久服使人心情喜悦。又治惊悸（李时珍说）。"}, {"source": "条60｜《本草乘雅半偈》第九帙·西红花", "原文": "《本草乘雅半偈》第九帙：“洎夫蓝气味甘平，无毒。主心忧郁积，气闷不散，活血。久服令人心喜，治惊悸。", "白话": "洎夫蓝气味甘平，无毒。主治心有忧郁积结、气闷不散，能活血。久服使人心喜，治惊悸。"}, {"source": "条61｜《证类本草》卷第八·百合", "原文": "《证类本草》卷第八：“日华子云：白百合，安心定胆，益志，养五脏，治癫邪、啼泣、狂叫、惊悸，杀蛊毒，气？火劦、乳痈、发背及诸疮肿，并治产后血狂运。又云红百合，凉，无毒。治疮肿及疗惊邪。此是红花者，名连珠。", "白话": "日华子说：白百合，安心定胆，益智，养五脏，治癫邪、啼泣、狂叫、惊悸，杀蛊毒，治乳痈、发背及各种疮肿（“气？火劦”数字讹脱，义不详），并治产后血运狂乱。又说红百合，性凉，无毒，治疮肿及惊邪。这是开红花的一种，名叫连珠。"}, {"source": "条62｜《本草集要·草部》·百合", "原文": "《本草集要·草部》：“味甘，气平。无毒。花白者入药佳。主邪气腹胀心痛，利大小便。补中益气，除浮肿腹胀，痞满寒热，通身疼痛。百邪鬼魅，涕泣不止，狂叫惊悸。杀蛊毒，乳痈喉痹，发背及诸疮肿。", "白话": "味甘，气平。无毒。白花者入药为佳。主治邪气腹胀心痛，利大小便。补中益气，除浮肿腹胀、痞满寒热、通身疼痛。治百邪鬼魅、涕泣不止、狂叫惊悸。杀蛊毒，治乳痈喉痹、发背及各种疮肿。"}, {"source": "条63｜《本草蒙筌·草部下》·百合", "原文": "《本草蒙筌·草部下》：“味甘，气平。无毒。洲渚山野俱生，花开红白二种。根如葫蒜，小瓣多层。人因美之，称名百合。白花者，养脏益志，定胆安心。逐惊悸狂叫之邪，消浮肿痞满之气。止遍身痛，利大小便。辟鬼气，除时疫咳逆；杀蛊毒，治外科痈疽。乳痈喉痹殊功，发背搭肩立效。又张仲景治伤寒坏后，已成百合病证，用此治之，固此名同，然未识有何义也。蒸食能补中益气，作面可代粮过荒。赤花者，仅治外科，不理他病。凡采待用，务", "白话": "味甘，气平。无毒。洲渚山野都生，花分红白两种。根如葫蒜，小瓣多层。人们因它美好，称名百合。白花的，养脏益智，定胆安心。逐惊悸狂叫之邪，消浮肿痞满之气。止遍身疼痛，利大小便。辟鬼气，除时疫咳逆；杀蛊毒，治外科痈疽。治乳痈喉痹有特殊功效，发背搭肩立效。又张仲景治伤寒坏病后已成百合病证的，用此药治疗——固然病名与此花同名，但不知是什么含义。蒸食能补中益气，磨面可代粮度荒。红花的仅治外科，不理其他病。凡采收备用，务必分别留存。"}, {"source": "条64｜《本草纲目·菜之二》·百合", "原文": "《本草纲目·菜之二》：“安心定胆益志，养五脏，治颠邪狂叫惊悸，产后血狂运，杀蛊毒气，胁痈乳痈发背诸疮肿。", "白话": "安心定胆益智，养五脏，治癫邪狂叫惊悸、产后血运狂乱，杀蛊毒之气，治胁痈、乳痈、发背及诸疮肿。"}, {"source": "条65｜《本草正·菜部》·百合", "原文": "《本草正·菜部》：“味微甘淡，气平功缓。以其甘缓，故能补益气血，润肺除嗽，定魄安心，逐惊止悸，缓时疫咳逆，解乳痈喉痹，兼治痈疽，亦解蛊毒，润大小便，消气逆浮肿。", "白话": "味微甘淡，气平而功效缓。因其甘缓，故能补益气血，润肺除嗽，定魄安心，逐惊止悸，缓时疫咳逆，解乳痈喉痹，兼治痈疽，也解蛊毒，润大小便，消气逆浮肿。"}, {"source": "条66｜《得配本草·菜部柔滑类》·百合", "原文": "《得配本草·菜部柔滑类》：“甘、苦、平。入手太阴及手少阴经。润肺宁心，清热止嗽，利二便，除浮肿，疗虚痞，退寒热，定惊悸，止涕泪，治伤寒百合病。", "白话": "味甘、苦，性平。入手太阴（肺）及手少阴（心）经。润肺宁心，清热止嗽，利大小便，除浮肿，疗虚痞，退寒热，定惊悸，止涕泪，治伤寒百合病。"}, {"source": "条67｜《本草汇言·草部芳草类》·当归", "原文": "《本草汇言·草部芳草类》：“当归，生血，养血，止血，活血之药也(时珍)。若吐血衄血(须四可稿)，淋血便血，或经漏失血，或产崩损血，皆血走也，必用归头以止之。如阴虚不足，精神困倦，或惊悸怔忡，健忘恍惚，皆血少也，必用归身以补之。", "白话": "当归是生血、养血、止血、活血的药（李时珍说）。如吐血衄血（“须四可稿”为原稿夹注残文）、淋血便血，或经漏失血，或产崩损血，都是血外走，必用当归头以止之。如阴虚不足、精神困倦，或惊悸怔忡、健忘恍惚，都是血少，必用当归身以补之。"}, {"source": "条68｜《药性本草约言·木部》·竹沥", "原文": "《药性本草约言·木部》：“竹沥烧取与荆沥同，横锯截尺余，直劈作数块，两砖架起，紧火中烘，沥从两头流出，每沥一杯，加生姜自然汁二匙。却阴虚发热，理中风噤牙。小儿天吊惊痫，入口便定。妇人胎产闷晕，下咽即苏。止惊悸，破痰涎。痰在手足四肢，非此不达；痰在皮里膜外，有此可驱。但俗反以大寒置疑不用，不知系火煅出，又佐姜汁，有何寒乎？丹溪云：虚痰用竹沥，实痰用荆沥，二味开经络、行血气要药也。俱加姜汁传送。", "白话": "竹沥的烧取法与荆沥相同：横锯截成一尺多长，直劈成几块，两块砖架起，猛火烘烤，汁从两头流出；每竹沥一杯，加生姜自然汁二匙。能退阴虚发热，调理中风噤牙；小儿天吊惊痫，入口便定；妇人胎产闷晕，下咽即苏。止惊悸，破痰涎。痰在手足四肢，非此不能达；痰在皮里膜外，有此可以驱。但世俗反因“大寒”之说而疑忌不用，不知它是火煅出来，又佐姜汁，有何寒呢？丹溪说：虚痰用竹沥，实痰用荆沥，二者是开经络、行血气的要药，都加姜汁以输送。"}, {"source": "条69｜《雷公炮制药性解·木部》·竹沥", "原文": "《雷公炮制药性解·木部》 ：“火烧竹沥，主阴虚发热，中风口噤，除自汗，解消渴，止惊悸，清烦躁，痰在手足四肢，非此不达；痰在皮里膜外，有此可驱。又主小儿天吊惊痫、妇人妊晕闷,胎前不损子,产后不得虚。", "白话": "火烧取竹沥，主治阴虚发热、中风口噤，除自汗，解消渴，止惊悸，清烦躁；痰在手足四肢，非此不能达；痰在皮里膜外，有此可以驱。又主小儿天吊惊痫、妇人妊娠晕闷；胎前不损胎儿，产后不致虚弱。"}, {"source": "条70｜《杂症痘疹药性主治合参·木部》·竹沥", "原文": "《杂症痘疹药性主治合参·木部》：“竹沥，系烧竹而两头流出之汁，每沥一杯，加生姜汁二匙用，却阴虚发热，中风噤牙，小儿天吊惊痫，妇人胎产闷晕，胎前不损子，产后不凝虚，止惊悸，却痰痫，痰在经络四肢，屈曲而搜剔，痰在皮里膜外，直达以宣通，但世以为大寒，殊不知系火煅出，又佐姜汁，有何寒乎！", "白话": "竹沥是烧竹而从两头流出的汁，每竹沥一杯加生姜汁二匙用。退阴虚发热，治中风噤牙、小儿天吊惊痫、妇人胎产闷晕；胎前不损胎儿，产后不凝滞致虚。止惊悸，祛痰痫。痰在经络四肢，它能曲折搜剔；痰在皮里膜外，它能直达宣通。但世人以为大寒，殊不知它是火煅出来又佐姜汁，有什么寒呢！"}, {"source": "条71｜《得配本草·竹部》·竹茹", "原文": "《得配本草·竹部》：“甘，微寒。入足少阳、阳明经。清上焦之火，消虚热之痰。疗惊悸，止胎动，呕啘噎膈，吐血崩中，因内火致者，非此不治。", "白话": "味甘，微寒。入足少阳、阳明经。清上焦之火，消虚热之痰。疗惊悸，止胎动；呕哕噎膈、吐血崩中，凡因内火所致的，非此不能治。"}, {"source": "条72｜《本草汇言·草部隰草类》·灯心草", "原文": "《本草汇言·草部隰草类》：“……又张氏方谓能消水肿，散喉痹，定惊悸，止小儿夜啼，疗大人痰热，皆取其轻凉清肃之性，以治热郁为诸病，悉主用焉。", "白话": "……又张氏方说它能消水肿、散喉痹、定惊悸、止小儿夜啼、疗大人痰热——都取其轻凉清肃之性，以治热郁所致诸病，都可主治应用。"}, {"source": "条73｜《本草汇言·草部隰草类》·麦门冬", "原文": "《本草汇言·草部隰草类》：“麦门冬清心润肺之药也(李东垣)。主心气不足(葛风寰稿)，惊悸怔忡，健忘恍惚，精神失守，或肺热肺燥，咳声连发，肺痿叶焦，短气虚喘，火伏肺中，咯血咳血，或虚劳客热，津液干少，或脾胃燥涸，虚秘便难，此皆心肺肾脾，元虚火郁之证也。", "白话": "麦门冬是清心润肺的药（李东垣说）。主治心气不足（葛风寰稿本）、惊悸怔忡、健忘恍惚、精神失守；或肺热肺燥、咳声连发、肺痿叶焦、短气虚喘、火伏肺中、咯血咳血；或虚劳客热、津液干少；或脾胃燥涸、虚秘便难——这都是心肺肾脾元气虚而火郁的证候。"}, {"source": "条74｜《医学摘粹·滋阴类》·麦门冬", "原文": "《医学摘粹·滋阴类》：“味甘微凉，入手太阴肺、足阳明胃经。清金润燥，解渴除烦，凉肺热而止咳，降心火而安悸。", "白话": "味甘微凉，入手太阴肺、足阳明胃经。清金（肺）润燥，解渴除烦，凉肺热而止咳，降心火而安悸。"}, {"source": "条75｜《本草经集注·草木上品》·远志", "原文": "《本草经集注·草木上品》：“味苦，温，无毒。主治咳逆伤中，补不足，除邪气，利九窍，益智慧，耳目聪明，不忘，强志，倍力。利丈夫，定心气，止惊悸，益精，去心下膈气，皮肤中热，面目黄。久服轻身，不老，好颜色，延年。叶名小草，主益精，补阴气，止虚损，梦泄。", "白话": "味苦，性温，无毒。主治咳逆伤中，补不足，除邪气，利九窍，益智慧，耳目聪明，使人不忘，强志，倍增气力。利于男子，定心气，止惊悸，益精，去心下膈气、皮肤中热、面目发黄。久服轻身不老、颜色美好、延年。叶名叫小草，主益精、补阴气、止虚损、梦泄。"}, {"source": "条76｜《药性本草约言·卷之一·草部》·远志", "原文": "《药性本草约言·卷之一·草部》：“味苦，气温，无毒，阴中之阳，可升可降。通塞而利滞，畅外而慧中，理心神之惊悸，去耳目之昏聋。", "白话": "味苦，气温，无毒，阴中之阳，可升可降。能通闭塞而利滞，畅达外而慧明内，调理心神之惊悸，去耳目昏聋。"}, {"source": "条77｜《医学入门·治燥门》·远志", "原文": "《医学入门·治燥门》：“远志苦温益肾精，补中高志定心惊，利膈通窍除咳逆，苗感阴生止梦萦。性能令人志识高远。苗名小草，其形细也。无毒。沉而降，阳也。主益精壮阳，补中虚，定心气惊悸、健忘、梦邪遗精，去心下膈气，除咳逆，利九窍，明耳目。", "白话": "远志苦温益肾精，补中强志定心惊，利膈通窍除咳逆；苗感阴而生，止梦扰。其性能使人志识高远。苗名叫小草，因其形细。无毒。性沉而降，属阳。主益精壮阳，补中虚，定心气惊悸、健忘、梦邪遗精，去心下膈气，除咳逆，利九窍，明耳目。"}, {"source": "条78｜《药鉴·新刻药鉴卷之二》·远志", "原文": "《药鉴·新刻药鉴卷之二》：“气温，味苦。无毒。主和颜悦色，轻身耐老。利九窍而补中伤，除咳逆而驱惊悸，益智慧而善不忘。小儿惊痫客忤，非此莫治；妇人血噤失音，非此莫疗。大都温则能补，故能益精气，壮阳神，强志倍力；苦则能泄，故能辟邪气，去邪梦，安心定神。畏珍珠、藜芦。", "白话": "气温，味苦。无毒。主和颜悦色，轻身耐老。利九窍而补中虚损伤，除咳逆而驱惊悸，益智慧而善忘能除。小儿惊痫客忤，非此不能治；妇人血噤失音，非此不能疗。大抵温则能补，所以能益精气、壮阳神、强志倍力；苦则能泄，所以能辟邪气、去邪梦、安心定神。畏珍珠、藜芦。"}, {"source": "条79｜《医方捷径指南全书·药性赋》·远志", "原文": "《医方捷径指南全书·药性赋》：“远志苦温除咳逆，盈精补气壮心神,祛邪利窍安惊悸，强志聪明智慧人。", "白话": "远志苦温除咳逆，益精补气壮心神，祛邪利窍安惊悸，强志使人聪明有智慧。"}, {"source": "条80｜《本草详节·草部》·远志", "原文": "《本草详节·草部》：“味苦，气温。生山东、河、陕。有二种，小叶者花白，大叶者花红，四月采根。入肾经气分……主健忘，惊悸，明目，聪耳，胸痹，喉痹，脑风头痛，奔豚，咳逆，长一切痈疽肌肉。", "白话": "味苦，气温。产于山东、河、陕。有两种：小叶的花白，大叶的花红，四月采根。入肾经气分……主治健忘、惊悸，明目，聪耳，治胸痹、喉痹、脑风头痛、奔豚、咳逆，生长一切痈疽之肌肉。"}, {"source": "条81｜《滇南本草·还阳参》·还阳参", "原文": "《滇南本草·还阳参》：“味甘、平,性大温。无毒，治诸虚百损，五劳七伤，气血衰败，头晕耳鸣，心慌怔忡，妇人白带漏下，肝肾虚弱，任督二脉损伤，其应如响。如肺热者忌用。吃之，恐动火燥热，令人咳血，或痰上带血丝，或出鼻血，烦躁不安。（单方） 治诸虚百损，五种劳症，虚劳蓐劳，白带漏下，头晕耳鸣，心慌怔忡，妇人内伤任督，下元虚寒，不能受胎者用。还阳参（四两） 、乌骨鸡（一只去肠，将参入腹内） 煮烂去皮油，将肉", "白话": "味甘、平，性大温。无毒。治诸虚百损、五劳七伤、气血衰败、头晕耳鸣、心慌怔忡、妇人白带漏下、肝肾虚弱、任督二脉损伤，取效如响应声。肺热者忌用，服之恐怕引动火燥热，使人咳血，或痰中带血丝，或出鼻血、烦躁不安。（单方）治诸虚百损、五种劳证、虚劳蓐劳、白带漏下、头晕耳鸣、心慌怔忡，妇人内伤任督、下元虚寒不能受孕者：用还阳参四两、乌骨鸡一只（去肠，将参放入鸡腹内）煮烂去皮油，将肉晒干，骨用新瓦焙黄，肉骨共研细末，或用蜜为丸如梧桐子大，或作散。每天早晨服二钱，白开水送下。若忌食煨鸡肉，猪"}, {"source": "条82｜《神农本草经·上品》·沙参", "原文": "《神农本草经·上品》：“味苦，微寒。主血积惊气，除寒热，补中，益肺气。久服利人。一名知母。生川谷。", "白话": "味苦，微寒。主治血积惊气，除寒热，补中，益肺气。久服对人体有利。又名知母。产于川谷。"}, {"source": "条83｜《滇南本草·苦远志》·苦远志", "原文": "《滇南本草·苦远志》：“味甘、微苦，性微寒。入心、肝、脾三经，养心血，镇惊宁心，定惊悸，散痰涎，疗五痫，角弓反张，惊搐，口吐痰涎，手足战摇，不省人事。缩小便，治赤、白便浊，膏淋，滑精不禁，点滴不收，良效。", "白话": "味甘、微苦，性微寒。入心、肝、脾三经。养心血，镇惊宁心，定惊悸，散痰涎，疗五痫、角弓反张、惊搐、口吐痰涎、手足颤抖、不省人事。缩小便，治赤白便浊、膏淋、滑精不禁、点滴不收，效果良好。"}, {"source": "条84｜《药鉴·药性（平门）》·郁李仁", "原文": "《药鉴·药性（平门）》：“郁李仁安心志，而惊悸能定；舒气结，而阳脏和调。", "白话": "郁李仁安心志，惊悸能定；舒展气结，使阳脏（腑）和调。"}, {"source": "条85｜《药性赋·平性》·郁李仁", "原文": "《药性赋·平性》：“郁李仁润肠宣水，去浮肿之疾。", "白话": "郁李仁润肠宣泄水湿，去浮肿之疾。"}, {"source": "条86｜《证类本草》卷第八·知母", "原文": "《证类本草》卷第八：“日华子云：味苦、甘。治热劳，传尸疰病，通小肠，消痰止嗽，润心肺，补虚乏，安心，止惊悸。", "白话": "日华子说：味苦、甘。治热劳、传尸疰病，通小肠，消痰止嗽，润心肺，补虚乏，安心，止惊悸。"}, {"source": "条87｜《本草纲目·草之一》·知母", "原文": "《本草纲目·草之一》：“知母，心烦躁闷，骨热劳往来，产后蓐劳，肾气劳，憎寒虚烦甄权。热劳传尸疰痛，通小肠，消痰止嗽，润心肺，安心，止惊悸大明。", "白话": "知母，治心烦躁闷、骨蒸劳热往来、产后蓐劳、肾气劳、憎寒虚烦（甄权说）；治热劳传尸疰痛，通小肠，消痰止嗽，润心肺，安心，止惊悸（大明说）。"}, {"source": "条88｜《本草正·竹木部》·金樱子", "原文": "《本草正·竹木部》：“味涩，性平。生者色青酸涩。熟者色黄甘涩。当用其将熟微酸而甘涩者为妙。其性固涩，涩可固阴治脱，甘可补中益气。故善理梦遗精滑，及崩淋带漏，止吐血衄血，生津液，安魂魄，收虚汗，敛虚火，益精髓，壮筋骨，补五脏，养血气，平咳嗽，定喘急，疗怔忡惊悸，止脾泄血痢及小水不禁。此固阴养阴之佳品，而人之忽之亦久矣，此后咸宜珍之。", "白话": "味涩，性平。生的色青而酸涩，熟的色黄而甘涩。当用将熟微酸而甘涩的为好。其性固涩——涩可固阴治脱，甘可补中益气。所以善于调理梦遗精滑及崩淋带漏，止吐血衄血，生津液，安魂魄，收虚汗，敛虚火，益精髓，壮筋骨，补五脏，养血气，平咳嗽，定喘急，疗怔忡惊悸，止脾泄血痢及小便不禁。这是固阴养阴的佳品，人们忽视它也很久了，此后都应当珍视。"}, {"source": "条89｜《得配本草·木部灌木类》·金樱子", "原文": "《得配本草·木部灌木类》：“甘，涩，微酸，性温，入足少阴经血分。固精秘气，止血生津，治虚痢，收虚汗，敛虚火，平虚嗽，定虚喘，疗怔忡。", "白话": "味甘、涩、微酸，性温，入足少阴经血分。固精秘气，止血生津，治虚痢，收虚汗，敛虚火，平虚嗽，定虚喘，疗怔忡。"}, {"source": "条90｜《本草汇言·草部水草类》·泽泻", "原文": "《本草汇言·草部水草类》：“味甘、淡，气寒，无毒，阴中微阳，降也，入足太阳、少阴经。……泽泻宣行水道之药也(甄权)。此药寒淡下行(许长如稿)，以疏渗利窍为事，故前古统治一切水病，专通利下焦，去胞中之垢，消蓄积之水(东垣)，凡湿热黄疸，四肢水肿，寒湿脚气(时珍)，阴汗湿痒，小便癃闭，淋沥白浊，或心忡悸动，奔豚疝瘕，如上中下三焦停水之证(丹溪)，并皆治之。", "白话": "味甘、淡，气寒，无毒，阴中微阳，主降，入足太阳、少阴经。……泽泻是宣行水道的药（甄权说）。此药寒淡下行（许长如稿），以疏渗利窍为能事，所以前古统治一切水病，专通利下焦，去胞中之垢，消蓄积之水（东垣说）；凡湿热黄疸、四肢水肿、寒湿脚气（时珍说）、阴汗湿痒、小便癃闭、淋沥白浊，或心忡悸动、奔豚疝瘕，如上中下三焦停水之证（丹溪说），都能治。"}, {"source": "条91｜《神农本草经·下品》·荩草", "原文": "《神农本草经·下品》：“味苦，平，主久咳上气、喘逆，久寒，惊悸，痂疥、白秃、疡气，杀皮肤小虫。", "白话": "味苦，性平。主治久咳上气、喘逆、久寒、惊悸，治痂疥、白秃、疡气，杀皮肤小虫。"}, {"source": "条92｜《本草经集注·草木下品》·荩草", "原文": "《本草经集注·草木下品》：“味苦，平，无毒。主治久咳上气喘逆，久寒惊悸，痂疥白秃疡气，杀皮肤小虫。", "白话": "味苦，性平，无毒。主治久咳上气喘逆、久寒惊悸、痂疥白秃疡气，杀皮肤小虫。"}, {"source": "条93｜《药性本草约言·卷之二·木部》·柏子仁", "原文": "《药性本草约言·卷之二·木部》：“味甘、辛，气平，无毒，阳也，可升可降，入手少阴心、足太阴脾、少阴肾。暖骨髓，润肾经之燥。安神志，益心气之虚。江云：养心脾而有益。", "白话": "味甘、辛，气平，无毒，属阳，可升可降，入手少阴心、足太阴脾、足少阴肾。暖骨髓，润肾经之燥。安神志，益心气之虚。江氏说：养心脾而有益。"}, {"source": "条94｜《发明》·柏子仁（《药性本草约言》条内引书）", "原文": "《发明》云：润肾之药也。盖肾苦燥，藉此甘辛润之，自能生益精血，则五脏安和，而凡虚损等症亦治。目得血而能明，耳得血而能聪。心神足，惊悸恍惚自定矣。", "白话": "《发明》说：这是润肾的药。肾恶燥，藉此甘辛之品滋润，自然能生益精血，则五脏安和，凡虚损等症也都能治。目得血而能明，耳得血而能聪。心神充足，惊悸恍惚自然安定。"}, {"source": "条95｜《本草汇言·木部香木类》·柏子仁", "原文": "《本草汇言·木部香木类》：“润燥补髓，养心神，定惊悸之药也(李东垣)。此药气极芬芳(御医朱振斯)，则脾胃所喜，质极润泽，则肝肾所宜。故前古谓安养五脏，主惊悸，定心神，悦颜色，聪耳目，为延年却病之上剂也。但体质多油，肠滑作泻者勿服，膈间多痰者勿服，阳道妄举，肾家有热者勿服。已油者能令哮肺，勿入药用。", "白话": "是润燥补髓、养心神、定惊悸的药（李东垣说）。此药气极芬芳（御医朱振斯说），为脾胃所喜；质极润泽，为肝肾所宜。所以前古说它安养五脏、主惊悸、定心神、悦颜色、聪耳目，是延年却病的上品。但本品多油，肠滑易泻者勿服，膈间多痰者勿服，阳强易举、肾家有热者勿服。走油的能令人哮发于肺，勿入药用。"}, {"source": "条96｜《本草正·竹木部》·柏子仁", "原文": "《本草正·竹木部》：“味甘平，性微凉。能润心肺。养肝脾，滋肾燥，安神魂，益志意。故可定惊悸怔忡，益阴气，美颜色，疗虚损，益血，止汗，润大肠，利虚秘，亦去百邪鬼魅，小儿惊痫。总之，气味清香，性多润滑，虽滋阴养血之佳剂，若欲培补根本，乃非清品所长。", "白话": "味甘平，性微凉。能润心肺，养肝脾，滋肾燥，安神魂，益志意。所以可定惊悸怔忡，益阴气，美颜色，疗虚损，益血，止汗，润大肠，利虚秘，也去百邪鬼魅、小儿惊痫。总之气味清香，性多润滑，虽是滋阴养血的佳品，但要培补根本，就不是清润之品所长了。"}, {"source": "条97｜《医宗必读·木部》·柏子仁", "原文": "《医宗必读·木部》：“味甘辛，性平，无毒。入心、肝、肾三经。畏菊花、羊蹄草。蒸，晒，炒。安神定悸，壮水强阳。润血而容颜美少，补虚而耳目聪明。心藏神，肾藏精与志，心肾虚,则病惊悸。入心养神、入肾定志，悸必愈矣。悦颜聪明,皆心血与肾水互相灌溉耳。", "白话": "味甘辛，性平，无毒。入心、肝、肾三经。畏菊花、羊蹄草。炮制宜蒸、晒、炒。安神定悸，壮水强阳。润血而容颜年轻美好，补虚而耳目聪明。心藏神，肾藏精与志，心肾虚则病惊悸；入心养神、入肾定志，悸必愈。悦颜聪明，都是心血与肾水互相灌溉的结果。"}, {"source": "条98｜《医宗说约·木部共五十四种》·柏子仁", "原文": "《医宗说约·木部共五十四种》：“柏仁味甘，补心益气，敛汗扶阳，更除惊悸去壳去油取霜用。", "白话": "柏仁味甘，补心益气，敛汗扶阳，更能除惊悸。用法：去壳去油取霜用。"}, {"source": "条99｜《本草崇原·卷上本经上品》·柏子仁", "原文": "《本草崇原·卷上本经上品》：“柏子仁，气味甘平，无毒。主治惊悸，益气，除风湿，安五脏。久服令人润泽美色，耳目聪明，不饥不老，轻身延年。", "白话": "柏子仁，气味甘平，无毒。主治惊悸，益气，除风湿，安五脏。久服使人润泽美色、耳目聪明、不饥不老、轻身延年。"}, {"source": "条100｜《神农本草经·上品》·柏实", "原文": "《神农本草经·上品》：“味甘，平。主惊悸，安五脏，益气，除湿痹。久服，令人悦泽美色，耳目聪明，不饥，不老，轻身，延年。生山谷。", "白话": "味甘，性平。主治惊悸，安五脏，益气，除湿痹。久服使人润泽美色、耳目聪明、不饥不老、轻身延年。产于山谷。"}, {"source": "条101｜《本草经集注·草木上品》·柏实", "原文": "《本草经集注·草木上品》：“味甘，平，无毒。主治惊悸，安五藏五脏，益气，除风湿痹。治恍惚、虚损，呼吸历节，腰中重痛，益血，止汗。久服令人润泽美色，耳目聪明，不饥，不老，轻身，延年。", "白话": "味甘，性平，无毒。主治惊悸，安五脏，益气，除风湿痹。治恍惚、虚损、呼吸不利、历节疼痛、腰中重痛，益血，止汗。久服使人润泽美色、耳目聪明、不饥不老、轻身延年。"}, {"source": "条102｜《本草蒙筌·木部》·柏实", "原文": "《本草蒙筌·木部》：“味甘、辛，气平。无毒。近道俱有，乾州（属陕西）独佳。屋边者为宜，冢上者切忌。霜后采实，去壳取仁。先以醇酒浸曝干，次取黄精汁和煮。执筋连搅，汁尽才休。研细成霜，入剂方效。畏羊菊曲面诸石，羊蹄根、菊花、神曲、白面、一切石。使蛎瓜子桂皮。聪耳目，却风寒湿痹止疼；益气血，去恍惚虚损敛汗。治肾冷腰冷并膀胱冷脓宿水，润肾燥体燥及面颜燥涩不光。兴阳道，杀百邪，止惊悸，安五脏。头风眩痛，亦可", "白话": "味甘、辛，气平。无毒。近道都有，乾州（属陕西）产的独佳。屋边的宜用，坟上的切忌。霜后采实，去壳取仁。先用醇酒浸后晒干，再取黄精汁和煮，用筷子不断搅动，汁尽才停。研细成霜，入方剂才有效。畏羊蹄根、菊花、神曲、白面、一切石类。使药为牡蛎、瓜子、桂皮。聪耳目，祛风寒湿痹止痛；益气血，去恍惚虚损敛汗。治肾冷腰冷及膀胱冷、脓液宿水，润肾燥、体燥及面容枯燥不润。兴阳道，杀百邪，止惊悸，安五脏。头风眩痛也可煎服调理。久服不饥，增寿耐老。"}, {"source": "条103｜《本草详节·木部》·柏实", "原文": "《本草详节·木部》：“味甘，气平。生各处，泰山者佳。……主润肝，养心气，益五脏气，滋肾燥，止汗，定悸，历节，腰中重痛，肾中冷脓宿水，百邪鬼魅，小儿惊痫。", "白话": "味甘，气平。各处都产，泰山产的为佳。……主治润肝、养心气、益五脏之气、滋肾燥、止汗、定悸，治历节、腰中重痛、肾中冷脓宿水、百邪鬼魅、小儿惊痫。"}, {"source": "条104｜《神农本草经·中品》·厚朴", "原文": "《神农本草经·中品》：“味苦，温。主中风、伤寒、头痛、寒热，惊悸气，血痹死肌，去三虫。", "白话": "味苦，性温。主治中风、伤寒、头痛、寒热、惊悸气、血痹死肌，去三虫。"}, {"source": "条105｜《本草经集注·草木中品》·厚朴", "原文": "《本草经集注·草木中品》：“味苦，温、大温，无毒。主治中风，伤寒，头痛，寒热，惊悸，气血痹。死肌，去三虫。温中，益气，消痰下气，治霍乱及腹痛，胀满，胃中冷逆，胸中呕逆不止，泄痢，淋露，除惊，去留热，止烦满，厚肠胃。", "白话": "味苦，温、大温，无毒。主治中风、伤寒、头痛、寒热、惊悸、气血痹、死肌，去三虫。温中，益气，消痰下气，治霍乱及腹痛、胀满、胃中冷逆、胸中呕逆不止、泄痢、淋露，除惊，去留热，止烦满，厚肠胃。"}, {"source": "条106｜《本草易读》卷七·厚朴", "原文": "《本草易读》卷七：“温，苦，无毒。健脾温胃，厚肠和中，除烦化痰，止呕消胀。破宿血而化水谷，导宿食而开水结，定霍乱而止喘咳，除反胃而疗吐酸。解风热之头痛，却膨满之腹痛。泄痢淋露之疾，寒热惊悸之疴。能泄五脏诸气，兼安胎产诸病。", "白话": "性温，味苦，无毒。健脾温胃，厚肠和中，除烦化痰，止呕消胀。破宿血而助水谷运化，导宿食而开水结，定霍乱而止喘咳，除反胃而疗吐酸。解风热头痛，去膨满腹痛。治泄痢淋露之疾、寒热惊悸之病。能泄五脏诸气，兼安胎产诸病。"}, {"source": "条107｜《玉楸药解·草部》·钩藤", "原文": "《玉楸药解·草部》：“味甘，微温，入足厥阴肝经。泻湿清风，止惊安悸，治木郁筋惕，惊悸瘛疭。", "白话": "味甘，微温，入足厥阴肝经。泻湿清风，止惊安悸，治肝郁筋惕、惊悸瘛疭。"}, {"source": "条108｜《麻科活人全书·麻后宜用药性》·香附", "原文": "《麻科活人全书·麻后宜用药性》：“三焦、肝经气分药。开郁，消痰食，止诸痛，散风寒，行血气，月候不调，胎产崩漏。多怒多忧者之要药。治两胁气妨，心忪少气。生用则上行胁膈，外达皮毛，故能散风寒。熟用则下走肝肾，外彻腰足，故能调气血。", "白话": "是三焦、肝经气分药。开郁，消痰食，止各种疼痛，散风寒，行血气，治月经不调、胎产崩漏。是多怒多忧者的要药。治两胁气滞、心忪少气。生用则上行胁膈、外达皮毛，所以能散风寒；熟用则下走肝肾、外彻腰足，所以能调气血。"}, {"source": "条109｜《本草备要·木部》·桂心", "原文": "《本草备要·木部》：“燥，补阳，活血。苦入心，辛走血。能引血、化汗、化脓，内托痈、疽、痘疮同丁香，治痘疮灰塌，益精明目，消瘀生肌，补劳伤，暖腰膝，续筋骨。治风痹症瘕，噎膈腹满，腹内冷痛，九种心痛（一虫、二疰、三风、四悸、五食、六饮、七冷、八热、九去来痛，皆邪乘于手少阴之络，邪正相激，故令心痛）。", "白话": "性燥，补阳，活血。苦入心，辛走血。能引血、化汗、化脓，内托痈疽痘疮（配丁香治痘疮灰塌），益精明目，消瘀生肌，补劳伤，暖腰膝，续筋骨。治风痹症瘕、噎膈腹满、腹内冷痛、九种心痛（一虫痛、二疰痛、三风痛、四悸痛、五食痛、六饮痛、七冷痛、八热痛、九去来痛——都是邪气乘袭手少阴之络，邪正相激，所以令人心痛）。"}, {"source": "条110｜《医学摘粹·温散类》·桂枝", "原文": "《医学摘粹·温散类》：“味甘辛，气香，性温，入足厥阴肝、足太阳膀胱经。入肝家而行血分，走经络而达营郁，善解风邪，最调木气，升清阳脱陷，降浊阴冲逆，舒筋脉之急挛，利关节之壅阻，入肝胆而散遏抑。极止痛楚，通经络而开痹涩；甚去湿寒，能止奔豚，更安惊悸。去皮用。", "白话": "味甘辛，气香，性温，入足厥阴肝、足太阳膀胱经。入肝而行血分，走经络而达营郁，善于解风邪，最能调肝（木）气，升举清阳下陷，降浊阴冲逆，舒筋脉拘急，利关节壅阻，入肝胆而散遏抑。极能止痛，通经络而开痹涩；很能去湿寒，能止奔豚，更能安惊悸。去皮用。"}, {"source": "条111｜《神农本草经·下品》·桔梗", "原文": "《神农本草经·下品》：“味辛，微温。主胸胁痛如刀刺，腹满，肠鸣幽幽，惊恐悸气（", "白话": "味辛，微温。主治胸胁痛如刀刺、腹满、肠鸣幽幽、惊恐悸气（……"}, {"source": "条112｜《御览》·桔梗（《神农本草经》桔梗条校注）", "原文": "《御览》引云∶：一名利如。", "白话": "《太平御览》引此条说：（桔梗）又名利如。"}, {"source": "条113｜《大观本》·桔梗（《神农本草经》桔梗条校注）", "原文": "《大观本》作黑字）。生山谷。", "白话": "《大观本草》本作黑字（即《名医别录》文）。产于山谷。"}, {"source": "条114｜《本草经集注·草木中品》·桔梗", "原文": "《本草经集注·草木中品》：“味辛、苦，微温，有小毒。主治胸胁痛如刀刺，腹满，肠鸣幽幽，惊恐悸气。利五脏肠胃，补血气，除寒热风痹，温中消谷，治喉咽痛，下蛊毒。", "白话": "味辛、苦，微温，有小毒。主治胸胁痛如刀刺、腹满、肠鸣幽幽、惊恐悸气。利五脏肠胃，补血气，除寒热风痹，温中消谷，治咽喉疼痛，下蛊毒。"}, {"source": "条115｜《本草蒙筌·草部中》·桔梗", "原文": "《本草蒙筌·草部中》：“味辛、苦，气微温。味厚气轻，阳中阴也，有小毒。嵩山虽盛，近道亦多。交秋分后采根，噬味苦者入药。芦苗去净泔渍洗米泔渍一宿。焙干。入手足肺胆二经，畏白芨白及、龙眼、龙胆。开胸膈除上气壅，清头目散表寒邪。驱胁下刺疼，通鼻中窒塞。咽喉肿痛急觅，中恶蛊毒当求。逐肺热住咳下痰，治肺痈排脓养血。仍消恚怒，尤却怔忡。", "白话": "味辛、苦，气微温。味厚气轻，阳中阴，有小毒。嵩山虽盛产，近道也多。秋分后采根，口尝味苦的入药。去掉芦头，用米泔水浸洗一夜，焙干。入手太阴肺、足少阳胆经。畏白及、龙眼、龙胆。开胸膈除上气壅，清头目散表寒邪。驱胁下刺痛，通鼻中窒塞。咽喉肿痛急寻此药，中恶蛊毒当求此药。逐肺热止咳下痰，治肺痈排脓养血。又能消恚怒，尤能祛怔忡。"}, {"source": "条116｜《万氏家抄济世良方·药性草部》·桔梗", "原文": "《万氏家抄济世良方·药性草部》：“桔梗臣。味辛苦，气微温，有小毒主胸胁痛，腹满肠鸣，惊悸，鼻塞咽痛，利胸膈。治肺热嗽逆，消痰。疗小儿惊痫、客忤。载诸药不沉，又能升提气血。", "白话": "桔梗为臣药。味辛苦，气微温，有小毒。主胸胁痛、腹满肠鸣、惊悸、鼻塞咽痛，利胸膈。治肺热咳嗽上逆，消痰。疗小儿惊痫、客忤。能载诸药上行而不下沉，又能升提气血。"}, {"source": "条117｜《本草正·山草部》·桔梗", "原文": "《本草正·山草部》：“味苦微辛，气微凉。气轻于味，阳中有阴，有小毒。其性浮。用此者，用其载药上升，故有舟楫之号，入肺、胆、胸膈、上焦。载散药表散寒邪；载凉药清咽疼喉痹，亦治赤目肿痛；载肺药解肺热肺痈，鼻塞唾脓咳嗽；载痰药能消痰止呕，亦可宽胸下气。引大黄可使上升，引青皮平肝止痛。能解中恶蛊毒，亦治惊痈怔忡。若欲专用降剂，此物不宜同用。", "白话": "味苦微辛，气微凉。气轻于味，阳中有阴，有小毒。其性浮。用它是为了载药上升，所以有舟楫之号，入肺、胆、胸膈、上焦。载散药以表散寒邪；载凉药以清咽痛喉痹，也治目赤肿痛；载肺药以解肺热肺痈、鼻塞唾脓咳嗽；载痰药能消痰止呕，也可宽胸下气。引大黄可使上升，引青皮平肝止痛。能解中恶蛊毒，也治惊痫怔忡。如果要用纯粹的降剂，此物不宜同用。"}, {"source": "条118｜《杂症痘疹药性主治合参·草部上》·桔梗", "原文": "《杂症痘疹药性主治合参·草部上》：“味辛、苦、甘、平，微温，无毒。入手足肺胆二经。主中恶虫毒，风热喘促，开胸隔，利肺经。除壅之气于上焦，清头目解诸风，散寒冷之邪于肌表，驱胁下刺疼，通鼻中窒塞，咽喉肿痛，施治如神。逐肺热，疗咳嗽而下痰涎，治肺痈，排腐脓而养新血。仍消恚怒，尤却怔忡，解利小儿惊痫，开提男子气血。", "白话": "味辛、苦、甘、平，微温，无毒。入手太阴肺、足少阳胆经。主治中恶虫毒、风热喘促，开胸膈，利肺经。除上焦壅滞之气，清头目解诸风，散肌表寒冷之邪，驱胁下刺痛，通鼻中窒塞，咽喉肿痛，施治如神。逐肺热，疗咳嗽而下痰涎，治肺痈，排腐脓而养新血。又能消恚怒，尤能祛怔忡，解治小儿惊痫，开提男子气血。"}, {"source": "条119｜《本草征要·（一）补气》·党参", "原文": "《本草征要·（一）补气》：“味甘，性平，无毒。入脾、肺二经。补中益气，脾肺均宜。健脾运而中宫不燥。滋胃阴而胸膈不泥。润肺而不犯寒凉、养血而不偏滋腻。中气微弱、气短心悸。食少便溏、体倦易疲。鼓午清阳，常服有济。党参功同人参，而力量较薄，但能久服、可无大弊。", "白话": "味甘，性平，无毒。入脾、肺二经。补中益气，脾肺均宜。健脾运而中宫不燥，滋胃阴而胸膈不滞。润肺而不犯寒凉，养血而不偏滋腻。治中气微弱、气短心悸、食少便溏、体倦易疲。升发清阳，常服有益。党参功用同人参，但力量较薄，然可久服，没有大害。"}, {"source": "条120｜《本草征要·（一）巅颠顶、头面用药》·桑椹子", "原文": "《本草征要·（一）巅颠顶、头面用药》：“桑椹子，味甘、酸。性偏温。入肝、肾二经。补肝益肾，养血生津。头旋心悸，目眩耳鸣。须发早白，便秘难行。此子能润滑大肠，故大便稀者勿用。", "白话": "桑椹子，味甘、酸，性偏温。入肝、肾二经。补肝益肾，养血生津。治头旋心悸、目眩耳鸣、须发早白、便秘难行。此子能润滑大肠，故大便稀者勿用。"}, {"source": "条121｜《本草发挥·草部》·黄连", "原文": "《本草发挥·草部》：“味苦，寒，无毒。主热气，目痛眦伤泪出，明目，腹痛，止烦渴，益胆。杀小儿疳虫，点赤眼昏痛，镇肝，治惊悸烦躁，润心肺，长肉止血，并疮疥、盗汗。", "白话": "味苦，性寒，无毒。主治热气、目痛眦伤流泪，明目，腹痛，止烦渴，益胆。杀小儿疳虫，点治赤眼昏痛，镇肝，治惊悸烦躁，润心肺，长肉止血，并治疮疥、盗汗。"}, {"source": "条122｜《本草集要·草部上》·黄连", "原文": "《本草集要·草部上》：“味苦，气寒。味厚气薄，阴中阳也。无毒。入手少阴经。……主热气，目痛眦伤，泣出。明目，肠澼，腹痛，下痢，妇人阴中肿痛。久服令人不忘。镇肝益胆，眼暴赤肿。久下赤白脓血，为治痢之最。解热毒，泻心火，止惊悸，止消渴，调胃厚肠，除胃中湿热，烦躁恶心，郁热在中焦，兀兀欲吐，心下痞满及诸疮肿毒必用之。", "白话": "味苦，气寒。味厚气薄，阴中阳。无毒。入手少阴经。……主治热气、目痛眦伤流泪，明目，治肠澼、腹痛、下痢、妇人阴中肿痛。久服使人不忘。镇肝益胆，治目暴赤肿。久下赤白脓血，是治痢的首选。解热毒，泻心火，止惊悸，止消渴，调胃厚肠，除胃中湿热、烦躁恶心、郁热在中焦、兀兀欲吐、心下痞满及诸疮肿毒——必用之药。"}, {"source": "条123｜《本草汇言·草部山草类》·黄连", "原文": "《本草汇言·草部山草类》：“……又如惊悸怔忡，烦乱恍惚而神志不宁，痛痒疮疡，癍毒瘄痘，而邪热有余，黄连为必用也。", "白话": "……又如惊悸怔忡、烦乱恍惚而神志不宁，痛痒疮疡、癍毒疹痘，凡邪热有余的，黄连是必用之药。"}, {"source": "条124｜《雷公炮制药性解·草部上》·黄连", "原文": "《雷公炮制药性解·草部上》：“黄连，味苦，性寒，无毒，入心经。主心火炎，目疾暴发，疮疡红肿，肠红下痢，痞满泄泻，小儿疳热，消口中疮，惊悸烦躁，天行热疾。黄芩、龙骨、连翘、滑石为使，恶菊花、芫花、玄参、白藓、白僵蚕，畏款冬花，解巴豆、乌头毒，忌猪肉、冷水。", "白话": "黄连，味苦，性寒，无毒，入心经。主治心火上炎、目疾暴发、疮疡红肿、肠红下痢、痞满泄泻、小儿疳热、口中生疮、惊悸烦躁、天行热病。黄芩、龙骨、连翘、滑石为使药；恶菊花、芫花、玄参、白藓皮、白僵蚕；畏款冬花；能解巴豆、乌头之毒；忌猪肉、冷水。"}, {"source": "条125｜《得配本草·草部山草类》·黄连", "原文": "《得配本草·草部山草类》：“川黄连大苦大寒。入手少阴经气分。泻心脾，凉肝胆，清三焦，解热毒，燥湿开郁，治心窍恶血，阳毒发狂，惊悸烦躁，恶心痞满，吞酸吐酸，心腹诸痛，肠澼泻痢，疳疾虫症，痈疽疮疥，暴赤目痛，牙疳口疮，孕妇腹中儿啼，胎惊子烦，阴户肿痛。", "白话": "川黄连大苦大寒。入手少阴经气分。泻心脾，凉肝胆，清三焦，解热毒，燥湿开郁，治心窍恶血、阳毒发狂、惊悸烦躁、恶心痞满、吞酸吐酸、心腹诸痛、肠澼泻痢、疳疾虫证、痈疽疮疥、暴发赤眼目痛、牙疳口疮、孕妇腹中儿啼、胎惊子烦、阴户肿痛。"}, {"source": "条126｜《本草详节·草部》·黄连", "原文": "《本草详节·草部》：“味苦，气寒。味厚气薄，可升可降，沉也，阴也，阴中微阳。……主心病逆而盛，心积伏梁，心窍恶血，肠澼腹痛，下痢，调胃厚肠，清肝胆火，止消渴，目痛，惊悸，盗汗，天行热疾，杀疳虫、蛔虫，口疮，诸疮疥。", "白话": "味苦，气寒。味厚气薄，可升可降，性沉，属阴，阴中微阳。……主治心病气逆而盛、心积伏梁、心窍恶血、肠澼腹痛、下痢，调胃厚肠，清肝胆火，止消渴、目痛、惊悸、盗汗，治天行热病，杀疳虫蛔虫，治口疮、诸疮疥。"}, {"source": "条127｜《随息居饮食谱·果食类》·梨", "原文": "《随息居饮食谱·果食类》：“甘凉。润肺清胃，凉心涤热，息风化痰已嗽，养阴濡燥，散结通肠，消痈疽，止烦渴。解丹石烟煤炙煿、膏粱、曲蘗 诸毒。治中风不语、痰热惊狂、温暑等疴。并绞汁服，名天生甘露饮。以皮薄心小，肉细无渣，略无酸味者良。……中虚寒泻，乳妇金疮忌之。新产及病后，须蒸熟食之。", "白话": "味甘性凉。润肺清胃，凉心涤热，息风化痰止嗽，养阴润燥，散结通肠，消痈疽，止烦渴。解丹石、烟煤、炙煿、膏粱厚味、酒曲诸毒。治中风不语、痰热惊狂、温暑等病。并可绞汁服，名叫天生甘露饮。以皮薄心小、肉细无渣、略无酸味者为良。……中焦虚寒泄泻者、乳妇、金疮患者忌。新产及病后须蒸熟食。"}, {"source": "条128｜《长沙药解》卷三·麻黄", "原文": "《长沙药解》卷三：“味苦、辛，气温，入手太阴肺、足太阳膀胱经。入肺家而行气分，开毛孔而达皮部，善泻卫郁，专发寒邪，治风湿之身痛，疗寒湿之脚肿，风水可驱，溢饮能散，消咳逆肺胀，解惊悸心忡。", "白话": "味苦、辛，气温，入手太阴肺、足太阳膀胱经。入肺而行气分，开毛孔而达皮表，善于泻卫郁，专发寒邪，治风湿身痛，疗寒湿脚肿，风水可驱，溢饮能散，消咳逆肺胀，解惊悸心忡。"}, {"source": "条129｜《神农本草经·下品》·旋覆花", "原文": "《神农本草经·下品》：“味咸，温。主结气、胁下满、惊悸，除水，去五脏间寒热，补中下气。一名金沸草，一名盛椹。生川谷。", "白话": "味咸，性温。主治结气、胁下胀满、惊悸，除水，去五脏间寒热，补中下气。又名金沸草，又名盛椹。产于川谷。"}, {"source": "条130｜《本草经集注·草木下品》·旋覆花", "原文": "《本草经集注·草木下品》：“味咸、甘，温、微温，冷利，有小毒。主治结气，胁下满，惊悸，除水，去五脏间寒热，补中下气。消胸上痰结，唾如胶漆，心胁痰水，膀胱留饮，风气湿痹，皮间死肉，目中眵目蔑˙，利大肠，通血脉，益色泽。", "白话": "味咸、甘，温、微温，冷利，有小毒。主治结气、胁下胀满、惊悸，除水，去五脏间寒热，补中下气。消胸上痰结、唾如胶漆、心胁痰水、膀胱留饮、风气湿痹、皮间死肉、目中眵糊（“目蔑˙”为原稿讹字），利大肠，通血脉，益色泽。"}, {"source": "条131｜《本草蒙筌·草部下》·旋覆花", "原文": "《本草蒙筌·草部下》：“味咸、甘，气温。无毒。一云冷利。有小毒。丛生深谷中，又名金沸草。颜色深黄如菊，人又呼金钱花。七月采收，曝干入药。治头风明目，逐水湿通便。去心满噫气痞坚，消胸结痰唾胶漆。惊悸亦止，寒热兼除。倘病者稍涉虚羸，防损气不宜多服。叶理金疮止血，根主风湿续筋。", "白话": "味咸、甘，气温。无毒（一说冷利，有小毒）。丛生深谷中，又名金沸草。颜色深黄如菊，人又称金钱花。七月采收，晒干入药。治头风明目，逐水湿通便。去心胸满闷、噫气痞坚，消胸中痰结唾如胶漆。惊悸也能止，寒热兼除。倘若病人稍见虚弱，防其损气，不宜多服。叶治金疮止血，根主风湿续筋。"}, {"source": "条132｜《医学入门·治湿门》·旋覆花", "原文": "《医学入门·治湿门》：“旋覆花咸甘冷烈，逐水消痰止呕噎，宽胸胁清头目风，治痹又利肠脏结。花如菊，淡黄绿，繁茂圆而复下，俗名金沸草。有小毒。治心胁痰水及膀胱留饮，寒热水肿，消胸上痰结、唾如胶漆，开胃，止呕逆不下食；治伤寒汗吐下后心下痞坚，噫气不止及结气胁下满，去头面风、目中眵˙、风气湿痹、皮间死肌，利大肠，去五脏间寒热结气。兼通血脉，除惊，补中下气。", "白话": "旋覆花咸甘冷烈，逐水消痰止呕噎，宽胸胁、清头目风，治痹又利肠脏结。花如菊，淡黄绿，繁茂圆而下垂，俗名金沸草。有小毒。治心胁痰水及膀胱留饮、寒热水肿，消胸上痰结、唾如胶漆，开胃，止呕逆不能食；治伤寒汗吐下后心下痞坚、噫气不止及结气胁下满，去头面风、目中眵、风气湿痹、皮间死肌，利大肠，去五脏间寒热结气。兼通血脉，除惊，补中下气。"}, {"source": "条133｜《本草汇言·草部隰草类》·旋覆花", "原文": "《本草汇言·草部隰草类》：“消痰逐水，利气下行之药也(寇氏)。主心肺结气(白尚之稿)，胁下虚满，胸中结痰，痞坚噫气，或心脾伏饮，膀胱留饮宿水等证。大抵此剂，味咸以软坚散痞硬，性利以下气行痰水，实消伐之药也。本草有定惊悸，补中之说，窍思痰闭心胞脾络之间，往往令人病惊，旋覆破痰逐饮，痰饮去，则胞络清净而无碍，五志自宁，惊悸安矣。又饮消则脾健，脾健则能运行饮食，中气自受其益而补养矣。然行痰水，下结气，是", "白话": "是消痰逐水、利气下行的药（寇氏说）。主治心肺结气（白尚之稿）、胁下虚满、胸中结痰、痞坚噫气，或心脾伏饮、膀胱留饮宿水等证。大抵此药味咸以软坚散痞硬，性利以下气行痰水，实是消伐之品。本草有“定惊悸、补中”之说，我思痰闭于心包脾络之间，往往使人病惊；旋覆花破痰逐饮，痰饮去则心包之络清净无碍，五志自宁，惊悸得安。又饮消则脾健，脾健则能运行饮食，中气自然受益而得补养。然而行痰水、下结气是它的专功，病人涉虚者不宜多服；冷利大肠，虚寒人禁用。"}, {"source": "条134｜《得配本草·草部》·旋覆花", "原文": "《得配本草·草部》：“苦辛，温。入手太阴、阳明经气分。降心脾伏饮，去五脏寒热，除胁下气满，破膈痰如漆，止呕逆，平惊悸。", "白话": "味苦辛，性温。入手太阴、阳明经气分。降心脾伏饮，去五脏寒热，除胁下气满，破膈间如胶漆之痰，止呕逆，平惊悸。"}, {"source": "条135｜《痰火点雪·附：捷方》·清河参", "原文": "《痰火点雪·附：捷方》：“清河参补五脏，安精神，定魂魄，又止惊悸，断淫梦，保中守神。", "白话": "清河参补五脏，安精神，定魂魄，又止惊悸，断淫梦，保中守神。"}, {"source": "条136｜《本草集要·木部》·淡竹叶", "原文": "《本草集要·木部》：“味辛、甘，气寒。主胸中痰热，咳逆上气，吐血热毒风，压丹石毒，止消渴。烧沥味甘，性缓。治卒中风，失音不语，风痹，胸中热狂烦闷，壮热头痛头风，并怀妊人头旋倒地。安胎，治子烦。除阴虚人发大热，消虚痰，痰盛人、气虚少食者宜用之。又痰在四肢、非此不能开。止惊悸，瘟疫迷闷，小儿惊痫天吊，茎叶同用。", "白话": "味辛、甘，气寒。主治胸中痰热、咳逆上气、吐血热毒风，解丹石毒，止消渴。烧取竹沥味甘，性缓。治卒中风、失音不语、风痹、胸中热狂烦闷、壮热头痛头风，及孕妇头眩倒地。安胎，治子烦。除阴虚人发大热，消虚痰——痰盛之人、气虚少食者宜用。又痰在四肢，非此不能开。止惊悸、瘟疫迷闷、小儿惊痫天吊，茎叶同用。"}, {"source": "条137｜《本草蒙筌·木部》·淡竹叶", "原文": "《本草蒙筌·木部》：“", "白话": "（此段原稿仅存引书起首标记，正文见下条《衍义》引文。）"}, {"source": "条138｜《衍义》·淡竹叶（《本草蒙筌》条内引书）", "原文": "《衍义》云：胎前不损子，产后不得虚。止惊悸，却痰涎。痰在手足四肢，非此不达；痰在皮里膜外，有此可驱。", "白话": "《本草衍义》说：胎前不损胎儿，产后不致虚弱。止惊悸，祛痰涎。痰在手足四肢，非此不能达；痰在皮里膜外，有此可以驱。"}, {"source": "条139｜《本草详节·木部》·淡竹叶", "原文": "《本草详节·木部》：“味辛、甘，气平、寒。阴中微阳，降也……主胃中痰热，咳逆上气，热狂烦闷，壮热头痛，头风，止惊悸，消渴，不睡，喉痹，妊妇头旋倒地，小儿惊痫天吊，煎汁漱齿血，洗脱肛，压丹石毒。", "白话": "味辛、甘，气平、寒。阴中微阳，主降。……主治胃中痰热、咳逆上气、热狂烦闷、壮热头痛、头风，止惊悸，治消渴、不寐、喉痹、妊妇头眩倒地、小儿惊痫天吊；煎汁漱口治齿血，洗脱肛，解丹石毒。"}, {"source": "条140｜《食物本草·菜类》·淡笋", "原文": "《食物本草·菜类》：“淡笋，即中母笋，味甘。主消痰，除热狂壮热、头痛风，并妊人头旋倒地、惊悸、温疫迷闷、小儿惊痫天吊等症。多食发背闷脚气。", "白话": "淡笋即中母笋，味甘。主治消痰，除热狂壮热、头痛风，及孕妇头眩倒地、惊悸、温疫迷闷、小儿惊痫天吊等症。多食会发背部闷胀、脚气。"}, {"source": "条141｜《本草汇言·木部寓木类》·琥珀", "原文": "《本草汇言·木部寓木类》：“味甘，气平，无毒。阳中之阴，降也。入手少阴、太阳、足厥阴经。琥珀镇定心神、澄清浊气、行逐瘀血之药也", "白话": "味甘，气平，无毒。阳中之阴，主降。入手少阴、手太阳、足厥阴经。琥珀是镇定心神、澄清浊气、行逐瘀血的药……"}, {"source": "条142｜《别录》·琥珀（《本草汇言》琥珀条内引书）", "原文": "《别录》。（方吉人稿）此得松木清气所结，精英所聚，质坚如石，体轻如桴。原其清明莹洁之相，故大氏方治心气浮越，躁乱不宁，以致失神丧志，魂魄不定，或惊悸怔仲怔忡，癫痫昏塞，或睡寐阴邪，鬼魅凭附，他如瘀血败秽，留滞经络，或目珠翳障，或腹胃瘕蛊，或小便淋闭结塞不通，此药如神明在躬，奠安神室，故惊狂可定；如晓霞秋露，清净无滓，故瘀血、蛊瘕、目翳、淋闭诸证可退矣。但体质轻清，而性多燥。如血燥阴虚，肾亏髓乏，以", "白话": "（承上，标示《别录》文并方吉人稿注）此物得松木清气所结，精英所聚，质坚如石，体轻如桴。推原它清明莹洁之相，所以大氏方用治心气浮越、躁乱不宁，以致失神丧志、魂魄不定，或惊悸怔忡、癫痫昏塞，或睡梦中阴邪鬼魅凭附；又如瘀血败秽留滞经络，或目生翳障，或腹胃瘕蛊，或小便淋闭结塞不通——此药如神明在身，奠安神室，所以惊狂可定；如晓霞秋露清净无滓，所以瘀血、蛊瘕、目翳、淋闭诸证可退。但体质轻清而性多燥，如血燥阴虚、肾亏髓乏，以致水涸火炎、小便不通的，服之反增燥急之苦。用者宜审。"}, {"source": "条143｜《玉楸药解·木部》·琥珀", "原文": "《玉楸药解·木部》：“琥珀凉肺清肝，磨障翳，止惊悸，除遗精白浊，下死胎胞衣，涂面益色，敷疔拔毒，止渴除烦，滑胎摧生。", "白话": "琥珀凉肺清肝，磨消目翳，止惊悸，除遗精白浊，下死胎胞衣，涂面益色，外敷疔疮拔毒，止渴除烦，滑胎催生。"}, {"source": "条144｜《证类本草》卷第九·款冬花", "原文": "《证类本草》卷第九：“日华子云：润心肺，益五脏，除烦，补劳劣，消痰止嗽，肺瘘吐血，心虚惊悸，洗肝明目及中风等疾。", "白话": "日华子说：润心肺，益五脏，除烦，补劳损，消痰止嗽，治肺痿吐血、心虚惊悸，洗肝明目及中风等疾。"}, {"source": "条145｜《本草集要·草部》·款冬花", "原文": "《本草集要·草部》：“味辛、甘，气温。无毒……主咳逆上气，善喘息，呼吸连连不绝，涕唾稠粘黏。润心肺，消痰止咳。治肺痿痈，吐脓血。心虚惊悸，洗肝明目，喉痹诸惊痫寒热邪气，除烦补劳劣。古今治咳之最。", "白话": "味辛、甘，气温。无毒。……主治咳逆上气、喘息连连不绝、涕唾稠粘。润心肺，消痰止咳。治肺痿肺痈、吐脓血。心虚惊悸，洗肝明目，治喉痹、诸惊痫寒热邪气，除烦补劳损。是古今治咳第一。"}, {"source": "条146｜《本草蒙筌》卷之二·款冬花", "原文": "《本草蒙筌》卷之二：“味辛、甘，气温。阳也。无毒。生常山县名，属浙江。山谷，及上党（注前）水傍。叶大成丛似葵，花出根下如菊。百草中惟唯此不顾冰雪，最先春者也。原呼钻冻，今名款冬。择未舒嫩蕊采收，去向外裹花零壳。甘草汤浸一宿，待干揉碎才煎。恶硝石、皂荚、玄参，畏麻黄、辛夷、贝母，仍畏四味芩连耆葙，。黄芩、黄连、黄耆、青葙。，使杏仁，宜紫菀。治肺痈脓血腥臭，止肺咳痰唾稠粘黏。润肺泻火邪，下气定喘促。却", "白话": "味辛、甘，气温。属阳。无毒。产于常山县（属浙江）山谷及上党水边。叶大成丛似葵，花从根下发出如菊。百草中只有它不畏冰雪，是最先报春的。原名钻冻，今名款冬。选未开放的嫩蕊采收，去掉外裹的花壳。用甘草汤浸一夜，待干揉碎才煎。恶硝石、皂荚、玄参；畏麻黄、辛夷、贝母，又畏黄芩、黄连、黄耆、青葙四味；使药杏仁，宜配紫菀。治肺痈脓血腥臭，止肺咳痰唾稠粘。润肺泻火邪，下气定喘促。祛心虚惊悸，去邪热惊痫。补劳损除烦，洗肝明目。又治久嗽，可烧烟吸入。"}, {"source": "条147｜《本草经集注·草木中品》·紫菀", "原文": "《本草经集注·草木中品》：“味苦、辛，温，无毒。主治咳逆上气，胸中寒热结气，去蛊毒、痿蹶，安五脏。治咳唾脓血，止喘悸，五劳体虚，补不足，小儿惊痫。", "白话": "味苦、辛，温，无毒。主治咳逆上气、胸中寒热结气，去蛊毒、痿蹶，安五脏。治咳唾脓血，止喘悸，治五劳体虚、补不足、小儿惊痫。"}, {"source": "条148｜《顾松园医镜·谷部》·黑芝麻", "原文": "《顾松园医镜·谷部》：“胡麻（即黑芝麻，一名巨胜。甘平，入脾、肝、肾三经。九蒸九晒研）益肝养血，治虚风而理瘫痪。（虚风者肝虚血少，热盛生风也。李廷飞云：患风病人，久食则步履端正，语言不謇。正治风先治血，血行风自灭之义）滋肾润燥，填髓脑而坚筋骨。（肾恶燥，黑色通肾，而能润燥。肾得滋补，则髓脑充满，而筋骨坚强）补中益气，（甘能益脾胃也）变白还黑。（黑须发者，补阴养血之功）长肌肉，（脾主肌肉也）明耳目。", "白话": "胡麻（即黑芝麻，又名巨胜。味甘平，入脾、肝、肾三经。九蒸九晒研用）益肝养血，治虚风而调理瘫痪。（虚风是肝虚血少、热盛生风。李廷飞说：患风病的人久食则步履端正、言语不謇——正是“治风先治血，血行风自灭”之义。）滋肾润燥，填髓脑而坚筋骨。（肾恶燥，黑色通肾而能润燥；肾得滋补，则髓脑充满而筋骨坚强。）补中益气，（甘能益脾胃。）使白发变黑。（黑须发是补阴养血之功。）长肌肉，（脾主肌肉。）明耳目。（耳为肾窍，目为肝窍。）止心惊，（心血得养。）利大肠。（多油而滑。）润养五脏。谷类之中只有"}, {"source": "条149｜《神农本草经·上品》·蜂蜜", "原文": "《神农本草经·上品》：“味甘，平。主心腹邪气，诸惊痫痓，安五藏五脏，诸不足，益气补中，止痛解毒，除众病，和百药。久服，强志轻身，不饥不老。一名石饴。生山谷。", "白话": "味甘，性平。主治心腹邪气、诸惊痫痓，安五脏，补诸不足，益气补中，止痛解毒，除众病，和百药。久服，强志轻身，不饥不老。又名石饴。产于山谷。"}, {"source": "条150｜《药性赋·平性》·酸枣仁", "原文": "《药性赋·平性》：“酸枣仁去怔忡之病。", "白话": "酸枣仁能去怔忡之病。"}, {"source": "条151｜《本草集要·木部》·酸枣仁", "原文": "《本草集要·木部》：“味酸，气平。无毒……主心腹寒热，邪结气聚，四肢酸疼湿痹，筋骨风。脐上下痛，心虚烦及振悸不得眠。宁心志，敛虚汗，止烦渴。补中益肝气，坚筋骨，助阴气。久服安五脏，轻身延年。", "白话": "味酸，气平。无毒。……主治心腹寒热、邪结气聚、四肢酸疼湿痹、筋骨风、脐上下疼痛、心虚烦及振悸不得眠。宁心志，敛虚汗，止烦渴。补中益肝气，坚筋骨，助阴气。久服安五脏，轻身延年。"}, {"source": "条152｜《杂症痘疹药性主治合参·木部》·酸枣仁", "原文": "《杂症痘疹药性主治合参·木部》：“酸枣仁，宁心益肝，敛汗止渴，心胸寒热，邪结气聚，四肢酸痛，湿痹，心烦意乱不眠，胆虚易惊悸，脾虚不嗜食，心虚易出汗，安神魂宁意，补中气，助阴，坚筋骨，安五脏，久服令人肥健轻身延年……按：枣仁，心、肝、胆三经气分之药、虽能宁心，更能宜肝，故若肝旺烦躁不宁者，及心阴不足，惊悸恍惚者，必同滋阴和肝养心之血药，相佐而用，其功乃见，否则心气无阴以敛，肝气得补而强，益增烦躁矣。", "白话": "酸枣仁，宁心益肝，敛汗止渴，治心胸寒热、邪结气聚、四肢酸痛、湿痹、心烦意乱不眠、胆虚易惊悸、脾虚不思食、心虚易出汗；安神魂宁意，补中气，助阴，坚筋骨，安五脏，久服使人肥健轻身延年。……按语：枣仁是心、肝、胆三经气分之药，虽能宁心，更能疏肝；所以若肝旺烦躁不宁者，以及心阴不足、惊悸恍惚者，必须配滋阴和肝养心血之药相佐而用，功效才显；否则心气无阴来收敛，肝气得补而更强，反而更增烦躁。"}, {"source": "条153｜《雷公炮制药性解·草部上》·熟地黄", "原文": "《雷公炮制药性解·草部上》：“熟地黄味甘苦，性温无毒，入心肝肾三经。活血气，封填骨髓；滋肾水，补益真阴。伤寒后胫股疼痛，新产后脐腹难禁。利耳目，乌须发，治五劳七伤，能安魂定魄。使忌畏恶，俱同生地，性尤泥滞，姜酒浸用。按：熟地黄为补血之剂，而心与肝，藏血生血者也，故能入焉。其色黑，其性沉阴重浊。", "白话": "熟地黄味甘苦，性温无毒，入心、肝、肾三经。活血气，封填骨髓；滋肾水，补益真阴。治伤寒后胫股疼痛、新产后脐腹痛不可忍。利耳目，乌须发，治五劳七伤，能安魂定魄。使、忌、畏、恶诸项都同生地；性尤泥滞，用姜酒浸制。按语：熟地黄是补血之剂，而心与肝是藏血生血的脏，所以能入心肝。其色黑，其性沉阴重浊……"}, {"source": "条154｜《经》·熟地黄（《雷公炮制药性解》条内引书）", "原文": "《经》曰：浊中浊者，坚强骨髓，肾主骨，故入之。精血既足，则胫股脐腹之证自愈，耳目须发，必受其益，而劳伤惊悸并可痊矣。", "白话": "《内经》说：浊中之浊者，能坚骨强髓；肾主骨，所以入肾。精血既足，则胫股脐腹诸证自愈，耳目须发必受其益，而劳伤惊悸也都可以痊愈。"}, {"source": "条155｜《神农本草经·上品》·薇衔", "原文": "《神农本草经·上品》：“味苦，平。主风湿痹，历节痛，惊痫，吐舌，悸气，贼风，鼠瘘，痈肿。一名糜衔。生川泽。", "白话": "味苦，性平。主治风湿痹、历节痛、惊痫、吐舌、悸气、贼风、鼠瘘、痈肿。又名糜衔。产于川泽。"}, {"source": "条156｜《本草经集注·草木中品》·薇衔", "原文": "《本草经集注·草木中品》：“味苦，平、微寒，无毒。主治风湿痹，历节痛，惊痫吐舌，悸气，贼风，鼠瘘，痈肿，暴症，逐水，治痿蹶。久服轻身明目。", "白话": "味苦，平、微寒，无毒。主治风湿痹、历节痛、惊痫吐舌、悸气、贼风、鼠瘘、痈肿、暴癥，逐水，治痿蹶。久服轻身明目。"}, {"source": "条157｜《杂症痘疹药性主治合参·草部下》·薇衔", "原文": "《杂症痘疹药性主治合参·草部下》：“薇衔根有两股，大者名大吴风草，小者名小吴风草。秦皮为使，主风淫湿痹，致历节酸痛，疗吐泻惊痈，及鼠漏痈肿，却热除痿蹶，逐水消暴癥。妇人服之，绝产无子，吐舌悸气、癫狂等症并祛。", "白话": "薇衔根有两种：大的叫大吴风草，小的叫小吴风草。秦皮为使药。主治风淫湿痹所致历节酸痛，疗吐泻、惊痫及鼠漏痈肿，退热除痿蹶，逐水消暴癥。妇人服之会绝产无子；吐舌悸气、癫狂等症也一并祛除。"}, {"source": "条158｜《折肱漫录·养形篇下》·糯米", "原文": "《折肱漫录·养形篇下》：“世人皆言糯米补人，考之本草云：主温中，令人多热，久食令人身软，发心悸。又云：多食令人多睡，发风动气，则不如粳米多矣。", "白话": "世人都说糯米补人，考察本草说：它主温中，使人多热，久食使人身体软弱、引发心悸。又说多食使人多睡、发风动气，那么远不如粳米。"}, {"source": "条159｜《神农本草经·中品》·天鼠屎", "原文": "《神农本草经·中品》：“味辛，寒。主面痈肿，皮肤洗洗时痛，肠中血气，破寒热积聚，除惊悸。一名鼠，一名石肝。生山谷。", "白话": "味辛，性寒。主治面部痈肿、皮肤淅淅时痛、肠中血气不和，破寒热积聚，除惊悸。又名鼠、石肝。产于山谷。"}, {"source": "条160｜《本草经集注·下品》·天鼠屎", "原文": "《本草经集注·下品》：“味辛，寒，有毒。主治面痈肿，皮肤说说，时痛，腹中血气，破寒热积聚，除惊悸，去面黑˙", "白话": "味辛，性寒，有毒。主治面部痈肿、皮肤淅淅（“说说”为“洗洗”之讹）、时痛、腹中血气不和，破寒热积聚，除惊悸，去面部黑斑（“黑˙”后原稿脱字）。"}, {"source": "条161｜《证类本草》卷第十六·牛黄", "原文": "《证类本草》卷第十六：“牛黄味苦，平，有小毒。主惊痫寒热，热盛狂痓，除邪逐鬼，疗小儿百病，诸痫热，口不开，大人狂癫，又堕胎。久服轻身增年，令人不忘。……日华子云：牛黄，凉。疗中风失音，口噤，妇人血噤，惊悸，天行时疾，健忘，虚乏。", "白话": "牛黄味苦，性平，有小毒。主治惊痫寒热、热盛狂痓，除邪逐鬼，疗小儿百病、诸痫发热、口噤不开、大人狂癫，又堕胎。久服轻身增年、使人不忘。……日华子说：牛黄性凉。疗中风失音、口噤，妇人血噤、惊悸，天行时疾、健忘、虚乏。"}, {"source": "条162｜《本草纲目·兽之一》·牛黄", "原文": "《本草纲目·兽之一》：“主治惊痫寒热，热盛狂痓，除邪逐鬼", "白话": "主治惊痫寒热、热盛狂痓，除邪逐鬼……"}, {"source": "条163｜《本经》·牛黄（《本草纲目》牛黄条内引书）", "原文": "《本经》。疗小儿百病，诸痫热，口不开，大人狂癫，又堕胎。久服，轻身增年，令人不忘", "白话": "（承上，标示《本经》文）疗小儿百病、诸痫发热、口噤不开、大人狂癫，又堕胎。久服轻身增年、使人不忘。"}, {"source": "条164｜《别录》·牛黄（《本草纲目》牛黄条内引书）", "原文": "《别录》。主中风失音口噤，妇人血噤惊悸，天行时疾，健忘虚乏", "白话": "（承上，标示《别录》文）主治中风失音口噤、妇人血噤惊悸、天行时疾、健忘虚乏。"}, {"source": "条165｜《日华》·牛黄（《本草纲目》牛黄条内引书）", "原文": "《日华》。安魂定魄，辟邪魅，猝中恶，小儿夜啼甄权。益肝胆，定精神，除热，止惊痢，辟恶气，除百病思邈。清心化热，利痰凉惊宁源。痘疮紫色，发狂谵语者可用时珍，出王氏方。", "白话": "（承上，标示《日华》文并后世诸家）安魂定魄，辟邪魅，治猝中恶、小儿夜啼（甄权说）；益肝胆，定精神，除热，止惊痢，辟恶气，除百病（思邈说）；清心化热，利痰凉惊（宁源说）；痘疮色紫、发狂谵语者可用（时珍说，出王氏方）。"}, {"source": "条166｜《本草征要·心经及小肠经》·龙齿", "原文": "《本草征要·心经及小肠经》：“龙齿：镇心安神，定惊止痉。", "白话": "龙齿：镇心安神，定惊止痉。"}, {"source": "条167｜《神农本草经·上品》·龙骨", "原文": "《神农本草经·上品》：“味甘，平。主心腹鬼注，精物老魁，咳逆，泄利脓血，女子漏下癥瘕坚结，小儿热气惊痫。齿∶：主小儿、大人惊痫疾狂走，心下结气，不能喘息，诸痉，杀精物。久服，轻身、通神明、延年。生山谷。", "白话": "味甘，性平。主治心腹鬼注、精物老魅、咳逆、泄利脓血、女子漏下癥瘕坚结、小儿热气惊痫。龙齿：主小儿大人惊痫发狂奔走、心下结气、不能喘息、诸痉，杀精物。久服轻身、通神明、延年。产于山谷。"}, {"source": "条168｜《本草正·虫鱼部》·龙骨", "原文": "《本草正·虫鱼部》：“味甘，平，性收涩。其气入肝、肾。故能安神志，定魂魄，镇惊悸，涩肠胃，逐邪气，除夜梦鬼交、吐血衄血、遗精梦泄，收虚汗，止泻痢，缩小便，禁肠风下血、尿血、虚滑脱肛、女子崩淋带浊、失血漏胎、小儿风热惊痫，亦疗肠痈脏毒、内疽阴蚀，敛脓敛疮，生肌长肉，涩可去脱，即此属也。", "白话": "味甘，性平，性收涩。其气入肝、肾。所以能安神志，定魂魄，镇惊悸，涩肠胃，逐邪气，除夜梦鬼交、吐血衄血、遗精梦泄，收虚汗，止泻痢，缩小便，禁肠风下血、尿血、虚滑脱肛、女子崩淋带浊、失血漏胎、小儿风热惊痫，也疗肠痈脏毒、内疽阴蚀，敛脓敛疮、生肌长肉——“涩可去脱”就是这一类。"}, {"source": "条169｜《医学摘粹·固精类》·龙骨", "原文": "《医学摘粹·固精类》：“龙骨，味咸，微寒，性涩，入手少阴心、足少阴肾、足厥阴肝、足少阳胆经。敛神魂而定惊悸，保精血而收滑脱。", "白话": "龙骨，味咸，微寒，性涩，入手少阴心、足少阴肾、足厥阴肝、足少阳胆经。敛神魂而定惊悸，保精血而收滑脱。"}, {"source": "条170｜《神农本草经·上品》·牡蛎", "原文": "《神农本草经·上品》：“味咸，平。主伤寒寒热，温疟洒洒，惊恚怒气，除拘缓鼠，女子带下赤白。久服，强骨节，杀邪气，延年。一名蛎蛤。生池泽。", "白话": "味咸，性平。主治伤寒寒热、温疟洒淅、惊恚怒气，除拘缓鼠瘘，治女子赤白带下。久服强骨节，杀邪气，延年。又名蛎蛤。产于池泽。"}, {"source": "条171｜《长沙药解·卷四》·牡蛎", "原文": "《长沙药解·卷四》：“牡蛎咸寒降涩，秘精敛神，清金泻热，安神魂而保精液，凡心悸神惊，遗精盗汗之证皆医，崩中带下，便滑尿数之病俱疗。善消胸胁痞热，缘少阳之经，逆而不降，则胸胁硬满，而生瘀热，牡蛎降摄君相之火，甲木下行，经气松畅，硬满自消。一切痰血症瘕，瘿瘤瘰疬之类，得之则化，软坚消痞，功力独绝。", "白话": "牡蛎咸寒降涩，秘精敛神，清金泻热，安神魂而保精液；凡心悸神惊、遗精盗汗之证都能治，崩中带下、便滑尿多之病都能疗。善于消胸胁痞热——因少阳经气逆而不降，则胸胁硬满而生瘀热；牡蛎降摄君相之火，使甲木（胆）下行，经气松畅，硬满自消。一切痰血症瘕、瘿瘤瘰疬之类，得此药则化，软坚消痞，功效独绝。"}, {"source": "条172｜《本草正·虫鱼部》·龟板膏", "原文": "《本草正·虫鱼部》：“龟板膏功用亦同龟板，而性味浓厚，尤属纯阴。能退孤阳阴虚劳热，阴火上炎，吐血衄血，肺热咳喘，消渴烦扰，热汗惊悸，谵妄狂躁之要药。然性禀阴寒，善消阳气，凡阳虚假热，及脾胃命门虚寒等证，皆切忌之，毋混用也。若误用，久之则必致败脾妨食之患。", "白话": "龟板膏功用也同龟板，而性味浓厚，尤其属纯阴。能退孤阳、阴虚劳热、阴火上炎、吐血衄血、肺热咳喘、消渴烦扰、热汗惊悸、谵妄狂躁，是这方面的要药。但性禀阴寒，善于消损阳气，凡阳虚假热及脾胃命门虚寒等证，都切忌，不可混用。若误用，日久必致败脾妨食之患。"}, {"source": "条173｜《本草汇言·介部甲虫类》·珍珠", "原文": "《本草汇言·介部甲虫类》：“味咸，气寒，无毒，可升可降。入手少阴，足厥阴经。……故寇氏方用此治惊悸怔仲怔忡，癫狂恍惚，神志不宁，魂魄散乱，及小儿血气未定，精神不足尝多惊恐。”1619", "白话": "味咸，气寒，无毒，可升可降。入手少阴、足厥阴经。……所以寇氏方用它治惊悸怔忡、癫狂恍惚、神志不宁、魂魄散乱，及小儿血气未定、精神不足而常多惊恐。"}, {"source": "条174｜《医宗必读·虫鱼部》·珍珠", "原文": "《医宗必读·虫鱼部》：“味咸，寒，无毒。入肝经。……安魂定悸，止渴除蒸，收口生肌，点睛退翳。", "白话": "味咸，性寒，无毒。入肝经。……安魂定悸，止渴除蒸（骨蒸），收口生肌，点眼退翳。"}, {"source": "条175｜《本草经集注·中品》·蚱蝉", "原文": "《本草经集注·中品》：“味咸、甘，寒，无毒。主治小儿惊痫，夜啼，癫病，寒热，惊悸，妇人乳难，胞衣不出，又堕胎。", "白话": "味咸、甘，性寒，无毒。主治小儿惊痫、夜啼、癫病、寒热、惊悸，妇人难产、胞衣不下，又堕胎。"}, {"source": "条176｜《本草蒙筌·蚱蝉》·蚱蝉（蝉蜕）", "原文": "《本草蒙筌·蚱蝉》：“治产妇胎衣不下，通乳堕胎；主小儿惊痫夜啼，驱邪逐热。蝉蜕系脱换薄壳，翅足须除，去翳膜侵睛、胬肉满眦，眼科诚奇；蝉花乃状类花冠，生壳顶上，止天吊瘛疭、心悸怔忡，幼科中果效。", "白话": "治产妇胎衣不下，通乳堕胎；主小儿惊痫夜啼，驱邪逐热。蝉蜕是蝉脱换的薄壳，翅足须去掉；治翳膜侵睛、胬肉满眦，眼科确实奇效；蝉花形状像花冠，生于蝉壳顶上，止天吊瘛疭、心悸怔忡，在幼科中确有效验。"}, {"source": "条177｜《证类本草》卷第二十二·蛇蜕", "原文": "《证类本草》卷第二十二：“日华子云：治蛊毒，辟恶，止呕逆，治小儿惊悸，客忤，催生。疬疡，白癜风，煎汁敷。入药并炙用。", "白话": "日华子说：治蛊毒，辟恶，止呕逆，治小儿惊悸、客忤，催生。治瘰疬白癜风，煎汁外敷。入药都炙后用。"}, {"source": "条178｜《神农本草经·中品》·羚羊角", "原文": "《神农本草经·中品》：“味咸，温。主青盲，明目，杀疥虫，止寒泄，辟恶鬼虎野狼，止惊悸。久服，安心，益气，轻身。生川谷。", "白话": "味咸，性温。主治青盲，明目，杀疥虫，止寒泄，辟恶鬼虎狼，止惊悸。久服安心，益气，轻身。产于川谷。"}, {"source": "条179｜《本草经集注·中品》·羚羊角", "原文": "《本草经集注·中品》：“味咸、苦，温、微寒，无毒。主治青盲，明目，杀疥虫，止寒泄，辟恶鬼、虎、狼，止惊悸。治百节中结气，风头痛及蛊毒，吐血，妇人产后余痛。烧之杀鬼魅，辟虎狼。久服安心，益气力，轻身。取无时，勿使中湿，湿有毒。", "白话": "味咸、苦，温、微寒，无毒。主治青盲，明目，杀疥虫，止寒泄，辟恶鬼虎狼，止惊悸。治百节中结气、风头痛及蛊毒、吐血、妇人产后余痛。烧之杀鬼魅，辟虎狼。久服安心，益气力，轻身。采集不限时，勿使受湿，湿则有毒。"}, {"source": "条180｜《本草集要·兽部》·羚羊角", "原文": "《本草集要·兽部》：“味咸苦，气温、微寒。无毒。菟丝子为之使。青羝为佳。取无时，勿使中湿，湿则有毒。主青盲，明目。杀疥虫，止寒泄，止惊悸。又虫毒吐血，妇人产后余痛，小儿惊痫，烧之辟恶鬼、虎、野狼，去蛇。久服安心益气轻身。", "白话": "味咸苦，气温、微寒。无毒。菟丝子为使药。青黑色公羊（角）为佳。采集不限时，勿使受湿，湿则有毒。主治青盲，明目。杀疥虫，止寒泄，止惊悸。又治虫毒吐血、妇人产后余痛、小儿惊痫；烧之辟恶鬼虎狼、去蛇。久服安心益气轻身。"}, {"source": "条181｜《证类本草》卷第二十一·蝉花", "原文": "《证类本草》卷第二十一：“蝉花味甘，寒，无毒。主小儿天吊，惊痫瘛疭，夜啼心悸。", "白话": "蝉花味甘，性寒，无毒。主治小儿天吊、惊痫瘛疭、夜啼心悸。"}, {"source": "条182｜《雷公炮制药性解·禽兽部》·麝香", "原文": "《雷公炮制药性解·禽兽部》：“麝香，味辛，性温，无毒，入十二经。主恶气鬼邪，蛇虺蛊毒，惊悸痈疽，中恶心腹暴痛胀满，目中翳膜泪眵，风毒温疟痫痓，通关窍，杀蛊虱，催生堕胎。忌大蒜。", "白话": "麝香，味辛，性温，无毒，入十二经。主治恶气鬼邪、蛇虺蛊毒、惊悸痈疽、中恶心腹暴痛胀满、目中翳膜泪眵、风毒温疟痫痓，通关窍，杀蛊虱，催生堕胎。忌大蒜。"}, {"source": "条183｜《证类本草》卷第三·五色石英", "原文": "《证类本草》卷第三：“治心腹邪气，女人心腹痛，镇心，疗胃冷气，益毛发，悦颜色，治惊悸，安魂定魄，壮阳道，下乳，通亮者为上。其补益随脏色而治，青者治肝，赤者治心，黄者治皮肤，白者治肺，黑者治肾。", "白话": "治心腹邪气、女人心腹痛，镇心，疗胃中冷气，益毛发，悦颜色，治惊悸，安魂定魄，壮阳道，下乳。以通透明亮的为上。其补益随五色分治五脏：青色的治肝，赤色的治心，黄色的治皮肤，白色的治肺，黑色的治肾。"}, {"source": "条184｜《本草汇言·金石类》·石青", "原文": "《本草汇言·金石类》：“味甘，气平，无毒。……石青，下顽痰、去风痫（时珍）、定惊悸、明目疾神农、坚筋骨折伤之药也（", "白话": "味甘，气平，无毒。……石青是下顽痰、去风痫（时珍说）、定惊悸、明目疾（《神农本草经》说）、坚筋骨治折伤的药（……"}, {"source": "条185｜《别录》·石青（《本草汇言》石青条内引书）", "原文": "《别录》）。", "白话": "（承上，“坚筋骨折伤之药也”系《名医别录》所载。）"}, {"source": "条186｜《神农本草经·中品》·石膏", "原文": "《神农本草经·中品》：“味辛，微寒。主中风寒热，心下逆气惊喘，口干苦焦，不能息，腹中坚痛，除邪鬼，产乳，金创。生山谷。", "白话": "味辛，微寒。主治中风寒热、心下逆气惊喘、口干苦焦、呼吸困难、腹中坚痛，除邪鬼，治产乳、金创。产于山谷。"}, {"source": "条187｜《万氏家抄济世良方·药性石部》·石膏", "原文": "《万氏家抄济世良方·药性石部》：“石膏臣。味辛甘，气微寒、无毒。胃虚寒人不可服。主心下逆气，惊喘，口干舌焦，腹中坚痛，产乳，金疮。散诸热及伤寒时气头痛，壮热，日晡潮热，解肌出汗，制火润肺，泻胃火不食，又治胃热能食，缓脾益气，止渴生津，又揩齿益齿。", "白话": "石膏为臣药。味辛甘，气微寒，无毒。胃虚寒的人不可服。主治心下逆气、惊喘、口干舌焦、腹中坚痛、产乳、金疮。散诸热及伤寒时气头痛、壮热、日晡潮热，解肌出汗，制火润肺，泻胃火（治不食），又治胃热善饥，缓脾益气，止渴生津，又可揩齿固齿。"}, {"source": "条188｜《得配本草·石部》·白石英", "原文": "《得配本草·石部》：“甘辛，微温。入手太阴阳明经气分。除风湿痿痹，疗寒气咳逆，利小便，治肺痈。得朱砂，治惊悸。……煅研，水飞用。久服多服，则元气下陷。", "白话": "味甘辛，微温。入手太阴、阳明经气分。除风湿痿痹，疗寒气咳逆，利小便，治肺痈。配朱砂治惊悸。……炮制：煅后研细，水飞用。久服多服，则元气下陷。"}, {"source": "条189｜《证类本草》卷第三·玄明粉", "原文": "《证类本草》卷第三：“……治一切热毒风，搜冷，痃癖气胀满，五劳七伤，骨蒸传尸，头痛烦热，搜除恶疾，五脏秘涩，大小肠不通，三焦热淋，疰忤疾，咳嗽呕逆，口苦干涩，咽喉闭塞，心、肝、脾、肺脏胃积热，惊悸，健忘，荣卫不调，中酒中脍，饮食过度，腰膝冷痛，手脚酸，久冷久热，四肢壅塞，背膊拘急，眼昏目眩，久视无力，肠风痔病，血癖不调。", "白话": "……治一切热毒风、搜冷、痃癖气胀满、五劳七伤、骨蒸传尸、头痛烦热，搜除恶疾，治五脏秘涩、大小肠不通、三焦热淋、疰忤病、咳嗽呕逆、口苦干涩、咽喉闭塞、心肝脾肺脏胃积热、惊悸、健忘、荣卫不调、饮酒食脍过度、饮食过度、腰膝冷痛、手脚酸、久冷久热、四肢壅塞、背膊拘急、眼昏目眩、久视无力、肠风痔病、血癖不调。"}, {"source": "条190｜《本草发挥·金石部》·玄明粉", "原文": "《本草发挥·金石部》：“味辛、甘，冷，无毒。治心热烦躁，并五脏宿滞瘕结，明目，退膈上虚热，消肿毒。大阴，号云治一切热毒风痃，瘕气胀满，口苦干涩，咽喉闭塞，积热，惊悸健忘，荣卫不调，中酒中鲙，饮食过度，四肢壅塞，肠风痔疾，血癖不消。……海藏云：本草注云治骨蒸五劳，惊悸热毒风等，服之立愈。", "白话": "味辛、甘，性冷，无毒。治心热烦躁及五脏宿滞瘕结，明目，退膈上虚热，消肿毒。性大阴，号称治一切热毒风痃、瘕气胀满、口苦干涩、咽喉闭塞、积热、惊悸健忘、荣卫不调、饮酒食鲙过度、饮食过度、四肢壅塞、肠风痔疾、血癖不消。……海藏（王好古）说：本草注说治骨蒸五劳、惊悸、热毒风等，服之立愈。"}, {"source": "条191｜《岭南卫生方·李杲药性赋》·朱砂", "原文": "《岭南卫生方·李杲药性赋》：“味甘，微寒，无毒。其用有四：明目能通血脉；震惊能安魂魄；润心肺而养精神；定怔忡而止烦渴。", "白话": "味甘，微寒，无毒。其用有四：明目而能通血脉；镇惊而能安魂魄；润心肺而养精神；定怔忡而止烦渴。"}, {"source": "条192｜《药性赋·热性》·朱砂（条内述灵砂）", "原文": "《药性赋·热性》：“吴茱萸疗心腹之冷气，灵砂定心脏之怔忡。", "白话": "吴茱萸疗心腹冷气，灵砂定心脏之怔忡。"}, {"source": "条193｜《医学入门·治疮门》·朱砂（条内述灵砂）", "原文": "《医学入门·治疮门》：“灵砂乃炼硫汞成，怔忡病去心自灵，痼冷百病皆能疗，坠痰益气通血凝。……味甘、温，无毒。东垣云：灵砂定心脏之怔忡，久服令人心灵。一切痼冷、五脏百病皆治，坠痰涎，益气力，通血脉，止烦，辟恶，明目.疥疮有虫毒者，涂之即效。", "白话": "灵砂是炼硫汞而成，能去怔忡之病而心自灵，痼冷百病都能治，坠痰益气、通散血凝。……味甘，性温，无毒。东垣说：灵砂定心脏怔忡，久服使人心灵。一切痼冷、五脏百病都治，坠痰涎，益气力，通血脉，止烦，辟恶，明目。疥疮有虫毒的，涂之即效。"}, {"source": "条194｜《本草纲目·金石之一》·朱砂", "原文": "《本草纲目·金石之一》：“主治延年益色，镇心安神，止惊悸，辟邪，治中恶蛊毒，心热煎烦，忧忘虚劣大明。", "白话": "主治延年益色，镇心安神，止惊悸，辟邪，治中恶蛊毒、心热煎烦、忧忘虚损（大明说）。"}, {"source": "条195｜《景岳全书·痘药正品（六十六）》·朱砂", "原文": "《景岳全书·痘药正品（六十六）》：“镇心气，除热毒，坠痰涎，安惊悸，定神魂。凡心经痘毒，及痰火上壅有余之证，皆宜用之。", "白话": "镇心气，除热毒，坠痰涎，安惊悸，定神魂。凡心经痘毒及痰火上壅的实证，都宜用。"}, {"source": "条196｜《证类本草》卷第五·自然铜", "原文": "《证类本草》卷第五：“自然铜味辛，平，无毒。疗折伤，散血止痛，破积聚。……（臣禹锡等谨按）日华子云：自然铜，凉。排脓消瘀血，续筋骨，治产后血邪，安心，止惊悸，以酒摩服。", "白话": "自然铜味辛，性平，无毒。疗折伤，散血止痛，破积聚。……（臣禹锡等谨按）日华子说：自然铜性凉。排脓消瘀血，续筋骨，治产后血邪，安心，止惊悸，以酒磨服。"}, {"source": "条197｜《本草纲目·金石之一》·自然铜", "原文": "《本草纲目·金石之一》：“主治折伤，散血止痛，破积聚。消瘀血，排脓，续筋骨，治产后血邪，安心，止惊悸，以酒磨服。", "白话": "主治折伤，散血止痛，破积聚。消瘀血，排脓，续筋骨，治产后血邪，安心，止惊悸，以酒磨服。"}, {"source": "条198｜《本草经集注·青石、赤石、黄石、白石、黑石脂等》·赤石脂", "原文": "《本草经集注·青石、赤石、黄石、白石、黑石脂等》：“白石脂，味甘、酸，平，无毒。主治养肺气，厚肠，补骨髓，治五脏惊悸不足，心下烦，止腹痛，下水，小肠澼热溏，便脓血，女子崩中，漏下，赤白沃，排痈疽疮痔。久服安心，不饥，轻身，长年。生太山之阴，采无时。得厚朴并米汁饮，止便脓。燕屎为之使，恶松脂，畏黄芩。", "白话": "白石脂，味甘、酸，性平，无毒。主治养肺气，厚肠，补骨髓，治五脏惊悸不足、心下烦，止腹痛，下水，治小肠澼热溏泻、便脓血、女子崩中漏下、赤白带下，排痈疽疮痔。久服安心，不饥，轻身，延年。产于泰山之北，采集不限时。配厚朴并米汁饮，止便脓。燕屎为使药，恶松脂，畏黄芩。"}, {"source": "条199｜《名医别录》卷第一·赤石脂", "原文": "《名医别录》卷第一：“赤石脂味甘、酸，平，无毒。主养肺气，厚肠，补骨髓，治五脏惊悸不足，心下烦，止腹痛，下水，小肠澼热溏，便脓血，女子崩中漏下，赤白沃，排痈疽疮痔。久服安心，不饥，轻身长年。", "白话": "赤石脂味甘、酸，性平，无毒。主治养肺气，厚肠，补骨髓，治五脏惊悸不足、心下烦，止腹痛，下水，治小肠澼热溏泻、便脓血、女子崩中漏下、赤白带下，排痈疽疮痔。久服安心，不饥，轻身延年。"}, {"source": "条200｜《证类本草》卷第三·赤石脂", "原文": "《证类本草》卷第三：“……日华子云：五色石脂，并温，无毒。畏黄芩、大黄。治泻痢，血崩带下，吐血、衄血，并涩精、淋疬，安心，镇五脏，除烦，疗惊悸，排脓，治疮疖痔瘘，养脾气，壮筋骨，补虚损。久服悦色，纹理腻，缀唇者为上也。", "白话": "……日华子说：五色石脂都性温，无毒。畏黄芩、大黄。治泻痢、血崩带下、吐血衄血，并涩精、治淋沥瘰疬，安心，镇五脏，除烦，疗惊悸，排脓，治疮疖痔瘘，养脾气，壮筋骨，补虚损。久服悦色。以纹理细腻、舔之缀唇的为上。"}, {"source": "条201｜《本草发挥·金石部》·赤石脂", "原文": "《本草发挥·金石部》：“", "白话": "（此段原稿仅存引书起首标记，正文见下条《日华》引文。）"}, {"source": "条202｜《日华》·赤石脂（《本草发挥》条内引书）", "原文": "《日华》云：治吐血、衄，并涩精淋沥，安心镇惊悸。", "白话": "《日华子本草》说：治吐血、鼻衄，并涩精、治淋沥，安心镇惊悸。"}, {"source": "条203｜《本草正·金石部》·赤石脂", "原文": "《本草正·金石部》：“味甘涩，性温平。脂有五色，而今之入药者，惟唯赤白二种。乃手、足阳明、足厥阴、少阴药也。其味甘而温，故能益气调中；其性涩而重，故能收湿固下。调中则可疗虚烦惊悸，止吐血衄血，壮筋骨，厚肠胃，除水湿黄疸、痈肿疮毒，排脓长肉，止血生肌之类是也；固下则可治梦泄遗精、肠风泻痢、血崩带浊，固大肠，收脱肛、痔漏、阴疮之类是也。又治产难胞衣不出。东垣曰：“胞衣不出。惟唯涩剂可以下之。”即此是也", "白话": "味甘涩，性温平。石脂有五色，现今入药的只有赤白两种。是手足阳明、足厥阴、少阴经之药。其味甘而温，所以能益气调中；其性涩而重，所以能收湿固下。调中则可疗虚烦惊悸、止吐血衄血、壮筋骨、厚肠胃、除水湿黄疸、痈肿疮毒、排脓长肉、止血生肌之类；固下则可治梦泄遗精、肠风泻痢、血崩带浊、固大肠、收脱肛、痔漏、阴疮之类。又治难产胞衣不下。东垣说：“胞衣不出，惟涩剂可以下之。”就是指此。然而石脂有五种，虽说……"}, {"source": "条204｜《本经》·赤石脂（《本草正》条内引书）", "原文": "《本经》言各随五色补五脏，又云白入气分，赤入血分。第五脂之性味略同，似亦不必强分者。且其性粘黏如膏，故用固炉鼎甚良。", "白话": "（承上，《本经》说）五色石脂各随其色补五脏，又说白的入气分、赤的入血分。五种石脂的性味大致相同，似乎也不必强分。而且它的性质粘腻如膏，所以用作固护炉鼎（丹家外用）很好。"}, {"source": "条205｜《证类本草》卷第五·金牙石", "原文": "《证类本草》卷第五：“治一切冷风气……暖腰膝，补水脏，惊悸，小儿惊痫。", "白话": "治一切冷风气……暖腰膝，补肾（水脏），治惊悸、小儿惊痫。"}, {"source": "条206｜《证类本草》卷第四·铁精", "原文": "《证类本草》卷第四：“铁精，平，微温。主明目，化铜。疗惊悸，定心气，小儿风痫，阴˙脱肛。", "白话": "铁精，性平，微温。主明目，化铜。疗惊悸，定心气，治小儿风痫、脱肛（“阴˙”原稿讹脱，义不详）。"}, {"source": "条207｜《本草经集注·上品》·紫石英", "原文": "《本草经集注·上品》：“味甘、辛，温，无毒。主治心腹咳逆邪气，补不足；女子风寒在子宫，绝孕十年无子，治上气心腹痛，寒热邪气结气，补心气不足；定惊悸，安魂魄，填下焦，止消渴，除胃中久寒，散痈肿，令人悦泽。久服温中，轻身延年。", "白话": "味甘、辛，性温，无毒。主治心腹咳逆邪气，补不足；治女子风寒在子宫、绝孕十年无子；治上气心腹痛、寒热邪气结气，补心气不足；定惊悸，安魂魄，填下焦，止消渴，除胃中久寒，散痈肿，使人润泽。久服温中，轻身延年。"}, {"source": "条208｜《证类本草》卷第三·紫石英", "原文": "《证类本草》卷第三：“味甘、辛，温，无毒。主心腹咳逆邪气，补不足，女子风寒在子宫，绝孕十年无子，疗上气心腹痛，寒热邪气结气，补心气不足，定惊悸，安魂魄，填下焦，止消渴，除胃中久寒，散痈肿，令人悦泽。久服温中，轻身延年。生泰山山谷。采无时。长石为之使，得茯苓、人参、芍药共疗心中结气；得天雄、菖蒲，共疗霍乱，畏扁青、附子，不欲鮀甲、黄连、麦句姜。", "白话": "味甘、辛，性温，无毒。主治心腹咳逆邪气，补不足，女子风寒在子宫、绝孕十年无子，疗上气心腹痛、寒热邪气结气，补心气不足，定惊悸，安魂魄，填下焦，止消渴，除胃中久寒，散痈肿，使人润泽。久服温中，轻身延年。产于泰山山谷，采集不限时。长石为使药；配茯苓、人参、芍药共疗心中结气；配天雄、菖蒲共疗霍乱。畏扁青、附子，不喜鮀甲、黄连、麦句姜。"}, {"source": "条209｜《增广和剂局方药性总论·玉石部上品》·紫石英", "原文": "《增广和剂局方药性总论·玉石部上品》：“味甘辛，温，无毒。主心腹咳逆邪气，补不足，女子风寒在子宫，绝孕十年无子。疗上气，心腹痛，寒热邪气，结气，补心气不足，定惊悸，安魂魄，填下焦，止消渴，除胃中久寒，散痈肿。", "白话": "味甘辛，性温，无毒。主治心腹咳逆邪气，补不足，女子风寒在子宫、绝孕十年无子。疗上气、心腹痛、寒热邪气结气，补心气不足，定惊悸，安魂魄，填下焦，止消渴，除胃中久寒，散痈肿。"}, {"source": "条210｜《药性论》·紫石英（条内引书）", "原文": "《药性论》云：君。主养肺气，治惊痫，蚀脓，虚而惊悸不安。", "白话": "《药性论》说：（紫石英）为君药。主养肺气，治惊痫，蚀脓，治虚证惊悸不安。"}, {"source": "条211｜《古今医统大全·本草石部》·紫石英", "原文": "《古今医统大全·本草石部》 ：“味甘、辛，气温。无毒。入手少阴经、足厥阴经。长石为之使。畏扁青、附子。不欲黄连、麦句姜。明彻如水精，紫石达头如樗蒲者。主心腹咳逆邪气，补不足。女子风寒在子宫，十年无子。疗上气，寒热邪气结气。补心气虚，定惊悸，安魂魄，填下焦。久服温中,轻身延年。", "白话": "味甘、辛，气温。无毒。入手少阴经、足厥阴经。长石为使药。畏扁青、附子，不喜黄连、麦句姜。以明澈如水晶、紫色通透如樗蒲的为好。主治心腹咳逆邪气，补不足；女子风寒在子宫、十年无子；疗上气、寒热邪气结气；补心气虚，定惊悸，安魂魄，填下焦。久服温中，轻身延年。"}, {"source": "条212｜《本草征要·金石部》·磁石", "原文": "《本草征要·金石部》：“磁石，味辛、性温，无毒。入肾经。恶牡丹皮、莽草。畏石脂。火煅，醋淬，水飞。治肾虚之恐怯，镇心脏之怔忡。", "白话": "磁石，味辛，性温，无毒。入肾经。恶牡丹皮、莽草，畏石脂。炮制：火煅、醋淬、水飞。治肾虚之恐怯，镇心脏之怔忡。"}, {"source": "条213｜《本草汇言·谷部造酿类》·饴糖", "原文": "《本草汇言·谷部造酿类》：“味甘，气温，无毒。入足阳明、太阴经气分之药。……饴糖之甘，以缓中也。如眩晕，如消渴，如消中，如怔忡烦乱，如忍饥五内颠倒四体欲倾，如产妇失血过多，卒时烦晕，如劳人呕血盈盆，上逆不止，如老人泄泻频仍，中气陷下，如暴受惊怖，失神丧志，如读书作文，劳心瘁思，神气无主。", "白话": "味甘，气温，无毒。是入足阳明、太阴经气分的药。……饴糖之甘，用以缓中。如眩晕、消渴、消中、怔忡烦乱、忍饥时五内颠倒四肢欲倾、产妇失血过多突然烦晕、劳伤之人呕血盈盆上逆不止、老人泄泻频仍中气下陷、暴受惊怖失神丧志、读书作文劳心瘁思神气无主——都可用它缓中。"}, {"source": "条214｜《神农本草经·上品》·茯苓", "原文": "《神农本草经·上品》：“味甘，平。主胸胁逆气", "白话": "味甘，性平。主治胸胁逆气……"}, {"source": "条215｜《御览》·茯苓（《神农本草经》茯苓条校注）", "原文": "《御览》作疝气，忧恚，惊邪，悸心下结痛，寒热烦满咳逆，口焦舌干，利小便。久服，安魂，养神，不饥，延年。一名茯菟", "白话": "（承上）《太平御览》本“逆气”作“疝气”。主治忧恚、惊邪、心下悸结痛、寒热烦满咳逆、口焦舌干，利小便。久服安魂养神，不饥延年。又名茯菟……"}, {"source": "条216｜《御览》·茯苓（《神农本草经》茯苓条校注）", "原文": "《御览》作茯神。案∶：原本云∶，其有抱根者，名茯神。作黑字。生山谷。", "白话": "（承上）《太平御览》本“茯菟”作“茯神”。按：原本说，其中抱松根而生的名叫茯神。此四字作黑字（属《别录》文）。产于山谷。"}, {"source": "条217｜《本草经集注·茯苓》·茯苓（茯神）", "原文": "《本草经集注·茯苓》：“茯神，味甘，平。主辟不祥，治风眩、风虚，五劳、七伤，口干，止惊悸，多恚怒，善忘，开心益智，安魂魄，养精神。", "白话": "茯神，味甘，性平。主辟不祥，治风眩、风虚、五劳七伤、口干，止惊悸、多恚怒、善忘，开心益智，安魂魄，养精神。"}, {"source": "条218｜《新修本草·茯苓》·茯苓", "原文": "《新修本草·茯苓》：“味甘，平，无毒。主胸胁逆气忧恚、惊邪、恐悸心下结痛，寒热，烦满，咳逆，止口焦舌干，利小便。止消渴，好唾，大腹淋沥，膈中淡水，水肿淋结，开胸腑，调脏气，伐肾邪，长阴，益气力，保神守中。久服安魂魄、养神、不饥、延年。", "白话": "味甘，性平，无毒。主治胸胁逆气、忧恚、惊邪、恐悸、心下结痛、寒热、烦满、咳逆，止口焦舌干，利小便。止消渴、多唾、大腹淋沥、膈中淡水、水肿淋结，开胸腑，调脏气，伐肾邪，长阴，益气力，保神守中。久服安魂魄、养神、不饥、延年。"}, {"source": "条219｜《苍生司命·药性》·茯苓（茯神）", "原文": "《苍生司命·药性》：“（茯神）补心，善镇惊悸，恍惚健忘，兼除怒恚。", "白话": "（茯神）补心，善于镇惊悸，治恍惚健忘，兼除怒恚。"}, {"source": "条220｜《药性赋·平性》·茯苓（茯神）", "原文": "《药性赋·平性》：“茯神宁神益智，除惊悸之疴。", "白话": "茯神宁神益智，除惊悸之病。"}, {"source": "条221｜《药性赋·木部》·茯苓", "原文": "《药性赋·木部》：“茯苓，有赤、白二种。赤者，通利小便，白者可补虚定悸。茯苓，味甘、平。无毒。多年松根之气熏所生。有赤、白二种，并除寒热，止渴消痰。而赤者专主利小便，分水谷；白者专补虚定悸。", "白话": "茯苓有赤、白两种。赤茯苓通利小便，白茯苓可补虚定悸。茯苓味甘，性平，无毒。是多年松根之气熏蒸而生。有赤、白两种，都能除寒热、止渴消痰；而赤茯苓专主利小便、分利水谷，白茯苓专补虚定悸。"}, {"source": "条222｜《心印绀珠经·辨药性情第八》·茯苓", "原文": "《心印绀珠经·辨药性情第八》：“白茯苓，味甘淡，性温，无毒。降也，阳中之阴也。其用有六：利窍而除湿，益气而和中，小便多而能止，大便结而能通，心惊悸而能保，津液少而能生，白者入壬癸，赤者入丙丁。", "白话": "白茯苓，味甘淡，性温，无毒。主降，阳中之阴。其用有六：利窍除湿，益气和中，小便多而能止，大便结而能通，心惊悸而能安，津液少而能生。白的入壬癸（肾、膀胱水），赤的入丙丁（心、小肠火）。"}, {"source": "条223｜《本草发挥·木部》·茯苓（茯神）", "原文": "《本草发挥·木部》：“（茯神）东垣云：味甘，平，纯阳，疗风眩，心虚辟不止，惊悸，开心益智，安魂魄，养精神，心虚非此不能除之。", "白话": "（茯神）东垣说：味甘，性平，纯阳。疗风眩、心虚、惊悸（“辟不止”疑讹，义不详），开心益智，安魂魄，养精神——心虚非此不能除。"}, {"source": "条224｜《药性本草约言·卷之二·茯神》·茯苓（茯神）", "原文": "《药性本草约言·卷之二·茯神》：“味甘、淡，气平，无毒，阳中之阴，可升可降。疗眩晕，定上气之乱；安神志，益心气之虚。", "白话": "味甘、淡，气平，无毒，阳中之阴，可升可降。疗眩晕，定上气之乱；安神志，益心气之虚。"}, {"source": "条225｜《赋》·茯苓（茯神）（《药性本草约言》条内引书）", "原文": "《赋》云：治风眩心虚，安痫定志，止心下急痛，惊悸虚劳。", "白话": "《药性赋》说：治风眩心虚，安痫定志，止心下急痛、惊悸虚劳。"}, {"source": "条226｜《本草汇言·木部寓木类》·茯苓", "原文": "《本草汇言·木部寓木类》：“味甘、淡，气平，无毒。气味俱薄，浮而升，阳也。入手少阴，太阴、太阳、阳明、足少阴、太阴、太阳、阳明八经。……故", "白话": "味甘、淡，气平，无毒。气味俱薄，浮而升，属阳。入手少阴、手太阴、手太阳、手阳明、足少阴、足太阴、足太阳、足阳明八经。……所以……"}, {"source": "条227｜《农皇》·茯苓（《本草汇言》茯苓条内引书）", "原文": "《农皇》治胸胁逆气，忧恚惊邪，此肝气不和也，恐悸，心下结痛，此心气不和也，寒热烦满，此脾气不和也，咳逆口焦，此肺气不和也，舌干，小便不利，此肾气不和也。五气不和，为病甚众。用此甘淡平和之剂，五气咸和，诸病自己自已矣。", "白话": "《神农本草经》治胸胁逆气、忧恚惊邪——这是肝气不和；恐悸、心下结痛——这是心气不和；寒热烦满——这是脾气不和；咳逆口焦——这是肺气不和；舌干、小便不利——这是肾气不和。五脏之气不和，产生的病很多。用此甘淡平和之剂，五气都调和，诸病自愈。"}, {"source": "条1｜《神农本草经》", "原文": "《神农本草经》，也是我国现存最早的药物学专著。后经过历代医家的经验总结，治疗心悸的药物得到了较大的扩展。本次收纳的收入心悸药物共91味，共计188条条文，分布在49种中医古籍中。按药物自然属性分类，植物类65味，动物类12味，矿物类12味，其他类2味（真菌类的茯苓和植物加工品饴糖）。中医古籍中辑录整理的治疗心悸的药物，有以下特点：。", "白话": "《神农本草经》是我国现存最早的药物学专著。此后经过历代医家的经验总结，治疗心悸的药物得到了较大的扩展。本次收纳的心悸药物共91味，共计188条条文，分布在49种中医古籍中。按药物自然属性分类：植物类65味、动物类12味、矿物类12味、其他类2味（真菌类的茯苓、植物加工品饴糖）。从中医古籍中辑录整理的治疗心悸药物，有以下特点。"}, {"source": "条2｜《神农本草经》", "原文": "本次收载的药物中最早记载源自《神农本草经》。如人参、川芎、远志、茯神、柏实、紫菀、桔梗、荩草、旋复花旋覆花等，多达18种，上品12种，中品和下品各3种，此类药物以养心安神为主，多数药物至今仍为临床上常用药。", "白话": "本次收载的药物中，最早记载的来源是《神农本草经》。如人参、川芎、远志、茯神、柏实、紫菀、桔梗、荩草、旋复花（旋覆花）等，多达18种：上品12种，中品、下品各3种。这类药物以养心安神为主，多数至今仍是临床常用药。"}, {"source": "条3｜《本草经集注》", "原文": "南北朝陶弘景著《本草经集注》对《神农本草经》进行注解，对治疗心悸之药进行了考证。", "白话": "南北朝陶弘景著《本草经集注》，对《神农本草经》加以注解，并对治疗心悸的药物进行了考证。"}, {"source": "条4｜《神农本草经》", "原文": "南北朝陶弘景著《本草经集注》对《神农本草经》进行注解，对治疗心悸之药进行了考证。", "白话": "（句译见条3。）本处《神农本草经》指被注解的本草底本，即《本草经集注》所注之书。"}, {"source": "条5｜《新修本草》", "原文": "经过了漫长的朝代变迁、时代背景变迁，药物学开始繁荣发展，到唐代，国家组织人员考证并编纂《新修本草》，总结唐代以前本草经验。本书是世界上最早的一部国家药典，对部分治疗心悸药物功效有所新的认识。", "白话": "经过漫长的朝代变迁、时代背景变迁，药物学开始繁荣发展；到唐代，国家组织人员考证并编纂《新修本草》，总结唐代以前的本草经验。本书是世界上最早的一部国家药典，对部分治疗心悸药物的功效有了新的认识。"}, {"source": "条6｜《证类本草》", "原文": "后又有宋官修本草《证类本草》，是《新修本草》后本草学的另一高峰，增加治疗心悸药物12种，对紫石英和石脂功效有所发挥。", "白话": "其后又有宋代官修本草《证类本草》，是《新修本草》之后本草学的又一高峰；它增加治疗心悸药物12种，并对紫石英、石脂的功效有所发挥。"}, {"source": "条7｜《新修本草》", "原文": "后又有宋官修本草《证类本草》，是《新修本草》后本草学的另一高峰，增加治疗心悸药物12种，对紫石英和石脂功效有所发挥。", "白话": "（句译见条6。）本处以《新修本草》为本草学前一高峰的时间坐标。"}, {"source": "条8｜《本草经集注》", "原文": "如紫石英相对《本草经集注》的记载增加了“长石为之使，得茯苓、人参、芍药共疗心中结气”的记载，指出药物之间相须相使的配伍，增加临床疗效。", "白话": "例如紫石英，相对于《本草经集注》的记载，增加了“长石为之使，得茯苓、人参、芍药共疗心中结气”的内容，指出药物之间相须、相使的配伍关系，可提高临床疗效。"}, {"source": "条9｜《本草纲目》", "原文": "明代本草著作较丰，且创新较多，且主要集中在本草类著作中，如《本草纲目》《本草发挥》《本草蒙筌》《药性本草约言》等。", "白话": "明代本草著作较为丰富，创新也较多，且主要集中在本草类著作中，如《本草纲目》等。"}, {"source": "条10｜《本草发挥》", "原文": "明代本草著作较丰，且创新较多，且主要集中在本草类著作中，如《本草纲目》《本草发挥》《本草蒙筌》《药性本草约言》等。", "白话": "（句译见条9。）本条所指为《本草发挥》。"}, {"source": "条11｜《本草蒙筌》", "原文": "明代本草著作较丰，且创新较多，且主要集中在本草类著作中，如《本草纲目》《本草发挥》《本草蒙筌》《药性本草约言》等。", "白话": "（句译见条9。）本条所指为《本草蒙筌》。"}, {"source": "条12｜《药性本草约言》", "原文": "明代本草著作较丰，且创新较多，且主要集中在本草类著作中，如《本草纲目》《本草发挥》《本草蒙筌》《药性本草约言》等。", "白话": "（句译见条9。）本条所指为《药性本草约言》。"}, {"source": "条13｜《本草汇言》", "原文": "如人参，在《本草汇言》中被记载：“惊悸怔忡，健忘恍惚，以此宁之……”；《本草详节》中认为“人参除梦邪惊悸，补肺胃中阳气不足，泻心、肺、脾、胃中伏火”，这与前代较前代相比功效方面有了新的发现和理论创新。", "白话": "例如人参，在《本草汇言》中被记载：“惊悸怔忡、健忘恍惚，用它来安定……”这与前代相比，功效上有了新的发现和理论创新。"}, {"source": "条14｜《本草详节》", "原文": "如人参，在《本草汇言》中被记载：“惊悸怔忡，健忘恍惚，以此宁之……”；《本草详节》中认为“人参除梦邪惊悸，补肺胃中阳气不足，泻心、肺、脾、胃中伏火”，这与前代较前代相比功效方面有了新的发现和理论创新。还有其他药物随着临床应用也有不同程度的拓展。", "白话": "《本草详节》认为人参“祛除梦邪所致惊悸，补肺、胃中的阳气不足，泻心、肺、脾、胃中的伏火”（句译余见条13）。其他药物也随着临床应用有不同程度的拓展。"}, {"source": "条15｜《证类本草》", "原文": "李时珍以《证类本草》为蓝本，著《本草纲目》，对9味中药在治疗心悸方面有了新的认识和不同的阐述，如生地黄“助心胆气”，玄参“补劳损，心惊烦躁”等，后又有《本草汇言》在前人的基础上，对17种中药在治疗心悸的功效方面有了新药发现，如升麻、麦冬、当归、灯心草、泽泻等。", "白话": "李时珍以《证类本草》为蓝本，著《本草纲目》，对9味中药治疗心悸有了新的认识和不同阐述，如生地黄“助心胆气”、玄参“补劳损，心惊烦躁”等；后又有《本草汇言》在前人基础上，对17种中药治疗心悸的功效有新的发现，如升麻、麦冬、当归、灯心草、泽泻等。"}, {"source": "条16｜《本草纲目》", "原文": "李时珍以《证类本草》为蓝本，著《本草纲目》，对9味中药在治疗心悸方面有了新的认识和不同的阐述，如生地黄“助心胆气”，玄参“补劳损，心惊烦躁”等，后又有《本草汇言》在前人的基础上，对17种中药在治疗心悸的功效方面有了新药发现，如升麻、麦冬、当归、灯心草、泽泻等。", "白话": "（句译见条15。）本处《本草纲目》为李时珍所著、对9味中药治疗心悸作新阐述之书。"}, {"source": "条17｜《本草汇言》", "原文": "李时珍以《证类本草》为蓝本，著《本草纲目》，对9味中药在治疗心悸方面有了新的认识和不同的阐述，如生地黄“助心胆气”，玄参“补劳损，心惊烦躁”等，后又有《本草汇言》在前人的基础上，对17种中药在治疗心悸的功效方面有了新药发现，如升麻、麦冬、当归、灯心草、泽泻等。", "白话": "（句译见条15。）本处《本草汇言》指在前人基础上新发现17味中药心悸功效之书。"}, {"source": "条18｜《神农本草经》", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "李中梓在吸取《神农本草经》《药性论》《丹溪药性》《东垣药性》《仲景全书》等精华的基础上，著《雷公炮制药性解》，对药性作了充分的阐述。"}, {"source": "条19｜《》（原稿空书名号）", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《》为空书名号，无书名可译。"}, {"source": "条20｜《药性论》", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《药性论》为李中梓所吸取的药性专著之一。"}, {"source": "条21｜《》（原稿空书名号）", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《》为空书名号，无书名可译。"}, {"source": "条22｜《丹溪药性》", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《丹溪药性》为托元·朱丹溪的药性书。"}, {"source": "条23｜《》（原稿空书名号）", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《》为空书名号，无书名可译。"}, {"source": "条24｜《东垣药性》", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《东垣药性》为托金·李东垣的药性书。"}, {"source": "条25｜《》（原稿空书名号）", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《》为空书名号，无书名可译。"}, {"source": "条26｜《仲景全书》", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《仲景全书》为张仲景著作合刊本。"}, {"source": "条27｜《雷公炮制药性解》", "原文": "李中梓在吸取了《神农本草经》、《》《药性论》、《》《丹溪药性》、《》《东垣药性》、《》《仲景全书》等精华的基础上，著《雷公炮制药性解》对药性作了做了充分的阐述。", "白话": "（句译见条18。）本处《雷公炮制药性解》为李中梓所著、充分阐述药性之书。"}, {"source": "条28｜《本草备要》", "原文": "清代本草著作大量涌现，约400余部本草著作，创新之处较明代较少，其中记载治疗心悸的重要本草著作有《本草备要》《药性赋》等。经过历代医家对心悸药物的的认识和临床经验总结，不断扩大了用药选择范围。", "白话": "清代本草著作大量涌现，约400余部，创新之处较明代为少；其中记载治疗心悸的重要本草著作有《本草备要》《药性赋》等。经过历代医家对心悸药物的认识和临床经验总结，用药选择范围不断扩大。"}, {"source": "条29｜《药性赋》", "原文": "清代本草著作大量涌现，约400余部本草著作，创新之处较明代较少，其中记载治疗心悸的重要本草著作有《本草备要》《药性赋》等。经过历代医家对心悸药物的的认识和临床经验总结，不断扩大了用药选择范围。", "白话": "（句译见条28。）本处《药性赋》为清代仍通行的药性歌赋。"}, {"source": "条30｜《神农本草经》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "本次文献整理中，很多本草专著对治疗心悸之药记载颇多，如《神农本草经》等。"}, {"source": "条31｜《本草纲目》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "（句译见条30。）本条所指为《本草纲目》。"}, {"source": "条32｜《本草蒙筌》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "（句译见条30。）本条所指为《本草蒙筌》。"}, {"source": "条33｜《本草详节》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "（句译见条30。）本条所指为《本草详节》。"}, {"source": "条34｜《本草发挥》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "（句译见条30。）本条所指为《本草发挥》。"}, {"source": "条35｜《本草正》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "（句译见条30。）本条所指为《本草正》。"}, {"source": "条36｜《得配本草》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "（句译见条30。）本条所指为《得配本草》。"}, {"source": "条37｜《药性本草约言》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "（句译见条30。）本条所指为《药性本草约言》。"}, {"source": "条38｜《药性赋》", "原文": "在本次文献整理中，很多本草专著对治疗心悸之药记载最颇多，如《神农本草经》《本草纲目》《本草蒙筌》《本草详节》《本草发挥》《本草正》《得配本草》《药性本草约言》《药性赋》等。", "白话": "（句译见条30。）本条所指为《药性赋》。"}, {"source": "条39｜《岭南卫生方》", "原文": "同时也涌现出了的部分区域性本草著作，如元代继洪的《岭南卫生方》，对朱砂功效进行了经验总结，言朱砂：“其用有四：明目能通血脉；震惊能安魂魄；润心肺而养精神；定怔忡而止烦渴。", "白话": "同时也出现了部分区域性本草著作，如元代继洪的《岭南卫生方》，对朱砂的功效作了经验总结，说朱砂：“其用有四：明目，能通血脉；（镇）惊，能安魂魄；润心肺而养精神；定怔忡而止烦渴。”"}, {"source": "条40｜《滇南本草》", "原文": "又如《滇南本草》是一部著名的主要记载现代云南省的地区性本草，流传较广，并被以后许多本草著作所引用。书中记述了苦远志、土千年健、双尾参、还阳参和丹参治疗心悸的功效。土千年健、双尾参、还阳参虽未在现今临床广泛应用，但对于科技不断创新的今天，仍有助于新药的研发和发挥临床效果。", "白话": "又如《滇南本草》，是一部著名的、主要记载今云南省药物的地区性本草，流传较广，并被后世许多本草著作引用。书中记述了苦远志、土千年健、双尾参、还阳参、丹参治疗心悸的功效。土千年健、双尾参、还阳参虽未在现今临床广泛应用，但对科技创新的今天，仍有助于新药研发和发挥临床效果。"}, {"source": "条41｜《冯氏锦囊秘录》", "原文": "中医古籍分类采用的事是12大类3级类目分类法，大类是指基础理论、伤寒金匮、本草、方书、临床各科、养生、综合性著作等12类。除本草类目外，在前述的临床各科及综合性医书中也有记载，也体现了各学科之间的专业交织，各医家的学术知识背景，即各医家对诊法、治法、药性均有较好为全面的理解。辑录文献中，亦有综合性著作对本草进行了汇总，如《冯氏锦囊秘录》《古今医统大全》《医学入门》《医学摘粹》等，多为在前人的基础上", "白话": "中医古籍采用12大类3级类目分类法，大类指基础理论、伤寒金匮、本草、方书、临床各科、养生、综合性著作等12类。除本草类目外，在前述的临床各科及综合性医书中也有记载，体现了各学科之间的专业交织与各医家的学术知识背景，即各医家对诊法、治法、药性均有较全面的理解。辑录的文献中也有综合性著作对本草作了汇总，如《冯氏锦囊秘录》等，多在前人基础上对临床经验有所发挥。"}, {"source": "条42｜《古今医统大全》", "原文": "辑录文献中，亦有综合性著作对本草进行了汇总，如《冯氏锦囊秘录》《古今医统大全》《医学入门》《医学摘粹》等，多为在前人的基础上，对临床经验有所发挥。", "白话": "（句译见条41。）本条所指为《古今医统大全》。"}, {"source": "条43｜《医学入门》", "原文": "辑录文献中，亦有综合性著作对本草进行了汇总，如《冯氏锦囊秘录》《古今医统大全》《医学入门》《医学摘粹》等，多为在前人的基础上，对临床经验有所发挥。", "白话": "（句译见条41。）本条所指为《医学入门》。"}, {"source": "条44｜《医学摘粹》", "原文": "辑录文献中，亦有综合性著作对本草进行了汇总，如《冯氏锦囊秘录》《古今医统大全》《医学入门》《医学摘粹》等，多为在前人的基础上，对临床经验有所发挥。", "白话": "（句译见条41。）本条所指为《医学摘粹》。"}, {"source": "条45｜《痰火点雪》", "原文": "如《痰火点雪》是一部痨瘵治疗专书，成书于1630年，作者为龚居中。其中载：“清河参（补五脏，安精神，定魂魄，又止惊悸，断淫梦，保中守神）。", "白话": "如《痰火点雪》是一部痨瘵治疗专书，成书于1630年，作者龚居中。其中记载：“清河参（补五脏，安定精神，镇定魂魄，又止惊悸，断除淫梦，守护中土以安神）。”"}, {"source": "条46｜《麻科活人全书》", "原文": "《麻科活人全书》是一部麻疹专著，由清代谢玉琼撰于1748年，其中说：“香附为多怒多忧者之要药。治两胁气妨，心忪少气。生用则上行胁膈，外达皮毛，故能散风寒。", "白话": "《麻科活人全书》是一部麻疹专著，清代谢玉琼撰于1748年，其中说：“香附是多怒多忧之人的要药。治两胁气机窒碍、心忪少气。生用则上行胁膈、外达皮毛，所以能散风寒。”"}, {"source": "条47｜《苍生司命》", "原文": "《苍生司命》《医宗说约》《冯氏锦囊秘录》《医心印绀珠经》等综合性医书中均在文中相应部分进行了药性记载。", "白话": "《苍生司命》《医宗说约》《冯氏锦囊秘录》《医心印绀珠经》等综合性医书，都在文中相应部分作了药性记载。"}, {"source": "条48｜《医宗说约》", "原文": "《苍生司命》《医宗说约》《冯氏锦囊秘录》《医心印绀珠经》等综合性医书中均在文中相应部分进行了药性记载。", "白话": "（句译见条47。）本条所指为《医宗说约》。"}, {"source": "条49｜《冯氏锦囊秘录》", "原文": "《苍生司命》《医宗说约》《冯氏锦囊秘录》《医心印绀珠经》等综合性医书中均在文中相应部分进行了药性记载。", "白话": "（句译见条47。）本条所指为《冯氏锦囊秘录》。"}, {"source": "条50｜《医心印绀珠经》", "原文": "《苍生司命》《医宗说约》《冯氏锦囊秘录》《医心印绀珠经》等综合性医书中均在文中相应部分进行了药性记载。", "白话": "（句译见条47。）本条所指为《医心印绀珠经》。"}, {"source": "条51｜《神农本草经》", "原文": "治疗心悸药物众多，按中药功效进行分类，包含解表药、清热药、泻下药、祛风湿药、化湿药、利水渗湿药、温里药、理气药、止血药、活血化瘀药、化痰止咳平喘药、安神药、平肝息风药、开窍药、补虚药、收涩药等16类药，其中以补虚药、安神药、清热药为主，补虚药中的补气药、补血药、补血药和补阴药均有涉及，以补气药和补阴药最多。这也反应映心悸内以气血阴阳不足，外有诸因可扰心神。其次治疗心悸的单味药，可治疗多种病症，如《", "白话": "治疗心悸的药物众多，按中药功效分类，包含解表、清热、泻下、祛风湿、化湿、利水渗湿、温里、理气、止血、活血化瘀、化痰止咳平喘、安神、平肝息风、开窍、补虚、收涩等16类药；其中以补虚药、安神药、清热药为主，补虚药中的补气、补血、补阴药均有涉及，以补气药和补阴药最多。这也反映心悸内以气血阴阳不足，外有诸因可扰心神。其次，治疗心悸的单味药可治疗多种病症，如《神农本草经》中治疗心悸之药都具有7种以上功效，后世临床经验的发挥又逐步扩展了功效范围。这说明药物治疗心悸的同时，也可治疗由它引发"}, {"source": "条52｜《本草经集注·草木中品》", "原文": "历代医家在自身的临床实践中，对药物的功效和认识，有所不同，如就桔梗而言，《本草经集注·草木中品》《万氏家抄济世良方·药性草部》中记载为“小毒”，而在《本草蒙筌·草部中》《本草正·山草部》中则无此“小毒”的记载；，且《本草正·山草部》载为“气微凉”，而其他三种古籍记载则为“微温”。而现代已不将桔梗有毒附在性味归经之后，《中国药典》载其为平性；就功效而言，现代多用于宣肺利咽，祛痰排脓。虽然现代将桔梗作", "白话": "历代医家在自身临床实践中，对药物功效的认识有所不同。就桔梗而言，《本草经集注·草木中品》《万氏家抄济世良方·药性草部》记载为“小毒”，而《本草蒙筌·草部中》《本草正·山草部》则无“小毒”之记；且《本草正·山草部》载“气微凉”，其他三种古籍则记“微温”。而现代已不把桔梗有毒附在性味归经之后，《中国药典》载其为平性；功效上现代多用于宣肺利咽、祛痰排脓。虽然现代以桔梗为君药的用法也相对较少，本节也不评论造成这些差异的原因，但这些差异强烈说明：医家用药时应保持质疑心态，不能完全照本宣"}, {"source": "条53｜《万氏家抄济世良方·药性草部》", "原文": "历代医家在自身的临床实践中，对药物的功效和认识，有所不同，如就桔梗而言，《本草经集注·草木中品》《万氏家抄济世良方·药性草部》中记载为“小毒”，而在《本草蒙筌·草部中》《本草正·山草部》中则无此“小毒”的记载；，且《本草正·山草部》载为“气微凉”，而其他三种古籍记载则为“微温”。", "白话": "（句译见条52。）本处《万氏家抄济世良方·药性草部》亦载桔梗“小毒”。"}, {"source": "条54｜《本草蒙筌·草部中》", "原文": "历代医家在自身的临床实践中，对药物的功效和认识，有所不同，如就桔梗而言，《本草经集注·草木中品》《万氏家抄济世良方·药性草部》中记载为“小毒”，而在《本草蒙筌·草部中》《本草正·山草部》中则无此“小毒”的记载；，且《本草正·山草部》载为“气微凉”，而其他三种古籍记载则为“微温”。", "白话": "（句译见条52。）本处《本草蒙筌·草部中》无桔梗“小毒”之记。"}, {"source": "条55｜《本草正·山草部》", "原文": "历代医家在自身的临床实践中，对药物的功效和认识，有所不同，如就桔梗而言，《本草经集注·草木中品》《万氏家抄济世良方·药性草部》中记载为“小毒”，而在《本草蒙筌·草部中》《本草正·山草部》中则无此“小毒”的记载；，且《本草正·山草部》载为“气微凉”，而其他三种古籍记载则为“微温”。", "白话": "（句译见条52。）本处《本草正·山草部》既无“小毒”之记，又载桔梗“气微凉”。"}, {"source": "条56｜《本草正·山草部》", "原文": "历代医家在自身的临床实践中，对药物的功效和认识，有所不同，如就桔梗而言，《本草经集注·草木中品》《万氏家抄济世良方·药性草部》中记载为“小毒”，而在《本草蒙筌·草部中》《本草正·山草部》中则无此“小毒”的记载；，且《本草正·山草部》载为“气微凉”，而其他三种古籍记载则为“微温”。", "白话": "（句译见条52。）本处第二次引《本草正·山草部》，指其载桔梗“气微凉”，与其余三书“微温”之说不同。"}, {"source": "条57｜《中国药典》", "原文": "而现代已不将桔梗有毒附在性味归经之后，《中国药典》载其为平性；就功效而言，现代多用于宣肺利咽，祛痰排脓。虽然现代将桔梗作为君药的使用也相对较少，本节也不评论造成这些差异的原因，但是这些差异也强烈说明，需要医家使用药物时不仅应保持质疑的心态，不能完全照本宣科，而且还应该结合中医基础理论和临床实际进行应用，以及需要结合现代研究进行验证。", "白话": "现代已不把桔梗有毒附在性味归经之后，《中国药典》载其为平性；功效上现代多用于宣肺利咽、祛痰排脓。（余句译见条52。）"}, {"source": "条58｜《神农本草经》", "原文": "我国古代就有食疗的说法，现代更是提出了药食两用或称药食同源的理论。结合国家有关部门公布的药食同源药物目录和日常生活习惯，本节纳入了百合、茯苓、大枣、龙眼、饴糖、山药、胡麻、郁李仁、桑椹子、梨、笋等17种药物（食物）。其中，《神农本草经》中17种药物中已包含桔梗、茯苓、大枣、蜂蜜、牡蛎5种。", "白话": "我国古代就有食疗之说，现代更提出药食两用（药食同源）理论。结合国家有关部门公布的药食同源目录和日常生活习惯，本节纳入百合、茯苓、大枣、龙眼、饴糖、山药、胡麻、郁李仁、桑椹子、梨、笋等17种药物（食物）。其中，《神农本草经》已包含桔梗、茯苓、大枣、蜂蜜、牡蛎5种。"}, {"source": "条59｜《本草蒙筌·果部》", "原文": "龙眼则见于《本草蒙筌·果部》中：“龙眼肉 味甘，气平。无毒。……养肌肉，美颜色，除健志，却怔忡。多服强魂聪明，久服轻身不老。", "白话": "龙眼则见于《本草蒙筌·果部》：“龙眼肉，味甘，气平，无毒。……滋养肌肉，美容颜，除健忘，祛怔忡。多服使人魂强聪明，久服轻身不老。”"}, {"source": "条60｜《本草汇言·谷部造酿类》", "原文": "饴糖在《本草汇言·谷部造酿类》中有载：“饴糖之甘，以缓中也。如眩晕，如消渴，如消中，如怔忡烦乱，……。", "白话": "饴糖在《本草汇言·谷部造酿类》中有记载：“饴糖味甘，用以缓中。如眩晕、如消渴、如消中、如怔忡烦乱，……。”"}, {"source": "条61｜《随息居饮食谱·果食类》", "原文": "《随息居饮食谱·果食类》载：“梨甘凉，治中风不语、痰热惊狂、温暑等疴。", "白话": "《随息居饮食谱·果食类》记载：“梨甘凉，治中风不语、痰热惊狂、温暑等病。”"}, {"source": "条62｜《折肱漫录·养形篇下》", "原文": "需要特别说明的是，考虑到现代人广泛食用糯米的习惯，而在《折肱漫录·养形篇下》中有说：“世人皆言糯米补人，考之本草云：主温中，令人多热，久食令人身软，发心悸。”有此一条多食糯米会引发心悸的记载，也纳入到本书中，以供参考。从前述这些收录的日常生活中药物（食物）来看，多数均性平味甘，具有补益脾胃、益气养血、补益五脏的功效。故在调治心悸中，可采用药食同源药物进行早期的预防和后期的调理。", "白话": "需要特别说明的是，考虑到现代人广泛食用糯米的习惯，而《折肱漫录·养形篇下》中说：“世人都说糯米补人，查考本草记载：（糯米）主温中，使人多热，久食使人身体软弱、引发心悸。”有这样一条“多食糯米会引发心悸”的记载，也纳入本书，以供参考。从前述收录的日常药物（食物）来看，多数性平味甘，具有补益脾胃、益气养血、补益五脏的功效。所以在调治心悸中，可用药食同源之品进行早期预防和后期调理。"}, {"source": "条63｜《神农本草经》", "原文": "综上，本部分共收录药物共91味，自《神农本草经》始，最晚为1911年，时间跨度长，涉及的朝代、医家医派、地域等时间空间纬度广，基本可以涵盖古代的各个阶段。也为了体现出时代特征，本部分的文献辑录采用取的是每个类别下按最早出现的年代排序的方法，出现的年代相同的再依据笔画顺序排列。主要收录了现代临床常用、无显著争议的药物，还纳入了具有药食两用或日常多食用的食物或药物，对现在的国家保护动植物的、已经无法获", "白话": "综上，本部分共收录药物91味，上起《神农本草经》，下至1911年，时间跨度长，涉及朝代、医家医派、地域等时空维度广，基本可涵盖古代各个阶段。为体现时代特征，本部分文献辑录采用“每一类别下按最早出现年代排序、年代相同再按笔画排列”的方法。主要收录现代临床常用、无显著争议的药物，也纳入药食两用或日常多食的食物/药物；对今属国家保护动植物、已无法获得或无法考证的特殊药物不予收录。虽然收录药物不少，但药物与组方的关系仍有待加强——这些药物并非方剂的全部组成，一些治疗心悸经典组方的君药"}, {"source": "条64｜《卫生易简方》", "原文": "心悸的经典方剂是经历代医家的实践的积累总结，在漫长的发展历程中逐渐形成的。这些方剂在组成、功效和剂型等方面对现代临床仍有权威性指导作用。心悸类方剂的演化遵循着组方结构由简单到复杂、药物组成的多少由少到多的规律进行发展的，组方结构。早期的方剂多数为单方或少量药味组成的，本书从单方和复方两个角度进行整理和统计，其中单方有434首，其余5221522首均为复方。本书整理了与心悸高度相关的古代方剂，并按照", "白话": "心悸的经典方剂是历代医家实践积累的总结，在漫长发展历程中逐渐形成。这些方剂在组成、功效、剂型等方面对现代临床仍有权威性指导作用。心悸类方剂的演化遵循“组方结构由简单到复杂、药物味数由少到多”的规律发展。早期方剂多数为单方或少量药味组成，本书从单方、复方两角度整理统计：单方434首，其余5221首均为复方。本书整理了与心悸高度相关的古代方剂，并按出现年代早晚排序，以期指导现代临床用药、为心悸治疗提供参考。本书记载了有关心悸的单方343首，分别为甘草、覆盆子、紫石英散和荆沥。《卫"}, {"source": "条65｜《赤水玄珠》", "原文": "同样，在本书中记载覆盆子有“益颜色，安五脏，养精气”的作用，故覆盆子可以用于治疗“惊悸”。孙一奎在《赤水玄珠》中则认为紫石英散可“治虚怯惊悸，饮食不进，成痨者”。", "白话": "同样，本书记载覆盆子有“益颜色、安五脏、养精气”的作用，所以覆盆子可用于治疗“惊悸”。孙一奎在《赤水玄珠》中则认为紫石英散可“治虚怯惊悸、饮食不进、渐成痨者”。"}, {"source": "条66｜《经验良方全集》", "原文": "在《经验良方全集》《圣济总录》中认为荆沥葫芦饮主治心虚伴随的惊悸与形体羸瘦气黄伴随的心悸。，如：“病人初得。先从两脚黄肿，大小便难。心中战悸。面目虚黄。不能食。宜服葫芦饮方。", "白话": "《经验良方全集》《圣济总录》认为荆沥葫芦饮主治心虚所致的惊悸，及形体羸瘦、色黄所致的心悸。如：“病人初得（此病），先从两脚黄肿，大小便艰难，心中战悸，面目虚黄，不能食，宜服葫芦饮方。”"}, {"source": "条67｜《圣济总录》", "原文": "在《经验良方全集》《圣济总录》中认为荆沥葫芦饮主治心虚伴随的惊悸与形体羸瘦气黄伴随的心悸。，如：“病人初得。先从两脚黄肿，大小便难。心中战悸。面目虚黄。不能食。宜服葫芦饮方。", "白话": "（句译见条66。）本处《圣济总录》为与《经验良方全集》并引之书。"}, {"source": "条68｜《伤寒论》", "原文": "先秦两汉时期记载治疗心悸的经典古籍主要包含张仲景所撰的《伤寒论》和《金匮要略方论》。其中，治疗“悸”的方剂有四逆散，其作为或然证在四逆散原方基础上强调“悸者，加桂枝五分”；治疗“心下悸”的有茯苓甘草汤、半夏麻黄丸、桂枝甘草汤及真武汤；针对“心中悸”的方剂有小建中汤、小柴胡汤，而小柴胡汤加减法中也已强调“若心下悸，小便不利者，去黄芩，加茯苓四两”。此时期治疗心悸最具代表性的方剂为炙甘草汤，即“伤寒脉", "白话": "先秦两汉时期记载治疗心悸的经典古籍，主要是张仲景所撰的《伤寒论》和《金匮要略方论》。其中治“悸”的方剂有四逆散——悸作为或然证，在四逆散原方基础上强调“悸者，加桂枝五分”；治“心下悸”的有茯苓甘草汤、半夏麻黄丸、桂枝甘草汤、真武汤；针对“心中悸”的有小建中汤、小柴胡汤，而小柴胡汤加减法已强调“若心下悸、小便不利者，去黄芩，加茯苓四两”。此时期治疗心悸最具代表性的方剂是炙甘草汤，即“伤寒脉结代，心动悸，炙甘草汤主之”；煎煮法中张仲景强调用“清酒七升、水八升”煎煮，这也是炙甘草汤"}, {"source": "条69｜《金匮要略方论》", "原文": "先秦两汉时期记载治疗心悸的经典古籍主要包含张仲景所撰的《伤寒论》和《金匮要略方论》。", "白话": "（句译见条68。）本处《金匮要略方论》与《伤寒论》并列为先秦两汉心悸方书。"}, {"source": "条70｜《肘后备急方》", "原文": "在魏晋南北朝时期，是心悸方剂学承上启下全面发展的时代。《肘后备急方》中引用《金匮要略》中治疗“心下悸”的半夏麻黄丸，并明确指出此方所治疗的心悸为“心下虚悸”，确定了此方所主症之虚实。", "白话": "魏晋南北朝是心悸方剂学承上启下、全面发展的时代。《肘后备急方》引用《金匮要略》治疗“心下悸”的半夏麻黄丸，并明确指出此方所治的心悸是“心下虚悸”，确定了该方所主证候的虚实属性。"}, {"source": "条71｜《金匮要略》", "原文": "《肘后备急方》中引用《金匮要略》中治疗“心下悸”的半夏麻黄丸，并明确指出此方所治疗的心悸为“心下虚悸”，确定了此方所主症之虚实。", "白话": "（句译见条70。）本处《金匮要略》为半夏麻黄丸所从出之书。"}, {"source": "条72｜《小品方》", "原文": "《小品方》中的九痛丸可治疗“悸心痛”及其他病因而引起的心痛，推测此方治疗心痛的效果更好。", "白话": "《小品方》的九痛丸可治疗“悸心痛”及其他病因引起的心痛，推测此方治疗心痛的效果更好。"}, {"source": "条73｜《刘涓子鬼遗方》", "原文": "《刘涓子鬼遗方》可治疗“金疮惊悸”，“心中满满如车所惊怛”则对心悸进行了更生动的描述。", "白话": "《刘涓子鬼遗方》可治疗“金疮惊悸”；“心中满满如车所惊怛”一句对心悸作了更生动的描述。"}, {"source": "条74｜《小品方》", "原文": "《小品方》中用理中汤治疗霍乱时，也记载了加减法“悸者加茯苓二两”，与《伤寒论》中的小柴胡汤加减法有相同之处。", "白话": "《小品方》用理中汤治疗霍乱时，也记载了加减法“悸者加茯苓二两”，与《伤寒论》小柴胡汤加减法有相同之处。"}, {"source": "条75｜《伤寒论》", "原文": "《小品方》中用理中汤治疗霍乱时，也记载了加减法“悸者加茯苓二两”，与《伤寒论》中的小柴胡汤加减法有相同之处。", "白话": "（句译见条74。）本处指《伤寒论》小柴胡汤加减法“若心下悸、小便不利者，去黄芩，加茯苓四两”（参条68）。"}, {"source": "条76｜《备急千金要方》", "原文": "隋唐时期有关心悸的记载则较前两个时期明显增加。多首方剂中记载导致心悸的原因之一是由虚引起的，如《备急千金要方》中大补心汤治疗“虚损不足，心气弱悸或时妄语，四肢损变气力，颜色不荣”，大定心汤治“心气虚悸，恍惚多忘”，《千金翼方》人参丸治疗“男子虚心悸不定”；还记载治疗产后大虚的方剂，如《备急千金要方》中甘草丸治疗“产后心虚不足，虚悸，心神不安，吸吸乏气，或若恍恍惚惚，不自知觉者”，安心汤治疗“产后心", "白话": "隋唐时期有关心悸的记载较前两个时期明显增加。多首方剂记载心悸的成因之一是虚：如《备急千金要方》大补心汤治“虚损不足，心气弱悸或时妄语，四肢损变气力，颜色不荣”，大定心汤治“心气虚悸，恍惚多忘”，《千金翼方》人参丸治“男子虚心悸不定”；还记载治产后大虚的方剂，如《备急千金要方》甘草丸治“产后心虚不足，虚悸，心神不安，吸吸乏气，或若恍恍惚惚、不自知觉者”，安心汤治“产后心忡悸不定，恍恍惚惚，不自知觉，言语错误，虚烦短气，志意不定，此是心虚所致”，《千金翼方》人参丸治“产后大虚，心"}, {"source": "条77｜《千金翼方》", "原文": "《千金翼方》人参丸治疗“男子虚心悸不定”；还记载治疗产后大虚的方剂，如《备急千金要方》中甘草丸治疗“产后心虚不足，虚悸，心神不安，吸吸乏气，或若恍恍惚惚，不自知觉者", "白话": "（句译见条76。）本处《千金翼方》人参丸治“男子虚心悸不定”。"}, {"source": "条78｜《备急千金要方》", "原文": "还记载治疗产后大虚的方剂，如《备急千金要方》中甘草丸治疗“产后心虚不足，虚悸，心神不安，吸吸乏气，或若恍恍惚惚，不自知觉者”，安心汤治疗“产后心忡悸不定，恍恍惚惚，不自知觉，言语错误，虚烦短气，志意不定，此是心虚所致", "白话": "（句译见条76。）本处《备急千金要方》甘草丸、安心汤均治产后心虚之悸。"}, {"source": "条79｜《千金翼方》", "原文": "《千金翼方》人参丸治疗“产后大虚，心悸，志意不安，恍惚不自觉，心中畏恐，夜不得眠，虚烦少气”。因此方剂组成中常含有人参、茯苓、茯神、远志等补气养心安神之药。针对产后虚弱导致心悸的，常增加当归、芍药、干地黄等补血之药。", "白话": "（句译见条76。）本处《千金翼方》人参丸治产后大虚心悸；方中常含人参、茯苓、茯神、远志等补气养心安神之药，产后者另加当归、芍药、干地黄等补血之药。"}, {"source": "条80｜《备急千金要方》", "原文": "同时也有记载引起心悸的原因为“实热”及“风热，如《备急千金要方》中竹沥汤治疗“心实热，惊梦喜笑恐畏悸惧不安”，《外台秘要》竹叶汤治疗风热引起的“睡觉心忪心闷”，从而使用竹沥、竹叶、石膏等清心实热的药物。", "白话": "同时也记载引起心悸的原因有“实热”与“风热”：如《备急千金要方》竹沥汤治“心实热，惊梦喜笑恐畏悸惧不安”，《外台秘要》竹叶汤治风热引起的“睡醒心忪心闷”，从而使用竹沥、竹叶、石膏等清心实热的药物。"}, {"source": "条81｜《外台秘要》", "原文": "同时也有记载引起心悸的原因为“实热”及“风热，如《备急千金要方》中竹沥汤治疗“心实热，惊梦喜笑恐畏悸惧不安”，《外台秘要》竹叶汤治疗风热引起的“睡觉心忪心闷”，从而使用竹沥、竹叶、石膏等清心实热的药物。", "白话": "（句译见条80。）本处《外台秘要》竹叶汤治风热所致“睡觉心忪心闷”。"}, {"source": "条82｜《备急千金要方》", "原文": "在药物加减部分，《备急千金要方》仲景三黄汤中，提出“心悸加牡蛎”，取牡蛎重镇安神的作用；竹叶汤中“若心中虚悸者，加人参二两”，因为人参具有“安定精神”的功效。", "白话": "在药物加减部分，《备急千金要方》仲景三黄汤提出“心悸加牡蛎”，取牡蛎重镇安神之用；竹叶汤“若心中虚悸者，加人参二两”，因为人参具有“安定精神”的功效。"}, {"source": "条83｜《圣济总录 • 卷第四十三》", "原文": "宋金元时期有关心悸的文献记载较隋唐时期要更多。《圣济总录 • 卷第四十三》提到乌犀汤可治疗“心脏烦热，睡即多惊，心忪不欲见人”，描写了心悸的严重程度。", "白话": "宋金元时期有关心悸的文献记载较隋唐更多。《圣济总录•卷第四十三》提到乌犀汤可治“心脏烦热，睡即多惊，心忪不欲见人”，描写了心悸的严重程度。"}, {"source": "条84｜《圣济总录 • 卷第三十一》", "原文": "此时期还存在多个同名异方的方剂，如《圣济总录 • 卷第三十一》中茯神丸用于治疗“伤后治寒，或用心力劳倦，四肢羸弱，心忪惊悸，吸吸短气”，药物组成为“茯神（去木） 麦门冬（去心焙） 熟干地黄（焙各一两） 牡丹皮 人参 黄芪（锉，各三分） 桂（去粗皮） 甘草（炙） 牛膝（去苗） 泽泻（各半两）”，多为补气安神滋阴之药；而在《圣济总录 • 卷第四十三》中用茯神丸治疗“心脏虚热，惊悸心忪，虚乏气短，睡卧不", "白话": "此时期还存在多个同名异方。如《圣济总录•卷第三十一》的茯神丸治“伤后治寒，或用心力劳倦，四肢羸弱，心忪惊悸，吸吸短气”，组成为“茯神（去木） 麦门冬（去心焙） 熟干地黄（焙各一两） 牡丹皮 人参 黄芪（锉，各三分） 桂（去粗皮） 甘草（炙） 牛膝（去苗） 泽泻（半两）”，多为补气、安神、滋阴之药；而《圣济总录•卷第四十三》的茯神丸治“心脏虚热，惊悸心忪，虚乏气短，睡卧不安”，组成“茯神（去木二两） 人参 麦门冬（去心焙） 龙齿 防风（去叉） 云母粉（各一两半） 犀角（镑） 黄"}, {"source": "条85｜《圣济总录 • 卷第四十三》", "原文": "而在《圣济总录 • 卷第四十三》中用茯神丸治疗“心脏虚热，惊悸心忪，虚乏气短，睡卧不安”，其组成为“茯神（去木二两） 人参 麦门冬（去心焙） 龙齿 防风（去叉） 云母粉（各一两半） 犀角（镑） 黄芩（去黑心） 薏苡仁（各二两）”，多为重镇安神祛风清热之药。二者名称虽相同，但功能主治及组成均不相同。", "白话": "（句译见条84。）本处《圣济总录•卷第四十三》茯神丸为重镇安神、祛风清热之剂。"}, {"source": "条86｜《圣济总录 • 卷第一百七十》", "原文": "同时还记录了一些治疗小儿心悸的方剂，如《圣济总录 • 卷第一百七十》治疗“小儿风热惊掣，心忪恐悸”时，用茯神汤治疗，并且用量较成人小。", "白话": "同时还记录了治疗小儿心悸的方剂，如《圣济总录•卷第一百七十》治“小儿风热惊掣、心忪恐悸”用茯神汤，且用量较成人小。"}, {"source": "条87｜《幼幼新书》", "原文": "《幼幼新书》中金泥煎方治疗“小儿心热，多惊悸”。", "白话": "《幼幼新书》的金泥煎方治疗“小儿心热，多惊悸”。"}, {"source": "条88｜《幼幼新书 • 卷第三十九》", "原文": "一些治疗范围广泛的疾病，如《幼幼新书 • 卷第三十九》中提到仙人炼绛雪可以“疗一切病”也被纳入进来；《太平惠民和剂局方 • 卷之五》宁志膏可治疗“一切心疾”，可以看出这些药物的适用范围较大。", "白话": "一些主治范围很广的方剂也被纳入，如《幼幼新书•卷第三十九》说仙人炼绛雪能“疗一切病”；《太平惠民和剂局方•卷之五》宁志膏治“一切心疾”——可见这些方药适用范围较大。"}, {"source": "条89｜《太平惠民和剂局方 • 卷之五》", "原文": "一些治疗范围广泛的疾病，如《幼幼新书 • 卷第三十九》中提到仙人炼绛雪可以“疗一切病”也被纳入进来；《太平惠民和剂局方 • 卷之五》宁志膏可治疗“一切心疾”，可以看出这些药物的适用范围较大。", "白话": "（句译见条88。）本处《太平惠民和剂局方•卷之五》宁志膏治“一切心疾”。"}, {"source": "条90｜《圣济总录 • 卷第一百六十八》", "原文": "值得注意的是，在送服汤药中，有文献专门提到治疗心悸用特定的汤药送下，如《圣济总录 • 卷第一百六十八》天南星丸中，若出现惊悸，则用“薄荷荆芥汤下”。", "白话": "值得注意的是，送服汤药中也有文献专门提到治心悸用特定汤药送下，如《圣济总录•卷第一百六十八》天南星丸，若出现惊悸，则用“薄荷荆芥汤送下”。"}, {"source": "条91｜《仁斋直指方论》", "原文": "明清时期多转述前人的内容，并在前人论述的基础上进行了发挥。《仁斋直指方论》明确指出用朱雀丸“治心病怔忪不止”，方中用茯神和沉香，共奏养心安神之功，是治疗心悸的重要方剂。", "白话": "明清时期多转述前人内容，并在前人论述基础上加以发挥。《仁斋直指方论》明确指出用朱雀丸“治心病怔忪不止”，方用茯神、沉香，共奏养心安神之功，是治疗心悸的重要方剂。"}, {"source": "条92｜《校注妇人良方》", "原文": "在治疗心血气虚导致的心悸时，《校注妇人良方》提到用茯神散治疗“五脏气血虚弱，惊悸怔忡，宜用此安神定志。”。养心汤“治心血虚，惊悸怔忡不宁，或盗汗无寐，发热烦躁”。", "白话": "治疗心血气虚所致心悸时，《校注妇人良方》提到用茯神散治“五脏气血虚弱，惊悸怔忡，宜用此安神定志”；养心汤“治心血虚，惊悸怔忡不宁，或盗汗无寐、发热烦躁”。"}, {"source": "条93｜《仁斋直指方论》", "原文": "《仁斋直指方论》用十四友丸“治心血俱虚，怔忡惊惕”。”方中大多使用用人参、远志、川芎、酸枣仁、黄芪、柏子仁等补气养心安神药物补益心血。归脾类方在明清书籍中也常用来治疗心悸，出现次数频繁，也是现代临床治疗心悸的常用方剂之一。", "白话": "《仁斋直指方论》用十四友丸“治心血俱虚、怔忡惊惕”。方中多用人参、远志、川芎、酸枣仁、黄芪、柏子仁等补气养心安神之品补益心血。归脾类方在明清医书中也常用以治疗心悸，出现频繁，也是现代临床治疗心悸的常用方剂之一。"}, {"source": "条94｜《仁斋直指方论》", "原文": "亦有因痰导致的心悸，如《仁斋直指方论》中用加味定志丸“治痰迷心膈，惊悸怔忡”。", "白话": "也有因痰致悸的，如《仁斋直指方论》用加味定志丸“治痰迷心膈、惊悸怔忡”。"}, {"source": "条95｜《世医得效方》", "原文": "《世医得效方》中用加味寿星图“治惊忧思虑，气结成痰，留蓄心胞，怔忡惊惕，痰逆恶心，睡卧不安”。”同时温胆汤类方在本时期也出现频繁，用于治疗心胆虚怯导致的心悸，对临床有很好的指导作用。例如十味温胆汤也治疗“心胆虚怯，触事易惊，梦寐不祥，异象感惑，遂致心惊胆慑，气郁生涎，涎与气搏，变生诸证。或短气悸乏，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安”等，则用陈皮、半夏、菖蒲、远志等药物燥湿化痰开窍，", "白话": "《世医得效方》用加味寿星图“治惊忧思虑、气结成痰、留蓄心胞、怔忡惊惕、痰逆恶心、睡卧不安”。同时温胆汤类方在本时期也出现频繁，用于治疗心胆虚怯所致心悸，对临床很有指导作用。例如十味温胆汤也治“心胆虚怯，触事易惊，梦寐不祥，异象感惑，遂致心惊胆慑，气郁生涎，涎与气搏，变生诸证；或短气悸乏，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安”等，用陈皮、半夏、菖蒲、远志等燥湿化痰开窍，防止心神被痰浊蒙蔽。同时温胆汤类方在本时期出现频繁，用于治疗心胆虚怯所致心悸，对临床很有指导作用。"}, {"source": "条96｜《婴童百问》", "原文": "还有因水饮形成的心悸，如《婴童百问》中用茯苓半夏汤治疗“诸呕吐，心下坚痞，膈间有痰水眩悸”。”方中茯苓二两有消水饮、安神之效，半夏有化痰之功，二者合用，能消除因水饮导致的心悸；。《仁斋直指方论》提到“小半夏茯苓汤、五苓散，并主水气，心下怔忪”。", "白话": "还有水饮所致的心悸，如《婴童百问》用茯苓半夏汤治“诸呕吐，心下坚痞，膈间有痰水眩悸”。方中茯苓二两消水饮、安神，半夏化痰，二者合用能消除水饮所致心悸。《仁斋直指方论》提到“小半夏茯苓汤、五苓散，并主水气，心下怔忪”。"}, {"source": "条97｜《仁斋直指方论》", "原文": "《仁斋直指方论》提到“小半夏茯苓汤、五苓散，并主水气，心下怔忪”。", "白话": "《仁斋直指方论》提到“小半夏茯苓汤、五苓散，都主治水气、心下怔忪”。"}, {"source": "条98｜《伤寒论》", "原文": "综上所述，经过对古代治疗心悸的古籍进行筛选，发现自明代之后，后世转载前人书中的内容（包含方名、功能主治、组成）较多，其中尤以引用《伤寒论》《金匮要略》中内容的次数最多，各个朝代治疗心悸的方剂总体以心血气虚、痰扰心神、水饮凌心、过度惊吓等原因进行应用，从而应用补益气血、养心安神、涤痰、化饮、镇惊等药物进行治疗，以达到缓解甚至治愈心悸的疗效。", "白话": "综上，经筛选古代治疗心悸的古籍发现：明代以后后世转载前人书中的内容（含方名、功能主治、组成）较多，其中尤以引用《伤寒论》《金匮要略》次数最多。各朝代治疗心悸的方剂总体针对心血气虚、痰扰心神、水饮凌心、过度惊吓等病因应用，采用补益气血、养心安神、涤痰、化饮、镇惊等药物治疗，以达到缓解甚至治愈心悸的疗效。"}, {"source": "条99｜《金匮要略》", "原文": "综上所述，经过对古代治疗心悸的古籍进行筛选，发现自明代之后，后世转载前人书中的内容（包含方名、功能主治、组成）较多，其中尤以引用《伤寒论》《金匮要略》中内容的次数最多，各个朝代治疗心悸的方剂总体以心血气虚、痰扰心神、水饮凌心、过度惊吓等原因进行应用，从而应用补益气血、养心安神、涤痰、化饮、镇惊等药物进行治疗，以达到缓解甚至治愈心悸的疗效。", "白话": "（句译见条98。）本处《金匮要略》与《伤寒论》并列为后世转载引用最多的方书。"}, {"source": "条100｜《针灸甲乙经》卷七", "原文": "《针灸甲乙经》卷七：“肺疟，令人心寒，甚热，热间善惊，如有所见者，刺手太阴、阳明。", "白话": "《针灸甲乙经》卷七：“肺疟，使人心中发冷，热势很重，热势间歇时容易惊恐，好像看见了什么似的——刺手太阴、手阳明（经）。”"}, {"source": "条101｜《针灸甲乙经》卷七", "原文": "《针灸甲乙经》卷七：“热病先手臂瘛疭，唇口聚鼻张，目下汗出如转珠，两乳下二寸坚，胁满，悸，列缺主之。", "白话": "《针灸甲乙经》卷七：“热病先见手臂抽搐拘挛、唇口收聚鼻翼扇动、目下汗出如转珠、两乳下二寸处坚硬、胁肋胀满、心悸——列缺主之。”"}, {"source": "条102｜《针灸甲乙经》卷七", "原文": "《针灸甲乙经》卷七：“心澹澹然，善惊，身热，烦心，口干，手清，逆气，呕血，时瘈瘛，善摇头，颜青汗出不过肩，伤寒温病，曲泽主之。", "白话": "《针灸甲乙经》卷七：“心中澹澹不宁、容易惊恐、身热、心烦、口干、手冷、气上逆、呕血、时或抽搐、常摇头、面色青而汗出不过肩——伤寒温病，曲泽主之。”"}, {"source": "条103｜《针灸甲乙经》卷七", "原文": "《针灸甲乙经》卷七：“热病烦心善呕，胸中澹澹，善动而热，间使主之。", "白话": "《针灸甲乙经》卷七：“热病心烦、常呕、胸中澹澹悸动、躁动而热——间使主之。”"}, {"source": "条104｜《针灸甲乙经》卷七", "原文": "《针灸甲乙经》卷七：“面赤皮热，热病汗不出，中风热，目赤黄，肘挛腋肿，实则心暴痛，虚则烦心，心惕惕不能动，失智，内关主之。", "白话": "《针灸甲乙经》卷七：“面赤肤热、热病汗不出、中风热、目赤黄、肘挛腋肿——实则心前暴痛，虚则心烦、心中惕惕不能动、神志失常——内关主之。”"}, {"source": "条105｜《针灸甲乙经》卷七", "原文": "《针灸甲乙经》卷七：“身懈，寒少气，热甚恶人 ，心惕惕然，取飞扬及绝骨、跗下临泣，立已。", "白话": "《针灸甲乙经》卷七：“身体懈怠、恶寒少气、热甚时厌恶见人、心中惕惕惊惧——取飞扬、绝骨及足跗上临泣，立即痊愈。”"}, {"source": "条106｜《针灸甲乙经》卷七", "原文": "《针灸甲乙经》卷七：“黄帝问曰∶：足阳明之脉病，恶人与火，闻木音则惕然而惊，欲独闭户牖而处，愿闻其故。岐伯对曰∶：阳明者胃脉也，胃土也，闻木音而惊者，土恶木也。阳明主肌肉，其血气盛，邪客之则热，热甚则恶火。阳明厥则喘闷，闷则恶人。阴阳相薄，阳尽阴盛，故欲独闭户牖而处按阴阳相薄至此，本《素问·脉解篇》篇，士安移续于此。", "白话": "《针灸甲乙经》卷七：“黄帝问：足阳明经脉发病，厌恶人与火，听到木音就惕然而惊，想独自闭门关窗独处，希望听听其中缘故。岐伯答：阳明是胃脉，胃属土，听到木音而惊，是土恶木的缘故。阳明主肌肉，血气旺盛，邪气侵犯就发热，热甚就恶火。阳明气厥就喘而胸闷，闷就厌恶见人。阴阳相争，阳尽而阴盛，所以想独自闭户而处。（按：自‘阴阳相薄’至此，本出《素问·脉解篇》，士安移录续于此。）”"}, {"source": "条107｜《素问·脉解篇》", "原文": "阴阳相薄，阳尽阴盛，故欲独闭户牖而处按阴阳相薄至此，本《素问·脉解篇》篇，士安移续于此。", "白话": "（校语）自“阴阳相薄”到此，本出自《素问·脉解篇》，皇甫谧（士安）移录续接于此。"}, {"source": "条108｜《针灸甲乙经》卷七", "原文": "《针灸甲乙经》卷七：“足少阳疟，令人身体解㑊，寒不甚，恶见人，心惕惕然，热多汗出甚，刺足少阳。", "白话": "《针灸甲乙经》卷七：“足少阳疟，使人身体懈怠无力、恶寒不重、厌恶见人、心中惕惕惊惧、热多而汗出甚——刺足少阳（经）。”"}, {"source": "条109｜《针灸甲乙经》卷八", "原文": "《针灸甲乙经》卷八：“寒热，唇口干，喘息，目急痛，善惊，三间主之。", "白话": "《针灸甲乙经》卷八：“寒热、唇口干、喘息、目急痛、容易惊恐——三间主之。”"}, {"source": "条110｜《针灸甲乙经》卷八", "原文": "《针灸甲乙经》卷八：“寒热食多，身羸瘦，两胁引痛，心下贲痛，心如悬，下引脐少腹急痛，热，面急一本作黑，目䀮䀮 ，喘咳少气，溺浊赤，肾俞主之。", "白话": "《针灸甲乙经》卷八：“寒热而食多、身体羸瘦、两胁牵引疼痛、心下贲痛、心如悬空、下引脐及少腹急痛、发热、面急（一本作‘面黑’）、目䀮䀮不明、喘咳少气、小便浑浊色赤——肾俞主之。”"}, {"source": "条111｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“凄寒嗽，吐血，逆气，惊，心痛，手阴郄主之。", "白话": "《针灸甲乙经》卷九：“凄凄恶寒咳嗽、吐血、气上逆、惊、心痛——（手少阴）阴郄主之。”"}, {"source": "条112｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“心澹澹而善惊恐，心悲，内关主之。", "白话": "《针灸甲乙经》卷九：“心中澹澹悸动、容易惊恐、心悲——内关主之。”"}, {"source": "条113｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“善惊，悲不乐，厥，胫足下热，面尽热，渴，行间主之。", "白话": "《针灸甲乙经》卷九：“容易惊恐、悲伤不乐、厥冷、胫及足下发热、满面发热、口渴——行间主之。”"}, {"source": "条114｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“胆病者，善太息，口苦，呕宿水，心下澹澹，善恐，如人将捕之，嗌中吤吤然，数咳唾，候在足少阳之本末，亦视其脉之陷下者灸之。", "白话": "《针灸甲乙经》卷九：“胆病，常太息、口苦、呕宿水、心下澹澹悸动、容易恐惧，好像有人要抓捕自己、咽中吤吤有声、频频咳唾——诊候在足少阳经的起止（本末），并察其脉陷下者施灸。”"}, {"source": "条115｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“心痛善悲，厥逆，悬心如饥之状，心澹澹而惊，大陵及间使主之。", "白话": "《针灸甲乙经》卷九：“心痛、常悲、厥逆、心悬如饥之状、心中澹澹而惊——大陵、间使主之。”"}, {"source": "条116｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“心如悬，哀而乱，善恐，嗌内肿，心惕惕恐，如人将捕之，多涎出，喘，少气，吸吸不足以息，然谷主之。", "白话": "《针灸甲乙经》卷九：“心如悬空、悲哀而心乱、容易恐惧、咽内肿、心中惕惕而恐、好像有人追捕、多涎出、喘、少气、吸吸不足以息——然谷主之。”"}, {"source": "条117｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“惊，善悲不乐，如堕坠，汗不出，面尘黑，病饮不欲食，照海主之。", "白话": "《针灸甲乙经》卷九：“惊、常悲不乐、如从高坠下、汗不出、面如尘黑、病水饮而不欲食——照海主之。”"}, {"source": "条118｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“胆眩寒厥，手臂痛，善惊忘言，面赤泣出，腋门主之。", "白话": "《针灸甲乙经》卷九：“胆病眩晕寒厥、手臂痛、容易惊恐而失语、面赤流泪——腋门主之。”"}, {"source": "条119｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“喘，少气不足以息，腹满，大便难，时上走，胸中鸣，胀满，口舌中吸吸，善惊，咽中痛，不可纳食，善怒，恐，不乐，大钟主之。", "白话": "《针灸甲乙经》卷九：“喘、少气不足以息、腹满、大便难、气时上冲、胸中鸣响、胀满、口舌中吸吸而动、容易惊恐、咽痛不能进食、常怒、恐惧、不乐——大钟主之。”"}, {"source": "条120｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“大惊乳痛，梁丘主之。", "白话": "《针灸甲乙经》卷九：“大惊而乳痛——梁丘主之。”"}, {"source": "条121｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“狐疝惊悸少气，巨阙主之。", "白话": "《针灸甲乙经》卷九：“狐疝、惊悸、少气——巨阙主之。”"}, {"source": "条122｜《针灸甲乙经》卷九", "原文": "《针灸甲乙经》卷九：“阴跳腰痛，实则挺长，寒热，挛，阴暴痛，遗溺，偏大，虚则暴痒气逆，肿睾卒疝，小便不利如癃状，数噫恐悸，气不足，腹中悒悒，少腹痛，嗌中有热，如有瘜肉状，如着欲出，背挛不可俛俯仰，蠡沟主之。", "白话": "《针灸甲乙经》卷九：“阴器跳动、腰痛——实则阴挺长、寒热、拘挛、阴部暴痛、遗尿、偏大；虚则暴痒气逆、睾丸肿卒疝、小便不利如癃闭之状、频频嗳气恐惧而悸、气不足、腹中悒悒不舒、少腹痛、咽中发热、如长瘜肉之状、如有物附着将出、背部拘挛不能俯仰——蠡沟主之。”"}, {"source": "条123｜《针灸甲乙经》卷十一", "原文": "《针灸甲乙经》卷十一：“脉代不至寸口，四逆脉鼓不通，云门主之。", "白话": "《针灸甲乙经》卷十一：“脉代而寸口不至、四肢厥逆、脉鼓动不通——云门主之。”"}, {"source": "条124｜《针灸甲乙经》卷十一", "原文": "《针灸甲乙经》卷十一：“胸中寒，脉代时至，上重下轻，足不能地，少腹胀，上抢心，胸榰满，咳唾有血，然谷主之。", "白话": "《针灸甲乙经》卷十一：“胸中寒、脉时现代止、上重下轻、足不能着地、少腹胀、气上冲心、胸胁支撑胀满、咳唾带血——然谷主之。”"}, {"source": "条125｜《针灸甲乙经》卷十一", "原文": "《针灸甲乙经》卷十一：“癫疾始作，而引口啼呼喘悸者，候之以手阳明、太阳，左强者攻其右一本作左，右强者攻其左一本作右，血变而止。", "白话": "《针灸甲乙经》卷十一：“癫疾初发，牵口歪斜、啼呼、喘而心悸的，诊候于手阳明、手太阳（经）；左侧强急的攻刺右侧（一本作‘左’），右侧强急的攻刺左侧（一本作‘右’），待血色改变而止针。”"}, {"source": "条126｜《针灸甲乙经》卷十二", "原文": "《针灸甲乙经》卷十二：“惊不得眠，善齘𬹼，水气上下，五脏游气也，三阴交主之。", "白话": "《针灸甲乙经》卷十二：“受惊不得眠、常咬牙切齿、水气上下攻冲、五脏游走之气——三阴交主之。”"}, {"source": "条127｜《针灸甲乙经》卷十二", "原文": "《针灸甲乙经》卷十二：“曰：人之哀而泣涕者何？曰：心者五脏六腑之主也；目者宗脉之所聚也，上液之道也；口鼻者气之门户也。故悲哀愁忧则心动，心动则五脏六腑皆摇，摇则宗脉感，宗脉感则液道开，液道开故涕泣出焉。液者所以灌精濡空窍者也，故上液之道开则泣，泣不止则液竭，液竭则精不灌，精不灌则目无所见矣，故名曰夺精，补天柱，经侠颈，侠颈者，头中分也。", "白话": "《针灸甲乙经》卷十二：“问：人悲哀时流泪涕泣是为什么？答：心是五脏六腑之主；目是众脉所聚之处，是上部津液的通道；口鼻是气的门户。所以悲哀愁忧则心动，心动则五脏六腑都动摇，动摇则宗脉感应，宗脉感应则液道开，液道开所以涕泪流出。津液是用来灌注精微、濡润孔窍的，所以上部液道开则流泪，流泪不止则津液枯竭，津液枯竭则精微不灌注，精微不灌注则目无所见，所以名叫‘夺精’——当补天柱穴（其经夹颈而行），夹颈者，在头中分之处。”"}, {"source": "条128｜《脉经》卷二", "原文": "《脉经》卷二：“左手关上阳绝者，无胆脉也。苦膝疼，口中苦，昩目，善畏，如见鬼状，多惊，少力。刺足厥阴经，治阴。在足大指间即行间穴也，或刺三毛中。", "白话": "《脉经》卷二：“左手关上（脉）阳绝的，是无胆脉。苦于膝疼、口中苦、目不明、易畏惧、如见鬼状、多惊、少力——刺足厥阴经以治其阴；在足大趾间，即行间穴，或刺足大趾三毛之中。”"}, {"source": "条129｜《备急千金要方》卷十四", "原文": "《备急千金要方》卷十四：“惊怖心忪，少力，灸大横五十壮。", "白话": "《备急千金要方》卷十四：“惊恐心悸、少力——灸大横五十壮。”"}, {"source": "条130｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“支沟、太溪、然谷，主心痛如锥刺，甚者手足寒至节，不息者死。", "白话": "《备急千金要方》卷三十：“支沟、太溪、然谷，主治心痛如锥刺，重者手足寒至肘膝关节，呼吸不续者死。”"}, {"source": "条131｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“大都、太白，主暴泄、心痛、腹胀，心痛尤甚。", "白话": "《备急千金要方》卷三十：“大都、太白，主治暴泄、心痛、腹胀，心痛尤其明显。”"}, {"source": "条132｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“临泣，主胸痹心痛，不得反侧。《甲乙》云：不得息，痛无常处。", "白话": "《备急千金要方》卷三十：“临泣，主治胸痹心痛、不能转侧。《甲乙》说：呼吸不利，疼痛无固定部位。”"}, {"source": "条133｜《甲乙》（《针灸甲乙经》简称）", "原文": "《备急千金要方》卷三十：“临泣，主胸痹心痛，不得反侧。《甲乙》云：不得息，痛无常处。", "白话": "（引书语）《甲乙》即《针灸甲乙经》，其文作：“（临泣主胸痹心痛）不得息，痛无常处。”——与《千金》本文略异，可互参。"}, {"source": "条134｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“行间，主心痛，色苍苍然如死灰状，终日不得太息。", "白话": "《备急千金要方》卷三十：“行间，主治心痛、面色苍苍如死灰之状、整日不得长叹息。”"}, {"source": "条135｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“通谷、巨阙、太仓、心俞、膻中、神府，主心痛。", "白话": "《备急千金要方》卷三十：“通谷、巨阙、太仓、心俞、膻中、神府，主治心痛。”"}, {"source": "条136｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“通里，主卒痛烦心，心中懊憹，数欠频伸，心下悸，悲恐。", "白话": "《备急千金要方》卷三十：“通里，主治猝然心痛心烦、心中懊憹不宁、频频呵欠伸腰、心下悸动、悲伤恐惧。”"}, {"source": "条137｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“期门、长强、天突、侠白、中冲，主心痛短气。", "白话": "《备急千金要方》卷三十：“期门、长强、天突、侠白、中冲，主治心痛短气。”"}, {"source": "条138｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“尺泽，主心痛彭彭然，心烦闷乱，少气不足以息。", "白话": "《备急千金要方》卷三十：“尺泽，主治心痛彭彭胀满、心烦闷乱、少气不足以息。”"}, {"source": "条139｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“肾俞、复溜、大陵、云门，主心痛如悬。", "白话": "《备急千金要方》卷三十：“肾俞、复溜、大陵、云门，主治心痛如悬。”"}, {"source": "条140｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“章门，主心痛而呕。", "白话": "《备急千金要方》卷三十：“章门，主治心痛而呕。”"}, {"source": "条141｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“建里，主心痛上抢心，不欲食。", "白话": "《备急千金要方》卷三十：“建里，主治心痛气上冲心、不欲食。”"}, {"source": "条142｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“少冲，主心痛而寒。", "白话": "《备急千金要方》卷三十：“少冲，主治心痛而恶寒。”"}, {"source": "条143｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“太渊，主心痛肺胀，胃气上逆。", "白话": "《备急千金要方》卷三十：“太渊，主治心痛、肺胀、胃气上逆。”"}, {"source": "条144｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“鸠尾，主心寒胀满，不得食，息贲，唾血，厥心痛善哕，心疝太息。", "白话": "《备急千金要方》卷三十：“鸠尾，主治心中寒冷、胀满、不能食、息贲、唾血、厥心痛而常呃逆、心疝太息。”"}, {"source": "条145｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“上脘，主心痛，有三虫，多涎，不得反侧。", "白话": "《备急千金要方》卷三十：“上脘，主治心痛、有三虫、多涎、不能转侧。”"}, {"source": "条146｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“中脘，主心痛难以俯仰。《甲乙》云：身寒心疝，冲冒死不知人。", "白话": "《备急千金要方》卷三十：“中脘，主治心痛难以俯仰。《甲乙》说：身寒、心疝、气冲昏冒、死不知人。”"}, {"source": "条147｜《甲乙》（《针灸甲乙经》简称）", "原文": "《备急千金要方》卷三十：“中脘，主心痛难以俯仰。《甲乙》云：身寒心疝，冲冒死不知人。", "白话": "（引书语）《甲乙》即《针灸甲乙经》，其文作：“（中脘主）身寒心疝，冲冒死不知人。”为《千金》引《甲乙经》之校文，照录为独立一条。"}, {"source": "条148｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“不容、期门，主心切痛，喜噫酸。", "白话": "《备急千金要方》卷三十：“不容、期门，主治心痛如切、常嗳腐酸。”"}, {"source": "条149｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“盲肓门，主心下大坚。", "白话": "“盲肓门（穴），主治心下部胀大坚硬。”"}, {"source": "条150｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“灵道，主心痛悲恐，相引瘛疭。", "白话": "“灵道（穴），主治心痛、悲伤恐惧，相互牵引而抽搐。”"}, {"source": "条151｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“间使，主心悬如饥。", "白话": "“间使（穴），主治心悬空如饥饿（之感）。”"}, {"source": "条152｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“商丘，主心下有寒痛；又主脾虚，令人病不乐，好太息。", "白话": "“商丘（穴），主治心下有寒痛；又主治脾虚，使人病而情绪不乐、好叹气。”"}, {"source": "条153｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“凡卒心痛汗出，刺大敦，出血立已。", "白话": "“凡突然心痛、汗出的，刺大敦，出血立刻痊愈。”"}, {"source": "条154｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“凡心实者，则心中暴痛，虚则心烦，惕然不能动，失智，内关主之。", "白话": "“凡心实的，就心中突然疼痛；心虚的就心烦、惊惕不能动作、神志丧失——都由内关主治。”"}, {"source": "条155｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“蠡沟，主数噫恐悸，气不足，腹中悒悒。", "白话": "“蠡沟（穴），主治频作嗳气、恐惧心悸、气不足、腹中郁闷不舒。”"}, {"source": "条156｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“彧中、云门，主咳逆上气，涎出多唾，呼吸喘悸，坐不安席。", "白话": "“彧中、云门（二穴），主治咳嗽气逆上气、涎出多唾、呼吸喘促心悸、坐不安稳。”"}, {"source": "条157｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“丝竹空、通谷，主风痫癫疾，涎沫，狂烦懑。", "白话": "“丝竹空、通谷（二穴），主治风痫、癫疾，涎沫，狂躁烦闷。”"}, {"source": "条158｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“天冲，主头痛癫疾互引，数惊悸。", "白话": "“天冲（穴），主治头痛、癫疾相互牵引，频发惊悸。”"}, {"source": "条159｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“神门、阳谷，主笑若狂。又云：神门，主数噫，恐悸不足。", "白话": "“神门、阳谷（二穴），主治笑如狂。又说：神门，主治频作嗳气、恐惧心悸、（正气）不足。”"}, {"source": "条160｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“巨阙、筑宾，主狂易妄言怒骂。又云：巨阙，主惊悸少气。", "白话": "“巨阙、筑宾（二穴），主治发狂失常、妄言怒骂。又说：巨阙，主治惊悸、少气。”"}, {"source": "条161｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“腕骨，主烦满惊。", "白话": "“腕骨（穴），主治心烦胀满而惊。”"}, {"source": "条162｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“少府，主数噫恐悸，气不足。", "白话": "“少府（穴），主治频作嗳气、恐惧心悸、气不足。”"}, {"source": "条163｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“通里，主心下悸。", "白话": "“通里（穴），主治心下悸动。”"}, {"source": "条164｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“行间，主心痛数惊，心悲不乐。", "白话": "“行间（穴），主治心痛频发惊恐、心中悲忧不乐。”"}, {"source": "条165｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“三间、合谷、厉兑，主吐舌，戾颈喜惊。又云：厉兑，主多卧好惊。", "白话": "“三间、合谷、厉兑（三穴），主治吐舌、颈项扭转不顺、容易受惊。又说：厉兑，主治多睡嗜卧、容易受惊。”"}, {"source": "条166｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“手少阴、阴郄，主气惊心痛。", "白话": "“手少阴（穴）、阴郄（穴），主治因气而惊、心痛。”"}, {"source": "条167｜《备急千金要方》卷三十", "原文": "《备急千金要方》卷三十：“列缺、曲池，主热病烦心心闷，先手臂身热，瘛疭，唇口聚，鼻张，目下汗出如珠。《甲乙》云：两乳下一寸坚，胁下满，心悸。", "白话": "“列缺、曲池（二穴），主治热病心烦心闷，先手臂与身体发热，抽搐，唇口收聚，鼻翼张动，目下汗出如珠。《甲乙经》说：两乳下一寸处坚硬，胁下胀满，心悸。”"}, {"source": "条168｜《甲乙》（条167 引文内所引）", "原文": "《甲乙》云：两乳下一寸坚，胁下满，心悸。", "白话": "“《甲乙经》说：两乳下一寸处坚硬，胁下胀满，心悸。”"}, {"source": "条169｜《黄帝内经太素》卷二十五", "原文": "《黄帝内经太素》卷二十五：“热病，嗌干多饮，善惊，卧不能定，取之肤肉，以第六针，五十九，索肉于脾，不得索之木，木，肝也。热病，嗌干多饮，喜惊，卧不得安，肉病者，可以第六员利针。", "白话": "“热病，咽喉干燥、饮水多、容易受惊、躺卧不能安定的，取治于肤肉（之分），用第六针，（依）五十九（刺法），从脾索求治肉病，不得从木（肝）求治——木属肝。热病，咽喉干燥、饮水多、容易受惊、躺卧不得安宁，属肉病的，可以用第六员利针。”"}, {"source": "条170｜《黄帝内经太素》卷二十五", "原文": "《黄帝内经太素》卷二十五：“热病数惊，瘛疭而狂，取之脉，以第四针，急泻有余者，癫疾毛髦去，惊瘛疭狂，此为血病，故取之脉。第四针者，锋针也，刃参隅，应心，可以泻热出血，痼癫疾及毛髦落，皆得愈也。", "白话": "“热病频发惊恐、抽搐发狂的，从脉论治，用第四针，急泻其有余——癫疾、毛发脱落，惊惕、抽搐、狂乱，这是血病，所以从脉论治。第四针即锋针，刃有三隅，与心相应，可以泻热出血，久痼癫疾及毛发脱落，都可痊愈。”"}, {"source": "条171｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“曲泽，主心下澹澹喜惊。", "白话": "“曲泽（穴），主治心下悸动不安、容易受惊。”"}, {"source": "条172｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“阴交、气海、大巨，主惊不得卧。", "白话": "“阴交、气海、大巨（三穴），主治受惊、不能安卧。”"}, {"source": "条173｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“阴跷，主卧惊视如见星。", "白话": "“阴跷（脉），主治睡眠惊惕、视物如见星光。”"}, {"source": "条174｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“大钟、郄门，主惊恐畏人，神气不足。", "白话": "“大钟、郄门（二穴），主治惊恐、怕见人、神气不足。”"}, {"source": "条175｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“然谷、阳陵泉，主心中悚惕，恐人将捕之。", "白话": "“然谷、阳陵泉（二穴），主治心中惊惧惕动，恐惧如有人要抓捕自己。”"}, {"source": "条176｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“解溪，主瘛疭而惊。", "白话": "“解溪（穴），主治抽搐而惊。”"}, {"source": "条177｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“少冲，主太息烦满，少气悲惊。", "白话": "“少冲（穴），主治叹气、烦闷胀满、气短、悲伤易惊。”"}, {"source": "条178｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“行间，主心痛数惊，心悲不乐。", "白话": "“行间（穴），主治心痛频发惊恐、心中悲忧不乐。”"}, {"source": "条179｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“阳谷，主风眩惊，心悲不乐。", "白话": "“阳谷（穴），主治风眩而惊、心中悲忧不乐。”"}, {"source": "条180｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“阳谷，主风眩惊手卷。", "白话": "“阳谷（穴），主治风眩而惊、手卷曲不伸。”"}, {"source": "条181｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“厉兑，主多卧好惊。", "白话": "“厉兑（穴），主治多睡嗜卧、容易受惊。”"}, {"source": "条182｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“腋门，主喜惊妄言面赤。", "白话": "“腋门（穴），主治容易受惊、妄言、面赤。”"}, {"source": "条183｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“神门，主数噫恐悸少气。", "白话": "“神门（穴），主治频作嗳气、恐惧心悸、少气。”"}, {"source": "条184｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“间使，主喜惊喑不能言。", "白话": "“间使（穴），主治容易受惊、失音不能言语。”"}, {"source": "条185｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“三间、合谷，主喜惊。", "白话": "“三间、合谷（二穴），主治容易受惊。”"}, {"source": "条186｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“阳溪，主惊瘛。", "白话": "“阳溪（穴），主治惊惕抽搐。”"}, {"source": "条187｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“通里，主心下悸。", "白话": "“通里（穴），主治心下悸动。”"}, {"source": "条188｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“大陵，主心中澹澹惊恐。", "白话": "“大陵（穴），主治心中悸动不安、惊恐。”"}, {"source": "条189｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“手少阴阴郄，主气惊心痛。", "白话": "“手少阴的阴郄（穴），主治因气而惊、心痛。”"}, {"source": "条190｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“天井，主惊瘛。", "白话": "“天井（穴），主治惊惕抽搐。”"}, {"source": "条191｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“后溪，主泪出而惊。", "白话": "“后溪（穴），主治流泪而惊。”"}, {"source": "条192｜《千金翼方》卷二十六", "原文": "《千金翼方》卷二十六：“腕骨，主烦满惊。", "白话": "“腕骨（穴），主治心烦胀满而惊。”"}, {"source": "条193｜《外台秘要》卷十九", "原文": "《外台秘要》卷十九：“又若胸中气散，而心下有脉洪大跳，其数向下，分入两髀股内，令人心急忪悸者，宜以手按捻少腹下两傍接髀大斜文中，有脉跳动，便当文上灸跳三七炷即定。灸毕，皆须灸三里二十炷，以引其气下也。", "白话": "“又若胸中之气涣散，而心下有脉洪大跳动，其搏动向下，分入两侧大腿内侧，使人心急心悸的，宜用手按揉少腹下两旁接大腿的斜纹中，有脉跳动处，便当在纹上灸跳动处三七（二十一）炷即安定。灸完，都须灸三里二十炷，以引其气下行。”"}, {"source": "条194｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“列缺，手太阴络，去腕上一寸半，灸五壮。甄权云：腕后臂侧三寸交叉头两筋骨罅宛宛中是也。主偏风口，半身不随，腕劳，灸三壮。主疟甚热，惊痫，如有见者，咳喘，掌中热，虚则肩背寒栗，少气不足以息，寒厥交两手如瞀，为口沫出。实则肩背热痛，汗出，四肢肿，身湿摇，时寒热，饥则烦，饱则面色变，口噤不开，恶风泣出，喉痹，咳上气，数欠，四肢厥逆，善笑，溺白。热病先手臂痛，身热瘛疭，唇口聚，鼻张", "白话": "“列缺，是手太阴的络穴，离腕上一寸半，灸五壮。甄权说：腕后臂侧三寸、两筋骨缝隙宛宛中即是。主治偏风口歪、半身不遂、腕部劳损，灸三壮。主治疟疾甚热、惊痫、如有鬼神所见、咳喘、掌中发热；虚则肩背寒栗、少气不足以息、寒厥两手交叉如瞀、口沫出；实则肩背热痛、汗出、四肢肿、身湿润摇动、时寒时热、饥饿则烦、饱食则面色改变、口噤不开、恶风流泪、喉痹、咳嗽上气、频打呵欠、四肢厥冷、善笑、小便色白。热病先手臂痛、身热抽搐、唇口收聚、鼻翼张动、呕吐汗出如连珠、小便白而热痛、两乳下三寸处坚硬、胁下"}, {"source": "条195｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“蠡沟，足厥阴络，在内踝上五寸，灸三壮。主女子疝，少腹肿，赤白淫时多时少，阴跳腰腹痛。实则挺长，寒热，挛，暴痛，遗溺，偏大。虚则暴痒，肿睾，卒疝，小便不利如癃状，数噫，恐悸，气不足。腹中悒悒，少腹痛，喉中有热，如息肉状。背挛不可俛俯仰。", "白话": "“蠡沟，是足厥阴的络穴，在内踝上五寸，灸三壮。主治女子疝气、少腹肿、赤白带下时多时少、阴中跳动、腰腹疼痛。实证则阴挺长、寒热、拘挛、暴痛、遗尿、偏大；虚证则突然瘙痒、睾丸肿、卒疝、小便不利如癃闭、频作嗳气、恐惧心悸、气不足。腹中郁闷、少腹痛、喉中发热如息肉状；背部拘挛不能俯仰。”"}, {"source": "条196｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“大迎，一名髓孔。在曲颔前一寸二分，骨陷者中动脉，足阳明脉气所发，灸三壮。主寒热，颈瘰疬。癫疾口。喘悸。痉口噤。噤厥。口僻失欠。下牙痛。颊肿。恶寒口不收舌。不能言。不得嚼。", "白话": "“大迎，又名髓孔。在曲颔前一寸二分，骨陷中动脉处，是足阳明脉气所发，灸三壮。主治寒热、颈项瘰疬、癫疾口歪、喘悸、痉病口噤、噤厥、口歪呵欠不止、下牙痛、颊肿、恶寒口不收舌、不能言语、不能咀嚼。”"}, {"source": "条197｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“上关，一名客主人，在耳前上廉起骨，开口有空，灸三壮。主唇呦强，上齿龋痛，口僻噤不开，耳痛聋齆，瘛疭，口沫出，寒热，痓，青盲●目，恶风寒。", "白话": "“上关，又名客主人，在耳前上廉起骨处，张口有空，灸三壮。主治唇口强急、上齿龋痛、口歪牙关不开、耳痛耳聋鼻塞、抽搐、口吐沫、寒热、痓病、青盲目疾、恶风寒。”"}, {"source": "条198｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“神门，一名锐中。，一名中都。在掌后锐骨之端陷者中。灸三壮。主疟心烦。，甚欲得冷水。，寒则欲处热。，热中喉干不嗜食。，心痛数噫。，恐悸气不足。，喘逆身热。，狂悲哭泣。，呕血上气遗溺。，手及臂寒。", "白话": "“神门，又名锐中，又名中都。在掌后锐骨之端的凹陷中。灸三壮。主治疟疾心烦，甚则想饮冷水，寒则想就温热处，热中咽喉干燥不欲进食，心痛频作嗳气，恐惧心悸气不足，喘逆身热，狂而悲哭，呕血上气遗尿，手及臂寒冷。”"}, {"source": "条199｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“通里，手少阴络。，在腕后一寸。灸三壮。主热病。，先不乐数日。，热则卒心中懊憹。，数欠频伸。，悲恐。，头眩痛。，面赤而热。，无汗。，反癫。，心下悸。，臂臑肘痛。，实则支满。，虚则不能言。，善呕。，喉痹。，少气。，遗溺。", "白话": "“通里，是手少阴的络穴，在腕后一寸。灸三壮。主治热病：先数日不乐，热则突然心中懊憹，频打呵欠伸懒腰，悲伤恐惧，头眩痛，面赤而热，无汗，反见癫疾，心下悸，臂臑肘痛；实则支撑胀满，虚则不能言语，善呕，喉痹，少气，遗尿。”"}, {"source": "条200｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“彧中，在俞府下一寸六分陷者中。足少阴脉气所发。仰卧而取之。灸五壮。主咳逆上气。，涎出多唾。，呼吸喘悸。，坐不得安。", "白话": "“彧中，在俞府下一寸六分的凹陷中，是足少阴脉气所发，仰卧取之，灸五壮。主治咳嗽气逆上气、涎出多唾、呼吸喘悸、坐不安稳。”"}, {"source": "条201｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“巨阙，在鸠尾下一寸。任脉气所发。灸五壮。主心痛不可按。，烦心，。热病胸中澹澹，。腹满暴痛，。恍惚不知人，。手清少腹满，。瘛疭，。病心疝满，。不得息，。息贲时唾血，。心腹胀满，。心噫烦热善呕，。膈中不通利，。霍乱，。狂妄言怒恐，。恶火善骂詈，。狐疝惊悸少气，。胸胁支满，。瘛疭引少腹痛，。短气烦乱，。呕吐心胀。", "白话": "“巨阙，在鸠尾下一寸，是任脉气所发，灸五壮。主治心痛不可按，心烦；热病胸中悸动不安；腹满暴痛；恍惚不省人事；手冷少腹满；抽搐；心疝胀满；呼吸不利；息贲时唾血；心腹胀满；心噫烦热善呕；膈中不通利；霍乱；狂妄怒骂；恶火善骂詈；狐疝惊悸少气；胸胁支撑胀满；抽搐牵引少腹痛；短气烦乱；呕吐心胀。”"}, {"source": "条202｜《外台秘要》卷三十九", "原文": "《外台秘要》卷三十九：“上管，在巨阙下一寸五分，去蔽骨三寸，足阳明、手太阳、任脉之会，灸五壮。主寒中，伤饱，食饮不化，五腹䐜胀，心腹胸胁支满，脉虚则生百病。甄权云：主心风惊悸不能食，心下有隔，呕血，目眩，头悬眩痛，身热汗不出，心痛有三虫，多涎，不得反侧，腹中满，暴痛，汗出。", "白话": "“上管，在巨阙下一寸五分，离蔽骨三寸，是足阳明、手太阳、任脉之会，灸五壮。主治寒中、伤于饱食、饮食不化、腹部胀满、心腹胸胁支撑胀满，脉虚则生百病。甄权说：主治心风惊悸不能食、心下有隔阻、呕血、目眩、头旋眩痛、身热汗不出、心痛有三虫、多涎、不能翻身、腹中满、暴痛、汗出。”"}, {"source": "条203｜《医心方》卷二", "原文": "《医心方》卷二：“大迎二穴，一名髓空。在曲颐前一寸二分陷者中，刺入三分，留七呼，灸三壮。主寒热，颈瘰疬，癫疾。口，喘，悸，齿痛寒，痓，口噤，舌不能言。", "白话": "“大迎二穴，又名髓空。在曲颐前一寸二分的凹陷中，刺入三分，留七呼，灸三壮。主治寒热、颈项瘰疬、癫疾；口歪、喘、悸、齿痛而寒、痓病、口噤、舌不能言语。”"}, {"source": "条204｜《医心方》卷二", "原文": "《医心方》卷二：“巨阙一穴，心募也。在鸠尾穴下五分，去鸠尾骨端一寸。灸五壮，刺入六分，留七呼。任脉。主心痛，烦心，热病，胸痛，腹满，瘛疭，唾血，霍乱，妄言，狐疝，惊悸，少气，呕吐。", "白话": "“巨阙一穴，是心的募穴。在鸠尾穴下五分，离鸠尾骨端一寸。灸五壮，刺入六分，留七呼。属任脉。主治心痛、烦心、热病、胸痛、腹满、抽搐、唾血、霍乱、妄言、狐疝、惊悸、少气、呕吐。”"}, {"source": "条205｜《医心方》卷二", "原文": "《医心方》卷二：“天冲二穴，在耳上如前三寸。刺入三分，灸九壮。足少阳脉胆腑；又，足太阳脉膀胱腑。主头痛，痓，癫疾互引，善惊。", "白话": "“天冲二穴，在耳上如前（入发际）三寸。刺入三分，灸九壮。属足少阳脉胆腑；又属足太阳脉膀胱腑。主治头痛、痓病、癫疾相互牵引、容易受惊。”"}, {"source": "条206｜《医心方》卷二", "原文": "《医心方》卷二：“间使二穴，在掌后三寸两筋间陷者中。刺入六分，留七呼，灸七壮。手少阳脉三焦腑。主悬心如饥状，善悲而惊狂，面赤，目黄，及热病烦心，善哕，胸痹引背，振寒。", "白话": "“间使二穴，在掌后三寸两筋间凹陷中。刺入六分，留七呼，灸七壮。属手少阳脉三焦腑。主治心悬如饥饿状，容易悲伤而惊狂，面赤，目黄，以及热病心烦，善呃逆，胸痹牵引背部，寒战。”"}, {"source": "条207｜《医心方》卷二", "原文": "《医心方》卷二：“阴交一穴，一名少因，一名横户。在脐下一寸。刺入五分，灸五壮。任脉；又，冲脉。主惊，不得眠，善齘𬹼，水气上下，五脏游气，手足拘挛，阴疝。女子月水不下，上气腹䐜坚痛。男子两丸骞，水胀，水气行皮中矣。", "白话": "“阴交一穴，又名少因，又名横户。在脐下一寸。刺入五分，灸五壮。属任脉；又属冲脉。主治受惊、不得眠、齘齿，水气上下，五脏游气，手足拘挛，阴疝。女子月经不下，气逆腹胀坚痛。男子两丸上缩，水胀，水气行于皮中。”"}, {"source": "条208｜《医心方》卷二", "原文": "《医心方》卷二：“大巨二穴，一名液门。在长溪下二寸。刺入八分，灸五壮。同上胃腑。主腹满痛，善烦，小便难，颓疝，偏枯，四肢不用，善惊。", "白话": "“大巨二穴，又名液门。在长溪下二寸。刺入八分，灸五壮。同上（足阳明）胃腑。主治腹满痛，容易心烦，小便难，颓疝，偏枯，四肢不能用，容易受惊。”"}, {"source": "条209｜《太平圣惠方》卷五十五", "原文": "《太平圣惠方》卷五十五：“通骨二穴，在足小指外侧本节前陷者中。刺入二分，留五呼，灸三壮。同上。主：身疼痛，善惊，互引，鼻鼽衄，寒热，善嚏，项痛，振寒。", "白话": "“通骨二穴，在足小趾外侧本节前凹陷中。刺入二分，留五呼，灸三壮。同上。主治：身疼痛，容易受惊，相互牵引，鼻流清涕鼻衄，寒热，善喷嚏，项痛，寒战。”"}, {"source": "条210｜《太平圣惠方》卷五十五", "原文": "《太平圣惠方》卷五十五：“惊黄者，面色青黄，心多惊悸，口舌干燥，不肯眠卧，卧即多言语、狂乱，身体壮热。烙风池二穴，后烙天窗穴、心俞二穴。", "白话": "“惊黄，见面色青黄，心中多惊悸，口舌干燥，不肯睡卧，一躺下就多言语、狂乱，身体壮热。用烙法先烙风池二穴，再烙天窗穴、心俞二穴。”"}, {"source": "条211｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“通里二穴，在腕后一寸。治热病卒心中懊憹，数欠频伸，悲恐，目眩头痛，面赤而热，心悸，肘臂臑痛。实则支肿，虚则不能言，苦呕喉痹，少气遗溺。针入三分。可灸三壮。", "白话": "“通里二穴，在腕后一寸。治热病突然心中懊憹，频呵欠伸懒腰，悲伤恐惧，目眩头痛，面赤而热，心悸，肘臂臑痛。实则支肿，虚则不能言语，苦于呕吐喉痹，少气遗尿。针入三分。可灸三壮。”"}, {"source": "条212｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“脑空二穴，一名颞颥，在承灵后一寸半。夹玉枕骨下陷中。针五分。，得气即泻。灸三壮。《铜人经》云，。足少阳阳维之会。治脑风。，头痛不可忍。，目瞑心悸。，发即为癫风。，引目眇。，劳疾羸瘦。，体热。，颈项强不能回顾。魏公苦患头风，。发即心闷乱，。目眩，。华佗当针而立愈。《西方子》云，。主鼻管疸发为厉，。鼻劳衄不止，。耳风鸣聋。《素问》注云，。按脑空在枕骨后枕骨上。《甲乙经》作玉枕骨", "白话": "“脑空二穴，又名颞颥，在承灵后一寸半，夹玉枕骨下的凹陷中。针五分，得气即泻。灸三壮。《铜人经》说：是足少阳与阳维之会。治脑风，头痛不可忍，闭目心悸，发病即为癫风，牵引目视昏渺，劳病羸瘦，体热，颈项强不能回顾。魏公苦患头风，发作即心闷乱、目眩，华佗为他针刺立愈。《西方子》说：主治鼻管疽发作成厉，鼻病衄血不止，耳鸣耳聋。《素问》注说：按脑空在枕骨后枕骨上。《甲乙经》作玉枕骨中。禁忌同前法。《明堂经》说：灸七壮，主治狂病，身发寒热。”"}, {"source": "条213｜《铜人经》（条212 引文内所引）", "原文": "《铜人经》云，。足少阳阳维之会。治脑风。，头痛不可忍。，目瞑心悸。，发即为癫风。，引目眇。，劳疾羸瘦。，体热。，颈项强不能回顾。", "白话": "“《铜人经》说：是足少阳与阳维之会。治脑风，头痛不可忍，闭目心悸，发病即为癫风，牵引目视昏渺，劳病羸瘦，体热，颈项强不能回顾。”"}, {"source": "条214｜《西方子》（条212 引文内所引）", "原文": "《西方子》云，。主鼻管疸发为厉，。鼻劳衄不止，。耳风鸣聋。", "白话": "“《西方子》说：主治鼻管疽发作成厉，鼻病衄血不止，耳鸣耳聋。”"}, {"source": "条215｜《素问》（条212 引文内所引）", "原文": "《素问》注云，。按脑空在枕骨后枕骨上。", "白话": "“《素问》注说：按脑空在枕骨后枕骨上。”"}, {"source": "条216｜《甲乙经》（条212 引文内所引）", "原文": "《甲乙经》作玉枕骨中。", "白话": "“《甲乙经》作‘玉枕骨中’（异文校记）。”"}, {"source": "条217｜《明堂经》（条212 引文内所引）", "原文": "《明堂经》云。，灸七壮。，主狂病，。身寒热。", "白话": "“《明堂经》说：灸七壮，主治狂病，身发寒热。”"}, {"source": "条218｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“液门二穴，水也，在手小指次指间陷中，手少阳脉之所流也，为荥。治惊悸妄言，咽外肿，寒厥手臂痛，不能自上下，痎疟寒热，目眩头痛，暴得耳聋，目赤涩，齿龋痛。针入二分。可灸三壮。", "白话": "“液门二穴，属水，在手小指次指间凹陷中，是手少阳脉气所流之处，为荥穴。治惊悸妄言、咽外肿、寒厥手臂痛、手臂不能上下活动、痎疟寒热、目眩头痛、暴得耳聋、目赤涩、齿龋痛。针入二分。可灸三壮。”"}, {"source": "条219｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“天井二穴，土也，在肘外大骨后，肘后上一寸两筋间陷中，屈肘得之，手少阳脉之所入也，为合。甄权云：曲肘后一寸，叉手按膝头取之两筋骨罅。治心胸痛，咳嗽上气，唾脓不嗜食，惊悸瘛疭，风痹臂肘痛，捉物不得。可灸三壮。针入三分。", "白话": "“天井二穴，属土，在肘外大骨后、肘后上一寸两筋间凹陷中，屈肘取之，是手少阳脉气所入之处，为合穴。甄权说：屈肘后一寸，两手交叉按膝头取之两筋骨缝隙中。治心胸痛、咳嗽上气、吐脓不欲食、惊悸抽搐、风痹臂肘痛、拿物不得。可灸三壮。针入三分。”"}, {"source": "条220｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“阳溪二穴，火也，一名中魁，在腕中上侧两筋陷中，手阳明脉之所行也，为经。治狂言喜笑见鬼，热病烦心，目风赤烂有翳，厥逆头痛，胸满不得息，寒热疟疾，喉痹耳鸣，齿痛惊掣，肘臂不举，痂疥。针入三分，留七呼。可灸三壮。慎如合谷法。", "白话": "“阳溪二穴，属火，又名中魁，在腕中上侧两筋凹陷中，是手阳明脉气所行之处，为经穴。治狂言喜笑见鬼、热病心烦、目风赤烂生翳、厥逆头痛、胸满呼吸不利、寒热疟疾、喉痹耳鸣、齿痛惊掣、肘臂不举、痂疥。针入三分，留七呼。可灸三壮。慎护如合谷法。”"}, {"source": "条221｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“支正二穴，在腕后五寸，别走少阴。治寒热颔肿，肘挛，头痛目眩，风虚惊恐狂惕，生疣目。可灸三壮。针入三分。", "白话": "“支正二穴，在腕后五寸，别走（络）于少阴。治寒热颔肿、肘挛、头痛目眩、风虚惊恐狂惕、生疣目。可灸三壮。针入三分。”"}, {"source": "条222｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“曲泽二穴，水也，在肘内廉陷中，屈肘取之，手厥阴脉之所入也，为合，治心痛善惊，身热烦渴口干，逆气呕血，风疹，臂肘手腕善动摇，可灸三壮，针入三分。留七呼。", "白话": "“曲泽二穴，属水，在肘内侧凹陷中，屈肘取之，是手厥阴脉气所入之处，为合穴。治心痛善惊、身热烦渴口干、逆气呕血、风疹、臂肘手腕经常动摇。可灸三壮，针入三分，留七呼。”"}, {"source": "条223｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“郄门二穴，去腕五寸，手厥阴郄，治心痛，衄血呕哕，惊恐畏人，神气不足，针入三分，可灸五壮。", "白话": "“郄门二穴，离腕五寸，是手厥阴的郄穴。治心痛、衄血呕呃、惊恐怕见人、神气不足。针入三分，可灸五壮。”"}, {"source": "条224｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“间使二穴，金也，在掌后三寸两筋间陷中，手厥阴脉之所行也，为经，治心悬如饥，卒狂，胸中澹澹，恶心寒，呕吐，怵惕，寒中少气，掌中热，腋肿肘挛，卒心痛，多惊，喑不得语，咽中如鲠，可灸五壮，针入三分。岐伯云，可灸鬼邪。", "白话": "“间使二穴，属金，在掌后三寸两筋间凹陷中，是手厥阴脉气所行之处，为经穴。治心悬如饥、突然发狂、胸中悸动不安、恶心恶寒、呕吐、怵惕、寒中少气、掌中热、腋肿肘挛、卒心痛、多惊、失音不能语、咽中如鲠。可灸五壮，针入三分。岐伯说：可灸鬼邪（为病者）。”"}, {"source": "条225｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“太陵二穴，土也，在掌后两筋间陷中，手厥阴脉之所注也，为腧。治热病汗不出，臂挛腋肿，善笑不休，心悬若饥，喜悲泣惊恐，目赤，小便如血，呕逆，狂言不乐，喉痹口干，身热头痛，短气胸胁痛。针入五分，可灸三壮。", "白话": "“太陵二穴，属土，在掌后两筋间凹陷中，是手厥阴脉气所注之处，为输穴。治热病汗不出、臂挛腋肿、善笑不休、心悬如饥、喜悲泣惊恐、目赤、小便如血、呕逆、狂言不乐、喉痹口干、身热头痛、短气胸胁痛。针入五分，可灸三壮。”"}, {"source": "条226｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“外陵二穴，在天枢下一寸，足阳明脉气所发。治腹中痛，心如悬，下引脐腹痛，可灸五壮，针入三分。", "白话": "“外陵二穴，在天枢下一寸，是足阳明脉气所发。治腹中痛，心如悬（空），下引脐腹痛。可灸五壮，针入三分。”"}, {"source": "条227｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“蠡沟二穴，在足内踝上五寸，别走少阳，足厥阴络，治卒疝，少腹肿，时少腹暴痛，小便不利如癃闭，数噫恐悸，少气不足，腹中痛，悒悒不乐，咽中闷如有息肉状，背拘急不可俯仰，针入二分，留三呼，可灸三壮。", "白话": "“蠡沟二穴，在足内踝上五寸，别走少阳，是足厥阴络穴。治卒疝、少腹肿、时少腹暴痛、小便不利如癃闭、频噫恐悸、少气不足、腹中痛、悒悒不乐、咽中闷如有息肉状、背拘急不能俯仰。针入二分，留三呼，可灸三壮。”"}, {"source": "条228｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“阴郄二穴，在掌后脉中，去腕五分。治失喑不能言，洒淅振寒，厥逆心痛，霍乱胸中满，衄血惊恐，针入三分，可灸七壮。", "白话": "“阴郄二穴，在掌后脉中，离腕五分。治失音不能言、洒淅寒战、厥逆心痛、霍乱胸中满、衄血惊恐。针入三分，可灸七壮。”"}, {"source": "条229｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“少冲二穴，木也，一名经始，在手小指内廉之端，去爪甲角如韭叶，手少阴脉之所出也，为井。治热病烦满，上气心痛，痰冷少气，悲恐善惊，掌中热，胸中痛，口中热，咽中酸，乍寒乍热，手挛不伸，引肘腋痛，针入一分，可灸三壮。", "白话": "“少冲二穴，属木，又名经始，在手小指内侧端，离爪甲角如韭叶宽处，是手少阴脉气所出之处，为井穴。治热病烦满、上气心痛、痰冷少气、悲恐善惊、掌中热、胸中痛、口中热、咽中酸、忽冷忽热、手挛不伸、牵引肘腋痛。针入一分，可灸三壮。”"}, {"source": "条230｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“神庭一穴，在鼻直入发际五分。督脉、足太阳、阳明三脉之会。治癫疾风痫，戴目上视，不识人，头风目眩，鼻出清涕不止，惊悸不得安寝。可灸二七壮，至七七壮止。岐伯曰：凡欲疗风，勿令灸多，缘风性轻，多即伤，惟唯宜灸一壮，至三七壮止，禁不可针，针即发狂。", "白话": "“神庭一穴，在鼻直上入发际五分。是督脉、足太阳、阳明三脉之会。治癫疾风痫、戴眼上视、不识人、头风目眩、鼻流清涕不止、惊悸不得安睡。可灸二七（十四）壮，至七七（四十九）壮为止。岐伯说：凡要治风，勿令灸多，因为风性轻扬，灸多即伤（正）；只宜灸一壮至三七（二十一）壮为止；禁不可针，针之即发狂。”"}, {"source": "条231｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“百会一穴，一名三阳五会，在前顶后一寸五分，顶中央旋毛中，可容豆，督脉、足太阳交会于巅颠上。治小儿脱肛久不差，风痫中风，角弓反张，或多哭，言语不择，发即无时，盛即吐沫，心烦惊悸健忘，痎疟，耳鸣耳聋，鼻塞不闻香臭，针入二分，得气即泻。可灸七壮，至七七壮即止，唐秦鸣鹤刺微出血，头痛立愈。凡灸头项，不过七七壮，缘头顶皮肤浅薄，灸不宜多。", "白话": "“百会一穴，又名三阳五会，在前顶后一寸五分，头顶中央旋毛中，可容豆大，是督脉、足太阳交会于巅顶之上。治小儿脱肛久不愈、风痫中风、角弓反张、或多哭、言语失序、发作无定时、病甚即吐沫、心烦惊悸健忘、痎疟、耳鸣耳聋、鼻塞不闻香臭。针入二分，得气即泻。可灸七壮至七七壮即止；唐代秦鸣鹤刺微出血，头痛立愈。凡灸头项不过七七壮，因为头顶皮肤浅薄，灸不宜多。”"}, {"source": "条232｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“上脘一穴，在巨阙下一寸，当一寸五分，去蔽骨三寸，任脉、足阳明、手太阳之会。治心中热烦，贲豚气胀不能食，霍乱吐利，身热汗不出，三虫多涎，心风惊悸，心痛不可忍，伏梁气状如覆杯。针入八分，先补后泻之，神验。如风痫热病，宜先泻后补，其疾立愈。灸亦良，日可灸二七壮至一百壮，未愈更倍之。", "白话": "“上脘一穴，在巨阙下一寸，当（原稿作‘当一寸五分’），离蔽骨三寸，是任脉、足阳明、手太阳之会。治心中热烦、贲豚气胀不能食、霍乱吐利、身热汗不出、三虫多涎、心风惊悸、心痛不可忍、伏梁气形如覆杯。针入八分，先补后泻，神验。如风痫热病，宜先泻后补，其病立愈。灸也好，每日可灸二七壮至一百壮，未愈加倍再灸。”"}, {"source": "条233｜《圣济总录·针灸门》", "原文": "《圣济总录·针灸门》：“巨阙一穴，心之募也。在鸠尾下一寸。人有鸠尾短者，少饶分寸，任脉气所发。治心中烦满，热病胸中痰饮，腹胀暴痛，恍惚不知人，息贲时唾血，蛔虫心痛，蛊毒霍乱，发狂不识人，惊悸少气，针入六分，留七呼，得气即泻。灸亦良，可灸七壮，至七七壮止。", "白话": "“巨阙一穴，是心的募穴。在鸠尾下一寸。人有鸠尾骨短的，须酌减分寸，是任脉气所发。治心中烦满、热病胸中痰饮、腹胀暴痛、恍惚不省人事、息贲时唾血、蛔虫心痛、蛊毒霍乱、发狂不识人、惊悸少气。针入六分，留七呼，得气即泻。灸也好，可灸七壮至七七壮止。”"}, {"source": "条234｜《针法灸法》卷下", "原文": "《针法灸法》卷下：“液门为荥次陷中，惊悸痫热共头痛。", "白话": "“液门是荥穴，在（小指）次指间凹陷中；（主治）惊悸、痫证、热病与头痛。”"}, {"source": "条235｜《针法灸法》卷下", "原文": "《针法灸法》卷下：“天井为合肘外寻，风痹筋挛及骨疼，咳嗽不食并惊悸，心胸气上即时针。", "白话": "“天井是合穴，向肘外寻找；（主治）风痹筋挛与骨疼，咳嗽不食并惊悸，心胸气上冲即时针刺。”"}, {"source": "条236｜《针法灸法》卷下", "原文": "《针法灸法》卷下：“间使心经掌后间，心痛呕逆恶风寒，热时咽痛并惊悸，神针和忤也须安。", "白话": "“间使在掌后两筋间（原稿作‘间使心经掌后间’）；（主治）心痛呕逆恶风寒，热时咽痛并惊悸，神针刺之邪忤也须安。”"}, {"source": "条237｜《针灸资生经》卷一", "原文": "《针灸资生经》卷一：“有云：人身有四穴最急应。四百四病皆能治之。百会盖其一也。因灸此穴而心气愈。后阅灸经，此穴果主心烦、惊悸、健忘、无心力、自是间或灸之，百病皆主，不特治此数疾而已也一名天满。", "白话": "“有书说：人身有四个穴位最能应急，四百四种病都能治疗，百会大概是其中之一。因灸此穴而心气之病得愈。后来阅读灸经，此穴果然主治心烦、惊悸、健忘、无心力；从此间或灸之，百病都主，不只治这几种病而已。一名天满。”"}, {"source": "条238｜《针灸资生经》卷三", "原文": "《针灸资生经》卷三：“蠡沟，治卒疝。小腹肿。时小腹暴痛。小便不利如癃闭，数噫恐悸。少气不足。腹痛，悒悒不乐，咽中闷如有息肉，背拘急不可俛俯仰。", "白话": "“蠡沟，治卒疝。小腹肿。时少腹暴痛。小便不利如癃闭，频噫恐悸。少气不足。腹痛，悒悒不乐，咽中闷如有息肉，背拘急不能俯仰。”"}, {"source": "条239｜《针灸资生经》卷三", "原文": "《针灸资生经》卷三：“大钟，治实则小便淋闭，洒洒腰脊强痛。大便秘涩。嗜卧口中热。虚则呕逆多寒，欲闭户而处，少气不足，胸胀喘息，舌干，咽中食噎不得下，善惊恐不乐，喉鸣咳唾血。", "白话": "“大钟，治实证则小便淋沥闭塞、洒淅腰脊强痛、大便秘涩、嗜卧口中热；虚证则呕逆多寒、想闭门独处、少气不足、胸胀喘息、舌干、咽中食物噎塞不能下、善惊恐不乐、喉鸣咳嗽唾血。”"}, {"source": "条240｜《针灸资生经》卷三", "原文": "《针灸资生经》卷三：“蠡沟，主数噫，恐悸，气不足。", "白话": "“蠡沟，主治频作嗳气、恐惧心悸、气不足。”"}, {"source": "条241｜《针灸资生经》卷三", "原文": "《针灸资生经》卷三：“神门：治数噫恐悸。", "白话": "“神门：治频作嗳气、恐惧心悸。”"}, {"source": "条242｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“然谷：主心如悬，少气不足以息。", "白话": "“然谷：主治心如悬（空），少气不足以息。”"}, {"source": "条243｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“通里：主卒痛烦心，心中懊侬，数欠频伸，心下悸，悲恐。", "白话": "“通里：主治突然心痛心烦，心中懊侬，频呵欠伸懒腰，心下悸，悲伤恐惧。”"}, {"source": "条244｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“外陵：治心如悬下痛见腹痛。", "白话": "“外陵：治心如悬空下痛（详见‘腹痛’门）。”"}, {"source": "条245｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“郄门治心痛衄血，呕哕，惊恐畏人，神气不足。", "白话": "“郄门治心痛、衄血、呕呃、惊恐怕见人、神气不足。”"}, {"source": "条246｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“心俞、天井、神道《明上下》同：治悲愁恍惚《千》见悲愁。狂惊恍惚，灸足阳明。", "白话": "“心俞、天井、神道（《明上下》同）：治悲愁恍惚（《千金》另见‘悲愁’门）。狂而惊惕恍惚，灸足阳明（经穴）。”"}, {"source": "条247｜《明上下》（条246 引文内所引）", "原文": "《明上下》同：治悲愁恍惚", "白话": "“《明堂上经》《明堂下经》同：治悲愁恍惚。”"}, {"source": "条248｜《千》（条246 引文内所引）", "原文": "《千》见悲愁。", "白话": "“《千金要方》另见‘悲愁’门（互见语）。”"}, {"source": "条249｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“少冲：治悲恐善惊见伤寒。", "白话": "“少冲：治悲伤恐惧、容易受惊（详见‘伤寒’门）。”"}, {"source": "条250｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“上管：治心风惊悸。《明》同作心忪。", "白话": "“上管：治心风惊悸。《明堂经》同（此条），文字作‘心忪’。”"}, {"source": "条251｜《明》（条250 引文内所引）", "原文": "《明》同作心忪。", "白话": "“《明堂经》同载，文字作‘心忪’。”"}, {"source": "条252｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“巨阙：治惊悸少气见狂。", "白话": "“巨阙：治惊悸少气（详见‘狂’门）。”"}, {"source": "条253｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“《明下》云：间使：疗惊悸见伤寒无汗。", "白话": "“《明堂下经》说：间使：疗惊悸（详见‘伤寒无汗’处）。”"}, {"source": "条254｜《明下》（条253 引文内所引）", "原文": "《明下》云：间使：疗惊悸见伤寒无汗。", "白话": "“《明堂下经》说：间使：疗惊悸（详见‘伤寒无汗’处）。”"}, {"source": "条255｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“百会见风痫、神道见头痛、天井见风痹、液门见狂：治惊悸。", "白话": "“百会（详见‘风痫’门）、神道（详见‘头痛’门）、天井（详见‘风痹’门）、液门（详见‘狂’门）：治惊悸。”"}, {"source": "条256｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“支正：治风虚惊恐狂惕，《明下》云：疗惊恐悲愁。", "白话": "“支正：治风虚惊恐狂惕，《明堂下经》说：疗惊恐悲愁。”"}, {"source": "条257｜《明下》（条256 引文内所引）", "原文": "《明下》云：疗惊恐悲愁。", "白话": "“《明堂下经》说：疗惊恐悲愁。”"}, {"source": "条258｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“神庭：治惊悸不得安寝《铜》。", "白话": "“神庭：治惊悸不得安睡（《铜人经》同载）。”"}, {"source": "条259｜《铜》（条258 引文内所引）", "原文": "《铜》。", "白话": "“（《铜人经》同载此条，校记）。”"}, {"source": "条260｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“脑空：治脑风头痛，目瞑心悸。", "白话": "“脑空：治脑风头痛，闭目心悸。”"}, {"source": "条261｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“曲泽、大陵：主心下澹澹喜惊《甲》作内关。", "白话": "“曲泽、大陵：主治心下澹澹、容易受惊（《甲乙经》作内关）。”"}, {"source": "条262｜《甲》（条261 引文内所引）", "原文": "《甲》作内关。", "白话": "“《甲乙经》作‘内关’（异文校记）。”"}, {"source": "条263｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“通里：主心下悸，《明下》云：疗悲恐畏人。", "白话": "“通里：主治心下悸，《明堂下经》说：疗悲恐怕见人。”"}, {"source": "条264｜《明下》（条263 引文内所引）", "原文": "《明下》云：疗悲恐畏人。", "白话": "“《明堂下经》说：疗悲恐怕见人。”"}, {"source": "条265｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“然谷《铜》同、阳陵泉《明》同：主心下惕恐，如人将捕之。", "白话": "“然谷（《铜人经》同）、阳陵泉（《明堂经》同）：主治心下惕恐，如有人将抓捕自己。”"}, {"source": "条266｜《铜》（条265 引文内所引）", "原文": "然谷《铜》同", "白话": "“然谷（《铜人经》同载）”"}, {"source": "条267｜《明》（条265 引文内所引）", "原文": "阳陵泉《明》同", "白话": "“阳陵泉（《明堂经》同载）”"}, {"source": "条268｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“少府，主数噫恐悸气不足。", "白话": "“少府，主治频作嗳气、恐惧心悸、气不足。”"}, {"source": "条269｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“神门，主数噫恐悸不足。", "白话": "“神门，主治频作嗳气、恐惧心悸、（正气）不足。”"}, {"source": "条270｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“巨阙主惊悸少气。", "白话": "“巨阙主治惊悸少气。”"}, {"source": "条271｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“风府：疗多悲恐惊悸《千》。", "白话": "“风府：疗多悲、恐惧、惊悸（《千金》）。”"}, {"source": "条272｜《千》（条271 引文内所引）", "原文": "《千》。", "白话": "“（此条出《千金要方》，校记）。”"}, {"source": "条273｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“鸠尾：疗心惊悸，神气耗散，儿睡中惊，目不合：灸屈肘横文中上三分，各一壮。", "白话": "“鸠尾：疗心惊悸、神气耗散，小儿睡中惊惕、目不合：灸屈肘横纹中上三分处，各一壮。”"}, {"source": "条274｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“上管：疗惊悸《明》见心烦。", "白话": "“上管：疗惊悸（《明堂经》另见‘心烦’门）。”"}, {"source": "条275｜《明》（条274 引文内所引）", "原文": "《明》见心烦。", "白话": "“《明堂经》另见‘心烦’门（互见语）。”"}, {"source": "条276｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“天井：疗惊悸《明下》见悲。", "白话": "“天井：疗惊悸（《明堂下经》另见‘悲’门）。”"}, {"source": "条277｜《明下》（条276 引文内所引）", "原文": "《明下》见悲。", "白话": "“《明堂下经》另见‘悲’门（互见语）。”"}, {"source": "条278｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“彧中等：主悸坐不安席《千》见上气。", "白话": "“彧中等穴：主治心悸坐不安席（《千金》另见‘上气’门）。”"}, {"source": "条279｜《千》（条278 引文内所引）", "原文": "《千》见上气。", "白话": "“《千金要方》另见‘上气’门（互见语）。”"}, {"source": "条280｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“百会治中风心烦，惊悸健忘《铜》。", "白话": "“百会治中风心烦、惊悸健忘（《铜人经》同载）。”"}, {"source": "条281｜《铜》（条280 引文内所引）", "原文": "《铜》。", "白话": "“（《铜人经》同载此条，校记）。”"}, {"source": "条282｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“惊怖心忪少力：灸大横五十壮。", "白话": "“惊恐心忪、少力：灸大横五十壮。”"}, {"source": "条283｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“予旧患心气，凡思虑过多，心下怔忪，或至自悲感慨，必灸百会。", "白话": "“我旧患心气之病，凡思虑过多，就心下怔忪，甚至自悲感慨，必灸百会。”"}, {"source": "条284｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“天井主大风默默，不知所痛，悲伤不乐。《明下》云：疗惊悸悲伤。", "白话": "“天井主治大风沉默不语、不知痛处、悲伤不乐。《明堂下经》说：疗惊悸悲伤。”"}, {"source": "条285｜《明下》（条284 引文内所引）", "原文": "《明下》云：疗惊悸悲伤。", "白话": "“《明堂下经》说：疗惊悸悲伤。”"}, {"source": "条286｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“通里见心痛主悸悲。", "白话": "“通里（详见‘心痛’门）主心悸悲伤。”"}, {"source": "条287｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“神门治疟，心烦甚，欲得饮冷，恶寒则欲处温中，咽干不嗜食，心痛数噫，恐悸，少气不足，手臂寒，喘逆身热，狂悲哭，呕血遗溺《铜》。", "白话": "“神门治疟：心烦甚，想饮冷水；恶寒则想处于温处；咽干不欲食，心痛频噫，恐惧心悸，少气不足，手臂寒，喘逆身热，狂而悲哭，呕血遗尿（《铜人经》同载）。”"}, {"source": "条288｜《铜》（条287 引文内所引）", "原文": "《铜》。", "白话": "“（《铜人经》同载此条，校记）。”"}, {"source": "条289｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“上管：疗心风惊悸《铜》同，不能食，心中闷发哕。", "白话": "“上管：疗心风惊悸（《铜人经》同载），不能食，心中闷发呃逆。”"}, {"source": "条290｜《铜》（条289 引文内所引）", "原文": "《铜》同", "白话": "“（《铜人经》同载）”"}, {"source": "条291｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“曲泽疗心痛出血，则心下澹澹，喜惊，身热烦心，口干，逆气唾血，肘瘛疭，喜摇头，清汗出不过肩。", "白话": "“曲泽疗心痛出血（之证）：则心下澹澹、容易受惊、身热心烦、口干、逆气唾血、肘部抽搐、喜摇头、清冷汗出不过肩。”"}, {"source": "条292｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“神庭：治惊悸不得安寝《铜》。", "白话": "“神庭：治惊悸不得安睡（《铜人经》同载）。”"}, {"source": "条293｜《铜》（条292 引文内所引）", "原文": "《铜》。", "白话": "“（《铜人经》同载此条，校记）。”"}, {"source": "条294｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“神庭：疗风痫惊悸，不得安寝《明》见癫痫。", "白话": "“神庭：疗风痫惊悸、不得安睡（《明堂经》另见‘癫痫’门）。”"}, {"source": "条295｜《明》（条294 引文内所引）", "原文": "《明》见癫痫。", "白话": "“《明堂经》另见‘癫痫’门（互见语）。”"}, {"source": "条296｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“间使治卒强，胸中澹澹，恶风寒，呕吐，怵惕，寒中少气，掌热腋肿，肘挛。", "白话": "“间使治突然强急（原稿作‘卒强’），胸中悸动不安，恶风寒，呕吐，怵惕，寒中少气，掌热腋肿，肘挛。”"}, {"source": "条297｜《明下》", "原文": "《明下》云：疗卒狂惊悸。", "白话": "《明堂下经》说：治疗突发狂乱、惊悸。"}, {"source": "条298｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“巨阙治发狂不识人，惊悸少气。", "白话": "《针灸资生经》卷四说：“巨阙穴治疗发狂不识人、惊悸、气少。”"}, {"source": "条299｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“液门治惊悸妄言。", "白话": "《针灸资生经》卷四说：“液门穴治疗惊悸、妄言。”"}, {"source": "条300｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“神庭疗肿气风痫，癫风不识人，羊鸣，角弓反张，披发而上歌下哭，多学人语，惊悸不安寝。", "白话": "《针灸资生经》卷四说：“神庭穴治疗肿气、风痫、癫风不识人、发出羊叫、角弓反张、披发而上歌下哭、多学人说话、惊悸不得安睡。”"}, {"source": "条301｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“通谷主心中愦愦，数欠，癫，心下悸恐，咽中澹澹。", "白话": "《针灸资生经》卷四说：“通谷穴主治心中昏乱不爽、频频呵欠、癫病、心下悸动恐惧、咽中澹澹不宁。”"}, {"source": "条302｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“百会疗风痫，青风心风，角弓反张，羊鸣，多哭，言语不择，发时即死，吐沫心热闷，头风，多睡心烦，惊悸无心力，忘前失后，食无味，头重饮酒而赤鼻塞。", "白话": "《针灸资生经》卷四说：“百会穴治疗风痫、青风、心风、角弓反张、羊鸣、多哭、说话不择（言语失次）、发作时即如死状、吐涎沫、心热烦闷、头风、多睡心烦、惊悸而无心力（精神不支）、忘前失后、饮食无味、头重、饮酒则面赤、鼻塞。”"}, {"source": "条303｜《明下》", "原文": "《明下》云：疗登高而歌，弃衣而走，角弓反张，羊痫吐舌。", "白话": "《明堂下经》说：（百会又）治疗登高而歌、弃衣而走、角弓反张、羊痫吐舌。"}, {"source": "条304｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“百会治风痫，中风，角弓反张，或多哭，言语不择，发即无时，盛即吐沫，心烦惊悸", "白话": "《针灸资生经》卷四说：“百会穴治疗风痫、中风、角弓反张，或多哭、说话不择、发作没有定时，病势盛时即吐涎沫、心烦惊悸。”"}, {"source": "条305｜《铜》", "原文": "《铜》。", "白话": "《铜人腧穴针灸图经》（亦载此条）。"}, {"source": "条306｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“前顶治小儿惊痫风痫", "白话": "《针灸资生经》卷四说：“前顶穴治疗小儿惊痫、风痫。”"}, {"source": "条307｜《铜》", "原文": "《铜》见癫痫。小儿发逆上，啼笑，面暗色不变，是痫候。或鼻口青时小惊，或目闭青时小惊，或身热头常汗出，或身热吐莔而喘，或身热目时直视，或卧惕惕而惊，手足振摇，或卧梦笑，手足动摇，或意气下而妄怒，或咽乳不利，或目瞳子卒大黑于常，或喜欠、目上视，或身热小便难，或身热目视不精，或吐痢不止，厥痛时起，或弄舌摇头。诸候二十条，皆痫之初也。见其候，便爪其阳脉所应灸，爪之皆重手，令儿骤啼，及足绝脉，亦依方与汤。", "白话": "《铜人腧穴针灸图经》（相关文字）见于癫痫门。小儿发作时气逆上冲、啼哭无常或发笑，面色暗而颜色不变，这是痫的征候。或者鼻口发青时时轻微惊惕，或者闭目时面色青而轻微受惊，或者身热而头部常出汗，或者身热吐奶而喘，或者身热而两眼时时直视，或者睡卧惊惕而惊、手足振摇，或者睡中发笑、手足摇动，或者意气下沉而无故发怒，或者咽乳不利，或者目瞳突然比平常大而黑，或者多呵欠、目上视，或者身热小便难，或者身热而视物不清，或者吐泻不止、厥冷腹痛时起，或者弄舌摇头。这各种征候共二十条，都是痫病初起的表"}, {"source": "条308｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“天井治惊悸瘛疭，风痹，臂肘痛，捉物不得", "白话": "《针灸资生经》卷四说：“天井穴治疗惊悸、瘛疭、风痹、臂肘疼痛、拿不住东西。”"}, {"source": "条309｜《铜》", "原文": "《铜》。", "白话": "《铜人腧穴针灸图经》（亦载此条）。"}, {"source": "条310｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“百会治风痫，中风，角弓反张，或多哭，言语不择，发即无时，盛即吐沫，心烦惊悸", "白话": "《针灸资生经》卷四说：“百会穴治疗风痫、中风、角弓反张，或多哭、说话不择、发作没有定时，病势盛时即吐涎沫、心烦惊悸。”"}, {"source": "条311｜《铜》", "原文": "《铜》。", "白话": "《铜人腧穴针灸图经》（亦载此条）。"}, {"source": "条312｜《针灸资生经》卷四", "原文": "《针灸资生经》卷四：“外陵：治腹痛心如悬，下引脐腹痛。", "白话": "《针灸资生经》卷四说：“外陵穴：治疗腹痛、心如悬空感，向下牵引脐腹作痛。”"}, {"source": "条313｜《针灸资生经》卷六", "原文": "《针灸资生经》卷六：“神道治寒", "白话": "《针灸资生经》卷六说：“神道穴治疗寒（《明堂下经》作‘身’）……”"}, {"source": "条314｜《明下》", "原文": "《明下》作身。热头痛，进退痃疟，恍惚悲愁", "白话": "《明堂下经》作“身”字。（治）发热头痛、往来进退的痃疟、精神恍惚悲伤忧愁。"}, {"source": "条315｜《明》", "原文": "《明》，健忘惊悸。", "白话": "《明堂经》（异文略），并治健忘、惊悸。"}, {"source": "条316｜《针灸资生经》卷六", "原文": "《针灸资生经》卷六：“脑空治脑风头痛不可忍，目瞑，心悸，发即为癫。", "白话": "《针灸资生经》卷六说：“脑空穴治疗脑风头痛不可忍受、闭目不欲开、心悸，发作即成癫病。”"}, {"source": "条317｜《针灸资生经》卷七", "原文": "《针灸资生经》卷七：“通里治热病，卒心中懊憹，数欠频伸，悲恐，目眩头痛，面赤而热，心悸，肘臂臑痛，实则肢肿，虚则不能言，若呕，喉痹少气遗溺", "白话": "《针灸资生经》卷七说：“通里穴治疗热病、突发心中懊憹不宁、频频呵欠伸懒腰、悲伤恐惧、目眩头痛、面赤而热、心悸、肘臂臑部疼痛；邪实则肢体浮肿，正虚则不能说话，或呕吐、喉痹、气少、遗尿。”"}, {"source": "条318｜《铜》", "原文": "《铜》。", "白话": "《铜人腧穴针灸图经》（亦载此条）。"}, {"source": "条319｜《针灸资生经》卷七", "原文": "《针灸资生经》卷七：“少冲治热病烦满，上气心痛，痰冷少气，悲恐善", "白话": "《针灸资生经》卷七说：“少冲穴治疗热病烦满、上气心痛、痰冷气少、悲伤恐惧而善（《明》作‘善喜惊’）……”"}, {"source": "条320｜《明》", "原文": "《明》作喜惊，掌热胸痛，口热咽痠酸，乍寒乍热，手挛不伸，引腋痛", "白话": "《明堂经》作“喜惊”。（并治）掌中发热、胸痛、口热、咽中酸楚、忽冷忽热、手指拘挛不能伸、牵引腋下疼痛。"}, {"source": "条321｜《铜》", "原文": "《铜》。", "白话": "《铜人腧穴针灸图经》（亦载此条）。"}, {"source": "条322｜《针灸资生经》卷七", "原文": "《针灸资生经》卷七：“甲云：主心澹善惊，身热烦心，口干手清，逆气呕唾，肘瘛，善摇头，颜青，汗出不过眉。", "白话": "《针灸资生经》卷七说：“《甲乙经》说：主治心澹澹不宁而善惊、身热心烦、口干手冷、气逆呕唾、肘部抽搐、多摇头、面色青、汗出不超过眉毛。”"}, {"source": "条323｜《针灸资生经》卷七", "原文": "《针灸资生经》卷七：“太陵治热病汗不出，臂挛腋肿，善笑不休，心悬若饥，喜悲泣，惊恐，目赤，小便如血，呕逆，狂言不乐。", "白话": "《针灸资生经》卷七说：“太陵（大陵）穴治疗热病汗不出、臂拘挛腋下肿、喜笑不止、心悬若饥、容易悲伤哭泣、惊恐、目赤、小便色如血、呕逆、狂言而不乐。”"}, {"source": "条324｜《扁鹊神应针灸玉龙经》一百二十穴玉龙歌", "原文": "《扁鹊神应针灸玉龙经》一百二十穴玉龙歌：“连月虚烦面赤妆，心中惊恐亦难当。通里心原真妙穴，神针一刺便安康。", "白话": "《扁鹊神应针灸玉龙经》“一百二十穴玉龙歌”说：“连月虚烦、面如涂妆色赤，心中惊恐也难以承当。通里是心经源头的真正妙穴，神针一刺便得安康。”"}, {"source": "条325｜《扁鹊神应针灸玉龙经》天星十一穴歌诀", "原文": "《扁鹊神应针灸玉龙经》天星十一穴歌诀：“通里腕侧后，度量一寸中，善呻并数欠，懊憹及心忪。", "白话": "《扁鹊神应针灸玉龙经》“天星十一穴歌诀”说：“通里在腕侧後，度量一寸之中；（主）多呻吟并频频呵欠，心中懊憹及心忪（心悸）。”"}, {"source": "条326｜《扁鹊神应针灸玉龙经》六十六穴治证", "原文": "《扁鹊神应针灸玉龙经》六十六穴治证：“通里，别走太阳，在腕上后一寸。治心惊怔忡，烦闷，腹胀减食，头面赤，四肢不遂，痠酸痛，气不和。", "白话": "《扁鹊神应针灸玉龙经》“六十六穴治证”说：“通里（络穴）别走太阳（小肠经），在腕上后一寸。治疗心惊怔忡、烦闷、腹胀纳减、头面红赤、四肢不遂、酸楚作痛、气机不和。”"}, {"source": "条327｜《扁鹊神应针灸玉龙经》六十六穴治证", "原文": "《扁鹊神应针灸玉龙经》六十六穴治证：“支正，别走太阳。在腕后五寸，去养老穴四寸。治五劳七伤，四肢虚乏，惊恐，肘挛指痛。", "白话": "《扁鹊神应针灸玉龙经》“六十六穴治证”说：“支正（络穴）别走太阳（小肠经），在腕后五寸，距养老穴四寸。治疗五劳七伤、四肢虚弱乏力、惊恐、肘部拘挛指痛。”"}, {"source": "条328｜《扁鹊神应针灸玉龙经》六十六穴治证", "原文": "《扁鹊神应针灸玉龙经》六十六穴治证：“间使，为经金。在掌后三寸，两筋间陷中。治癫发狂，疟生寒热，心疼惊悸，呕逆胸满，咽痛、臂疼。", "白话": "《扁鹊神应针灸玉龙经》“六十六穴治证”说：“间使为经金（五输之经穴，属金），在掌后三寸、两筋间凹陷中。治疗癫病发狂、疟疾寒热、心痛惊悸、呕逆胸满、咽痛、臂疼。”"}, {"source": "条329｜《扁鹊神应针灸玉龙经》六十六穴治证", "原文": "《扁鹊神应针灸玉龙经》六十六穴治证：“曲泽，为合水。在肘内廉陷中，屈肘取之。治心痛呕血，胸满口干，肘臂筋挛。郄门，手厥阴郄。去腕五寸。治神气不足，惊恐畏人，心痛，呕血，鼻衄。", "白话": "《扁鹊神应针灸玉龙经》“六十六穴治证”说：“曲泽为合水（合穴属水），在肘内侧凹陷中，屈肘取穴。治疗心痛呕血、胸满口干、肘臂筋脉拘挛。郄门是手厥阴的郄穴，距腕五寸。治疗神气不足、惊恐怕见人、心痛、呕血、鼻出血。”"}, {"source": "条330｜《扁鹊神应针灸玉龙经》六十六穴治证", "原文": "《扁鹊神应针灸玉龙经》六十六穴治证：“液门，为荥水。在小指次指间陷中，握拳取。治五痫，惊悸，头痛目赤，齿出血，手臂肿痛。", "白话": "《扁鹊神应针灸玉龙经》“六十六穴治证”说：“液门为荥水（荥穴属水），在小指与次指之间凹陷中，握拳取穴。治疗五痫、惊悸、头痛目赤、齿龈出血、手臂肿痛。”"}, {"source": "条331｜《扁鹊神应针灸玉龙经》六十六穴治证", "原文": "《扁鹊神应针灸玉龙经》六十六穴治证：“天井，为合土。在肘后大骨一寸两筋骨间。叉手按膝上取。治五噎十膈，翻胃吐食，风痹，筋挛骨痛，咳嗽上气，心疼惊悸，小腹胀疼，及羊痫。", "白话": "《扁鹊神应针灸玉龙经》“六十六穴治证”说：“天井为合土（合穴属土），在肘后大骨下一寸、两筋骨之间；两手交叉按膝上取穴。治疗五噎十膈、翻胃吐食、风痹、筋挛骨痛、咳嗽上气、心痛惊悸、小腹胀痛，以及羊痫。”"}, {"source": "条332｜《扁鹊神应针灸玉龙经》六十六穴治证", "原文": "《扁鹊神应针灸玉龙经》六十六穴治证：“神门，为俞土。在掌后兑骨端。治疟恶寒，发热，咽干，身热，狂言，胸满，腹痛，减食，心惊，少气，喘嗽、唾红，吐血，遗尿，手臂难举，五痫之疾。", "白话": "《扁鹊神应针灸玉龙经》“六十六穴治证”说：“神门为俞土（输穴属土），在掌后兑骨（豌豆骨）端。治疗疟疾恶寒发热、咽干、身热、狂言、胸满、腹痛、纳减、心惊、气少、喘咳、唾红、吐血、遗尿、手臂难举、五痫之疾。”"}, {"source": "条333｜《扁鹊神应针灸玉龙经》针灸歌", "原文": "《扁鹊神应针灸玉龙经》针灸歌：“心悸怔忡多健忘，顶心百会保安康。", "白话": "《扁鹊神应针灸玉龙经》“针灸歌”说：“心悸怔忡又多健忘的，取头顶心的百会穴可保安康。”"}, {"source": "条334｜《黄帝明堂灸经》卷上", "原文": "《黄帝明堂灸经》卷上：“少冲，二穴，在手小指内廉之侧，去爪甲如韭叶。灸三壮。主烦心上气，卒心痛，悲恐畏人，善惊，手拳不得伸，掌中热痛也。", "白话": "《黄帝明堂灸经》卷上说：“少冲二穴，在手小指内侧边缘，距爪甲角如一韭叶宽。灸三壮。主治心烦上气、突发心痛、悲伤恐惧怕见人、容易受惊、手握拳不能伸开、掌中热痛。”"}, {"source": "条335｜《黄帝明堂灸经》卷上", "原文": "《黄帝明堂灸经》卷上：“间使，二穴，在掌后三寸两筋间陷者中。灸七壮。主卒狂惊悸，臂中肿痛，屈伸难。岐伯云：主鬼神邪也。", "白话": "《黄帝明堂灸经》卷上说：“间使二穴，在掌后三寸、两筋间凹陷中。灸七壮。主治突发狂乱惊悸、臂中肿痛、屈伸困难。岐伯说：主治鬼神邪气（之疾）。”"}, {"source": "条336｜《黄帝明堂灸经》卷上", "原文": "《黄帝明堂灸经》卷上：“上管，一穴，在巨阙下一寸，灸三壮。主呕吐，食饮不下，腹胀气满，心忪惊悸，时吐呕血，腹●刺痛，痰多吐涎也。", "白话": "《黄帝明堂灸经》卷上说：“上管（上脘）一穴，在巨阙下一寸，灸三壮。主治呕吐、饮食不下、腹胀气满、心忪惊悸、时时吐血、腹中刺痛、痰多吐涎。”"}, {"source": "条337｜《黄帝明堂灸经》卷上", "原文": "《黄帝明堂灸经》卷上：“鸠尾，一穴，在蔽骨下五分陷者中。灸三壮。主心惊悸，神气耗散，癫痫病狂，歌不择言也。", "白话": "《黄帝明堂灸经》卷上说：“鸠尾一穴，在蔽骨（胸骨剑突）下五分凹陷中。灸三壮。主治心惊悸、神气耗散、癫痫发狂、唱歌般言语不择。”"}, {"source": "条338｜《黄帝明堂灸经》卷中", "原文": "《黄帝明堂灸经》卷中：“京骨，二穴，在足外侧大骨下，白肉际陷者中。灸五壮。主寒疟寒热，善惊悸，不欲食，腿膝胫痿，脚挛不得伸，癫病狂走，善自啮，及膝胫寒也。", "白话": "《黄帝明堂灸经》卷中说：“京骨二穴，在足外侧大骨（第五跖骨粗隆）下、赤白肉际凹陷中。灸五壮。主治寒疟寒热、容易惊悸、不欲饮食、腿膝胫部痿软、脚拘挛不能伸、癫病狂走、常自咬（唇舌），以及膝胫发冷。”"}, {"source": "条339｜《西方子明堂灸经》卷一", "原文": "《西方子明堂灸经》卷一：“神庭，在发际直鼻上，督脉上一夫发际。灸二七壮至百壮。主肿气，风痫，癫风不识人，羊鸣，角弓反张，披发而上歌下哭，多学人言语，惊悸不得安寝，头痛，喘喝，目不可视，目泣出，鼻清涕出。", "白话": "《西方子明堂灸经》卷一说：“神庭在发际正对鼻直上，督脉上入发际一夫（三寸）处。灸二七壮（十四壮）至百壮。主治肿气、风痫、癫风不识人、羊鸣、角弓反张、披发而上歌下哭、多学人说话、惊悸不得安睡、头痛、喘喝、目不能视、流泪、流清鼻涕。”"}, {"source": "条340｜《西方子明堂灸经》卷一", "原文": "《西方子明堂灸经》卷一：“彧中二穴，在腧府下一寸六分，陷中。仰卧取之。灸五壮。主胸胁支满，咳逆、喘不能食饮，上气，涎出多唾，呼吸喘悸，坐不安席。", "白话": "《西方子明堂灸经》卷一说：“彧中二穴，在腧府（俞府）下一寸六分凹陷中，仰卧取穴。灸五壮。主治胸胁胀满、咳逆、喘而不能食饮、上气、涎唾多、呼吸喘悸、坐不安席。”"}, {"source": "条341｜《西方子明堂灸经》卷一", "原文": "《西方子明堂灸经》卷一：“通谷二穴，在幽门下一寸，灸五壮。主头痛寒热，汗出不恶寒。主项如拔不可左右顾，目䀮䀮不明。风寒及鼻鼽清涕出，及结积留饮癖囊，胸满饮。主喜呕及心中愦愦数欠，癫心下悸，咽中澹澹恐。主失欠，口，食饮善呕，暴哑不能言。", "白话": "《西方子明堂灸经》卷一说：“通谷二穴，在幽门下一寸，灸五壮。主治头痛寒热、汗出而不恶寒；主治颈项如被牵拽不能左右回顾、目䀮䀮不明；风寒及鼻流清涕，以及结积留饮癖囊、胸满有饮；主治喜呕及心中昏乱频频呵欠、癫病心下悸、咽中澹澹而恐；主治呵欠频作、口眼歪斜、食饮即呕、暴哑不能言。”"}, {"source": "条342｜《西方子明堂灸经》卷一", "原文": "《西方子明堂灸经》卷一：“外陵二穴，在天枢下半寸。灸五壮。主腹中尽痛，心如悬下引脐腹痛。", "白话": "《西方子明堂灸经》卷一说：“外陵二穴，在天枢下半寸，灸五壮。主治腹中尽痛、心如悬空感并向下牵引脐腹作痛。”"}, {"source": "条343｜《西方子明堂灸经》卷二", "原文": "《西方子明堂灸经》卷二：“少府二穴，在手小指大节后陷者中直劳宫，大节又作本节。灸十壮。主嗌中有气如息肉状。主小便不利，癃。主数噫恐悸气不足。主阴痛，实时挺长、寒热，阴暴痛，遗尿，偏虚则暴痒，气逆，及主烦满少气，悲恐畏人，掌中热，肘腋挛急，胸中痛，手卷不能伸。", "白话": "《西方子明堂灸经》卷二说：“少府二穴，在手小指本节后凹陷中，正对劳宫（‘大节’又作‘本节’）。灸十壮。主治咽中如有息肉状物堵塞；主治小便不利、癃闭；主治频作嗳气、恐惧惊悸、气不足；主治阴部疼痛，实证则阴挺长、寒热、阴部暴痛、遗尿，偏虚则突然作痒、气逆；又主治烦满气少、悲伤恐惧怕见人、掌中热、肘腋拘急、胸中痛、手卷曲不能伸。”"}, {"source": "条344｜《西方子明堂灸经》卷二", "原文": "《西方子明堂灸经》卷二：“大陵二穴，在掌后两骨间，灸二壮。主喉痹嗌干。主心痛。主目赤，小便如血，咳逆寒热发。主手掣手挛，及肘挛腋肿。主风热善怒，心中悲喜思慕，歔欷喜笑不止。主心下澹澹喜惊。主热病烦心，心闷而汗不出，掌中热，头痛，身热如火浸淫，烦满，舌本痛。主疟乍寒乍热。主咳喘。主呕血。主胸中痛。主痂疥。", "白话": "《西方子明堂灸经》卷二说：“大陵二穴，在掌后两骨之间，灸二壮。主治喉痹咽干；主治心痛；主治目赤、小便如血、咳逆寒热发作；主治手牵掣拘挛，及肘挛腋肿；主治风热善怒、心中悲喜思慕、抽泣而喜笑不止；主治心下澹澹易惊；主治热病心烦、胸闷而汗不出、掌中热、头痛、身热如火浸淫、烦满、舌根痛；主治疟疾忽冷忽热；主治咳喘；主治呕血；主治胸中痛；主治痂疥。”"}, {"source": "条345｜《西方子明堂灸经》卷二", "原文": "《西方子明堂灸经》卷二：“间使二穴，在掌后三寸，两筋间，灸七壮。主心胸痹，背相引。主心悬如饥。主嗌中如扼。主肘内廉痛。主热病烦心，喜哕，胸中澹澹喜动而热，恶风寒，呕吐，怵惕，寒中少气，掌中热，多惊，瘖不得语，腋肿肘挛，卒心痛。", "白话": "《西方子明堂灸经》卷二说：“间使二穴，在掌后三寸两筋之间，灸七壮。主治心胸痹痛、牵引及背；主治心悬如饥；主治咽中如被扼住；主治肘内侧痛；主治热病心烦、喜哕、胸中澹澹欲动而热、恶风寒、呕吐、怵惕（惊惧）、寒中气少、掌中热、多惊、失音不能语、腋肿肘挛、突发心痛。”"}, {"source": "条346｜《西方子明堂灸经》卷二", "原文": "《西方子明堂灸经》卷二：“曲泽二穴，在肘内廉下陷者中，屈肘得之，灸三壮。主心痛。主逆气呕涎或血。主掣痛，手不可伸。主心下澹澹喜惊。主伤寒温病身热，心口干，肘瘈瘛善摇，头颜清。", "白话": "《西方子明堂灸经》卷二说：“曲泽二穴，在肘内侧下方凹陷中，屈肘取之，灸三壮。主治心痛；主治气逆呕涎或呕血；主治牵掣疼痛、手不能伸；主治心下澹澹易惊；主治伤寒温病身热、心烦口干、肘部瘛疭多摇动、头面清冷。”"}, {"source": "条347｜《西方子明堂灸经》卷二", "原文": "《西方子明堂灸经》卷二：“少冲二穴，在手小指内廉之端，去爪甲如韭叶，灸三壮。又名经始，主胸痛，口热，咽酸，乍寒乍热。主咽酸。主太息，烦满，痰冷，少气，悲惊。主热病烦心，心闷而汗不出，掌中热。主上气，卒心痛，悲恐畏人，善惊，手拳不得伸，引肘腋痛。", "白话": "《西方子明堂灸经》卷二说：“少冲二穴，在手小指内侧端，距爪甲如一韭叶宽，灸三壮。又名经始。主治胸痛、口热、咽酸、忽冷忽热；主治咽酸；主治太息、烦满、痰冷、气少、悲伤易惊；主治热病心烦、胸闷而汗不出、掌中热；主治上气、突发心痛、悲伤恐惧怕见人、容易受惊、手握拳不能伸、牵引肘腋痛。”"}, {"source": "条348｜《西方子明堂灸经》卷四", "原文": "《西方子明堂灸经》卷四：“脑空二穴，在承灵后一寸半侠玉枕傍枕骨下陷中又名颞颥，灸三壮。主鼻管疽发为厉，鼻劳，癫疾，大瘦，头痛，头目瞑，癫疾及寒热引项强急，鼻衄不止，耳风鸣聋，脑风头痛不可忍。心悸目眩，癫疾，羸疾，体热项强不得回顾。魏武患头风，发则心闷乱，目眩，华佗灸而立愈。", "白话": "《西方子明堂灸经》卷四说：“脑空二穴，在承灵后一寸半、侠玉枕旁枕骨下凹陷中，又名颞颥，灸三壮。主治鼻管生疽发为厉病、鼻劳、癫疾、形体消瘦、头痛、头目昏瞑、癫疾及寒热牵引颈项强急、鼻衄不止、耳中风鸣耳聋、脑风头痛不可忍受；心悸目眩、癫疾、羸弱之疾、身热颈项强不能回顾。魏武（曹操）患头风，发作则心闷乱、目眩，华佗为灸而立即痊愈。”"}, {"source": "条349｜《西方子明堂灸经》卷四", "原文": "《西方子明堂灸经》卷四：“神道，在第五椎节下间，俛俯而取之，灸三壮。主腰脊急强，寒疟恍惚悲愁，健忘惊悸。主寒热头疼，进退往来，热喘目痛，视物无明。", "白话": "《西方子明堂灸经》卷四说：“神道在第五胸椎棘突下间，俯首取之，灸三壮。主治腰脊紧急强直、寒疟、恍惚悲愁、健忘惊悸；主治寒热头痛、往来进退、热喘目痛、视物不明。”"}, {"source": "条350｜《西方子明堂灸经》卷六", "原文": "《西方子明堂灸经》卷六：“通谷二穴，在足小趾外侧本节前陷中，灸三壮。主头重头痛，寒热汗出不恶寒，项如拔，不可左右顾，目眩，目䀮䀮不明，恶风寒，胸胁支满，心中愦愦，数欠，癫，心下悸，咽中澹澹恐。主结积留饮，癖囊，胸满饮心痛，鼻鼽、清涕出，善惊引鼽衄，项痛，胸满食不化。", "白话": "《西方子明堂灸经》卷六说：“通谷二穴，在足小趾外侧本节前凹陷中，灸三壮。主治头重头痛、寒热汗出不恶寒、颈项如被牵拽不能左右回顾、目眩、目䀮䀮不明、恶风寒、胸胁胀满、心中昏乱、频频呵欠、癫病、心下悸、咽中澹澹而恐；主治结积留饮、癖囊、胸满有饮心痛、鼻流清涕、容易受惊而鼻衄、项痛、胸满食不化。”"}, {"source": "条351｜《西方子明堂灸经》卷六", "原文": "《西方子明堂灸经》卷六：“京骨二穴，在足外侧大骨下赤白肉际陷中，灸三壮。主目中白翳，目反白从内眦始，目眩。主头热鼻衄，鼻不利，涕黄，鼻中衄血不止，淋泺，自啮唇，背恶寒痛，脊颈项强难以俛俯仰，脚挛足寒，脊痓反折，狂仆，疟寒热，善惊悸，不欲食，癫病狂走，痰髀枢痛。", "白话": "《西方子明堂灸经》卷六说：“京骨二穴，在足外侧大骨下赤白肉际凹陷中，灸三壮。主治目生白翳、目反白从内眦开始、目眩；主治头热鼻衄、鼻不利、涕黄、鼻中出血不止、淋泺、自咬唇、背恶寒疼痛、脊颈项强难以俯仰、脚挛足寒、脊强反折、狂而仆倒、疟疾寒热、容易惊悸、不欲饮食、癫病狂走、痰流髀枢（髋关节）作痛。”"}, {"source": "条352｜《西方子明堂灸经》卷八", "原文": "《西方子明堂灸经》卷八：“蠡沟二穴，在足内踝上五寸，灸三壮。主卒疝，少腹肿，时少腹暴痛，小便不利如癃闭，数噫，恐悸，少气不足，腹中痛，悒悒不利，咽中闷，如有息肉状，背拘急不可俯仰，女子赤白淫下，时多时少，暴腹痛刺。", "白话": "《西方子明堂灸经》卷八说：“蠡沟二穴，在足内踝上五寸，灸三壮。主治突发疝气、少腹肿、时时少腹暴痛、小便不利如癃闭、频作嗳气、恐惧惊悸、气少不足、腹中痛、悒悒不舒、咽中闷如有息肉状、背部拘急不能俯仰、女子赤白带下时多时少、突发腹中刺痛。”"}, {"source": "条353｜《西方子明堂灸经》卷八", "原文": "《西方子明堂灸经》卷八：“行间二穴，在足大趾间，动脉应手陷中，灸三壮。主溺难，白浊，寒疝，少腹肿，咳逆呕血，腰痛不可俯仰，腹中胀，心痛，色苍苍如死状，终日不得息，口，四肢逆冷，嗌干、烦渴，瞑不欲视，目中泪出，大息，癫疾，短气，癃闭，茎中痛，面色苍苍黑，短气，呕血，胸背痛，心痛数惊，心悲不乐，妇人月事不利，见赤白而有身反败，阴寒振寒，溲白，尿难、痛。", "白话": "《西方子明堂灸经》卷八说：“行间二穴，在足大趾之间、动脉应手的凹陷中，灸三壮。主治小便难、白浊、寒疝、少腹肿、咳逆呕血、腰痛不能俯仰、腹中胀、心痛、面色苍苍如死状、整日呼吸不利、口眼歪斜、四肢逆冷、咽干烦渴、闭目不欲视、目中流泪、频作太息、癫疾、短气、癃闭、茎中痛、面色苍苍而黑、短气、呕血、胸背痛、心痛而频惊、心中悲伤不乐、妇人月经不利、见赤白带下而胎反堕败、阴部寒冷振栗、小便白、小便难而痛。”"}, {"source": "条354｜《医学纲目》卷十四", "原文": "《医学纲目》卷十四：“狐疝，惊悸少气，巨缺主之。", "白话": "《医学纲目》卷十四说：“狐疝，惊悸气少，取巨阙主治。”"}, {"source": "条355｜《普济方》卷三", "原文": "《普济方》卷三：“足少阴肾之经。是动病：饥不欲食，面黑如炭色，咳唾则有血，喝喝而喘，坐而欲起，目䀮䀮然如无所见，心悬如饥状，气不足则善恐，心惕惕如人将捕之，是谓骨厥。是主肾。", "白话": "《普济方》卷三说：“足少阴肾经。本经变动所生的病候：饥饿却不想吃、面色黑如炭色、咳唾则带血、喝喝有声而喘、坐下又想起立、目䀮䀮如无所见、心悬如饥饿状、气不足则容易恐惧、心中惕惕如有人将要抓捕自己——这叫做骨厥。（本经）主肾所生病。”"}, {"source": "条356｜《普济方》卷三", "原文": "《普济方》卷三：“足阳明胃之经。是动则病，洒洒振寒，善伸数欠，颜黑。病至则恶人与火。闻木音则惕然而惊，心欲动，独闭户塞牖而处，甚则欲上高而歌，弃衣而走，贲响向腹胀，是谓骭厥。主血。", "白话": "《普济方》卷三说：“足阳明胃经。本经变动所生病：瑟瑟发抖恶寒、多伸展频频呵欠、面色黑。病来则厌恶人与火；听见木音就惕然而惊、心悸欲动，只想闭门塞窗独处；病甚则要登高而歌、弃衣而走、肠鸣贲响而腹胀——这叫做骭厥。（本经）主血所生病。”"}, {"source": "条357｜《普济方》卷五", "原文": "《普济方》卷五：“灵道为经掌后真，心痛肘挛悲恐惊，暴瘖即便难言语，建时到后即宜针。", "白话": "《普济方》卷五说：“灵道为经穴在掌后真（正），心痛肘挛、悲伤恐惧易惊，暴然失音即便言语困难，时候一到就宜针刺。”"}, {"source": "条358｜《普济方》卷五", "原文": "《普济方》卷五：“液门为荥刺陷中。，惊悸痫热共头疼。，目赤齿血出不定。三棱针刺即时灵。", "白话": "《普济方》卷五说：“液门为荥穴刺其凹陷中，惊悸、痫热并头痛，目赤、齿出血不定，用三棱针刺立刻见效。”"}, {"source": "条359｜《普济方》卷五", "原文": "《普济方》卷五：“天井为合肘外寻，。风痹筋挛入骨深。，咳嗽不食并惊悸。，心胸气上即时针。", "白话": "《普济方》卷五说：“天井为合穴在肘外寻取，风痹筋挛深入于骨，咳嗽不食并惊悸，心胸气上逆即时针刺。”"}, {"source": "条360｜《普济方》卷五", "原文": "《普济方》卷五：“间使心经掌后间。，心痛呕逆恶风寒。，热时咽痛并惊悸。，神针邪忤也须安。", "白话": "《普济方》卷五说：“间使（属）心经在掌后之间，心痛呕逆恶风寒，发热时咽痛并惊悸，神针（刺之）邪忤也须得安宁。”"}, {"source": "条361｜《普济方》卷五", "原文": "《普济方》卷五：“五里，在肘上三寸。又行向裹大脉中央。灸十壮。主风劳惊恐吐血。肘不能举。风痫。嗜卧。四肢不欲动摇。身黄寒热颈肿。咳逆呼吸。目视䀮䀮。少气痎疟。心下胀满痛。上气。左取右。右取左。", "白话": "《普济方》卷五说：“五里在肘上三寸，又行向内侧大脉中央，灸十壮。主治风劳、惊恐、吐血、肘不能举、风痫、嗜卧、四肢不欲动摇、身黄寒热颈肿、咳逆呼吸不利、目视䀮䀮不明、气少痎疟、心下胀满疼痛、上气。左病取右，右病取左。”"}, {"source": "条362｜《普济方》卷五", "原文": "《普济方》卷五：“光明，足少阳络。在外踝五寸。灸五壮。主身体寒少热甚。恶心惕然。此与绝骨穴疗病同功。主淋漓胫痠酸。热病汗不出。狂痛。虚则痿躄。坐不能起。实则厥胫热。膝痛。身体不仁。手足偏小。啮颊。不能俛俯仰。", "白话": "《普济方》卷五说：“光明是足少阳的络穴，在外踝上五寸，灸五壮。主治身体寒少而热甚、恶心惕然（惊惧），这与绝骨穴疗病功效相同；主治小便淋漓、胫部酸痛、热病汗不出、狂痛；虚则下肢痿躄、坐不能起，实则厥冷而胫热、膝痛、身体不仁、手足偏小、咬颊、不能俯仰。”"}, {"source": "条363｜《普济方》卷五", "原文": "《普济方》卷五：“少冲，一名经始。在手小指内廉之端。，去爪甲如韭叶。灸三壮。主热病烦心。上气心痛而冷。烦满少气。悲恐善惊。掌中热。肘腋胸中痛。口中热。咽喉中痠酸。乍寒乍热。手卷不伸。掌痛引肘腋。", "白话": "《普济方》卷五说：“少冲又名经始，在手小指内侧端、距爪甲如一韭叶宽，灸三壮。主治热病心烦、上气心痛而冷、烦满气少、悲伤恐惧易惊、掌中热、肘腋胸中痛、口中热、咽喉酸楚、忽冷忽热、手卷曲不能伸、掌痛牵引肘腋。”"}, {"source": "条364｜《普济方》卷五", "原文": "《普济方》卷五：“大陵，在掌后两筋间陷者中。灸三壮。主心痛善悲。厥逆。悬心如饥之状。心澹澹而惊恐。热病烦心。而汗不出。肘挛腋肿。喜笑不休。心中痛。目赤黄。小便如血。欲呕。胸中热。狂言不乐太息。喉痹嗌干。喘逆身热如火。头痛如破。短气胸痛。而手挛不伸及腋。偏枯不仁。手●偏小筋急。呕血瘃痒欲呕。耳鸣。", "白话": "《普济方》卷五说：“大陵在掌后两筋间凹陷中，灸三壮。主治心痛善悲、厥逆、心悬如饥饿之状、心澹澹而惊恐、热病心烦而汗不出、肘挛腋肿、喜笑不休、心中痛、目赤黄、小便如血、欲呕、胸中热、狂言不乐而太息、喉痹咽干、喘逆身热如火、头痛如破、短气胸痛、手拘挛不伸及于腋、偏枯不仁、手（缺字）偏小筋急、呕血、瘃痒欲呕、耳鸣。”"}, {"source": "条365｜《普济方》卷五", "原文": "《普济方》卷五：“内关，手心主络。在掌后去腕二寸。灸三壮。主面赤皮热。热病汗不出。中风热。目赤黄。肘挛腋肿。实则心暴痛。虚则烦心。惕惕不能动。失智。心澹澹善惊恐。心悲。", "白话": "《普济方》卷五说：“内关是手心主（心包）的络穴，在掌后距腕二寸，灸三壮。主治面赤皮热、热病汗不出、中风热、目赤黄、肘挛腋肿；实则心暴痛，虚则心烦、惕惕不能动、失智、心澹澹善惊恐、心悲。”"}, {"source": "条366｜《普济方》卷五", "原文": "《普济方》卷五：“间使，在掌后三寸两筋间陷者中。灸三壮。主心痛善悲。厥逆。悬心如饥之状。心澹澹而惊恐。惊狂。面赤目黄。热病烦心。善哕。胸中澹澹善动。与身热风热呕吐。怵惕。寒中少气。掌中热。肘挛腋肿。卒心中痛。瘛疭。互相引肘内廉痛。心熬熬然。胸痹引背时寒。喜惊。瘖不能语。咽中哽。头大浸淫。", "白话": "《普济方》卷五说：“间使在掌后三寸两筋间凹陷中，灸三壮。主治心痛善悲、厥逆、心悬如饥之状、心澹澹而惊恐、惊狂、面赤目黄、热病心烦、善哕、胸中澹澹善动、身热风热呕吐、怵惕、寒中气少、掌中热、肘挛腋肿、突发心中痛、瘛疭、互相牵引肘内廉痛、心中熬熬然（烦热灼心）、胸痹引背时觉寒冷、易惊、失音不能语、咽中如哽、头大浸淫（头肿大浸淫）。”"}, {"source": "条367｜《普济方》卷五", "原文": "《普济方》卷五：“曲泽，在肘内廉下陷者中。屈肘得之。灸三壮。主心痛。卒咳逆。心下澹然喜惊。身热烦心。口干。手清。逆气呕血。肘瘈瘛。善悲。摇头清汗不出。肘不能过肩。伤寒病温。", "白话": "《普济方》卷五说：“曲泽在肘内侧下方凹陷中，屈肘取之，灸三壮。主治心痛、突发咳逆、心下澹然易惊、身热心烦、口干、手冷、气逆呕血、肘部瘛疭、善悲、摇头而清汗不出、肘不能过肩、伤寒温病。”"}, {"source": "条368｜《普济方》卷五", "原文": "《普济方》卷五：“然谷，一名龙渊。在足内踝前起大骨下陷者中。灸三壮。主不嗜食。心如悬。哀而善怒。嗌内肿。心惕惕然恐。如人将捕之。多涎出。喘逆少气。呼吸不足以息。心痛如刺。厥心痛。与背相引。善瘛疭如后触其心。伛偻者。肾心痛也。厥心痛。如锥刺其心。心痛甚者。脾心痛也。胸中寒。脉代时不至。上重下轻。足不能安地。小腹胀上抢心。胸胁支满。咳唾有血。喉痹。癃疝石水。女子不子。阴暴出。淋漏。男子精溢胫痠酸。不能", "白话": "《普济方》卷五说：“然谷又名龙渊，在足内踝前起大骨下凹陷中，灸三壮。主治不欲食、心如悬、悲哀而善怒、咽内肿、心惕惕然恐惧如有人将要抓捕自己、多涎出、喘逆气少、呼吸不足以息、心痛如刺；厥心痛牵引及背、容易瘛疭如从背后触动其心而伛偻的，是肾心痛；厥心痛如锥刺其心、心痛剧烈的，是脾心痛；胸中寒、脉代而时有歇止、上重下轻、足不能踏地、小腹胀上冲于心、胸胁胀满、咳唾带血、喉痹、癃疝石水、女子不孕、阴挺暴出、淋漏、男子精溢胫酸、不能久立、寒热、消渴、黄疸、足一寒一热、烦乱纵弛烦满、小儿脐"}, {"source": "条369｜《普济方》卷五", "原文": "《普济方》卷五：“复溜，一名伏白。一名昌阳。在足内踝上二寸陷者中。灸五壮。主腰痛引脊内廉。嗌干。腹瘈瘛痛。坐而欲起。目䀮䀮善忘。多言。疟热。少气。足胻寒。不能自温。腹䐜切痛引心。心如悬。阴厥。脚臑后廉急不可前却。血淋肠澼。便脓血。足趺上痛。舌卷不能言。喜笑足痿不收履。溺青赤白黄黑。青取井。赤取荣。黄取俞。白取经。黑取合。血痔泄后重。腹痛如淋状。在仆必有所扶持。及大气涎出。鼻孔中痛。腹中雷鸣。骨寒热", "白话": "《普济方》卷五说：“复溜又名伏白、昌阳，在足内踝上二寸凹陷中，灸五壮。主治腰痛牵引脊内侧、咽干、腹中瘛疭痛、坐下又想起、目䀮䀮不明而善忘、多言、疟热、气少、足胫冷不能自温、腹中胀满剧痛引心、心如悬、阴厥、小腿后侧拘急不能前后举动、血淋肠澼、便脓血、足背痛、舌卷不能言、喜笑、足痿不能着鞋行走、小便见青赤白黄黑五色（青取井穴，赤取荥穴，黄取俞穴，白取经穴，黑取合穴）、血痔泄后重、腹痛如淋状、欲仆必有所扶持、以及大气上逆涎出、鼻孔中痛、腹中雷鸣、骨寒热无处安适、汗出不休、心风四肢肿"}, {"source": "条370｜《普济方》卷五", "原文": "《普济方》卷五：“上脘，在巨阙下一寸五分。去蔽骨三寸。足阳明手太阴任脉之会。灸五壮。主寒中伤饱。食饮不化。腹䐜胀。心腹痛。胸胁支满。脉虚则生百病。甄权云。主心风。惊悸不能食。心下有膈。呕血。目眩。头悬眩痛。身热汗不出。心痛有三虫。多涎。不得反侧。腹中满。暴痛汗出。", "白话": "《普济方》卷五说：“上脘在巨阙下一寸五分，距蔽骨三寸，是足阳明、手太阴、任脉的交会穴，灸五壮。主治寒中伤饱、饮食不化、腹胀满、心腹痛、胸胁胀满；脉虚则生百病。甄权说：主治心风、惊悸不能食、心下如有膈、呕血、目眩、头悬眩痛、身热汗不出、心痛有三虫、多涎、不能转侧、腹中满、暴痛汗出。”"}, {"source": "条371｜《普济方》卷五", "原文": "《普济方》卷五：“通谷，在足小指外侧本节前陷者中。灸三壮。主身疼痛。喜惊。互引鼻鼽癫疾。寒热。目䀮䀮喜咳。喘逆呕沫。痓善悸。头眩项痛。烦满。振寒。痎疟。", "白话": "《普济方》卷五说：“通谷在足小趾外侧本节前凹陷中，灸三壮。主治身疼痛、易惊、互相牵引之鼻鼽癫疾、寒热、目䀮䀮不明而喜咳、喘逆呕沫、痓证而易悸、头眩项痛、烦满、振寒、痎疟。”"}, {"source": "条372｜《普济方》卷五", "原文": "《普济方》卷五：“飞阳，一名厥阳。在足外踝上七寸。足太阳络。灸三壮。主身懈寒。少气热甚。恶人声。心惕然。取飞阳。及绝骨附上临泣。及淫泺。胫痛热病汗不出皆主之。下部寒。体重逆气。头眩痛。痓反折。疟。实则腰背痛。虚则鼽衄不止。间日作狂癫疾。体痛颈项痛。历节汗出而步失履。寒腹不仁喘中痛。痔篡痛。", "白话": "《普济方》卷五说：“飞阳又名厥阳，在足外踝上七寸，是足太阳的络穴，灸三壮。主治身体懈怠发冷、气少而热甚、厌恶人声、心惕然（惊惧），取飞阳；以及绝骨、（阳）辅、上临泣诸穴；以及淫泺、胫痛、热病汗不出都主治之；下部寒冷、身体沉重气逆、头眩痛、痓证反折、疟疾；实则腰背痛，虚则鼻衄不止、隔日发作之狂癫疾、体痛颈项痛、历节痛汗出而走路掉鞋、身寒腹不仁、喘中痛、痔疮阴部痛。”"}, {"source": "条373｜《普济方》卷五", "原文": "《普济方》卷五：“肾俞，在第十四椎下两旁各一寸半。灸三壮。主腰痛不可俛俯仰反侧。热痓。寒热。身多羸瘦。两胁引痛。心下腹痛。心如悬。下引脐。少腹急痛热。面黑目䀮䀮。喘咳少气。溺赤骨寒热。溲难。肾胀。头风痛如破。足寒如冰。头重身热振栗。腰中四肢淫泺。欲吐腹鼓。大寒中身。洞泄食不化。骨寒热。引背不得息。", "白话": "《普济方》卷五说：“肾俞在第十四椎下两旁各一寸半，灸三壮。主治腰痛不能俯仰转侧、热痓、寒热、身体多羸瘦、两胁牵引痛、心下腹痛、心如悬向下牵引脐部、少腹急痛而热、面色黑而目䀮䀮、喘咳气少、小便赤、骨寒热、小便难、肾胀、头风痛如破、足冷如冰、头重身热振栗、腰中四肢淫泺、欲吐腹胀如鼓、大寒中身、洞泄食不化、骨寒热、牵引及背呼吸不利。”"}, {"source": "条374｜《普济方》卷六", "原文": "《普济方》卷六：“神庭一穴，在鼻直入发际五分。灸二七壮。，至七七壮止。岐伯曰。，凡欲疗风。，勿令灸多。，缘风性轻。，多即伤。惟唯宜灸七壮。，至三七壮止。禁针。，针即发狂。忌生冷鸡猪羊鱼肉酒面动风等物。明堂经云。，举火之时。，忌热食。，不宜热衣。，亦云灸三壮。铜人经云。，在发际直鼻上。，督脉。，入发际五分。，灸二七壮。，至百壮。治肿气。，风痫癫风。，戴目上不识人。，羊鸣吐舌。，角弓反张。，弃衣而走。", "白话": "《普济方》卷六说：“神庭一穴，在鼻直上入发际五分。灸二七壮（十四壮）至七七壮（四十九壮）止。岐伯说：凡是要治风的，不要灸得太多，因为风性轻扬，灸多反伤（正气）；只宜灸七壮至二七壮（十四壮）止。禁针，针了就会发狂。忌生冷、鸡猪羊鱼肉酒面等动风之物。明堂经说：施灸之时，忌热食，不宜穿热衣；也说灸三壮。铜人经说：在发际直鼻上，属督脉，入发际五分，灸二七壮至百壮。治疗肿气、风痫癫风、戴目上视不识人、羊鸣吐舌、角弓反张、弃衣而走、披发而行、上歌下哭、多学人言语、惊悸不得安睡、头痛、喘渴"}, {"source": "条375｜《普济方》卷六", "原文": "《普济方》卷六：“百会一穴，一名三阳五会。在前顶后一寸半顶中央旋毛中。，可容豆。灸七壮。，止七七壮。凡灸头顶。，不得过七壮。缘头顶皮薄。，灸不宜。多针二分。，得气即泻。", "白话": "《普济方》卷六说：“百会一穴，又名三阳五会，在前顶后一寸半、头顶中央旋毛中，凹陷可容豆。灸七壮至七七壮止。凡灸头顶诸穴，不得超过七壮，因为头顶皮薄，不宜多灸。针刺二分，得气即泻。”"}, {"source": "条376｜《素问》", "原文": "《素问》注云。，刺四分。", "白话": "《素问》（王冰）注说：刺入四分。"}, {"source": "条377｜《铜人经》", "原文": "《铜人经》云。，督脉足太阳交会于颠。，上治大人小儿脱肛久不差。，风痫中风角弓反张。，羊鸣。，或多哭。，言语不择。，发即无时。，发时即死。，盛即吐沫。，心烦惊悸健忘。，心神恍惚。，痎疟耳鸣耳聋。，鼻塞不闻香臭。又云。，疗头风头疼。，目眩多睡。，无心力。，吃食无味。，头重。，饮酒面赤。，如灸数至百五即停。三五日讫。绕四畔。，以三棱针刺令出血。以井花水淋之。，令气宣通。不得令向火灸。，恐拔气上。，令人眼", "白话": "《铜人经》说：“（百会）为督脉与足太阳交会于巅顶。上治大人小儿脱肛久不愈、风痫中风角弓反张、羊鸣、或多哭、言语不择、发作无定时、发作时即如死、病盛即吐沫、心烦惊悸健忘、心神恍惚、痎疟耳鸣耳聋、鼻塞不闻香臭。又说：治疗头风头痛、目眩多睡、无心力、饮食无味、头重、饮酒则面赤。如灸数已到一百五十壮即停，三五日完毕；绕穴四周用三棱针刺令出血，再以井华水淋之，使气宣通。不得向着火灸，恐怕拔气上逆，使人眼暗。忌酒面猪鱼荞麦蒜（缺字）等。”"}, {"source": "条378｜《普济方》卷六", "原文": "《普济方》卷六：“风府一穴，一名舌本。在项后发际上一寸。，大箸内宛宛中。疾言其肉立起。，言休立下。禁灸。，使人失音。针三分。铜人经", "白话": "《普济方》卷六说：“风府一穴，又名舌本，在项后发际上一寸、大筋内宛宛凹陷中；快速说话则其处肌肉立起，说话停则立下。禁灸，灸了使人失音。针刺三分。铜人经……”"}, {"source": "条379｜《铜人经》", "原文": "《铜人经》云。，一名舌本。督脉阳维之会。治头痛。，颈急不得回顾。，目眩。，鼻衄。，喉咽痛。，狂走目妄视。又云。，主头项急不可倾侧。，鼻不得息。，嗌痛。，足不仁。明堂经云。，主暴瘖。，不得言。多悲恐惊悸。，欲自杀。，目反视。又云。，针四分。，留三呼。又云。，舌缓。，针风府。", "白话": "《铜人经》说：“（风府）又名舌本，是督脉与阳维脉之会。治疗头痛、颈项紧急不能回顾、目眩、鼻衄、咽喉痛、狂走而目妄视。又说：主治头项紧急不能倾侧、鼻不得息、咽痛、足不仁。明堂经说：主治暴瘖不能言、多悲伤恐惧惊悸、想自杀、目上翻。又说：针四分，留三呼。又说：舌缓不收，针风府。”"}, {"source": "条380｜《普济方》卷六", "原文": "《普济方》卷六：“神道一穴，在五椎节下间陷中。，俛俯而取之。灸七七壮。，止百壮。小儿风癫瘛疭。，可灸七壮。明堂经云。，针五分。，灸三壮。下云。，五壮。铜人经", "白话": "《普济方》卷六说：“神道一穴，在第五椎节下间凹陷中，俯首取之。灸七七壮（四十九壮）至百壮；小儿风癫瘛疭可灸七壮。明堂经说：针五分，灸三壮；《明堂下经》说五壮。铜人经……”"}, {"source": "条381｜《铜人经》", "原文": "《铜人经》云。，督脉气所发。西方子云。，主腰脊急强。，痎疟。，恍惚。，悲愁。，健忘。，惊悸。主寒热头疼。，进退往来。，热喘目痛。，视物不明。", "白话": "《铜人经》说：“（神道为）督脉之气所发。”西方子说：“主治腰脊紧急强直、痎疟、恍惚、悲愁、健忘、惊悸；主治寒热头痛、往来进退、热喘目痛、视物不明。”"}, {"source": "条382｜《普济方》卷七", "原文": "《普济方》卷七：“彧中二穴，在腧府下一寸六分陷中。仰面取之明堂经云。，仰卧取之。针四分。，灸五壮。明堂下经云。，腧府下一寸。灸三壮。又云。，主咳嗽上喘。，不能食也。铜人经", "白话": "《普济方》卷七说：“彧中二穴，在俞府下一寸六分凹陷中，仰面取之（明堂经说仰卧取之）。针四分，灸五壮。明堂下经说：在俞府下一寸，灸三壮。又说：主治咳嗽上喘、不能食。铜人经……”"}, {"source": "条383｜《铜人经》", "原文": "《铜人经》云。，足少阳脉气所发。治胸胁支满。，咳嗽喘逆不得息。，呕吐，。上气涎出多。，胸满不得食。，喘悸。，坐不安席又云。足少阴脉气所发。", "白话": "《铜人经》说：“（彧中）是足少阳脉气所发（又说：是足少阴脉气所发）。治疗胸胁胀满、咳嗽喘逆呼吸不利、呕吐、上气涎出多、胸满不得食、喘悸、坐不安席。”"}, {"source": "条384｜《普济方》卷七", "原文": "《普济方》卷七：“鸠尾一穴，一名尾翳。，一名●骭。在胸前蔽骨下五分。，不可灸。灸即令人毕世少心力。此穴大难针。，大好手方可下针。不然。，取气多。，令人夭。针三分。，留三呼。，泻五吸。肥人倍之。明堂经云。，在蔽骨下五分陷者中。灸三壮。主心惊悸。，神气耗散。，癫痫病狂。，不择言也。素问注云。，不可灸刺。人无蔽骨者。，从歧骨际下行一寸。铜人经", "白话": "《普济方》卷七说：“鸠尾一穴，又名尾翳，又名（缺字）骭。在胸前蔽骨下五分。不可灸，灸了令人终身心力不支。此穴极难针，须高手下针，不然取气过多，使人夭折。针三分，留三呼，泻五吸，肥人加倍。明堂经说：在蔽骨下五分凹陷中，灸三壮。主治心惊悸、神气耗散、癫痫病狂、言语不择。《素问》注说：不可灸刺。没有蔽骨的人，从歧骨际下行一寸（取穴）。铜人经……”"}, {"source": "条385｜《铜人经》", "原文": "《铜人经》云。，治心风惊痫发癫。，状如鸟鸣。，破心吐血。，心中气闷。，不喜闻人语。，心腹胀满胸中满。，咳逆数噫。，喘息。，喉痹咽壅。，水浆不下。忌如前法。西方子云。，禁灸。", "白话": "《铜人经》说：“（鸠尾）治疗心风惊痫发癫，症状如鸟鸣，心破吐血，心中气闷，不喜听人说话，心腹胀满、胸中满，咳逆频频嗳气，喘息，喉痹咽部壅塞，水浆不下。禁忌如前法。西方子说：禁灸。”"}, {"source": "条386｜《普济方》卷七", "原文": "《普济方》卷七：“巨关一穴，心之募。在鸠尾下一寸。鸠尾巨者。少令强一寸中取穴。针六分。，留七呼。，得气即泻。可灸七壮。，止七七壮。明堂经云。，在鸠尾下一寸陷者中。主心痛不可忍。，呕血。，烦心。，膈中不利。，胸胁支满。，霍乱吐痢不止。，困顿不知人。铜人经", "白话": "《普济方》卷七说：“巨关（巨阙）一穴，是心的募穴，在鸠尾下一寸。鸠尾大的人，稍微强取一寸之中定穴。针六分，留七呼，得气即泻；可灸七壮至七七壮止。明堂经说：在鸠尾下一寸凹陷中。主治心痛不可忍、呕血、心烦、膈中不利、胸胁胀满、霍乱吐泻不止、困顿不省人事。铜人经……”"}, {"source": "条387｜《铜人经》", "原文": "《铜人经》云。，任脉气所发。，治心中烦满。，热病。，胸中痰饮。，腹胀暴痛。，恍惚不知人。，息贲时唾血。，蛔虫心痛。，蛊毒霍乱。，发狂不识人。，惊悸少气。又云。，主热风痫。西方子云。，主风癫浪言。，或作鸟鸣声。，不能食。，无心力。凡心痛有数种。，冷痛。，蛔虫心痛。，蛊毒。，霍乱不识人。，及腹中满暴痛。，汗出及手清臂不举。忌同。", "白话": "《铜人经》说：“（巨阙）是任脉之气所发，治疗心中烦满、热病、胸中痰饮、腹胀暴痛、恍惚不省人事、息贲时时唾血、蛔虫心痛、蛊毒霍乱、发狂不识人、惊悸气少。又说：主治热风痫。”西方子说：“主治风癫妄言，或作鸟鸣声，不能食，无心力。”凡心痛有数种：冷痛、蛔虫心痛、蛊毒、霍乱不识人，以及腹中胀满暴痛、汗出及手冷臂不举。（禁忌）与前同。"}, {"source": "条388｜《普济方》卷七", "原文": "《普济方》卷七：“上脘 一作管一穴，在巨阙下一寸。当一寸五分去蔽骨一寸明堂经云去巨骨三寸。针入八分。，先补后泻。，神验。如风痫热病。，宜先泻后补。，立愈。日灸二七壮。，至百壮。未愈。，倍之。忌同。明堂下经云。，灸三壮。铜人经", "白话": "《普济方》卷七说：“上脘（一作‘管’）一穴，在巨阙下一寸（当为一寸五分，距蔽骨一寸；明堂经说距巨骨三寸）。针入八分，先补后泻，效果如神；如是风痫热病，宜先泻后补，立刻痊愈。每日灸二七壮（十四壮）至百壮，未愈则加倍。禁忌同前。明堂下经说：灸三壮。铜人经……”"}, {"source": "条389｜《铜人经》", "原文": "《铜人经》云。，任脉足阳明手太阳之会。，治心中热烦。，贲豚气胀满不能食。，霍乱吐利。，身热汗不出。，三焦多涎。，心常惊悸。，心痛不可忍。，伏梁气状如覆杯。林又云主霍乱心痛不可眠卧。，心中闷发哕。西方子云。，去鸠尾三寸。明堂经云。，主呕吐食饮不下。，胸胀气满。，心忪惊悸。，时吐呕血。，腹内刺痛。", "白话": "《铜人经》说：“（上脘）是任脉、足阳明、手太阳之会，治疗心中热烦、贲豚之气胀满不能食、霍乱吐利、身热汗不出、三焦多涎、心常惊悸、心痛不可忍、伏梁之气形状如覆杯。”林（林亿等）又说：主治霍乱心痛不能眠卧、心中闷发哕。西方子说：（上脘）距鸠尾三寸。明堂经说：主治呕吐饮食不下、胸胀气满、心忪惊悸、时时吐呕血、腹内刺痛。"}, {"source": "条390｜《普济方》卷七", "原文": "《普济方》卷七：“通谷二穴，在幽门下一寸。针五分。，灸五壮。明堂经云。，夹上脘两旁。，相去三寸。下经云。，灸三壮。又云。，在幽关下一寸陷者中。，灸三壮。主失欠口。，及呕。，暴哑不能言也。西方子云。，主头痛寒热。汗出不恶寒。主项如拔不可左右顾。目䀮䀮 不明。风寒及鼻出清涕。结积留饮。●癖。癖囊胸满支饮。主喜呕。及心中愤愤。数欠。癫痫。心下悸。咽中澹澹恐生食喜呕。铜人经", "白话": "《普济方》卷七说：“通谷二穴，在幽门下一寸。针五分，灸五壮。明堂经说：夹上脘两旁，相距三寸。下经说：灸三壮。又说：在幽关下一寸凹陷中，灸三壮。主治呵欠频作、口眼歪斜，以及呕吐、暴哑不能言。西方子说：主治头痛寒热、汗出不恶寒；主治项如被牵拽不能左右回顾、目䀮䀮不明、风寒及鼻流清涕、结积留饮、（缺字）癖、癖囊胸满支饮；主治喜呕，以及心中昏乱、频频呵欠、癫痫、心下悸、咽中澹澹而恐、生食喜呕。铜人经……”"}, {"source": "条391｜《铜人经》", "原文": "《铜人经》云。冲脉足少阴之会。主干呕。又无所出。又治劳食。欲膈结。", "白话": "《铜人经》说：“（通谷）是冲脉与足少阴之会。主治干呕而无所出，又治劳伤饮食、将成膈结之证。”"}, {"source": "条392｜《普济方》卷七", "原文": "《普济方》卷七：“外陵二穴，在天枢下一寸。灸五壮。针三分。西方子云。在天枢下半寸。灸五壮。主腹中疼痛。心如悬。下引脐腹痛。铜人经", "白话": "《普济方》卷七说：“外陵二穴，在天枢下一寸。灸五壮，针三分。西方子说：在天枢下半寸，灸五壮。主治腹中疼痛、心如悬空感、向下牵引脐腹作痛。铜人经……”"}, {"source": "条393｜《铜人经》", "原文": "《铜人经》云。足阳明脉气所发。", "白话": "《铜人经》说：“（外陵）是足阳明脉气所发。”"}, {"source": "条394｜《普济方》卷八", "原文": "《普济方》卷八：“少府二穴，火也。在手小指本节后陷中。直劳宫劳宫在手中。针二分。灸七壮。明堂云。，三壮。铜人经", "白话": "《普济方》卷八说：“少府二穴，属火，在手小指本节后凹陷中，正对劳宫（劳宫在手中）。针二分，灸七壮（明堂说三壮）。铜人经……”"}, {"source": "条395｜《铜人经》", "原文": "《铜人经》云。，手少阴脉之所流也。，为荥。，治烦满少气。，悲恐畏人。，臂痠酸。，掌中热。，肘腋挛急。，胸中痛。，手拳不得伸。西方子云。，在手小指大节后陷者中。，直劳宫。，主嗌中。，有气如息肉状。，主小便不利。，便癃。，主数噫恐悸。，气不足。，主阴痛。，实时梃长。，寒热。，阴暴痛。，遗尿偏虚则暴痒气逆。明堂云。，主痎疟久不愈。", "白话": "《铜人经》说：“（少府）是手少阴脉气所流（溜）之处，为荥穴，治疗烦满气少、悲伤恐惧怕见人、臂酸、掌中热、肘腋拘急、胸中痛、手握拳不能伸。”西方子说：“在手小指大节（本节）后凹陷中，正对劳宫。主治咽中有气如息肉状；主治小便不利、癃闭；主治频作嗳气、恐惧惊悸、气不足；主治阴痛，实证则阴挺长、寒热、阴部暴痛、遗尿，偏虚则突发瘙痒气逆。”明堂说：主治痎疟久不愈。"}, {"source": "条396｜《普济方》卷八", "原文": "《普济方》卷八：“神门二穴，土也。一名兑冲。在掌后兑骨端陷中。灸七壮。，炷如小麦。针二分。，留七呼。铜人经", "白话": "《普济方》卷八说：“神门二穴，属土，又名兑冲，在掌后兑骨端凹陷中。灸七壮，艾炷如小麦大；针二分，留七呼。铜人经……”"}, {"source": "条397｜《铜人经》", "原文": "《铜人经》云。，手少阴脉之所注也。，为腧。，治疟心烦甚。，欲得饮冷。，恶寒则欲处温。，咽干不嗜食。，心痛数噫恐悸。，少气不足。，臂寒。，喘逆。，身热狂悲哭。，呕血少气遗溺。，大人小儿五痫。西方子云。，笑若狂手掣挛挛。，主喉痹。", "白话": "《铜人经》说：“（神门）是手少阴脉气所注之处，为输穴，治疗疟疾心烦甚、想喝冷水、恶寒则想居温暖处、咽干不欲食、心痛频频嗳气恐惧惊悸、气少不足、臂冷、喘逆、身热发狂而悲哭、呕血气少遗尿、大人小儿五痫。”西方子说：“笑如发狂、手牵掣拘挛，主治喉痹。”"}, {"source": "条398｜《普济方》卷八", "原文": "《普济方》卷八：“通里二穴，在腕后一寸陷中。针三分。灸三壮。明堂云。，灸七壮。，主头目眩痛。，悲恐畏人。，肘腕痠酸重。，及暴瘖不能言语。铜人经", "白话": "《普济方》卷八说：“通里二穴，在腕后一寸凹陷中。针三分，灸三壮（明堂说灸七壮）。主治头目眩痛、悲伤恐惧怕见人、肘腕酸重，以及暴瘖不能言语。铜人经……”"}, {"source": "条399｜《铜人经》", "原文": "《铜人经》云。，主热病。，卒心中懊憹。，数欠频伸。，悲恐。，目眩头痛。，面赤而热。，心悸。，肘臑臂痛。，实则皮肿。，虚则不能言。，苦呕喉痹。，少气遗溺。西方子云。，主热病先不乐数日烦心。", "白话": "《铜人经》说：“（通里）主治热病、突发心中懊憹、频频呵欠伸展、悲伤恐惧、目眩头痛、面赤而热、心悸、肘臑臂痛；实则肌肤肿，虚则不能说话，苦于呕吐喉痹、气少遗尿。”西方子说：“主治热病先不乐、数日心烦。”"}, {"source": "条400｜《普济方》卷八", "原文": "《普济方》卷八：“大陵二穴，土也。在掌后两筋间陷中。针五分。，灸三壮。铜人经", "白话": "《普济方》卷八说：“大陵二穴，属土，在掌后两筋间凹陷中。针五分，灸三壮。铜人经……”"}, {"source": "条401｜《铜人经》", "原文": "《铜人经》云。，手厥阴脉之所注也。为腧。治热病汗不出。，臂挛腋肿。，善笑不休。，心悬若饥。，喜悲泣惊恐。，目赤。，小便如血。，呕逆狂言不乐。，喉痹口干。，身热头痛。，短气胸胁痛。西方子云。，主心痛。，咳逆寒热发。，手掣手挛。，及主风热善怒。，心中悲喜。，思慕歔●欷。，喜笑不止。主心下澹澹。主掌中热。，身热如火。，浸淫烦满。舌本痛。主疟乍寒乍热。主咳喘。主呕血。主胸中痛。主痂疥。", "白话": "《铜人经》说：“（大陵）是手厥阴脉气所注之处，为输穴。治疗热病汗不出、臂挛腋肿、喜笑不休、心悬如饥、容易悲泣惊恐、目赤、小便如血、呕逆狂言不乐、喉痹口干、身热头痛、短气胸胁痛。”西方子说：“主治心痛、咳逆寒热发作、手牵掣拘挛；又主治风热善怒、心中悲喜、思慕抽泣（歔欷）、喜笑不止；主治心下澹澹；主治掌中热、身热如火、浸淫烦满、舌根痛；主治疟疾忽冷忽热；主治咳喘；主治呕血；主治胸中痛；主治痂疥。”"}, {"source": "条402｜《普济方》卷八", "原文": "《普济方》卷八：“间使二穴，金也。在掌后三寸两筋间陷中。针三分。灸五壮。明堂下经云。，七壮千金云。，腕后三寸。或云掌后陷中。又云。，主卒狂惊悸。，臂中肿痛。，屈伸难。岐伯云。，主鬼神邪也。铜人经", "白话": "《普济方》卷八说：“间使二穴，属金，在掌后三寸两筋间凹陷中。针三分，灸五壮（明堂下经说七壮；千金说腕后三寸，或说掌后凹陷中）。又说：主治突发狂乱惊悸、臂中肿痛、屈伸困难。岐伯说：主治鬼神邪气之疾。铜人经……”"}, {"source": "条403｜《铜人经》", "原文": "《铜人经》云。，手厥阴脉之所行也为经。治心悬如饥。，卒狂。，胸中澹澹恶风寒。，呕吐怵惕。，寒中少气。，掌中热。，腋肿肘挛。，卒心痛多惊。，瘖不得语。，咽中如鲠。西方子云。，灸七壮。主心胸痹背相引。主嗌中如扼。主肘内廉痛。主热病烦心。喜哕喜动为热。", "白话": "《铜人经》说：“（间使）是手厥阴脉气所行之处，为经穴。治疗心悬如饥、突发狂乱、胸中澹澹而恶风寒、呕吐怵惕、寒中气少、掌中热、腋肿肘挛、突发心痛而多惊、失音不能语、咽中如鲠。”西方子说：“灸七壮。主治心胸痹牵引及背；主治咽中如扼；主治肘内廉痛；主治热病心烦、善哕善动为热。”"}, {"source": "条404｜《普济方》卷八", "原文": "《普济方》卷八：“曲泽二穴，水也。在肘内廉陷中。，屈肘取之。灸三壮。针三分。留七呼。素问注云。，内廉下。铜人经", "白话": "《普济方》卷八说：“曲泽二穴，属水，在肘内廉凹陷中，屈肘取之。灸三壮，针三分，留七呼。《素问》注说：（在）内廉下。铜人经……”"}, {"source": "条405｜《铜人经》", "原文": "《铜人经》云。，厥阴心主脉之所入也。，为合。治心痛善惊。，身热。，烦渴口干。，逆气呕血。，风胗。疹，臂肘手腕善动摇。又云。，主心下澹澹。，时瘛疭喜摇头。，颜清汗出不过肩。，伤寒病温温身热。西方子云。，主呕涎或血。，掣痛手不可伸。", "白话": "《铜人经》说：“（曲泽）是厥阴心主脉气所入之处，为合穴。治疗心痛易惊、身热、烦渴口干、气逆呕血、风疹，臂肘手腕多动摇。”又说：“主治心下澹澹、时时瘛疭喜摇头、面色清冷汗出不过肩、伤寒温病身热。”西方子说：“主治呕涎或呕血、牵掣疼痛手不能伸。”"}, {"source": "条406｜《普济方》卷八", "原文": "《普济方》卷八：“液门二穴，水也。在手小指次指间陷中。针二分。灸三壮一云握拳取之。明堂经云。，主肘痛不能上下。，痎疟寒热。，目涩䀮䀮。，头痛泣出也一作腋门。铜人经", "白话": "《普济方》卷八说：“液门二穴，属水，在手小指与次指之间凹陷中。针二分，灸三壮（一说握拳取之）。明堂经说：主治肘痛不能上下活动、痎疟寒热、目涩䀮䀮不明、头痛流泪（一作‘腋门’）。铜人经……”"}, {"source": "条407｜《铜人经》", "原文": "《铜人经》云。，手少阳脉之所流为荥。治惊悸妄言。，咽外肿。，寒厥手臂痛。，不能自上下。，痎疟寒热。，目眩头痛。，暴得耳聋。，目赤涩。，齿龋痛。西方子云。，主呼吸短气。，咽如息肉状。，面赤热。，病先不乐。，面热无汗。，风寒热。，耳痛鸣聋。", "白话": "《铜人经》说：“（液门）是手少阳脉气所溜之处，为荥穴。治疗惊悸妄言、咽外肿、寒厥手臂痛、手臂不能自主上下、痎疟寒热、目眩头痛、突发耳聋、目赤涩、龋齿痛。”西方子说：“主治呼吸短气、咽中如有息肉状、面赤热、病先不乐、面热无汗、风寒热、耳痛耳鸣耳聋。”"}, {"source": "条408｜《普济方》卷八", "原文": "《普济方》卷八：“天井二穴，土也。在肘外大骨后肘上明堂作后。，一寸两筋间陷中。，屈肘取之。甄权云。，曲肘后一寸。叉手按膝头取之两筋骨罅。针三分。，灸三壮。忌同。明堂云。，五壮。素问注。，刺一寸。千金云。，肘后两筋间。明堂经云。，主肘痛引肩不可屈伸。，颈项及肩背痛。，臂痿不仁。，惊悸悲伤。，痫病羊鸣吐舌也。铜人经", "白话": "《普济方》卷八说：“天井二穴，属土，在肘外大骨后、肘上（明堂作‘后’）一寸两筋间凹陷中，屈肘取之。甄权说：屈肘后一寸，两手交叉按膝头取之两筋骨罅（缝）中。针三分，灸三壮（禁忌同前；明堂说五壮；《素问》注说刺一寸；千金说肘后两筋间）。明堂经说：主治肘痛牵引肩部不能屈伸、颈项及肩背痛、手臂痿弱不仁、惊悸悲伤、痫病羊鸣吐舌。铜人经……”"}, {"source": "条409｜《铜人经》", "原文": "《铜人经》云。，手少阳脉之所入也。，为合。治心胸痛。，咳嗽上气。，唾脓。，不嗜食。，惊悸瘛疭。，风痹。，臂肘痛。，捉物不得。，慎如常法。西方子云。，主大风默默不知所痛。，悲伤不乐。，悲愁恍惚。，疟食时发心痛。主癫疾。，惊掣羊痫戾颈。，肩肉●木。", "白话": "《铜人经》说：“（天井）是手少阳脉气所入之处，为合穴。治疗心胸痛、咳嗽上气、唾脓、不欲食、惊悸瘛疭、风痹、臂肘痛、拿不住东西，谨慎依常法（施治）。”西方子说：“主治大风默默不知所痛、悲伤不乐、悲愁恍惚、疟疾进食时发心痛；主治癫疾、惊掣羊痫而颈项强戾、肩肉（缺字）麻木。”"}, {"source": "条410｜《普济方》卷八", "原文": "《普济方》卷八：“蠡沟二穴，在足内踝上五寸。，别走少阳。针二分。留三呼。灸三壮又云交仪在内踝上五寸陷者中。恐即蠡沟穴。但别出蠡沟。故不同晓。蠡沟亦名交仪。铜人经", "白话": "《普济方》卷八说：“蠡沟二穴，在足内踝上五寸，（络脉）别走少阳。针二分，留三呼，灸三壮。又说：交仪在内踝上五寸凹陷中，恐怕就是蠡沟穴，只是另行分出蠡沟，所以不能明晓（二者之别）。蠡沟又名交仪。铜人经……”"}, {"source": "条411｜《铜人经》", "原文": "《铜人经》云。，足厥阴络。，治卒疝少腹肿。，时少腹暴痛。，小便不利如癃闭。，数噫恐悸。，少气不足。，腹中痛。，悒悒不乐。，咽中闷如有息肉壮。，背拘急不可俛俯仰。西方子云。，主女子赤白淫下。，时多时少。，腹暴刺痛。明堂云。，治卒疝小腹痛。，及妇人漏下赤白。，月水不调。脐下积气如卵石。，足寒胫痠酸。，屈伸难也。又云，。灸七壮。", "白话": "《铜人经》说：“（蠡沟）是足厥阴的络穴，治疗突发疝气少腹肿、时时少腹暴痛、小便不利如癃闭、频作嗳气恐惧惊悸、气少不足、腹中痛、悒悒不乐、咽中闷如有息肉状、背部拘急不能俯仰。”西方子说：“主治女子赤白带下、时多时少、腹部突发刺痛。”明堂说：“治疗突发疝气小腹痛，以及妇人漏下赤白、月经不调、脐下积气如卵石、足冷胫酸、屈伸困难。”又说：灸七壮。"}, {"source": "条412｜《普济方》卷八", "原文": "《普济方》卷八：“通谷二穴，水也。在足小指外侧。，本节前陷中。灸三壮。针二分。铜人经", "白话": "《普济方》卷八说：“通谷二穴，属水，在足小趾外侧、本节前凹陷中。灸三壮，针二分。铜人经……”"}, {"source": "条413｜《铜人经》", "原文": "《铜人经》云。，足太阳脉之所流。，为荥。治头重目眩。，善惊引鼽衄。，颈项痛。，目䀮䀮。甄权云。，结积留饮癖。，胸满食不化。西方子云。，主头痛寒热。，汗出不恶寒。，项如拔。，不可左右顾。，目不明。，恶风寒。，胸胁支满。，心中愤愦数欠。，癫心下悸。，咽中澹澹恐。主心痛鼻鼽清涕。", "白话": "《铜人经》说：“（通谷）是足太阳脉气所溜之处，为荥穴。治疗头重目眩、容易受惊而牵引鼻衄、颈项痛、目䀮䀮不明。”甄权说：“（治）结积留饮癖、胸满饮食不化。”西方子说：“主治头痛寒热、汗出不恶寒、项如被牵拽不能左右回顾、目不明、恶风寒、胸胁胀满、心中昏乱频频呵欠、癫病心下悸、咽中澹澹而恐；主治心痛鼻流清涕。”"}, {"source": "条414｜《普济方》卷八", "原文": "《普济方》卷八：“京骨二穴，在足外侧大骨下。，赤白肉际陷中。，按而得之。针三分。灸三壮。明堂云。，五壮。素问注三壮。明堂云。，灸五壮。主寒疟苦热。，惊悸不欲食。，腿膝痿。，脚挛不得伸。，癫病狂走痰髀枢痛。及胫膝寒也。铜人经", "白话": "《普济方》卷八说：“京骨二穴，在足外侧大骨下、赤白肉际凹陷中，按压而得其处。针三分，灸三壮（明堂说五壮；《素问》注说三壮；明堂又说灸五壮）。主治寒疟而苦于发热、惊悸不欲食、腿膝痿弱、脚拘挛不能伸、癫病狂走、痰流髀枢作痛，以及胫膝发冷。铜人经……”"}, {"source": "条415｜《铜人经》", "原文": "《铜人经》云。，足太阳脉之所过也。，为原。治膝痛不得屈伸。，目内皆赤烂。，发疟寒热。，善惊。，颈项强。，筋挛足●痠酸。，腰背不可俛俯仰，。鼽衄血不止。，目眩。西方子云。，主目中白翳。目反白。从内皆始主头热鼻不利涕。，黄淋沥。，自啮唇。，背恶寒痛。，脚挛足寒。，脊痉反折狂仆。", "白话": "《铜人经》说：“（京骨）是足太阳脉气所过之处，为原穴。治疗膝痛不能屈伸、目内眦红赤糜烂、发疟寒热、容易受惊、颈项强、筋挛足（缺字）酸、腰背不能俯仰、鼻衄血不止、目眩。”西方子说：“主治目中白翳、目反白从内眦开始；主治头热鼻不利涕黄淋沥、自咬唇、背恶寒疼痛、脚挛足冷、脊强反折狂仆。”"}, {"source": "条416｜《普济方》卷八", "原文": "《普济方》卷八：“顶上旋毛中及耳后青络脉。灸各三壮。炷如小麦大。治小儿惊痫。先惊悸啼叫。，后乃发也。", "白话": "《普济方》卷八说：“（小儿惊痫取）头顶旋毛中及耳后青色络脉处，各灸三壮，艾炷如小麦大。治疗小儿惊痫：先惊悸啼叫，然后发作。”"}, {"source": "条417｜《普济方》卷九", "原文": "《普济方》卷九：“治惊悸瘛疭。风痹。臂肘痛。捉物不得。穴天井。", "白话": "《普济方》卷九说：“治疗惊悸、瘛疭、风痹、臂肘疼痛、拿不住东西，取天井穴。”"}, {"source": "条418｜《普济方》卷九", "原文": "《普济方》卷九：“治风痫。青风心风。角弓反张。羊鸣多哭。言语不择。发时即死。吐沫。心热闷。头风多睡。心烦惊悸。无心力。忘前失后。食无味。头重。饮酒面赤。鼻塞。及疗登高而歌。弃衣而走。角弓反张。羊痫吐舌。穴百会。", "白话": "《普济方》卷九说：“治疗风痫、青风、心风、角弓反张、羊鸣多哭、言语不择、发作时即如死、吐沫、心热烦闷、头风多睡、心烦惊悸、无心力、忘前失后、饮食无味、头重、饮酒面赤、鼻塞；又疗登高而歌、弃衣而走、角弓反张、羊痫吐舌。取百会穴。”"}, {"source": "条419｜《普济方》卷九", "原文": "《普济方》卷九：“治风痫。中风角弓反张。或多哭。言语不择。发即无时。盛即吐沫。心烦惊悸。穴百会。", "白话": "《普济方》卷九说：“治疗风痫、中风角弓反张，或多哭、言语不择、发作无定时、病盛即吐沫、心烦惊悸。取百会穴。”"}, {"source": "条420｜《普济方》卷九", "原文": "《普济方》卷九：“治风痫。热病。心风。惊悸。霍乱吐痢。伏梁。气壮如覆杯。穴上脘一穴 三里二穴。", "白话": "《普济方》卷九说：“治疗风痫、热病、心风、惊悸、霍乱吐泻、伏梁（气形状如覆杯）。取上脘一穴、三里二穴。”"}, {"source": "条421｜《普济方》卷九", "原文": "《普济方》卷九：“治肿气风痫癫风。不识人。羊鸣。角弓反张。披发而上歌下哭。多学人语。惊悸不安寝。穴神庭。", "白话": "《普济方》卷九说：“治疗肿气、风痫、癫风、不识人、羊鸣、角弓反张、披发而上歌下哭、多学人说话、惊悸不得安睡。取神庭穴。”"}, {"source": "条422｜《普济方》卷九", "原文": "《普济方》卷九：“治发狂不识人。惊悸少气。穴巨阙。", "白话": "《普济方》卷九说：“治疗发狂不识人、惊悸气少。取巨阙穴。”"}, {"source": "条423｜《普济方》卷九", "原文": "《普济方》卷九：“治惊悸妄言。穴液门。", "白话": "《普济方》卷九说：“治疗惊悸、妄言。取液门穴。”"}, {"source": "条424｜《普济方》卷十", "原文": "《普济方》卷十：“治热病。卒心中懊憹。数欠频伸。悲恐。目眩头痛。面赤而热。心悸肘臂臑痛。实则支肿。虚者不能言。若咽喉痹。少气遗溺。穴通里。", "白话": "《普济方》卷十说：“治疗热病、突发心中懊憹、频频呵欠伸展、悲伤恐惧、目眩头痛、面赤而热、心悸肘臂臑痛；实则肢体肿，虚则不能说话；或咽喉痹、气少遗尿。取通里穴。”"}, {"source": "条425｜《普济方》卷十", "原文": "《普济方》卷十：“治热病烦满。上气心痛。痰冷少气。悲恐善一作喜惊及掌热。胸痛。口热咽痠酸。乍寒乍热。手挛不伸。引眼痛。穴少冲。", "白话": "《普济方》卷十说：“治疗热病烦满、上气心痛、痰冷气少、悲伤恐惧善（一作‘喜’）惊及掌热、胸痛、口热咽酸、忽冷忽热、手挛不能伸、牵引眼痛。取少冲穴。”"}, {"source": "条426｜《普济方》卷十", "原文": "《普济方》卷十：“治伤寒温病。身热烦心。口干心澹善惊。手清。逆气呕唾。肘瘈瘛善摇。头颜清。汗不过肩。穴曲泽。", "白话": "《普济方》卷十说：“治疗伤寒温病、身热心烦、口干、心澹善惊、手冷、气逆呕唾、肘部瘛疭多摇动、头面清冷、汗不过肩。取曲泽穴。”"}, {"source": "条427｜《普济方》卷十", "原文": "《普济方》卷十：“治热病汗不出。臂膊腋肿。喜笑不休。心悬若饥。喜悲泣惊恐。目赤。小便如血。呕逆。狂言不乐。穴大陵。", "白话": "《普济方》卷十说：“治疗热病汗不出、臂膊腋肿、喜笑不休、心悬如饥、容易悲泣惊恐、目赤、小便如血、呕逆、狂言不乐。取大陵穴。”"}, {"source": "条428｜《普济方》卷十", "原文": "《普济方》卷十：“治疟病灸刺法论曰。，足太阳疟。，令人腰痛头重。，寒从背起。，先寒后热。，热止汗出难已。刺郄中出血。足少阳疟。，令人身体解㑊。，寒不甚。，热不甚恶。，恶人见人。，心惕惕然。，热多汗。，刺足少阳。，足阳明疟。，令人先寒。，洒淅寒甚。，久乃热。，热去汗出。，喜见日光火气乃快然。，刺足阳明脚趺上。足太阴疟。，令人不乐。，好太息。，不嗜饮食。，多寒热。，汗出病至。，则呕。，呕已乃衰。", "白话": "《普济方》卷十说：“治疟病灸刺法之论说道：足太阳疟，使人腰痛头重，寒从背起，先寒后热，热退则汗出，难以速已，刺郄中（委中）出血；足少阳疟，使人身体懈怠无力，寒不太甚，热也不太甚，厌恶见人，心惕惕然（惊惧），热多汗多，刺足少阳（经）；足阳明疟，使人先寒，洒淅寒甚，久后才热，热退汗出，喜见日光与火气才觉爽快，刺足阳明脚背上（冲阳）；足太阴疟，使人不乐、好太息、不欲饮食、多寒热，汗出而病来，则呕吐，呕止则病衰。”"}, {"source": "条429｜《普济方》卷十一", "原文": "《普济方》卷十一：“治寒热头痛。进退痎疟。恍惚悲愁。健忘惊悸。穴神道。", "白话": "《普济方》卷十一说：“治疗寒热头痛、进退痎疟、恍惚悲愁、健忘惊悸。取神道穴。”"}, {"source": "条430｜《普济方》卷十一", "原文": "《普济方》卷十一：“治脑风头痛不可忍。目瞑心悸。发即为癫风。引目眇。穴脑空。", "白话": "《普济方》卷十一说：“治疗脑风头痛不可忍受、闭目不欲开、心悸，发作即成癫风，牵引目视昏眇。取脑空穴。”"}, {"source": "条431｜《普济方》卷十二", "原文": "《普济方》卷十二：“治中风心烦。惊悸健忘。穴百会。", "白话": "《普济方》卷十二说：“治疗中风心烦、惊悸健忘。取百会穴。”"}, {"source": "条432｜《普济方》卷十二", "原文": "《普济方》卷十二：“主心悸少力。穴大横。灸五十壮。", "白话": "《普济方》卷十二说：“主治心悸、气力不足。取大横穴，灸五十壮。”"}, {"source": "条433｜《普济方》卷十二", "原文": "《普济方》卷十二：“治无心力。忘前失后。穴百会。王氏云。，予旧患心气。，凡思虑过多。，心下怔忡。，或至自悲感慨。，必灸百会。则以百会有治无心力忘前失后证故也兼服镇心丹。", "白话": "《普济方》卷十二说：“治疗无心力、忘前失后，取百会穴。”王氏说：“我旧时患心气（病），凡思虑过多，就心下怔忡，甚至自己悲伤感慨，必定灸百会——因为百会能治无心力、忘前失后之证的缘故；兼服镇心丹。”"}, {"source": "条434｜《普济方》卷十二", "原文": "《普济方》卷十二：“治心如悬。少气不足以息。穴然谷。", "白话": "《普济方》卷十二说：“治疗心如悬空感、气少不足以息。取然谷穴。”"}, {"source": "条435｜《普济方》卷十二", "原文": "《普济方》卷十二：“治卒痛烦心。心中懊憹。数欠频伸。心下悸悲。穴通理。", "白话": "《普济方》卷十二说：“治疗突发疼痛心烦、心中懊憹、频频呵欠伸展、心下悸动悲伤。取通理（通里）穴。”"}, {"source": "条436｜《普济方》卷十二", "原文": "《普济方》卷十二：“治心如悬下痛。穴大陵。", "白话": "《普济方》卷十二说：“治疗心如悬空感而下部作痛。取大陵穴。”"}, {"source": "条437｜《普济方》卷十二", "原文": "《普济方》卷十二：“治心风惊悸。穴上脘。", "白话": "《普济方》卷十二说：“治疗心风、惊悸。取上脘穴。”"}, {"source": "条438｜《普济方》卷十二", "原文": "《普济方》卷十二：“治惊悸少气。穴神门、蠡沟、巨阙。", "白话": "《普济方》卷十二说：“治疗惊悸、气少。取神门、蠡沟、巨阙三穴。”"}, {"source": "条439｜《普济方》卷十二", "原文": "《普济方》卷十二：“疗惊悸。穴间使。", "白话": "《普济方》卷十二说：“治疗惊悸。取间使穴。”"}, {"source": "条440｜《普济方》卷十二", "原文": "《普济方》卷十二：“治惊恐。穴五里。", "白话": "《普济方》卷十二说：“治疗惊恐。取五里穴。”"}, {"source": "条441｜《普济方》卷十二", "原文": "《普济方》卷十二：“治善惊恐。穴京骨、大钟、大陵。", "白话": "《普济方》卷十二说：“治疗容易惊恐。取京骨、大钟、大陵三穴。”"}, {"source": "条442｜《普济方》卷十二", "原文": "《普济方》卷十二：“治惊悸。穴百会、神道、天井、液门。", "白话": "《普济方》卷十二说：“治疗惊悸。取百会、神道、天井、液门四穴。”"}, {"source": "条443｜《普济方》卷十二", "原文": "《普济方》卷十二：“治风虚惊恐狂惕。又疗惊恐悲愁。穴支正。", "白话": "《普济方》卷十二说：“治疗风虚惊恐、狂而惊惕；又疗惊恐悲愁。取支正穴。”"}, {"source": "条444｜《普济方》卷十二", "原文": "《普济方》卷十二：“治惊恐畏人。穴郄门。", "白话": "《普济方》卷十二说：“治疗惊恐、怕见人。取郄门穴。”"}, {"source": "条593｜《针方六集》卷五", "原文": "《针方六集》卷五：“液门二穴，主惊悸妄言，咽外肿，臂痛不能自上下，痎疟寒热，目赤涩，头痛，耳暴聋，齿暴痛，五指无力。手背红肿宜此出血；四肢肿满，宜此出水。", "白话": "液门两穴，主治惊悸、妄言，咽外肿痛，臂痛不能上下举动，痎疟寒热，目赤干涩，头痛，暴发耳聋，暴发牙痛，五指无力。手背红肿宜在此穴出血；四肢肿满宜在此穴出水。"}, {"source": "条594｜《针方六集》卷五", "原文": "《针方六集》卷五：“天井二穴，主心胸痛，咳嗽上气，短气不得语，唾脓，不嗜食，寒热凄凄不得卧，惊悸，癫痫瘛疭，风痹肘臂痛不能屈伸，耳聋嗌肿，喉痹，目锐眦痛，颊肿，耳后痛，瘰疬肿痛。", "白话": "天井两穴，主治心胸痛，咳嗽上气，短气说不出话，吐脓，不思饮食，寒热凄凄不得安卧，惊悸，癫痫瘛疭，风痹肘臂疼痛不能屈伸，耳聋咽肿，喉痹，目外眦痛，颊肿，耳后痛，瘰疬肿痛。"}, {"source": "条595｜《针方六集》卷五", "原文": "《针方六集》卷五：“蠡沟二穴，主五噎，喉中闭塞如有息肉，肩背拘急不可俯仰，数噫恐悸，少气不足以息，悒悒不乐，小腹胀满，暴痛如有癃闭，脐下积气如石，睾丸卒痛，内引少腹，足胫寒酸，屈伸不便。女子赤白带下，月水不调，阴挺暴痒。", "白话": "蠡沟两穴，主治五噎，喉中闭塞如有息肉，肩背拘急不能俯仰，频嗳气、恐惧心悸，少气不足以息，悒悒不乐，小腹胀满，暴痛如有癃闭，脐下积气如石，睾丸突然疼痛、上引少腹，足胫寒酸，屈伸不便。女子赤白带下，月经不调，阴挺暴痒。"}, {"source": "条596｜《针方六集》卷五", "原文": "《针方六集》卷五：“肓俞二穴，主善饥不欲食，心如悬，腹大，时切痛，寒疝，大便燥，心下有寒，目赤痛从内眦始。", "白话": "肓俞两穴，主治善饥却不想吃，心如悬空，腹大，时时剧痛，寒疝，大便燥结，心下有寒，目赤痛从内眼角开始。"}, {"source": "条597｜《针方六集》卷六", "原文": "《针方六集》卷六：“百劳止虚汗，通里疗心惊而立愈。", "白话": "百劳穴止虚汗，通里穴疗心惊而立刻痊愈。"}, {"source": "条598｜《针方六集》卷六", "原文": "《针方六集》卷六：“连月虚烦面赤妆，心中惊惧亦难当，通里奇穴如寻得，金针一试即安康。　通里：穴在腕后一寸。针入五分，泻，禁灸。应穴心俞。治惊惧怔忡。", "白话": "连月虚烦、面红如妆，心中惊惧也难以承受；通里这个奇穴若能找到，金针一试即安康。通里：穴在腕后一寸。针入五分，用泻法，禁灸。应穴是心俞。治惊惧怔忡。"}, {"source": "条599｜《针方六集》卷六", "原文": "《针方六集》卷六：“申脉能除寒与热，头风偏正及心惊。", "白话": "申脉能祛除寒热、偏正头风以及心惊。"}, {"source": "条600｜《针方六集》卷六", "原文": "《针方六集》卷六：“通里腕骨后，一寸五分中，欲言声不出，懊憹及怔忡，实则四肢重，头腮面颊红，虚则不能食，暴喑面无容，毫针微微刺，方信有神功。", "白话": "通里在腕骨后一寸五分之中；欲言语而声音不出，懊憹及怔忡；实证则四肢沉重、头腮面颊红；虚证则不能食、暴喑面无华；毫针微微刺之，方信有神功。"}, {"source": "条601｜《类经》卷二十一", "原文": "《类经》卷二十一：“癫疾始作而引口啼呼喘悸者，候之手阳明、太阳，左强者攻其右，右强者攻其左，血变而止。引口者，牵引歪斜也。或为啼呼，或为喘悸，当候于手阳明太阳二经，察病所在而刺之穴如前。强，坚强也。左右牵引，病多在络，故左强者当攻右，右强者当攻左，必候其血变而止，此缪刺之法也。悸音匮，心动也。", "白话": "癫疾开始发作而口眼牵引、啼呼喘悸的，诊候手阳明、手太阳，左侧强急的攻其右，右侧强急的攻其左，血色变了为止。张介宾注：引口，是牵引歪斜。或作啼呼，或作喘悸，当诊候手阳明、太阳二经，察病所在而刺，取穴如前。强，是坚强。左右牵引，病多在络，所以左强的当攻右、右强的当攻左，必候其血变而止，这是缪刺之法。悸音匮，心动也。"}, {"source": "条602｜《类经》卷二十一", "原文": "《类经》卷二十一：“热病嗌干多饮、善惊悸、肢体倦怠、卧不能起者，邪在肤肉，脾经病也。当用第六针曰员利针者，以取五十九穴之肉分也。若目眦青者，正以木气乘土，亦为脾病。脾属土，其合在肉，故但求之于肉，即所以求于脾也。若求脾而不得效者，则当求之于木，木者肝也，补肝筋之气，则木能胜土，而脾热当自平矣。嗌音益。", "白话": "热病咽干多饮、易惊悸、肢体倦怠、卧不能起的，邪在肤肉，是脾经病。当用第六针即员利针，以取五十九穴的肉分。若目眦发青，正是木气乘土，也属脾病。脾属土，其合在肉，所以只求之于肉，就是求之于脾。若求脾而不见效，则当求之于木，木即肝，补肝筋之气，则木能胜土，脾热自当平。嗌音益。"}, {"source": "条603｜《类经》卷二十七", "原文": "《类经》卷二十七：“阴痹者按之不得，腰脊头项痛，时眩，大便难，阴气不用，饥不欲食，咳唾则有血，心如悬，病本于肾，胕肿骨痛等证，皆肾经病也。按经脉篇以腰脊头项痛，为足太阳膀胱病，以饥不欲食，咳唾则有血、心如悬，为足少阴肾病。此以肾与膀胱为表里，水为土克，故诸病皆本于肾也。五邪篇阴痹，与此略同，详针刺类二十五。", "白话": "阴痹者按之无定处，腰脊头项痛，时时眩晕，大便难，阴气不用，饥不欲食，咳唾带血，心如悬——病本于肾；浮肿骨痛等证，都是肾经病。按《经脉篇》以腰脊头项痛为足太阳膀胱病，以饥不欲食、咳唾有血、心如悬为足少阴肾病。此因肾与膀胱为表里，水被土克，所以诸病都本于肾。《五邪篇》阴痹与此略同，详见针刺类二十五。"}, {"source": "条604｜《类经图翼》卷六", "原文": "《类经图翼》卷六：“阳溪一名中魁，在手腕中上侧，两筋间陷中。手阳明所行为经。刺三分，留七呼，灸三壮。主治狂言喜笑见鬼，热病烦心，掌中热，汗不出，目赤烂翳，厥逆头痛，胸满不得息，寒热痰疟呕沫，喉痹耳鸣齿痛，惊掣肘臂不举，痂疥。席弘赋云：兼二间，治牙疼腰痛喉痹。百证赋云：兼解溪，治惊悸怔忡。", "白话": "阳溪穴，又名中魁，在手腕背侧上方、两筋之间的凹陷中。为手阳明大肠经所行的经穴。针刺三分深，留针七呼，灸三壮。主治狂言妄语、喜笑无常、如见鬼神，热病心烦，掌心发热，汗不出，目赤烂生翳，厥逆头痛，胸满呼吸不利，寒热痰疟、呕吐涎沫，喉痹、耳鸣、牙痛，惊风抽掣、肘臂不能抬举，痂疥诸疮。《席弘赋》说：配二间穴，治牙痛、腰痛、喉痹。《百证赋》说：配解溪穴，治惊悸怔忡。"}, {"source": "条605｜《类经图翼》卷七", "原文": "《类经图翼》卷七：“液门，在手小指次指间陷者中。手少阳所溜为荥。刺二分，留二呼，灸三壮。主治惊悸忘言，寒厥，臂痛不得上下，痎疟寒热头痛，目眩赤涩泣出，耳暴聋，咽外肿，牙龈痛，若手臂红肿痛楚，泻之出血为妙。", "白话": "液门穴，在手小指与无名指之间的凹陷中。为手少阳三焦经所溜的荥穴。针刺二分深，留针二呼，灸三壮。主治惊悸、健忘失语，寒厥，臂痛、不能上下举动，痎疟寒热头痛，目眩、目赤干涩流泪，突发耳聋，咽外肿痛，牙龈疼痛。若手臂红肿疼痛，用泻法出血为好。"}, {"source": "条606｜《类经图翼》卷八", "原文": "《类经图翼》卷八：“脑空一名颞颥，在承灵后一寸五分，夹玉枕骨下陷中。气府论王氏注曰：夹枕骨后枕骨上。足少阳阳维之会。刺四分，灸五壮。主治劳瘵身热羸瘦，脑风头痛不可忍，项强不得顾，目瞑鼻衄耳聋，惊悸癫风，引目眇鼻痛。昔魏公苦患头风，发即心乱目眩，华佗刺此立愈。", "白话": "脑空穴，又名颞颥，在承灵穴后一寸五分、玉枕骨两侧的凹陷中。《气府论》王冰注说：夹枕骨之后、枕骨之上。为足少阳胆经与阳维脉的交会穴。针刺四分深，灸五壮。主治劳瘵、身热消瘦，脑风头痛不可忍受，颈项强急不能回头，闭目、鼻出血、耳聋，惊悸、癫风，牵引目视不明、鼻痛。昔日魏公苦患头风，一发作即心乱目眩，华佗刺此穴立即痊愈。"}, {"source": "条607｜《类经图翼》卷八", "原文": "《类经图翼》卷八：“上脘，在巨阙下一寸五分，去蔽骨三寸，脐上五寸。足阳明手太阳任脉之会。刺八分，留七呼，灸五壮。千金云：日灸二七壮至百壮，三报之。孕妇不可灸。主治心中烦热，痛不可忍，腹中雷鸣，饮食不化，霍乱翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸心风，惊悸呕血，身热汗不出。", "白话": "上脘穴，在巨阙穴下一寸五分，距蔽骨三寸，脐上五寸。为足阳明胃经、手太阳小肠经与任脉的交会穴。针刺八分深，留针七呼，灸五壮。《千金方》说：每日灸二七壮至百壮，三次报灸。孕妇不可灸。主治心中烦热、疼痛不可忍受，腹中雷鸣，饮食不化，霍乱、翻胃呕吐，三焦多涎，奔豚、伏梁，气胀积聚，黄疸、心风，惊悸呕血，身热汗不出。"}, {"source": "条608｜《类经图翼》卷八", "原文": "《类经图翼》卷八：“鸠尾一名●骭，一名尾翳 在臆前蔽骨下五分。人无蔽骨者，从岐骨歧骨际下行一寸。《甲乙经》曰：一寸半。膏之原也。禁刺灸。一云可刺三分，灸三壮。此穴大难下针，非甚妙高手，不可轻刺也。主治心惊悸，神气耗散，癫痫狂病。", "白话": "鸠尾穴，又名●骭（原稿首字缺脱），又名尾翳，在胸前蔽骨之下五分处。没有蔽骨的人，从岐骨分叉处下行一寸即是。《甲乙经》说：一寸半。为膏之原。禁刺禁灸。一说可针刺三分深，灸三壮。此穴极难下针，非手法高妙的医家，不可轻率针刺。主治心惊悸动、神气耗散、癫痫狂病。"}, {"source": "条609｜《甲乙经》", "原文": "《类经图翼》卷八：“鸠尾一名●骭，一名尾翳 在臆前蔽骨下五分。人无蔽骨者，从岐骨歧骨际下行一寸。《甲乙经》曰：一寸半。膏之原也。禁刺灸。一云可刺三分，灸三壮。此穴大难下针，非甚妙高手，不可轻刺也。主治心惊悸，神气耗散，癫痫狂病。", "白话": "（句译见条608。）本处《甲乙经》引作鸠尾定位“一寸半”之异说。"}, {"source": "条610｜《类经图翼》卷八", "原文": "《类经图翼》卷八：“风府一名舌本，在项上入发际一寸，大筋内宛宛中。疾言其肉立起，言休其肉立下。督脉阳维之会。《热论》曰：巨阳者，诸阳之属也，其脉连于风府。刺三分，留三呼，禁灸，灸则令人喑。主治中风舌缓，暴喑不语，振寒汗出，身重，偏风半身不遂，伤风头痛项急，不得回顾，目眩反视，鼻衄咽痛，狂走悲恐惊悸欲自杀。一云主泻胸中之热，与大杼、缺盆、中府同。", "白话": "风府穴，又名舌本，在项后入发际一寸、大筋内侧的凹陷中。快说话时该处肌肉立即凸起，话停则肌肉立即落下。为督脉与阳维脉的交会穴。《热论》说：巨阳（太阳）为诸阳之所属，其脉上连于风府。针刺三分深，留针三呼，禁灸，灸之使人失音。主治中风舌体弛缓，突然失音不语，恶寒战栗、汗出，身体沉重，偏风半身不遂，伤风头痛、颈项强急、不能回顾，目眩、目上视，鼻出血、咽痛，狂走、悲伤恐惧、惊悸欲自杀。一说主泻胸中之热，与大杼、缺盆、中府诸穴相同。"}, {"source": "条611｜《热论》", "原文": "《类经图翼》卷八：“风府一名舌本，在项上入发际一寸，大筋内宛宛中。疾言其肉立起，言休其肉立下。督脉阳维之会。《热论》曰：巨阳者，诸阳之属也，其脉连于风府。刺三分，留三呼，禁灸，灸则令人喑。主治中风舌缓，暴喑不语，振寒汗出，身重，偏风半身不遂，伤风头痛项急，不得回顾，目眩反视，鼻衄咽痛，狂走悲恐惊悸欲自杀。一云主泻胸中之热，与大杼、缺盆、中府同。", "白话": "（句译见条610。）本处《热论》引“巨阳者，诸阳之属也，其脉连于风府”，以证风府为诸阳所会。"}, {"source": "条612｜《类经图翼》卷八", "原文": "《类经图翼》卷八：“百会一名三阳五会，一名巅颠上，一名天满，在前顶后一寸五分，顶中央旋毛心，容豆许，直两耳尖，上对是穴。督脉足太阳之会，手足少阳足厥阴俱会于此。刺二分，灸五壮。《甲乙经》曰：刺三分，灸三壮。一曰灸头顶，不得过七七壮。主治头风头痛，耳聋鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张，吐沫心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫惊风，脱肛", "白话": "百会穴，又名三阳五会、巅上、天满，在前顶穴后一寸五分，头顶中央旋毛凹陷中，约容一豆，与两耳尖直对之处即是。为督脉与足太阳之会，手足少阳、足厥阴也都交会于此。针刺二分深，灸五壮。《甲乙经》说：针刺三分深，灸三壮。一说灸头顶，不可超过七七壮。主治头风头痛，耳聋、鼻塞、鼻出血，中风语言蹇涩，口噤不开，或多悲伤哭泣，偏风半身不遂，风痫猝厥，角弓反张，吐沫、心神恍惚，惊悸健忘，痎疟，妇女血风，胎前产后风疾，小儿风痫惊风，脱肛久治不愈。一说百病皆治，宜针刺二分，得气即用泻法；若灸至百壮，"}, {"source": "条613｜《甲乙经》", "原文": "《类经图翼》卷八：“百会一名三阳五会，一名巅颠上，一名天满，在前顶后一寸五分，顶中央旋毛心，容豆许，直两耳尖，上对是穴。督脉足太阳之会，手足少阳足厥阴俱会于此。刺二分，灸五壮。《甲乙经》曰：刺三分，灸三壮。一曰灸头顶，不得过七七壮。主治头风头痛，耳聋鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张，吐沫心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫惊风，脱肛", "白话": "（句译见条612。）本处《甲乙经》引作百会针灸剂量“刺三分，灸三壮”之异说。"}, {"source": "条614｜《类经图翼》卷八", "原文": "《类经图翼》卷八：“神庭，直鼻上入发际五分，发高者发际是穴，发低者加二三分。督脉足太阳阳明之会。灸三壮，禁刺，刺之令人癫狂目失明。一曰灸七壮至三七壮止。主治发狂登高妄走，风痫癫疾，角弓反张，目上视不识人，头风鼻渊，流涕不止，头痛目泪，烦满喘喝，惊悸不得安寝。", "白话": "神庭穴，在鼻直上入发际五分处；发际高的以发际为穴，发际低的再加二三分。为督脉与足太阳、足阳明之会。灸三壮，禁刺，刺之令人癫狂、目失明。一说灸七壮至三七壮为止。主治发狂登高乱走，风痫癫疾，角弓反张，目上视不识人，头风鼻渊、流涕不止，头痛流泪，心烦满闷、喘息有声，惊悸不得安睡。"}, {"source": "条615｜《类经图翼》卷八", "原文": "《类经图翼》卷八：“蠡沟一名交仪，在足内踝上五寸。足厥阴络，别走少阳。刺二分，留三呼，灸三壮。主治疝痛，小腹满痛，癃闭脐下积气如石，数噫，恐悸少气，足胫寒痠酸，屈伸难，腰背拘急，不可俛俯仰，月经不调，溺下赤白。", "白话": "蠡沟穴，又名交仪，在足内踝上五寸。为足厥阴肝经之络穴，别走足少阳。针刺二分深，留针三呼，灸三壮。主治疝痛、小腹胀满疼痛，小便癃闭、脐下积气如石，频作嗳气，恐惧心悸、气短，足胫寒冷酸痛、屈伸困难，腰背拘急、不能俯仰，月经不调，小便下赤白浊物。"}, {"source": "条616｜《类经图翼》卷八", "原文": "《类经图翼》卷八：“胆经有病口作苦，忽听惊响悸必多，妙法推脾清肾水，阴阳穴上要频搓。", "白话": "胆经有病则口中发苦，忽听惊响、心悸必多；妙法在于推补脾土、清泻肾水，在阴阳穴位上须频频搓揉。"}, {"source": "条617｜《病机沙篆》卷下", "原文": "《病机沙篆》卷下：“小儿急慢惊痫，切不可执持，其发搐又不可混灸，愚谓风痫可灸，惊热不可灸，风痫之痰，若灸着穴，痰去心清，可渐安矣。每见人无术，辄投艾火，不惟唯失穴，儿反增悸，且小儿经络脉道未全，戒之。", "白话": "小儿急慢惊痫，切不可把持，其发搐又不可混灸。我以为风痫可灸，惊热不可灸；风痫之痰，若灸着穴位，痰去心清，可渐安。每见人无术，辄投艾火，不惟失穴，小儿反增心悸，且小儿经络脉道未全，切戒。"}, {"source": "条618｜《病机沙篆》卷下", "原文": "《病机沙篆》卷下：“心中虚惕，神思不安，胆俞、心俞、内关、通里。怔忡健忘不寐，手少阴心虚，内关针五分灸三壮，神门针三分灸二七壮，少海针一分。", "白话": "心中虚惕、神思不安，取胆俞、心俞、内关、通里。怔忡、健忘、不寐，属手少阴心虚：内关针五分、灸三壮，神门针三分、灸二七壮，少海针一分。"}, {"source": "条619｜《勉学堂针灸集成》卷二", "原文": "《勉学堂针灸集成》卷二：“惊悸不得眠，取阴交。不得卧，取浮郗。《甲乙》", "白话": "惊悸不得眠，取阴交。不得卧，取浮郗。《甲乙》"}, {"source": "条620｜《甲乙》", "原文": "《勉学堂针灸集成》卷二：“惊悸不得眠，取阴交。不得卧，取浮郗。《甲乙》", "白话": "（句译见条619。）本处《甲乙》为所引取穴出处（阴交、浮郄条）。"}, {"source": "条621｜《勉学堂针灸集成》卷三", "原文": "《勉学堂针灸集成》卷三：“阳溪，在手腕横纹上侧两筋间陷中、直合谷。针三分、留七呼，灸三壮。主治狂言喜笑见鬼，热病烦心，掌中热，汗不出，目赤烂翳，厥逆头痛，胸满不得息，寒热痰疟，呕沫，喉痹，耳鸣，齿痛，惊掣，肘臂不举，痂疥。兼二间，治牙疼、腰痛、喉痹。《席弘赋》 兼解溪，治惊悸怔忡；兼肩髃，能消瘾风之热极。《百证赋》", "白话": "阳溪穴，在手腕横纹上侧、两筋之间的凹陷中，与合谷穴直对。针刺三分深，留针七呼，灸三壮。主治狂言妄语、喜笑无常、如见鬼神，热病心烦，掌中发热，汗不出，目赤烂生翳，厥逆头痛，胸满呼吸不利，寒热痰疟，呕吐涎沫，喉痹，耳鸣，牙痛，惊风抽掣，肘臂不能抬举，痂疥。配二间穴，治牙痛、腰痛、喉痹（《席弘赋》）；配解溪穴，治惊悸怔忡；配肩髃穴，能消除瘾风之热极（《百证赋》）。"}, {"source": "条622｜《席弘赋》", "原文": "《勉学堂针灸集成》卷三：“阳溪，在手腕横纹上侧两筋间陷中、直合谷。针三分、留七呼，灸三壮。主治狂言喜笑见鬼，热病烦心，掌中热，汗不出，目赤烂翳，厥逆头痛，胸满不得息，寒热痰疟，呕沫，喉痹，耳鸣，齿痛，惊掣，肘臂不举，痂疥。兼二间，治牙疼、腰痛、喉痹。《席弘赋》 兼解溪，治惊悸怔忡；兼肩髃，能消瘾风之热极。《百证赋》", "白话": "（句译见条621。）本处《席弘赋》引“兼二间，治牙疼腰痛喉痹”之配穴说。"}, {"source": "条623｜《百证赋》", "原文": "《勉学堂针灸集成》卷三：“阳溪，在手腕横纹上侧两筋间陷中、直合谷。针三分、留七呼，灸三壮。主治狂言喜笑见鬼，热病烦心，掌中热，汗不出，目赤烂翳，厥逆头痛，胸满不得息，寒热痰疟，呕沫，喉痹，耳鸣，齿痛，惊掣，肘臂不举，痂疥。兼二间，治牙疼、腰痛、喉痹。《席弘赋》 兼解溪，治惊悸怔忡；兼肩髃，能消瘾风之热极。《百证赋》", "白话": "（句译见条621。）本处《百证赋》引“兼解溪，治惊悸怔忡”之配穴说。"}, {"source": "条624｜《刺灸心法要诀》卷一", "原文": "《刺灸心法要诀》卷一：“心包里之原穴大陵，三焦表之络穴外关，二穴应刺之证即：面红目赤，好笑不休，心中动悸，内热，手心热，胸腋与臂手疼痛。皆心包络、三焦经病也。", "白话": "心包里之原穴大陵、三焦表之络穴外关，两穴应刺之证即：面红目赤，好笑不休，心中动悸，内热，手心热，胸腋与臂手疼痛。这都是心包络、三焦经的病。"}, {"source": "条625｜《刺灸心法要诀》卷一", "原文": "《刺灸心法要诀》卷一：“九种心疼病不宁，结胸翻胃食难停，酒食积聚肠鸣见，水食气疾膈脐疼，腹痛胁胀胸膈满，疟疾肠风大便红，胎衣不下血迷心，急刺公孙穴自灵。【注】九种心疼者：曰饮、曰食、曰风、曰冷、曰热、曰悸、曰虫、曰注、曰去来痛。结胸者，胸满硬痛也。翻胃者，朝食暮吐，食难停留也。伤酒，伤食，积滞，肠胃雷鸣，水食，气疾，膈间脐腹疼痛，两肋作胀，胸膈满闷，疟疾肠风，大便下血，以及妇人胞衣不下，瘀血上攻迷", "白话": "九种心疼诸病令人不得安宁，结胸、翻胃饮食难停，酒食积滞、肠鸣，水食气疾、膈间脐腹疼痛，腹痛胁胀、胸膈满闷，疟疾肠风、大便下血，胞衣不下、瘀血攻心迷乱，急刺公孙穴自见灵效。【注】所谓九种心疼是：饮痛、食痛、风痛、冷痛、热痛、悸痛、虫痛、注痛、去来痛。结胸，指胸中满闷硬痛。翻胃，指朝食暮吐、饮食难以停留。伤酒、伤食、积滞、肠胃雷鸣、水饮、气疾、膈间脐腹疼痛、两胁作胀、胸膈满闷、疟疾肠风、大便下血，以及妇人胞衣不下、瘀血上攻迷心，都宜刺公孙穴，则立即效应。"}, {"source": "条626｜《刺灸心法要诀》卷七", "原文": "《刺灸心法要诀》卷七：“胆俞主灸胁满呕，惊悸卧睡不能安，兼灸酒疸目黄色，面发赤斑灸自痊。【注】胆俞穴，主治两胁胀满，干呕，惊悸，睡卧不安及酒疸，目睛发黄，面发赤斑等证。灸三壮，禁针。", "白话": "胆俞主灸两胁胀满、呕吐，惊悸睡卧不能安；兼灸酒疸目黄，面发赤斑，灸之自愈。【注】胆俞穴主治两胁胀满、干呕、惊悸、睡卧不安，以及酒疸、目睛发黄、面发赤斑等证。灸三壮，禁针。"}, {"source": "条627｜《刺灸心法要诀》卷七", "原文": "《刺灸心法要诀》卷七：“解溪主治风水气，面腹足肿喘嗽频，气逆发噎头风眩，悲泣癫狂悸与惊。【注】解溪穴，主治风气面浮，腹胀，足肿，喘满，咳嗽，气逆发噎，头痛，目眩，悲泣癫狂，惊悸，怔忡等证。针五分，留五呼，灸三壮。", "白话": "解溪主治风水气肿：面部腹部足部浮肿、喘嗽频作，气逆发噎、头风眩晕，悲伤哭泣、癫狂、心悸惊恐。【注】解溪穴主治风气面浮、腹胀、足肿、喘满咳嗽、气逆发噎、头痛目眩、悲泣癫狂、惊悸怔忡等证。针刺五分深，留针五呼，灸三壮。"}, {"source": "条628｜《刺灸心法要诀》卷七", "原文": "《刺灸心法要诀》卷七：“膏肓一穴灸劳伤，百损诸虚无不良，此穴禁针惟唯宜艾，千金百壮效非常。【注】膏肓穴，主治诸虚百损，五劳七伤，身形羸瘦，梦遗失精，上气咳逆，痰火发狂，健忘，怔忡，胎前、产后劳瘵、传尸等证。灸七七壮至百壮。", "白话": "膏肓一穴灸治劳伤，百损诸虚无所不宜；此穴禁针、只宜艾灸，灸千金百壮，效验非常。【注】膏肓穴主治诸虚百损、五劳七伤、形体消瘦、梦遗失精、上气咳逆、痰火发狂、健忘、怔忡，以及胎前产后劳瘵、传尸等证。灸七七壮至百壮。"}, {"source": "条629｜《刺灸心法要诀》卷八", "原文": "《刺灸心法要诀》卷八：“通里腕侧后，去腕一寸中。欲言声不出，懊憹及怔忡，实则四肢重，头腮面颊红，声平仍数欠，喉痹气难通，虚则不能食，暴喑面无容，毫针微微刺，方信有神功。【注】通里穴，其穴在腕侧后一寸陷中。主治声哑，心烦极甚，怔忡不宁，四肢重痛，头腮面颊红肿，倦言，数欠，喉咽疼痛，气息不通，虚损不思食，暴喑面无润泽。针三分，灸三壮。", "白话": "通里在腕侧之后、距腕一寸处。欲说话而声音不出，心中懊憹及怔忡；实证则四肢沉重、头腮面颊发红，声音虽平仍频作呵欠，喉痹气息难通；虚证则不能饮食、突然失音、面容无华。用毫针微微刺之，方信其有神功。【注】通里穴在腕侧后一寸凹陷中。主治声音嘶哑、心烦极甚、怔忡不宁、四肢重痛、头腮面颊红肿、懒言、频作呵欠、喉咽疼痛、气息不通、虚损不思饮食、暴喑面容无润泽。针刺三分深，灸三壮。"}, {"source": "条630｜《灵枢悬解》卷九", "原文": "《灵枢悬解》卷九：“悸者，心下动也。癫狂之病，皆生惊悸，胆木失根，惊悸乃作，实则为狂，虚则为癫也。左强攻右，右强攻左，所谓缪刺也。", "白话": "悸，是心下动。癫狂之病，都生于惊悸；胆木失根，则惊悸乃作；实则为狂，虚则为癫。左强攻右，右强攻左，所谓缪刺也。"}, {"source": "条631｜《针灸易学》卷上", "原文": "《针灸易学》卷上：“其十一：通里腕侧后，去腕一寸中。欲言声不出，懊恼及怔忡，实则四肢重，头腮面颊红，虚则不能食，暴喑面无容，毫针微微刺，方信有神功针三分，灸三壮。", "白话": "其十一：通里在腕侧之后、距腕一寸处。欲说话而声音不出，心中懊恼及怔忡；实证则四肢沉重、头腮面颊发红，虚证则不能饮食、突然失音、面容无华。用毫针微微刺之，方信有神功。针刺三分深，灸三壮。"}, {"source": "条632｜《金匮启钥眼科》卷一", "原文": "《金匮启钥眼科》卷一：“神庭 直鼻上入发际五分，发高者发际是穴，发低者加二三分。督脉、足太阳、阳明之会。灸三壮，禁刺，刺之令人癫狂面肿目失明，一曰灸七壮，至三七壮止。主治发狂，登高妄走，风痫癫疾，角弓反张，目上视，不认人，头风鼻渊，流涕不止，头痛目泪，烦满，喘渴，悸不得安寝。", "白话": "神庭穴，在鼻直上入发际五分处；发际高的以发际为穴，发际低的再加二三分。为督脉、足太阳、足阳明之会。灸三壮，禁刺，刺之令人癫狂、面肿、目失明。一说灸七壮，至三七壮为止。主治发狂登高乱走，风痫癫疾，角弓反张，目上视、不认人，头风鼻渊、流涕不止，头痛流泪，烦满，喘渴，心悸不得安睡。"}, {"source": "条633｜《灵素节注类编》卷六", "原文": "《灵素节注类编》卷六：“足少阳之疟，令人身体解㑊，寒不甚，热不甚，恶见人，见人心惕惕然，热多汗出甚，刺足少阳。足少阳胆经之脉也，内通肝经，肝主筋，邪热侵之，筋脉弛纵而解㑊也；邪入近阴分，故发寒热而皆不甚；其邪伤胆则胆怯，故恶见人，见人而心惕然也；人身之阳，初由少阳而升，及其阳升邪发，则热多而汗出甚也。刺法同上。", "白话": "足少阳之疟，令人身体懈怠无力，寒不太甚，热也不太甚，厌恶见人，见人则心中惕惕然恐惧，热多而汗出甚，刺足少阳经。足少阳胆经之脉，内通肝经；肝主筋，邪热侵犯，则筋脉弛纵而懈怠无力；邪入接近阴分，所以发寒热而都不太甚；邪伤胆则胆怯，所以厌恶见人、见人而心中惕然；人身的阳气，初由少阳而升发，等到阳气升、邪气发，则热多而汗出甚。刺法同上。"}, {"source": "条634｜《灵素节注类编》卷八", "原文": "《灵素节注类编》卷八：“癫疾始作，而引口啼呼，喘悸者，候之手阳明、太阳，左强者，攻其右，右强者，攻其左，血变乃止。此痰闭风动，癫而兼痫者也，故口牵引啼呼而喘悸，其肢体或左或右而强急。候其大肠、小肠两经而针治之，邪在左，则右强，故攻其左，邪在右，则左强，故攻其右，以邪闭经脉，而血气不得流注于无邪之处，故筋脉燥急而强也。", "白话": "癫疾开始发作，口角牵引、啼呼、气喘心悸的，诊候手阳明大肠、手太阳小肠二经，左侧强急的攻其右侧，右侧强急的攻其左侧，待血色改变即止。这是痰闭风动、癫而兼痫的病证，所以口角牵引、啼呼而喘悸，其肢体或左或右而强急。候大肠、小肠两经而针治：邪在左，则右强，故攻其左；邪在右，则左强，故攻其右。因邪气闭阻经脉，血气不得流注到无邪之处，所以筋脉燥急而强。"}, {"source": "条635｜《杂病广要》", "原文": "《杂病广要》：“又若胸中气散，而心下有脉洪大跳，其数向下分入两髀股内，令人心急忪悸者，宜以手按捻小腹下两傍，接髀大斜文中，有脉跳动，便当文上，灸跳三七炷即定。灸毕皆须灸三里二十炷，以引其气下也。", "白话": "又若胸中气散，而心下有脉洪大搏动，其搏动向下分入两侧大腿内侧，令人心中急迫、怔忪心悸的，宜用手按揉小腹下两旁、连接大腿的斜纹中，有脉跳动处，即在纹上灸跳动处三七炷，即可安定。灸毕都必须再灸三里二十炷，以引其气下行。"}, {"source": "条636｜《灸法秘传》", "原文": "《灸法秘传》：“上脘穴脐上五寸，巨阙下一寸。凡心腹疼痛，惊悸，痰疾，伏梁，气蛊状如覆盆，风痫等症，针此穴。", "白话": "上脘穴在脐上五寸，巨阙穴下一寸。凡心腹疼痛、惊悸、痰疾、伏梁、气蛊（腹大如覆盆）等症，针刺此穴。"}, {"source": "条637｜《针灸问答》卷上", "原文": "《针灸问答》卷上：“太巨外陵下一寸，三分五壮针灸宜，主治腹胀小便涩，㿉疝偏坠惊悸施。注：大巨穴，在天枢下二寸。五壮，三分。主治小腹胀满，烦渴，小便难，㿉疝偏堕，四肢不收，惊悸不眠等症。", "白话": "太巨（大巨）穴在外陵下一寸，针三分、灸五壮为宜；主治腹胀、小便艰涩，㿉疝偏坠、惊悸，用此施治。注：大巨穴在天枢穴下二寸。灸五壮，针三分。主治小腹胀满、烦渴、小便难、㿉疝偏坠、四肢不能收摄、惊悸不眠等症。"}, {"source": "条638｜《针灸集成》卷一", "原文": "《针灸集成》卷一：“ 肾属病，饥不欲食，面黑如炭色，咳唾有血，喉鸣而喘，坐而欲起，目䀮䀮如无所见，心如悬若饥状，气不足则善恐，心惕惕若人将捕之，是谓骨厥证也。口热舌干，咽肿上气，嗌干及痛，烦心心痛，黄疸肠澼，脊、臀、股内后廉痛，厥阙嗜卧，足下热而痛。", "白话": "肾的病候：饥而不欲食，面色黑如炭色，咳唾带血，喉中痰鸣而喘，坐而欲起（坐立不安），目视䀮䀮一无所见，心如悬空若饥状；气不足则善恐惧，心中惕惕如有人将捕之，这叫做骨厥证。口热舌干，咽肿上气，咽干作痛，心烦心痛，黄疸肠澼，脊、臀、股内后缘疼痛，厥冷嗜卧，足下热而疼痛。"}, {"source": "条639｜《针灸集成》卷二", "原文": "《针灸集成》卷二：“《资》云：心邪实则心中暴痛，虚则心烦惕然失智。心惕惕失智内关、百会、神门。", "白话": "《资》（疑指《针灸资生经》，待核）说：心邪实则心中暴痛，虚则心烦、惕然失智。心惕然失智，取内关、百会、神门。"}, {"source": "条640｜《资》", "原文": "《针灸集成》卷二：“《资》云：心邪实则心中暴痛，虚则心烦惕然失智。心惕惕失智内关、百会、神门。", "白话": "（句译见条639。）本处《资》为“心邪实则心中暴痛，虚则心烦惕然失智”之出处。"}, {"source": "条641｜《针灸集成》卷二", "原文": "《针灸集成》卷二：“大概，诸疸口淡、怔忡、耳鸣、脚软、寒热、小便白浊、渴则难治，不渴则可治也。", "白话": "大抵各种黄疸，见口淡、怔忡、耳鸣、脚软、寒热、小便白浊者，口渴则难治，不渴则可治。"}, {"source": "条642｜《针灸集成》卷二", "原文": "《针灸集成》卷二：“善恐心惕惕，取然谷、内关、阴陵泉、侠溪、行间。《纲目》", "白话": "善恐心惕惕，取然谷、内关、阴陵泉、侠溪、行间。《纲目》"}, {"source": "条643｜《纲目》", "原文": "《针灸集成》卷二：“善恐心惕惕，取然谷、内关、阴陵泉、侠溪、行间。《纲目》", "白话": "（句译见条642。）本处《纲目》为然谷、内关等取穴之出处。"}, {"source": "条644｜《针灸集成》卷二", "原文": "《针灸集成》卷二：“心澹澹大动，取太陵、三里。《纲目》", "白话": "心澹澹大动，取太陵、三里。《纲目》"}, {"source": "条645｜《纲目》", "原文": "《针灸集成》卷二：“心澹澹大动，取太陵、三里。《纲目》", "白话": "（句译见条644。）本处《纲目》为“心澹澹大动，取太陵、三里”之出处。"}, {"source": "条646｜《针灸集成》卷二", "原文": "《针灸集成》卷二：“惊悸不得眠，取阴交。不得卧，取浮郄。《甲乙》", "白话": "惊悸不得眠，取阴交。不得卧，取浮郄。《甲乙》"}, {"source": "条647｜《甲乙》", "原文": "《针灸集成》卷二：“惊悸不得眠，取阴交。不得卧，取浮郄。《甲乙》", "白话": "（句译见条646。）本处《甲乙》为“惊悸不得眠，取阴交”之出处。"}, {"source": "条648｜《针灸集成》卷三", "原文": "《针灸集成》卷三：“阳溪在手腕横纹上侧两筋间陷中、直合谷。针三分、留七呼。灸三壮。主治狂言喜笑见鬼，热病烦心，掌中热，汗不出，目赤烂翳，厥逆头痛，胸满不得息，寒热痰疟，呕沫，喉痹，耳鸣，齿痛，惊掣，肘臂不举，痂疥。兼二间，治牙疼、腰痛、喉痹。《席弘赋》兼解溪，治惊悸怔忡；兼肩髑，能消瘾风之热极。《百证赋》", "白话": "阳溪穴在手腕横纹上侧、两筋之间的凹陷中，与合谷直对。针刺三分深，留针七呼。灸三壮。主治狂言妄语、喜笑无常、如见鬼神，热病心烦，掌中发热，汗不出，目赤烂生翳，厥逆头痛，胸满呼吸不利，寒热痰疟，呕吐涎沫，喉痹，耳鸣，牙痛，惊风抽掣，肘臂不能抬举，痂疥。配二间穴，治牙痛、腰痛、喉痹（《席弘赋》）；配解溪穴，治惊悸怔忡；配肩髑（肩髃）穴，能消除瘾风之热极（《百证赋》）。"}, {"source": "条649｜《席弘赋》", "原文": "《针灸集成》卷三：“阳溪在手腕横纹上侧两筋间陷中、直合谷。针三分、留七呼。灸三壮。主治狂言喜笑见鬼，热病烦心，掌中热，汗不出，目赤烂翳，厥逆头痛，胸满不得息，寒热痰疟，呕沫，喉痹，耳鸣，齿痛，惊掣，肘臂不举，痂疥。兼二间，治牙疼、腰痛、喉痹。《席弘赋》兼解溪，治惊悸怔忡；兼肩髑，能消瘾风之热极。《百证赋》", "白话": "（句译见条648。）本处《席弘赋》引阳溪“兼二间”配穴说。"}, {"source": "条650｜《百证赋》", "原文": "《针灸集成》卷三：“阳溪在手腕横纹上侧两筋间陷中、直合谷。针三分、留七呼。灸三壮。主治狂言喜笑见鬼，热病烦心，掌中热，汗不出，目赤烂翳，厥逆头痛，胸满不得息，寒热痰疟，呕沫，喉痹，耳鸣，齿痛，惊掣，肘臂不举，痂疥。兼二间，治牙疼、腰痛、喉痹。《席弘赋》兼解溪，治惊悸怔忡；兼肩髑，能消瘾风之热极。《百证赋》", "白话": "（句译见条648。）本处《百证赋》引阳溪“兼解溪，治惊悸怔忡；兼肩髑，能消瘾风之热极”之说。"}, {"source": "条651｜《针灸集成》卷三", "原文": "《针灸集成》卷三：”“大巨 在外陵下，去中行二寸，对石门。针五分，灸五壮。《甲乙经》作针八分。主治小腹胀满，烦渴，小便难，㿉疝，四肢不收，惊悸不眠。", "白话": "大巨穴在外陵之下，距前正中线二寸，与石门穴平对。针刺五分深，灸五壮。《甲乙经》作针八分。主治小腹胀满、烦渴、小便难、㿉疝、四肢不能收摄、惊悸不眠。"}, {"source": "条652｜《甲乙经》", "原文": "《针灸集成》卷三：”“大巨 在外陵下，去中行二寸，对石门。针五分，灸五壮。《甲乙经》作针八分。主治小腹胀满，烦渴，小便难，㿉疝，四肢不收，惊悸不眠。", "白话": "（句译见条651。）本处《甲乙经》引作大巨“针八分”之异说。"}, {"source": "条653｜《针灸集成》卷三", "原文": "《针灸集成》卷三：“三里在膝眼下三寸，䯒骨外廉大筋内宛宛中，坐而竖膝低跗取之。极重按之则跗上动脉止矣。针五分、留七呼，灸三壮。《千金》云：灸二百壮至五百壮。主治胃中寒，心腹胀痛，逆气上攻，脏气虚惫，胃气不足，恶闻食臭，腹痛肠鸣，食不化，大便不通，腰痛膝弱不得俛俯仰。小肠气。此穴主泻胃中之热，与气冲、巨虚上下廉同。诸病皆治，食气、水气、蛊毒、痃癖、四肢肿满、膝䯒酸痛、目不明。秦承祖疗五劳七伤，羸瘦虚", "白话": "三里穴在膝眼之下三寸，胫骨外侧大筋内侧的凹陷中，坐位竖膝、垂足取之。极重按之，则足跗上动脉应手而止。针刺五分深，留针七呼，灸三壮。《千金方》说：灸二百壮至五百壮。主治胃中寒冷，心腹胀痛，逆气上攻，脏气虚惫，胃气不足，恶闻食臭，腹痛肠鸣，饮食不化，大便不通，腰痛膝弱、不能俯仰，小肠气。此穴主泻胃中之热，与气冲、巨虚上下廉相同。诸病皆治：食气、水气、蛊毒、痃癖、四肢肿满、膝胫酸痛、目不明。秦承祖用以疗五劳七伤、羸瘦虚乏、瘀血乳痈。华佗说：人年三十以外，若不灸三里，令气上冲于目，使"}, {"source": "条654｜《千金》", "原文": "《针灸集成》卷三：“三里在膝眼下三寸，䯒骨外廉大筋内宛宛中，坐而竖膝低跗取之。极重按之则跗上动脉止矣。针五分、留七呼，灸三壮。《千金》云：灸二百壮至五百壮。主治胃中寒，心腹胀痛，逆气上攻，脏气虚惫，胃气不足，恶闻食臭，腹痛肠鸣，食不化，大便不通，腰痛膝弱不得俛俯仰。小肠气。此穴主泻胃中之热，与气冲、巨虚上下廉同。诸病皆治，食气、水气、蛊毒、痃癖、四肢肿满、膝䯒酸痛、目不明。秦承祖疗五劳七伤，羸瘦虚", "白话": "（句译见条653。）本处《千金》引三里“灸二百壮至五百壮”之灸量说。"}, {"source": "条655｜《千金》", "原文": "《针灸集成》卷三：“三里在膝眼下三寸，䯒骨外廉大筋内宛宛中，坐而竖膝低跗取之。极重按之则跗上动脉止矣。针五分、留七呼，灸三壮。《千金》云：灸二百壮至五百壮。主治胃中寒，心腹胀痛，逆气上攻，脏气虚惫，胃气不足，恶闻食臭，腹痛肠鸣，食不化，大便不通，腰痛膝弱不得俛俯仰。小肠气。此穴主泻胃中之热，与气冲、巨虚上下廉同。诸病皆治，食气、水气、蛊毒、痃癖、四肢肿满、膝䯒酸痛、目不明。秦承祖疗五劳七伤，羸瘦虚", "白话": "（句译见条653。）本处《千金》引三里治“心腹胀满……五劳七伤，灸七壮”之说。"}, {"source": "条656｜《神农经》", "原文": "《针灸集成》卷三：“三里在膝眼下三寸，䯒骨外廉大筋内宛宛中，坐而竖膝低跗取之。极重按之则跗上动脉止矣。针五分、留七呼，灸三壮。《千金》云：灸二百壮至五百壮。主治胃中寒，心腹胀痛，逆气上攻，脏气虚惫，胃气不足，恶闻食臭，腹痛肠鸣，食不化，大便不通，腰痛膝弱不得俛俯仰。小肠气。此穴主泻胃中之热，与气冲、巨虚上下廉同。诸病皆治，食气、水气、蛊毒、痃癖、四肢肿满、膝䯒酸痛、目不明。秦承祖疗五劳七伤，羸瘦虚", "白话": "（句译见条653。）本处《神农经》引三里“兼束骨，针治项强肿痛、体重腰瘫”之说。"}, {"source": "条657｜《太乙歌》", "原文": "《针灸集成》卷三：“三里在膝眼下三寸，䯒骨外廉大筋内宛宛中，坐而竖膝低跗取之。极重按之则跗上动脉止矣。针五分、留七呼，灸三壮。《千金》云：灸二百壮至五百壮。主治胃中寒，心腹胀痛，逆气上攻，脏气虚惫，胃气不足，恶闻食臭，腹痛肠鸣，食不化，大便不通，腰痛膝弱不得俛俯仰。小肠气。此穴主泻胃中之热，与气冲、巨虚上下廉同。诸病皆治，食气、水气、蛊毒、痃癖、四肢肿满、膝䯒酸痛、目不明。秦承祖疗五劳七伤，羸瘦虚", "白话": "（句译见条653。）本处《太乙歌》为三里条所引歌赋出处。"}, {"source": "条658｜《玉龙赋》", "原文": "《针灸集成》卷三：“三里在膝眼下三寸，䯒骨外廉大筋内宛宛中，坐而竖膝低跗取之。极重按之则跗上动脉止矣。针五分、留七呼，灸三壮。《千金》云：灸二百壮至五百壮。主治胃中寒，心腹胀痛，逆气上攻，脏气虚惫，胃气不足，恶闻食臭，腹痛肠鸣，食不化，大便不通，腰痛膝弱不得俛俯仰。小肠气。此穴主泻胃中之热，与气冲、巨虚上下廉同。诸病皆治，食气、水气、蛊毒、痃癖、四肢肿满、膝䯒酸痛、目不明。秦承祖疗五劳七伤，羸瘦虚", "白话": "（句译见条653。）本处《玉龙赋》引三里“兼绝骨、三阴交……又治心悸虚烦”诸配穴说。"}, {"source": "条659｜《针灸集成》卷三", "原文": "《针灸集成》卷三：“解溪，在冲阳后一寸五分、足跗上系鞋带处陷中。针五分、留五呼，灸三壮。主治风气面浮，头痛目眩，生翳，厥气上冲，喘咳，腹胀颠疾，烦心悲泣，惊瘈瘛转筋，霍乱大便下重、股膝䯒肿。又泻胃热善饥不食，食即支满腹胀，及疗痎疟寒热，须兼针厉兑、三里、解溪、商丘出血。治腹胀，脚跗痛，目眩头疼，可灸七壮。《神农经》兼商丘，丘墟，堪追脚痛。《玉龙赋》兼阳谷，治惊悸怔忡。《百证赋》一传：腹虚肿及足胫虚", "白话": "解溪穴在冲阳穴后一寸五分、足背上系鞋带处的凹陷中。针刺五分深，留针五呼，灸三壮。主治风气面浮，头痛目眩，目生翳膜，厥气上冲，喘咳，腹胀，癫疾，心烦悲泣，惊风抽搐瘛疭、转筋，霍乱大便下坠、大腿膝胫浮肿。又泻胃热：善饥而不欲食，食入即支撑胀满；又疗痎疟寒热，须兼针厉兑、三里、解溪、商丘出血。治腹胀、脚跗疼痛、目眩头痛，可灸七壮。《神农经》配商丘、丘墟，能治脚痛（《玉龙赋》）。配阳谷，治惊悸怔忡（《百证赋》）。一说：腹虚肿及足胫虚肿，灸之有效；又气逆发噎将死者，灸之有效。"}, {"source": "条660｜《神农经》", "原文": "《针灸集成》卷三：“解溪，在冲阳后一寸五分、足跗上系鞋带处陷中。针五分、留五呼，灸三壮。主治风气面浮，头痛目眩，生翳，厥气上冲，喘咳，腹胀颠疾，烦心悲泣，惊瘈瘛转筋，霍乱大便下重、股膝䯒肿。又泻胃热善饥不食，食即支满腹胀，及疗痎疟寒热，须兼针厉兑、三里、解溪、商丘出血。治腹胀，脚跗痛，目眩头疼，可灸七壮。《神农经》兼商丘，丘墟，堪追脚痛。《玉龙赋》兼阳谷，治惊悸怔忡。《百证赋》一传：腹虚肿及足胫虚", "白话": "（句译见条659。）本处《神农经》引解溪“兼商丘、丘墟，堪追脚痛”之说。"}, {"source": "条661｜《玉龙赋》", "原文": "《针灸集成》卷三：“解溪，在冲阳后一寸五分、足跗上系鞋带处陷中。针五分、留五呼，灸三壮。主治风气面浮，头痛目眩，生翳，厥气上冲，喘咳，腹胀颠疾，烦心悲泣，惊瘈瘛转筋，霍乱大便下重、股膝䯒肿。又泻胃热善饥不食，食即支满腹胀，及疗痎疟寒热，须兼针厉兑、三里、解溪、商丘出血。治腹胀，脚跗痛，目眩头疼，可灸七壮。《神农经》兼商丘，丘墟，堪追脚痛。《玉龙赋》兼阳谷，治惊悸怔忡。《百证赋》一传：腹虚肿及足胫虚", "白话": "（句译见条659。）本处《玉龙赋》引解溪条所附配穴说。"}, {"source": "条662｜《百证赋》", "原文": "《针灸集成》卷三：“解溪，在冲阳后一寸五分、足跗上系鞋带处陷中。针五分、留五呼，灸三壮。主治风气面浮，头痛目眩，生翳，厥气上冲，喘咳，腹胀颠疾，烦心悲泣，惊瘈瘛转筋，霍乱大便下重、股膝䯒肿。又泻胃热善饥不食，食即支满腹胀，及疗痎疟寒热，须兼针厉兑、三里、解溪、商丘出血。治腹胀，脚跗痛，目眩头疼，可灸七壮。《神农经》兼商丘，丘墟，堪追脚痛。《玉龙赋》兼阳谷，治惊悸怔忡。《百证赋》一传：腹虚肿及足胫虚", "白话": "（句译见条659。）本处《百证赋》引解溪“兼阳谷，治惊悸怔忡”之说。"}, {"source": "条663｜《针灸集成》卷三", "原文": "《针灸集成》卷三：“是动则病洒洒然振寒，善伸数欠颜黑颜即额也，病至，则恶人与火，闻木音则惕然而惊，心动，欲独闭户牖而处，甚则欲上高而歌，弃衣而走，贲响腹胀，是谓骭厥骭即胫之别名。是主血所生病者，狂疟温淫汗出，鼽衄，口唇疹，颈肿喉痹，大腹水肿，膝膑肿痛，循膺、乳、气街、股、伏兔、骭外廉，足跗上皆痛，中指不用。气盛则身以前皆热，其有余于胃，则消谷善饥，尿色黄。气不足则身以前皆寒栗，胃中寒则胀满。盛者", "白话": "足阳明“是动”病：洒洒然恶寒战栗，频伸呵欠、额部色黑；病发则厌恶人与火，听见木音则惕然而惊，心动，欲独自闭门关窗而处，甚则欲登高而歌、弃衣而奔走，肠鸣腹胀，这叫骭厥（骭即胫之别名）。“是主血”所生病：狂疟、温病汗出，鼻流清涕、鼻衄，口眼㖞斜、唇生疹，颈肿喉痹，大腹水肿，膝髌肿痛；循胸膺、乳、气街、股、伏兔、胫外缘、足跗上皆痛，中指不能活动。气盛则身前皆热，其气有余于胃，则消谷善饥、尿色黄；气不足则身前皆寒栗，胃中寒则胀满。盛者人迎脉大于寸口三倍，虚者人迎反小于寸口。（《灵枢》"}, {"source": "条664｜《灵枢》", "原文": "《针灸集成》卷三：“是动则病洒洒然振寒，善伸数欠颜黑颜即额也，病至，则恶人与火，闻木音则惕然而惊，心动，欲独闭户牖而处，甚则欲上高而歌，弃衣而走，贲响腹胀，是谓骭厥骭即胫之别名。是主血所生病者，狂疟温淫汗出，鼽衄，口唇疹，颈肿喉痹，大腹水肿，膝膑肿痛，循膺、乳、气街、股、伏兔、骭外廉，足跗上皆痛，中指不用。气盛则身以前皆热，其有余于胃，则消谷善饥，尿色黄。气不足则身以前皆寒栗，胃中寒则胀满。盛者", "白话": "（句译见条663。）本处《灵枢》为足阳明胃经“是动、是主血所生病”病候之出处。"}, {"source": "条665｜《入门》", "原文": "《针灸集成》卷三：“是动则病洒洒然振寒，善伸数欠颜黑颜即额也，病至，则恶人与火，闻木音则惕然而惊，心动，欲独闭户牖而处，甚则欲上高而歌，弃衣而走，贲响腹胀，是谓骭厥骭即胫之别名。是主血所生病者，狂疟温淫汗出，鼽衄，口唇疹，颈肿喉痹，大腹水肿，膝膑肿痛，循膺、乳、气街、股、伏兔、骭外廉，足跗上皆痛，中指不用。气盛则身以前皆热，其有余于胃，则消谷善饥，尿色黄。气不足则身以前皆寒栗，胃中寒则胀满。盛者", "白话": "（句译见条663。）本处《入门》引“阳明根于厉兑，结于●大”根结说。"}, {"source": "条666｜《灵枢》", "原文": "《针灸集成》卷三：“是动则病洒洒然振寒，善伸数欠颜黑颜即额也，病至，则恶人与火，闻木音则惕然而惊，心动，欲独闭户牖而处，甚则欲上高而歌，弃衣而走，贲响腹胀，是谓骭厥骭即胫之别名。是主血所生病者，狂疟温淫汗出，鼽衄，口唇疹，颈肿喉痹，大腹水肿，膝膑肿痛，循膺、乳、气街、股、伏兔、骭外廉，足跗上皆痛，中指不用。气盛则身以前皆热，其有余于胃，则消谷善饥，尿色黄。气不足则身以前皆寒栗，胃中寒则胀满。盛者", "白话": "（句译见条663。）本处《灵枢》为足阳明经气流注（辰时自迎香……至厉兑）之出处。"}, {"source": "条667｜《针灸集成》卷三", "原文": "《针灸集成》卷三：“通里 在腕侧后一寸陷中微向外。针三分，灸三壮。主治热病头痛，目眩面热，无汗懊憹，暴瘖，心悸，悲恐畏人，喉痹，苦呕，虚损，数欠少气，遗溺，肘臂肿痛，妇人经血过多崩漏。治目眩头痛，可灸七壮。《神农经》疗心惊。《玉龙赋》兼大钟，治倦言嗜卧。《百证赋》治欲言声不出，懊憹及怔忡。实则四肢重，头腮面颊红，声平仍欠，数喉闭气难通；虚则不能食，暴瘖面无容，毫针微微针，方信有神功。《马丹阳》", "白话": "通里穴在腕侧后一寸凹陷中、微向外。针刺三分深，灸三壮。主治热病头痛，目眩面热，无汗懊憹，突然失音，心悸，悲恐惧人，喉痹，恶心欲呕，虚损，频作呵欠、气短，遗尿，肘臂肿痛，妇人经血过多、崩漏。治目眩头痛，可灸七壮。《神农经》疗心惊。《玉龙赋》配大钟，治懒言嗜卧。《百证赋》治欲说话而声音不出、懊憹及怔忡：实证则四肢沉重、头腮面颊发红，声音虽平仍频作呵欠、喉闭气难通；虚证则不能饮食、突然失音、面容无华。用毫针微微刺之，方信有神功（《马丹阳》）。"}, {"source": "条668｜《神农经》", "原文": "《针灸集成》卷三：“通里 在腕侧后一寸陷中微向外。针三分，灸三壮。主治热病头痛，目眩面热，无汗懊憹，暴瘖，心悸，悲恐畏人，喉痹，苦呕，虚损，数欠少气，遗溺，肘臂肿痛，妇人经血过多崩漏。治目眩头痛，可灸七壮。《神农经》疗心惊。《玉龙赋》兼大钟，治倦言嗜卧。《百证赋》治欲言声不出，懊憹及怔忡。实则四肢重，头腮面颊红，声平仍欠，数喉闭气难通；虚则不能食，暴瘖面无容，毫针微微针，方信有神功。《马丹阳》", "白话": "（句译见条667。）本处《神农经》引通里“疗心惊”之说。"}, {"source": "条669｜《玉龙赋》", "原文": "《针灸集成》卷三：“通里 在腕侧后一寸陷中微向外。针三分，灸三壮。主治热病头痛，目眩面热，无汗懊憹，暴瘖，心悸，悲恐畏人，喉痹，苦呕，虚损，数欠少气，遗溺，肘臂肿痛，妇人经血过多崩漏。治目眩头痛，可灸七壮。《神农经》疗心惊。《玉龙赋》兼大钟，治倦言嗜卧。《百证赋》治欲言声不出，懊憹及怔忡。实则四肢重，头腮面颊红，声平仍欠，数喉闭气难通；虚则不能食，暴瘖面无容，毫针微微针，方信有神功。《马丹阳》", "白话": "（句译见条667。）本处《玉龙赋》引通里“兼大钟，治倦言嗜卧”之说。"}, {"source": "条670｜《百证赋》", "原文": "《针灸集成》卷三：“通里 在腕侧后一寸陷中微向外。针三分，灸三壮。主治热病头痛，目眩面热，无汗懊憹，暴瘖，心悸，悲恐畏人，喉痹，苦呕，虚损，数欠少气，遗溺，肘臂肿痛，妇人经血过多崩漏。治目眩头痛，可灸七壮。《神农经》疗心惊。《玉龙赋》兼大钟，治倦言嗜卧。《百证赋》治欲言声不出，懊憹及怔忡。实则四肢重，头腮面颊红，声平仍欠，数喉闭气难通；虚则不能食，暴瘖面无容，毫针微微针，方信有神功。《马丹阳》", "白话": "（句译见条667。）本处《百证赋》引通里“治欲言声不出，懊憹及怔忡”之说。"}, {"source": "条671｜《马丹阳》", "原文": "《针灸集成》卷三：“通里 在腕侧后一寸陷中微向外。针三分，灸三壮。主治热病头痛，目眩面热，无汗懊憹，暴瘖，心悸，悲恐畏人，喉痹，苦呕，虚损，数欠少气，遗溺，肘臂肿痛，妇人经血过多崩漏。治目眩头痛，可灸七壮。《神农经》疗心惊。《玉龙赋》兼大钟，治倦言嗜卧。《百证赋》治欲言声不出，懊憹及怔忡。实则四肢重，头腮面颊红，声平仍欠，数喉闭气难通；虚则不能食，暴瘖面无容，毫针微微针，方信有神功。《马丹阳》", "白话": "（句译见条667。）本处《马丹阳》指天星十二穴通里歌（“实则四肢重……方信有神功”）。"}, {"source": "条672｜《针灸集成》卷三", "原文": "《针灸集成》卷三：“少冲，在手小指内正端。针一分、留一呼，灸一壮。一曰：三壮。主治热病烦满上气，心火炎上眼赤，血少，呕吐血沫及心痛冷痰，少气，悲恐善惊，口热咽痠酸，胸胁痛，乍寒乍热，臑臂内后廉痛，手挛不伸。可治心虚热壅。《玉龙赋》兼曲池，治发热。《百证赋》凡初中风，跌倒卒暴、昏沉痰涎壅满、不省人事、牙关紧闭、药水不下，急以三棱针针少商、商阳、中冲、关冲、少泽及此穴，使气血流通，乃起死回生、急救之妙", "白话": "少冲穴在手小指内侧端正处。针刺一分深，留针一呼，灸一壮（一说三壮）。主治热病烦满上气，心火上炎、眼睛发红，血少，呕吐血沫及心痛冷痰，气短，悲伤恐惧善惊，口热咽酸，胸胁疼痛，乍寒乍热，上臂内后缘疼痛，手指挛急不能伸展。可治心虚热壅。《玉龙赋》配曲池，治发热。《百证赋》凡初中风、跌倒猝暴、昏沉痰涎壅盛、不省人事、牙关紧闭、药水不能下者，急用三棱针刺少商、商阳、中冲、关冲、少泽及本穴，使气血流通，是起死回生的急救妙穴。"}, {"source": "条673｜《玉龙赋》", "原文": "《针灸集成》卷三：“少冲，在手小指内正端。针一分、留一呼，灸一壮。一曰：三壮。主治热病烦满上气，心火炎上眼赤，血少，呕吐血沫及心痛冷痰，少气，悲恐善惊，口热咽痠酸，胸胁痛，乍寒乍热，臑臂内后廉痛，手挛不伸。可治心虚热壅。《玉龙赋》兼曲池，治发热。《百证赋》凡初中风，跌倒卒暴、昏沉痰涎壅满、不省人事、牙关紧闭、药水不下，急以三棱针针少商、商阳、中冲、关冲、少泽及此穴，使气血流通，乃起死回生、急救之妙", "白话": "（句译见条672。）本处《玉龙赋》引少冲“兼曲池，治发热”之说。"}, {"source": "条674｜《百证赋》", "原文": "《针灸集成》卷三：“少冲，在手小指内正端。针一分、留一呼，灸一壮。一曰：三壮。主治热病烦满上气，心火炎上眼赤，血少，呕吐血沫及心痛冷痰，少气，悲恐善惊，口热咽痠酸，胸胁痛，乍寒乍热，臑臂内后廉痛，手挛不伸。可治心虚热壅。《玉龙赋》兼曲池，治发热。《百证赋》凡初中风，跌倒卒暴、昏沉痰涎壅满、不省人事、牙关紧闭、药水不下，急以三棱针针少商、商阳、中冲、关冲、少泽及此穴，使气血流通，乃起死回生、急救之妙", "白话": "（句译见条672。）本处《百证赋》引少冲（与少商、商阳等井穴）急救中风之说。"}, {"source": "条675｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“是动则病饥不欲食，面黑如炭色，咳唾则有血，喉鸣而喘，坐而欲起，目䀮䀮如无所见，心如悬若饥状，气不足则善恐心惕惕若人将捕之，是谓骨厥；是主肾所生病者，口热舌干，咽肿上气嗌干及痛，烦心心痛，黄疸，肠癖，脊臀股内后廉痛，痿厥嗜卧，足下热而痛。灸则强食生肉勉强饮食，以生肌肉，缓带披发，大杖重履而步。盛者寸口大再倍于人迎，虚者寸口反小于人迎也。《灵枢》 酉时自至阴与涌泉循膝上行至胸俞府穴", "白话": "足少阴“是动”病：饥而不欲食，面色黑如炭色，咳唾则有血，喉中痰鸣而喘，坐而欲起，目视䀮䀮一无所见，心如悬空若饥状；气不足则善恐惧、心中惕惕如有人将捕之，这叫骨厥。“是主肾所生病”：口热舌干，咽肿上气、咽干作痛，心烦心痛，黄疸，肠澼，脊臀股内后缘疼痛，痿厥嗜卧，足下热而疼痛。灸则强令进食以生肌肉（原稿夹注：勉强饮食，以生肌肉），松缓衣带、披发，持大杖、着重履而步行。盛者寸口脉大于人迎两倍，虚者寸口反小于人迎。（《灵枢》）酉时自至阴与涌泉循膝上行至胸俞府穴止（《入门》）。少阴根于"}, {"source": "条676｜《灵枢》", "原文": "《针灸集成》卷四：“是动则病饥不欲食，面黑如炭色，咳唾则有血，喉鸣而喘，坐而欲起，目䀮䀮如无所见，心如悬若饥状，气不足则善恐心惕惕若人将捕之，是谓骨厥；是主肾所生病者，口热舌干，咽肿上气嗌干及痛，烦心心痛，黄疸，肠癖，脊臀股内后廉痛，痿厥嗜卧，足下热而痛。灸则强食生肉勉强饮食，以生肌肉，缓带披发，大杖重履而步。盛者寸口大再倍于人迎，虚者寸口反小于人迎也。《灵枢》 酉时自至阴与涌泉循膝上行至胸俞府穴", "白话": "（句译见条675。）本处《灵枢》为足少阴肾经病候之出处（与条638 互见）。"}, {"source": "条677｜《入门》", "原文": "《针灸集成》卷四：“是动则病饥不欲食，面黑如炭色，咳唾则有血，喉鸣而喘，坐而欲起，目䀮䀮如无所见，心如悬若饥状，气不足则善恐心惕惕若人将捕之，是谓骨厥；是主肾所生病者，口热舌干，咽肿上气嗌干及痛，烦心心痛，黄疸，肠癖，脊臀股内后廉痛，痿厥嗜卧，足下热而痛。灸则强食生肉勉强饮食，以生肌肉，缓带披发，大杖重履而步。盛者寸口大再倍于人迎，虚者寸口反小于人迎也。《灵枢》 酉时自至阴与涌泉循膝上行至胸俞府穴", "白话": "（句译见条675。）本处《入门》引“少阴根于涌泉，结于廉泉”根结说。"}, {"source": "条678｜《灵枢》", "原文": "《针灸集成》卷四：“是动则病饥不欲食，面黑如炭色，咳唾则有血，喉鸣而喘，坐而欲起，目䀮䀮如无所见，心如悬若饥状，气不足则善恐心惕惕若人将捕之，是谓骨厥；是主肾所生病者，口热舌干，咽肿上气嗌干及痛，烦心心痛，黄疸，肠癖，脊臀股内后廉痛，痿厥嗜卧，足下热而痛。灸则强食生肉勉强饮食，以生肌肉，缓带披发，大杖重履而步。盛者寸口大再倍于人迎，虚者寸口反小于人迎也。《灵枢》 酉时自至阴与涌泉循膝上行至胸俞府穴", "白话": "（句译见条675。）本处《灵枢》为足少阴经气流注（酉时自至阴……至俞府）之出处。"}, {"source": "条679｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“郄门，在掌后去腕五寸。针三分，灸五壮。主治呕吐衄血，心痛呕哕，惊恐神气不足，久痔。", "白话": "郄门穴在掌后距腕五寸。针刺三分深，灸五壮。主治呕吐衄血，心痛呕哕，惊恐、神气不足，久痔。"}, {"source": "条680｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“间使，在掌后三寸。针三分、留七呼，灸五壮。主治伤寒结胸，心悬如饥，呕沫少气，中风气塞，昏危不语，卒狂，胸中澹澹，恶风寒，霍乱干呕，腋肿肘挛，卒心痛，多惊，咽中如鲠，妇人月水不调，小儿客忤久疟，可灸鬼邪随年壮。 干呕不止，所食即吐不停，灸三十壮；若四肢脉绝不至者，灸之便通，此法能起死人；又治卒死灸百息；又十三鬼穴云此名鬼路，针百邪癫狂，当在第九次下针。《千金》 治脾寒、寒热往来、", "白话": "间使穴在掌后三寸。针刺三分深，留针七呼，灸五壮。主治伤寒结胸，心悬如饥，呕吐涎沫、气短，中风气塞、昏危不语，猝狂，胸中澹澹动悸，恶风寒，霍乱干呕，腋肿肘挛，猝心痛，多惊，咽中如有物梗阻，妇人月经不调，小儿客忤久疟，可灸鬼邪随年龄壮数。干呕不止、食入即吐不停者，灸三十壮；若四肢脉绝不至者，灸之便通，此法能救活死人；又治猝死，灸百息（《千金方》）。又十三鬼穴称此名鬼路，针治百邪癫狂，当在第九次下针。《千金方》治脾寒、寒热往来、浑身疮疥，灸七壮。《神农经》配风池、环跳，治疟疾；又配"}, {"source": "条681｜《千金》", "原文": "《针灸集成》卷四：“间使，在掌后三寸。针三分、留七呼，灸五壮。主治伤寒结胸，心悬如饥，呕沫少气，中风气塞，昏危不语，卒狂，胸中澹澹，恶风寒，霍乱干呕，腋肿肘挛，卒心痛，多惊，咽中如鲠，妇人月水不调，小儿客忤久疟，可灸鬼邪随年壮。 干呕不止，所食即吐不停，灸三十壮；若四肢脉绝不至者，灸之便通，此法能起死人；又治卒死灸百息；又十三鬼穴云此名鬼路，针百邪癫狂，当在第九次下针。《千金》 治脾寒、寒热往来、", "白话": "（句译见条680。）本处《千金》引间使治“脾寒、寒热往来、浑身疮疥，灸七壮”之说。"}, {"source": "条682｜《神农经》", "原文": "《针灸集成》卷四：“间使，在掌后三寸。针三分、留七呼，灸五壮。主治伤寒结胸，心悬如饥，呕沫少气，中风气塞，昏危不语，卒狂，胸中澹澹，恶风寒，霍乱干呕，腋肿肘挛，卒心痛，多惊，咽中如鲠，妇人月水不调，小儿客忤久疟，可灸鬼邪随年壮。 干呕不止，所食即吐不停，灸三十壮；若四肢脉绝不至者，灸之便通，此法能起死人；又治卒死灸百息；又十三鬼穴云此名鬼路，针百邪癫狂，当在第九次下针。《千金》 治脾寒、寒热往来、", "白话": "（句译见条680。）本处《神农经》引间使“兼风池、环跳，治疟疾”等配穴说。"}, {"source": "条683｜《太乙歌》", "原文": "《针灸集成》卷四：“间使，在掌后三寸。针三分、留七呼，灸五壮。主治伤寒结胸，心悬如饥，呕沫少气，中风气塞，昏危不语，卒狂，胸中澹澹，恶风寒，霍乱干呕，腋肿肘挛，卒心痛，多惊，咽中如鲠，妇人月水不调，小儿客忤久疟，可灸鬼邪随年壮。 干呕不止，所食即吐不停，灸三十壮；若四肢脉绝不至者，灸之便通，此法能起死人；又治卒死灸百息；又十三鬼穴云此名鬼路，针百邪癫狂，当在第九次下针。《千金》 治脾寒、寒热往来、", "白话": "（句译见条680。）本处《太乙歌》引间使治痎疟之说。"}, {"source": "条684｜《玉龙赋》", "原文": "《针灸集成》卷四：“间使，在掌后三寸。针三分、留七呼，灸五壮。主治伤寒结胸，心悬如饥，呕沫少气，中风气塞，昏危不语，卒狂，胸中澹澹，恶风寒，霍乱干呕，腋肿肘挛，卒心痛，多惊，咽中如鲠，妇人月水不调，小儿客忤久疟，可灸鬼邪随年壮。 干呕不止，所食即吐不停，灸三十壮；若四肢脉绝不至者，灸之便通，此法能起死人；又治卒死灸百息；又十三鬼穴云此名鬼路，针百邪癫狂，当在第九次下针。《千金》 治脾寒、寒热往来、", "白话": "（句译见条680。）本处《玉龙赋》引间使“兼天鼎，治失音”之说。"}, {"source": "条685｜《百证赋》", "原文": "《针灸集成》卷四：“间使，在掌后三寸。针三分、留七呼，灸五壮。主治伤寒结胸，心悬如饥，呕沫少气，中风气塞，昏危不语，卒狂，胸中澹澹，恶风寒，霍乱干呕，腋肿肘挛，卒心痛，多惊，咽中如鲠，妇人月水不调，小儿客忤久疟，可灸鬼邪随年壮。 干呕不止，所食即吐不停，灸三十壮；若四肢脉绝不至者，灸之便通，此法能起死人；又治卒死灸百息；又十三鬼穴云此名鬼路，针百邪癫狂，当在第九次下针。《千金》 治脾寒、寒热往来、", "白话": "（句译见条680。）本处《百证赋》引间使“兼水沟，治邪癫”之说。"}, {"source": "条686｜《灵光赋》", "原文": "《针灸集成》卷四：“间使，在掌后三寸。针三分、留七呼，灸五壮。主治伤寒结胸，心悬如饥，呕沫少气，中风气塞，昏危不语，卒狂，胸中澹澹，恶风寒，霍乱干呕，腋肿肘挛，卒心痛，多惊，咽中如鲠，妇人月水不调，小儿客忤久疟，可灸鬼邪随年壮。 干呕不止，所食即吐不停，灸三十壮；若四肢脉绝不至者，灸之便通，此法能起死人；又治卒死灸百息；又十三鬼穴云此名鬼路，针百邪癫狂，当在第九次下针。《千金》 治脾寒、寒热往来、", "白话": "（句译见条680。）本处《灵光赋》引间使“治热病频哕”之说。"}, {"source": "条687｜《捷径》", "原文": "《针灸集成》卷四：“间使，在掌后三寸。针三分、留七呼，灸五壮。主治伤寒结胸，心悬如饥，呕沫少气，中风气塞，昏危不语，卒狂，胸中澹澹，恶风寒，霍乱干呕，腋肿肘挛，卒心痛，多惊，咽中如鲠，妇人月水不调，小儿客忤久疟，可灸鬼邪随年壮。 干呕不止，所食即吐不停，灸三十壮；若四肢脉绝不至者，灸之便通，此法能起死人；又治卒死灸百息；又十三鬼穴云此名鬼路，针百邪癫狂，当在第九次下针。《千金》 治脾寒、寒热往来、", "白话": "（句译见条680。）本处《捷径》为间使条所引出处（篇末）。"}, {"source": "条688｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“大陵，在掌后正横纹陷中。针三分、留七呼，灸三壮。主治热病汗不出，舌本痛，喘咳呕血，心悬如饥，善笑不休，头痛气短，胸胁痛，惊恐悲泣，呕逆喉痹，口干目赤，肘臂挛痛，小便如血。治胸中疼痛，胸前疮疥，可灸三壮。《神农经》吐血呕逆，灸五十壮；又凡卒患腰肿、附骨痈疽、节肿、遊风热毒此等疾，但初觉有异即急灸之，从手掌后第一横纹后两筋间灸五壮，立愈，患左灸右，患右灸左，当中者，两手俱灸；又此为", "白话": "大陵穴在掌后正横纹凹陷中。针刺三分深，留针七呼，灸三壮。主治热病汗不出，舌根疼痛，喘咳呕血，心悬如饥，善笑不休，头痛气短，胸胁疼痛，惊恐悲泣，呕逆喉痹，口干目赤，肘臂挛痛，小便色如血。治胸中疼痛、胸前疮疥，可灸三壮。《神农经》吐血呕逆，灸五十壮；又凡猝患腰肿、附骨痈疽、关节肿、游风热毒等疾，初觉有异即急灸之，从手掌后第一横纹之后两筋之间灸五壮，立即痊愈；患左灸右、患右灸左，病在当中者两手俱灸。又此为鬼心穴，治百邪癫狂，在第四次下针。《千金方》配劳宫，疗心闷疮痍；又合人中频泻，"}, {"source": "条689｜《神农经》", "原文": "《针灸集成》卷四：“大陵，在掌后正横纹陷中。针三分、留七呼，灸三壮。主治热病汗不出，舌本痛，喘咳呕血，心悬如饥，善笑不休，头痛气短，胸胁痛，惊恐悲泣，呕逆喉痹，口干目赤，肘臂挛痛，小便如血。治胸中疼痛，胸前疮疥，可灸三壮。《神农经》吐血呕逆，灸五十壮；又凡卒患腰肿、附骨痈疽、节肿、遊风热毒此等疾，但初觉有异即急灸之，从手掌后第一横纹后两筋间灸五壮，立愈，患左灸右，患右灸左，当中者，两手俱灸；又此为", "白话": "（句译见条688。）本处《神农经》引大陵治吐血呕逆、痈疽灸法之说。"}, {"source": "条690｜《千金》", "原文": "《针灸集成》卷四：“大陵，在掌后正横纹陷中。针三分、留七呼，灸三壮。主治热病汗不出，舌本痛，喘咳呕血，心悬如饥，善笑不休，头痛气短，胸胁痛，惊恐悲泣，呕逆喉痹，口干目赤，肘臂挛痛，小便如血。治胸中疼痛，胸前疮疥，可灸三壮。《神农经》吐血呕逆，灸五十壮；又凡卒患腰肿、附骨痈疽、节肿、遊风热毒此等疾，但初觉有异即急灸之，从手掌后第一横纹后两筋间灸五壮，立愈，患左灸右，患右灸左，当中者，两手俱灸；又此为", "白话": "（句译见条688。）本处《千金》引大陵为“鬼心”（十三鬼穴第四）之说。"}, {"source": "条691｜《玉龙赋》", "原文": "《针灸集成》卷四：“大陵，在掌后正横纹陷中。针三分、留七呼，灸三壮。主治热病汗不出，舌本痛，喘咳呕血，心悬如饥，善笑不休，头痛气短，胸胁痛，惊恐悲泣，呕逆喉痹，口干目赤，肘臂挛痛，小便如血。治胸中疼痛，胸前疮疥，可灸三壮。《神农经》吐血呕逆，灸五十壮；又凡卒患腰肿、附骨痈疽、节肿、遊风热毒此等疾，但初觉有异即急灸之，从手掌后第一横纹后两筋间灸五壮，立愈，患左灸右，患右灸左，当中者，两手俱灸；又此为", "白话": "（句译见条688。）本处《玉龙赋》引大陵“兼劳宫、人中、外关、支沟”诸配穴说。"}, {"source": "条692｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“液门，在手小指、次指间合缝纹头。针二分、留二呼，灸三壮。主治惊悸忘言，寒厥臂痛不得上下，痎疟寒热，头痛目眩，赤涩泣出，耳暴聋，咽外肿，牙龈痛。若手臂红肿痛楚，泻之出血为妙。治耳聋不得眠，针入三分补之。《千金》兼中渚，治手臂红肿。《玉龙赋》兼鱼际，能疗喉痛。《百证赋》", "白话": "液门穴在手小指、无名指之间合缝纹头处。针刺二分深，留针二呼，灸三壮。主治惊悸、健忘失语，寒厥臂痛不能上下举动，痎疟寒热，头痛目眩，目赤干涩流泪，突发耳聋，咽外肿痛，牙龈疼痛。若手臂红肿疼痛，用泻法出血为好。治耳聋不得眠，针入三分用补法。《千金方》配中渚，治手臂红肿（《玉龙赋》）。配鱼际，能疗喉痛（《百证赋》）。"}, {"source": "条693｜《千金》", "原文": "《针灸集成》卷四：“液门，在手小指、次指间合缝纹头。针二分、留二呼，灸三壮。主治惊悸忘言，寒厥臂痛不得上下，痎疟寒热，头痛目眩，赤涩泣出，耳暴聋，咽外肿，牙龈痛。若手臂红肿痛楚，泻之出血为妙。治耳聋不得眠，针入三分补之。《千金》兼中渚，治手臂红肿。《玉龙赋》兼鱼际，能疗喉痛。《百证赋》", "白话": "（句译见条692。）本处《千金》引液门“兼中渚，治手臂红肿”之说。"}, {"source": "条694｜《玉龙赋》", "原文": "《针灸集成》卷四：“液门，在手小指、次指间合缝纹头。针二分、留二呼，灸三壮。主治惊悸忘言，寒厥臂痛不得上下，痎疟寒热，头痛目眩，赤涩泣出，耳暴聋，咽外肿，牙龈痛。若手臂红肿痛楚，泻之出血为妙。治耳聋不得眠，针入三分补之。《千金》兼中渚，治手臂红肿。《玉龙赋》兼鱼际，能疗喉痛。《百证赋》", "白话": "（句译见条692。）本处《玉龙赋》引液门“兼鱼际，能疗喉痛”之说。"}, {"source": "条695｜《百证赋》", "原文": "《针灸集成》卷四：“液门，在手小指、次指间合缝纹头。针二分、留二呼，灸三壮。主治惊悸忘言，寒厥臂痛不得上下，痎疟寒热，头痛目眩，赤涩泣出，耳暴聋，咽外肿，牙龈痛。若手臂红肿痛楚，泻之出血为妙。治耳聋不得眠，针入三分补之。《千金》兼中渚，治手臂红肿。《玉龙赋》兼鱼际，能疗喉痛。《百证赋》", "白话": "（句译见条692。）本处《百证赋》为液门条所引歌赋出处。"}, {"source": "条696｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“天井，在肘微后些正中陷中。针三分、留七呼，灸三壮。《甲乙经》：针一分。主治咳嗽上气，胸痛不得言，唾脓，不嗜食，寒热凄凄，不得卧，惊悸悲伤，瘛疭癫疾，五痫风痹，头颈肩背痛，耳聋目锐眥痛，颊肿，肘臂痛不得捉物，及泻一切瘰疬疮肿瘾疹。治咳嗽上气，风痹肘疼，可灸七壮。《神农经》", "白话": "天井穴在肘尖微后方正中凹陷中。针刺三分深，留针七呼，灸三壮。《甲乙经》：针一分。主治咳嗽上气，胸痛不能言语，唾脓，不欲饮食，寒热凄凄，不得卧，惊悸悲伤，瘛疭癫疾，五痫风痹，头颈肩背疼痛，耳聋目外眦痛，面颊肿，肘臂疼痛不能持物，及泻一切瘰疬疮肿瘾疹。治咳嗽上气、风痹肘疼，可灸七壮（《神农经》）。"}, {"source": "条697｜《甲乙经》", "原文": "《针灸集成》卷四：“天井，在肘微后些正中陷中。针三分、留七呼，灸三壮。《甲乙经》：针一分。主治咳嗽上气，胸痛不得言，唾脓，不嗜食，寒热凄凄，不得卧，惊悸悲伤，瘛疭癫疾，五痫风痹，头颈肩背痛，耳聋目锐眥痛，颊肿，肘臂痛不得捉物，及泻一切瘰疬疮肿瘾疹。治咳嗽上气，风痹肘疼，可灸七壮。《神农经》", "白话": "（句译见条696。）本处《甲乙经》引作天井“针一分”之异说。"}, {"source": "条698｜《神农经》", "原文": "《针灸集成》卷四：“天井，在肘微后些正中陷中。针三分、留七呼，灸三壮。《甲乙经》：针一分。主治咳嗽上气，胸痛不得言，唾脓，不嗜食，寒热凄凄，不得卧，惊悸悲伤，瘛疭癫疾，五痫风痹，头颈肩背痛，耳聋目锐眥痛，颊肿，肘臂痛不得捉物，及泻一切瘰疬疮肿瘾疹。治咳嗽上气，风痹肘疼，可灸七壮。《神农经》", "白话": "（句译见条696。）本处《神农经》引天井治“咳嗽上气，风痹肘疼，可灸七壮”之说。"}, {"source": "条699｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“脑空，在悬颅后七分，风池上寸半。针四分，灸五壮。主治劳瘵身热羸瘦，脑风头痛不可忍，项强不得顾，目瞑，鼻衄，耳聋，惊悸，癫风引目眇，鼻痛。", "白话": "脑空穴在悬颅穴后七分，风池穴上一寸半。针刺四分深，灸五壮。主治劳瘵、身热消瘦，脑风头痛不可忍受，颈项强急不能回头，闭目，鼻出血，耳聋，惊悸，癫风牵引目视不明，鼻痛。"}, {"source": "条700｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“蠡沟，在内踝前上五寸，针二分、留三呼，灸三壮。主治疝痛小腹满痛，癃闭，脐下积气如石，数噫，恐悸，少气，足胫寒痠酸屈伸难，腰背拘急不可俛俯仰月经不调，溺下赤白。”", "白话": "蠡沟穴在内踝前上五寸。针刺二分深，留针三呼，灸三壮。主治疝痛、小腹胀满疼痛，小便癃闭，脐下积气如石，频作嗳气，恐惧心悸，气短，足胫寒冷酸痛、屈伸困难，腰背拘急不能俯仰，月经不调，小便下赤白浊物。"}, {"source": "条701｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“上脘，在脐上五寸，巨阙下一寸半，去弊骨三寸。针八分、留七呼，灸五壮。《千金》云：日灸二七壮至百壮三报之，孕妇不可灸。主治心中烦热，痛不可忍，腹中雷鸣，饮食不化，霍乱，翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸，心风惊悸呕血，身热汗不出。治心疼积块，呕吐，可灸十四壮。《神农经》 合中脘，治九种之心疼。《玉龙赋》 兼丰隆，针治心疼呕吐，伤寒吐蚘蛔。《太乙歌》 合神门，治发狂奔走。", "白话": "上脘穴在脐上五寸，巨阙穴下一寸半，距蔽骨（原稿作“弊骨”）三寸。针刺八分深，留针七呼，灸五壮。《千金方》说：每日灸二七壮至百壮，三次报灸，孕妇不可灸。主治心中烦热、疼痛不可忍受，腹中雷鸣，饮食不化，霍乱，翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸，心风惊悸呕血，身热汗不出。治心疼积块、呕吐，可灸十四壮。《神农经》合中脘，治九种心痛（《玉龙赋》）。配丰隆，针治心疼呕吐、伤寒吐蛔（《太乙歌》）。合神门，治发狂奔走（《百证赋》）。治风痫热病、蛔虫心痛（《捷径》）。"}, {"source": "条702｜《千金》", "原文": "《针灸集成》卷四：“上脘，在脐上五寸，巨阙下一寸半，去弊骨三寸。针八分、留七呼，灸五壮。《千金》云：日灸二七壮至百壮三报之，孕妇不可灸。主治心中烦热，痛不可忍，腹中雷鸣，饮食不化，霍乱，翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸，心风惊悸呕血，身热汗不出。治心疼积块，呕吐，可灸十四壮。《神农经》 合中脘，治九种之心疼。《玉龙赋》 兼丰隆，针治心疼呕吐，伤寒吐蚘蛔。《太乙歌》 合神门，治发狂奔走。", "白话": "（句译见条701。）本处《千金》引上脘“日灸二七壮至百壮三报之，孕妇不可灸”之说。"}, {"source": "条703｜《神农经》", "原文": "《针灸集成》卷四：“上脘，在脐上五寸，巨阙下一寸半，去弊骨三寸。针八分、留七呼，灸五壮。《千金》云：日灸二七壮至百壮三报之，孕妇不可灸。主治心中烦热，痛不可忍，腹中雷鸣，饮食不化，霍乱，翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸，心风惊悸呕血，身热汗不出。治心疼积块，呕吐，可灸十四壮。《神农经》 合中脘，治九种之心疼。《玉龙赋》 兼丰隆，针治心疼呕吐，伤寒吐蚘蛔。《太乙歌》 合神门，治发狂奔走。", "白话": "（句译见条701。）本处《神农经》引上脘治心疼积块、呕吐灸法之说。"}, {"source": "条704｜《玉龙赋》", "原文": "《针灸集成》卷四：“上脘，在脐上五寸，巨阙下一寸半，去弊骨三寸。针八分、留七呼，灸五壮。《千金》云：日灸二七壮至百壮三报之，孕妇不可灸。主治心中烦热，痛不可忍，腹中雷鸣，饮食不化，霍乱，翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸，心风惊悸呕血，身热汗不出。治心疼积块，呕吐，可灸十四壮。《神农经》 合中脘，治九种之心疼。《玉龙赋》 兼丰隆，针治心疼呕吐，伤寒吐蚘蛔。《太乙歌》 合神门，治发狂奔走。", "白话": "（句译见条701。）本处《玉龙赋》引上脘“合中脘，治九种之心疼”之说。"}, {"source": "条705｜《太乙歌》", "原文": "《针灸集成》卷四：“上脘，在脐上五寸，巨阙下一寸半，去弊骨三寸。针八分、留七呼，灸五壮。《千金》云：日灸二七壮至百壮三报之，孕妇不可灸。主治心中烦热，痛不可忍，腹中雷鸣，饮食不化，霍乱，翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸，心风惊悸呕血，身热汗不出。治心疼积块，呕吐，可灸十四壮。《神农经》 合中脘，治九种之心疼。《玉龙赋》 兼丰隆，针治心疼呕吐，伤寒吐蚘蛔。《太乙歌》 合神门，治发狂奔走。", "白话": "（句译见条701。）本处《太乙歌》引上脘“兼丰隆，针治心疼呕吐，伤寒吐蚘蛔”之说。"}, {"source": "条706｜《百证赋》", "原文": "《针灸集成》卷四：“上脘，在脐上五寸，巨阙下一寸半，去弊骨三寸。针八分、留七呼，灸五壮。《千金》云：日灸二七壮至百壮三报之，孕妇不可灸。主治心中烦热，痛不可忍，腹中雷鸣，饮食不化，霍乱，翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸，心风惊悸呕血，身热汗不出。治心疼积块，呕吐，可灸十四壮。《神农经》 合中脘，治九种之心疼。《玉龙赋》 兼丰隆，针治心疼呕吐，伤寒吐蚘蛔。《太乙歌》 合神门，治发狂奔走。", "白话": "（句译见条701。）本处《百证赋》引上脘“合神门，治发狂奔走”之说。"}, {"source": "条707｜《捷径》", "原文": "《针灸集成》卷四：“上脘，在脐上五寸，巨阙下一寸半，去弊骨三寸。针八分、留七呼，灸五壮。《千金》云：日灸二七壮至百壮三报之，孕妇不可灸。主治心中烦热，痛不可忍，腹中雷鸣，饮食不化，霍乱，翻胃呕吐，三焦多涎，奔豚伏梁，气胀积聚，黄疸，心风惊悸呕血，身热汗不出。治心疼积块，呕吐，可灸十四壮。《神农经》 合中脘，治九种之心疼。《玉龙赋》 兼丰隆，针治心疼呕吐，伤寒吐蚘蛔。《太乙歌》 合神门，治发狂奔走。", "白话": "（句译见条701。）本处《捷径》引上脘“治风痫热病，蚘蛔虫心痛”之说。"}, {"source": "条708｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“鸠尾，在臆前蔽骨下五分，无蔽骨者，从岐骨歧骨际下行一寸。禁针灸。一云：可针三分，灸三壮，此穴大难下针，非甚妙高手，不可轻针也。主治心惊悸、神气耗散，癫痫狂病。鸠尾能治五般痫，若下湧涌泉人不死。《席弘赋》", "白话": "鸠尾穴在胸前蔽骨之下五分处，无蔽骨者，从岐骨分叉处下行一寸。禁针灸。一说：可针三分，灸三壮。此穴极难下针，非手法高妙之手，不可轻率针刺。主治心惊悸、神气耗散、癫痫狂病。鸠尾能治五般痫证，若再下涌泉穴则人可不死（《席弘赋》）。"}, {"source": "条709｜《席弘赋》", "原文": "《针灸集成》卷四：“鸠尾，在臆前蔽骨下五分，无蔽骨者，从岐骨歧骨际下行一寸。禁针灸。一云：可针三分，灸三壮，此穴大难下针，非甚妙高手，不可轻针也。主治心惊悸、神气耗散，癫痫狂病。鸠尾能治五般痫，若下湧涌泉人不死。《席弘赋》", "白话": "（句译见条708。）本处《席弘赋》引“鸠尾能治五般痫，若下湧涌泉人不死”之说。"}, {"source": "条710｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“神道，在五椎节下间，俛俯而取之。针五分、留五呼，灸五壮。一曰：可灸七七壮至百壮，禁针。主治伤寒头痛，寒热往来，痎疟，悲愁，健忘，惊悸，牙车急，张口不合，小儿风痫瘛疭，可灸七壮。兼心俞，治风痫常发自宁。《百证赋》", "白话": "神道穴在第五胸椎棘突之下，俯身取之。针刺五分深，留针五呼，灸五壮。一说：可灸七七壮至百壮，禁针。主治伤寒头痛，寒热往来，痎疟，悲伤忧愁，健忘，惊悸，牙车（下颌）拘急、张口不合，小儿风痫瘛疭，可灸七壮。配心俞，治风痫常发者自得安宁（《百证赋》）。"}, {"source": "条711｜《百证赋》", "原文": "《针灸集成》卷四：“神道，在五椎节下间，俛俯而取之。针五分、留五呼，灸五壮。一曰：可灸七七壮至百壮，禁针。主治伤寒头痛，寒热往来，痎疟，悲愁，健忘，惊悸，牙车急，张口不合，小儿风痫瘛疭，可灸七壮。兼心俞，治风痫常发自宁。《百证赋》", "白话": "（句译见条710。）本处《百证赋》引神道“兼心俞，治风痫常发自宁”之说。"}, {"source": "条712｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“风府，在项入发际一寸大筋内宛宛中。针三分、留三呼，禁灸，灸则令人瘖。主治中风舌缓，暴瘖不语，振寒汗出，身重偏风、半身不遂，伤风头痛，项急不得回顾，目眩反视，鼻衄咽痛，狂走悲恐惊悸欲自杀。一云：主泻胸中之热，与大杼、缺盆、中府同。风府、风池寻得到，伤寒百病一时消；又云：阳明二日寻风府；又云：从来风府最难寻，须用功夫度浅深，倘若膀胱气未散，更宜三里穴中寻。风伤项急求风府。《通玄赋》", "白话": "风府穴在项后入发际一寸、大筋内侧凹陷中。针刺三分深，留针三呼，禁灸，灸之令人失音。主治中风舌体弛缓，突然失音不语，恶寒战栗、汗出，身体沉重、偏风半身不遂，伤风头痛、颈项强急不能回顾，目眩、目上视，鼻出血、咽痛，狂走、悲伤恐惧、惊悸欲自杀。一说：主泻胸中之热，与大杼、缺盆、中府相同。“风府、风池寻得到，伤寒百病一时消”；又说：“阳明二日寻风府”；又说：“从来风府最难寻，须用功夫度浅深，倘若膀胱气未散，更宜三里穴中寻”。“风伤项急求风府”（《通玄赋》）。一说：治感冒风寒、呕吐不止"}, {"source": "条713｜《通玄赋》", "原文": "《针灸集成》卷四：“风府，在项入发际一寸大筋内宛宛中。针三分、留三呼，禁灸，灸则令人瘖。主治中风舌缓，暴瘖不语，振寒汗出，身重偏风、半身不遂，伤风头痛，项急不得回顾，目眩反视，鼻衄咽痛，狂走悲恐惊悸欲自杀。一云：主泻胸中之热，与大杼、缺盆、中府同。风府、风池寻得到，伤寒百病一时消；又云：阳明二日寻风府；又云：从来风府最难寻，须用功夫度浅深，倘若膀胱气未散，更宜三里穴中寻。风伤项急求风府。《通玄赋》", "白话": "（句译见条712。）本处《通玄赋》引“风伤项急求风府”等歌诀。"}, {"source": "条714｜《千金》", "原文": "《针灸集成》卷四：“风府，在项入发际一寸大筋内宛宛中。针三分、留三呼，禁灸，灸则令人瘖。主治中风舌缓，暴瘖不语，振寒汗出，身重偏风、半身不遂，伤风头痛，项急不得回顾，目眩反视，鼻衄咽痛，狂走悲恐惊悸欲自杀。一云：主泻胸中之热，与大杼、缺盆、中府同。风府、风池寻得到，伤寒百病一时消；又云：阳明二日寻风府；又云：从来风府最难寻，须用功夫度浅深，倘若膀胱气未散，更宜三里穴中寻。风伤项急求风府。《通玄赋》", "白话": "（句译见条712。）本处《千金》引风府为十三鬼穴“鬼枕”（第六次下针）之说。"}, {"source": "条715｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“百会，在前顶后一寸五分顶中央容豆许，直两耳尖。针二分，灸五壮。《甲乙经》曰：针三分，灸三壮。一曰：灸头顶，不得过七七壮。主治头风头痛，耳聋，鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张吐沫，心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫，惊风，脱肛久不瘥。一曰：百病皆治，宜针此二分，得气即泻；若灸至百壮，停三五日后，绕四畔用三棱针出血", "白话": "百会穴在前顶穴后一寸五分、头顶中央凹陷处约容豆大，与两耳尖直对。针刺二分深，灸五壮。《甲乙经》说：针三分，灸三壮。一说：灸头顶，不可超过七七壮。主治头风头痛，耳聋，鼻塞鼻衄，中风语言蹇涩，口噤不开，或多悲伤哭泣，偏风半身不遂，风痫猝厥，角弓反张吐沫，心神恍惚，惊悸健忘，痎疟，妇女血风，胎前产后风疾，小儿风痫惊风，脱肛久治不愈。一说：百病皆治，宜针二分，得气即用泻法；若灸至百壮，停三五日后，绕四周用三棱针刺出血，以井花水淋洗，使气宣通，否则恐火气上壅令人目暗。一说：治悲笑欲死、"}, {"source": "条716｜《甲乙经》", "原文": "《针灸集成》卷四：“百会，在前顶后一寸五分顶中央容豆许，直两耳尖。针二分，灸五壮。《甲乙经》曰：针三分，灸三壮。一曰：灸头顶，不得过七七壮。主治头风头痛，耳聋，鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张吐沫，心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫，惊风，脱肛久不瘥。一曰：百病皆治，宜针此二分，得气即泻；若灸至百壮，停三五日后，绕四畔用三棱针出血", "白话": "（句译见条715。）本处《甲乙经》引作百会“针三分，灸三壮”之异说。"}, {"source": "条717｜《史记》", "原文": "《针灸集成》卷四：“百会，在前顶后一寸五分顶中央容豆许，直两耳尖。针二分，灸五壮。《甲乙经》曰：针三分，灸三壮。一曰：灸头顶，不得过七七壮。主治头风头痛，耳聋，鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张吐沫，心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫，惊风，脱肛久不瘥。一曰：百病皆治，宜针此二分，得气即泻；若灸至百壮，停三五日后，绕四畔用三棱针出血", "白话": "（句译见条715。）本处《史记》载扁鹊治虢太子尸厥、针取三阳五会而苏之事。"}, {"source": "条718｜《神农经》", "原文": "《针灸集成》卷四：“百会，在前顶后一寸五分顶中央容豆许，直两耳尖。针二分，灸五壮。《甲乙经》曰：针三分，灸三壮。一曰：灸头顶，不得过七七壮。主治头风头痛，耳聋，鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张吐沫，心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫，惊风，脱肛久不瘥。一曰：百病皆治，宜针此二分，得气即泻；若灸至百壮，停三五日后，绕四畔用三棱针出血", "白话": "（句译见条715。）本处《神农经》引百会治头风、小儿脱肛灸量之说。"}, {"source": "条719｜《玉龙赋》", "原文": "《针灸集成》卷四：“百会，在前顶后一寸五分顶中央容豆许，直两耳尖。针二分，灸五壮。《甲乙经》曰：针三分，灸三壮。一曰：灸头顶，不得过七七壮。主治头风头痛，耳聋，鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张吐沫，心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫，惊风，脱肛久不瘥。一曰：百病皆治，宜针此二分，得气即泻；若灸至百壮，停三五日后，绕四畔用三棱针出血", "白话": "（句译见条715。）本处《玉龙赋》引百会“兼囟会，治卒暴中风”之说。"}, {"source": "条720｜《灵光赋》", "原文": "《针灸集成》卷四：“百会，在前顶后一寸五分顶中央容豆许，直两耳尖。针二分，灸五壮。《甲乙经》曰：针三分，灸三壮。一曰：灸头顶，不得过七七壮。主治头风头痛，耳聋，鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张吐沫，心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫，惊风，脱肛久不瘥。一曰：百病皆治，宜针此二分，得气即泻；若灸至百壮，停三五日后，绕四畔用三棱针出血", "白话": "（句译见条715。）本处《灵光赋》引“小儿脱肛患多时，先灸百会后尾骶”之说。"}, {"source": "条721｜《席弘赋》", "原文": "《针灸集成》卷四：“百会，在前顶后一寸五分顶中央容豆许，直两耳尖。针二分，灸五壮。《甲乙经》曰：针三分，灸三壮。一曰：灸头顶，不得过七七壮。主治头风头痛，耳聋，鼻塞鼻衄，中风言语蹇滞，口噤不开，或多悲哭，偏风半身不遂，风痫卒厥，角弓反张吐沫，心神恍惚，惊悸健忘，痎疟，女人血风，胎前产后风疾，小儿风痫，惊风，脱肛久不瘥。一曰：百病皆治，宜针此二分，得气即泻；若灸至百壮，停三五日后，绕四畔用三棱针出血", "白话": "（句译见条715。）本处《席弘赋》引百会“兼太冲、照海、阴交，治咽喉疾”之说。"}, {"source": "条722｜《针灸集成》卷四", "原文": "《针灸集成》卷四：“神庭，在直鼻上入发际五分，发高者，际边是穴，发低者，高二三分。灸三壮，禁针，针之令人癫狂目失明。一曰灸七壮至三七壮止。主治发狂登高妄走，风痫癫疾，角弓反张，目上视，不识人，头风鼻渊，流涕不止，头痛目泪，烦满喘喝，惊悸不得安寝。专理头风。《玉龙赋》", "白话": "神庭穴在鼻直上入发际五分，发际高的以发际边缘为穴，发际低的再高二三分。灸三壮，禁针，针之令人癫狂、目失明。一说灸七壮至三七壮为止。主治发狂登高乱走，风痫癫疾，角弓反张，目上视、不识人，头风鼻渊、流涕不止，头痛流泪，烦满喘喝，惊悸不得安睡。专理头风（《玉龙赋》）。"}, {"source": "条723｜《玉龙赋》", "原文": "《针灸集成》卷四：“神庭，在直鼻上入发际五分，发高者，际边是穴，发低者，高二三分。灸三壮，禁针，针之令人癫狂目失明。一曰灸七壮至三七壮止。主治发狂登高妄走，风痫癫疾，角弓反张，目上视，不识人，头风鼻渊，流涕不止，头痛目泪，烦满喘喝，惊悸不得安寝。专理头风。《玉龙赋》", "白话": "（句译见条722。）本处《玉龙赋》引神庭“专理头风”之说。"}, {"source": "条724｜《百家针灸歌赋》天星十一穴歌诀", "原文": "《百家针灸歌赋》 天星十一穴歌诀：“通里腕侧后，度晕寸中，善呻并数欠，懊侬及心忪，实在四肢肿，喉间气难通，虚则不能语，苦呕痛连胸，肘膊连臑痛，头腮面颊红，针入三分妙，神功甚不穷。", "白话": "通里在腕侧之后、一寸之中；善呻吟并频作呵欠，心中懊侬及心忪；实证则四肢浮肿、喉间气息难通，虚证则不能言语、恶心呕吐、痛连胸胁，肘臂连及肩臂疼痛，头腮面颊发红；针入三分甚妙，神功无穷。"}, {"source": "条725｜《医学入门》卷一", "原文": "《医学入门》卷一：“通里，掌后一寸。针入三分，灸三壮。主头痛，目眩，面赤，暴哑，肘腕酸重，热病烦心，心悸，遗尿。", "白话": "通里穴在掌后一寸。针入三分，灸三壮。主治头痛、目眩、面赤、突然失音、肘腕酸重、热病心烦、心悸、遗尿。"}, {"source": "条726｜《医学入门》卷一", "原文": "《医学入门》卷一：“少府，手小指本节后直劳宫陷中。针入三分，灸五壮。主嗌中有气如息肉状，掌热，肘腋手挛急，胸痛烦满，恐悸畏人及阴痛阴痒，遗尿。", "白话": "少府穴在手小指本节之后、与劳宫直对的凹陷中。针入三分，灸五壮。主治咽中气阻如息肉状，掌心发热，肘腋手部拘挛紧急，胸痛烦满，恐惧心悸畏人，以及阴痛阴痒、遗尿。"}, {"source": "条727｜《医学入门》卷一", "原文": "《医学入门》卷一：“京骨，足外侧大骨下赤白肉际陷中。针三分，灸三壮。主头热目眩，白翳从内眦始，鼻衄，鼻不利，涕黄，颈项强痛，脊背及脚难以俯仰，痓，疟，癫狂，惊悸，不食，痰注，髀枢痛，淋沥。", "白话": "京骨穴在足外侧大骨之下、赤白肉际的凹陷中。针三分，灸三壮。主治头热目眩，白翳从内眼角起，鼻出血，鼻不利，涕黄，颈项强痛，脊背及两脚难以俯仰，痓证，疟疾，癫狂，惊悸，不欲饮食，痰注，髀枢（髋部）疼痛，小便淋沥。"}, {"source": "条728｜《医学入门》卷一", "原文": "《医学入门》卷一：“通谷，足小指外侧本节前陷中。针二分，灸三壮。主头重头痛，目眩，咽疮，鼻衄清涕，项强痛，胸胁满，心下悸，留饮数欠，热病汗不出。", "白话": "通谷穴在足小趾外侧本节之前的凹陷中。针二分，灸三壮。主治头重头痛，目眩，咽疮，鼻出血流清涕，颈项强痛，胸胁满闷，心下悸动，留饮、频作呵欠，热病汗不出。"}, {"source": "条729｜《医学入门》卷一", "原文": "《医学入门》卷一：“通谷，幽门下一寸。针五分，灸五壮。主头痛目昏，鼻鼽清涕，项强，口，暴喑，咽喉不利，心中愤郁，惊悸，呕吐，胸满留饮，癖积。", "白话": "通谷穴在幽门穴下一寸。针五分，灸五壮。主治头痛目昏，鼻流清涕，颈项强，口眼㖞斜，突然失音，咽喉不利，心中愤郁，惊悸，呕吐，胸满留饮，癖积。"}, {"source": "条730｜《医学入门》卷一", "原文": "《医学入门》卷一：“彧中，俞府下一寸六分。针四分，灸五壮。主喘悸，余同灵墟。", "白话": "彧中，俞府下一寸六分。针四分，灸五壮。主喘悸，余同灵墟。"}, {"source": "条731｜《医学入门》卷一", "原文": "《医学入门》卷一：“蠡沟，内踝上五寸。针二分，灸三壮。主卒疝小腹肿，时小腹暴痛，小便癃闭，数噫，恐悸，少气，腹痛，咽如有息肉，背拘急，女子赤白带下，暴腹刺痛。", "白话": "蠡沟穴在内踝上五寸。针二分，灸三壮。主治猝疝小腹肿，时而小腹暴痛，小便癃闭，频作嗳气，恐惧心悸，气短，腹痛，咽中如有息肉，背部拘急，女子赤白带下，腹部暴发刺痛。"}, {"source": "条732｜《医学入门》卷一", "原文": "《医学入门》卷一：“神道，五节。禁针，灸三壮。主腰脊急强，痎疟，恍惚，悲愁健忘，惊悸，寒热往来，热喘，目昏头痛。", "白话": "神道穴在第五椎节下（原稿作“五节”）。禁针，灸三壮。主治腰脊拘急强直，痎疟，神志恍惚，悲伤忧愁健忘，惊悸，寒热往来，热喘，目昏头痛。"}, {"source": "条733｜《医学入门》卷一", "原文": "《医学入门》卷一：“百会，前顶上一寸半，头顶中心旋毛中。针三分，灸百五十壮，即停三五日讫。绕四围以三棱针刺令出血，以井花水淋之，令气宣通。频灸拔气上升，令人眼暗。主脱肛，风痫，青风心风，角弓反张，羊鸣多哭，言语不择，发时即死，吐沫，心中热闷，头风多睡，心烦，惊悸健忘，饮食无味，饮酒面赤，头重鼻塞，目泣出，耳鸣聋。", "白话": "百会穴在前顶上一寸半、头顶中心旋毛之中。针三分，灸百五十壮，即停三五日为止。绕四周以三棱针刺令出血，以井花水淋洗，使气宣通。频灸拔气上升，令人眼暗。主治脱肛，风痫，青风心风，角弓反张，羊鸣多哭，言语失次、发作即死，吐沫，心中热闷，头风多睡，心烦，惊悸健忘，饮食无味，饮酒面赤，头重鼻塞，目泪自出，耳鸣耳聋。"}, {"source": "条734｜《医学入门》卷一", "原文": "《医学入门》卷一：“神庭，额前直鼻入发际五分。禁针，误用令人颠，目暗。灸二七壮，至百壮止。主风痫，癫风羊鸣，角弓反张，披发歌哭，惊悸不得安寝，喘渴，头痛目昏，目泣出，鼻流清涕。", "白话": "神庭穴在额前、鼻直上入发际五分。禁针，误用令人癫狂、目暗。灸二七壮至百壮为止。主治风痫，癫风羊鸣，角弓反张，披发歌哭，惊悸不得安睡，喘渴，头痛目昏，目泪自出，鼻流清涕。"}, {"source": "条735｜《医学入门》卷一", "原文": "《医学入门》卷一：“上脘，鸠尾下二寸。针八分，日灸二七壮，至一百壮止，不瘥更倍之。主心中烦热，胀满不能食，霍乱吐利，心痛不得卧，心风，惊悸，闷哕，伏梁气，贲豚气，风痫，热病身热汗不出，三虫，多涎。", "白话": "上脘穴在鸠尾下二寸。针八分，每日灸二七壮至一百壮为止，不愈再加倍。主治心中烦热，胀满不能饮食，霍乱吐泻，心痛不得卧，心风，惊悸，闷恶呃逆，伏梁气，奔豚气，风痫，热病身热汗不出，三虫，多涎。"}, {"source": "条736｜《医学入门》卷一", "原文": "《医学入门》卷一：“神门，主惊悸，怔忡，呆痴等疾，及卒中鬼邪，恍惚振禁，小儿惊痫。", "白话": "神门，主惊悸，怔忡，呆痴等疾，及卒中鬼邪，恍惚振禁，小儿惊痫。"}, {"source": "条737｜《医学入门》卷一", "原文": "《医学入门》卷一：“中渚，主手足麻木，战掉蜷挛，肩臂连背疼痛，手背痈毒。", "白话": "中渚，主手足麻木，战掉蜷挛，肩臂连背疼痛，手背痈毒。"}, {"source": "条738｜《医学入门》卷一", "原文": "《医学入门》卷一：“少冲，主心虚，胆寒，怔忡，癫狂。", "白话": "少冲，主心虚，胆寒，怔忡，癫狂。"}, {"source": "条739｜《医学入门》卷一", "原文": "《医学入门》卷一：“外陵，天枢下一寸。针入八分，灸五壮。主腹中尽痛，心如悬，下引脐痛。", "白话": "外陵穴在天枢穴下一寸。针入八分，灸五壮。主治腹中疼痛，心如悬空，下引脐痛。"}, {"source": "条1｜《先醒斋医学广笔记》卷二", "原文": "太学朱方仲内人，禀赋极弱，兼之作劳善怒，内热怔忡，胆虚气怯，已三四年矣。壬申夏，忽发厥冒，痰气上升，则两目上窜，手足发搐，不省人事。初时一日一发，三四日后，则连发不止，日夜几百次，牛黄、竹沥，遍尝不效。予计已穷，意欲用参、附峻补，因其时常口渴，大便不通，不敢轻投。适一友至，极其赞决，谓非附不可。强用附子二钱，人参六钱，作一剂投下。午后进药，黄昏发大热，烦躁渴甚，不两日毙矣。此固非因附子而然，第证候", "白话": "太学生朱方仲之妻，先天禀赋极弱，又劳作过度、善怒，内热怔忡、胆虚气怯，已经三四年了。壬申年夏天，突然厥逆昏冒，痰气上升，则两目上窜、手足抽搐、不省人事。初时一天发作一次，三四天后连续发作不止，日夜达几百次，牛黄、竹沥等药遍尝无效。我已计穷，想用人参、附子峻补，因她时常口渴、大便不通，不敢轻率投用。恰好一位友人到来，极力主张，说非用附子不可。勉强用附子二钱、人参六钱，作一剂投下。午后进药，黄昏即发高热，烦躁口渴甚剧，不到两天就死了。这固然不是单因附子而致，但此证绝不应当用附子—"}, {"source": "条2｜《素灵微蕴》卷三（案叙）", "原文": "陈梦周，患作酸嗳气，头晕耳鸣，春季膈热，火升头痛，手麻惊悸，不寐善忘，左乳下跳动不息。每午后膝冷病作，鸡鸣膝温而轻，平旦膝暖而差。服燥土疏木之药，饱食甘寝，但胸有火块，游移上下左右，时时冲击微痛，心跳未已。初秋膝冷又发，项脊两肩作痛，面颧浮肿，喷嚏时来，四肢拘急，心跳连脐，遍身筋脉亦动。八月后睡醒口苦，舌根干燥，每夜鸡鸣，膝冷病作，午后膝温而轻，日夕膝暖而差。病来计粒而食，饮啖稍过，胀闷不消，滞气", "白话": "陈梦周，患泛酸嗳气、头晕耳鸣，春季胸膈发热、火气上冲头痛、手麻惊悸、不寐善忘，左乳下跳动不息。每到午后膝冷病作，鸡鸣时膝温而减轻，平旦膝暖则痊愈。服燥土疏木之药后，能饱食安睡，但胸中有火块，游移上下左右，时时冲击微痛，心跳未止。初秋膝冷又发，项脊两肩疼痛，面颧浮肿，时时喷嚏，四肢拘急，心跳连及脐部，遍身筋脉也牵动。八月以后睡醒口苦、舌根干燥，每夜鸡鸣膝冷病作，午后膝温而减轻，日暮膝暖则愈。病中饮食按粒而计，饮啖稍过即胀闷不消、气滞而泄，略吃瓜果便觉腹痛，喝粥则吐稀痰，晚饭稍多"}, {"source": "条3｜《素灵微蕴》卷三（案论）", "原文": "此缘土湿不运，阳气莫藏。心藏神，肾藏精，人之虚灵善悟者，神之发也，睹记不忘者，精之藏也。而精交于神，神归于精，则火不上炎，水不下润，是谓既济。精不交神，则心神飞越，不能知来，神不归精，则肾精驰走，不能藏往，此善忘之由也。精根于神，及其右降而为金，则魄具而精生；神根于精，及其左升而为木，则魂成而神化，《子华子》所谓精秉于金火而气谐于水木也。今火炎于上，则金被其克而不降，水润于下，则木失其政而不升矣…", "白话": "此病源于脾土湿滞不运、阳气无处潜藏。心藏神、肾藏精：人虚灵善悟是神的发用，过目不忘是精的闭藏。精上交于神、神下归于精，则火不上炎、水不下润，这叫「既济」。精不交神，则心神飞越，不能预知；神不归精，则肾精驰走，不能藏往——这是健忘的根由。精根于神，当其右降而为金，则魄具备而精生；神根于精，当其左升而为木，则魂成就而神化，即《子华子》所谓「精秉于金火，而气谐于水木」。如今火炎于上，则金被火克而不能降；水润于下，则木失其政而不能升……悸是肝木（乙木）之郁冲，惊是胆木（甲木）之浮荡："}, {"source": "条4｜《回春录·内科》", "原文": "比丘尼心能，体厚蹒跚，偶患眩悸。医以为虚，久服温补，渐至发肿不饥。仲夏延孟英视之，脉甚弦滑，舌色光绛。主清痰热，尽撤补药。彼不之信，仍服八味等方。至季夏再屈孟英诊之，脉数七至，眠食尽废，不可救药矣。果及秋而荼毗。", "白话": "比丘尼法名心能，体胖步态蹒跚，偶患眩晕心悸。医生认为是虚证，久服温补之药，渐渐全身浮肿、不饥不食。仲夏请王孟英来诊，脉象弦滑甚，舌色光绛。主张清化痰热，把补药全部撤掉。她不相信，仍服八味丸等方。到季夏再请王孟英诊治，脉数一息七至，睡眠饮食全废，已不可救药。果然到秋天就火化（去世）了。"}, {"source": "条5｜《心悸·第八章 评述》导言", "原文": "历代医家实践证明，中医对心悸的治疗从整体出发，辨证施治，有着简、便、验、廉等明显优势，因而日益受到了人们重视。从先秦到清末两千多年间历代医家在长期临床实践中积累了丰富的心悸病证诊疗经验，并留下了大量的文献资料，这些丰富的理论、经验、学术思想更具实用性与鲜活性，通过系统整理、总结，对今人的研究具有宝贵的借鉴价值和指导意义。", "白话": "历代医家的实践证明，中医治疗心悸从整体出发、辨证施治，具有简便验廉的明显优势，因而日益受到人们重视。从先秦到清末两千多年间，历代医家在长期临床实践中积累了丰富的心悸病证诊疗经验，并留下大量文献资料；这些理论、经验与学术思想更具实用性与鲜活性，通过系统整理总结，对今人的研究具有宝贵的借鉴价值和指导意义。"}, {"source": "条6｜《心悸·第八章 评述》导言", "原文": "通过对先贤留下的诸多医案进行梳理，可以看出心悸或外感所致、或气血两虚、或痰饮为病、或痰火相兼、或气血虚伴有痰饮、或病及五脏。", "白话": "通过梳理先贤留下的诸多医案可以看出：心悸或由外感所致，或为气血两虚，或为痰饮为病，或痰火相兼，或气血虚而兼痰饮，或病及五脏。"}, {"source": "条7｜《心悸·第八章 评述》导言", "原文": "实践经验表明，心悸的辨证论治应当首先考量其病源与成因，对心悸的形成机理、人群、治疗过程进行贯通性研究，这是治疗心悸的基本方法。通过这一研究方法既可证实中医在疗效方面的独特优势，又可以洞见历代心悸病证辨证论治成果，做到理论研究与经验研究的有机统一，明晰心悸学术研究的源流与演变，在智知识积累的基础上，推动研究的深化与完善。", "白话": "实践经验表明，心悸的辨证论治应当首先考量病源与成因，对心悸的形成机理、发病人群、治疗过程进行贯通性研究，这是治疗心悸的基本方法。通过这一研究方法，既可证实中医在疗效方面的独特优势，又可以洞见历代心悸病证辨证论治的成果，做到理论研究与经验研究的有机统一，明晰心悸学术研究的源流与演变，在知识积累的基础上推动研究的深化与完善。"}, {"source": "条8｜《心悸·第八章 评述》一、审证求因，辨证论治", "原文": "心悸的形成常与心神不宁、心虚胆怯、心气不足、心血不足、心阳不振、水饮凌心、肝肾阴虚、痰饮内停、瘀血阻络等因素有关。", "白话": "心悸的形成常与心神不宁、心虚胆怯、心气不足、心血不足、心阳不振、水饮凌心、肝肾阴虚、痰饮内停、瘀血阻络等因素有关。"}, {"source": "条9｜《心悸·第八章 评述》一、审证求因，辨证论治", "原文": "《杂病源流犀烛·怔忡》谓：“悸者……非缘外有所触，自然跳动不宁，其原由水衰火旺，故心胸躁动……或水停心下，心为火而恶水，故筑筑跳动不安……或汗吐下后正气虚而悸不得卧……此皆悸病之由也。", "白话": "《杂病源流犀烛·怔忡》说：「悸……并非因外物触动，而是自然跳动不宁，其原由是水衰火旺，所以心胸躁动……或水停心下，心属火而恶水，所以筑筑跳动不安……或汗、吐、下之后正气虚而心悸不得安卧……这些都是悸病的成因。」"}, {"source": "条10｜《心悸·第八章 评述》一、审证求因，辨证论治", "原文": "又曰：“怔忡，心血不足病也……心血消亡，神气内守，则心中空虚，怏怏动摇不得安宁，无时不作，故曰证忡；或由阳气内虚，或由阴血内耗，或由水停心下，水气乘心……，或事故烦冗，用心太劳……，……或由气郁不宣而致心动……，以上皆怔忡所致之由也。", "白话": "又说：「怔忡是心血不足之病……心血消亡而神气内守，则心中空虚，怏怏动摇不得安宁，无时不发作，所以叫怔忡；或因阳气内虚，或因阴血内耗，或因水停心下、水气上乘于心……，或事务繁冗、用心太劳……，……或因气郁不宣而致心动……，以上都是怔忡的成因。」"}, {"source": "条11｜《心悸·第八章 评述》一、审证求因，辨证论治", "原文": "凡外感、内伤诸病中均可出现惊悸、怔忡之因，其因甚多，但以惊恐伤人为最。", "白话": "凡外感、内伤各种疾病中都可出现惊悸、怔忡的病因，其原因很多，但以惊恐伤人最为突出。"}, {"source": "条12｜《心悸·第八章 评述》一、审证求因，辨证论治", "原文": "临证宜“伏其所主，而先其所因”。”故益气养血、滋阴温阳、行气化瘀、化痰涤饮以及养心安神、重镇安神等为历代医家诊治心悸的治疗大法。虚当补之，实当泻之。", "白话": "临证应当「伏其所主，而先其所因」（制服病之所在，先究其病因）。所以益气养血、滋阴温阳、行气化瘀、化痰涤饮以及养心安神、重镇安神等，是历代医家诊治心悸的治疗大法。虚证当补，实证当泻。"}, {"source": "条13｜《心悸·第八章 评述》二、误治传变，谨防危候", "原文": "由于其他疾病迁延不愈或失治误治，致使正气受损，或邪气乘之，亦可导致心悸。", "白话": "由于其他疾病迁延不愈，或失治误治，致使正气受损，或邪气乘虚而入，也可以导致心悸。"}, {"source": "条14｜《心悸·第八章 评述》二、误治传变，谨防危候", "原文": "《伤寒论》中即有太阳病发汗太过或误用下法、少阳病误用汗吐下皆可导致心悸的记载。", "白话": "《伤寒论》中即有记载：太阳病发汗太过，或误用下法，少阳病误用汗、吐、下，都可导致心悸。"}, {"source": "条15｜《心悸·第八章 评述》二、误治传变，谨防危候", "原文": "至于他病传变致悸，《内经》中即指出痹证迁延不愈, 内舍于心，可致心悸；《诸病源候论》中提出金疮可致惊悸，并对脚气风经五脏惊悸、虚劳惊悸的病机进行了初步论述；唐代孙思邈在《备急千金要方》中指出风癫、风眩两病常伴心悸；《太平圣惠方》提出“伤寒后心虚惊悸”；北宋年间的《圣济总录》提出“痈内虚”导致惊悸及肾虚致悸，并对《诸病源候论》中关于脚气风经五脏惊悸、虚劳惊悸的内容进一步发挥。", "白话": "至于其他疾病传变致悸：《内经》即指出痹证迁延不愈、内舍于心，可致心悸；《诸病源候论》提出金疮可致惊悸，并对脚气风经五脏惊悸、虚劳惊悸的病机作了初步论述；唐代孙思邈《备急千金要方》指出风癫、风眩两病常伴心悸；《太平圣惠方》提出「伤寒后心虚惊悸」；北宋《圣济总录》提出「痈内虚」导致惊悸及肾虚致悸，并对《诸病源候论》中脚气风经五脏惊悸、虚劳惊悸的内容进一步发挥。"}, {"source": "条16｜《心悸·第八章 评述》二、误治传变，谨防危候", "原文": "在历代古籍医案中，伤寒过汗、肝风误治及温病误治致惊悸；久疟、吐血、崩漏、胸痹、痹病、痰饮、暑湿、咳久、肺胀、喘病、产后致心悸；癫狂、虚损、痢后、不寐致怔忡等，不胜枚举。", "白话": "历代古籍医案中，伤寒过汗、肝风误治、温病误治致惊悸；久疟、吐血、崩漏、胸痹、痹病、痰饮、暑湿、久咳、肺胀、喘病、产后致心悸；癫狂、虚损、痢后、不寐致怔忡等，不胜枚举。"}, {"source": "条17｜《心悸·第八章 评述》二、误治传变，谨防危候", "原文": "故久病虚实夹杂，病机复杂者则宜标本兼顾，攻补兼施。谨防出现心阳暴脱的厥脱、抽搐等危候。", "白话": "所以久病虚实夹杂、病机复杂者，应当标本兼顾、攻补兼施；谨防出现心阳暴脱的厥脱、抽搐等危候。"}, {"source": "条18｜《心悸·第八章 评述》三、特殊发病人群", "原文": "值得注意的是，通过梳理医案不难发现，心悸多见于小儿、妇人。", "白话": "值得注意的是，通过梳理医案不难发现，心悸多见于小儿和妇女。"}, {"source": "条19｜《心悸·第八章 评述》三、特殊发病人群", "原文": "《保婴撮要》《先醒斋医学广笔记》《医学穷源集》《灵验良方汇编》《临证指南医案》《万病回春》《女科证治准绳》《续名医类案》等有诸多医案记载。妇人产后心悸尤为多发，知晓诱发因素可提前进行调摄防护。", "白话": "《保婴撮要》《先醒斋医学广笔记》《医学穷源集》《灵验良方汇编》《临证指南医案》《万病回春》《女科证治准绳》《续名医类案》等书有诸多医案记载。妇人产后心悸尤为多发，知晓诱发因素即可提前进行调摄防护。"}, {"source": "条20｜《心悸·第八章 评述》四、医家临证特色", "原文": "自明清已降，论述更为精要，对本病认识已臻于完善。虞抟在《医学正传·惊悸怔忡健忘证》中对惊悸、怔忡的区别与联系有详尽的描述；龚居中在其著作中也有相关命题的论述；", "白话": "明清以来论述更为精要，对本病的认识已臻完善。虞抟在《医学正传·惊悸怔忡健忘证》中对惊悸、怔忡的区别与联系有详尽描述；龚居中在其著作中也有相关命题的论述；"}, {"source": "条21｜《心悸·第八章 评述》四、医家临证特色", "原文": "张介宾认为“阴虚”是心悸形成的根本；《景岳全书·怔忡惊悸》指出“怔忡之病，心胸筑筑振动，惶惶惕惕，无时得宁者是也，……此证惟唯阴虚劳损之人乃有之”。", "白话": "张介宾认为「阴虚」是心悸形成的根本；《景岳全书·怔忡惊悸》指出：「怔忡这个病，是心胸筑筑振动、惶惶惕惕、无时得安宁……此证只有阴虚劳损的人才会得。」"}, {"source": "条22｜《心悸·第八章 评述》四、医家临证特色", "原文": "至清乾隆年间，政府组织编纂的大型综合性医书《医宗金鉴》将心悸总结为“筑筑惕惕心动悸，怔怔忡忡不自安，饮多尿少为停水，厥冷汗后是虚寒”。百家争鸣，各有发挥，推动了心悸病诊疗实践的发展。", "白话": "到清乾隆年间，政府组织编纂的大型综合性医书《医宗金鉴》把心悸总结为歌诀：「筑筑惕惕心动悸，怔怔忡忡不自安，饮多尿少为停水，厥冷汗后是虚寒」（心胸筑惕跳动是心动悸，怔怔忡忡不得自安；饮水多而小便少是水停，四肢厥冷、汗出之后是虚寒）。百家争鸣、各有发挥，推动了心悸病诊疗实践的发展。"}, {"source": "条23｜《心悸·第八章 评述》（一）明代龚延贤——养血清火，清痰补虚，益气安神", "原文": "龚氏在《万病回春》中将怔忡与惊悸分别分为三型进行论治。具言之，怔忡，“若思虑即心跳者，是血虚也”，治以四物安神汤兼辰砂安神丸；“心若时跳时止者，是痰因火动也”，治以二陈汤加枳实、麦冬、黄连、山栀、人参、白术、当归、辰砂等；“心慌神乱者，血虚火动也，治以朱砂安神丸”。惊悸，“属血虚火动者，宜养血以清火也”，治以养血安神汤；“属痰火而气虚者，宜清痰火以补虚也”，治以金箔镇心丸：“属心虚气虚而兼有痰者，", "白话": "龚氏在《万病回春》中将怔忡与惊悸各分三型论治。具体而言，怔忡：「若思虑即心跳者，是血虚也」（一思虑就心跳的是血虚），治以四物安神汤兼辰砂安神丸；「心若时跳时止者，是痰因火动也」（心时跳时止的是痰因火动），治以二陈汤加枳实、麦冬、黄连、山栀、人参、白术、当归、辰砂等；「心慌神乱者，血虚火动也」（心慌神乱的是血虚火动），治以朱砂安神丸。惊悸：「属血虚火动者，宜养血以清火也」，治以养血安神汤；「属痰火而气虚者，宜清痰火以补虚也」，治以金箔镇心丸；「属心虚气虚而兼有痰者，宜安神补虚化"}, {"source": "条24｜《心悸·第八章 评述》（二）明代张介宾——益气养心，精气互根，治不离本", "原文": "张氏深谙精气互根之理，强调治病求本，善于把握病机本质。《景岳全书·怔忡惊恐论治》云：“凡治怔忡惊恐者，虽有心脾肝肾之分，然阳统乎阴，心本乎肾。所以上不宁者，未有不由乎下，心气虚者，未有不因乎精。此心肝脾肾之气，名虽有异，而治有不可离者，亦以精气互根之宜然而君相相资之全力也。”提纲掣挈领地对心悸病证的施治进行论述。\n在具体治疗上，张介宾圆通活法，随病情灵活应变：“然或宜先气而后精，或宜先精而后气，或", "白话": "张氏深谙精气互根之理，强调治病求本，善于把握病机本质。《景岳全书·怔忡惊恐论治》说：「凡治怔忡惊恐者，虽有心脾肝肾之分，然阳统乎阴，心本乎肾。所以上不宁者，未有不由乎下，心气虚者，未有不因乎精。此心肝脾肾之气，名虽有异，而治有不可离者，亦以精气互根之宜然而君相相资之全力也」（凡治怔忡惊恐，虽有心脾肝肾之分，但阳统于阴、心本于肾；所以上部不安者，没有不因于下部的，心气虚者，没有不因于精亏的。心肝脾肾之气名称虽异，而治法有不可分者，正因为精气互根、君相相资）。以提纲挈领的方式论述"}, {"source": "条25｜《心悸·第八章 评述》（三）清代叶天士——益气宁心，温化痰饮，补肾清心", "原文": "叶氏治疗心悸未单独列门类，从气血阴阳、，或挟夹痰、饮、瘀综合进行辨证调理，主张“治法宜惟唯理偏”。用药首选补虚药、安神药，其次为清热药、利水渗湿药。近贤程门雪评：“不用金石重镇药，见地极高。重镇则悸反甚，余屡试之，方治心悸络动最好。", "白话": "叶氏治疗心悸未单独列门类，从气血阴阳入手，或兼夹痰、饮、瘀综合辨证调理，主张「治法宜惟唯理偏」（治法宜调理其偏）。用药首选补虚药、安神药，其次为清热药、利水渗湿药。近贤程门雪评价：「不用金石重镇药，见地极高。重镇则悸反甚，余屡试之，方治心悸络动最好」（不用金石重镇药，见识极高；用重镇药心悸反而加重，我多次试过，此法治疗心悸络动最好）。"}, {"source": "条26｜《心悸·第八章 评述》（四）清代王九峰——培养心脾，兼滋肝肾，燮理阴阳", "原文": "王氏在《王九峰医案》中将诊治怔忡总结曰：“《经》以喜怒伤气，寒署伤形，冲脉起于肾下，小于气街，挟脐上行，至胸而散。冲脉动，则诸脉皆动。少腹属厥阴，厥阴肝也。气从少腹蠕动，逆冲于上。心慌意乱，虚里穴跳如跃梭。肾不养肝，气失摄纳，皆根蒂之亏。寡欲固是良谋，更宜恬淡虚无为妙，否则尽恃草木功能，一曝十寒，亦无益也。”\n其师从温补派医家张介宾温补派医家，治疗注重补肾，认为“心为致病之标，肾为致病之本，不必治", "白话": "王氏在《王九峰医案》中总结怔忡的诊治说：「《经》以喜怒伤气，寒署伤形，冲脉起于肾下，小于气街，挟脐上行，至胸而散。冲脉动，则诸脉皆动。少腹属厥阴，厥阴肝也。气从少腹蠕动，逆冲于上。心慌意乱，虚里穴跳如跃梭。肾不养肝，气失摄纳，皆根蒂之亏。寡欲固是良谋，更宜恬淡虚无为妙，否则尽恃草木功能，一曝十寒，亦无益也」（《内经》说喜怒伤气、寒暑伤形；冲脉起于肾下，下行气街，夹脐上行，至胸而散。冲脉动则诸脉皆动。少腹属厥阴，厥阴就是肝。气从少腹蠕动，逆冲于上，心慌意乱，虚里穴跳动如梭。肾不"}, {"source": "条27｜《心悸·第八章 评述》（五）清代林珮佩琴——据证虚实，或补或攻，亦或兼施", "原文": "林氏在《类证治裁·怔忡惊恐论治》中对惊悸证治作做了比较全面的概括，“心脾气血本虚，而致怔忡惊恐，或因大惊猝恐，神志昏乱”者宜七福饮甚或大补元煎；“肾水亏，真阴不足致怔忡”者宜左归饮；“命门衰，真阳不足致怔忡”者宜右归饮；“三阴精血亏损，阴中之阳不足，而致怔忡惊恐”者宜大营煎或理阴煎；“水亏火盛，烦躁热渴而为怔忡惊悸”者宜二阴煎或加减一阴煎；“思虑郁损心营，而为怔忡惊悸”者逍遥散或益营煎；“痰火盛，", "白话": "林氏在《类证治裁·怔忡惊恐论治》中对惊悸证治作了比较全面的概括：「心脾气血本虚，而致怔忡惊恐，或因大惊猝恐，神志昏乱」者，宜七福饮甚至大补元煎；「肾水亏，真阴不足致怔忡」者，宜左归饮；「命门衰，真阳不足致怔忡」者，宜右归饮；「三阴精血亏损，阴中之阳不足，而致怔忡惊恐」者，宜大营煎或理阴煎；「水亏火盛，烦躁热渴而为怔忡惊悸」者，宜二阴煎或加减一阴煎；「思虑郁损心营，而为怔忡惊悸」者，用逍遥散或益营煎；「痰火盛，心下怔忡」者，宜温胆汤加味；「寒痰停蓄心下而怔忡」者，宜姜术汤；「痰"}, {"source": "条28｜《心悸·第八章 评述》（六）清代张聿青——熄息肝宁神，化痰宣窍，养血和营", "原文": "张氏在《张聿青医案》中将诊治心悸过程完整、清晰。心悸兼有痹证者，滋水以涵肝木，育阴而和营血；兼有头痛者，熄息肝和阳；眩晕心跳者，熄息肝宁神。肝胆皆木也，肝木上升，胆木下降，是为和平。惟唯肝升太过，则胆降不及，胆木漂拔，自然气馁，胆病、实肝病也。经云、虚则补其母。木之母，水也，所以降胆必先熄息肝，熄息肝必先滋肾。剂型方面不独用汤剂，而常用膏剂开水化服，久病服用方便效佳。", "白话": "张氏在《张聿青医案》中对心悸的诊治过程记录完整清晰。心悸兼有痹证者，滋水以涵养肝木、育阴而和营血；兼头痛者，「熄息肝」以和阳；眩晕心跳者，「熄息肝」以宁神。肝胆都属木：肝木上升、胆木下降，是为和平；若肝升太过，则胆降不及，胆木虚飘无根，自然气馁——胆病其实是肝病。《经》云「虚则补其母」，木之母是水，所以降胆必先「熄息肝」，「熄息肝」必先滋肾。剂型方面不独用汤剂，而常用膏剂开水化服，久病服用方便、效果好。"}, {"source": "条29｜《心悸·第八章 评述》（七）清代沈金鳌——交通心肾，温阳化饮，益气养心", "原文": "沈氏在《杂病源流犀烛》中以心伤火动、火郁生痰概括悸之病由。水衰火旺者，治以天王补心丹；水停心下者，治以茯苓饮子、半夏麻黄汤；汗吐下后正气虚者，治以温胆汤。怔忡则分二十二型论治，尤为详尽，对怔忡的证治作了做了最为全面的总结。", "白话": "沈氏在《杂病源流犀烛》中以「心伤火动」「火郁生痰」概括悸的病由：水衰火旺者，治以天王补心丹；水停心下者，治以茯苓饮子、半夏麻黄汤；汗吐下后正气虚者，治以温胆汤。怔忡则分二十二型论治，尤为详尽，对怔忡的证治作了最全面的总结。"}, {"source": "条30｜《心悸·第八章 评述》（八）清代费绳甫——和胃清肝，补益心脾，交济水火", "原文": "费氏是孟河医派名家费伯雄之孙，深得家学真传，擅治内科杂病，对心悸治疗深有心得。其提出心悸肝阳激越、血不养心、元阳散越、心火外浮的分型，并提出相应的治则治法用药规律。细言之，肝阳激越，心悸头眩，治宜养阴清肝；血不养心，心悸自觉下坠，治宜培补心血；心阳散越，心悸惊恐，治宜益气镇心，载神返宅；烦恼太过，心火外浮，心悸懊憹，内热舌绛，治宜养心清火。", "白话": "费氏是孟河医派名家费伯雄之孙，深得家学真传，擅治内科杂病，对心悸治疗深有心得。他提出心悸肝阳激越、血不养心、元阳散越、心火外浮的分型，并提出相应的治则治法与用药规律。具体而言：肝阳激越，心悸头眩，治宜养阴清肝；血不养心，心悸自觉下坠，治宜培补心血；心阳散越，心悸惊恐，治宜益气镇心、载神返宅；烦恼太过、心火外浮，心悸懊憹、内热舌绛，治宜养心清火。"}, {"source": "条31｜《心悸·第八章 评述》（九）民国曹沧洲——清心化痰，柔肝益肾，重以去怯", "原文": "曹氏治疗心悸总不离心肝二脏，肝失条达、痰火扰心为其总机。然血不养肝，或水不涵木，皆可使肝失疏泄；或化气火升腾，或成虚阳上扰。但木盛势必克土，土运失司则痰从中生。故治疗养血柔肝、益肾平肝同时，化痰助运自在情理之中。心主神明，惊悸总属心神受扰，标实多为痰火，故清心化痰安神掺杂其中，为标本兼顾之举。此正与清代吴澄《不居集·怔忡惊悸健忘善恐不眠》所谓“心者，身之主，神之舍也。心血不足，或为痰火扰动”相合。", "白话": "曹氏治疗心悸总不离心肝二脏，肝失条达、痰火扰心为其总病机。血不养肝或水不涵木，都可使肝失疏泄，或气火升腾，或成虚阳上扰；但木盛势必克土，脾土运化失司则痰从中生。所以治疗在养血柔肝、益肾平肝的同时，化痰助运自在情理之中。心主神明，惊悸总属心神受扰，标实多为痰火，故清心化痰安神之品掺杂其中，是标本兼顾之举。这正与清代吴澄《不居集·怔忡惊悸健忘善恐不眠》所谓「心者，身之主，神之舍也。心血不足，或为痰火扰动」相合。"}, {"source": "条32｜《心悸·第八章 评述》（十）民国张锡纯——益元养血，兼化痰瘀", "原文": "张氏首次提出胸中大气下陷而致怔忡的新观点，病因、病机、证候和治疗等均有独创性阐发，创制的升陷汤疗效确切，《医学衷中参西录》中记载了多则以升陷汤治疗怔忡验案。张氏在治疗心悸病处方用药中，善用对药，配伍精当。最喜用龙骨、牡蛎，山茱萸、山药，黄芪、知母等。剂型的选择上，也体现张氏灵活多变的用药风格，不拘泥于汤剂，而是与粥、饼、茶以及单味药等巧妙运用。", "白话": "张氏首次提出胸中大气下陷而致怔忡的新观点，对病因、病机、证候和治疗均有独创性阐发，创制的升陷汤疗效确切，《医学衷中参西录》中记载了多则以升陷汤治疗怔忡的验案。张氏治疗心悸处方用药善用对药、配伍精当，最喜用龙骨与牡蛎、山茱萸与山药、黄芪与知母等。剂型选择上也体现其灵活多变的用药风格，不拘泥于汤剂，而与粥、饼、茶及单味药等巧妙运用。"}, {"source": "条33｜《心悸·第八章 评述》结语", "原文": "整体来看，历代医家思辨的主流将心悸病分为“惊悸”、“”和“怔忡”。二者病因病机相似，轻重程度有别，“惊悸”日久不愈可转为重证“怔忡”，可视为同一疾病过程的两个不同阶段，现代中医将其统称为“心悸”病。现代中医学者普遍认为，心悸病相当于西医内科的心律失常、心功能不全、神经官能症等具有心悸临床表现的疾病。随着祖国中医学对心悸病证认识的不断深入发展与积累，心悸病命名趋于统一、概念内涵逐渐明晰、疗效愈加明确", "白话": "整体来看，历代医家思辨的主流将心悸病分为「惊悸」和「怔忡」。二者病因病机相似、轻重程度有别：「惊悸」日久不愈可转为重证「怔忡」，可视为同一疾病过程的两个不同阶段，现代中医将其统称为「心悸」病。现代中医学者普遍认为，心悸病相当于西医内科的心律失常、心功能不全、神经官能症等具有心悸临床表现的疾病。随着中医学对心悸病证认识的不断深入发展与积累，心悸病命名趋于统一、概念内涵逐渐明晰、疗效愈加明确。"}, {"source": "条34｜《心悸·外治评述》导言", "原文": "心悸包括惊悸与怔忡，病情轻者为惊悸，病情重者为怔忡，指心中急剧跳动，惊慌不安，甚则不能自主为主要临床表现的一种病证。历代医家对心悸的治疗方法不仅仅局限于内服药物，在外治方面也有诸多探寻。如采用针刺疗法、艾灸疗法、穴位贴敷疗法、耳穴贴压疗法、穴位按摩疗法、五脏导引疗法、调息疗法、服紫霄疗法、拍打疗法、膏滋疗法、酒剂疗法、药粥疗法、药茶疗法等，本部分围绕古今文献中的心悸外治疗法开展论述，并对历代针灸疗", "白话": "心悸包括惊悸与怔忡：病情轻者为惊悸，病情重者为怔忡，是以心中急剧跳动、惊慌不安，甚则不能自主为主要临床表现的一种病证。历代医家对心悸的治疗方法不限于内服药物，在外治方面也有诸多探寻，如针刺、艾灸、穴位贴敷、耳穴贴压、穴位按摩、五脏导引、调息、服紫霄、拍打、膏滋、酒剂、药粥、药茶等疗法。本部分围绕古今文献中的心悸外治疗法开展论述，并对历代针灸疗法治疗心悸的文献进行辑录。"}, {"source": "条35｜《心悸·外治评述》一、针刺疗法", "原文": "针刺疗法是指运用不同针具刺激机体某些特定部位，通过经络的作用以调节人体功能，从而防病治病的一种治疗方法。针刺治疗心悸疗效显著，可有效降低药物毒副作用和心悸的复发率，已作为一种安全有效的外治法被广泛应用。采用针刺疗法治疗不同证型的心悸，在主穴选取上具有相同的规律，多取如内关穴、神门穴、郄门穴、间使穴、大陵穴等心经及心包经穴位。除内关、神门这两处穴位外，心悸反射点的俞募穴如心俞穴、膻中穴、百会穴、神道", "白话": "针刺疗法是运用不同针具刺激机体某些特定部位，通过经络的作用调节人体功能，从而防病治病的一种治疗方法。针刺治疗心悸疗效显著，可有效降低药物毒副作用和心悸复发率，已作为安全有效的外治法被广泛应用。针刺治疗不同证型的心悸，主穴选取具有相同规律，多取内关、神门、郄门、间使、大陵等心经及心包经穴位；除内关、神门外，心悸反射点的俞募穴如心俞、膻中、百会、神道、灵台等也是常用主穴。配穴则根据心悸辨证分型选用：如心阳不振型常配关元、中脘、血海、气海、膻中等——中脘汇聚水谷之气、膻中汇聚清气、"}, {"source": "条36｜《心悸·外治评述》二、艾灸疗法", "原文": "艾灸疗法是指用纸包裹艾绒卷成圆形的艾卷，一端燃烧，在穴位或患处施灸的一种治疗方法。此方法最早见于明代朱权的《寿阈神方卷•灸阴证》：“用纸实卷艾，以纸隔之点穴，于隔纸上用力按之，待腹内觉热，汗出即瘥。”因操作简便，疗效良好，临床上常用此法治疗心悸。具体操作方法包括温和灸、回旋灸、雀啄灸等。温和灸是将艾卷燃着的一端靠近穴位熏烤（一般距皮肤约3cm），患者有温热舒适感后固定不动，灸至皮肤稍红晕即可，一般", "白话": "艾灸疗法是用纸包裹艾绒卷成圆柱形艾条，一端点燃，在穴位或患处施灸的治疗方法。此法最早见于明代朱权《寿阈神方·灸阴证》：「用纸实卷艾，以纸隔之点穴，于隔纸上用力按之，待腹内觉热，汗出即瘥」（用纸把艾卷紧，以纸隔开点穴，在隔纸上用力按压，待腹内觉热、汗出即愈）。因操作简便、疗效良好，临床常用此法治疗心悸。操作方法包括温和灸、回旋灸、雀啄灸等：温和灸是将艾条燃着端靠近穴位熏烤（一般距皮肤约 3cm），患者有温热舒适感后固定不动，灸至皮肤微红晕即可，一般灸 15 分钟左右；回旋灸又称"}, {"source": "条37｜《心悸·外治评述》三、穴位贴敷疗法", "原文": "穴位贴敷疗法是以中医经络学说为理论依据，把药物研成细末，用水、醋、酒、蛋清、蜂蜜、植物油、清凉油、药液甚至唾液调成糊状，或用呈凝固状的油脂、黄蜡、米饭、枣泥制成软膏、丸剂或饼剂，或将中药汤剂熬成膏，或将药末散于膏药上，再直接贴敷穴位，用来治疗疾病的一种无创痛穴位疗法。此疗法最早见于《五十二病方》中：“蚖……以蓟印其中颠”的记载。穴位贴敷法治疗心悸可选用双侧肺俞穴双、心俞穴双、膈俞穴双、肝俞穴双、大", "白话": "穴位贴敷疗法以中医经络学说为依据，把药物研成细末，用水、醋、酒、蛋清、蜂蜜、植物油、清凉油、药液甚至唾液调成糊状，或用凝固状的油脂、黄蜡、米饭、枣泥制成软膏、丸剂或饼剂，或将中药汤剂熬成膏，或将药末撒于膏药上，直接贴敷穴位以治病，是一种无创痛的穴位疗法。此疗法最早见于《五十二病方》「蚖……以蓟印其中颠」的记载。穴位贴敷治疗心悸可选双侧肺俞、心俞、膈俞、肝俞、大肠俞、肾俞、三焦俞、关元俞及气海穴，每次取 14 穴，每日 1 次。贴敷药材为延胡索、醋甘遂、干姜、细辛、白芥子等，根"}, {"source": "条38｜《心悸·外治评述》四、耳穴贴压法", "原文": "耳穴贴压法简称耳压法，是指在耳穴表面用胶布固定贴压药籽的一种方法。选用耳穴诊治疾病，早在二千多年前的《灵枢•五邪》中就有记载：“邪在肝，则两胁中痛……取耳间青脉以去其掣。”此法操作简便，药籽刺激持久，无不良反应，对心悸患者更为适宜。具体操作方法是结合临床症状进行辩证辨证选穴后，用75%酒精消毒耳廓，选用油菜籽、小米、绿豆、莱菔子、王不留行籽、白芥子等药豆贴紧穴位后用拇指、示食指按捏，手法由轻到重，", "白话": "耳穴贴压法简称耳压法，是在耳穴表面用胶布固定贴压药籽的一种方法。选用耳穴诊治疾病，早在两千多年前的《灵枢·五邪》中就有记载：「邪在肝，则两胁中痛……取耳间青脉以去其掣」（邪在肝，则两胁中痛……取耳间青筋以除其牵掣）。此法操作简便、药籽刺激持久、无不良反应，对心悸患者尤为适宜。操作：结合临床症状辨证选穴后，用 75% 酒精消毒耳廓，选油菜籽、小米、绿豆、莱菔子、王不留行籽、白芥子等药豆贴紧穴位，用拇指、食指按捏，手法由轻到重，使局部产生胀、痛、酸、麻感，每天自行按压 4–5 次"}, {"source": "条39｜《心悸·外治评述》五、穴位按摩疗法", "原文": "穴位按摩疗法指在掌握了一定按摩手法，熟悉了人体一些基本穴位之后，自行在身体上进行按摩的一种最方便、最简单的方法。中医学认为，穴位按摩具有调和气血、疏通经络、益肾补虚、清泄三焦燥热等功效。常见的治疗心悸的按摩手法有按法、点法、揉法、擦法、摩法、捻法等。如瘀血阻络型心悸可选用膻中穴、神封穴调理。可将右手搁在膻中穴，先按顺时针方向轻揉100下，再按逆时针方向轻揉100下；按摩神封穴时将两只手的四指并拢，", "白话": "穴位按摩疗法是掌握一定按摩手法、熟悉人体基本穴位后，自行在身体上按摩的一种最方便、最简单的方法。中医学认为，穴位按摩具有调和气血、疏通经络、益肾补虚、清泄三焦燥热等功效。常见治疗心悸的按摩手法有按法、点法、揉法、擦法、摩法、捻法等。如瘀血阻络型心悸可选膻中、神封穴调理：右手放在膻中穴，先顺时针轻揉 100 下，再逆时针轻揉 100 下；按摩神封穴时两手四指并拢，轻轻按摩两侧胸部边缘的神封穴，一按一放，持续 2–3 分钟。按揉膻中、神封两穴可加强气血运行，具理气化瘀、通经活络、"}, {"source": "条40｜《心悸·外治评述》六、五脏导引疗法", "原文": "五脏导引疗法是一套专门用于治疗五脏疾病的一种运动疗法。原出自唐代胡愔所撰的《黄庭内景五脏六腑补泻图》，明代《遵生八笺》和清代《沈氏尊生书》等相继转载本法，文字上略有出入。此法可用于治疗各种原因引起的心悸，有着很好的疗效。如心血亏虚型心悸可采用脾脏导引法，具体操作方法为采用坐式，一脚前伸，一脚屈曲，同时两手向后拉伸，左右交替各15次。亦可跪坐，两手按地，头部向两侧交替怒目后视各15次。此疗法操作时宜", "白话": "五脏导引疗法是专门用于治疗五脏疾病的一套运动疗法，原出唐代胡愔《黄庭内景五脏六腑补泻图》，明代《遵生八笺》、清代《沈氏尊生书》等相继转载，文字略有出入。此法可治疗各种原因引起的心悸，疗效很好。如心血亏虚型心悸可采用脾脏导引法：取坐式，一脚前伸、一脚屈曲，同时两手向后拉伸，左右交替各 15 次；也可跪坐，两手按地，头部向两侧交替怒目后视各 15 次。操作时宜量力而行，动作幅度由小渐大，不可骤然用力，且不宜饱食后进行。高血压、青光眼、脑动脉硬化、肝硬化者慎用。"}, {"source": "条41｜《心悸·外治评述》七、调息疗法", "原文": "调息疗法是一种静功自我疗法，主要通过调整呼吸排除杂念，使元气恢复或增强，从而祛除病邪防治心悸。调息疗法原载于清代著名医家李士材的弟子尤乘编纂的《寿世青编•勿药须知》中，后来汪昂在《医方集解•勿药元诠》中曾予以转录。调息疗法用于心悸可以起到静心安神的疗效。此方法可用于各种原因引起的心悸。具体操作方法为不拘时候，随便而坐，宽衣松带，躯干正直，两手置腿膝或握置小腹前，全身放松。以舌搅口腔数遍，微微呵出浊", "白话": "调息疗法是一种静功自我疗法，主要通过调整呼吸排除杂念，使元气恢复或增强，从而祛除病邪、防治心悸。原载于清代李士材弟子尤乘编纂的《寿世青编·勿药须知》，后汪昂《医方集解·勿药元诠》曾予转录。用于心悸可起静心安神之效，适用于各种原因引起的心悸。操作：不拘时候，随便而坐，宽衣松带，躯干正直，两手置腿膝或握于小腹前，全身放松；以舌搅口腔数遍，微微呵出浊气数口，以鼻微微纳清气 3–5 次（呵气与纳气皆不可有声），口中有津液即咽下；再叩齿数遍，舌抵上颚，两目垂帘、微露一线光，呈朦胧之状。"}, {"source": "条42｜《心悸·外治评述》八、服紫霄疗法", "原文": "服紫霄疗法是一种以存想为主的静功自我疗法，主要借助于存想“天边紫霄”自头入腹以安神宁心，培植元气，而获得防治心悸之效。此疗法原出《摄养枕中方》，宋代《云笈七签》卷三十五转载了此疗法。所谓“服”者，并非口服，只是存想“紫霄”（高空紫色的云气）入腹而已。可治疗各种原因引起的心悸，心慌不安，甚至乏力者。具体操作方法为盘坐或平坐于静室内，两手握固，忘却一切。片刻后，观想自身元神从头顶冲出，穿屋顶直上，到达", "白话": "服紫霄疗法是一种以存想为主的静功自我疗法，主要借助存想「天边紫霄」自头入腹，以安神宁心、培植元气，从而防治心悸。原出《摄养枕中方》，宋代《云笈七签》卷三十五转载。所谓「服」并非口服，只是存想「紫霄」（高空紫色云气）入腹而已。可治疗各种原因引起的心悸、心慌不安甚至乏力。操作：盘坐或平坐于静室，两手握固，忘却一切；片刻后观想自身元神从头顶冲出，穿屋顶直上，到达无限遥远的天空，元神吸引空中紫色云彩，又自上而下，穿屋过头顶，直达腹中；如感觉紫气尚未充满腹中而弥散全身，可连续做数次，直"}, {"source": "条43｜《心悸·外治评述》九、拍打疗法", "原文": "拍打疗法是经手法刺激，通过经络的作用，使体内的气血通畅，脏腑功能恢复正常以达到治愈疾病的一种方法，属于传统治法中的点穴疗法范畴。用拍打疗法治疗心悸，具有简便易行，安全有效的特点。治疗各种原因引起的心悸可以采用此疗法拍打胸部、上腹部，每天2次，每次150下左右。运用拍打疗法要由轻到重，由缓至急，循序渐进。在采用此方法治疗心悸的同时，也可根据病情需要配合其它其他疗法。", "白话": "拍打疗法是通过手法刺激、经由经络作用，使体内气血通畅、脏腑功能恢复正常以治病的方法，属传统点穴疗法范畴。拍打治疗心悸简便易行、安全有效。各种原因引起的心悸均可拍打胸部、上腹部，每天 2 次、每次 150 下左右。运用时要由轻到重、由缓至急、循序渐进；也可根据病情需要配合其他疗法。"}, {"source": "条44｜《心悸·外治评述》十、膏滋疗法", "原文": "膏滋是将食物或药物加水煮煎，滤出汁液进行浓缩，加入糖或者蜂蜜熬炼成稠厚的膏药。因此类药膏大多数具有滋补性能，故称为膏滋。膏滋疗法是在中医理论指导下，使用膏滋预防和治疗疾病的一种独特的疗法。如症见心悸易惊，心烦失眠，口干微热可服用玉苓膏。方用龙眼肉30g、白糖3g、西洋参3g，共置碗内，每日于饭锅上蒸之，蒸至多次，每服1匙，早晚各1次。应用膏滋大多时间较长，应注意保存，防止霉变。", "白话": "膏滋是将食物或药物加水煮煎，滤出汁液浓缩，加入糖或蜂蜜熬炼成稠厚的膏。因这类药膏大多具有滋补性能，故称膏滋。膏滋疗法是在中医理论指导下，用膏滋预防和治疗疾病的一种独特疗法。如症见心悸易惊、心烦失眠、口干微热，可服玉苓膏：龙眼肉 30g、白糖 3g、西洋参 3g，共置碗内，每日放在饭锅上蒸，蒸多次后每服 1 匙，早晚各 1 次。膏滋应用时间大多较长，应注意保存、防止霉变。"}, {"source": "条45｜《心悸·外治评述》十一、酒剂疗法", "原文": "酒剂疗法又称药酒疗法，是指以酒作为溶媒浸泡中药材，浸出有效成分而得到澄明液体的制剂。《史记•扁鹊仓公列传》记载了西汉名医淳于意用三石药酒治疗“风厥胸满”病。如心血瘀阻型心悸，症见心悸怔忡，胸痛不舒，心痛时作者可饮用桃红酒。方用桃仁10g、红花30g、白酒500g。制法为将桃仁用开水浸泡，去皮尖，麸炒微黄，捣碎后与红花和酒同浸于干净容器中，封口，煮沸取下侯，候冷后搅匀。每次饮用10-~20mlmL，", "白话": "酒剂疗法又称药酒疗法，是以酒为溶媒浸泡中药材、浸出有效成分而得澄明液体的制剂。《史记·扁鹊仓公列传》记载西汉名医淳于意用三石药酒治疗「风厥胸满」病。如心血瘀阻型心悸，症见心悸怔忡、胸痛不舒、心痛时作者，可饮桃红酒：桃仁 10g、红花 30g、白酒 500g。制法：桃仁开水浸泡、去皮尖，麸炒微黄，捣碎后与红花、酒同浸于干净容器中，封口，煮沸取下，候冷后搅匀。每次饮 10–20ml，每日 1–2 次。酒精过敏、胃溃疡、肝肾功能不全、有出血倾向及精神病患者均不宜；阴虚火旺者不宜饮高"}, {"source": "条46｜《心悸·外治评述》十二、药粥疗法", "原文": "将中药与米谷同煮为粥，成为药粥。运用药粥预防和治疗疾病的方法即药粥疗法。汉代张仲景在《伤寒杂病论》中有许多药粥同用或药后食粥的论述，如服“桂枝汤”时必须饮粥以助药力。药粥疗法用于心悸，效果颇佳。如阴虚火旺型心悸，可饮用玉竹麦冬粥。方用玉竹20g、麦冬15g、百合30g、糯米100g、冰糖适量，分早晚温服。药粥疗法多为辅助疗法，对某些急性病、重病患者不宜单独使用；选用药粥应辩证辨证施粥，最好在有经验", "白话": "将中药与米谷同煮为粥，即成药粥；用药粥预防和治疗疾病的方法即药粥疗法。汉代张仲景《伤寒杂病论》中有许多药粥同用或药后食粥的论述，如服「桂枝汤」时必须饮粥以助药力。药粥疗法用于心悸效果颇佳。如阴虚火旺型心悸，可饮玉竹麦冬粥：玉竹 20g、麦冬 15g、百合 30g、糯米 100g、冰糖适量，分早晚温服。药粥疗法多为辅助疗法，某些急性病、重病患者不宜单独使用；选用药粥应辨证施粥，最好在有经验的中医师指导下应用。"}, {"source": "条47｜《心悸·外治评述》十三、药茶疗法", "原文": "药茶疗法是指应用茶或茶加上某些中药或者有药性的食物，经加工制成茶剂饮用，用于防治疾病的一种方法。距今二两千年前的《神农本草经》中就已将茶叶作为一味重要的药物，认为“茶味苦，饮之使人益思、少卧、轻身名目。”如气血阴阳亏虚，心失所养导致的心悸可饮用枣仁夜交藤合欢茶，方用枣仁30g、夜交藤30g、合欢花10g、合欢皮10g、生甘草5g，水煎后代茶饮，具有益气养血、解郁安神的功效。凡年老体虚者、慢性疾病者", "白话": "药茶疗法是用茶或茶加某些中药、有药性的食物，加工制成茶剂饮用以防治疾病的方法。距今约两千年前的《神农本草经》已将茶叶作为一味重要药物，认为「茶味苦，饮之使人益思、少卧、轻身明目」（茶味苦，饮之使人多思虑、少睡眠、身轻目明）。如气血阴阳亏虚、心失所养导致的心悸，可饮枣仁夜交藤合欢茶：枣仁 30g、夜交藤 30g、合欢花 10g、合欢皮 10g、生甘草 5g，水煎代茶饮，具益气养血、解郁安神之效。年老体虚者、慢性病者用此法治疗心悸应长期少量饮用；药茶当日冲泡当日饮用。"}, {"source": "条48｜《心悸·外治评述》十四、盐热敷疗法", "原文": "盐热敷疗法是中医热敷疗法的一种，是将食盐爆炒受热后，置于身体的病患部位以驱祛除病邪的一种疗法。盐热敷疗法历史悠久，可追溯至春秋战国时期。《史记•扁鹊仓公列传》中载：“扁鹊，乃使子豹为五分之熨，以八减之齐（剂）和煮之，以更熨两胁下。太子起坐。”盐热敷疗法的具体操作为将生粗盐约250克g放在铁锅内，用急火爆炒，然后趁热用纸包裹，外面包一层布（或者直接用布包），放在患处。亦可食盐布包，微波炉加热后，放于", "白话": "盐热敷疗法是中医热敷疗法的一种，将食盐爆炒受热后置于病患部位以驱除病邪。历史悠久，可追溯至春秋战国时期。《史记·扁鹊仓公列传》载：「扁鹊，乃使子豹为五分之熨，以八减之齐（剂）和煮之，以更熨两胁下。太子起坐」（扁鹊让弟子子豹做五分热熨，用八减之剂和煮，交替熨两胁下，虢太子于是起坐）。操作：生粗盐约 250g 放铁锅内急火爆炒，趁热用纸包裹、外包一层布（或直接用布包），放在患处；也可将食盐布包用微波炉加热后放于患处。心脾两虚型心悸可用热盐敷额部。须注意避免烫伤，治疗中如有不适应立"}, {"source": "条49｜《心悸·外治评述》十五、鸡敷疗法", "原文": "鸡敷疗法是用雄鸡加药物外敷以达到治疗目的的一种疗法。此疗法在土家族流传很广，其作用机制是通过雄鸡的温热作用促使药力直达病所而起到治疗作用。具体操作方法为取500g雄鸡1只，剖开肚子腹部去掉内脏，将事先准备好的药粉撒在鸡肚子内，加白酒喷洒趁热贴敷于患者胸部，半小时即可。如病未减轻，过4-~8小时再贴1次。此法可治疗各种原因引起的心悸气短，胸闷乏力，心惊不安等症状。方用雄黄10g、冰片10g、石膏50", "白话": "鸡敷疗法是用雄鸡加药物外敷以治病的疗法，在土家族流传很广，其作用机制是借雄鸡的温热作用促使药力直达病所。操作：取 500g 雄鸡 1 只，剖开腹部去掉内脏，将备好的药粉撒在鸡肚内，加白酒喷洒，趁热贴敷患者胸部，半小时即可；如病未减轻，过 4–8 小时再贴 1 次。可治各种原因引起的心悸气短、胸闷乏力、心惊不安等。方用雄黄 10g、冰片 10g、石膏 50g、金银花 30g、麝香 1g 研细末备用；或雄黄 6g、皮硝 10g、蓖麻 3g、冰片 1g 研细末备用。雄鸡最好选当年的"}, {"source": "条50｜《心悸·外治评述》十六、香佩疗法", "原文": "香佩疗法是将芳香性药物装入小布袋或荷包内佩带在身上以防治疾病的一种方法。汉代华佗在《中藏经》中记述了用绛囊盛安息香来防治传尸、肺萎、时气、瘴虐等病，是香佩疗法较早较全面的治例。如治疗各种原因引起的心悸可用川芎、砂仁、细辛、薄荷各等份，研末做成香佩，戴在身上经常闻嗅。对药物气味过敏者不宜应用此法。", "白话": "香佩疗法是把芳香性药物装入小布袋或荷包内佩带身上以防治疾病的方法。汉代华佗《中藏经》记述用绛色布囊盛安息香防治传尸、肺萎、时气、瘴虐等病，是香佩疗法较早、较全面的治例。治疗各种原因引起的心悸，可用川芎、砂仁、细辛、薄荷各等份研末做香佩，戴在身上经常闻嗅。药物气味过敏者不宜。"}, {"source": "条51｜《心悸·外治评述》十七、药枕疗法", "原文": "药枕疗法是将某种药物装入袋内用作枕以治疗疾病的一种方法。晋代葛洪的《肘后备急方》中就有用蒸大豆装枕以治疗失眠的记载。唐代孙思邈《备急千金要方》载有“治头项强不得四顾方，蒸好大豆一斗，令色变，内囊中枕之”。”如治疗心阳不振型心悸可用丁香桂心枕，方用公丁香500g、肉桂心500g、大附子200g、麻黄150g、细辛100g。将上述药物分别烘干，碾碎混匀，装入枕芯，制成药枕，令病人患者枕之。枕前需喝温开", "白话": "药枕疗法是把药物装入袋内作枕以治病的方法。晋代葛洪《肘后备急方》已有用蒸大豆装枕治疗失眠的记载；唐代孙思邈《备急千金要方》载「治头项强不得四顾方，蒸好大豆一斗，令色变，内囊中枕之」（治头项强痛不能四顾方：蒸好大豆一斗，蒸至色变，装入囊中作枕）。治疗心阳不振型心悸可用丁香桂心枕：公丁香 500g、肉桂心 500g、大附子 200g、麻黄 150g、细辛 100g，分别烘干、碾碎混匀，装入枕芯制成药枕，令患者枕之。枕前需饮温开水 50mL；阴血不足、虚火上炎者禁用。药枕见效较慢，"}, {"source": "条52｜《心悸·外治评述》十八、冷水疗法", "原文": "冷水疗法是用冷水冲洗、浸浴、饮用、摩擦、包裹或拍打来治疗疾病的一种疗法。唐代孙思邈的《千金要方》《备急千金要方》中记载的用新汲水和蜜饮之以治心闷汗出就是冷水疗法治疗心悸的病例之一。如症见心悸，失眠健忘，头痛头晕者可采用冷水浸浴的方法，即将身体的全部浸在冷水中10分钟，出冷水后擦干身体，每周2次；或者采用冷水摩擦的方法，即用冷水浸湿毛巾摩擦全身直至皮肤发红为止，擦过之后再用干毛巾拭干身体表面的水分，", "白话": "冷水疗法是用冷水冲洗、浸浴、饮用、摩擦、包裹或拍打来治病的方法。唐代孙思邈《备急千金要方》记载用新汲水和蜜饮之治疗心闷汗出，就是冷水疗法治疗心悸的病例之一。如症见心悸、失眠健忘、头痛头晕者，可用冷水浸浴：全身浸入冷水中 10 分钟，出水后擦干，每周 2 次；或冷水摩擦：用冷水浸湿毛巾摩擦全身直至皮肤发红，再用干毛巾拭干水分，每周 1 次。虚寒体质禁用；年老体弱、妇女经期、妊娠期、冠心病患者不宜用。宜夏季使用，冬季可用温水。"}, {"source": "条53｜《心悸·外治评述》结语", "原文": "心悸病症虽在心，实则与肝、脾、肾及情志因素均有密不可分的关系，随着对心悸病因病机研究的逐渐深入，中医外治法也越来越独特、精细，体系愈加完备，疗效更加显著。在中医基础理论的指导下，外治法治疗心悸大多会依据其辩证辨证进行分型论治。有些方法手法简单，便于操作；有些方法使用极少的药性较为平和药物在正常饮食生活中即可达到去除病痛的效果。在所有外治法中，针灸疗法为心悸的主要外治法之一，可见于历代针灸学著作中，", "白话": "心悸病位虽在心，实则与肝、脾、肾及情志因素均有密不可分的关系。随着心悸病因病机研究的逐渐深入，中医外治法越来越独特精细、体系愈完备、疗效更显著。在中医基础理论指导下，外治法治疗心悸大多依据辨证分型论治：有些方法手法简单、便于操作；有些方法只用极少的平和药物，在正常饮食生活中即可去除病痛。所有外治法中，针灸是心悸的主要外治法之一，历代针灸学著作均有记载，疗效显著。针灸治疗心悸总体以安神、定悸、调理心气为主要原则；选穴相对集中，具有循经取穴为主、辨证取穴为辅、远端取穴辅以局部取穴"}, {"source": "条1｜《校注妇人良方》卷三", "原文": "一妇人劳则心跳怔忡，寒热往来，用归脾汤为主，佐以八珍汤，诸症渐愈。又用加味逍遥散、宁志丸而安。后复作，服归脾、定志二药即愈。", "白话": "一位妇女，劳累就心跳怔忡，寒热往来。医家用归脾汤为主方，配合八珍汤，各种症状逐渐痊愈；又用加味逍遥散、宁志丸而安。后来复发，服归脾汤、定志二药即愈。"}, {"source": "条2｜《校注妇人良方》卷三", "原文": "一妇人患惊悸怔忡，日晡发热，月经过期，饮食少思，用八珍汤加远志、山药、酸枣仁，三十余剂渐愈，佐以归脾汤痊全愈。后因劳发热，食少体倦，用补中益气汤。又因怒，适月经去血不止，前症复作，先以加味逍遥散，热退经止，又用养心汤治之而痊。", "白话": "一位妇女患惊悸怔忡，午后发热，月经过期，饮食少思。用八珍汤加远志、山药、酸枣仁，三十余剂逐渐痊愈，配合归脾汤而完全治愈。后因劳累发热、食少体倦，用补中益气汤；又因发怒，正值月经血出不止，前症复发，先用加味逍遥散，热退经止，再用养心汤治愈。"}, {"source": "条3｜《校注妇人良方》卷三", "原文": "一妇人惊悸怔忡无寐，自汗盗汗，饮食不甘，怠惰嗜卧，用归脾汤而愈。至年余，怀抱郁结，患前症，兼衄血便血，仍用前汤而愈。", "白话": "一位妇女惊悸怔忡、不能入睡，自汗盗汗，饮食无味，怠惰嗜卧。用归脾汤治愈。过了一年多，情志郁结，旧病复发，并兼衄血、便血，仍用归脾汤治愈。"}, {"source": "条4｜《校注妇人良方》卷十九", "原文": "产后心神惊悸恐惧，或目睛不转，口不能言，乃心气虚而六淫内侵。诊其脉动而弱者，惊悸也。动则为惊，弱则为悸矣。一产妇患前症二度，服琥珀地黄丸、《局方》妙香散，随效。再患服之，其症益甚，而脉浮大，按之如无，发热恶寒，此血气俱虚。余用十全大补、加味归脾二汤，各百余剂而愈。后遇惊恐劳怒复作，仍复前药而安。", "白话": "产后心神惊悸恐惧，或目睛不转、口不能言，是心气虚而六淫之邪内侵。诊其脉动而弱者为惊悸：动则为惊，弱则为悸。一位产妇两次患此症，服琥珀地黄丸、《局方》妙香散即效；再患时服之反而加重，脉浮大、按之如无，发热恶寒，此为气血俱虚。我用十全大补汤、加味归脾汤各百余剂而愈。后来遇惊恐劳怒复发，仍用前药而安。"}, {"source": "条5｜《石山医案·附录》", "原文": "一女，年十五，病心悸，常若有人捕之，欲避而无所也。其母抱之于怀，数婢护之于外，犹恐恐然不能安寝。医者以为病心，用安神丸、镇心丸、四物汤不效。居士诊之，脉皆细弱而缓。曰：此胆病也。用温胆汤服之而安。", "白话": "一女，年十五，病心悸，常觉有人要抓她，想躲避又无处可躲。她母亲把她抱在怀里，几个丫鬟在门外守着，她还是惶惶不能安睡。别的医生当作心病，用安神丸、镇心丸、四物汤无效。汪机（石山居士）诊之，脉皆细弱而缓，说：这是胆病。用温胆汤服之而安。"}, {"source": "条6｜《保婴撮要》卷十", "原文": "一女子素血虚惊悸，出嫁后更怔忡晡热，月经过期。用八珍汤加远志、山药、酸枣仁，三十余剂渐愈，佐以归脾汤痊愈。后因劳怒，适经行不止，前症复作。先用加味逍遥散，热退经止，又用养心汤而痊。", "白话": "一女子平素血虚惊悸，出嫁后更见怔忡、午后发热、月经过期。用八珍汤加远志、山药、酸枣仁，三十余剂逐渐痊愈，配合归脾汤治愈。后因劳累发怒，正值经行不止，前症复发，先用加味逍遥散热退经止，再用养心汤而痊。"}, {"source": "条7｜《保婴撮要》卷十", "原文": "一小儿十五岁，因用心太过，少寐惊悸，怔忡恶寒。先用补中益气汤、茯苓、酸枣仁、远志，恶寒渐止；又用加味归脾汤，惊悸稍安；又用养心汤而愈。", "白话": "一小孩十五岁，因用心太过，睡眠少、惊悸，怔忡恶寒。先用补中益气汤加茯苓、酸枣仁、远志，恶寒渐止；又用加味归脾汤，惊悸稍安；再用养心汤而愈。"}, {"source": "条8｜《保婴撮要》卷十", "原文": "一小儿惊悸，睡卧不安，发热饮冷，用治要茯苓散而愈。又因劳役恚怒，发热吐痰自汗，用温胆汤，二剂而安，又用归脾汤、宁志丸而愈。", "白话": "一小孩惊悸，睡卧不安，发热而喜冷饮，用治要茯苓散而愈。又因劳役恼怒，发热、吐痰、自汗，用温胆汤两剂而安，再用归脾汤、宁志丸而愈。"}, {"source": "条9｜《保婴撮要》卷十", "原文": "一小儿十三岁，善思多忧，体倦发热，心怀畏惧，必多人相伴乃止。用茯神汤，佐以归脾汤，两月余渐愈。毕姻后，前症复作，加寒热头晕。先用前二汤而惊悸愈，后用十全大补汤、补中益气汤，诸症渐愈。后因科举入场劳役，朝寒暮热，自服前二汤各三十余剂，不应。时仲秋，脉虚大，按之微细，面白腹痛，亦用前方，倍加肉桂、干姜，四剂亦不应。遂以八味丸料，煎服四剂，稍缓，又四剂，渐愈，乃用八味丸、十全大补汤而安。", "白话": "一小孩十三岁，善思多忧，体倦发热，心怀畏惧，必有多人陪伴才安。用茯神汤，配合归脾汤，两月余逐渐痊愈。成婚后旧症复发，加寒热头晕，先用前二方而惊悸愈，后用十全大补汤、补中益气汤诸症渐愈。后因科举入场劳役，朝寒暮热，自服前二方各三十余剂无效。时值仲秋，脉虚大、按之微细，面白腹痛，仍用前方，倍加肉桂、干姜，四剂亦无效。遂用八味丸料煎服四剂，稍缓；又四剂渐愈，再用八味丸、十全大补汤而安。"}, {"source": "条10｜《保婴撮要》卷十", "原文": "一女子十五岁，性沉静，被盗所恐，遂惊悸，腹胁胀痛，寒热往来，不食无寐，善思恐惧，用酸枣仁丸、归脾汤、加味逍遥散而寻愈。出嫁后，因丧子兼大劳，惊悸无寐，吐痰发热，饮食少思，胸腹膨胀，服化痰药，日吐痰四五碗。时考续至京，请治。余谓脾肺虚寒，不能摄涎化食而为痰也。用六君、干姜六剂，痰益甚，手足并冷；用前药，每加附子一钱，仍不应；乃用人参一两，附子二钱，四剂始稍缓；又二剂，仍用六君加姜、附各五分，数剂后，", "白话": "一女子十五岁，性情沉静，被盗贼惊吓，遂惊悸、腹胁胀痛、寒热往来、不食不寐、善思恐惧。用酸枣仁丸、归脾汤、加味逍遥散而渐愈。出嫁后因丧子加上过劳，惊悸不寐、吐痰发热、饮食少思、胸腹膨胀。服化痰药后每天吐痰四五碗。时逢其父考绩到京，请我诊治。我说这是脾肺虚寒，不能摄涎化食而生痰。用六君子汤加干姜六剂，痰反而更多，手足并冷；用前药每剂加附子一钱，仍无效；乃用人参一两、附子二钱，四剂才稍缓；又二剂，仍用六君子汤加姜、附各五分，数剂后改用肉桂治愈。"}, {"source": "条11｜《保婴撮要》卷十", "原文": "一小儿十五岁，彻夜用功记诵，去后少寐，仍不戒劳，患怔忡发热不止，用归脾汤为主，佐以八珍汤，诸症渐愈。后复作，服归脾、定志二药即愈。", "白话": "一小孩十五岁，彻夜用功背诵，睡得很少，仍不戒劳，患怔忡发热不止。用归脾汤为主，配合八珍汤，诸症渐愈。后复发，服归脾汤、定志二药即愈。"}, {"source": "条12｜《医学入门》卷首", "原文": "宁阳侯孙生九月，惊悸、频啼而汗，百方莫效。公命坐儿于地，使掬水为戏，惊啼顿止。人问之，曰：时当季春，儿丰衣帷处不离怀抱，其热郁安所泄耶？使之近水，则火邪杀，得土气则脏平，故不药而愈。吴下小儿医善钱氏云。", "白话": "宁阳侯的孙子生下九个月，惊悸、频频啼哭而汗出，百方无效。某公让孩子坐在地上，让他捧水作游戏，惊啼立止。有人问其故，答道：时当季春，孩子穿得厚、住在帷帐里、不离怀抱，内热郁遏往哪里泄呢？让他接近水，则火邪被制；得土气（坐地）则脏气得平，所以不药而愈。吴地小儿科医生多推崇钱乙（钱氏）之说。"}, {"source": "条13｜《医学入门》卷首", "原文": "治一人因心高志大，所谋不遂，怔忡善忘，口淡舌燥，多汗，四肢疲软，发热，小便白浊。诸医以内伤不足，拟进茸、附。公视其脉，虚大而数，曰：此思虑过度，少阴君火行患耳。夫君火以名，相火以位，相火代君火行事也。相火一扰，能为百病，况少阴乎！用补中益气汤、朱砂安神丸，空心则进坎离丸，月余而愈。", "白话": "治一人因心高志大、所谋不遂，怔忡善忘、口淡舌燥、多汗、四肢疲软、发热、小便白浊。众医以内伤不足论治，打算用人参、鹿茸、附子。某公诊其脉虚大而数，说：这是思虑过度、少阴君火为患。君火以名（主神明），相火以位（代行事），相火代君火行事；相火一扰能生百病，何况少阴！用补中益气汤、朱砂安神丸，空腹另进坎离丸，一月余而愈。"}, {"source": "条14｜《万病回春》卷六", "原文": "一妇人，惊悸怔忡、无寐、自汗盗汗、怠惰嗜卧、饮食不甘。用归脾汤而愈。至年余，怀抱郁结，患前症，兼衄血、便血，仍用前汤而愈。", "白话": "一位妇女，惊悸怔忡、不寐、自汗盗汗、怠惰嗜卧、饮食不甘。用归脾汤而愈。过了一年多，怀抱郁结，旧症复发，并兼衄血、便血，仍用归脾汤而愈。"}, {"source": "条15｜《女科证治准绳》卷二", "原文": "一妇人劳则心跳怔忡，寒热往来，用归脾汤为主，佐以八珍汤，诸证渐愈，又用加味逍遥散、宁志丸而安。后复作，服归脾、定志二药即愈。", "白话": "一位妇女劳累就心跳怔忡、寒热往来，用归脾汤为主，配合八珍汤，诸证渐愈；又用加味逍遥散、宁志丸而安。后复发，服归脾汤、定志二药即愈。"}, {"source": "条16｜《女科证治准绳》卷三", "原文": "一妇人尿血，因怒气寒热，或头痛，或胁胀，此肝血虚而肝火盛，用加味逍遥散而血胀止，补中益气加蔓荆子而头痛痊。后郁怒腹痛尿血，仍用前散，加龙胆草并归脾汤治之。将愈，又因饮食所伤，复作心忡不宁，彻夜不寐，仍用前汤而痊。", "白话": "一位妇女尿血，因发怒而寒热，或头痛，或胁胀。此为肝血虚而肝火盛，用加味逍遥散而血胀止，补中益气汤加蔓荆子而头痛痊愈。后又因郁怒腹痛尿血，仍用前散加龙胆草，并配归脾汤治之。将愈时又因饮食所伤，复发心忡不宁、彻夜不寐，仍用归脾汤而痊。"}, {"source": "条17｜《肯堂医论》卷下", "原文": "韩飞霞《医通》有云：黄连、肉桂，能交心肾于顷刻，谓治不寐之灵丹，历验不爽。今特拈出，以启后学之悟。\n按：前贤方法固良，要在对病，捷如影响。如上法，余治一妇，惊悸不寐，已延半载，医治不效，乞余诊治。尺脉微数，两寸浮洪，显是阳不交阴，卫气仅行于阳而不入于阴，故心肾不交也。即仿前法，用川连二钱，另煎待冷；桂心二钱，另煎待冷；用半夏、秫米各三钱，取甘澜水煎成，加连汁、肉桂汁和匀，乘温徐徐频饮，服后觉倦，至", "白话": "韩飞霞《医通》说：黄连、肉桂能交心肾于顷刻，是治不寐的灵丹，屡用屡验。今特拈出，以启发后学。按语：前贤的方法固然好，关键在对证，则效如桴鼓。如上法，我治一位妇女，惊悸不寐已延半年，医治无效，请我诊治。尺脉微数，两寸浮洪，显然是阳不交阴——卫气只行于阳而不入于阴，故心肾不交。即仿前法：川连二钱另煎待冷，桂心二钱另煎待冷，半夏、秫米各三钱，取甘澜水煎成，加入黄连汁、肉桂汁和匀，乘温缓缓频饮。服后觉倦，至夜安睡甚酣，前患已愈。稍有惊悸，改用补心丹加减而愈。足见方药对证，如鼓应桴，非"}, {"source": "条18｜《先醒斋医学广笔记》卷二", "原文": "王六息乃正，产后惊悸，闻声辄死，非用力抱持，则虚烦欲死，如是累月。仲淳曰：此心脾肝三经俱虚也。用人参、酸枣仁、茯神、远志、芍药、石斛、甘草、麦门冬、五味、丹砂为丸，以龙眼汤吞。弥月而愈。", "白话": "王六息的妻子产后惊悸，一听见声音就吓得要死；非用力抱住，则虚烦欲死，这样持续了几个月。缪希廉（仲淳）说：这是心、脾、肝三经俱虚。用人参、酸枣仁、茯神、远志、芍药、石斛、甘草、麦门冬、五味子、丹砂为丸，以龙眼汤送服。满一月而愈。"}, {"source": "条19｜《医学穷源集》卷四", "原文": "姚氏，廿四，小产后，心虚怔忡，发热头运，食减神疲，夜不能寐，医以养心汤及归脾汤治之，反见舌燥唇焦、痰嗽气急之象。脉细数。\n案：此系脾经不能摄血，而卫气无所归也。其法当先以养阴为主。服五六剂后，乃用补阳之剂。女子阳藏于内，阴包乎外，阴不固则阳泄而神疲。服此方六剂后，虚象必减，仍用归脾汤可也。\n鲜生地钱半 鲜首乌二钱半 白芍钱半 云苓钱半 鲜石斛三钱 炒山栀钱二 木通钱半 知母钱半 砂仁钱半 陈香橼五", "白话": "姚氏，二十四岁，小产后心虚怔忡，发热头晕，食减神疲，夜不能寐。前医用养心汤及归脾汤治之，反见舌燥唇焦、痰嗽气急。脉细数。案语：这是脾经不能摄血、卫气无所归。治法当先以养阴为主，服五六剂后，再用补阳之剂。女子阳藏于内、阴包乎外，阴不固则阳泄而神疲。服此方六剂后虚象必减，仍用归脾汤可也。方：鲜生地一钱半、鲜首乌二钱半、白芍一钱半、云苓一钱半、鲜石斛三钱、炒山栀一钱二分、木通一钱半、知母一钱半、砂仁一钱半、陈香橼五分。"}, {"source": "条20｜《折肱漫录》卷一", "原文": "予里屠谕德公夫人，患怔忡，闻声即惊怵，服天王补心丹，立效。则知肝王人，此丹原自宜服也。", "白话": "我乡里屠谕德公的夫人患怔忡，听见声音就惊怕，服天王补心丹立刻见效。由此可知肝旺之人，此丹原本就适宜服用。"}, {"source": "条21｜《医验大成·眩晕章》", "原文": "一人患惊悸三月矣。闻响则惊，遇夜则恐，恐甚即上屋逾墙，旋食旋饥，口啖饭数碗。咸为心偏神失，用补心汤，病滋甚。一日求予诊视，其右关脉洪数无伦，两尺浮大，按之极濡。此病得之酒，其皆因由肾水枯竭，客热犯胃也。《内经》曰：肾主恐。又曰：胃热亦令人恐。又曰：胃热则消食易机。又曰：足阳明病闻木音则惕然若惊，病甚则逾桓上屋。汝病在胃与肾。脾合胃，心属火，是脾之母也。补心则胃益实，火盛则水益涸，无怪乎药之而病反甚", "白话": "一人患惊悸三个月了。听见响动就惊，入夜就恐，恐极就上屋翻墙；刚吃完就饿，一顿吃几碗饭。众医都认为心偏神失，用补心汤，病更重。一天请我诊视：其右关脉洪数无伦，两尺浮大、按之极濡。此病得之于酒，皆因肾水枯竭、客热犯胃。《内经》说：肾主恐；又说胃热也令人恐；又说胃热则消谷善饥；又说足阳明胃病闻木音则惕然若惊，病甚则逾垣上屋。你的病在胃与肾：脾合胃，心属火是脾之母，补心则胃更实，火盛则水更涸，无怪乎服药病反甚。但病本在肾、标在胃，当先治其标用泻黄汤，后治其本用肾气丸。一病而寒热并用、"}, {"source": "条22｜《医验大成·虚损章》", "原文": "一人病怔忡善忘，口淡舌燥，多汗，四肢疲软，发热，小便白浊，脉息虚大而数。此由思虑过度，厥阴之火为患，且养心以宁神，和肝以清热。方：茯神、枣仁、远志、熟地、麦冬、黄柏、杜仲、骨皮、甘草。", "白话": "一人病怔忡善忘，口淡舌燥，多汗，四肢疲软，发热，小便白而浑浊，脉虚大而数。此由思虑过度、厥阴之火为患，宜养心以宁神、和肝以清热。方：茯神、酸枣仁、远志、熟地、麦冬、黄柏、杜仲、地骨皮、甘草。"}, {"source": "条23｜《裴子言医》卷二", "原文": "惊悸、恍惚、恐怖及怔忡、不得卧诸证，同出而异名者也。不可疑其证之异而治亦与之俱异也。一商，年近五旬，诸证咸集，而于怔忡则尤甚，远近名家，大半以为心血不足，余则有谓胆气弱者，有谓心肾不交者，又有谓痰客胞络，以致神舍不清者。其所用之药，则皆不外当归、地黄、人参、五味、黄连、麦冬、菖蒲，远志、天麻、胆星、茯神、酸枣，以及琥珀、牛黄、丹砂、龙齿之属，逡巡数年，日以增剧，甚至烦躁靡宁，不餐不寝者逾月。余诊之", "白话": "惊悸、恍惚、恐怖及怔忡、不得卧诸证，是同出而异名，不可因其证名不同而治法也随之不同。一位商人年近五旬，诸证俱全，怔忡尤其重。远近名家大半认为心血不足，其余有说胆气弱者、心肾不交者、痰客胞络以致神舍不清者；所用之药不外当归、地黄、人参、五味、黄连、麦冬、菖蒲、远志、天麻、胆星、茯神、酸枣仁，以及琥珀、牛黄、丹砂、龙齿之类。迁延数年，日以增剧，甚至烦躁不宁、不餐不寝逾月。我诊之：脉来数且洪，右关尤滑，这是胃中有火有痰的明证。先投小胃丹五十丸，胸中便有旋转之势，神情稍安；随即用铁锈"}, {"source": "条24｜《辨证录》卷九", "原文": "人有怔忡善忘，口淡舌燥，多汗，四肢疲软，发热，小便白而浊，脉虚大而数，人以为内伤之病也，谁知是由思虑过度而成之者乎。？夫君火者，心火也；相火者，膻中之火也。膻中手厥阴之经，性属阴而主热，古人以厥阳名之，以其火起之不可遏也。越人云：忧愁思虑则伤心。心气一伤，心血自耗，心血既耗，心气遂不能自主，每欲寄其权于相火，而相火欺君火之弱，即夺心之权而恣肆矣。治法宜以水济火。然见火势之炽张，用寒凉以济之，则心气", "白话": "有人怔忡善忘、口淡舌燥、多汗、四肢疲软、发热、小便白而浑浊，脉虚大而数，人们以为是内伤之病，谁知是由思虑过度而成。君火是心火，相火是膻中之火；膻中为手厥阴经，性属阴而主热，古人以「厥阳」名之，因其火起不可遏。越人说：忧愁思虑则伤心。心气一伤，心血自耗；心血既耗，心气遂不能自主，常想把权委托给相火，而相火欺君火之弱，即夺心之权而恣肆。治法宜以水济火；但见火势炽张而用寒凉去济，则心气益虚，更激起焦焚之害。宜急补心气之虚、大滋肾水之涸，则心火宁静，相火不安而自安。方用坎离两补汤：人"}, {"source": "条25｜《灵验良方汇编》卷上", "原文": "一妇人气盛血少、火旺痰多，因事不遂意，得怔忡之患，心惕然而惊，时发时止。每服镇心金石之药，愈不安，左手脉弦而大，右手浮滑不匀，此是血少火旺，气盛痰多故也。须用温胆汤加苏子、海粉，数服而安。后用安神丸痊全愈。", "白话": "一位妇人气盛血少、火旺痰多，因事不遂意而得怔忡，心中惕然而惊，时发时止。每服镇心金石重镇之药，越发不安。左手脉弦而大，右手浮滑不匀，这是血少火旺、气盛痰多的缘故。须用温胆汤加苏子、海粉，数服而安。后用安神丸完全治愈。"}, {"source": "条26｜《静香楼医案》卷上", "原文": "惊悸易泄，腰疼足软，有似虚象，而实因痰火。盖脉不弱数，形不枯瘁，未可遽与补也。半夏、炙草、秫米、橘红、茯苓、竹茹 、远志、石菖蒲。", "白话": "惊悸并易遗泄，腰疼足软，看似虚象，其实是痰火为患。因为脉不弱数、形不枯瘁，未可骤然进补。药用：半夏、炙甘草、秫米、橘红、茯苓、竹茹、远志、石菖蒲。"}, {"source": "条27｜《不居集》卷二十二", "原文": "罗谦甫治一人，患神气不宁，卧则梦飞扬，身虽在床而神魂离体，惊悸多魇，通宵不寐，诸医不效。罗诊视之，问曰：医作何病治之？曰：众皆以为心病。罗曰：以脉言之，肝经受邪，非心病也。以珍珠母为君，龙齿佐之，使以他药，治之而愈。", "白话": "罗谦甫治一人，患神气不宁，躺下就梦魂飞扬，身虽在床上而神魂离体，惊悸多噩梦，通宵不寐，诸医无效。罗诊视后问：众医当作什么病治？答：都以为是心病。罗说：以脉而言，是肝经受邪，不是心病。用珍珠母为君，龙齿为佐，以他药为使，治之而愈。"}, {"source": "条28｜《类证普济本事方释义》卷八", "原文": "乡里有姓京者，以鬻绳为业。子年三十，初得病，身微汗，脉弱恶风。医以麻黄汤与之，汗遂不止，发热，心多惊悸，夜不得眠，谵语，不识人，筋惕肉瞤，振振动摇。医者进惊风药。予曰：此强汗之过也。仲景云：脉微弱，汗出恶风者，不可服青龙汤。服之则筋惕肉瞤。此为逆也，惟唯真武汤可救。连进三服，继以清心圆，竹叶汤送下。数日遂愈。", "白话": "乡里有姓京的，以卖绳为业。儿子年三十，初得病时身微汗、脉弱、恶风。医生给了麻黄汤，汗出不止，发热，心多惊悸，夜不能眠，谵语不识人，筋惕肉瞤、振振动摇。医生又进惊风药。我说：这是强发汗的过错。仲景说：脉微弱、汗出恶风者，不可服青龙汤（大青龙），服之则筋惕肉瞤，这是误治。只有真武汤可救。连进三服，接着以清心圆用竹叶汤送下，数日遂愈。"}, {"source": "条29｜《景岳全书发挥》卷二", "原文": "双林韩佐相患怔忡病三载不愈，时医俱用景岳之言，而用参芪地黄群补之药，日甚一日，就医于余。余用豁痰降火之药一剂，是夜即大减，后以温胆汤加山栀、黄连、石膏、胆星、枣仁，丸服，不一月而痊全愈。照此书而执用补剂，必致误人。", "白话": "双林韩佐相患怔忡病三年不愈，时医都依景岳之说而用人参、黄芪、地黄等群补之药，病一天比一天重，来我处就医。我用豁痰降火之药一剂，当夜病就大减；后以温胆汤加山栀、黄连、石膏、胆星、酸枣仁，作丸服，不满一月而痊愈。照这本书（《景岳全书》）而执用补剂，必致误人。"}, {"source": "条30｜《临证指南医案》卷九", "原文": "余，产后不复，心悸欲呕，遇寒腹痛。先议进和营卫，继当补摄。归桂枝汤加茯苓。", "白话": "姓余的患者，产后未复，心悸欲呕，遇寒腹痛。先议进调和营卫之法，接着再进补养固摄之剂。用归桂枝汤（桂枝汤加当归类）加茯苓。"}, {"source": "条31｜《徐批叶天士晚年方案真本》卷下", "原文": "周，情志易生嗔怒，肝胆木火上攻，胃脘心悸忽嘈，手抚动跃。夫动皆阳化，沉香、肉桂辛热，肝有摧捍恶燥之累，非入理也。柏子仁、归须、桃仁、大麻仁、南查楂肉。", "白话": "周某，情志容易嗔怒，肝胆木火上攻，胃脘部心悸忽然嘈杂，用手抚之觉动跃。凡动皆属阳化，沉香、肉桂辛热，于肝有刚燥劫阴之累，并非合乎理法之治。方用：柏子仁、当归须、桃仁、大麻仁、南楂肉。"}, {"source": "条32｜《徐批叶天士晚年方案真本》卷下", "原文": "陈，心虚忡悸，君相多升。生地、天冬、茯神、柏子仁、枣仁、炙甘草。", "白话": "陈某，心虚忡悸，君火相火多上升。方用：生地、天冬、茯神、柏子仁、酸枣仁、炙甘草。"}, {"source": "条33｜《洄溪医案·怔忡》", "原文": "淮安巨商程某，母患怔忡，日服参、术峻补，病益甚，闻声即晕，持厚聘邀余。余以老母有恙，坚持不往，不得已，来就医，诊视见二女仆从背后抱持，二女仆遍体敲摩，呼太太无恐，吾侪俱在也，犹惊惕不已。余以消痰之药去其涎，以安神之药养其血，以重坠补精之药纳其气，稍得寝。半月余，惊恐全失，开船放炮，亦不为动，船挤喧嚷，欢然不厌。盖心为火脏，肾为水脏，肾气挟夹痰以冲心，水能克火，则心振荡不能自主，使各安其位，则不但不", "白话": "淮安巨商程某，母亲患怔忡，每天服人参、白术峻补，病越发重，听见声音就晕倒。程某出重金请我。我因老母有恙坚持不去，不得已程某携母来就医。诊时见两个女仆从背后抱持，两个女仆遍体敲摩，喊「太太莫怕，我们都在」，仍惊惕不已。我用消痰之药去其涎，用安神之药养其血，用重坠补精之药纳其气，稍得入睡。半月余惊恐全失，开船放炮也不为所动，船中拥挤喧嚷，她欢然不厌。因为心为火脏、肾为水脏，肾气夹痰上冲于心，水能克火，则心振荡不能自主；使各安其位，则不但不相克，而且相济，这是自然之理。"}, {"source": "条34｜《洄溪医案按·失魂》", "原文": "长兴赵某，以经营过劳其心，患怔忡证，医者议论不一，远来就余。余以消痰补心之品治其上，滋肾纳气之药治其下，数日而安。此与程母病同，而法稍异。一则气体多痰，误服补剂，水溢而火受克之证；一则心血虚耗，相火不宁，侵犯天君之证，不得混淆之也。", "白话": "长兴赵某，因经营过度劳心，患怔忡证。医者议论不一，远道来我处。我用消痰补心之品治其上，滋肾纳气之药治其下，数日而安。此与程母病相同而治法稍异：一是气体多痰、误服补剂，水溢而火受克之证；一是心血虚耗、相火不宁、侵犯天君（心）之证，不可混淆。"}, {"source": "条35｜《续名医类案》卷二", "原文": "冯楚瞻治张铨部，先年以焦劳，遂得怔忡耳鸣诸症。医以痰治，涌出痰涎斗许，复用滚痰丸，痰势虽清，精神内夺，初秋卒倒僵仆，痰涌鼻鼾，目窜口开，手足强直，自汗如雨，危甚。脉之，六部皆豁大无伦，其候欲脱，刻不容缓矣。乃用人参三两，白术二两，附子五钱，浓煎灌之。日三剂，按时而进。\n服后，脉势渐敛，身热渐和，溃汗渐收。次日，仍用前方，日二服，夜一服。\n至三日，诸症渐减，僵仆不省如故，此工夫未到，故标症稍平，而元", "白话": "冯楚瞻治张铨部，先前因焦劳而得怔忡耳鸣诸症。医生按痰治，涌出痰涎斗许，又用滚痰丸，痰势虽清而精神内夺，初秋突然僵仆倒地，痰涌鼻鼾，目窜口开，手足强直，自汗如雨，危甚。脉之六部皆豁大无伦，其证欲脱，刻不容缓。乃用人参三两、白术二两、附子五钱，浓煎灌之，每日三剂，按时而进。服后脉势渐敛，身热渐和，汗渐收。次日仍用前方，日二服、夜一服。至三日诸症渐减，僵仆不省如故——此是功力未到，标症稍平而元神未复。仍照前服，服后必灌浓米汁半盅以保胃气、助药力。有人劝加风药，答：保之尚且不暇，敢散"}, {"source": "条36｜《续名医类案》卷四", "原文": "万密斋治县丞李天泉，六月中暑腹痛。渠有婢妾，医谓病寒，进理中汤，一剂痛止。乃发热，一身骨节尽痛，又进十神汤发汗，热退身不痛矣。万候之，李称病愈，观其面色带赤，知病未解。请脉之，洪滑而数色脉相对。经曰：大则病进。今汗后脉犹洪数，病方进也，而彼自称愈。万未去，食顷而病作矣。满腹急痛，状如奔豚，上下左右，举手按摩。亟延万至，曰：汝先诊脉，不言而去，知我病也，幸急救我。万曰：无伤。乃进建中汤，一服而痛定。", "白话": "万密斋治县丞李天泉，六月中暑腹痛。他有婢妾，医生说是寒病，进理中汤，一剂痛止，却发热、一身骨节尽痛；又进十神汤发汗，热退身不痛了。万密斋诊之，李自称病愈；观其面色带赤，知道病未解。请脉之：洪滑而数，色脉相对。《经》说「大则病进」，今汗后脉仍洪数，病正在进展，而他自称愈。万未离去，一顿饭工夫病就发作了：满腹急痛，状如奔豚，上下左右攻冲，举手按摩。急忙请万至，说：你先前诊脉不言而去，定是知道我的病，请急救我。万说无妨。乃进建中汤，一服而痛定。次日有省祭官万朴来探病，万朴也懂医，诊"}, {"source": "条37｜《续名医类案》卷八", "原文": "易思兰治省亭殿下，七月病痢。始服通利，次行和解，又次滋补。月余转甚，每日行数次，肚腹绞痛，但泄气而便不多，起则腰痛屈曲难伸，胸膈胀满，若有物碍，嗳气连声，四肢厥逆，喘息不定。诊之，两寸沉大，右寸更有力，右关沉紧，左关弦长而洪。喜两尺沉微，来去一样，曰：此神劳气滞之病也。以畅中汤进之，制香附八分，苍术一钱，神曲三钱五分，抚芎七分，黄芩八分，枳壳三分，苏梗五分，甘草三分，姜一片，枣二个。服后兀兀欲吐，", "白话": "易思兰治省亭殿下，七月患痢。先服通利药，次行和解，又次滋补，一个多月转重：每日泻数次，肚腹绞痛，但泄气而便不多，起立则腰痛屈伸难，胸膈胀满如有物阻，嗳气连声，四肢厥逆，喘息不定。诊之：两寸沉大，右寸更有力，右关沉紧，左关弦长而洪，所幸两尺沉微、来去一致。说：这是神劳气滞之病。进畅中汤：制香附八分、苍术一钱、神曲三钱五分、抚芎七分、黄芩八分、枳壳三分、苏梗五分、甘草三分，姜一片、枣二个。服后昏昏欲吐，冷气上升，嗳气数十口，随即大便泻下秽污甚多，胸次舒畅，腹中觉饥，自午至酉只泻一"}, {"source": "条38｜《续名医类案》卷二十一", "原文": "老僧悟庵心悸善恐，遍服补心养血之药不应，天王补心丹服过数斤，惊悸转增，面目四肢微有浮肿之状，求张治。察其形肥白不坚，诊其脉濡弱而滑，此气虚痰饮浸渍于膈上也。以导痰汤稍加参桂通其阳气，数服而悸恐悉除。更以六君子加桂，水泛作丸，调补中气而安。雄按：此证最多，世皆误治。", "白话": "老僧悟庵心悸善恐，遍服补心养血之药无效，天王补心丹服过数斤，惊悸反而加重，面目四肢微有浮肿，求张路玉治疗。察其形体肥白不结实，诊其脉濡弱而滑，这是气虚痰饮浸渍于膈上。用导痰汤稍加人参、桂枝以通其阳气，数服而悸恐悉除；再用六君子汤加桂，水泛为丸，调补中气而安。王孟英按：此证最多，世医皆误治。"}, {"source": "条39｜《续名医类案》卷二十一", "原文": "吴孚先治王兵宪，患惊悸，时或烦躁，夜更靡宁，右关虚弱，左寸尤甚，与加味归脾二十剂而全愈痊愈。", "白话": "吴孚先治王兵宪，患惊悸，时或烦躁，夜间尤其不宁，右关脉虚弱、左寸尤甚，给加味归脾汤二十剂而痊愈。"}, {"source": "条40｜《续名医类案》卷二十一", "原文": "龚子才治一童子，因用心过度，少寐惊悸，怔忡恶寒，先用补中益气汤加茯苓、枣仁、远志，恶寒渐止。又用加味归脾汤，惊悸稍安，再用养心汤而安。", "白话": "龚子才治一童子，因用心过度，睡少惊悸，怔忡恶寒。先用补中益气汤加茯苓、酸枣仁、远志，恶寒渐止；又用加味归脾汤，惊悸稍安；再用养心汤而安。"}, {"source": "条41｜《续名医类案》卷二十一", "原文": "马元仪治一人，患心悸症，肢体倦怠，或以阴虚治之不效。诊其脉浮虚无力，盖得之焦劳思虑伤心也。《内经》云：心痹者，脉不通，烦则心下鼓。又《原病式》云：水衰火旺，心胸躁动。其言脉不通者，正以焦劳太过，心脏之脉郁而不通也。郁则伤血而动君火，故悸动不宁也。心之下脾位，脾受心病，郁而生涎，精液不生，清阳不布，故四肢无气以动而倦怠也。法宜大补心脾，乃与归脾汤二十剂，即以此方作丸，服之痊愈。", "白话": "马元仪治一人患心悸，肢体倦怠，或按阴虚治之无效。诊其脉浮虚无力，盖得之于焦劳思虑伤心。《内经》说：「心痹者，脉不通，烦则心下鼓。」《原病式》说：「水衰火旺，心胸躁动。」所谓脉不通，正因焦劳太过，心脏之脉郁而不通；郁则伤血而动君火，所以悸动不宁。心的下面是脾位，脾受心病影响，郁而生涎，精液不生、清阳不布，所以四肢无气以动而倦怠。治法宜大补心脾，乃给归脾汤二十剂，又以此方作丸服之，痊愈。"}, {"source": "条42｜《续名医类案》卷二十一", "原文": "章氏妇因失恃于归，劳心悒郁，形志倍伤，遂心悸恍惚，身体如在舟车云雾中，或与降气理痰之剂不应。诊之，两脉虚微，尺脉倍弱，曰：忧劳过度则脾损，脾虚必盗母气以自救，故心虚而悸。心藏神，为十二官之主，虚则无所听命而恍惚不安也。宜大培土气，则脾自复，不仰给于心，而心亦安，神亦守矣。与人参附子理中汤，一剂而安，四剂神气大复，脉和而愈。", "白话": "章氏妇因母亲去世后出嫁（失恃于归），劳心忧郁，形体情志俱伤，遂心悸恍惚，身体像在舟车云雾之中。有人给降气理痰之剂无效。诊之两脉虚微，尺脉倍弱。说：忧劳过度则脾损，脾虚必盗母气（心气）以自救，所以心虚而悸；心藏神、为十二官之主，虚则无所听命而恍惚不安。宜大培土气，则脾自复，不再仰给于心，而心亦安、神亦守。给人参附子理中汤，一剂而安，四剂神气大复，脉和而愈。"}, {"source": "条43｜《续名医类案》卷二十一", "原文": "李季蚪庶母，因儿痘惊苦积劳，虚烦不得卧，心胆虚怯，触事惊悸，百药不效。家弟长文偶于友人处，闻兴化陈丹崖疗一女人甚奇，其症与母类。叩其方，乃温胆汤也，试之数剂而效。\n半夏七钱 竹茹、枳实各三钱 陈皮四钱半 茯苓、甘草各二钱二分半\n分二剂，姜枣煎服，外加枣仁五钱，后因虚极加人参二钱。\n质之仲淳，曰：此必有痰而善饮者也。果然。", "白话": "李季蚪的庶母，因儿子出痘惊苦积劳，虚烦不得卧，心胆虚怯，遇事惊悸，百药无效。我弟长文偶然在友人处听说兴化陈丹崖治一女人甚奇，其症与母亲类似，叩问其方，乃是温胆汤。试服数剂即效：半夏七钱，竹茹、枳实各三钱，陈皮四钱半，茯苓、甘草各二钱二分半，分二剂，姜枣煎服，外加酸枣仁五钱；后因虚极加人参二钱。拿去请教仲淳（缪希廉），说：这人必定素有痰而善饮。一问果然。"}, {"source": "条44｜《续名医类案》卷二十五", "原文": "薛立斋治一产妇，患颠狂，或用大泽兰汤而愈。后又怔忡妄言，其痰甚多，用茯神散，补其心虚，顿愈。又用八珍散加远志、茯神养其气，遂瘥。", "白话": "薛立斋治一产妇，患癫狂，用大泽兰汤而愈；后又怔忡妄言，其痰甚多，用茯神散补其心虚，顿时而愈；又用八珍散加远志、茯神养其气，遂瘥。"}, {"source": "条45｜《续名医类案》卷二十五", "原文": "高鼓峰治用晦室人，患产后惊悸。初起时，见筐中棉絮，念将所生儿入棉絮中，不几闷死，遂作惊恐忧患之状。后凡有所触，意中以为不耐，即忧患不止。或一端执想，数日才已，饮食不进，面少精采，服诸补心养血药无一效。高脉之曰：孩时得毋因齿病致大惊否？用晦向室人问之。曰：十岁时，果曾病齿，治齿者用刀钳之，几受惊而死，子何能识之也？解曰：脉法当如是耳，不精于象数钤法之学者，不能也。此语不必。少时以惊受损，伤其君火，心", "白话": "高鼓峰治用晦的妻子，患产后惊悸。初起时见筐中棉絮，想到将所生婴儿放入棉絮中岂不闷死，遂作惊恐忧患之状；此后凡有所触，心里觉得受不住，就忧患不止，或一个念头执著数日才罢，饮食不进，面少精采，服各种补心养血药无一效。高诊脉后说：她小时候莫非因牙病受过大惊？用晦问妻子，答：十岁时果然曾病牙，治牙者用刀钳之，几乎受惊而死。你怎么知道？解曰：脉法当如此，不精通象数钤法之学者不能知（此语不必信）。少时因惊受损，伤其君火，心包气散，痰得留之；如今产后火虚，痰因虚动，病根发作了。心为君主，主"}, {"source": "条46｜《续名医类案》卷二十五", "原文": "施笠泽治庠友唐仲宣乃正，产后惊悸恍惚，语言错乱。此产后心虚，败血停积，上干包络，致病若此。先用佛手散加石菖蒲、五灵脂、刘寄奴、姜黄等药，以除败血，后以归脾调理而愈。至明年五月复产，复病前症，遍延诸医，施仍书前方。一医讶曰：寄奴、蒲黄等药，从何来邪？仲宣疑不复用。至是冬，施偶同李士材过大洪桥，忽遇仲宣，喜而迎曰：内人自乳子后，或歌曲嗔笑，狂妄不常，向服安神清心之剂不效，夜来几自缢矣，今偶值二子，岂天", "白话": "施笠泽治秀才唐仲宣的妻子，产后惊悸恍惚、语言错乱。此为产后心虚、败血停积，上犯包络，以致如此。先用佛手散加石菖蒲、五灵脂、刘寄奴、姜黄等药以除败血，后以归脾汤调理而愈。到第二年五月再生产，又患前症，遍请诸医，施仍开前方。一位医生惊讶道：刘寄奴、蒲黄等药从何（依据）而来？仲宣起疑不再用。到这年冬天，施笠泽偶然与李士材过大洪桥，忽遇仲宣，仲宣喜而迎道：内人自哺乳后，或歌唱、嗔笑，狂妄不常，向来服安神清心之剂无效，昨夜几乎自缢，今天偶然遇到二位，岂不是天赐？请为诊治。遂同往诊之，六"}, {"source": "条47｜《缪松心医案·中风》", "原文": "郭，悸动健忘，汗易泄，手振少寐，症由烦劳过度，心血渐衰，类中可虑。宜防患于未萌。党参、黄芪、当归、麦冬、紫石英、枣仁、茯神、柏仁、五味、淮麦、南枣，另服天王补心丹。", "白话": "郭某，悸动健忘，汗易外泄，手振颤、睡眠少。证由烦劳过度、心血渐衰，有类中风之虞，宜防患于未然。方用：党参、黄芪、当归、麦冬、紫石英、酸枣仁、茯神、柏子仁、五味子、淮小麦、南枣，另服天王补心丹。"}, {"source": "条48｜《松心医案笔记》卷上", "原文": "余数年来忽得怔忡病，耳中时闻风雨声，夜间更甚，后竟一无所闻，此劳心太过所致也。病在上者，当取之下，遂制此方服，未及半料而耳已聪，心亦宁矣，名之曰：磁朱七味都气丸。\n熟地酒拌蒸晒，八两 砂仁八钱 怀山药炒，四两 山萸肉炒，四两 丹皮三两 泽泻盐炒，三两 茯苓三两 北五味盐水炒，三两 桂心八钱 鱼胶蛤粉炒成珠，四两 灵磁石煅醋淬九次，一两 朱砂水飞为衣，一两\n炼蜜丸。", "白话": "我数年来忽得怔忡病，耳中常闻风雨声，夜间更重，后来竟一无所闻（耳聋），这是劳心太过所致。病在上者当取之下，遂制此方服，未及半料而耳已聪、心亦宁了，取名磁朱七味都气丸：熟地（酒拌蒸晒）八两，砂仁八钱，怀山药（炒）四两，山萸肉（炒）四两，丹皮三两，泽泻（盐炒）三两，茯苓三两，北五味（盐水炒）三两，桂心八钱，鱼胶（蛤粉炒成珠）四两，灵磁石（煅、醋淬九次）一两，朱砂（水飞为衣）一两，炼蜜为丸。"}, {"source": "条49｜《奇症汇》卷四", "原文": "学士卢抱经，为侍读时，每寤心必惊惕。医用安神补血之剂，数年不效。时值乾隆戊寅，予至燕京，与公同寓，初寓之日，公即问予曰：此症何故使然？予视其脉，独左关弦数。予曰：《内经》云卧而惊者属肝，卧则血归于肝。今血不静，血不归肝，故惊悸于卧也。《三因》用羌活胜湿汤加柴胡，治卧而多惊悸多魇溲者，为风寒在少阳厥阴也，非风药行经不可。今切肝脉弦数，此风热内侵肝脏，正经所谓血不静，血不归肝故也。当用加味逍遥散凉血舒", "白话": "学士卢抱经任侍读时，每次睡醒必心中惊惕。医生用安神补血之剂数年无效。时值乾隆戊寅年，我到燕京与他同住，初到之日他即问：此症何故如此？我诊其脉独左关弦数。我说：《内经》说「卧而惊者属肝」，卧则血归于肝，今血不静、血不归肝，故睡卧时惊悸。《三因方》用羌活胜湿汤加柴胡治卧而多惊悸、多噩梦、多尿者，认为是风寒在少阳、厥阴，非风药行经不可。今切肝脉弦数，此风热内侵肝脏，正是经所谓「血不静、血不归肝」。当用加味逍遥散凉血舒肝，更加防风以祛其风，使风散热解，血自归经。他听从了，服数剂而愈。"}, {"source": "条50｜《金匮启钥（妇科）》卷二", "原文": "一妇病心悸，其夫自配天王补心丹，煎犹未服，请予治。切其脉细而数，六七至无伦，知是欲脱之脉，土败水刑心悸，所煎之药，阻断不可服。予欲用真武汤，有畏附子之燥者，予曰：人生肾水居中，赖中州土制之庶不上刑。初用附子二钱，一剂悸静，次日舌中润黑，始见水刑心火，倍用附子数剂愈。", "白话": "一位妇女病心悸，她丈夫自己配了天王补心丹，药刚煎好还未服，请我治疗。切其脉细而数、六七至而无伦次，知道是欲脱之脉——土败水刑而心悸。所煎之药立予阻止、不可服。我想用真武汤，有人畏惧附子燥烈。我说：人身肾水居中，赖中州土制约之，才不上刑于心。初用附子二钱，一剂悸止；次日舌中润而黑，才显出水刑心火之象，倍用附子，数剂而愈。"}, {"source": "条51｜《金匮启钥（妇科）》卷二", "原文": "一妇心悸，恐惧如人将捕，以大补元煎，加附子、炮姜、远志、柏子仁，服至百剂，方愈。", "白话": "一位妇女心悸，恐惧如有人要抓她，用大补元煎加附子、炮姜、远志、柏子仁，服至一百剂才愈。"}, {"source": "条52｜《金匮启钥（妇科）》卷二", "原文": "一妇心悸，未服药，继发狂，目赤面红，切脉平静，知其假热症，以大剂归脾汤，重加附子二剂愈。", "白话": "一位妇女心悸，未服药即继发狂，目赤面红，但切脉平静，知道是假热证。用大剂归脾汤重加附子，二剂而愈。"}, {"source": "条53｜《程杏轩医案·续录》", "原文": "芃兄恙抱怔忡，久而不愈，每发心旌摇摇，头晕神倦，辗转不安。予诊之曰：此烦劳郁伤，心脾肝三经病也。方定黑归脾汤，去木香，加白芍、柴胡，合逍遥散，间参以麦冬、五味、柏子仁、丹参、牡蛎之属。疾发虽轻，然犹未断，芃兄忧之。予曰：神者伸也，人之神好伸而恶郁，郁则伤神。孔圣二论，首揭说乐，佛家《般若经》，首称自在。庄生著《南华》，首标逍遥游。情志中病，未可全凭药力，务须屏烦颐养，方能除根。如言闲散半载，服煎药", "白话": "芃兄患怔忡久而不愈，每发作则心旌摇摇、头晕神倦、辗转不安。我诊后说：此烦劳郁伤心、脾、肝三经之病。方定黑归脾汤去木香，加白芍、柴胡，合逍遥散，其间参以麦冬、五味子、柏子仁、丹参、牡蛎之类。病发虽减轻但仍未断根，芃兄忧虑。我说：神者伸也，人之神好伸展而恶抑郁，郁则伤神。孔圣《论语》首章即标「说（悦）乐」；佛家《般若经》首称「自在」；庄子著《南华经》首标「逍遥游」。情志之病不能全凭药力，务须摒除烦扰、颐养情志，才能除根。他如言闲散半年，服煎药两百剂，至今病不再发。"}, {"source": "条54｜《友渔斋医话·第四种》", "原文": "僧达禅，病发热，胸烦呕吐，背痛不恶风，脉来弦而有力。症俱温疟，用小柴胡去参，加竹茹、栝蒌皮，以除胸中烦热。一服不应，呕逆转甚，加石膏五钱。一服亦无进退，怔忡复发，心摇不已。即构思一方，以怔忡为君，事主昏乱。由于包络少外护之能，邪热乘虚，侵犯城郭，主亦为之动摇，岂可投补，但宜泻其丁火。\n川连八分 小生地三钱 木通一钱 甘草梢四分 连翘一钱五分 山栀一钱五分\n服下心病渐安。", "白话": "僧人达禅病发热、胸烦呕吐、背痛而不恶风，脉来弦而有力。诸证都像温疟，用小柴胡汤去人参，加竹茹、栝蒌皮以除胸中烦热。一服无效，呕逆更重，加石膏五钱；一服仍无进退，怔忡复发、心摇不已。我即构思一方：以怔忡为主证——心主神明昏乱，由于包络失却外护之能，邪热乘虚侵犯城郭（心包），君主也随之动摇。岂可投补？只宜泻其丁火（心火）：川连八分、小生地三钱、木通一钱、甘草梢四分、连翘一钱五分、山栀一钱五分。服下心病渐安。"}, {"source": "条55｜《王九峰医案》下卷", "原文": "心为一身之主宰，所藏者神。曲运神机，劳伤乎心，心神过用，暗吸肾阴，木失敷荣，肝胆自怯，神不安舍，舍空则痰居之，心悸多疑，情志不适，腹中澎湃如潮，嚏则稍爽，心病波及肝胆，天王补心丹、酸枣仁汤，皆是法程。拟阿胶鸡子黄汤加味。然否清政。\n阿胶 姜夏 桔红 枳实 鸡子黄 竹茹 茯苓 炙草", "白话": "心为一身之主宰，所藏为神。曲运神机（过度思虑）劳伤于心，心神过用，暗吸肾阴；肝木失于敷荣，肝胆自怯，神不安于舍；舍空则痰居之，故心悸多疑、情志不适、腹中澎湃如潮，打喷嚏则稍爽。心病波及肝胆，天王补心丹、酸枣仁汤都是成法。拟阿胶鸡子黄汤加味，妥否请指正。药：阿胶、姜半夏、橘红、枳实、鸡子黄、竹茹、茯苓、炙甘草。"}, {"source": "条56｜《王九峰医案》下卷", "原文": "服秘传酸枣仁汤，竟得酣寐，连霄达旦。前议专补精血，不寻痰火，已合病机。第病两月之久，阴已亏耗，以致惊悸、怔忡等，未能悉退，宜加补三阴之品。\n洋参 冬术 熟地 枸玄 萸肉 黄芪 归身 淮药 远志 枣仁 炙草 茯苓神", "白话": "服秘传酸枣仁汤后竟得酣睡，通宵达旦。前议专补精血、不寻痰火，已合病机。但病已两月之久，阴已亏耗，以致惊悸、怔忡等未能全退，宜加补三阴（肝脾肾）之品：西洋参、冬术、熟地、枸杞、玄参、山萸肉、黄芪、当归身、淮山药、远志、酸枣仁、炙甘草、茯苓、茯神。"}, {"source": "条57｜《叶天士曹仁伯何元长医案·何元长医案》", "原文": "头晕心悸，六脉不静。虚风内动也。\n大熟地 茯神 麦冬 柏子仁 蒺藜 归身 枣仁 甘菊 桑叶 石决明", "白话": "头晕心悸，六脉不静，是虚风内动。方：大熟地、茯神、麦冬、柏子仁、白蒺藜、当归身、酸枣仁、甘菊、桑叶、石决明。"}, {"source": "条58｜《叶天士曹仁伯何元长医案·何元长医案》", "原文": "心烦不寐，惊悸神呆。肝郁生风。\n川连 半夏 枣仁 龙齿 橘叶 麦冬 茯神 郁金 柏子仁 竹茹 丹参", "白话": "心烦不寐，惊悸神呆，是肝郁生风。方：川连、半夏、酸枣仁、龙齿、橘叶、麦冬、茯神、郁金、柏子仁、竹茹、丹参。"}, {"source": "条59｜《叶天士曹仁伯何元长医案·何元长医案》", "原文": "心悸遗精，脉虚无力。由阴不恋阳所致。惟唯清心固肾，俾得水火交合，病当渐减。\n熟地 枣仁 麦冬 远志 杞子 茯神 五味 芡实 金樱子 桂圆肉 湘莲", "白话": "心悸遗精，脉虚无力，由阴不恋阳所致。只宜清心固肾，使水火交合，病当渐减。方：熟地、酸枣仁、麦冬、远志、枸杞子、茯神、五味子、芡实、金樱子、桂圆肉、湘莲。"}, {"source": "条60｜《叶天士曹仁伯何元长医案·何元长医案》", "原文": "痰火内扰，心悸不安。治以清热疏郁，佐以涤痰。\n川连 陈皮 枣仁 石菖蒲 郁金 枳实 麦冬 石决明 半夏 茯苓", "白话": "痰火内扰，心悸不安。治以清热疏郁，佐以涤痰。方：川连、陈皮、酸枣仁、石菖蒲、郁金、枳实、麦冬、石决明、半夏、茯苓。"}, {"source": "条61｜《叶天士曹仁伯何元长医案·何元长医案》", "原文": "夜不能寐，时成惊悸。由深思郁结，阳不恋阴也。治以苦泄，佐用安神。\n炒川连 枣仁 半夏 煅龙齿 麦冬 茯神 陈皮 柏子仁 郁金 菖蒲", "白话": "夜不能寐，时发惊悸，由深思郁结、阳不恋阴所致。治以苦泄（清泄），佐用安神。方：炒川连、酸枣仁、半夏、煅龙齿、麦冬、茯神、陈皮、柏子仁、郁金、菖蒲。"}, {"source": "条62｜《叶天士曹仁伯何元长医案·何元长医案》", "原文": "经漏后，脉络空虚，以致心悸头晕，筋骨酸软，及足跗浮肿。非轻候也。必须进补。\n熟地 茯神 杜仲 白术 归身 狗脊 枣仁 白芍 香白薇", "白话": "经漏（经血淋漓）之后，脉络空虚，以致心悸头晕、筋骨酸软、足背浮肿。不是轻证，必须进补。方：熟地、茯神、杜仲、白术、当归身、狗脊、酸枣仁、白芍、香白薇。"}, {"source": "条63｜《叶天士曹仁伯何元长医案·何元长医案》", "原文": "血症频发，延至心悸不安，遍体作痛。乃气不摄血，营络空虚。劳怯之基，急宜进补。\n党参 枣仁 麦冬 阿胶 白芍 橘白 牛膝 杞子 茯神\n又方：去白芍、党参、橘白、杞子，加熟地、人参、女贞、炙草 。\n另煎并入。", "白话": "血证频发，延至心悸不安、遍体作痛。乃气不摄血、营络空虚，是劳怯（虚劳）之根基，急宜进补。方：党参、酸枣仁、麦冬、阿胶、白芍、橘白、牛膝、枸杞子、茯神。又方：去白芍、党参、橘白、枸杞子，加熟地、人参、女贞子、炙甘草，另煎并入。"}, {"source": "条64｜《吴门治验录》", "原文": "袁，左寸虚滑，右关沉弱。，此由惊恐思虑，三阴俱伤，痰火郁结，故神情恍惚，不能自主，不知饥饱，已渐成怔忡健忘重症，。急宜静养少言，再服心脾两调之剂，可愈。\n朱拌茯神朱拌，三钱 远志肉甘草水浸，一钱五分，甘草水浸 石菖蒲朱拌炒，三分，朱拌 炒丹参二钱 陈皮一钱 制半夏一钱五分 真琥珀五分 煅龙齿煅，二钱 生甘草五分 合欢皮五钱\n煎汤代水。\n又：昨用心脾两调之法，右关稍起，左寸微平，舌苔虽减，尚嫌白腻，", "白话": "袁某，左寸脉虚滑、右关沉弱。此由惊恐思虑、三阴（肝脾肾）俱伤、痰火郁结，故神情恍惚、不能自主、不知饥饱，已渐成怔忡健忘重症。急宜静养少言，再服心脾两调之剂，可愈。初方：朱拌茯神三钱、远志肉（甘草水浸）一钱五分、石菖蒲（朱拌炒）三分、炒丹参二钱、陈皮一钱、制半夏一钱五分、真琥珀五分、煅龙齿二钱、生甘草五分、合欢皮五钱，煎汤代水。又诊：昨日用用心脾两调之法，右关脉稍起、左寸微平，舌苔虽减尚嫌白腻，中宫痰火郁结未开，再照昨日之法加减：瓜蒌皮三钱、薤白（酒洗）一钱、茯神（朱拌）四钱、"}, {"source": "条65｜《类证治裁》卷一", "原文": "房师午园张公，高年上盛下虚，案牍劳神，冬春不寐，感温呛咳，晕仆，两寸脉洪大。由平昔阳不交阴，内风上冒，兼引温邪，表里煽动。症见眩仆，喉痛声哑，舌如煤熏。夫心为君主，义不受邪，因春温伤肺，逆传心包，神明俱为震动，且素饵桂附，致炎阳独亢，营液内劫，此怔忡无寐根由。师言昔病足痹，徽医用祛风药兼桂附得效，近三年矣。愚谓风药多燥，况桂附乎。？以脉症参时令，宜辛凉轻剂，于熄息风润燥中，佐以滋阴安神。不过一剂，", "白话": "业师午园张公，高年上盛下虚，案牍劳神，冬春不寐，感受温邪呛咳，晕仆，两寸脉洪大。由于平昔阳不交阴、内风上冒，兼引温邪，表里煽动。症见眩晕仆倒、喉痛声哑、舌如煤熏。夫心为君主、义不受邪，因春温伤肺、逆传心包，神明俱为震动；且平素常服桂、附，致炎阳独亢、营液内劫——这就是怔忡不寐的根由。老师说昔日病足痹，徽医用祛风药兼桂、附得效，已近三年。我说：风药多燥，何况桂、附？以脉证参合时令，宜辛凉轻剂，在熄风润燥之中佐以滋阴安神。不过一剂，当夜自能成寐；再剂呛咳除、悸眩止。初剂：鲜生地三"}, {"source": "条66｜《类证治裁》卷四", "原文": "贡氏，惊悸恍惚，不饥不食不寐，脉虚促。病因怒恐而得，胆火上冒则头眩心忡，胸脘刺痛，气结，呵欠怯冷，倏烦热多惊，皆阳越失镇，服药鲜效，总由治失其要。先镇浮阳，再议和阴。\n牡蛎、龙骨俱煅研，二钱 磁石一钱 柏子仁、连翘心各五分 茯神、生枣仁各二钱\n三服症象大减，改用：\n羚羊角六分 嫩桑叶三钱 熟地、枣仁、茯神、白芍各二钱 小麦一合 麦冬、半夏各钱半\n数服能寐思食矣。", "白话": "贡氏，惊悸恍惚，不饥不食不寐，脉虚而促。病因怒恐而得：胆火上冒则头眩心忡，胸脘刺痛、气结，呵欠怯冷，忽然烦热多惊——皆阳越失于镇潜，服药少效，总因未得治要。先镇浮阳，再议和阴。方：牡蛎、龙骨（俱煅研）各二钱，磁石一钱，柏子仁、连翘心各五分，茯神、生枣仁各二钱。三服症状大减，改用：羚羊角六分，嫩桑叶三钱，熟地、酸枣仁、茯神、白芍各二钱，小麦一合，麦冬、半夏各一钱半。数服能睡能食了。"}, {"source": "条67｜《类证治裁》卷四", "原文": "汪氏，病久失调，延成虚损，怔忡汗出，手足心热，坐起眩晕，善饥无寐。诊左寸虚散，右寸关虚弦，两尺稍大。此阴亏火炎之渐，惟唯营虚生内热，故手足如烙。寤烦神失安，故汗液自泄。虚阳挟夹风上蒙清窍，故头目眩晕。肝阳肆横，阳明当其冲，风火消铄，故善饥。滋液熄息风，全用柔剂，归脾汤去芪、术、木香、归、姜，加白芍、丹皮、熟地、甘菊炒，六服渐安。去丹皮、甘菊，再加山药、柏子仁，晚服六味丸痊全愈。", "白话": "汪氏，病久失调，延成虚损：怔忡汗出，手足心热，坐起眩晕，善饥不寐。诊之左寸虚散、右寸关虚弦、两尺稍大。这是阴亏火炎之渐：只有营虚生内热，故手足心热如烙；寤则烦、神失所安，故汗液自泄；虚阳夹风上蒙清窍，故头目眩晕；肝阳横逆，阳明（胃）当其冲，风火消烁，故善饥。治宜滋液熄风，全用柔剂：归脾汤去黄芪、白术、木香、当归、干姜，加白芍、丹皮、熟地、甘菊（炒），六服渐安；再去丹皮、甘菊，加山药、柏子仁，晚服六味丸而痊愈。"}, {"source": "条68｜《类证治裁》卷八", "原文": "吴氏，胎漏半产已匝月，崩带未止。用补气摄血之剂，犹淋沥不断，延至怔忡不安，腰腿酸痛，《脉诀》所谓‘崩中日久为白带，漏下多时骨髓枯’也。急须摄固奇经，仿徐之才涩以止脱意，用金锁匙丹。\n龙骨煅研 牡蛎醋煅研 茯神、远志炒 赤石脂研 杞子酒焙 加杜仲、枣仁俱炒 乌梅\n一服漏止，怔忡亦减。又加减前方而安。", "白话": "吴氏，胎漏半产已满月，崩中带下不止。用补气摄血之剂仍淋沥不断，延至怔忡不安、腰腿酸痛——《脉诀》所谓「崩中日久为白带，漏下多时骨髓枯」。急须收摄固涩奇经，仿徐之才「涩以止脱」之意，用金锁匙丹：龙骨（煅研）、牡蛎（醋煅研）、茯神、远志（炒）、赤石脂（研）、杞子（酒焙），加杜仲、酸枣仁（俱炒）、乌梅。一服漏止，怔忡亦减；又加减前方而安。"}, {"source": "条69｜《回春录·内科》", "原文": "太仑陆竹琴之令正陡患心悸，肢冷如冰。其子惶惶，浼吴江程勉耘恳援于孟英。察其脉浮弦而数，视其舌尖赤无苔，乃阴虚阳越，煎厥根萌。予元参、二至、三甲、龙齿、石英、生地、牛膝、茯神、莲子心而愈。", "白话": "太仓陆竹琴的夫人突然心悸、四肢冰冷如冰。其子惶惶，请吴江程勉耘恳请王孟英援助。察其脉浮弦而数，望其舌尖赤无苔，乃阴虚阳越、煎厥（厥证）初起之萌。给元参、二至丸（女贞子、旱莲草）、三甲（龟板、鳖甲、牡蛎）、龙齿、紫石英、生地、牛膝、茯神、莲子心而愈。"}, {"source": "条70｜《回春录·内科》", "原文": "王雪山令媳患心悸眩晕，广服补剂，初若甚效，继乃日剧，时时出汗，肢冷息微，气逆欲脱。灌以参汤，稍有把握。延逾半载，大费不资。庄芝阶舍人令延孟英诊视。脉沉弦且滑，舌绛而有黄腻之苔，口苦溲热，汛事仍行，病属痰热轇轕，误补则气机壅塞。与大剂清热涤痰药，吞当归龙荟丸，服之渐以向安。仲夏即受孕，次年二月诞一子。惜其娠后停药，去疾未尽，娩后复患悸晕不眠，气短不饥，或作产后血虚治不效，仍请孟英视之。脉极滑数，曰：", "白话": "王雪山的儿媳患心悸眩晕，广服补剂，初时似乎很有效，继而日渐加重，时时出汗、肢冷息微、气逆欲脱；灌以参汤才稍有把握。迁延半年多，花费不赀。庄芝阶舍人让请王孟英诊视：脉沉弦且滑，舌绛而有黄腻之苔，口苦、小便热，月经仍行。病属痰热胶结，误补则气机壅塞。给大剂清热涤痰药，吞当归龙荟丸，服后渐趋安定。仲夏即受孕，次年二月生一子。可惜她孕后停药，病根未尽，产后又患悸晕不眠、气短不饥，或按产后血虚治之无效，仍请孟英诊视：脉极滑数，说「病根未除」，给蠲痰清气法果然见效。"}, {"source": "条71｜《回春录·内科》", "原文": "康康侯司马令郎尔九，在玉环署中，患心忡自汗，气短面赤，霎时溲溺数十次，澄澈如水。医佥谓虚，补之日剧，乃来省就孟英诊焉。左寸关数，右弦滑，心下似阻，因作痰火阻气，心热移肺。治用蛤壳、黄连、枳实、楝实、旋覆、花粉、橘红、杏仁、百合、丝瓜络、冬瓜子、海蜇、荸荠、竹茹、竹沥、梨汁等出入为方，服之良愈。", "白话": "康康侯司马的公子尔九，在玉环官署中患心忡自汗、气短面赤，片刻之间小便数十次、澄澈如水。医生都说是虚，用补药一天比一天重，乃到省城请王孟英诊：左寸关数、右弦滑，心下如有阻塞。因辨为痰火阻气、心热移肺。治用蛤壳、黄连、枳实、楝实、旋覆花、花粉、橘红、杏仁、百合、丝瓜络、冬瓜子、海蜇、荸荠、竹茹、竹沥、梨汁等加减出入为方，服之痊愈。"}, {"source": "条72｜《回春录·内科》", "原文": "孟英治其令弟季杰之簉室，因夜间未寐，侵晨饮酒解寒，适见旁人争谇，即觉心跳欲吐，家人疑其醉也；而欲吐不出，气即奔逆如喘，且肢麻手握，语言难出，又疑为急痧而欲刺之。孟英闻而视之，脉象弦驶。曰：夜坐阳升，饮醇则肝阳益浮，见人争谇，是惊则气更上逆，不可刺也。灌以苏合香丸一颗，下咽即瘥。", "白话": "王孟英治其弟季杰的簉室（妾），因夜间未睡，清晨饮酒御寒，恰见旁人争吵，即觉心跳欲吐。家人疑她醉了；欲吐不出，气即上奔如喘，且肢麻手握、语言难出，又疑是急痧想用针刺。孟英听说来看：脉象弦而数急。说：夜间久坐阳气升动，饮醇酒则肝阳更浮，见人争受惊则气更上逆，不可针刺。灌苏合香丸一颗，下咽即愈。"}, {"source": "条73｜《王氏医案三编》卷一", "原文": "李健伯夫人因伤情志而患心跳，服药数月，大解渐溏，气逆不眠，面红易汗，卧榻不起，势已濒危。其次婿余朗斋浼孟英诊之，坚辞不治。其长婿瞿彝斋力恳设法，且云妇翁游楚，须春节旋里，纵使不治，亦须妙药稽延时日。孟英曰：是则可也。立案云：此本郁痰证，缘谋虑伤肝，营阴久耗，风阳独炽，烁液成痰。痰因火动，跳跃如舂。若心为君主之官，苟一跳动，即无生理，焉能淹缠至此乎？但郁痰之病，人多不识，广服温补，阴液将枯。脉至右寸", "白话": "李健伯夫人因情志受伤而患心跳，服药数月，大便渐溏、气逆不眠、面红易汗、卧床不起，势已濒危。其次婿余朗斋请王孟英诊治，孟英坚决辞谢不治；其长婿瞿彝斋恳切求法，且说岳父游宦楚地，须等春节回乡，纵使不治也须用好药拖延时日。孟英说：这样可以。立案道：此本是郁痰证，因谋虑伤肝、营阴久耗、风阳独炽，烁液成痰；痰因火动，跳跃如舂。若心为君主之官，一跳动即无生理，怎能缠绵到今天？但郁痰之病世人多不识，广服温补，阴液将枯；脉虽右寸关滑，而其余各部虚弦软数、指下无情。养液开痰不过暂作缓兵之计，一"}, {"source": "条74｜《验方新编》卷二十二", "原文": "记异症方案一条：靖江刘姓，年四旬，遇疫遭数丧自外归，母病旋卒，遂成惊悸不寐，略睡去即叫跳，其心如荡如撞，服天王补心丹之类半月不效。予用奇方制就琥珀丸，三服遂定每服三分三厘，共钱。又变怪症，饮食如故，忽然目翻涎流，喊如羊，其头侧过左肩，手亦向左反张，突起旋走，面如土色，食顷稍苏，日夜百番，或曰羊痫、曰痉病。然痫症当见怪脉，今无脉，非五痫可知；若作痉治，用麻黄发汗，续命祛风，恐立毙耳。予书原载角弓痧，", "白话": "记录异症方案一条：靖江刘某，年四十，遭瘟疫、连丽数丧，自外归家，母亲病故，遂成惊悸不寐，刚睡去就叫跳，其心如荡如撞，服天王补心丹之类半月无效。我用奇方制成琥珀丸，三服即定（每服三分三厘，共约一钱）。后又变出怪症：饮食如故，忽然目翻、流涎、喊声如羊，头侧向左肩、手也向左反张，突起旋走，面如土色，一顿饭工夫稍苏，一日夜发作百次。或说是羊痫、或说是痉病；但痫证当见怪脉，今无怪脉，可知不是五痫；若按痉证治、用麻黄发汗、小续命汤祛风，恐立刻致死。我书中原载有角弓痧，症状略相似，即投炼石"}, {"source": "条75｜《沈俞医案合钞·疟》", "原文": "疟后心中冲悸，脉象左大右小。此元气阴不足，阴为火扰，宜补中寓清。\n参须 元生地 茯神 小草 丹参 柏子仁 紫石英 枣仁 加辰砂三分，以红绢包悬药中煎", "白话": "疟疾之后心中冲悸，脉象左大右小。此元气阴分不足，阴为火扰，宜补中寓清。方：参须、元生地、茯神、小草（远志苗）、丹参、柏子仁、紫石英、酸枣仁，加辰砂三分，用红绢包悬于药中同煎。"}, {"source": "条76｜《沈俞医案合钞·忡悸》", "原文": "惊悸恐怕，心肾两虚也。自述火升背热，头重带摇，此痰火上冒清阳之位，恐延癫痫痼疾，不可遽补，且进清理为妥。\n生地 小川连 钩钩 青黛一钱 连翘 橘红 丹皮 胆星 甘草 辰砂", "白话": "惊悸恐惧，属心肾两虚。自述火升背热、头重带摇，这是痰火上冒清阳之位，恐延为癫痫痼疾，不可骤补，且进清利之剂为妥。方：生地、小川连、钩藤、青黛一钱、连翘、橘红、丹皮、胆星、甘草、辰砂。"}, {"source": "条77｜《沈俞医案合钞·忡悸》", "原文": "嘈杂心悸，见人则畏，夜梦纷纷，皆心神受病。脉沉弦，兼痰滞胆经也。\n茯神 法夏 龙骨 远志 柏子仁 枣仁 石菖蒲 丹金器一件同煎。", "白话": "嘈杂心悸，见人则畏，夜梦纷纷，皆属心神受病。脉沉弦，兼痰滞胆经。方：茯神、法半夏、龙骨、远志、柏子仁、酸枣仁、石菖蒲、丹参，金器一件同煎。"}, {"source": "条78｜《沈俞医案合钞·忡悸》", "原文": "神气模糊，夜不能寐，心忡，腰痛，舌苔黄垢，脉象左弦细右滑大。此心肾两虚，痰涎沃胆之候，宜先清后补。\n陈胆星 茯神 远志 半夏 丹参 杜仲 海浮石 橘红 加姜皮\n又：先服暂服方。\n茯神 法半夏 熟石膏 白福花 枳实 橘红 石菖蒲 甘草\n又：心忡稍缓，心膈仍热，脊腰时痛，夜寐未安，脉之滑大虽减，犹带数象。此水衰不能制火，肝胆厥阳上冒，宜去痰药，佐以潜降品。\n虎膝骨 牡蛎 元生地 茯神 川石斛 杜仲 淮", "白话": "神气模糊，夜不能寐，心忡，腰痛，舌苔黄垢，脉象左弦细、右滑大。此心肾两虚、痰涎沃胆之候，宜先清后补。初方：陈胆星、茯神、远志、半夏、丹参、杜仲、海浮石、橘红，加姜皮。又：先服暂服方：茯神、法半夏、熟石膏、白福花、枳实、橘红、石菖蒲、甘草。又：心忡稍缓，心膈仍热，脊腰时痛，夜寐未安，脉之滑大虽减仍带数象。此水衰不能制火、肝胆厥阳上冒，宜去痰药，佐以潜降之品：虎膝骨、牡蛎、元生地、茯神、川石斛、杜仲、淮牛膝、小叶沉香汁二分。又：《经》云肾开窍于二阴，从二便不爽、必努挣而出，及脊腰"}, {"source": "条79｜《邵氏方案·卷之射》", "原文": "气逆耳鸣，不寐神呆，此怔忡之渐也。现在舌苔黄厚，尚有湿热。\n枣仁 竹茹 半夏 磁石 石决明 川连 茯神 秫米 胆星 紫贝齿", "白话": "气逆耳鸣，不寐神呆，这是怔忡之渐。现在舌苔黄厚，尚有湿热。方：酸枣仁、竹茹、半夏、磁石、石决明、川连、茯神、秫米、胆星、紫贝齿。"}, {"source": "条80｜《邵氏方案·卷之射》", "原文": "不寐神烦，久延恐成怔忡。但现在舌苔白厚，脉象濡弦，尚有湿阻。先从标治。\n半夏 枣茯 茅术 石决明 秫米 青陈 米仁 沉香曲", "白话": "不寐神烦，日久恐成怔忡。但现在舌苔白厚、脉象濡弦，尚有湿阻，先从标治。方：半夏、酸枣仁、茯苓、茅术、石决明、秫米、青陈皮、米仁、沉香曲。"}, {"source": "条81｜《杂病广要·身体类》", "原文": "一妇惊悸，触事有所大惊，且眩晕不安。予曰：此名曰心惊胆寒，病在心胆经。诊脉大动如豆粒，厥厥动摇如无头尾也。此宜镇定，乃用黄连安神丸，用温胆汤加茯神、当归、菖蒲、远志、龙眼肉，水煎温服，旬月愈。", "白话": "一位妇女惊悸，因遇事大惊，且眩晕不安。我说：这病名叫心惊胆寒，病在心胆经。诊脉大动如豆粒、厥厥动摇、无头无尾（动脉）。此宜镇定，乃用黄连安神丸，再用温胆汤加茯神、当归、菖蒲、远志、龙眼肉，水煎温服，一月而愈。"}, {"source": "条82｜《古今医案按选》卷三", "原文": "高果斋治铁塞庵，怔忡不寐，心脉独虚，肝脉独旺。因述上年驿路还乡，寇盗充斥，风声鹤唳，日夜惊惧而致。遂用生地、麦冬、元参各五钱，人参三钱，龙眼肉十五枚。服数剂，又用夏枯草、羚羊角、远志、茯神、甘草、人参大效，仍以补心丹常服痊全愈。", "白话": "高果斋治铁塞庵，怔忡不寐，心脉独虚、肝脉独旺。他自述上年经驿路还乡，寇盗充斥，风声鹤唳，日夜惊惧而致此病。遂用生地、麦冬、元参各五钱，人参三钱，龙眼肉十五枚，服数剂；又用夏枯草、羚羊角、远志、茯神、甘草、人参，大效；仍以补心丹常服而痊愈。"}, {"source": "条83｜《王氏医案三编》卷二", "原文": "钱氏妇患嗽数月，多医莫治，渐至废寝忘餐，凛寒乍热，经停形瘦，心悸耳鸣，滋补填阴，转兼便泄。孟英视脉虚弦缓大，而气短懒言，卧榻不支，动即自汗。曰：固虚也，然非滋阴药所宜。予参、芪、龙、牡、桂、苓、甘、芍、冬虫夏草、饴糖，大剂服旬日而安。继去龙、牡，加归、杞服二十剂，汛至而康。病者欲常服补药，孟英止之曰：病痊体健，何以药为？吾先慈尝云，人如欹器，虚则欹，中则正，满则覆。世之过服补剂，致招盈满之灾者比比", "白话": "钱氏妇患咳数月，多医莫治，渐至废寝忘餐、凛寒乍热、经停形瘦、心悸耳鸣；用滋补填阴药，反增便泄。王孟英视之：脉虚弦缓大，气短懒言、卧床不支、动则自汗。说：固然是虚，但非滋阴药所宜。给党参、黄芪、龙骨、牡蛎、桂枝、茯苓、甘草、白芍、冬虫夏草、饴糖，大剂服十日而安；继去龙骨、牡蛎，加当归、杞子，服二十剂，月经来潮而康复。病者想常服补药，孟英制止道：病愈体健，何必吃药？我先母曾说：人如欹器（宥坐之器），虚则倾、中则正、满则覆。世人过服补剂招致盈满之灾者比比皆是，可不引以为戒吗？"}, {"source": "条84｜《归砚录》卷四", "原文": "梅溪蒋君宝斋令堂，自上年夏秋间患痢之后，神疲少寐，不能起床，医谓其虚，率投补药，驯致惊疑善悸，烦躁呓语，胁痛巅颠疼，耳鸣咽痛，凛寒暮热，大汗如淋，晕厥时形，愈补愈殆。李君苍雨邀余诊之，脉弦滑而数，白睛微红，而眼眶如墨，舌绛无苔。因问胸闷乎？曰闷甚。便秘乎？曰秘甚。溺热乎？曰热甚。岂非气郁而痰凝，痰阻而气痹，肺胃无以肃降，肝胆并力上升，浊不下行，风自火出？虽年逾五旬，阴血不足，而上中窒塞，首要通阳。", "白话": "梅溪蒋宝斋的母亲，自上年夏秋间患痢之后，神疲少寐、不能起床。医生说虚，一律投补药，渐渐出现惊疑善悸、烦躁呓语、胁痛巅顶痛、耳鸣咽痛、凛寒暮热、大汗如淋、时发晕厥——越补越危。李苍雨请我诊之：脉弦滑而数，白睛微红而眼眶如墨，舌绛无苔。因而问道：胸闷吗？答：很闷。便秘吗？答：很秘。小便热吗？答：很热。这岂非气郁而痰凝、痰阻而气痹，肺胃无以肃降、肝胆并力上升，浊不下行、风从火出？虽然年过五旬、阴血不足，但上中焦窒塞，首要通阳。为处小陷胸汤加菖蒲、薤白、旋覆花、竹茹、茯苓、枳实、郁李"}, {"source": "条85｜《冷庐医话》卷四", "原文": "表兄周乙藜学博士照，于道光壬寅年患腿热，而按之不热，行步无力，不痛不肿，延医诊治，谓是湿热，重用防己，服之忽心悸不寐，别招医治，谓是阴虚，用熟地等药，心悸仍然，腿患益甚，腿肉日削，食少神惫，势就危殆，时乙藜家质库中友朱光甫能医，乃令治之，曰：此痿病也。诚然是湿热，诚然是阴虚，然专治一端则误矣。投以清燥汤，病日减，继用虎潜丸法，出入增损，至三百剂始复原。乙藜因是潜玩医书，深究脉学，为人治病屡奏效。", "白话": "表兄周乙藜学博士（照），于道光壬寅年患腿热而按之不热、行步无力、不痛不肿。延医诊治，说是湿热，重用防己，服后忽然心悸不寐；另请医生，说是阴虚，用熟地等药，心悸仍在而腿病更重，腿肉日削、食少神惫，势就危殆。当时乙藜家当铺中友人朱光甫懂医，让他治疗。说：这是痿证。确实是湿热，确实是阴虚，但专治一端就错了。投以清燥汤，病日渐减轻；继用虎潜丸法加减出入，至三百剂才复原。乙藜因此潜心研读医书、深究脉学，为人治病屡见效。"}, {"source": "条86｜《临症经应录》卷四", "原文": "某，半产十数日，恶露涌行，乃瘀血未尽，新血未生，是以心悸头眩，饮食减少，阴虚不寐，阳虚汗多，脉象弦细。法宜黑神散进退，虽补阴理阳，最怕虚脱之变。\n金按：丹溪先生云：产后禁芍，恐酸寒伐生生之气。此语几误苍生，总而言之非定法也，临症见机而作可也。\n炒当归 炒赤芍 炒枣仁 黄芪皮 阿胶 浮麦 炙草 柏子仁 朱茯神 熟地炭 桂圆壳 秋荷叶蒂饭上蒸", "白话": "某人，半产（流产）十几天，恶露大量而下——这是瘀血未尽、新血未生，所以心悸头眩、饮食减少；阴虚则不寐，阳虚则汗多，脉象弦细。治法宜黑神散加减进退；虽在补阴理阳，最怕虚脱之变。金按：丹溪先生说「产后禁芍药，恐酸寒伐生生之气」，此语几乎误尽苍生；总而言之不是定法，临证见机而作可也。方：炒当归、炒赤芍、炒酸枣仁、黄芪皮、阿胶、浮小麦、炙甘草、柏子仁、朱茯神、熟地炭、桂圆壳、秋荷叶蒂（饭上蒸）。"}, {"source": "条87｜《得心集医案》卷四", "原文": "屡接来书，颇为病累，急欲图治，以保天年。弟于手录中查阅甲辰秋有来书，偶因醉酒激怒，心悸难支，服参数钱，遂好如故。白后每逢喧闹之地则惕然而惊，至幽静之处方渐安适。连年所服之药，无非养心生血。近月以来，怔忡尤甚，动静无分，所幸时惊时止，故不服药尚可耐过。惟唯虑作文之时心悸，难以完卷，现在精神似实为惊所困，时爽时滞，难以名状，望为斟酌云云。余思兄之旧病根源，良由将息失宜，耽酒多怒，扰动五志之阳，下元水亏", "白话": "（病家来书）屡接来信，深为病累，急想图治以保天年。弟在手录中查到甲辰秋有来信说：偶然因醉酒激怒，心悸难支，服了几钱人参即恢复如常。此后每逢喧闹之地就惕然而惊，到幽静之处才渐渐安适。连年所服之药无非养心生血。近月以来怔忡尤甚，动静皆然，所幸时惊时止，不服药尚可耐过；只是顾虑作文（考试）之时心悸难以完卷。现在精神似实为惊所困，时爽时滞，难以名状，望为斟酌。（医者）我想兄长旧病根源，确由将息失宜、嗜酒多怒，扰动五志之阳，下元水亏、风木内震、肝肾阴耗，所以多怔忡；连年所进汤丸都归咎于"}, {"source": "条88｜《王旭高临证医案》卷二", "原文": "吴，气血两虚，心跳头眩。肝郁不舒，胸中痞胀。用景岳逍遥饮参入丹溪左金丸。\n大熟地 香附 当归 陈皮 白芍 茯神 枣仁 砂仁 白术 吴萸炒川连", "白话": "吴某，气血两虚，心跳头眩；肝郁不舒，胸中痞胀。用景岳逍遥饮合入丹溪左金丸：大熟地、香附、当归、陈皮、白芍、茯神、酸枣仁、砂仁、白术、吴茱萸炒川连。"}, {"source": "条89｜《王旭高临证医案》卷二", "原文": "赵，血不养心，则心悸少寐。胃有寒饮，则呕吐清水。虚火燥金，则咽痛。肝木乘中，则腹胀。此时调剂，最难熨贴。盖补养心血之药，多嫌其滞；清降虚火之药，又恐其滋。欲除胃寒，虑其温燥劫液；欲平肝木，恐其克伐耗气。今仿胡洽居士法，专治其胃。以胃为气血之乡，土为万物之母，一举而三善备焉。请试服之。\n党参 冬术 茯苓 半夏 枣仁 扁豆 陈皮 怀山药 秫米", "白话": "赵某，血不养心则心悸少寐；胃有寒饮则呕吐清水；虚火灼肺则咽痛；肝木乘土则腹胀。此时调剂最难熨帖：补养心血之药多嫌其滞，清降虚火之药又恐其滋腻；欲除胃寒，顾虑温燥劫液；欲平肝木，顾虑克伐耗气。今仿胡洽居士法，专治其胃——以胃为气血之乡、土为万物之母，一举而三善备。请试服之。方：党参、冬术、茯苓、半夏、酸枣仁、扁豆、陈皮、怀山药、秫米。"}, {"source": "条90｜《王旭高临证医案》卷二", "原文": "李，病将半载，寒热淹缠。前方补营，兼以疏郁，心悸腹胀仍然。兹更便溏足肿，是脾气虚弱也。脉缓无力，当补其脾，进归脾加减法。\n防风根 党参 黄芪 冬术 茯苓 大腹皮 归身 白芍 枣仁 木香 荷叶蒂", "白话": "李某，病近半年，寒热缠绵。前方补营兼疏郁，心悸腹胀仍然。现在又便溏、足肿，是脾气虚弱也。脉缓无力，当补其脾，进归脾汤加减法。方：防风根、党参、黄芪、冬术、茯苓、大腹皮、当归身、白芍、酸枣仁、木香、荷叶蒂。"}, {"source": "条91｜《王旭高临证医案》卷二", "原文": "倪，据述有时惊悸，有时肌肉顽木，或一日溏泄数次，或数日一大便，坚干难出，惟唯小便常红。此心气郁结，脾气失运。失运则生湿，郁结则聚火。火则耗精，湿则阻气而气机不利矣。拟荆公妙香散加味，补益心脾，通达气机立法。\n西洋参 黄芪 茯神 桔梗 远志 怀山药 麝香调服 辰砂 木香 川连盐水炒 炙甘草 麦冬元米炒", "白话": "倪某，据述有时惊悸，有时肌肉顽麻，或一日溏泻数次，或数日大便一次、坚干难出，只是小便常红。此心气郁结、脾气失运：失运则生湿，郁结则聚火；火则耗精，湿则阻气而气机不利。拟荆公妙香散加味，以补益心脾、通达气机立法。方：西洋参、黄芪、茯神、桔梗、远志、怀山药、麝香（调服）、辰砂、木香、川连（盐水炒）、炙甘草、麦冬（元米炒）。"}, {"source": "条92｜《王旭高临证医案》卷三", "原文": "孙，水停心下则悸，气郁胸中则痛，痛甚则痞塞而吐白沫，得食则宽。此中虚夹痰饮为患也。\n六君子汤加川朴、干姜、桂木、沉香。", "白话": "孙某，水停心下则悸，气郁胸中则痛，痛甚则痞塞而吐白沫，得食则宽。此中虚夹痰饮为患。方：六君子汤加川朴、干姜、桂木、沉香。"}, {"source": "条93｜《王旭高临证医案》卷三", "原文": "徐，昔立斋治病，每定一方，令人服数十剂，非心精识果，乌能如此！然非病家信之真，任之专，亦乌能如此！林也不才，何敢妄希前哲。然审病既的，药当不谬。从此加鞭，以图进益。\n天冬 麦冬 生地 熟地 怀山药 沙参 茯神 枣仁 牡蛎 白芍 洋参 阿胶 红枣 浮麦\n此妇年三十四五，从未生育，因惊恐患怔忡头昏，耳鸣，火升，发热汗出，食少便坚，将及百日。服此方三十帖，见效。即将此方加重，煎膏常服，几及一年，痊全愈。", "白话": "徐某案：昔日薛立斋治病，每定一方让人服数十剂，不是心思精专、见识果决，怎能如此？然非病家信之真、任之专，又怎能如此？我不才，何敢妄希前哲；但审病既准，药当不谬，从此加鞭以图进益。方：天冬、麦冬、生地、熟地、怀山药、沙参、茯神、酸枣仁、牡蛎、白芍、洋参、阿胶、红枣、浮小麦。此妇年三十四五，从未生育，因惊恐患怔忡、头昏耳鸣、火升、发热汗出、食少便坚，将及百日。服此方三十帖见效；即将此方加重煎膏常服，近一年而痊愈，后来生一子。"}, {"source": "条94｜《环溪草堂医案》卷三", "原文": "赵，病后小产，产后感邪咳嗽，寒热似疟。服解散疏和药五六剂，邪退未尽，夜犹微热。然头晕心跳，寐则惊惕，虚象见矣。拟养营化邪法。\n四物汤合二贤，加苏子、苏梗、苏叶、川贝、杏仁、枳壳、茯苓、款冬花。\n用三苏、二贤、四物，意在泄血分之风，和血中之气。加化痰止咳药，佐使之耳。", "白话": "赵某，病后小产，产后感邪咳嗽、寒热如疟。服解散疏和之药五六剂，邪退未尽，夜里仍微热；但头晕心跳、睡则惊惕，虚象已见。拟养营化邪法：四物汤合二贤，加苏子、苏梗、苏叶、川贝、杏仁、枳实（壳）、茯苓、款冬花。用三苏、二贤、四物，意在泄血分之风、和血中之气；加化痰止咳药佐使。"}, {"source": "条95｜《凌临灵方·心悸怔忡》", "原文": "某，心体不足，心用有余，肝为心母，操用神机，肝木与心火相为煽动，肝阳浮越不潜，彻夜不寐，心悸忡怔，有不能支持之候。脉弦滑数，左寸关长直。治宜清心和胃，佐以平肝。\n紫丹参猪心血拌炒 广陈皮 朱茯神 川郁金 卷心竹叶 元参 宋半夏 苍龙齿 石菖蒲 猪胆汁 炒枣仁 石决明 玳瑁边如无，以元武板 鲜竹茹", "白话": "某人，心体不足、心用有余；肝为心之母，操用神机，肝木与心火相煽动，肝阳浮越不潜，彻夜不寐、心悸怔忡，有不能支持之候。脉弦滑数、左寸关长直。治宜清心和胃、佐以平肝。方：紫丹参（猪心血拌）、广陈皮、朱茯神、川郁金、卷心竹叶、元参、宋半夏、苍龙齿、石菖蒲、猪胆汁炒枣仁、石决明、玳瑁边（如无以玄武板代）、鲜竹茹。"}, {"source": "条96｜《校注医醇賸剩义》卷一", "原文": "常州丁姓女，患惊悸气促，喉舌作痛，予制驯龙驭虎汤，连服数十剂而愈。驯龙驭虎汤自制：\n龙齿二钱 琥珀一钱 真珠母八钱 生地六钱 玉竹四钱 栝蒌皮三钱 石斛三钱 柏子霜二钱 白芍一钱五分 薄荷一钱 莲子二十粒，打碎，勿去心 沉香四分，人乳磨冲", "白话": "常州某丁姓女子，患惊悸气促、喉舌作痛。我制驯龙驭虎汤，连服数十剂而愈。驯龙驭虎汤（自制方）：龙齿二钱、琥珀一钱、真珠母八钱、生地六钱、玉竹四钱、栝蒌皮三钱、石斛三钱、柏子霜二钱、白芍一钱五分、薄荷一钱、莲子二十粒（打碎、勿去心）、沉香四分（人乳磨冲）。"}, {"source": "条97｜《王乐亭指要》卷二", "原文": "章左，思虑太过，心神不安，时而震动，譬之鱼失水即跃。心无血养，焉得宁静，此即怔忡惊悸之渐也。\n桂圆制洋参三钱 枣仁炒，八钱 茯神辰砂拌，三钱 丹参二钱 柏子仁去油，一钱 紫石英三钱 红枣五个 淮小麦一撮 猪心一个，煮烂一碗去油煎药", "白话": "章某（男），思虑太过，心神不安，时而震动——好比鱼失水就跳跃；心无血养，怎能宁静？这正是怔忡惊悸之渐。方：桂圆制洋参三钱、炒酸枣仁八钱、茯神（辰砂拌）三钱、丹参二钱、柏子仁（去油）一钱、紫石英三钱、红枣五个、淮小麦一撮、猪心一个（煮烂一碗，去油）煎药。"}, {"source": "条98｜《蠢子集》卷一", "原文": "有一幼妇六脉毫不动，惟唯有心脉往上冲。中指根节动。知是经脉结下焦，心颤心悸兼心疼。经脉结住，必上窜胞络为祟。我用风药带金丹，肉肉桂附附子吴萸往下通。连吃两付病皆愈，六脉皆动，病自安矣。再用蜡丸细细攻。用黄蜡溶化，入金丹搅匀为丸，日食数丸，不久痊全愈。", "白话": "有一年轻妇女，六部脉都不见搏动，只有心脉往上冲、中指根节跳动。知道是经脉结于下焦，心颤心悸兼心痛；经脉结住必上窜胞络为祟。我用风药带金丹、肉桂、附子、吴茱萸往下通，连吃两剂病都好了，六脉皆复动，病自安。再用蜡丸缓攻：用黄蜡熔化，入金丹搅匀为丸，每日服数丸，不久痊愈。"}, {"source": "条99｜《慎五堂治验录》卷十", "原文": "陆星农孙女。武叔卿曰：血闭于阴经，营卫行之不通则发热。脉始由足少阴肾，生于足阳明胃，主于手少阴心。少阴之气不与阳明交合，阳明之气不与少阴相合，上下不交，血液不生，经脉不通，是以心悸脉代，经来身热，治以炙甘草汤。", "白话": "陆星农孙女案。武叔卿说：血闭于阴经，营卫运行不通则发热。脉始于足少阴肾、生于足阳明胃、主于手少阴心；少阴之气不与阳明交合、阳明之气不与少阴相合，上下不交、血液不生、经脉不通，因此心悸脉代、经来身热。治以炙甘草汤。"}, {"source": "条100｜《慎五堂治验录》卷十一", "原文": "杨宗保，乙酉七月，西石牌泾。因惊疑致心悸，甚至呕吐痰涎，肢痉不寐，一遇逆境其症愈剧，脉细兼滑。心胆不足，邪附痰涎为患。先予清镇化痰，后用丸药善后，俾不成痫症为吉。\n竹沥制半夏二钱 青龙齿三钱 甘草四分 云南白茯神三钱 广郁金白矾炒，一钱半 辰砂五分 生左顾牡蛎五钱 淮小麦三钱 天竺黄一钱\n素体心怯，近得惑疾，凡遇声响人众则惕然而惊，心声疑惧，不知所从，饮良渐减，四肢萎软，投剂似合病机，依原进步可也", "白话": "杨宗保，乙酉七月，西石牌泾人。因惊疑致心悸，甚至呕吐痰涎、肢痉不寐，一遇逆境其症愈剧，脉细兼滑。心胆不足，邪附痰涎为患。先予清镇化痰，后用丸药善后，以不变成痫证为吉。方：竹沥制半夏二钱、青龙齿三钱、甘草四分、云南白茯神三钱、广郁金（白矾炒）一钱半、辰砂五分、生左顾牡蛎五钱、淮小麦三钱、天竺黄一钱。（二诊）素体心怯，近得「惑疾」，凡遇声响人众就惕然而惊、心疑恐惧、不知所从，饮食渐减、四肢萎软；投剂似合病机，依原进步可也。方：制半夏三钱、龙骨三钱、紫石英三钱、桃枝五枝、北秫米三钱"}, {"source": "条101｜《王应震要诀·王震云先生诊视脉案》", "原文": "江桥镇金思荣。失血之后，时有怔忡，甚则眩晕，闻人声则惊恐而悸，四肢厥冷，小腹微满，此系咯血后恐怖伤其神志。细审六脉虚软带急，心肾不足，气血不充，明有验矣。其咳呛无定者，亦因君相之火上炎烁肺，故宁静则嗽亦稍安，恼怒则惊恐怔忡更甚。当以上下分治，拟血肉有情之品填补虚处，不致酿成损症。\n河车胶 元武胶 真阿胶 大熟地 芡实肉 建莲肉 云茯神 淡秋石 怀山药\n共为末，猪脊筋蒸熟和丸，参须汤送下。\n晚服丸方", "白话": "江桥镇金思荣，失血之后时有怔忡，重则眩晕，听见人声就惊恐而悸，四肢厥冷，小腹微满。这是咯血后惊恐伤其神志。细审六脉虚软带急，心肾不足、气血不充，验证明白。其咳嗽无定者，也因君相之火上炎灼肺，故安静则咳稍安，恼怒则惊恐怔忡更甚。当上下分治，拟血肉有情之品填补虚处，不致酿成虚损重证。方：河车胶、元武胶（龟板胶）、真阿胶、大熟地、芡实肉、建莲肉、云茯神、淡秋石、怀山药，共为末，猪脊筋蒸熟和丸，参须汤送下。晚服丸方：参须、人参、白茯神为末，蜜丸，米饮汤送下。"}, {"source": "条102｜《马培之医案·怔忡惊悸》", "原文": "常州，郁左，肾水不足，不能涵木。君相之火上升，心神不安，惊惕，卧不成寐，头眩肉瞤，胸闷作恶，舌苔灰黑。浊痰在胃，胃失下降。养阴和中，以安君相。\n南沙参 麦冬 黄连酒炒 石斛 玄参 竹茹 石决 茯神 枇杷叶 合欢皮 青果 丹皮\n二诊：惊惕稍定，君相之火稍平，舌苔灰黑未化，胸咽不舒，肺胃之气不展，浊痰不清，溺后浑浊，澄澈有底。此败精宿于精关，变而为浊。养阴清肝，兼舒肺胃。\n南沙参 麦冬 黄连 丹皮 ", "白话": "常州郁某（左），肾水不足不能涵木，君相之火上升，心神不安、惊惕、卧不成寐、头眩、肌肉瞤动、胸闷作恶，舌苔灰黑。浊痰在胃，胃失下降。治以养阴和中、以安君相。初方：南沙参、麦冬、黄连（酒炒）、石斛、玄参、竹茹、石决明、茯神、枇杷叶、合欢皮、青果、丹皮。二诊：惊惕稍定，君相之火稍平，舌苔灰黑未化，胸咽不舒，肺胃之气不展、浊痰不清；小便后浑浊、澄之有底——此败精宿于精关变而为浊。治以养阴清肝、兼舒肺胃。方：南沙参、麦冬、黄连、丹皮、石决明、石斛、枳壳、甘草、枇杷叶、竹茹、山栀（鸡子黄"}, {"source": "条103｜《马培之医案·怔忡惊悸》", "原文": "郑，恙由惊恐而起，旋即不寐，心胸热辣，咽嗌气痹，呃逆，甚则昏厥。《内经》云∶：惊者，心与肝胃病也。心气强则触之不动，心气虚则触之易惊。肝属木属风，风木震动，故病发惊骇。胃为多气多血之经，胃气壅则生热，故恶人与火，闻声则惊。心主藏神，惊则神恐，阳明痰热内踞心包，神不归舍，故见症如是。拟养心、和胃、平肝，以安神志。\n北沙参 法半夏 茯神 丹参 远志 当归 佛手 柏子仁 龙齿 竹茹 合欢皮 白蒺藜 鸡子", "白话": "郑某，病由惊恐而起，随即不寐、心胸热辣、咽喉气痹、呃逆，甚则昏厥。《内经》说：惊者，心与肝胃之病也。心气强则触之不动，心气虚则触之易惊；肝属木属风，风木震动，故病发惊骇；胃为多气多血之经，胃气壅则生热，故恶人与火、闻声则惊。心主藏神，惊则神恐；阳明痰热内踞心包，神不归舍，故见症如此。拟养心、和胃、平肝以安神志。方：北沙参、法半夏、茯神、丹参、远志、当归、佛手、柏子仁、龙齿、竹茹、合欢皮、白蒺藜、鸡子黄。"}, {"source": "条104｜《马培之医案·怔忡惊悸》", "原文": "某，季胁之旁，是虚里穴，跳跃如梭，阳明络空也。身前冲气欲动，胀痛一无形象，冷汗跗寒，食入恶心。仲景于“动气篇”中，都属阳微，仿以为法。\n人参 熟附子 桂枝 茯苓 杜仲 小茴香 真艾 紫石英", "白话": "某人，季胁之旁是虚里穴，跳跃如梭，是阳明络空。身前冲气欲动，胀痛而无形迹，冷汗、足跗发寒，食入恶心。仲景「动气篇」诸条都属阳微（阳气虚），仿其意为法。方：人参、熟附子、桂枝、茯苓、杜仲、小茴香、真艾、紫石英。"}, {"source": "条105｜《马培之医案·怔忡惊悸》", "原文": "某，思虑过度，心脾受亏，脾郁生痰，木郁化火，胸腹不舒，肉瞤心悸，左乳根动跃，食不甘味，痰涎如沫，梦泄耳鸣，心脾、肾三脏皆亏。拟养心脾以和肝胃。", "白话": "某人，思虑过度，心脾受亏，脾郁生痰、木郁化火，胸腹不舒，肉瞤心悸，左乳根动跃，食不甘味，痰涎如沫，梦遗耳鸣。心、脾、肾三脏皆亏。拟养心脾以和肝胃。方：当归、紫丹参、法半夏、茯神、远志肉、北沙参、酸枣仁、陈皮、合欢皮、山药、木香、秫米。"}, {"source": "条106｜《马培之医案·怔忡惊悸》", "原文": "某，肝肾阴亏，心气不宣，头眩、腰酸、足乏，心神惊悸。育阴调荣，兼养心气。\n归身 生地炙 枣仁 白芍 川断 茯神 丹参 怀牛膝 参须 金毛脊 柏子仁 夜交藤 红枣", "白话": "某人，肝肾阴亏，心气不宣，头眩、腰酸、足乏，心神惊悸。治以育阴调荣、兼养心气。方：当归身、炙生地、酸枣仁、白芍、川断、茯神、丹参、怀牛膝、参须、金毛狗脊、柏子仁、夜交藤、红枣。"}, {"source": "条107｜《张聿青医案》卷四", "原文": "顾右，心悸肢节作痛，皮寒骨热，脉象细弦。营血亏损，遂致营卫失和，营血不能濡养经络，宜养血和营。\n全当归三钱 黑草炙，五分 柏子霜三钱 甘杞子三钱 龙眼肉五枚 白芍酒炒，二钱 茯神三钱 枣仁二钱 阿胶珠炒，二钱 大南枣四枚\n二诊：心悸稍定，胃纳如常。的是营血不足，心阳不能下降。效方扩充。\n大生地四钱 辰麦冬三钱 枣仁二钱 白归身炒，一钱五分 阿胶二钱 白芍酒炒，一钱五分 辰茯神三钱 柏子霜三钱 龙眼", "白话": "顾某（女），心悸、肢节作痛，皮寒骨热，脉象细弦。营血亏损，以致营卫失和，营血不能濡养经络，宜养血和营。初方：全当归三钱、炙黑甘草五分、柏子霜三钱、甘杞子三钱、龙眼肉五枚、白芍（酒炒）二钱、茯神三钱、酸枣仁二钱、阿胶珠（炒）二钱、大南枣四枚。二诊：心悸稍定，胃纳如常，确是营血不足、心阳不能下降。效方扩充：大生地四钱、辰麦冬三钱、酸枣仁二钱、炒白归身一钱五分、阿胶二钱、白芍（酒炒）一钱五分、辰茯神三钱、柏子霜三钱、龙眼肉四枚，天王补心丹三钱清晨先服。又膏方：营阴亏损、营血不足，不"}, {"source": "条108｜《张聿青医案》卷七", "原文": "钟左，心下虚悸，脉细濡而右关滑。此由痰水聚于胸中，阴湿弥漫于下，则心阳浮越于上，长沙独得其旨，故《玉函经》中一则曰心下悸者为有水气，再则曰水停心下则心下悸。近医每以心营不足目之，未知圣训耳。\n制半夏一钱五分 炒杏仁三钱 云茯苓四钱 橘皮一钱五分 薤白头三钱 栝蒌仁炒，研，三钱 生姜汁二匙，冲", "白话": "钟某（男），心下虚悸，脉细濡而右关滑。此由痰水聚于胸中，阴湿弥漫于下，则心阳浮越于上。张仲景（长沙）独得其旨，故《玉函经》（《金匮要略》）中一则说「心下悸者为有水气」，再则说「水停心下则心下悸」。近世医生每以心营不足视之，未闻圣训耳。方：制半夏一钱五分、炒杏仁三钱、云茯苓四钱、橘皮一钱五分、薤白头三钱、栝蒌仁（炒研）三钱、生姜汁二匙（冲）。"}, {"source": "条109｜《张聿青医案》卷八", "原文": "王右，向有痰饮，兹则心悸不宁，遍身筋脉动跃，背脊寒冷，渐即汗出。脉象弦滑，舌胖苔腻。此肝阴不足，脾胃湿痰悉随肝阳鼓舞，君火为水气所干，以致摇撼震动。无性命之忧，有频年之累。\n茯苓神 石菖蒲 制半夏 广橘红 真武丸 远志肉 块辰砂 煨天麻 指迷茯苓丸", "白话": "王某（女），素有痰饮，现心悸不宁、遍身筋脉动跃、背脊寒冷、渐渐汗出。脉象弦滑，舌胖苔腻。此肝阴不足，脾胃湿痰都随肝阳鼓舞，君火为水气所干，以致摇撼震动。无性命之忧，有多年之累。方：茯苓、茯神、石菖蒲、制半夏、广橘红、真武丸、远志肉、块辰砂、煨天麻、指迷茯苓丸。"}, {"source": "条110｜《张聿青医案》卷八", "原文": "吴左，惊动胆木，木火蒸痰，窒碍灵府。怔忡不宁，神情呆钝。化痰宣窍，参以镇坠。\n制半夏一钱五分 广橘红一钱 广玉金一钱五分 块辰砂三钱，包 陈胆星五分 白茯苓三钱 远志肉五分 炒枣仁二钱，打 九节菖蒲二分 金器一件，悬煎", "白话": "吴某（男），惊动胆木，木火蒸痰，窒碍灵府（心窍）。怔忡不宁，神情呆钝。治以化痰宣窍、参以镇坠。方：制半夏一钱五分、广橘红一钱、广郁金一钱五分、块辰砂三钱（包）、陈胆星五分、白茯苓三钱、远志肉五分、炒酸枣仁二钱（打）、九节菖蒲二分，金器一件悬煎。"}, {"source": "条111｜《张聿青医案》卷九", "原文": "某右，头痛偏右，痰时带红。二者今虽暂安，然眩晕心悸，火从上逆，脉弦带滑。无非肝肾之阴精不足，而脾胃之痰湿有余，胆胃之气，不克下降，则肝脏之阳，上升太过。拟熄息肝和阳。\n白蒺藜 黄芩 青防风 炒枣仁 石决明 朱茯神 羌活 白归身 稆豆衣 制半夏", "白话": "某女，头痛偏右，痰中带血。二者今虽暂安，但眩晕心悸、火从上逆，脉弦带滑。无非肝肾阴精不足，而脾胃痰湿有余；胆胃之气不能下降，则肝脏之阳上升太过。拟熄肝和阳。方：白蒺藜、黄芩、青防风、炒酸枣仁、石决明、朱茯神、羌活、白归身、稆豆衣、制半夏。"}, {"source": "条112｜《张聿青医案》卷十四", "原文": "王左，阴虚夹痰，胆胃失降，肝阳暗动。每至将寐，辄作惊惕。拟介类以镇肝潜阳。\n炙龟板五钱 煅磁石三钱 茯神三钱 酒炒杭白芍一钱五分 生牡蛎四钱 煅龙齿三钱 黑豆衣三钱 薄橘红一钱 金器一件悬煎", "白话": "王某（男），阴虚夹痰，胆胃失降，肝阳暗动。每到将睡之时就惊惕。拟用介类以镇肝潜阳。方：炙龟板五钱、煅磁石三钱、茯神三钱、酒炒杭白芍一钱五分、生牡蛎四钱、煅龙齿三钱、黑豆衣三钱、薄橘红一钱，金器一件悬煎。"}, {"source": "条113｜《张聿青医案》卷十四", "原文": "某，上年眩晕心跳，甚至心气昏糊，经壮水涵木而化肝热，诸恙较前大退。惟唯心悸仍未霍全，时觉胆怯。肝胆皆木也，肝木上升，胆木下降，是为和平。惟唯肝升太过，则胆降不及，胆木漂拔，自然气馁，胆病、实肝病也。经云、虚则补其母。木之母，水也，所以降胆必先熄息肝，熄息肝必先滋肾。\n炙龟板十二两 炒枣仁三两 朱茯神三两 丹皮二两 石决明五两 女贞子酒蒸，三两 潼沙苑酒炒，三两 白归身酒炒，二两 炒萸肉一两五钱 炙", "白话": "某人，上年眩晕心跳，甚至心气昏糊。经壮水涵木、清化肝热后，诸恙大退；只是心悸仍未全好，时觉胆怯。肝胆都属木：肝木上升、胆木下降，是为和平；若肝升太过，则胆降不及，胆木漂拔，自然气馁——胆病实即肝病。《经》云「虚则补其母」，木之母是水，所以降胆必先熄肝，熄肝必先滋肾。膏方：炙龟板十二两、炒酸枣仁三两、朱茯神三两、丹皮二两、石决明五两、女贞子（酒蒸）三两、潼沙苑（酒炒）三两、白归身（酒炒）二两、炒萸肉一两五钱、炙鳖甲十两、生山药三两、柏子霜三两、奎党参五两、远志肉六钱、大生地六两"}, {"source": "条114｜《张聿青医案》卷十四", "原文": "杨媪，心悸跳荡，时为不寐，偏左头痛，腰股作酸，脉弦尺涩。阳升不熄息，拟熄息肝宁神。\n朱茯神三钱 煅龙齿三钱 酒炒杭白芍一钱五分 黑豆衣三钱 炒枣仁二钱 夜交藤三钱 柏子霜三钱 滁菊花三钱 天王补心丹三钱，先服，另五钱包煎", "白话": "杨老妇，心悸跳荡，时而不寐，偏左头痛，腰股作酸，脉弦、尺涩。阳升不熄，拟熄肝宁神。方：朱茯神三钱、煅龙齿三钱、酒炒杭白芍一钱五分、黑豆衣三钱、炒酸枣仁二钱、夜交藤三钱、柏子霜三钱、滁菊花三钱，天王补心丹三钱先服，另五钱包煎。"}, {"source": "条115｜《张聿青医案》卷十四", "原文": "严右，风阳不平，心悸多恐，乙木过升，甲木不降也。\n阿胶珠二钱 辰麦冬三钱 炒枣仁二钱 酒炒杭白芍一钱五分 女贞子三钱酒蒸 钩藤三钱 辰茯神三钱 黑豆衣三钱 柏子霜三钱", "白话": "严某（女），风阳不平，心悸多恐。此乙木（肝）升发太过、甲木（胆）下降不及之故。方：阿胶珠二钱、辰麦冬三钱、炒酸枣仁二钱、酒炒杭白芍一钱五分、女贞子三钱（酒蒸）、钩藤三钱、辰茯神三钱、黑豆衣三钱、柏子霜三钱。"}, {"source": "条116｜《张聿青医案》卷十四", "原文": "某，脉症相安，然阳气仍复上升，皆由木失滋涵。再滋肾养肝，宁神熄息木。\n阿胶二钱 夜交藤四钱 黑豆衣三钱 炒枣仁二钱 煅龙齿三钱 酒炒女贞子三钱 酒炒杭白芍一钱五分 滁菊花一钱五分 海蛤粉三钱 淮小麦五钱 糯稻根五钱 天王补心丹三钱，晨服四钱，包煎\n二诊：寐得稍安，饮食如常。育阴熄息肝，再望应手。\n阿胶珠三钱 朱茯神三钱 夜交藤三钱 酒炒杭白芍一钱五分 酒炒女贞子三钱 炒枣仁二钱 煅青龙齿三钱 柏子", "白话": "某人，脉证相安，但阳气仍复上升，皆由肝木失于滋涵。再拟滋肾养肝、宁神熄风。初方：阿胶二钱、夜交藤四钱、黑豆衣三钱、炒酸枣仁二钱、煅龙齿三钱、酒炒女贞子三钱、酒炒杭白芍一钱五分、滁菊花一钱五分、海蛤粉三钱、淮小麦五钱、糯稻根五钱，天王补心丹三钱（晨服四钱，包煎）。二诊：睡眠稍安，饮食如常。育阴熄肝，再图应手。方：阿胶珠三钱、朱茯神三钱、夜交藤三钱、酒炒杭白芍一钱五分、酒炒女贞子三钱、炒酸枣仁二钱、煅青龙齿三钱、柏子霜三钱、淮小麦五钱，金器一件。三诊：腰为肾之府，腿股为奇经所辖，"}, {"source": "条117｜《张聿青医案》卷十七", "原文": "某右，经至如崩，腹胀已舒，心悸头晕。统藏失职。再益心脾。\n炙黄芪二钱 野于术一钱五分 血余炭一钱 阿胶珠三钱 党参三钱 炒枣仁三钱 乌贼骨三钱 蒲黄炭八分 朱茯神三钱 龙眼肉三枚", "白话": "某女，月经来如崩，腹胀已舒，心悸头晕。是脾统肝藏失职。再益心脾。方：炙黄芪二钱、野于术一钱五分、血余炭一钱、阿胶珠三钱、党参三钱、炒酸枣仁三钱、乌贼骨三钱、蒲黄炭八分、朱茯神三钱、龙眼肉三枚。"}, {"source": "条118｜《贯唯集·不寐》", "原文": "据述病起多年，心悸不寐，或止或发，时轻时重，所进药饵颇多，未能全好。刻诊脉弦数而滑，其为痰火阻络可知。拟进《三因》温胆法加味治之。\n半夏梨汁炒 橘红 枳实 茯苓 炙草 李仁猪胆汁拌炒 元参 丹参 焦栀 秫米 竹二青", "白话": "据述病起多年，心悸不寐，或止或发，时轻时重，所进药物颇多，未能全好。刻诊脉弦数而滑，其为痰火阻络可知。拟进《三因方》温胆汤法加味治之。方：半夏（梨汁炒）、橘红、枳实、茯苓、炙甘草、李仁（猪胆汁拌炒）、元参、丹参、焦山栀、秫米、竹二青（竹茹）。"}, {"source": "条119｜《临诊医案·正文》", "原文": "顾咸坤，奚家木桥一元鞋子店。年已七旬有余，劳神太过，肝风震动，患久湿痰，心肝血少，思虑伤脾，怔忡惊悸。此系思虑太过，伤神气营卫，拟调养安神定悸法。\n炒黑远志六分 川郁金六分 紫丹参一钱五分 柏子仁三钱 炒白芍一钱五分 川石斛四钱 制半夏一钱五分 云苓二钱 加嫩钩钩三钱，后下 玫瑰花二朵", "白话": "顾咸坤（奚家木桥一元鞋店），年已七旬余，劳神太过，肝风震动，患久湿痰，心肝血少，思虑伤脾，怔忡惊悸。此系思虑太过、伤神气营卫，拟调养安神定悸法。方：炒黑远志六分、川郁金六分、紫丹参一钱五分、柏子仁三钱、炒白芍一钱五分、川石斛四钱、制半夏一钱五分、云苓二钱，加嫩钩藤三钱（后下）、玫瑰花二朵。"}, {"source": "条120｜《临诊医案·正文》", "原文": "大东门外郎家桥，福康水先生。劳神太过，心血内亏，而成怔忡、健忘、惊悸之症。\n经霜桑叶一钱五分 柏子霜包，三钱 生枣仁二钱 女贞子三钱 霍石斛三钱 炒黑远志六分 紫丹参一钱五分 加抱茯神三钱 嫩钩钩三钱，后入 灯心二十寸，辰拌", "白话": "大东门外郎家桥福康水先生，劳神太过，心血内亏，而成怔忡、健忘、惊悸之症。方：经霜桑叶一钱五分、柏子霜（包）三钱、生酸枣仁二钱、女贞子三钱、霍石斛三钱、炒黑远志六分、紫丹参一钱五分，加抱茯神三钱、嫩钩藤三钱（后入）、灯心二十寸（辰砂拌）。"}, {"source": "条121｜《旌孝堂医案·湿痰》", "原文": "肝旺胆虚，湿痰入络，虚阳上升，于是心悸头眩耳鸣，懊憹难名，间有呛咳，惊悸麻痹，善怯多疑，脉息弦滑，右脉反关，左脉独见。拟方善图，方可渐入佳境。\n煅磁石 瓜蒌霜 半夏粉 木防己 九制于术 木茯神 白蒺藜 广橘皮络 荷筋 瓦楞子 路路通 八楞麻 苦竹根 络石藤 首乌藤", "白话": "肝旺胆虚，湿痰入络，虚阳上升，于是心悸、头眩、耳鸣，心中懊憹难以名状，间有呛咳、惊悸麻痹、善怯多疑。脉息弦滑，右脉反关、左脉独见。拟方善图，方可渐入佳境。方：煅磁石、瓜蒌霜、半夏粉、木防己、九制于术、朱茯神、白蒺藜、广橘皮络、荷筋、瓦楞子、路路通、八楞麻、苦竹根、络石藤、首乌藤。"}, {"source": "条122｜《医学衷中参西录·医方》", "原文": "一媪，年近六旬。资禀素弱，又兼家务劳心，遂致心中怔忡，肝气郁结，胸腹胀满，不能饮食，舌有黑苔，大便燥结，十数日一行。广延医者为治，半载无效，而羸弱支离，病势转增。后愚诊视，脉细如丝，微有弦意，幸至数如常，知犹可治。遂投以升降汤，为舌黑便结，加鲜地骨皮一两，数剂后，舌黑与便结渐愈，而地骨皮亦渐减。至十剂病愈强半，共服百剂，病愈而体转健康。升降汤：\n野台参二钱 生黄芪二钱 白术二钱 广陈皮二钱 川厚朴", "白话": "一位老妇，年近六旬，禀赋素弱，又兼家务劳心，遂致心中怔忡、肝气郁结、胸腹胀满、不能饮食，舌有黑苔，大便燥结、十数日一行。广延医生治疗半年无效，羸弱支离，病势转增。后来我诊视：脉细如丝、微有弦意，所幸至数如常，知犹可治。遂投以升降汤，因舌黑便结加鲜地骨皮一两；数剂后舌黑与便结渐愈，地骨皮也渐减量；服至十剂病愈过半，共服百剂，病愈而体质转为健康。升降汤：野台参二钱、生黄芪二钱、白术二钱、广陈皮二钱、川厚朴二钱、生鸡内金（捣细）二钱、知母三钱、生杭芍三钱、桂枝尖一钱、川芎一钱、生姜"}, {"source": "条123｜《医学衷中参西录·医方》", "原文": "一人，年四十七。咳嗽短气，大汗如洗昼夜不止，心中怔忡，病势危急。遣人询方，律先用山萸肉去净核二两煎服，以止其汗。翌日迎愚诊视，其脉微弱欲无，呼吸略似迫促。自言大汗虽止，而仍有出汗之时，怔忡见轻，仍觉短气。知其确系大气下陷，遂投以升陷汤，为其有汗，加龙骨、牡蛎皆不用煅各五钱，三剂而愈。", "白话": "一人年四十七，咳嗽短气，大汗如洗昼夜不止，心中怔忡，病势危急。派人询方，嘱先用山萸肉（去净核）二两煎服以止其汗。次日请我诊视：脉微弱欲无，呼吸略似迫促。自言大汗虽止但仍时时出汗，怔忡见轻仍觉短气。知其确系大气下陷，遂投以升陷汤；因其有汗，加龙骨、牡蛎（皆不用煅）各五钱，三剂而愈。"}, {"source": "条124｜《医学衷中参西录·药物》", "原文": "沧州董氏女，年二十余。胸胁满闷，心中怔忡，动则自汗，其脉沉迟微弱，右部尤甚，为其脉迟，疑是心肺阳虚，询之不觉寒凉，知其为胸中大气下陷也。其家适有预购黄芪一包，俾用一两煎汤服之。其族兄在座，其人颇知医学，疑药不对证。愚曰：勿多疑，倘有差错，余职其咎。服后，果诸病皆愈。其族兄疑而问曰：《神农本草经》黄芪原主大风，有透表之力，生用则透表之力益大，与自汗证不宜，其性升而能补，有膨胀之力，与满闷证不宜，今单", "白话": "沧州董氏女，年二十余。胸胁满闷，心中怔忡，动则自汗，脉沉迟微弱、右部尤甚。因其脉迟疑是心肺阳虚，问之不觉寒凉，知其为胸中大气下陷。她家恰有预购黄芪一包，让用一两煎汤服之。她的族兄在座，颇知医，怀疑药不对证。我说：不必多疑，倘有差错，我负责任。服后果然诸病皆愈。其族兄疑而问道：《神农本草经》黄芪原主大风，有透表之力，生用透表力更大，与自汗证不宜；其性升而能补、有膨胀之力，与满闷证不宜。今单用生黄芪一两许，而两证皆愈，连心中怔忡也愈，是何道理？答：黄芪确有透表之力，气虚不能逐邪外"}, {"source": "条125｜《医学衷中参西录·医案》", "原文": "表兄赵文林之妻，年近三旬，得不寐证，兼心中恒惊悸。\n病因：因家中诸事皆其自理，劳心过度，因得不寐兼惊悸病。\n证候：初苦不寐时，不过数日偶然，其过半夜犹能睡，继则常常如此，又继则彻夜不寐。一连七八日困顿已极，仿佛若睡，陡觉心中怦怦而动，即蓦然惊醒，醒后心犹怔忡，移时始定。心常发热，呼吸似觉短气，懒于饮食，大便燥结，四五日始一行。其脉左部弦硬，右部近滑，重诊不实，一息数近六至。\n诊断：此因用心过度，心", "白话": "表兄赵文林之妻，年近三旬，得不寐证，兼心中常惊悸。病因：家中诸事都由她操持，劳心过度，因而得不寐兼惊悸。证候：初病不寐时不过偶尔数日，过半夜还能睡；继则经常如此，再继则彻夜不寐。一连七八日困顿已极，仿佛睡着，陡觉心中怦怦而动，蓦然惊醒，醒后心仍怔忡，过一会才定。心常发热，呼吸似觉短气，懒于饮食，大便燥结、四五日一行。脉左部弦硬、右部近滑，重按不实，一息近六至。诊断：此因用心过度、心热耗血，又因热生痰之证。血液因热暗耗，阴虚不能潜阳，所以不寐；痰停心下，火畏水刑（心属火、痰属水"}, {"source": "条126｜《邵兰荪医案》卷二", "原文": "遗风徐，血后阴耗，脉濡数，舌黄滑，湿火未清，心悸健忘，仍遵前法再进。\n生地四钱 焦山栀三钱 黄草石斛三钱 夜交藤三钱 麦冬三钱 茯神四钱 远志肉八分 白薇钱半 丹参三钱 元参钱半 炒条芩钱半 淡竹叶钱半 灯心七支　四帖。\n介按：阳明湿热未清，再以劳神动肝，以致咳血而暗吸肾阴，肾液既虚，未能上承于心，则心悸健忘，滋液清热，安神养胃。治法极为周到。", "白话": "遗风徐某，失血后阴分耗损，脉濡数，舌黄滑，湿火未清，心悸健忘。仍遵前法再进。方：生地四钱、焦山栀三钱、黄草石斛三钱、夜交藤三钱、麦冬三钱、茯神四钱、远志肉八分、白薇一钱半、丹参三钱、元参一钱半、炒条芩一钱半、淡竹叶一钱半、灯心七支，四帖。介按：阳明湿热未清，又因劳神动肝，以致咳血而暗吸肾阴；肾液既虚、不能上承于心，则心悸健忘。滋液清热、安神养胃，治法极为周到。"}, {"source": "条127｜《竹亭医案》卷三", "原文": "苏府任太守恭人风火内郁，怔忡、眩晕治验。　　苏州太守任蓝轩先生恭人，嘉庆三年七月二十一日延诊。案云：始而火为风搏，风乃外来之风；既而风自火出，火乃内郁之火。火得风而摇动，风得火而熏蒸。痰因火起，悸由痰成，此怔忡、眩晕、汗多之所由来也，为之养阴清火，而风痰不致为累。\n制首乌三钱 炙鳖甲五钱 归身二钱 白芍炒，二钱 粉丹皮一钱半 半夏曲一钱半 茯神二钱 陈皮一钱半 远志肉炒，一钱半 酸枣仁炒，一钱半\n", "白话": "苏州知府任蓝轩先生的夫人，风火内郁，怔忡眩晕治验。嘉庆三年七月二十一日请诊。案云：起先火为风搏——风是外来之风；继而风自火出——火是内郁之火。火得风而摇动，风得火而熏蒸；痰因火起，悸由痰成，这就是怔忡、眩晕、汗多的由来。治以养阴清火，使风痰不致为害。方：制首乌三钱、炙鳖甲五钱、当归身二钱、白芍（炒）二钱、粉丹皮一钱半、半夏曲一钱半、茯神二钱、陈皮一钱半、远志肉（炒）一钱半、酸枣仁（炒）一钱半。用旧铁器约一两烧红，淬入药汤即取出，候温服，三剂而愈。"}, {"source": "条128｜《竹亭医案》卷四", "原文": "海盐上舍张铁珊由怔忡症兼脐上胀痛，肝胃气阻，宜先治标之验。上舍张铁珊，道光元年六月十四。病原：气出于中焦而行于遍体，贯注百脉，往来不息。近缘怔忡时发，心荣不足，胃土失养，肺气因而不充，肝木乘之。以故三日间，每至四鼓气由脐而上达于胸，并紧不舒，且胀且疼，必得手捺重按而后渐散。种种情事，合之脉象之浮而不沉，似与病象不符。惟唯两关细小兼弦，又未尝不关乎肝胃，而其源实由于心荣之不足，中气之有亏也。《经》云", "白话": "海盐上舍张铁珊，由怔忡兼脐上胀痛、肝胃气阻，宜先治标之验案。上舍张铁珊，道光元年六月十四诊。病原：气出于中焦而行于全身，贯注百脉，往来不息。近因怔忡时发，心营不足，胃土失养，肺气因而不充，肝木乘之。所以三天来每到四更（凌晨），气由脐上冲达于胸，紧束不舒，且胀且痛，必得手按重压才渐渐散去。种种情事，合之脉象浮而不沉，似与病象不符；只是两关细小兼弦，又未尝不关乎肝胃，而其根源实由心营不足、中气亏虚。《经》云「缓治其本，急治其标」，宜先治其标，再作探本穷源之法。方：盐水炒香附二钱、"}, {"source": "条129｜《竹亭医案》卷四", "原文": "鲍氏价人怔忡治验。鲍氏价者，怔忡有年，心荡无时。迩来胸膺气筑，不食少缓，食稍增则肚脐收缩吊紧，背曲，两乳下有似筋抽难状之势。头眩足浮，脉象细小。进后方六帖，心荡大减，食后脐腹之收缩顿平，背曲、头眩俱缓。方附下：\n丹参四钱 茯神二钱 远志一钱，去心炒 沉香五分 柏子仁三钱 归身一钱半 木瓜一钱半 元参三钱\n加白檀香一钱五分同煎。\n复诊：仍以原方加西党参二钱，煎服数剂而痊。", "白话": "鲍氏价人怔忡治验。鲍氏价者怔忡多年，心荡无时。近来胸膺气筑（攻撑），不食稍缓，进食稍多则肚脐收缩吊紧、背曲，两乳下似有筋抽，难以名状；头眩、足浮，脉象细小。进下方六帖，心荡大减，食后脐腹收缩顿平，背曲、头眩俱缓。方：丹参四钱、茯神二钱、远志一钱（去心炒）、沉香五分、柏子仁三钱、当归身一钱半、木瓜一钱半、元参三钱，加白檀香一钱五分同煎。复诊：仍以原方加西党参二钱，煎服数剂而痊。"}, {"source": "条130｜《剑慧草堂医案》卷中", "原文": "惊怖动心，心悸目直，脉迟弦。是心肝神魂不藏，防成怔忡。\n饭蒸菖蒲 紫丹参猪心血拌 礞石 远志 桑叶 郁金 牡蛎 杏仁 酸枣仁 柏子仁 胆星 茯神 白芍 枳壳 龙骨 知母\n品珠诊：血虚木旺，心肾失交，头眩心悸，瘛疭怵惕，症属怔忡。怡养为宜。\n紫丹参猪心血拌 茯神 柏子仁 半夏 胆星 牡蛎 鸡血藤 饭蒸菖蒲 远志 酸枣仁 秫米 石决 龙齿 夜交藤\n又初诊：无痰不作眩，眩旋心悸，脉濡弦。以桑麻温胆汤。\n", "白话": "（初诊）惊怖动心，心悸目直，脉迟弦。是心肝神魂不藏，防成怔忡。方：饭蒸菖蒲、紫丹参（猪心血拌）、礞石、远志、桑叶、郁金、牡蛎、杏仁、酸枣仁、柏子仁、胆星、茯神、白芍、枳壳、龙骨、知母。（品珠诊）血虚木旺，心肾失交，头眩心悸、瘛疭怵惕，证属怔忡。怡养为宜。方：紫丹参（猪心血拌）、茯神、柏子仁、半夏、胆星、牡蛎、鸡血藤、饭蒸菖蒲、远志、酸枣仁、秫米、石决明、龙齿、夜交藤。（又初诊）「无痰不作眩」，眩晕心悸，脉濡弦。用桑麻温胆汤：桑叶、半夏、胆星、饭蒸菖蒲、远志、牡蛎、枳实、天麻、"}, {"source": "条131｜《剑慧草堂医案》卷下", "原文": "惊怖动心，心悸眩旋，得食则胀，脘痛彻背，脉左弦。是心肝之阳偏亢也，切宜怡养。\n紫栙丹参猪心血拌 茯神 桑叶 珍珠母 牡蛎 香附 白芍 熟枣仁 远志 滁菊 青陈皮 龙齿 川郁金 菟丝 吴萸川连拌", "白话": "惊怖动心，心悸眩晕，得食则胀，胃脘痛彻背，脉左弦。是心肝之阳偏亢，切宜怡养。方：紫丹参（猪心血拌）、茯神、桑叶、珍珠母、牡蛎、香附、白芍、熟酸枣仁、远志、滁菊、青陈皮、龙齿、川郁金、菟丝（子）、吴茱萸（川连拌）。"}, {"source": "条132｜《剑慧草堂医案》卷下", "原文": "血不养肝，气火风阳上僭，以致眩旋心悸，脘满辄胀，舌糙，脉右弦。当养血润肝，兼和营卫。\n银胡 当归 熟枣仁川连拌 远志甘草水浸 香附四制 广木香 合欢 白芍 桑叶 紫丹参 茯神 砂仁 川郁金 川斛", "白话": "血不养肝，气火风阳上僭，以致眩晕心悸，脘满易胀，舌糙，脉右弦。当养血润肝、兼和营卫。方：银柴胡、当归、熟酸枣仁（川连拌）、远志（甘草水浸）、香附（四制）、广木香、合欢（皮）、白芍、桑叶、紫丹参、茯神、砂仁、川郁金、川石斛。"}, {"source": "条133｜《孤鹤医案·痰》", "原文": "痰火内忧，心悸不宁。治以清热疏郁，佐以涤痰。\n川连五分 辰砂拌麦冬二钱 炒枣仁三钱 茯神三钱 橘红一钱 半夏一钱半 孔石菖蒲一钱 炒枳实一钱 郁金一钱\n加九孔石决明五钱。", "白话": "痰火内扰，心悸不宁。治以清热疏郁、佐以涤痰。方：川连五分、辰砂拌麦冬二钱、炒酸枣仁三钱、茯神三钱、橘红一钱、半夏一钱半、孔石菖蒲一钱、炒枳实一钱、郁金一钱，加九孔石决明五钱。"}, {"source": "条134｜《孤鹤医案·杂证案例》", "原文": "营亏火升。营液内亏，肝脾失养，木火上升，心跳时眩，筋脉不舒，脉数略弦。拟用柔剂。\n潞党参三钱 炒丹皮二钱 炒黑归身二钱 炒杜仲二钱 焦白芍一钱半 化入阿胶二钱 炒枣仁三钱 新会皮一钱 炒远志八分 黑山栀一钱半 茯神三钱", "白话": "营亏火升。营液内亏，肝脾失养，木火上升，心跳时眩，筋脉不舒，脉数略弦。拟用柔剂（柔润滋阴）。方：潞党参三钱、炒丹皮二钱、炒黑归身二钱、炒杜仲二钱、焦白芍一钱半、阿胶（化入）二钱、炒酸枣仁三钱、新会皮一钱、炒远志八分、黑山栀一钱半、茯神三钱。"}, {"source": "条135｜《江泽之医案·痰饮》", "原文": "水饮凌心则心悸，蔓延阳明则虚里穴动。胆热则怯甚，入经络则筋惕肉瞤。善怯多疑，善虑多思，皆胆虚痰多之幻境也。前经调治，渐次向愈，水到渠成，勿过虑也。\n茯苓神 於术散 石决明 夜合花 瓜蒌霜 防己 络石藤 粉丹皮 半夏曲 秫秫米 橘皮、络 首乌藤 鲜竹茹", "白话": "水饮凌心则心悸，蔓延阳明则虚里穴动；胆热则恐惧更甚，入经络则筋惕肉瞤。善怯多疑、善虑多思，都是胆虚痰多的幻境。前经调治，已渐次向愈，水到渠成，不必过虑。方：茯苓、茯神、於术、石决明、夜合花、瓜蒌霜、防己、络石藤、粉丹皮、半夏曲、秫米、橘皮络、首乌藤、鲜竹茹。"}, {"source": "条136｜《江泽之医案·症》", "原文": "操劳郁怒，肝叶迫肺膈，震动心君，致成怔忡。拟镇肝养营为治，戒怒安闲为要。\n白芍 牡蛎 丹参 酸枣仁 朱茯神 木瓜 远志 归身 柏子霜 桂圆肉\n复诊：加冬术一两四钱、生地、西洋参\n同前为末，桂圆肉杵膏和蜜成丸。", "白话": "操劳郁怒，肝气（肝叶）迫肺膈，震动心君，致成怔忡。拟镇肝养营为治，戒怒安闲为要。方：白芍、牡蛎、丹参、酸枣仁、朱茯神、木瓜、远志、当归身、柏子霜、桂圆肉。复诊：加冬术一两四钱、生地、西洋参；同前为末，桂圆肉杵膏和蜜成丸。"}, {"source": "条137｜《王仲奇医案·正文》", "原文": "潘，爱多亚路。脉来弦搏刚劲，左寸滑而濡，右尤粗大，心悸不得卧，咳出之物非血非痰，有如肺体，心肺之伤久矣。惟唯近来益甚，气逆不舒，少腹作痛，面黄暗不泽，舌黄白而腻，肠胃又连带为病，难以图治。\n法半夏一钱五分 丝瓜络带子，三钱 炙远志一钱 光杏仁三钱 生苡仁三钱 旋覆花一钱五分 赖橘红一钱 御米壳一钱五分 白茯苓三钱 预知子三钱 伽楠香一分，锉研细末，冲", "白话": "潘某（爱多亚路），脉来弦搏刚劲，左寸滑而濡、右手更粗大；心悸不得卧，咳出之物非血非痰、有如肺体（组织状物）——心肺受伤已久。只是近来更重：气逆不舒，少腹作痛，面黄暗不泽，舌黄白而腻，肠胃又连带为病，难以图治。方：法半夏一钱五分、丝瓜络（带子）三钱、炙远志一钱、光杏仁三钱、生苡仁三钱、旋覆花一钱五分、赖橘红一钱、御米壳一钱五分、白茯苓三钱、预知子三钱、伽楠香一分（锉研细末冲）。"}, {"source": "条138｜《曹沧洲医案·风温湿热》", "原文": "某右，向病风湿骨痛，至今不净，胸闷，心悸，寐不安，脉细数。宜宽中宁神，宣通经脉为法。\n瓜蒌皮四钱 朱茯神一钱五分 竹茹三钱 川石斛四钱 枳壳三钱 北秫米四钱 紫贝齿生杵，一两 朱连翘三钱 广郁金三钱五分 盐半夏三钱 首乌藤三钱 陈佛手三钱五分", "白话": "某女，素患风湿骨痛至今未净，胸闷、心悸、睡眠不安，脉细数。宜宽中宁神、宣通经脉为法。方：瓜蒌皮四钱、朱茯神一钱五分、竹茹三钱、川石斛四钱、枳壳三钱、北秫米四钱、紫贝齿（生杵）一两、朱连翘三钱、广郁金三钱五分、盐半夏三钱、首乌藤三钱、陈佛手三钱五分。"}, {"source": "条139｜《曹沧洲医案·肝脾门》", "原文": "某右，心悸不得寐，腰痛，胃纳式微，脉软弦。本虚为病，须逐渐调养。\n上川连四分，盐水炒 首乌藤三钱 杜仲三钱 川断一两三钱一两 沙苑子二三二钱，三三味咪盐水同炒 ？川石斛三钱 全瓜蒌五钱，切 炒香枣仁三钱 石决明一两生，先煎 盐半夏三钱 抱木茯神五钱，朱米朱拌 竹茹二钱 鲜稻叶三钱", "白话": "某女，心悸不得寐，腰痛，胃纳甚少，脉软弦。本虚为病，须逐渐调养。方：上川连四分（盐水炒）、首乌藤三钱、杜仲三钱、川断、沙苑子（三味盐水同炒）、川石斛三钱、全瓜蒌五钱（切）、炒香酸枣仁三钱、石决明一两（生，先煎）、盐半夏三钱、抱木茯神五钱（朱拌）、竹茹二钱、鲜稻叶三钱。（原文「川断一两三钱一两」「沙苑子二三二钱，三三味咪盐水同炒」字数残缺疑误，照录待核。）"}, {"source": "条140｜《费绳甫医案》", "原文": "崇明钱仰翁，心悸气急，内热头眩，肾阴久虚，水不涵木。肝阳升腾无制，销灼胃阴，心营宣布无权，脉来细弦而数。治宜益肾清肝，养心和胃。\n冬青子四钱 柏子仁三钱 北沙参四钱 大白芍一钱五分 云茯神二钱 钩藤钩一钱五分 生甘草五分 象贝母三钱 瓜蒌皮二钱 生熟谷芽各四钱 肥知母一钱 生杜仲三钱 内金炙，三钱 川石斛二钱 灯心二尺", "白话": "崇明钱仰翁，心悸气急、内热头眩。肾阴久虚、水不涵木，肝阳升腾无制，销灼胃阴，心营宣布无权；脉来细弦而数。治宜益肾清肝、养心和胃。方：冬青子（女贞子）四钱、柏子仁三钱、北沙参四钱、大白芍一钱五分、云茯神二钱、钩藤钩一钱五分、生甘草五分、象贝母三钱、瓜蒌皮二钱、生熟谷芽各四钱、肥知母一钱、生杜仲三钱、炙内金三钱、川石斛二钱、灯心二尺。"}, {"source": "条141｜《费绳甫医案》", "原文": "广东李茂堂，心悸不寐，右足趾作痛，牵引足跗，鼻塞涕多此中虚血亏，湿痰入络而兼感冒也。须补散兼行，化痰通络，方合法度。\n吉林参须五分 嫩苏梗一钱 陈广皮一钱 制半夏一钱五分 象贝母三钱 苡仁四钱 左秦艽一钱 杏仁三钱 瓜蒌三钱 地肤子三钱 五加皮二钱 甜瓜子三钱 北秫米三钱 嫩桑枝二钱\n连进三剂，鼻通涕少，右足趾作痛已止，夜寐亦酣。外邪清而湿痰化，足筋自舒。\n别直参一钱 全当归二钱 陈广皮一钱 制半", "白话": "广东李茂堂，心悸不寐，右足趾作痛牵引足背，鼻塞涕多。此中虚血亏、湿痰入络而兼感冒也。须补散兼行、化痰通络，方合法度。初方：吉林参须五分、嫩苏梗一钱、陈广皮一钱、制半夏一钱五分、象贝母三钱、苡仁四钱、左秦艽一钱、杏仁三钱、瓜蒌三钱、地肤子三钱、五加皮二钱、甜瓜子三钱、北秫米三钱、嫩桑枝二钱。连进三剂，鼻通涕少，右足趾作痛已止，夜寐亦酣——外邪清而湿痰化，足筋自舒。后方：别直参一钱、全当归二钱、陈广皮一钱、制半夏一钱五分、象贝母三钱、柏子仁二钱、云茯神二钱、北秫米三钱、龙眼肉五枚"}, {"source": "条142｜《费绳甫医案》", "原文": "广东姚仁峰，心悸不寐，肢麻怯冷，食入作吐。余诊其脉，左弦右缓，中气久虚，湿痰阻胃。\n高丽参一钱 茯神二钱 白术一钱 当归二钱 枣仁一钱五分 远志八分 广皮一钱 半夏一钱五分 茅术一钱 木香五分 砂仁一钱 姜炮，八分 龙眼肉三枚   连服10十剂而愈。", "白话": "广东姚仁峰，心悸不寐，肢麻怯冷，食入作吐。我诊其脉左弦右缓，是中气久虚、湿痰阻胃。方：高丽参一钱、茯神二钱、白术一钱、当归二钱、酸枣仁一钱五分、远志八分、广皮一钱、半夏一钱五分、茅术一钱、木香五分、砂仁一钱、炮姜八分、龙眼肉三枚。连服十剂而愈。"}, {"source": "条143｜《陈莲舫医案》卷下", "原文": "心阴不足，肝阳有余，两耳发鸣，头蒙肢麻，多梦少寐，心悸肉瞤，证属怔忡。脉偏弦细，右滑。从中积痰蓄饮，拟以镇养。\n洋参 木神 胆星 潼、白蒺藜 半夏 贝齿 夜交藤 丹参 秫米 珠母粉 白芍 新会 玫瑰露玫炒竹茹", "白话": "心阴不足、肝阳有余，两耳鸣响、头蒙肢麻、多梦少寐、心悸肉瞤，证属怔忡。脉偏弦细、右滑，中焦积痰蓄饮。拟以镇养。方：洋参、茯神（「木神」）、胆星、潼白蒺藜、半夏、贝齿、夜交藤、丹参、秫米、珍珠母粉、白芍、新会皮、玫瑰露炒竹茹。"}, {"source": "条144｜《陈莲舫医案》卷下", "原文": "左，彻夜不寐，将成怔忡，属操劳过度，肝阳内扰，以致神不守舍，痰热内蒙。脉见细弦，拟以镇养。\n洋参 木神 胆星 丹参 半夏 远志 柏子仁 白芍 秫米 龙齿 夜交藤 会皮 龙眼肉 竹茹", "白话": "某（男），彻夜不寐，将成怔忡。属操劳过度、肝阳内扰，以致神不守舍、痰热内蒙。脉见细弦，拟以镇养。方：洋参、茯神（「木神」）、胆星、丹参、半夏、远志、柏子仁、白芍、秫米、龙齿、夜交藤、陈皮（「会皮」）、龙眼肉、竹茹。"}, {"source": "条145｜《顾氏医案·肝火、肝风门》", "原文": "恍惚惊悸，眩晕怔忡，脉芤涩，形疲，色不华。皆由心阴过亏，暗吸肾真，水不涵木，则无风而自动矣。\n熟地 白芍 淮麦 茯神 山药 甘草 南枣 牡蛎", "白话": "恍惚惊悸、眩晕怔忡，脉芤涩，形体消瘦、面色无华。皆由心阴过亏，暗吸肾中真阴，水不涵木，则无风而自动（内风自起）。方：熟地、白芍、淮小麦、茯神、山药、甘草、南枣、牡蛎。"}, {"source": "条146｜《经方实验录》第一集中卷", "原文": "姚建，律师，现住小西门外大兴街，尝来请诊，眠食无恙，按其脉结代，约十余至一停，或二三十至一停不等，又以事繁，心常跳跃不宁，此仲师所谓‘心动悸，脉结代，炙甘草汤主之’之证是也，因书经方与之，服十余剂而瘥。\n甘草炙，四钱 生姜三钱 桂枝三钱 潞党参二钱 生地一两 真阿胶二钱 麦冬烊冲，四钱 麻仁四钱 大枣四枚", "白话": "姚建，律师，现住小西门外大兴街，曾来请诊。睡眠饮食都无恙，按其脉结代——约十余至一停、或二三十至一停不等；又因事务繁忙，心常跳跃不宁。这正是仲景所谓「心动悸、脉结代，炙甘草汤主之」之证，于是书经方给他，服十余剂而愈。方：炙甘草四钱、生姜三钱、桂枝三钱、潞党参二钱、生地一两、真阿胶二钱、麦冬（烊冲）四钱、麻仁四钱、大枣四枚。"}, {"source": "条147｜《经方实验录》第一集中卷", "原文": "唐左，初诊：脉结代，心动悸，炙甘草汤主之，此仲景先师之法，不可更变者也。\n甘草炙，四钱 川桂枝三钱 潞党参三钱 阿胶珠二钱 大麻仁一两 大麦冬八钱 大生地一两 生姜五片 红枣十枚\n二诊：二进炙甘草汤，胃纳较增，惟唯口中燥而气短，左脉结代渐减，右脉尚未尽和，仍宜前法加减，加制军者，因大便少也。\n甘草炙，五钱 川桂枝四钱 潞党参五钱 阿胶珠二钱 大熟地一两 大麻仁一两 麦冬四钱 紫苏叶五钱 天花粉一两", "白话": "唐某（男）。初诊：脉结代、心动悸，用炙甘草汤主之——这是仲景先师之法，不可更改。方：炙甘草四钱、川桂枝三钱、潞党参三钱、阿胶珠二钱、大麻仁一两、大麦冬八钱、大生地一两、生姜五片、红枣十枚。二诊：二进炙甘草汤，胃纳较增，只是口中燥而气短；左脉结代渐减、右脉尚未尽和。仍宜前法加减——加制军（大黄）是因大便少。方：炙甘草五钱、川桂枝四钱、潞党参五钱、阿胶珠二钱、大熟地一两、大麻仁一两、麦冬四钱、紫苏叶五钱、天花粉一两、生姜三片、红枣七枚、制军三钱。"}, {"source": "条1｜《灵枢·经脉》", "原文": "闻木声则惕然而惊，心欲动……为此诸病，盛则泻之，虚则补之，热则疾之，寒则留之，陷下则灸之，不盛不虚以经取之。", "白话": "听到木的声响就警惕而惊恐，心中悸动不安……（经气厥逆）出现这些病证时：邪气盛的就用泻法，正气虚的就用补法，属热的就用疾刺法，属寒的就用留针法，脉气陷下的就用灸法，不盛不虚的就从本经取穴治疗。"}, {"source": "条2｜《难经·十四难》", "原文": "损其心者，调其荣卫。", "白话": "心受损伤的（病证），要调和它的营卫。"}, {"source": "条3｜《圣济总录》卷五十六", "原文": "论曰:：九种心痛，曰虫，曰注，曰风，曰悸，曰食，曰饮，曰冷，曰热，曰去来者是也，治病必求其本。今九种心痛，其名虽异而治疗各有其法，盖正气和调则邪不能入，若或虚弱，外邪乘之，则种种皆能致疾，善医者惟唯明攻邪以扶正，则九种之痛，其治一也。", "白话": "论述说：九种心痛——虫、注、风、悸、食、饮、冷、热、去来心痛——治疗疾病必推求其根本。现在九种心痛，名称虽然不同，而治疗各有相应的方法；正气和调，邪气就不能入侵；如果正气虚弱，外邪乘虚侵入，那么种种因素都能导致疾病。善于医道的人，只要明于攻邪以扶正，那么九种心痛的治疗法则是一致的。"}, {"source": "条4｜《医学启源》卷上", "原文": "初之气为病，多发咳嗽，风痰、风厥，涎潮痹塞，口喎、半身不遂，失音，风癫、风中妇人、胃中留饮，脐腹微痛、呕逆恶心、旋运，惊悸，阳狂心风，搐搦、颤掉。初之气，依《内经》在上者宜吐，在下者宜下。", "白话": "初之气为病，多发咳嗽，风痰、风厥，涎液上涌、痹塞不通，口眼歪斜、半身不遂，失音，风癫、风邪中于妇人，胃中留饮，脐腹轻微疼痛、呕逆恶心、眩晕，惊悸，阳狂、心风，抽搐、震颤动摇。初之气为病，依照《内经》的原则：病在上的宜用吐法，病在下的宜用下法。"}, {"source": "条5｜《内经》（据《医学启源》卷上转引）", "原文": "在上者宜吐，在下者宜下。", "白话": "病在上的可用吐法，病在下的可用下法。"}, {"source": "条6｜《严氏济生方》", "原文": "方其虚也，虚则生寒，寒则血脉虚少，时多恐畏，情绪不乐，心暴痛，时唾清涎，心膈胀闷，好忘多惊，梦寐飞扬，精神离散，其脉浮而虚者，是虚寒之候也……治之之法，热则清之，寒则温之，又当审其所自焉。", "白话": "当它虚的时候，虚就生寒，寒就血脉虚少，时时多恐惧畏怯，情绪不乐，心部猝痛，时时吐清稀涎沫，心胸膈间胀闷，善忘多惊，梦中魂梦飞扬，精神离散；脉浮而虚的，就是虚寒的证候……治疗的方法：有热就清，有寒就温，还应当审察病因从何而来。"}, {"source": "条7｜《世医得效方》卷十一", "原文": "至于惊、疳、积、热四证，惊者虚惕怔忪，气怯神散，痰涎来去，其泻必青，积渐生风，其证有冷热虚实。冷则燥之，虚则温之，实则利之，热则凉之，是为活法。", "白话": "至于惊、疳、积、热四种病证——惊证是虚怯惕然、怔忪不安，气怯神散，痰涎往来，泻下之物必色青；积滞渐久生风，其证有冷热虚实之分。冷的就用燥法，虚的就用温法，实的就用利法，热的就用凉法，这就是圆机活法。"}, {"source": "条8｜《医学原理》", "原文": "盖心无血养，如鱼失水，惕然而跳跃也。时作时止者，以痰因火动，瘦人多是血虚，肥人多是痰饮，法宜先养心血，理其脾土，亦当幽闲安乐，制其忧虑，远其七情六淫则自安矣。", "白话": "心没有血来奉养，就像鱼失去水，惕然而跳动。时发时止的，是痰因火而动；瘦人多属血虚，肥人多属痰饮。治法宜先养心血、理其脾土；又当处于幽静安乐的环境，节制忧虑，远离七情六淫，就自然安和了。"}, {"source": "条9｜《辨证奇闻》卷四", "原文": "若怔忡，正悸之渐也；若悸，非惊之渐也。故惊悸宜知轻重。一遇怔忡，宜防惊，惊宜防悸。然虽分轻重，治虚则一。", "白话": "如果是怔忡，正是心悸渐进（加重）的结果；如果是悸，并不是惊的渐进。所以惊与悸应当知道轻重。一遇怔忡，应当防其转为惊；惊，应当防其转为悸。然而虽然分轻重，治疗虚证的法则是一致的。"}, {"source": "条10｜《史载之方》卷上", "原文": "产后心虚中风，心中战栗，惊动不安，如人将捕，大府伤冷，六脉微而肝心脉偏细沉，又产后只缘肾气之虚寒，风邪所中，肾脉细而搏以沉，肾既受病传其所胜，心感肾邪非时惊悸，如人将捕，初以益心气去风邪药治之，次当补其肾，又次当益其肝，足其血，缘心受肾邪，而又肝气微弱，不能生其心气，故以三方药治之。", "白话": "产后心虚而被风邪所中，心中战栗，惊动不安，好像有人要抓捕自己，大腑伤于寒冷，六部脉微而肝、心脉偏于细沉；又有产后只因肾气虚寒，被风邪所中，肾脉细而搏指、沉伏。肾受病后传其所胜（心），心感肾邪，不拘时惊悸，好像有人要抓捕自己。初期用益心气、去风邪的药治疗，其次当补肾，再次当补肝、充足其血——因为心受肾邪，而肝气微弱、不能生其心气，所以分三个阶段用药治疗。"}, {"source": "条11｜《校注妇人良方》卷十九", "原文": "产后心神惊悸恐惧，或目睛不转，口不能言，乃心气虚而六淫内侵。诊其脉动而弱者，惊悸也。动则为惊，弱则为悸矣。愚按：人之所主者心，心之所主者血。心血一虚，神气不守，此惊悸所由作也，当补血气为主。", "白话": "产后心神惊悸恐惧，或眼珠不能转动，口不能言语，这是心气虚而六淫之邪内侵。诊其脉见动而弱的，就是惊悸——脉动的是惊，脉弱的是悸。我按：人身的主宰是心，心所主宰的是血。心血一旦亏虚，神气不能守藏，这就是惊悸发生的原因，治疗当以补益气血为主。"}, {"source": "条12｜《金镜内台方议》卷九", "原文": "心中悸动，因脉结代，故知为真阴气虚少，阴气虚败。故与炙甘草为君，人参、大枣为臣，以补无气之不足者。以桂枝、生姜之辛，而益正气为佐。以麦门冬、阿胶、麻子仁、地黄之甘，润经益血，而补其阴为使。以清酒为引而能通，以复脉者也。", "白话": "心中悸动，因脉见结代，所以知道是真阴之气虚少、阴气虚败。故用炙甘草为君药，人参、大枣为臣药，以补元气之不足；用桂枝、生姜之辛味，以益正气为佐药；用麦门冬、阿胶、麻子仁、地黄之甘味，润经脉、益血液而补其阴为使药；用清酒为引经药而能通达，以恢复脉搏。"}, {"source": "条13｜《医方选要》卷七", "原文": "夫怔忡也，健忘也，动悸也，三者名虽不同，未有不由心血不足，脾气虚弱，积饮停痰而成也。治之唯在补养心血，调和脾气，宁其神，化其痰，使神气充满，心安气舒，则无三者之患也。", "白话": "怔忡、健忘、动悸三者名称虽然不同，没有不是由心血不足、脾气虚弱、积饮停痰所形成的。治疗只在补养心血、调和脾气、安宁心神、化其痰饮，使神气充满，心安气舒，就没有这三者的疾患。"}, {"source": "条14｜《濒湖脉学》", "原文": "脉虚身热为伤暑，自汗怔忡惊悸多。发热阴虚须早治，养营益气莫蹉跎。", "白话": "脉虚而身热是伤暑，自汗、怔忡、惊悸多见。发热属阴虚的须及早治疗，养营益气，不要迟疑误时。"}, {"source": "条15｜《证治准绳·杂病》", "原文": "因惊恐得疾，心下怔忡者，见惊悸门。脉滑者，多血少气。涩者，少血多气。大者，血气俱多。小者，血气俱少。下手脉沉，便知是气。其或沉滑，气兼痰饮。脉弦软，或虚大，虚滑微弱，饮食不节，劳伤过度，精神倦怠，四肢困乏，法当补益。补中益气汤、调中益气汤、十全大补汤。夏月清暑益气汤、四君、四物之类加减。", "白话": "因惊恐而得病、心下怔忡的，详见惊悸门。脉滑的，多血少气；涩的，少血多气；大的，血气俱多；小的，血气俱少。手按脉沉，便知是气病；若见沉滑，是气兼痰饮。脉弦软，或虚大、虚滑微弱，加上饮食不节、劳伤过度，精神倦怠、四肢困乏的，治法当用补益——补中益气汤、调中益气汤、十全大补汤；夏季用清暑益气汤、四君子汤、四物汤之类加减。"}, {"source": "条16｜《痰火点雪》卷三", "原文": "脉虚身热，主伤暑自汗，怔忡惊悸，阴虚发热，法当养营益卫。”；“弱脉主阴气虚，阳气衰，恶寒发热，筋骨痿软，多惊多汗，精神减少，法当益气调营。", "白话": "（其一）脉虚而身热，主伤暑自汗、怔忡惊悸、阴虚发热，治法当养营益卫。（其二）弱脉主阴气虚、阳气衰，恶寒发热，筋骨痿软无力，多惊多汗，精神减少，治法当益气调营。"}, {"source": "条17｜《理虚元鉴》卷上", "原文": "治之原不相离，故于滑精、梦泄种种精病者，必本于神治；于怔忡、惊悸种种神病者，必本于气治。盖安神必益其气，益气必补其精。", "白话": "治疗的本原是不能分离的：对于滑精、梦泄等种种精病，必须从神入手治疗；对于怔忡、惊悸等种种神病，必须从气入手治疗。因为安神必须补益其气，益气必须补其精。"}, {"source": "条18｜《医宗说约》卷二", "原文": "健忘、惊悸怔忡、虚烦不寤俱属少阴，故多用安神养心之品。然须察其所挟夹，挟夹水者，合四苓；挟夹痰者，合二陈。", "白话": "健忘、惊悸怔忡、虚烦不寐都属于少阴（心肾），所以多用安神养心的药。但必须审察其所兼夹：兼夹水饮的，合入四苓散；兼夹痰的，合入二陈汤。"}, {"source": "条19｜《证治百问》", "原文": "盖怔忡者，心中如有物撞，谓之忡，忡者，忡逆之谓。忽然跳跃，谓之怔，怔者，振动之谓。本心气虚而三焦之火冲于包络，包络不和而心忡。若心神自虚，包络无血以养，致心体躁而忽然跳跃，而心怔，须调补气血为主，清火安神之药佐之。其脉左寸、右尺数而不敛可征。", "白话": "怔忡是心中好像有物撞击，这叫做“忡”——忡是冲逆的意思；忽然跳动叫做“怔”——怔是振动的意思。根本在于心气虚而三焦之火上冲于心包络，包络不和而发心忡；若心神自虚，包络无血奉养，以致心体躁扰而忽然跳跃，则发心怔。必须以调补气血为主，用清火安神的药佐之；其脉左寸、右尺数而无力不敛，可以验证。"}, {"source": "条20｜《女科经纶》卷六", "原文": "薛立斋曰：产后恍惚证，当大补血气为主，佐后方为善。盖风为虚极之假象，固其本元，诸病自退，若专治其风，则速其危矣。慎斋按：以上四条，序产后有惊悸恍惚之证也。", "白话": "薛立斋说：产后恍惚证，当以大补气血为主，佐以后列方剂为好。因为“风”象是虚极的假象；固护本元，各种病自然消退；若专一治风，就会加速危险。慎斋按：以上四条，是依次论述产后有惊悸恍惚之证。"}, {"source": "条21｜《辨证录》卷四", "原文": "人有得怔忡之证者，一遇怫情之事，或听逆耳之言，便觉心气怦怦上冲，有不能自主之势，似烦而非烦，似晕而非晕，人以为心虚之故也。然而心虚由于肝虚，肝虚则肺金必旺，以心弱不能制肺也；肺无火煅炼，则金必制木，肝不能生心，而心气益困。故补心必须补肝，而补肝尤宜制肺。然而肺不可制也，肺乃娇脏，用寒凉以制肺，必致伤损脾胃，肺虽制矣，而脾胃受寒，不能运化水谷，则肝又何所取资，而肾又何能滋益？?所以肺不宜制而宜养也。", "白话": "有人患怔忡证，一遇不顺心的事，或听到逆耳的话，便觉心气怦怦上冲，有不能自主之势，像烦躁而又不是烦躁，像眩晕而又不是眩晕；人们以为是心虚的缘故。然而心虚是由于肝虚，肝虚则肺金必旺，因为心弱不能制约肺；肺没有火来煅炼，金就必制约木，肝不能生心，心气就愈发困顿。所以补心必须补肝，而补肝尤其应当制约肺。然而肺是不可直接抑制的——肺为娇脏，用寒凉来抑制肺，必然损伤脾胃；肺虽被抑制了，而脾胃受寒、不能运化水谷，那么肝又从哪里取资，肾又怎能得到滋益？所以肺不宜抑制而宜调养。方用制忡汤治疗。"}, {"source": "条22｜《妇人大全良方》", "原文": "妇人热劳由心肺壅热，伤于气血，以致心神烦躁，眼赤头疼，眼涩唇干，口舌生疮，神思昏倦，四肢壮热，饮食无味，肢体酸疼，心忪盗汗，肌肤日瘦，或寒热往来。当审所因，调补气血，其病自愈矣（(是言实火，非同劳热之火可补）)。", "白话": "妇人热劳，是因心肺壅热，损伤气血，以致心神烦躁，眼睛红赤、头疼，眼涩唇干，口舌生疮，神思昏倦，四肢大热，饮食无味，肢体酸疼，心悸盗汗，肌肤日渐消瘦，或寒热往来。当审察病因，调补气血，病就自然痊愈（按：这是说实火，与劳热之虚火可补者不同）。"}, {"source": "条23｜《增订通俗伤寒论》", "原文": "心动而悸，脉见结代，舌淡红而干光，血枯气怯者宜双补，复脉汤加减。", "白话": "心中动悸，脉见结代，舌淡红而干而光莹，属血枯气怯的，宜用气血双补法，用复脉汤加减。"}, {"source": "条24｜《严氏济生方》", "原文": "夫怔忡者，此心血不足也。盖心主于血，血乃心之主，心乃形之君，血富则心君自安矣。多因汲汲富贵，戚戚贫贱，又思所爱，触事不意，真血虚耗，心帝失辅，渐成怔忡。怔忡不已，变生诸证，舌强恍惚，善忧悲，少颜色，皆心病之候。《难经》云：损其心者，益其荣，法当专补真血，真血若富，心帝有辅，无不愈者矣。", "白话": "怔忡是心血不足。心主血，血是心的主宰，心是形体的君主；血充盛，心君自然安宁。多因急切追求富贵、忧愁贫贱，又思念所爱之人，行事不如意，真血虚耗，心帝失去辅佐，逐渐形成怔忡。怔忡不止，变生各种证候：舌强、精神恍惚、容易忧悲、面色少华——这都是心病的征候。《难经》说：心受损伤的，当补益其营血，治法当专补真血；真血若充盛，心帝有辅佐，没有不痊愈的。"}, {"source": "条25｜《难经》（据《严氏济生方》转引）", "原文": "损其心者，益其荣，法当专补真血", "白话": "心受损伤的，当补益其营血，治法当专补真血。"}, {"source": "条26｜《奇效良方》卷四十六", "原文": "《难经》云：损其心者益其荣，法当专补真血。血若富，心主有辅，无不愈者。又有风寒暑湿，闭塞诸经，令人怔忡。又有七情过伤，加以协饮所致，遂成五饮停蓄，堙塞中脘，亦令人怔忡。当随其证，施以治法。……然治之法，必须养其心血，理其脾土，凝神定志之剂以调理。亦当以幽闲之处，安乐之中，使其绝于忧虑，远其六淫七情，如此日渐安矣。", "白话": "《难经》说：心受损伤的当补益营血，治法当专补真血；血若充盛，心主有了辅佐，没有不痊愈的。又有风寒暑湿闭塞诸经，使人怔忡；又有七情过度所伤、加上挟饮所致，于是形成五饮停蓄，堵塞中脘，也使人怔忡。当随其证施以治法……然而治疗的方法，必须养其心血、理其脾土，用凝神定志的方剂来调理；又当处于幽静之处、安乐之中，使其断绝忧虑，远离六淫七情，这样就会日渐安好。"}, {"source": "条27｜《难经》（据《奇效良方》卷四十六转引）", "原文": "损其心者益其荣，法当专补真血。", "白话": "心受损伤的，当补益其营血，治法当专补真血。"}, {"source": "条28｜《赤水玄珠》卷六", "原文": "治怔忡之法，惟唯当益其心血，壮其神气。治惊悸则有诸经之证，当分别治之。", "白话": "治疗怔忡的方法，只当补益心血、壮其神气；治疗惊悸则有各经的证候，应当分别治疗。"}, {"source": "条29｜《医林绳墨·惊悸篇》", "原文": "如心血虚少而发惊悸者，治宜猪心血丸。", "白话": "如果心血虚少而发为惊悸的，治疗宜用猪心血丸。"}, {"source": "条30｜《医林绳墨·怔忡篇》", "原文": "怔则心胸之气左右攻击，聚而不散，搐动中焦，如将征战者也，致令心有所动，郁烦躁扰，懊侬不宁，坐卧难安，甚则恶心呕哕，欲吐不吐之状。治当安心养血、清痰理气之剂，如二陈汤加归、术、人参、姜汁、炒山栀。久病去半。", "白话": "“怔”是心胸之气左右攻冲，聚而不散，牵动中焦，如同将要征战的样子，致使心中跳动，郁烦躁扰，懊憹不宁，坐卧难安；甚至恶心呕哕，想吐又吐不出的样子。治疗当用安心养血、清痰理气的方剂，如二陈汤加当归、白术、人参、姜汁、炒山栀；久病去掉半夏。"}, {"source": "条31｜《云林神彀》卷二", "原文": "大凡思虑即心跳，此是心经血虚兆，心若时跳又时止，痰因火动治痰妙。若有思虑，即便心跳，此是血虚，养血为妙。", "白话": "大凡一思虑就心跳，这是心经血虚的征兆；心若时跳时止，是痰因火而动，以治痰为妙。如果一有思虑就心跳，这是血虚，以养血为好。"}, {"source": "条32｜《孕育玄机》卷下", "原文": "产后惊悸怔忡，由产惊忧劳倦，去血过多，则中心躁动不宁，惕然而惊，谓之惊悸。心中惕惕然如人将捕之状，谓之怔忡。治此惟唯宜调和脾胃，补养心血，俾志定神宁，气舒心安，而病愈矣。", "白话": "产后惊悸怔忡，是由于产时惊忧劳倦、失血过多，以致心中躁动不宁：惕然而惊的，叫做惊悸；心中惕惕然好像有人要抓捕自己的样子，叫做怔忡。治疗此证只宜调和脾胃、补养心血，使志定神宁、气舒心安，病就痊愈了。"}, {"source": "条33｜《绛雪丹书》", "原文": "产妇惊忧劳倦，去血过多，以致心中躁动不宁，谓之怔忡；若惕然而惊，如人将捕之状，谓之惊悸。治此二症，惟唯调和脾胃，补养心血，使之志定神宁、气舒心安而病自愈矣。", "白话": "产妇惊忧劳倦、失血过多，以致心中躁动不宁的，叫做怔忡；若惕然而惊、好像有人要抓捕自己的样子，叫做惊悸。治疗这两种病证，只宜调和脾胃、补养心血，使志定神宁、气舒心安，病就自然痊愈。"}, {"source": "条34｜《傅青主女科》卷四", "原文": "由产忧、惊、劳、倦，去血过多，则心中跳动不安，谓之怔忡。若惕然震惊，心中怯怯，如人将捕之状，谓之惊悸。治此二症，惟唯调和脾胃，志定神清而病愈矣。如分娩后血块未消，宜服生化汤，且补血行块。血旺则怔定惊平，不必加定神定志剂。", "白话": "由于产时忧、惊、劳、倦，失血过多，就心中跳动不安，叫做怔忡；若惕然震惊、心中怯怯、好像有人要抓捕自己的样子，叫做惊悸。治疗这两种病证，只宜调和脾胃，志定神清病就痊愈。如果分娩后血块未消，宜服生化汤，既能补血又可行血块；血旺则怔定惊平，不必另加安神定志的药。"}, {"source": "条35｜《辨证录》卷四", "原文": "夫神魂不定而惊生，神魂不安而悸起，皆心肝二部之血虚也。血虚则神无所归，魂无所主。今用生血之剂，以大补其心肝，则心肝有血以相养，神魂何至有惊悸哉！倘此等之药，用之骤效，未几而仍然惊悸者，此心肝大虚之故也。", "白话": "神魂不定而惊发生，神魂不安而悸出现，都是心肝二部的血虚。血虚则神无所归、魂无所主。现在用生血之剂大补心肝，使心肝有血互相奉养，神魂哪里还会有惊悸呢！倘若这类药用后很快见效，不久又仍然惊悸的，这是心肝大虚的缘故。"}, {"source": "条36｜《叶氏医效秘传》卷二", "原文": "悸者，心中筑筑然动，而不能自安，即名怔忡，此属心，心虚故筑然而动，若人捕焉。然悸症有九，其治法惟唯三。一曰气虚，因发表太过，气衰神弱，心虚不能自持。二曰水停心下，水气乘心，心火畏水不能安。三曰汗为心液，汗之过多，液去心空，无所倚依。各从症治，或养神，或补气，或温经分水可也。", "白话": "悸是心中筑筑然跳动而不能自安，就名为怔忡，这属于心——心虚所以筑筑而动，好像有人要抓捕自己。然而悸证有九种，其治法只有三条：一是气虚，因发汗解表太过，气衰神弱，心虚不能自持；二是水停心下，水气乘心，心火畏水不能安；三是汗为心之液，出汗过多，津液耗去、心中空虚，无所倚靠。各随证治疗：或养神，或补气，或温经分水。"}, {"source": "条37｜《评注产科心法》卷下", "原文": "心慌惊悸或目不转睛，语言健忘，此由心血空虚，神不守舍，当补心神为主。", "白话": "心慌惊悸，或目不转睛，言语健忘，这是由于心血空虚、神不守舍，治疗当以补益心神为主。"}, {"source": "条38｜《中西温热串解》卷八", "原文": "瘥后惊悸，属血虚，宜养血镇惊。", "白话": "热病愈后惊悸，属于血虚，宜养血镇惊。"}, {"source": "条39｜《中风斠诠》卷二", "原文": "试观肝阳易动之人，必有惊悸怔忡、健忘恍惚诸症，谓非血少心虚之明验，则为肝病培本之计，虽宜滋肾之水，补母以及其子，亦必生心之血，助阴以涵其阳，此养心一层，亦治疗肝阳者所必不可忽也。", "白话": "试看肝阳容易动的人，必有惊悸怔忡、健忘恍惚等症，若说这不是血少心虚的明证；那么为肝病培本的治法，虽然宜滋肾水（补母）以养肝（其子），也必须补生心血，助阴以涵阳——这养心一层，也是治疗肝阳者所万不可忽视的。"}, {"source": "条40｜《诸病源候论》卷十五", "原文": "心气不足，则胸腹大，胁下与腰背相引痛，惊悸，恍惚，少颜色，舌本强，善忧悲，是为心气之虚也，则宜补之。", "白话": "心气不足，就胸腹胀大，胁下与腰背相互牵引疼痛，惊悸，恍惚，面色少华，舌根强硬，容易忧悲——这是心气之虚，就宜补益。"}, {"source": "条41｜《圣济总录》卷四", "原文": "劳极惊悸者，过伤之病也,每本于心气之不足，使心气内和，则精神莫得而动也。", "白话": "劳极惊悸是过度劳伤的病，每每本于心气不足；使心气内和，精神就不能被扰动了。"}, {"source": "条42｜《伤寒家秘》卷二", "原文": "其气虚者，阳气内弱，心中空虚而为悸。又有汗下后正气虚而亦悸，与气虚而悸又甚，皆须定治其气也。", "白话": "气虚的，阳气内弱，心中空虚而发为心悸；又有汗下之后正气虚而也发心悸，比一般气虚心悸更重——都必须安定、治疗其气。"}, {"source": "条43｜《罗氏会约医镜》卷十五", "原文": "心气不足则胸腹大，胁下与腰背相引而令痛，惊悸恍惚，少颜色，舌本强，善忧悲，是为 发心气之虚也，则宜补之于四时。", "白话": "心气不足就胸腹胀大，胁下与腰背相互牵引而疼痛，惊悸恍惚，面色少华，舌根强硬，容易忧悲——这是心气之虚，就宜随时（四时）补益。"}, {"source": "条44｜《医学入门》卷一", "原文": "《五脏穿凿论》曰：心与胆相通（心病怔忡，宜温胆为主；胆病战栗癫狂，宜补心为主）。", "白话": "《五脏穿凿论》说：心与胆相通（心病见怔忡的，宜以温胆为主；胆病见战栗癫狂的，宜以补心为主）。"}, {"source": "条45｜《五脏穿凿论》（据《医学入门》卷一转引）", "原文": "心与胆相通（心病怔忡，宜温胆为主；胆病战栗癫狂，宜补心为主）。", "白话": "心与胆互通：心病见怔忡，宜温胆；胆病见战栗癫狂，宜补心。"}, {"source": "条46｜《辨证奇闻》卷四", "原文": "法徒补心则怔忡不能痊，补各脏腑而不补胆气，内无刚断之风，外有纷纭之扰，安望心之宁静乎？故必补胆气，后可去祛。用坚胆汤 ：白术、人参五钱，茯神、花粉、生枣仁三钱，白芍二两，铁粉、丹砂、竹茹一钱。二剂胆壮，十剂怦怦如失。此肝胆同治，亦心胆共治。肝胆相表里，治胆因治肝者，兄旺弟不衰也。心胆为母子，补胆兼补心者，子强母不弱也。况镇定之品以安神，刻削之味以消痰，宜取效之速也。", "白话": "治法上只补心，怔忡不能痊愈；补各脏腑而不补胆气，内无刚断之风，外有纷纭之扰，怎能指望心的宁静呢？所以必须补胆气，然后才能祛怯。用坚胆汤：白术、人参五钱，茯神、花粉、生枣仁三钱，白芍二两，铁粉、丹砂、竹茹一钱。二剂胆壮，十剂心中怦怦之感消失。这是肝胆同治，也是心胆共治：肝胆相表里，治胆即所以治肝，兄旺则弟不衰；心胆为母子，补胆兼补心，子强则母不弱。况且用镇定之品以安神，削伐之味以消痰，所以取效迅速。"}, {"source": "条47｜《罗氏会约医镜》卷十五", "原文": "胆气不足，其气上溢而口苦，善太息，呕悸宿汁，心下澹澹如人将捕之，嗌中介介数唾，是为胆气之虚也,则宜补之。", "白话": "胆气不足，其气上溢而口苦，容易叹气，呕出悸动宿汁，心下澹澹不安好像有人要抓捕自己，咽中梗阻不舒、频频唾吐——这是胆气之虚，就宜补益。"}, {"source": "条48｜《彤园医书》卷三", "原文": "怔忡、惊悸、恍惚、健忘、失志、伤神，皆名神病，总因心虚胆怯，诸邪得以乘之。病由内生，法宜补养。", "白话": "怔忡、惊悸、恍惚、健忘、失志、伤神，都名为神病，总因心虚胆怯，各种邪气得以乘虚侵入。病由内生，治法宜补养。"}, {"source": "条49｜《辨证录》卷四", "原文": "人有得怔忡之症，心常怦怦不安，常若有官事未了，人欲来捕之状，人以为心气之虚也，谁知是胆气之怯乎？夫胆属少阳，心之母也，母虚则子亦虚。惟唯是胆气虽虚，何便作怔忡之病？不知脏腑之气，皆取决于胆，胆气一虚，而脏腑之气皆无所遵从，而心尤无主，故怦怦而不安者，乃似乎怔忡，而实非怔忡也。治法徒补心而不补各脏腑之气，则怔忡之病不能痊；补各脏腑之气而不补胆之气，内无刚断之风，外有纷纭之扰，又安望心中之宁静乎！故必", "白话": "有人患怔忡证，心常怦怦不安，好像有官府讼事未了、有人要来抓捕的样子；人们以为是心气虚，谁知是胆气怯呢？胆属少阳，是心之母，母虚则子也虚。但胆气虽然虚，为何便发为怔忡？不知脏腑之气都取决于胆，胆气一虚，脏腑之气都无所遵从，而心尤其无主，所以怦怦不安，是像怔忡而其实不是怔忡。治法上只补心而不补各脏腑之气，怔忡之病不能痊愈；补各脏腑之气而不补胆气，内无刚断之风，外有纷纭之扰，又怎能指望心中宁静！所以必须补胆气，然后才能祛怯。"}, {"source": "条50｜《辨证奇闻》卷四", "原文": "法徒补心则怔忡不能痊，补各脏腑而不补胆气，内无刚断之风，外有纷纭之扰，安望心之宁静乎？故必补胆气，后可去祛。用坚胆汤 ：白术、人参五钱，茯神、花粉、生枣仁三钱，白芍二两，铁粉、丹砂、竹茹一钱。二剂胆壮，十剂怦怦如失。此肝胆同治，亦心胆共治。肝胆相表里，治胆因治肝者，兄旺弟不衰也。心胆为母子，补胆兼补心者，子强母不弱也。况镇定之品以安神，刻削之味以消痰，宜取效之速也。", "白话": "治法上只补心，怔忡不能痊愈；补各脏腑而不补胆气，内无刚断之风，外有纷纭之扰，怎能指望心的宁静呢？所以必须补胆气，然后才能祛怯。用坚胆汤：白术、人参五钱，茯神、花粉、生枣仁三钱，白芍二两，铁粉、丹砂、竹茹一钱。二剂胆壮，十剂心中怦怦之感消失。这是肝胆同治，也是心胆共治：肝胆相表里，治胆即所以治肝，兄旺则弟不衰；心胆为母子，补胆兼补心，子强则母不弱。况且用镇定之品以安神，削伐之味以消痰，所以取效迅速。"}, {"source": "条51｜《罗氏会约医镜》卷十五", "原文": "胆气不足，其气上溢而口苦，善太息，呕悸宿汁，心下澹澹如人将捕之，嗌中介介数唾，是为胆气之虚也,则宜补之。", "白话": "胆气不足，其气上溢而口苦，容易叹气，呕出悸动宿汁，心下澹澹不安好像有人要抓捕自己，咽中梗阻不舒、频频唾吐——这是胆气之虚，就宜补益。"}, {"source": "条52｜《伤寒论·辨太阳病脉证并治》", "原文": "发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之。", "白话": "发汗太过，病人两手交叉按护在心前区，心下悸动、想要按压的，用桂枝甘草汤主治。"}, {"source": "条53｜《伤寒论·辨太阳病脉证并治》", "原文": "伤寒脉浮，医以火迫劫之，亡阳，必惊狂，卧起不安者，桂枝去芍药加蜀漆牡蛎龙骨救逆汤主之。", "白话": "伤寒脉浮，医生用火法强迫劫汗，以致亡阳，必然发生惊狂、卧起不安的，用桂枝去芍药加蜀漆牡蛎龙骨救逆汤主治。"}, {"source": "条54｜《伤寒论·辨太阳病脉证并治》", "原文": "伤寒二三日，心中悸而烦者，小建中汤之。", "白话": "伤寒二三天，心中悸动而烦躁的，用小建中汤治疗。"}, {"source": "条55｜《妇人规》上卷", "原文": "真阳不足者，必神疲气怯，或心跳不宁，或四体不收，或眼见邪祟，或阳衰无子等证，俱速宜益火之源，以培右肾之元阳，而神气自强矣。", "白话": "真阳不足的，必精神疲倦、气怯，或心跳不宁，或四肢不能收持，或眼见鬼邪怪异，或阳衰无子等证——都宜赶紧温益阳气之源，以培补右肾的元阳，神气自然强壮。"}, {"source": "条56｜《广瘟疫论》卷二", "原文": "阳虚则呕利、悸眩之证多，责在脾，宜六君子汤。", "白话": "阳虚则呕吐、下利、心悸、眩晕等证多见，病责在脾，宜用六君子汤。"}, {"source": "条57｜《重订通俗伤寒论》", "原文": "《内经》云：若外感证，发汗过多，津液亏少，阳气偏虚，自汗不止，筋失所养而惕惕跳动，肉失所养而瞤然蠕动，目眩心悸，振振欲擗地者，此为亡阳之重证。故以附、姜、辛热回阳为君；臣以白术培中益气，茯苓通阳化气，以助附姜峻补回阳之力；尤必佐白芍阴药以维系者，庶几阳附于阴而内返矣。此为回阳摄阴。急救亡阳之祖方。", "白话": "《内经》说：如果是外感证，发汗过多，津液亏少，阳气偏虚，自汗不止，筋失所养而惕惕跳动，肉失所养而瞤然蠕动，目眩心悸，身体颤振像要扑倒在地的，这是亡阳的重证。所以用附子、干姜辛热回阳为君；臣以白术培补中气、茯苓通阳化气，以助附子干姜峻补回阳之力；尤其必须佐以白芍阴药来维系，这样阳附于阴而能内返。这叫回阳摄阴，是急救亡阳的祖方。"}, {"source": "条58｜《内经》（据《重订通俗伤寒论》转引）", "原文": "若外感证，发汗过多，津液亏少，阳气偏虚，自汗不止，筋失所养而惕惕跳动，肉失所养而瞤然蠕动，目眩心悸，振振欲擗地者，此为亡阳之重证。", "白话": "外感证发汗过多，津液亏少，阳气偏虚，自汗不止，筋肉失养而惕惕瞤动，目眩心悸，振振欲倒——这是亡阳的重证。"}, {"source": "条59｜《圣济总录》卷一百八十六", "原文": "风者百病之始，清净则肉腠膝闭拒，虽有大风苛毒，弗之能害，体虚之人，本脏亏耗，风邪易乘，其证或心神惊悸，手足颤掉，筋脉拘急。凡此之类，皆因虚挟夹风所致，法宜于补药中，加以治风之剂。", "白话": "风是百病的开端；（真气）清净，肌肉腠理就闭密拒邪，即使有大风苛毒也不能伤害。体虚的人，本脏亏耗，风邪容易乘虚侵入，其证或心神惊悸、手足颤掉、筋脉拘急。凡是这类证，都是因虚挟风所致，治法宜在补药中加入治风的药。"}, {"source": "条60｜《素问病机气宜保命集·病机论》卷上", "原文": "云:：“诸禁鼓栗傈，如丧神守，皆属于火。禁栗傈惊惑，如丧神守，悸动怔松，皆热之内作。故治当以制火，制其神守，血荣而愈也。", "白话": "（引《素问》）说：各种口噤、鼓颔战栗，好像神不能主持的，都属于火。口噤战栗、惊恐惑乱，好像神失所守，悸动怔忪，都是热从内生。所以治疗当用制火（清热）之法，使神守恢复、营血充盛，就痊愈了。"}, {"source": "条61｜《圣济总录》卷一", "原文": "心澹澹大动，胸胁胃脘不安，面赤目黄，善噫嗌干，甚则色炲，渴而欲饮，病本于心，……法宜治以苦热，佐以酸淡，以苦燥之，以淡泄之。", "白话": "心中澹澹大动，胸胁胃脘不安，面色红、眼睛黄，多嗳气、咽喉干燥，甚至面色如烟煤，口渴想喝水，病本在于心……治法宜用苦热之味，佐以酸淡，用苦味来燥，用淡味来泄。"}, {"source": "条62｜《普济方》卷十", "原文": "心澹澹大动。，胸胁胃脘不安。，面赤目黄。，善噫嗌干。，甚则色炱。，渴而欲饮。病本于心。，诊在手神门之脉。其法平以辛热。，佐以甘苦。，以咸泻之。", "白话": "心中澹澹大动，胸胁胃脘不安，面红目黄，多嗳气、咽喉干燥，甚至色如烟煤，渴而想喝水。病本在心，诊察在手神门之脉。治法用辛热平之，佐以甘苦，用咸味泻之。"}, {"source": "条63｜《奇效良方》卷八", "原文": "禁栗惊惑，如丧神守，悸动怔忡，皆热之内作，故治当以制火之剂，其神守血，荣自愈也。", "白话": "口噤战栗、惊恐惑乱，好像神失所守，悸动怔忡，都是热从内生，所以治疗当用制火之剂，使神守恢复、营血充盛，自然痊愈。"}, {"source": "条64｜《痘治理辨》", "原文": "烦躁睡卧不安，身热悸动者，宜清心利小便。", "白话": "烦躁、睡卧不安，身热悸动的，宜清心火、利小便。"}, {"source": "条65｜《丹溪手镜》", "原文": "治惊悸癫痫狂妄，大率痰宜吐之，火则下之，血虚宜补血、平木降火。", "白话": "治疗惊悸、癫痫、狂妄，大体上：痰的宜用吐法，火的用下法，血虚的宜补血、平肝木、降火。"}, {"source": "条66｜《医述》卷十", "原文": "若思虑烦劳，身心过动，风阳内扰，则营热心悸，惊怖不寐，胁中动跃。治以酸枣仁汤、补心丹、枕中丹，清营中之热，佐以敛摄神志。", "白话": "如果思虑烦劳、身心过度扰动，风阳内扰，就营热而心悸、惊恐不寐、胁中跳动。治疗用酸枣仁汤、补心丹、枕中丹，清营中之热，佐以敛摄神志。"}, {"source": "条67｜《血证论》", "原文": "又有胃火强梁，上攻于心而跳跃者，其心下如筑墙然，听之有声，以手按其心下，复有气来抵拒，此为心下有动气，治宜大泻心胃之火，火平则气平也，泻心汤主之，或玉女煎加枳壳、厚朴、代赭石、旋覆花以降之，再加郁金、莪术以攻之，使血、气、火三者皆平，自不强梁矣。", "白话": "又有胃火强梁上攻于心而心跳跳跃的，其心下好像筑墙一样，听之有声，用手按其心下，又有气来抵拒——这是心下有动气。治疗宜大泻心胃之火，火平则气平，用泻心汤主治；或用玉女煎加枳壳、厚朴、代赭石、旋覆花以降逆，再加郁金、莪术以攻逐，使血、气、火三者都平，自然不再强梁。"}, {"source": "条68｜《六因条辨》卷上", "原文": "中热神清，能食便闭，目瞑不寐，而多惊惕，此热留胆络，营卫失度。宜用秫米半夏汤……清胆热而下肝系也……寤而不寤，目瞑惊惕不宁，因胆热肝横，胃失冲和，营卫失度。仿《内经》秫米半夏，和胃气之升降，枣仁、郁李、龙齿下肝系以镇惊，羚角、猪胆、丹皮清胆热，而泄火风为妙。", "白话": "中热而神清，能食而大便闭，闭目而不能入睡，多惊惕——这是热留胆络、营卫失度。宜用秫米半夏汤……清胆热而下肝系……想睡而睡不着，闭目则惊惕不宁，是因为胆热肝横、胃失冲和、营卫失度。仿《内经》半夏秫米汤和胃气之升降，用枣仁、郁李仁、龙齿下肝系以镇惊，羚羊角、猪胆、丹皮清胆热而泻火熄风为妙。"}, {"source": "条69｜《内经》秫米半夏（据《六因条辨》卷上转引）", "原文": "仿《内经》秫米半夏，和胃气之升降", "白话": "效法《内经》的秫米半夏（半夏秫米汤），以和胃气之升降。"}, {"source": "条70｜《重订通俗伤寒论》", "原文": "若无淋毒。但心经遗热于膀胱。膀胱热结则尿血。症见虚烦不寐。或昏睡不省。或舌咽作痛。或怔忡懊憹。治宜凉血泄热。", "白话": "如果没有淋毒，只是心经遗热于膀胱，膀胱热结就尿血。证见虚烦不寐，或昏睡不省，或舌咽作痛，或怔忡懊憹。治疗宜凉血泄热。"}, {"source": "条71｜《东垣试效方》", "原文": "朱砂安神丸。心病烦乱，怔忡，兀兀欲吐，胸中气乱而热，皆隔上血中伏火蒸蒸而不安。宜用权衡法，以镇阴火之浮行，以养上焦元气。", "白话": "朱砂安神丸。心病烦乱、怔忡、恶心兀兀欲吐、胸中气乱而热，这都是膈上血中伏火蒸蒸而致不安。宜用权衡之法，以镇伏阴火的浮行，以养上焦元气。"}, {"source": "条72｜《医林绳墨·怔忡篇》", "原文": "怔者血之虚，忡者火之盛，养血则怔自安，降火则忡自定。", "白话": "“怔”是血虚，“忡”是火盛；养血则怔自安，降火则忡自定。"}, {"source": "条73｜《丹溪手镜》", "原文": "治惊悸癫痫狂妄，大率痰宜吐之，火则下之，血虚宜补血、平木降火。", "白话": "治疗惊悸、癫痫、狂妄，大体上：痰的宜用吐法，火的用下法，血虚的宜补血、平肝木、降火。"}, {"source": "条74｜《医学正传》", "原文": "惊悸者属血虚，用朱砂安神丸最好。", "白话": "惊悸属于血虚的，用朱砂安神丸最好。"}, {"source": "条75｜《类经》卷五", "原文": "虚里跳动，最为虚损病本，故凡患阴虚劳怯，则心下多有跳动，及为惊悸慌张者，是即此证，人止知其心跳而不知为虚里之动也。但动之微者病尚微，动之甚者病则甚，亦可因此以察病之轻重。凡患此者，余常以纯甘壮水之剂，填补真阴，活者多矣。然经言宗气之泄，而余谓真阴之虚，其说似左，不知者必谓谬诞，愚请竟其义焉。夫谷入于胃，以传于肺，五藏五脏六府六腑，皆以受气，是由胃气而上为宗气也。气为水母，气聚则水生，是由肺气而下生", "白话": "虚里跳动，最是虚损病的根本。所以凡患阴虚劳怯的，心下多有跳动，以至惊悸慌张的，就是此证；人们只知道心跳，而不知是虚里之动。跳动轻微的病尚轻，跳动严重的病就重，也可以据此来察病的轻重。凡患此证的，我常用纯甘壮水之剂填补真阴，救活的很多。然而《内经》说是宗气外泄，而我说是真阴之虚，两种说法似相背离，不知者一定说荒诞，请让我把道理讲完：谷物入胃，上输于肺，五脏六腑都借此受气，这是由胃气上而成为宗气；气是水之母，气聚则水生，这是由肺气下而生肾水。现在胃气传到肺，而肾虚不能摄纳，所以宗"}, {"source": "条76｜《增订叶评伤暑全书》卷下", "原文": "厥阴病外寒内热，心动悸，脉结代者，制复脉汤，凉补以滋阴。", "白话": "厥阴病外寒内热，心动悸、脉结代的，创制复脉汤，凉补以滋阴。"}, {"source": "条77｜《幼科证治准绳》", "原文": "大凡幼稚欲令常时惊悸不作，在乎肾脏和平，故戴氏曰：治惊不若补肾。谓心属火，火性燥，得肝风则烟焰起，致生惊悸，补肾则水升火降，邪热无侵，虽有肝风，不生惊骇。", "白话": "大凡要使小儿平时不发惊悸，关键在肾脏和平，所以戴氏说：治惊不如补肾。心属火，火性燥，得肝风就烟焰升起，以致发生惊悸；补肾则水升火降，邪热无从侵犯，虽有肝风，也不生惊骇。"}, {"source": "条78｜《景岳全书》卷十八", "原文": "凡治怔忡惊恐者，虽有心脾肝肾之分，然阳统乎阴，心本乎肾。所以上不宁者，未有不由乎下，心气虚者，未有不因乎精。然心肝脾肾之气名虽有异，而治不可有离者，亦以精气互根之宜然而君相相资之全力也。", "白话": "凡治疗怔忡惊恐，虽有心、脾、肝、肾的区分，但阳统于阴，心本于肾。所以心神上部不安的，没有不由于下部；心气虚的，没有不因于精亏。心肝脾肾之气名称虽有不同，而治疗不可分割，这也是精气互根的自然之理、君相二火相互资助的完整作用。"}, {"source": "条79｜《证治汇补》", "原文": "阴火上炎者，治其肾而心悸自已。", "白话": "阴火上炎的，治其肾，心悸自然停止。"}, {"source": "条80｜《辨证奇闻》卷四", "原文": "惊有出于暂不出于常，悸有成于暗不成于明者，又不可不别。暂惊轻于常惊，明悸重于暗悸而惊悸仍伺，则将分治乎？抑合治乎？知其合中之分，则分治效；知其分中之合，则合治亦效。盖惊出于暂，吾治其常；悸出于明，吾治其暗。吾一方合而治之，名两静汤：人参、巴戟天一两，生枣仁二两，菖蒲一钱，白芥子、丹砂三钱。四剂定。方妙在生枣仁之多，以安心，尤妙在人参、巴戟以通心肾。则心气通肾夜安，肾气通心日安。又何虑常、暂、明、暗", "白话": "惊有出于一时而不出于经常的，悸有成于暗处而不成于明处的，又不可不辨别。一时之惊轻于经常之惊，明处之悸重于暗处之悸；然而惊悸交替出现，是分治呢，还是合治？懂得合中的分，分治就有效；懂得分中的合，合治也有效。惊出于一时，我治其经常；悸出于明处，我治其暗处。我用一方合而治之，名叫两静汤：人参、巴戟天各一两，生枣仁二两，菖蒲一钱，白芥子、丹砂各三钱。四剂安定。方妙在生枣仁用量之多以安心，尤其妙在人参、巴戟天以通心肾：心气通肾则夜安，肾气通心则昼安。又何必顾虑常、暂、明、暗呢。"}, {"source": "条81｜《辨证录》卷四", "原文": "人有得怔忡之症，日间少轻，至夜则重，欲思一睡熟而不可得者，人以为心虚之极也，谁知是肾气之乏乎。凡人夜卧则心气必下降于肾宫，惟唯肾水大耗，一如家贫，客至无力相延，客见主人之窘迫，自然不可久留，徘徊岐歧路，实乃徨耳。治法大补其肾中之精，则肾气充足矣。", "白话": "有人患怔忡证，白天稍轻，到夜间加重，想睡熟一觉却不可得；人们以为是心虚到极点，谁知是肾气匮乏呢？凡人夜间躺卧，心气必下降于肾宫；只是肾水大耗，好比家中贫穷，客人来了无力接待，客人见主人窘迫，自然不能久留，在歧路上徘徊，实在是彷徨无依。治法大补肾中之精，肾气就充足了。"}, {"source": "条82｜《不居集》", "原文": "怔忡之病，心胸筑筑振动，惶惶惕惕，无时得宁者是也。此证惟唯阴虚劳损之症恒有之。盖阴虚于下，则宗气无根，而气不归原，所以在上则浮撼于胸臆，在下则振动于脐旁，虚微者动亦微，虚甚者动亦甚。凡患此者，速宜节欲节劳，切戒酒色。凡治此者，速宜养气养精、滋培根本。", "白话": "怔忡之病，是心胸筑筑振动、惶惶惕惕、无时安宁的证。这证只有阴虚劳损之证常有。阴虚于下，则宗气无根而气不归元，所以在上就浮撼于胸臆，在下就振动于脐旁；虚轻微的动也轻微，虚甚的动也甚。凡患此证的，宜赶紧节欲节劳，切戒酒色；凡治疗此证的，宜赶紧养气养精、滋培根本。"}, {"source": "条83｜《王九峰医案》下卷", "原文": "心为君主之乡，肾为藏水之脏。火性炎上，水体润下；水欲上升，火欲下降。水无以上升，火何以下降？水火不济，心肾不交，是以心烦意乱，不知所从，宗气上浮，虚里跳动，脉来软数无神，有惊悸健忘之虞。法当壮水潜阳为主。", "白话": "心是君主所居之处，肾是藏水之脏。火性炎上，水性润下；水要上升，火要下降。水不能上升，火怎能下降？水火不济、心肾不交，所以心烦意乱、不知所从，宗气上浮，虚里跳动，脉来软数而无神，有惊悸健忘之忧。治法当以壮水潜阳为主。"}, {"source": "条84｜《王九峰医案》下卷", "原文": "木惊卒恐，心神肾志交伤。肾藏精，恐则精怯，精化气，法则精无以化。心藏神，惊则神乱，化生精无以生。是以心神震动，惶惶惕慯伤，莫能自主。阳统于阴，精本乎气，上下安者，必由于下，心气虚者，必因于精。证以精气互根之宜，君相所资之道。法当峻补心肾，仍须尽释疑怀，使气归精，精化气，则神志安定，病自己已矣。", "白话": "因肝木而惊、猝然恐惧，心神肾志交相损伤。肾藏精，恐惧则精怯；精化气，精伤则气化无源。心藏神，受惊则神乱，神乱则精无从生。所以心神震动，惶惶惕然伤损，不能自主。阳统于阴，精本于气；上部安宁必由于下部，心气虚必因于精亏。以精气互根之理、君相相资之道为依据，治法当峻补心肾，还必须尽释疑虑，使气归精、精化气，神志安定，病就自然痊愈。"}, {"source": "条85｜《温热经纬》卷四", "原文": "瘥后怔忡，乃水衰火旺，心肾不交，宜补水养心。", "白话": "热病愈后怔忡，是水衰火旺、心肾不交，宜补水养心。"}, {"source": "条86｜《医法圆通》", "原文": "夫曰惊者，触物而心即惶惶无措，偶闻震响而即恐惧；无依，此皆由正气衰极，神无所主。法宜扶阳交通水火为主，如白通汤、补坎益离丹之类多服自愈。", "白话": "所谓惊，是触物而心就惶惶无措，偶闻震响就恐惧无依——这都是正气衰极、神无所主。治法宜以扶阳、交通水火为主，如白通汤、补坎益离丹之类，多服自愈。"}, {"source": "条87｜《医法圆通》", "原文": "心病不安一症，有心血不足为病者，有心气不足为病者。心血不足为病者，其人多烦，小便短赤而咽中干，肌肤枯槁憔悴而神不大旺，甚则狂妄喜笑，脉必细数，或洪大，喜食甘凉清淡油润之品者是也。心气不足为病者，其人少神，喜卧懒言，小便清长，或多言、多劳力、多用心一刻，心中便潮热而自汗出。心阳不足，固宜真补其心阳，而又曰补坎者，盖以火之根在下也。予意心血不足与心阳不足，皆宜专在下求之，何也？水火互为其根，其实皆在坎", "白话": "心病不安一证，有心血不足为病的，有心气不足为病的。心血不足的，其人多烦，小便短赤而咽中干，肌肤枯槁憔悴而神气不旺，甚至狂妄喜笑，脉必细数或洪大，喜吃甘凉清淡油润之品。心气不足的，其人神少，喜卧懒言，小便清长；或多说话、多劳力、多用心一会儿，心中就潮热而自汗出。心阳不足，固然宜温补其心阳，而又说“补坎”，是因为火之根在下（坎属肾）。我以为心血不足与心阳不足，都宜专从下部求治——为什么？水火互为其根，其实都在坎（肾）。真火旺则君火自旺，心阳不足自然可愈；真气升则真水也升，心血不足"}, {"source": "条88｜《仁斋直指方》", "原文": "惊者，与之豁痰定惊之剂。", "白话": "惊证，给以豁痰定惊的方剂。"}, {"source": "条89｜《医方选要》卷七", "原文": "夫怔忡也，健忘也，动悸也，三者名虽不同，未有不由心血不足，脾气虚弱，积饮停痰而成也。治之唯在补养心血，调和脾气，宁其神，化其痰，使神气充满，心安气舒，则无三者之患也。", "白话": "怔忡、健忘、动悸三者名称虽然不同，没有不是由心血不足、脾气虚弱、积饮停痰所形成的。治疗只在补养心血、调和脾气、安宁心神、化其痰饮，使神气充满，心安气舒，就没有这三者的疾患。"}, {"source": "条90｜《医学正传》", "原文": "惊悸……或有痰迷心窍者，宜用治痰药。", "白话": "惊悸……有的是痰迷心窍，宜用治痰的药。"}, {"source": "条91｜《古今医鉴》卷八", "原文": "惊悸、健忘、怔忡、失志不寐、心风，皆是胆涎沃心，以致心气不足。若用凉剂太过，则心火愈微，痰涎愈盛，而病益深，宜理痰气。", "白话": "惊悸、健忘、怔忡、失志不寐、心风，都是胆涎沃心，以致心气不足。如果用寒凉药太过，心火就愈微弱，痰涎愈盛，病就更深——宜理气化痰。"}, {"source": "条92｜《医林绳墨·怔忡》", "原文": "怔则心胸之气左右攻击，聚而不散，搐动中焦，如将征战者也，致令心有所动，郁烦躁扰，懊侬不宁，坐卧难安，甚则恶心呕哕，欲吐不吐之状。治当安心养血、清痰理气之剂，如二陈汤加归、术、人参、姜汁、炒山栀。久病去半。", "白话": "“怔”是心胸之气左右攻冲，聚而不散，牵动中焦，如同将要征战的样子，致使心中跳动，郁烦躁扰，懊憹不宁，坐卧难安；甚至恶心呕哕，想吐又吐不出的样子。治疗当用安心养血、清痰理气的方剂，如二陈汤加当归、白术、人参、姜汁、炒山栀；久病去掉半夏。"}, {"source": "条93｜《医林绳墨·惊悸》", "原文": "悸则搐动心志，摇头气窜，或默或想，如畏如惧，默想不来，警然而惕，是则为悸。然清痰理气可也，治宜苓连二陈汤，或牛黄苏合丸。若心气太虚，神不自守，如物所惑，忽然而惧惕者，亦当作悸治之，乃心为痰所迷也，治宜枳桔二陈汤加归、术、参、麦。", "白话": "悸是心志搐动，摇头气窜，或沉默或冥想，如有所畏所惧，沉默冥想间突然警然而惕——这就是悸。用清痰理气的方法即可，治宜苓连二陈汤或牛黄苏合丸。如果心气太虚、神不自守，如被外物迷惑、忽然惧惕的，也当按悸治疗——这是心被痰所迷，治宜枳桔二陈汤加当归、白术、人参、麦冬。"}, {"source": "条94｜《医学原理》卷九", "原文": "怔忡惊悸之症，肥人多是痰火冲心，瘦人多是心血不足。故在肥人，宜理气导痰为先；在瘦人，当补血养心为要。", "白话": "怔忡惊悸之证，肥人多是痰火冲心，瘦人多是心血不足。所以在肥人宜以理气导痰为先，在瘦人当以补血养心为要。"}, {"source": "条95｜《证治准绳·杂病》", "原文": "大抵惊悸健忘，怔忡失志，心风不寐，皆是胆涎沃心，以致心气不足。若用凉心之剂太过，则心火愈微，痰涎愈盛，病愈不减，惟唯当以理痰气为第一义，导痰汤加石菖蒲半钱。喘不得卧，以喘法治之。厥不得卧，以脚气法治之。", "白话": "大抵惊悸健忘、怔忡失志、心风不寐，都是胆涎沃心，以致心气不足。如果用寒凉清心之剂太过，心火愈微弱、痰涎愈盛，病愈加不减；只当以理气化痰为第一要义，用导痰汤加石菖蒲半钱。喘促不能卧的，按喘证治疗；厥逆不能卧的，按脚气治疗。"}, {"source": "条96｜《万氏家抄济世良方》卷二", "原文": "凡痰之为患，为喘、为嗽、为呕、为利、为眩、为晕。心嘈杂，怔忡惊怖为寒热……善治疾者不治痰而治气，气顺则一身之津液亦随气而顺矣。治疾法实脾土，燥脾湿是治其本也。凡奇怪之症人所不识者皆当作痰治。", "白话": "凡痰为患，或为喘、为嗽、为呕、为利、为眩、为晕；心嘈杂，怔忡惊怖，发为寒热……善于治病的不治痰而治气，气顺则一身津液也随气而顺。治疗的方法：实脾土、燥脾湿是治其根本。凡是奇怪之证、人们不能辨识的，都当按痰治疗。"}, {"source": "条97｜《丹溪手镜》", "原文": "治惊悸癫痫狂妄，大率痰宜吐之，火则下之，血虚宜补血、平木降火。", "白话": "治疗惊悸、癫痫、狂妄，大体上：痰的宜用吐法，火的用下法，血虚的宜补血、平肝木、降火。"}, {"source": "条98｜《景岳全书》", "原文": "凡痰证饮食少思，或胸隔不利者，此中气虚弱也，宜用补中益气为主，中气既健，其痰自运化。若肾气亏损，津液难降，败浊为痰者，乃真脏之病，宜用六味地黄丸为主。肾气既壮，津液清化，而何痰之有哉。亦有因脾胃亏损，中焦气虚，不能运化而为痰者；亦有因峻厉过度，脾气愈虚，不能运化津液，凝滞而为痰者，凡此皆当健脾胃为主。", "白话": "凡痰证饮食减少，或胸膈不利的，这是中气虚弱，宜以补中益气为主；中气健旺，痰自然运化。若肾气亏损、津液难降、败浊为痰的，是真脏之病，宜以六味地黄丸为主；肾气壮旺，津液清化，又哪里会有痰呢？也有因脾胃亏损、中焦气虚、不能运化而生痰的；也有因攻伐峻厉过度、脾气愈虚、不能运化津液、凝滞为痰的——凡此种种都当以健脾胃为主。"}, {"source": "条99｜《济阳纲目》卷三十一", "原文": "水气者，漉漉有声，怔忪浮肿，当逐水利小便。惊忧者，惕惕闷闷，引息鼻张，当宽中下气。胃络不和者，宜分气化痰以和之。", "白话": "水气为病，漉漉有声，怔忪浮肿，当逐水利小便；惊忧为病，惕惕闷闷，呼吸引动、鼻翼扇张，当宽中下气；胃络不和的，宜分气化痰以调和。"}, {"source": "条100｜《证治汇补》", "原文": "痰结者，降下之。", "白话": "痰结的，用降下（攻下痰结）的方法。"}, {"source": "条101｜《张氏医通》", "原文": "盖惊悸健忘失志心风不寐，皆是痰涎沃心，以致心气不足。若凉心太过，则心火愈微，痰涎愈盛，惟唯以理痰顺气为第一义。", "白话": "惊悸健忘、失志心风不寐，都是痰涎沃心，以致心气不足。如果寒凉清心太过，心火愈微弱、痰涎愈盛，只以理痰顺气为第一要义。"}, {"source": "条102｜《医林绳墨·惊悸》", "原文": "又有心虚而郁痰，或耳闻大声，目击异物，心为物忤，是则为惊，乃痰因火动也，治宜归术二陈汤加苓、连、枣仁。", "白话": "又有心虚而郁痰，或耳闻大声、目见异物，心被外物所触犯，这就是惊——是痰因火而动，治宜归术二陈汤加茯苓、黄连、枣仁。"}, {"source": "条103｜《古今名医荟萃》卷六", "原文": "今失其阴，偏倾于阳，阳亦失其所承而散乱，故精神怔怔忡忡不能自安矣。若内外诸邪郁其二火，不得发越，隔绝营卫，不得充养其正气者，则皆以治邪解郁为主，若痰饮停于中焦，碍其经络，不得舒通，而郁火与痰相击于心下，以为怔忡者，必导去其痰，经脉行则病自已。", "白话": "现在阴气亏失，偏倾于阳，阳也失去所承而散乱，所以精神怔怔忡忡不能自安。如果内外诸邪郁遏二火（君火、相火），不得发越，隔绝营卫，不能充养正气的，都以治邪解郁为主；若痰饮停于中焦，阻碍经络不得舒通，郁火与痰相击于心下而成为怔忡的，必须导去其痰，经脉通行病就自止。"}, {"source": "条104｜《重订广温热论》卷一", "原文": "瘥后惊悸。凡温热新瘥，触事易惊，梦寐不安者，余热挟夹痰也。痰与气搏，震荡心宫，故惊悸。宜用竹茄、黄连、石菖蒲、半夏、胆星、栀子、知母、茯苓、旋复花旋覆花、橘红等，清余热而消痰。", "白话": "愈后惊悸。凡温热病初愈，遇事容易受惊、梦寐不安的，是余热挟痰。痰与气相搏结，震荡心宫，所以惊悸。宜用竹茹、黄连、石菖蒲、半夏、胆星、栀子、知母、茯苓、旋覆花、橘红等，清余热而消痰。"}, {"source": "条105｜《伤寒论》", "原文": "伤寒厥而心下悸，宜先治水，当服茯苓甘草汤，却治其厥，不尔，水渍入胃，必作利也。", "白话": "伤寒四肢厥冷而心下悸动的，宜先治水，当服茯苓甘草汤，然后再治其厥；不这样，水饮浸渍入胃，必然发生下利。"}, {"source": "条106｜《仁斋直指方》", "原文": "悸者，与之逐水消饮之剂。", "白话": "悸证，给以逐水消饮的方剂。"}, {"source": "条107｜《普济方》卷一百二十一", "原文": "心振寒而动曰悸。厥阴证云。厥逆怔忪。此有水也。宜治水。", "白话": "心振寒而跳动的叫做悸。厥阴证说：厥逆怔忪，这是有水，宜治水。"}, {"source": "条108｜《伤寒家秘》卷二", "原文": "其停饮者，由饮水过多，水停心下，心火恶水，不能自安，虽有余邪，必先治悸与水也。治法必先分水、气，虽有余邪，亦先治悸，免使水气散走而成他证也。", "白话": "停饮的，是由于饮水过多，水停心下，心火恶水，不能自安；虽然还有余邪，也必须先治悸与水。治法必先分辨水与气，虽然有余邪，也先治悸，以免水气散走而变生他证。"}, {"source": "条109｜《丹溪手镜》卷上", "原文": "有停饮者，饮水多必心下悸，心火恶水，心不安也。凡治悸者，必先治饮，以水停心下，散而无所不至。浸于肺则喘咳，浸于胃则哕噎，溢于皮肤则肿，渍于肠间则利下，可以茯苓甘草汤治之。", "白话": "有停饮的，饮水多必心下悸，因心火恶水、心不安。凡治悸必先治饮，因为水停心下，散开则无处不到：浸于肺就喘咳，浸于胃就哕噎，溢于皮肤就浮肿，渍于肠间就下利——可用茯苓甘草汤治疗。"}, {"source": "条110｜《叶氏医效秘传》卷二", "原文": "悸者，心中筑筑然动，而不能自安，即名怔忡，此属心，心虚故筑然而动，若人捕焉。然悸症有九，其治法惟唯三。一曰气虚，因发表太过，气衰神弱，心虚不能自持。二曰水停心下，水气乘心，心火畏水不能安。三曰汗为心液，汗之过多，液去心空，无所倚依。各从症治，或养神，或补气，或温经分水可也。", "白话": "悸是心中筑筑然跳动而不能自安，就名为怔忡，这属于心——心虚所以筑筑而动，好像有人要抓捕自己。然而悸证有九种，其治法只有三条：一是气虚，因发汗解表太过，气衰神弱，心虚不能自持；二是水停心下，水气乘心，心火畏水不能安；三是汗为心之液，出汗过多，津液耗去、心中空虚，无所倚靠。各随证治疗：或养神，或补气，或温经分水。"}, {"source": "条111｜《杂病广要》", "原文": "若自腰以上发热，极则汗出，出已则凉，移时如故，复加昏冒，腹中膨满，其气上攻，时时咳嗽，嗽引胁下牵痛，睡中惊悸，其脉弦急带疾。此由外寒搏客，内冷相合，寒则气收，而水液聚而不行，内化成饮，医以热药攻寒，寒未已而复增客热，阴寒内闭，拒阳于外而不得入，逼阳上行，发而为热，散而为汗，汗多亡阳，心气内虚，故令惊悸，治属饮家，温而利之。", "白话": "如果自腰以上发热，极则汗出，汗出就凉，过一会又同前，又加昏冒，腹中膨满，其气上攻，时时咳嗽，咳嗽引动胁下牵痛，睡中惊悸，脉弦急带数——这是外寒搏结，与内冷相合；寒则气收，水液聚而不行，内化成饮；医生用热药攻寒，寒未去而反增客热；阴寒内闭，拒阳于外而不得入，逼阳上行，发而为热，散而为汗；汗多亡阳，心气内虚，所以发生惊悸。治疗属于饮家（痰饮病），用温而利的方法。"}, {"source": "条112｜《医法圆通》", "原文": "悸者，心下有水气也。心为火地，得阴水以扰之，故心不安。水停心下，时时荡漾，故如有物忡也。法宜行水为主，如桂苓术甘汤、泽泻散之类。", "白话": "悸是心下有水气。心为火之地，被阴水扰动，所以心不安；水停心下，时时荡漾，所以好像有物冲动作忡。治法宜以行水为主，如桂苓术甘汤、泽泻散之类。"}, {"source": "条113｜《素问病机气宜保命集》", "原文": "怯则气浮，欲其镇也。如丧神守而惊悸，气上厥以颠疾，必重剂以镇之，《本草》曰‘重可去怯’，即磁石、铁粉之属。经所谓‘厥成为颠疾’，故惊乃平之，所以镇涎也，故使其物体之重，则下涎而用之也。", "白话": "怯就会气浮，需要镇降。如神失所守而惊悸、气上逆而成癫疾，必须用重剂镇降——《本草》说“重可去怯”，就是磁石、铁粉之类。经所谓“厥逆成为癫疾”，所以惊要用平镇的方法，这是为了镇涎；用质重之物，是取其下涎而用。"}, {"source": "条114｜《本草》（据《素问病机气宜保命集》转引）", "原文": "《本草》曰‘重可去怯’，即磁石、铁粉之属。", "白话": "《本草》说：重剂可以祛怯，就是磁石、铁粉之类。"}, {"source": "条115｜《普济方》卷五", "原文": "如丧神守而惊悸，气上厥而巅颠疾，必重剂以镇之。", "白话": "如神失所守而惊悸、气上逆而成癫疾的，必须用重剂镇降。"}, {"source": "条116｜《考证病源》", "原文": "怯则气浮，必重剂以镇之，如惊悸怔忡之属。本草曰：重可去怯，磁石铁粉之属。", "白话": "怯就会气浮，必须用重剂镇降，如惊悸怔忡之类。《本草》说：重剂可以祛怯，就是磁石、铁粉之类。"}, {"source": "条117｜《证治准绳·杂病》", "原文": "所以惊者，必先安其神，然后散乱之气可敛，气敛则阳道行矣。", "白话": "所以治惊必先安神，然后散乱之气可以收敛，气敛则阳气之道得行。"}, {"source": "条118｜《简明医彀》卷四", "原文": "经曰：阳气与阴气相搏，水火相恶，故惕然惊也……治宜镇心神，安魂魄，清痰制火，养血疏肝。", "白话": "《内经》说：阳气与阴气相搏，水火相恶，所以惕然而惊……治疗宜镇心神、安魂魄、清痰制火、养血疏肝。"}, {"source": "条119｜《伤寒附翼》卷下", "原文": "惊是木邪犯心，谵语是热邪入胃。惊者须重以镇怯，铅禀于金之体，受癸水之气，能清上焦无形之烦满，中焦有形之热结，炼而成丹，不特入心而安神，且以入肝而滋血矣。龙骨重能镇惊而平木，蛎体坚不可破，其性守而不移，不特静可以镇惊，而寒可以除烦热。", "白话": "惊是木邪犯心，谵语是热邪入胃。惊须用重镇以祛怯——铅禀金之体、受癸水之气，能清上焦无形之烦满、中焦有形之热结；炼而成丹，不仅能入心安神，且能入肝滋血。龙骨质重能镇惊而平肝木；牡蛎之体坚不可破，其性守而不移，不仅能镇惊，其寒又能除烦热。"}, {"source": "条120｜《证治汇补》", "原文": "若外物卒惊，宜行镇重:：又惊者平之，所谓平者，平昔所见所闻，使之习熟，自然不惊也。", "白话": "如果外物猝然致惊，宜用镇重之法；又“惊者平之”——所谓“平”，是让其对平日所见所闻习以为常，自然就不惊了。"}, {"source": "条121｜《医碥》卷四", "原文": "惊则气上，以重坠之药镇其浮越。（丹砂、龙骨之类。）", "白话": "惊则气上逆，用重坠之药镇其浮越之气（如丹砂、龙骨之类）。"}, {"source": "条122｜《增订通俗伤寒论》", "原文": "伤寒坏证若震及心脾而为悸为消者，用甘麦大枣汤合龙杜之属，为缓急重镇法。", "白话": "伤寒坏证，如果震动心脾而为心悸、为消渴的，用甘麦大枣汤合龙骨、牡蛎之类，这是缓急重镇法。"}, {"source": "条123｜《医林绳墨》惊悸篇", "原文": "治惊莫若安心，治悸莫若顺气，心气既宁，惊悸必除。", "白话": "治惊不如安心，治悸不如顺气；心气安宁，惊悸必除。"}, {"source": "条124｜《济阳纲目》卷三十一", "原文": "惊忧者，惕惕闷闷，引息鼻张，当宽中下气。", "白话": "惊忧为病，惕惕闷闷，呼吸引动、鼻翼扇张，当宽中下气。"}, {"source": "条125｜《证治汇补》", "原文": "气郁者，舒畅之。", "白话": "气郁的，用舒畅（理气解郁）的方法。"}, {"source": "条126｜《金匮悬解》卷八", "原文": "惊悸之家，风木郁动，营血失敛，往往上溢而下泄，不溢不泄，则蓄结而内瘀。", "白话": "惊悸患者，风木郁动，营血失于收敛，往往上溢（吐血衄血）而下泄（便血尿血）；不溢不泄的，就蓄结而成内瘀。"}, {"source": "条127｜《医林改错》", "原文": "血府逐瘀汤所治之病开列于后……心跳心忙，用归脾、安神等方不效，用此方百发百中。", "白话": "血府逐瘀汤所治的病开列在后……心跳心慌，用归脾汤、安神等方不见效的，用此方百发百中。"}, {"source": "条128｜《血证论·脏腑病机论》", "原文": "血虚则神不安而怔忡，有瘀血亦怔忡。", "白话": "血虚则神不安而发怔忡，有瘀血也发怔忡。"}, {"source": "条129｜《血证论·怔忡》", "原文": "俗名心跳。心为火脏，无血以养之，则火气冲动，是以心跳，安神丸清之，归脾汤加麦冬五味子以补之。凡思虑过度，及失血家去血过多者，乃有此虚证。否则多挟夹痰瘀．宜细辨之。", "白话": "怔忡俗名心跳。心是火脏，没有血来奉养，火气就冲动，所以心跳；用安神丸清之，归脾汤加麦冬、五味子补之。凡思虑过度及失血者去血过多的，才有这种虚证；否则多挟痰挟瘀，应当细辨。"}, {"source": "条1｜《伤寒论》", "原文": "脉浮数者，法当汗出而愈。若下之，身重、心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚。须表里实，津液自和，便自汗出愈。", "白话": "“脉浮数的，依法当用发汗法，汗出就会痊愈。如果误用泻下，出现身重、心悸的，不可再发汗，待其自行汗出便可解除。之所以这样，是因为尺中脉微——这是里虚。必须待表里之气充实、津液自和，便会自行汗出而愈。”"}, {"source": "条2｜《古今医鉴》卷六", "原文": "又有时气、伤寒、伤风、伏暑解散未尽，亦令人发黄。如有其状，口淡怔忡，耳鸣脚弱，微寒微热，小便白浊，此为虚证，不可妄用凉药，愈伤气血。", "白话": "“又有时气、伤寒、伤风、伏暑等邪解散未尽，也能使人发黄。如果见有这样的症状：口中味淡、怔忡、耳鸣、两脚软弱、轻微寒热、小便白浊——这是虚证，不可乱用凉药，（否则）愈加损伤气血。”"}, {"source": "条3｜《石室秘录》卷四", "原文": "如人病虚劳，四肢无力，饮食少思，怔忡惊悸，失血之后，大汗之后是也。此等各症，俱不可用偏寒偏热之药，必须温乎之品，少少与之，渐移默夺，庶几奏效。倘以偏师出奇，必有后患。", "白话": "“如人患虚劳，四肢无力、饮食少思、怔忡惊悸，见于失血之后、大汗之后之类。这各种证候，都不能用偏寒偏热的药物，必须用温和平缓之品，少量给予，渐渐潜移默夺，才可望见效。倘若以偏师出奇（用猛峻之药求奇效），必留后患。”"}, {"source": "条4｜《神农本草经疏》", "原文": "易惊属胆气虚。忌破气、升发、燥热。诸药俱见前。宜补胆气、甘温、辛温、酸平。", "白话": "“容易受惊属于胆气虚。忌用破气、升发、燥热（诸药都见于前文）。宜补胆气，药性宜甘温、辛温、酸平。”"}, {"source": "条5｜《心悸》三审稿·第四章评述（开篇总说）", "原文": "中医学对于心悸的诊治有着悠久的历史，早在《黄帝内经》时期就明确提出了补虚泻实的治疗原则，经过历代医家的不断充实与发展，现已形成内容丰富的治则治法理论体系。在对古代医籍中心悸相关治则治法文献进行全面系统梳理与研究的基础上，分层次进行整理，发掘、汇聚大量有价值的典籍文献，力求反映心悸治则治法各时代的发展脉络，明晰其治法理论源流及论治特色，为临床和科研工作提供有益参考。", "白话": "中医学对心悸的诊治有着悠久的历史：早在《黄帝内经》时期就已明确提出补虚泻实的治疗原则，经过历代医家不断充实与发展，如今已形成内容丰富的治则治法理论体系。本部分在对古代医籍中心悸相关治则治法文献作全面系统梳理与研究的基础上，分层次加以整理，发掘、汇聚大量有价值的典籍文献，力求反映心悸治则治法各时代的发展脉络，弄清其治法理论源流及论治特色，为临床和科研工作提供有益的参考。"}, {"source": "条6｜《心悸》三审稿·第四章评述（治疗原则·本虚标实）", "原文": "心悸为本虚标实之证，虚者为气、血、阴、阳亏损，使心失滋养而致惊悸；实者多由痰火（郁痰）扰心、水饮上凌或心血瘀阻、气血运行不畅所致，。", "白话": "心悸是本虚标实的病证：属虚的，是气、血、阴、阳亏损，使心失于滋养而导致惊悸；属实的，多由痰火（郁痰）扰心、水饮上凌，或心血瘀阻、气血运行不畅所致。"}, {"source": "条7｜《心悸》三审稿·第四章评述（治疗原则·《灵枢》补虚泻实）", "原文": "《灵枢》中载：“虚则补之，盛则泻之，寒则留之，热则疾之，下则炙之，不虚不盛者，以经取之。”其确立了以补虚泻实为首要治则，为后世临床论治本病奠定了一定理论基础。", "白话": "《灵枢》中记载：“正气虚的就用补法，邪气盛的就用泻法；属寒的留针（久留），属热的疾刺（速出）；病位在下的用灸法；不虚不盛的，取本经腧穴治疗。”这确立了以补虚泻实为首要治疗原则，为后世临床论治本病奠定了一定的理论基础。"}, {"source": "条8｜《心悸》三审稿·第四章评述（治疗原则·《难经》调营卫）", "原文": "《难经》中则提出了：“损其心者，调其荣卫”的心悸治则。", "白话": "《难经》中则提出了“损其心者，调其荣卫”的心悸治疗原则。"}, {"source": "条9｜《心悸》三审稿·第四章评述（治疗原则·仲景辨证论治）", "原文": "仲景在《内经》基础上，对心悸病证有了进一步的认识，将理论与实践紧密结合，确定了心悸病证的辨证论治法则。", "白话": "张仲景在《内经》的基础上，对心悸病证有了进一步的认识，把理论与实践紧密结合，确立了心悸病证的辨证论治法则。"}, {"source": "条10｜《心悸》三审稿·第四章评述（治疗原则·《严氏济生方》虚寒证治）", "原文": "后世医家继承并有所发挥，如宋·严用和《严氏济生方》：“方其虚也，虚则生寒，寒则血脉虚少，时多恐畏，情绪不乐，心暴痛，时唾清涎，心膈胀闷，好忘多惊，梦寐飞扬，精神离散，其脉浮而虚者，是虚寒之候也……治之之法，热则清之，寒则温之，又当审其所自焉。”临证时当随其证，施以治法。", "白话": "后世医家继承并有所发挥，如宋代严用和《严氏济生方》说：“正当其虚的时候，虚就生寒，寒则血脉虚少，时时多恐惧畏惧、情绪不乐、心前暴痛、时唾清稀涎沫、心膈胀闷、健忘多惊、梦中飞扬不安、精神离散——其脉浮而虚的，是虚寒之候……治疗的方法：属热的就清，属寒的就温，又当审察其病因从何而来。”临证时当随其证，施以相应治法。"}, {"source": "条11｜《心悸》三审稿·第四章评述（补益法·心藏神与益气补血）", "原文": "《内经》谓“心藏神”，神以心为宿，心中气血为其保护，若心中气血亏损，失其保护之职，心中神明遂觉不能自主，故气血不足是导致心悸的主要病因，益气补血法为历代医家治疗心悸最重要治法之一。", "白话": "《内经》说“心藏神”，神以心为寄居之处，心气心血是它的护卫；如果心气心血亏损，失去护卫的职责，心中的神明便会觉得不能自主。所以气血不足是导致心悸的主要病因，益气补血法是历代医家治疗心悸最重要的治法之一。"}, {"source": "条12｜《心悸》三审稿·第四章评述（补益法·炙甘草汤证）", "原文": "《伤寒论·辨太阳病脉证并治》载：“伤寒脉结代，心动悸，炙甘草汤主之。”其证是由伤寒汗、吐、下或失血后或杂病阴血不足、阳气不振所致。治宜滋心阴，养心血，益心气，温心阳以复脉定悸。", "白话": "《伤寒论·辨太阳病脉证并治》记载：“伤寒病，脉来结代、心中动悸的，用炙甘草汤主治。”这种证候是由伤寒经汗、吐、下诸法（误治），或失血之后，或杂病阴血不足、阳气不振所致。治疗宜滋心阴、养心血、益心气、温心阳，以恢复脉律、止住悸动。"}, {"source": "条13｜《心悸》三审稿·第四章评述（补益法·《诸病源候论》心气不足）", "原文": "隋唐时期医家遵循补泻之旨，治疗上仍以补养气血为主，如《诸病源候论》卷十五：“心气不足，则胸腹大，胁下与腰背相引痛，惊悸，恍惚，少颜色，舌本强，善忧悲，是为心气之虚也，则宜补之。", "白话": "隋唐时期的医家遵循补泻的宗旨，治疗上仍以补养气血为主，如《诸病源候论》卷十五说：“心气不足，就会胸腹胀大、胁下与腰背相互牵引疼痛，惊悸、精神恍惚、面色少华、舌根僵硬、容易忧愁悲伤——这是心气的虚，就应当补它。”"}, {"source": "条14｜《心悸》三审稿·第四章评述（补益法·《和剂局方》诸虚门与《丹溪心法》血少）", "原文": "宋金元时期延续前代因虚致悸的学术论点并有所发挥，《和剂局方》治疗惊悸病症方子归卷五治诸虚门，包括定志圆、预知子圆、宁志膏、十四友圆、平补镇心丹等，朱震亨《丹溪心法》中论述：“觉心跳者是血少，四物、朱砂安神之类。", "白话": "宋金元时期延续前代“因虚致悸”的学术观点并有所发挥：《和剂局方》治疗惊悸病症的方子归在卷五“治诸虚门”，包括定志圆、预知子圆、宁志膏、十四友圆、平补镇心丹等；朱震亨《丹溪心法》中论述：“感觉心跳的是血少，用四物（汤）、朱砂安神（丸）之类。”"}, {"source": "条15｜《心悸》三审稿·第四章评述（补益法·《史载之方》产后心悸）", "原文": "此外，因女性产后多心悸，针对其气血两虚的特点，治疗产后心悸多补养气血、安神镇静，《史载之方》卷上载：“产后心虚中风，心中战栗，惊动不安，如人将捕，大府伤冷，六脉微而肝心脉偏细沉，又产后只缘肾气之虚寒，风邪所中，肾脉细而搏以沉，肾既受病传其所胜，心感肾邪非时惊悸，如人将捕，初以益心气去风邪药治之，次当补其肾，又次当益其肝，足其血，缘心受肾邪，而又肝气微弱，不能生其心气，故以三方药治之。", "白话": "此外，因妇女产后多见心悸，针对其气血两虚的特点，治疗产后心悸多用补养气血、安神镇静之法。《史载之方》卷上记载：“产后心虚又感受风邪，心中战栗、惊动不安，好像有人要抓捕自己，大府伤于冷，六脉微而肝、心脉偏于细沉；又有产后只因肾气虚寒、被风邪所中，肾脉细而搏指、位置沉——肾既然受病，就传给它所克的脏，心感受肾的邪气，不时惊悸、好像有人要抓捕自己。初起先用益心气、去风邪的药治疗，其次当补肾，再次当益肝、充足其血——因为心受肾邪，而又肝气微弱，不能生助心气，所以分三步用药治疗。”"}, {"source": "条16｜《心悸》三审稿·第四章评述（补益法·明清养血安神与虞抟）", "原文": "明清时期的医家多继承前人之说，诸家论心悸治疗以养血安神化痰为主，少数医家注重养阴抑火为治疗大法。如虞抟认为治疗归之“四物汤、安神丸之类”。", "白话": "明清时期的医家多继承前人之说，各家论心悸治疗以养血、安神、化痰为主，少数医家注重以养阴抑火为治疗大法。例如虞抟认为治疗归结于“四物汤、安神丸之类”。"}, {"source": "条17｜《心悸》三审稿·第四章评述（补益法·龚居中论血虚痰饮）", "原文": "明代龚居中认为，“盖心无血养，如鱼失水，惕然而跳跃也。时作时止者，以痰因火动，瘦人多是血虚，肥人多是痰饮，法宜先养心血，理其脾土，亦当幽闲安乐，制其忧虑，远其七情六淫则自安矣”。", "白话": "明代龚居中认为：“心没有血来滋养，就像鱼失去水，会惕然跳跃不安。时作时止的，是痰因火而动；瘦人多是血虚，肥人多是痰饮。治法宜先养心血、调理脾土；又应当幽静安乐，控制忧虑，远离七情六淫，就自然安好了。”"}, {"source": "条18｜《心悸》三审稿·第四章评述（补益法·陈士铎补肝制忡汤）", "原文": "清代医家陈士铎则认为心悸的治疗在补养气血的基础上应养肝润肺，在《辨证录》中指出：“心虚由于肝虚，肝虚则肺金必旺，以心弱不能制肺也；肺无火煅炼，则金必制木，肝不能生心，而心气益困。故补心必须补肝，而补肝尤宜制肺。然而肺不可制也，肺乃娇脏，用寒凉以制肺，必致伤损脾胃，肺虽制矣，而脾胃受寒，不能运化水谷，则肝又何所取资，而肾又何能滋益?所以肺不宜制而宜养也。方用制忡汤治之。", "白话": "清代医家陈士铎则认为，心悸的治疗应在补养气血的基础上兼养肝润肺，在《辨证录》中指出：“心虚是由于肝虚，肝虚则肺金必旺——因为心弱不能制约肺；肺没有火来煅炼，金就必会制约木，肝不能生助心，心气就愈发困顿。所以补心必须补肝，而补肝尤其应当制约肺。然而肺是不能‘制约’的：肺是娇脏，用寒凉去制约肺，必然损伤脾胃；肺虽被制约了，而脾胃受寒、不能运化水谷，那肝又从哪里取得资助，肾又怎能得到滋益？所以肺不宜制约而宜滋养。方用制忡汤治疗。”"}, {"source": "条19｜《心悸》三审稿·第四章评述（补益法·张锡纯定心汤升陷汤）", "原文": "近代医家张锡纯结合当时西医学对于心悸的认识，创制补气活血，兼敛心气的定心汤和补虚祛痰的安魂汤来治疗心悸，更创造性地提出“若脉沉迟无力者，其怔忡多因胸中大气下陷”，宜用升陷汤，开补气升陷法治心悸之先河。", "白话": "近代医家张锡纯结合当时西医学对心悸的认识，创制了补气活血、兼敛心气的定心汤和补虚祛痰的安魂汤来治疗心悸；更创造性地提出“若脉沉迟无力的，其怔忡多因胸中大气下陷”，宜用升陷汤——开补气升陷法治疗心悸的先河。"}, {"source": "条20｜《心悸》三审稿·第四章评述（补益心胆·《三因方》温胆汤）", "原文": "宋代陈无择《三因极一病证方论》载:：“温胆汤治心胆虚怯，触事易惊”，提出了心胆两虚证，并首选温胆汤作为治疗心悸的常用方。", "白话": "宋代陈无择《三因极一病证方论》记载：“温胆汤治心胆虚怯，遇事容易受惊”，提出了心胆两虚证，并首选温胆汤作为治疗心悸的常用方。"}, {"source": "条21｜《心悸》三审稿·第四章评述（补益心胆·严用和宁心壮胆）", "原文": "严用和发挥陈氏之说，在《济生方》中专立“惊悸怔忡健忘门”，认为惊悸为心虚胆怯所致，治法为宁心壮胆。", "白话": "严用和发挥陈氏之说，在《济生方》中专立“惊悸怔忡健忘门”，认为惊悸是心虚胆怯所致，治法为宁心壮胆。"}, {"source": "条22｜《心悸》三审稿·第四章评述（补益心胆·《辨证奇闻》补胆气）", "原文": "清代医家陈士铎在《辨证奇闻》中记载：“法徒补心则怔忡不能痊，补各脏腑而不补胆气，内无刚断之风，外有纷纭之扰，安望心之宁静乎？故必补胆气，后可去祛。”其指出怔忡需在补心气的同时补养胆气方能得治。", "白话": "清代医家陈士铎在《辨证奇闻》中记载：“若只是白白地补心，怔忡不能痊愈；补各脏腑而不补胆气，内无刚决果断之风，外有纷纭杂乱的干扰，怎能指望心神宁静呢？所以必须补胆气，之后才可以祛除（怔忡）。”他指出：怔忡需要在补心气的同时补养胆气，才能治愈。"}, {"source": "条23｜《心悸》三审稿·第四章评述（温补心阳·总说）", "原文": "心为阳中之太阳，是一身阳气之主，心阳在心主血脉和心主神明的功能中也是占据主导地位，心阳不足是心悸发生的重要原因，张仲景在心悸的治疗中首重温补心阳。", "白话": "心是阳中的太阳，是一身阳气的主宰；心阳在“心主血脉”和“心主神明”的功能中也占主导地位。心阳不足是心悸发生的重要原因，张仲景在心悸的治疗中首重温补心阳。"}, {"source": "条24｜《心悸》三审稿·第四章评述（温补心阳·桂枝甘草汤）", "原文": "如《伤寒论·辨太阳病脉证并治》载：“发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之。", "白话": "如《伤寒论·辨太阳病脉证并治》记载：“发汗过多，病人双手交叉按护在心前区，心下悸动、想要按压的，用桂枝甘草汤主治。”"}, {"source": "条25｜《心悸》三审稿·第四章评述（温补心阳·救逆汤）", "原文": "伤寒脉浮，医以火迫劫之，亡阳，必惊狂，卧起不安者，桂枝去芍药加蜀漆牡蛎龙骨救逆汤主之。”采用桂枝甘草汤作为治疗发汗过多，内伤心阳以致心中动悸者治以温补心阳以治疗心悸的基础方，若因发汗过多致亡阳，心神浮越或火邪亡阳致悸，病情较重者则当与桂枝去芍药加蜀漆牡砺龙骨救逆汤。", "白话": "同篇又载：“伤寒脉浮，医生用火法逼迫发汗，以致亡阳，必然惊狂、坐卧不安的，用桂枝去芍药加蜀漆牡蛎龙骨救逆汤主治。”（临床）采用桂枝甘草汤作为治疗发汗过多、内伤心阳以致心中动悸的基础方，以温补心阳；若因发汗过多致亡阳、心神浮越，或火邪亡阳致悸、病情较重的，则当用桂枝去芍药加蜀漆牡蛎龙骨救逆汤。"}, {"source": "条26｜《心悸》三审稿·第四章评述（温补脾肾·真武汤小建中汤）", "原文": "温阳是张仲景治疗心悸的重要治法，其在补益心阳的同时，亦重视温补脾肾，多用真武汤治疗肾阳不足、水饮凌心导致的心悸，小建中汤治疗中焦虚寒所致的心悸。", "白话": "温阳是张仲景治疗心悸的重要治法。他在补益心阳的同时，也重视温补脾肾：多用真武汤治疗肾阳不足、水饮凌心导致的心悸，用小建中汤治疗中焦虚寒所致的心悸。"}, {"source": "条27｜《心悸》三审稿·第四章评述（温补脾肾·张景岳益火之源）", "原文": "明代张景岳在《妇人规》中也强调了真阳不足导致心悸应“速宜益火之源，以培右肾之元阳”。", "白话": "明代张景岳在《妇人规》中也强调：真阳不足导致的心悸，应当“速宜温益阳气之源，以培补右肾的元阳”。"}, {"source": "条28｜《心悸》三审稿·第四章评述（温补脾肾·戴天章从脾论治）", "原文": "清代戴天章延续前人观点，认为阳虚所致心悸，其病位在脾，故多从脾论治，《广瘟疫论》卷二载：“阳虚则呕利、悸眩之证多，责在脾，宜六君子汤。", "白话": "清代戴天章延续前人观点，认为阳虚所致的心悸，其病位在脾，故多从脾论治；《广瘟疫论》卷二记载：“阳虚则呕吐下利、悸眩等证为多，病责在脾，宜用六君子汤。”"}, {"source": "条29｜《心悸》三审稿·第四章评述（回阳救逆·俞根初）", "原文": "清代俞根初先生根据《黄帝内经》中对“亡阳之重证”的论述并结合心悸等临床症状提出以回阳救逆为治疗原则，以附子、生姜为君，茯苓、白术为臣，佐以白芍回阳摄阴的治疗方案，此法至今仍被后世医家沿用以治疗心悸亡阳的危急重症。", "白话": "清代俞根初先生根据《黄帝内经》中对“亡阳重证”的论述，结合心悸等临床症状，提出以回阳救逆为治疗原则：以附子、生姜为君药，茯苓、白术为臣药，佐以白芍回阳摄阴。此法至今仍被后世医家沿用，以治疗心悸亡阳的危急重症。"}, {"source": "条30｜《心悸》三审稿·第四章评述（扶正祛风·《诸病源候论》风惊悸候）", "原文": "风为百病之长，风邪导致惊悸在隋代巢元方《诸病源候论》中即有论述，专列风惊悸候言明“风惊悸者，由体虚，心气不足，心之府为风邪所乘”。", "白话": "风为百病之长，风邪导致惊悸在隋代巢元方《诸病源候论》中即有论述：书中专列“风惊悸候”，说明“风惊悸，是由于体虚、心气不足，心之腑被风邪所乘袭”。"}, {"source": "条31｜《心悸》三审稿·第四章评述（扶正祛风·《千金要方》风药定悸）", "原文": "唐代孙思邈《备急千金要方》“风虚惊悸”门中方剂善用风药祛风定悸。", "白话": "唐代孙思邈《备急千金要方》“风虚惊悸”门中的方剂，善用风药来祛风定悸。"}, {"source": "条32｜《心悸》三审稿·第四章评述（扶正祛风·《圣济总录》虚挟风）", "原文": "宋代由太医院编制的《圣济总录》在一百八十六卷中记载：“风者百病之始，清净则肉膝闭拒，虽有大风苛毒，弗之能害，体虚之人，本脏亏耗，风邪易乘，其证或心神惊悸，手足颤掉，筋脉拘急。凡此之类，皆因虚挟夹风所致，法宜于补药中，加以治风之剂。", "白话": "宋代由太医院编纂的《圣济总录》在一百八十六卷中记载：“风是百病的起始；（人若）清净养正，则腠理闭密拒邪，即使有大风苛毒，也不能伤害；体虚之人，本脏亏耗，风邪容易乘袭，其证或心神惊悸、手足颤摇、筋脉拘急。凡此之类，都因虚夹风所致，治法宜在补药中，加入治风之剂。”"}, {"source": "条33｜《心悸》三审稿·第四章评述（扶正祛风·小结）", "原文": "书中内容集前代人以风、虚立论，强调心悸病机内多见体虚气血不足，外则多因风邪所伤而致，治法偏重于补气血扶正气，兼以祛风。", "白话": "书中内容汇集前人以风、虚立论的观点，强调心悸的病机：内多见体虚气血不足，外多因风邪所伤而致；治法偏重于补气血、扶正气，兼以祛风。"}, {"source": "条34｜《心悸》三审稿·第四章评述（清热泻火·《内经》火热致悸）", "原文": "《黄帝内经》认为心悸的发生与火热之邪相关，如《素问·至真要大论》：“诸禁鼓傈栗，如丧神守，皆属于火”，至金元时期刘完素倡“火热论”，进一步强调了这一病因。", "白话": "《黄帝内经》认为心悸的发生与火热之邪相关，如《素问·至真要大论》说：“各种口噤、鼓颔战栗，好像神守不住的病，都属于火。”到金元时期，刘完素倡“火热论”，进一步强调了这一病因。"}, {"source": "条35｜《心悸》三审稿·第四章评述（清热泻火·刘完素《原病式》）", "原文": "如《素问玄机原病式》中说:：“心胸躁动，谓之怔忡，俗云心忪，皆为热也。", "白话": "如《素问玄机原病式》中说：“心胸躁动，叫作怔忡，俗称心忪，都是热所致。”"}, {"source": "条36｜《心悸》三审稿·第四章评述（清热泻火·《保命集》制火之剂）", "原文": "其又在《素问病机气宜保命集·病机论》提出了心悸的治法：“禁栗傈惊感，如丧神守，悸动怔松，皆热之内作。故治当以制火之剂，其神守血荣而愈也。", "白话": "他又在《素问病机气宜保命集·病机论》中提出心悸的治法：“口噤战栗、惊恐惑乱，好像神守不住，悸动怔忪，都是热在内发作。所以治疗当用制火之剂，使其神守安定、血液荣润而痊愈。”"}, {"source": "条37｜《心悸》三审稿·第四章评述（清热泻火·《丹溪手镜》下火）", "原文": "朱丹溪在《丹溪手镜》中提出：“治惊悸癫痫狂妄……火则下之。", "白话": "朱丹溪在《丹溪手镜》中提出：“治惊悸、癫痫、狂妄……属火的就用下法（泻下）。”"}, {"source": "条38｜《心悸》三审稿·第四章评述（清热泻火·《血证论》胃火上攻）", "原文": "唐容川在朱丹溪理论的基础上补充了惊悸怔忡形成的原因和治疗方法，他在《血证论》中提出：“胃火强梁，上攻于心而跳跃者，其心下如筑墙然，听之有声，以手按其心下，复有气来抵拒，此为心下有动气，治宜大泻心胃之火，火平则气平也，泻心汤主之，或玉女煎加枳壳、厚朴、代赭石、旋覆花以降之，再加郁金、莪术以攻之，使血、气、火三者皆平，自不强梁矣。", "白话": "唐容川在朱丹溪理论的基础上，补充了惊悸怔忡形成的原因和治疗方法，他在《血证论》中提出：“胃火强梁，上攻于心而使人跳跃（悸动）的，其心下好像筑墙一样，听之有声；用手按其心下，又有气来抵拒——这是心下有动气。治疗宜大泻心胃之火，火平则气也平，用泻心汤主治；或用玉女煎加枳壳、厚朴、代赭石、旋覆花以降逆，再加郁金、莪术以攻逐，使血、气、火三者都平，自然就不再强梁了。”"}, {"source": "条39｜《心悸》三审稿·第四章评述（清热泻火·泻心降胃小结）", "原文": "明确指出惊悸是心胃之火导致，胃火上攻于心致使心悸跳动不安，并提出泻心火降胃火的治疗原则。", "白话": "（该段）明确指出惊悸是心、胃之火所致：胃火上攻于心，致使心悸跳动不安，并提出泻心火、降胃火的治疗原则。"}, {"source": "条40｜《心悸》三审稿·第四章评述（滋阴降火·李东垣朱砂安神丸）", "原文": "元代李东垣擅长用滋阴清热法治疗心悸，他认为治疗“宜用权衡法，以镇阴火之浮越，以养上焦之元气”，并在《兰室秘藏》中立方朱砂安神丸治疗血虚心悸。", "白话": "元代李东垣擅长用滋阴清热法治疗心悸，他认为治疗“宜用权衡（斟酌）之法，以镇摄阴火的浮越，以养护上焦的元气”，并在《兰室秘藏》中立朱砂安神丸一方，治疗血虚心悸。"}, {"source": "条41｜《心悸》三审稿·第四章评述（滋阴降火·方隅养血降火）", "原文": "明代方隅延续李东垣的治疗思想，在《医林绳墨》中言：“怔者血之虚，忡者火之盛，养血则怔自安，降火则忡自定”，用养血清火法以定惊悸。", "白话": "明代方隅延续李东垣的治疗思想，在《医林绳墨》中说：“怔是血的虚，忡是火的盛；养血则怔自安，降火则忡自定。”用养血清火法来安定惊悸。"}, {"source": "条42｜《心悸》三审稿·第四章评述（滋阴降火·张景岳壮水）", "原文": "张景岳亦十分注重滋阴壮水法的使用，其治疗心悸慌张者常使用纯甘壮水之剂以填补真阴。", "白话": "张景岳也很注重滋阴壮水法的使用，他治疗心悸慌张的患者，常用纯甘壮水之剂来填补真阴。"}, {"source": "条43｜《心悸》三审稿·第四章评述（交通心肾·王肯堂）", "原文": "明代王肯堂在总结前人治疗心悸经验的基础上，结合自己的临床经验认为，肾水不能上奉于心，水不济火，或心火内炽，不能下交于肾，则为心悸怔忡、失眠心烦等症，治法当交通心肾。", "白话": "明代王肯堂在总结前人治疗心悸经验的基础上，结合自己的临床经验认为：肾水不能上奉于心、水不济火，或心火内炽、不能下交于肾，就会发生心悸怔忡、失眠心烦等症，治法当交通心肾。"}, {"source": "条44｜《心悸》三审稿·第四章评述（交通心肾·《幼科证治准绳》补肾）", "原文": "《幼科证治准绳》中记载：“治惊不若补肾。谓心属火，火性燥，得肝风则烟焰起，致生惊悸，补肾则水升火降，邪热无侵，虽有肝风，不生惊骇。", "白话": "《幼科证治准绳》中记载：“治惊不如补肾。说心属火，火性燥，得肝风相助则烟焰升起，导致惊悸；补肾则水升火降，邪热无从侵袭，虽有肝风，也不生惊骇。”"}, {"source": "条45｜《心悸》三审稿·第四章评述（交通心肾·《景岳全书》心本乎肾）", "原文": "张介宾在《景岳全书》中亦提到“凡治怔忡惊恐者，虽有心脾肝肾之分，然阳统乎阴，心本乎肾。所以上不宁者，未有不由乎下，心气虚者，未有不因乎精。然心肝脾肾之气名虽有异，而治不可有离者，亦以精气互根之宜然而君相相资之全力也。”对临床证治起到了提纲掣领的指导作用。", "白话": "张介宾在《景岳全书》中也提到：“凡治疗怔忡惊恐之病，虽有心、脾、肝、肾的区分，然而阳统摄于阴，心根源于肾。所以上部不安宁的，没有不是由于下部（不足）；心气虚的，没有不是因为精（虚）。心、肝、脾、肾之气名称虽有不同，而治疗不可分离——这也是因为精气互根是自然之理，而君火相火相互资助是完整的功能。”对临床证治起到了提纲挈领的指导作用。"}, {"source": "条46｜《心悸》三审稿·第四章评述（交通心肾·陈士铎心肾两交汤）", "原文": "陈士铎在传统交通心肾治法的基础上，从整体着眼，将心肾相交理论扩展为本脏交济和上下交济，并将交通心肾的治法从传统的只着眼于心肾扩展为在心、肾基础上，综合治疗脾胃肝胆诸脏的治法，在其基础上，组方心肾两交汤。该方以大滋肾水为主，同时滋养心气心血，兼能濡养肝血。如《辨证录》卷四载：“人有得怔忡之症，日间少轻，至夜则重，欲思一睡熟而不可得者，人以为心虚之极也，谁知是肾气之乏乎。？凡人夜卧则心气必下降于肾宫，", "白话": "陈士铎在传统交通心肾治法的基础上，从整体着眼，把心肾相交理论扩展为“本脏交济”和“上下交济”，并将交通心肾的治法从传统的只着眼心肾，扩展为在心、肾基础上综合治疗脾胃肝胆诸脏；在此基础上组方心肾两交汤。该方以大滋肾水为主，同时滋养心气心血，兼能濡养肝血。如《辨证录》卷四记载：“有人患怔忡之症，白天稍轻，到夜里就加重，想睡熟一觉而不可得：人们以为是心虚到了极点，谁知是肾气匮乏呢？凡人夜晚躺卧，则心气必下降于肾宫；只是肾水大耗，一如家贫，客人来了无力接待，客人见主人窘迫，自然不可久"}, {"source": "条47｜《心悸》三审稿·第四章评述（理气化痰·仲景痰饮致悸）", "原文": "汉代张仲景在《伤寒论》中即提出了“痰饮致悸”的观点，历代医家都对痰饮致悸的病机和治法进行了研究和阐释。", "白话": "汉代张仲景在《伤寒论》中就提出了“痰饮致悸”的观点，历代医家都对痰饮致悸的病机和治法进行了研究与阐释。"}, {"source": "条48｜《心悸》三审稿·第四章评述（理气化痰·《仁斋直指方》豁痰定惊）", "原文": "宋代杨士瀛《仁斋直指方》延续《伤寒论》的观点，认为惊悸由于心虚郁痰，可从痰饮论治的观点，应“与之豁痰定惊之剂”。", "白话": "宋代杨士瀛《仁斋直指方》延续《伤寒论》的观点，认为惊悸是由于心虚郁痰、可以从痰饮论治，应当“给予豁痰定惊之剂”。"}, {"source": "条49｜《心悸》三审稿·第四章评述（理气化痰·《古今医鉴》胆涎沃心）", "原文": "明代龚信在认为“胆涎沃心”是心悸的重要病机，应用理气化痰法治之，其在《古今医鉴》中言：“惊悸、健忘、怔忡、失志不寐、心风，皆是胆涎沃心，以致心气不足。若用凉剂太过，则心火愈微，痰涎愈盛，而病益深，宜理痰气。”。", "白话": "明代龚信认为“胆涎沃心”是心悸的重要病机，应当用理气化痰法治疗；他在《古今医鉴》中说：“惊悸、健忘、怔忡、失志不寐、心风，都是胆涎浸渍于心，以致心气不足。如果用凉剂太过，则心火愈加微弱、痰涎愈加壅盛，而病愈加深重——宜理痰气。”"}, {"source": "条50｜《心悸》三审稿·第四章评述（理气化痰·《张氏医通》理痰顺气）", "原文": "清代医家张璐延续前人观点，在所著的《张氏医通》中提出“盖惊悸健忘失志心风不寐。皆是痰涎沃心。以致心气不足。若凉心太过。则心火愈微。痰涎愈盛。惟唯以理痰顺气为第一义”，强调了理气化痰法治疗心悸的重要性。", "白话": "清代医家张璐延续前人观点，在所著《张氏医通》中提出：“凡惊悸、健忘、失志、心风、不寐，都是痰涎沃心，以致心气不足。若凉心太过，则心火愈微、痰涎愈盛；唯有以理痰顺气为第一要义。”强调了理气化痰法治疗心悸的重要性。"}, {"source": "条51｜《心悸》三审稿·第四章评述（清热化痰·《济生方》痰火扰心）", "原文": "宋代严用和在《济生方·惊悸论治》中指出：“惊悸者……化火生痰，痰火扰心，心神失养而心悸。", "白话": "宋代严用和在《济生方·惊悸论治》中指出：“惊悸……化火生痰，痰火扰乱心神，心神失于滋养而发生心悸。”"}, {"source": "条52｜《心悸》三审稿·第四章评述（清热化痰·《丹溪心法》痰因火动）", "原文": "朱丹溪在《丹溪心法·惊悸怔忡》亦指出:：“时作时止者,痰因火动。”可见，痰火扰心是导致心悸的重要病因。", "白话": "朱丹溪在《丹溪心法·惊悸怔忡》中也指出：“时作时止的，是痰因火而动。”可见，痰火扰心是导致心悸的重要病因。"}, {"source": "条53｜《心悸》三审稿·第四章评述（清热化痰·《万病回春》清痰补虚）", "原文": "明代医家龚廷贤在《万病回春》中明确指出清热化痰以治心悸：“惊悸属痰火而兼气虚者，宜清痰火以补虚也。", "白话": "明代医家龚廷贤在《万病回春》中明确指出用清热化痰以治疗心悸：“惊悸属痰火而又兼气虚的，宜清痰火以补虚。”"}, {"source": "条54｜《心悸》三审稿·第四章评述（清热化痰·《古今名医荟萃》治邪解郁）", "原文": "清代医家罗美在《古今名医荟萃》第六卷中提出“若内外诸邪郁其二火，不得发越，隔绝营卫，不得充养其正气者，则皆以治邪解郁为主”的治疗方法，意在通过清热解郁祛热痰以治疗心悸；", "白话": "清代医家罗美在《古今名医荟萃》第六卷中提出“若内外诸邪郁遏其二火，不能发越，隔绝营卫，不能充养其正气的，则都以治邪解郁为主”的治疗方法，意在通过清热解郁、祛热痰来治疗心悸。"}, {"source": "条55｜《心悸》三审稿·第四章评述（清热化痰·《重订广温热论》余热挟痰）", "原文": "戴天章在《重订广温热论》第一卷中提出：“凡温热新瘥，触事易惊，梦寐不安者，余热挟夹痰也”，并通过运用竹茹、黄连、石菖蒲等药物以清余热而消痰为治疗大法治疗惊悸。", "白话": "戴天章在《重订广温热论》第一卷中提出：“凡温热病新愈，遇事容易受惊、梦寐不安的，是余热夹痰所致。”并用竹茹、黄连、石菖蒲等药物，以清余热、消痰为治疗大法来治疗惊悸。"}, {"source": "条56｜《心悸》三审稿·第四章评述（温阳化饮·《伤寒明理论》心悸两因）", "原文": "金元医家成无己在《伤寒明理论》中概括心悸病机为：“心悸之由，不越两种，一者气虚也，二者停饮也。”可见痰饮是导致心悸的重要病机。", "白话": "金元医家成无己在《伤寒明理论》中概括心悸病机为：“心悸的由来，不超出两种：一是气虚，二是停饮。”可见痰饮是导致心悸的重要病机。"}, {"source": "条57｜《心悸》三审稿·第四章评述（温阳化饮·仲景温阳化饮）", "原文": "痰饮为阴邪，易阻遏阳气，同时阴邪最易伤人阳气，阳气被伤则寒饮易停聚体内，张仲景治疗心悸首重温阳化饮，创制了真武汤、茯苓甘草汤等方以振奋阳气则痰饮自除。", "白话": "痰饮是阴邪，容易阻遏阳气；同时阴邪最易损伤人的阳气，阳气受伤则寒饮容易停聚体内。张仲景治疗心悸首重温阳化饮，创制了真武汤、茯苓甘草汤等方，以振奋阳气，痰饮自除。"}, {"source": "条58｜《心悸》三审稿·第四章评述（温阳化饮·《丹溪手镜》治悸先治饮）", "原文": "朱丹溪在继承仲景思想的基础上，提出” “百病兼痰”“的论点，针对痰饮导致的惊悸怔忡，其在《丹溪手镜》遵循仲景之法，认为“有停饮者，饮水多必心下悸，心火恶水，心不安也。凡治悸者，必先治饮，以水停心下，散而无所不至。浸于肺则喘咳，浸于胃则哕噎，溢于皮肤则肿，渍于肠间则利下，可以茯苓甘草汤治之。", "白话": "朱丹溪在继承仲景思想的基础上，提出“百病兼痰”的论点。针对痰饮导致的惊悸怔忡，他在《丹溪手镜》中遵循仲景之法，认为：“有停饮的，饮水多必致心下悸——心火恶水，心不安也。凡治悸者，必先治饮，因为水停心下，散行而无处不到：浸渍于肺则喘咳，浸渍于胃则呃逆噎塞，泛溢于皮肤则浮肿，浸渍于肠间则下利——可以用茯苓甘草汤治疗。”"}, {"source": "条59｜《心悸》三审稿·第四章评述（温阳化饮·明清诸书记载）", "原文": "明清医家继承了这一观点，在《叶氏医效秘传》《杂病广要》《医法圆通》等书中均有温阳利水法治疗水停心下心悸的记载。", "白话": "明清医家继承了这一观点，《叶氏医效秘传》《杂病广要》《医法圆通》等书中都有关于用温阳利水法治疗水停心下所致心悸的记载。"}, {"source": "条60｜《心悸》三审稿·第四章评述（安神法·心藏神肝藏魂）", "原文": "心藏神，肝藏魂，若肝不藏魂，则神魂不安，略受惊扰便会导致心悸不宁。因此心悸始于心神不安，但其发作与肝风内动密切相关，故应以平肝潜阳、重镇安神为治法。", "白话": "心藏神、肝藏魂；如果肝不藏魂，则神魂不安，稍受惊扰就会导致心悸不宁。因此心悸始于心神不安，但其发作与肝风内动密切相关，故应以平肝潜阳、重镇安神为治法。"}, {"source": "条61｜《心悸》三审稿·第四章评述（安神法·刘完素重镇）", "原文": "刘完素对心悸的治疗明确提出了“重剂以镇之”的治法，《素问病机气宜保命集》言：“怯则气浮，欲其镇也。如丧神守而惊悸，气上厥以颠疾，必重剂以镇之，《本草》日曰‘重可去怯’，即磁石、铁粉之属。经所谓‘厥成为颠疾’，故惊乃平之，所以镇涎也，故使其物体之重，则下涎而用之也”，其结合前人对心悸的治疗手段并加以延伸，进一步完善了心悸治法的内容。", "白话": "刘完素对心悸的治疗明确提出了“用重剂来镇之”的治法。《素问病机气宜保命集》说：“怯弱则气浮，要使它镇定；如神守不住而惊悸、气上逆而成癫疾，必用重剂来镇之。《本草》说‘重可去怯’，就是磁石、铁粉之类。经书所谓‘厥逆成为癫疾’，所以惊要平抑，用以镇痰涎；故取其物质之重，使痰涎下行而用它。”他结合前人对心悸的治疗手段并加以延伸，进一步完善了心悸治法的内容。"}, {"source": "条62｜《心悸》三审稿·第四章评述（安神法·流布）", "原文": "其后《普济方》《证治汇补》《增订通俗伤寒论》等书均有使用重镇安神法治疗心悸的记载，成为治疗心悸的主要治法之一沿用至今。", "白话": "其后《普济方》《证治汇补》《增订通俗伤寒论》等书都有关于使用重镇安神法治疗心悸的记载，此法成为治疗心悸的主要治法之一，沿用至今。"}, {"source": "条63｜《心悸》三审稿·第四章评述（理气法·《医林绳墨》安心顺气）", "原文": "明代医家方隅结合《黄帝内经》、仲景学说并参考金元诸家之论，结合己见提出以行气解郁法治疗心悸，方隅在所著的《医林绳墨》惊悸篇写到：“治惊莫若安心，治悸莫若顺气，心气既宁，惊悸必除。", "白话": "明代医家方隅结合《黄帝内经》、仲景学说并参考金元诸家之论，结合己见提出以行气解郁法治疗心悸；方隅在所著《医林绳墨》惊悸篇写道：“治惊莫如安心，治悸莫如顺气；心气既然安宁，惊悸必然除去。”"}, {"source": "条64｜《心悸》三审稿·第四章评述（理气法·《证治汇补》气郁舒畅）", "原文": "《证治汇补》中亦指出惊悸属气郁者应舒畅之。", "白话": "《证治汇补》中也指出：惊悸属气郁的，应当予以舒畅（疏利气机）。"}, {"source": "条65｜《心悸》三审稿·第四章评述（活血法·《医林改错》血府逐瘀汤）", "原文": "清代王清任著《医林改错》，创制一系列活血化瘀名方，提出用活血化瘀法治疗心悸，《医林改错》在血府逐瘀汤所治证目章中提到：“心跳心忙，用归脾安神等方不效，用此方百发百中。", "白话": "清代王清任著《医林改错》，创制了一系列活血化瘀名方，提出用活血化瘀法治疗心悸；《医林改错》在“血府逐瘀汤所治证目”章中提到：“心跳心忙（心慌），用归脾（汤）、安神等方不见效的，用此方百发百中。”"}, {"source": "条66｜《心悸》三审稿·第四章评述（活血法·因瘀致悸小结）", "原文": "以方测证，王清任不仅提出了因瘀致悸的病机认识，并创制血府逐瘀汤治疗心悸每多获效，至今仍为临床治疗心悸的常用方剂。", "白话": "以方测证：王清任不仅提出了因瘀致悸的病机认识，而且创制血府逐瘀汤治疗心悸，每多获效；至今仍是临床治疗心悸的常用方剂。"}, {"source": "条67｜《心悸》三审稿·第四章评述（小结·治则治法源流四期）", "原文": "关于心悸治则治法的论述始于秦汉时期，《内经》《难经》提出补虚泻实、调和营卫的基本治疗原则，《伤寒杂病论》论述了心悸的具体治法，并注重温阳化饮法的应用；成长于隋唐时期，医家治疗心悸循补泻之理，补虚祛风并重；发展于宋金元时期，医家以益气养血、理气化痰、滋阴抑火、重镇安神，互为补充；成熟于明清时期，医家总结了前人的论治心悸的经验，并补充“活血化瘀”“补气升陷”等治法，中医治疗心悸的治疗法则臻于全面。这些", "白话": "关于心悸治则治法的论述始于秦汉时期：《内经》《难经》提出补虚泻实、调和营卫的基本治疗原则，《伤寒杂病论》论述了心悸的具体治法，并注重温阳化饮法的应用。成长于隋唐时期：医家治疗心悸遵循补泻之理，补虚与祛风并重。发展于宋金元时期：医家以益气养血、理气化痰、滋阴抑火、重镇安神诸法互为补充。成熟于明清时期：医家总结了前人论治心悸的经验，并补充“活血化瘀”“补气升陷”等治法，中医治疗心悸的治疗法则臻于全面。这些灵活的论治思路、丰富的治疗方法，至今仍很好地指导着我们的临床实践；大部分作为"}, {"source": "万病回春心悸条文注释｜一、怔忡总论——心无血养、如鱼无水", "原文": "怔忡者，心无血养，如鱼无水，心中惕惕然而跳动也，如人将捕捉之貌。若思虑即心跳者，是血虚也。", "白话": "怔忡是**心失去血的滋养，像鱼离开水**，心中惕惕跳动、像有人要抓自己。若一思虑就心跳的，是**血虚**。"}, {"source": "万病回春心悸条文注释｜二、四物安神汤——怔忡主方（兼服辰砂安神丸）", "原文": "四物安神汤** 治心中无血养，故作怔忡。兼服辰砂安神丸。\n> 当归（酒洗） 白芍（酒炒） 生地黄（酒洗） 熟地黄 人参（去芦） 白术（去芦） 茯神（去皮木） 酸枣仁（炒） 黄连（姜炒） 栀子（炒） 麦门冬（去心） 竹茹 辰砂（研末，临服调入） 乌梅（一个）\n> 上锉一剂。枣二枚，炒米一撮，水煎，食远服。", "白话": "治心无血养而成怔忡。药用当归（酒洗）、白芍（酒炒）、生地、熟地、人参、白术、茯神、炒枣仁、姜炒黄连、炒栀子、麦冬、竹茹、辰砂（研末临服调入）、乌梅一个；切一剂，加大枣二枚、炒米一撮，水煎，食远服。另兼服辰砂安神丸。"}, {"source": "万病回春心悸条文注释｜三、怔忡分路——时跳时止（痰火）与心慌神乱（血虚火动）", "原文": "心若时跳时止者，是痰因火动也。二陈汤治痰因火动作怔忡（方见痰症）。根据本方加枳实、麦冬、竹茹、炒黄连、炒山栀、人参、白术、当归、辰砂、乌梅、竹沥、姜三片、枣一枚，水煎，用辰砂末调服。\n> 心慌神乱者，血虚火动也。**朱砂安神丸** 治血虚心烦懊 、惊悸怔忡、胸中气乱。朱砂（另研末，水飞过，二钱） 当归（酒洗净，二钱半） 生地黄（酒洗，一钱五分） 黄连（酒洗，炒，六钱） 甘草（炙，二钱半）", "白话": "心跳**时跳时止**的，是痰因火动——二陈汤加枳实、麦冬、竹茹、炒连、炒栀、人参、白术、当归、辰砂、乌梅、竹沥、姜枣煎，辰砂末调服。心慌神乱的，是血虚火动——朱砂安神丸（朱砂二钱水飞、当归二钱半、生地一钱五分、黄连酒炒六钱、炙草二钱半；一方加人参白术茯苓枣仁麦冬等分），炼蜜丸如黍米大，每服五十丸，食远米汤下。"}, {"source": "万病回春心悸条文注释｜四、惊悸门——养血安神汤与安神镇惊丸", "原文": "脉：惊悸怔忡，寸动而弱；寸紧胃浮，悸病乃作；饮食痰火，伏动滑搏；浮微弦濡，忧惊过怯；健忘神亏，心虚浮薄。\n> 惊悸者，忽然惊惕而不安也。惊悸属血虚火动者，宜养心以清火也。\n> **养血安神汤** 当归身（五分，酒洗） 川芎（五分） 白芍（炒，五分） 生地黄（酒洗，一钱） 陈皮（五分） 白术（七分） 茯神（一钱） 酸枣仁（七分，炒） 柏子仁（五分，炒） 黄连（五分，酒炒） 甘草（炙，三分）上锉一剂。", "白话": "脉法同前（寸动而弱等）。惊悸是**忽然惊惕不安**；属血虚火动者，宜养心清火。养血安神汤：当归身、川芎、炒白芍各五分，生地一钱，陈皮五分，白术七分，茯神一钱，炒枣仁七分，炒柏子仁五分，酒炒黄连五分，炙草三分，水煎服。安神镇惊丸治血虚心神不安、惊悸怔忡不寐：上十三味为末，炼蜜丸绿豆大，每服五十丸，食远枣汤下。"}, {"source": "万病回春心悸条文注释｜五、惊悸三路——温胆汤（本院版）与重镇诸丸", "原文": "惊悸属痰火而兼气虚者，宜清痰火以补虚也。**温胆汤** 治痰火而惊惕不眠。人参 白术（去芦） 茯神（去皮木） 当归（酒洗） 生地黄（酒洗） 酸枣仁（炒） 麦门冬 半夏（姜汁炒） 枳实（麸炒） 黄连（酒炒） 竹茹 山栀（炒，各等分） 甘草（三分） 辰砂（五分临服研末调入）上锉一剂。姜一片，枣一枚，乌梅一个，竹沥调辰砂末服。\n> 惊悸属心虚、气虚而有痰者，宜安神补虚以化痰也。**益气安神汤**……**", "白话": "惊悸属**痰火兼气虚**者，清痰火兼补虚——温胆汤（本院版）：人参、白术、茯神、当归、生地、枣仁、麦冬、半夏、枳实、黄连、竹茹、山栀各等分，甘草三分、辰砂五分临服调入，姜枣乌梅煎、竹沥调辰砂服。属**心虚气虚有痰**者，安神补虚化痰——益气安神汤（当归茯神黄连麦冬枣仁远志参芪胆星竹叶小草生地）；琥珀定志丸（南星琥珀辰砂人乳楝参二苓菖蒲远志）；辰砂宁志丸治**劳神过度伤心血**，惊悸怔忡、梦寐不宁、若有人捕捉，渐成心疾甚至癫狂。"}, {"source": "万病回春心悸条文注释｜六、健忘门——★归脾汤（十味各一钱制）与状元丸", "原文": "归脾汤** 治脾经失血，少寐，发热盗汗；或思虑伤脾，不能摄血，以致妄行或健忘怔忡、惊悸不寐；或心脾伤痛、嗜卧少食；或忧思伤脾、血虚发热；或肢体作痛、大便不调；或经候不准、晡热内热；或瘰 流注，不能消散溃敛。\n> 人参 白术 黄 （炒） 白茯苓（去皮） 龙眼肉 当归 远志（甘草泡去心） 酸枣仁（炒，各一钱） 木香 甘草（炙，各五分）上锉一剂。生姜三片，枣一枚，水煎服。本方加柴胡、山栀，名加味归脾汤。", "白话": "归脾汤治脾经失血、少寐、发热盗汗；或思虑伤脾不能摄血而妄行，或健忘怔忡、惊悸不寐；或心脾伤痛、嗜卧少食；或忧思伤脾、血虚发热；或肢体痛、大便不调；妇女经期不准、午后内热、瘰疬流注不消不敛。人参、白术、黄芪（炒）、茯神〔原文作白茯苓〕、龙眼肉、当归、远志（甘草泡去心）、炒枣仁各一钱，木香、炙甘草各五分；姜三片枣一枚水煎。加柴胡、山栀名**加味归脾汤**。状元丸补心生血、宁神定志、清火化痰，治勤政读书辛苦之健忘怔忡不寐（人参二钱、茯神枣仁当归各三钱、麦冬远志龙眼生地玄参朱砂菖蒲各"}, {"source": "世医得效方心恙门条文注释｜一、十味温胆汤（**原方**·心恙门）", "原文": "十味温胆汤** 治**心胆虚怯，触事易惊，梦寐不祥，异象感惑，遂致心惊胆慑，气郁生涎**，涎〔与气搏〕变生诸证。或**短气悸乏**，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。\n> 半夏（汤洗七次）、枳实（去穣，切，麸炒）、陈皮（去白。各三两）；白茯苓（去皮，一两半）；酸枣仁（微炒）、大远志（去心，甘草水煮，姜汁炒，一两）、北五味子、熟地黄（切，酒炒）、条参（各一两）、粉草（五钱）。\n> 上", "白话": "治心胆虚怯、遇事易惊、噩梦纷纭，气郁生痰变生诸证；或短气心慌乏力、自汗、四肢浮肿、纳差、心虚烦闷、坐卧不安。组成：半夏、枳实、陈皮各三两，茯苓一两半，酸枣仁、远志各一两，五味子、熟地、条参（人参）各一两，炙甘草五钱。煮散每服四钱，姜枣煎。"}, {"source": "严氏济生方心悸条文注释｜一、惊悸论治——心虚胆怯为惊悸之纲", "原文": "夫惊悸者，心虚胆怯之所致也。且心者君主之官，神明出焉，胆者中正之官，决断出焉。〔中段脱文·待核〕……无不瘥者矣。", "白话": "惊悸一病，是**心虚胆怯**所致。心为君主之官、主管神明，胆为中正之官、主管决断；心胆亏虚则神魂不安，遇事容易受惊。〔此下论治文字底本残脱，大意存「依法调治则无不愈」，待核〕"}, {"source": "严氏济生方心悸条文注释｜二、温胆汤、远志丸——惊悸二方（组成底本残缺）", "原文": "温胆汤** 治心虚胆怯，触事易惊，梦寐不祥，异象感惑，遂致心惊胆怯，气郁生涎，涎与气〔脱文·待核〕复生诸证，或短气悸乏，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。组成残文：「半夏〔脱〕皮，一两半） 甘〔脱〕」——**组成待核**。\n> **远志丸** 治因事有所大惊，梦寐不祥，登高陟险，神魂不安，惊悸恐怯。组成残文：「远志（去心，姜汁〔脱〕……齿（各一两）」——**组成待核**（据文义含龙", "白话": "温胆汤**：治心虚胆怯之人，遇事易惊、噩梦纷纭，以致心惊胆怯、气郁生痰，变生诸证；或见短气心慌乏力、自汗、四肢浮肿、纳差、心虚烦闷、坐卧不安。\n- **远志丸**：治因事受大惊，噩梦、登高临险时神魂不安、惊悸恐惧。"}, {"source": "严氏济生方心悸条文注释｜三、怔忡论治——心血不足说（严氏病机总纲）", "原文": "夫怔忡者，此心血不足也。盖心主于血，血乃心之主，心乃形之君，血富则心君自安矣。〔下段脱文·待核〕", "白话": "怔忡一证，病本是**心血不足**。心主血，血是心的物质基础，心是身体的君主；血充盈则心君自安，血不足则惕惕而动、无时自安。〔此下论证文字底本残脱，待核〕"}, {"source": "严氏济生方心悸条文注释｜四、★归脾汤——原方原出处（全书核心条文）", "原文": "归脾汤** 治思虑过度，劳伤心脾，健忘怔忡。\n> 白术 茯神（去木） 黄〔芪〕（去芦） 龙眼肉 酸枣仁（炒，去壳。各一两） 人参 木香（不见火。各半两） 甘草（炙，二钱半）\n> 上〔 咀〕，每服四钱，水一盏半，生姜五片，枣子一枚，煎至七分，去滓，温服，不拘时候。\n\n（注：底本「黄」后脱一字，据文义当为「芪」，**待核**；「上」下「 咂/咀」字样底本残。其余剂量原样照录。）", "白话": "治**思虑过度、劳伤心脾**所致的健忘与怔忡。药用：白术、茯神（去木）、黄芪（去芦）、龙眼肉、酸枣仁（炒，去壳）各一两，人参、木香（不见火）各半两，炙甘草二钱半。上药切碎，每次服四钱，用水一盏半，生姜五片、大枣一枚，煎取七分，去渣温服，不拘时服。"}, {"source": "严氏济生方心悸条文注释｜五、益荣汤、龙齿丹、茯苓饮子——怔忡三方向", "原文": "益荣汤** 治思虑过制，耗伤心血，心帝无辅，怔忡恍惚，善悲忧，少颜色，夜多不寐，小〔脱文〕。组成残：「当归（去芦，酒浸） 黄〔芪〕（去芦） 小草 酸枣仁（炒，去壳） 柏子仁（炒） 麦门冬〔脱〕参 甘草（炙。〔脱〕〕」——**组成待核**。\n> **龙齿丹** 治心血虚寒，怔忡不已，痰多恍惚。组成残：「龙齿 附子（炮，去皮脐，切片，姜汁浸一宿） 远志（去心，甘草煮） 酸枣仁（炒，去壳〔脱〕……黄〔脱", "白话": "益荣汤**：治思虑过度耗伤心血、心君失辅，怔忡恍惚、易悲伤忧愁、面色少华、夜寐不安。\n- **龙齿丹**：治心血虚寒，怔忡不止、痰多神恍。\n- **茯苓饮子**：治痰饮停蓄心胃，怔忡不止。赤茯苓、半夏、茯神、橘皮、麦冬各一两，沉香、炙甘草、槟榔各半两；煮散每服四钱，姜五片煎。"}, {"source": "伤寒恒论心悸条文注释｜一、第 82 条真武汤——亡阳心悸（火神派核心解读）", "原文": "二十一、太阳病发汗，汗出不解，其人仍发热，**心下悸**，头眩身瞤动，振振欲擗地者，真武汤主之。（原文 82）\n> **郑论：** 按发汗原是解表……今汗出而热仍然，所现种种病形，**非表邪未透之征，却是亡阳之候**，必是因发汗过度，伤及肾阳。**太阳底面，即是少阴**，此际发热者，**阳越于外**也；心下悸、头眩身瞤者，**阳气外亡而群阴僭上**也；振振欲擗地者，阳欲藏而不得也。夫先天之真阳，*", "白话": "发汗后汗出热不解、心悸头眩身颤欲倒——不是表邪未解，而是**过汗亡阳**：发热是虚阳外越，心悸头眩是阳亡阴盛上僭，站立不稳是真阳欲藏不得。真阳喜藏不喜露，真武汤的用意是**温藏真阳**。"}, {"source": "伤寒恒论心悸条文注释｜二、第 64 条桂枝甘草汤——汗为心液", "原文": "二十三、发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之。（原文 64）\n> **郑论：** 按**汗为心之液**，今发汗过多，则**心阳不足**，其人叉手自冒者，是**欲扶心之意**，外援之一助也。至心下悸欲按，皆本此。", "白话": "汗为心之液，过汗伤心阳——患者双手护胸是自我扶助心阳的动作；心悸喜按同理。桂枝甘草汤温补心阳。"}, {"source": "伤寒恒论心悸条文注释｜三、第 127 条饮水悸——水饮凌心辨微", "原文": "四十一、太阳病，小便利者，以饮水多，必心下悸；小便少者，必苦里急也。（原文 127）\n> **郑论：** 按饮水多而小便亦多，此理之常。但既称小便多，水以下行，又何致上逆凌心而为悸乎？必是**小便少而水道不畅，上逆以凌心而为悸**，与理方恰……或曰太阳行身之背，水气何得凌心？余以为凌心者，诚以**太阳之气，由下而至胸腹**也。", "白话": "饮水多而心悸，郑氏辨微：关键是**小便不利、水道不畅、水气上逆凌心**——不是单纯饮水多；太阳经气贯通胸腹，故水气可凌心。"}, {"source": "伤寒论心悸条文注释｜一、第 177 条 + 178 条——炙甘草汤与结代脉（房颤古论第一锚点）", "原文": "177．** 伤寒脉结代、心动悸，炙甘草汤主之。方三十九。\n> 甘草（炙，四两） 生姜（切，三两） 人参（二两） 生地黄（一斤） 桂枝（去皮，三两） 阿胶（二两） 麦门冬（去心，半升） 麻仁（半升） 大枣（擘，三十枚）\n> 上九味，以清酒七升，水八升，先煮八味，取三升，去滓，内胶烊消尽，温服一升，日三服。一名复脉汤。\n>\n> **178．** 脉按之来缓，时一止复来者，名曰结。又脉来动而中止，更来", "白话": "177：** 外感热病过程中出现**脉搏跳动中有间歇（结代脉）并伴心慌悸动不安**的，用炙甘草汤主治。方由炙甘草、生姜、人参、生地黄、桂枝、阿胶、麦冬、火麻仁、大枣九味组成；用清酒七升加水八升，先煮前八味取三升，去渣后放入阿胶烊化融化，每次温服一升，每日三次。此方又名「复脉汤」。\n- **178：** 脉搏按之来势较缓、时有停跳但随即恢复的，叫**结脉**。又有脉搏跳动中突然中止、再来时略快（小数）以补偿、停跳后能自行恢复节律的，也叫结脉，属阴证。脉搏跳动中止后**不能自行恢"}, {"source": "伤寒论心悸条文注释｜二、第 64 条——桂枝甘草汤（心阳虚悸·叉手自冒心）", "原文": "64．** 发汗过多，其人叉手自冒心，心下悸欲得按者，桂枝甘草汤主之。方二十七。\n> 桂枝（去皮，四两） 甘草（炙，二两） 上二味，以水三升，煮取一升，去滓，顿服。", "白话": "发汗太过，病人**双手交叉按护在心前区（叉手自冒心）、心慌心跳要用手按着才舒服**的，用桂枝甘草汤主治。桂枝四两、炙甘草二两，水煮取一升，一次服完（顿服）。"}, {"source": "伤寒论心悸条文注释｜三、第 82 条——真武汤（阳虚水泛悸）", "原文": "82．** 太阳病发汗，汗出不解，其人仍发热，心下悸、头眩、身动，振振欲擗（一作僻）地者，真武汤主之。方四十三。\n> 茯苓 芍药 生姜（切，各三两） 白术（二两） 附子（炮，去皮，破八片，一枚）", "白话": "太阳病发汗后汗出而病不解，仍有发热，并见**心慌心跳、头晕目眩、身体肌肉跳动、抖抖索索像要倒地**的，用真武汤主治。茯苓、芍药、生姜各三两，白术二两，炮附子一枚。"}, {"source": "伤寒论心悸条文注释｜四、第 102 条——小建中汤（心中悸而烦）", "原文": "102．** 伤寒二三日，心中悸而烦者，小建中汤主之。方五十二。", "白话": "伤寒才两三天，就出现**心慌伴心烦**的，用小建中汤主治。"}, {"source": "伤寒论心悸条文注释｜五、第 118 条——桂枝甘草龙骨牡蛎汤（火逆烦躁悸）", "原文": "118．** 火逆下之，因烧针烦躁者，桂枝甘草龙骨牡蛎汤主之。方六十二。\n> 桂枝（去皮，一两） 甘草（炙，二两） 牡蛎（熬，二两） 龙骨（二两）", "白话": "误用火法（烧针）又误下之后，病人**烦躁心悸**的，用桂枝甘草龙骨牡蛎汤主治。桂枝一两、炙甘草二两、煅牡蛎二两、龙骨二两。"}, {"source": "伤寒论注心悸条文注释｜一、复脉汤证——「阳证见阴脉」与背城借一", "原文": "伤寒脉结代，心动悸者，炙甘草汤主之。\n> 寒伤心主，神明不安，故动悸；心不主脉，失其常度，故结代也。结与代皆为阴脉，伤寒有此，所谓阳证见阴脉者死矣。不忍坐视，姑制炙甘草汤，以欲挽回于已去之候耳。收检余烬，背城借一，犹胜于束手待毙乎？", "白话": "外感病见脉中歇止（结代）而心慌跳动的，用炙甘草汤。柯琴注：寒邪伤犯心主，神明不得安宁，所以悸动；心不能主持血脉、脉失常度，所以结代。结与代都是阴脉，伤寒病中见到，就是「阳证见阴脉」的死候。仲景不忍坐视，姑且立炙甘草汤，想在阳气已去的关头挽回——收捡余烬、背城一战，总胜过束手待毙。"}, {"source": "伤寒论注心悸条文注释｜二、炙甘草汤方论——枣仁改字与「叔和所附」之疑", "原文": "炙甘草汤∶甘草（四两，炙） 桂枝 生姜（各三两） 麦门冬（半升） **枣仁（半升，旧本用麻仁者误）** 人参 阿胶（各二两） 大枣（三十枚） 生地黄（一斤）\n> 一百十三方，未有用及地黄、麦冬者，恐亦叔和所附。……此或阳亢阴竭而然，复出补阴制阳之路，以开后学滋阴一法乎？地黄、麦冬、阿胶滋阴，人参、桂枝、清酒以通脉，甘草、姜、枣以和营卫，酸枣仁以安神，结代可和而悸动可止矣。", "白话": "柯琴本方：甘草四两炙，桂枝、生姜各三两，麦门冬半升，**酸枣仁半升（旧本作麻仁是错的）**，人参、阿胶各二两，大枣三十枚，生地黄一斤。柯琴又疑：伤寒 113 方从没用过地黄、麦冬，恐怕是王叔和附入的；但也可能是阳亢阴竭之证，另开滋阴补阴制阳一路。方义：地黄、麦冬、阿胶滋阴；人参、桂枝、清酒通脉；甘草、姜、枣和营卫；**酸枣仁安神**——结代可调而悸动可止。"}, {"source": "伤寒论注心悸条文注释｜三、第 178 条脉法——五十动/五至为平/雀啄虾游", "原文": "持其脉口五十动而不一止者，五脏皆受气。呼吸闰息，脉以五至为平，太过不及，是阴阳偏胜失其常度矣。偏胜之脉，更为邪阻，则止而不前。阳邪盛而数中见止，名曰促……阴邪盛而缓中见止，名曰结……\n> 更来小数中有还者反动，宛如雀啄之状……为心家真藏之阴脉也。更有动而中止，不能自还，因而复动，宛如虾游之状……以乍疏乍数为脾家将绝之阴脉也。", "白话": "按寸口连续跳动五十下而无一次歇止的，五脏都得到胃气充养。一呼一吸加闰息，脉跳五至为正常；过或不及都是阴阳偏胜、失其常度。偏胜之脉再被邪气阻遏，就会停而不前：阳邪盛而数中见止叫促（有急趋忽跌之势），阴邪盛而缓中见止叫结（有绵绵泻漆之状）。……停跳后补跳略快、中间又见反动的，像**雀啄**之状——是心的真脏阴脉；停跳后不能自还、过时再动的，像**虾游**之状、乍疏乍数——是**脾将绝**的阴脉。"}, {"source": "伤寒论注心悸条文注释｜四、桂枝甘草汤证（64 条）——虚悸鉴别金标准", "原文": "发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之。\n> 汗多则心液虚，心气馁故悸；叉手自冒，则外有所卫，得按则内有所凭，则望之而知其虚矣。桂枝为君，独任甘草为佐，去姜之辛散、枣之泥滞，并不用芍药……甘温相得，气血和而悸自平。**与心中烦、心下有水气而悸者迥别。**", "白话": "发汗过多则心液虚、心气衰馁而悸；双手交叉覆按是求外护、按之舒服是求内凭——望诊即可知其虚。桂枝为君、甘草为佐，去掉生姜的辛散、大枣的泥滞，也不用芍药的酸收苦泄，甘温相合，气血和则悸平。**这与「心中烦」之悸、「心下有水气」之悸截然不同。**"}, {"source": "伤寒论注心悸条文注释｜五、真武汤证（82 条）——「重在心下悸」的辨证眼目", "原文": "太阳病发汗，汗出不解，其人仍发热，心下悸，头眩，身 动振振欲擗地者，真武汤主之。\n> 仍发热而心下悸，坎阳外亡而肾水凌心耳。头眩身 ，因心下悸所致。……**此条用真武者，全在降火利水，重在发热而心下悸，并不在头眩身 动也。**如伤寒厥而心下悸，宜先治水，亦重在悸，不重在厥。但彼本于太阳寒水内侵，故用桂枝；此则少阴邪水泛溢，故用附子。……要知小便自利，心下不悸，便非真武汤证。", "白话": "发汗后汗出不解仍发热，见心下悸、头眩、身瞤动、抖索欲倒的，用真武汤。柯琴注：仍发热兼心下悸，是坎阳外亡、肾水上凌心；头眩身瞤都是**因心下悸所致**。此条用真武汤全在**降火利水**，眼目是「发热＋心下悸」，不在头眩身瞤动。就像「厥而心下悸先治水」也是重在悸不重在厥——但那条是太阳寒水内侵所以用桂枝，这条是少阴邪水泛溢所以用附子。……**要知道：小便自利、心下不悸，就不是真武汤证。**"}, {"source": "伤寒论纲目心悸条文注释｜一、「悸」门纲目——心下悸六纲总汇", "原文": "【纲】仲景曰。发汗过多。其人叉手自冒心。心下悸。欲得按者。桂枝甘草汤主之。\n> 【纲】仲景曰。伤寒二三日。心下悸而烦者。小建中汤主之。\n> 【纲】仲景曰。伤寒厥而心下悸者。宜先治水。当用茯苓甘草汤。却治其厥。", "白话": "发汗太过，病人双手交叉按护心前区、心慌要用手按住才舒服的，用桂枝甘草汤。伤寒才两三天即见心慌心烦的，用小建中汤。手冷而又心下悸动的，应先治水饮，用茯苓甘草汤，再治手冷——不这样，水饮下渗胃肠必致腹泻。"}, {"source": "伤寒论纲目心悸条文注释｜二、咳悸门——真武汤证（沈金鳌自按定病机）", "原文": "【纲】仲景曰。太阳病。发汗。汗出不解。其人仍发热。心下悸。头眩。身 动。振振欲擗地者。真武汤主之。\n> 【目】鳌按。仍发热而心下悸。坎阳外亡。而肾水凌心也。以其为肾水凌心之故。故亦列少阴款中。", "白话": "太阳病发汗后汗出而病不解，仍发热，并见心下悸动、头晕、身体肌肉跳动（「身 动」原文第二字缺，疑为「瞤」，待核）、抖抖索索像要倒地的，用真武汤。沈金鳌自按：仍发热兼心下悸，是肾中坎阳外越亡失、肾水上逆凌犯心火；正因病本在肾水凌心，所以把这条编入少阴门类。"}, {"source": "伤寒论纲目心悸条文注释｜三、厥阴经脉门——脉结代、心动悸（柯琴注·雀啄虾游说）", "原文": "【纲】仲景曰。伤寒脉结代。心动悸者。炙甘草汤主之。脉来缓。时一止。复来者。名曰结。脉来数。时一止。复来者。名曰促。阳盛则促。阴盛则结。此皆病脉。\n> 【目】柯琴曰。首条。寒伤心主。心不主脉。失其常度。故结代也。结代皆阴脉。伤寒有此。所谓阳症见阴脉者死矣。", "白话": "外感病见脉中歇止（结代）并心慌跳动的，用炙甘草汤。脉来迟缓而时有一停随即恢复的叫结；脉来快而时有一停的叫促——阳盛则促、阴盛则结，都是病脉。柯琴注：寒邪伤犯心主（心包/心），心不能主持血脉、脉失常度，所以出现结代。结代都是阴脉，伤寒病中见到它，就是「阳证见阴脉」的死候。"}, {"source": "伤寒论辩证广注心悸条文注释｜一、第 177 条——脉结代、心动悸（邪正分属说）", "原文": "伤寒脉结代。心动悸。炙甘草汤主之。（结代脉名义。详见下文。大抵伤寒之病。见此等脉。成注所云。气血虚衰。不能相续也。悸。心动也。心中动悸。则知营血内虚。真气已馁。而藏神不自宁也。）\n> 愚按此条伤寒。必系发汗过剂。汗多亡阳。阳亡则气馁。又汗为血液。汗多则血虚。血虚气馁。以故心动悸。而脉结代也。夫结者。邪气之结代者。正气之虚。", "白话": "外感病见脉中歇止（结代）而心慌跳动的，用炙甘草汤。汪琥注：结代脉名义详见下文；大抵伤寒见到这种脉，就是成无己所说的气血虚衰、脉气接续不上。「悸」就是心动——心中跳动慌乱，说明营血内虚、真气衰馁，心藏神而神不自安。汪琥自按：这条的伤寒必定是**发汗过度**——汗多则亡阳、阳亡则气馁；汗又是血液所化，汗多则血虚；血虚加气馁，所以心动悸而脉结代。**结是邪气的结滞，代是正气的虚衰**。"}, {"source": "伤寒论辩证广注心悸条文注释｜二、炙甘草汤方注——姜桂散邪说（驳成注）", "原文": "成注云补可以去弱。人参甘草大枣之甘。以补不足之气。桂枝生姜之辛。以益正气。……麻仁阿胶麦门冬地黄之甘。润经益血。复脉通心也。\n> 琥按上注云。桂枝生姜之辛。以益正气。夫姜桂之辛。力能散邪。成氏反云。益气。误矣。……炙甘草汤。本甘温湿润之剂。用之以滋补枯竭。则气血充溢。而结代之脉自复。故一名复脉汤也。", "白话": "成无己注：补药可以去弱——人参、甘草、大枣之甘补不足之气；桂枝、生姜之辛「益正气」；麻仁、阿胶、麦冬、地黄之甘润经益血、复脉通心。汪琥驳：说姜桂之辛是「益正气」错了——**姜桂味辛力能散邪**。炙甘草汤本是甘温滋润之剂，用以滋补枯竭，气血充溢则结代之脉自然恢复，所以又名复脉汤。方中入清酒，《内台方议》说是以之为引，「为能通血助气。以复脉。故必欲用之」。"}, {"source": "伤寒论辩证广注心悸条文注释｜三、第 178 条——结代脉详解（仲叔和预后调停说）", "原文": "脉按之来缓。而时一止。复来者。名曰结。又脉来动而中止。更来小数。中有还者。反动。名曰结。阴也。脉来动而中止。不能自还。因而复动。名曰代阴也。得此脉者必难治。\n> 滑氏云。寻之良久乃复强起。此善于形容代脉之状者也。成注以代脉为真气衰极。夫真气衰极。亦因邪气久留所致。叔和脉经云。脉结者生。代者死。故云。难治。", "白话": "脉按之来势较缓、时有一停即恢复的叫结；脉跳动中止、再来时略快（小数）、中间有一两下反而更动的，叫结阴——是邪气留结更甚，脉既动且数而真气骤然接续不上。脉动中止后**不能自己恢复**、过一阵才再动的叫代阴；滑伯仁形容代脉「寻之良久乃复强起」（按下去良久才重新鼓起）。成注说代脉是真气衰极；汪琥补：真气衰极也是**邪气久留**造成的。王叔和《脉经》说「脉结者生，代者死」，所以说「难治」。"}, {"source": "伤寒论辩证广注心悸条文注释｜四、第 64 条 + 65 条——桂枝甘草汤与苓桂甘草大枣汤", "原文": "发汗过多。其人叉手自冒心。心下悸。欲得按者。桂枝甘草汤主之。（汗者心之液。发汗过多。则阳亡而心液虚耗。心虚则动惕而悸……冒字作覆字解。发汗过多。必是多服麻黄汤之故。）\n> 琥按成注云。桂枝之辛走肺而益气。夫桂枝虽系护表助阳之药。然其味大辛反能散气。……愚以此等注。不甚晓畅。删之可也。", "白话": "发汗过多，汗为心之液，阳亡而心液虚耗，心虚则跳动惊惕而悸，所以病人双手交叉覆按心胸而欲得按（「冒」作「覆」解）；发汗过多多半是多服麻黄汤之故。用桂枝固表守阳、甘草益气缓悸。汪琥驳成注「桂枝之辛走肺而益气」：桂枝虽是护表助阳之药，但味大辛**反而能散气**——这种注解不晓畅，删掉都可以。"}, {"source": "伤寒论辩证广注心悸条文注释｜五、第 82 条 + 厥而心下悸 + 少阳加减（本书独有处理）", "原文": "太阳病发汗。汗出不解。其人仍发热心下悸。头眩。身 动。振振欲擗地者。真武汤主之。（此条虽太阳病。强发汗亡阳。以致里虚。实系真寒阴证。正文与注并汤俱见中寒论中）\n> 伤寒厥而心下悸者。宜先治水。当服茯苓甘草汤。却治其厥。不尔。水渍入胃必作利也。（此条乃厥阴病热。消渴以后之变证也……明系消渴。饮水多。寒饮留于心下。胸中之阳。不能四布。故见厥。此非外来之寒比也。故仲景之法。宜先治水……盖水去。则厥自除也", "白话": "82 条真武汤证：汪琥认为此条虽冠「太阳病」，实系强发汗亡阳以致里虚，是**真寒阴证**——故把正文与注文、方剂整体移入其《中寒论》部分（txt 中注明「俱见中寒论中」）。\n- 厥而心下悸：这是厥阴病消渴之后的变证——消渴饮水多，寒饮留在心下，胸中阳气不能四布，所以手冷；并非外来之寒。治法宜**先治水**（茯苓甘草汤），水去则厥自除；不治水，水下渗入肠必作湿热利。汪琥并驳：诸家以阴寒为厥、谓仲景另有治厥法，误矣；郭白云以四逆汤治厥「大误之极」。心下=胃脘，「入胃」=下接于肠。"}, {"source": "冯氏锦囊秘录心悸条文注释｜一、三症总纲（经典定义）", "原文": "健忘者，为事有始无终，言语不知首尾；**怔忡者，心中惕惕，动而不宁，无时而作；惊悸者，外有所触，心中跳动，因惊而作**。三症皆属心血不足，通宜**天王补心、归脾之属**治之。然亦有挟火挟痰所致。如挟火者，则天王补心加减，如犀角、黄连之属；挟痰者……（温胆之属）", "白话": "健忘=做事有头无尾；**怔忡=心中惕惕跳动、无时而作（自发持续）**；**惊悸=外有所触、因惊而作（发作性）**。三症病本都是心血不足，主方天王补心丹/归脾汤；兼火加犀角黄连，兼痰用温胆类。"}, {"source": "冯氏锦囊秘录心悸条文注释｜二、惊悸阴阳内外分（脉证鉴别）", "原文": "大抵**惊则不自知，而证属阳，从外入**也……**悸者，自知如人将捕之状，不能独卧，而证属阴，从内出**也。悸即怔忡，心中如有物撞，谓之忡，忽然跳跃谓之怔，此血自内虚也……古无怔忡之名，曰**心掣，心悬**者是也。", "白话": "惊**=不自知、属阳、从外入（受惊）；**悸**=自知、如人将捕、不能独卧、属阴、从内生（血虚）。「怔」=忽然跳跃，「忡」=心中物撞；古名**心掣、心悬**。"}, {"source": "冯氏锦囊秘录心悸条文注释｜三、心病须心药医（心身论·名句）", "原文": "《经》曰：尝贵后贱……名曰**脱营**。……尝富后贫，名曰**失精**，谓心有所郁，而气不舒畅也。总心为君主之官，神明出焉，**思虑过度，耗其心血**，失去向导，则神明伤而成心劳，故怔忡健忘也……故无论富贵贫贱，**病生于内者难治，伤于外者易合**……**心病须心药医**也。", "白话": "社会地位骤变（脱营/失精）→ 心郁气滞→思虑耗心血→怔忡健忘。内伤难治、外伤易愈——**心病要用心药（情志开导）来医**。"}, {"source": "医学入门心悸条文注释｜一、惊悸、怔忡、健忘门总纲（外集·卷四·杂病分类）", "原文": "惊悸惕惕不自定，如人将捕曰怔忡。思虚过度及因大惊、大恐，以致心虚停痰，或耳闻大声，目见异物，临危触事，便觉惊悸，甚则心跳欲厥，脉弦濡者，虚也。", "白话": "惊悸**是心里惕惕跳动、自己控制不住；**怔忡**是（无外触也）心中跳动不安，像有人要来抓自己一样。病因是思虑过度，或受了大惊大恐，以致心虚而痰饮停聚；也有听到大声音、看到怪异东西、身临危险境地便觉心慌的，重的**心跳剧烈像要昏厥**，脉弦而濡者属**虚证**。"}, {"source": "医学入门心悸条文注释｜二、惊悸怔忡分层治法（辨证纲领+方药链）", "原文": "血虚，四物汤、茯神汤、妙香散、朱砂安神丸；气血俱虚，人参养荣汤、养心汤。时作时止者，痰也，二陈汤加白术、黄连、远志、竹沥、姜汁。怔忡因惊悸久而成，痰在下，火在上故也，温胆汤加黄连、山栀、当归、贝母；气郁者，四七汤加茯神、远志、竹沥、姜汁，或十味温胆汤、金箔镇心丸；停饮胸中漉漉有声，怏怏不安者，二陈汤加茯神、槟榔、麦门冬、沉香，或朱雀丸。", "白话": "血虚心悸用四物汤、茯神汤、妙香散、朱砂安神丸；气血两虚用人参养荣汤、养心汤。**发作时有时无的是痰**，用二陈汤加白术、黄连、远志、竹沥、姜汁。怔忡是惊悸日久不愈发展而成，病机是**痰在下、火在上**，用温胆汤加黄连、山栀、当归、贝母；气郁者四七汤加茯神、远志、竹沥、姜汁，或十味温胆汤、金箔镇心丸；**水饮停胸、胸中漉漉有声**、心中郁郁不安者，二陈汤加茯神、槟榔、麦门冬、沉香，或朱雀丸。"}, {"source": "医学入门心悸条文注释｜三、健忘传变与三证合治", "原文": "怔忡久则健忘，三证虽有浅深，然皆心脾血少神亏，清气不足，痰火浊气上攻，引神归舍丹主之……三证通用归脾汤、仁熟散、梦授天王补心丹、寿星丸、参枣丸。", "白话": "怔忡日久会发展为健忘，惊悸、怔忡、健忘三证虽有轻重浅深之别，但病本都是**心脾血少、神气亏虚，兼痰火浊气上攻**，主方是引神归舍丹……三证通用归脾汤、仁熟散、梦授天王补心丹、寿星丸、参枣丸。"}, {"source": "医学入门心悸条文注释｜四、心病怔忡宜温胆（五脏穿凿论）＋问诊条", "原文": "《五脏穿凿论》曰：心与胆相通（心病怔忡，宜温胆为主；胆病战栗癫狂，宜补心为主）……\n> （问诊）心烦否？或只烦躁不宁，或欲吐不吐，谓之嘈杂。或多惊恐，谓之怔忡。", "白话": "《五脏穿凿论》说：心与胆相通——**心病见怔忡，应以温胆法为主**；胆病见战栗癫狂，应以补心为主。（问诊十问之一）问心烦吗：只有烦躁不宁，或想吐又吐不出，是嘈杂；**若多惊恐不安，就是怔忡**。"}, {"source": "医学入门心悸条文注释｜五、脉法条（惊悸怔忡脉＋结代脉）", "原文": "惊悸怔忡，寸动而弱，寸紧胃浮，悸病仍作。饮食痰火，伏动滑搏，浮微弦濡，忧惊过却，健忘神亏，心虚浮薄。\n> 沉弱阳虚多惊悸，《权舆》云：左寸弱兮阳气虚，心惊悸兮汗难除。\n> 促乃阳盛而阴不相济……结乃阴盛而阳不相入，内外邪滞为积。非若结代之脉动而中止。", "白话": "惊悸怔忡的脉：寸口**动而弱**（动为惊、弱为悸）；寸紧、趺阳浮者，胃气虚，悸病仍会发作；饮食痰火者脉伏动滑搏；浮微弦濡者为忧惊已过；健忘者神亏，心虚则脉浮薄。**沉弱脉主阳虚而多惊悸**——《脉诀权舆》说：左寸弱是阳气虚，心惊悸而汗出难止。促脉是阳盛而阴不济；结脉是阴盛而阳不入、邪滞为积；不同于结代脉的「动而中止」。"}, {"source": "医学入门心悸条文注释｜六、兼证条（水喘、水呕、悸痛、呃逆脉结、便血怔忡）", "原文": "水喘，水气辘辘有声，怔忡者，小青龙汤、古葶枣散、白前汤。\n> 水呕，心下怔忡，先渴后呕者，赤茯苓汤；先呕后渴者，猪苓汤；水入即吐者，五苓散。\n> 悸痛，内因七情，轻则怔忡惊悸，似痛非痛，妙香散、四七汤、小草丸……\n> 中虚昏聩脉结者，炙甘草汤救之。内伤忧思，怔忡少寝，有汗者，归脾汤。", "白话": "水喘：水气辘辘有声兼怔忡，用小青龙汤、古葶枣散、白前汤。水呕：心下怔忡，**先口渴后呕**的用赤茯苓汤；**先呕后渴**的用猪苓汤；**水入即吐**的用五苓散。悸痛：七情内伤，轻则怔忡惊悸、似痛非痛，用妙香散、四七汤、小草丸。呃逆见中虚昏聩、**脉结**者，用炙甘草汤救治；内伤忧思、怔忡失眠有汗者，用归脾汤。"}, {"source": "医学摘粹心悸条文注释｜一、心下悸——悸证辨证决策树（水/寒/虚三级方梯）", "原文": "心下悸**：心下筑筑惕惕，怔怔忡忡，悸病之状也。**饮水多而小便少，水停心下，宜茯苓甘草汤，或五苓散。厥冷为寒，宜真武汤。汗后为虚，宜小建中汤。或不因汗后，是虚之甚也，宜炙甘草汤。**", "白话": "心下（胃脘/心前区）筑筑跳动、惕惕不安、怔怔忡忡，就是悸病的表现。辨治分四路：**饮水多而小便少、水停心下的，用茯苓甘草汤或五苓散；伴四肢厥冷属寒的，用真武汤；发汗之后属虚的，用小建中汤；不经发汗而悸的，是虚之更甚，用炙甘草汤**。"}, {"source": "医学摘粹心悸条文注释｜二、怔忡——土湿木郁、相火逼宫城（黄氏病机模型）", "原文": "怔忡**：怔忡者，心下跳动不安也。即惊悸之类，**缘土湿木郁，相火浮动，逼扰宫城，以致心神震荡不安也。以金鼎汤主之**。如因水气凌心，而成怔忡者，以小半夏加茯苓汤主之。重者以桂枝茯苓大枣甘草汤主之。再重者以真武汤主之。如因奔豚而成怔忡者，当于奔豚门求方治之。\n> 〔怔忡提纲〕此证原由木郁生，上炎相火逼宫城，神魂震荡难安谧，因水凌心病亦成。\n> **桂枝茯苓大枣甘草汤**：茯苓（八钱） 桂枝（四钱）", "白话": "怔忡是心下跳动不安，属惊悸一类，**病由脾土湿、肝木郁，相火浮动上炎、逼扰心（宫城），致心神震荡不安——用金鼎汤主治**。若因水气凌心而成，用小半夏加茯苓汤；重者桂枝茯苓大枣甘草汤；再重者真武汤。若由奔豚引发，到奔豚门求方。提纲诗：此证由木郁而生，相火上炎逼宫城，神魂震荡；水气凌心亦可成。桂苓枣甘汤用茯苓八钱、桂枝四钱、甘草二钱、大枣二枚，以**甘澜水**（水扬三百遍）三杯先煮茯苓减半，入诸药煎至七分温服。"}, {"source": "医学摘粹心悸条文注释｜三、神惊——神不交精生惊悸与金鼎汤（桂甘龙牡汤加味）", "原文": "神惊**：神藏于心，而交于肾，则神清而不摇。**若神不交精，乃生惊悸。其原由于胆胃之不降**，甲木降而固水，戊土降而收金，金水秘藏，阴气收敛，阳神静谧，故不摇荡。一自胃湿不降，火失封蛰之性，是以上炎而生烦扰。法宜降土清木敛相火而固其根，则神自不摇矣。**以金鼎汤主之**。\n> **金鼎汤**：桂枝（三钱） 茯苓（三钱） 半夏（三钱） 甘草（二钱） 芍药（三钱） 龙骨（三钱） 牡蛎（三钱）。水煎大半", "白话": "神藏于心而下交于肾，则神清不摇；**神不能下交于精（心肾不交），则生惊悸**。其根原在胆胃不降：甲木（胆）降则肾水得固、戊土（胃）降则肺金得收，金水秘藏、阴气收敛，阳神自静；一旦胃湿不降、火失封蛰而上炎，即生烦扰惊悸。治宜**降胃土、清肝木、敛相火、固其根**——金鼎汤：桂枝、茯苓、半夏、甘草、芍药、龙骨、牡蛎各等分（桂芍苓甘夏龙牡七味），水煎温服；上热加倍芍药清胆火，下寒加附子温肾水。病重年深、奔豚凝结者缓用附子，先燥土去湿调脾胃（详黄氏奔豚证）。"}, {"source": "医学摘粹心悸条文注释｜四、炙甘草证与表里俱虚证——脉结代心动悸的再确认", "原文": "（表里俱虚证）**伤寒脉结代、心动悸者，炙甘草汤主之。**……按：以上诸证，或脉结代而气血两虚，或脉沉恶寒而真阳已败，故以表里俱虚证统之。\n> **炙甘草汤**：甘草（二钱） 桂枝（一钱五分） 生姜（一钱五分） 人参（一钱） 阿胶（二钱） 大枣（二枚） 麻仁（一钱五分） 麦冬（一钱五分） 生地（六钱）。水二杯，清酒一杯，煎八分，入胶烊，温服。\n> 按：此证相火上燔，辛金受刑，甲木上郁，戊土被克，土", "白话": "伤寒脉结代、心动悸者，用炙甘草汤主治；与少阴附子汤证（脉沉恶寒真阳败）同列「表里俱虚证」——**脉结代属气血两虚**。炙甘草汤：炙甘草二钱、桂枝、生姜各一钱五分、人参一钱、阿胶二钱、大枣二枚、麻仁、麦冬各一钱五分、生地六钱；水二杯清酒一杯煎取八分，阿胶烊化温服。作者按语：此证相火上燔、肺金受刑、甲木上郁、胃土被克，土金俱败而中气伤——故用参甘姜枣益中气、地胶麦麻养阴血、桂枝清酒通阳复脉。方歌：脉形结代、悸动心惊不得安，中气已虚宜补，炙甘草汤阴阳两补、安心悸，立法无偏。"}, {"source": "医学摘粹心悸条文注释｜五、奔豚与脐下悸——惊悸为奔豚欲发之兆", "原文": "奔豚**：奔豚者，肾之积也。缘阴气凝聚，结于少腹……有时逢郁则发，奔腾逆上，势如惊豚。腹胁心胸，诸病皆作，气冲咽喉，七窍火发，危困欲死……**其将发之时，则脐下悸作，凡惊悸一生，即为奔豚欲发之兆也**。如汗后亡阳，脐下悸动，奔豚欲作者，以茯苓桂枝甘草大枣汤主之。如奔豚方作，气从少腹上冲心部者，以桂枝加桂汤主之。如奔豚盛作，气上冲胸，头疼腹痛，往来寒热者，以奔豚汤主之。", "白话": "奔豚是肾之积：阴气凝聚结于少腹，郁则发作，气从少腹奔腾上冲如惊奔之豚，腹胁心胸诸症并作、气冲咽喉、危困欲死。**发作先兆是脐下悸动——凡惊悸一出现，即奔豚欲发之兆**。汗后亡阳、脐下悸而欲作者，用茯苓桂枝甘草大枣汤（甘澜水煎）；奔豚初起、气从少腹上冲心者，桂枝加桂汤；盛作而气上冲胸、头疼腹痛、往来寒热者，奔豚汤（甘草半夏芍药当归黄芩生姜芎生葛李根白皮）。"}, {"source": "医学摘粹心悸条文注释｜六、脉占动止——五十动一止为常的停跳分层", "原文": "脉占动止**：寸口动脉，**五十一止，合于经常、不病之脉也。若四十动一止，一脏无气，主四岁死。三十动一止，二脏无气，主三岁死。二十动一止，三脏无气，主二岁死。十动一止，四脏无气，主一岁死。不满十动一止，五脏无气。若更乍数乍疏，止而不能即还，岁内必死也。**", "白话": "寸口脉跳动，**五十动中一止是合于常规的平脉（不病）**；四十动一止为一脏无气，主四年后死；三十动一止为二脏无气，主三年死；二十动一止为三脏无气，主二年死；十动一止为四脏无气，主一年死；不满十动一止为五脏无气；若更见快慢不匀、停后不能即还，一年内必死。"}, {"source": "医学纲目心悸条文注释｜一、名义总纲——惊、悸、怔忡三分", "原文": "惊者，心卒动而不宁也。悸者，心跳动而怕惊也。怔忡，亦心动而不宁也。（《医学纲目》篇首）\n> 〔丹〕怔忡，大概属血虚与痰。有虑便动者属虚，时作时止者，痰因火动。瘦人多是血虚，肥人多是痰饮，真觉心跳者是血少，宜四物、安神之类。", "白话": "惊**：心突然跳动而不安宁；**悸**：心跳动而害怕受惊；**怔忡**：也是心动不宁。朱丹溪说：怔忡大体属**血虚与痰**——一有思虑就跳动的属虚，时作时止的属痰因火动；瘦人多血虚，胖人多痰饮；真正觉心跳的是血少，宜四物汤、安神丸之类。"}, {"source": "医学纲目心悸条文注释｜二、东垣脉案——六脉俱大按之空虚（气盛亡血）", "原文": "〔垣〕六脉俱大，按之空虚，必面赤善惊上热，乃手少阴心之脉也。此气盛多而亡血，以甘寒镇坠之剂泻火与气，以坠气浮，以甘辛温微苦峻补其血，熟地黄、生地黄、柴胡、升麻、白芍药、牡丹皮、川芎、黄 之类以补之，以防血溢上竭。", "白话": "李东垣说：六脉都大、按之空虚，兼见面红、易惊、上部有热——这是手少阴心的脉象，属**气盛于上而亡血**。治法：用甘寒镇坠之剂（如丹砂之类）泻火与气、镇坠浮越之气；同时用甘辛温微苦之品峻补其血——熟地黄、生地黄、柴胡、升麻、白芍药、牡丹皮、川芎、黄芪之类，以防血溢于上而下竭。"}, {"source": "医学纲目心悸条文注释｜三、杜氏海味案——咸胜血伤心（饮食病因）", "原文": "〔杜〕林学士有一子……居常喜食海蛤，饮食之顷，未尝不设，至十八年，忽面色顿青，形体瘦削，夜多惊悸。皆谓劳瘵之疾，百疗不瘳。遂召杜脉之，杜曰∶非病……但多服生津液药，病当自愈。如是经两月，面色渐有红润意，夜亦无惊悸。\n> 杜曰∶王冰《素问》曰，盐发渴，乃胜血之证。海味皆咸物，既多食海味，使心血渐衰，则夜惊悸。", "白话": "杜氏医案：林学士之子常年嗜食海蛤，每餐必备，十八年后忽然面色发青、形体消瘦、夜间多惊悸。众医都当劳瘵治，百治不愈。杜氏诊后说这不是劳病——只是让他多服生津液的药，两月后面色转红润、夜惊悸消失。杜氏解释：王冰注《素问》说「盐发渴，乃胜血之证」，海味都是咸物，多食咸使心血渐衰，所以夜间惊悸。"}, {"source": "医学纲目心悸条文注释｜四、水饮悸——仲景、三因与半夏麻黄丸", "原文": "〔仲〕食少饮多，水停心下，甚者则悸，微者短气。（饮水多必心下悸。）\n> 〔无〕五饮停蓄，闭于中脘，最使人惊悸，属饮家。\n> 〔仲〕心下悸者，半夏麻黄丸主之。半夏 麻黄（等分）上二味为末，炼蜜和丸，如小豆大。饮服三丸，日三服。\n> \\x温胆汤\\x 治心胆虚怯，触事易惊……气郁生涎，涎与气搏，变生诸症。或短气悸乏，或复自汗。半夏（汤洗） 竹茹 枳实（炒。各二两） 橘皮（二两，去白） 甘草（炙，一两） ", "白话": "张仲景：进食少而饮水多，水停心下，重则心悸，轻则短气（饮水多必心下悸）。《三因方》：五饮停留闭塞中脘，最令人惊悸，属饮家。心下悸用**半夏麻黄丸**：半夏、麻黄等分，为末炼蜜丸如小豆大，每次服三丸，日三服。**温胆汤**治心胆虚怯、触事易惊、气郁生涎、痰气相搏：半夏、竹茹、枳实各二两，橘皮二两，炙甘草一两，白茯苓一两五钱。"}, {"source": "医学纲目心悸条文注释｜五、心惊胆寒与镇心诸法", "原文": "〔无〕惊悸，因事有所大惊而成者，名曰心惊胆寒，病在心胆经，其脉大动……东垣朱砂安神丸。（外物惊宜镇，平以黄连安神丸是也。）\n> 〔无〕\\x镇心丹\\x 治惊悸。辰砂（用黄松节酒浸） 龙齿（用远志苗醋煮）上只取辰砂、龙齿各等分为末。猪心血为丸，如芡实大。每服一丸，以麦门冬叶、绿豆、灯心、白蜜，水煎……临卧咽下。\n> 〔无〕\\x寒水石散\\x 治因惊心气不行，郁而生涎，结为饮，遂为大疾，忪悸陨KT ，不自", "白话": "《三因方》：因事受大惊而发的惊悸，叫「心惊胆寒」，病在心胆经，**脉大而动**（动脉如豆、厥厥动摇无头尾）——用东垣朱砂安神丸（外物所致之惊宜镇坠，以黄连安神丸平之）。**镇心丹**治惊悸：辰砂（黄松节酒浸）、龙齿（远志苗醋煮）各等分为末，猪心血丸如芡实大，每服一丸，用麦门冬叶、绿豆、灯心、白蜜煎汤送下，临卧咽。**寒水石散**治因惊心气不行、郁生涎结为饮、心慌不能自持：寒水石（煅）、滑石（水飞）各一钱，生甘草一钱，为末每服二钱。"}, {"source": "医学纲目心悸条文注释｜六、伤寒部·悸——经方条文汇编（楼氏互见体）", "原文": "汗后心下悸，若头眩身 动，振振欲擗地者，真武汤也。若叉手自冒心者，后条桂枝甘草汤也……若脐下悸者，后条茯苓桂枝甘草大枣汤也。\n> 发汗过多，其人叉手自冒心，心下悸欲得按者，宜桂枝甘草汤。桂枝（四钱） 甘草（二钱）上二味，以水一盏半，煎八分，去渣温服。\n> 伤寒二三日，心中悸而烦者，小建中汤主之。伤寒脉结代，心动悸，宜炙甘草汤。甘草（炙，一两） 生姜（三片） 人参（半两） 生地（一两） 桂枝（去皮）", "白话": "汗后心下悸分四路：头眩身瞤动、振振欲倒的用**真武汤**；叉手自冒心、喜按的用**桂枝甘草汤**（桂枝四钱、甘草二钱，水煎顿温）；谵语胃不和烦悸的《活人》用调胃承气汤；脐下悸欲作奔豚的用**茯苓桂枝甘草大枣汤**（茯苓八钱、炙甘草二钱、桂枝四钱、大枣二枚，甘澜水煎）。伤寒二三日心中悸而烦，**小建中汤**主之；伤寒脉结代、心动悸，宜**炙甘草汤**（炙甘草一两、生姜三片、人参半两、生地一两、桂枝、麦冬各一两、麻仁一合、阿胶半两，水酒煎，阿胶溶化）。"}, {"source": "医学纲目心悸条文注释｜七、伤寒部·惊悸——火逆与柴龙牡", "原文": "少阳耳聋目赤，胸满而烦者，不可吐下，吐下则悸而惊。\n> 伤寒八九日，下之胸满烦惊，小便不利，谵语，一身尽重，不可转侧者，宜柴胡加龙骨牡蛎汤。半夏（二合） 大枣（六枚） 柴胡（四两） 生姜 人参 龙骨 铅丹 桂枝 茯苓（各一两半） 大黄（二两半） 牡蛎（一两半）。\n> 伤寒脉浮，医以火迫劫之，亡阳必惊狂，起卧不安者，桂枝去芍药加蜀漆牡蛎龙骨救逆汤主之。桂枝（去皮，三两） 甘草（炙，二两） 生姜（切，", "白话": "少阳病见耳聋目赤、胸满而烦，禁吐下——误用则悸而惊。伤寒八九日误下后胸满烦惊、小便不利、谵语、一身沉重不能转侧，用**柴胡加龙骨牡蛎汤**（半夏二合、大枣六枚、柴胡四两、生姜、人参、龙骨、铅丹、桂枝、茯苓各一两半、大黄二两半、牡蛎一两半）。伤寒脉浮误用火法逼汗，亡阳必发惊狂、起卧不安，用**桂枝去芍药加蜀漆牡蛎龙骨救逆汤**（桂枝三两、炙甘草二两、生姜三两、牡蛎五两、龙骨四两、大枣十二枚、蜀漆三两洗去腥）。"}, {"source": "医学纲目心悸条文注释｜八、脉候、针灸与产惊悸、心动", "原文": "〔仲〕寸口脉动而弱，动即为惊，弱即为悸。\n> 〔《脉》〕惊主病者，其脉止而复来，其人目睛不转，不能呼气。\n> 〔《撮》〕心烁烁跳动，少冲泻之，灸立效。\n> 〔仲〕病有奔豚，有吐脓，有惊怖，有火邪，此四病皆从惊发得之。\n> **心动** ，因痰动也。心 动者，谓不怕惊而心自动也……经云∶心主手厥阴之脉是动，则病心中 大动。", "白话": "张仲景：寸口脉动而弱——**动即为惊，弱即为悸**。《脉经》：惊病之脉停而复来，目睛直视不能转动、呼吸短促。《针灸撮要》：心烁烁跳动，泻**少冲**穴，灸之立效。仲景：奔豚、吐脓、惊怖、火邪四病都可从惊而发。「心动」篇：心中悸动者，谓不怕惊而心自动，因痰而动；属手厥阴心主经（「心中憺憺大动」）或少阳病（「其传为心掣」）。又：**产惊悸**——七宝散（辰砂、桂心、当归、川芎、人参、白茯苓、羚羊角、干姜）产后安神压惊。"}, {"source": "医学衷中参西录心悸条文注释｜一、定心汤——治心虚怔忡（心悸怔忡第一方源头）", "原文": "1．定心汤**（医方·治心病方）\n> 「治心虚怔忡。龙眼肉（一两） 酸枣仁（五钱，炒捣） 萸肉（五钱，去净核） 柏子仁（四钱，炒捣） 生龙骨（四钱，捣细） 生牡蛎（四钱，捣细） 生明乳香（一钱） 生明没药（一钱）」\n> 「心因热怔忡者，酌加生地数钱，若脉沉迟无力者，其怔忡多因胸中大气下陷。」", "白话": "主治**心虚所致的怔忡**（心慌跳动不安）。方由龙眼肉一两、炒酸枣仁五钱、净山萸肉五钱、炒柏子仁四钱、捣细生龙骨四钱、捣细生牡蛎四钱、生明乳香一钱、生明没药一钱组成。兼热的怔忡加生地黄数钱；若脉沉迟无力，其怔忡多因胸中大气下陷，当另治（升陷汤法）。"}, {"source": "医学衷中参西录心悸条文注释｜二、定心汤按语——西人「心跳真假」辨（房颤表象鉴别古译）", "原文": "「西人论心跳证有真假，真者手扪之实觉其跳，假者手扪之不觉其跳……假心跳即怔忡证也……特因气血虚而神明亦虚，即心之寻常舒缩，徐徐跳动，神明当之，亦若有冲激之势，多生惊恐。」\n> 「惟怔忡由于大气下陷者，断不宜用。」", "白话": "张锡纯引西医之说：心跳证有真假——**真跳者手摸得到心跳**（心脏本病，如心房门户大小窄阔失常），可用定心汤（乳香、没药各改三钱，更加当归、丹参各三钱）；**假跳者手摸不到**，即怔忡——心脏跳动其实正常，只因气血虚、神明失养，平常心跳也让患者觉得冲撞惊恐，此证用定心汤时**磨铁锈水煎药更佳**（取铁之镇重安神）。惟怔忡因大气下陷者禁用。"}, {"source": "医学衷中参西录心悸条文注释｜三、安魂汤——气血虚损兼痰饮惊悸不眠", "原文": "2．安魂汤**（医方·治心病方）\n> 「治心中气血虚损，兼心下停有痰饮，致惊悸不眠。龙眼肉（六钱） 酸枣仁（四钱，炒捣） 生龙骨（五钱，捣末） 生牡蛎（五钱，捣末） 清半夏（三钱） 茯苓片（三钱） 生赭石（四钱，轧细）」", "白话": "主治**心中气血虚损，兼心下停有痰饮**，以致惊悸、失眠。方由龙眼肉六钱、炒酸枣仁四钱、捣末生龙骨五钱、捣末生牡蛎五钱、清半夏三钱、茯苓片三钱、轧细生赭石四钱组成。若服一两剂无效，可另于临睡时开水送服西药臭剥（溴化物）一瓦借其麻痹神经之暂效。"}, {"source": "医学衷中参西录心悸条文注释｜四、安魂汤医案二则（古用例）", "原文": "「一媪，年五十余，累月不能眠……诊其脉有滑象，且其身形甚丰腴。知其心下停痰也。为制此汤，服两剂而愈。」\n> 「一妇人，年三十许，一月之间未睡片时，自言倦极仿佛欲睡，即无端惊恐而醒。诊其脉左右皆有滑象，遂用苦瓜蒂十枚……吐出胶痰数碗，觉心中异常舒畅。」", "白话": "案一：五十余岁老妇数月失眠，脉滑、体胖，断为心下停痰，服安魂汤两剂痊愈。案二：三十余岁妇人整月未睡，倦极欲睡时**无端惊恐而醒**，脉左右皆滑，先用苦瓜蒂十枚焙焦轧细空心开水送服，吐出胶痰数碗，心中异常舒畅；临睡前再服熟枣仁细末二钱，当夜安睡，续以利痰养心安神药十余剂巩固不发。附《内经》半夏秫米汤治目不得瞑法（长流水扬万遍、苇薪煎），门生高××治天津刘姓四月不寐，用鲜莱菔煎汤煎清半夏四钱，当夜即安睡。"}, {"source": "医学衷中参西录心悸条文注释｜五、论心病治法——心机亢进/心脏麻痹二纲与怔忡定位", "原文": "「心者，血脉循环之枢机也……心之病虽多端，实可分心机亢进、心脏麻痹为二大纲。」（医论 62）\n> 「有非心机亢进而有若心机亢进者，怔忡之证是也……其气血过于虚损，致神明失其凭根据，虽心机之动照常……而神明恒若不任其震撼者。」", "白话": "心是血液循环的枢纽：心房一动则周身脉一动。心机亢进则脉大有力或脉数；心脏麻痹则脉细无力或脉迟——心病虽多，总分**心机亢进、心脏麻痹两大纲**。心机亢进有：阳明热盛上蒸（白虎汤/承气汤）、下焦阴虚君火浮越（加味左归饮）、心阳素旺胃腑实热（咸寒法）、思虑生热夹痰（大承气加赭石甘遂）、肝升太过脑充血（建瓴汤）等。**怔忡则「非亢进而若亢进」**：心体舒缩照常而患者觉心中跳动不安，因气血虚损、神明失其所凭；脉多微细或兼数，治以萸肉、枣仁、山药保气，龙眼肉、熟地、柏仁养血，龙骨、牡蛎"}, {"source": "医学衷中参西录心悸条文注释｜六、太阳病炙甘草汤证——结代脉辨析与方义新解", "原文": "「脉之跳动，偶有止时，其止无定数者为结……止有定数者曰代……至代脉则止有定数，是脏腑中有一脏之气内亏，不能外达于脉之部位，是以为病甚重也。其心动悸者，正其结代脉之所由来也。」（医论 13）\n> 「炙甘草汤之用意甚深……原以补助肾中之气化，俾其壮旺上升，与心中之气化相济救为要着也。」", "白话": "脉跳偶有停歇、**停跳次数无规律者为结脉**（气血凝滞偶阻，病犹轻）；**停跳有规律（如几跳一止）者为代脉**（脏气内亏不能外达，病甚重）。心动悸正是结代脉的由来。炙甘草汤（甘草四两炙、生姜三两、桂枝三两、人参二两、生地黄一斤、阿胶二两、麦冬半升、麻子仁半升、大枣三十枚，清酒七升水八升煎）的深意不在单纯滋补心血：**生地黄重用一斤配酒水久煮，是变凉为温、温补肾脏**——脉之跳动在心，脉之所以有力赖肾气上升与心气相济，故本方要着在**补助肾中气化上升与心气相济**，滋心血只是兼"}, {"source": "医学衷中参西录心悸条文注释｜七、炙甘草汤证医案三则（结代脉/雀啄脉实治）", "原文": "「其脉象洪而不实，现有代象……用生石膏三两，大生地一两，野台参四钱……将三次服完，脉已不代，热退强半。」\n> 「其脉象洪滑甚实，或七八动一止，或十余动一止，其止皆在左部……知其左脉之结乃肝气之不舒也。」\n> 「恒现有雀啄之象，有如雀之啄粟，恒连二三啄也。」", "白话": "案一（代脉实热案）：年近六旬伤寒，表里大热，脉洪不实而见代象，舌苔白微黄，大便数日未行——用白虎加人参汤变通（生石膏三两、大生地一两、野台参四钱、生山药六钱、甘草三钱），三服后脉已不代。案二（结脉肝郁案）：钱姓壮年伤寒，脉洪滑实、七八至十余动一止（结脉），止皆在左部，病前曾怒动肝火——白虎加人参汤加生莱菔子四钱疏肝，结脉除而愈。案三（雀啄脉案）：少妇伤寒，脉六至有力，十余至二十余动后现雀啄之象（连二三啄），呼吸不畅，因账目差误被责斥——仍用前方加天花粉，脉调匀、呼吸顺而愈。张"}, {"source": "医学衷中参西录心悸条文注释｜八、附录·茯苓治心悸案（心液内涸、肾水上救）", "原文": "「茯苓固治心悸之要药，亦治汗出之主药……可知心悸者汗出过多，心液内涸，肾水上救入心则悸，余药不能治水，故用茯苓以镇之。」（茯苓药后附录，友人竹××案）", "白话": "产后月余妇人，壮热口渴不引饮、汗出不止、心悸不寐，面红脉滑；叠进养心敛汗诸方不效，后误打误撞用**茯苓四五两**煎服而愈。竹××自省：汗出过多则心液内涸，**肾水上救入心**故悸（水气凌心），茯苓利水镇心、又主汗出，为治心悸要药；伤寒「厥而心下悸者宜先治水，当服茯苓甘草汤」即此义。"}, {"source": "医宗金鉴心悸条文注释｜一、伤寒心法要诀·心下悸（34 诀）——心悸辨证总纲", "原文": "34.筑筑惕惕心动悸，怔怔忡忡不自安，饮多尿少为停水，厥冷汗后是虚寒。**\n> 【注】心下筑筑惕惕、怔怔忡忡，谓悸病之状也。饮水多而小便少，水停心下之悸也，宜茯苓甘草汤，或五苓散。厥冷为寒，宜真武汤。汗后为虚，宜小建中汤。或不因汗后，是虚之甚也，宜炙甘草汤。", "白话": "心下像小锤乱敲（筑筑惕惕）、心跳慌乱不能自安，就是悸病的样子。**喝水多而小便少＝水停心下**的悸，用茯苓甘草汤或五苓散；**手脚冷＝寒**，用真武汤；**发汗之后的悸＝虚**，用小建中汤；若不因发汗也悸，是**虚到极点**，用炙甘草汤。"}, {"source": "医宗金鉴心悸条文注释｜二、金匮要略注·惊悸篇——惊与悸的脉辨（动弱分惊悸）", "原文": "「寸口脉动而弱，动即为惊，弱即为悸。」【注】动即为惊，以惊为外触而动也；弱即为悸，以悸为内生而怯也。【集注】徐彬曰：惊为外邪袭心……悸乃神不自主……邪之所袭，因心之虚，故惊悸并见。", "白话": "寸口脉**见动象主惊**（惊由外物触动而发），**脉弱主悸**（悸由内虚而生怯）。惊是外邪袭心、脉来乱动；悸是神不能自主、脉沉无力。正因心虚，邪才乘袭，所以惊悸常同时出现。"}, {"source": "医宗金鉴心悸条文注释｜三、金匮要略注·心下悸——半夏麻黄丸（水饮实悸）", "原文": "「心下悸者，半夏麻黄丸主之。」【按】此方是治寒水心下悸者，与首条之脉弱悸病不合，必是错简。\n> **半夏麻黄丸方**：半夏、麻黄等分。右二味，末之，炼蜜和丸，小豆大，饮服三丸，日三服。", "白话": "心下（胃脘部）悸动的，用半夏麻黄丸主治。半夏、麻黄等分研末，炼蜜为丸小豆大，每次服三丸，每日三次。吴谦按语：本方治**寒水凌心之悸**，与首条「弱脉之虚悸」不合，疑为错简。"}, {"source": "医宗金鉴心悸条文注释｜四、金匮要略注·火邪惊狂——桂枝救逆汤（火逆心悸）", "原文": "「火邪者，桂枝去芍药，加蜀漆牡蛎龙骨，救逆汤主之。」【按】此方是治火逆惊狂者……必是错简。\n> **桂枝救逆汤方**：桂枝三两 甘草（炙）二两 生姜三两 牡蛎（熬）五两 龙骨四两 大枣十二枚 蜀漆（洗去腥）三两。右为末，以水一斗三升，先煮蜀漆，减一升，内诸药，煮取三升，温服一升。", "白话": "因火法（烧针、艾火等）致惊狂的，用桂枝去芍药加蜀漆牡蛎龙骨救逆汤。桂枝、炙甘草、生姜、牡蛎、龙骨、大枣、蜀漆（常山苗，洗去腥），先煮蜀漆，再纳诸药。"}, {"source": "医宗金鉴心悸条文注释｜五、太阳篇注·悸分虚热——小建中汤与「先后辨」", "原文": "「伤寒二、三日，心中悸而烦者，小建中汤主之。」【集注】王肯堂曰……大抵先烦而后悸者是热，先悸而后烦者是虚，治病必求其本者此也。\n> **小建中汤方**：桂枝三两 芍药六两 甘草二两 生姜（切）三两 胶饴一升 大枣（擘）十二枚。右六味，以水七升，煮取三升，去滓，内胶饴，更上微火消解，温服一升，日三服。呕家不可用建中汤，以甜故也。", "白话": "伤寒才两三天就心中悸而烦的，用小建中汤（桂枝汤倍芍药加饴糖）。王肯堂：**先烦后悸属热，先悸后烦属虚**。另：误下后身重、心悸、尺脉微者不可再发汗，须先建中（小建中汤法）。"}, {"source": "医宗金鉴心悸条文注释｜六、太阳篇注·脉结代心动悸——四辨与炙甘草汤", "原文": "「伤寒脉结代，心动悸，炙甘草汤主之。」【注】心动悸者，谓心下筑筑，惕惕然动而不自安也。若因汗下者多虚，不因汗下者多热，欲饮水小便不利者属饮，厥而下利者属寒……总以补中生血复脉为急。\n> **炙甘草汤方**：甘草（炙）四两 生姜（切）三两 桂枝三两 麦门冬半升 麻子仁半斤 大枣（擘）十二枚 人参二两 阿胶二两 生地黄一斤。右九味，以清酒七升，水八升，先煮八味，取三升，去滓，内阿胶，烊消尽，温服一升，", "白话": "心动悸＝心下像小锤敲、惕惕跳动不安。辨证四分：**因汗下而悸多虚；不因汗下多热；想喝水、小便不利属饮；手冷下利属寒**。脉结代之悸不论表证，急当补中生血复脉。炙甘草汤九味，清酒加水先煮八味，阿胶烊化，日三服，又名复脉汤。"}, {"source": "医宗金鉴心悸条文注释｜七、杂病心法要诀·虚损门——归脾汤、天王补心丹（怔忡虚损方阵）", "原文": "归脾汤 17.**归脾思虑伤心脾，热烦盗汗悸惊俱，健忘怔忡时恍惚，四君酸远木归耆。【注】悸，心自跳动也。惊，目触物骇也。健忘，言事易忘也。怔忡，心冲动甚也。恍惚，心时不明也。方乃四君子，加酸枣仁，远志，木香，当归，黄耆。\n> **天王补心丹 16.**天王补心心虚损，健忘神虚烦不眠，柏子味苓归地桔，三参天麦远朱酸。【注】即柏子仁、五味子、茯苓、当归、生地、桔梗、丹参、人参、元参、天冬、麦冬、远志、", "白话": "归脾汤治思虑伤心脾：心烦发热、盗汗、心悸惊惕、健忘怔忡、恍惚，方用四君子（参术苓草）加酸枣仁、远志、木香、当归、黄芪。天王补心丹治心虚损、健忘神虚、烦而不眠，即柏子仁、五味子、茯苓、当归、生地、桔梗、丹参、人参、玄参、天冬、麦冬、远志、朱砂、酸枣仁。"}, {"source": "医宗金鉴心悸条文注释｜八、删补名医方论·朱砂安神丸＋神病治法＋九气（惊则气乱）", "原文": "朱砂安神丸**：治心神昏乱，惊悸怔忡，寤寐不安。朱砂（另研）、黄连各半两，当归二钱，生地黄三钱，甘草二钱。右为细末，酒泡蒸饼丸如麻子大，朱砂为衣。每服三十丸，卧时津液下。\n> **神病治法 4.**内生不恐心跳悸，悸更惊惕是怔忡，善忘前言曰健忘，如昏似慧恍惚名，失志伤神心胆弱，痰饮九气火相乘，清热朱连归地草，余病他门治法精。\n> **诸气总括 1.**……恐则气下伤精志，惊心无倚乱怔忡……【注】若", "白话": "朱砂安神丸治心神昏乱、惊悸怔忡、睡醒不安：朱砂、黄连各半两，当归二钱，生地三钱，甘草二钱，丸剂睡前服。神病总诀：**不因恐吓而自心跳者为悸；悸而兼惊惕者是怔忡**；善忘前言叫健忘；似昏似慧叫恍惚——总由**心虚胆弱，痰饮、九气、火乘虚而入**；心气热先用朱砂安神丸（朱连归地草），其余按虚损、九气、癫痫、痰饮门合证选方。九气之中，**惊则气乱**：心无所倚、神无所归、虑无所定，发为怔忡心动不安。"}, {"source": "医述心悸条文注释｜一、经义（《素问》惊恐病机总纲）", "原文": "东方青色，入通于肝，其病发惊骇。○肝气虚则恐，实则怒。○惊则心无所倚，神无所归，虑无所定，故气乱矣。○忧愁恐惧则伤心。○恐则精却，却则上焦闭，闭则气还，还则下焦胀，故气下行矣。（《素问》）", "白话": "东方青色之气通于肝，肝病易发惊骇；肝气虚则恐惧，肝气实则易怒。**受惊则心无所依靠、神无所归藏、思虑无法安定，所以气机逆乱**。忧愁恐惧都能伤心。恐惧则阴精退却，上焦闭塞，气还于下，下焦胀满，气往下走。"}, {"source": "医述心悸条文注释｜二、惊悸怔忡鉴别（《医学正传》＋李东垣＋《赤水玄珠》）", "原文": "惊悸者，忽若有惊，惕惕然心中不安，其动也，有时。怔忡者，心中惕惕然动摇不静，其作也，无时。（《医学正传》）\n> 有触而心动曰惊。无惊而自动曰悸，即怔忡也。（李东垣）\n> 恐与惊悸相似而实非也。子和云：惊者为自不知，恐者为自知故也。（《赤水玄珠》）", "白话": "惊悸**是忽然像受了惊、心中惕惕不安，**跳动有时有止**；**怔忡**是心中惕惕跳动摇动不静，**发作没有定时**。受外触而心动的叫「惊」；没有外触自己跳动的叫「悸」，也就是怔忡。恐惧与惊悸相似而实不同：受惊时自己不知（无意识的反射），恐惧时自己清楚（如有人追捕、不敢独坐、夜里须灯照）。"}, {"source": "医述心悸条文注释｜三、怔忡病机正源（张景岳论）——本篇辨证纲领", "原文": "怔忡之病，心胸筑筑振动，惶惶惕惕，无时得安者是也。然古无是名，其在《内经》则曰：胃之大络，名曰虚里，出于左乳下，其动应衣，宗气泄也……此证惟阴虚劳损之人乃有之。盖阴虚于下，则宗气无根而气不归原，所以在上则浮撼于胸臆，在下则振动于脐旁。虚微者动亦微，虚甚者动亦甚……若或误认为痰火而妄施清利，则速其危矣。（张景岳）", "白话": "怔忡就是心胸处筑筑振动、惶惶惕惕、无时安宁的病。古时没有「怔忡」这个病名，《内经》说的「**虚里（胃之大络）其动应衣，宗气泄也**」、越人和仲景说的「动气在上下左右之辨（诸动气皆不可汗下）」，都属怔忡之类。此证**只有阴虚劳损的人才会得**：阴虚于下则宗气失去根本、气不归元，所以在上浮撼胸臆，在下振动脐旁——虚轻微的动也轻微，虚甚的动也甚。患者须**节欲节劳、切戒酒色**；治宜养气养精、滋培根本。**如果误认作痰火而妄用清利，就加速其危险。**"}, {"source": "医述心悸条文注释｜四、惊有二证＋丹溪血虚痰论＋《己任编》心肾论", "原文": "惊有二证：有因病而惊者，有因惊而病者……若因惊而病者……是宜安养心神，滋培肝胆，当以专扶元气为主治。又如惊则气乱，恐则气下，惊恐虽同类，而不知恐之伤人尤甚于惊。（张景岳）\n> 怔忡大概属血虚与痰。有思虑便动者属虚，时作时止者，痰因火动也。瘦人多是血虚，肥人多是痰饮。时觉心跳者，是血少不能养心也。（朱丹溪）\n> 怔忡，心血少也。其原起于肾水不足，不能上升，以致心火不能下降。治宜归脾汤，去木香加麦、味", "白话": "惊分两类：因病而惊（外邪/岁气所致，治其客邪）与因惊而病（闻见夺气，宜安养心神、滋培肝胆、扶元气为主）。惊是气乱、恐是气下，**恐比惊伤人更甚**（惊出于暂可复，恐积于渐难解）。——朱丹溪：怔忡大抵属**血虚与痰**：一想事就跳的属虚；时作时止的，是痰因火动；**瘦人多血虚，肥人多痰饮**；时时觉心跳的是血少不能养心。——《己任编》：怔忡是心血少，根源于**肾水不足不能上济、心火不能下降**，用归脾汤去木香加麦冬、五味子、枸杞，送服都气丸。"}, {"source": "医述心悸条文注释｜五、脉候与结代之辨", "原文": "寸口脉动而弱，动则为惊，弱则为悸。（《金匮》）\n> 结促之止，止无常数；代脉之止，止有常数。结促之止，一止即来，代脉之止，良久方至。《内经》以代脉之见，为脏气衰微，脾经脱绝之候。", "白话": "寸口脉动而弱：**动脉主惊，弱脉主悸**（《金匮要略》）。结脉、促脉的停跳**没有固定规律**，代脉的停跳**有固定规律**；结促停一下马上恢复，代脉停后要过很久才来。《内经》认为见到代脉是**脏气衰微、脾气脱绝**的危候。"}, {"source": "医述心悸条文注释｜六、选案（辨证失治教训）", "原文": "一女年十余岁，病心悸，常若有人捕之，欲擗地而无所容……医者以为心病，用安神丸、镇心丹，不效。诊脉细弱而缓。谓曰：此胆病，服温胆汤而安。（汪石山）\n> 余尝病怔忡、盗汗，补心肾无功，乃加猪心数片引之，遗已。药贵向导，不可不审。（王宇泰）", "白话": "一女十余岁心悸、像有人追捕、惶惶无地容身，前医按心病用安神丸、镇心丹无效；汪石山诊脉细弱而缓，断为**胆病**，服温胆汤而安。——王宇泰自述：曾患怔忡盗汗，补心肾无效，后在方中加**猪心数片作引经药**，一次即愈——用药贵在引经报使，不可不审。"}, {"source": "医述心悸条文注释｜七、方论三条（复脉汤/温胆汤/生脉散）＋伤寒条柯注", "原文": "伤寒脉结代，心动悸者，炙甘草汤主之。……方内旧本用麻仁者误。当用枣仁以安神，结代可和，而悸动可止矣。（柯韵伯）\n> 按：此汤，仲景用治伤寒邪少虚多，脉结代，心动悸之圣方。又名炙甘草汤。《千金翼》用治虚劳，《外台》用治肺痿。（复脉汤方论）\n> 温胆汤：胆为中正之官，清静之府……若大病后，或久病……致伤少阳和气，以故虚烦惊悸者，中正之官以郁蒸而不安也。\n> 生脉散，本复脉立法……厥阴病，外寒内热，心动", "白话": "伤寒见脉结代、心动悸，用炙甘草汤。柯韵伯认为方中**麻仁是传抄之误，应当用酸枣仁安神**，则结代可调、悸动可止。——复脉汤方论：仲景用它治伤寒**邪少虚多、脉结代心动悸**，是圣方；《千金翼》用治虚劳，《外台》用治肺痿。——温胆汤方论：胆为中正之官、清静之府；大病久病后余热伤少阳和气，致**虚烦惊悸**，是胆被郁蒸而不安。——生脉散从复脉汤立法：少阴里寒外热用通脉四逆温阳；厥阴外寒内热、心动悸脉结代，制复脉汤**凉补滋阴**。"}, {"source": "医述心悸条文注释｜八、包络论与产后惊悸（心血不足两条）", "原文": "善寐神清，心血有余；怔忡惊悸，心血不足……包络得养，则心神安足，何有惊悸怔忡之患耶？（《冯氏锦囊》）\n> 人之所主者，心也。心之所主者，血也。心血一虚，则神气不守，惊悸所由来也。治当大补血气为主。（薛立斋·产后惊悸恍惚）", "白话": "睡眠好神志清是心血有余；怔忡惊悸是心血不足——**治心病必先养心包络**，包络得养则心神安足。——薛立斋论产后惊悸恍惚：心主血，心血一虚则神气不守，惊悸由此而来，**治当大补血气**；产后恍惚亦然，风象是虚极的假象，固本则诸病自退，专治风则加速危险。"}, {"source": "古今医统大全心悸条文注释｜一、惊悸门·病机（心血为本论＋怔忡惊悸鉴别）", "原文": "人之所主者心，心之所主者血。心血一亏，神气不守，此惊悸之所肇端也。惊者恐也，悸者怖也，血不足则神不守，神不守则惊恐悸怖之证作矣。", "白话": "人身以心为主，心以血为主。心血一亏，神气失去守护，这是惊悸的开端。惊就是恐，悸就是怖；血不足则神不守舍，惊恐悸怖诸证随之发生。"}, {"source": "古今医统大全心悸条文注释｜二、惊悸门·病机（怔忡与惊悸鉴别——持续 vs 阵发）", "原文": "怔忡证，心中惕惕，摇动而不得安静，无时而作者是也。惊悸者，蓦然而跳跃，忽闻声而即惊，或触事而即悸，有时而仆者是也。其为证虽少异，其为治则大同，皆不外乎心、肝、胆过劳伤触而致者也。", "白话": "怔忡**：心中惕惕跳动摇动不得安静，**无定时发作**；**惊悸**：突然跳跃，听到声音即惊、遇事即悸，甚或突然跌倒。二者表现略异而治法大同，都不出心、肝、胆过劳受触所致。"}, {"source": "古今医统大全心悸条文注释｜三、惊悸门·治法（养心安神先行＋丹溪虚实分法＋「惊者平之」行为疗法）", "原文": "治惊悸必先以养心安神之剂，随后豁痰，或用吐法，大便结而脉实者，以朱砂滚痰丸下之。丹溪曰∶惊悸多属血虚，有虑便动，则虚也。时作时止者，痰因火动。瘦人多是血少，肥人只是痰多。时觉心跳者，亦是血虚。怔忡无时，惊悸有时而作。", "白话": "治惊悸必先用养心安神之剂，随后豁痰，或用吐法；大便结而脉实的，用朱砂滚痰丸攻下。朱丹溪说：惊悸多属血虚——一有思虑就发作的是虚证；**时作时止的是痰因火动**；瘦人多血少，肥人多痰多；时时心跳也是血虚。怔忡无定时发作，惊悸有时而作。"}, {"source": "古今医统大全心悸条文注释｜五、促结代脉辨（结促代三分——心律失常脉学总纲）", "原文": "仲景云∶脉来缓，时一止复来者名曰结……脉来动而中止不能自还……代也，得此脉者必难治。故有结脉者有促脉者有代脉者。结者阴也，阴盛则结。脉来缓，时一止复来曰结，主胸满烦躁。促者阳也，阳盛则促。脉来数，时一止复来曰促，主积聚气痞，忧思所成。大抵结促之脉虽时一止，为病脉，非死也，惟代者真死矣。仲景《伤寒论》云∶脉促代，心悸动，炙甘草汤主之。", "白话": "脉来缓、时有一停随即恢复的叫**结**；脉跳动中止不能自行恢复的叫**代**，见此脉难治。故脉分结、促、代三种：结属阴，阴盛则结，主胸满烦躁；**促属阳，阳盛则促，脉来数、时一止复来，主积聚气痞，忧思所致**。大抵结促虽有停跳，是病脉而非死脉；惟**代脉是真死候**。仲景说「脉促代，心悸动，炙甘草汤主之」。"}, {"source": "古今医鉴心悸条文注释｜一、怔忡、惊悸专篇——病名定义与总病机", "原文": "脉：** 心中惊悸，脉必大结；饮食之悸，沉伏动滑。\n> **病：** 夫怔忡者，心中躁动不安，惕惕然如人将捕是也。多因富贵戚戚，贫贱不遂所愿而成。属血虚，有虑便动；属虚，时作时止者。痰因火动，瘦人多是血少，肥人属痰。夫惊悸者，蓦然而跳跃，惊动如有欲厥之状，有时而作者是也，属血虚。或时觉心跳，亦是血虚。盖人之所主者，心；心之所养者，血。**心血一虚，神气不守，此惊悸之肇端也**。又曰：惊者，恐怖之谓", "白话": "脉法**：心中惊悸的脉象多大而结；饮食积滞所致的心悸，脉沉伏动滑。\n**病机**：怔忡——心里躁动不安、惕惕跳动像有人要抓自己，多因患得患失、愿望不遂而起；属血虚，一有思虑就发作；属虚证，时作时止；痰因火动者，瘦人多血少，肥胖人多痰。惊悸——突然跳动一下、像要晕厥，阵发，属血虚；时常觉得心跳也是血虚。**心主神明靠血养，心血一虚则神气不守，是惊悸的开端**。惊就是恐怖之意。**怔忡、健忘、惊悸三个病名不同而病根相同**。"}, {"source": "古今医鉴心悸条文注释｜二、怔忡惊悸六方——分证论治的方阵", "原文": "朱砂安神丸** 治血虚心烦懊憹，惊悸怔忡，胸中气乱。朱砂（五钱，水飞过，另研） 黄连（酒洗，六钱） 生甘草（炙，二钱半） 生地黄（一钱半） 当归（二钱半）。上为细末，蒸饼为丸，如黍米大，每服三五十丸，食后、临卧津咽下。\n> **安神补心汤** 当归（一钱二分） 川芎（七分） 白芍（一钱，炒） 生地黄（一钱二分） 白术（一钱） 茯神（一钱二分） 远志（甘草水泡、去心，八分） 酸枣仁（炒，八分） 麦门", "白话": "六方分证：①**朱砂安神丸**——血虚心烦懊憹、惊悸怔忡、胸中气乱（朱砂五钱水飞另研、黄连酒洗六钱、炙甘草二钱半、生地一钱半、当归二钱半，蒸饼丸黍米大，每服三五十丸）；②**安神补心汤**——归芎芍地术苓志枣麦芩玄草养血安神；③**养心汤**——忧愁思虑伤心、惊悸不宁、痰多嗜睡（黄芪、二苓、夏曲、归芎、肉桂、远志、柏子仁、五味、枣仁、人参、生地），**兼停水怔忡加槟榔、赤茯苓**；④**参归腰子**——心气怔忡自汗，人参当归煮猪腰子，一二服即愈；⑤**琥珀定智丸**——补心生"}, {"source": "古今医鉴心悸条文注释｜三、脉法——结代促散与「伤寒心悸而脉代」", "原文": "代脉** 动而中止，不能自还，因而复动，由是复止，寻之良久，乃复强起曰代。主形容羸瘦，口不能言……若因病而气血骤损，以致元气不续，或风家、痛家、脉见代止，只为病脉。**故伤寒家亦有心悸而脉代者**，心腹痛亦有结涩止代不匀者。盖凡痛之脉，不可准也。又妊娠亦有脉代，此必二月胎也。\n> **结脉** 按之往来迟缓，时一止复来曰结。阴独盛而阳不能相入也……故张仲景谓结、促皆病脉，然渐加即死，渐退即生。\n>", "白话": "代脉**：跳动中止、不能自行恢复、良久才再起。主形瘦体弱；若是病中气血骤损、元气不续所致，或见于痛证，只是病脉（可治）——**所以伤寒家中也有心悸而见代脉的**，心腹痛也可见结涩止代不匀（痛证脉不可作准）。孕妇亦见代脉，多是孕二月。**结脉**：往来迟缓、时有一止即来，主阴盛阳衰气血凝滞；仲景说结、促都是病脉，渐加重则死、渐减轻则生。**散脉**：浮散大而无力，主气血耗散、阳虚不敛，也主心气不足。**动脉**：如豆大跳动，主痛、惊。"}, {"source": "古今医鉴心悸条文注释｜四、定心汤与三白饮——伤寒瘥后心悸二方", "原文": "定心汤**（秘方）〔按此方治心慌之剂〕治伤寒瘥后心下怔忡。生地汁、童便各半盏，二味和合，重汤煮数沸服。\n> **三白饮** 治伤寒时气，热极狂乱者，及发热不退。鸡子（一个，用清） 白蜜（一大匙） 芒硝（三钱）。上合作一处，用凉水和下。**如心不宁者，北人谓之心慌也，加珍珠末五分**。\n> **泻心导赤饮** 治伤寒……渐变神昏不语……邪热传入少阴心经也……山栀子 黄芩 麦门冬 滑石 人参 犀角 知", "白话": "定心汤**（秘方，注明是治心慌的方子）：治**伤寒瘥后心下怔忡**。生地汁、童便各半盏和匀，隔水煮沸服。\n- **三白饮**：治伤寒时气高热狂乱、发热不退（鸡子清、白蜜一大匙、芒硝三钱，凉水调下）；**如心神不宁（北方人叫「心慌」）加珍珠末五分**。\n- **泻心导赤饮**：治邪热传入少阴心经、神昏不语（栀芩麦滑参犀知茯连草）。"}, {"source": "古今医鉴心悸条文注释｜五、痰饮、虚劳、妇人门——跨科心悸条文", "原文": "（痰饮）其为病也……为眩晕，为嘈杂，**为怔忡惊悸**，为癫狂……皆痰所致。百病中多有兼痰者。\n> （滚痰丸）一切**心下怔忡恍惚，如畏人将捕之状，怵惕不安**，阴阳关格，变生乖症，每服七八十丸。\n> （虚劳·清离滋坎汤）心下怔忡，加远志、酸枣仁。（东实两虚泻南补北汤）**心下怔忡惊悸，加茯神、远志、柏子仁、酸枣仁**。\n> **天王补心丹** 宁心益志，壮力强精，安神魂，**定惊悸怔忡**，祛烦", "白话": "痰饮门**：痰饮致病可见眩晕、嘈杂、怔忡惊悸、癫狂等；滚痰丸（大黄、黄芩、沉香、青礞石）主治一切「心下怔忡恍惚、如畏人将捕、怵惕不安」之怪症。\n- **虚劳门**：清离滋坎汤加减——心下怔忡加远志、酸枣仁；泻南补北汤——心下怔忡惊悸加茯神、远志、柏子仁、酸枣仁；天王补心丹——安神定惊悸怔忡。\n- **妇人门**：加减逍遥散心慌心跳加枣仁远志；百合汤治血虚劳怯心慌头痛；通瘀饮治产后恶露不行、心慌昏沉。"}, {"source": "古今医鉴心悸条文注释｜六、健忘门与不寐门——心悸的认知-睡眠共病", "原文": "归脾散** 治忧思过度，劳伤心脾，令人转盼遗忘，**心下怔忡**。黄 （炙） 人参 白术 茯神（去木） 当归 远志 酸枣仁 龙眼肉（各二钱二分） 木香（一钱） 甘草（炙，五分）。\n> **温胆汤** 治病后虚烦不得卧，及**心胆虚怯，触事易惊，短气悸乏**，或复自汗。半夏（七钱） 竹茹 枳实（各三钱） 陈皮（四钱半） 白茯苓（去皮） 甘草（炙，二钱二分半）。\n> **高枕无忧散**（云林制）治心胆", "白话": "归脾散**：治忧思过度劳伤心脾、健忘心下怔忡（黄芪、人参、白术、茯神、当归、远志、枣仁、龙眼肉、木香、炙甘草）。\n- **温胆汤**：治病后虚烦不眠、心胆虚怯、遇事易惊、短气心悸、自汗。\n- **高枕无忧散**：治心胆虚怯昼夜不睡、百方无效（参、石膏、陈夏苓枳、竹茹、麦冬、龙眼、甘草、枣仁）。\n- 总论：惊悸、健忘、怔忡、失志不寐、心风都是**胆痰上扰（胆涎沃心）致心气不足**；若一味用凉药，心火更微、痰涎更盛，须理痰气为治。"}, {"source": "古今医鉴心悸条文注释｜七、药性与妇人心慌——本草与跨科补充", "原文": "（药性赋）茯苓安惊利窍，益气生津，和中用白，而导水用赤，禁与阴虚。……远志……壮神益志，梦遗惊悸何愁。……茯神去木益心脾，开心助志而除健忘。酸枣取仁宁魂魄，多眠用生而不眠炒。\n> （产后）一、产后血虚发热，咳嗽吐痰，喘满，**心慌**、口干，宜用茯苓补心汤加麦门冬、五味子煎服。\n> **济阴至宝丹**（云林制）……**定心悸**，安神魂……（当归、白芍、二苓、术、陈皮、知母、贝母、香附、柴胡、薄荷", "白话": "本草要点：**茯苓**安惊利窍（白茯苓和中、赤茯苓导水，阴虚慎用）；**远志**壮神益志治惊悸；**茯神**益心脾除健忘；**酸枣仁**宁魂魄（治多眠用生、治不眠用炒）。产后血虚发热、喘满心慌口干——茯苓补心汤加麦冬、五味子。济阴至宝丹调经定心悸；加味归脾汤治健忘怔忡惊悸不宁。"}, {"source": "奇效良方心悸条文注释｜一、附论总纲——怔忡病机（引《原病式》心血不足论）", "原文": "《原病式》曰∶夫怔忡为病，躁扰动烦热，扰乱而不宁，火之体也……或逆气动躁者，由水衰火旺，而犹火之动也，故心胸躁动，谓之怔忪，此心血不足也。盖心主血……血富则心主自安矣。多因汲汲富贵，戚戚贫贱……真血虚耗，心主失辅，渐成怔忡。怔忡不已，变生诸证。舌强恍惚，善忧悲，少颜色，皆心病之候。《难经》云∶损其心者益其荣，法当专补真血。", "白话": "怔忡病：心胸躁动烦热、扰乱不宁，属火之象。其因是**水衰火旺、心血不足**——心主血，血足则心安；多由名利思虑、真血暗耗，心失所养，渐成怔忡，久则舌强、恍惚、善悲、面色少华。《难经》：**损其心者补其营血，当专补真血**。"}, {"source": "奇效良方心悸条文注释｜二、附论·惊悸辨——惊与悸分治（豁痰定惊/逐水消饮/温养心血）", "原文": "且夫惊悸即动悸也。动之为病，惕然而惊，悸之为病，心下怯怯，如人所捕，皆心虚胆怯之所致也……曰惊曰悸，其可无辞乎？惊者恐怖之谓，悸者怔忡之谓……惊者去之，豁痰定惊之剂，悸者去之，逐水消饮之剂，所谓扶虚不过温养心血，和平心气而已。若一概以刚燥用工，或者心火自炎，反助风热之证，可不慎乎？", "白话": "惊悸即动悸。**惊＝惕然而惊、恐怖之谓；悸＝心下怯怯如人将捕、怔忡之谓**，皆由心虚胆怯。心虚而郁痰者，闻大声、见异物、遇险而惊（豁痰定惊）；心虚伤肾水者，胸中渗漉、虚气流动而悸（逐水消饮）。**扶正不过温养心血、和平心气**；切忌一概刚燥，反助心火风热。"}, {"source": "奇效良方心悸条文注释｜三、怔忡主治方（一）——补血养心线（方名待核）", "原文": "治思虑过多，耗伤心血，心血既伤，神无所守。是以怔忡恍惚，善悲忧，少颜色，夜不多寐，小便或浊。当归（去芦，酒浸） 黄 （去芦） 小草 酸枣仁（炒，去壳） 柏子仁（炒） 茯神（去木） 木香（不见火） 麦门冬（去心） 白芍药 人参（去芦） 紫石英（ 研） 甘草（炙，各一钱）。上作一服，水二盅，生姜三片，红枣一枚，煎一盅，不拘时服。\n> 治心血虚寒，怔忡不已，痰多恍惚。龙齿 远志（去心，甘草水煮） 酸枣仁", "白话": "方一（方名待核）**：治思虑过多耗伤心血、怔忡恍惚、善悲忧、面色少华、夜寐不安。当归、黄芪、小草（远志苗）、炒枣仁、炒柏子仁、茯神、木香、麦冬、白芍、人参、紫石英、炙甘草各一钱，姜枣煎。**方二（方名待核）**：治心血虚寒、怔忡不止、痰多恍惚。龙齿、远志、枣仁、官桂、当归、琥珀、炮附子、南星、木香、沉香、紫石英、熟地各半两，蜜丸朱砂衣，枣汤下五十丸。"}, {"source": "奇效良方心悸条文注释｜四、怔忡主治方（二）——停饮怔忡三线（茯苓甘草汤/姜术类/茯苓饮子类）", "原文": "治心下停水忪悸。茯苓（去皮） 桂枝（各三钱） 生姜（半两） 甘草（二钱）。上作一服，水二盅，煎至一盅，不拘时服。\n> 治虚证，停饮怔忡。白姜（生） 白术 茯苓（去皮） 半夏曲（各二钱） 辣桂（去皮） 甘草（炙，各半钱）。上作一服，水二盅，生姜三片，红枣一枚，煎一盅，不拘时服。\n> 治痰饮蓄于心胃，怔忡不已。赤茯苓（去皮） 半夏（汤泡） 茯神（去木） 麦门冬（去心） 橘皮（去白，各一钱半） 沉香（不", "白话": "①茯苓甘草汤**（方名可核，即仲景方）：治心下停水心悸。茯苓、桂枝各三钱，生姜半两，甘草二钱。**②（方名待核，类姜术汤）**：治虚证停饮怔忡。生姜、白术、茯苓、半夏曲各二钱，肉桂、炙甘草各半钱，姜枣煎。**③（方名待核，类茯苓饮子）**：治痰饮蓄于心胃、怔忡不止。赤茯苓、半夏、茯神、麦冬、橘皮各一钱半，沉香、槟榔、炙甘草各一钱，姜五片煎。"}, {"source": "奇效良方心悸条文注释｜五、怔忡主治方（三）——心胆惊悸线（十味温胆汤/定志丸/归脾汤）", "原文": "治心胆虚怯，触事易惊，梦寐不祥，异象感触，遂致心惊气郁，生痰涎，涎与气搏，变生诸证，或短气悸乏，或复自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。半夏（汤泡） 枳实（麸炒） 陈皮（去白，各二钱） 白茯苓（去皮，一钱半） 酸枣仁（炒） 远志（去心，甘草水煮） 五味子 熟地黄（酒洗，焙） 人参（去芦，各一钱） 粉甘草（炙，半钱）。\n> 治心气不足，恍惚多忘，常服安神定志。远志（去苗心） 菖蒲（各二两）", "白话": "①十味温胆汤**（方名待核·与十味温胆汤组成同）：治心胆虚怯、触事易惊、短气悸乏、自汗浮肿、坐卧不安。半夏、枳实、陈皮各二钱，茯苓一钱半，枣仁、远志、五味子、熟地、人参各一钱，炙甘草半钱。**②定志丸**（方名待核）：远志、菖蒲各二两，人参、茯苓各三两，蜜丸朱砂衣。**③归脾汤**（方名待核·即归脾汤）：人参、木香各一钱，茯神、龙眼肉、黄芪、枣仁、白术各一钱半，炙甘草半钱。"}, {"source": "寿世保元心悸条文注释｜一、惊悸门总论——动为惊、弱为悸", "原文": "寸口脉动而弱。动为惊。弱为悸。心中惊悸。脉必大结。饮食之悸。沉伏动滑。夫惊悸即动悸也。动之为病。惕然而惊。悸之为病。心下怯怯。如恐人捕。皆心虚胆怯之所致也。", "白话": "寸口脉见**动脉主惊、弱脉主悸**；心中惊悸者脉多大而结，饮食所致之悸脉沉伏动滑。惊悸即「动悸」：动的病态是突然惕然而惊，悸的病态是心下怯怯不安、像有人要抓自己——**都是心虚胆怯所致**。"}, {"source": "寿世保元心悸条文注释｜二、怔忡门总论——痰火、血虚、体质三分", "原文": "夫怔忡者。心中不安。惕惕然如人将捕是也。属血虚。有虑便动。属虚。时作时止者。痰因火动。瘦人多是血少。肥人属痰。怔忡者。心胸躁动。谓之怔忡。此心血不足也。多因汲汲富贵。戚戚贫贱。不遂所愿而成。", "白话": "怔忡是**心中不安、惕惕跳动如有人要抓**的样子。属血虚；一有思虑就跳动的属虚；**时作时止的属痰因火动**；瘦人多是血少，肥人多属痰。怔忡即心胸躁动不宁，病本心血不足，多由汲汲于富贵、戚戚于贫贱、欲望不遂郁结而成。"}, {"source": "寿世保元心悸条文注释｜三、★归脾汤（寿世保元本·十味加味法）", "原文": "一论思虑伤脾。不能摄血。致血妄行。或吐或下。或健忘怔忡。惊悸不寐。发热盗汗。或心脾伤痛。嗜卧少食。大便不调。或血虚发热。或肢体重痛。妇人月经不调。赤白带下。或晡热内热。瘰 流注。不能消耗溃敛。或思虑伤脾。而作疟痢。\n> **归脾汤** 主方。人参（三钱） 黄 （二钱） 白术（一钱五分） 白茯苓（三钱） 当归（三钱） 远志（一钱甘草水泡去心） 龙眼肉（十枚） 酸枣仁（三钱炒） 木香（八分） 甘草（六", "白话": "思虑伤脾、不能统摄血脉，致血外溢（吐血、便血），或健忘怔忡、惊悸不寐、发热盗汗，或心脾痛、嗜卧少食、大便不调，或血虚发热、肢体重痛，妇女月经不调、赤白带下、午后内热、瘰疬流注久不收口，或思虑伤脾而成疟痢者。**归脾汤主方**：人参三钱、黄芪二钱、白术一钱五分、白茯苓三钱、当归三钱、远志一钱（甘草水泡去心）、龙眼肉十枚、酸枣仁三钱（炒）、木香八分、炙甘草六分。切片，姜枣煎服。加柴胡、附子名**加味归脾汤**；神不宁而健忘者，倍酸枣仁、茯神、当归，加柏子仁。"}, {"source": "寿世保元心悸条文注释｜四、天王补心丹与安神定志丸——怔忡不寐对药", "原文": "一论宁心保神。益血固精。壮力强志。令人不忘。清三焦。化痰涎。祛烦热。疗咽干。除惊悸。定怔忡。育养心神。大补元气。读书劳神。勤政劳心。并宜服之。\n> **天王补心丹** 怀生地（四两） 天门冬（去心） 桔梗（各五钱） 当归 柏子仁 酸枣仁（炒） 五味子（各一两） 麦门冬（去心） 远志（甘草水泡去心） 白茯苓（去皮） 元参 丹参 人参（各一两）〔一方加酒炒黄连五钱〕", "白话": "功能**宁心保神、益血固精、除惊悸定怔忡**；治读书劳神、勤政劳心所致心悸健忘。天王补心丹：生地四两、天冬、桔梗各五钱，当归、柏子仁、炒枣仁、五味子各一两，麦冬、远志、茯苓、玄参、丹参、人参各一两；为末炼蜜丸，朱砂为衣，每服二三十丸，临卧灯心竹叶汤下。〔另一方加酒炒黄连五钱〕"}, {"source": "张氏医通心悸条文注释｜一、悸·脉辨总纲（金匮发端）", "原文": "金匮云。寸口脉动而弱。动则为惊。弱则为悸。\n> 惊自外邪触入而动。故属阳。阳变则脉动。悸自内恐而生。故属阴。阴耗则脉弱。", "白话": "《金匮要略》说：寸口脉动而弱——**动是惊，弱是悸**。张璐阐发：惊由外邪触动而发，属阳，阳变所以脉动；悸由内生恐惧而来，属阴，阴耗所以脉弱。"}, {"source": "张氏医通心悸条文注释｜二、金匮三悸方证（张璐注解）", "原文": "心下悸者。半夏麻黄丸主之。此形寒饮冷。经脉不利。水停心下而致动悸。故用麻黄以散营中寒。半夏以散心下水……用丸不用汤者。取缓散水。不取急汗也。\n> 卒呕吐。心下痞。膈间有水。眩悸者。半夏茯苓汤主之。悸则心受水凌。非半夏可独治。必加茯苓以去水。水去则神安而悸愈矣。\n> 假令瘦人脐下有悸。吐涎沫而颠眩。此水也。五苓散主之。", "白话": "心下悸用**半夏麻黄丸**：此因形寒饮冷、经脉不利、水停心下而动悸，故用麻黄散营中寒、半夏散心下水；与伤寒水停心下用小青龙汤同理。首条以脉弱为悸，而此方用麻黄半夏散寒治水，可知其脉必不弱，非弦即紧——脉弱是心气不足，岂是此药所宜？用丸不用汤，取缓散水而不取急汗。突然呕吐、心下痞、膈间有水、眩悸者用**半夏茯苓汤**：悸是心受水凌，非半夏可独治，必加茯苓去水，水去神安悸愈。瘦人脐下悸、吐涎沫而颠眩，此水证，用**五苓散**：瘦人火水之盛，水邪抑郁于阴分不得升发，故脐下作悸，郁发"}, {"source": "张氏医通心悸条文注释｜三、悸即怔忡论（病机总断）", "原文": "悸即怔忡之谓。心下惕惕然跳。筑筑然动。怔怔忡忡。本无所惊。自心动而不宁。即所谓悸也。\n> 盖水衰火动则为烦。水乘火位则为悸。原病式曰。水衰火旺。必烦渴引饮。水停心下而为悸也。\n> 心下悸有气虚血虚。属饮属火之殊。", "白话": "悸就是怔忡：心下提心跳动、筑筑然跳，怔怔忡忡，本来无所惊吓而心动不宁，就是悸。张璐病机总断：**水衰火动则发烦，水乘火位则发悸**（刘完素说：水衰火旺必烦渴引饮，水停心下则为悸）。心下悸有气虚、血虚、属饮、属火的不同。"}, {"source": "张氏医通心悸条文注释｜四、悸证治全纲（张璐辨治体系核心）", "原文": "夫气虚者。由阳气内微。心下空虚。内动为悸。……千金定志丸、千金茯神汤。或六君子加菖蒲、远志。血虚者。由阴气内虚。虚火妄动。归脾汤加丹参、麦冬。\n> 停饮者。水停心下……半夏茯苓汤、茯苓甘草汤。或二陈汤加白术、猪苓、泽泻。有表邪挟饮。半夏麻黄丸、小青龙汤选用。\n> 火旺者。因水不能制火。故时悸时烦。跳动不宁。天王补心丹。不应。六味丸加五味、麦冬、远志。\n> 有营卫涸流。脉来结代者。必补气益血生精。炙", "白话": "心下悸的辨治总纲：\n- **气虚**（阳气内微、心下空虚、内动为悸）→ 千金定志丸、千金茯神汤，或六君子汤加菖蒲、远志；\n- **血虚**（阴气内虚、虚火妄动）→ 归脾汤加丹参、麦冬；\n- **停饮**（水停心下）→ 半夏茯苓汤、茯苓甘草汤，或二陈汤加白术、猪苓、泽泻；表邪挟饮 → 半夏麻黄丸、小青龙汤选用；\n- **火旺**（水不制火、时悸时烦、跳动不宁）→ 天王补心丹；不应，六味丸加五味子、麦冬、远志；\n- **营卫涸流、脉来结代** → 必补气益血生精，**炙甘草汤**"}, {"source": "张氏医通心悸条文注释｜五、悸·诊法", "原文": "〔诊〕沉细属饮。结代者。虚而有饮。虚弱者。属气虚。沉数者。为血热。尺中弦紧。为肾气凌心。寸口脉动而弱。动则为惊。弱则为悸。", "白话": "诊法：脉沉细属饮；**结代者属虚而有饮**；脉虚弱属气虚；沉数为血热；**尺中弦紧为肾气凌心**；寸口脉动而弱——动为惊、弱为悸。"}, {"source": "张氏医通心悸条文注释｜六、石顽医案·老僧悟庵（补养心血误治纠错）", "原文": "石顽治老僧悟庵。心悸善恐。遍服补养心血之药。不应。天王补心丹服过数斤。悸恐转增。面目四肢。微有浮肿之状……察其形。肥白不坚。诊其脉。濡弱而滑。此气虚痰饮侵渍于膈上也。遂以导痰汤稍加参、桂通其阳气。数服而悸恐悉除。更以六君子加桂。水泛作丸。调补中气而安。", "白话": "张璐治老僧悟庵：心悸善恐，遍服补养心血之药无效，天王补心丹吃了数斤，悸恐反而加重，面目四肢微浮肿。张璐察其形体肥白不坚、脉濡弱而滑——断为**气虚痰饮侵渍于膈上**，用导痰汤稍加人参、桂枝通其阳气，数服悸恐全除；再以六君子汤加桂，水泛为丸调补中气而安。"}, {"source": "张氏医通心悸条文注释｜七、惊·肝虚风袭与石顽产后案", "原文": "亦有肝虚风袭之者。本事方治卧则魂梦飞扬。惊悸多魇。通夕不寐。先用独活汤数剂。后用珍珠母丸神效。盖因肝脏本虚。虚风内袭。所以魂游无定……若作心血虚治必殆。\n> 石顽治河南督学汪缄庵媳。产后病虚无气。洒洒然如惊。常时咳青黑结痰。欲咳则心中大动。咳则浑身麻木……脉浮微弦而芤。独左寸厥厥动摇。此必胎前先伤风热。坐草时迸力过甚。痰血随气上逆。冲过膈膜而流入心包也。朝用异功散加童便 淬蛤粉。夕用大剂独参汤下来", "白话": "肝虚风袭**：卧则魂梦飞扬、惊悸多魇、通宵不寐——先用独活汤数剂，后用珍珠母丸神效。因肝虚受风，魂游无定；「**若作心血虚治必殆**」——此证最易愠怒，小怒则惊悸转剧，是肝脏受困之验。\n- **汪缄庵媳案**：产后虚无气、阵阵如惊、咳青黑结痰，欲咳则心中大动、浑身麻木，闻声则头面哄热汗出、神魂如飞越。前医屡用补养心血无效，虚羸转剧。张璐诊脉浮微弦而芤、独左寸厥厥动摇——判为胎前伤风热、产时用力过甚，痰血随气上逆流入心包。朝用异功散加童便淬蛤粉清痰气，夕用大剂独参汤送下来复丹搜"}, {"source": "张氏医通心悸条文注释｜八、张弘蘧怔忡失血案（阴火内伏、误温补戒）", "原文": "石顽治太史张弘蘧精气下脱。虚火上逆。怔忡失血证。诊其右关气口独显弦象。左尺稍嫌微数。余皆微细搏指。明系阴火内伏之象……云自去冬劳心太过。精气滑脱。加以怵惕恐惧。怔忡惊悸不宁。都门之医。峻用人参、桂、附。至岁底稍可。交春复剧如前……怔忡之状。如碓杵。如牵绳。如簸物。如绷绢。如以竹击空。控引头中。如失脑髓之状……总属真元下脱。虚阳上扰之候。当此急宜转关以救垂绝之阴。为疏二方。煎用保元合四君。丸用六味合", "白话": "张璐治翰林张弘蘧：精气下脱、虚火上逆的怔忡失血证。脉右关独弦、左尺微数、余脉微细搏指——明是**阴火内伏**。患者劳心太过、精气滑脱，又怵惕恐惧、怔忡惊悸不宁；京中医生峻用人参、桂、附，年底稍好，交春复发。张璐细述其怔忡之状：像碓杵捣、像牵绳、像簸箕簸物、像绷绢、像竹子击空，牵控头脑如失髓状；梦中自作文、达旦倦怠、便欲失精、精去则神魂飞越。判为真元下脱、虚阳上扰——先时虽属阳气虚脱，但过服辛温峻补致阳暴亢反耗真阴，**当急转关以救垂绝之阴**。处方二方：煎剂用保元汤合四君子汤"}, {"source": "明医指掌心悸条文注释｜一、歌曰——病象总括", "原文": "【歌】惊悸心中常惕惕，如人将捕时惊惑。延缠不已渐怔忡，寤寐神魂多恍惚。精神短少或多痰，健忘之病因而得。皆缘大恐与大惊，触事丧志心神失。", "白话": "惊悸是心中常惕惕跳动、像有人要抓自己、时时惊恐疑惑；**日久不愈则渐渐变成怔忡**，醒里梦里神魂恍惚；精神短少或痰多，进而得健忘之病。其因都是大恐大惊、遇事挫败丧志，致使心神失守。"}, {"source": "明医指掌心悸条文注释｜二、论——心血虚停痰的统一病机（全书核心理论段）", "原文": "【论】夫人之所主者心，心之所养者血。心血一虚，神气失守，神去则舍空，舍空则郁而停痰，痰居心位，此惊悸之所以肇端也。或耳闻大声，目击异物，遇险临危，触事丧志，则心为之忤，使人有惕惕之状，始则为惊悸。久而心虚停饮，水气乘心，胸中渗漉，虚气流动，水既上乘，心火畏之，心不自安，故怏怏然而怔忡也。", "白话": "人身以心为主宰，心以血为营养。**心血一虚，神气失守**；神去则心位空虚，空则气郁停痰，痰占心位——这就是惊悸的起因。或耳闻巨响、目见异物、遇险临危、遇事丧志，则心受触动，出现惕惕惊跳，开始是惊悸；日久心虚停饮，**水气上乘于心**，胸中漉漉水声、虚气流动，水气上凌、心火受制，心不能自安，于是怏怏不宁而成怔忡。\n\n（续段）日久不已，精神短少，心气空虚，神不清而生痰，痰迷心窍，则遇事多忘；亦因思虑过度，病在心脾，故令转盼遗忘，名曰健忘。三者虽有浅深之殊，皆心脾之病，其所由来者一"}, {"source": "明医指掌心悸条文注释｜三、脉——惊悸怔忡脉法", "原文": "【脉】惊悸怔忡，寸动而弱。寸紧关浮，悸病乃作。饮食痰火，伏动滑搏。浮微弦濡，忧惊过却。健忘神亏，心虚浮薄。", "白话": "惊悸怔忡的脉：**寸脉动而弱**；寸紧关浮则悸病发作；饮食痰火所致者脉伏、动、滑、搏；脉浮微弦濡是忧惊已过；健忘属神亏，脉心虚浮薄。"}, {"source": "明医指掌心悸条文注释｜四、惊悸治法——血虚/气血两虚二路", "原文": "惊悸：血虚惊悸者，四物汤加贝母、橘红、黄连、山栀，安神丸。气血两虚者，益荣汤、天王补心丹。\n> **天王补心丹** 人参（四两） 玄参（二两） 杜仲（炒，去丝，四两） 天门冬（三两） 麦门冬（三两） 远志（四两） 熟地黄（六两） 百部（三两） 桔梗（三两） 牡丹皮（四两） 柏子仁（四两） 五味子（四两） 甘草（二两） 茯神（四两） 茯苓（四两） 石菖蒲（四两） 酸枣仁（四两）\n> 末之，蜜丸，每下", "白话": "惊悸属**血虚**者，用四物汤加贝母、橘红、黄连、山栀，或安神丸；属**气血两虚**者，用益荣汤、天王补心丹。天王补心丹：人参四两、玄参二两、杜仲四两、天冬三两、麦冬三两、远志四两、熟地六两、百部三两、桔梗三两、丹皮四两、柏子仁四两、五味子四两、甘草二两、茯神四两、茯苓四两、石菖蒲四两、枣仁四两；为末蜜丸，每服三钱。"}, {"source": "明医指掌心悸条文注释｜五、怔忡治法——★朱雀丸（水气怔忡专方）", "原文": "怔忡：心血虚少，惕惕然恍惚怔忡，益荣汤。痰火盛，心下怔忡者，温胆汤加炒黄连、山栀、当归、贝母。（温胆汤即二陈汤加炒枳壳一钱、竹茹一钱，二陈方见痰证。）水气承心而作怔忡，朱雀丸。心气郁滞，痰气结于心下而作怔忡，四七汤加竹沥、姜汁。\n> **朱雀丸** 治水气怔忡。白茯苓（一两） 沉香（半两）\n> 末之，蜜丸桐子大，每服三十丸，人参汤送下。", "白话": "怔忡分四路：①心血虚少、惕惕恍惚→益荣汤；②痰火盛、心下怔忡→温胆汤加黄连、山栀、当归、贝母（温胆汤即二陈汤加炒枳壳一钱、竹茹一钱）；③**水气上冲于心而怔忡→朱雀丸**（白茯苓一两、沉香半两，蜜丸桐子大，每服三十丸，人参汤送下）；④心气郁滞、痰气结于心下→四七汤加竹沥、姜汁。"}, {"source": "明医指掌心悸条文注释｜六、健忘治法——★归脾汤（存宋本八味原貌）", "原文": "健忘：思虑伤脾，作事忘前失后者，归脾汤。心气不定，恍惚多忘者，定志丸。年老神衰，遇事多忘，二丹丸。痰多郁滞于心脾而善忘者，四七汤加竹沥、姜汁、胆星、栝蒌。\n> **归脾汤** 治怔忡、健忘。白术（一两） 茯神（一两） 黄 （一两） 圆眼肉（一两） 枣仁（炒，一两） 人参（半两） 木香（半两） 甘草（二钱半，炙）\n> 每服锉四钱，姜三片，枣一枚，水煎服。\n> **定志丸** 治恍惚多忘。远志（一两）", "白话": "健忘分四路：思虑伤脾、做事忘前失后→**归脾汤**（治怔忡、健忘）：白术、茯神、黄芪、圆眼肉、炒枣仁各一两，人参、木香各半两，炙甘草二钱半；每次锉四钱，姜三片、枣一枚水煎服。心气不定、恍惚多忘→定志丸（远志、人参、蒲黄、茯苓，辰砂为衣）；年老神衰→二丹丸（丹参、二冬、熟地、茯苓、人参、远志、朱砂、菖蒲，圆眼汤下）；痰多郁滞心脾→四七汤加竹沥姜汁胆星栝蒌。"}, {"source": "普济方心悸条文注释｜一、怔忡惊悸·附论（心血不足论＋惊悸忪悸之辨）", "原文": "夫怔忡者。此心血不足也。盖心主于血。血乃心之主。心乃形之君。血富则心君自安矣。\n> 人之所主者心。心之所养者血。心血一虚。神气不守。此惊悸之所肇端也。曰惊。曰悸。其触事丧志。心为之忤。使人有惕惕之状。是则为惊。心虚而停水。则胸中渗漉。虚气流动。水既上乘。心火恶之。心不自安。使人有怏怏之状。是则为悸。惊者。与之豁痰定惊之剂。悸者。与之逐水消饮之剂。所谓扶虚。不过调养心血。和平心气而已。", "白话": "怔忡是心血不足所致：心主血，血是心的主宰，心是形体的君主，血充足则心君自安。人以心为主、以血为养，心血一虚神气不守，这是惊悸的开端。**惊**：遇事丧志、心受触动，呈惕惕之状；**悸**：心虚而停水，胸中渗漉、虚气流动，水气上乘，心火恶之，心不自安，呈怏怏之状。治法：惊用豁痰定惊剂，悸用逐水消饮剂；扶虚不过调养心血、和平心气。"}, {"source": "普济方心悸条文注释｜二、伤寒心悸·附论（气虚停饮二因＋汗下误治＋歌诀）", "原文": "夫伤寒心悸者。谓心下悸动也。此由伤寒病。发汗以后。因又下之。内有虚热发渴。渴则饮。水气乘心。必振寒而心下悸也。……伤寒心悸者。心忪是也。筑筑踢踢然动。怔怔忪忪不能自安者是矣。心悸之由。不越二种。一者气虚也。二者停饮也。\n> 又歌曰。心悸三阳证自详。粪坚 语胃调汤。冒旋甘桂 真武。小建中兼炙草方。", "白话": "伤寒心悸即心下悸动：伤寒发汗后又攻下，内生虚热口渴而饮水，水气乘心，必振寒而心下悸。伤寒心悸就是「心忪」——心中筑筑踢踢跳动、怔怔忪忪不能自安。**心悸的病因不过两种：一是气虚，二是停饮**。歌诀（原文有残字待核）：心悸从三阳证辨治；大便坚、谵语者调胃承气；头眩用桂甘类/真武汤；小建中汤与炙草（炙甘草汤）并举。"}, {"source": "景岳全书心悸条文注释｜一、论怔忡——病名定义与宗气说", "原文": "怔忡之病，心胸筑筑振动，惶惶惕惕，无时得宁者是也。然古无是名，其在《内经》，则曰∶胃之大络，名曰虚里，出于左乳下，其动应衣，宗气泄也。在越人、仲景，则有动气在上下左右之辨，云∶诸动气皆不可汗下也。凡此者，即皆怔忡之类。", "白话": "怔忡＝**心胸跳动不停、惶惶惕惕、无时安宁**。古无此名，《内经》「虚里（左乳下）其动应衣，宗气泄」、越人仲景的「动气在上下左右之辨（动气不可汗下）」都是同类病变。"}, {"source": "景岳全书心悸条文注释｜二、论怔忡——阴虚劳损为本（景岳虚实辨核心）", "原文": "此证惟阴虚劳损之人乃有之，盖阴虚于下，则宗气无根，而气不归源，所以在上则浮撼于胸臆，在下则振动于脐旁，虚微者动亦微，虚甚者动亦甚。凡患此者，速宜节欲节劳，切戒酒色；凡治此者，速宜养气养精，滋培根本。若或误认为痰火而妄施清利，则速其危矣。", "白话": "怔忡**只见于阴虚劳损之人**：阴虚于下→宗气无根、气不归源→在上胸中浮撼、在下脐旁振动；**虚轻动轻、虚重动重**。患者务必节欲节劳、戒酒色；治疗务必**养气养精、滋培根本**。若误认作痰火而妄用清热攻利之药，只会加速其危。"}, {"source": "景岳全书心悸条文注释｜三、论惊恐——因病而惊 vs 因惊而病", "原文": "惊有二证，有因病而惊者，有因惊而病者……因病而惊者……是当察客邪以兼治其标。若因惊而病者，如惊则气乱，而心无所倚，神无所归，虑无所定之类，此必于闻见夺气而得之，是宜安养心神，滋培肝胆，当以专扶元气为主治……总之主气强者不易惊，而易惊者必肝胆之不足者也。故虽有客邪，亦当知先本后标之义。又如惊则气乱，恐则气下……恐之伤人，尤甚于惊……予尝治暴惊者，十愈其八九；治恐惧者，十不得其一二。", "白话": "惊分两种：**因病而惊**（邪热等病引起惊，如阳明闻木音而惊——治客邪兼治标）与**因惊而病**（受惊后气乱心无所倚——宜安养心神、滋培肝胆、专扶元气）。气强者不易惊，易惊者必肝胆不足，即使有客邪也要**先本后标**。惊出于暂可复，恐积于渐难解；我治暴惊十愈八九，治恐惧十不得一二。"}, {"source": "景岳全书心悸条文注释｜四、论治（一）——心本乎肾与虚证方阵（新方组成抄录）", "原文": "凡治怔忡惊恐者，虽有心脾肝肾之分，然阳统乎阴，心本乎肾，所以上不宁者，未有不由乎下，心气虚者，未有不因乎精，此心肝脾肾之气，名虽有异，而治有不可离者，亦以精气互根之宜然……心脾血气本虚……俱宜七福饮，甚者大补元煎。命门水亏，真阴不足而怔忡不已者，左归饮。命门火亏，真阳不足而怔忡者，右归饮。三阴精血亏损……大营煎或理阴煎。若水亏火盛，烦躁热渴，而怔忡惊悸不宁者，二阴煎或加减一阴煎。若思郁过度，耗伤心", "白话": "怔忡惊恐虽分心脾肝肾，但**阳统乎阴、心本乎肾**：上不安必因于下，心气虚必因于精亏。心脾血气虚→七福饮，重者大补元煎；命门水亏→左归饮；命门火亏→右归饮；三阴精血亏损→大营煎或理阴煎；水亏火盛烦渴怔忡→二阴煎或加减一阴煎；思郁耗血→逍遥饮或益营汤；寒痰停蓄心下→姜术汤。"}, {"source": "景岳全书心悸条文注释｜五、论治（二）——惊悸方阵（古方补阵组成抄录）", "原文": "心虚血少，神志不宁而惊悸者，养心汤或宁志丸，或十四友丸。若因惊失志而心神不宁者，宁志膏或远志丸。心血不足，肝火不清，血热多惊者，朱砂安神丸。心神虚怯，微兼痰火而惊悸者，八物定志丸。心气郁滞，多痰而惊者，加味四七汤。痰迷心窍惊悸者，温胆汤或茯苓饮子，甚者朱砂消痰饮。风热生痰，上乘心膈而惊悸者，简要济众方。若大恐大惧，以致损伤心脾肾气而神消精却，饮食日减者，必用七福饮、理阴煎，或大营煎，或大补元煎之类", "白话": "心虚血少惊悸→养心汤/宁志丸/十四友丸；因惊失志→宁志膏/远志丸；心血不足肝火血热多惊→朱砂安神丸；心神虚怯兼痰火→八物定志丸；心气郁滞多痰→加味四七汤；痰迷心窍→温胆汤/茯苓饮子，重者朱砂消痰饮；风热生痰→简要济众方；大恐大惧伤心脾肾气→七福饮/理阴煎/大营煎/大补元煎。"}, {"source": "杂病广要心悸条文注释｜一、总说——惊与悸名义之辨（杨仁斋说首揭）", "原文": "总说（名义）** 人之所主者心，心之所养者血，心血一虚，神气不守，此惊悸之所肇端也。曰惊曰悸，其可无辨乎。惊者恐怖之谓，悸者怔忪之谓。（《直指》）\n> 心虚而郁痰，则耳闻大声，目击异物……心为之忤，使人有惕惕之状，是则为惊。心虚而停水，则胸中渗漉，虚气流动，水既上乘，心火恶之，心不自安，使人有怏怏之状，是则为悸。（《直指》）", "白话": "心是主宰，靠血来滋养；心血一虚，神气就守不住，这是惊悸发病的开端。「惊」和「悸」必须分辨：**惊是恐怖的意思，悸是怔忪（心慌）的意思**。心虚又兼郁痰的人，听到大声音、看到怪东西、遇到危险，心受触动，出现提心吊胆的样子——这是惊；心虚又停水的人，胸中水液渗流、虚气浮动，水气上乘于心，心火厌恶水气，心神不能自安，出现郁郁不乐、心跳不宁的样子——这是悸。"}, {"source": "杂病广要心悸条文注释｜二、惊病所由——心虚胆怯（《济生》严用和）", "原文": "夫惊悸者，心虚胆怯之所致也。且心者君主之官，神明出焉。胆者中正之官，决断出焉。心气安逸，胆气不怯，决断思虑，得其所矣。（《济生》）\n> 或因事有所大惊，或闻虚响，或见异相，登高陟险，惊忤心神，气与涎郁，遂使惊悸。惊悸不已，变生诸证，或短气悸乏，体倦自汗，四肢浮肿，饮食无味，心虚烦闷，坐卧不安。（《济生》）", "白话": "惊悸是**心虚胆怯**造成的。心是君主之官主神明，胆是中正之官主决断；心气安乐、胆气不虚，人的决断思虑才正常。或因事情受到大惊吓，或听到虚响、见到怪异景象、登高涉险，惊动心神，气与痰涎郁结，就发为惊悸。惊悸不止会变生诸证：短气心慌乏力、体倦自汗、四肢浮肿、吃饭没味、心虚烦闷、坐卧不安。"}, {"source": "杂病广要心悸条文注释｜三、悸病所由——怔忡心血不足（《济生》）+ 河间主热", "原文": "夫怔忡者，由心血不足也。盖心主于血，血乃心之主，心乃形之君，血富则心君自安矣。多因汲汲富贵，戚戚贫贱，久思所爱，触事不意，真血虚耗，心帝失辅，遂成怔忡。（《济生》）\n> 又有冒风寒暑湿，闭塞诸经，令人怔忡。五饮停蓄，堙塞中脘，亦令人怔忡。当随其证，施以治法。（《济生》）\n> 心胸躁动，谓之怔忡，俗云心忪，皆为热也。（《原病式》）", "白话": "怔忡是**心血不足**所致：心主血，血足则心君自安。多因急切追求富贵、忧戚于贫贱、长久思念所爱之人、事不遂意，真血逐渐虚耗，心君失去辅养，就成怔忡。又有感受风寒暑湿、闭塞经络而令人怔忡的；五饮停留、堵塞中脘，也令人怔忡——当随证施治。刘完素说：心胸躁动叫怔忡（俗称心忪），**皆属于热**。"}, {"source": "杂病广要心悸条文注释｜四、丹溪纲领与《准绳》虚饮二分", "原文": "怔忡者血虚，怔忡无时，血少者多。有思虑便动，属虚。时作时止者，痰因火动。瘦人多是因血少，肥人属痰。寻常者多是痰。真觉心跳者是血少，四物、朱砂安神之类。（《丹溪》）\n> 假如病因惊而得，惊则神出其舍，舍空则痰生也。（《丹溪》）\n> 心悸之由，不越二种，一者虚也，二者饮也。气虚者由阳气内虚，心下空虚，火气内动而为悸也，血虚者亦然。其停饮者，由水停心下……故为悸也。（《准绳》）", "白话": "怔忡属血虚，**发作没有定时**（对比惊悸「有时」），血少者居多：一想事情就跳动的属虚；时作时止的，是痰因火动。瘦人多血少，胖人多痰；普通情形下痰多，真正觉心跳者是血少——用四物汤、朱砂安神丸之类。若病因惊吓而得，惊让神离开心舍，舍空则痰就生成。王肯堂总括：心悸原因不外两种——**虚**与**饮**。气虚者阳气内虚、心下空虚、火气内动为悸；血虚同理；停饮者水停心下，心属火恶水，心不自安故悸。"}, {"source": "杂病广要心悸条文注释｜五、脉候（《脉经》）", "原文": "趺阳脉微而浮，浮则胃气虚，微则不能食，此恐惧之脉，忧迫所作也。惊生病者，其脉止而复来，其人目睛不转，不能呼气。（《脉经》）", "白话": "趺阳脉（足背动脉）微而浮：浮是胃气虚，微是不能进食——这是恐惧之脉，由忧惧逼迫所致。因惊而病者，**脉搏停跳后又恢复**，两目直视不能转动，呼吸短促不能呼气。"}, {"source": "杂病广要心悸条文注释｜六、治法诸说（《永类》《要诀》《医统》《汇补》）", "原文": "治惊悸，必先以养心安神之剂，随后豁痰。或用此法，大便结而脉实者，以朱砂滚痰丸下之。（《医统》）\n> 肝出谋虑，游魂散守，恶动而惊，重治于肝经。胆为决断，属志不伸，触事而惊，重治于胆腑。（《医统》）\n> 痰则豁痰定惊，饮则逐水蠲饮，血虚者调养心血，气虚者和平心气，痰结者降下之，气郁者舒畅之。阴火上炎者，治其肾而心悸自已。（《汇补》）\n> 大抵惊悸、健忘、怔忡、失志、不寐、心风，皆是胆涎沃心，以致心气", "白话": "治惊悸先用养心安神之剂，随后豁痰；大便干结脉实的，用朱砂滚痰丸攻下。肝主谋虑、藏魂，厌恶扰动而惊的，重点治肝经；胆主决断，志不伸、遇事而惊的，重点治胆腑。李用粹分治纲领：有痰则豁痰定惊，有饮则逐水蠲饮，血虚调养心血，气虚和平心气，痰结者降下，气郁者疏畅；阴火上炎者治肾而心悸自止。《要诀》总断：惊悸、健忘、怔忡、失志、不寐、心风，都是**胆涎沃心**致心气不足；若寒凉药用得太过，心火更微、痰涎更盛，唯有理痰气为第一要义。"}, {"source": "杂病广要心悸条文注释｜七、方药选萃（镇心／补心／消饮三组）", "原文": "镇心诸方** 深师龙骨汤，疗宿惊失志，忽忽喜忘，悲伤不乐，阳气不起方。龙骨 茯苓 桂心 远志（去心各一两） 麦门冬（去心二两） 牡蛎（熬） 甘草（炙各三两） 生姜（四两）。（《外台》）（按∶此桂枝加龙骨牡蛎汤变方。）\n> **安神丸**，治心神烦乱怔忡，兀兀欲吐，胸中气乱而热，有似懊 之状，皆膈上血中伏火……黄连（一钱五分酒洗） 朱砂（一钱水飞） 酒生地黄 酒当归身 炙甘草（以上各五分）。（《兰室", "白话": "深师龙骨汤**（《外台》）治宿惊失志、喜忘悲伤、阳气不起：龙骨、茯苓、桂心、远志各一两，麦冬二两，牡蛎、炙甘草各三两，生姜四两——丹波氏按：此即**桂枝加龙骨牡蛎汤变方**。\n- **安神丸**（《兰室》，即朱砂安神丸）治心神烦乱怔忡、胸中气乱而热、似懊憹状，属膈上血中伏火：黄连一钱五分（酒洗）、朱砂一钱（水飞）、酒生地黄、酒当归身、炙甘草各五分——镇阴火浮越、养上焦元气。丹溪用「辰砂安神丸」治心虚胆怯之人怔忡、烦乱、健忘。\n- **姜术汤**（《直指》）治**虚证停饮怔忡*"}, {"source": "杂病广要心悸条文注释｜八、移精治验——张子和击几案（惊者平之）", "原文": "卫德新之妻，旅中宿于楼上，夜值盗劫人烧舍，惊堕床下，自后每闻有响，则惊倒不知人……戴人见而断之曰∶惊者为阳，从外入也；恐者为阴，从内出。（《十形三疗》）\n> 戴人曰∶《内经》云惊者平之，平者常也，平常见之必无惊。是夜使人击其门窗，自夕达曙……一二日，虽闻雷亦不惊。（同上）", "白话": "卫德新的妻子夜遇盗劫惊堕床下，此后一听见响声就惊倒不省人事，家人蹑足而行。众医作心病治，人参、珍珠及定志丸都无效。张子和（戴人）判断：惊属阳、从外入；恐属阴、从内出。令两侍女按住她坐于高椅，当面以木猛击小几，先惊后渐定，连击数次，又击门、击窗，使她平常见之——「惊者平之，平者常也」。当夜让人敲门窗自夕达曙，一两天后虽闻雷也不惊了。"}, {"source": "李培生老中医经验集心悸条文注释｜一、伤寒心悸条文串讲——心系病机总纲", "原文": "「心为火脏，主血、主脉，又主神志疾患。心在左乳下，正当虚里处。《内经》谓'胃之大络，名曰虚里，贯膈络肺，出于左乳下，其动应衣'，脉结代，心动悸，炙甘草汤主之（１７７条）。此是阴血虚而不得濡润，阳气虚而不能煦化，故见心悸之证，结代之脉，法以通阳复脉育阴濡润为治。」\n> 「若'发汗过多，其人叉手自冒心，心下悸，欲得按者，桂枝甘草汤主之'（６４条），则是心液外泄，心阳大虚……可见中医诊法，虚则喜按，实则", "白话": "心主血脉与神志，位于左乳下虚里处。李培生引《内经》虚里句后接《伤寒论》177 条「脉结代，心动悸，炙甘草汤主之」——**阴血虚不得濡润+阳气虚不能煦化**故心悸脉结代，治法通阳复脉、育阴濡润。64 条发汗过多「叉手自冒心、心下悸欲得按」是心液外泄、心阳大虚——喜按属虚、拒按属实是不磨之论，治用辛甘化阳、甘温益气；若心阳进一步外越、烦躁甚至惊狂，用桂甘龙牡、桂枝救逆汤甘温镇涩。又心病多火热之证：少阴「心中烦不得眠」黄连阿胶汤（心火亢肾阴竭，补水泻火）；「伤寒二三日，心下悸而烦者"}, {"source": "李培生老中医经验集心悸条文注释｜二、心律失常辨治总纲——虚实两类", "原文": "「李氏认为心律失常可分为虚实两类：实证多由痰滞、气郁、血瘀所致；虚证多与阴血不足、阳气虚衰有关。其临床特点：心悸、胸闷、胸痹、短气、乏力、脉结代、或疾或迟等，临床当循此而辨证处方用药。」", "白话": "心律失常分虚实两类：**实证**多因痰滞、气郁、血瘀；**虚证**多因阴血不足、阳气虚衰。临床表现特点为心悸、胸闷、胸痹、短气、乏力、脉结代或脉疾或脉迟，据此辨证处方。"}, {"source": "李培生老中医经验集心悸条文注释｜三、滋阴和阳法——气阴两虚（炙甘草汤加减）+ 室早医案", "原文": "「心律失常者，每有气阴两虚之脉证……外邪入心，心阴阳受损，气血亏虚，心失所养，鼓动无力，则心悸气短，脉结或代。当以滋阴养血，通阳复脉为主……证见心悸气短、自汗、少寐多梦、胃纳不振、疲乏无力，脉细或细数或结代，舌质淡红，苔薄黄或苔剥。此证多见于植物神经功能紊乱心肌病、冠心病等引起的房性或室性期外收缩、心动过速、心房纤颤等。」\n> 「张某，男，４０岁，干部。１９８２年９月１０日初诊……心电图检查，提示", "白话": "气阴两虚型心律失常：心悸气短、自汗、少寐多梦、纳差乏力，脉细或细数或结代，舌淡红苔薄黄或剥——多见于植物神经功能紊乱、心肌病、冠心病等引起的房性/室性早搏、心动过速、**心房纤颤**。治宜滋阴和阳、益气养血：炙甘草、人参、生地、麦冬、阿胶、麻仁、茯神、炒山楂、砂仁、大枣；触事易惊加龙牡、珍珠母、柏子仁、炙远志；胸闷窒息加郁金、瓜蒌皮、薤白、橘皮；胸刺痛舌紫暗加三七、丹参、赤芍、制乳没；心烦不寐口糜舌绛加丹皮、丹参、竹叶、玄参，甚者黄连。医案：张某男 40 岁，劳心太过，「频发"}, {"source": "李培生老中医经验集心悸条文注释｜四、涤痰通络法——痰湿阻络 + 风心病房颤误治案", "原文": "「《证治汇补》所谓：'痰迷于心，为心痛惊悸怔忡恍惚。'李时珍亦云：'迟司脏病或多痰。'……其多见于冠心病、风心病、高心病等引起的早搏，传导阻滞或心房纤颤等。治宜涤痰通络。药用：瓜蒌实、薤白、法夏、川贝、炒枳实、橘皮、橘络、炒山楂等。」\n> 「胡某，女，４３岁，工人。１９８３年３月１２日初诊……心电图：Ｐ波增宽并有切迹，电轴右偏，心房颤动。Ｘ线检查：心房增大……某院诊断为风湿性心瓣膜病，二尖瓣狭窄，", "白话": "痰湿阻络型：心痛闷胀、胸中窒闷、左肩背臂胀闷痛麻、头晕泛恶，舌红或暗淡苔白腻，脉弦缓或弦滑或迟或结代——多见于冠心病、风心病、高心病引起的早搏、传导阻滞、**心房纤颤**。治宜涤痰通络（瓜蒌实薤白法夏川贝枳实橘皮橘络山楂）；胸闷气短加党参麦冬五味子，心悸怔忡加炙甘草柏子仁，心前区闷痛加菖蒲檀香，心痛彻背加赤白芍丹参乳没，血压高加龙牡天麻。医案：胡某女 43 岁，风心病二尖瓣狭窄、心衰Ⅱ°、心房颤动（心率１０２次／分律不齐、心尖低音隆隆样舒张期杂音、Ｐ波增宽切迹、心房增大），阵"}, {"source": "李培生老中医经验集心悸条文注释｜五、解郁行滞法——情志致悸 + 周某案", "原文": "「《灵枢·口问》谓：'心者，五脏六腑之大主也……故悲哀愁忧则心动，心动则五脏六腑皆摇。'……情志失调引起心律失常者以肝气郁结者为多见。」\n> 「周某，女，４６岁，教师。１９９１年９月３日初诊……心电图：'频发室性早搏'……现症：心悸胸闷，头昏乏力，失眠多梦，性情烦躁，腹胀纳呆，嗳气频作……月事已３月未潮，舌红苔薄黄，脉来结代，每分钟歇止８～９次。李氏断曰：……情志不遂，滥用补益，则肝气郁滞，脾胃失", "白话": "情志失调致心律失常以肝气郁结为多：胸闷心悸、失眠多梦、短气乏力、胁肋胀痛、情志抑郁善太息、嗳噫纳呆、咽中物阻、月经不调，舌红苔薄白或薄黄，脉弦结代或细而结代——多见于心脏神经官能症、更年期综合征伴心律失常。治宜疏肝解郁、养心安神（柴胡、白芍、枳壳、香附、郁金、陈皮、茯神、丹参、山楂）。医案：周某女 46 岁教师，人流术后情志不舒+过服补益药膏，浮肿心悸腹胀，「频发室性早搏」，脉来结代每分钟歇止８～９次，更年期经闭 3 月——断为肝气郁滞、脾胃失运、心神失养；柴胡１０克、炒枳壳"}, {"source": "李培生老中医经验集心悸条文注释｜六、活血通络法——瘀血型 + 冠心病房颤案（梁某）", "原文": "「血瘀气滞于心律失常中极为常见……李时珍所谓'结脉皆因气血凝'（《濒湖脉学》）是也……其多见于冠心病、风心病等引起的早搏、房颤等心律失常。治宜活血通络，行气止痛。」\n> 「梁某，男，７４岁，干部。１９８９年９月初诊……超声心动图等检查，诊断为冠心病，心房纤颤。用西地兰等治疗……稍遇劳累或情志不舒时，房颤又发。先后住院５次……舌质暗红边有瘀点，苔光剥少津，脉来见代。辨属心血瘀阻，脉络不通，阴津亏耗，", "白话": "瘀血气滞型：胸闷刺痛频发、心悸气短、精神抑郁、头昏身倦、面色晦暗、唇甲青紫、舌暗红或有瘀点、脉沉弦涩或促或结代——多见于冠心病、风心病引起的早搏、房颤。治宜活血通络行气止痛（桃仁、红花、当归、赤芍、枳壳、生地、丹参、香附、山楂炭）。医案：梁某男 74 岁，冠心病**心房纤颤** 5 年，劳累饮酒诱发，西地兰可缓解但遇劳或情志不舒即发，住院 5 次，近半年频发；心悸气短、胸痛如针刺、动则喘、口干便结、舌暗红瘀点苔光剥少津、脉来见代——心血瘀阻+阴津亏耗，治以活血通络、理气宽胸、"}, {"source": "李培生老中医经验集心悸条文注释｜七、心律失常用药经验——快慢双向调节", "原文": "「李氏认为，心律失常一般以虚证多见，然也有以瘀血、气滞或痰阻为主者，临床治疗当有所侧重。据李氏经验，若过速性心律失常者，用柏子仁、当归、菟丝子、石斛、徐长卿等养血安神，滋阴补肾的药物有减慢心律的作用；若过缓性心律失常者，用麻绒、麝香、鹿茸、茶叶等芳香走窜，温阳兴奋的药物，有加速心率的作用。此外，如炙甘草汤及生地、麦冬、玄胡、赤芍、柴胡、桂枝、茵陈、苦参等均有抗心律失常的作用，临床可随证选用，又不可", "白话": "心律失常以虚证为多，也有瘀血、气滞、痰阻为主者，治疗各有侧重。**过速性心律失常**用柏子仁、当归、菟丝子、石斛、徐长卿等养血安神、滋阴补肾药以减慢心律；**过缓性心律失常**用麻绒、麝香、鹿茸、茶叶等芳香走窜、温阳兴奋药以加速心率。此外炙甘草汤及生地、麦冬、玄胡、赤芍、柴胡、桂枝、茵陈、苦参等均有抗心律失常作用，随证选用，不可拘于一隅。"}, {"source": "李翰卿心悸条文注释｜一、心悸证治总论——惊悸与怔忡之辨", "原文": "「《红炉点雪》中说：'悸者，心卒动而不安也。惊者，心跳而怕惊也。怔忡者，心中躁动不安，惕惕然如人将捕之也。'惊悸与怔忡在程度上有轻重之分……因外因所引起，如突然受刺激，受到惊吓而发，心悸时作时止，谓之'惊悸'，病情轻；不因惊恐而发，心中动摇不宁，无休止时者，谓之'怔忡'，病情较重。」", "白话": "悸是心脏突然跳动不安；惊是心跳兼害怕惊吓；怔忡是心中躁动不安、惶惶然像有人要抓捕自己。**惊悸与怔忡有轻重之分**：因突然刺激、受惊吓而发，心悸时作时止的叫惊悸，病情轻；不因惊恐而发、心中动摇不宁、无休止时的叫怔忡，多由内因造成，稍劳即发，全身情况差，发病缓而病情重。"}, {"source": "李翰卿心悸条文注释｜二、案一·风心病二尖瓣病变——炙甘草汤加减（气阴两虚）", "原文": "「陈某，男，34岁。1960年8月9日初诊：心悸失眠，疲乏无力，面色无华，前几天咳嗽、咯血，舌质暗，苔薄白，脉细无力。西医诊断为风湿性心脏病、二尖瓣狭窄与闭锁不全。」\n> 处方：「炙甘草9克 党参7.5克 桂枝7.5克 熟地9克 生白芍7.5克 黑芝麻7.5克 阿胶4.5克(烊化) 生龙牡各9克 茯神7.5克　2剂，水煎服。」", "白话": "34 岁男性，心悸失眠、疲乏无力、面色无华，近日咳嗽咯血，舌暗苔薄白脉细无力；西医诊断风湿性心脏病、二尖瓣狭窄合并关闭不全。辨证为**气阴两虚**——气血亏虚心失所养、神不守舍，舌暗为血行不畅。治以炙甘草汤加减：辛润通阳、气血并补、通利血脉、镇惊安神。党参炙甘草补中益气，白芍敛和营血，桂枝通阳活络，熟地黑芝麻阿胶补血，生龙牡茯神镇惊安神。"}, {"source": "李翰卿心悸条文注释｜三、案二·脾虚水泛——五皮饮加减（水气凌心）", "原文": "「李某，男，40岁。1959年1月7日初诊：心悸气短，下肢及颜面浮肿，面色萎黄，大便稀，小便黄，苔薄白，脉滑。」\n> 处方：「陈皮7.5克 茯苓皮6克 生姜皮6克 桑皮7.5克 大腹皮7.5克 车前子6克(另包) 怀牛膝15克 生白芍9克　2剂，水煎服。」", "白话": "40 岁男性，心悸气短、下肢及颜面浮肿、面色萎黄、大便稀、小便黄，苔薄白脉滑。病机：脾虚运化失常、湿邪浸渍成饮，**寒饮上迫、水气凌心、心阳阻遏**则心悸气短；水湿内聚、三焦决渎失司则小便不利、大便稀。治法：理气健脾、通阳利水——五皮饮加车前子、怀牛膝、生白芍，寒湿尽除则心悸自止。"}, {"source": "李翰卿心悸条文注释｜四、案三+案四·产后失血与思虑伤心——养血安神两路", "原文": "「案三 李某，女，28岁。1963年6月10日初诊：因分娩时出血过多，面色苍黄，心悸失眠，气短乏力，苔薄白，脉虚无力。此证属心血不足，胸阳不振。」\n> 处方：「党参7.5克 麦冬6克 五味子6克 炒枣仁9克 当归4.5克 菖蒲4.5克 茯神7.5克 甘草6克」\n> 「案四 冯某，男，45岁。1964年2月7日初诊：心悸失眠，健忘，自汗，气短，不思饮食，苔薄白，脉细弱。此证乃思虑过度，劳伤心神。治宜", "白话": "案三：28 岁女性分娩出血过多，面色苍黄、心悸失眠、气短乏力、脉虚无力——**心血不足、胸阳不振**，治以益气养血、安神止惊（党参甘草麦冬五味子益气养阴，枣仁当归和血敛津，茯神菖蒲通窍安神）。案四：45 岁男性思虑过度劳伤心神，心悸失眠健忘自汗纳差脉细弱——归脾汤加减健脾养心、益气补血（党参白术黄芪当归茯神远志木香元肉五味子），「气旺血生，则心悸自愈」。"}, {"source": "李翰卿心悸条文注释｜五、桂枝甘草汤方——心阳虚心悸的「必须具有」指征", "原文": "「桂枝甘草汤方第十七　[方义]此温补心阳，兼补中气，治心悸之方。[主治]发汗过多形成心悸之证。但必须具有**喜用手按、小便尚利、喜热怕凉或脉沉迟**等方能准确。」\n> 「[禁忌证]（1）喜冷或口苦脉沉数者忌之……（2）汗仍未止，脉虚而不调者忌之。因系气虚将脱之象……（3）四肢厥逆，小便不利，有明显停水现象者不宜用。因此系阳虚水泛之重证，此方力有未足。」", "白话": "桂枝甘草汤是**温补心阳、兼补中气治心悸**之方，主治发汗过多形成的心悸，但必须具备：喜用手按（虚证）、小便尚利（无停水、不需苓术）、喜热怕凉或脉沉迟（确属寒证）才准确。药品：桂枝二至三钱、炙草一钱至钱半，水煎顿服。禁忌：①喜冷、口苦、脉沉数（热证）；②汗仍不止、脉虚不调（气虚将脱，当补气固脱）；③四肢厥逆、小便不利、明显停水（阳虚水泛重证，本方力不及，当用真武汤或茯苓四逆汤）。类似方参考：朱砂安神丸（血虚有热心悸）、来复汤（气虚欲脱心悸）、真武汤及茯苓四逆汤（阳虚水泛重剂，"}, {"source": "李翰卿心悸条文注释｜六、桂枝甘草龙骨牡蛎汤方——火逆救逆镇心", "原文": "「桂枝甘草龙骨牡蛎汤方第十六　[方义]此补心阳，镇心安神，救逆之方。也系温性镇静之剂。[主治]火逆证误下后，心阳被伤，烦躁不安。但必须具有喜热畏冷的现象。」\n> 「[药品]桂枝二至三钱 炙草一至二钱 龙骨三至五钱 牡蛎三至五钱　[用药大意]桂枝、甘草补心阳以救逆；龙骨、牡蛎镇惊悸以安神。[禁忌证]喜冷畏热者忌之，因热证不宜用热药。」", "白话": "本方是**补心阳、镇心安神、救逆**之方，属温性镇静剂。主治火逆证误下后心阳被伤、烦躁不安，但必须具有喜热畏冷现象。桂枝二至三钱、炙草一至二钱、龙骨三至五钱、牡蛎三至五钱，水二茶杯半煎至半茶杯温服。桂枝甘草补心阳救逆，龙骨牡蛎镇惊悸安神。喜冷畏热的热证禁用。类方参考：桂枝去芍药加蜀漆龙骨牡蛎救逆汤（温性祛痰镇静兼散外邪）。"}, {"source": "李翰卿心悸条文注释｜七、炙甘草汤方——脉结代的寒热分水岭", "原文": "「炙甘草汤方第四十三　[方义]此心经气血俱虚温补之方。[主治]伤寒心悸，脉结代。但必须兼有**不喜冷性饮食的阳虚寒证现象**。」\n> 「[禁忌证]喜冷恶热之心悸脉结代证忌之。因热性病不宜使用温补药也。[类似方剂参考]**加减复脉汤：此治脉结代，心悸，属于热性病喜冷性饮食证之方。**」", "白话": "炙甘草汤是**心经气血俱虚温补**之方，主治伤寒心悸、脉结代，但必须兼见**不喜冷性饮食的阳虚寒证**。药品：炙甘草二至三钱、生姜五分至一钱、人参一至二钱、生地三至五钱、桂枝五分至一钱、阿胶一至二钱、麦门冬一至二钱、麻子仁一至二钱、大枣二至四枚；水三茶杯加白酒一小盅煎至半杯温服。炙草大枣人参补中强心，麦冬生地阿胶养血，麻仁润燥，桂枝生姜祛寒，白酒通血脉。**喜冷恶热的心悸脉结代证禁用**（热性病不宜温补）；热性病喜冷饮食的脉结代心悸当用**加减复脉汤**（温病学化裁方）。"}, {"source": "濒湖脉学脉学条文注释｜一、涩脉（阴）——细迟短涩往来难", "原文": "涩脉，细而迟，往来难，短且散，或一止复来（《脉经》）。参伍不调（《素问》）。如轻刀刮竹（《脉诀》）。如雨沾沙（《通真子》）。如病蚕食叶。\n> 〔体状诗〕细迟短涩往来难，散止依稀应指间。如雨沾沙容易散，病蚕食叶慢而艰。\n> 〔主病诗〕涩缘血少或伤精，反胃亡阳汗雨淋。寒湿入营为血痹，女人非孕即无经。寸涩心虚痛对胸……尺为精血俱伤候，肠结溲淋或下红。", "白话": "涩脉：**脉细、跳得慢，往来艰涩困难，脉体短而涣散，或有停一跳再恢复的**（《脉经》说）。《素问》叫「参伍不调」（节律不匀）；《脉诀》比喻「轻刀刮竹」（刮涩不滑）；《通真子》比喻「雨沾沙」（沾在沙上不流利）；又像「病蚕食叶」（迟慢艰难）。主病诗：涩脉主**血少或精伤**，又主反胃、亡阳汗多；寒湿入营成血痹；女子见涩非孕即经闭。**寸涩主心虚、心痛胸痛**；尺涩主精血俱伤，见肠结、尿淋或便血。"}, {"source": "濒湖脉学脉学条文注释｜二、促脉（阳）——「数止为促，缓止为结」的辨正", "原文": "促脉，来去数，时一止复来（《脉经》）。如蹶之趣，徐疾不常（黎氏）……数止为促，缓止为结，何独寸口哉！\n> 〔体状诗〕促脉数而时一止，此为阳极欲亡阴。三焦郁火炎炎盛，进必无生退可生。\n> 〔主病诗〕促脉惟将火病医，其因有五细推之。时时喘咳皆痰积，或发狂斑与毒疽。促主阳盛之病。", "白话": "促脉：**脉来去急数，时有一停，停后复来**（《脉经》）。像**急步快走中绊了一跤，快慢不匀**（黎氏比喻）。李时珍辨正：《脉经》只说「数而止」为促，《脉诀》却说「并居寸口」而不讲时有歇止，是错的——**数而歇止才是促，缓而歇止是结，哪里只限于寸口！**体状诗：促脉数而时一止，是**阳极将要耗亡阴液**的表现；三焦郁火炽盛时见到，病进则凶、病退可生。主病诗：促脉主要从**火**论治，病因有五（气、血、痰、饮、食）须细推；时时喘咳是痰积，或发狂、发斑、生毒疽——**促主阳盛之病"}, {"source": "濒湖脉学脉学条文注释｜三、结脉（阴）——三结辨与「名同实异」", "原文": "结脉，往来缓，时一止复来（《脉经》）。《脉诀》言∶或来或去，聚而却还。与结无关。仲景有累累如循长竿曰阴结，蔼蔼如车盖曰阳结。《脉经》又有如麻子动摇，旋引旋收，聚散不常者曰结，主死。此三脉，名同实异也。\n> 〔体状诗〕结脉缓而时一止，独阴偏盛欲亡阳。浮为气滞沉为积，汗下分明在主张。\n> 〔主病诗〕结脉皆因气血凝，老痰结滞苦沉吟。内生积聚外痈肿，疝瘕为殃病属阴。", "白话": "结脉：**脉往来较缓，时有一停，停后复来**（《脉经》）。李时珍辨正：《脉诀》说「或来或去，聚而却还」，与结脉无关。另外仲景有「累累如循长竿」叫阴结、「蔼蔼如车盖」叫阳结（指脉形）；《脉经》又有「如麻子动摇、旋引旋收、聚散不常」叫结、主死（怪脉）——**这三种「结」名同实异**。体状诗：结脉缓而时一止，是**独阴偏盛、将要亡阳**；浮取见结主气滞，沉取见积，治法汗下须分明。主病诗：结脉皆因**气血凝滞**、老痰结滞；内生积聚、外生痈肿、疝瘕为患——**病属阴**。"}, {"source": "濒湖脉学脉学条文注释｜四、代脉（阴）——脏气衰与「结生代死」", "原文": "代脉，动而中止，不能自还，因而复动（仲景）。脉至还入尺，良久方来（吴氏）……盖一脏之气衰，而他脏之气代至也。《经》曰∶代则气衰。滑伯仁曰∶若无病，羸瘦脉代者，危脉也。有病而气血乍损，气不能续者，只为病脉。伤寒心悸脉代者，复脉汤主之，妊娠脉代者。其胎百日。\n> 〔体状诗〕动而中止不能还，复动因而作代看。病者得之犹可疗，平人却与寿相关。\n> 〔相类诗〕数而时至名为促，缓止须将结脉呼。止不能回方是代，结", "白话": "代脉：**脉跳动中间停歇，不能自行恢复，过一阵才重新跳动**（仲景说）；脉气下陷入尺部、良久才来（吴氏说）。病机是**一脏之气衰，由他脏之气代为接续**。《内经》说「代则气衰」。滑伯仁说：无病而羸瘦者见代脉，是危脉；有病而气血乍伤、气接不上的，只是病脉。**伤寒心悸见脉代的，用复脉汤（炙甘草汤）主治**；妊娠见代脉，主胎孕百日。体状诗：病中见代尚可治，平人见代关乎寿命。相类诗：**数而时止叫促，缓而歇止叫结，歇止不能回的才是代——结脉预后好、代脉预后凶，是两条路**。"}, {"source": "濒湖脉学脉学条文注释｜五、代脉·主病诗与五十动说——死期推断（存疑照录）", "原文": "〔主病诗〕代脉元因脏气衰，腹痛泄痢下元亏。或为吐泻中宫病，女子怀胎三月兮。《脉经》曰∶代散者死。生泄及便脓血。五十不止身无病，数内有止皆知定。四十一止一脏绝，四年之后多亡命。\n> 戴同父曰∶脉必满五十动，出自《难经》……柳东阳曰∶古以动数候脉，是吃紧语。须候五十动，乃知五脏缺失。", "白话": "代脉总因**脏气衰**：主腹痛、泄痢、下元亏；或吐泻中宫（脾胃）病；女子怀孕三月见代为常。《脉经》说代脉兼散脉者死，主泄泻便脓血。**五十动无歇止者无病；有歇止者依止数定脏气**：四十动一止为一脏绝，多在四年后亡……戴同父说候脉必满五十动，出自《难经》；柳东阳说古法以数动数候脉是要紧处，**须候满五十动才知五脏缺失**，今人指到腕臂就说看完了，哪是弹指间的事。"}, {"source": "濒湖脉学脉学条文注释｜六、《四言举要》——四脉总括与「伤寒心悸，女胎三月」", "原文": "迟细为涩，往来极难，易散一止，止而复还。结则来缓，止而复来；代则来缓，止不能回。（总括）\n> 阳盛则促，肺痈阳毒；阴盛则结，疝瘕积郁；代则气衰，或泄脓血；伤寒心悸，女胎三月。（主病总括）\n> 代脉止歇，脏绝倾危；散脉无根，形损难医。（死候）", "白话": "总括：**迟细往来难的是涩，易散或一止但能复还；结是来缓、歇止能复来；代是来缓、歇止不能回**。主病总括：**阳盛见促脉**（肺痈、阳毒）；**阴盛见结脉**（疝瘕积郁）；**代脉主气衰**，或泄泻便脓血——又主**伤寒心悸、女子怀胎三月**。死候：代脉歇止、脏气断绝的危殆；散脉无根、形损的难医。"}, {"source": "濒湖脉学脉学条文注释｜七、《四言举要》——诸病脉候中的结代促涩（临床应用带）", "原文": "涩脉少血，或中寒湿，反胃结肠，自汗亡阳……（主病带）\n> 霍乱之候，脉代勿讶；厥逆迟微，是则可怕。\n> 咳嗽多浮，聚肺关胃，沉紧小危，浮濡易治；喘急息肩，浮滑者顺，沉涩肢寒，散脉逆证。\n> 诸风眩晕，有火有痰，左涩死血，右大虚看……真痛短涩。", "白话": "涩脉主血少或中寒湿，见反胃、肠结、自汗亡阳。霍乱见代脉不必惊怪（吐泻气血乍损），**厥逆而脉迟微才可怕**。咳嗽脉浮为顺，沉紧小者危；喘急抬肩，脉浮滑者顺，**沉涩而肢寒、散脉者是逆证**。眩晕分火分痰；**左脉涩主瘀血（死血）**；真心痛见短涩脉。"}, {"source": "疡医大全心悸条文注释｜一、卷二脉法——惊悸怔忡的脉象定位", "原文": "（虚脉）寸虚自汗多惊悸**，（虚脉主气血虚……汗者心之液也……心藏神，血虚则神失所养，故多惊；火气冲心，故跳动而多悸。）\n> **（散脉）左寸怔忡**，右寸自汗，（散主气实血虚，心主血，血虚则心神恍惚不宁曰怔忡。）\n> **（代脉）动而中止不能还，止有常数斯名代，不是伤寒心悸多，即有腹疼泄痢害，久病固为凶**……平人亦脏败……女胎三月余，见之不为碍。\n> **（细脉）直软如丝细，劳伤损血气……身汗", "白话": "脉法歌诀：**虚脉**见于寸部主自汗、多惊悸（血虚神失养则惊，火气冲心则悸）；**散脉**见于左寸主怔忡（气实血虚、心神恍惚不宁）；**代脉**跳动中止不能自还、停跳有常数——「不是伤寒心悸多，即有腹疼泄痢害」，久病见之凶，平人见之为脏败，孕妇三月余见之无碍；**细脉**如丝主气血劳损，「身汗来，心慌至」（汗多心虚故慌）；**涩脉**寸部主心疼神怯；关部数而无力主疮热兼怔忡烦躁。"}, {"source": "疡医大全心悸条文注释｜二、卷之心部汇论——惊悸怔忡诸家总集（本书最大心悸单元）", "原文": "《纲目》曰：惊者，心卒动而不宁也。**悸者，心跳动而怕惊也**。\n> 《三因》曰：惊悸，因事有所大惊而成者，名曰心惊胆慑，病在心胆经，其脉大动。又曰：五饮停蓄，闭于中脘，最使人惊悸，属饮家。\n> 仲景曰：**心悸者，火惧水也。惟肾欺心故为悸；伤寒饮水多，必心下悸**。又曰：食少饮多，水停心下，甚者则悸，微者短气。\n> 丹溪曰：惊悸者，有时而作，大概属血虚与痰；瘦人多是血虚，肥人多是痰饮。\n> 《直", "白话": "本书卷之心部把历代心悸怔忡论汇为一编：惊=心突然跳动不宁；悸=心跳而易受惊。《三因》：因大惊而发者名心惊胆慑，病在心胆经，脉大动；五饮停蓄中脘亦致惊悸。仲景：心悸是「火惧水」，肾水欺心故悸；伤寒饮水多必心下悸，食少饮多水停心下，重则悸轻则短气。丹溪：惊悸阵发，多属血虚与痰，瘦人血少、肥人痰饮。《直指》：心虚痰郁→惊悸（惕惕之状）；心虚停水→怔忡（胸中渗漉之感）。《济生》思虑耗心血→益荣汤；《得效》痰饮蓄心胃→茯苓饮子、虚人停饮→姜术汤；《回春》「心中无血如鱼无水」→四物安神汤"}, {"source": "疡医大全心悸条文注释｜三、疮疡溃后怔忡惊悸——外科七恶与虚极传变", "原文": "蒋示吉曰：**夫虚极传变，惊悸怔忡，牙关紧闭，而卧不宁，或发热恶寒作渴，自汗盗汗，手撒身热，脉洪大，按之如无，俱恶证也**。（《说约》）\n> 此外，更有**溃后发热恶寒，作渴或怔忡惊悸，寤寐不宁，牙关紧急**，或头目赤痛，自汗盗汗，寒战切牙，手撒身热，脉洪大按之如无，或身热恶衣，欲投于水，其脉浮大按之微细……**此气血虚极传变之恶证也**。若手足逆冷，肚腹疼痛，泄利肠鸣，饮食不入，呃逆呕吐，此阳气", "白话": "蒋示吉：**虚极传变的恶证**包括惊悸怔忡、牙关紧闭、卧不安、寒热口渴、自汗盗汗、手撒身热、脉洪大而按之无力。疮疡溃后若见发热恶寒、口渴、**怔忡惊悸、睡卧不宁**、牙关紧急、头目赤痛、自汗盗汗、寒战、手撒、身热、脉洪大按之空——是**气血虚极传变的恶证**；若手足冷、腹痛、泄利肠鸣、呃逆呕吐，是阳气虚寒乘之。急用人参、黄芪、当归、白术、附子救之，或有可生。虚证见恶候难治，实证无恶候易治。"}, {"source": "疡医大全心悸条文注释｜四、跌打损伤后怔忡惊悸——外伤性心悸", "原文": "《可法良规》云：凡伤损之证……次则壮脾胃，进饮食，生血气，降阴火，则瘀血易于腐溃，新肉易于收敛……若刺破之后，或有**发热恶寒，口干作渴，怔忡惊悸，寤寐不宁，牙关紧急，目赤头痛，自汗盗汗，寒战切牙，气短喘促，遗尿手撒，身热脉大，按之如无**……此气血挟虚使然也。皆宜**参、、归、术之类急补之，如不应，速加附子，缓则不救**。", "白话": "《可法良规》：跌打损伤治疗，先砭刺和经络，再壮脾胃、生血气、降阴火。若刺破后出现发热恶寒、口干、**怔忡惊悸、睡卧不宁**、牙关紧急、目赤头痛、自汗盗汗、寒战气促、遗尿手撒、身热脉大按之无力——是气血挟虚所致，急用人参、黄芪、当归、白术峻补，不应速加附子，缓则不救。"}, {"source": "疡医大全心悸条文注释｜五、瘰疬、疔疮、脚气等跨科心悸条文", "原文": "又曰：有久生瘰 ，颈间尽烂，且及于胸膈……以至身体发热发寒，肌肉消瘦，不思饮食，**自汗盗汗，惊悸恍惚**。此证原难医治，然治得法，亦在可救也……用**转败丹**：人参二两，柴胡二钱，白芍三钱，金银花三两，当归二两，半夏五钱，白术一两，生甘草三钱。\n> （黑靥疔）毒气发于肾经者……初生黑斑紫泡，毒串皮肤，渐至肌肉，顽硬如钉，痛沏骨髓；重则手足青紫，**惊悸沉困**，软陷孔深，目睛透露。\n> （金液", "白话": "瘰疬久烂：颈项溃烂及胸膈，消瘦、自汗盗汗、惊悸恍惚——转败丹（人参二两、柴胡二钱、白芍三钱、银花三两、当归二两、半夏五钱、白术一两、生甘草三钱）补多于消。\n- 疔疮走黄（黑靥疔·肾经）：黑斑紫泡、痛彻骨髓、手足青紫、**惊悸沉困**——疔毒内陷攻心的危候。\n- 金液戊土丹：治膏粱丹石耗伤肾水、不能上制心火，消渴、九窍不通、**惊悸健忘**（人中黄、乌梅、胡黄连、茯神、五味、菖蒲、远志、雄黄、辰砂、硝石、牛黄、冰片、金箔）。\n- 加味养荣丸：妇女脚气、心虚血少怔忡心悸、肝脾不足"}, {"source": "痰火点雪心悸条文注释｜一、惊悸怔忡总论——血虚为本、痰火为标（本书病机总纲）", "原文": "惊者，心卒动而不宁也。悸者，心跳动而怕惊也。怔忡者，心中躁动不安，惕惕然如人将捕是也。多因富贵而戚戚，贫穷而不遂所愿……其三症病同而名异，**其原皆由心血虚，盖心无血养，如鱼失水，惕然而跳跃也。时作时止者，以痰因火动；瘦人多是血虚，肥人多是痰饮**。法宜先养心血，理其脾土，亦当幽闲安乐，制其忧虑，远其七情六淫则自安矣。", "白话": "「惊」是心突然跳动不宁；「悸」是心跳动而易受惊吓；「怔忡」是心中躁动不安、惶惶然像有人要抓他。多因境遇不顺、忧思抑郁所致。三症**病位同在心而名称有异，根原都是心血虚**——心失去血的濡养，像鱼离水一样惕惕跳跃。**发作时有时无（时作时止）的，是痰因火动**；瘦人多属血虚，肥人多属痰饮。治法宜先养心血、调理脾土，兼以情绪调摄（幽闲安乐、节制忧虑、远离七情六淫）。"}, {"source": "痰火点雪心悸条文注释｜二、痰饮惊悸与心惊胆寒——引经据典的病因谱", "原文": "《素问》云：东方青色，入通于肝，其病发惊骇。又云：脾移热于肝，则为惊衄。**仲景云：食少饮多，水停不下，甚者则悸，微者短气。又云：五饮停蓄，闭于中脘，最使人惊悸。又云：因有大事所惊而成者，名曰心惊胆寒，病在心胆经，其脉大动，其动也如豆，动摇无头尾是也。丹溪云：病自惊而得者，则神出其舍，舍得液则成痰也，血气入舍，则痰拒其神，不得归。**\n> 黄帝问曰：胃足阳明之脉病，恶人与火，闻木音则惕然而惊……岐", "白话": "《素问》说肝病发惊骇、脾移热于肝则惊衄。**仲景说：进食少而饮水多、水停不化，重则心悸、轻则短气；五饮停蓄闭阻中脘，最易令人惊悸；因突受大惊而病者名「心惊胆寒」，病在心胆经，其脉大动、脉形如豆、无头无尾**。丹溪说：因惊而病者，神气浮越出其舍（心），舍中津液凝聚成痰，痰占据其舍、拒神不得归，故惊悸不宁。阳明胃病闻木音而惊，是「土畏木」；**痰饮惊悸属脾土**。凡火病吐血盗汗之后，多见此症。"}, {"source": "痰火点雪心悸条文注释｜三、惊悸怔忡主方——补心汤与朱砂安神丸", "原文": "惊悸怔忡主方·即补心汤**：当归（一钱） 白术（八分，壁土炒） 陈皮（五分，去白） 白芍（五分，炙） 生地（七分） 远志（五分，去骨） 石菖蒲（六分） 麦冬（七分，去心） 酸枣仁（五分，略炒） 甘草（三分半） 黄柏（三分，童便炒） 知母（五分，童便炒） 茯神（五分，去木）。虚极者，加人参三分。又一方加柏子仁、北五味，水煎服。\n> **朱砂安神丸**：朱砂（三钱，水研末） 黄连（酒洗，六钱） 甘草（", "白话": "补心汤**（惊悸怔忡主方）：当归一钱、壁土炒白术八分、陈皮五分、炙白芍五分、生地七分、远志五分、石菖蒲六分、麦冬（去心）七分、略炒酸枣仁五分、甘草三分半、童便炒黄柏三分、童便炒知母五分、茯神五分。虚极者加人参三分；另一方加柏子仁、北五味子，水煎服。**朱砂安神丸**：朱砂三钱（水飞研末）、酒洗黄连六钱、炙甘草二钱五分、生地黄一钱五分、当归二钱，共研细末，蒸饼为丸如黍米大，每次三五十丸，临卧津液送下。"}, {"source": "痰火点雪心悸条文注释｜四、名医治验两则——惊恐致悸与「惊者平之」", "原文": "林学院历官海南地方，有一子……喜食海蛤，每食必设。至十八年，忽面色顿青，形体消瘦，夜多惊悸，皆谓痨瘵，百疗不瘳。遂召杜诊之，杜曰：非病……盖虽病削面青，精神不减……《素问》云：盐发渴，乃胜血之证。今既去盐，用生津液之药，人且少壮，血液易生，而色渐红润，此病去乃安矣。\n> 卫德新之妻，旅宿楼上，夜值盗劫人烧舍，惊坠床下，自后每闻有响，则惊倒不知，诸医作心病治之，皆无效。戴人见而断之曰：**惊者，为阳", "白话": "海南某官员之子嗜食海蛤（味咸），十八年后面色发青、消瘦、夜间多惊悸，众医当痨瘵治无效。杜氏诊曰非痨：虽消瘦面青但精神不减——《素问》「盐发渴，乃胜血」，过咸伤血。嘱停咸食、服生津液药，两月后血充色润、夜惊自止。\n卫德新之妻因夜盗惊坠，此后闻响即惊倒，诸医治心无效。张戴人断为「惊从外入」，治以**「惊者平之」——反复暴露于惊刺激使之习以为常**：令其坐定，从击几、击门、击窗渐次进行，惊定而愈，十二日后闻雷不惊。"}, {"source": "痰火点雪心悸条文注释｜五、痰火脉·结代促——痰火书中的脉律不齐判读", "原文": "结**：结脉往来缓，时一止复来。《脉诀》言或来或去、聚而却还，与结无关……又曰：结脉缓而时一止，独阴偏胜欲亡阳，浮为气滞沉为积。**主病**：结脉主血凝气滞，老痰结滞内积，外痈肿疝。\n> **代**：代脉动而中止，不能自还，因而复动，脉至还入尺，良久方来……**滑氏曰：若无他病，羸瘦脉代者，危脉也。有病而气血乍损，气不能续者，只为病脉，伤寒心悸脉代者，复脉汤主之，妊娠脉代者，其胎百日**，代之生死", "白话": "结脉**往来缓、时一止复来，主血凝气滞、老痰结滞内积。**代脉**动而中止、不能自还、脉退回尺中良久才来：滑氏说——无他病而羸瘦见代脉是危脉；有病而气血乍损不能接续的只是病脉，如**伤寒心悸脉代者用复脉汤（炙甘草汤）、妊娠见代脉是胎元百日之候**，代脉的生死预后不可不辨。李氏概括：数时一止叫促、缓而有止看作结、**停后不能恢复才是代，结生代死预后不同**；促结的停跳无常数，代脉的停跳有常数、按数而止、良久复来。**促脉**是数而时一止、如快跑绊倒、快慢不匀；《脉诀》只说「并居"}, {"source": "痰火点雪心悸条文注释｜六、痰火虚证脉与可补不可补——结代无力为虚", "原文": "（痰火绪言）凡痰火之证，始于阴虚，于法当补……**盖以脉之可补者，浮而芤濡虚大，迟缓无力，沉而迟涩弱细，结代无力，皆虚而不足，可补者也**……若于此不补，或恣用苦寒，则虚虚之祸，岂不旋踵而至耶？**其脉之不可补者，弦长紧实，滑数有力，此皆火郁内实**，不受补者也。\n> （痰火虚症主方）治虚劳瘦损，潮汗遗嗽，失血诸证全具，脉浮而芤濡虚大，缓迟无力，或沉而迟涩，弱细**结代无力**，皆虚而不足，可补者", "白话": "凡痰火证始于阴虚，本应补，但要脉证互参：**可补之脉是浮而芤濡虚大、迟缓无力、沉迟涩弱细、结代而无力**——皆属虚不足，当补（君以参芪、佐归芎芍地）；若不补反恣用苦寒，则犯「虚虚」之戒。**不可补之脉是弦长紧实、滑数有力**——火郁内实，当滋阴抑阳（四物合二冬二母沙参玄参），误补则「实实」之灾。痰火虚症主方治潮汗遗嗽失血俱见、脉结代无力者：人参、蜜炒黄芪、炙甘草、生地、玄参、五味子、沙参、天冬、麦冬等十二味。"}, {"source": "类证治裁心悸条文注释｜一、怔忡定义（总纲——无诱因自发心悸）", "原文": "怔忡者，心动不安，无所见闻惊恐，而胸间惕惕自动也。惊者，神气失守，由见闻夺气，而骇出临时也。恐者，胆怯股栗，如人将捕之，乃历久而惧难自释也。怔忡伤心神，惊伤胆液，恐伤肾精，三者心胆肝肾病。", "白话": "怔忡**是心跳不安，**没有任何听到见到的惊吓诱因**，胸中自然惕惕跳动；**惊**是受外界刺激（见闻）而神气失守、当场惊骇；**恐**是胆怯腿抖、像有人要抓他，久久不能自我释怀。怔忡伤心神，惊伤胆液，恐伤肾精——三者分属心、胆、肝、肾。"}, {"source": "类证治裁心悸条文注释｜二、景岳治法段（八法对证谱系）", "原文": "如心脾气血本虚，而致怔忡惊恐、或因大惊猝恐，神志昏乱者，七福饮，甚者大补元煎。如肾水亏，真阴不足致怔忡者，左归饮。如命火衰，真阳不足致怔忡者，右归饮。……如水亏火盛，烦躁热渴而为怔忡惊悸者，二阴煎或加减一阴煎。如思虑郁损心营，而为怔忡惊悸者，逍遥散，或益营煎。如痰火盛，心下怔忡者，温胆汤加炒黄连、山栀、当归、贝母。如寒痰停蓄心下而怔忡者，姜术汤。", "白话": "心脾气血本虚致怔忡惊恐、或大惊猝恐神志昏乱：七福饮，重者大补元煎；肾水亏、真阴不足：左归饮；命火衰、真阳不足：右归饮；三阴精血亏损、阴中之阳不足：大营煎或理阴煎；水亏火盛、烦躁热渴：二阴煎或加减一阴煎；思虑郁损心营：逍遥散或益营煎；痰火盛、心下怔忡：温胆汤加炒黄连、山栀、当归、贝母；寒痰停蓄心下：姜术汤；痰迷心窍惊悸：温胆汤，甚者朱砂消痰饮。这是张景岳一派的治法。"}, {"source": "类证治裁心悸条文注释｜三、分治〔怔忡症〕（心包血虚·火迫·脉结代用养心汤）", "原文": "〔怔忡症〕由心包血虚，心火下迫，震动君主神明，或思虑劳神，或郁怒动火，致头晕汗出，不寐便浊等因，宜养心血调心气，降火安神为主。……水衰火旺，心动不安，天王补心丹。由汗下后气虚，益营煎。营卫俱衰，脉来结代，心惕不安，养心汤。心动而卧不安，枣仁汤。……忧思郁结，怔忡不已，归脾汤。心虚怔忡自汗，养营汤去木香，加浮小麦煎汤。", "白话": "怔忡症多由心包血虚、心火下迫震动心神，或思虑劳神、郁怒动火，伴头晕汗出、不寐、尿浊等，治宜养心血、调心气、降火安神：心火甚用安神丸（即朱砂安神丸）；心血虚热用四物安神汤；心神浮越用清镇汤；水衰火旺、心动不安用天王补心丹；汗下后气虚用益营煎；**营卫俱衰、脉来结代、心惕不安用养心汤**；心动卧不安用枣仁汤；思虑烦劳心动不寐用养营汤；忧思郁结怔忡不已用归脾汤；心虚怔忡自汗用养营汤去木香加浮小麦；气郁不宣用加味四七汤加姜汁竹沥；痰火怔忡时作时止用参胡温胆汤、金箔镇心丸。"}, {"source": "类证治裁心悸条文注释｜四、脉候（「惊悸脉必结代」——脉学锚点）", "原文": "手厥阴脉动甚，则心澹澹大动，胃络名虚里，贯膈络肺，出左乳下，其动应衣，虚而有痰则动，更须臾发一阵热者是也。以上怔忡脉。惊悸脉必结代，寸口脉动而弱。动为惊，弱为悸。病在心胆，其脉必大动，惊者其脉止而复来，其人目睛不转，不能呼气。", "白话": "手厥阴脉（心包）搏动明显时，心下澹澹大动；胃之络脉名虚里，贯膈络肺，出于左乳下，其搏动可透过衣服看到——虚而有痰则动，且一阵阵发热，这是怔忡的脉。**惊悸的脉必见结代**；寸口脉动而弱：动主惊，弱主悸。病在心胆者脉大动；惊证的脉停而复来，伴目睛不转、不能呼气。"}, {"source": "类证治裁心悸条文注释｜五、医案选（怔忡脉案三则＋惊恐脉案一则）", "原文": "汪氏 病久失调，延成虚损，怔忡汗出，手足心热，坐起眩晕，善饥无寐。诊左寸虚散，右寸关虚弦，两尺稍大。此阴亏火炎之渐……滋液熄风，全用柔剂，归脾汤去 、术、木香、归、姜。加白芍、丹皮、熟地、甘菊（炒），六服渐安。\n> 贡氏 惊悸恍惚，不饥不食不寐，脉虚促。病因怒恐而得，胆火上冒则头眩心忡，胸脘刺痛，气结，呵欠怯冷，倏烦热多惊，皆阳越失镇……先镇浮阳，再议和阴。牡蛎、龙骨、磁石、柏子仁、连翘心、茯神、", "白话": "汪氏**：久病失调理而成虚损，怔忡出汗、手足心热、坐起头晕、易饥失眠。左寸脉虚散、右寸关虚弦、两尺稍大——阴亏火炎之渐，用滋液熄风柔剂，归脾汤加减，六服渐安（后以六味丸收功）。\n- **贡氏**：因怒恐而病惊悸恍惚、不饥不食不寐，**脉虚促**，胆火上冒则头眩心忡、胸脘刺痛、呵欠怯冷、倏然烦热多惊——阳气浮越失于镇摄。先镇浮阳（牡蛎、龙骨、磁石、柏子仁、连翘心、茯神、生枣仁），再议和阴（羚羊角、桑叶、熟地、枣仁、茯神、白芍、小麦、麦冬、半夏）。\n- 他案：吴氏产后去血多、心虚"}, {"source": "素问六气玄珠密语运气心病条文注释｜一、五运经天总纲", "原文": "丁壬为木运也，戊癸为火运也，甲己为土运也，乙庚为金运也，丙辛为水运也……故**先轮五运后纪司天**也，即常以司天为客，运气为主也，在泉亦为客，居气间气为次客也。", "白话": "天干化五运（丁壬木/戊癸火/甲己土/乙庚金/丙辛水）；推算次序：先定岁运、再纪司天——司天为客气、岁运为主气，在泉与间气为次。"}, {"source": "素问六气玄珠密语运气心病条文注释｜二、水运太过伤心（年运实例·核心）", "原文": "丙寅中水运太羽**，水气有余，其名流衍……**中克心脏受病**，即寒气流行，邪害心火，民病**身热烦心、燥悸**、阴厥、上中下寒、谵忘、**心痛**，寒气早至，甚则腹大胫肿、喘咳。\n> **丙子中水运太羽**……太阳司天太过，即水气临火令长不从……**心脏受病，久及小肠**。", "白话": "丙寅年（水运太过）：寒水之气克心——人们多病身热心烦、燥悸、厥冷、谵妄善忘、**心痛**；重则腹大胫肿喘咳。丙子年水运太过+太阳司天：水气临火，**心脏受病，久连小肠**。"}, {"source": "脉经脉学条文注释｜一、卷一·脉形状指下秘决第一——促脉（数而时一止）", "原文": "促脉，来去数，时一止复来。", "白话": "促脉的脉象：**脉搏往来急数，中间时有一停跳，停后随即恢复跳动**。"}, {"source": "脉经脉学条文注释｜二、卷一·脉形状指下秘决第一——涩脉（细迟散止）", "原文": "涩脉，细而迟，往来难且散，或一止复来。（一曰浮而短，一曰短而止。或曰散也）", "白话": "涩脉的脉象：**脉体细、跳得慢，往来艰涩不流畅，且有涣散感，或兼见停一跳再恢复**。一说浮而短；一说短而有歇止；也有说即是散象。"}, {"source": "脉经脉学条文注释｜三、卷一·脉形状指下秘决第一——结脉（缓而时一止）", "原文": "结脉，往来缓，时一止复来。（按之来缓，时一止者，名结阳；初来动止，更来小数，不能自还，举之则动，名结阴）", "白话": "结脉的脉象：**脉搏往来较缓，中间时有一停跳，停后即恢复**。括注一说：按之来势缓、时有一止的叫「结阳」；初来即停、再来略快（小数）而不能自复、轻取则动的叫「结阴」。"}, {"source": "脉经脉学条文注释｜四、卷一·脉形状指下秘决第一——代脉（不能自还）与「脉结者生，代者死」", "原文": "代脉，来数中止，不能自还，因而复动。脉结者生，代者死。", "白话": "代脉的脉象：**脉搏跳动中间停歇，停后不能自行恢复原有节律，过一阵才重新跳动**。见到结脉的预后尚好，见到代脉的预后险恶。"}, {"source": "脉经脉学条文注释｜五、卷一·迟疾短长杂脉法第十三——代则气衰、涩则心痛（主病纲领）", "原文": "夫脉者，血之府也。长则气治，短则气病，数则烦心，大则病进，上盛则气高，下盛则气胀，代则气衰，细则气少，涩则心痛。", "白话": "脉是血汇聚运行的场所。脉长说明气足，脉短说明气病，脉数则心烦，脉大则病进……**代脉主正气衰败，细脉主气少，涩脉主心痛**。"}, {"source": "脉经脉学条文注释｜六、卷四·诊脉动止投数疏数死期年月第六——止数定死期（古脉律量化）", "原文": "脉一动一止，二日死……五十动一止，五岁死。不满五十动一止，五岁死。\n> 脉来五十投而不止者，五脏皆受气，即无病。\n> 脉来四十投而一止者，一脏无气，却后四岁，春草生而死。", "白话": "脉搏每跳几下就停一停，停得越频繁，死期越近：每动一止的约二日死……每五十动一止的约五年死。反之，**连续跳五十动而无歇止的，五脏之气皆足，是无病之脉**。四十动一止者一脏无气，四年后当死；三十动一止者二脏无气；十动一止者四脏无气。"}, {"source": "脉经脉学条文注释｜七、卷五·扁鹊诊诸反逆死脉要诀第五——死脉类「结」「代」（同名异实辨）", "原文": "脉有表无里者，死。经名曰结，去即死。何谓结？脉在指下如麻子动摇，属肾，名曰结，去死近也。\n> 脉五来一止，不复增减者，死。经名曰代。何谓代？脉五来一止也。", "白话": "脉浮取有、沉取无（有表无里）的，是死脉，经书称之为「结」，一出现即凶。什么是这种结脉？**指下如麻子（芝麻）般细碎动摇、旋引旋收、聚散无常**的，名叫结，离死不远。又：脉五跳一停、停后节律不再恢复的，是死脉，经书称之为代。"}, {"source": "脉经脉学条文注释｜八、卷九·平惊悸衄吐下血胸满瘀血脉证第十三——动则为惊，弱则为悸", "原文": "寸口脉动而弱，动则为惊，弱则为悸。趺阳脉微而浮，浮则胃气虚，微则不能食，此恐惧之脉，忧迫所作也。\n> 惊生病者，其脉止而复来，其人目睛不转，不能呼气。", "白话": "寸口脉见动而弱的：**动脉主惊，弱脉主心悸**。趺阳脉微而浮，是胃气虚、不能食，属恐惧之脉，由忧惧所生。因惊而病者，**脉搏停而复来、目睛呆滞不能转动、呼吸窘迫不能出气**。"}, {"source": "脉经脉学条文注释｜九、卷七·病发汗吐下以后证第八＋病不可下证第六——误治致悸（心悸的医源性观察）", "原文": "太阳病三日，已发其汗，吐下、温针而不解，此为坏病……脉浮数，法当汗出而愈，而下之，则身体重，心悸，不可发其汗，当自汗出而解。所以然者，尺中脉微，此里虚。\n> 动气在右，不可下。下之则津液内竭，咽燥鼻干，头眩心悸。", "白话": "太阳病误治成坏病：脉浮数本应汗解，误下后出现**身体沉重、心悸**，此时不可再发汗，待其自汗出而解——因为尺脉微，是**里虚**。脐右动气者禁下，误下则津液枯竭，见咽鼻干燥、**头晕心悸**。"}, {"source": "脉经脉学条文注释｜十、卷四·诊百病死生诀第七——结生代死的临床再证", "原文": "泄注，脉缓，时小结者，生；浮大数者，死。\n> 寒热，瘈疭，其脉代、绝者，死。\n> 热病，七、八日，其脉微细，小便不利，加暴口燥，脉代，舌焦干黑者，死。", "白话": "暴泻如注者，脉缓而偶有小结（轻度歇止）的，预后好；脉浮大数的，预后差。寒热抽搐者见代脉或脉绝的，死。热病七八日见微细脉、小便不利、口燥、**代脉**、舌焦干黑的，死。"}, {"source": "脉诀刊误脉学条文注释｜一、促脉——数而时一止（快速型脉律不齐）", "原文": "〔四〕促者阳也。** 指下寻之，极数，并居寸口。（又曰：来去数，时一止复来。）曰促。渐加则死，渐退则生。\n> 促脉，尺微关细，寸口独实而滑数，并居于上。或来去数，时一止复来。黎氏曰：促脉虽盛疾，必时一止复来者，如趋之蹶也，故徐疾不常。\n> 歌曰：促脉前来已出关，并居寸口〔血成斑〕（证危难）。**血成斑非促脉证。** 忽然渐退人生也，若或加时命在天。", "白话": "促脉属阳。指下按去脉跳极快，独盛聚于寸部（一说脉来去皆快、中间时有停跳而又恢复），称为促脉；**逐渐加重者预后差，逐渐减退者可生**。促脉的形态是尺部微、关部细、寸口独实而滑数，盛于上部；或脉来去皆数、时有一停而复来。黎氏说：促脉虽然来势盛疾，但必有「时一止复来」，像快跑的人绊了一跤（蹶），所以快慢不匀。歌诀旧文说促脉主「血成斑」，戴氏明断**血成斑不是促脉的主证**（旧文误）；病情忽然减退则生，若持续加重则命在旦夕。"}, {"source": "脉诀刊误脉学条文注释｜二、结脉——缓而时一止、能自还", "原文": "〔五〕结者阴也。** 指下寻之，〔或来或去聚而却还〕（脉来缓，时一止复来，无常数。又曰：脉来动而中止，更来小数，中有还者反动。）曰结。主四肢，气闷，连痛，时来。\n> 迟而小驶为缓，应指暂歇为止，**缓而止为结**。……盖止而复来，数至，间或三两至，或又一止，**无常数**。若有常数，如五动一止，又五动一止，根据数而止，则为死脉。", "白话": "结脉属阴。指下所见，旧文说「或来或去、聚而却还」，戴氏据仲景改为「脉来缓，时一止复来，无常数」，又引仲景「脉来动而中止，更来小数，中有还者反动」（停后稍快补上）亦曰结。主四肢气闷连痛、时发时来。脉势缓而略快叫缓，指下暂歇叫止，**缓而有止就是结脉**。其停跳无规律：或跳若干至一止、或三两至又一止。**若有规律（如五动一止、又五动一止、按数而止），那是死脉（代脉类），不属结**。"}, {"source": "脉诀刊误脉学条文注释｜三、代脉——止有常数、不能自还（预后分层核心）", "原文": "〔六〕代者阴也。** 指下寻之，〔动而复起冉冉不能自还〕（动而中止，不能自还，因而复动。）曰代。主形容羸瘦，口不能言。\n> 代者，此脉已绝，他脏代其至之义……代与止异者：止者按之，觉于指下而中止；代者忽还尺中，停久方来……因其呼吸阴阳相引乃复动也。《内经》曰「代则气衰」。仲景曰「伤寒脉结代，心动悸，炙甘草汤主之」，**皆不以代为死脉也**。王氏《脉经》始曰「脉结者生，代者死」。", "白话": "代脉属阴。指下所见为脉跳动而中止、不能自行恢复、过一阵才再动。代脉的本义是**一脏气绝、他脏之气代而至**。代与一般「止」不同：止只是指下觉出中停；代是**停跳后脉气退回尺部、良久才来**，靠呼吸间阴阳相引才重新鼓动。《内经》说「代则气衰」，仲景说「伤寒脉结代、心动悸，炙甘草汤主之」——**两部经典都不把代脉一概判死**；「脉结者生、代者死」是王叔和《脉经》才出现的说法。旧《脉诀》「动而复起」的说法不确（动而复起就不是代了），戴氏据仲景原文改正。"}, {"source": "脉诀刊误脉学条文注释｜四、四止脉鉴别——涩促结代同一止而全不同", "原文": "诸脉有止者四：**涩、促、结、代**也。脉细而迟，往来难，时一止者，为涩；脉来数，时一止者为促；脉来缓，时一止者为结。凡此三者均谓之止，而其所以止者**迥然不同**，为病亦异，**而皆非死脉也**。……真见其止如代中之止，然后断之为死，则不失矣。\n> **代脉之止，其止有常数而不忒**：如十动一止，则数十止皆见于十动之后；如二十动一止，则数十止皆见于二十动之后，及加进亦如是，方为代脉。\n> 活人书", "白话": "有停跳的脉共四种：涩、促、结、代。脉细而慢、往来艰涩、时有一止的是**涩**；脉快、时有一止的是**促**；脉缓、时有一止的是**结**。三者都叫「有止」，但停跳的机理、主病都不同，**都不是死脉**。只有见到代脉那种停跳，才可断为危候。**代脉的停跳有固定节律（常数）**：十动一止就每次都在第十动后停，二十动一止就每次在二十动后停，病情进退也照此比例——这才是代脉。《活人书》说：阴盛则结（胸满烦躁），阳盛则促（积聚气痞、忧思所致）；**结、促只是病脉，代才是危脉**。"}, {"source": "脉诀刊误脉学条文注释｜五、脉难尽凭——促脉的寒热反证与脉证合参", "原文": "又云**促脉为阳盛，宜用葛根黄芩黄连汤；若脉促厥冷为虚脱，非灸非温不可**。此又非促为阳盛之脉也。……凡此皆脉难尽凭之明验也。**若只凭脉而不问症**，未……", "白话": "仲景又说：促脉一般属阳盛，宜用葛根黄芩黄连汤（表证误下、里热喘汗之促）；**但若脉促而四肢厥冷，则属虚脱，非用灸法温阳不可**——这就不是「促=阳盛」能涵盖的了。这些例子都证明脉象不能单独作为定论；若只诊脉不问症状，就会误判。"}, {"source": "脉诀刊误脉学条文注释｜六、相类脉辨——涩促结代「同一止也而全不同」", "原文": "又有数脉之相类，如**涩、促、结、代，同一止也，而全不同**。他如濡弱迟，如芤虚，如微细濡弱涩，已辨于各脉条下。", "白话": "脉象有形态相近而实质不同的「相类」关系：涩、促、结、代四者都表现为「有停跳」，但机理与主病完全不同；濡与弱、迟，芤与虚，微细与濡弱涩等亦各有所别，已在各脉条目下分别辨明。"}, {"source": "脉诀汇辨脉学条文注释｜一、卷三·涩脉（阴）——「心痛怔忡」的病机链展开", "原文": "体象 涩脉蹇滞，如刀刮竹；迟细而短，三象俱足。\n> 主病 涩为血少，亦主精伤。左寸涩者，心痛怔忡。涩在左关，血虚肋胀。左尺得涩，精伤胎漏。\n> 血少则不能养心而痛作；积久而加以惊疑，则怔忡至矣。\n> 叔和谓其「一止复来」，亦有疵病。盖涩脉往来迟难，有类乎止而实非止也。", "白话": "涩脉体象同《诊家正眼》：**蹇滞如刀刮竹，迟、细、短三象俱足**。主病：涩主血少、精伤；**左寸涩主心痛、怔忡**；左关涩主血虚胁胀；左尺涩主精伤胎漏。病机链：**血少则不能养心而心痛发作；拖延日久加上惊恐疑虑，就会发展为怔忡**。李延昰按：王叔和说涩「一止复来」有毛病——涩往来迟难，类似歇止而其实不是歇止。"}, {"source": "脉诀汇辨脉学条文注释｜二、卷四·促脉（阳）——「促脉随病呈形」与轻重二因", "原文": "体象 促为急促，数时一止；如趋而蹶，进则必死。\n> 藏气乖违，则稽留凝泣，阻其营运之机，因而歇止者，其止为轻；若真元衰惫，则阳弛阴涸，失其揆度之常，因而歇止者，其止为重。\n> 然促脉之故，得于藏气乖违者十之六七，得于真元衰惫者十之二三……促脉随病呈形。", "白话": "促脉体象：**急促之中数而时一止，像快走中绊倒，病进则凶**。按语：因**脏气乖违**（稽留凝泣阻遏营运）而歇止的，病轻；因**真元衰惫**（阳弛阴涸失其常度）而歇止的，病重。促脉成因前者占十之六七、后者十之二三……**促脉的形态随具体疾病而呈现**（须与他脉相参）。"}, {"source": "脉诀汇辨脉学条文注释｜三、卷四·结脉（阴）——止歇多寡断轻重", "原文": "体象 结为凝结，缓时一止；徐行而怠，颇得其旨。\n> 结而不散，迟滞中时见一止也。\n> 主病 结属阴寒，亦由凝积。左寸结者，心寒疼痛……右寸结者，肺虚气寒。结在右关，痰滞食停。\n> 浮结者外有痛积，伏结者内有积聚。故知结而有力者，方为积聚；而无力者，是真气衰弱……是知又当以止歇之多寡，而断病之重轻也。", "白话": "结脉体象：**凝结不散、迟滞中时见一止，如慢走偶歇一步**。主病：结属**阴寒**，也由**凝积**；左寸结主心寒疼痛，右寸结主肺虚气寒，右关结主痰滞食停。按语：**浮取见结主外有痛积，沉取见结主内有积聚；结而有力的才是积聚，无力的是真气衰弱（宜温补）——还应以歇止的多少判断病情轻重**（越人「结甚则积甚，结微则气微」）。"}, {"source": "脉诀汇辨脉学条文注释｜四、卷四·代脉（阴）——结代促辨异总纲与伤寒心悸三因", "原文": "代亦歇止之脉。但促、结之止，内有所碍，虽止而不全断，中有还意；代则止而不还，良久复止，如四时之禅代，不愆其期也。又促、结之止，止无常数；代脉之止，止有定期。\n> 主病 代主藏衰，危恶之候。脾土败坏，吐利为咎。\n> 伤寒心悸，有中气虚者，停饮者，汗下后者……诸悸者，未必皆脉代；若脉代者，正指汗后之悸，以汗为心液，脉为心之合耳。\n> 女胎十月而产……当三月之时，心包络养胎……若分气及胎，脉必虚代。", "白话": "代也是歇止脉，但**促、结的歇止是内有阻碍，虽止而未全断、中间有恢复之意；代脉则止后不能恢复、良久才又动，如四时禅代不误期。促结的歇止无常数，代脉的歇止有定期**。主病：代主脏气衰败、危恶之候，脾土败坏见吐泻。又：**伤寒心悸有三种病机——中气虚（阳陷不能上充胸中）、停饮（水停心下、水气上凌）、汗下后（汗为心液、心液耗则心虚）**。但各种心悸未必都见代脉；**若见代脉，正指汗后之心悸**（汗为心液、脉为心之合）。女子怀胎三月由心包络养胎（心包主脉），此时脉见虚代为常。"}, {"source": "脉诀汇辨脉学条文注释｜五、卷三·迟脉按语——迟涩结的三向分界", "原文": "迟而不流利则为涩脉，迟而有歇止则为结脉，迟而浮大且缓则为虚脉。\n> 有力冷痛，无力虚寒。浮迟表冷，沉迟里寒。迟涩血少，迟缓湿寒。", "白话": "迟脉兼象的分界：迟而往来不流利的是涩脉；迟而有歇止的是结脉；迟而浮大且缓的是虚脉**。兼脉主病：迟而有力主冷痛，无力主虚寒；浮迟表冷、沉迟里寒；迟兼涩主血少，迟兼缓主湿寒。"}, {"source": "脉诀汇辨脉学条文注释｜六、卷五·小儿脉法——「气促脉代」与「散乱无伦」", "原文": "三岁以上，便可凭脉。独以一指，按其三部；六至七至，乃为常则……伏结物聚。单细疳劳。气促脉代。散乱无伦，此所最忌，百难必一。", "白话": "小儿三岁以上可凭脉，以一指按三部，**六七至为常**（小儿脉快于成人）……沉伏有结主宿食物聚；单细则疳劳；**气息急促而脉见代的，危重；脉散乱无规律的最忌，百例难活一例**。"}, {"source": "脉诀汇辨脉学条文注释｜七、卷九·医案两则——促代预后的著名对照课", "原文": "燕都王湛六兄，以脾泄求治，神疲色瘁。诊得促脉，或十四五至得一止，或十七八至得一止。余谓其原医者曰，法在不治……是真元败坏，阴阳交穷，而促脉呈形……居一月而果殁。\n> 善化令黄桂岩，心疼夺食，脉三动一止，良久不能自还……古人谓痛甚者脉多代。周梅屋云∶「少得代脉者死，老得代脉者生。」今桂岩春秋高矣……果越两旬而桂岩起矣。", "白话": "王湛六患脾泄、神疲色瘁，诊得促脉（十四五至或十七八至一止）——李延昰断「法在不治」，医者争「这不是代脉不过是促脉」，答：**是真元败坏、阴阳交穷的促脉，与稽留凝泣的促脉不同**，一月后果然死亡。黄桂岩心疼少食，脉三动一止、良久不能自还（代脉）——原医断旦夕死；李延昰据「痛甚者脉多代」「少得代脉者死，老得代脉者生」，因其年高且胸腹负痛，断不足虑，果两旬而愈。「故欲穷脉之变者，非博学人不能也。」"}, {"source": "证治准绳·伤寒心悸条文注释｜一、「悸」总论——悸的三大病机纲领", "原文": "成：** 悸，心忪也，筑筑惕惕然动，怔怔忪忪不能自安也。有气虚而悸，有停饮而悸，有汗下后而悸者。（汗为心液，汗去心虚，如鱼无水，故悸。）……其治或镇固之，或化散之。惟饮之为悸甚于他邪，虽有余邪必先治悸。何者？以水停心下无所不入，侵于肺为喘嗽，传于胃为哕噎，溢于皮肤为肿，渍于肠者为利，治不可缓也。故经曰：厥而心下悸，宜先治水，与茯苓甘草汤，后治其厥。", "白话": "成无己注：** 「悸」就是心慌——心跳阵阵跳动、惕惕不安，心里怔怔忪忪没法安静。病机分三类：**①气虚而悸；②水饮停蓄而悸；③汗下误治后而悸**（汗是心的津液，汗出过多则心虚，如鱼离水，所以发悸）。治疗上或用镇固法、或用化散法。唯独**水饮致悸最重**，即使还有别的余邪，也必须先治悸——因为水停心下无处不侵：射肺则喘咳，犯胃则哕噎，外溢皮肤则浮肿，下渍肠道则下利，治不可缓。所以《伤寒论》说「厥而心下悸，宜先治水，与茯苓甘草汤，却治其厥」。"}, {"source": "证治准绳·伤寒心悸条文注释｜二、伤寒脉结代、心动悸——炙甘草汤（复脉汤）", "原文": "伤寒脉结代、心动悸，炙甘草汤主之。**成：** 结代之脉，动而中止，能自还者名曰结，不能自还者名曰代，由血气虚衰不能相续也。心中悸动，知真气内虚也，与炙甘草汤益虚补血气而脉复。\n> **炙甘草汤方（一名复脉汤）** 甘草（炙四两） 生姜（切） 桂枝（去粗皮各三两） 人参 阿胶（各二两） 生地黄（一片） 麦门冬（去心） 麻子仁（各半升） 大枣（十二枚擘）。上九味，以清酒七升、水八升，先煮八味取三升，", "白话": "外感热病中出现**脉跳中间有停歇（结代脉）伴心慌跳动**的，用炙甘草汤主治。成无己注：结代脉都是跳动中突然中止——**停后能自己恢复的叫结，不能恢复的叫代**，由血气虚衰、脉气不能接续所致；心中悸动说明真气内虚，用炙甘草汤补益虚损、恢复血气则脉复。方：炙甘草四两，生姜、桂枝各三两，人参、阿胶各二两，生地黄一片（原文如此），麦冬、麻子仁各半升，大枣十二枚；清酒七升加水八升，先煮八味取三升，去渣后把阿胶烊化，每次温服一升，日三服。"}, {"source": "证治准绳·伤寒心悸条文注释｜三、桂枝甘草汤与茯苓桂枝甘草大枣汤（心阳虚悸与欲作奔豚）", "原文": "发汗过多，其人叉手自冒心，心下悸欲得按者，桂枝甘草汤主之。**成：** 发汗过多亡阳也，阳受气于胸中，胸中阳气不足，故病叉手自冒心。心下悸欲得按者，与桂枝甘草汤以调不足之气。\n> **桂枝甘草汤方** 桂枝（去粗皮四两） 甘草（炙二两）。上二味，以水三升煮取一升，去滓，顿服。\n> 发汗后，其人脐下悸者，欲作奔豚，茯苓桂枝甘草大枣汤主之。**成：** 汗者心之液，发汗后脐下悸者，心气虚而肾气发动也…", "白话": "发汗太过，病人双手交叉按护心前区、**心慌要用手按着才舒服**的，用桂枝甘草汤（桂枝四两、炙甘草二两，水煮取一升，一次服完）。发汗后**脐下跳动、像要发奔豚**的，用茯苓桂枝甘草大枣汤：茯苓半斤、桂枝四两、炙甘草二两、大枣十五枚，用「甘烂水」一斗煎（甘烂水制法：水二斗放盆中用勺扬，水面起五六千颗相逐的水珠即取用）。"}, {"source": "证治准绳·伤寒心悸条文注释｜四、真武汤——阳虚水泛悸（附医案二则）", "原文": "太阳病发汗，汗出不解，其人仍发热，心下悸、头眩、身动，振振欲擗地者，真武汤主之。（方见下利）\n> **孙：** 太乙宫道士周德真患伤寒发汗出多，惊悸目眩，身战掉欲倒地……召孙至曰：太阳经病得汗早，欲解不解者，因太阳经欲解复作汗，肾气不足，汗不来，所以心悸目眩身转。遂作真武汤服之，三服微汗自出，遂解。盖真武汤附子白术和其肾气，肾气得行故汗得来也。\n> **许学士：** 乡里有一姓高者子，年三十，初得", "白话": "太阳病发汗后汗出而病不解，仍发热，见**心慌、头晕、肌肉瞤动、抖得像要倒地**的，用真武汤。孙姓医案：道士周德真伤寒汗出太多，心惊悸动、目眩、浑身战抖欲倒——孙氏认为汗出太早而肾气不足、汗不能收，用真武汤三服微汗出而解（附子白术温固肾气）。许叔微案：高家子三十岁，误用麻黄发汗不止，发热、惊悸不眠、谵语、筋惕肉瞤，前医又用镇心药无效；许氏断为强汗之过，用真武汤三服而救。"}, {"source": "证治准绳·伤寒心悸条文注释｜五、厥阴心下悸与小柴胡加减（水饮悸与和解法度）", "原文": "伤寒厥而心下悸者，宜先治水，当服茯苓甘草汤，却治其厥；不尔，水渍入胃，必作利也。**成：** 金匮要略曰「水停心下甚者则悸」。厥虽寒胜，然以心下悸为水饮内甚，先与茯苓甘草汤治其厥而后治其水（原文如此，语序待核）。\n> **茯苓甘草汤方** 茯苓 桂枝（去粗皮各二两） 生姜（三两切） 甘草（炙一两）。上四味，以水四升煮取二升，去滓分温三服。\n> 若心下悸、小便不利者，去黄芩，加茯苓四两。（小柴胡汤加", "白话": "伤寒手足厥冷兼**心下悸**的，应当先治水，用茯苓甘草汤，然后再治厥冷；不这样，水饮浸渍胃肠必变下利。茯苓甘草汤：茯苓、桂枝各二两，生姜三两，炙甘草一两，水煮分三次温服。小柴胡汤加减法：**兼心下悸、小便不利者，去苦寒的黄芩，加茯苓四两**利水宁心。太阳病若小便通利而饮水过多，水停胸胃，必心下悸；小便少者则水蓄于内必苦里急。"}, {"source": "证治准绳·伤寒心悸条文注释｜六、伤寒后惊悸怔忡——调理四方（茯苓丸/犀角汤/麦门冬茯苓饮子/温胆汤）", "原文": "惊悸**……伤寒中有单言惊者，有单言悸者……其兼言惊悸者，则少阳耳聋目赤胸满而烦者，不可吐下，吐下则悸而惊一条而已。\n> **海 茯苓丸** 治伤寒后或用心劳倦，四肢羸弱，心忪惊悸，吸吸短气。茯神 麦门冬（去心） 熟地（各一两） 牡丹皮 人参 黄 （各七钱） 桂枝 甘草（炙） 牛膝 泽泻（各半两）。上为细末，炼蜜和捣，丸如梧桐子大，每服二十丸，食前温酒下。\n> **犀角汤** 治伤寒后伏热在心，怔", "白话": "「惊」与「悸」分论：少阳病耳聋目赤胸满而烦者不可吐下，**误吐下则悸而惊**（医源性致悸）。伤寒后调理诸方：\n- **茯苓丸**：治伤寒后劳心疲倦、四肢瘦弱、心慌惊悸、气短不续（茯神、麦冬、熟地、丹皮、人参、黄芪、桂枝、炙甘草、牛膝、泽泻为蜜丸，温酒下）。\n- **犀角汤**：治伤寒后**伏热在心**、怔忡惊悸、失眠（犀角、茵陈、茯苓、芍药、生地、麦冬、山栀，竹叶生姜煎）。\n- **麦门冬茯苓饮子**：治伤寒后心神恍惚不得卧。\n- **加味温胆汤**：治瘥后心胆虚怯、遇事易惊"}, {"source": "证治准绳·伤寒心悸条文注释｜七、惊——柴胡加龙骨牡蛎汤与救逆汤（误治惊狂）", "原文": "夫惊，坏病也，由误下、火逆、温针所致，仲景之法不过随其逆而调之。\n> 伤寒八九日，下之，胸满烦惊，小便不利，谵语，一身尽重不可转侧者，柴胡加龙骨牡蛎汤主之。**成：** ……惊者，心恶热而神不守也……与柴胡汤以除胸满而烦，加龙骨牡蛎铅丹收敛神气而镇惊，加茯苓以行津液利小便，加大黄以逐胃热止谵语，加桂枝以行阳气而解身重。\n> 伤寒脉浮，医以火迫劫之，亡阳，必惊狂起卧不安者，桂枝去芍药加蜀漆牡蛎龙骨救", "白话": "「惊」是坏病，由误下、火逆、温针等误治造成，仲景治法是随其逆证调治。伤寒八九天误下后，胸满、**烦惊**、小便不利、谵语、一身沉重不能转侧的，用柴胡加龙骨牡蛎汤（小柴胡加龙骨、牡蛎、铅丹镇惊，茯苓利水，大黄逐胃热，桂枝行阳）。伤寒脉浮本应汗解，医家用火法强迫发汗，亡阳而见**惊狂、坐卧不安**的，用桂枝去芍药加蜀漆牡蛎龙骨救逆汤：桂枝、生姜、蜀漆各三两，牡蛎五两，龙骨四两，炙甘草二两，大枣十二枚。"}, {"source": "证治准绳·伤寒心悸条文注释｜八、动气与误下悸——禁忌证中的心悸", "原文": "动气在右，不可下，下之则津液内竭，咽燥鼻干，**头眩心悸**也。……脉浮数者，法当汗出而愈，若下之身重心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚，须表里实，津液自和，便自汗出愈。\n> 少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，四逆散主之。（悸者，加桂五分。）\n> 手足厥冷而悸者，茯苓甘草汤；手足逆而不温者，四逆散加桂枝；霍乱吐利心悸者，理中丸加茯苓。", "白话": "脐右有动气（跳动感）者不可攻下，误下则津液枯竭，出现咽鼻干燥、头晕心慌。脉浮数本当发汗，误下后身重、心悸者**不可再发汗**，待里气实、津液自和而自汗解（尺脉微=里虚）。少阴病手足冷兼或然悸者，用四逆散，**悸者加桂枝五分**。手足厥冷而悸者用茯苓甘草汤；手足逆冷不温者四逆散加桂枝；霍乱吐泻后心悸者理中丸加茯苓。"}, {"source": "证治汇补心悸条文注释｜一、大意与内因（辨证总纲）", "原文": "大率惊悸属痰与火。怔忡属血虚有火。（丹溪）\n> 人之所主者心。心之所养者血。心血一虚。神气失守。神去则舍空。舍空则郁而停痰。痰居心位。此惊悸之所以肇端也。（汇补）", "白话": "大体上**惊悸属痰与火，怔忡属血虚有火**（朱丹溪语）。心是人身之主，心所赖以滋养的是血。心血一虚，神气就失于守藏；神离开则心舍空虚，心舍空虚则气郁而痰停，**痰占据心的位置**——这就是惊悸发生的起点。"}, {"source": "证治汇补心悸条文注释｜二、外候（惊悸/怔忡鉴别定式）", "原文": "惊悸者。忽然若有惊。惕惕然心中不宁。其动也有时。怔忡者。心中惕惕然。动摇不静。其作也无时。（正传）", "白话": "惊悸**是忽然像受惊一样、心中惕惕不宁，**跳动有时有止**；**怔忡**是心中惕惕、摇动不静，**发作没有定时**。"}, {"source": "证治汇补心悸条文注释｜三、病因八条（本篇辨证纲领主体·每条附脉）", "原文": "肝胆心虚：或因怒伤肝。或因惊入胆。母令子虚。而心血为之不足……其脉弦者是也。\n> 郁痰：或耳闻大声。目见异物。遇险临危……大惊大恐。心为之忤。以致心虚停痰……甚则心跳欲厥。其脉滑者是也。\n> 停饮：有停饮水气乘心者。则胸中漉漉有声……故筑筑跳动。使人有怏怏之状。其脉偏弦。\n> 气虚：有阳气内虚。心下空豁。状若惊悸。右脉大而无力者是也。\n> 血虚：有阴气内虚。虚火妄动。心悸体瘦。五心烦热。面赤唇燥。", "白话": "①**肝胆心虚**：怒伤肝或惊入胆，母令子虚致心血不足（脉弦）；②**郁痰**：听到大声音、见异物、临险遇危、大惊大恐，心受触动而虚、停痰，甚则心跳欲厥（脉滑）；③**停饮**：水气乘心，胸中漉漉有声、筑筑跳动、郁郁不安（脉偏弦）；④**气虚**：阳气内虚，心下空豁，像惊悸（右脉大而无力）；⑤**血虚**：阴气内虚、虚火妄动，心悸体瘦、五心烦热、面赤唇燥（左脉微弱或虚大无力）；⑥**痰结**：膏粱厚味生痰，忽然惊惕而悸（脉弦滑有力）；⑦**气郁**：忧郁之人气郁生涎，涎气相搏"}, {"source": "证治汇补心悸条文注释｜四、脉法与治法（总治则）", "原文": "脉法：寸口脉动而弱。动为惊。弱为悸。惊者其脉止而复来。其人目睛不转。不能呼气。（必读）\n> 治法：痰则豁痰定惊。饮则逐水蠲饮。血虚者。调养心血。气虚者。和平心气。痰结者。降下之。气郁者。舒畅之。阴火上炎者。治其肾而心悸自已。若外物卒惊。宜行镇重。又惊者平之。所谓平者。平昔所见所闻。使之习熟。自然不惊也。（汇补）", "白话": "脉法：寸口脉动而弱——**动是惊，弱是悸**；受惊者脉有停跳而复来，伴**目睛不转、不能呼气**（《医宗必读》）。治法：痰用豁痰定惊，饮用逐水蠲饮，血虚调养心血，气虚和平心气，痰结用降下法，气郁用舒畅法，**阴火上炎者治肾而心悸自止**。外物猝惊者宜用镇重法；「惊者平之」的「平」是让病人对平素所见所闻反复习熟，自然不再惊。"}, {"source": "证治汇补心悸条文注释｜五、用药加减（主方+加味法度）", "原文": "用药：主以安神丸。心虚甚者。加茯神、人参。神不宁者。加柏子、枣仁、远志。痰。加贝母、南星、半夏、石菖蒲。或用吐法。水饮。宜用小半夏茯苓汤。气虚。用参、芪。血虚。用四物。肾虚。用地黄汤。阳虚。用八味丸。痰结。用温胆汤。或滚痰丸。气郁。用四七汤。", "白话": "用药以**朱砂安神丸**为主方随证加减：心虚甚加茯神、人参；神不宁加柏子仁、酸枣仁、远志；有痰加贝母、南星、半夏、石菖蒲（或用吐法）；水饮用小半夏茯苓汤；气虚用参、芪；血虚用四物汤；肾虚用地黄汤（六味）；阳虚用八味丸；痰结用温胆汤或滚痰丸；气郁用四七汤。"}, {"source": "证治汇补心悸条文注释｜六、附证两条（卑惵、失志）", "原文": "【附卑惵】有胸中痞塞。不欲饮食。心中常有所歉。爱居暗室。或倚门见人。即惊避无地。似失志状。此为卑惵之病。由心血不足者。人参养荣汤。脾胃不和者。六君子汤。加益智、远志治之。\n> 【附失志】有所求不遂。或过纵自悔。嘘嗟夜语。若有所失。宜温胆汤。加人参、柏子仁为丸。辰砂为衣。日进三次。", "白话": "卑惵**：胸中痞塞、不欲饮食、心中常觉欠缺，喜欢待在暗室，或靠门见人就惊慌躲避无地可容，像失志之状——由心血不足者用人参养荣汤；脾胃不和者用六君子汤加益智仁、远志。**失志**：所求不遂或放纵后自悔，唉声叹气、夜里自语、若有所失——用温胆汤加人参、柏子仁为丸，辰砂为衣，每日三次。"}, {"source": "诊家正眼脉学条文注释｜一、卷二·涩脉（阴）——「有类乎止而实非止」（涩非止辨）", "原文": "〔体象〕涩脉蹇滞，如刀刮竹；迟细而短，三象俱足。\n> 〔主病〕涩为血少，亦主精伤。寸涩心痛，或为怔忡。关涩阴虚，因而中热……尺涩遗淋，血痢可决；孕为胎病，无孕血竭。\n> 〔兼脉〕涩而坚大，为有实热。涩而虚软，虚火炎灼。\n> 王叔和谓其一止复来，亦有疵病。盖涩脉往来迟难，有类乎止，而实非止也。", "白话": "涩脉的体象：**脉行蹇滞像刀刮竹子；迟、细、短三象俱全**。主病：涩主**血少、精伤**；**寸脉涩主心痛或怔忡**；关脉涩主阴虚中热；尺脉涩主遗精尿淋、血痢；孕妇见涩是胎病，非孕见涩是阴血枯竭。兼脉：涩而坚大为实热，涩而虚软为虚火。**李中梓辨：王叔和说涩脉「一止复来」有毛病——涩脉往来迟难，看似有歇止而其实不是歇止**。"}, {"source": "诊家正眼脉学条文注释｜二、卷二·促脉（阳）——轻重二因与「止数」进退判据", "原文": "〔体象〕促为急促，数时一止；如趋而蹶，进则必死。\n> 〔主病〕促因火亢，亦因物停。左寸见促，心火炎炎。右寸见促，肺鸣咯咯……左尺逢之，遗滑堪忧。右尺逢之，灼热为定。\n> 脏气乖违，则稽留凝泣，阻其营运之机，因而歇止者，其症为轻。若真元衰惫，则阳弛阴涸……因而歇止者，其症为重。", "白话": "促脉体象：**急促之中数而时有一止，像快走中绊倒**。主病：促因**火亢**，也因**有形之物停聚**（气滞/血凝/痰停/食壅）。左寸促是心火上炎，右寸促是肺气鸣响……按语：**因脏气乖违（气滞血凝痰食阻遏）而歇止的，病轻；因真元衰惫（阴阳亏竭）而歇止的，病重**——前者占十之六七，后者十之二三。"}, {"source": "诊家正眼脉学条文注释｜三、卷二·结脉（阴）——有力积聚、无力温补（虚实分治）", "原文": "〔体象〕结为凝结，缓时一止；徐行而怠，颇得其旨。\n> 〔主病〕结属阴寒，亦因凝积。左寸结见，心寒疼痛可决……右关结形，痰滞食停。左尺结见，痿 之 。右尺见结，阴寒为楚。\n> 结而有力者，方为积聚；结而无力者，是真气衰弱，违其运化之常，唯一味温补为正治也。", "白话": "结脉体象：**凝结不通、缓而时有一止，像慢走中偶歇一步**。主病：结属**阴寒**，也因**凝积**；左寸结主心寒疼痛，右关结主痰滞食停，右尺结主阴寒。按语：**结而有力的才是积聚（实）；结而无力的是真气衰弱（虚），只宜一味温补**。"}, {"source": "诊家正眼脉学条文注释｜四、卷二·代脉（阴）——禅代之义·代义四辨·黄桂岩案", "原文": "〔体象〕代为禅代，止有常数；不能自还，良久复动。\n> 〔主病〕代主脏衰，危恶之候。脾土败坏，吐利为咎。中寒不食，腹疼难救。两动一止，三四日死。四动一止，六七日死。\n> 惟伤寒心悸，怀胎三月，或七情太过，或跌打重伤，及风家痛症，俱不忌代脉，未可断其必死耳。\n> 若脉平匀而忽强忽弱者，乃形体之代……脾旺四季，而随时更代者，乃气候之代……五十动而不一代者，是乃至数之代也。", "白话": "代脉体象：**如四时禅代有定期——歇止有常数、不能自还、良久才复动**。主病：代主**脏气衰败**，危恶之候；脾土败坏见吐利，中寒不食腹痛难救。但**伤寒心悸、怀孕三月、七情太过、跌打重伤、风家痛症这五种情况都不忌代脉，不可断为必死**。按语辨「代」有四义：脉率歇止（至数之代）、忽强忽弱（形体之代）、随时更代（气候之代）、脾脉代（脏气常候）——须因变察情。"}, {"source": "诊家正眼脉学条文注释｜五、望色与闻诊——「叉手摸心，闭目不言，必心虚怔忡」", "原文": "掌中热，气不足，虚火盛。诊时病患叉手摸心，闭目不言，必心虚怔忡。", "白话": "掌中发热是气不足、虚火盛。**诊脉时病人双手交叉按护心前区、闭着眼睛不愿说话的，必定是心虚怔忡**。"}, {"source": "诊家正眼脉学条文注释｜六、怔忡脉证群——虚·细·散三脉左寸所主", "原文": "〔虚脉主病〕虚主血虚，又主伤暑。左寸心亏，惊悸怔忡。\n> 〔细脉主病〕细主气衰，诸虚劳损。细居左寸，怔忡不寐。\n> 〔散脉主病〕散为本伤，见则危殆。左寸见散，怔忡不寐。右寸见散，自汗淋漓。\n> 心脉软散而怔忡，肺脉软散为汗出，肝脉软散为溢饮。（戴同父）", "白话": "虚脉主血虚伤暑：**左寸虚主心亏，见惊悸怔忡**。细脉主气衰虚劳：**左寸细主怔忡不寐**。散脉主本元损伤、见则危殆：**左寸散主怔忡不寐**，右寸散主自汗淋漓。戴同父说：心脉软散主怔忡，肺脉软散主汗出，肝脉软散主溢饮。"}, {"source": "诊家正眼脉学条文注释｜七、诸病宜忌之脉＋脉辨至数——候五十动与忌短涩", "原文": "〔诸病宜忌之脉〕心痛 宜浮滑，忌短涩。\n> 〔脉辨至数〕五十动而不一代者，以为常也……不满十动一代者，五脏无气。予之短期。\n> 戴同父云∶三部九候，每候必满五十动，出自《难经》。", "白话": "心痛病宜见浮滑脉，忌见短涩脉。《灵枢》说：**五十动中无歇止是常脉**；不满十动就一歇止的，五脏无气、死期近了。戴同父说：三部九候每候必须数满五十动，出自《难经》。"}, {"source": "重订通俗伤寒论心悸条文注释｜一、复脉汤（滋阴复脉法）——俞氏对「心动悸、脉结代」的病机新解", "原文": "复脉汤** 滋阴复脉法，俞氏经验，从仲景方加减，一名炙甘草汤。\n> 大生地（一两） 真人参（钱半另煎冲） 炒枣仁（二钱） 桂枝尖（五分） 陈阿胶（二钱烊冲） 大麦冬（五钱） 清炙草（三钱） 陈绍酒（一瓢分冲） 生姜汁（两滴冲） 大红枣（三枚对劈）。\n> 【秀按】脉之动虽属心，而迫之使动者则在肺……病而至于心动悸，心主脉而本能动，动而至于悸，乃心筑筑然跳，按其心部动跃震手也，**是为血虚**。脉结代", "白话": "复脉汤即仲景炙甘草汤的俞氏加减版：大生地一两，人参钱半另煎兑入，炒枣仁二钱，桂枝尖五分，阿胶二钱烊化冲，麦冬五钱，炙甘草三钱，陈绍酒一瓢分冲，生姜汁两滴冲，大枣三枚对劈。何秀山按：脉搏跳动虽由心主持，但推动它跳的是肺气（一呼一吸促成脉动）。**病到「心动悸」，是心在胸中筑筑跳动、按之心前区搏动震手——这是血虚**；**脉结代**：跳得缓而时有一止的是结脉，停跳有固定规律（十余至一止、或七八至五六至一止）的是代脉——这是**血中之气虚**。所以重用阿胶、生地、炙甘草、大枣大剂补"}, {"source": "重订通俗伤寒论心悸条文注释｜二、真武汤（回阳摄阴法·重剂）——亡阳重证的目眩心悸", "原文": "真武汤** 回阳摄阴法（重剂），俞氏经验方，载仲景《伤寒论》。\n> 炮附子（四钱） 生白芍（三钱） 浙茯苓（三钱） 鲜生姜（二钱） 生冬术（二钱）。\n> 【秀按】《内经》云：阳气者，精则养神，柔则养筋。若外感证，发汗过多，津液亏少，阳气偏虚，自汗不止，筋失所养而惕惕跳动，肉失所养而然蠕动，**目眩心悸，振振欲擗地者，此为亡阳之重证**。故以附、姜辛热回阳为君，臣以白术培中益气，茯苓通阳化气……佐白", "白话": "真武汤（俞氏定为回阳摄阴重剂）：炮附子四钱、生白芍三钱、浙茯苓三钱、鲜生姜二钱、生冬术二钱。何秀山按：发汗过多、津亏阳虚、自汗不止，筋失养而惕惕跳动，肉失养而蠕动，**目眩心悸、抖得像要倒地，是亡阳重证**。附子生姜辛热回阳为君，白术培中，茯苓通阳化气，白芍阴药维系使阳附于阴而内返。若少阴腹痛下利、内有水气，茯苓要重用（六钱至一两）通阳利水，白芍酒炒防阴凝。"}, {"source": "重订通俗伤寒论心悸条文注释｜三、坎气潜龙汤与加味金匮肾气汤（心肾两亏、肾气凌心）", "原文": "如心肾两亏，颧赤耳聋，**舌绛心悸**，神烦不寐，腰痛如折，前阴出汗，时欲晕厥者，**坎气潜龙汤**主之。阴复则生，阴竭则死。\n> 【秀按】（坎气潜龙汤）……右脉浮大，左脉细数，**舌绛心悸，自汗虚烦**，手足躁扰，时时欲厥者，始为恰合。若肢厥脉细，额汗如珠，宜再加人参、附子、五味等品，急追元阳以收汗。\n> **一肾气凌心证**：气短息促，**头晕心悸**，足冷溺清，大便或溏或泻，气少不能言，强言", "白话": "温热病后期**心肾两亏**：颧红、耳聋、舌绛、心悸、神烦失眠、腰痛如折、前阴出汗、时时欲晕厥——用坎气潜龙汤（坎气即初生脐带，配二地、龙牡、珠母、磁朱、芍薇等滋阴潜阳、交济心肾）；若肢冷脉细、额汗如珠，加人参、附子、五味子急固元阳。\n- **肾气凌心证**（真寒假热的戴阳证）：气短息促、头晕心悸、足冷尿清、便溏、气少不能言，脉浮数按之欲散或浮大空豁——用加味《金匮》肾气汤滋阴纳阳。"}, {"source": "重订通俗伤寒论心悸条文注释｜四、火为水遏与水火互结（少阴传变中的悸）", "原文": "（二）**火为水遏**：四肢厥逆，**干咳心悸**，便泄溺涩，腹痛下重，舌苔白而底绛，脉左沉弦而滑，右弦急。此阳气内郁不得外达，水气上冲而下注也。治宜达郁通阳，**加味四逆散**（川柴胡八分、炒枳实一钱、生白芍一钱、清炙草八分、干姜五分拌捣北五味三分、桂枝尖五分、浙茯苓四钱、烧酒洗捣干薤白五枚、淡附片五分）主之。\n> （三）**水火互结**：下利口渴，小便不利，咳逆干呕，心烦不得眠，舌本绛而苔白薄", "白话": "少阴传变三证见悸：①**火为水遏**——四肢冷、干咳、心悸、便泻尿涩、腹痛下重，苔白底绛，脉左沉弦滑右弦急，是阳气内郁、水气上冲下注，用加味四逆散达郁通阳（四逆散加干姜五味、桂枝、茯苓、薤白、附片）；②**水火互结**——下利口渴、小便不利、咳逆干呕、心烦不眠，用猪苓汤滋水泄火（加灯心、童便、枇杷叶）；③**上寒下热**——水结胸胁、肢冷心悸、腹痛热泻，先用蠲饮万灵汤逐水，再用加味白头翁汤清肝泄热。"}, {"source": "重订通俗伤寒论心悸条文注释｜五、夹饮与动气——「巅眩心悸」与脐间动气诊法", "原文": "【秀按】……至若**蠲饮万灵汤**，则合小半夏加茯苓、甘遂半夏、十枣三汤为剂。无论心下支饮，膈间留饮，胃肠悬饮，为喘为满，为痛为胀，**为巅眩心悸**，为呕涎吐沫，善用者投无不效……惟**苓术二陈**及**真武加减**，一主外饮治脾，一主内饮治肾，则治夹饮之属虚者也。\n> 经云：动气在右，不可下，**下之则津液内竭，咽燥鼻干，头眩心悸**也。……故脐名神阙，是神气之穴，为保生之根。凡诊脐间动脉者…", "白话": "夹饮证七方分虚实：实证用蠲饮万灵汤（三方合剂逐水）——心下支饮、膈间/胃肠留饮，喘满痛胀、**巅顶眩晕心悸**、呕涎吐沫皆治；虚证外饮治脾用苓术二陈，内饮治肾用真武汤加减。\n- 脐间动气诊法：动气在右者禁下，误下则津液枯竭、咽鼻干、头眩心悸；诊脐间动脉（神阙周围）——动而和缓一息二至=肾气充；一息五六至=冲任伏热；虚冷沉微=命门不足。\n- **虚里脉**（心尖搏动）：寸口脉结者虚里脉亦必结；按之有形、三四至或五六至一止=积聚之候；浅按得深按不得=气虚，轻按洪大重按虚细=血虚。"}, {"source": "重订通俗伤寒论心悸条文注释｜六、瘥后怔忡与瘥后惊悸不寐（热病后心律失常的调理）", "原文": "（十一）**瘥后不寐**：凡伤寒温热病，热退之后，夜不欲寐者，胃不和也，温胆汤加秫米和之。**惊悸不寐者，心气虚也**，前方合酸枣仁汤去川芎清敛之。触事易惊，梦寐不安者，乃有余热挟痰也，宜用竹茹、黄连、石菖蒲、半夏、胆星、栀子、知母、茯苓、旋复花、橘红等味。\n> （十三）**瘥后怔忡**：凡热病新瘥，**怔忡惊骇**，乃水衰火旺，心肾不交也。宜补水养心，**朱砂安神丸**最妙。半夏秫米汤合交泰丸尤", "白话": "伤寒温热病瘥后诸证：①**惊悸不寐**——心气虚，用温胆汤合酸枣仁汤去川芎清敛；触事易惊、梦寐不安是余热挟痰，用竹茹、黄连、菖蒲、半夏、胆星、栀子、知母、茯苓、旋复花、橘红等清化；②**怔忡惊骇**——水衰火旺、心肾不交，用朱砂安神丸补水养心，或半夏秫米汤合交泰丸；③目闭则惊悸梦惕——余邪留肝胆、肝魂不安，用郁李仁、枣仁、猪胆皮、黄连、焦栀、竹茹、桑叶滑以去着、苦以泄热。"}, {"source": "重订通俗伤寒论心悸条文注释｜七、虚劳与大热证中的惊悸怔忡", "原文": "（虚劳）在心则为**惊悸怔忡**，为掌中干热，为虚烦不寐，或梦魇不宁，为口苦舌干，或口舌糜烂……此皆五脏虚劳之本证。\n> 【荣斋按】血虚当补之候是：面唇淡白，头晕目眩，五心烦热作渴，神志不宁，健忘**怔忡**失眠，肠燥便艰……\n> 神烦不寐，**心悸胆怯**，恍惚不安，躁则语言错乱，静则独语如见鬼，交睫则惊恐非常，倏醒则叫呼不宁，脉左寸浮洪，两尺沉细数搏，舌形圆大嫩红者，以**阿胶黄连汤**加半夏", "白话": "虚劳病在心的症状是惊悸怔忡、掌心干热、虚烦不眠、梦魇、口苦舌干等。徐荣斋按引何廉臣《重订广温热论》血虚当补之候：面白唇淡、头晕目眩、五心烦热、神志不宁、健忘怔忡失眠等。大热证后期神烦不眠、心悸胆怯、恍惚不安，脉左寸浮洪、两尺细数、舌圆大嫩红——用阿胶黄连汤加半夏、秫米、枣仁、茯神；怔忡重者加朱砂、西黄、玳瑁、珠粉重镇。"}, {"source": "重订通俗伤寒论心悸条文注释｜八、脉法篇——代脉主病与「伤寒心悸」", "原文": "……阳盛则促，肺痈阳毒。阴盛则结，疝瘕积郁。**代则气衰，或泄脓血，伤寒心悸，女胎三月**。\n> 汗后脉静，身凉则安；汗后脉躁，热甚必难。……**代脉止歇，脏绝倾危。散脉无根，形损难医**。\n> （虚里）脉结者，虚里脉亦必结……凡脉候难凭时，按虚里脉确有可据。", "白话": "脉法歌诀：阳盛见促脉（肺痈阳毒），阴盛见结脉（疝瘕积郁）；**代脉主气衰，见于泄利脓血、伤寒心悸、妇人怀孕三月**。汗后脉静身凉为佳，汗后脉躁热甚为难。代脉停跳不止、脏气将绝者危；散脉无根者难医。凡寸口脉难凭时，按虚里（心尖搏动）确有可据——脉结者虚里亦结。"}, {"source": "金匮要略胸痹心痛条文注释｜〇、脉法总纲（首条）", "原文": "师曰。夫脉当取太过不及。**阳微阴弦。即胸痹而痛**。所以然者。责其极虚也。今阳虚知在上焦。所以胸痹心痛者。以其阴弦故也。\n> （尤注）阳微、阳不足也。阴弦、阴太过也。阳主开。阴主闭。阳虚而阴干之。即胸痹而痛。痹者闭也。", "白话": "老师说：诊脉要辨**太过与不及**。寸脉微（阳虚）尺脉弦（阴盛）——就会发生胸痹心痛。根本在于**上焦阳气极虚**，阴邪乘虚上干，痹阻胸阳而痛。"}, {"source": "金匮要略胸痹心痛条文注释｜一、栝蒌薤白白酒汤（胸痹正治）", "原文": "胸痹之病。喘息咳唾。胸背痛。短气。**寸口脉沉而迟。关上小紧数**。栝蒌薤白白酒汤主之。\n> 栝蒌实（一枚捣） 薤白（半升） 白酒（七升） 上三味。同煮。取二升。分温再服。\n> （尤注）是当以通胸中之阳为主。薤白、白酒。辛以开痹。温以行阳。栝蒌实者。以阳痹之处。必有痰浊阻其间耳。", "白话": "胸痹病见**喘息咳嗽、胸背疼痛、气短**，寸脉沉迟、关脉小紧带数的，用栝蒌薤白白酒汤：栝蒌实一枚、薤白半升、白酒七升同煮取二升，分两次温服。治法以**通胸阳、散痰浊**为主。"}, {"source": "金匮要略胸痹心痛条文注释｜二、栝蒌薤白半夏汤（痰饮加重）", "原文": "胸痹不得卧。**心痛彻背**者。栝蒌薤白半夏汤主之。\n> 栝蒌实（一枚捣） 薤白（三两） 半夏（半升） 白酒（一斗）\n> （尤注）胸痹不得卧。是肺气上而不下也。心痛彻背。是心气塞而不和也……有痰饮以为之援也。故于胸痹药中。加半夏以逐痰饮。", "白话": "胸痹重至**不能平卧、心痛牵连后背**的，用栝蒌薤白半夏汤——在前方基础上加半夏逐痰饮。"}, {"source": "金匮要略胸痹心痛条文注释｜三、枳实薤白桂枝汤 vs 人参汤（去邪/扶正分野）", "原文": "胸痹。心中痞气。气结在胸。胸满。胁下逆抢心。**枳实薤白桂枝汤主之。人参汤亦主之**。\n> （尤注）是宜急通其痞结之气。否则速复其不振之阳。盖去邪之实。即以安正。养阳之虚。即以逐阴。是在审其病之久暂。与气之虚实而决之。\n> 枳实薤白桂枝汤：枳实（四枚） 薤白（半升） 桂枝（一两） 浓朴（四两） 栝蒌实（一枚）\n> 人参汤：人参 甘草 干姜 白术（各三两）", "白话": "胸痹见**心中痞闷、气结在胸、胸满、胁下气逆上冲撞心**的：实证急通痞结用**枳实薤白桂枝汤**；虚证温复阳气用**人参汤**（理中汤）——**据病程久暂与气之虚实决断**。"}, {"source": "金匮要略胸痹心痛条文注释｜四、茯苓杏仁甘草汤 / 橘枳生姜汤（轻证气塞）", "原文": "胸痹。胸中气塞。短气。茯苓杏仁甘草汤主之。橘枳生姜汤亦主之。\n> 茯苓（三两） 杏仁（五十个） 甘草（一两）／橘皮（一斤） 枳实（三两） 生姜（半斤）\n> （尤注）此亦气闭气逆之证。视前条为稍缓矣。二方皆下气散结之剂。而有甘淡苦辛之异。亦在酌其强弱而用之。", "白话": "胸痹轻证见**胸中气闷、气短**的：水饮偏重用茯苓杏仁甘草汤（甘淡渗利），气滞偏重用橘枳生姜汤（苦辛行气）——**据强弱酌用**。"}, {"source": "顾松园医镜心悸条文注释｜二、归脾汤加味（十味版+加味归脾汤）", "原文": "归脾汤** 治类中风，心、脾、肝三经俱虚，或**怔忡惊悸，眠则易醒**（心血不足也）……人参、黄芪、白术、甘草（补脾），茯神、远志、枣仁、元肉（安神），当归（养血），木香（快气）。肝火旺，加丹皮、黑山栀。\n> （虚劳门）归脾汤〔亦作膏丸〕治思虑伤心，健忘怔忡，惊悸不寐，自汗盗汗……**惊悸怔忡，加辰砂、麦冬。如有痰者，再加竹沥、天竺黄，或牛黄**。本方加柴胡、山栀，名**加味归脾汤**。\n\n###", "白话": "虚里跳动（心尖搏动）是虚损之本——阴虚劳怯者心下跳动、惊悸慌张就是这个；**搏动轻微病轻、搏动亢进病重**。"}, {"source": "黄帝内经素问心脉条文注释｜一、心主血脉（痿论篇）", "原文": "心主身之血脉**，肝主身之筋膜，脾主身之肌肉，肾主身之骨髓……心气热，则下脉厥而上，上则下脉虚，虚则生**脉痿**，枢折挈，胫纵而不任地也。", "白话": "心主管全身的血脉**（肝主筋膜、脾主肌肉、肾主骨髓）。心气热盛，血逆于上而下脉空虚，发为**脉痿**——关节如折、足胫弛纵不能站立。"}, {"source": "黄帝内经素问心脉条文注释｜二、心-五脏-情志-五行（阴阳应象大论篇）", "原文": "在脏为**心**，在色为赤，在音为征，在声为笑，在变动为忧，在窍为舌，在味为苦，在志为**喜**。**喜伤心，恐胜喜**；热伤气，寒胜热；苦伤气，咸胜苦。", "白话": "（南方生热，热生火）在脏对应**心**，色赤、音征、声笑、变动为忧、开窍于舌、味苦、在志为**喜**。**过度喜乐伤心，恐惧可以抑制喜**（情志相胜）。"}, {"source": "黄帝内经素问心脉条文注释｜三、心之合脉与五味所伤（五脏生成篇）", "原文": "心之合脉也**，其荣色也，其主肾也……是故**多食咸，则脉凝泣而变色**……心痹，得之外疾，思虑而心虚，故邪从之。", "白话": "心相合的是脉**（荣华表现在面色，制约它的是肾）……**过食咸味则血脉凝涩、面色改变**……心痹的成因：外邪侵袭+思虑过度心虚，邪气乘虚而入。"}, {"source": "黄帝内经素问心脉条文注释｜四、虚里宗气诊（平人气象论篇）——古心脏触诊", "原文": "宗气**也。**盛喘数绝者，则病在中；结而横，有积矣；绝不至曰死**。**乳之下其动应衣，宗气泄也**。", "白话": "（虚里搏动反映）宗气的状态：搏动**急促频断**的是病在内；**搏动结滞横布**的有积聚；**断绝不来的是死候**。乳下虚里搏动**强烈到震动衣服**的，是宗气外泄。"}, {"source": "黄帝内经素问心脉条文注释｜五、心脉诊法与预后（脉要精微论篇）", "原文": "心脉搏坚而长，当病舌卷不能言**；其软而散者，当消环自已……帝曰：诊得**心脉而急**，此为何病？岐伯曰：病名**心疝**，少腹当有形也……**脉涩曰痹**……**脉从阴阳，病易已；脉逆阴阳，病难已**。", "白话": "心脉搏击坚长的，病舌卷不能言语；软散的，病消渴但可自行缓解……心脉急的病叫**心疝**（少腹有形可见）……**脉涩主痹证**……**脉与阴阳相应（顺）病易愈，脉与阴阳相逆病难愈**。"}];